import { AgentLoop } from '../core/agent.loop';
import { ToolRegistry } from '../tools/tool.registry';
import type { LLMProvider, ChatEvent } from '../core/llm.provider';
import { createAskUserTool } from '../tools/implementations/ask_user.tool';
import { engineEvents } from '../engine/events';
import { getConfig, loadConfig } from '../engine/config';
function scripted(rounds: ChatEvent[][]) {
 let n=0;return { applyConfig(){},userModel:'scripted',async *chat(){ for(const e of rounds[Math.min(n++,rounds.length-1)]) yield e; } } as unknown as LLMProvider;
}
const ask = (id:string,options=['Yes','No']):ChatEvent => ({type:'tool_call',id,name:'AskUserTool',args:JSON.stringify({question:'Which option?',options})});
test('duplicate clarification in a user run reuses its exact answer without prompting; next run asks anew', async () => {
 const registry=new ToolRegistry(),execute=jest.fn(async ()=> 'User selected: No');
 registry.register({name:'AskUserTool',description:'ask',schema:{type:'object',properties:{question:{type:'string'},options:{type:'array',items:{type:'string'}}}},isDestructive:false,isConcurrencySafe:false,execute});
 const loop=new AgentLoop(scripted([[ask('1'),{type:'done'}],[ask('2'),{type:'done'}],[{type:'token',text:'I will use your answer.'},{type:'done'}]]),registry,null as any);
 for await(const _ of loop.execute([{role:'user',content:'Choose the option'}],'sys',{maxIterations:4})){ /* Fixture body intentionally performs no work. */ }
 expect(execute).toHaveBeenCalledTimes(1);
 expect(loop.messages.filter(m=>m.role==='tool')[1].content).toContain('User selected: No');
 const next=new AgentLoop(scripted([[ask('3'),{type:'done'}],[{type:'token',text:'I will use your answer.'},{type:'done'}]]),registry,null as any);
 for await(const _ of next.execute([{role:'user',content:'Choose again'}],'sys',{maxIterations:3})){ /* Fixture body intentionally performs no work. */ }
 expect(execute).toHaveBeenCalledTimes(2);
});
test('changed choice options are a new clarification', async () => {
 const registry=new ToolRegistry(),execute=jest.fn(async ()=> 'User selected: No');registry.register({name:'AskUserTool',description:'',schema:{},isDestructive:false,isConcurrencySafe:false,execute});
 const loop=new AgentLoop(scripted([[ask('1'),{type:'done'}],[ask('2',['Keep','Delete']),{type:'done'}],[{type:'token',text:'Both answers received.'},{type:'done'}]]),registry,null as any);
 for await(const _ of loop.execute([{role:'user',content:'Choose two options'}],'sys',{maxIterations:4})){ /* Fixture body intentionally performs no work. */ }
 expect(execute).toHaveBeenCalledTimes(2);
});
test('Stop releases a real pending human clarification and late answers do not resume the turn', async () => {
 await loadConfig();const config=getConfig(),previous=config.autoAgentDecisions;config.autoAgentDecisions=false;
 let answer!: (s:string)=>void;
 const listener=(_q:string,_options:string[],callback:(s:string)=>void)=>{answer=callback;};engineEvents.on('veto_prompt',listener);
 try {
  const tool=createAskUserTool({approveTaskExecution:async()=>{}} as any,{} as any),stop=new AbortController();
  const pending=tool.execute({question:'Choose the target project folder',options:['First','Second']},{signal:stop.signal});
  while(!answer) await new Promise(r=>setImmediate(r));stop.abort();await expect(pending).rejects.toThrow(/cancelled/);answer('First');
 } finally { config.autoAgentDecisions=previous;engineEvents.off('veto_prompt',listener); }
});
test('a blocked embedded workflow forces an answer-only provider round', async () => {
 const registry=new ToolRegistry();registry.register({name:'NativeHost',description:'',schema:{},isDestructive:true,isConcurrencySafe:false,outputSource:'screen',execute:async()=>({ok:false,blocked:true,executor:'stop',code:'native_workflow_stopped',reason:'postcondition failed',replay:false})});
 const schemaCounts:number[]=[];let n=0;
 const llm={userModel:'scripted',applyConfig(){},async *chat(_m:any,options:any){schemaCounts.push(options?.tools?.length || 0); if(n++===0) yield {type:'tool_call',id:'1',name:'NativeHost',args:'{}'};else yield {type:'token',text:'The operation stopped because verification failed.'};yield {type:'done'};}} as unknown as LLMProvider;
 const loop=new AgentLoop(llm,registry,null as any);for await(const _ of loop.execute([{role:'user',content:'Do the task'}],'sys',{maxIterations:4,toolNames:['NativeHost']})){ /* Fixture body intentionally performs no work. */ }
 expect(schemaCounts[0]).toBe(1);expect(schemaCounts[1]).toBe(0);
});

test('a native terminal failure prevents later calls from the same model response', async () => {
 const registry=new ToolRegistry(),later=jest.fn(async()=> 'would mutate');
 registry.register({name:'NativeHost',description:'',schema:{},isDestructive:true,isConcurrencySafe:false,outputSource:'screen',execute:async()=>({ok:false,blocked:true,executor:'stop',code:'native_workflow_stopped',reason:'denied',replay:false})});
 registry.register({name:'LaterTool',description:'',schema:{},isDestructive:true,isConcurrencySafe:false,execute:later});
 const llm=scripted([[{type:'tool_call',id:'1',name:'NativeHost',args:'{}'},{type:'tool_call',id:'2',name:'LaterTool',args:'{}'},{type:'done'}],[{type:'token',text:'The native operation stopped.'},{type:'done'}]]);
 const loop=new AgentLoop(llm,registry,null as any);for await(const _ of loop.execute([{role:'user',content:'Do the task'}],'sys',{maxIterations:3,toolNames:['NativeHost','LaterTool']})){ /* Fixture body intentionally performs no work. */ }
 expect(later).not.toHaveBeenCalled();expect(loop.messages.filter(m=>m.role==='tool').map(m=>m.tool_call_id)).toEqual(['1','2']);
});

test('a model-emitted out-of-scope call cannot execute despite being in the registry', async () => {
 const registry=new ToolRegistry(),mutate=jest.fn(async()=> 'escaped'),native=jest.fn(async()=>({ok:true,operation:'workflow',verified:true}));
 registry.register({name:'BashTool',description:'shell',schema:{type:'object'},isDestructive:true,isConcurrencySafe:false,execute:mutate});
 registry.register({name:'NativeHost',description:'native',schema:{type:'object'},isDestructive:true,isConcurrencySafe:false,outputSource:'screen',execute:native});
 const seen:string[][]=[];let turn=0;
 const llm={userModel:'scripted',applyConfig(){},async *chat(_m:any,opts:any){seen.push(opts.tools.map((t:any)=>t.name));if(turn++===0){yield {type:'tool_call',id:'escape',name:'BashTool',args:'{}'};yield {type:'tool_call',id:'native',name:'NativeHost',args:'{}'};}else yield {type:'token',text:'Verified.'};yield {type:'done'};}} as unknown as LLMProvider;
 const loop=new AgentLoop(llm,registry,null as any);
 for await(const _ of loop.execute([{role:'user',content:'Do native work'}],'sys',{maxIterations:3,toolNames:['NativeHost']})){ /* Fixture body intentionally performs no work. */ }
 expect(mutate).not.toHaveBeenCalled();expect(native).toHaveBeenCalledTimes(1);expect(seen[0]).toEqual(['NativeHost']);
 expect(loop.messages.some(m=>m.role==='tool'&&String(m.content).includes('outside this turn'))).toBe(true);
});

test('explicit-only host tools stay absent in normal schemas and cannot be guessed into a normal turn', async () => {
 const registry=new ToolRegistry(),native=jest.fn(async()=>({ok:true}));
 registry.register({name:'NativeHost',description:'native',schema:{},scopeOnly:true,isDestructive:true,isConcurrencySafe:false,execute:native});registry.discover('NativeHost');
 expect(registry.getSchemas({mode:'smart'})).toEqual([]);expect(registry.getSchemas({mode:'full'})).toEqual([]);expect(registry.getAllSchemas().map(t=>t.name)).toEqual(['NativeHost']);expect(registry.deferredSummary()).toEqual([]);
 const loop=new AgentLoop(scripted([[{type:'tool_call',id:'guess',name:'NativeHost',args:'{}'},{type:'done'}],[{type:'token',text:'Select the capability first.'},{type:'done'}]]),registry,null as any);
 for await(const _ of loop.execute([{role:'user',content:'Normal turn'}],'sys',{maxIterations:3})){ /* Fixture body intentionally performs no work. */ }
 expect(native).not.toHaveBeenCalled();
});

import { AgentLoop, terminalCapabilityBlocker } from '../core/agent.loop';
import { ToolRegistry } from '../tools/tool.registry';
import { LLMProvider, ChatEvent } from '../core/llm.provider';

/**
 * The operation completion gate.
 *
 * `requireTool` proves the model REACHED the capability — `requiredToolUsed` flips on the first
 * call of any kind. It never proved the operation was attempted, so a single target-acquisition
 * verb satisfied it and the turn was free to end on narration.
 *
 * Measured live 2026-08-18 on "send hi to my mom using Messages": the model called
 * {action:"open", app:"Messages"}, received a 44-element observation, and then answered with a
 * missed-call notice copied out of that very observation. Nothing was typed and nothing was sent,
 * yet the turn reported as complete.
 */
const TOOL = 'mcp__bimax-mac__mac_control';

function registryWithCapability() {
  const calls: any[] = [];
  const registry = new ToolRegistry();
  registry.register({
    name: TOOL,
    description: 'capability',
    schema: { type: 'object', properties: {} },
    isDestructive: true,
    isConcurrencySafe: false,
    execute: async (args: any) => { calls.push(args); return JSON.stringify({ ok: true }); },
  } as any);
  return { registry, calls };
}


/** A capability whose calls fail — the honest end is the blocker, not another nudge. */
function registryWithFailingCapability() {
  const calls: any[] = [];
  const registry = new ToolRegistry();
  registry.register({
    name: TOOL,
    description: 'capability',
    schema: { type: 'object', properties: {} },
    isDestructive: true,
    isConcurrencySafe: false,
    execute: async (args: any) => {
      calls.push(args);
      return JSON.stringify({ ok: false, summary: 'blocked by permission denial' });
    },
  } as any);
  return { registry, calls };
}

/** A model that emits the given capability actions on successive rounds, then narrates forever. */
function scriptedLlm(actions: string[]) {
  let round = 0;
  return {
    userModel: 'test-model',
    async *chat(): AsyncGenerator<ChatEvent> {
      const action = actions[round++];
      if (action) {
        yield {
          type: 'tool_call',
          id: `c${round}`,
          name: TOOL,
          args: JSON.stringify({ action, app: 'Messages' }),
        } as any;
      } else {
        yield { type: 'token', text: 'Dear Customer, you have a missed call from +91 97019 52447.' };
      }
      yield { type: 'done' } as any;
    },
  } as unknown as LLMProvider;
}

async function drain(loop: AgentLoop, system: string, opts: any): Promise<string> {
  let out = '';
  for await (const chunk of loop.execute([] as any, system, opts)) out += chunk;
  return out;
}

describe('AgentLoop — a prepared turn is not a completed operation', () => {
  it('classifies native stop receipts but preserves named snapshot recovery', () => {
    expect(terminalCapabilityBlocker(JSON.stringify({
      ok: false, blocked: true, executor: 'stop',
      code: 'native_logical_action_unavailable', reason: 'focus is unavailable',
    }))).toBe('native_logical_action_unavailable: focus is unavailable');
    expect(terminalCapabilityBlocker(JSON.stringify({
      ok: false, blocked: true, executor: 'stop',
      code: 'native_snapshot_required', reason: 'observe first',
    }))).toBeNull();
  });

  it('turns a terminal native stop into an enforced answer-only round', async () => {
    const calls: any[] = [];
    const registry = new ToolRegistry();
    registry.register({
      name: TOOL, description: 'capability', schema: { type: 'object', properties: {} },
      isDestructive: true, isConcurrencySafe: false,
      execute: async (args: any) => {
        calls.push(args);
        return JSON.stringify({
          ok: false, blocked: true, executor: 'stop',
          code: 'foreground_activation_unverified', reason: 'Messages did not become frontmost',
        });
      },
    } as any);
    let round = 0;
    const seenToolCounts: number[] = [];
    const llm = {
      userModel: 'test-model',
      async *chat(_messages: any[], options: any): AsyncGenerator<ChatEvent> {
        seenToolCounts.push((options?.tools || []).length);
        round++;
        if (round === 1) {
          yield { type: 'tool_call', id: 'open', name: TOOL, args: '{"action":"open","app":"Messages"}' } as any;
        } else {
          yield { type: 'token', text: 'Messages could not be verified as frontmost, so I stopped.' };
        }
        yield { type: 'done' } as any;
      },
    } as unknown as LLMProvider;
    const loop = new AgentLoop(llm, registry, undefined, 128_000);
    const out = await drain(loop, 'sys', {
      requireTool: TOOL, toolNames: [TOOL], maxIterations: 5,
    });

    expect(calls).toHaveLength(1);
    expect(seenToolCounts).toEqual([1, 0]);
    expect(out).toContain('could not be verified as frontmost');
    expect(loop.messages.some(message => typeof message.content === 'string'
      && message.content.includes('[OPERATION BLOCKED — ANSWER ONLY]'))).toBe(true);
  });

  it('does not let a lone open end the turn, and re-asks for the real action', async () => {
    const { registry, calls } = registryWithCapability();
    // The live shape: open, then narrate instead of acting. The gate must interrupt that and the
    // model then performs the action it had skipped.
    const loop = new AgentLoop(scriptedLlm(['open', '', 'type']), registry, undefined, 128_000);
    await drain(loop, 'sys', { requireTool: TOOL, toolNames: [TOOL], maxIterations: 8 });

    const actions = calls.map(c => c.action);
    expect(actions).toContain('open');
    expect(actions).toContain('type');
    const nudge = (loop.messages as any[]).find(m =>
      typeof m?.content === 'string' && m.content.includes('[OPERATION COMPLETION GATE]'));
    expect(nudge).toBeTruthy();
    expect(String(nudge.content)).toMatch(/never repeat text read off the screen/i);
  });

  it('terminates instead of looping when the model will not advance', async () => {
    const { registry, calls } = registryWithCapability();
    // Only ever prepares: open, observe, then narration forever.
    const loop = new AgentLoop(scriptedLlm(['open', 'observe']), registry, undefined, 128_000);
    const out = await drain(loop, 'sys', { requireTool: TOOL, toolNames: [TOOL], maxIterations: 12 });

    // Bounded: the gate nudges twice at most and then lets the turn end honestly.
    expect(calls.every(c => ['open', 'observe'].includes(c.action))).toBe(true);
    expect(typeof out).toBe('string');
  });

  it('leaves a turn that really acted alone', async () => {
    const { registry, calls } = registryWithCapability();
    const loop = new AgentLoop(scriptedLlm(['open', 'click']), registry, undefined, 128_000);
    await drain(loop, 'sys', { requireTool: TOOL, toolNames: [TOOL], maxIterations: 8 });

    expect(calls.map(c => c.action)).toEqual(['open', 'click']);
    const nudged = (loop.messages as any[]).some(m =>
      typeof m?.content === 'string' && m.content.includes('[OPERATION COMPLETION GATE]'));
    expect(nudged).toBe(false);
  });
  /**
   * The over-refusing direction, which the first version of this gate got wrong: it nudged twice
   * even when the preparatory call had FAILED, so a model correctly reporting a concrete blocker
   * had its answer emitted three times. A failed call is a legitimate place to stop.
   */
  it('does not nudge when the preparatory call failed and the model reports the blocker', async () => {
    const { registry, calls } = registryWithFailingCapability();
    const loop = new AgentLoop(scriptedLlm(['open', '', 'type']), registry, undefined, 128_000);
    await drain(loop, 'sys', { requireTool: TOOL, toolNames: [TOOL], maxIterations: 8 });

    expect(calls.map(c => c.action)).toEqual(['open']);
    const nudged = (loop.messages as any[]).some(m =>
      typeof m?.content === 'string' && m.content.includes('[OPERATION COMPLETION GATE]'));
    expect(nudged).toBe(false);
  });
});

import { AgentLoop } from '../core/agent.loop';
import { ChatEvent, LLMProvider, Message } from '../core/llm.provider';
import { ContextManager } from '../memory/context.manager';
import { ToolRegistry } from '../tools/tool.registry';

const contextError: ChatEvent = {
  type: 'error',
  message: 'Request Entity Too Large',
  recoverable: true,
  kind: 'context',
};

function toolExchange(id: string, result: string): Message[] {
  return [
    {
      role: 'assistant',
      tool_calls: [{ id, type: 'function', function: { name: 'noop', arguments: '{}' } }],
    },
    { role: 'tool', tool_call_id: id, content: result },
  ];
}

function drainableHistory(trailingUsers = 0): Message[] {
  return [
    { role: 'system', content: 'Keep this system instruction.' },
    { role: 'user', content: 'Complete the long-running task.' },
    ...Array.from({ length: 10 }).flatMap((_, index) =>
      toolExchange(`old-${index}`, `tool result ${index}: ${'payload '.repeat(120)}`),
    ),
    ...Array.from({ length: trailingUsers }).map((_, index) => ({
      role: 'user' as const,
      content: `recent turn ${index}: ${'detail '.repeat(40)}`,
    })),
  ];
}

function nonDrainableHistory(): Message[] {
  return [
    { role: 'system', content: 'Keep this system instruction.' },
    ...Array.from({ length: 12 }).map((_, index) => ({
      role: 'user' as const,
      content: `history turn ${index}: ${'detail '.repeat(80)}`,
    })),
  ];
}

async function run(loop: AgentLoop, messages: Message[], maxIterations = 10): Promise<string> {
  let output = '';
  for await (const text of loop.execute(messages, 'system prompt', {
    contextMode: 'full',
    maxIterations,
  })) {
    output += text;
  }
  return output;
}

describe('AgentLoop — bounded graded context recovery', () => {
  afterEach(() => jest.restoreAllMocks());

  it('runs the cheap reactive drain first, retries, and completes after one context error', async () => {
    const drain = jest.spyOn(ContextManager.prototype, 'reactiveDrain');
    let calls = 0;
    const llm: LLMProvider = {
      async *chat(): AsyncGenerator<ChatEvent> {
        calls++;
        if (calls === 1) yield contextError;
        else {
          yield { type: 'token', text: 'Recovered cheaply.' };
          yield { type: 'done' };
        }
      },
    };

    const loop = new AgentLoop(llm, new ToolRegistry(), null as any);
    const output = await run(loop, drainableHistory());

    expect(drain).toHaveBeenCalledTimes(1);
    expect(calls).toBe(2);
    expect(output).toContain('Recovered cheaply.');
    expect(loop.messages.some(message => String(message.content).startsWith('[tool result cleared to save context'))).toBe(true);
  });

  it('advances through tiers 0, 1, and 2, then stops at the terminal bound', async () => {
    const drain = jest.spyOn(ContextManager.prototype, 'reactiveDrain');
    const compact = jest.spyOn(ContextManager.prototype, 'reactiveCompact');
    let calls = 0;
    const llm: LLMProvider = {
      async *chat(): AsyncGenerator<ChatEvent> {
        calls++;
        yield contextError;
      },
    };

    const loop = new AgentLoop(llm, new ToolRegistry(), null as any);
    const output = await run(loop, nonDrainableHistory(), 20);

    expect(drain).toHaveBeenCalledTimes(1);
    expect(compact).toHaveBeenCalledTimes(1);
    // Tier 0 cannot change this tool-free history, so tier 1 runs in the same error handling.
    // Only tiers 1 and 2 earn retries; the third model rejection reaches the terminal bound.
    expect(calls).toBe(3);
    expect(output).toContain(
      'The task context stayed over the model\'s limit after draining, summarizing, and truncating — stopping this turn to avoid a compaction loop.',
    );
    expect(output).not.toContain('Stopped after 20 rounds');
  });

  it('resets the recovery ladder after a clean tool-call turn', async () => {
    const drain = jest.spyOn(ContextManager.prototype, 'reactiveDrain');
    const compact = jest.spyOn(ContextManager.prototype, 'reactiveCompact');
    const registry = new ToolRegistry();
    registry.register({
      name: 'noop',
      description: 'No-op tool',
      schema: {},
      isDestructive: false,
      isConcurrencySafe: true,
      execute: async () => 'new result',
    } as any);

    const script: ChatEvent[][] = [
      [contextError],
      [{ type: 'tool_call', id: 'new-tool', name: 'noop', args: '{}' }, { type: 'done' }],
      [contextError],
      [{ type: 'token', text: 'Finished after both recoveries.' }, { type: 'done' }],
    ];
    let calls = 0;
    const llm: LLMProvider = {
      async *chat(): AsyncGenerator<ChatEvent> {
        const events = script[calls++] ?? script[script.length - 1];
        for (const event of events) yield event;
      },
    };

    const loop = new AgentLoop(llm, registry, null as any);
    const output = await run(loop, drainableHistory());

    expect(calls).toBe(4);
    expect(drain).toHaveBeenCalledTimes(2);
    expect(compact).not.toHaveBeenCalled();
    expect(output).toContain('Finished after both recoveries.');
  });

  it('strictly reduces the existing token estimate at every retry tier', async () => {
    const sent: Message[][] = [];
    let calls = 0;
    const llm: LLMProvider = {
      async *chat(messages: Message[]): AsyncGenerator<ChatEvent> {
        sent.push(messages);
        calls++;
        if (calls <= 3) yield contextError;
        else {
          yield { type: 'token', text: 'Completed after the ladder.' };
          yield { type: 'done' };
        }
      },
    };

    const loop = new AgentLoop(llm, new ToolRegistry(), null as any);
    const output = await run(loop, drainableHistory(6));
    const manager = (loop as any).contextManager as ContextManager;
    const estimates = sent.map(messages => manager.estimateTokens(messages));

    expect(estimates).toHaveLength(4);
    expect(estimates[1]).toBeLessThan(estimates[0]); // tier 0: cheap drain
    expect(estimates[2]).toBeLessThan(estimates[1]); // tier 1: reactive compact
    expect(estimates[3]).toBeLessThan(estimates[2]); // tier 2: recent-turn truncation
    expect(output).toContain('Completed after the ladder.');
  });
});

import * as fs from 'fs';
import * as os from 'os';
import * as path from 'path';
import { AgentLoop } from '../core/agent.loop';
import { ToolRegistry } from '../tools/tool.registry';
import { LLMProvider, ChatEvent } from '../core/llm.provider';

// A successful failover PERSISTS the new model, so these tests must never see the developer's real
// ~/.breakglass/config.json. Without this they rewrite it — which is exactly what happened once:
// a test run silently repointed a real machine's `model` at the catalog default.
let tmpBreakglass: string;
const realBreakglassDir = process.env.BIMAX_BREAKGLASS_DIR;
beforeAll(() => {
  tmpBreakglass = fs.mkdtempSync(path.join(os.tmpdir(), 'bgw-fallback-cfg-'));
  process.env.BIMAX_BREAKGLASS_DIR = tmpBreakglass;
});
afterAll(() => {
  if (realBreakglassDir === undefined) delete process.env.BIMAX_BREAKGLASS_DIR;
  else process.env.BIMAX_BREAKGLASS_DIR = realBreakglassDir;
  try { fs.rmSync(tmpBreakglass, { recursive: true, force: true }); } catch { /* best-effort */ }
});

/**
 * Model fallback chain (the Claude Code `fallbackModel` analogue): when the active model keeps
 * failing — transient retry budget exhausted, or a hard provider rejection — the loop switches
 * the session to the configured fallback model ONCE and re-asks, instead of dying mid-run.
 */
describe('AgentLoop — fallback model chain', () => {
  afterEach(() => {
    delete process.env.BIMAX_FALLBACK_MODEL;
    delete process.env.BIMAX_DESKTOP_STRICT_MODEL;
  });

  it('never retries or fails over when Desktop locks the exact model', async () => {
    process.env.BIMAX_DESKTOP_STRICT_MODEL = 'stepfun-ai/step-3.7-flash';
    process.env.BIMAX_FALLBACK_MODEL = 'backup-model';
    const { llm, applied } = makeFailoverLlm({ type: 'error', message: 'stream stalled', recoverable: true, kind: 'transient' });
    let calls = 0;
    const original = (llm as any).chat.bind(llm);
    (llm as any).chat = async function* (...args: any[]) { calls++; yield* original(...args); };

    const loop = new AgentLoop(llm, new ToolRegistry(), null as any);
    let out = '';
    for await (const token of loop.execute([{ role: 'user', content: 'go' }], 'sys', { maxIterations: 10 })) out += token;

    expect(calls).toBe(1);
    expect(applied).toEqual([]);
    expect(out).toContain('provider returned an error');
  });

  // An LLM whose chat() fails until applyConfig() switches the model, then succeeds.
  function makeFailoverLlm(failWith: ChatEvent) {
    const applied: any[] = [];
    let model = 'primary-model';
    const llm = {
      userModel: 'primary-model',
      applyConfig(cfg: any) {
        applied.push(cfg);
        if (cfg.model) { model = cfg.model; (llm as any).userModel = cfg.model; }
      },
      async *chat(): AsyncGenerator<ChatEvent> {
        if (model === 'primary-model') {
          yield failWith;
        } else {
          yield { type: 'token', text: `Answered on ${model}.` };
          yield { type: 'done' };
        }
      },
    };
    return { llm: llm as unknown as LLMProvider, applied };
  }

  it('a lite-routed turn fails over its QUICK model, not just the work model (measured live 2026-09-28)', async () => {
    process.env.BIMAX_FALLBACK_MODEL = 'backup-model';
    const applied: any[] = [];
    let quick = 'stalled-quick';
    const models: string[] = [];
    const llm = {
      userModel: 'stalled-quick',
      liteModel: 'stalled-quick',
      applyConfig(cfg: any) {
        applied.push(cfg);
        if (cfg.model) (llm as any).userModel = cfg.model;
        if (cfg.liteModel) { quick = cfg.liteModel; (llm as any).liteModel = cfg.liteModel; }
      },
      async *chat(_m: any, opts: any): AsyncGenerator<ChatEvent> {
        const model = opts?.lite ? quick : (llm as any).userModel;
        models.push(model);
        if (model === 'stalled-quick') {
          yield { type: 'error', message: 'stream stalled', recoverable: true, kind: 'transient', retryAfterSecs: 0 };
        } else {
          yield { type: 'token', text: `Answered on ${model}.` };
          yield { type: 'done' };
        }
      },
    };
    const loop = new AgentLoop(llm as unknown as LLMProvider, new ToolRegistry(), null as any);
    let out = '';
    for await (const t of loop.execute([{ role: 'user', content: 'go' }], 'sys', { maxIterations: 10, useLite: true } as any)) out += t;
    expect(applied).toContainEqual({ model: 'backup-model', liteModel: 'backup-model' });
    expect(models[models.length - 1]).toBe('backup-model');
    expect(out).toContain('Answered on backup-model.');
  });

  it('when only the quick model fails, the healthy work model can be its fallback', async () => {
    process.env.BIMAX_FALLBACK_MODEL = 'healthy-work';
    let quick = 'stalled-quick';
    const llm = {
      userModel: 'healthy-work',
      liteModel: 'stalled-quick',
      applyConfig(cfg: any) { if (cfg.liteModel) quick = cfg.liteModel; if (cfg.model) (llm as any).userModel = cfg.model; },
      async *chat(_m: any, opts: any): AsyncGenerator<ChatEvent> {
        const model = opts?.lite ? quick : (llm as any).userModel;
        if (model === 'stalled-quick') {
          yield { type: 'error', message: 'stream stalled', recoverable: true, kind: 'transient', retryAfterSecs: 0 };
        } else {
          yield { type: 'token', text: `Answered on ${model}.` };
          yield { type: 'done' };
        }
      },
    };
    const loop = new AgentLoop(llm as unknown as LLMProvider, new ToolRegistry(), null as any);
    let out = '';
    for await (const t of loop.execute([{ role: 'user', content: 'go' }], 'sys', { maxIterations: 10, useLite: true } as any)) out += t;
    // The fallback equals the WORK model, which is fine: it is not the model that failed.
    expect(out).toContain('Answered on healthy-work.');
  });

  it('fails over after the transient budget is exhausted and completes on the fallback', async () => {
    process.env.BIMAX_FALLBACK_MODEL = 'backup-model';
    const { llm, applied } = makeFailoverLlm({ type: 'error', message: 'stream stalled', recoverable: true, kind: 'transient' });

    const loop = new AgentLoop(llm, new ToolRegistry(), null as any);
    let out = '';
    for await (const t of loop.execute([{ role: 'user', content: 'go' }], 'sys', { maxIterations: 10 })) {
      out += t;
    }

    expect(applied).toEqual([{ model: 'backup-model' }]);
    expect(out).toContain('Answered on backup-model.');
    expect(out).not.toContain('provider returned an error');
  }, 15000); // rides through 2 real backoff sleeps (~3s) before the failover

  it('fails over immediately on a hard (unrecoverable) provider rejection', async () => {
    process.env.BIMAX_FALLBACK_MODEL = 'backup-model';
    const { llm, applied } = makeFailoverLlm({ type: 'error', message: 'model decommissioned', recoverable: false } as ChatEvent);

    const loop = new AgentLoop(llm, new ToolRegistry(), null as any);
    let out = '';
    for await (const t of loop.execute([{ role: 'user', content: 'go' }], 'sys', { maxIterations: 10 })) {
      out += t;
    }

    expect(applied).toEqual([{ model: 'backup-model' }]);
    expect(out).toContain('Answered on backup-model.');
  });

  it('fires only once — a failing fallback surfaces the error instead of ping-ponging', async () => {
    process.env.BIMAX_FALLBACK_MODEL = 'backup-model';
    let calls = 0;
    const llm = {
      userModel: 'primary-model',
      applyConfig(cfg: any) { if (cfg.model) (llm as any).userModel = cfg.model; },
      async *chat(): AsyncGenerator<ChatEvent> {
        calls++;
        // Both models are down.
        yield { type: 'error', message: 'everything is on fire', recoverable: false } as ChatEvent;
      },
    };

    const loop = new AgentLoop(llm as unknown as LLMProvider, new ToolRegistry(), null as any);
    let out = '';
    for await (const t of loop.execute([{ role: 'user', content: 'go' }], 'sys', { maxIterations: 10 })) {
      out += t;
    }

    expect(calls).toBe(2); // primary once, fallback once — then surfaced, never spun
    expect(out).toContain('The provider returned an error');
  });

  // Failing over is the machine picking a model on the user's behalf, so it must obey the same
  // safety policy as healing. The live failure this encodes: the configured fallback was
  // stepfun-ai/step-3.7-flash, which sends no response headers for 180s — so a visible model error
  // turned into a spinner that never resolved and a turn that never replied.
  describe('never fails over to a model that cannot serve the turn', () => {
    const hardFail: ChatEvent = { type: 'error', message: 'model decommissioned', recoverable: false } as ChatEvent;

    it('skips a fallback the provider already rejected this session', async () => {
      process.env.BIMAX_FALLBACK_MODEL = 'known-dead-model';
      const { llm, applied } = makeFailoverLlm(hardFail);
      // The adapter learned this id is a lie (listed by /models, 404s on completion).
      (llm as any).isUnservable = (id: string) => id === 'known-dead-model';
      (llm as any).listProviderModels = async () => [];

      const loop = new AgentLoop(llm, new ToolRegistry(), null as any);
      for await (const _ of loop.execute([{ role: 'user', content: 'go' }], 'sys', { maxIterations: 10 })) { /* drain */ }

      expect(applied.map(a => a.model)).not.toContain('known-dead-model');
    });

    it('HONORS a configured fallback the catalog bars from automatic selection', async () => {
      // This asserted the opposite until 2026-09-02, and the assertion was the bug. `avoidAutoSelect`
      // gates the models the machine may pick BY ITSELF; BIMAX_FALLBACK_MODEL is a value the user
      // set. Letting the flag override it discarded a configured `nemotron-3.5-lightning-30b-a3b`
      // (6.7s, calls tools) for carrying the note "task probe pending", and derived a replacement
      // the provider does not serve — turning a working fallback into a dead turn.
      // eslint-disable-next-line @typescript-eslint/no-require-imports
      const { MODEL_CATALOG } = require('../engine/models') as typeof import('../engine/models');
      const avoided = MODEL_CATALOG.find(m => m.avoidAutoSelect)!.value;
      process.env.BIMAX_FALLBACK_MODEL = avoided;
      const { llm, applied } = makeFailoverLlm(hardFail);
      (llm as any).listProviderModels = async () => [];

      const loop = new AgentLoop(llm, new ToolRegistry(), null as any);
      for await (const _ of loop.execute([{ role: 'user', content: 'go' }], 'sys', { maxIterations: 10 })) { /* drain */ }

      expect(applied.map(a => a.model)).toContain(avoided);
    });

    it('derives a served model when the configured fallback is disqualified BY EVIDENCE', async () => {
      // The other half of the split: once the provider has actually rejected the configured value,
      // it is disqualified and derivation takes over — and derivation DOES respect the catalogue
      // bar, so it must not land on the avoided model even though the provider serves it.
      // eslint-disable-next-line @typescript-eslint/no-require-imports
      const { MODEL_CATALOG, autoSelectCandidates } = require('../engine/models') as typeof import('../engine/models');
      const avoided = MODEL_CATALOG.find(m => m.avoidAutoSelect)!.value;
      // Ask the policy which model it would pick, rather than restating the rule with a different one.
      const good = autoSelectCandidates('coding', MODEL_CATALOG.map(m => m.value))[0];
      process.env.BIMAX_FALLBACK_MODEL = avoided;
      const { llm, applied } = makeFailoverLlm(hardFail);
      (llm as any).isUnservable = (id: string) => id === avoided;
      (llm as any).listProviderModels = async () => [avoided, good];

      const loop = new AgentLoop(llm, new ToolRegistry(), null as any);
      let out = '';
      for await (const t of loop.execute([{ role: 'user', content: 'go' }], 'sys', { maxIterations: 10 })) out += t;

      expect(applied.map(a => a.model)).toEqual([good]);
      expect(out).toContain(`Answered on ${good}.`);
    });
  });

  it('does not fail over to the model that is already active', async () => {
    process.env.BIMAX_FALLBACK_MODEL = 'primary-model'; // same as current
    let applies = 0;
    const llm = {
      userModel: 'primary-model',
      applyConfig() { applies++; },
      async *chat(): AsyncGenerator<ChatEvent> {
        yield { type: 'error', message: 'down', recoverable: false } as ChatEvent;
      },
    };

    const loop = new AgentLoop(llm as unknown as LLMProvider, new ToolRegistry(), null as any);
    let out = '';
    for await (const t of loop.execute([{ role: 'user', content: 'go' }], 'sys', { maxIterations: 10 })) {
      out += t;
    }

    expect(applies).toBe(0);
    expect(out).toContain('The provider returned an error');
  });
});

import { AgentLoop, isStrayFragment } from '../core/agent.loop';
import { ToolRegistry } from '../tools/tool.registry';
import { LLMProvider, ChatEvent } from '../core/llm.provider';

/**
 * A reasoning model once ended a full turn with the five characters "Thead" and the loop presented it as
 * the answer. A reply that is only a stray fragment is held back and re-asked once; real short answers are
 * shown as they are, and a model that keeps producing the fragment cannot spin the loop.
 */
function scripted(rounds: ChatEvent[][]) {
  let calls = 0;
  const llm = {
    userModel: 'scripted-model',
    applyConfig() {},
    async *chat(): AsyncGenerator<ChatEvent> {
      const round = rounds[Math.min(calls, rounds.length - 1)];
      calls++;
      for (const event of round) yield event;
    },
  };
  return { llm: llm as unknown as LLMProvider, calls: () => calls };
}

async function run(llm: LLMProvider): Promise<string> {
  const loop = new AgentLoop(llm, new ToolRegistry(), null as any);
  let out = '';
  for await (const token of loop.execute([{ role: 'user', content: 'what files do you see ?' }], 'sys', { maxIterations: 6 })) out += token;
  return out;
}

describe('a stray one-word fragment is not presented as the answer', () => {
  test('the fragment never reaches the output and the model is asked once more', async () => {
    const { llm, calls } = scripted([
      [{ type: 'token', text: 'The' }, { type: 'token', text: 'ad' }, { type: 'done' }],
      [{ type: 'token', text: 'Here are the files: ' }, { type: 'token', text: 'notes.txt' }, { type: 'done' }],
    ]);
    const out = await run(llm);
    expect(out).not.toContain('Thead');
    expect(out).toContain('Here are the files: notes.txt');
    expect(calls()).toBe(2);
  });

  test('a real short answer is shown once, with no extra round', async () => {
    const { llm, calls } = scripted([[{ type: 'token', text: 'Yes' }, { type: 'done' }]]);
    expect((await run(llm)).trim()).toBe('Yes');
    expect(calls()).toBe(1);
  });

  test('a model that keeps sending the fragment is re-asked only once, then shown', async () => {
    const { llm, calls } = scripted([[{ type: 'token', text: 'Thead' }, { type: 'done' }]]);
    expect((await run(llm)).trim()).toBe('Thead');
    expect(calls()).toBe(2);
  });

  test('which replies count as a stray fragment', () => {
    expect(isStrayFragment('Thead')).toBe(true);
    expect(isStrayFragment('Paris')).toBe(true); // costs one extra round, then shown
    for (const answer of ['Yes', 'done', '42', 'Done.', 'Here are the files', '', 'OK']) expect(isStrayFragment(answer)).toBe(false);
  });
});

import { AgentLoop } from '../core/agent.loop';
import { ChatEvent, ChatOptions, LLMProvider, Message } from '../core/llm.provider';
import { ToolRegistry } from '../tools/tool.registry';

type BudgetedProvider = LLMProvider & { maxTokens: number };

async function run(loop: AgentLoop, maxIterations = 20): Promise<string> {
  let output = '';
  for await (const text of loop.execute(
    [{ role: 'user', content: 'Complete the task.' }],
    'system prompt',
    { contextMode: 'full', maxIterations },
  )) {
    output += text;
  }
  return output;
}

function pureReasoningTruncation(): ChatEvent[] {
  return [
    { type: 'thinking', text: 'Still reasoning without producing an answer.' },
    { type: 'truncated' },
    { type: 'done' },
  ];
}

describe('AgentLoop — scoped pure-reasoning output escalation', () => {
  const originalRecorder = process.env.BIMAX_RECORDER;
  const originalContinues = process.env.BIMAX_MAX_CONTINUES;
  const originalCeiling = process.env.BIMAX_MAX_OUTPUT_CEILING;

  beforeEach(() => {
    process.env.BIMAX_RECORDER = '0';
    process.env.BIMAX_MAX_CONTINUES = '1';
    process.env.BIMAX_MAX_OUTPUT_CEILING = '16384';
  });

  afterEach(() => {
    if (originalRecorder === undefined) delete process.env.BIMAX_RECORDER;
    else process.env.BIMAX_RECORDER = originalRecorder;
    if (originalContinues === undefined) delete process.env.BIMAX_MAX_CONTINUES;
    else process.env.BIMAX_MAX_CONTINUES = originalContinues;
    if (originalCeiling === undefined) delete process.env.BIMAX_MAX_OUTPUT_CEILING;
    else process.env.BIMAX_MAX_OUTPUT_CEILING = originalCeiling;
    jest.restoreAllMocks();
  });

  it('escalates 4096 → 8192 → 16384, caps there, and remains bounded', async () => {
    const requestedBudgets: Array<number | undefined> = [];
    let calls = 0;
    const llm: BudgetedProvider = {
      maxTokens: 4096,
      async *chat(_messages: Message[], options: ChatOptions): AsyncGenerator<ChatEvent> {
        calls++;
        requestedBudgets.push(options.maxTokens);
        for (const event of pureReasoningTruncation()) yield event;
      },
    };

    const output = await run(new AgentLoop(llm, new ToolRegistry(), null as any));
    const effectiveBudgets = requestedBudgets.map(budget => budget ?? llm.maxTokens);

    // Three escalation retries are allowed: the third is capped at 16k rather than exceeding it.
    // One existing bounded continuation then runs at the configured default before giving up.
    expect(effectiveBudgets).toEqual([4096, 8192, 16384, 16384, 4096]);
    expect(Math.max(...effectiveBudgets)).toBe(16384);
    expect(calls).toBe(5);
    expect(output).toContain('response hit the max output limit');
  });

  it('resets the one-call budget and escalation ladder after a tool-producing turn', async () => {
    const requestedBudgets: Array<number | undefined> = [];
    let calls = 0;
    let toolExecutions = 0;
    const registry = new ToolRegistry();
    registry.register({
      name: 'noop',
      description: 'No-op tool',
      schema: {},
      isDestructive: false,
      isConcurrencySafe: true,
      execute: async () => {
        toolExecutions++;
        return 'tool completed';
      },
    } as any);
    const llm: BudgetedProvider = {
      maxTokens: 4096,
      async *chat(_messages: Message[], options: ChatOptions): AsyncGenerator<ChatEvent> {
        const call = calls++;
        requestedBudgets.push(options.maxTokens);
        const events: ChatEvent[] = call === 0
          ? pureReasoningTruncation()
          : call === 1
            ? [{ type: 'tool_call', id: 'tool-1', name: 'noop', args: '{}' }, { type: 'done' }]
            : call === 2
              ? pureReasoningTruncation()
              : [{ type: 'token', text: 'Finished normally.' }, { type: 'done' }];
        for (const event of events) yield event;
      },
    };

    const output = await run(new AgentLoop(llm, registry, null as any));

    // The post-tool call returns to the configured 4096 budget. Its next overflow therefore starts
    // a fresh ladder at 8192 instead of retaining the prior escalation and jumping to 16384.
    expect(requestedBudgets).toEqual([undefined, 8192, undefined, 8192]);
    expect(toolExecutions).toBe(1);
    expect(calls).toBe(4);
    expect(output).toContain('Finished normally.');
  });

  it('does not escalate a normal truncation that already produced visible content', async () => {
    const requestedBudgets: Array<number | undefined> = [];
    let calls = 0;
    const llm: BudgetedProvider = {
      maxTokens: 4096,
      async *chat(_messages: Message[], options: ChatOptions): AsyncGenerator<ChatEvent> {
        const call = calls++;
        requestedBudgets.push(options.maxTokens);
        const events: ChatEvent[] = call === 0
          ? [
            { type: 'token', text: 'Partial answer. ' },
            { type: 'truncated' },
            { type: 'done' },
          ]
          : [{ type: 'token', text: 'Finished answer.' }, { type: 'done' }];
        for (const event of events) yield event;
      },
    };

    const loop = new AgentLoop(llm, new ToolRegistry(), null as any);
    const output = await run(loop);

    expect(requestedBudgets).toEqual([undefined, undefined]);
    expect(calls).toBe(2);
    expect(output).toContain('Partial answer. Finished answer.');
    expect(loop.messages.some(message =>
      message.role === 'user' &&
      typeof message.content === 'string' &&
      message.content.includes('Continue from exactly where it stopped'),
    )).toBe(true);
  });
});

describe('AgentLoop — provider-required reasoning replay', () => {
  beforeEach(() => { process.env.BIMAX_RECORDER = '0'; });
  afterEach(() => { delete process.env.BIMAX_RECORDER; jest.restoreAllMocks(); });

  function registryWithNoop(): ToolRegistry {
    const registry = new ToolRegistry();
    registry.register({
      name: 'noop', description: 'No-op tool', schema: {}, isDestructive: false,
      isConcurrencySafe: true, execute: async () => 'tool completed',
    } as any);
    return registry;
  }

  it('replays Kimi-style reasoning_content with the assistant tool-call message', async () => {
    const calls: Message[][] = [];
    const llm: LLMProvider = {
      async *chat(messages: Message[]): AsyncGenerator<ChatEvent> {
        calls.push(messages.map((message) => ({ ...message })));
        if (calls.length === 1) {
          yield { type: 'thinking', text: 'provider reasoning', replay: true };
          yield { type: 'tool_call', id: 'tool-1', name: 'noop', args: '{}' };
        } else {
          yield { type: 'token', text: 'Finished.' };
        }
        yield { type: 'done' };
      },
    };

    await run(new AgentLoop(llm, registryWithNoop(), null as any));

    const replayed = calls[1].find((message) => message.role === 'assistant' && message.tool_calls?.length);
    expect(replayed).toEqual(expect.objectContaining({
      reasoning_content: 'provider reasoning',
      tool_calls: [expect.objectContaining({ id: 'tool-1' })],
    }));
  });

  it('does not persist ordinary hidden thinking when replay is not required', async () => {
    const calls: Message[][] = [];
    const llm: LLMProvider = {
      async *chat(messages: Message[]): AsyncGenerator<ChatEvent> {
        calls.push(messages.map((message) => ({ ...message })));
        if (calls.length === 1) {
          yield { type: 'thinking', text: 'private reasoning' };
          yield { type: 'tool_call', id: 'tool-1', name: 'noop', args: '{}' };
        } else {
          yield { type: 'token', text: 'Finished.' };
        }
        yield { type: 'done' };
      },
    };

    await run(new AgentLoop(llm, registryWithNoop(), null as any));

    const replayed = calls[1].find((message) => message.role === 'assistant' && message.tool_calls?.length);
    expect(replayed?.reasoning_content).toBeUndefined();
  });
});

import { AgentLoop } from '../core/agent.loop';
import { ToolRegistry } from '../tools/tool.registry';
import { LLMProvider, ChatEvent, Message } from '../core/llm.provider';
import { observeToolOutcome } from '../core/tool.outcome.observers';
import { __resetFailureMemoryForTests } from '../core/failure.memory';

/**
 * Three behaviours of the agent loop that no test pinned before its 1,230-line execute() was split into phases (flaw
 * list C14): removing any of them left the whole suite green. Each is a user-visible promise.
 */

function scripted(rounds: ChatEvent[][]) {
  const requests: Message[][] = [];
  const llm = {
    userModel: 'scripted-model',
    applyConfig() {},
    async *chat(messages: Message[]): AsyncGenerator<ChatEvent> {
      requests.push(messages.map((m) => ({ ...m })));
      const round = rounds[Math.min(requests.length - 1, rounds.length - 1)];
      for (const event of round) yield event;
    },
  };
  return { llm: llm as unknown as LLMProvider, requests };
}

const lastUser = (messages: Message[]) => [...messages].reverse().find((m) => m.role === 'user')?.content;

test('a reply that is only a remark about tool usage is re-asked once, as that — not as an empty reply', async () => {
  const { llm, requests } = scripted([
    [{ type: 'token', text: 'I will now call the search tool.' }, { type: 'done' }],
    [{ type: 'token', text: 'Paris is the capital of France.' }, { type: 'done' }],
  ]);
  const loop = new AgentLoop(llm, new ToolRegistry(), null as any);
  let out = '';
  for await (const t of loop.execute([{ role: 'user', content: 'capital of France?' }], 'sys', { maxIterations: 5 })) out += t;
  expect(out).toContain('Paris is the capital of France.');
  expect(requests).toHaveLength(2);
  expect(String(lastUser(requests[1]))).toMatch(/only a remark about tool usage/);
});

test('an interrupt between tool batches still answers every call the model made, so the next request is valid', async () => {
  const stop = new AbortController();
  const registry = new ToolRegistry();
  const ran: string[] = [];
  for (const name of ['FirstTool', 'SecondTool']) {
    registry.register({
      name, description: name, schema: { type: 'object', properties: {} }, isDestructive: true, isConcurrencySafe: false,
      execute: async () => { ran.push(name); if (name === 'FirstTool') stop.abort(); return 'done'; },
    } as any);
  }
  const { llm } = scripted([[
    { type: 'tool_call', id: 'c1', name: 'FirstTool', args: '{}' },
    { type: 'tool_call', id: 'c2', name: 'SecondTool', args: '{}' },
    { type: 'done' },
  ]]);
  const loop = new AgentLoop(llm, registry, null as any);
  for await (const _ of loop.execute([{ role: 'user', content: 'do both' }], 'sys', { maxIterations: 5, signal: stop.signal })) { /* drain */ }
  expect(ran).toEqual(['FirstTool']);
  const results = loop.messages.filter((m) => m.role === 'tool');
  expect(results.map((m) => m.tool_call_id)).toEqual(['c1', 'c2']);
  expect(results[1].content).toBe('Tool call interrupted before it ran.');
});

test('the same failing action, repeated, is answered with a note to change strategy once its budget is spent', () => {
  __resetFailureMemoryForTests();
  const failing = {
    call: { id: 'x', name: 'ReadFileTool', args: '{"path":"missing.txt"}' },
    result: 'ENOENT: no such file or directory', isError: true, durationMs: 1,
    span: { setAttribute() {}, addEvent() {}, context: {} } as any, cwd: process.cwd(), background: false,
  };
  const seen = [observeToolOutcome(failing), observeToolOutcome(failing), observeToolOutcome(failing)];
  expect(seen[0]).toBe(failing.result);
  expect(seen.some((r) => r.includes('⟳'))).toBe(true);
  expect(seen.filter((r) => r.includes('⟳')).every((r) => r.startsWith(failing.result))).toBe(true);
});

import { AgentLoop } from '../core/agent.loop';
import { ToolRegistry } from '../tools/tool.registry';
import { LLMProvider, ChatEvent, Message } from '../core/llm.provider';
import { engineEvents, ToolCallEntry } from '../engine/events';

/**
 * End-to-end: when the model writes a tool call as plain text instead of using the
 * function-calling API, the loop must recover it, execute the real tool, and carry
 * on to produce the follow-up answer.
 */
describe('AgentLoop — recovers and executes a text-emitted tool call', () => {
  it('parses the leaked JSON, runs the tool, and continues the loop', async () => {
    let executedWith: any = null;
    const registry = new ToolRegistry();
    registry.register({
      name: 'WriteFileTool',
      description: 'writes a file',
      schema: {},
      isDestructive: false,
      isConcurrencySafe: true,
      execute: async (args: any) => { executedWith = args; return 'OK: file written'; },
    } as any);

    // Turn 1: emit a tool call as text. Turn 2 (after the tool result): real answer.
    let call = 0;
    const mockLlm: LLMProvider = {
      async *chat(): AsyncGenerator<ChatEvent> {
        call++;
        if (call === 1) {
          yield { type: 'token', text: 'The final answer is {"name": "WriteFileTool", "parameters": {"path": "/tmp/x", "content": "working"}}.' };
        } else {
          yield { type: 'token', text: 'Done — the file is written.' };
        }
        yield { type: 'done' };
      },
    };

    const loop = new AgentLoop(mockLlm, registry, null as any);
    let out = '';
    for await (const t of loop.execute([{ role: 'user', content: 'create the file' }], 'sys', { maxIterations: 5 })) {
      out += t;
    }

    // The recovered call actually executed with the parsed arguments.
    expect(executedWith).toEqual({ path: '/tmp/x', content: 'working' });
    // The loop continued past the tool result to the real answer.
    expect(out).toContain('Done');

    // History is well-formed and clean: an assistant tool_calls message, a tool
    // result, then the final assistant answer — and no raw tool JSON persisted.
    const assistantWithToolCalls = loop.messages.find(m => m.role === 'assistant' && m.tool_calls?.length);
    expect(assistantWithToolCalls?.tool_calls?.[0].function.name).toBe('WriteFileTool');
    expect(loop.messages.some(m => m.role === 'tool')).toBe(true);
    const finalAssistant = [...loop.messages].reverse().find(m => m.role === 'assistant');
    expect(finalAssistant?.content).toContain('Done');
    expect(loop.messages.some(m => m.role === 'assistant' && typeof m.content === 'string' && m.content.includes('"name"'))).toBe(false);
  });
});

/**
 * Tool-result ordering: when a turn mixes concurrency-safe (parallel) and unsafe (sequential)
 * tools, the pushed `tool` result messages must appear in the SAME order the model emitted the
 * tool_calls — not "all parallel first, then all sequential". Order-sensitive OpenAI-compatible
 * backends reject a mismatch, and every tool_call must be answered exactly once.
 */
describe('AgentLoop — tool results are pushed in tool_call order', () => {
  it('pairs each result to its call in emission order across parallel/sequential tools', async () => {
    const registry = new ToolRegistry();
    registry.register({
      name: 'WriteFileTool', description: 'writes', schema: {},
      isDestructive: true, isConcurrencySafe: false, // sequential
      execute: async () => 'WROTE',
    } as any);
    registry.register({
      name: 'ReadFileTool', description: 'reads', schema: {},
      isDestructive: false, isConcurrencySafe: true, // parallel
      execute: async () => 'READ',
    } as any);

    let call = 0;
    const mockLlm: LLMProvider = {
      async *chat(): AsyncGenerator<ChatEvent> {
        call++;
        if (call === 1) {
          // Emission order: sequential tool FIRST, parallel tool SECOND.
          yield { type: 'tool_call', id: 'w1', name: 'WriteFileTool', args: '{"path":"/tmp/a","content":"x"}' };
          yield { type: 'tool_call', id: 'r1', name: 'ReadFileTool', args: '{"path":"/tmp/b"}' };
          yield { type: 'done' };
        } else {
          yield { type: 'token', text: 'Done.' };
          yield { type: 'done' };
        }
      },
    };

    const loop = new AgentLoop(mockLlm, registry, null as any);
    // eslint-disable-next-line no-empty
    for await (const _ of loop.execute([{ role: 'user', content: 'go' }], 'sys', { maxIterations: 3 })) {}

    const toolMsgs = loop.messages.filter(m => m.role === 'tool');
    // Both calls answered, in emission order (write result before read result).
    expect(toolMsgs.map(m => m.tool_call_id)).toEqual(['w1', 'r1']);
    // Each id answered exactly once — no gaps, no duplicates.
    const asst = loop.messages.find(m => m.role === 'assistant' && m.tool_calls?.length);
    const callIds = asst!.tool_calls!.map(tc => tc.id).sort();
    const resultIds = toolMsgs.map(m => m.tool_call_id).sort();
    expect(resultIds).toEqual(callIds);
  });
});

/**
 * C3 live tool-arg streaming: a `tool_call_partial` event must surface as a live "running" tool
 * entry on the UI bus (so the call shows as it forms) WITHOUT being executed — only the final
 * authoritative `tool_call` runs the tool.
 */
describe('AgentLoop — live tool-arg streaming (tool_call_partial)', () => {
  it('emits a running tool_call for the partial without executing it', async () => {
    let execCount = 0;
    const registry = new ToolRegistry();
    registry.register({
      name: 'WriteFileTool', description: 'writes', schema: {},
      isDestructive: false, isConcurrencySafe: true,
      execute: async () => { execCount++; return 'OK'; },
    } as any);

    let call = 0;
    const mockLlm: LLMProvider = {
      async *chat(): AsyncGenerator<ChatEvent> {
        call++;
        if (call === 1) {
          yield { type: 'tool_call_partial', id: 'tc1', name: 'WriteFileTool', args: '{"path":"/tmp/' };
          yield { type: 'tool_call_partial', id: 'tc1', name: 'WriteFileTool', args: '{"path":"/tmp/x","content":"hi"}' };
          yield { type: 'tool_call', id: 'tc1', name: 'WriteFileTool', args: '{"path":"/tmp/x","content":"hi"}' };
          yield { type: 'done' };
        } else {
          yield { type: 'token', text: 'Done.' };
          yield { type: 'done' };
        }
      },
    };

    const seen: ToolCallEntry[] = [];
    const onCall = (c: ToolCallEntry) => seen.push(c);
    engineEvents.on('tool_call', onCall);
    try {
      const loop = new AgentLoop(mockLlm, registry, null as any);
      // eslint-disable-next-line no-empty
      for await (const _ of loop.execute([{ role: 'user', content: 'go' }], 'sys', { maxIterations: 2 })) {}
    } finally {
      engineEvents.off('tool_call', onCall);
    }

    // The partials surfaced as running entries (live activity) with the growing args...
    const running = seen.filter(c => c.id === 'tc1' && c.status === 'running');
    expect(running.length).toBeGreaterThanOrEqual(2);
    expect(running.some(c => c.input === '{"path":"/tmp/')).toBe(true);
    // ...and the tool executed exactly once (driven by the final tool_call, not the partials).
    expect(execCount).toBe(1);
  });
});

/**
 * A turn that produces nothing visible — no streamed text, no tool call, not pure filler
 * (e.g. a coding model that emitted only `reasoning_content` then ended empty, or a model
 * that went silent right after a tool result) must not leave the user staring at a stopped
 * spinner. The loop nudges once for a direct answer; bounded so it can't spin.
 */
describe('AgentLoop — recovers from a silent empty turn', () => {
  it('nudges once when a turn is completely empty, then completes', async () => {
    let call = 0;
    const mockLlm: LLMProvider = {
      async *chat(): AsyncGenerator<ChatEvent> {
        call++;
        if (call === 1) {
          // Only reasoning, no visible content, no tool call — collapses to empty.
          yield { type: 'thinking', text: 'hmm let me think' };
          yield { type: 'done' };
        } else {
          yield { type: 'token', text: 'Here is the actual answer.' };
          yield { type: 'done' };
        }
      },
    };

    const loop = new AgentLoop(mockLlm, new ToolRegistry(), null as any);
    let out = '';
    for await (const t of loop.execute([{ role: 'user', content: 'do it' }], 'sys', { maxIterations: 5 })) {
      out += t;
    }

    expect(call).toBe(2); // nudged exactly once
    expect(out).toContain('Here is the actual answer.');
    // The nudge was injected as a user message so the model re-answers.
    expect(loop.messages.some(m => m.role === 'user' && typeof m.content === 'string' && m.content.includes('empty response'))).toBe(true);
  });

  it('surfaces a visible note rather than dead silence if it stays empty', async () => {
    const mockLlm: LLMProvider = {
      async *chat(): AsyncGenerator<ChatEvent> {
        // Always empty — exhausts the single empty-turn retry.
        yield { type: 'done' };
      },
    };

    const loop = new AgentLoop(mockLlm, new ToolRegistry(), null as any);
    let out = '';
    for await (const t of loop.execute([{ role: 'user', content: 'do it' }], 'sys', { maxIterations: 5 })) {
      out += t;
    }

    // Never silent — the user gets a note explaining no response came back.
    expect(out).toContain('No response was produced');
  });
});

