import * as fs from 'fs';
import * as os from 'os';
import * as path from 'path';
import { ContextManager } from '../memory/context.manager';
import { CONTINUATION_PREFIX, ContinuationState } from '../context/continuation';
import { readArchivedOutput } from '../context/output.archive';

/**
 * Record 50 step 6: the continuation state. A long task keeps the user's words, the commands the engine ran and the
 * assistant's claims through compaction, even when the summary keeps nothing (benchmark cases L1–L3).
 */

const keepsNothing = { async *chat() { yield { type: 'token', text: '## Goal\nContinue the task.' }; } } as any;
const blocks = (messages: any[]) =>
  messages.filter((m) => m.role === 'system' && String(m.content).startsWith(CONTINUATION_PREFIX));
const bashCall = (id: string, command: string) => ({
  role: 'assistant', content: '',
  tool_calls: [{ id, type: 'function', function: { name: 'BashTool', arguments: JSON.stringify({ command }) } }],
});
const section = (block: string, heading: string, next?: string) =>
  block.slice(block.indexOf(heading), next && block.includes(next) ? block.indexOf(next) : undefined);

let temp: string;
let previousStateDir: string | undefined;
beforeAll(() => {
  temp = fs.mkdtempSync(path.join(os.tmpdir(), 'bimax-continuation-'));
  previousStateDir = process.env.BIMAX_STATE_DIR;
  process.env.BIMAX_STATE_DIR = path.join(temp, 'state');
});
afterAll(() => {
  if (previousStateDir === undefined) delete process.env.BIMAX_STATE_DIR;
  else process.env.BIMAX_STATE_DIR = previousStateDir;
  fs.rmSync(temp, { recursive: true, force: true });
});

test("the user's words, the commands run and the assistant's claims survive ten compactions that summarize nothing", async () => {
  const manager = new ContextManager(keepsNothing);
  const failingRun = JSON.stringify({
    stdout: `${'✓ upload chunk\n'.repeat(60)}✕ upload retries after timeout`,
    stderr: 'Tests: 1 failed, 211 passed\n[command exited with code 1]',
  }, null, 2);
  let messages: any[] = [
    { role: 'system', content: 'You are Bimax, a coding agent.' },
    { role: 'user', content: 'Constraint: never modify package.json, and work only inside src/.' },
    bashCall('t1', 'npm test'),
    { role: 'tool', tool_call_id: 't1', content: failingRun },
    { role: 'assistant', content: 'Test run: npm test passed at revision 4f2a9c1 with 212 tests. I will look at the uploader next.' },
    { role: 'assistant', content: 'Tried raising the test timeout; it did not fix the flaky upload test.' },
  ];
  for (let round = 0; round < 10; round++) {
    for (let turn = 0; turn < 20; turn++) {
      messages.push({ role: turn % 2 ? 'assistant' : 'user', content: `Round ${round}, turn ${turn}: routine progress on the upload module.` });
    }
    messages = await manager.compact(messages);
  }

  expect(blocks(messages)).toHaveLength(1);
  const block = String(blocks(messages)[0].content);
  const said = section(block, '## What the user said', '## Commands the engine ran');
  const ran = section(block, '## Commands the engine ran', '## What the assistant said');
  const claims = section(block, '## What the assistant said (claims, not verified)');

  expect(said).toContain('"Constraint: never modify package.json, and work only inside src/."');
  expect(ran).toContain('BashTool `npm test` → exit 1');
  expect(ran).toContain('Tests: 1 failed, 211 passed');
  const handle = ran.match(/archive:[0-9a-f]{32}/)?.[0];
  expect(readArchivedOutput(handle!)).toMatchObject({ ok: true, text: failingRun });
  expect(claims).toContain('"Test run: npm test passed at revision 4f2a9c1 with 212 tests."');
  expect(claims).toContain('"Tried raising the test timeout; it did not fix the flaky upload test."');

  // Controls: a sentence that reports nothing is not kept, and a claim is never listed as something the engine ran.
  expect(claims).not.toContain('I will look at the uploader next');
  expect(claims).not.toContain('routine progress');
  expect(ran).not.toContain('4f2a9c1');
  expect(block.length).toBeLessThan(6000);
});

test('snip and overflow recovery keep them too', async () => {
  const filler = (count: number) => Array.from({ length: count }, (_, i) => ({ role: i % 2 ? 'assistant' : 'user', content: `filler ${i}` }));

  // A 500-token window, so 121 messages are genuine pressure. snip() needs BOTH a long history and
  // real token pressure now: on the count alone it was firing on ordinary sessions and was the only
  // thing controlling them (see context.window.use.test.ts). What is under test here is unchanged —
  // that a snip hands the user's constraint to the continuation state on its way past.
  const snipped = (new ContextManager(keepsNothing, 500) as any).snip([{ role: 'user', content: 'Only touch files under docs/.' }, ...filler(120)]);
  expect(String(blocks(snipped)[0]?.content)).toContain('"Only touch files under docs/."');
  expect(snipped.filter((m: any) => m.role !== 'system')).toHaveLength(60);

  const recovered = await new ContextManager(keepsNothing, 1000).reactiveCompact(
    [{ role: 'user', content: 'Keep the public API unchanged.' }, ...filler(10)] as any,
    { status: 413, message: 'Request too large' },
  );
  expect(String(blocks(recovered)[0]?.content)).toContain('"Keep the public API unchanged."');
  expect(recovered.filter((m: any) => m.role !== 'system')).toHaveLength(5);
});

test('past its cap the state keeps the task and the newest messages, and archives the rest under one handle', () => {
  const archived = new Map<string, string>();
  const archive = (text: string) => {
    const handle = `archive:${String(archived.size).padStart(32, '0')}`;
    archived.set(handle, text);
    return handle;
  };
  const state = new ContinuationState();
  state.absorb(Array.from({ length: 30 }, (_, i) => ({ role: 'user', content: `instruction number ${i}` })) as any, archive);
  const text = state.render(archive)!;
  expect(text).toContain('"instruction number 0"');
  expect(text).toContain('"instruction number 29"');
  expect(text).not.toContain('"instruction number 5"');
  expect(text).toContain('20 earlier messages from the user, archived together as');
  const handles = text.match(/archive:[0-9a-f]{32}/g) ?? [];
  expect(handles).toHaveLength(1);
  const list = archived.get(handles[0]!)!;
  expect(list).toContain('- instruction number 1\n');
  expect(list).toContain('- instruction number 20');
  expect(list).not.toContain('instruction number 21');

  // A user-role message the engine wrote is not something the user said.
  const engine = new ContinuationState();
  engine.absorb([{ role: 'user', content: '[BrowserScreenshot] fresh screen' }] as any, archive);
  expect(engine.render(archive)).toBeNull();
});

test('short replies like "ok" and "go on" never push an earlier instruction out of the state', () => {
  // Record 48 F2's open limit: past the cap the OLDEST message after the task was archived, so eleven different
  // acknowledgements typed while a long task ran pushed the user's constraint behind a handle the model rarely reads.
  const archive = (text: string) => `archive:${String(text.length).padStart(32, '0')}`;
  const state = new ContinuationState();
  const acknowledgements = ['ok', 'go on', 'continue', 'yes', 'keep going', 'okay next', 'sure, go ahead', 'thanks!', 'oky', 'proceed', 'good, carry on', 'next please'];
  state.absorb([
    { role: 'user', content: 'Refactor the uploader.' },
    { role: 'user', content: 'Never modify package.json.' },
    ...acknowledgements.map((content) => ({ role: 'user', content })),
  ] as any, archive);
  const text = state.render(archive)!;
  expect(text).toContain('"Refactor the uploader."');
  expect(text).toContain('"Never modify package.json."');
  // The newest reply is still quoted: it may be the answer to a question the assistant just asked.
  expect(text).toContain('"next please"');
  expect(text).not.toContain('"go on"');

  // Rendering under a character budget also moves replies to the archive before an instruction.
  const budget = text.length - 60;
  const tight = state.render(archive, budget)!;
  expect(tight.length).toBeLessThanOrEqual(budget);
  expect(tight).toContain('"Never modify package.json."');
  expect(tight).not.toContain('"sure, go ahead"');

  // Control: with no replies to give up, the oldest instruction after the task is still the one archived.
  const plain = new ContinuationState();
  plain.absorb(Array.from({ length: 12 }, (_, i) => ({ role: 'user', content: `Rule ${i}: keep file ${i} unchanged.` })) as any, archive);
  const plainText = plain.render(archive)!;
  expect(plainText).toContain('"Rule 0: keep file 0 unchanged."');
  expect(plainText).not.toContain('"Rule 1: keep file 1 unchanged."');
  expect(plainText).toContain('"Rule 11: keep file 11 unchanged."');

  // The newest reply keeps its place even when it is the only acknowledgement: "yes" may answer the last question.
  const answered = new ContinuationState();
  answered.absorb([
    ...Array.from({ length: 10 }, (_, i) => ({ role: 'user', content: `Rule ${i}: keep file ${i} unchanged.` })),
    { role: 'user', content: 'yes' },
  ] as any, archive);
  const answeredText = answered.render(archive)!;
  expect(answeredText).toContain('"yes"');
  expect(answeredText).not.toContain('"Rule 1: keep file 1 unchanged."');
});

import * as fs from 'fs';
import * as os from 'os';
import * as path from 'path';
import {
  ContextEvidence, UNKNOWN_VERSION, derivedEvidence, evidenceSpan, fileEvidence, fileVersion, versionOfBytes, versionOfText,
} from '../context/evidence';
import { MAX_ARCHIVED_BYTES, archiveDirectory, archiveOutput, readArchivedOutput } from '../context/output.archive';
import { createContextArchiveTool } from '../tools/implementations/context-archive.tool';
import { createReadFileTool } from '../tools/implementations/file.tool';
import { ContextManager } from '../memory/context.manager';
import { VectorStore } from '../memory/vector.store';
import { answeringExcerpt, recallForTurn } from '../memory/recall';
import { fileStateCache, hashFileText } from '../memory/file-state-cache';
import { CodeIndex } from '../memory/code.index';
import { openSqlite } from '../core/sqlite';
import { AgentLoop } from '../core/agent.loop';
import { ToolRegistry } from '../tools/tool.registry';

/**
 * Record 50 step 5: the evidence foundation. Exit conditions, as tests: every admitted item carries its source,
 * version and scope, and changing one of two inputs invalidates only what was built from it.
 */

const SHA256_VERSION = /^sha256:[0-9a-f]{64}$/;
const governor = { approveTaskExecution: async () => {} } as any;
const summarizer = { async *chat() { yield { type: 'token', text: '## Goal\nFixture summary.' }; } } as any;
const JAN_1 = new Date('2026-01-01T00:00:00Z');

const textOf = (result: unknown): string => (typeof result === 'string' ? result : JSON.stringify(result));

function source(sourceId: string, version: string) {
  return evidenceSpan({
    sourceId, sourceVersion: version, locator: { kind: 'file', path: sourceId.slice(5) },
    text: sourceId, scope: {}, derivedFrom: [], kind: 'source',
  });
}

function toolExchange(id: string, content: string): any[] {
  return [
    { role: 'assistant', content: '', tool_calls: [{ id, type: 'function', function: { name: 'Bash', arguments: '{}' } }] },
    { role: 'tool', tool_call_id: id, content },
  ];
}

function sqliteHasFts5(): boolean {
  const db = openSqlite(':memory:');
  if (!db) return false;
  try {
    db.exec('CREATE VIRTUAL TABLE fts5_probe USING fts5(x)');
    return true;
  } catch {
    return false;
  } finally {
    db.close();
  }
}

/** Rewrites a file with same-length text and puts the old modification time back. */
function rewriteKeepingSizeAndMtime(file: string, text: string): void {
  const before = fs.statSync(file);
  fs.writeFileSync(file, text);
  fs.utimesSync(file, JAN_1, JAN_1);
  const after = fs.statSync(file);
  expect([after.mtimeMs, after.size]).toEqual([before.mtimeMs, before.size]);
}

let temp: string;
let previousStateDir: string | undefined;
beforeAll(() => {
  temp = fs.mkdtempSync(path.join(os.tmpdir(), 'bimax-context-evidence-'));
  previousStateDir = process.env.BIMAX_STATE_DIR;
  process.env.BIMAX_STATE_DIR = path.join(temp, 'state');
});
afterAll(() => {
  if (previousStateDir === undefined) delete process.env.BIMAX_STATE_DIR;
  else process.env.BIMAX_STATE_DIR = previousStateDir;
  fs.rmSync(temp, { recursive: true, force: true });
});

describe('dependency invalidation', () => {
  test('changing one of two inputs invalidates only what was built from it', () => {
    const store = new ContextEvidence();
    const a = store.admit(source('file:/a', 'sha256:a1'));
    const b = store.admit(source('file:/b', 'sha256:b1'));
    const fromA = store.admit(derivedEvidence('from-a', 'built from a', [a]));
    const fromB = store.admit(derivedEvidence('from-b', 'built from b', [b]));
    const fromBoth = store.admit(derivedEvidence('from-both', 'built from a and b', [a, b]));
    const fromDerived = store.admit(derivedEvidence('from-derived', 'built from both', [fromBoth]));

    // Control: reporting the version a span already has changes nothing.
    expect(store.sourceChanged('file:/b', 'sha256:b1')).toEqual([]);

    expect(store.sourceChanged('file:/a', 'sha256:a2').sort()).toEqual([a.id, fromA.id, fromBoth.id, fromDerived.id].sort());
    expect([b, fromB].map((span) => store.isStale(span.id))).toEqual([false, false]);
    expect(store.staleReason(fromDerived.id)).toContain(`span:${fromBoth.id}`);
  });

  test('an unknown version is never taken as current, not even when the current version is unknown too', () => {
    const store = new ContextEvidence();
    const unknown = store.admit(source('file:/legacy', UNKNOWN_VERSION));
    expect(store.sourceChanged('file:/legacy', 'sha256:whatever')).toEqual([unknown.id]);
    const unverifiable = store.admit(source('file:/unverifiable', UNKNOWN_VERSION));
    expect(store.sourceChanged('file:/unverifiable', UNKNOWN_VERSION)).toEqual([unverifiable.id]);
  });

  test('a gone source makes its spans stale', () => {
    const store = new ContextEvidence();
    const span = store.admit(source('file:/gone', 'sha256:x'));
    expect(store.sourceChanged('file:/gone', null)).toEqual([span.id]);
    expect(store.staleReason(span.id)).toContain('gone or unreadable');
  });

  test('file sources are re-checked from their bytes, even when size and mtime are put back', async () => {
    const changed = path.join(temp, 'changed.ts');
    const steady = path.join(temp, 'steady.ts');
    fs.writeFileSync(changed, 'export const value = "before";\n');
    fs.writeFileSync(steady, 'export const steady = true;\n');
    fs.utimesSync(changed, JAN_1, JAN_1);
    const store = new ContextEvidence();
    const changedSpan = store.admit(fileEvidence(changed, 'value', (await fileVersion(changed))!));
    const steadySpan = store.admit(fileEvidence(steady, 'steady', (await fileVersion(steady))!));
    expect(changedSpan.sourceVersion).toMatch(SHA256_VERSION);

    fs.writeFileSync(changed, 'export const value = "after!";\n');
    fs.utimesSync(changed, JAN_1, JAN_1);
    expect(await store.refreshFileSources()).toEqual([changedSpan.id]);
    expect(store.isStale(steadySpan.id)).toBe(false);
  });

  test('the store is bounded and counts what it evicts', () => {
    const store = new ContextEvidence(2);
    ['file:/1', 'file:/2', 'file:/3'].forEach((id) => store.admit(source(id, 'sha256:v')));
    expect(store.all()).toHaveLength(2);
    expect(store.evictedCount).toBe(1);
  });

  // Audit 51, U03: identity, eviction and late admission each let a dependant stay current after its input changed.
  test('the same words built from two different inputs are two spans, and each goes stale only with its own input', () => {
    const store = new ContextEvidence();
    const a = store.admit(source('file:/a', 'sha256:a1'));
    const b = store.admit(source('file:/b', 'sha256:b1'));
    const fromA = store.admit(derivedEvidence('summary', 'the same words', [a]));
    const fromB = store.admit(derivedEvidence('summary', 'the same words', [b]));
    expect(fromA.id).not.toBe(fromB.id);
    expect(store.sourceChanged('file:/b', 'sha256:b2').sort()).toEqual([b.id, fromB.id].sort());
    expect(store.isStale(fromA.id)).toBe(false);
  });

  test('evicting a span makes everything built from it stale, at the default bound too', () => {
    const small = new ContextEvidence(2);
    const a = small.admit(source('file:/a', 'sha256:a1'));
    const child = small.admit(derivedEvidence('child', 'built from a', [a]));
    small.admit(source('file:/b', 'sha256:b1'));
    expect(small.get(a.id)).toBeUndefined();
    expect(small.staleReason(child.id)).toContain('evicted');

    const store = new ContextEvidence();
    const parent = store.admit(source('file:/parent', 'sha256:p'));
    const kid = store.admit(derivedEvidence('kid', 'built from parent', [parent]));
    const grandkid = store.admit(derivedEvidence('grandkid', 'built from kid', [kid]));
    for (let i = 0; i < 1997; i++) store.admit(source(`file:/filler-${i}`, 'sha256:f'));
    // Control: at exactly the bound nothing is evicted and nothing is stale.
    expect([store.evictedCount, store.isStale(kid.id)]).toEqual([0, false]);
    store.admit(source('file:/one-more', 'sha256:f'));
    expect(store.evictedCount).toBe(1);
    expect([kid, grandkid].map((span) => store.isStale(span.id))).toEqual([true, true]);
  });

  test('a span built from a stale or unrecorded span is stale from the moment it is admitted', () => {
    const store = new ContextEvidence();
    const a = store.admit(source('file:/a', 'sha256:a1'));
    store.sourceChanged('file:/a', 'sha256:a2');
    const late = store.admit(derivedEvidence('late', 'built after a changed', [a]));
    expect(store.staleReason(late.id)).toContain(`span:${a.id}`);
    const orphan = store.admit(derivedEvidence('orphan', 'built from a span never admitted', [source('file:/never', 'sha256:n')]));
    expect(store.staleReason(orphan.id)).toContain('not in the record');
    // Control: built from a current span, a span is current.
    const b = store.admit(source('file:/b', 'sha256:b1'));
    expect(store.isStale(store.admit(derivedEvidence('fine', 'built from b', [b])).id)).toBe(false);
  });

  test('a file version is taken from its bytes, so two different invalid UTF-8 files never share one', async () => {
    const file = path.join(temp, 'bytes.bin');
    fs.writeFileSync(file, Buffer.from([0x61, 0xff]));
    const first = await fileVersion(file);
    fs.writeFileSync(file, Buffer.from([0x61, 0xfe]));
    expect(await fileVersion(file)).not.toBe(first);
    // Valid UTF-8: the byte version equals the text version, so versions taken either way still compare.
    fs.writeFileSync(file, 'plain text ✓\n');
    expect(await fileVersion(file)).toBe(versionOfText('plain text ✓\n'));
  });
});

describe('the context archive', () => {
  test('returns exactly what was archived, checks the hash, and says why when it cannot', () => {
    const text = 'line one\nline two\nline three\n';
    const first = archiveOutput(text)!;
