/**
 * The originating failure: asked for a PDF the agent had no tool for it, wrote prose with
 * WriteFileTool and named the file `.pdf`. `file` reported "Unicode text" and nothing could open
 * it. So these tests assert the FORMAT SIGNATURE on disk, not that a function returned.
 */
const governor: any = { approveTaskExecution: async () => true, mode: 'bypass' };

const PDF_MAGIC = Buffer.from('%PDF-');
/** docx / pptx / xlsx are ZIP containers; the local file header is 50 4b 03 04. */
const ZIP_MAGIC = Buffer.from([0x50, 0x4b, 0x03, 0x04]);

describe('DocumentTool produces real, openable files', () => {
  let dir: string;
  const tool = createDocumentTool(governor);
  const run = (args: Record<string, unknown>): Promise<string> =>
    tool.execute(args, { cwd: dir }) as Promise<string>;

  beforeEach(() => { dir = fs.mkdtempSync(path.join(os.tmpdir(), 'bimax-doc-')); });
  afterEach(() => { fs.rmSync(dir, { recursive: true, force: true }); });

  const prose = {
    title: 'Approval Note',
    blocks: [
      { kind: 'heading', level: 1, text: 'Recommendation' },
      { kind: 'paragraph', text: 'Replace the spool during the current window.' },
      { kind: 'table', columns: ['Point', 'Measured'], rows: [['TP-02', '5.98'], ['TP-04', '5.61']] },
    ],
  };

  test('pdf carries the PDF signature, not prose in a renamed file', async () => {
    const out = await run({ format: 'pdf', path: 'note.pdf', spec: prose });
    expect(out).toContain('note.pdf');
    const bytes = fs.readFileSync(path.join(dir, 'note.pdf'));
    expect(bytes.subarray(0, 5)).toEqual(PDF_MAGIC);
  });

  test('docx and xlsx are real OOXML containers', async () => {
    await run({ format: 'docx', path: 'a.docx', spec: prose });
    await run({ format: 'xlsx', path: 'a.xlsx', spec: { title: 'Book', sheets: [{ name: 'S', columns: ['A'], rows: [[1]] }] } });
    for (const f of ['a.docx', 'a.xlsx']) {
      expect(fs.readFileSync(path.join(dir, f)).subarray(0, 4)).toEqual(ZIP_MAGIC);
    }
  });

  /**
   * pptxgenjs uses a dynamic `import()` internally, which jest's CJS sandbox cannot execute
   * ("A dynamic import callback was invoked without --experimental-vm-modules"). That is a test-
   * runner limit, not a product one — the engine is bundled by bun and runs under real node. So
   * this builds the deck in a real node process and asserts the bytes it wrote, rather than
   * skipping the only format jest happens to be unable to load.
   */
  test('pptx is a real OOXML container with a slide per entry', () => {
    const { execFileSync } = require('node:child_process') as typeof import('node:child_process');
    const out = path.join(dir, 'a.pptx');
    const script = `
      const { buildPptx } = require('${path.resolve(__dirname, '..', 'documents', 'pptx.writer')}');
      const fs = require('fs');
      buildPptx({ title: 'Deck', slides: [{ title: 'One', bullets: ['x'] }, { title: 'Two', statement: '11 months' }] })
        .then(b => { fs.writeFileSync('${out}', b); })
        .catch(e => { console.error(e); process.exit(1); });
    `;
    execFileSync('npx', ['tsx', '-e', script], { cwd: path.resolve(__dirname, '..', '..'), stdio: 'pipe', timeout: 120_000 });

    const bytes = fs.readFileSync(out);
    expect(bytes.subarray(0, 4)).toEqual(ZIP_MAGIC);
    // A cover plus the two content slides.
    const text = bytes.toString('latin1');
    expect(text).toContain('ppt/slides/slide3.xml');
  }, 150_000);

  test('the xlsx total is a live SUM formula, not a typed-in number', async () => {
    await run({
      format: 'xlsx', path: 'n.xlsx',
      spec: { title: 'N', sheets: [{ name: 'S', columns: ['Item', 'Qty'], rows: [['a', 2], ['b', 3]], totals: [1] }] },
    });
    const buf = fs.readFileSync(path.join(dir, 'n.xlsx'));
    const zlib = require('node:zlib') as typeof import('node:zlib');
    let found = false;
    for (let i = 0; i + 30 < buf.length && !found; i++) {
      if (!(buf[i] === 0x50 && buf[i + 1] === 0x4b && buf[i + 2] === 0x03 && buf[i + 3] === 0x04)) continue;
      const nameLen = buf.readUInt16LE(i + 26);
      const extraLen = buf.readUInt16LE(i + 28);
      try {
        const body = buf.subarray(i + 30 + nameLen + extraLen);
        const text = zlib.inflateRawSync(body, { finishFlush: zlib.constants.Z_SYNC_FLUSH }).toString();
        if (text.includes('SUM(')) found = true;
      } catch { /* not a deflated member we can read from here */ }
    }
    expect(found).toBe(true);
  });

  test('a mismatched extension is refused rather than written', async () => {
    const out = await run({ format: 'pdf', path: 'note.txt', spec: prose });
    expect(out).toMatch(/must match/i);
    expect(fs.existsSync(path.join(dir, 'note.txt'))).toBe(false);
  });

  test('a malformed table is refused with the offending row named', async () => {
    const out = await run({
      format: 'docx', path: 'b.docx',
      spec: { title: 'T', blocks: [{ kind: 'table', columns: ['A', 'B'], rows: [['only-one']] }] },
    });
    expect(out).toMatch(/rows\[0\]/);
    expect(fs.existsSync(path.join(dir, 'b.docx'))).toBe(false);
  });
});

import * as fs from 'fs/promises';
import * as path from 'path';
import * as os from 'os';
import { createEditFileTool } from '../tools/implementations/edit.tool';
import { createMultiEditTool } from '../tools/implementations/multiedit.tool';
import { IGovernor } from '../core/interfaces';

const governor = { approveTaskExecution: jest.fn().mockResolvedValue(undefined) } as unknown as IGovernor;

// Regression: String.prototype.replace interprets `$$`, `$&`, `` $` `` and `$'` in a STRING
// replacement even when the search pattern is a plain string. A newString carrying those (Makefiles,
// shell `$$`/PID, sed/regex code) used to be silently corrupted on write. The tools now use a
// replacer FUNCTION, so the replacement text lands verbatim.
describe('edit tools insert $-bearing replacement text verbatim (no $-pattern expansion)', () => {
  let dir: string;
  beforeEach(async () => { dir = await fs.mkdtemp(path.join(os.tmpdir(), 'bimax-dollar-')); });
  afterEach(async () => { await fs.rm(dir, { recursive: true, force: true }); });

  it('EditFileTool: $$ stays $$ (not collapsed to $)', async () => {
    const file = path.join(dir, 'Makefile');
    await fs.writeFile(file, 'target:\n\techo PLACEHOLDER\n', 'utf8');
    await createEditFileTool(governor).execute(
      { file_path: file, old_string: 'PLACEHOLDER', new_string: 'price is $$5 and $& and $`' } as any,
      { cwd: dir },
    );
    expect(await fs.readFile(file, 'utf8')).toBe('target:\n\techo price is $$5 and $& and $`\n');
  });

  it('MultiEditTool: $-sequences are inserted literally', async () => {
    const file = path.join(dir, 'script.sh');
    await fs.writeFile(file, 'echo OLD\n', 'utf8');
    await createMultiEditTool(governor).execute(
      { edits: [{ file_path: file, old_string: 'OLD', new_string: 'pid=$$ arg=$1 whole=$&' }] } as any,
      { cwd: dir },
    );
    expect(await fs.readFile(file, 'utf8')).toBe('echo pid=$$ arg=$1 whole=$&\n');
  });
});

import * as fs from 'fs/promises';
import * as path from 'path';
import * as os from 'os';
import { createEditFileTool, closestRegion } from '../tools/implementations/edit.tool';
import { createMultiEditTool } from '../tools/implementations/multiedit.tool';
import { IGovernor } from '../core/interfaces';

const governor = { approveTaskExecution: jest.fn().mockResolvedValue(undefined) } as unknown as IGovernor;

// MiniMax (and similar) struggle to reproduce deeply-indented multi-line blocks verbatim — the #1
// cause of the failed-edit loop. MultiEdit used to be exact-match-only, so one wrong space aborted
// the whole batch. It now shares EditFileTool's fuzzy chain, and a true miss reports the closest
// region so the model can self-correct instead of re-sending the same near-miss.
describe('edit fuzzy recovery + actionable miss hint', () => {
  let dir: string;
  beforeEach(async () => { dir = await fs.mkdtemp(path.join(os.tmpdir(), 'bimax-fuzzy-')); });
  afterEach(async () => { await fs.rm(dir, { recursive: true, force: true }); });

  const indented = [
    'class Rule {',
    '  evaluate() {',
    '                                verdicts.push({',
    '                                  kind: "JWT",',
    '                                  evidence: count,',
    '                                });',
    '  }',
    '}',
    '',
  ].join('\n');

  it('MultiEdit recovers an edit whose indentation drifted (was exact-only → aborted the batch)', async () => {
    const file = path.join(dir, 'rule.ts');
    await fs.writeFile(file, indented, 'utf8');
    // Model emits the block with collapsed indentation — must still match via IndentationFlexible.
    const res = await createMultiEditTool(governor).execute(
      {
        edits: [{
          path: file,
          oldString: 'verdicts.push({\n  kind: "JWT",\n  evidence: count,\n});',
          newString: 'verdicts.push({\n  kind: "JWT",\n  evidence: count,\n  severity: severityFromEvidenceCount(count),\n});',
        }],
      } as any,
      { cwd: dir },
    );
    expect(String(res)).not.toMatch(/not found/i);
    expect(await fs.readFile(file, 'utf8')).toContain('severityFromEvidenceCount(count)');
  });

  it('a genuine miss returns the closest region (line-numbered) instead of a bare "not found"', async () => {
    const file = path.join(dir, 'rule.ts');
    await fs.writeFile(file, indented, 'utf8');
    // Near-miss the fuzzy chain genuinely can't resolve (different first + last lines, so BlockAnchor
    // and ContextAware both fail), yet a middle line ("evidence: count,") matches the file exactly —
    // so the hint should still surface the real region.
    const res = String(await createEditFileTool(governor).execute(
      {
        path: file,
        oldString: 'verdicts.append({\n  evidence: count,\n  weight: 9,\n})',
        newString: 'x',
      } as any,
      { cwd: dir },
    ));
    expect(res).toMatch(/not found/i);
    expect(res).toMatch(/closest region/i);
    expect(res).toMatch(/verdicts\.push/); // shows the real nearby text with a line number
  });

  it('shows a multiline near-miss when the requested oldString was flattened to one line', async () => {
    const file = path.join(dir, 'ledger.mjs');
    const content = [
      'export function buildBalances(transactions) {',
      '  const balances = new Map();',
      '',
      '  for (const transaction of transactions) {',
      '    balances.set(transaction.account, transaction.cents);',
      '  }',
      '',
      '  return balances;',
      '}',
      '',
    ].join('\n');
    await fs.writeFile(file, content, 'utf8');

    const res = String(await createEditFileTool(governor).execute(
      {
        path: file,
        oldString: content.replace(/\s+/g, ' ').trim(),
        newString: 'replacement',
      } as any,
      { cwd: dir },
    ));

    expect(res).toMatch(/not found/i);
    expect(res).toMatch(/closest region/i);
    expect(res).toContain('export function buildBalances(transactions) {');
    expect(res).toMatch(/Copy oldString VERBATIM/);
  });

  it('explains the approximate region when Edit Shield rejects a fuzzy block match', async () => {
    const file = path.join(dir, 'ledger.mjs');
    const content = [
      'export function buildBalances(transactions) {',
      '  const balances = new Map();',
      '',
      '  for (const transaction of transactions) {',
      '    balances.set(',
      '      transaction.account,',
      '      (balances.get(transaction.account) ?? 0) + transaction.cents,',
      '    );',
      '  }',
      '',
      '  return balances;',
      '}',
      '',
    ].join('\n');
    const oldString = content.split('\n').filter(line => line !== '').join('\n').trimEnd();
    const newString = [
      'export function buildBalances(transactions) {',
      '  const balances = new Map();',
      '  const seen = new Set();',
      '  for (const transaction of transactions) {',
      '    if (seen.has(transaction.id)) continue;',
      '    seen.add(transaction.id);',
      '    balances.set(transaction.account, transaction.cents);',
      '  }',
      '  return balances;',
      '}',
    ].join('\n');
    await fs.writeFile(file, content, 'utf8');

    const res = String(await createEditFileTool(governor).execute(
      { path: file, oldString, newString } as any,
      { cwd: dir },
    ));

    expect(res).toContain('Edit Shield');
    expect(res).toContain('oldString was not an exact match');
    expect(res).toContain('via BlockAnchor');
    expect(res).toContain('wrong or incomplete region');
    expect(res).toContain('do not switch write mechanisms');
    expect(await fs.readFile(file, 'utf8')).toBe(content);
  });

  it('closestRegion returns null when nothing in the file resembles oldString', () => {
    expect(closestRegion('const a = 1;\nconst b = 2;\n', 'completely unrelated zzzzz qqqqq')).toBeNull();
  });
});

import * as fs from 'fs/promises';
import * as path from 'path';
import * as os from 'os';
import { createEditFileTool } from '../tools/implementations/edit.tool';
import { createMultiEditTool } from '../tools/implementations/multiedit.tool';
import { IGovernor } from '../core/interfaces';

const governor = { approveTaskExecution: jest.fn().mockResolvedValue(undefined) } as unknown as IGovernor;

// Models trained on Claude Code emit snake_case keys (file_path / old_string / new_string). The tools
// must accept those as well as our camelCase schema — previously they arrived as undefined fields and
// failed with "edit #1 (undefined): newString must differ from oldString".
describe('edit tools accept snake_case (Claude-Code style) params', () => {
  let dir: string;
  beforeEach(async () => { dir = await fs.mkdtemp(path.join(os.tmpdir(), 'bimax-snake-')); });
  afterEach(async () => { await fs.rm(dir, { recursive: true, force: true }); });

  it('EditFileTool applies a snake_case edit', async () => {
    const file = path.join(dir, 'a.txt');
    await fs.writeFile(file, 'hello world', 'utf8');
    const res = await createEditFileTool(governor).execute(
      { file_path: file, old_string: 'hello world', new_string: 'hi world' } as any,
      { cwd: dir },
    );
    expect(String(res)).not.toMatch(/must differ|undefined/i);
    expect(await fs.readFile(file, 'utf8')).toBe('hi world');
  });

  it('MultiEditTool applies snake_case edits', async () => {
    const file = path.join(dir, 'b.txt');
    await fs.writeFile(file, 'alpha beta', 'utf8');
    const res = await createMultiEditTool(governor).execute(
      { edits: [{ file_path: file, old_string: 'alpha', new_string: 'ALPHA' }] } as any,
      { cwd: dir },
    );
    expect(String(res)).not.toMatch(/must differ|undefined/i);
    expect(await fs.readFile(file, 'utf8')).toBe('ALPHA beta');
  });
});

import * as http from 'http';
import * as net from 'net';
import * as dns from 'dns';
import {
  installEgressPerimeter, uninstallEgressPerimeter, isEgressPerimeterInstalled,
  _resetPerimeterDedupeForTests,
} from '../security/egress.perimeter';
import { EgressRefused } from '../security/egress.guard';
import { setSovereignMode, setSovereignAllowlist, resetSovereignMode } from '../security/sovereign';
import { resetSessionEgress, sessionEgress, summarize } from '../security/egress.ledger';

// The ledger writes NDJSON beside the workspace; point it at a temp file so the suite never
// appends to the real audit trail.
const LEDGER = `${process.env.TMPDIR || '/tmp'}/bimax-perimeter-test-${process.pid}.ledger`;

/**
 * Call a connect-style primitive and immediately tear down whatever it returns.
 *
 * These assertions are about whether the PERIMETER refuses, not about whether anything is
 * listening. Without this the socket that is allowed through really does try to connect, and its
 * unhandled 'error' event (ECONNREFUSED, or ENOENT for a docker socket that is not running) takes
 * down the Jest worker.
 */
function attempt(fn: () => unknown): void {
  const handle = fn() as { on?: (e: string, cb: () => void) => void; destroy?: () => void } | undefined;
  handle?.on?.('error', () => undefined);
  handle?.destroy?.();
}

beforeAll(() => { process.env.BIMAX_EGRESS_LEDGER = LEDGER; });
beforeEach(() => {
  resetSovereignMode();
  resetSessionEgress();
  _resetPerimeterDedupeForTests();
  installEgressPerimeter();
});
afterEach(() => {
  uninstallEgressPerimeter();
  resetSovereignMode();
});
afterAll(() => {
  try { require('fs').unlinkSync(LEDGER); } catch { /* nothing to clean */ }
  delete process.env.BIMAX_EGRESS_LEDGER;
});

describe('installEgressPerimeter', () => {
  it('is idempotent — a second install does not double-wrap', () => {
    const once = (globalThis as any).fetch;
    installEgressPerimeter();
    expect((globalThis as any).fetch).toBe(once);
    expect(isEgressPerimeterInstalled()).toBe(true);
  });

  it('restores every primitive on uninstall', () => {
    const patched = { fetch: (globalThis as any).fetch, request: http.request, connect: net.connect, lookup: dns.lookup };
    uninstallEgressPerimeter();
    expect((globalThis as any).fetch).not.toBe(patched.fetch);
    expect(http.request).not.toBe(patched.request);
    expect(net.connect).not.toBe(patched.connect);
    expect(dns.lookup).not.toBe(patched.lookup);
    installEgressPerimeter(); // afterEach expects it installed
  });
});

describe('refusal in sovereign mode', () => {
  beforeEach(() => setSovereignMode(true));

  it('refuses an external fetch and never reaches the network', async () => {
    await expect((globalThis as any).fetch('https://api.openai.com/v1/models')).rejects.toThrow(EgressRefused);
  });

  it('refuses an external http.request synchronously', () => {
    expect(() => http.request('http://example.com/x')).toThrow(EgressRefused);
  });

  it('refuses a raw socket to an external host — the bypass the old guard could not see', () => {
    // browser.runtime.ts, mcp/client.ts and the embedding backend all reached the network this way
    // without ever touching checkEgress.
    expect(() => net.connect(443, 'api.openai.com')).toThrow(EgressRefused);
  });

  it('refuses a name lookup, because resolving a hostname already leaks it', () => {
    // telemetry/netprobe.ts did exactly this to the provider origin on every stalled turn.
    expect(() => dns.lookup('secret-project.example.com', () => undefined)).toThrow(EgressRefused);
  });

  it('names the host and the setting that would legitimately permit it', () => {
    try {
      net.connect(8443, 'models.corp.mrpl');
      throw new Error('should have refused');
    } catch (e: any) {
      expect(e).toBeInstanceOf(EgressRefused);
      expect(e.message).toContain('models.corp.mrpl');
      expect(e.message).toContain('BIMAX_SOVEREIGN_ALLOW');
      expect(e.message).toContain('No data left the premises');
    }
  });
});

describe('what sovereign mode must NOT break', () => {
  beforeEach(() => setSovereignMode(true));

  it('permits loopback, so a local model server still serves', () => {
    expect(() => attempt(() => http.request('http://127.0.0.1:11434/v1/chat/completions'))).not.toThrow();
    expect(() => attempt(() => http.request('http://localhost:8000/v1/models'))).not.toThrow();
  });

  it('permits a private-LAN GPU box', () => {
    expect(() => attempt(() => net.connect(8000, '10.4.1.20'))).not.toThrow();
  });

  it('permits an operator-allowlisted on-premises host', () => {
    setSovereignAllowlist(['models.corp.mrpl']);
    expect(() => attempt(() => net.connect(8443, 'models.corp.mrpl'))).not.toThrow();
  });

  it('ignores a Unix domain socket — it is not a network hop', () => {
    // A Docker client talks to /var/run/docker.sock. Treating a filesystem path as an unresolvable
    // hostname would classify it external and break local tooling the moment the mode came on.
    expect(() => attempt(() => net.connect('/var/run/docker.sock'))).not.toThrow();
    expect(() => attempt(() => http.request({ socketPath: '/var/run/docker.sock', path: '/info' }))).not.toThrow();
  });

  it('treats a port with no host as localhost rather than as an empty target', () => {
    expect(() => attempt(() => net.connect({ port: 11434 }))).not.toThrow();
  });
});

describe('the ledger the audit reads', () => {
  it('records allowed loopback traffic, not only refusals', () => {
    setSovereignMode(true);
    attempt(() => http.request('http://127.0.0.1:11434/v1/models'));
    const summary = summarize(sessionEgress());
    expect(summary.attempts).toBeGreaterThan(0);
    expect(summary.loopback).toBeGreaterThan(0);
    expect(summary.external).toBe(0);
    expect(summary.refused).toBe(0);
  });

  it('records a refusal with the external host named', () => {
    setSovereignMode(true);
    expect(() => net.connect(443, 'telemetry.vendor.io')).toThrow(EgressRefused);
    const summary = summarize(sessionEgress());
    expect(summary.external).toBe(1);
    expect(summary.refused).toBe(1);
    expect(summary.externalHosts).toEqual(['telemetry.vendor.io']);
  });

  it('records outside sovereign mode too, so "what did it contact?" is always answerable', () => {
    setSovereignMode(false);
    expect(() => attempt(() => net.connect(443, 'api.openai.com'))).not.toThrow();
    const entries = sessionEgress();
    expect(entries).toHaveLength(1);
    expect(entries[0].verdict).toBe('allowed');
    expect(entries[0].destination).toBe('external');
    expect(entries[0].sovereign).toBe(false);
  });

  it('records one line per request, not one per layer', () => {
    setSovereignMode(false);
    attempt(() => net.connect(443, 'example.com'));
    dns.lookup('example.com', () => undefined);   // the inner layer of the same logical request
    expect(sessionEgress()).toHaveLength(1);
  });

  it('attributes the entry to the calling module, not to the primitive', () => {
    setSovereignMode(false);
    attempt(() => net.connect(443, 'example.com'));
    // This test file is the caller, so the subsystem is read off the stack rather than being
    // the generic layer name.
    expect(sessionEgress()[0].subsystem).toContain('egress.perimeter.test');
    expect(sessionEgress()[0].purpose).toBe('via net.connect');
  });
});

