import * as fs from 'fs';
import * as os from 'os';
import * as path from 'path';
import {
  EpisodeWriter, RecordingProvider, ReplayProvider,
  hashRequest, listEpisodes, loadEpisode, startEpisodeRecording,
} from '../mind/episode.recorder';
import { LLMProvider, Message, ChatOptions, ChatEvent } from '../core/llm.provider';

/** Scripted provider: serves one pre-baked event stream per chat() call, in order. */
function scripted(streams: ChatEvent[][]): LLMProvider {
  let call = 0;
  return {
    async *chat(): AsyncGenerator<ChatEvent> {
      const events = streams[call++] || [{ type: 'done' } as ChatEvent];
      for (const ev of events) yield ev;
    },
  };
}

async function drain(gen: AsyncGenerator<ChatEvent>): Promise<ChatEvent[]> {
  const out: ChatEvent[] = [];
  for await (const ev of gen) out.push(ev);
  return out;
}

const OPTS: ChatOptions = { system: 'you are bimax', tools: [{ function: { name: 'BashTool' } }] };

describe('Episode recorder (v2 Phase 4 — black-box bundles + replay)', () => {
  let dir: string;

  beforeEach(() => {
    dir = fs.mkdtempSync(path.join(os.tmpdir(), 'bgw-episodes-'));
  });
  afterEach(() => {
    fs.rmSync(dir, { recursive: true, force: true });
  });

  const TURN1: ChatEvent[] = [
    { type: 'thinking', text: 'let me check ' }, { type: 'thinking', text: 'the file' },
    { type: 'tool_call', id: 't1', name: 'BashTool', args: '{"command":"ls"}' },
    { type: 'usage', prompt: 100, completion: 20 },
    { type: 'done' },
  ];
  const TURN2: ChatEvent[] = [
    { type: 'token', text: 'All ' }, { type: 'token', text: 'done.' },
    { type: 'usage', prompt: 140, completion: 5 },
    { type: 'done' },
  ];

  async function recordTwoTurnEpisode(): Promise<{ id: string; msgs2: Message[] }> {
    const writer = new EpisodeWriter(dir);
    const rec = new RecordingProvider(scripted([TURN1, TURN2]), writer);
    const msgs1: Message[] = [{ role: 'user', content: 'list the files' }];
    await drain(rec.chat(msgs1, OPTS));
    const msgs2: Message[] = [
      ...msgs1,
      { role: 'assistant', tool_calls: [{ id: 't1', type: 'function', function: { name: 'BashTool', arguments: '{"command":"ls"}' } }] },
      { role: 'tool', tool_call_id: 't1', content: 'a.ts\nb.ts' },
    ];
    await drain(rec.chat(msgs2, OPTS));
    return { id: writer.id, msgs2 };
  }

  it('records a two-call episode: coalesced streams, request deltas, intact hash chain', async () => {
    const { id } = await recordTwoTurnEpisode();

    const ep = loadEpisode(id, dir)!;
    expect(ep).not.toBeNull();
    expect(ep.chainOk).toBe(true);
    expect(ep.header.id).toBe(id);
    expect(ep.calls).toHaveLength(2);

    // Call 0: thinking coalesced, tool call captured, no text.
    expect(ep.calls[0].response.thinking).toBe('let me check the file');
    expect(ep.calls[0].response.toolCalls).toEqual([{ id: 't1', name: 'BashTool', args: '{"command":"ls"}' }]);
    expect(ep.calls[0].response.incomplete).toBeUndefined();
    expect(ep.calls[0].newMessages).toEqual([{ role: 'user', content: 'list the files' }]);

    // Call 1: token stream coalesced; delta holds only the NEW messages (assistant + tool result).
    expect(ep.calls[1].response.text).toBe('All done.');
    expect(ep.calls[1].newMessages.map(m => m.role)).toEqual(['assistant', 'tool']);
    expect(ep.calls[1].newMessages[1].content).toBe('a.ts\nb.ts');
    expect(ep.calls[1].response.usage).toEqual({ prompt: 140, completion: 5 });
  });

  it('replays identical requests deterministically — zero divergence, byte-identical responses', async () => {
    const { id, msgs2 } = await recordTwoTurnEpisode();
    const ep = loadEpisode(id, dir)!;

    const replay = new ReplayProvider(ep.calls);
    const out1 = await drain(replay.chat([{ role: 'user', content: 'list the files' }], OPTS));
    expect(out1).toContainEqual({ type: 'tool_call', id: 't1', name: 'BashTool', args: '{"command":"ls"}' });
    const out2 = await drain(replay.chat(msgs2, OPTS));
    expect(out2).toContainEqual({ type: 'token', text: 'All done.' });
    expect(replay.divergences).toHaveLength(0);
    expect(replay.served).toBe(2);

    // Recording exhausted → unrecoverable error event, not a hang.
    const out3 = await drain(replay.chat(msgs2, OPTS));
    expect(out3[0].type).toBe('error');
  });

  it('flags divergence when the request changes (harness change detection) but still serves in order', async () => {
    const { id } = await recordTwoTurnEpisode();
    const ep = loadEpisode(id, dir)!;

    const replay = new ReplayProvider(ep.calls);
    // A changed system prompt = different request hash = the point of divergence.
    const out = await drain(replay.chat([{ role: 'user', content: 'list the files' }], { ...OPTS, system: 'NEW PROMPT' }));
    expect(out.some(e => e.type === 'tool_call')).toBe(true); // in-order fallback still serves call 0
    expect(replay.divergences).toHaveLength(1);
    expect(replay.divergences[0].idx).toBe(0);
  });

  it('detects tampering — editing a recorded line breaks the chain at that line', async () => {
    const { id } = await recordTwoTurnEpisode();
    const file = path.join(dir, '.bimax', 'episodes', `${id}.jsonl`);
    const lines = fs.readFileSync(file, 'utf-8').trim().split('\n');
    expect(lines[1]).toContain('list the files');
    lines[1] = lines[1].replace('list the files', 'delete everything');
    fs.writeFileSync(file, lines.join('\n') + '\n');

    const ep = loadEpisode(id, dir)!;
    expect(ep.chainOk).toBe(false);
    expect(ep.brokenAt).toBe(2);
  });

  it('an abandoned stream (abort) is recorded as incomplete, not lost', async () => {
    const writer = new EpisodeWriter(dir);
    const rec = new RecordingProvider(scripted([TURN1]), writer);
    const gen = rec.chat([{ role: 'user', content: 'hi' }], OPTS);
    await gen.next();          // consume one event…
    await gen.return(undefined as any); // …then abandon the stream (user interrupt)

    const ep = loadEpisode(writer.id, dir)!;
    expect(ep.calls).toHaveLength(1);
    expect(ep.calls[0].response.incomplete).toBe(true);
  });

  it('lists episodes with call/tool-call counts and hashRequest is order-stable on tool names', async () => {
    await recordTwoTurnEpisode();
    const eps = listEpisodes(dir);
    expect(eps).toHaveLength(1);
    expect(eps[0].calls).toBe(2);
    expect(eps[0].toolCalls).toBe(1);

    const msgs: Message[] = [{ role: 'user', content: 'x' }];
    const a = hashRequest(msgs, { tools: [{ function: { name: 'A' } }, { function: { name: 'B' } }] });
    const b = hashRequest(msgs, { tools: [{ function: { name: 'B' } }, { function: { name: 'A' } }] });
    expect(a).toBe(b);
  });

  it('BIMAX_RECORDER=0 disables recording entirely', async () => {
    process.env.BIMAX_RECORDER = '0';
    try {
      const { llm, id } = startEpisodeRecording(scripted([TURN2]), dir);
      expect(id).toBeNull();
      await drain(llm.chat([{ role: 'user', content: 'hi' }], OPTS));
      expect(listEpisodes(dir)).toHaveLength(0);
    } finally {
      delete process.env.BIMAX_RECORDER;
    }
  });
});

import * as fs from 'fs';
import * as os from 'os';
import * as path from 'path';
import { EventLedger } from '../mind/event.ledger';

describe('EventLedger (v2 D1 minimal — SQLite, append-only, hash-chained)', () => {
  let dir: string;
  let ledger: EventLedger;

  beforeEach(() => {
    dir = fs.mkdtempSync(path.join(os.tmpdir(), 'bgw-ledger-'));
    ledger = new EventLedger(dir);
  });
  afterEach(() => {
    ledger.close();
    fs.rmSync(dir, { recursive: true, force: true });
  });

  it('is available on this Node (node:sqlite) and creates .bimax/ledger.db', () => {
    expect(ledger.isAvailable()).toBe(true);
    expect(fs.existsSync(path.join(dir, '.bimax', 'ledger.db'))).toBe(true);
  });

  it('appends events and reads them back in order with payloads intact', () => {
    ledger.append('tool_outcome', { tool: 'EditFileTool', domain: 'ts', status: 'ok' });
    ledger.append('tool_outcome', { tool: 'BashTool', domain: 'tsc', status: 'ok', exitCode: 2 });
    ledger.append('evidence', { command: 'npx tsc --noEmit', ok: false });
    expect(ledger.count()).toBe(3);
    const tail = ledger.tail(10);
    expect(tail.map(e => e.type)).toEqual(['tool_outcome', 'tool_outcome', 'evidence']);
    expect(tail[1].payload.exitCode).toBe(2);
    expect(ledger.countByType()).toEqual({ tool_outcome: 2, evidence: 1 });
  });

  it('hash chain verifies clean and detects retroactive tampering', () => {
    for (let i = 0; i < 5; i++) ledger.append('tool_outcome', { i });
    expect(ledger.verifyChain()).toEqual({ ok: true, events: 5, brokenAt: null });

    // Tamper with event #3 behind the ledger's back — verification must break AT it.
    const { DatabaseSync } = require('node:sqlite');
    const raw = new DatabaseSync(path.join(dir, '.bimax', 'ledger.db'));
    raw.prepare("UPDATE events SET payload = '{\"i\":999}' WHERE id = 3").run();
    raw.close();
    const v = ledger.verifyChain();
    expect(v.ok).toBe(false);
    expect(v.brokenAt).toBe(3);
  });

  it('the chain stays consistent across ledger instances (prev hash read from the DB, not memory)', () => {
    ledger.append('a', { n: 1 });
    ledger.close();
    const second = new EventLedger(dir);
    second.append('b', { n: 2 });
    expect(second.verifyChain().ok).toBe(true);
    expect(second.count()).toBe(2);
    second.close();
    ledger = new EventLedger(dir); // so afterEach close() has a live instance
  });

  it('append never throws even after close (best-effort recording)', () => {
    ledger.close();
    expect(() => ledger.append('x', {})).not.toThrow();
    expect(ledger.count()).toBe(0);
    expect(ledger.tail()).toEqual([]);
    expect(ledger.verifyChain().ok).toBe(true);
  });
});

import * as fs from 'fs';
import * as os from 'os';
import * as path from 'path';
import {
  ExecutionLedger, LEDGER_SCHEMA_VERSION, redactForLedger, __resetExecutionLedgerForTests,
} from '../core/execution.ledger';

// §7 mandate coverage: reconstruction by folding, corruption recovery (line + whole-file),
// schema-version forward-compat skip, redaction + bounded strings, retention/compaction,
// crash-recovery candidates (interruptedTasks), user cleanup (clearCompleted).

describe('ExecutionLedger', () => {
  let dir: string;
  let ledger: ExecutionLedger;

  beforeEach(() => {
    dir = fs.mkdtempSync(path.join(os.tmpdir(), 'bimax-ledger-'));
    ledger = new ExecutionLedger(dir);
  });
  afterEach(() => {
    fs.rmSync(dir, { recursive: true, force: true });
  });

  test('reconstructs task state by folding created + transitions', () => {
    ledger.append({ taskId: 't1', type: 'created', kind: 'shell', title: 'build it', command: 'make', cwd: '/tmp/x' });
    ledger.append({ taskId: 't1', type: 'transition', state: 'starting' });
    ledger.append({ taskId: 't1', type: 'transition', state: 'running' });
    ledger.append({ taskId: 't1', type: 'transition', state: 'completed' });
    const [t] = ledger.reconstruct();
    expect(t.taskId).toBe('t1');
    expect(t.state).toBe('completed');
    expect(t.resumable).toBe(true); // command + cwd recorded
  });

  test('resumable is false without a recorded command+cwd — never fake resumability', () => {
    ledger.append({ taskId: 'b1', type: 'created', kind: 'browser', title: 'browser session' });
    ledger.append({ taskId: 'b1', type: 'transition', state: 'running' });
    const [t] = ledger.reconstruct();
    expect(t.resumable).toBe(false);
  });

  test('interruptedTasks returns only non-terminal tasks (crash-recovery candidates)', () => {
    ledger.append({ taskId: 'a', type: 'created', kind: 'shell', title: 'a', command: 'sleep 5', cwd: '/tmp' });
    ledger.append({ taskId: 'a', type: 'transition', state: 'running' });
    ledger.append({ taskId: 'b', type: 'created', kind: 'shell', title: 'b', command: 'ls', cwd: '/tmp' });
    ledger.append({ taskId: 'b', type: 'transition', state: 'completed' });
    const interrupted = ledger.interruptedTasks();
    expect(interrupted.map(t => t.taskId)).toEqual(['a']);
  });

  test('retry records fold into a retry count; failure reason captured', () => {
    ledger.append({ taskId: 'r1', type: 'created', kind: 'shell', title: 'flaky', command: 'x', cwd: '/tmp' });
    ledger.append({ taskId: 'r1', type: 'retry', attempt: 1 });
    ledger.append({ taskId: 'r1', type: 'retry', attempt: 2 });
    ledger.append({ taskId: 'r1', type: 'transition', state: 'failed-resumable', reason: 'exit 1' });
    const [t] = ledger.reconstruct();
    expect(t.retries).toBe(2);
    expect(t.failureReason).toBe('exit 1');
  });

  test('corrupt lines are skipped without losing valid records', () => {
    ledger.append({ taskId: 'ok', type: 'created', kind: 'shell', title: 'ok', command: 'ls', cwd: '/tmp' });
    fs.appendFileSync(ledger.filePath, '{"broken json\nnot json at all\n', 'utf-8');
    ledger.append({ taskId: 'ok', type: 'transition', state: 'running' });
    const records = ledger.readAll();
    expect(records).toHaveLength(2);
    expect(ledger.reconstruct()[0].state).toBe('running');
  });

  test('a wholly unreadable file is preserved aside and treated as empty', () => {
    fs.mkdirSync(dir, { recursive: true });
    fs.writeFileSync(ledger.filePath, 'garbage\x00binary\nmore garbage\n', 'utf-8');
    expect(ledger.readAll()).toEqual([]);
    const preserved = fs.readdirSync(dir).filter(f => f.includes('.corrupt-'));
    expect(preserved).toHaveLength(1); // evidence preserved, never silently destroyed
    expect(fs.existsSync(ledger.filePath)).toBe(false);
  });

  test('records with a NEWER schema version are skipped, older/current kept', () => {
    ledger.append({ taskId: 'cur', type: 'created', kind: 'shell', title: 'cur', command: 'ls', cwd: '/tmp' });
    fs.appendFileSync(ledger.filePath, JSON.stringify({
      v: LEDGER_SCHEMA_VERSION + 1, ts: Date.now(), taskId: 'future', type: 'created', title: 'from-the-future',
    }) + '\n', 'utf-8');
    const records = ledger.readAll();
    expect(records.map(r => r.taskId)).toEqual(['cur']);
  });

  test('redaction: sensitive keys and credential-shaped values never reach disk', () => {
    ledger.append({
      taskId: 's1', type: 'created', kind: 'shell', title: 'deploy',
      command: 'curl -H "auth: nvapi-abc123def456ghi789"', cwd: '/tmp',
      data: { apiKey: 'super-secret', nested: { token: 'x', fine: 'keep-me' }, value: 'nvapi-abcdefgh12345678' },
    } as any);
    const raw = fs.readFileSync(ledger.filePath, 'utf-8');
    expect(raw).not.toContain('super-secret');
    expect(raw).not.toContain('nvapi-abc');
    expect(raw).toContain('keep-me');
    expect(raw).toContain('[redacted]');
  });

  test('redaction bounds string sizes (large-output exclusion)', () => {
    const huge = 'x'.repeat(10_000);
    const out = redactForLedger({ note: huge });
    expect((out.note as string).length).toBeLessThan(3000);
    expect(out.note).toContain('[truncated]');
  });

  test('clearCompleted drops terminal tasks, keeps interrupted ones', () => {
    ledger.append({ taskId: 'live', type: 'created', kind: 'shell', title: 'live', command: 'sleep 9', cwd: '/tmp' });
    ledger.append({ taskId: 'live', type: 'transition', state: 'running' });
    ledger.append({ taskId: 'done', type: 'created', kind: 'shell', title: 'done', command: 'ls', cwd: '/tmp' });
    ledger.append({ taskId: 'done', type: 'transition', state: 'completed' });
    const dropped = ledger.clearCompleted();
    expect(dropped).toBe(2); // both 'done' records gone
    expect(ledger.reconstruct().map(t => t.taskId)).toEqual(['live']);
  });

  test('bounded retention: file compacts once past the size budget, live tasks survive', () => {
    // A live task created early — must survive compaction even though it is old data.
    ledger.append({ taskId: 'keepme', type: 'created', kind: 'shell', title: 'keep', command: 'sleep 99', cwd: '/tmp' });
    ledger.append({ taskId: 'keepme', type: 'transition', state: 'running' });
    // Flood with completed-task records until the file crosses 512KB.
    const pad = 'p'.repeat(1500);
    for (let i = 0; i < 400; i++) {
      ledger.append({ taskId: `bulk${i}`, type: 'created', kind: 'shell', title: 'bulk', command: 'ls', cwd: '/tmp', data: { pad } });
      ledger.append({ taskId: `bulk${i}`, type: 'transition', state: 'completed' });
    }
    const size = fs.statSync(ledger.filePath).size;
    expect(size).toBeLessThan(1024 * 1024); // compaction kicked in — file is bounded
    const tasks = ledger.reconstruct();
    expect(tasks.find(t => t.taskId === 'keepme')?.state).toBe('running'); // live task retained in full
  });

  test('append never throws even when the directory is unwritable', () => {
    const ro = new ExecutionLedger('/nonexistent-root-path/nope');
    expect(() => ro.append({ taskId: 'x', type: 'created', title: 'x' })).not.toThrow();
    expect(ro.readAll()).toEqual([]);
  });

  test('__resetExecutionLedgerForTests points the singleton at a fresh dir', () => {
    const l = __resetExecutionLedgerForTests(dir);
    l.append({ taskId: 'sing', type: 'created', title: 'singleton' });
    expect(l.filePath.startsWith(dir)).toBe(true);
  });
});

import * as fs from 'fs';
import * as os from 'os';
import * as path from 'path';
import { ExemplarStore, Exemplar } from '../mind/exemplar.store';
import { embed, cosine, packEmbedding, nearest, setEmbedBackend, embedderInfo, EmbedBackend, EMBED_DIM } from '../mind/embedder';

describe('experience retrieval (v2 §9.3) — verified exemplars into the prompt', () => {
  let dir: string;
  let store: ExemplarStore;

  const seed = (items: Partial<Exemplar>[]) => {
    fs.mkdirSync(path.join(dir, '.bimax'), { recursive: true });
    fs.writeFileSync(
      path.join(dir, '.bimax', 'exemplars.json'),
      JSON.stringify(items.map(e => ({ at: new Date().toISOString(), kind: 'mutation-fix', outcome: 'exact', ...e })), null, 2),
      'utf-8'
    );
  };

  beforeEach(() => {
    dir = fs.mkdtempSync(path.join(os.tmpdir(), 'bgw-exemplar-'));
    store = new ExemplarStore(dir);
  });
  afterEach(() => fs.rmSync(dir, { recursive: true, force: true }));

  it('retrieves the verified win most similar to the task, with its verification named', () => {
    seed([
      { op: 'negate-condition', file: 'src/auth/session.ts', testFile: 'src/__tests__/session.test.ts', defect: 'inverted token expiry check in validateSession' },
      { op: 'off-by-one', file: 'src/render/pager.go', testFile: 'pager_test.go', defect: 'pager scroll boundary off by one' },
    ]);
    const block = store.getPromptBlock('fix the session token expiry validation bug in src/auth/session.ts');
    expect(block).toContain('VERIFIED EXPERIENCE');
    expect(block).toContain('src/auth/session.ts');
    expect(block).toContain('session.test.ts'); // the receipts: every line names its verification
  });

  it('returns an EMPTY block when nothing is similar enough — no vibes injection', () => {
    seed([{ op: 'off-by-one', file: 'src/render/pager.go', testFile: 'pager_test.go', defect: 'pager scroll boundary' }]);
    expect(store.getPromptBlock('rewrite the marketing landing page hero copy')).toBe('');
  });

  it('returns empty on an empty corpus and blank context', () => {
    expect(store.getPromptBlock('anything at all')).toBe('');
    seed([{ op: 'x', file: 'a.ts', testFile: 'a.test.ts' }]);
    expect(store.getPromptBlock('')).toBe('');
  });

  it('backfills missing embeddings on first retrieval and caches them to disk', () => {
    seed([{ op: 'negate-condition', file: 'src/auth/session.ts', testFile: 'session.test.ts', defect: 'session expiry inverted' }]);
    let onDisk = JSON.parse(fs.readFileSync(path.join(dir, '.bimax', 'exemplars.json'), 'utf-8'));
    expect(onDisk[0].embedding).toBeUndefined();

    store.retrieve('session expiry bug in src/auth/session.ts');

    onDisk = JSON.parse(fs.readFileSync(path.join(dir, '.bimax', 'exemplars.json'), 'utf-8'));
    expect(Array.isArray(onDisk[0].embedding)).toBe(true);
    expect(onDisk[0].embedderV).toBe(1);
  });

  it('history-replay exemplars render with their task and recorded evidence', () => {
    seed([{ kind: 'history-replay', outcome: 'verified', task: 'add retry with backoff to the mcp client reconnect path', evidence: 'npx jest mcp.client.test.ts' }]);
    const block = store.getPromptBlock('mcp client reconnect should retry with backoff');
    expect(block).toContain('re-solved');
    expect(block).toContain('npx jest mcp.client.test.ts');
  });
});

describe('local embedder — the honest lexical kernel under retrieval', () => {
  it('similar code-task texts score far above unrelated ones', () => {
    const a = embed('fix the token expiry check in src/auth/session.ts validateSession');
    const b = embed('token expiry validation broken in src/auth/session.ts');
    const c = embed('paint the bikeshed a warmer shade of terracotta');
    expect(cosine(a, b)).toBeGreaterThan(cosine(a, c) + 0.2);
  });

  it('vectors are L2-normalized and survive the packed round-trip', () => {
    const v = embed('some representative input text');
    let mag = 0;
    for (let i = 0; i < v.length; i++) mag += v[i] * v[i];
    expect(Math.sqrt(mag)).toBeCloseTo(1, 5);
    const packed = packEmbedding(v);
    expect(cosine(v, packed)).toBeGreaterThan(0.999);
  });

  it('backend seam: a swapped encoder takes over embed() and bumps embedderInfo().version', () => {
    const fake: EmbedBackend = {
      name: 'fake-onnx', version: 2, dim: EMBED_DIM,
      embed: () => { const v = new Float32Array(EMBED_DIM); v[0] = 1; return v; },
    };
    try {
      setEmbedBackend(fake);
      expect(embedderInfo()).toEqual({ name: 'fake-onnx', version: 2, dim: EMBED_DIM });
      expect(embed('anything')[0]).toBe(1);
    } finally {
      setEmbedBackend(null);
    }
    expect(embedderInfo().name).toBe('hash-kernel'); // the floor is back
    expect(embedderInfo().version).toBe(1);
  });

  it('backend swap re-embeds a cached exemplar corpus — vector spaces never mix', () => {
    const dir2 = fs.mkdtempSync(path.join(os.tmpdir(), 'bgw-exswap-'));
    try {
      fs.mkdirSync(path.join(dir2, '.bimax'), { recursive: true });
      fs.writeFileSync(path.join(dir2, '.bimax', 'exemplars.json'), JSON.stringify([
        { at: new Date().toISOString(), kind: 'mutation-fix', outcome: 'exact', op: 'boundary', file: 'src/a.ts', testFile: 'a.test.ts', defect: 'x' },
      ]), 'utf-8');
      const s = new ExemplarStore(dir2);
      s.retrieve('src/a.ts boundary'); // caches v1 vectors
      expect(JSON.parse(fs.readFileSync(path.join(dir2, '.bimax', 'exemplars.json'), 'utf-8'))[0].embedderV).toBe(1);

      const fake: EmbedBackend = {
        name: 'fake-onnx', version: 2, dim: EMBED_DIM,
        embed: () => { const v = new Float32Array(EMBED_DIM); v.fill(1 / Math.sqrt(EMBED_DIM)); return v; },
      };
      setEmbedBackend(fake);
      try {
        s.retrieve('anything at all');
        expect(JSON.parse(fs.readFileSync(path.join(dir2, '.bimax', 'exemplars.json'), 'utf-8'))[0].embedderV).toBe(2);
      } finally {
        setEmbedBackend(null);
      }
    } finally {
      fs.rmSync(dir2, { recursive: true, force: true });
    }
  });

  it('nearest() ranks by cosine, honors k and the similarity floor', () => {
    const q = embed('session token expiry');
    const items = [
      { id: 1, embedding: packEmbedding(embed('session token expiry check')) },
      { id: 2, embedding: packEmbedding(embed('token session lifetime expiry')) },
      { id: 3, embedding: packEmbedding(embed('completely unrelated three.js gyroscope hero')) },
      { id: 4 }, // no embedding — skipped, never crashes
    ];
    const hits = nearest(q, items, 2, 0.2);
    expect(hits.length).toBeLessThanOrEqual(2);
    expect(hits[0].item.id).toBe(1);
    expect(hits.every(h => h.sim >= 0.2)).toBe(true);
    expect(hits.some(h => (h.item as any).id === 3)).toBe(false);
  });
});

import { Segment } from '../documents/extract';

/**
 * The scanned half of the per-page merge.
 *
 * A page with no text layer has no floor to be measured against, so the decision is different and
 * worth its own suite: the converter runs its own recognizer, so a scanned page it DID read is
 * better than re-recognising it ourselves — but a scanned page it dropped has nothing behind it
 * except OCR, and that page must still be rasterised and read rather than silently omitted.
 *
 * `pdf.raster` and `ocr` are both mocked here so the branch is exercised without poppler, without a
 * recognizer, and without a genuinely scanned fixture. That is the point: the thing under test is
 * the ROUTING DECISION, and the two suites that cover the real readers already exist.
 */

jest.mock('../documents/docling', () => ({
  doclingAvailable: jest.fn(),
  doclingConvert: jest.fn(),
  toSegments: jest.fn(),
}));

jest.mock('../documents/pdf.raster', () => ({
  extractTextLayer: jest.fn(),
  hasTextLayer: jest.fn((text?: string) => !!text && text.replace(/[^\p{L}\p{N}]/gu, '').length >= 20),
  readPdf: jest.fn(),
}));

jest.mock('../documents/ocr', () => ({ ocrPages: jest.fn() }));

// eslint-disable-next-line @typescript-eslint/no-require-imports
const docling = require('../documents/docling') as Record<string, jest.Mock>;
// eslint-disable-next-line @typescript-eslint/no-require-imports
const raster = require('../documents/pdf.raster') as Record<string, jest.Mock>;
// eslint-disable-next-line @typescript-eslint/no-require-imports
const ocr = require('../documents/ocr') as Record<string, jest.Mock>;
// eslint-disable-next-line @typescript-eslint/no-require-imports
const { extractFile } = require('../documents/extract') as typeof import('../documents/extract');

const fs = require('fs') as typeof import('fs');
const os = require('os') as typeof import('os');
const path = require('path') as typeof import('path');

let pdf: string;

const layoutSegment = (page: number, text: string): Segment => ({ text, locator: { page }, via: 'layout' });

beforeAll(() => {
  const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'bimax-layout-ocr-'));
  pdf = path.join(dir, 'scan.pdf');
  // Content is irrelevant — every reader is mocked. It only has to exist and be non-empty.
  fs.writeFileSync(pdf, '%PDF-1.4 stub');
});

beforeEach(() => {
  jest.clearAllMocks();
  docling.doclingAvailable.mockResolvedValue(true);
  docling.doclingConvert.mockResolvedValue([{ path: pdf, ok: true, paged: true, pages: [] }]);
  // Three scanned pages: no text layer anywhere.
  raster.extractTextLayer.mockResolvedValue(['', '', '']);
  raster.readPdf.mockResolvedValue({
    totalPages: 3,
    pages: [
      { page: 1, imagePath: '/tmp/page-1.png', source: 'raster' },
      { page: 2, imagePath: '/tmp/page-2.png', source: 'raster' },
      { page: 3, imagePath: '/tmp/page-3.png', source: 'raster' },
    ],
  });
});

describe('a scanned page the converter read is kept without re-recognising it', () => {
  it('does not rasterise at all when the converter covered every page', async () => {
    docling.toSegments.mockReturnValue([
      layoutSegment(1, 'Scanned findings for course one, recovered by the layout model.'),
      layoutSegment(2, 'Scanned findings for course two, recovered by the layout model.'),
      layoutSegment(3, 'Scanned findings for course three, recovered by the layout model.'),
    ]);

    const result = await extractFile(pdf);

    // The saving that makes this worth doing: no raster pass, no OCR pass.
    expect(raster.readPdf).not.toHaveBeenCalled();
    expect(ocr.ocrPages).not.toHaveBeenCalled();
    expect(result.segments.map((s) => s.via)).toEqual(['layout', 'layout', 'layout']);
  });
});

describe('a scanned page the converter dropped is still read', () => {
  beforeEach(() => {
    ocr.ocrPages.mockResolvedValue({
      backend: 'vision',
      pages: [{ imagePath: '/tmp/page-2.png', text: 'Recovered by OCR: minimum thickness 7.8 mm.', lines: 1, confidence: 0.91 }],
    });
  });

  it('OCRs ONLY the dropped page, not the whole document', async () => {
    docling.toSegments.mockReturnValue([
      layoutSegment(1, 'Scanned findings for course one, recovered by the layout model.'),
      layoutSegment(3, 'Scanned findings for course three, recovered by the layout model.'),
    ]);

    const result = await extractFile(pdf);

    expect(ocr.ocrPages).toHaveBeenCalledTimes(1);
    // Only dropped page 2 is recognized; raster coverage is tested separately with real children.
    expect(ocr.ocrPages).toHaveBeenCalledWith(['/tmp/page-2.png']);

    expect(result.segments.map((s) => s.locator.page)).toEqual([1, 2, 3]);
    expect(result.segments.map((s) => s.via)).toEqual(['layout', 'ocr', 'layout']);
  });

  it('carries the recognizer confidence through, so a weak read can be flagged later', async () => {
    docling.toSegments.mockReturnValue([layoutSegment(1, 'Course one, recovered by the layout model.'), layoutSegment(3, 'Course three, recovered by the layout model.')]);

    const result = await extractFile(pdf);
    const page2 = result.segments.find((s) => s.locator.page === 2)!;

    expect(page2.confidence).toBeCloseTo(0.91);
    expect(page2.text).toContain('7.8 mm');
  });

  it('a page nobody could read is omitted rather than emitted empty', async () => {
    docling.toSegments.mockReturnValue([layoutSegment(1, 'Course one, recovered by the layout model.'), layoutSegment(3, 'Course three, recovered by the layout model.')]);
    ocr.ocrPages.mockResolvedValue({
      backend: 'vision',
      pages: [{ imagePath: '/tmp/page-2.png', text: '   ', lines: 0 }],
    });

    const result = await extractFile(pdf);

    // A citable segment with nothing in it is worse than an acknowledged gap.
    expect(result.segments.map((s) => s.locator.page)).toEqual([1, 3]);
  });

  it('an empty layout string counts as dropped, not as read', async () => {
    docling.toSegments.mockReturnValue([
      layoutSegment(1, 'Course one, recovered by the layout model.'),
      layoutSegment(2, '   '),
      layoutSegment(3, 'Course three, recovered by the layout model.'),
    ]);

    const result = await extractFile(pdf);

    expect(ocr.ocrPages).toHaveBeenCalledWith(['/tmp/page-2.png']);
    expect(result.segments.map((s) => s.via)).toEqual(['layout', 'ocr', 'layout']);
  });
});

describe('when there is no text layer to compare against at all', () => {
  it('a converter result stands on its own when pdftotext is missing', async () => {
    raster.extractTextLayer.mockRejectedValue(new Error('pdftotext is not installed'));
    docling.toSegments.mockReturnValue([layoutSegment(2, 'Only page two was converted.')]);

    const result = await extractFile(pdf);

    // No floor exists, so the layout result is not discarded over a missing comparison — and no
    // raster pass is attempted either, because nothing can be said about the pages it did not cover.
    expect(result.segments).toHaveLength(1);
    expect(result.segments[0].via).toBe('layout');
    expect(ocr.ocrPages).not.toHaveBeenCalled();
  });
});

import {
  FailureMemory, actionFingerprint, operationClass, DEFAULT_BUDGETS,
} from '../core/failure.memory';

// §5 mandate coverage — the FP/FN matrix:
//   TRUE POSITIVES:  same action + same failure repeated past its class budget → exhausted
//   FALSE-POSITIVE guards: changed error resets; different target = different fingerprint;
//                          success clears; new user turn clears; transient classes get patience
//   FALSE-NEGATIVE guards: timestamp/port churn in the target cannot dodge the fingerprint

describe('actionFingerprint', () => {
  test('same action → same fingerprint; different target → different fingerprint', () => {
    const a = actionFingerprint({ tool: 'ReadTool', target: '/src/a.ts' });
    const b = actionFingerprint({ tool: 'ReadTool', target: '/src/a.ts' });
    const c = actionFingerprint({ tool: 'ReadTool', target: '/src/b.ts' });
    expect(a).toBe(b);
    expect(a).not.toBe(c);
  });

  test('numeric churn (timestamps, ports, PIDs ≥4 digits) cannot dodge the fingerprint', () => {
    const a = actionFingerprint({ tool: 'BashTool', target: 'curl localhost:8901/v1?ts=1721000000' });
    const b = actionFingerprint({ tool: 'BashTool', target: 'curl localhost:8902/v1?ts=1721999999' });
    expect(a).toBe(b); // FN guard — retrying with a fresh timestamp is still the same action
  });

  test('extracts the target from args JSON when no explicit target given', () => {
    const a = actionFingerprint({ tool: 'BashTool', args: JSON.stringify({ command: 'npm test' }) });
    const b = actionFingerprint({ tool: 'BashTool', target: 'npm test' });
    expect(a).toBe(b);
  });

  test('small numbers (exit codes, http/2) are NOT normalized away', () => {
    const a = actionFingerprint({ tool: 'BashTool', target: 'git push origin v1' });
    const b = actionFingerprint({ tool: 'BashTool', target: 'git push origin v2' });
    expect(a).not.toBe(b);
  });
});

describe('operationClass', () => {
  test('classifies by tool and shell command shape', () => {
    expect(operationClass('BashTool', 'npm install left-pad')).toBe('install');
    expect(operationClass('BashTool', 'npm run build')).toBe('build');
    expect(operationClass('BashTool', 'npx jest src/x.test.ts')).toBe('test');
    expect(operationClass('BashTool', 'ls -la')).toBe('shell');
    expect(operationClass('WebFetchTool')).toBe('network');
    expect(operationClass('mcp__github__get_pr')).toBe('network');
    expect(operationClass('ReadTool')).toBe('file');
    expect(operationClass('SomethingNew')).toBe('generic');
  });
});

describe('FailureMemory', () => {
  let mem: FailureMemory;
  beforeEach(() => { mem = new FailureMemory(); });

  const fileAction = { tool: 'ReadTool', target: '/missing.txt' };
  const enoent = { ok: false, errorClass: 'ENOENT' };

  test('TP: same action + same failure exhausts at the class budget', () => {
    const budget = DEFAULT_BUDGETS.file; // 2
    let verdict = mem.report(fileAction, enoent);
    expect(verdict.exhausted).toBe(false);
    verdict = mem.report(fileAction, enoent);
    expect(verdict.repeatCount).toBe(budget);
    expect(verdict.exhausted).toBe(true);
    expect(verdict.note).toContain('failed 2 times');
  });

  test('FP guard: a CHANGED failure resets the counter (the world moved)', () => {
    mem.report(fileAction, enoent);
    const changed = mem.report(fileAction, { ok: false, errorClass: 'EACCES' });
    expect(changed.repeatCount).toBe(1); // different error — retrying was legitimate
    expect(changed.exhausted).toBe(false);
  });

  test('FP guard: different result content resets the counter even with same errorClass', () => {
    mem.report(fileAction, { ok: false, errorClass: 'ERR', resultSample: 'missing symbol foo' });
    const v = mem.report(fileAction, { ok: false, errorClass: 'ERR', resultSample: 'missing symbol bar' });
    expect(v.repeatCount).toBe(1);
  });

  test('FP guard: success wipes the slate for that action', () => {
    mem.report(fileAction, enoent);
    mem.report(fileAction, { ok: true });
    expect(mem.countFor(fileAction)).toBe(0);
    expect(mem.report(fileAction, enoent).repeatCount).toBe(1);
  });

  test('FP guard: similar action on a DIFFERENT target has its own budget', () => {
    mem.report(fileAction, enoent);
    const other = mem.report({ tool: 'ReadTool', target: '/other.txt' }, enoent);
    expect(other.repeatCount).toBe(1); // separate fingerprint, separate count
  });

  test('FP guard: a new user turn resets all counters (user-requested repetition)', () => {
    mem.report(fileAction, enoent);
    mem.report(fileAction, enoent);
    mem.newUserTurn();
    const v = mem.report(fileAction, enoent);
    expect(v.repeatCount).toBe(1);
    expect(v.exhausted).toBe(false);
  });

  test('transient error classes earn extra patience (+2)', () => {
    const net = { tool: 'WebFetchTool', target: 'https://api.example.com' };
    const to = { ok: false, errorClass: 'ETIMEDOUT' };
    const base = DEFAULT_BUDGETS.network; // 4
    let v = { exhausted: false, repeatCount: 0, budget: 0 } as any;
    for (let i = 0; i < base + 1; i++) v = mem.report(net, to);
    expect(v.exhausted).toBe(false); // base budget alone would have tripped by now
    expect(v.budget).toBe(base + 2);
    v = mem.report(net, to);
    expect(v.exhausted).toBe(true);
  });

  test('transient detection also reads the result sample when errorClass is silent', () => {
    const net = { tool: 'WebFetchTool', target: 'https://x.test' };
    const v = mem.report(net, { ok: false, resultSample: 'HTTP 429 rate limit exceeded' });
