import { LlmAdapter } from '../core/llm.adapter';
import { ApiKeyManager } from '../credits/api.key.manager';
import { MemoryKeyUsageStore } from '../credits/key.usage.ledger';
import type { ChatEvent } from '../core/llm.provider';

/**
 * What the adapter actually PUTS ON THE WIRE and reads back, driven through `chat()` with a fake
 * provider. Unit tests of tool.wire.ts prove the mapping; these prove the adapter uses it.
 */

function streamOf(chunks: any[]) {
  return { [Symbol.asyncIterator]: async function* () { for (const c of chunks) yield c; } };
}

function adapterFor(provider: string, model: string, respond: (req: any) => any[] | Error) {
  const manager = new ApiKeyManager([{ keyStr: 'test-key-abcdefghijk', provider, model }], { store: new MemoryKeyUsageStore() });
  const adapter = new LlmAdapter(manager);
  adapter.applyConfig({ model });
  const requests: any[] = [];
  (adapter as any).createClient = () => ({
    chat: {
      completions: {
        create: async (req: any) => {
          requests.push(JSON.parse(JSON.stringify(req)));
          const out = respond(req);
          if (out instanceof Error) throw out;
          return streamOf(out);
        },
      },
    },
  });
  return { adapter, requests };
}

async function collect(gen: AsyncGenerator<ChatEvent>): Promise<ChatEvent[]> {
  const out: ChatEvent[] = [];
  for await (const e of gen) out.push(e);
  return out;
}

const toolCallChunk = (name: string, args: string, extra?: unknown) => ({
  choices: [{ delta: { tool_calls: [{ index: 0, id: 'call_1', function: { name, arguments: args }, ...(extra ? { extra_content: extra } : {}) }] }, finish_reason: null }],
});
const stop = { choices: [{ delta: {}, finish_reason: 'tool_calls' }] };

describe('the adapter sends provider-safe tools and reads the calls back', () => {
  test('an MCP tool with a dotted name is sent valid and the call comes back under its real name', async () => {
    const { adapter, requests } = adapterFor('openai', 'gpt-4.1', (req) => {
      const wire = req.tools[0].function.name;
      return [toolCallChunk(wire, '{"q":"x"}'), stop];
    });
    const events = await collect(adapter.chat(
      [{ role: 'user', content: 'search' },
        { role: 'assistant', tool_calls: [{ id: 'old', type: 'function', function: { name: 'mcp__docs.site__search', arguments: '{}' } }] },
        { role: 'tool', tool_call_id: 'old', content: 'r' }],
      { tools: [{ name: 'mcp__docs.site__search', description: 'search', input_schema: { $schema: 'x', type: 'object', properties: { q: { type: 'string' } } } }] },
    ));
    const sent = requests[0];
    expect(sent.tools[0].function.name).toMatch(/^[a-zA-Z0-9_-]{1,64}$/);
    expect(sent.tools[0].function.parameters.$schema).toBeUndefined();
    // The earlier call in the history went out under the same valid spelling.
    const past = sent.messages.find((m: any) => m.role === 'assistant');
    expect(past.tool_calls[0].function.name).toBe(sent.tools[0].function.name);
    const call = events.find((e) => e.type === 'tool_call') as any;
    expect(call.name).toBe('mcp__docs.site__search');
  });

  test('GPT-6 tool requests are sent with reasoning off; tool-free requests are not', async () => {
    const { adapter, requests } = adapterFor('openai', 'gpt-6-sol', () => [{ choices: [{ delta: { content: 'ok' }, finish_reason: 'stop' }] }]);
    await collect(adapter.chat([{ role: 'user', content: 'hi' }], { tools: [{ name: 'ReadFileTool', input_schema: { type: 'object', properties: {} } }] }));
    await collect(adapter.chat([{ role: 'user', content: 'hi' }], {}));
    expect(requests[0].reasoning_effort).toBe('none');
    expect(requests[1].reasoning_effort).not.toBe('none');
    expect(requests[0].temperature).toBeUndefined();
  });

  test('provider data on a tool call (Gemini thought signature) comes back on the event', async () => {
    const sig = { google: { thought_signature: 'abc123' } };
    const { adapter } = adapterFor('google', 'gemini-3.8-flash', () => [toolCallChunk('ReadFileTool', '{}', sig), stop]);
    const events = await collect(adapter.chat([{ role: 'user', content: 'read' }], { tools: [{ name: 'ReadFileTool', input_schema: { type: 'object', properties: {} } }] }));
    expect((events.find((e) => e.type === 'tool_call') as any).extra).toEqual(sig);
  });

  test('a refused Quick model is retried at once instead of failing the turn', async () => {
    const { adapter, requests } = adapterFor('nvidia', 'moonshotai/kimi-k3', (req) => {
      if (req.model === 'mistralai/mistral-7b-instruct-v0.3') {
        const e: any = new Error("404 Function 'x': Not found for account 'y'. model not found");
        e.status = 404;
        return e;
      }
      return [{ choices: [{ delta: { content: 'hello' }, finish_reason: 'stop' }] }];
    });
    adapter.applyConfig({ liteModel: 'mistralai/mistral-7b-instruct-v0.3' });
    const first = await collect(adapter.chat([{ role: 'user', content: 'hi' }], { lite: true }));
    const err = first.find((e) => e.type === 'error') as any;
    expect(err).toMatchObject({ recoverable: true, kind: 'transient', retryAfterSecs: 0 });
    // The loop's re-ask lands on the work model.
    const second = await collect(adapter.chat([{ role: 'user', content: 'hi' }], { lite: true }));
    expect(requests[requests.length - 1].model).toBe('moonshotai/kimi-k3');
    expect(second.some((e) => e.type === 'token')).toBe(true);
  });

  test('a refused WORK model is still a real error (nothing to fall back to here)', async () => {
    const { adapter } = adapterFor('nvidia', 'dead/model', () => {
      const e: any = new Error('model not found');
      e.status = 404;
      return e;
    });
    const events = await collect(adapter.chat([{ role: 'user', content: 'hi' }], {}));
    expect((events.find((e) => e.type === 'error') as any).recoverable).toBe(false);
  });
});

import { LoopDetector } from '../core/loop-detector';

describe('LoopDetector — interleaved repeats', () => {
  it('fires a hard signal when the SAME call recurs non-consecutively (the thrash bug)', () => {
    const d = new LoopDetector();
    // Model interleaves: read evaluator, then other files, then evaluator again, … never twice in a
    // row. The old "N-in-a-row" check missed this; the count-in-window check must catch it.
    const others = ['a.ts', 'b.ts', 'c.ts'];
    let hard = null as ReturnType<LoopDetector['record']>;
    for (let i = 0; i < 4; i++) {
      d.record('Read', JSON.stringify({ path: 'evaluator.ts' }), 'contents');
      const sig = d.record('Read', JSON.stringify({ path: others[i % others.length] }), 'contents');
      if (sig?.severity === 'hard') hard = sig; // a filler read should never be the hard trigger
    }
    // The 4th interleaved evaluator read is the hard stop.
    const last = d.record('Read', JSON.stringify({ path: 'evaluator.ts' }), 'contents');
    expect(last?.severity).toBe('hard');
    expect(last?.type).toBe('generic_repeat');
  });

  it('does not fire for a normal read → edit → re-read (2 identical reads)', () => {
    const d = new LoopDetector();
    expect(d.record('Read', '{"path":"x.ts"}', 'v1')).toBeNull();
    d.record('Edit', '{"path":"x.ts"}', 'ok');
    expect(d.record('Read', '{"path":"x.ts"}', 'v2')).toBeNull();
  });
});

describe('LoopDetector — error thrashing (varying args, repeated failure)', () => {
  it('fires when the same tool keeps ERRORING with DIFFERENT args', () => {
    const d = new LoopDetector();
    // A classic edit-match spiral: the model tweaks the old_string each time, and each attempt fails.
    // generic_repeat can't see this because the args differ every time.
    let sig = null as ReturnType<LoopDetector['record']>;
    for (let i = 0; i < 4; i++) {
      sig = d.record('EditFileTool', JSON.stringify({ old: `attempt-${i}` }), 'Tool Error: no match found', true);
    }
    expect(sig?.type).toBe('error_thrashing');
    expect(sig?.severity).toBe('hard');
    expect(sig?.tool).toBe('EditFileTool');
  });

  it('escalates soft → hard as failures accumulate', () => {
    const d = new LoopDetector();
    expect(d.record('BashTool', '{"cmd":"a"}', 'err', true)).toBeNull();          // 1 fail
    expect(d.record('BashTool', '{"cmd":"b"}', 'err', true)).toBeNull();          // 2 fails
    expect(d.record('BashTool', '{"cmd":"c"}', 'err', true)?.severity).toBe('soft'); // 3 → soft
  });

  it('does not fire when the calls SUCCEED (isError=false), even with repeated tool', () => {
    const d = new LoopDetector();
    for (let i = 0; i < 6; i++) {
      const sig = d.record('BashTool', JSON.stringify({ cmd: `step-${i}` }), 'ok', false);
      expect(sig).toBeNull();
    }
  });

  it('infers failure from result text when isError is omitted', () => {
    const d = new LoopDetector();
    let sig = null as ReturnType<LoopDetector['record']>;
    for (let i = 0; i < 4; i++) {
      sig = d.record('EditFileTool', JSON.stringify({ old: `v${i}` }), 'Tool Error: could not apply edit');
    }
    expect(sig?.type).toBe('error_thrashing');
  });
});

describe('LoopDetector — visual provider progress', () => {
  const result = (frameHash: string) => JSON.stringify({ ok: true, action: 'click', frameHash, screenshot: `/tmp/${Date.now()}.png` });

  it('allows repeated visual actions while the captured pixels keep changing', () => {
    const d = new LoopDetector();
    for (let i = 0; i < 500; i++) {
      expect(d.record('HostVisionTool', '{"action":"click","x":10,"y":10}', result(`frame-${i}`))).toBeNull();
    }
  });

  it('detects a visual action polling the same unchanged frame', () => {
    const d = new LoopDetector();
    const args = '{"action":"observe"}';
    expect(d.record('HostVisionTool', args, result('same-frame'))).toBeNull();
    expect(d.record('HostVisionTool', args, result('same-frame'))).toBeNull();
    expect(d.record('HostVisionTool', args, result('same-frame'))?.type).toBe('no_progress_poll');
  });

  it('is not defeated by a volatile field in an otherwise identical result', () => {
    // The screenshot path changes every call while the frame does not — which is what a real visual
    // tool emits. Hashing the WHOLE result made this poll invisible: the two guards cancelled out
    // (frameHash suppresses generic_repeat, and no_progress_poll never matched because the path
    // differed), so a vision tool stuck on one frame was caught by nothing. Explicit counters here
    // rather than Date.now(), which made the test above pass or fail on millisecond boundaries.
    const d = new LoopDetector();
    const args = '{"action":"observe"}';
    const withPath = (n: number) =>
      JSON.stringify({ ok: true, action: 'click', frameHash: 'frozen', screenshot: `/tmp/frame-${n}.png` });

    expect(d.record('HostVisionTool', args, withPath(1))).toBeNull();
    expect(d.record('HostVisionTool', args, withPath(2))).toBeNull();
    expect(d.record('HostVisionTool', args, withPath(3))?.type).toBe('no_progress_poll');
  });

  it('still allows progress when the frame changes but the path does not', () => {
    // The mirror image: identical result envelope, moving frame. Must stay silent.
    const d = new LoopDetector();
    const args = '{"action":"observe"}';
    const withFrame = (n: number) =>
      JSON.stringify({ ok: true, action: 'click', frameHash: `frame-${n}`, screenshot: '/tmp/fixed.png' });

    for (let i = 0; i < 20; i++) {
      expect(d.record('HostVisionTool', args, withFrame(i))).toBeNull();
    }
  });
});

