import { Bm25Index, tokenize } from '../memory/bm25';
import { reciprocalRankFusion, RRF_K } from '../memory/fusion';
import { RemoteEmbeddingBackend, normalize, dot, type EmbeddingTransport } from '../memory/embeddings';

/**
 * The retrieval layer, graded on the properties that make it retrieval rather than grep.
 *
 * Every test here is written against a failure the previous implementation actually had, or a trap
 * the new one can silently fall into. "It returns some documents" is not one of them: the store it
 * replaces returned documents too, and returned the wrong ones.
 */

describe('BM25 ranking', () => {
  const corpus = [
    { id: 'a', text: 'the permission flow is broken and the permission dialog is broken' },
    { id: 'b', text: 'permission granted for accessibility on macOS' },
    { id: 'c', text: 'the sidebar animation clips the panel instead of resizing it' },
    { id: 'd', text: 'permission permission permission permission permission permission' },
  ];

  test('a rare term outranks a common one', () => {
    // The defect TF-cosine could not express. "accessibility" appears once in the corpus and
    // identifies exactly one document; "permission" is in three of four and identifies nothing.
    const index = new Bm25Index(corpus);
    const hits = index.search('permission accessibility');
    expect(hits[0].id).toBe('b');
  });

  test('term frequency saturates instead of scaling linearly', () => {
    // Document d says "permission" six times and nothing else. Under TF cosine it is the single
    // best match for the word by a wide margin. Under BM25 the sixth mention is nearly free, so a
    // document that says it twice *in context* is not buried by pure repetition.
    const index = new Bm25Index(corpus);
    const hits = index.search('permission');
    const d = hits.find((h) => h.id === 'd')!;
    const a = hits.find((h) => h.id === 'a')!;
    // Six mentions vs two: a linear model would put d at 3x. Saturation keeps it well under.
    expect(d.score / a.score).toBeLessThan(1.6);
  });

  test('IDF never goes negative, so a ubiquitous term cannot penalise a document', () => {
    // The textbook formula returns a negative weight once a term is in more than half the corpus,
    // which makes containing the query's own word *lower* the score. On a corpus this small that is
    // not an edge case — it is most common words.
    const index = new Bm25Index([
      { id: '1', text: 'alpha beta' },
      { id: '2', text: 'alpha gamma' },
      { id: '3', text: 'alpha delta' },
    ]);
    expect(index.idf('alpha')).toBeGreaterThanOrEqual(0);
    expect(index.search('alpha').every((h) => h.score >= 0)).toBe(true);
  });

  test('length normalisation stops a long document winning by being long', () => {
    const index = new Bm25Index([
      { id: 'short', text: 'clip path bug' },
      { id: 'long', text: `clip path bug ${'filler word here '.repeat(60)}` },
    ]);
    expect(index.search('clip path bug')[0].id).toBe('short');
  });

  test('digits survive tokenisation', () => {
    // Error codes and version numbers are the most searchable tokens in this corpus. A tokenizer
    // that dropped them would lose exactly what someone types when something has broken.
    expect(tokenize('AXError -25208 in driver 0.12.3')).toEqual(
      expect.arrayContaining(['axerror', '25208', 'driver', '12']),
    );
  });

  test('an empty or stopword-only query returns nothing rather than everything', () => {
    const index = new Bm25Index(corpus);
    expect(index.search('')).toEqual([]);
    expect(index.search('the is a to')).toEqual([]);
  });
});

describe('reciprocal rank fusion', () => {
  test('agreement between two retrievers beats one retriever’s enthusiasm', () => {
    // The property that makes fusion worth doing. `both` is 3rd and 3rd; `one` is 1st and absent.
    const fused = reciprocalRankFusion({
      lexical: { ids: ['one', 'x', 'both'] },
      dense: { ids: ['y', 'z', 'both'] },
    });
    expect(fused[0].id).toBe('both');
  });

  test('a missing list degrades to the other list’s exact order', () => {
    // What makes an offline run safe: with no dense results the output must be the BM25 ranking,
    // in order — not a blend of a real ranking with an absent one.
    const fused = reciprocalRankFusion({
      lexical: { ids: ['a', 'b', 'c'] },
      dense: { ids: [] },
    });
    expect(fused.map((f) => f.id)).toEqual(['a', 'b', 'c']);
  });

  test('scores are rank-derived, so an outlier score cannot rescale the ranking', () => {
    // The reason we fuse ranks and not scores: BM25 is unbounded and corpus-dependent, cosine is
    // bounded. Here the top hit's contribution is fixed by k and its rank alone.
    const fused = reciprocalRankFusion({ lexical: { ids: ['a'] } });
    expect(fused[0].score).toBeCloseTo(1 / (RRF_K + 1), 10);
  });

  test('ties break deterministically', () => {
    const once = reciprocalRankFusion({ l: { ids: ['b', 'a'] }, d: { ids: ['a', 'b'] } });
    const twice = reciprocalRankFusion({ l: { ids: ['b', 'a'] }, d: { ids: ['a', 'b'] } });
    expect(once.map((f) => f.id)).toEqual(twice.map((f) => f.id));
  });

  test('ranks are reported, so a surprising order can be explained', () => {
    const fused = reciprocalRankFusion({ lexical: { ids: ['a'] }, dense: { ids: ['b', 'a'] } });
    expect(fused.find((f) => f.id === 'a')!.ranks).toEqual({ lexical: 1, dense: 2 });
  });
});

describe('embedding backend', () => {
  const credentials = async () => ({ apiKey: 'k', baseURL: 'https://example.invalid/v1' });

  function capturingTransport(vectors: number[][]): { transport: EmbeddingTransport; bodies: any[] } {
    const bodies: any[] = [];
    const transport: EmbeddingTransport = async (_url, init) => {
      bodies.push(JSON.parse(init.body));
      return {
        ok: true,
        status: 200,
        json: async () => ({ data: vectors.map((embedding, index) => ({ embedding, index })) }),
      };
    };
    return { transport, bodies };
  }

  test('a query and a passage are sent with different input_type', async () => {
    // The asymmetric half, and the one that fails silently. These models have separate query and
    // passage encoders; embedding a query as a passage lands it in the wrong region of the space
    // and produces quietly worse recall with no error anywhere.
    const { transport, bodies } = capturingTransport([[1, 0]]);
    const backend = new RemoteEmbeddingBackend({ resolve: credentials, transport });

    await backend.embed(['hello'], 'query');
    await backend.embed(['hello'], 'passage');

    expect(bodies[0].input_type).toBe('query');
    expect(bodies[1].input_type).toBe('passage');
  });

  test('truncate is END, because the provider default NONE is an error', async () => {
    const { transport, bodies } = capturingTransport([[1, 0]]);
    await new RemoteEmbeddingBackend({ resolve: credentials, transport }).embed(['x'], 'passage');
    expect(bodies[0].truncate).toBe('END');
  });

  test('vectors come back unit length, so cosine is a dot product', async () => {
    const { transport } = capturingTransport([[3, 4]]);
    const backend = new RemoteEmbeddingBackend({ resolve: credentials, transport });
    const [vector] = (await backend.embed(['x'], 'passage'))!;
    expect(Math.hypot(...vector)).toBeCloseTo(1, 10);
    expect(dot(vector, vector)).toBeCloseTo(1, 10);
  });

  test('out-of-order responses are re-ordered by index', async () => {
    // The spec permits any order. Trusting arrival order attaches every vector to the wrong
    // document, which produces a store that returns confident, entirely unrelated results.
    const transport: EmbeddingTransport = async () => ({
      ok: true,
      status: 200,
      json: async () => ({ data: [{ embedding: [0, 1], index: 1 }, { embedding: [1, 0], index: 0 }] }),
    });
    const vectors = await new RemoteEmbeddingBackend({ resolve: credentials, transport })
      .embed(['first', 'second'], 'passage');
    expect(vectors![0]).toEqual([1, 0]);
    expect(vectors![1]).toEqual([0, 1]);
  });

  test('oversized inputs are split into batches, not rejected', async () => {
    const { transport, bodies } = capturingTransport([[1, 0], [0, 1]]);
    const backend = new RemoteEmbeddingBackend({ resolve: credentials, transport, batchSize: 2 });
    const out = await backend.embed(['a', 'b', 'c', 'd'], 'passage');
    expect(bodies).toHaveLength(2);
    expect(out).toHaveLength(4);
  });

  test('no key returns null — never a fabricated vector', async () => {
    // The whole point of the module. A hashed stand-in would let the store rank on noise while
    // reporting a semantic score, which is the failure this replaces.
    const backend = new RemoteEmbeddingBackend({ resolve: async () => null });
    expect(await backend.embed(['x'], 'query')).toBeNull();
    expect(backend.unavailableReason()).toMatch(/no API key/i);
  });

  test('a 404 latches off; a 429 does not', async () => {
    // A provider that serves no embeddings will not start to. A rate limit will pass. Latching the
    // second would silently disable semantic search for the rest of the session.
    let status = 404;
    const transport: EmbeddingTransport = async () => ({ ok: false, status, json: async () => ({}) });
    const dead = new RemoteEmbeddingBackend({ resolve: credentials, transport });
    await dead.embed(['x'], 'query');
    expect(dead.unavailableReason()).toContain('404');

    status = 429;
    const throttled = new RemoteEmbeddingBackend({ resolve: credentials, transport });
    await throttled.embed(['x'], 'query');
    expect(throttled.unavailableReason()).toBeNull();
  });

  test('the space id changes with the model or the dimensions', async () => {
    // Vectors are only comparable within one space. If this id failed to move, a model swap would
    // compare two spaces and produce plausible-looking nonsense.
    const a = new RemoteEmbeddingBackend({ resolve: credentials, model: 'm1', dimensions: 768 });
    const b = new RemoteEmbeddingBackend({ resolve: credentials, model: 'm2', dimensions: 768 });
    const c = new RemoteEmbeddingBackend({ resolve: credentials, model: 'm1', dimensions: 384 });
    expect(a.id).not.toBe(b.id);
    expect(a.id).not.toBe(c.id);
  });

  test('normalize leaves a zero vector alone rather than producing NaN', () => {
    expect(normalize([0, 0, 0])).toEqual([0, 0, 0]);
  });
});

import * as fs from 'fs';
import * as os from 'os';
import * as path from 'path';
import { VectorStore } from '../memory/vector.store';
import { RemoteEmbeddingBackend, type EmbeddingTransport } from '../memory/embeddings';
import { resolveMemorySettings, DEFAULT_EMBEDDING_MODEL, DEFAULT_EMBEDDING_DIMENSIONS } from '../memory/settings';
import { DEFAULTS } from '../engine/config';

/**
 * Store-level behaviours added with the second retrieval pass: dedup-before-store, tag scoping
 * applied before depth, recency that survives a restart (coalesced), and a readout for /retrieval.
 * Each test is written against the failure mode the feature exists to prevent.
 */

const credentials = async () => ({ apiKey: 'k', baseURL: 'https://example.invalid/v1' });

/** Keyword-axis space: text about keyboards → [1,0], text about colour → [0,1]. */
const axisTransport: EmbeddingTransport = async (_url, init) => {
  const body = JSON.parse(init.body);
  const vec = (text: string): number[] => {
    const kb = /key|qwerty|keyboard|typing|input|shortcut/i.test(text) ? 1 : 0;
    const colour = /colou?r|palette|hue|tint/i.test(text) ? 1 : 0;
    return kb && !colour ? [1, 0] : colour && !kb ? [0, 1] : [kb, colour];
  };
  return {
    ok: true,
    status: 200,
    json: async () => ({ data: body.input.map((text: string, index: number) => ({ embedding: vec(text), index })) }),
  };
};

const backend = () => new RemoteEmbeddingBackend({ resolve: credentials, transport: axisTransport });

let tmp: string;
let cwd: string;

beforeEach(() => {
  cwd = process.cwd();
  tmp = fs.mkdtempSync(path.join(os.tmpdir(), 'bimax-store-'));
  process.chdir(tmp);
});
afterEach(() => {
  process.chdir(cwd);
  fs.rmSync(tmp, { recursive: true, force: true });
});

describe('near-duplicate merging on write', () => {
  test('a near-verbatim restatement updates the existing memory instead of appending', async () => {
    const store = new VectorStore(null);
    await store.storeDocument('a', 'the permission coach polls once per second on the main thread', []);
    await store.storeDocument('b', 'The permission coach polls once per second on the main thread.', []);
    const hits = await store.semanticSearch('permission coach polling', 5, 0);
    const ids = hits.map((h) => h.id);
    expect(ids).toContain('a');
    expect(ids).not.toContain('b'); // merged into a — one fact, one entry, newest phrasing
  });

  test('a different fact about the same topic is NOT merged', async () => {
    const store = new VectorStore(null);
    await store.storeDocument('a', 'the permission coach polls once per second on the main thread', []);
    await store.storeDocument('b', 'the permission coach dialog is styled by the Trust Center layer', []);
    const hits = await store.semanticSearch('permission', 5, 0);
    expect(hits.map((h) => h.id).sort()).toEqual(['a', 'b']);
  });

  test('embedding agreement alone cannot merge — a coarse space must not delete distinct memories', async () => {
    // The failure this guards against, found on this repo's own eval fixture: two DIFFERENT facts
    // whose centroids collide above the threshold (easy in a low-dimension space) would have their
    // older copy silently deleted by a cosine-only rule. Lexical corroboration is required.
    const store = new VectorStore(backend());
    // Both texts land on the SAME axis → centroid cosine 1.0, but they share almost no words.
    await store.storeDocument('keyboard-nav', 'QWERTY remapping intercepts hardware key events early', []);
    await store.storeDocument('keyboard-crt', 'Shortcut cheat-sheet colours follow the palette tint rules', []);
    const raw = JSON.parse(fs.readFileSync('.breakglass/memory/vectors.json', 'utf8'));
    expect(raw.map((d: any) => d.id).sort()).toEqual(['keyboard-crt', 'keyboard-nav']);
  });

  test('a true paraphrase with embeddings merges', async () => {
    const store = new VectorStore(backend());
    await store.storeDocument('old', 'QWERTY remapping intercepts the hardware key events before the app sees them', []);
    await store.storeDocument('new', 'QWERTY remapping intercepts the hardware key events before the app receives them', []);
    const raw = JSON.parse(fs.readFileSync('.breakglass/memory/vectors.json', 'utf8'));
    expect(raw).toHaveLength(1);
    expect(raw[0].metadata.content).toContain('receives'); // newest phrasing wins
    expect(raw[0].id).toBe('old'); // the id survives so retrieval history does too
  });
});

describe('tag scoping', () => {
  test('tags filter BEFORE depth: the best tagged memory wins even when an untagged one matches harder', async () => {
    const store = new VectorStore(null);
    await store.storeDocument('untagged-exact', 'AXError -25208 on a Notes row', []);
    await store.storeDocument('tagged-loose', 'background press delivery is refused per control', ['project-memory']);

    // The exact-token doc would rank first unscoped; scoped, it is not a candidate at all —
    // not "returned second", absent.
    const scoped = await store.semanticSearch('AXError -25208 background press refusal', 1, 0, { tags: ['project-memory'] });
    expect(scoped.map((h) => h.id)).toEqual(['tagged-loose']);
  });

  test('excludeTags keeps the two injection paths from showing one memory twice', async () => {
    const store = new VectorStore(null);
    await store.storeDocument('convention', 'always run the build after edits in this repo', ['project-memory']);
    await store.storeDocument('episode', 'the build was broken by a stale dist artifact last week', []);

    const both = await store.semanticSearch('the build after edits', 2, 0);
    expect(both.map((h) => h.id).sort()).toEqual(['convention', 'episode']);

    const recallOnly = await store.semanticSearch('the build after edits', 2, 0, { excludeTags: ['project-memory'] });
    expect(recallOnly.map((h) => h.id)).toEqual(['episode']);
  });
});

describe('recency persistence', () => {
  test('a coalesced flush survives retrieval-only sessions, and never blocks the read', async () => {
    // Short real window via the env knob rather than fake timers: the flush rides the store's
    // async mutex, and faking the clock wedges that chain for no insight.
    process.env.BIMAX_RECENCY_FLUSH_MS = '50';
    try {
      const store = new VectorStore(null);
      await store.storeDocument('used', 'AXError -25208 background press refusal', []);
      await store.storeDocument('unused', 'something else entirely about typography', []);
      // Wall-clock granularity: without this the retrieval lands in the same millisecond as the
      // write and the comparison is a coin flip (see the eviction test for the same trap).
      await new Promise((r) => setTimeout(r, 5));

      const results = await store.semanticSearch('AXError -25208', 1, 0);
      expect(results[0]?.id).toBe('used');

      // Before the window closes, the file does not know about the retrieval: the timestamp it
      // holds is the one from the WRITE (storeDocument), not the read.
      const rawBefore = JSON.parse(fs.readFileSync('.breakglass/memory/vectors.json', 'utf8'));
      const usedBefore = rawBefore.find((d: any) => d.id === 'used').lastUsedAt;

      // …after the window it does, without any write having happened.
      await new Promise((r) => setTimeout(r, 250));
      const raw = JSON.parse(fs.readFileSync('.breakglass/memory/vectors.json', 'utf8'));
      expect(raw.find((d: any) => d.id === 'used').lastUsedAt).toBeGreaterThan(usedBefore);
    } finally {
      delete process.env.BIMAX_RECENCY_FLUSH_MS;
    }
  });

  test('multiple searches inside one flush window preserve every recency update', async () => {
    process.env.BIMAX_RECENCY_FLUSH_MS = '50';
    try {
      const store = new VectorStore(null);
      await store.storeDocument('first', 'FIRST_RECENCY_SENTINEL', []);
      await store.storeDocument('second', 'SECOND_RECENCY_SENTINEL', []);
      const before = JSON.parse(fs.readFileSync('.breakglass/memory/vectors.json', 'utf8'));
      const beforeById = new Map<string, number>(before.map((d: any) => [d.id, Number(d.lastUsedAt)]));
      await new Promise((r) => setTimeout(r, 5));

      expect((await store.semanticSearch('FIRST_RECENCY_SENTINEL', 1, 0))[0]?.id).toBe('first');
      await new Promise((r) => setTimeout(r, 5));
      expect((await store.semanticSearch('SECOND_RECENCY_SENTINEL', 1, 0))[0]?.id).toBe('second');
      await new Promise((r) => setTimeout(r, 250));

      const after = JSON.parse(fs.readFileSync('.breakglass/memory/vectors.json', 'utf8'));
      expect(after.find((d: any) => d.id === 'first').lastUsedAt).toBeGreaterThan(beforeById.get('first')!);
      expect(after.find((d: any) => d.id === 'second').lastUsedAt).toBeGreaterThan(beforeById.get('second')!);
    } finally {
      delete process.env.BIMAX_RECENCY_FLUSH_MS;
    }
  });
});

describe('stats', () => {
  test('counts documents, chunks and pending embeddings for the /retrieval readout', async () => {
    const store = new VectorStore(backend());
    await store.storeDocument('embedded', 'QWERTY remapping for key events', []);
    const stats = store.stats();
    expect(stats.documents).toBe(1);
    expect(stats.chunks).toBeGreaterThanOrEqual(1);
    expect(stats.embedded).toBe(stats.chunks);
    expect(stats.pending).toBe(0);
  });

  test('chunks stored without a backend count as pending, not embedded', async () => {
    const store = new VectorStore(null);
    await store.storeDocument('bare', 'a note written while embeddings were off', []);
    const stats = store.stats();
    expect(stats.embedded).toBe(0);
    expect(stats.pending).toBe(stats.chunks);
  });
});

describe('memory model settings', () => {
  test('remote source-code embeddings require explicit consent', () => {
    expect(DEFAULTS.codeIndexEnabled).toBe(true);
    expect(DEFAULTS.codeIndexRemoteEmbeddings).toBe(false);
  });

  test('defaults when nothing is set', () => {
    const s = resolveMemorySettings({}, {});
    expect(s.embeddingModel).toBe(DEFAULT_EMBEDDING_MODEL);
    expect(s.embeddingDimensions).toBe(DEFAULT_EMBEDDING_DIMENSIONS);
  });

  test('config keys beat defaults; env beats config', () => {
    const s = resolveMemorySettings(
      { memoryEmbeddingModel: 'config/model', memoryEmbeddingDimensions: 1024, memoryRerankModel: 'config/rerank' },
      { BIMAX_EMBED_MODEL: 'env/model' },
    );
    expect(s.embeddingModel).toBe('env/model'); // env wins
    expect(s.embeddingDimensions).toBe(1024); // config: env var absent
    expect(s.rerankModel).toBe('config/rerank');
  });

  test('a dimension the model cannot emit resolves to the default rather than disabling embeddings', () => {
    const s = resolveMemorySettings({ memoryEmbeddingDimensions: 777 }, {});
    expect(s.embeddingDimensions).toBe(DEFAULT_EMBEDDING_DIMENSIONS);
  });
});

import * as fs from 'fs';
import * as os from 'os';
import * as path from 'path';
import { VectorStore } from '../memory/vector.store';
import { normalize, type EmbeddingBackend } from '../memory/embeddings';

/**
 * The store, graded on the one claim it makes: that it finds things a keyword search cannot.
 *
 * The store writes under `process.cwd()`, so each test runs in its own temp directory — otherwise
 * these would read and overwrite the developer's real memory file, which is both a wrong test and
 * a destructive one.
 */

let tmp: string;
let cwd: string;

beforeEach(() => {
  cwd = process.cwd();
  tmp = fs.mkdtempSync(path.join(os.tmpdir(), 'bimax-vec-'));
  process.chdir(tmp);
});

afterEach(() => {
  process.chdir(cwd);
  fs.rmSync(tmp, { recursive: true, force: true });
});

/**
 * A backend with a hand-placed geometry, so "semantically close" is a fact of the fixture rather
 * than a hope about a real model. Texts are mapped to points on a circle; paraphrases are placed
 * next to each other and unrelated text on the far side.
 */
function fakeBackend(angles: Record<string, number>, id = 'fake@2'): EmbeddingBackend {
  return {
    id,
    dimensions: 2,
    async embed(texts, _role) {
      return texts.map((t) => {
        const angle = angles[t];
        if (angle === undefined) return normalize([0.01, 0.01]);
        return normalize([Math.cos(angle), Math.sin(angle)]);
      });
    },
  };
}

const CI_RED = 'CI is red on main';
const BUILD_FAILING = 'the build is failing';
const UNRELATED = 'sidebar corner radius interpolation';

const ANGLES = {
  [CI_RED]: 0.05,
  [BUILD_FAILING]: 0.0,     // paraphrase of CI_RED — adjacent
  [UNRELATED]: Math.PI,     // opposite side of the space
};

test('dense bounded selection preserves pre-depth scope, recency ties and foreign-space rejection', async () => {
  const storePath = path.join(tmp, 'selection-fixture.json');
  const docs = Array.from({ length: 220 }, (_, i) => ({
    id: `d-${String(i).padStart(3, '0')}`,
    metadata: { content: `record-${i}`, tags: [i < 100 ? 'foreign' : 'owned', ...(i === 219 ? ['exclude'] : [])] },
    lastUsedAt: i % 5,
    chunks: [{ id: `c-${String(i).padStart(3, '0')}`, text: `record-${i}`, embedding: [1, 0], space: i === 218 ? 'foreign-space' : 'selection@2' }],
  }));
  fs.writeFileSync(storePath, JSON.stringify(docs));
  const backend: EmbeddingBackend = { id: 'selection@2', dimensions: 2, embed: async texts => texts.map(() => [1, 0]) };
  const store = new VectorStore(backend, null, { storePath, maxVectors: 300, dedup: false });
  const expected = docs.filter(doc => doc.metadata.tags.includes('owned') && !doc.metadata.tags.includes('exclude') && doc.chunks[0].space === backend.id)
    .sort((a, b) => b.lastUsedAt - a.lastUsedAt || a.chunks[0].id.localeCompare(b.chunks[0].id)).slice(0, 8).map(doc => doc.id);
  const hits = await store.semanticSearch('query', 8, 0, { mode: 'dense', tags: ['owned'], excludeTags: ['exclude'], where: tags => tags.includes('owned') });
  expect(hits.map(doc => doc.id)).toEqual(expected);
  expect(store.lastSearchMode().dense).toBe(true);
});

describe('hybrid retrieval', () => {
  test('finds a paraphrase that shares no words with the query', async () => {
    // The capability this whole change exists to add, and the one the previous store could not
    // have: "the build is failing" and "CI is red on main" have zero tokens in common.
    const store = new VectorStore(fakeBackend(ANGLES));
    await store.storeDocument('ci', CI_RED, []);
    await store.storeDocument('other', UNRELATED, []);

    const hits = await store.semanticSearch(BUILD_FAILING, 3, 0.25);
    expect(hits.map((h) => h.id)).toContain('ci');
    expect(store.lastSearchMode().dense).toBe(true);
  });

  test('the same query finds nothing under lexical-only retrieval', async () => {
    // The control. Without embeddings this is exactly the old behaviour — which is the point: the
    // test above is measuring the new capability, not a change in the fixture.
    const store = new VectorStore(null);
    await store.storeDocument('ci', CI_RED, []);
    await store.storeDocument('other', UNRELATED, []);

    const hits = await store.semanticSearch(BUILD_FAILING, 3, 0.25);
    expect(hits.map((h) => h.id)).not.toContain('ci');
    expect(store.lastSearchMode().dense).toBe(false);
  });

  test('exact identifiers still win, which is what BM25 is carrying', async () => {
    // Dense retrieval is worst on tokens the model never saw. If adding embeddings had cost us
    // exact-match recall, the hybrid would be a downgrade dressed as an upgrade.
    const store = new VectorStore(fakeBackend({}));
    await store.storeDocument('err', 'AXError -25208 refused the background press', []);
    await store.storeDocument('noise', 'a note about panels and animation', []);

    const hits = await store.semanticSearch('-25208', 3, 0);
    expect(hits[0].id).toBe('err');
  });

  test('an embedding failure degrades to lexical rather than returning nothing', async () => {
    // Offline, no key, provider down. The store must get worse, not break — and must say so.
    const failing: EmbeddingBackend = {
      id: 'x@1',
      dimensions: 1,
      async embed() { return null; },
    };
    const store = new VectorStore(failing);
    await store.storeDocument('a', 'permission coach drag and drop', []);

    const hits = await store.semanticSearch('permission drag', 3, 0);
    expect(hits.map((h) => h.id)).toEqual(['a']);
    expect(store.lastSearchMode().dense).toBe(false);
  });

  test('vectors from another model are discarded, never compared', async () => {
    // Mixing two spaces yields similarity scores that look entirely plausible and mean nothing.
    const first = new VectorStore(fakeBackend(ANGLES, 'model-a@2'));
    await first.storeDocument('ci', CI_RED, []);

    const raw = JSON.parse(fs.readFileSync(path.join(tmp, '.breakglass/memory/vectors.json'), 'utf8'));
    expect(raw[0].chunks[0].space).toBe('model-a@2');

    // Reopen under a different model: the stale vector must not be used.
    const second = new VectorStore(fakeBackend(ANGLES, 'model-b@2'));
    await second.semanticSearch('anything', 3, 0);
    const reread = JSON.parse(fs.readFileSync(path.join(tmp, '.breakglass/memory/vectors.json'), 'utf8'));
    expect(reread[0].chunks[0].space === 'model-a@2' && reread[0].chunks[0].embedding).toBeTruthy();

    // …and a backfill under the new model re-embeds it into the new space.
    const result = await second.backfillEmbeddings();
    expect(result.embedded).toBe(1);
    const after = JSON.parse(fs.readFileSync(path.join(tmp, '.breakglass/memory/vectors.json'), 'utf8'));
    expect(after[0].chunks[0].space).toBe('model-b@2');
  });

  test('a document stored while embeddings are down is still stored, and backfills later', async () => {
    // Refusing the write because the network was down loses the memory entirely, which is far
    // worse than a memory that is briefly lexical-only.
    let online = false;
    const flaky: EmbeddingBackend = {
      id: 'flaky@2',
      dimensions: 2,
      async embed(texts) {
        return online ? texts.map(() => normalize([1, 0])) : null;
      },
    };
    const store = new VectorStore(flaky);
    await store.storeDocument('a', 'something worth remembering', []);

    let raw = JSON.parse(fs.readFileSync(path.join(tmp, '.breakglass/memory/vectors.json'), 'utf8'));
    expect(raw[0].chunks[0].embedding).toBeUndefined();
    expect(raw[0].metadata.content).toBe('something worth remembering');

    online = true;
    expect((await store.backfillEmbeddings()).embedded).toBe(1);
    raw = JSON.parse(fs.readFileSync(path.join(tmp, '.breakglass/memory/vectors.json'), 'utf8'));
    expect(raw[0].chunks[0].space).toBe('flaky@2');
  });

  test('backfill is idempotent', async () => {
    const store = new VectorStore(fakeBackend(ANGLES));
    await store.storeDocument('ci', CI_RED, []);
    expect((await store.backfillEmbeddings()).embedded).toBe(0);
  });

  test('an empty query returns nothing instead of the whole store', async () => {
    const store = new VectorStore(fakeBackend(ANGLES));
    await store.storeDocument('ci', CI_RED, []);
    expect(await store.semanticSearch('   ', 3, 0)).toEqual([]);
  });
});

import * as fs from 'fs';
