let dir: string;
let nbPath: string;
const run = (args: any) => tool.execute(args, { cwd: dir });
const readNb = () => JSON.parse(fs.readFileSync(nbPath, 'utf-8'));

beforeEach(() => {
  dir = fs.mkdtempSync(path.join(os.tmpdir(), 'nb-'));
  nbPath = path.join(dir, 'n.ipynb');
