    );
  });

  it('resolves a nested relative path', () => {
    expect(resolvePath('a/b/c.txt', fakeCwd)).toBe(
      require('path').resolve(fakeCwd, 'a/b/c.txt'),
    );
  });

  it('handles cwd with a trailing slash', () => {
