import * as fs from 'fs';
import * as os from 'os';
import * as path from 'path';
import { startShellTask } from '../core/shell.tasks';
import { __resetTaskRegistryForTests, TaskRegistry } from '../core/task.registry';
import { __resetExecutionLedgerForTests } from '../core/execution.ledger';
import { createTasksTool } from '../tools/implementations/tasks.tool';

const quote = (s: string) => "'" + s.replace(/'/g, "'\\''") + "'";
const delay = (ms: number) => new Promise(resolve => setTimeout(resolve, ms));
async function until(ready: () => boolean, limit = 4000) {
  const deadline = Date.now() + limit;
  while (!ready()) {
    if (Date.now() >= deadline) throw new Error('fixture did not reach its expected state');
    await delay(20);
  }
}

describe('real background shell end states', () => {
  let dir: string, registry: TaskRegistry, pids: number[];
  beforeEach(() => {
    dir = fs.mkdtempSync(path.join(os.tmpdir(), 'bimax-shell-real-'));
    __resetExecutionLedgerForTests(dir); registry = __resetTaskRegistryForTests(); pids = [];
  });
  afterEach(async () => {
    for (const task of registry.live()) registry.cancel(task.id);
    for (const pid of pids) { try { process.kill(-pid, 'SIGKILL'); } catch { /* already dead */ } }
    await until(() => registry.live().length === 0);
    fs.rmSync(dir, { recursive: true, force: true });
  });
  function fixture(body: string) {
    const file = path.join(dir, 'job.cjs');
    fs.writeFileSync(file, body);
    return startShellTask(`exec ${quote(process.execPath)} ${quote(file)}`, { cwd: dir }).task;
  }
  it('cooperative cancellation wakes a genuinely paused job and drains its final output', async () => {
    const task = fixture(`process.on('SIGTERM', () => { console.log('TERM handled'); process.exit(0); });
      console.log('PID=' + process.pid); setInterval(() => {}, 1000);`);
    await until(() => registry.output(task.id).includes('PID='));
    const pid = Number(registry.output(task.id).split('PID=')[1]); pids.push(pid);
    expect(registry.pause(task.id)).toContain('Paused');
    registry.cancel(task.id);
    await until(() => task.state === 'cancelled');
    expect(registry.output(task.id)).toContain('TERM handled');
    expect(() => process.kill(pid, 0)).toThrow();
  });
  it('kills a SIGTERM-resistant job and its inherited process-group descendant', async () => {
    const task = fixture(`const {spawn} = require('child_process');
      const child = spawn(process.execPath, ['-e', "process.on('SIGTERM',()=>{}); console.log('child ready'); setInterval(()=>{},1000)"], {stdio:['ignore','pipe','inherit']});
      process.on('SIGTERM',()=>{});
      child.stdout.once('data', () => console.log('PIDS=' + process.pid + ',' + child.pid));
      setInterval(()=>{},1000);`);
    await until(() => registry.output(task.id).includes('PIDS='));
    const [pid, descendant] = registry.output(task.id).split('PIDS=')[1].split(',').map(Number); pids.push(pid);
    registry.cancel(task.id); await until(() => task.state === 'cancelled');
    expect(task.lastEvent).toContain('SIGKILL');
    expect(() => process.kill(pid, 0)).toThrow();
    await until(() => { try { process.kill(descendant, 0); return false; } catch { return true; } });
  });
  it('a real BashTool background task is inspectable and waitable through TasksTool', async () => {
    const { createBashTool } = await import('../tools/implementations/bash.tool');
    const governor: any = { approveTaskExecution: async () => {} };
    const bash = createBashTool(governor), tasks = createTasksTool(governor);
    const launched = JSON.parse(await bash.execute({ command: "printf 'parser: ready\\n'; exit 3", background: true }, { cwd: dir }));
    const result = await tasks.execute({ action: 'wait', taskId: launched.taskId, timeout_seconds: 2 });
    expect(result).toContain('[failed-resumable]'); expect(result).toContain('exit 3'); expect(result).toContain('parser: ready');
    expect(await tasks.execute({ action: 'get', taskId: launched.taskId })).toContain('parser: ready');
  });
});

import { EventEmitter } from 'events';
import childProcess = require('child_process');
import * as fs from 'fs';
import * as os from 'os';
import * as path from 'path';
import { startShellTask } from '../core/shell.tasks';
import { __resetTaskRegistryForTests, TaskRegistry } from '../core/task.registry';
import { __resetExecutionLedgerForTests, getExecutionLedger } from '../core/execution.ledger';
import { createBashTool } from '../tools/implementations/bash.tool';

describe('background shell lifecycle and stream regression', () => {
  let dir: string, registry: TaskRegistry, child: any;
  beforeEach(() => {
    dir = fs.mkdtempSync(path.join(os.tmpdir(), 'bimax-shell-sprint-'));
    __resetExecutionLedgerForTests(dir);
    registry = __resetTaskRegistryForTests();
    child = Object.assign(new EventEmitter(), {
      pid: 12345678, stdout: new EventEmitter(), stderr: new EventEmitter(), kill: jest.fn(),
    });
    jest.spyOn(childProcess, 'spawn').mockReturnValue(child);
    jest.spyOn(process, 'kill').mockReturnValue(true);
    jest.useFakeTimers();
  });
  afterEach(() => {
    child.emit('close', null, 'SIGKILL');
    jest.useRealTimers(); jest.restoreAllMocks();
    fs.rmSync(dir, { recursive: true, force: true });
  });
  it('cancel wakes a paused process so its termination signal can be handled', () => {
    const { task } = startShellTask('sleep 99', { cwd: dir });
    registry.pause(task.id); registry.cancel(task.id);
    expect(process.kill).toHaveBeenCalledWith(-child.pid, 'SIGTERM');
    expect(process.kill).toHaveBeenCalledWith(-child.pid, 'SIGCONT');
    child.emit('close', null, 'SIGTERM');
    expect(task.state).toBe('cancelled');
    expect(getExecutionLedger().reconstruct().find(t => t.taskId === task.id)?.state).toBe('cancelled');
  });
  it('escalates an ignored termination and clears all timers after pipes close', () => {
    const { task } = startShellTask('sleep 99', { cwd: dir, timeoutMs: 100 });
    jest.advanceTimersByTime(100);
    expect(task.state).toBe('cancelling');
    jest.advanceTimersByTime(5000);
    expect(process.kill).toHaveBeenCalledWith(-child.pid, 'SIGKILL');
    child.emit('close', null, 'SIGKILL');
    expect(task.state).toBe('cancelled'); expect(jest.getTimerCount()).toBe(0);
  });
  it.each([0, 2])('a close racing pause records the real exit %s', code => {
    const { task } = startShellTask('build', { cwd: dir });
    registry.pause(task.id); child.emit('close', code, null);
    expect(task.state).toBe(code === 0 ? 'completed' : 'failed-resumable');
    expect(registry.live()).toHaveLength(0);
  });
  it('preserves UTF-8 characters and logical lines across arbitrary pipe chunks', () => {
    const { task } = startShellTask('build', { cwd: dir });
    const bytes = Buffer.from('src/π.ts: error\nnext line');
    const split = bytes.indexOf(Buffer.from('π')) + 1;
    child.stdout.emit('data', bytes.subarray(0, split));
    child.stdout.emit('data', bytes.subarray(split, bytes.length - 4));
    child.stdout.emit('data', bytes.subarray(bytes.length - 4));
    child.emit('close', 1, null);
    expect(registry.output(task.id)).toBe('src/π.ts: error\nnext line');
  });
  it('keeps streamed no-newline output bounded without manufacturing extra lines', () => {
    const { task } = startShellTask('build', { cwd: dir });
    for (let i = 0; i < 1000; i++) child.stdout.emit('data', Buffer.from('x'.repeat(100)));
    child.emit('close', 0, null);
    expect(registry.output(task.id)).toBe('x'.repeat(500) + '…');
  });
  it('BashTool honors an explicit short background timeout', async () => {
    const tool = createBashTool({ approveTaskExecution: jest.fn().mockResolvedValue(undefined) } as any);
    const result = JSON.parse(await tool.execute({ command: 'sleep 99', background: true, timeout: 100 }, { cwd: dir }));
    jest.advanceTimersByTime(100);
    expect(registry.get(result.taskId)?.state).toBe('cancelling');
    child.emit('close', null, 'SIGTERM');
  });
  it('BashTool refuses to report a synchronously failed spawn as success', async () => {
    jest.spyOn(require('../core/fault.injection'), 'faultPoint').mockImplementation((site: unknown) => {
      if (site === 'shell.spawn') throw new Error('injected spawn failure');
    });
    const tool = createBashTool({ approveTaskExecution: jest.fn().mockResolvedValue(undefined) } as any);
    await expect(tool.execute({ command: 'sleep 99', background: true }, { cwd: dir })).rejects.toThrow('injected spawn failure');
    expect(registry.live()).toHaveLength(0);
  });
  it('keeps a large streamed tail bounded and never joins stdout to stderr fragments', () => {
    const { task } = startShellTask('build', { cwd: dir });
    child.stdout.emit('data', Buffer.from('src/parser'));
    child.stderr.emit('data', Buffer.from('.ts: error\n'));
    expect(registry.output(task.id)).toBe('src/parser\n.ts: error');
    child.stdout.emit('data', Buffer.from(Array.from({ length: 1000 }, (_, i) => `line ${i}\n`).join('')));
    const lines = registry.output(task.id, 1000).split('\n');
    expect(lines).toHaveLength(TaskRegistry.OUTPUT_MAX_LINES);
    expect(lines[0]).toBe('line 600'); expect(lines.at(-1)).toBe('line 999');
    child.emit('close', 0, null);
  });
});

import { validateParam, bindParams, QueryTemplate, ParamSpec, MAX_PARAM_CHARS, MAX_TOTAL_PARAM_CHARS } from '../sockets/contract';
import { assertReadOnly, SocketQueryError } from '../sockets/adapters';

/**
 * The Open Socket's security claims, graded.
 *
 * The requirement was "it can only take information in, never send anything out". A query is
 * necessarily an outbound send, so the claim that has to hold instead is: *the only thing that
 * leaves is a pre-declared statement plus short, shaped parameters.* These tests grade that, and
 * each block ends with the mutation the assertion exists to catch — a test that passes against a
 * neutered implementation is not evidence.
 */

const template = (over: Partial<QueryTemplate> = {}): QueryTemplate => ({
  name: 'equipment_history',
  description: 'Inspection history for one equipment tag',
  connector: 'historian',
  statement: 'SELECT tag, thickness_mm, inspected_on FROM inspections WHERE tag = $1 ORDER BY inspected_on DESC',
  params: [{ name: 'tag', type: 'string', pattern: '[A-Z]-\\d{3}', maxLength: 16 }],
  ...over,
});

describe('the outbound channel is bounded, not merely read-only', () => {
  it('refuses a parameter long enough to carry a document', () => {
    const spec: ParamSpec = { name: 'tag', type: 'string' };
    // A confidential paragraph is exactly what exfiltration through a WHERE clause looks like.
    const leak = 'Board strategy: divest the Mangaluru aromatics complex in Q3. '.repeat(20);
    expect(() => validateParam(spec, leak)).toThrow(/limit is/);
  });

  it('caps a string parameter even when the template author declared a larger limit', () => {
    // A template author who writes maxLength 100000 must not be able to widen the channel.
    const spec: ParamSpec = { name: 'note', type: 'string', maxLength: 100_000 };
    expect(() => validateParam(spec, 'x'.repeat(MAX_PARAM_CHARS + 1))).toThrow(/limit is 128/);
    expect(validateParam(spec, 'x'.repeat(MAX_PARAM_CHARS))).toHaveLength(MAX_PARAM_CHARS);
  });

  it('caps the SUM of parameters, so many short fields cannot be assembled into a long one', () => {
    const many: ParamSpec[] = Array.from({ length: 8 }, (_, i) => ({ name: `p${i}`, type: 'string' as const }));
    const args = Object.fromEntries(many.map((spec) => [spec.name, 'y'.repeat(MAX_PARAM_CHARS)]));
    expect(() => bindParams(template({ params: many }), args)).toThrow(/per-call limit/);
  });

  it('a pattern constrains a parameter to an identifier, so it cannot carry prose at all', () => {
    const spec: ParamSpec = { name: 'tag', type: 'string', pattern: '[A-Z]-\\d{3}' };
    expect(validateParam(spec, 'E-204')).toBe('E-204');
    expect(() => validateParam(spec, 'E-204 and also the merger terms')).toThrow(/permitted form/);
  });

  it('anchors a pattern the author left unanchored', () => {
    // Without anchoring, "E-204<payload>" matches an unanchored /[A-Z]-\d{3}/ and the payload rides along.
    const spec: ParamSpec = { name: 'tag', type: 'string', pattern: '[A-Z]-\\d{3}' };
    expect(() => validateParam(spec, 'E-204' + 'PAYLOAD')).toThrow(/permitted form/);
  });

  it('MUTANT — dropping the length cap would let a whole memo leave in one parameter', () => {
    const unbounded = (value: string): string => value; // the neutered implementation
    const memo = 'z'.repeat(5_000);
    expect(unbounded(memo)).toHaveLength(5_000);
    expect(() => validateParam({ name: 'tag', type: 'string' }, memo)).toThrow();
  });
});

describe('the model cannot widen its own interface', () => {
  it('refuses an undeclared parameter rather than ignoring it', () => {
    // Ignoring it silently would let a caller believe a filter applied that never did.
    expect(() => bindParams(template(), { tag: 'E-204', extra: 'anything' })).toThrow(/unknown parameter/);
  });

  it('requires a declared parameter to be supplied', () => {
    expect(() => bindParams(template(), {})).toThrow(/required/);
  });

  it('binds parameters positionally in the template’s declared order', () => {
    const two = template({
      statement: 'SELECT * FROM r WHERE unit = $1 AND year = $2',
      params: [
        { name: 'unit', type: 'string', pattern: '[A-Z]{3}' },
        { name: 'year', type: 'integer', min: 1990, max: 2100 },
      ],
    });
    expect(bindParams(two, { year: '2026', unit: 'CDU' })).toEqual(['CDU', 2026]);
  });

  it('coerces a numeric string but refuses text where a number is declared', () => {
    const spec: ParamSpec = { name: 'year', type: 'integer', min: 1990, max: 2100 };
    expect(validateParam(spec, '2026')).toBe(2026);
    expect(() => validateParam(spec, 'last year')).toThrow(/must be a number/);
    expect(() => validateParam(spec, 2500)).toThrow(/<= 2100/);
    expect(() => validateParam(spec, 2026.5)).toThrow(/integer/);
  });

  it('enum parameters admit only declared values', () => {
    const spec: ParamSpec = { name: 'status', type: 'enum', values: ['open', 'closed'] };
    expect(validateParam(spec, 'open')).toBe('open');
    expect(() => validateParam(spec, 'open OR 1=1')).toThrow(/must be one of/);
  });
});

describe('read-only is enforced at config load, before anything reaches a server', () => {
  it('accepts the read forms', () => {
    for (const statement of [
      'SELECT 1',
      'WITH recent AS (SELECT * FROM t) SELECT * FROM recent',
      '  -- a leading comment\n SELECT tag FROM inspections',
      'EXPLAIN SELECT 1',
    ]) {
      expect(() => assertReadOnly(template({ statement }), 'postgres')).not.toThrow();
    }
  });

  it('refuses a write however it is dressed up', () => {
    for (const statement of [
      'UPDATE inspections SET thickness_mm = 9 WHERE tag = $1',
      'DELETE FROM inspections',
      'INSERT INTO inspections VALUES (1)',
      'DROP TABLE inspections',
      'TRUNCATE inspections',
    ]) {
      expect(() => assertReadOnly(template({ statement }), 'postgres')).toThrow(SocketQueryError);
    }
  });

  it('refuses a write hidden inside a CTE behind a SELECT head', () => {
    // This is the case a naive "starts with SELECT" check waves through.
    const sneaky = 'WITH gone AS (DELETE FROM inspections RETURNING *) SELECT * FROM gone';
    expect(() => assertReadOnly(template({ statement: sneaky }), 'postgres')).toThrow(/write keyword/);
  });

  it('refuses stacked statements', () => {
    const stacked = 'SELECT 1; DROP TABLE inspections';
    expect(() => assertReadOnly(template({ statement: stacked }), 'postgres')).toThrow(/more than one statement/);
  });

  it('permits a single trailing semicolon', () => {
    expect(() => assertReadOnly(template({ statement: 'SELECT 1;' }), 'postgres')).not.toThrow();
  });

  it('allows Redis reads and refuses Redis writes', () => {
    for (const statement of ['GET insp:$1', 'HGETALL equipment:$1', 'ZRANGE hist:$1 0 -1', 'FT.SEARCH idx $1']) {
      expect(() => assertReadOnly(template({ statement }), 'redis')).not.toThrow();
    }
    for (const statement of ['SET insp:$1 1', 'DEL insp:$1', 'FLUSHALL', 'PUBLISH ch $1', 'EVAL "..." 0']) {
      expect(() => assertReadOnly(template({ statement }), 'redis')).toThrow(SocketQueryError);
    }
  });

  it('MUTANT — a head-only check would admit the CTE delete', () => {
    const sneaky = 'WITH gone AS (DELETE FROM inspections RETURNING *) SELECT * FROM gone';
    const headOnly = (s: string): boolean => /^(SELECT|WITH)\b/i.test(s.trim());
    expect(headOnly(sneaky)).toBe(true);                 // the neutered check passes it
    expect(() => assertReadOnly(template({ statement: sneaky }), 'postgres')).toThrow(); // ours does not
  });
});

import * as fs from 'fs';
import * as path from 'path';
import { requireNetworkConsent, resetNetworkConsent } from '../security/network.consent';
import { resetSovereignMode, setSovereignAllowlist, setSovereignMode } from '../security/sovereign';
import { resetSessionEgress, summarize } from '../security/egress.ledger';

/**
 * A guard nothing calls proves nothing.
 *
 * The classifier is unit-tested next door; what this file protects is the property that every seam
 * capable of reaching the network actually routes through it. That property is not visible from
 * any single unit test — it is a statement about the whole codebase — so the enumeration is
 * asserted directly against the source. A new egress surface added without a guard fails here,
 * which is the only moment anyone would notice before an audit does.
 */
const ROOT = path.resolve(__dirname, '..');

/** Every file that can originate an outbound request, and what it must route through. */
const EGRESS_SURFACES = [
  'core/llm.adapter.ts',                    // every model request
  'security/network.consent.ts',            // WebFetchTool + WebSearchTool, via consent
];

describe('egress surfaces are guarded', () => {
  for (const rel of EGRESS_SURFACES) {
    test(`${rel} routes through the egress guard`, () => {
      const source = fs.readFileSync(path.join(ROOT, rel), 'utf8');
      // Accepts both spellings of the import: `./egress.guard` from inside security/, and
      // `../security/egress.guard` from anywhere else.
      expect(source).toMatch(/from '(\.\.?\/)+(security\/)?egress\.guard'/);
      expect(source).toMatch(/assertEgressAllowed|checkEgress/);
    });
  }

  test('the web tools still reach the network only through consent', () => {
    // Guarding `network.consent.ts` only covers the web tools while they keep calling it. If a tool
    // ever fetches directly, its guard disappears silently — so the call site is pinned too.
    for (const tool of ['tools/implementations/webfetch.tool.ts', 'tools/implementations/websearch.tool.ts']) {
      const source = fs.readFileSync(path.join(ROOT, tool), 'utf8');
      expect([tool, /requireNetworkConsent\(/.test(source)]).toEqual([tool, true]);
    }
  });
});

describe('sovereign mode reaches the consent path', () => {
  beforeEach(() => {
    resetNetworkConsent();
    resetSessionEgress();
    resetSovereignMode();
    setSovereignAllowlist([]);
    process.env.BIMAX_EGRESS_LEDGER = path.join(
      fs.mkdtempSync(path.join(require('os').tmpdir(), 'egress-boundary-')), 'egress.ledger',
    );
  });

  afterEach(() => {
    delete process.env.BIMAX_EGRESS_LEDGER;
    resetSovereignMode();
  });

  const governor = (): any => ({ approveTaskExecution: jest.fn().mockResolvedValue(undefined) });

  test('an external fetch is refused WITHOUT asking the user', async () => {
    setSovereignMode(true);
    const g = governor();
    const refusal = await requireNetworkConsent(g, {
      target: 'https://docs.python.org/3/',
      tool: 'WebFetchTool',
      purpose: 'read docs',
    });

    expect(refusal).toMatch(/sovereign/i);
    // Asking would be worse than not asking: the deployment cannot honour an "allow" answer, and a
    // prompt the user can't meaningfully act on teaches them to click through prompts.
    expect(g.approveTaskExecution).not.toHaveBeenCalled();
    expect(summarize()).toMatchObject({ external: 1, refused: 1 });
  });

  test('with the mode off the user is still asked, and the attempt is still recorded', async () => {
    setSovereignMode(false);
    const g = governor();
    const refusal = await requireNetworkConsent(g, {
      target: 'https://docs.python.org/3/',
      tool: 'WebFetchTool',
      purpose: 'read docs',
    });

    expect(refusal).toBeNull();
    expect(g.approveTaskExecution).toHaveBeenCalledTimes(1);
    expect(summarize()).toMatchObject({ attempts: 1, external: 1, refused: 0 });
  });

  test('a local endpoint is not refused by the mode', async () => {
    setSovereignMode(true);
    const g = governor();
