    expect(numberSetting('7.5', true)).toBe(7.5);
    set({ spendTaskShareUsd: null });
    expect(configuredSpend('spendTaskShareUsd')).toBeUndefined();
    spy.mockRestore();
    set({ spendTaskShareUsd: 0 });
    expect(configuredSpend('spendTaskShareUsd')).toBe(0);
  });
});

import * as fs from 'fs';
import * as os from 'os';
import * as path from 'path';
import { openSqlite, sqliteFlavor } from '../core/sqlite';
import { createGraphStore } from '../graph/sqlite.graph.store';
import { GraphNode, GraphData } from '../graph/models';
import { EventLedger } from '../mind/event.ledger';

// P0.3 — the packaged desktop engine (bun --compile) lacked node:sqlite, so the graph + ledger
// never persisted. openSqlite() adds a bun:sqlite fallback. These tests prove (on the Node backend
// jest runs under) that persistence round-trips a "restart": write, drop the handle, reopen.

describe('openSqlite adapter', () => {
  it('resolves a real SQLite backend in this (Node) runtime', () => {
    expect(sqliteFlavor()).toBe('node'); // jest runs on Node ≥22 → node:sqlite
  });

  it('exec/prepare/get/all/run/iterate round-trip and survive reopen', () => {
    const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'bgw-sqlite-'));
    const dbPath = path.join(dir, 'x.db');
    try {
      const db = openSqlite(dbPath)!;
      expect(db).toBeTruthy();
      db.exec('CREATE TABLE kv (k TEXT PRIMARY KEY, v TEXT)');
      db.prepare('INSERT INTO kv (k, v) VALUES (?, ?)').run('a', '1');
      db.prepare('INSERT INTO kv (k, v) VALUES (?, ?)').run('b', '2');
      expect(db.prepare('SELECT v FROM kv WHERE k = ?').get('a').v).toBe('1');
      expect(db.prepare('SELECT COUNT(*) AS n FROM kv').get().n).toBe(2);
      expect([...db.prepare('SELECT k FROM kv ORDER BY k').iterate()].map((r) => r.k)).toEqual(['a', 'b']);
      db.close();

      // "Restart": a brand-new handle on the same file must see the committed rows.
      const db2 = openSqlite(dbPath)!;
      expect(db2.prepare('SELECT v FROM kv WHERE k = ?').get('b').v).toBe('2');
      expect(db2.prepare('SELECT COUNT(*) AS n FROM kv').get().n).toBe(2);
      db2.close();
    } finally {
      fs.rmSync(dir, { recursive: true, force: true });
    }
  });
});

describe('graph store persistence across restart', () => {
  it('saveToDisk → new store → loadFromDisk recovers nodes and edges', async () => {
    const root = fs.mkdtempSync(path.join(os.tmpdir(), 'bgw-graphstore-'));
    try {
      const nodes = new Map<string, GraphNode>([
        ['a.ts#Foo', { id: 'a.ts#Foo', name: 'Foo', type: 'CLASS', filePath: 'a.ts' }],
        ['a.ts#bar', { id: 'a.ts#bar', name: 'bar', type: 'FUNCTION', filePath: 'a.ts' }],
      ]);
      const store = createGraphStore(root);
      store.setGraph({ nodes, edges: [{ sourceId: 'a.ts#Foo', targetId: 'a.ts#bar', type: 'CONTAINS' }] } as GraphData);
      await store.saveToDisk();
      (store as any).close?.();

      // Fresh store on the same project root — simulates an app restart.
      const reopened = createGraphStore(root);
      await reopened.loadFromDisk();
      const g = reopened.getGraph();
      expect(g.nodes.size).toBe(2);
      expect(g.nodes.get('a.ts#Foo')?.name).toBe('Foo');
      expect(g.edges.length).toBe(1);
      expect(g.edges[0].type).toBe('CONTAINS');
      (reopened as any).close?.();
    } finally {
      fs.rmSync(root, { recursive: true, force: true });
    }
  });
});

describe('event ledger persistence across restart', () => {
  it('reopens the hash chain with all events intact', () => {
    const root = fs.mkdtempSync(path.join(os.tmpdir(), 'bgw-ledger-'));
    try {
      const ledger = new EventLedger(root);
      expect(ledger.isAvailable()).toBe(true);
      ledger.append('tool.outcome', { tool: 'Edit', ok: true });
      ledger.append('verification', { suite: 'desktop', passed: 17 });
      expect(ledger.count()).toBe(2);
      expect(ledger.verifyChain()).toEqual({ ok: true, events: 2, brokenAt: null });
      ledger.close();

      const reopened = new EventLedger(root);
      expect(reopened.count()).toBe(2);
      expect(reopened.byType('verification')[0]?.payload).toEqual({ suite: 'desktop', passed: 17 });
      expect(reopened.verifyChain()).toEqual({ ok: true, events: 2, brokenAt: null });
      reopened.close();
    } finally {
      fs.rmSync(root, { recursive: true, force: true });
    }
  });
});

import { AgentLoop } from '../core/agent.loop';
import { ToolRegistry } from '../tools/tool.registry';
import type { ChatEvent, LLMProvider } from '../core/llm.provider';
import { engineEvents } from '../engine/events';
import { HeadlessSession } from '../protocol/headless.session';
import { clearSteer, drainSteer, hasSteer, pushSteer, steerMessage } from '../core/steering';

/**
 * Backlog F7: words the user sends while a task works reach the running turn at its next step, instead of waiting in
 * the queue until the turn ends.
 */

afterEach(() => clearSteer());

function recording(rounds: Array<{ tool: string; args: object } | string>, during?: (round: number) => void) {
  let round = 0;
  const seen: any[][] = [];
  const llm = {
    userModel: 'test-model',
    async *chat(messages: any[]): AsyncGenerator<ChatEvent> {
      seen.push(messages.map((m) => ({ role: m.role, content: m.content })));
      const step = rounds[round++] ?? 'Done.';
      during?.(round);
      if (typeof step === 'string') yield { type: 'token', text: step } as any;
      else yield { type: 'tool_call', id: `c${round}`, name: step.tool, args: JSON.stringify(step.args) } as any;
      yield { type: 'done' } as any;
    },
  } as unknown as LLMProvider;
  return { llm, seen };
}

function tools(onRun?: () => void) {
  const registry = new ToolRegistry();
  registry.register({
    name: 'ReadFileTool', description: 'read a file', isDestructive: false, isConcurrencySafe: true,
    schema: { type: 'object', properties: { path: { type: 'string' } } },
    execute: async () => { onRun?.(); return 'file contents'; },
  } as any);
  return registry;
}

async function drain(loop: AgentLoop): Promise<string> {
  let out = '';
  for await (const chunk of loop.execute([{ role: 'user', content: 'Refactor the parser.' }] as any, 'system', {})) out += chunk;
  return out;
}

test('words sent during a step reach the next model call, as the user’s own words, and are reported taken', async () => {
  const { llm, seen } = recording([{ tool: 'ReadFileTool', args: { path: 'parser.ts' } }, 'Refactored, and kept the old name exported.']);
  const steered = jest.fn();
  engineEvents.on('steered', steered);
  try { await drain(new AgentLoop(llm, tools(() => pushSteer('Keep the old function name exported too.')))); }
  finally { engineEvents.off('steered', steered); }
  const second = seen[1];
  expect(second[second.length - 1]).toEqual({ role: 'user', content: steerMessage('Keep the old function name exported too.') });
  // Not an engine tag: the continuation state keeps it as something the user said.
  expect(steerMessage('x')).not.toMatch(/^\[/);
  expect(steered).toHaveBeenCalledWith({ text: 'Keep the old function name exported too.' });
  expect(hasSteer()).toBe(false);
});

test('words that arrive while the model writes its final answer keep the turn going until they are read', async () => {
  const { llm, seen } = recording(['Done — the parser is refactored.', 'Also added the README note.'], (round) => {
    if (round === 1) pushSteer('Add a note to the README as well.');
  });
  const out = await drain(new AgentLoop(llm, tools()));
  expect(seen).toHaveLength(2);
  expect(seen[1][seen[1].length - 1].content).toBe(steerMessage('Add a note to the README as well.'));
  expect(out).toContain('Also added the README note.');
});

describe('the engine session', () => {
  function session(execute: (prompt: string, onToken: (t: string) => void) => Promise<string>) {
    const persona = { messages: [], execute: jest.fn(execute) } as any;
    const llmAdapter = { userModel: 'same-model', liteModel: 'same-model' } as any;
    return {
      persona,
      session: new HeadlessSession({ personas: { bimax: persona }, options: { llmAdapter, maxToolIterations: 5, governor: { mode: 'default' } }, graphStore: {} as any }),
    };
  }

  test('while a turn runs, steering is held for it; what it never took goes back before the turn ends', async () => {
    let release!: () => void;
    const { session: s } = session(() => new Promise((resolve) => { release = () => resolve(''); }));
    const events: Array<[string, unknown]> = [];
    const on = (name: string) => (value: unknown) => events.push([name, value]);
    const handlers = ['steer_queued', 'steer_unused', 'spinner_state'].map((name) => [name, on(name)] as const);
    handlers.forEach(([name, fn]) => engineEvents.on(name, fn));
    try {
      const turn = s.dispatchAutonomous('Refactor the parser.');
      await new Promise((resolve) => setImmediate(resolve));
      s.steer('Keep the old name exported.');
      expect(events).toContainEqual(['steer_queued', { text: 'Keep the old name exported.' }]);
      expect(hasSteer()).toBe(true);
      release();
      await turn;
    } finally {
      handlers.forEach(([name, fn]) => engineEvents.off(name, fn));
    }
    // The fake persona never ran the loop, so the words were never taken: handed back, and before idle.
    const unused = events.findIndex(([name]) => name === 'steer_unused');
    const idle = events.findIndex(([name, value]) => name === 'spinner_state' && value === 'idle');
    expect(events[unused]).toEqual(['steer_unused', { texts: ['Keep the old name exported.'] }]);
    expect(unused).toBeLessThan(idle);
    expect(hasSteer()).toBe(false);
  });

  test('Stop drops steering, as it drops queued messages', async () => {
    let release!: () => void;
    const { session: s } = session(() => new Promise((resolve) => { release = () => resolve(''); }));
    const turn = s.dispatchAutonomous('Refactor the parser.');
    await new Promise((resolve) => setImmediate(resolve));
    s.steer('Also rename the module.');
    s.interrupt();
    expect(drainSteer()).toEqual([]);
    release();
    await turn;
  });
});

import { SubAgentManager } from '../core/subagent.manager';
import { globalSubAgentBlackboard } from '../core/subagent.blackboard';
import { engineEvents, ToolCallEntry } from '../engine/events';
import { createWorktree } from '../core/worktree.manager';
import { execFileSync } from 'child_process';
import * as fs from 'fs';
import * as os from 'os';
import * as path from 'path';

describe('SubAgentManager — worker watchdog timeout', () => {
  let dir: string;
  let hangScript: string;
  let quickScript: string;

  beforeAll(() => {
    dir = fs.mkdtempSync(path.join(os.tmpdir(), 'bgw-worker-'));
    // A worker that never posts a message and never exits.
    hangScript = path.join(dir, 'hang.js');
    fs.writeFileSync(hangScript, 'setInterval(() => {}, 1000);\n');
    // A worker that immediately reports success.
    quickScript = path.join(dir, 'quick.js');
    fs.writeFileSync(quickScript, "const { parentPort } = require('worker_threads'); parentPort.postMessage({ type: 'success', result: 'ok' });\n");
  });

  afterAll(() => {
    try { fs.rmSync(dir, { recursive: true, force: true }); } catch { /* ignore */ }
  });

  const cfg = { agentType: 'test', prompt: 'x', cwd: os.tmpdir(), parentMode: 'safe' };

  // Regression: sub-agents crashed at module load ("Cannot find package 'minimatch'") because the
  // worker ran the TypeScript source with a tsx loader that doesn't propagate into worker threads.
  // The default entry must resolve to a COMPILED .js worker with no TS-loader execArgv.
  it('defaults to a compiled .js worker entry with no tsx loader', () => {
    const mgr = new SubAgentManager() as any;
    expect(mgr.workerScriptPath.endsWith('.js')).toBe(true);
    expect(mgr.workerExecArgv).toEqual([]);
  });

  it('terminates and rejects a worker that exceeds the timeout', async () => {
    const mgr = new SubAgentManager({ workerScriptPath: hangScript, timeoutMs: 300 });
    const start = Date.now();
    await expect(mgr.spawnWorker('t-hang', cfg)).rejects.toThrow(/timed out/i);
    // Rejected promptly (not left hanging) and the worker was cleaned up.
    expect(Date.now() - start).toBeLessThan(3000);
    expect(mgr.activeCount()).toBe(0);
  });

  it('resolves a healthy worker and clears the watchdog (no late rejection)', async () => {
    const mgr = new SubAgentManager({ workerScriptPath: quickScript, timeoutMs: 5000 });
    await expect(mgr.spawnWorker('t-ok', cfg)).resolves.toMatchObject({
      version: 1, taskId: 't-ok', report: 'ok', observedChangedFiles: [],
    });
    expect(mgr.activeCount()).toBe(0);
    // Give any (incorrectly uncleared) timer a chance to fire — it must not.
    await new Promise(r => setTimeout(r, 50));
  });

  // Regression: after a timeout, terminate() fires an 'exit' event. The exit handler used to run
  // its side-effects unconditionally, overwriting the board's "timed out after Nms" reason with
  // "worker exited with code N". The settled-guard must keep the real (timeout) reason.
  it('keeps the timeout reason on the board after the terminate-driven exit fires', async () => {
    const mgr = new SubAgentManager({ workerScriptPath: hangScript, timeoutMs: 200 });
    await expect(mgr.spawnWorker('t-clobber', cfg)).rejects.toThrow(/timed out/i);
    // Let the exit event (from terminate) land — the guard must suppress its board write.
    await new Promise(r => setTimeout(r, 150));
    const claim = globalSubAgentBlackboard.all().find(c => c.taskId === 't-clobber');
    expect(claim?.status).toBe('failed');
    expect(claim?.error).toMatch(/timed out/i);
    expect(claim?.error).not.toMatch(/exited with code/i);
  });
});

describe('SubAgentManager — T3 sub-agent tool-event relay', () => {
  let dir: string;
  let toolScript: string;

  beforeAll(() => {
    dir = fs.mkdtempSync(path.join(os.tmpdir(), 'bgw-relay-'));
    toolScript = path.join(dir, 'tool.js');
    // A worker that forwards one tool_call event, then reports success.
    fs.writeFileSync(toolScript,
      "const { parentPort } = require('worker_threads');\n" +
      "parentPort.postMessage({ type: 'tool_event', subtype: 'tool_call', call: { id: 'c1', toolName: 'BashTool', input: 'ls', output: '', status: 'running', startTime: new Date() } });\n" +
      "parentPort.postMessage({ type: 'tool_event', subtype: 'tool_call_result', call: { id: 'c1', toolName: 'BashTool', input: 'ls', output: 'done', status: 'success', startTime: new Date(), endTime: new Date() } });\n" +
      "parentPort.postMessage({ type: 'success', result: 'ok' });\n");
  });

  afterAll(() => {
    try { fs.rmSync(dir, { recursive: true, force: true }); } catch { /* ignore */ }
  });

  it('re-emits forwarded tool events on the main bus, tagged with parentId + agentLabel', async () => {
    const calls: ToolCallEntry[] = [];
    const results: ToolCallEntry[] = [];
    const onCall = (c: ToolCallEntry) => calls.push(c);
    const onResult = (c: ToolCallEntry) => results.push(c);
    engineEvents.on('tool_call', onCall);
    engineEvents.on('tool_call_result', onResult);
    try {
      const mgr = new SubAgentManager({ workerScriptPath: toolScript, timeoutMs: 5000 });
      await mgr.spawnWorker('t-relay', { agentType: 'Hermes', prompt: 'x', cwd: os.tmpdir(), parentMode: 'safe' });
    } finally {
      engineEvents.off('tool_call', onCall);
