import { loadConfig } from '../engine/config';
import { createContainer } from '../core/container';

/**
 * Every registered tool, checked as the MODEL sees it.
 *
 * 51 tools ship and nothing iterated them: per-tool tests covered a dozen, and the schema each tool
 * hands the model — the only thing a weak model has to go on — was checked nowhere. This repo has
 * already shipped a schema/runtime mismatch (the MCP surface advertised `seconds` while the runtime
 * read `ms`), and weak models are the deliberate strategy here, so a malformed schema is a product
 * defect, not a lint.
 *
 * The structural rules below are ENFORCED. Parameter descriptions are not yet universal, so the
 * count of missing ones is pinned instead: it may shrink, never grow.
 */
jest.setTimeout(120_000);

// The registry is the subject; the optional subsystems are not. Without these the container spawns
// the codebase-memory MCP SERVER — a real child process asking for a 4 GB budget on an 8 GB box —
// which then outlives the suite and makes jest force-kill the worker. These are the same four flags
// a ⌘2 task runs with, so nothing about the tool set changes.
process.env.BIMAX_DISABLE_CODEMEM = '1';
process.env.BIMAX_DISABLE_CODEBASE_MEMORY = '1';
process.env.BIMAX_AUTO_INDEX = '0';
process.env.BIMAX_DRIVES_BOOT = '0';

interface Finding { tool: string; detail: string }

let tools: Array<{ name: string; schema: any; description?: string }> = [];

beforeAll(async () => {
  // Stale launch flags must not register the retired capability in either product surface.
  process.env.BIMAX_COMPUTER_LOOK = '1';
  process.env.BIMAX_COMPUTER_USE = '1';
  process.env.BIMAX_COMPUTER_PRESS = '1';
  const { toolRegistry } = await createContainer(await loadConfig());
  const registry = toolRegistry as any;
  tools = (registry.getToolNames() as string[])
    .map((name) => registry.getTool(name))
    .filter(Boolean)
    .map((t: any) => ({ name: t.name ?? t.definition?.name, schema: t.schema ?? t.definition?.schema ?? t.parameters, description: t.description ?? t.definition?.description }));
});

test('the real model registry has coding tools and no Computer Use, even with old flags enabled', () => {
  const names = tools.map(t => t.name);
  expect(names).toContain('BashTool');
  for (const name of ['LookAtAppTool', 'PressInAppTool', 'TypeInAppTool', 'ScrollInAppTool']) {
    expect(names).not.toContain(name);
  }
});

test('the registry is not empty — a container that registers nothing would pass every check below', () => {
  expect(tools.length).toBeGreaterThan(40);
});

test('every tool has a usable name and description', () => {
  const bad: Finding[] = [];
  for (const t of tools) {
    if (!t.name || !/^[A-Za-z0-9_-]{1,64}$/.test(t.name)) bad.push({ tool: String(t.name), detail: 'name is not a plain identifier' });
    if (!t.description || t.description.trim().length < 10) bad.push({ tool: t.name, detail: 'description missing or too short' });
  }
  expect(bad).toEqual([]);
});

test('every schema is an object schema whose required fields actually exist', () => {
  // A `required` entry with no matching property is a phantom parameter: the model is told to send
  // something the tool never defined, and the failure surfaces as an unexplained refusal.
  const bad: Finding[] = [];
  for (const t of tools) {
    if (!t.schema || typeof t.schema !== 'object') { bad.push({ tool: t.name, detail: 'no schema' }); continue; }
    if (t.schema.type !== 'object') bad.push({ tool: t.name, detail: `schema.type is ${JSON.stringify(t.schema.type)}` });
    const props = t.schema.properties ?? {};
    for (const req of t.schema.required ?? []) {
      if (!(req in props)) bad.push({ tool: t.name, detail: `required "${req}" is not a property` });
    }
    for (const [key, spec] of Object.entries<any>(props)) {
      if (!spec || typeof spec !== 'object') { bad.push({ tool: t.name, detail: `${key}: not an object` }); continue; }
      if (!spec.type && !spec.enum && !spec.oneOf && !spec.anyOf) bad.push({ tool: t.name, detail: `${key}: no type or enum` });
    }
  }
  expect(bad).toEqual([]);
});

test('a multi-action tool always enumerates its actions', () => {
  // An `action` discriminator without an enum leaves the model guessing the verb set, which is the
  // single most expensive thing to get wrong: every call fails and nothing says why.
  const bad: Finding[] = [];
  for (const t of tools) {
    const action = t.schema?.properties?.action;
    if (action && !action.enum) bad.push({ tool: t.name, detail: 'action has no enum' });
  }
  expect(bad).toEqual([]);
});

test('undescribed parameters may shrink, never grow', () => {
  const missing = tools.flatMap((t) =>
    Object.entries<any>(t.schema?.properties ?? {})
      .filter(([, spec]) => spec && typeof spec === 'object' && !spec.description)
      .map(([key]) => `${t.name}.${key}`));
  // Measured 2026-09-19: 30, of which 21 are OutcomeTool's. Lower this number when you describe
  // some; if it rises, a new tool shipped parameters the model has to guess at.
  expect(missing.length).toBeLessThanOrEqual(30);
});

import { ToolRegistry } from '../tools/tool.registry';
import { BuiltTool } from '../tools/tool.factory';
import { createToolSearchTool } from '../tools/implementations/toolsearch.tool';
import { IGovernor } from '../core/interfaces';

const governor = { approveTaskExecution: jest.fn().mockResolvedValue(undefined) } as unknown as IGovernor;

// Minimal fake tool — enough for the registry to slot it in and emit a schema.
function fakeTool(name: string, description = `${name} does a thing`): BuiltTool {
  return { name, description, schema: { type: 'object', properties: {} }, isDestructive: false, isConcurrencySafe: true, execute: async () => 'ok' };
}

function names(schemas: any[]): string[] {
  return schemas.map(s => s.name).sort();
}

describe('ToolRegistry — smart vs full context modes', () => {
  let reg: ToolRegistry;

  beforeEach(() => {
    reg = new ToolRegistry();
    // A couple of core tools, a deferred native tool, a deferred MCP tool.
    reg.register(fakeTool('ReadFileTool'));
    reg.register(fakeTool('BashTool'));
    reg.register(fakeTool('ScoutTool'));      // not in CORE → deferred
    reg.register(fakeTool('mcp__github__create')); // mcp__ → always deferred
    reg.register(createToolSearchTool(governor, reg));
  });

  it('full mode sends every tool except ToolSearchTool', () => {
    expect(names(reg.getSchemas({ mode: 'full' }))).toEqual(
      ['BashTool', 'ReadFileTool', 'ScoutTool', 'mcp__github__create'].sort(),
    );
  });

  it('smart mode sends only core tools + ToolSearchTool, deferring the rest', () => {
    expect(names(reg.getSchemas({ mode: 'smart' }))).toEqual(
      ['BashTool', 'ReadFileTool', 'ToolSearchTool'].sort(),
    );
  });

  it('keeps precision editing and targeted verification callable in smart mode', () => {
    reg.register(fakeTool('SymbolEditTool'));
    reg.register(fakeTool('RelatedTestsTool'));
    expect(names(reg.getSchemas({ mode: 'smart' }))).toEqual(
      expect.arrayContaining(['SymbolEditTool', 'RelatedTestsTool']),
    );
    expect(reg.isDeferred('SymbolEditTool')).toBe(false);
  });

  it('classifies deferred tools correctly', () => {
    expect(reg.isDeferred('ScoutTool')).toBe(true);
    expect(reg.isDeferred('mcp__github__create')).toBe(true);
    expect(reg.isDeferred('ReadFileTool')).toBe(false);
    expect(reg.isDeferred('ToolSearchTool')).toBe(false);
  });

  it('deferredSummary lists undiscovered deferred tools only', () => {
    const before = reg.deferredSummary().map(t => t.name).sort();
    expect(before).toEqual(['ScoutTool', 'mcp__github__create'].sort());
  });

  it('once discovered, a deferred tool is sent in smart mode and drops off the summary', () => {
    reg.markDiscovered(['ScoutTool']);
    expect(names(reg.getSchemas({ mode: 'smart' }))).toContain('ScoutTool');
    expect(reg.deferredSummary().map(t => t.name)).not.toContain('ScoutTool');
  });

  it('searchDeferred by keyword marks matches discovered and returns their schemas', () => {
    const found = reg.searchDeferred('scout');
    expect(found.map((s: any) => s.name)).toContain('ScoutTool');
    expect(reg.isDiscovered('ScoutTool')).toBe(true);
  });

  it('searchDeferred supports select:Name syntax', () => {
    const found = reg.searchDeferred('select:mcp__github__create');
    expect(found.map((s: any) => s.name)).toEqual(['mcp__github__create']);
    expect(reg.isDiscovered('mcp__github__create')).toBe(true);
  });

  // Note: these use DEFERRED tool names (not CORE tools like WebFetchTool, which are never deferred).
  it('searchDeferred fuzzy-ranks by relevance, name over description', () => {
    const r = new ToolRegistry();
    r.register(fakeTool('ScoutTool', 'browse the internet'));          // "scout" in the NAME
    r.register(fakeTool('CrawlerTool', 'scout and index remote pages')); // "scout" only in description
    r.register(fakeTool('DockerTool', 'run containers'));               // irrelevant
    const found = r.searchDeferred('scout').map((s: any) => s.name);
    expect(found[0]).toBe('ScoutTool');    // name hit ranks first
    expect(found).not.toContain('DockerTool'); // irrelevant tool excluded
  });

  it('searchDeferred matches abbreviations/dropped chars (proving fuzzy, not substring)', () => {
    const r = new ToolRegistry();
    r.register(fakeTool('ScoutTool', 'browse the internet'));
    r.register(fakeTool('DockerTool', 'run containers'));
    // "scot" is a subsequence of "scout" — no contiguous substring match, so the old includes() path
    // would find nothing; fuzzysort still resolves it.
    const found = r.searchDeferred('scot').map((s: any) => s.name);
    expect(found).toContain('ScoutTool');
  });

  it('unregister clears discovery state', () => {
    reg.markDiscovered(['ScoutTool']);
    reg.unregister('ScoutTool');
    expect(reg.isDiscovered('ScoutTool')).toBe(false);
    expect(names(reg.getSchemas({ mode: 'smart' }))).not.toContain('ScoutTool');
  });
});

