test('F05 rejects private and mixed DNS results before a connection', async () => {
  jest.mocked(lookup).mockResolvedValue([
    { address: '93.184.216.34', family: 4 },
    { address: '127.0.0.1', family: 4 },
  ] as never);
  await expect(fetchPublicText('https://public-fixture.invalid/', async () => {})).rejects.toThrow('non-public');
  expect(reached).toEqual([]);
});
test('F05 redirects revalidate destination and cannot reuse public-host consent for a private target', async () => {
  replies.push({ status: 302, headers: { location: 'http://127.0.0.1/secret' } });
  const authorize = jest.fn(async () => {});
  await expect(fetchPublicText('https://public-fixture.invalid/', authorize)).rejects.toThrow('Non-public');
  expect(reached).toHaveLength(1);
  expect(authorize).toHaveBeenCalledTimes(1);
  expect(streams[0].destroyed).toBe(true);
});
test('F05 each allowed redirect has separate policy admission; loops and HTTPS downgrades stop', async () => {
  replies.push(
    { status: 302, headers: { location: 'https://other-fixture.invalid/' } },
    { chunks: [Buffer.from('result')] },
  );
  const authorized: string[] = [];
  expect(
    (
      await fetchPublicText('https://public-fixture.invalid/', async (url) => {
        authorized.push(url.host);
      })
    ).body,
  ).toBe('result');
  expect(authorized).toEqual(['public-fixture.invalid', 'other-fixture.invalid']);
  replies.push({ status: 302, headers: { location: 'http://other-fixture.invalid/' } });
  await expect(fetchPublicText('https://public-fixture.invalid/', async () => {})).rejects.toThrow('downgrade');
  replies.push(
    ...Array.from({ length: 6 }, () => ({ status: 302, headers: { location: 'https://loop-fixture.invalid/' } })),
  );
  await expect(fetchPublicText('https://loop-fixture.invalid/', async () => {})).rejects.toThrow('redirects');
});
test('F05 Stop before/during DNS prevents socket admission', async () => {
  const stop = new AbortController();
  stop.abort(new Error('stopped'));
  await expect(fetchPublicText('https://public-fixture.invalid/', async () => {}, stop.signal)).rejects.toThrow(
    'stopped',
  );
  expect(reached).toEqual([]);
  const pending = new AbortController();
  let resolveDns!: (value: unknown) => void;
  jest.mocked(lookup).mockImplementation(
    () =>
      new Promise((resolve) => {
        resolveDns = resolve;
      }) as never,
  );
  const job = fetchPublicText('https://public-fixture.invalid/', async () => {}, pending.signal);
  await new Promise((resolve) => setImmediate(resolve));
  pending.abort(new Error('stopped during DNS'));
  await expect(job).rejects.toThrow('stopped during DNS');
  resolveDns([{ address: '93.184.216.34', family: 4 }]);
  await new Promise((resolve) => setImmediate(resolve));
  expect(reached).toEqual([]);
});
test('F06 rejects declared and chunked overflow, destroys streams, and preserves split UTF-8', async () => {
  const make = (headers: Record<string, string>, chunks: Buffer[]) =>
    Object.assign(Readable.from(chunks), { headers }) as unknown as http.IncomingMessage;
  const declared = make({ 'content-length': '2097152' }, []);
  await expect(boundedBody(declared, 1024)).rejects.toThrow('byte budget');
  expect(declared.destroyed).toBe(true);
  const chunked = make({}, [Buffer.alloc(1000), Buffer.alloc(1000)]);
  await expect(boundedBody(chunked, 1024)).rejects.toThrow('byte budget');
  expect(chunked.destroyed).toBe(true);
  const compressed = make({ 'content-encoding': 'gzip' }, [Buffer.from('compressed')]);
  await expect(boundedBody(compressed, 1024)).rejects.toThrow('Compressed');
  expect(compressed.destroyed).toBe(true);
  expect(await boundedBody(make({}, [Buffer.from([0xce]), Buffer.from([0xb1])]), 1024)).toBe('α');
});

import * as fs from 'fs';
import * as os from 'os';
import * as path from 'path';
import * as childProcess from 'child_process';
import { promisify } from 'util';
import { engineWorkerRoot, installWorkerFolder, type WorkerFolderModules } from '../engine/worker.folder';

/**
 * Record 64, M1: an engine running as a worker thread gets a working folder of its own. Installed here on COPIES of
 * the real modules, so the test process's own fs and cwd are never touched; the real install happens only inside an
 * engine worker (`engineWorkerRoot`).
 */

let root: string;
let scratchCwd: string;
let realCwd: string;
let m: WorkerFolderModules & { fs: typeof fs & { promises: typeof fs.promises }; childProcess: typeof childProcess };

// The test process itself works from a scratch folder while these run: if the code under test ever fails to resolve
// a relative path, the stray file lands there — never in the repository (a mutant run once left a.txt in the repo root).
beforeAll(() => {
  realCwd = process.cwd();
  scratchCwd = fs.realpathSync(fs.mkdtempSync(path.join(os.tmpdir(), 'bimax-worker-folder-cwd-')));
  process.chdir(scratchCwd);
});
afterAll(() => {
  process.chdir(realCwd);
  fs.rmSync(scratchCwd, { recursive: true, force: true });
});

beforeEach(() => {
  root = fs.realpathSync(fs.mkdtempSync(path.join(os.tmpdir(), 'bimax-worker-folder-')));
  fs.mkdirSync(path.join(root, 'sub'));
  m = {
    process: { cwd: () => '/', chdir: () => undefined },
    fs: { ...fs, promises: { ...fs.promises } },
    childProcess: { ...childProcess },
  } as never;
  installWorkerFolder(root, m);
});
afterEach(() => fs.rmSync(root, { recursive: true, force: true }));

test('the worker reports its own folder, and the real process is untouched', () => {
  expect(m.process.cwd()).toBe(root);
  expect(process.cwd()).toBe(scratchCwd);
});

test('relative reads and writes land in the worker\'s folder', async () => {
  m.fs.writeFileSync('a.txt', 'one');
  expect(fs.readFileSync(path.join(root, 'a.txt'), 'utf8')).toBe('one');
  expect(fs.existsSync(path.join(scratchCwd, 'a.txt'))).toBe(false);
  expect(m.fs.readFileSync('a.txt', 'utf8')).toBe('one');
  await m.fs.promises.writeFile('b.txt', 'two');
  expect(await m.fs.promises.readFile(path.join(root, 'b.txt'), 'utf8')).toBe('two');
  m.fs.renameSync('b.txt', 'sub/c.txt');
  expect(fs.readFileSync(path.join(root, 'sub', 'c.txt'), 'utf8')).toBe('two');
  expect(m.fs.readdirSync('.').sort()).toEqual(['a.txt', 'sub']);
  expect(m.fs.realpathSync.native('a.txt')).toBe(path.join(root, 'a.txt'));
});

test('absolute paths pass through unchanged', () => {
  const elsewhere = fs.mkdtempSync(path.join(os.tmpdir(), 'bimax-worker-folder-abs-'));
  try {
    m.fs.writeFileSync(path.join(elsewhere, 'x.txt'), 'x');
    expect(fs.readFileSync(path.join(elsewhere, 'x.txt'), 'utf8')).toBe('x');
  } finally { fs.rmSync(elsewhere, { recursive: true, force: true }); }
});

test('chdir moves the folder, and fails the way the real one does', () => {
  m.process.chdir('sub');
  expect(m.process.cwd()).toBe(path.join(root, 'sub'));
  m.fs.writeFileSync('in-sub.txt', 'y');
  expect(fs.existsSync(path.join(root, 'sub', 'in-sub.txt'))).toBe(true);
  m.process.chdir('..');
  expect(() => m.process.chdir('missing')).toThrow(expect.objectContaining({ code: 'ENOENT' }));
  m.fs.writeFileSync('file.txt', 'z');
  expect(() => m.process.chdir('file.txt')).toThrow(expect.objectContaining({ code: 'ENOTDIR' }));
  expect(m.process.cwd()).toBe(root);
});

test('a symlink\'s target stays as written; only the link path is resolved', () => {
  m.fs.writeFileSync('target.txt', 't');
  m.fs.symlinkSync('target.txt', 'link.txt');
  expect(fs.readlinkSync(path.join(root, 'link.txt'))).toBe('target.txt');
  expect(fs.readFileSync(path.join(root, 'link.txt'), 'utf8')).toBe('t');
});

test('file-descriptor calls are untouched', () => {
  const fd = m.fs.openSync('fd.txt', 'w');
  m.fs.writeSync(fd, 'by fd');
  m.fs.closeSync(fd);
  expect(fs.readFileSync(path.join(root, 'fd.txt'), 'utf8')).toBe('by fd');
});

test('child processes that name no folder start in the worker\'s; one that names a folder keeps it', () => {
  expect(m.childProcess.execFileSync('pwd').toString().trim()).toBe(root);
  expect(m.childProcess.execFileSync('pwd', []).toString().trim()).toBe(root);
  expect(m.childProcess.execSync('pwd').toString().trim()).toBe(root);
  expect(m.childProcess.spawnSync('pwd').stdout.toString().trim()).toBe(root);
  expect(m.childProcess.spawnSync('pwd', [], { encoding: 'utf8' }).stdout.trim()).toBe(root);
  expect(m.childProcess.execFileSync('pwd', { cwd: path.join(root, 'sub') }).toString().trim()).toBe(path.join(root, 'sub'));
});

test('promisify keeps the custom forms of exec and exists', async () => {
  const run = await promisify(m.childProcess.exec)('pwd');
  expect(run).toEqual({ stdout: `${root}\n`, stderr: '' });
  m.fs.writeFileSync('here.txt', 'h');
  // eslint-disable-next-line @typescript-eslint/no-deprecated
  await expect(promisify(m.fs.exists)('here.txt')).resolves.toBe(true);
});

test('glob searches the worker\'s folder', () => {
  if (typeof (fs as unknown as { globSync?: unknown }).globSync !== 'function') return; // Node without fs.glob
  m.fs.writeFileSync('g1.md', '1');
  m.fs.writeFileSync('sub/g2.md', '2');
  const found = (m.fs as unknown as { globSync: (p: string) => string[] }).globSync('**/*.md').sort();
  expect(found).toEqual(['g1.md', path.join('sub', 'g2.md')]);
});

test('outside an engine worker nothing is installed', () => {
  expect(engineWorkerRoot()).toBeNull();
});

import * as fs from 'fs/promises';
import * as path from 'path';
import * as os from 'os';
import { WorkflowEvidence, evidenceIsCurrent, readEvidenceFile } from '../core/workflow.evidence';
import { createToolWorkflowTool } from '../tools/implementations/workflow.tool';
import { createReadFileTool } from '../tools/implementations/file.tool';
import { createGrepTool, createGlobTool } from '../tools/implementations/search.tool';
import { ToolRegistry } from '../tools/tool.registry';
import { IGovernor } from '../core/interfaces';
import { WorkflowStep, WorkflowResult } from '../core/tool.workflow';
import { clearHooks, registerPreHook, registerPostHook } from '../tools/hooks';
import { walkFiles } from '../utils/fsWalk';
import { WorkflowStore } from '../core/workflow.store';

interface Result { ok: boolean; workflowId?: string; retained: boolean; steps: WorkflowResult[]; error?: string }
const read = (id: string, file: string): WorkflowStep => ({ id, tool: 'ReadFileTool', args: { path: file } });

describe('workflow evidence and incremental refresh', () => {
  let cwd: string;
  let registry: ToolRegistry;
  let tool: ReturnType<typeof createToolWorkflowTool>;
  let approve: jest.Mock;
  let context: { cwd: string; sessionId: string };
  const run = async (steps: WorkflowStep[]): Promise<Result> => JSON.parse(await tool.execute({ steps }, context));
  const refresh = async (workflowId: string): Promise<Result> => JSON.parse(await tool.execute({ action: 'refresh', workflowId }, context));
  beforeEach(async () => {
    cwd = await fs.mkdtemp(path.join(os.tmpdir(), 'bimax-evidence-'));
    context = { cwd, sessionId: 'fixture-session' };
    approve = jest.fn(async () => {});
    const governor = { approveTaskExecution: approve } as unknown as IGovernor;
    registry = new ToolRegistry();
    registry.register(createReadFileTool(governor));
    registry.register(createGrepTool(governor));
    registry.register(createGlobTool(governor));
    tool = createToolWorkflowTool(governor, registry);
    await fs.writeFile(path.join(cwd, 'config.json'), '{"entry":"a.ts"}');
    await fs.writeFile(path.join(cwd, 'a.ts'), 'export const value = 1;');
    await fs.writeFile(path.join(cwd, 'b.ts'), 'export const value = 2;');
    await fs.writeFile(path.join(cwd, 'human.txt'), 'unfinished human edit');
  });
  afterEach(async () => { clearHooks(); await fs.rm(cwd, { recursive: true, force: true }); });

  const graph = (): WorkflowStep[] => [
    read('config', 'config.json'),
    { id: 'source', tool: 'ReadFileTool', args: {}, bindings: { path: { step: 'config', pointer: '/entry' } } },
    read('independent', 'human.txt'),
  ];

  it('reuses unchanged branches, but reruns a changed input and its dependents', async () => {
    const first = await run(graph());
    expect(first.ok).toBe(true);
    expect(first.steps.map(s => s.freshness)).toEqual(['current', 'current', 'current']);
    expect(first.steps.every(s => !!s.evidenceDigest && !!s.checkedAt && s.inputCount === 1)).toBe(true);
    const second = await refresh(first.workflowId!);
    expect(second.steps.map(s => s.reused)).toEqual([true, true, true]);
    await fs.writeFile(path.join(cwd, 'config.json'), '{"entry":"b.ts"}');
    const third = await refresh(first.workflowId!);
    expect(third.steps.map(s => s.reused)).toEqual([false, false, true]);
    expect(third.steps[1].output).toBe('export const value = 2;');
    expect(third.steps[0].evidenceDigest).not.toBe(first.steps[0].evidenceDigest);
    expect(await fs.readFile(path.join(cwd, 'human.txt'), 'utf8')).toBe('unfinished human edit');
    // Outer + every child still reaches the Governor, including the all-reused run.
    expect(approve).toHaveBeenCalledTimes(12);
  });

  it('detects byte changes even when size and modification time are preserved', async () => {
    const file = path.join(cwd, 'a.ts');
    const before = await fs.stat(file);
    const first = await run([read('a', 'a.ts')]);
    await fs.writeFile(file, 'export const value = 9;');
    await fs.utimes(file, before.atime, before.mtime);
    const next = await refresh(first.workflowId!);
    expect(next.steps[0].reused).toBe(false);
    expect(next.steps[0].output).toBe('export const value = 9;');
  });

  it('reruns descendants of changed evidence even when their resolved arguments are unchanged', async () => {
    const first = await run(graph());
    await fs.writeFile(path.join(cwd, 'config.json'), '{ "entry": "a.ts" }');
    const next = await refresh(first.workflowId!);
    expect(next.steps.map(s => s.reused)).toEqual([false, false, true]);
    expect(next.steps[1].output).toBe(first.steps[1].output);
  });

  it('invalidates search absence when a new matching file appears', async () => {
    const first = await run([
      { id: 'search', tool: 'GrepTool', args: { pattern: 'UNIQUE_MARKER', path: '.', glob: '*.ts' } },
      read('independent', 'human.txt'),
    ]);
    expect(first.steps[0].freshness).toBe('current');
    expect(first.steps[0].output).toContain('No matches');
    expect((await refresh(first.workflowId!)).steps[0].reused).toBe(true);
    await fs.writeFile(path.join(cwd, 'new.ts'), 'export const UNIQUE_MARKER = true;');
    const next = await refresh(first.workflowId!);
    expect(next.steps.map(s => s.reused)).toEqual([false, true]);
    expect(next.steps[0].output).toContain('UNIQUE_MARKER = true');
  });

  it('invalidates glob membership on deletion and empty-directory additions', async () => {
    await fs.mkdir(path.join(cwd, 'empty'));
    const first = await run([{ id: 'files', tool: 'GlobTool', args: { pattern: '**/*.ts' } }]);
    await fs.unlink(path.join(cwd, 'a.ts'));
    await fs.writeFile(path.join(cwd, 'empty', 'nested.ts'), '');
    const next = await refresh(first.workflowId!);
    expect(next.steps[0].reused).toBe(false);
    expect(next.steps[0].output).not.toContain('\na.ts');
    expect(next.steps[0].output).toContain('empty/nested.ts');
  });

  it('does not reuse incomplete result-limited searches or their dependent conclusions', async () => {
    const first = await run([
      { id: 'search', tool: 'GrepTool', args: { pattern: 'value', glob: '*.ts', maxResults: 1 } },
      { ...read('dependent', 'human.txt'), dependsOn: ['search'] },
    ]);
    expect(first.steps.map(s => s.freshness)).toEqual(['incomplete', 'incomplete']);
    expect(first.steps[0].evidenceGaps).toContain('Result limit reached');
    expect((await refresh(first.workflowId!)).steps.map(s => s.reused)).toEqual([false, false]);
  });

  it('marks binary-file omission incomplete rather than complete absence', async () => {
    await fs.writeFile(path.join(cwd, 'binary.dat'), Buffer.from([0, 1, 2]));
    const result = await run([{ id: 'search', tool: 'GrepTool', args: { pattern: 'absent', path: 'binary.dat' } }]);
    expect(result.steps[0].freshness).toBe('incomplete');
    expect(result.steps[0].evidenceGaps).toContain('Binary file skipped');
  });

  it('detects a change in a post-hook before allowing a dependent to consume it', async () => {
    registerPostHook('ReadFileTool', async (_name, args) => {
      if (args.path === 'config.json') await fs.writeFile(path.join(cwd, 'config.json'), '{"entry":"b.ts"}');
    });
    const result = await run(graph());
    expect(result.ok).toBe(false);
    expect(result.steps[0].freshness).toBe('stale');
    expect(result.steps[1].status).toBe('skipped');
    expect(result.steps[1].freshness).toBe('stale');
    expect(result.steps[2].freshness).toBe('current');
  });

  it('propagates a late stale input to already-completed descendants at the final check', async () => {
    registerPostHook('ReadFileTool', async (_name, args) => {
      if (args.path === 'human.txt') await fs.writeFile(path.join(cwd, 'config.json'), '{"entry":"b.ts"}');
    });
    const steps = graph();
    steps[2].dependsOn = ['source'];
    const result = await run(steps);
    expect(result.ok).toBe(false);
    expect(result.steps.map(s => s.freshness)).toEqual(['stale', 'stale', 'stale']);
  });

  it('checks current permission and hooks before returning a reusable result', async () => {
    const first = await run([read('a', 'a.ts')]);
    registerPreHook('ReadFileTool', () => ({ block: true, reason: 'revoked' }));
    const result = await refresh(first.workflowId!);
    expect(result.ok).toBe(false);
    expect(result.steps[0].output).toContain('revoked');
    expect(result.steps[0].output).not.toContain('value = 1');
  });

  it('rejects a revoked Governor permission before touching the cached result', async () => {
    const first = await run([read('a', 'a.ts')]);
    approve.mockImplementation(async (_type: string, payload: { tool: string }) => {
      if (payload.tool === 'ReadFileTool') throw new Error('read permission revoked');
    });
    const result = await refresh(first.workflowId!);
    expect(result.ok).toBe(false);
    expect(result.steps[0].output).toContain('read permission revoked');
    expect(result.steps[0].output).not.toContain('value = 1');
  });

  it('revalidates arguments after pre-hooks before selecting cached raw output', async () => {
    const first = await run([read('a', 'a.ts')]);
    registerPreHook('ReadFileTool', (_name, args) => { args.path = 'b.ts'; });
    const result = await refresh(first.workflowId!);
    expect(result.steps[0].reused).toBe(false);
    expect(result.steps[0].output).toContain('value = 2');
  });

  it('does not reuse output across a tool implementation replacement', async () => {
    const first = await run([read('a', 'a.ts')]);
    const governor = { approveTaskExecution: approve } as unknown as IGovernor;
    registry.register(createReadFileTool(governor));
    const result = await refresh(first.workflowId!);
    expect(result.steps[0].reused).toBe(false);
  });

  it('recomputes post-hook output and never accumulates old appended text', async () => {
    const first = await run([read('a', 'a.ts')]);
    registerPostHook('ReadFileTool', () => ({ appendToResult: 'fresh diagnostic' }));
    const second = await refresh(first.workflowId!);
    expect(second.steps[0].freshness).toBe('incomplete');
    expect(second.steps[0].output.match(/fresh diagnostic/g)).toHaveLength(1);
    const third = await refresh(first.workflowId!);
    expect(third.steps[0].reused).toBe(false);
    expect(third.steps[0].output.match(/fresh diagnostic/g)).toHaveLength(1);
  });

  it('fences retained graphs by session and cwd', async () => {
    const first = await run([read('a', 'a.ts')]);
    const otherSession = JSON.parse(await tool.execute({ action: 'refresh', workflowId: first.workflowId }, { ...context, sessionId: 'other' }));
    expect(otherSession.ok).toBe(false);
    expect(otherSession.steps).toEqual([]);
    const otherDir = JSON.parse(await tool.execute({ action: 'refresh', workflowId: first.workflowId }, { ...context, cwd: path.dirname(cwd) }));
    expect(otherDir.ok).toBe(false);
  });

  it('never accepts a replacement plan during refresh', async () => {
    const first = await run([read('a', 'a.ts')]);
    const result = JSON.parse(await tool.execute({ action: 'refresh', workflowId: first.workflowId, steps: [read('b', 'b.ts')] }, context));
    expect(result.ok).toBe(false);
    expect(result.steps).toEqual([]);
  });

  it('detects retargeting of a symlink to different content', async () => {
    await fs.symlink(path.join(cwd, 'a.ts'), path.join(cwd, 'link.ts'));
    const first = await run([read('link', 'link.ts')]);
    await fs.unlink(path.join(cwd, 'link.ts'));
    await fs.symlink(path.join(cwd, 'b.ts'), path.join(cwd, 'link.ts'));
    const result = await refresh(first.workflowId!);
    expect(result.steps[0].reused).toBe(false);
    expect(result.steps[0].output).toContain('value = 2');
  });

  it('bounds file reads before allocating a whole oversized file', async () => {
    await expect(readEvidenceFile(path.join(cwd, 'a.ts'), undefined, 4)).rejects.toThrow('byte limit');
    const collector = new WorkflowEvidence();
    await expect(collector.readFile(path.join(cwd, 'missing'))).rejects.toThrow();
    expect(collector.snapshot().complete).toBe(false);
  });

  it('rejects missing observations and stops walks on cancellation', async () => {
    expect(await evidenceIsCurrent(new WorkflowEvidence().snapshot())).toBe(false);
    const abort = new AbortController();
    let visited = 0;
    await expect((async () => {
      for await (const _file of walkFiles(cwd, { signal: abort.signal })) { visited++; abort.abort(); }
    })()).rejects.toThrow();
    expect(visited).toBe(1);
  });

  it('reports a capped or unreadable walk as incomplete', async () => {
    const gaps: string[] = [];
    for await (const _file of walkFiles(cwd, { maxFiles: 1, onIncomplete: reason => gaps.push(reason) })) { /* drain */ }
    expect(gaps).toContain('File scan limit reached');
    for await (const _file of walkFiles(path.join(cwd, 'missing'), { onIncomplete: reason => gaps.push(reason) })) { /* drain */ }
    expect(gaps).toContain('Directory could not be read');
  });

  it('expires retained workflows and rejects overlapping refreshes', () => {
    const store = new WorkflowStore();
    const id = store.save('scope', [], new Map())!;
    store.acquire(id, 'scope');
    expect(() => store.acquire(id, 'scope')).toThrow('already running');
    store.release(id);
    const now = jest.spyOn(Date, 'now').mockReturnValue(Date.now() + 31 * 60_000);
    try { expect(() => store.acquire(id, 'scope')).toThrow('unavailable'); }
    finally { now.mockRestore(); }
  });

  it('bounds the retained workflow count by evicting old idle entries', () => {
    const store = new WorkflowStore();
    const first = store.save('scope', [], new Map())!;
    for (let i = 0; i < 16; i++) store.save('scope', [], new Map());
    expect(() => store.acquire(first, 'scope')).toThrow('unavailable');
  });

  it('bounds retained state bytes instead of keeping an oversized graph', () => {
    const store = new WorkflowStore();
    expect(store.save('scope', [read('big', 'x'.repeat(8 * 1024 * 1024))], new Map())).toBeUndefined();
  });
});

import * as fs from 'fs';
import * as os from 'os';
import * as path from 'path';
import { execFileSync } from 'child_process';
import { WorkspaceManager, initWorkspace } from '../core/workspace.manager';
import { workspaceWriteBlock } from '../tools/path.util';

function mkRepo(dir: string): string {
  fs.mkdirSync(dir, { recursive: true });
  execFileSync('git', ['init', '-q'], { cwd: dir });
  return dir;
}

describe('WorkspaceManager (multi-repo workspace, PR1)', () => {
  let root: string;
  let primary: string;

  beforeEach(() => {
    root = fs.mkdtempSync(path.join(os.tmpdir(), 'bimax-ws-'));
    primary = mkRepo(path.join(root, 'primary'));
  });

  afterEach(() => {
    fs.rmSync(root, { recursive: true, force: true });
  });

  it('registers the primary repo writable on refresh and persists the manifest', () => {
    const ws = new WorkspaceManager(primary);
    ws.refresh();
    const act = ws.active();
    expect(act.length).toBe(1);
    expect(act[0].scope).toBe('write');
    expect(act[0].name).toBe('primary');
    expect(fs.existsSync(path.join(primary, '.bimax', 'workspace.json'))).toBe(true);
  });

  it('registers additional repos read-only by default and scopes them', () => {
    const other = mkRepo(path.join(root, 'reference'));
    const ws = new WorkspaceManager(primary);
    ws.refresh();
    const r = ws.register(other, { purpose: 'pattern source' });
    expect(r.scope).toBe('read');

    expect(ws.checkWrite(path.join(other, 'lib.ts')).allowed).toBe(false);
    expect(ws.checkWrite(path.join(primary, 'src', 'a.ts')).allowed).toBe(true);
    // Paths outside every registered repo keep today's behavior.
    expect(ws.checkWrite(path.join(root, 'elsewhere', 'x.txt')).allowed).toBe(true);

    ws.setScope(other, 'write');
    expect(ws.checkWrite(path.join(other, 'lib.ts')).allowed).toBe(true);
  });

  it('detects a git clone from a shell command and queues it as an ask-once candidate', () => {
    const cloned = mkRepo(path.join(root, 'fresh-find'));
    const ws = new WorkspaceManager(primary);
    ws.refresh();
    ws.noticeCommand(`git clone https://github.com/x/fresh-find ${cloned}`, root);
    expect(ws.pending()).toContain(cloned);

    // ignore = ask-once "no": never suggested again, even after a rescan.
    ws.ignore(cloned);
    expect(ws.pending()).not.toContain(cloned);
    ws.scan(root);
    expect(ws.pending()).not.toContain(cloned);
  });

  it('derives the clone target dir from the URL when none is given', () => {
    const cloned = mkRepo(path.join(root, 'by-url'));
    const ws = new WorkspaceManager(primary);
    ws.noticeCommand('git clone https://github.com/someone/by-url.git', root);
    expect(ws.pending()).toContain(cloned);
  });

  it('survives reload: registrations and scopes come back from the manifest', () => {
    const other = mkRepo(path.join(root, 'reference'));
    const ws1 = new WorkspaceManager(primary);
    ws1.refresh();
    ws1.register(other, { purpose: 'ref', scope: 'write' });

    const ws2 = new WorkspaceManager(primary);
    const found = ws2.find(other);
    expect(found?.scope).toBe('write');
    expect(found?.purpose).toBe('ref');
  });

  it('exposes the context block and snapshot only in multi-repo sessions', () => {
    const ws = new WorkspaceManager(primary);
    ws.refresh();
    expect(ws.contextBlock()).toBe(''); // single repo: no block, zero prompt cost

    const other = mkRepo(path.join(root, 'reference'));
    ws.register(other, { purpose: 'pattern source' });
    const block = ws.contextBlock();
    expect(block).toContain('WORKSPACE (2 repos)');
    expect(block).toContain('reference (read-only)');
    expect(ws.snapshot()).toEqual({ count: 2, names: ['primary', 'reference'], writable: 1 });
  });

  it('workspaceWriteBlock wires the singleton into the write tools', () => {
    const other = mkRepo(path.join(root, 'readonly-ref'));
    initWorkspace(primary);
    const ws = require('../core/workspace.manager').getWorkspace();
    ws.register(other);
    expect(workspaceWriteBlock(path.join(other, 'x.ts'))).toContain('READ-ONLY');
    expect(workspaceWriteBlock(path.join(primary, 'x.ts'))).toBeNull();
  });
});

import { execSync, execFileSync } from 'child_process';
import * as fs from 'fs';
import * as path from 'path';
import * as os from 'os';

export interface ScoutReport {
  url: string;
  repoName: string;
  defaultBranch: string;
  topFiles: string[];
  entryPoints: string[];
  languages: Record<string, number>;
  readme: string;
  packageJson?: Record<string, any>;
  exportedSymbols: string[];
  error?: string;
}

const EXT_TO_LANG: Record<string, string> = {
  '.ts': 'TypeScript', '.tsx': 'TypeScript', '.js': 'JavaScript', '.jsx': 'JavaScript',
  '.py': 'Python', '.go': 'Go', '.rs': 'Rust', '.java': 'Java', '.rb': 'Ruby',
  '.cs': 'C#', '.cpp': 'C++', '.c': 'C', '.swift': 'Swift', '.kt': 'Kotlin',
};

const SKIP_DIRS = new Set(['.git', 'node_modules', '__pycache__', 'target', 'dist', 'build', '.next']);

/** Recursively enumerate files, skipping well-known vendor/build dirs. */
function* walkFiles(dir: string): Generator<{ fullPath: string; size: number }> {
  let entries: fs.Dirent[];
  try { entries = fs.readdirSync(dir, { withFileTypes: true }); } catch { return; }
  for (const e of entries) {
    if (SKIP_DIRS.has(e.name)) continue;
    const fullPath = path.join(dir, e.name);
    if (e.isDirectory()) { yield* walkFiles(fullPath); }
    else if (e.isFile()) {
      try { yield { fullPath, size: fs.statSync(fullPath).size }; } catch { /* skip unreadable */ }
    }
  }
}

function detectLanguages(dir: string): Record<string, number> {
  const counts: Record<string, number> = {};
  for (const { fullPath } of walkFiles(dir)) {
    const lang = EXT_TO_LANG[path.extname(fullPath).toLowerCase()];
    if (lang) counts[lang] = (counts[lang] ?? 0) + 1;
  }
  return counts;
}

function topFilesBySize(dir: string, limit = 20): string[] {
  const files: { rel: string; size: number }[] = [];
  for (const { fullPath, size } of walkFiles(dir)) {
    files.push({ rel: path.relative(dir, fullPath), size });
  }
  return files
    .sort((a, b) => b.size - a.size)
    .slice(0, limit)
    .map(f => f.rel);
}

function findEntryPoints(dir: string): string[] {
  const candidates = [
    'src/index.ts', 'src/main.ts', 'index.ts', 'main.ts',
    'src/index.js', 'index.js', 'main.py', '__main__.py', 'main.go', 'src/lib.rs',
  ];
  return candidates.filter(c => fs.existsSync(path.join(dir, c)));
}

function extractExportedSymbols(dir: string, limit = 20): string[] {
  const symbols: string[] = [];
  try {
    const out = execSync(
      `grep -r --include="*.ts" --include="*.js" -h "^export " . 2>/dev/null | head -${limit}`,
      { cwd: dir, encoding: 'utf8', stdio: ['ignore', 'pipe', 'ignore'], timeout: 10000 }
    );
    for (const line of out.trim().split('\n').filter(Boolean).slice(0, limit)) {
      symbols.push(line.trim().slice(0, 120));
    }
  } catch { /* ignore */ }
  return symbols;
}

/**
 * ScoutAgent — read-only repo inspector. Shallow-clones a remote git repository into a temp
 * directory, extracts structural information (languages, entry points, exports, README),
 * then deletes the clone. Never writes to the user's working directory.
 */
export class ScoutAgent {
  async inspect(url: string): Promise<ScoutReport> {
    const tmpDir = fs.mkdtempSync(path.join(os.tmpdir(), 'bimax-scout-'));
    const repoName = url.split('/').pop()?.replace(/\.git$/, '') ?? 'unknown';

    try {
      try {
        execFileSync('git', ['clone', '--depth=1', '--quiet', url, tmpDir], {
          timeout: 60000,
          stdio: ['ignore', 'ignore', 'ignore'],
        });
      } catch (e: any) {
        return {
          url, repoName, defaultBranch: '', topFiles: [], entryPoints: [],
          languages: {}, readme: '', exportedSymbols: [],
          error: `Clone failed: ${e.message?.slice(0, 200)}`,
        };
      }

      let branch = 'main';
      try {
        branch = execFileSync('git', ['rev-parse', '--abbrev-ref', 'HEAD'], {
          cwd: tmpDir, encoding: 'utf8', stdio: ['ignore', 'pipe', 'ignore'],
        }).trim() || 'main';
      } catch { /* use default */ }

      const readmePath = ['README.md', 'readme.md', 'README.txt', 'README']
        .find(r => fs.existsSync(path.join(tmpDir, r)));
      let readme = '';
      if (readmePath) {
        try { readme = fs.readFileSync(path.join(tmpDir, readmePath), 'utf8').slice(0, 2000); } catch { /* ignore */ }
      }

      let packageJson: Record<string, any> | undefined;
      const pkgPath = path.join(tmpDir, 'package.json');
      if (fs.existsSync(pkgPath)) {
        try { packageJson = JSON.parse(fs.readFileSync(pkgPath, 'utf8')); } catch { /* ignore */ }
      }

      return {
        url,
        repoName,
        defaultBranch: branch,
        topFiles: topFilesBySize(tmpDir),
        entryPoints: findEntryPoints(tmpDir),
        languages: detectLanguages(tmpDir),
        readme,
        packageJson,
        exportedSymbols: extractExportedSymbols(tmpDir),
      };
    } finally {
      try { fs.rmSync(tmpDir, { recursive: true, force: true }); } catch { /* ignore */ }
    }
  }
}

export function formatScoutReport(r: ScoutReport): string {
  if (r.error) return `Scout failed: ${r.error}`;

  const lines: string[] = [
    `## Scout Report: ${r.repoName}`,
    `URL: ${r.url}  branch: ${r.defaultBranch}`,
    '',
  ];

  const langStr = Object.entries(r.languages)
    .sort((a, b) => b[1] - a[1])
    .map(([l, n]) => `${l} (${n})`)
    .join(', ');
  if (langStr) lines.push(`**Languages:** ${langStr}`, '');

  if (r.entryPoints.length > 0) lines.push(`**Entry points:** ${r.entryPoints.join(', ')}`, '');

  if (r.packageJson) {
    const name = r.packageJson.name ?? r.repoName;
    const desc = r.packageJson.description ?? '';
    const ver = r.packageJson.version ?? '';
    lines.push(`**Package:** ${name}${ver ? ` v${ver}` : ''}${desc ? ` — ${desc}` : ''}`, '');
    const deps = Object.keys(r.packageJson.dependencies ?? {}).slice(0, 10).join(', ');
    if (deps) lines.push(`**Key deps:** ${deps}`, '');
  }

  if (r.exportedSymbols.length > 0) {
    lines.push('**Top exports:**');
    for (const s of r.exportedSymbols.slice(0, 10)) lines.push(`  ${s}`);
    lines.push('');
  }

  if (r.topFiles.length > 0) {
    lines.push('**Top files by size:**');
    for (const f of r.topFiles.slice(0, 10)) lines.push(`  ${f}`);
    lines.push('');
  }

  if (r.readme) {
    lines.push('**README (first 2000 chars):**', '```');
    lines.push(r.readme);
    lines.push('```');
  }

  return lines.join('\n');
}

// The capability installation transaction — owner section 29 (V29B), slice S29-B.
//
// §15 of docs/product-reset/11_SECTIONS_28_29_RESEARCH_AND_DELIVERY_PLAN.md gives the exact order:
//
//   fetch trusted metadata → resolve version/platform/dependencies → show permission + disk +
//   provenance diff → user/policy approval → download to staging → verify length/digest/signature/
//   provenance/notarization → scan/decompress with path and size limits → register inactive →
//   health-check isolated entrypoint → atomically activate → preserve rollback target
//
// This file is that order, made unskippable. The steps are a sequence, each one refuses to run
// before its predecessor succeeded, and the *only* way to reach `activate` is through all of them.
//
// The property S29-17 grades is rollback: "resolver failure with dirty project → rollback preserves
// all unrelated user changes and previous capability graph". So the transaction never mutates the
// live graph until activation, and activation captures the exact prior node — state, version and
// history — so restoring it is a copy back rather than a re-derivation. A re-derived "previous
// state" is a guess, and a guess is what the mutation test is looking for.

import {
  CapabilityGraph, CapabilityManifest, CapabilityNode, CapabilityState, declaredAuthority,
} from './manifest';
import {
  DownloadedArtifact, MetadataVerdict, ReviewNotes, TargetDescriptor, isDependencyConfusion,
} from './metadata';
import { ArchiveEntry, StagingVerdict, inspectArchive } from './staging';
import { DeclaredEffects } from '../evidence/schema';

export type TransactionStep =
  | 'metadata' | 'resolve' | 'preview' | 'approve' | 'verify' | 'stage'
  | 'register' | 'health-check' | 'activate' | 'committed'
  | 'refused' | 'rolled-back';

/** The order a transaction must pass through. Index comparison is the whole enforcement. */
const ORDER: TransactionStep[] = [
  'metadata', 'resolve', 'preview', 'approve', 'verify', 'stage',
  'register', 'health-check', 'activate', 'committed',
];

export interface InstallPreview {
  capabilityId: string;
  fromVersion: string | null;
  toVersion: string;
  /** Permissions being added relative to what is already permitted. The approval is about these. */
  newPermissions: DeclaredEffects;
  diskBytes: number;
  publisherIdentity: string | null;
  provenance: string | null;
  /** Vulnerability notes, review-only. §15 forbids acting on these automatically. */
  review: ReviewNotes;
  /** True when the manifest says a previous version can be restored. */
  rollbackSupported: boolean;
}

export interface StepResult {
  ok: boolean;
  step: TransactionStep;
  problems: string[];
  remedy: string | null;
}

const fail = (step: TransactionStep, problems: string[], remedy: string | null = null): StepResult =>
  ({ ok: false, step, problems, remedy });
const pass = (step: TransactionStep): StepResult => ({ ok: true, step, problems: [], remedy: null });

/** A byte-exact copy of a graph node, so restoring it cannot drift from what was there. */
function snapshotNode(node: CapabilityNode): CapabilityNode {
  return {
    manifest: { ...node.manifest, permissions: { ...node.manifest.permissions } },
    state: node.state,
    history: node.history.map(entry => ({ ...entry })),
    rollbackTarget: node.rollbackTarget,
  };
}

export interface TransactionOptions {
  requireNotarization?: boolean;
  now?: () => number;
}

/**
 * One installation. Single-use: a transaction that refused or committed is finished, and a retry is
 * a new transaction with fresh metadata. Reusing one would let a stale verification carry forward.
 */
export class CapabilityTransaction {
  private step: TransactionStep = 'metadata';
  private readonly problems: string[] = [];
  private preview: InstallPreview | null = null;
  private approvedPreview: InstallPreview | null = null;
  private stagingPlan: StagingVerdict | null = null;
  /** The exact node that was live before activation. The rollback target, not a reconstruction. */
  private priorNode: CapabilityNode | null = null;
  private priorAbsent = false;

  constructor(
    private readonly graph: CapabilityGraph,
    private readonly manifest: CapabilityManifest,
    private readonly options: TransactionOptions = {},
  ) {}

  get currentStep(): TransactionStep { return this.step; }
  get failures(): string[] { return [...this.problems]; }
  get approvedFor(): InstallPreview | null { return this.approvedPreview; }

  private at(step: TransactionStep): boolean { return this.step === step; }

  private advanceTo(step: TransactionStep): void {
    this.step = step;
  }

  private refuse(step: TransactionStep, problems: string[], remedy: string | null): StepResult {
    this.problems.push(...problems);
    this.step = 'refused';
    return fail(step, problems, remedy ?? 'nothing was installed; the existing capability graph is unchanged');
  }

  /** Step 1. The caller verifies the metadata chain; this records the verdict and refuses on it. */
  acceptMetadata(verdict: MetadataVerdict): StepResult {
    if (!this.at('metadata')) return fail('metadata', ['metadata was already accepted or the transaction is finished']);
    if (!verdict.trusted) return this.refuse('metadata', verdict.problems, verdict.remedy);
    this.advanceTo('resolve');
    return pass('metadata');
  }

  /** Step 2. Version, platform, dependency and namespace resolution against the live graph. */
  resolve(requestedId: string): StepResult {
    if (!this.at('resolve')) return fail('resolve', ['resolve ran out of order']);
    const problems: string[] = [];
    if (isDependencyConfusion(requestedId, this.manifest.id)) {
      problems.push(`requested ${requestedId} but the catalog resolved ${this.manifest.id}, a different namespace`);
    }
    const compatibility = this.graph.compatibility(this.manifest);
    if (!compatibility.compatible) problems.push(...compatibility.reasons);
    for (const unmet of this.graph.unmetDependencies(this.manifest)) {
      problems.push(`dependency ${unmet.id} ${unmet.want} is ${unmet.have ? `installed at ${unmet.have}` : 'not installed'}`);
    }
    if (problems.length) {
      return this.refuse('resolve', problems, 'resolve the listed constraints, then try the install again');
    }
    this.advanceTo('preview');
    return pass('resolve');
  }

  /** Step 3. Build the diff the user approves. Never mutates anything. */
  buildPreview(diskBytes: number, review: ReviewNotes): InstallPreview {
    const existing = this.graph.get(this.manifest.id);
    this.preview = {
      capabilityId: this.manifest.id,
      fromVersion: existing?.manifest.version ?? null,
      toVersion: this.manifest.version,
      newPermissions: permissionDelta(existing?.manifest ?? null, this.manifest),
      diskBytes,
      publisherIdentity: this.manifest.publisherIdentity,
      provenance: this.manifest.provenance,
      review,
      rollbackSupported: this.manifest.rollbackSupported,
    };
    if (this.at('preview')) this.advanceTo('approve');
    return this.preview;
  }

  /**
   * Step 4. Approval is bound to the exact preview shown. If the preview changed between display
   * and approval — new permissions, a different version — the approval does not carry.
   */
  approve(approvedPreview: InstallPreview): StepResult {
    if (!this.at('approve')) return fail('approve', ['approve ran out of order']);
    if (!this.preview) return this.refuse('approve', ['no preview was built'], null);
    if (JSON.stringify(approvedPreview) !== JSON.stringify(this.preview)) {
      return this.refuse(
        'approve',
        ['the approved preview does not match what this transaction would install'],
        'review the change again — the permissions, version or disk impact moved after it was shown',
      );
    }
    this.approvedPreview = approvedPreview;
    this.advanceTo('verify');
    return pass('approve');
  }

  /** Step 5. Length, digest, publisher identity, provenance and notarization of the artifact. */
  verifyArtifact(verdict: MetadataVerdict): StepResult {
    if (!this.at('verify')) return fail('verify', ['verify ran out of order']);
    if (!verdict.trusted) return this.refuse('verify', verdict.problems, verdict.remedy);
    this.advanceTo('stage');
    return pass('verify');
  }

  /** Step 6. Bounded inspection. Nothing is written unless the whole archive is accepted. */
  stage(entries: ArchiveEntry[], stagingRoot: string): StepResult {
    if (!this.at('stage')) return fail('stage', ['stage ran out of order']);
    const verdict = inspectArchive(entries, stagingRoot, this.manifest.scripts);
    this.stagingPlan = verdict;
    if (!verdict.accepted) {
      return this.refuse(
        'stage',
        verdict.rejections.map(r => `${r.rule}: ${r.entry} — ${r.detail}`),
        'the archive was rejected before extraction; nothing was written outside the staging root',
      );
    }
    this.advanceTo('register');
    return pass('stage');
  }

  /** What extraction would write. Empty until staging accepted, and empty forever if it refused. */
  get plannedWrites(): ArchiveEntry[] { return this.stagingPlan?.plan ?? []; }

  /** Step 7. Register inactive. The capability exists in the graph but grants nothing yet. */
  register(): StepResult {
    if (!this.at('register')) return fail('register', ['register ran out of order']);
    const existing = this.graph.get(this.manifest.id);
    if (existing) {
      this.priorNode = snapshotNode(existing);
    } else {
      this.priorAbsent = true;
    }
    // Discovery replaces the node with the incoming version, still at `discovered` — nothing is
    // granted, and the prior node is already captured byte-for-byte above.
    this.graph.discover(this.manifest, `staged ${this.manifest.version} for installation`);
    const walked = this.graph.advance(this.manifest.id, 'verified', 'signed metadata and artifact digest verified')
      && this.graph.advance(this.manifest.id, 'compatible', 'platform, macOS minimum and dependencies resolved')
      && this.graph.advance(this.manifest.id, 'permitted', 'the exact preview shown was approved');
    if (!walked) return this.refuse('register', ['the capability graph refused a transition'], null);
    this.advanceTo('health-check');
    return pass('register');
  }

  /** Step 8. Health-check the isolated entrypoint before it can be reached by a task. */
  healthCheck(healthy: boolean, detail: string): StepResult {
    if (!this.at('health-check')) return fail('health-check', ['health check ran out of order']);
    if (!healthy) {
      this.rollback(`health check failed: ${detail}`);
      return fail('health-check', [`health check failed: ${detail}`],
        'the previous version remains active and the staged version was discarded');
    }
    this.advanceTo('activate');
    return pass('health-check');
  }

  /** Step 9. Atomic activation, with the rollback target preserved. */
  activate(): StepResult {
    if (!this.at('activate')) return fail('activate', ['activate ran out of order']);
    if (!this.graph.advance(this.manifest.id, 'activated', 'health check passed on the isolated entrypoint')) {
      return this.refuse('activate', ['the capability graph refused activation'], null);
    }
    this.graph.setRollbackTarget(this.manifest.id, this.priorNode?.manifest.version ?? null);
    this.graph.advance(this.manifest.id, 'healthy', 'activated and reachable');
    this.advanceTo('committed');
    return pass('activate');
  }

  /**
   * Restore the exact prior graph.
   *
   * "Exact" is the whole point: the captured node is written back as it was, including its history,
   * so the timeline shows the failed attempt and the restoration rather than a graph that quietly
   * looks like nothing happened. When there was no prior version the capability is removed by being
   * marked `rollback`, which is off the forward path — a half-installed capability must never be
   * reachable, and leaving it `discovered` would let a later step pick it up.
   */
  rollback(reason: string): StepResult {
    const restored = this.priorNode;
    if (restored) {
      this.graph.discover(restored.manifest, `rolled back to ${restored.manifest.version}: ${reason}`);
      const node = this.graph.get(restored.manifest.id) as CapabilityNode;
      node.state = restored.state;
      node.rollbackTarget = restored.rollbackTarget;
      node.history = [
        ...restored.history,
        { at: (this.options.now ?? Date.now)(), state: restored.state, reason: `rolled back: ${reason}` },
      ];
    } else if (this.priorAbsent) {
      this.graph.halt(this.manifest.id, 'rollback', `install did not complete: ${reason}`);
    }
    this.step = 'rolled-back';
    this.problems.push(reason);
    return { ok: true, step: 'rolled-back', problems: [reason], remedy: null };
  }

  /** True when this transaction reached a state where nothing further may happen. */
  get finished(): boolean {
    return this.step === 'committed' || this.step === 'refused' || this.step === 'rolled-back';
  }

  /** How far through the required order this transaction got, for the receipt. */
  get progress(): { reached: TransactionStep; index: number; total: number } {
    const index = ORDER.indexOf(this.step);
    return { reached: this.step, index: index < 0 ? -1 : index, total: ORDER.length };
  }
}

/**
 * Permissions the incoming version adds over the installed one. An upgrade that asks for nothing new
 * should not present the user with the whole permission set again — and an upgrade that quietly
 * widens authority must not be able to hide inside a version bump.
 */
export function permissionDelta(from: CapabilityManifest | null, to: CapabilityManifest): DeclaredEffects {
  const incoming = declaredAuthority(to);
  if (!from) return incoming;
  const existing = declaredAuthority(from);
  const added = (next: string[], previous: string[]) => next.filter(value => !previous.includes(value));
  return {
    reads: added(incoming.reads, existing.reads),
    writes: added(incoming.writes, existing.writes),
    deletes: added(incoming.deletes, existing.deletes),
    hosts: added(incoming.hosts, existing.hosts),
    processes: added(incoming.processes, existing.processes),
    installsDependencies: incoming.installsDependencies && !existing.installsDependencies,
    readOnly: incoming.readOnly,
  };
}

/** True when the delta asks for anything at all — the trigger for a fresh approval on upgrade. */
export function widensAuthority(delta: DeclaredEffects): boolean {
  return delta.reads.length > 0 || delta.writes.length > 0 || delta.deletes.length > 0
    || delta.hosts.length > 0 || delta.processes.length > 0 || delta.installsDependencies;
}

