// Line-delimited sentinels the sub-agent SUBPROCESS (bun-compiled binary re-execing itself) writes to
// stdout, and the parent parses back into the same {type} messages a worker_thread posts. Shared with
// worker.entry.ts's runAsSubprocess so the two ends can never drift.
export const SUB_RESULT = '\x00BIMAX_SUB_RESULT\x00';
export const SUB_ERROR = '\x00BIMAX_SUB_ERROR\x00';
export const SUB_EVENT = '\x00BIMAX_SUB_EVENT\x00';
export const SUB_READY = '\x00BIMAX_SUB_READY\x00';

// The uniform surface both a Worker (Node dev/dist) and a child-process handle (bun binary) expose,
// so the spawn/timeout/settle logic below is identical for both transports.
interface WorkerHandle {
  on(event: 'message' | 'error' | 'exit', listener: (arg: any) => void): void;
  terminate(): void | Promise<number>;
}

export interface SubAgentConfig {
  /** Frozen, host-admitted bot assignment; absent for ordinary sub-agent workers. */
  botRun?: import('../bots/worker.policy').BotAssignment;
  runBudget?: SharedArrayBuffer;
  agentType: string;
  prompt: string;
  cwd: string;
  parentMode: string;
  // What this agent is responsible for (paths/globs/topic) — its claim on the blackboard, used to
  // detect overlap with sibling agents and to show coverage in /subagents and the TUI panel.
  scope?: string;
  // Model this sub-agent runs on. Unset = inherit the parent's configured model. Set per-spawn
  // (SpawnSubagentTool's `model` arg) or globally (config.subagentModel).
  model?: string;
  // Sandbox floor (BiMax v2): when set, the worker runs as an isolated autonomous episode —
  // Bash confined by the OS sandbox to this root with network denied, file tools' workspace
  // narrowed to it, net-facing tools not registered. Carried via the worker's own env copy.
  sandboxFloorRoot?: string;
  // Worktree isolation (the Cursor 2.0 / Claude Code pattern): the sub-agent runs in its own git
  // worktree + branch under .bimax/worktrees/, so parallel agents can't clobber each other's
  // edits. Auto-removed when the agent changed nothing; kept (and reported) when it did.
  isolation?: 'worktree';
  /** Coordinated writable assignments fail closed if their requested worktree cannot be created. */
  isolationRequired?: boolean;
  // Nesting depth of this agent in the tree: the main session is 0, its sub-agents are 1, theirs
  // are 2. Workers register SpawnSubagentTool only while depth < MAX_SUBAGENT_DEPTH, giving the
  // 3-level agent trees Claude Code ships (main + two nested layers).
  depth?: number;
  /** Stable link to the engine-owned outcome task this worker is executing. */
  outcomeTaskId?: string;
  /** Outcome session owning the assignment, so a late result cannot settle a different thread. */
  outcomeSessionId?: string;
  /** Shared cross-process capacity context inherited by nested workers and worktrees. */
  capacityPath?: string;
  capacityRunId?: string;
  capacityLeaseId?: string;
  capacityParentLeaseId?: string;
  /** Durable identity of an already-created isolated checkout; used to resume crash-surviving edits. */
  recoveryWorktree?: WorktreeInfo;
  /** Previous worker id when this config was reconstructed from a crash checkpoint. */
  recoveryOf?: string;
}

/** Maximum nesting depth of the agent tree (main session = 0, so 3 ⇒ two nested worker layers). */
export const MAX_SUBAGENT_DEPTH = 3;

/**
 * The heap limit of one sub-agent worker, a MEMORY cap. In the monolith (record 64) every isolate in the app's
 * process shares one 4 GB V8 heap, so a sub-agent gets a bounded share: over it, that worker is terminated and its task
 * fails, instead of the whole app hitting the process-wide limit. An engine indexing this whole repository peaked at
 * 128 MB used heap; a sub-agent does less.
 */
export const SUBAGENT_WORKER_HEAP_MB = 384;

/**
 * Read a sub-agent's stdout sentinels and emit the messages a worker_thread would post. Shared by the subprocess and
 * the bundle-worker paths, so the two can never parse differently.
 */
function translateSentinels(stdout: NodeJS.ReadableStream, emitter: import('events').EventEmitter): void {
  let buf = '';
  // StringDecoder, not per-chunk toString(): a multibyte UTF-8 char split across two pipe
  // reads would otherwise decode to U+FFFD and corrupt the sub-agent's result text.
  // eslint-disable-next-line @typescript-eslint/no-require-imports
  const { StringDecoder } = require('string_decoder') as typeof import('string_decoder');
  const utf8 = new StringDecoder('utf8');
  stdout.on('data', (d: Buffer) => {
    buf += utf8.write(d);
    let nl: number;
    while ((nl = buf.indexOf('\n')) >= 0) {
      const line = buf.slice(0, nl); buf = buf.slice(nl + 1);
      try {
        if (line.startsWith(SUB_RESULT)) emitter.emit('message', { type: 'success', result: JSON.parse(line.slice(SUB_RESULT.length)).result });
        else if (line.startsWith(SUB_ERROR)) emitter.emit('message', { type: 'error', error: JSON.parse(line.slice(SUB_ERROR.length)).error });
        else if (line.startsWith(SUB_READY)) emitter.emit('message', { type: 'ready' });
        else if (line.startsWith(SUB_EVENT)) { const e = JSON.parse(line.slice(SUB_EVENT.length)); emitter.emit('message', { type: 'tool_event', subtype: e.subtype, call: e.call }); }
        // any other line is stray stdout — ignore it
      } catch { /* malformed sentinel line — ignore */ }
    }
  });
}

export class SubAgentManager {
  private activeWorkers = new Map<string, WorkerHandle>();
  private workerScriptPath: string;
  // Extra Node args for the worker thread. In dev the engine runs from TypeScript source via `tsx`,
  // so the worker must load the tsx hooks to parse the .ts entry — otherwise `new Worker(...ts)`
  // throws "Cannot find module" / can't parse TS. Empty in prod (compiled .js needs no loader).
  private readonly workerExecArgv: string[];
  // True inside a `bun --compile` single binary (the shipped global install). There is no dist/ or
  // node_modules on disk there, so the worker can't be spawned from a filesystem path — it must be
  // the bun-EMBEDDED worker (see worker.target.bun.ts). Node dev/dist keep the compiled-.js path.
  private readonly isBun: boolean = !!(process as any).versions?.bun;
  // Set when a test passes an explicit worker script — that path always wins over bun-embedding.
  private readonly hasScriptOverride: boolean;
  // A sub-agent that hangs (stalled stream, infinite loop) must not block the parent
  // forever. Configurable; defaults to 10 minutes — generous for slow reasoning models.
  private readonly workerTimeoutMs: number;

  // opts is a test seam: production callers use the default worker entrypoint and timeout.
  constructor(opts?: { workerScriptPath?: string; timeoutMs?: number }) {
    // ALWAYS prefer a COMPILED worker entry. A worker thread does not reliably inherit a TypeScript
    // loader (tsx/ts-node) via execArgv across Node versions — passing `--import tsx` to the worker
    // fails to register the ESM hooks, which surfaced as "Cannot find package 'minimatch'" /
    // "Unknown file extension '.ts'" and killed EVERY sub-agent whenever the engine ran from source.
    // A plain .js worker under plain node needs no loader and just works.
    // Candidates: the sibling .js when we're already compiled (dist/core → dist/engine), and the dist
    // copy when running from source (src/core → ../../dist/engine). Fall back to the .ts entry + tsx
    // only if no compiled worker exists at all (pure-source checkout with no build).
    const compiledCandidates = [
      path.resolve(__dirname, '../engine/worker.entry.js'),
      path.resolve(__dirname, '../../dist/engine/worker.entry.js'),
    ];
    const compiledJs = compiledCandidates.find(existsSync);
    const tsPath = path.resolve(__dirname, '../engine/worker.entry.ts');
    this.hasScriptOverride = !!opts?.workerScriptPath;
    if (opts?.workerScriptPath) {
      this.workerScriptPath = opts.workerScriptPath;
      this.workerExecArgv = opts.workerScriptPath.endsWith('.ts') ? ['--import', 'tsx'] : [];
    } else if (compiledJs) {
      this.workerScriptPath = compiledJs;
      this.workerExecArgv = [];
    } else {
      this.workerScriptPath = tsPath;
      this.workerExecArgv = ['--import', 'tsx'];
    }
    this.workerTimeoutMs = opts?.timeoutMs ?? parseInt(process.env.BGW_WORKER_TIMEOUT_MS || '600000', 10);
  }

  // Choose the transport. Node dev/dist → a worker_thread (fast, shared address space). The
  // bun-compiled single binary → a CHILD PROCESS that re-execs the binary itself: worker_threads
  // in a bun --compile executable cannot resolve their dependencies (minimatch et al. aren't
  // bundled into the embedded worker), but a re-exec of the whole binary carries every dependency.
  private createHandle(taskId: string, config: SubAgentConfig, workerOpts: any): WorkerHandle {
    if (this.isBun && !this.hasScriptOverride) {
      if (config.runBudget) throw new Error('Shared run budgets require the desktop worker transport.');
      return this.spawnSubprocessHandle(config, workerOpts);
    }
    // The Bimax app names the engine bundle it started (BIMAX_ENGINE_MODULE). Run the sub-agent as that same
    // bundle in a worker thread, in sub-agent mode. Before this, the app's bundle had no worker.entry.js beside it,
    // so the packaged app fell through to the .ts entry (which cannot load there) and a development run picked up
    // whatever stale dist/engine/worker.entry.js was lying around (record 64, M1).
    const bundle = process.env.BIMAX_ENGINE_MODULE;
    if (bundle && !this.hasScriptOverride && existsSync(bundle)) {
      return this.spawnBundleWorkerHandle(bundle, config, workerOpts);
    }
    return new Worker(this.workerScriptPath, { ...workerOpts, execArgv: this.workerExecArgv });
  }

  /**
   * A sub-agent as a worker thread running the engine bundle itself with BIMAX_SUBAGENT_CONFIG: index.ts takes the
   * sub-agent path, gets the sub-agent's folder as its working folder (worker.folder.ts), and reports over the same
   * stdout sentinels the subprocess path uses — translated by the same code.
   */
  private spawnBundleWorkerHandle(bundle: string, config: SubAgentConfig, workerOpts: any): WorkerHandle {
    // eslint-disable-next-line @typescript-eslint/no-require-imports
    const { EventEmitter } = require('events') as typeof import('events');
    const env = { ...(workerOpts.env || process.env), BIMAX_SUBAGENT_CONFIG: JSON.stringify(config) };
    const worker = new Worker(bundle, {
      env, stdout: true, stderr: false,
      workerData: { bimaxEngineRoot: config.cwd || process.cwd(), runBudget: config.runBudget },
      // Bound the young generation too: Node 24 otherwise adds ~192 MiB beyond the old-generation budget.
    resourceLimits: { maxOldGenerationSizeMb: SUBAGENT_WORKER_HEAP_MB, maxYoungGenerationSizeMb: 16 },
    });
    const emitter = new EventEmitter();
    translateSentinels(worker.stdout, emitter);
    worker.on('error', (e: Error) => emitter.emit('error', e));
    worker.on('exit', (code: number) => emitter.emit('exit', code ?? 0));
    return {
      on: (ev, fn) => { emitter.on(ev, fn); },
      terminate: () => { void worker.terminate().catch(() => undefined); },
    };
  }

  // Re-exec THIS binary with BIMAX_SUBAGENT_CONFIG set; index.ts detects it and runs the sub-agent
  // instead of the engine, streaming results back over stdout sentinels which we translate into the
  // same {type: 'success'|'error'|'tool_event'} messages a worker_thread would post.
  private spawnSubprocessHandle(config: SubAgentConfig, workerOpts: any): WorkerHandle {
    // eslint-disable-next-line @typescript-eslint/no-require-imports
    const { spawn } = require('child_process') as typeof import('child_process');
    // eslint-disable-next-line @typescript-eslint/no-require-imports
    const { EventEmitter } = require('events') as typeof import('events');
    const env = { ...(workerOpts.env || process.env), BIMAX_SUBAGENT_CONFIG: JSON.stringify(config) };
    const child = spawn(process.execPath, [], { env, stdio: ['ignore', 'pipe', 'inherit'] });
    const emitter = new EventEmitter();
    if (child.stdout) translateSentinels(child.stdout, emitter);
    child.on('error', (e: Error) => emitter.emit('error', e));
    child.on('exit', (code: number | null) => emitter.emit('exit', code ?? 0));
    return {
      on: (ev, fn) => { emitter.on(ev, fn); },
      terminate: () => { try { child.kill('SIGKILL'); } catch { /* best-effort */ } },
    };
  }

  // The config each live task was spawned with — the recovery data the checkpoint persists.
  private spawnConfigs = new Map<string, SubAgentConfig>();

  /**
   * Snapshot the blackboard onto the event bus (so the /subagents view + TUI panel stay live)
   * AND checkpoint the agent tree to disk (so a crashed parent's swarm is recoverable).
   */
  private emitBoard(): void {
    try { engineEvents.emit('subagent_update', globalSubAgentBlackboard.all()); } catch { /* best-effort */ }
    try {
      const agents: CheckpointedAgent[] = globalSubAgentBlackboard.all()
        .filter(c => this.spawnConfigs.has(c.taskId))
        .map(c => ({ claim: c, config: this.spawnConfigs.get(c.taskId)! }));
      saveCheckpoint(agents);
    } catch { /* best-effort */ }
  }

  public spawnWorker(taskId: string, config: SubAgentConfig): Promise<SubAgentResultEnvelope> {
    return new Promise((resolve, reject) => {
      Logger.info(`[SubAgentManager] Spawning worker for task ${taskId} (Agent: ${config.agentType})`);

      // WS2.1 — lifecycle instrumentation. All timestamps are parent-side (message arrival),
      // so the journal adds zero overhead inside the worker. t0 is taken BEFORE worktree
      // creation so isolation cost lands in msToFirstEvent, where it belongs.
      const t0 = Date.now();
      let sawFirstEvent = false;
      let toolCallCount = 0;
      const journalFirstEvent = () => {
        if (sawFirstEvent) return;
        sawFirstEvent = true;
        journalSubagent({ taskId, phase: 'first_event', ms: Date.now() - t0 });
      };
      const journalSettled = (outcome: 'done' | 'failed' | 'timeout') =>
        journalSubagent({ taskId, phase: 'settled', outcome, ms: Date.now() - t0, toolCalls: toolCallCount });

      // Worktree isolation: give the agent its own checkout + branch BEFORE the config is frozen
      // into workerData. Creation failing (not a git repo, git missing) falls back to running
      // unisolated — the pre-worktree behavior — never a spawn failure. A floored episode is
      // re-floored to the worktree so the OS sandbox confines it to its own copy.
      const capacityRootCwd = config.recoveryWorktree?.repoRoot || config.cwd;
      let worktree: WorktreeInfo | null = null;
      if (config.isolation === 'worktree') {
        if (config.recoveryWorktree) {
          if (!validateWorktree(config.recoveryWorktree)) {
            reject(new Error(`Checkpointed worktree for ${taskId} is missing or no longer matches its recorded branch; refusing to discard interrupted work.`));
            return;
          }
          worktree = config.recoveryWorktree;
          config = {
            ...config,
            cwd: worktree.path,
            ...(config.sandboxFloorRoot ? { sandboxFloorRoot: worktree.path } : {}),
          };
        } else {
          worktree = createWorktree(config.cwd, taskId);
        }
        if (!worktree && config.isolationRequired) {
          reject(new Error(`Required worktree isolation could not be created for ${taskId}.`));
          return;
        }
        if (worktree) {
          config = {
            ...config,
            cwd: worktree.path,
            recoveryWorktree: worktree,
            ...(config.sandboxFloorRoot ? { sandboxFloorRoot: worktree.path } : {}),
          };
        }
      }
      const capacityContext = resolveCapacityContext(capacityRootCwd, config.capacityPath, config.capacityRunId);
      const capacity = new SubAgentCapacityCoordinator(capacityContext.path);
      let capacityLease: SubAgentCapacityLease;
      try {
        capacityLease = capacity.acquire({
          taskId,
          runId: capacityContext.runId,
          parentLeaseId: config.capacityParentLeaseId,
        });
        config = {
          ...config,
          capacityPath: capacityContext.path,
          capacityRunId: capacityContext.runId,
          capacityLeaseId: capacityLease.id,
        };
      } catch (error: any) {
        const note = worktree ? settleWorktree(worktree).note : '';
        reject(new Error(`${error?.message || String(error)}${note ? `\n\n${note}` : ''}`));
        return;
      }
      let capacityReleased = false;
      const heartbeat = setInterval(() => {
        try { capacity.heartbeat(capacityLease.id); } catch { /* expiry remains the crash fallback */ }
      }, 10_000);
      heartbeat.unref?.();
      const releaseCapacity = () => {
        if (capacityReleased) return;
        capacityReleased = true;
        clearInterval(heartbeat);
        try { capacity.release(capacityLease.id); } catch { /* TTL reclaims it */ }
      };
      // Settle exactly once on whichever completion path fires first: remove the worktree when
      // the agent changed nothing, keep + describe it when it made edits/commits.
      const settleIsolation = (): string => {
        if (!worktree) return '';
        const info = worktree;
        worktree = null;
        try { return settleWorktree(info).note; } catch { return ''; }
      };
      const outsideOwnedScope = (changed: string[]): string[] => {
        if (!config.outcomeTaskId || changed.length === 0) return [];
        const owned = (config.scope || '').split(/[\s,;]+/)
          .map(value => value.trim().replace(/^\.\//, '').replace(/\/+$/, ''))
          .filter(Boolean);
        if (owned.length === 0) return changed;
        return changed.filter(file => !owned.some(scope => file === scope || file.startsWith(`${scope}/`)));
      };

      globalSubAgentBlackboard.register(taskId, config.agentType, config.scope || '', config.prompt, config.outcomeTaskId);
      this.spawnConfigs.set(taskId, config);
      this.emitBoard();

      journalSubagent({
        taskId, phase: 'spawned', agentType: config.agentType,
        ...(config.model ? { model: config.model } : {}),
        ...(config.depth ? { depth: config.depth } : {}),
        ...(config.isolation ? { isolation: config.isolation } : {}),
      });

      // Sub-agent lifetime span (OTel GenAI invoke_agent). end() is idempotent, so the
      // timeout / error / exit paths can all settle it without coordination.
      const span = getTracer().startSpan(`invoke_agent ${config.agentType}`, {
        'gen_ai.operation.name': 'invoke_agent',
        'gen_ai.agent.name': config.agentType,
        'bimax.subagent.task_id': taskId,
        ...(config.scope ? { 'bimax.subagent.scope': config.scope } : {}),
      });

      config.runBudget = activeRunBudget();
      const workerOpts = {
        workerData: config,
        // Floored episodes get their own env copy with the floor flag — thread-scoped, so the
        // parent session and sibling workers are unaffected.
        ...(config.sandboxFloorRoot
          ? { env: { ...process.env, [FLOOR_ENV]: config.sandboxFloorRoot } }
          : {}),
      };
      let worker: WorkerHandle;
      try {
        worker = this.createHandle(taskId, config, workerOpts);
      } catch (error) {
        globalSubAgentBlackboard.markFailed(taskId, error instanceof Error ? error.message : String(error));
        this.spawnConfigs.delete(taskId);
        this.emitBoard();
        settleIsolation();
        releaseCapacity();
        reject(error);
        return;
      }

      this.activeWorkers.set(taskId, worker);

      // Watchdog: terminate and reject if the worker produces no result in time. Cleared
      // the moment the promise settles so a healthy worker never trips it.
      let settled = false;
      const timer = setTimeout(() => {
        if (settled) return;
        settled = true;
        Logger.error(`[SubAgentManager] Worker for task ${taskId} timed out after ${this.workerTimeoutMs}ms. Terminating.`);
        this.activeWorkers.delete(taskId);
        Promise.resolve(worker.terminate()).catch(() => { /* TTL reclaims the lease */ }).finally(releaseCapacity);
        // Settle the board too — a timed-out agent must not linger as 'running' (it would show
        // forever in /subagents AND look crash-recoverable to the checkpoint).
        globalSubAgentBlackboard.markFailed(taskId, `timed out after ${this.workerTimeoutMs}ms`);
        this.spawnConfigs.delete(taskId);
        this.emitBoard();
        span.end('error', `timed out after ${this.workerTimeoutMs}ms`);
        journalSettled('timeout');
        const note = settleIsolation();
        if (note) Logger.warn(`[SubAgentManager] ${taskId} timed out but left changes: ${note}`);
        reject(new Error(`Worker for task ${taskId} timed out after ${this.workerTimeoutMs}ms`));
      }, this.workerTimeoutMs);

      const finalize = (fn: () => void) => {
        if (settled) return;
        settled = true;
        clearTimeout(timer);
        this.activeWorkers.delete(taskId);
        releaseCapacity();
        fn();
      };

      worker.on('message', (message) => {
        // Post-settlement guard: after a timeout (or any earlier terminal event) a late
        // success/error message must NOT re-write the board — it would flip a timed-out agent to
        // "done" or overwrite the real failure reason and fire a spurious board refresh.
        if (settled && (message.type === 'success' || message.type === 'error')) return;
        // 'ready' = boot finished, about to make the first llm call. It's OUR overhead and precedes
        // any real work, so record it as its own phase and do NOT let it consume first_event.
        if (message.type === 'ready') {
          if (!settled) {
            // The worker now owns lease renewal. Stopping the parent heartbeat is important for
            // subprocesses: otherwise parent/child PIDs would race in the shared lease record.
            clearInterval(heartbeat);
            globalSubAgentBlackboard.setPhase(taskId, 'working');
            this.emitBoard();
            journalSubagent({ taskId, phase: 'ready', ms: Date.now() - t0 });
          }
          return;
        }
        journalFirstEvent(); // first substantive message — log, tool event, or immediate result
        if (message.type === 'success') {
          let changed: string[];
          try {
            changed = worktree
              ? (config.outcomeTaskId ? inspectWorktreeChanges(worktree) : worktreeChangedPaths(worktree))
              : [];
          } catch (error: any) {
            const detail = `Could not inspect coordinated worktree changes: ${error?.message || error}`;
            globalSubAgentBlackboard.markFailed(taskId, detail);
            this.spawnConfigs.delete(taskId);
            this.emitBoard();
            span.end('error', detail);
            journalSettled('failed');
            const note = settleIsolation();
            finalize(() => reject(new Error(`${detail}${note ? `\n\n${note}` : ''}`)));
            return;
          }
          const outside = outsideOwnedScope(changed);
          if (outside.length > 0) {
            const error = `Assignment changed files outside owned scope ${config.scope}: ${outside.join(', ')}`;
            globalSubAgentBlackboard.markFailed(taskId, error);
            this.spawnConfigs.delete(taskId);
            this.emitBoard();
            span.end('error', error);
            journalSettled('failed');
            const note = settleIsolation();
            finalize(() => reject(new Error(`${error}${note ? `\n\n${note}` : ''}`)));
            return;
          }
          const rawResult = typeof message.result === 'string' ? message.result : JSON.stringify(message.result);
          const result: SubAgentResultEnvelope = {
            version: 1,
            taskId,
            outcomeTaskId: config.outcomeTaskId,
            agentType: config.agentType,
            report: rawResult,
            claimedScope: config.scope || '',
            observedChangedFiles: changed,
            startedAt: t0,
            endedAt: Date.now(),
            toolCalls: toolCallCount,
            ...(worktree && changed.length ? {
              isolation: {
                kind: 'worktree' as const,
                repoRoot: worktree.repoRoot,
                path: worktree.path,
                branch: worktree.branch,
                baseCommit: worktree.baseCommit,
                state: 'pending_integration' as const,
              },
            } : {}),
          };
          globalSubAgentBlackboard.markDone(taskId, formatSubAgentResult(result));
          this.spawnConfigs.delete(taskId); // settled — no longer crash-recoverable
          this.emitBoard();
          span.end('ok');
          journalSettled('done');
          const note = settleIsolation();
          if (note) Logger.info(`[SubAgentManager] ${taskId}: ${note}`);
          finalize(() => resolve(result));
        } else if (message.type === 'error') {
          globalSubAgentBlackboard.markFailed(taskId, String(message.error));
          this.spawnConfigs.delete(taskId);
          this.emitBoard();
          span.end('error', String(message.error));
          journalSettled('failed');
          const note = settleIsolation();
          if (note) Logger.warn(`[SubAgentManager] ${taskId} failed but left changes: ${note}`);
          finalize(() => reject(new Error(message.error)));
        } else if (message.type === 'log') {
          Logger.info(`[Worker ${taskId}] ${message.content}`);
        } else if (message.type === 'tool_event' && message.call) {
          // T3 — re-emit a sub-agent's tool activity on the main event bus, tagged so the UI nests
          // it under this spawn. Tag-and-forward only; never settles the spawn promise.
          globalSubAgentBlackboard.incTool(taskId);
          if (message.subtype === 'tool_call') {
            const tool = String(message.call.toolName || '').toLowerCase();
            const input = String(message.call.input || '').toLowerCase();
            const phase = /test|jest|vitest|pytest|cargo test|go test|typecheck|lint/.test(`${tool} ${input}`)
              ? 'testing'
              : /edit|write|delete|multiedit|symboledit/.test(tool)
                ? 'editing'
                : /search|grep|glob|read|graph|web|scout/.test(tool)
                  ? 'researching'
                  : 'working';
            globalSubAgentBlackboard.setPhase(taskId, phase);
            this.emitBoard(); // one board refresh per new call, not per result
            toolCallCount++;
            journalSubagent({ taskId, phase: 'tool_call', tool: message.call.toolName, ms: Date.now() - t0 });
          }
          const call = { ...message.call, parentId: taskId, agentLabel: config.agentType };
          engineEvents.emit(message.subtype === 'tool_call_result' ? 'tool_call_result' : 'tool_call', call);
        }
      });

      worker.on('error', (err) => {
        if (settled) return; // already resolved/rejected/timed-out — don't clobber the outcome
        globalSubAgentBlackboard.markFailed(taskId, err?.message || String(err));
        this.spawnConfigs.delete(taskId);
        this.emitBoard();
        span.end('error', err?.message || String(err));
        settleIsolation();
        finalize(() => reject(err));
      });

      worker.on('exit', (code) => {
        // A terminate()-driven exit follows every timeout/error/success settle. Bail so it can't
        // overwrite the recorded reason ("timed out after Nms" → "exited with code 1") or double-emit.
        if (settled) return;
        if (code !== 0) {
          span.end('error', `exit code ${code}`);
          settleIsolation();
          // A worker that died without posting an error would otherwise stay 'running' on the
          // board — settle it so the panel and the crash checkpoint both see the truth.
          globalSubAgentBlackboard.markFailed(taskId, `worker exited with code ${code}`);
          this.spawnConfigs.delete(taskId);
          this.emitBoard();
          finalize(() => reject(new Error(`Worker stopped with exit code ${code}`)));
        } else {
          span.end('ok');
          const note = settleIsolation();
          this.spawnConfigs.delete(taskId);
          // Worker exited cleanly but never posted a 'success' message — settle the
          // promise so the caller is never left hanging. No-op if already settled.
          const result: SubAgentResultEnvelope = {
            version: 1, taskId, outcomeTaskId: config.outcomeTaskId, agentType: config.agentType,
            report: `Worker exited cleanly with no explicit result.${note ? ` ${note}` : ''}`,
            claimedScope: config.scope || '', observedChangedFiles: [], startedAt: t0,
            endedAt: Date.now(), toolCalls: toolCallCount,
          };
          finalize(() => resolve(result));
        }
      });
    });
  }

  public activeCount(): number {
    return this.activeWorkers.size;
  }

  public killWorker(taskId: string): void {
    const worker = this.activeWorkers.get(taskId);
    if (worker) {
      worker.terminate();
      this.activeWorkers.delete(taskId);
      Logger.warn(`[SubAgentManager] Terminated worker for task ${taskId}`);
    }
  }

  public killAll(): void {
    for (const [taskId, worker] of this.activeWorkers) {
      worker.terminate();
      Logger.warn(`[SubAgentManager] Terminated worker for task ${taskId}`);
    }
    this.activeWorkers.clear();
  }
}

export const globalSubAgentManager = new SubAgentManager();

import { engineEvents } from '../engine/events';
import { getExecutionLedger, TaskState, TERMINAL_STATES } from './execution.ledger';

// ─── Task registry: the live half of task workspaces ────────────────────────────────────────────
// The execution ledger is the durable record; this registry is the in-memory truth for tasks in
// THIS process — long shell commands, browser sessions, builds — with a validated state machine,
// honest capability flags (pause/resume only where the underlying process supports it — a shell
// child takes SIGSTOP/SIGCONT; a model stream does not), bounded output storage, and actions
// (cancel/pause/resume/pin/close). Every transition is appended to the ledger, which is what makes
// tasks reconstructible after a crash. Model: docs/TASK_WORKSPACES.md (panels + chips — the
// conversation stays primary; tasks get a focusable panel, not stolen tabs).

export type TaskKind = 'shell' | 'browser' | 'subagent' | 'build' | 'test' | 'generic';

export interface TaskCapabilities {
  cancel: boolean;
  pause: boolean;   // true ONLY when a real suspend exists (SIGSTOP) — never faked
  resume: boolean;
}

export interface TaskHandle {
  /** Kill/abort the underlying work. Must be idempotent. */
  cancel?: () => void;
  /** Real suspension (e.g. SIGSTOP). Only set when genuinely supported. */
  pause?: () => void;
  resume?: () => void;
}

export interface WorkspaceTask {
  id: string;
  kind: TaskKind;
  title: string;
  state: TaskState;
  createdAt: number;
  startedAt?: number;
  endedAt?: number;
  model?: string;
  activeTool?: string;
  lastEvent?: string;      // last meaningful event, human-readable, short
  progress?: number;       // 0..1 where measurable; undefined otherwise
  attention: boolean;      // needs the user's eyes (failed, waiting-user, finished long task)
  retries: number;
  pinned: boolean;
  command?: string;        // shell tasks: what re-running means
  cwd?: string;
  exitCode?: number;
  failure?: string;        // short failure summary
  supports: TaskCapabilities;
}

// Legal state transitions. Anything not listed is a programming error — surfaced loudly in tests,
// tolerated (ignored + logged) at runtime so a bad caller can't wedge the registry.
const LEGAL: Record<TaskState, TaskState[]> = {
  'queued':           ['starting', 'cancelled'],
  'starting':         ['running', 'streaming', 'waiting-model', 'waiting-tool', 'waiting-browser', 'failed', 'failed-resumable', 'cancelling', 'cancelled'],
  'running':          ['streaming', 'waiting-model', 'waiting-tool', 'waiting-browser', 'waiting-user', 'retrying', 'recovering', 'paused', 'cancelling', 'completed', 'failed', 'failed-resumable'],
  'streaming':        ['running', 'waiting-model', 'waiting-tool', 'paused', 'completed', 'failed', 'failed-resumable', 'cancelling'],
  'waiting-model':    ['running', 'streaming', 'retrying', 'cancelling', 'failed', 'failed-resumable'],
  'waiting-tool':     ['running', 'retrying', 'cancelling', 'failed', 'failed-resumable'],
  'waiting-browser':  ['running', 'recovering', 'retrying', 'cancelling', 'failed', 'failed-resumable'],
  'waiting-user':     ['running', 'cancelling', 'cancelled'],
  'retrying':         ['running', 'starting', 'failed', 'failed-resumable', 'cancelling'],
  'recovering':       ['running', 'starting', 'failed', 'failed-resumable', 'cancelling'],
  'paused':           ['running', 'cancelling', 'cancelled', 'completed', 'failed', 'failed-resumable'],
  'cancelling':       ['cancelled', 'failed'],
  'cancelled':        [],
  'completed':        [],
  'failed':           [],
  'failed-resumable': ['retrying', 'starting'],
};

let seq = 0;

export class TaskRegistry {
  private tasks = new Map<string, WorkspaceTask>();
  private handles = new Map<string, TaskHandle>();
  private outputs = new Map<string, string[]>(); // bounded ring buffers (OUTPUT_MAX_LINES)
  private streamTails = new Map<string, string>(); // channel of the unfinished last line
  private listeners = new Set<() => void>();

  /** Subscribe to lifecycle changes; the disposer belongs to the pending waiter. */
  onChange(listener: () => void): () => void {
    this.listeners.add(listener);
    return () => { this.listeners.delete(listener); };
  }

  static readonly OUTPUT_MAX_LINES = 400;

  create(opts: {
    kind: TaskKind; title: string; command?: string; cwd?: string; model?: string;
    handle?: TaskHandle; supports?: Partial<TaskCapabilities>;
  }): WorkspaceTask {
    const id = `tk-${Date.now().toString(36)}-${++seq}`;
    const task: WorkspaceTask = {
      id, kind: opts.kind, title: opts.title.slice(0, 80), state: 'queued',
      createdAt: Date.now(), retries: 0, attention: false, pinned: false,
      command: opts.command, cwd: opts.cwd, model: opts.model,
      supports: {
        cancel: opts.supports?.cancel ?? !!opts.handle?.cancel,
        pause: opts.supports?.pause ?? !!opts.handle?.pause,
        resume: opts.supports?.resume ?? !!opts.handle?.resume,
      },
    };
    this.tasks.set(id, task);
    if (opts.handle) this.handles.set(id, opts.handle);
    getExecutionLedger().append({
      taskId: id, type: 'created', kind: opts.kind, title: task.title,
      command: opts.command, cwd: opts.cwd, model: opts.model,
    });
    this.changed();
    return task;
  }

  get(id: string): WorkspaceTask | undefined { return this.tasks.get(id); }
  /** Match a task by id or unambiguous prefix (CLI ergonomics). */
  find(idOrPrefix: string): WorkspaceTask | undefined {
    if (this.tasks.has(idOrPrefix)) return this.tasks.get(idOrPrefix);
    const matches = [...this.tasks.values()].filter(t => t.id.startsWith(idOrPrefix));
    return matches.length === 1 ? matches[0] : undefined;
  }
  list(): WorkspaceTask[] {
    return [...this.tasks.values()].sort((a, b) =>
      Number(b.pinned) - Number(a.pinned) || b.createdAt - a.createdAt);
  }
  live(): WorkspaceTask[] { return this.list().filter(t => !TERMINAL_STATES.has(t.state)); }

  transition(id: string, to: TaskState, reason?: string): boolean {
    const t = this.tasks.get(id);
    if (!t) return false;
    if (!LEGAL[t.state]?.includes(to)) {
      console.warn(`[Tasks] illegal transition ${t.state} → ${to} for ${id} (ignored)`);
      return false;
    }
    t.state = to;
    if (to === 'running' && !t.startedAt) t.startedAt = Date.now();
    if (TERMINAL_STATES.has(to)) {
      t.endedAt = Date.now();
      this.handles.delete(id); // the underlying work is gone; never hold a dead handle
    }
    if (to === 'failed' || to === 'failed-resumable') { t.failure = reason?.slice(0, 200); t.attention = true; }
    if (to === 'waiting-user') t.attention = true;
    if (to === 'completed') t.attention = (Date.now() - t.createdAt) > 30_000; // long tasks announce completion
    if (reason) t.lastEvent = reason.slice(0, 120);
    getExecutionLedger().append({ taskId: id, type: 'transition', state: to, reason });
    this.changed();
    return true;
  }

  /** Record activity without a state change (active tool, progress, last event). */
  touch(id: string, patch: { activeTool?: string; lastEvent?: string; progress?: number; model?: string }): void {
    const t = this.tasks.get(id);
    if (!t) return;
    if (patch.activeTool !== undefined) t.activeTool = patch.activeTool;
    if (patch.lastEvent !== undefined) t.lastEvent = patch.lastEvent.slice(0, 120);
    if (patch.progress !== undefined) t.progress = Math.max(0, Math.min(1, patch.progress));
    if (patch.model !== undefined) t.model = patch.model;
    this.changed();
  }

  checkpoint(id: string, data: Record<string, unknown>): void {
    getExecutionLedger().append({ taskId: id, type: 'checkpoint', data });
  }

  retry(id: string, fingerprint?: string): void {
    const t = this.tasks.get(id);
    if (!t) return;
    t.retries++;
    getExecutionLedger().append({ taskId: id, type: 'retry', attempt: t.retries, fingerprint });
    this.changed();
  }

  appendOutput(id: string, chunk: string): void {
    this.streamTails.delete(id);
    let buf = this.outputs.get(id);
    if (!buf) { buf = []; this.outputs.set(id, buf); }
    for (const line of chunk.split('\n')) {
      buf.push(line.length > 500 ? line.slice(0, 500) + '…' : line);
    }
    // Bounded storage: keep the newest OUTPUT_MAX_LINES lines (virtualized tail, not the world).
    if (buf.length > TaskRegistry.OUTPUT_MAX_LINES) buf.splice(0, buf.length - TaskRegistry.OUTPUT_MAX_LINES);
  }
  /** Pipe chunks are not lines. Join only consecutive chunks from the same output channel. */
  appendStreamOutput(id: string, chunk: string, channel: string): void {
    if (!chunk) return;
    let buf = this.outputs.get(id);
    if (!buf) { buf = []; this.outputs.set(id, buf); }
    let start = 0;
    let continues = this.streamTails.get(id) === channel;
    while (start < chunk.length) {
      const newline = chunk.indexOf('\n', start);
      const end = newline === -1 ? chunk.length : newline;
      const previous = continues ? buf.pop() || '' : '';
      const available = Math.max(0, 500 - previous.length);
      const text = previous + chunk.slice(start, Math.min(end, start + available));
      buf.push(previous.length > 500 || end - start > available ? text.slice(0, 500) + '…' : text);
      if (buf.length > TaskRegistry.OUTPUT_MAX_LINES) buf.shift();
      continues = false;
      start = end + 1;
    }
    if (chunk.endsWith('\n')) this.streamTails.delete(id);
    else this.streamTails.set(id, channel);
  }
  output(id: string, lastN = 40): string {
    const buf = this.outputs.get(id) || [];
    return buf.slice(-lastN).join('\n');
  }

  // ── Actions — each returns a short human-readable result (surfaced by /tasks) ──
  cancel(id: string): string {
    const t = this.find(id);
    if (!t) return `No task ${id}.`;
    if (TERMINAL_STATES.has(t.state)) return `${t.title} already ${t.state}.`;
    if (!this.transition(t.id, 'cancelling', 'cancel requested')) return `Cannot cancel from ${t.state}.`;
    try { this.handles.get(t.id)?.cancel?.(); } catch { /* dying anyway */ }
    return `Cancelling ${t.title}.`;
  }

  pause(id: string): string {
    const t = this.find(id);
    if (!t) return `No task ${id}.`;
    // HONEST pause: refuse (with the reason) for work that cannot actually suspend.
    if (!t.supports.pause) return `${t.title} can't pause — ${t.kind === 'shell' ? 'its process handle is gone' : `a ${t.kind} task has no real suspend`}. Cancel is available.`;
    if (t.state !== 'running' && t.state !== 'streaming') return `Can only pause a running task (currently ${t.state}).`;
    try { this.handles.get(t.id)?.pause?.(); } catch (e: any) { return `Pause failed: ${e?.message}`; }
    this.transition(t.id, 'paused', 'paused (SIGSTOP)');
    return `Paused ${t.title} (real suspend — resume with /tasks resume ${t.id}).`;
  }

  resume(id: string): string {
    const t = this.find(id);
    if (!t) return `No task ${id}.`;
    if (t.state !== 'paused') return `${t.title} is ${t.state}, not paused.`;
    try { this.handles.get(t.id)?.resume?.(); } catch (e: any) { return `Resume failed: ${e?.message}`; }
    this.transition(t.id, 'running', 'resumed (SIGCONT)');
    return `Resumed ${t.title}.`;
  }

  pin(id: string): string {
    const t = this.find(id);
    if (!t) return `No task ${id}.`;
    t.pinned = !t.pinned;
    this.changed();
    return `${t.pinned ? 'Pinned' : 'Unpinned'} ${t.title}.`;
  }

  /** Close (remove from the strip) — terminal tasks only; live work must be cancelled first. */
  close(id: string): string {
    const t = this.find(id);
    if (!t) return `No task ${id}.`;
    if (!TERMINAL_STATES.has(t.state)) return `${t.title} is still ${t.state} — cancel it first.`;
    this.tasks.delete(t.id);
    this.outputs.delete(t.id);
    this.streamTails.delete(t.id);
    this.changed();
    return `Closed ${t.title}.`;
  }

  /** Clear attention (the user looked at it). */
  seen(id: string): void {
    const t = this.tasks.get(id);
    if (t) { t.attention = false; this.changed(); }
  }

  private changed(): void {
    for (const listener of this.listeners) {
      try { listener(); } catch { /* observers cannot break task lifecycle */ }
    }
    try { engineEvents.emit('tasks_changed'); } catch { /* wiring optional in tests */ }
  }
}

let registry: TaskRegistry | null = null;
export function getTaskRegistry(): TaskRegistry {
  if (!registry) registry = new TaskRegistry();
  return registry;
}
export function __resetTaskRegistryForTests(): TaskRegistry {
  registry = new TaskRegistry();
  return registry;
}

/**
 * Recovery for tool calls a model emits as plain text instead of through the
 * function-calling API. Some OpenAI-compatible models (notably minimax on NVIDIA)
 * intermittently answer with `{"name":"BashTool","parameters":{...}}` written into
 * the content channel. Left alone, that JSON leaks to the user and the tool never
 * runs — so the agent loop uses this to recover the call and execute it through the
 * normal, governor-gated path.
 *
 * Safety: a JSON blob is only treated as a call when its `name` matches a REAL
 * registered tool (checked via the `isRegisteredTool` predicate). Arbitrary JSON a
 * user asked the model to produce will not name a live tool, so it is never matched
 * and never executed.
 */

/** A tool call recovered from text, shaped like the native streaming tool_call. */
export interface ParsedToolCall {
  id: string;
  name: string;
  /** Arguments as a JSON string, matching the native function-calling path. */
  args: string;
}

/** The one tool an operation turn already requires, used to recover a NAMELESS argument object. */
export interface DefaultToolCandidate {
  name: string;
  /** JSON Schema of that tool's arguments; only `properties` and `required` are consulted. */
  schema: unknown;
}

export interface TextToolCallOptions {
  /**
   * When the loop has already required one specific tool for this turn, a bare argument object with
   * no `name` is still an unambiguous invocation of it. Supplying the tool here enables that
   * recovery; omitting it keeps the strict name-gated behaviour.
   */
  defaultTool?: DefaultToolCandidate;
}

export interface TextToolCallExtraction {
  toolCalls: ParsedToolCall[];
  /** The content with every recognized tool-call JSON blob removed. */
  cleanedText: string;
}

/** Index of the `}` that closes the `{` at `start`, respecting strings/escapes; -1 if unbalanced. */
function matchBalancedObject(s: string, start: number): number {
  let depth = 0, inStr = false, esc = false;
  for (let i = start; i < s.length; i++) {
    const c = s[i];
    if (inStr) {
      if (esc) esc = false;
      else if (c === '\\') esc = true;
      else if (c === '"') inStr = false;
    } else if (c === '"') inStr = true;
    else if (c === '{') depth++;
    else if (c === '}' && --depth === 0) return i;
  }
  return -1;
}

/** Parse a candidate object into a tool call if it has a registered name; else null. */
/**
 * A tool name without the harmony tokens gpt-oss sometimes glues to it (backlog Q1): `AskUserTool<|channel|>commentary`
 * and `functions.AskUserTool` both name AskUserTool. Left in, the fuzzy registry lookup could still run the tool, but the
 * garbled name went back to the model in its own history and showed in the thread.
 */
export function cleanToolName(name: string): string {
  return name.replace(/<\|[^|>]*\|>[\s\S]*$/, '').replace(/^functions\./, '').trim();
}

function asToolCall(candidate: string, isRegisteredTool: (name: string) => boolean): { name: string; args: string } | null {
  let obj: any;
  try {
    obj = JSON.parse(candidate);
  } catch {
    return null;
  }
  if (!obj || typeof obj !== 'object' || Array.isArray(obj)) return null;

  // Accept the common shapes: {name, parameters|arguments|input} and {function:{name, arguments}}.
  const raw = obj.name ?? obj.tool ?? obj.function?.name;
  const name = typeof raw === 'string' ? cleanToolName(raw) : raw;
  if (typeof name !== 'string' || !isRegisteredTool(name)) return null;

  const rawArgs = obj.parameters ?? obj.arguments ?? obj.input ?? obj.function?.arguments ?? {};
  let args: string;
  if (typeof rawArgs === 'string') {
    args = rawArgs; // already a JSON string (some models nest a stringified payload)
  } else {
    try { args = JSON.stringify(rawArgs); } catch { args = '{}'; }
  }
  return { name, args };
}

/** Everything that wraps a tool-call payload without being part of it. */
function unwrapToolCallPayload(content: string): string {
  return content
    .replace(/<\/?tool_call>/gi, '')
    .replace(/```(?:json|tool_code)?/gi, '```')
    .replace(/```/g, '')
    .trim();
}

/**
 * A nameless argument object, recovered ONLY against the tool this turn already requires.
 *
 * The observed failure: on a required-tool turn the model stops emitting a name and writes
 * just `{"action":"click","query":"mom","frameId":"…"}` into the content channel. That is a
 * complete, unambiguous invocation of the one tool the turn is about, but the name-gated path
 * cannot see it, so the operation silently ends one action short of sending the message.
 *
 * Kept safe by shape, not by trust: the payload must be the WHOLE message (bar fences/wrappers) —
 * never a JSON example embedded in prose — every key must exist in that tool's schema, and every
 * required key must be present. Arbitrary JSON a user asked the model to produce does not satisfy
 * a real tool's schema, and outside a required-tool turn this path never runs at all.
 */
function asDefaultToolCall(content: string, defaultTool: DefaultToolCandidate): ParsedToolCall | null {
  const payload = unwrapToolCallPayload(content);
  if (!payload.startsWith('{') || matchBalancedObject(payload, 0) !== payload.length - 1) return null;

  let value: any;
  try { value = JSON.parse(payload); } catch { return null; }
  if (!value || typeof value !== 'object' || Array.isArray(value)) return null;
  // A named object is the strict path's business; never let this one re-interpret a rejected name.
  if (value.name != null || value.tool != null || value.function != null) return null;

  const schema = defaultTool.schema as { properties?: Record<string, unknown>; required?: unknown } | undefined;
  const properties = schema?.properties;
  if (!properties || typeof properties !== 'object') return null;
  const keys = Object.keys(value);
  if (keys.length === 0 || !keys.every(key => Object.prototype.hasOwnProperty.call(properties, key))) return null;
  const required = Array.isArray(schema?.required) ? schema!.required as string[] : [];
  if (!required.every(key => value[key] !== undefined)) return null;

  return {
    id: `text-call-default-${Date.now()}`,
    name: defaultTool.name,
    args: JSON.stringify(value),
  };
}

/**
 * Scan `content` for tool calls written as JSON text and return them alongside the
 * content with those blobs stripped out. Only blobs naming a registered tool match,
 * unless `options.defaultTool` supplies the tool this turn already requires.
 */
export function extractTextToolCalls(
  content: string,
  isRegisteredTool: (name: string) => boolean,
  options?: TextToolCallOptions
): TextToolCallExtraction {
  const toolCalls: ParsedToolCall[] = [];
  const removals: Array<[number, number]> = [];

  for (let i = 0; i < content.length; i++) {
    if (content[i] !== '{') continue;
    const end = matchBalancedObject(content, i);
    // ponytail: this `{` never closes (a truncated snippet, a bare `${`), but a real tool-call
    // object can still appear later — keep scanning instead of giving up. O(n²) worst case is fine
    // on turn-sized content; revisit if calls are ever parsed over megabytes.
    if (end === -1) continue;
    const call = asToolCall(content.slice(i, end + 1), isRegisteredTool);
    if (call) {
      toolCalls.push({ id: `text-call-${toolCalls.length}-${Date.now()}`, name: call.name, args: call.args });
      removals.push([i, end + 1]);
      i = end; // skip past this object
    }
  }

  if (toolCalls.length === 0 && options?.defaultTool) {
    const recovered = asDefaultToolCall(content, options.defaultTool);
    // The whole message WAS the call, so nothing user-facing survives it.
    if (recovered) return { toolCalls: [recovered], cleanedText: '' };
  }

  let cleanedText = content;
  if (removals.length > 0) {
    let out = '';
    let last = 0;
    for (const [a, b] of removals) { out += content.slice(last, a); last = b; }
    out += content.slice(last);
    cleanedText = out.replace(/<\/?tool_call>/gi, '').replace(/\n{3,}/g, '\n\n').trim();
  }

  return { toolCalls, cleanedText };
}

import * as crypto from 'crypto';

/**
 * The tool list as a PROVIDER will accept it.
 *
 * THE DEFECT THIS CLOSES. Tool names and input schemas went to the provider exactly as registered,
 * and an MCP server decides both. OpenAI and Anthropic reject a whole request when one function
 * name falls outside `^[a-zA-Z0-9_-]{1,64}$` (Gemini is similar), and MCP names routinely do: a
 * server called `github.com` or `my server`, a tool called `files.read`, or simply a long server
 * name plus a long tool name inside `mcp__<server>__<tool>`. Because MCP tools are deferred, the
 * failure arrived one turn AFTER the model discovered the tool — and from then on every request in
 * the session was refused, not just calls to that tool. Schemas had the same shape of problem:
 * `$schema`/`$ref`/`$defs`, a root without `type: "object"`, `type: ["string", "null"]`, all of
 * which some providers refuse outright.
 *
 * WHAT IT DOES. Maps every name to a provider-safe wire name (unchanged when already valid, so
 * every built-in tool and every well-named MCP tool keeps its exact name), and maps the model's
 * calls back. Normalizes every schema to the portable subset, with a stricter pass for Gemini.
 * Nothing about what a tool does, or which tools the model sees, changes here.
 */

/** OpenAI's documented function-name rule; Anthropic's allows 128, so 64 satisfies both. */
const VALID_NAME = /^[a-zA-Z0-9_-]{1,64}$/;
export const WIRE_NAME_MAX = 64;

/**
 * The most tools one request may carry. OpenAI refuses more than 128; the others accept at least
 * that many. A registry this large is rare (deferred MCP tools only join once discovered), so the
 * cap drops the tail rather than failing every turn.
 */
export const MAX_TOOLS_PER_REQUEST = 128;

function shortHash(text: string): string {
  return crypto.createHash('sha256').update(text).digest('hex').slice(0, 8);
}

/** A provider-safe spelling of `name`. Stable: the same input always gives the same output. */
export function wireToolName(name: string): string {
  if (VALID_NAME.test(name)) return name;
  const cleaned = String(name || '').replace(/[^a-zA-Z0-9_-]+/g, '_').replace(/^_+|_+$/g, '') || 'tool';
  if (cleaned.length <= WIRE_NAME_MAX && cleaned !== name) {
    // Cleaning can merge two names ("a.b" and "a_b"); the hash suffix below keeps them apart
    // only when needed — see ToolNameMap.
    return cleaned;
  }
  const suffix = `_${shortHash(name)}`;
  return `${cleaned.slice(0, WIRE_NAME_MAX - suffix.length)}${suffix}`;
}

/** The two-way mapping for one request's tool list. */
export class ToolNameMap {
  private readonly toWireMap = new Map<string, string>();
  private readonly fromWireMap = new Map<string, string>();

  constructor(names: string[]) {
    for (const name of names) this.add(name);
  }

  private add(name: string): string {
    const existing = this.toWireMap.get(name);
    if (existing) return existing;
    let wire = wireToolName(name);
    if (this.fromWireMap.has(wire) && this.fromWireMap.get(wire) !== name) {
      // Two different tools cleaned to the same spelling: disambiguate the later one by its own hash.
      const suffix = `_${shortHash(name)}`;
      wire = `${wire.slice(0, WIRE_NAME_MAX - suffix.length)}${suffix}`;
    }
    this.toWireMap.set(name, wire);
    this.fromWireMap.set(wire, name);
    return wire;
  }

  /** The name to send. A name absent from this request (an older call in history) is still made valid. */
  toWire(name: string): string {
    return this.toWireMap.get(name) ?? this.add(name);
  }

  /** The registered name for a name the model sent. Unknown names pass through for the loop to report. */
  fromWire(name: string): string {
    return this.fromWireMap.get(name) ?? name;
  }

  /** True when at least one name had to change — the only case where history needs rewriting. */
  get renamed(): boolean {
    for (const [name, wire] of this.toWireMap) if (name !== wire) return true;
    return false;
  }
}

export type SchemaFlavor = 'portable' | 'gemini';

/** Which schema subset a model/provider pair needs. */
export function schemaFlavorFor(provider: string | null | undefined, model: string | null | undefined): SchemaFlavor {
  const p = String(provider || '').toLowerCase();
  const m = String(model || '').toLowerCase();
  if (p === 'google' || /(^|\/)gemini-/.test(m)) return 'gemini';
  return 'portable';
}

/** Keywords Gemini's function declarations refuse; everything else it supports is kept. */
const GEMINI_DROP = new Set([
  'additionalProperties', 'unevaluatedProperties', 'patternProperties', 'propertyNames',
  'dependentRequired', 'dependentSchemas', 'if', 'then', 'else', 'not', 'const', 'examples',
  'exclusiveMinimum', 'exclusiveMaximum', 'multipleOf', 'contentEncoding', 'contentMediaType',
  'readOnly', 'writeOnly', 'deprecated', 'default', 'title',
]);
/** Metadata no provider needs and several refuse. */
const ALWAYS_DROP = new Set(['$schema', '$id', '$comment', '$anchor', '$dynamicAnchor', '$vocabulary']);
const MAX_DEPTH = 24;

type Json = any;

function resolveRef(ref: string, root: Json): Json | undefined {
  if (!ref.startsWith('#/')) return undefined;
  let node: Json = root;
  for (const part of ref.slice(2).split('/')) {
    const key = part.replace(/~1/g, '/').replace(/~0/g, '~');
    if (!node || typeof node !== 'object' || !(key in node)) return undefined;
    node = node[key];
  }
  return node;
}

function normalizeNode(node: Json, root: Json, flavor: SchemaFlavor, depth: number, refs: Set<string>): Json {
  if (Array.isArray(node)) return node.map((v) => normalizeNode(v, root, flavor, depth + 1, refs));
  if (!node || typeof node !== 'object') return node;
  if (depth > MAX_DEPTH) return { type: 'object' };

  // Local references are inlined (several providers refuse `$ref`); a cycle becomes a plain object.
  if (typeof node.$ref === 'string') {
    const ref = node.$ref;
    const target = refs.has(ref) ? undefined : resolveRef(ref, root);
    if (!target) return { type: 'object', ...(node.description ? { description: node.description } : {}) };
    const merged = { ...target, ...Object.fromEntries(Object.entries(node).filter(([k]) => k !== '$ref')) };
    return normalizeNode(merged, root, flavor, depth + 1, new Set([...refs, ref]));
  }

  const out: Json = {};
  for (const [key, value] of Object.entries(node)) {
    if (ALWAYS_DROP.has(key) || key === '$defs' || key === 'definitions') continue;
    if (flavor === 'gemini' && GEMINI_DROP.has(key)) continue;
    if (key === 'properties' && value && typeof value === 'object' && !Array.isArray(value)) {
      out.properties = Object.fromEntries(
        Object.entries(value).map(([k, v]) => [k, normalizeNode(v, root, flavor, depth + 1, refs)]),
      );
    } else if (key === 'items' || key === 'anyOf' || key === 'oneOf' || key === 'allOf' || key === 'prefixItems') {
      out[key] = normalizeNode(value, root, flavor, depth + 1, refs);
    } else {
      out[key] = value;
    }
  }

  if (flavor === 'gemini') {
    // `type: ["string", "null"]` → `type: "string", nullable: true` (Gemini takes one type).
    if (Array.isArray(out.type)) {
      const types = out.type.filter((t: unknown) => t !== 'null');
      if (types.length < out.type.length) out.nullable = true;
      out.type = types[0] ?? 'string';
    }
    // Gemini's `enum` is a list of strings.
    if (Array.isArray(out.enum)) out.enum = out.enum.filter((v: unknown) => v !== null).map((v: unknown) => String(v));
    // `oneOf` is not in Gemini's subset; `anyOf` is, with the same meaning for a tool argument.
    if (out.oneOf && !out.anyOf) { out.anyOf = out.oneOf; delete out.oneOf; }
    if (out.allOf) {
      // Merge an allOf of object schemas; anything else keeps its first member.
      const parts: Json[] = Array.isArray(out.allOf) ? out.allOf : [];
      delete out.allOf;
      for (const part of parts) {
        if (part?.properties) out.properties = { ...(out.properties || {}), ...part.properties };
        if (Array.isArray(part?.required)) out.required = [...new Set([...(out.required || []), ...part.required])];
        if (!out.type && part?.type) out.type = part.type;
      }
    }
  }

  // `required` may only name properties that exist (OpenAI and Gemini both refuse otherwise).
  if (Array.isArray(out.required)) {
    const props = out.properties && typeof out.properties === 'object' ? out.properties : null;
    out.required = out.required.filter((r: unknown) => typeof r === 'string' && (!props || r in props));
    if (out.required.length === 0) delete out.required;
  }
  if (out.properties && !out.type) out.type = 'object';
  // An array without `items` is refused by OpenAI and Gemini alike.
  if (out.type === 'array' && !out.items) out.items = {};
  return out;
}

/**
 * The parameters schema one provider will accept. The root is always `type: "object"` with
 * `properties`: OpenAI refuses any other root, and a root `anyOf`/`oneOf` of object alternatives
 * is folded into one object whose properties are all optional (the tool validates for itself).
 */
export function normalizeToolSchema(schema: Json, flavor: SchemaFlavor = 'portable'): Json {
  const root = schema && typeof schema === 'object' && !Array.isArray(schema) ? schema : {};
  let out = normalizeNode(root, root, flavor, 0, new Set());
  const alternatives: Json[] | undefined = Array.isArray(out.anyOf) ? out.anyOf : Array.isArray(out.oneOf) ? out.oneOf : undefined;
  if (alternatives && !out.properties) {
    const properties: Json = {};
    for (const alt of alternatives) if (alt?.properties) Object.assign(properties, alt.properties);
    const { anyOf: _a, oneOf: _o, ...rest } = out;
    out = { ...rest, properties };
  }
  if (out.type !== 'object') out = { ...out, type: 'object' };
  if (!out.properties || typeof out.properties !== 'object') out.properties = {};
  return out;
}

/** One request's tools, in the provider's shape, and the map to read the model's calls back. */
export function buildWireTools(
  tools: Array<{ name: string; description?: string; input_schema?: Json; parameters?: Json }>,
  flavor: SchemaFlavor,
): { defs: Array<{ type: 'function'; function: { name: string; description: string; parameters: Json } }>; names: ToolNameMap; dropped: string[] } {
  const kept = tools.slice(0, MAX_TOOLS_PER_REQUEST);
  const dropped = tools.slice(MAX_TOOLS_PER_REQUEST).map((t) => t.name);
  const names = new ToolNameMap(kept.map((t) => t.name));
  const defs = kept.map((t) => ({
    type: 'function' as const,
    function: {
      name: names.toWire(t.name),
      description: String(t.description || t.name).slice(0, 4096),
      parameters: normalizeToolSchema(t.input_schema || t.parameters, flavor),
    },
  }));
  return { defs, names, dropped };
}

/** Rewrite the tool-call names already in the conversation to the spelling this request uses. */
export function renameHistoryToolCalls(messages: Json[], names: ToolNameMap): Json[] {
  let anyChanged = false;
  const out = messages.map((m) => {
    if (!m || m.role !== 'assistant' || !Array.isArray(m.tool_calls)) return m;
    let changed = false;
    const calls = m.tool_calls.map((c: Json) => {
      const name = c?.function?.name;
      if (typeof name !== 'string') return c;
      const wire = names.toWire(name);
      if (wire === name) return c;
      changed = true;
      return { ...c, function: { ...c.function, name: wire } };
    });
    if (!changed) return m;
    anyChanged = true;
    return { ...m, tool_calls: calls };
  });
  return anyChanged ? out : messages;
}

import { ToolRegistry } from '../tools/tool.registry';
import { BuiltTool } from '../tools/tool.factory';
import { checkToolArgs } from '../tools/args.validate';
import { TypedOutcome } from '../tools/outcome';
import { maxParallelToolCalls } from './tool.schedule';
import { EvidenceSnapshot, evidenceIsCurrent, WorkflowEvidence } from './workflow.evidence';
import { createHash } from 'crypto';

export interface WorkflowBinding {
  step: string;
  /** JSON Pointer into a JSON result; omitted returns the complete text. */
  pointer?: string;
  /** Zero-based line of text, selected after the optional JSON Pointer. */
  line?: number;
}
export interface WorkflowStep {
  id: string;
  tool: string;
  args: Record<string, unknown>;
  dependsOn?: string[];
  bindings?: Record<string, WorkflowBinding>;
}
export interface WorkflowResult {
  id: string;
  tool: string;
  status: 'ok' | 'error' | 'skipped' | 'cancelled';
  output: string;
  durationMs: number;
  truncated: boolean;
  freshness?: 'current' | 'stale' | 'incomplete';
  checkedAt?: string;
  inputCount?: number;
  evidenceDigest?: string;
  evidenceGaps?: string[];
  reused?: boolean;
}

export interface WorkflowStepState {
  tool: BuiltTool;
  args: string;
  raw?: string;
  output: string;
  evidence: EvidenceSnapshot;
}
export interface WorkflowRunOptions {
  previous?: Map<string, WorkflowStepState>;
  save?: (state: Map<string, WorkflowStepState>) => void;
}

const MAX_STEPS = 32;
const MAX_RESULT_BYTES = 64 * 1024;
const PREVIEW_CHARS = 2000;
const forbidden = new Set(['__proto__', 'constructor', 'prototype']);
const own = (o: object, key: string) => Object.prototype.hasOwnProperty.call(o, key);

function select(binding: WorkflowBinding, text: string): unknown {
  let value: unknown = text;
  if (binding.pointer !== undefined) {
    value = JSON.parse(text);
    if (binding.pointer !== '') {
      if (!binding.pointer.startsWith('/') || /~(?![01])/u.test(binding.pointer)) {
        throw new Error('Invalid JSON Pointer');
      }
      for (const token of binding.pointer.slice(1).split('/')) {
        const key = token.replace(/~1/g, '/').replace(/~0/g, '~');
        if (forbidden.has(key) || value === null || typeof value !== 'object' || !own(value, key)) {
          throw new Error(`Result pointer does not resolve: ${binding.pointer}`);
        }
        value = (value as Record<string, unknown>)[key];
      }
    }
  }
  if (binding.line !== undefined) {
    if (typeof value !== 'string') throw new Error('Line selection requires text');
    const lines = value.split(/\r?\n/);
    if (binding.line >= lines.length) throw new Error('Result line does not exist');
    value = lines[binding.line];
  }
  return value;
}

/** Declarative data flow, never eval. All graph/authority errors reject before any dispatch. */
export async function runToolWorkflow(
  steps: WorkflowStep[], registry: ToolRegistry, context: any = {}, options: WorkflowRunOptions = {},
): Promise<{ ok: boolean; steps: WorkflowResult[] }> {
  if (!Array.isArray(steps) || !steps.length || steps.length > MAX_STEPS) {
    throw new Error(`Workflow must contain 1–${MAX_STEPS} steps`);
  }
  const nodes = new Map<string, { step: WorkflowStep; tool: BuiltTool; deps: Set<string> }>();
  for (const step of steps) {
    if (!step || typeof step.id !== 'string' || !/^[a-zA-Z0-9_-]{1,64}$/.test(step.id) || nodes.has(step.id)) {
      throw new Error('Step IDs must be unique, 1–64 letters, digits, underscores or hyphens');
    }
    // Exact identity only: model aliases must not select a different capability inside a graph.
    const tool = typeof step.tool === 'string' ? registry.getTool(step.tool) : undefined;
    if (!tool || tool.name !== step.tool || tool.workflowReadOnly !== true || tool.isDestructive) {
      throw new Error(`Tool is not eligible for read-only workflows: ${step.tool}`);
    }
    if (!step.args || typeof step.args !== 'object' || Array.isArray(step.args)) throw new Error('Step args must be an object');
    if (step.dependsOn !== undefined && (!Array.isArray(step.dependsOn) || step.dependsOn.some(d => typeof d !== 'string'))) {
      throw new Error('dependsOn must be an array of step IDs');
    }
    if (step.bindings !== undefined && (!step.bindings || typeof step.bindings !== 'object' || Array.isArray(step.bindings))) {
      throw new Error('bindings must be an object');
    }
    const deps = new Set(step.dependsOn ?? []);
    for (const [key, binding] of Object.entries(step.bindings ?? {})) {
      if (forbidden.has(key) || own(step.args, key)) throw new Error(`Conflicting or unsafe binding: ${key}`);
      if (!binding || typeof binding.step !== 'string'
        || (binding.pointer !== undefined && typeof binding.pointer !== 'string')
        || (binding.line !== undefined && (!Number.isInteger(binding.line) || binding.line < 0))) {
        throw new Error(`Invalid binding: ${key}`);
      }
      deps.add(binding.step);
    }
    if (!Object.keys(step.bindings ?? {}).length) {
      const check = checkToolArgs(tool.schema, step.args);
      if (check.violations.length) throw new Error(`${step.id}: ${check.violations.join('; ')}`);
    }
    nodes.set(step.id, { step, tool, deps });
  }
  const visited = new Set<string>();
  const visiting = new Set<string>();
  const visit = (id: string): void => {
    if (visited.has(id)) return;
    const node = nodes.get(id);
    if (!node) throw new Error(`Unknown dependency: ${id}`);
    if (visiting.has(id)) throw new Error(`Dependency cycle at ${id}`);
    visiting.add(id);
    node.deps.forEach(visit);
    visiting.delete(id);
    visited.add(id);
  };
  nodes.forEach((_, id) => visit(id));

  const results = new Map<string, WorkflowResult>();
  const outputs = new Map<string, string>();
  const running = new Map<string, Promise<void>>();
  const states = new Map<string, WorkflowStepState>();
  const limit = Math.min(8, maxParallelToolCalls());
  let exclusive = false;
  const record = (step: WorkflowStep, status: WorkflowResult['status'], output: string, started: number): void => {
    results.set(step.id, {
      id: step.id, tool: step.tool, status, output: output.slice(0, PREVIEW_CHARS),
      durationMs: Date.now() - started, truncated: output.length > PREVIEW_CHARS,
    });
  };
  const execute = async (step: WorkflowStep, tool: BuiltTool, args: unknown): Promise<void> => {
    const started = Date.now();
    let outcome: TypedOutcome | undefined;
    const collector = new WorkflowEvidence(context.signal);
    let evidence: EvidenceSnapshot | undefined;
    let rawResult: unknown;
    let reused = false;
    const argsKey = () => JSON.stringify(args);
    try {
      // Recheck ancestors immediately before binding use; a human edit can occur mid-workflow.
      const ancestors = new Set<string>();
      const collect = (id: string): void => { for (const dep of nodes.get(id)!.deps) if (!ancestors.has(dep)) { ancestors.add(dep); collect(dep); } };
      collect(step.id);
      for (const id of ancestors) {
        const state = states.get(id);
        if (state?.evidence.complete && !await evidenceIsCurrent(state.evidence, context.signal)) {
          results.get(id)!.freshness = 'stale';
          record(step, 'skipped', `Prerequisite ${id} changed after observation. Refresh the workflow.`, started);
          return;
        }
      }
      const raw = await tool.execute(args, {
        ...context,
        workflowEvidence: collector,
        workflowRawResult: (value: unknown) => { rawResult = value; },
        workflowReuse: async () => {
          const previous = options.previous?.get(step.id);
          if (!previous || previous.tool !== tool || previous.args !== argsKey() || previous.raw === undefined) return undefined;
          if ([...nodes.get(step.id)!.deps].some(id => results.get(id)?.reused !== true
            || outputs.get(id) !== options.previous?.get(id)?.output)) return undefined;
          if (!await evidenceIsCurrent(previous.evidence, context.signal)) return undefined;
          evidence = previous.evidence;
          reused = true;
          return previous.raw;
        },
        // Child outcomes must not overwrite the parent's aggregate outcome.
        reportOutcome: (o: TypedOutcome) => { outcome = o; },
      });
      const output = typeof raw === 'string' ? raw : JSON.stringify(raw);
      if (typeof output !== 'string') throw new Error('Tool returned no serializable output');
      if (context.signal?.aborted) {
        record(step, 'cancelled', 'Interrupted while running; result not used.', started);
      } else if (outcome && outcome.status !== 'ok') {
        record(step, 'error', output, started);
      } else if (Buffer.byteLength(output, 'utf8') > MAX_RESULT_BYTES) {
        record(step, 'error', 'Result exceeds 64 KiB. Narrow the source query or line range.', started);
      } else {
        evidence ??= collector.snapshot();
        if (reused && collector.gaps().length) evidence = { ...evidence, complete: false, reasons: collector.gaps() };
        if ([...nodes.get(step.id)!.deps].some(id => !states.get(id)?.evidence.complete)) {
          evidence = { ...evidence, complete: false, reasons: [...evidence.reasons, 'Prerequisite evidence is incomplete'] };
        }
        states.set(step.id, {
          tool, args: argsKey(),
          raw: typeof rawResult === 'string' && Buffer.byteLength(rawResult) <= MAX_RESULT_BYTES ? rawResult : undefined,
          output, evidence,
        });
        outputs.set(step.id, output);
        record(step, 'ok', output, started);
        Object.assign(results.get(step.id)!, {
          freshness: evidence.complete ? 'current' : 'incomplete',
          inputCount: evidence.inputs.length, evidenceGaps: evidence.reasons,
          evidenceDigest: createHash('sha256').update(JSON.stringify(evidence.inputs)).digest('hex'), reused,
        });
      }
    } catch (error) {
      record(step, context.signal?.aborted ? 'cancelled' : 'error', error instanceof Error ? error.message : String(error), started);
    }
  };

  while (results.size < nodes.size) {
    for (const { step, tool, deps } of nodes.values()) {
      if (results.has(step.id) || running.has(step.id)) continue;
      if (context.signal?.aborted) {
        record(step, 'cancelled', 'Interrupted before dispatch.', Date.now());
        continue;
      }
      if ([...deps].some(d => results.has(d) && results.get(d)!.status !== 'ok')) {
        record(step, 'skipped', 'A prerequisite did not succeed.', Date.now());
        continue;
      }
      if ([...deps].some(d => !results.has(d)) || exclusive || running.size >= limit) continue;
      try {
        const args = { ...step.args };
        for (const [key, binding] of Object.entries(step.bindings ?? {})) args[key] = select(binding, outputs.get(binding.step)!);
        const check = checkToolArgs(tool.schema, args);
        if (check.violations.length) throw new Error(check.violations.join('; '));
        let safe = false;
        try { safe = (tool.concurrencySafeFor?.(check.args) ?? tool.isConcurrencySafe) === true; } catch { /* exclusive */ }
        if (!safe && running.size) continue;
        exclusive = !safe;
        const work = execute(step, tool, check.args).finally(() => {
          running.delete(step.id);
          if (!safe) exclusive = false;
        });
        running.set(step.id, work);
      } catch (error) {
        record(step, 'error', error instanceof Error ? error.message : String(error), Date.now());
      }
    }
    // Drain started operations even on abort; never return while a nested operation is still live.
    if (running.size) await Promise.race(running.values());
  }
  await Promise.all(running.values());
  // A last check catches changes during sibling work or post-hooks. No claim of an atomic FS snapshot.
  for (const [id, state] of states) {
    if (context.signal?.aborted) break;
    try {
      if (state.evidence.complete && !await evidenceIsCurrent(state.evidence, context.signal)) results.get(id)!.freshness = 'stale';
    } catch (error) { if (context.signal?.aborted) break; throw error; }
  }
  for (let pass = 0; pass < steps.length; pass++) {
    for (const { step, deps } of nodes.values()) {
      if ([...deps].some(id => results.get(id)?.freshness === 'stale')) results.get(step.id)!.freshness = 'stale';
    }
  }
  for (const result of results.values()) {
    result.checkedAt = new Date().toISOString();
    if (context.signal?.aborted && result.status === 'ok') { result.status = 'cancelled'; result.freshness = 'stale'; }
    if (result.freshness === 'stale' || result.status !== 'ok') states.delete(result.id);
  }
  options.save?.(states);
  return { ok: [...results.values()].every(r => r.status === 'ok' && r.freshness !== 'stale'), steps: steps.map(s => results.get(s.id)!) };
}

import { stateDir } from '../utils/state.dir';
import * as fs from 'fs/promises';
import { constants } from 'fs';
import * as path from 'path';
import { createHash, randomBytes } from 'crypto';
import { Logger } from '../utils/logger';

/**
 * Tracked multi-file edit transactions (`/tx`).
 * Snapshot lifecycle is fenced; filesystem reads and writes are not an OS-level atomic unit.
 *
 * The pre-edit state of a path is a THREE-state value, not a string:
 *
 *   - `file`       — the path held these exact bytes. Rollback restores them.
 *   - `absent`     — nothing was there. Rollback deletes what the transaction created.
 *   - `unreadable` — the path exists but its bytes could not be captured (permissions, a
 *                    directory, a file past the snapshot ceiling). Rollback restores NOTHING and
 *                    says so; the transaction never protected that path.
 *
 * The previous implementation collapsed all three onto `originalContent: string` and used `''` to
 * mean "absent", so rollback DELETED an existing zero-byte file and treated an unreadable file as
 * a new one. It also blind-wrote the snapshot back, destroying any edit a human made after the
 * agent's write, and cleared its own records before restoring, so a failed restore lost the only
 * copy of the original bytes. Reproduced 2026-09-07 in
 * `docs/product-reset/competitive/evidence/2026-09-08-plan-recheck/transaction-result.json`.
 *
 * Conflict policy (explicit): rollback only writes over an on-disk state this transaction itself
 * produced — the recorded baseline, or one of the contents a caller declared it was about to
 * write. Anything else means somebody changed the file after we did; that content is KEPT, the
 * path is reported as a conflict, and the pre-transaction bytes are saved under
 * `.breakglass/transactions/<id>/` so the original is still recoverable. `rollback({ force: true })`
 * overrides that deliberately.
 *
 * That check depends on callers declaring what they write, so the default for a caller that does
 * NOT declare is strict: every changed path becomes a conflict and nothing is restored. It is the
 * deliberate trade. Permissive-by-default would mean a forgotten argument silently reintroduces
 * exactly the defect this module was rewritten to remove — an agent rollback erasing somebody's
 * later edit. Strict-by-default degrades instead into "your bytes were kept and here is why",
 * which the receipt says out loud and `trackEdit` warns about at the time of the call. Every
 * in-tree caller (edit, multiedit, symbol-edit, write and delete tools) declares its intent.
 */

/** Bytes are held in memory for the length of a transaction; refuse to snapshot past this. */
const DEFAULT_MAX_SNAPSHOT_BYTES = 64 * 1024 * 1024;

/** Token for "this path holds nothing", used alongside `sha256:<hex>` content tokens. */
const ABSENT = 'absent';

export type BaselineKind = 'file' | 'absent' | 'unreadable';

export interface Baseline {
  kind: BaselineKind;
  /** Present only for `file`. */
  bytes?: Buffer;
  /** Present only for `file`. */
  sha256?: string;
  /** Present only for `file` — restored with content; external mode changes require --force. */
  mode?: number;
  size?: number;
  /** True when the path itself is a symlink; restoring writes THROUGH it, never replacing it. */
  viaSymlink?: boolean;
  /** Present only for `unreadable` — why the bytes are not held. */
  error?: string;
  code?: string;
}

/**
 * What the caller is about to leave on disk: the exact content for a write, `null` for a delete,
 * `undefined` when the caller does not say. An undeclared intent cannot be verified at rollback,
 * so the receipt marks that path unverified.
 */
export type MutationIntent = string | Uint8Array | null | undefined;

export interface TrackResult {
  /** False when no transaction is open — the call was a no-op. */
  tracked: boolean;
  baseline: BaselineKind;
  /** False for an `unreadable` baseline: rollback cannot put this path back. */
  protectedByTx: boolean;
  /** Set when `protectedByTx` is false — the reason, for the caller to surface. */
  message?: string;
}

export type RestoreStatus =
  /** Baseline bytes were written back over different content. */
  | 'restored'
  /** Baseline file was gone (the transaction deleted it) and has been re-created. */
  | 'recreated'
  /** Baseline was absent; the file this transaction created has been deleted. */
  | 'removed'
  /** On-disk state already equalled the baseline; nothing was written. */
  | 'unchanged'
  /** On-disk state was not produced by this transaction; it was KEPT, not overwritten. */
  | 'conflict'
  /** Baseline was never captured (unreadable); nothing to restore. */
  | 'unprotected'
  /** Restoration was attempted and failed; the baseline bytes are retained. */
  | 'failed';

export interface RestoreEntry {
  absPath: string;
  status: RestoreStatus;
  /** False when the caller never declared what it was writing, so the state could not be verified. */
  verified: boolean;
  detail?: string;
  /** Where the pre-transaction bytes were retained, for `conflict` and `failed`. */
  recoveryPath?: string;
}

export interface RollbackResult {
  id: string;
  message: string;
  entries: RestoreEntry[];
  /** Entries that can be retried by `recover()`. */
  pending: number;
}

interface EditRecord {
  absPath: string;
  baseline: Baseline;
  /** Every state this transaction declared it would leave: `sha256:<hex>` tokens and/or ABSENT. */
  expected: Set<string>;
  /** False when no caller ever declared an intent for this path. */
  intentDeclared: boolean;
}

interface RetainedRecovery {
  id: string;
  dir: string | null;
  records: EditRecord[];
}

interface OpenTransaction {
  id: string;
  edits: EditRecord[];
  snapshots: Map<string, Promise<EditRecord>>;
  pending: number;
}

export interface TransactionManagerOptions {
  /** Root under which `.breakglass/transactions/<id>/` is written. Defaults to the process cwd. */
  recoveryRoot?: string;
  maxSnapshotBytes?: number;
  /** Aggregate byte budget for captured/reserved baselines, including unresolved recoveries. */
  maxTotalSnapshotBytes?: number;
}

export interface TransactionStatus {
  id: string | null;
  phase: 'idle' | 'open' | 'restoring';
  paths: number;
  protectedPaths: number;
  unprotectedPaths: number;
  pendingSnapshots: number;
  snapshotBytes: number;
  /** Includes old recovery baselines and reads that have reserved space but are still pending. */
  heldSnapshotBytes: number;
  maxTotalSnapshotBytes: number;
}

function contentToken(bytes: Buffer): string {
  return `sha256:${createHash('sha256').update(bytes).digest('hex')}`;
}

function toBuffer(intent: string | Uint8Array): Buffer {
  return typeof intent === 'string' ? Buffer.from(intent, 'utf8') : Buffer.from(intent);
}

export class TransactionManager {
  private openTx: OpenTransaction | null = null;
  private rollingBack = false;
  /** Baselines that rollback could not put back, kept so the bytes are not lost with the process. */
  private retained = new Map<string, RetainedRecovery>();

  private readonly recoveryRoot?: string;
  private readonly maxSnapshotBytes: number;
  private readonly maxTotalSnapshotBytes: number;
  private heldSnapshotBytes = 0;

  constructor(options: TransactionManagerOptions = {}) {
    this.recoveryRoot = options.recoveryRoot;
    this.maxSnapshotBytes = options.maxSnapshotBytes ?? DEFAULT_MAX_SNAPSHOT_BYTES;
    this.maxTotalSnapshotBytes = options.maxTotalSnapshotBytes ?? DEFAULT_MAX_SNAPSHOT_BYTES;
    for (const limit of [this.maxSnapshotBytes, this.maxTotalSnapshotBytes]) {
      if (!Number.isSafeInteger(limit) || limit < 0) throw new RangeError('Snapshot byte budgets must be non-negative safe integers.');
    }
  }

  isOpen(): boolean {
    return this.openTx !== null;
  }

  currentId(): string | null {
    return this.openTx?.id ?? null;
  }

  /** Paths whose pre-transaction bytes are still held after a failed restoration. */
  pendingRecovery(): { id: string; paths: string[]; dir: string | null } | null {
    return this.pendingRecoveries()[0] ?? null;
  }

  pendingRecoveries(): { id: string; paths: string[]; dir: string | null }[] {
    return [...this.retained.values()].map(r => ({ id: r.id, paths: r.records.map(e => e.absPath), dir: r.dir }));
  }

  status(): TransactionStatus {
    const edits = this.openTx?.edits ?? [];
    const unprotectedPaths = edits.filter(e => e.baseline.kind === 'unreadable').length;
    return {
      id: this.currentId(), phase: this.rollingBack ? 'restoring' : this.openTx ? 'open' : 'idle',
      paths: edits.length, protectedPaths: edits.length - unprotectedPaths, unprotectedPaths,
      pendingSnapshots: this.openTx?.pending ?? 0,
      snapshotBytes: edits.reduce((n, e) => n + (e.baseline.bytes?.length ?? 0), 0),
      heldSnapshotBytes: this.heldSnapshotBytes, maxTotalSnapshotBytes: this.maxTotalSnapshotBytes,
    };
  }

  begin(id: string): string {
    if (this.rollingBack) return 'A restoration is in progress. Wait before beginning another transaction.';
    if (this.openTx) {
      return `Transaction ${this.openTx.id} is already open. Commit or rollback it first.`;
    }
    if (this.retained.has(id)) return `Transaction ${id} still has recovery records. Choose a different ID.`;
    this.openTx = { id, edits: [], snapshots: new Map(), pending: 0 };
    Logger.info(`[TX] Opened transaction ${id}`);
    return `Transaction ${id} opened. File edits until /tx commit are tracked for rollback; unreadable snapshots are reported as unprotected.`;
  }

  /**
   * Called by the mutating tools BEFORE writing — captures the pre-edit state for rollback.
   *
   * `intent` is what the caller is about to leave on disk (content, or `null` for a delete). It is
   * what makes a later third-party edit detectable at rollback time: a state that is neither the
   * baseline nor something we declared came from somebody else. Omitting it does not break
   * tracking, but changed content is kept as a conflict and the receipt says so.
   */
  async trackEdit(absPath: string, intent?: MutationIntent): Promise<TrackResult> {
    if (this.rollingBack) throw new Error('A restoration is in progress; file edits cannot be tracked yet.');
    if (!this.openTx) return { tracked: false, baseline: 'absent', protectedByTx: false };
    const tx = this.openTx;
    const key = path.resolve(absPath);
    // `undefined` means the caller did not say; `null` means "this path will be gone".
    const intentGiven = intent !== undefined;

    // Register the promise before yielding: callers of the same path share the FIRST baseline.
    let snapshot = tx.snapshots.get(key);
    if (!snapshot) {
      tx.pending++;
      snapshot = this.capture(key, true).then(baseline => {
        const record: EditRecord = { absPath: key, baseline, expected: new Set(), intentDeclared: false };
        tx.edits.push(record);
        return record;
      }).finally(() => { tx.pending--; });
      tx.snapshots.set(key, snapshot);
    }
    // Count every waiting caller too; lifecycle operations must not close between their continuations.
    tx.pending++;
    let record: EditRecord;
    try {
      record = await snapshot;
      if (intentGiven) {
        record.intentDeclared = true;
        record.expected.add(intent === null ? ABSENT : contentToken(toBuffer(intent)));
      }
    } finally {
      tx.pending--;
    }
    const baseline = record.baseline;

    if (baseline.kind === 'unreadable') {
      Logger.warn(`[TX] ${tx.id}: ${key} is NOT protected — ${baseline.error}`);
      return { tracked: true, baseline: 'unreadable', protectedByTx: false, message: baseline.error };
    }
    if (!intentGiven) {
      // Say it here, where the caller is, rather than only in a rollback receipt nobody may read.
      Logger.warn(
        `[TX] ${tx.id}: ${key} was tracked without a declared write. Rollback cannot tell ` +
        `this transaction's own change from an external one, so it will keep whatever is on disk.`
      );
    }
    return { tracked: true, baseline: baseline.kind, protectedByTx: true };
  }

  commit(): string {
    if (!this.openTx) return 'No open transaction to commit.';
    if (this.openTx.pending) return 'Snapshot capture is in progress. Wait before committing this transaction.';
    const id = this.openTx.id;
    const count = this.openTx.edits.length;
    const unprotected = this.openTx.edits.filter(e => e.baseline.kind === 'unreadable');
    this.releaseBaselines(this.openTx.edits);
    this.openTx = null;
    Logger.info(`[TX] Committed ${id} (${count} file(s))`);
    const msg = [`Transaction ${id} committed (${count} file(s) changed).`];
    if (unprotected.length) {
      msg.push(
        `${unprotected.length} path(s) were never protected by this transaction (pre-edit content unreadable): ` +
        unprotected.map(e => `${e.absPath} — ${e.baseline.error}`).join('; ')
      );
    }
    return msg.join('\n');
  }

  async rollback(options: { force?: boolean } = {}): Promise<string> {
    return (await this.rollbackDetailed(options)).message;
  }

  /** Same as `rollback`, with the per-path outcomes the receipt is built from. */
  async rollbackDetailed(options: { force?: boolean } = {}): Promise<RollbackResult> {
    if (this.rollingBack) {
      return { id: '', message: 'A restoration is already in progress.', entries: [], pending: 0 };
    }
    if (!this.openTx) {
      return { id: '', message: 'No open transaction to roll back.', entries: [], pending: 0 };
    }
    if (this.openTx.pending) {
      return { id: '', message: 'Snapshot capture is in progress. Wait before rolling back this transaction.', entries: [], pending: 0 };
    }
    const { id, edits } = this.openTx;
    // Stop tracking new edits into a transaction that is being undone, but keep the records: they
    // hold the only copy of the original bytes until every path is actually back.
    this.openTx = null;
    this.rollingBack = true;

    const entries: RestoreEntry[] = [];
    const keep: EditRecord[] = [];
    try {
      for (const record of [...edits].reverse()) {
        const entry = await this.restoreOne(record, options.force === true);
        entries.push(entry);
        if (entry.status === 'failed' || entry.status === 'conflict') keep.push(record);
      }
      const dir = keep.length ? await this.retainBaselines(id, keep, entries) : null;
      if (keep.length) this.retained.set(id, { id, dir, records: keep });
      const kept = new Set(keep);
      this.releaseBaselines(edits.filter(e => !kept.has(e)));
    } finally {
      this.rollingBack = false;
    }

    return {
      id,
      message: this.receipt(id, entries),
      entries,
      pending: entries.filter(e => e.status === 'failed').length,
    };
  }

  /**
   * Retry unresolved paths using the same strict conflict checks. A conflict is only restored if
   * its current state now matches a declared write; recovery never implies --force.
   */
  async recover(): Promise<string> {
    if (this.rollingBack) return 'A restoration is already in progress.';
    if (this.openTx) return 'Commit or roll back the open transaction before retrying recovery.';
    if (!this.retained.size) return 'Nothing is pending recovery.';
    this.rollingBack = true;
    const receipts: string[] = [];
    try {
      for (const { id, records, dir } of [...this.retained.values()]) {
        const entries: RestoreEntry[] = [];
        const keep: EditRecord[] = [];
        for (const record of records) {
          const entry = await this.restoreOne(record, false);
          entries.push(entry);
          if (entry.status === 'failed' || entry.status === 'conflict') keep.push(record);
        }
        const kept = new Set(keep);
        this.releaseBaselines(records.filter(e => !kept.has(e)));
        if (keep.length) this.retained.set(id, { id, dir, records: keep });
        else this.retained.delete(id);
        receipts.push(`Recovery of transaction ${id}: ${this.receipt(id, entries)}`);
      }
    } finally {
      this.rollingBack = false;
    }
    return receipts.join('\n');
  }

  private releaseBaselines(records: EditRecord[]): void {
    this.heldSnapshotBytes -= records.reduce((n, r) => n + (r.baseline.bytes?.length ?? 0), 0);
  }

  /** Called on a mutating tool's failure while a transaction is open — auto-rollback. */
  async autoRollback(failedPath: string, reason: string): Promise<string> {
    if (!this.openTx) return '';
    const txId = this.openTx.id;
    const result = await this.rollbackDetailed();
    const outcome = result.id === txId
      ? `Automatic rollback attempted for transaction ${txId}; inspect the per-path outcomes below.`
      : `Automatic rollback could not start for transaction ${txId}.`;
    return `Edit to ${failedPath} failed (${reason}). ${outcome}\n${result.message}`;
  }

  // ---------------------------------------------------------------------------------------------

  /** Read the pre-edit state. Missing, empty and unreadable are three different answers. */
  private async capture(absPath: string, reserveBaseline = false): Promise<Baseline> {
    let viaSymlink = false;
    let handle: fs.FileHandle | undefined;
    let reserved = 0;
    let accepted = false;
    try {
      const link = await fs.lstat(absPath);
      viaSymlink = link.isSymbolicLink();
    } catch {
      /* resolved below by stat */
    }
    try {
      // Nonblocking open prevents a path swapped for a FIFO from hanging the engine.
      handle = await fs.open(absPath, constants.O_RDONLY | constants.O_NONBLOCK);
      const st = await handle.stat();
      if (!st.isFile()) {
        return { kind: 'unreadable', error: `not a regular file (${st.isDirectory() ? 'directory' : 'special file'})`, code: 'ENOTFILE', viaSymlink };
      }
      if (st.size > this.maxSnapshotBytes) {
        return {
          kind: 'unreadable',
          error: `too large to snapshot (${st.size} bytes > ${this.maxSnapshotBytes} byte limit)`,
          code: 'EFBIG',
          size: st.size,
          viaSymlink,
        };
      }
      if (reserveBaseline && st.size > this.maxTotalSnapshotBytes - this.heldSnapshotBytes) {
        return {
          kind: 'unreadable', code: 'ETXBUDGET', size: st.size, viaSymlink,
          error: `snapshot memory budget exhausted (${this.heldSnapshotBytes} held + ${st.size} bytes > ${this.maxTotalSnapshotBytes} byte aggregate limit)`,
        };
      }
      if (reserveBaseline) {
        reserved = st.size;
        this.heldSnapshotBytes += reserved;
      }
      // Allocate exactly the inspected size: a file growing during the read cannot exceed the cap.
      const bytes = Buffer.alloc(st.size);
      let offset = 0;
      while (offset < bytes.length) {
        const { bytesRead } = await handle.read(bytes, offset, bytes.length - offset, offset);
        if (!bytesRead) break;
        offset += bytesRead;
      }
      const after = await handle.stat();
      const atPath = await fs.stat(absPath);
      if (offset !== st.size || after.size !== st.size || after.mtimeMs !== st.mtimeMs ||
          after.ctimeMs !== st.ctimeMs || after.mode !== st.mode || atPath.dev !== st.dev || atPath.ino !== st.ino) {
        return { kind: 'unreadable', code: 'ESTALE', viaSymlink, error: 'file changed during snapshot capture; no stable baseline was captured' };
      }
      accepted = true;
      return { kind: 'file', bytes, sha256: contentToken(bytes), mode: st.mode & 0o7777, size: bytes.length, viaSymlink };
    } catch (e: any) {
      // ENOENT is the ONLY error that means "nothing was here". Everything else is a file we
      // failed to read, and deleting it on rollback would destroy content we never captured.
      if (e?.code === 'ENOENT' && !handle && !viaSymlink) return { kind: 'absent', viaSymlink };
      return { kind: 'unreadable', error: `${e?.code || 'read failed'}: ${e?.message ?? String(e)}`, code: e?.code, viaSymlink };
    } finally {
      if (!accepted) this.heldSnapshotBytes -= reserved;
      await handle?.close().catch(() => {});
    }
  }

  private async restoreOne(record: EditRecord, force: boolean): Promise<RestoreEntry> {
    const { absPath, baseline, expected, intentDeclared } = record;
    const verified = intentDeclared;

    if (baseline.kind === 'unreadable') {
      return {
        absPath,
        status: 'unprotected',
        verified,
        detail: `pre-transaction content was never captured (${baseline.error}); nothing was restored`,
      };
    }

    const current = await this.capture(absPath);
    if (current.kind === 'unreadable' && !force) {
      // We cannot see what is there now, so we cannot prove it is ours to overwrite.
      return {
        absPath,
        status: 'conflict',
        verified,
        detail: `current content could not be read (${current.error}); it was left alone`,
      };
    }

    const baselineToken = baseline.kind === 'absent' ? ABSENT : baseline.sha256!;
    const currentToken = current.kind === 'absent' ? ABSENT : current.sha256 ?? '';
    const modeMatches = baseline.kind !== 'file' || current.kind !== 'file' || current.mode === baseline.mode;

    if (currentToken === baselineToken && modeMatches) {
      return { absPath, status: 'unchanged', verified, detail: 'already matched the pre-transaction state' };
    }

    // Strict by design: we overwrite ONLY a state this transaction declared it would produce.
    // A caller that does not declare its writes gets a conflict rather than a blind overwrite, so
    // dropping the intent argument degrades into "keep the user's bytes", never into losing them.
    // A torn write (the process died mid-write, leaving neither state) also lands here: the file is
    // kept, the original is retained on disk, and `/tx rollback --force` applies it deliberately.
    const producedByUs = expected.has(currentToken);
    if ((!producedByUs || !modeMatches) && !force) {
      return {
        absPath,
        status: 'conflict',
        verified,
        detail: !modeMatches ? 'file permissions changed outside the declared content write; the newer mode was kept' : intentDeclared
          ? 'changed after this transaction wrote it; the newer content was kept'
          : 'the caller never declared what it wrote, so this content could not be attributed to this transaction; it was kept',
      };
    }

    try {
      if (baseline.kind === 'absent') {
        await fs.rm(absPath, { force: true });
        const after = await this.capture(absPath);
        if (after.kind !== 'absent') throw new Error('file still present after removal');
        return { absPath, status: 'removed', verified, detail: force && !producedByUs ? 'forced' : undefined };
      }
      await this.writeBack(absPath, baseline);
      const after = await this.capture(absPath);
      if (after.kind !== 'file' || after.sha256 !== baseline.sha256 || after.mode !== baseline.mode) {
        throw new Error(`read-back mismatch after restoring ${absPath}`);
      }
      return {
        absPath,
        status: current.kind === 'absent' ? 'recreated' : 'restored',
        verified,
        detail: force && !producedByUs ? 'forced over a newer change' : undefined,
      };
    } catch (e: any) {
      Logger.error(`[TX] Rollback failed for ${absPath}: ${e?.message ?? e}`);
      return { absPath, status: 'failed', verified, detail: e?.message ?? String(e) };
    }
  }

  /**
   * Replace the file's bytes. A same-directory temp file plus rename means a crash mid-restore
   * leaves the old content, never a half-written file — except through a symlink, where a rename
   * would silently replace the LINK with a regular file, so that case writes in place.
   */
  private async writeBack(absPath: string, baseline: Baseline): Promise<void> {
    const bytes = baseline.bytes!;
    let isLink = baseline.viaSymlink === true;
    try {
      isLink = (await fs.lstat(absPath)).isSymbolicLink();
    } catch {
      /* gone; fall back to the captured answer */
    }
    if (isLink) {
      await fs.writeFile(absPath, bytes);
      if (baseline.mode !== undefined) await fs.chmod(absPath, baseline.mode);
      return;
    }
    const dir = path.dirname(absPath);
    await fs.mkdir(dir, { recursive: true });
    const tmp = path.join(dir, `.${path.basename(absPath)}.bimax-tx-${randomBytes(6).toString('hex')}`);
    try {
      await fs.writeFile(tmp, bytes);
      if (baseline.mode !== undefined) await fs.chmod(tmp, baseline.mode);
      await fs.rename(tmp, absPath);
    } catch (e) {
      await fs.rm(tmp, { force: true }).catch(() => {});
      throw e;
    }
  }

  /**
   * Put the still-unrestored baselines somewhere they survive this process, and tell each entry
   * where its copy went. Best-effort: a read-only workspace must not turn into a thrown rollback.
   */
  private async retainBaselines(id: string, keep: EditRecord[], entries: RestoreEntry[]): Promise<string | null> {
    const dir = path.join(stateDir('.breakglass', this.recoveryRoot ?? process.cwd()), 'transactions', id);
    try {
      await fs.mkdir(dir, { recursive: true });
      const manifest: object[] = [];
      for (let i = 0; i < keep.length; i++) {
        const record = keep[i];
        const entry = entries.find(e => e.absPath === record.absPath);
        let saved: string | undefined;
        if (record.baseline.kind === 'file') {
          saved = path.join(dir, `${String(i).padStart(3, '0')}-${path.basename(record.absPath)}`);
          await fs.writeFile(saved, record.baseline.bytes!);
          if (entry) entry.recoveryPath = saved;
        }
        manifest.push({
          absPath: record.absPath,
          baseline: record.baseline.kind,
          sha256: record.baseline.sha256 ?? null,
          mode: record.baseline.mode ?? null,
          status: entry?.status ?? 'failed',
          savedAs: saved ?? null,
        });
      }
      await fs.writeFile(
        path.join(dir, 'manifest.json'),
        JSON.stringify({ schema: 1, transaction: id, savedAt: new Date().toISOString(), paths: manifest }, null, 2) + '\n'
      );
      return dir;
    } catch (e: any) {
      Logger.error(`[TX] Could not retain rollback baselines for ${id} in ${dir}: ${e?.message ?? e}`);
      return null;
    }
  }

  private receipt(id: string, entries: RestoreEntry[]): string {
    const of = (s: RestoreStatus) => entries.filter(e => e.status === s);
    const restored = [...of('restored'), ...of('recreated')];
    const removed = of('removed');
    const unchanged = of('unchanged');
    const conflicts = of('conflict');
    const unprotected = of('unprotected');
    const failed = of('failed');

    const summary = [
      `${restored.length} restored`,
      `${removed.length} removed`,
      `${unchanged.length} already matched`,
      `${conflicts.length} kept (changed after this transaction)`,
      `${unprotected.length} unprotected`,
      `${failed.length} failed`,
    ].join(', ');
    const msg = [`Transaction ${id} rolled back — ${entries.length} path(s): ${summary}.`];

    const list = (label: string, rows: RestoreEntry[]) => {
      if (!rows.length) return;
      msg.push(`${label}: ${rows.map(r => r.absPath + (r.detail ? ` (${r.detail})` : '')).join('; ')}`);
    };
    list('Restored', restored);
    list('Removed (created by this transaction)', removed);
    list('Unchanged', unchanged);
    list('KEPT — not overwritten', conflicts);
    list('NOT protected — no pre-transaction content was captured', unprotected);
    list('FAILED to restore', failed);

    const unverified = entries.filter(e => !e.verified && e.status !== 'unprotected');
    if (unverified.length) {
      msg.push(
        `Unverified (the caller did not declare what it wrote, so a later external change could not be detected): ` +
        unverified.map(r => r.absPath).join(', ')
      );
    }
    const withCopies = entries.filter(e => e.recoveryPath);
    if (withCopies.length) {
      msg.push(`Pre-transaction content retained at: ${withCopies.map(r => r.recoveryPath).join(', ')}`);
    }
    if (failed.length) msg.push('Run /tx recover to retry the failed paths.');
    return msg.join('\n');
  }
}

export const globalTransactionManager = new TransactionManager();

import { stateDir } from '../utils/state.dir';
import * as fs from 'fs';
import * as path from 'path';
import { execFileSync } from 'child_process';
import { Logger } from '../utils';

/**
 * Multi-repo workspace — native cross-repo awareness (docs/UPGRADE_2026_RESEARCH.md PR1).
 *
 * Pattern sources: Claude Code's additional working directories (`--add-dir`) and Plandex's
 * multi-repo planning. BiMax keeps a manifest of every repo the user has registered for this
 * project (`.bimax/workspace.json`), refreshes branch/sync state on session start, detects
 * fresh `git clone`s made mid-session, and scopes edits per-repo: the primary repo is always
 * writable, other repos join read-only until explicitly unlocked ("pull the pattern from repo Y
 * into repo X" needs Y readable, only X writable).
 *
 * Deliberately additive: paths OUTSIDE any registered repo behave exactly as before — this
 * layer only grants awareness of sibling repos and enforces the scope the user chose for them.
 */

export type RepoScope = 'write' | 'read' | 'ignored';

export interface WorkspaceRepo {
  /** Absolute path to the repo root (contains .git). */
  path: string;
  /** Short display name (basename of path unless overridden). */
  name: string;
  /** Why this repo is in the workspace ("upstream reference", "pattern source", …). */
  purpose?: string;
  /** Current branch, refreshed on session start / refresh(). */
  branch?: string;
  /** Last time we refreshed git state for this entry (ISO). */
  lastSynced?: string;
  /** write = editable · read = readable reference · ignored = user declined registration. */
  scope: RepoScope;
  registeredAt: string;
}

interface Manifest { version: 1; repos: WorkspaceRepo[] }

export class WorkspaceManager {
  private manifestPath: string;
  private repos: WorkspaceRepo[] = [];
  /** Freshly-detected clone paths awaiting the one-time "register?" ask. */
  private candidates: string[] = [];

  constructor(private primaryRoot: string) {
    this.manifestPath = path.join(stateDir('.bimax', primaryRoot), 'workspace.json');
    this.load();
  }

  // ---- persistence -------------------------------------------------------------------

  private load(): void {
    try {
      const m = JSON.parse(fs.readFileSync(this.manifestPath, 'utf8')) as Manifest;
      if (Array.isArray(m.repos)) this.repos = this.dedupe(m.repos);
    } catch { /* first run — no manifest yet */ }
  }

  /**
   * Collapse entries that are the same repo under different paths.
   *
   * Preventing new duplicates is not enough: a manifest written before aliases were understood
   * already holds them, and this one did — ~/Bimax and ~/Desktop/Bimax (a symlink to it) were both
   * listed write-scope, so every repo walk counted one checkout twice. Healing on load means the
   * next session is correct without anyone editing JSON by hand.
   *
   * The survivor is the entry whose own path IS the canonical one, so the real location wins over
   * the alias and the stored path stays meaningful. Failing that, the first entry — which for the
   * primary repo is the one `refresh` unshifts.
   */
  private dedupe(repos: WorkspaceRepo[]): WorkspaceRepo[] {
    const byIdentity = new Map<string, WorkspaceRepo>();
    for (const repo of repos) {
      const identity = this.canonical(repo.path);
      const held = byIdentity.get(identity);
      if (!held) { byIdentity.set(identity, repo); continue; }
      if (path.resolve(repo.path) === identity && path.resolve(held.path) !== identity) {
        byIdentity.set(identity, repo);
      }
      Logger.info(`[Workspace] Collapsed duplicate repo entry (same checkout via another path): ${repo.path}`);
    }
    return [...byIdentity.values()];
  }

  private save(): void {
    try {
      fs.mkdirSync(path.dirname(this.manifestPath), { recursive: true });
      const m: Manifest = { version: 1, repos: this.repos };
      fs.writeFileSync(this.manifestPath, JSON.stringify(m, null, 2));
    } catch (e: any) {
      Logger.warn(`[Workspace] Could not save manifest: ${e?.message ?? e}`);
    }
    // Nudge the UI (status-bar repo chip) — lazy require keeps core free of the CLI layer.
    try { require('../engine/events').engineEvents.emit('workspace_changed'); } catch { /* headless-boot ok */ }
  }

  // ---- git helpers (best-effort, never throw) ------------------------------------------

  private gitBranch(repoPath: string): string | undefined {
    try {
      return execFileSync('git', ['-C', repoPath, 'rev-parse', '--abbrev-ref', 'HEAD'],
        { encoding: 'utf8', timeout: 3000, stdio: ['ignore', 'pipe', 'ignore'] }).trim() || undefined;
    } catch { return undefined; }
  }

  private isGitRepo(p: string): boolean {
    try { return fs.existsSync(path.join(p, '.git')); } catch { return false; }
  }

  // ---- session lifecycle ---------------------------------------------------------------

  /**
   * Session start: make sure the primary repo is registered (always writable), refresh
   * branch/lastSynced on every live entry, drop entries whose directory vanished, and scan the
   * primary root's direct children for unregistered clones (they become ask-once candidates).
   */
  public refresh(): void {
    this.repos = this.repos.filter(r => {
      if (fs.existsSync(r.path)) return true;
      Logger.info(`[Workspace] Repo gone from disk, dropping: ${r.path}`);
      return false;
    });

    if (this.isGitRepo(this.primaryRoot) && !this.find(this.primaryRoot)) {
      this.repos.unshift({
        path: this.primaryRoot,
        name: path.basename(this.primaryRoot),
        purpose: 'primary project',
        scope: 'write',
        registeredAt: new Date().toISOString(),
      });
    }

    const now = new Date().toISOString();
    for (const r of this.repos) {
      if (r.scope === 'ignored') continue;
      const b = this.gitBranch(r.path);
      if (b) { r.branch = b; r.lastSynced = now; }
    }

    this.scan(this.primaryRoot);
    this.save(); // entries and branch refresh both worth persisting
  }

  /** Scan a directory's direct children for git repos not yet registered/ignored. */
  public scan(dir: string): string[] {
    try {
      for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
        if (!entry.isDirectory() || entry.name.startsWith('.') || entry.name === 'node_modules') continue;
        const full = path.join(dir, entry.name);
        if (full === this.primaryRoot) continue;
        if (this.isGitRepo(full) && !this.find(full) && !this.candidates.some(c => this.canonical(c) === this.canonical(full))) {
          this.candidates.push(full);
        }
      }
    } catch { /* unreadable dir — nothing to scan */ }
    return [...this.candidates];
  }

  /**
   * Sniff a completed shell command for `git clone`; a clone's target directory becomes an
   * ask-once registration candidate. Called by BashTool/GitTool after successful execution.
   */
  public noticeCommand(command: string, cwd: string): void {
    const m = /git\s+clone\s+(?:-[-\w=]+\s+)*(\S+?)(?:\.git)?(?:\s+(\S+))?\s*(?:$|[;&|])/.exec(command);
    if (!m) return;
    const target = m[2] && !m[2].startsWith('-')
      ? m[2]
      : path.basename(m[1].replace(/\.git$/, '').replace(/\/+$/, ''));
    const full = path.resolve(cwd, target);
    // The clone may still be settling; only queue when it really landed as a repo.
    if (this.isGitRepo(full) && !this.find(full) && !this.candidates.includes(full)) {
      this.candidates.push(full);
      Logger.info(`[Workspace] Detected fresh clone: ${full} — awaiting registration decision.`);
    }
  }

  // ---- registration --------------------------------------------------------------------

  /**
   * One repo, one identity — even when reached through a symlink.
   *
   * `path.resolve` normalises `..` and relative segments but does NOT follow symlinks, so a repo
   * opened as ~/Desktop/Bimax and the same repo opened as ~/Bimax registered as two separate
   * write-scope repos. Observed live: workspace.json listed both, and everything that iterates repos
   * — the drives measurement, scope checks, clone candidates — then did it twice for one checkout.
   * That is not hypothetical here; ~/Desktop/Bimax has been a symlink to ~/Bimax since 2026-09-14.
   *
   * realpath is the identity, with `path.resolve` as the fallback: a path that does not exist yet
   * (a clone still settling, a scope set ahead of time) cannot be realpath'd and must not throw.
   */
  private canonical(repoPath: string): string {
    const resolved = path.resolve(this.primaryRoot, repoPath);
    try {
      return fs.realpathSync(resolved);
    } catch {
      return resolved;
    }
  }

  /**
   * The same identity rule for a FILE path, including one that does not exist yet.
   *
   * realpath needs the target to exist, and the common case here is a write CREATING a file — so the
   * directory is canonicalised (it exists) and the basename rejoined. Without this, a read-only repo
   * reached through a symlinked alias matched no registered root at all, fell through to the
   * additive "not in any repo, allow" default, and its read-only scope was simply bypassed.
   *
   * Both sides of the containment test are canonicalised, so this only ever makes the match MORE
   * accurate: an alias now resolves onto the repo that actually governs it. It does not widen what
   * is writable — a path outside every registered repo is still allowed, exactly as before.
   */
  private canonicalFile(filePath: string): string {
    const resolved = path.resolve(filePath);
    try {
      return fs.realpathSync(resolved);
    } catch { /* does not exist yet — canonicalise the directory instead */ }
    try {
      return path.join(fs.realpathSync(path.dirname(resolved)), path.basename(resolved));
    } catch {
      return resolved;
    }
  }

  public find(repoPath: string): WorkspaceRepo | undefined {
    const norm = this.canonical(repoPath);
    return this.repos.find(r => this.canonical(r.path) === norm);
  }

  public register(repoPath: string, opts?: { purpose?: string; scope?: RepoScope; name?: string }): WorkspaceRepo {
    const full = this.canonical(repoPath);
    const existing = this.find(full);
    if (existing) {
      if (opts?.purpose) existing.purpose = opts.purpose;
      if (opts?.scope) existing.scope = opts.scope;
      if (opts?.name) existing.name = opts.name;
      this.save();
      return existing;
    }
    const repo: WorkspaceRepo = {
      path: full,
      name: opts?.name || path.basename(full),
      purpose: opts?.purpose,
      branch: this.gitBranch(full),
      lastSynced: new Date().toISOString(),
      scope: opts?.scope || 'read', // joins read-only unless the user says otherwise
      registeredAt: new Date().toISOString(),
    };
    this.repos.push(repo);
    this.candidates = this.candidates.filter(c => this.canonical(c) !== full);
    this.save();
    return repo;
  }

  /** The ask-once "no": remembered in the manifest so the repo is never suggested again. */
  public ignore(repoPath: string): void {
    const full = this.canonical(repoPath);
    const existing = this.find(full);
    if (existing) existing.scope = 'ignored';
    else this.repos.push({
      path: full, name: path.basename(full), scope: 'ignored', registeredAt: new Date().toISOString(),
    });
    this.candidates = this.candidates.filter(c => this.canonical(c) !== full);
    this.save();
  }

  public setScope(repoPath: string, scope: RepoScope): WorkspaceRepo | undefined {
    const r = this.find(repoPath);
    if (r) { r.scope = scope; this.save(); }
    return r;
  }

  // ---- queries ---------------------------------------------------------------------------

  /** Registered, non-ignored repos (primary first). */
  public active(): WorkspaceRepo[] {
    return this.repos.filter(r => r.scope !== 'ignored');
  }

  /** Absolute path of the primary project repo (the always-writable one this session opened in). */
  public primaryPath(): string { return this.primaryRoot; }

  /** Fresh clones awaiting the one-time registration ask. */
  public pending(): string[] { return [...this.candidates]; }

  /**
   * Per-repo edit scoping. Purely additive: paths not under ANY registered repo keep today's
   * behavior (allowed). A write landing inside a repo registered read-only is refused with
   * guidance, so "adapt the pattern from repo Y into repo X" edits X, quotes Y — never the
   * reverse by accident.
   */
  public checkWrite(filePath: string): { allowed: boolean; reason?: string } {
    const full = this.canonicalFile(filePath);
    // The INNERMOST containing repo governs scope: a read-only repo nested inside the
    // writable primary (a clone landed in a subdir) must win over the primary, or its
    // files would be writable because the primary's root prefix-matches first. Pick the
    // repo with the longest matching root, not the first in iteration order.
    let best: WorkspaceRepo | undefined;
    let bestLen = -1;
    for (const r of this.active()) {
      const root = this.canonical(r.path);
      if ((full === root || full.startsWith(root + path.sep)) && root.length > bestLen) {
        best = r;
        bestLen = root.length;
      }
    }
    if (!best || best.scope === 'write') return { allowed: true };
    return {
      allowed: false,
      reason: `${best.name} is registered READ-ONLY in this workspace (reference repo). ` +
        `Quote/adapt its code into a writable repo instead — or, if the user explicitly asked to modify ${best.name}, ` +
        `unlock it first with WorkspaceTool {action:"scope", path:"${best.path}", scope:"write"}.`,
    };
  }

  /** System-prompt block: the model's map of what repos are in context and what it may touch. */
  public contextBlock(): string {
    const act = this.active();
    if (act.length <= 1 && this.candidates.length === 0) return '';
    const lines = act.map(r => {
      const tag = r.scope === 'write' ? 'WRITABLE' : 'read-only';
      return `- ${r.name} (${tag}) at ${r.path}${r.branch ? ` [${r.branch}]` : ''}${r.purpose ? ` — ${r.purpose}` : ''}`;
    });
    let block = `### WORKSPACE (${act.length} repos)\nThis session spans multiple repos. Read/cross-reference freely across all of them; edit only WRITABLE ones. Use absolute paths when working outside the primary repo.\n${lines.join('\n')}`;
    if (this.candidates.length > 0) {
      block += `\nUNREGISTERED CLONES DETECTED: ${this.candidates.join(', ')} — ask the user ONCE whether to add each to the workspace, then call WorkspaceTool {action:"register"|"ignore"}.`;
    }
    return block;
  }

  /** Compact snapshot for the ui_snapshot wire (TUI status chip). */
  public snapshot(): { count: number; names: string[]; writable: number } {
    const act = this.active();
    return {
      count: act.length,
      names: act.map(r => r.name),
      writable: act.filter(r => r.scope === 'write').length,
    };
  }
}

let _ws: WorkspaceManager | null = null;

export function initWorkspace(primaryRoot: string): WorkspaceManager {
  _ws = new WorkspaceManager(primaryRoot);
  _ws.refresh();
  return _ws;
}

export function getWorkspace(): WorkspaceManager {
  if (!_ws) throw new Error('WorkspaceManager not initialized');
  return _ws;
}

/** Best-effort accessor for call sites that must never throw (tools, snapshots). */
export function tryGetWorkspace(): WorkspaceManager | null { return _ws; }

import { execFileSync } from 'child_process';
import * as fs from 'fs';
import * as path from 'path';
import { Logger } from '../utils/logger';

/**
 * Git-worktree isolation for parallel sub-agents (the Cursor 2.0 / Claude Code
 * `isolation: "worktree"` pattern): each isolated agent gets its own checkout of the repo on its
 * own branch under .bimax/worktrees/<taskId>, so parallel agents can never clobber each other's
 * edits. Worktrees share the object store with the main checkout — creating one is near-instant
 * and costs no re-clone.
 *
 * Lifecycle: create → agent works inside it → settle. Settle removes the worktree AND its branch
 * when the agent changed nothing (no dirty files, no commits); otherwise both are kept and the
 * caller surfaces the path + branch so the user (or the orchestrator) can review/merge.
 *
 * Once distinct from evolution/worktree.manager.ts, which served the swarm/evolution waves (async
 * ops serialized because they fired in Promise.all, commit/merge helpers, .evolution_worktrees/).
 * That file and everything that drove it were archived on 2026-09-19 — see
 * docs/product-reset/58 — so this is now the only worktree manager. It is the spawn-path
 * primitive: synchronous
 * (execFileSync blocks the event loop, so calls can never interleave with each other), falls back
 * to unisolated instead of throwing, and detects "did the agent change anything" against the base
 * commit. git arguments are always argv arrays — never shell strings — since taskIds pass through.
 */

export interface WorktreeInfo {
  /** Absolute path of the worktree checkout the agent should use as cwd. */
  path: string;
  /** The branch created for this worktree (bimax/sub-…). */
  branch: string;
  /** Commit the worktree was created from — the baseline for "did anything change?". */
  baseCommit: string;
  /** The main checkout the worktree belongs to (where `git worktree` bookkeeping lives). */
  repoRoot: string;
}

export interface WorktreeSettle {
  /** True when the worktree was deleted (agent changed nothing). */
  removed: boolean;
  /** True when edits or commits were found and the worktree/branch were kept. */
  changed: boolean;
  /** Human-readable note for the sub-agent result ('' when removed cleanly). */
  note: string;
}

export interface WorktreeIntegration {
  commit: string;
  paths: string[];
  integratedAt: number;
  cleanedUp: boolean;
}

/** Exact paths changed from the worktree's clean base. Throws when inspection is unavailable. */
export function inspectWorktreeChanges(info: WorktreeInfo): string[] {
  const committed = git(info.path, 'diff', '--name-only', `${info.baseCommit}...HEAD`).split('\n');
  // Do not parse porcelain through git(): its intentional trim removes the leading status column
  // (` M src/a.ts` -> `M src/a.ts`) and silently chopped the first character from paths. Diff and
  // ls-files return path-only records, covering staged/unstaged tracked files plus untracked files.
  const dirty = git(info.path, 'diff', '--name-only', 'HEAD').split('\n');
  const untracked = git(info.path, 'ls-files', '--others', '--exclude-standard').split('\n');
  return [...new Set([...committed, ...dirty, ...untracked].map(value => value.trim()).filter(Boolean))].sort();
}

/** Legacy best-effort wrapper; coordinated outcome assignments use the fail-closed inspector. */
export function worktreeChangedPaths(info: WorktreeInfo): string[] {
  try { return inspectWorktreeChanges(info); } catch { return []; }
}

/** Validate that a checkpointed worktree still exists and points at the recorded branch/repo. */
export function validateWorktree(info: WorktreeInfo): boolean {
  try {
    const actualRoot = fs.realpathSync(git(info.path, 'rev-parse', '--show-toplevel'));
    const expectedRoot = fs.realpathSync(info.path);
    const actualRepo = fs.realpathSync(git(info.path, 'rev-parse', '--path-format=absolute', '--git-common-dir'));
    const expectedRepo = fs.realpathSync(git(info.repoRoot, 'rev-parse', '--path-format=absolute', '--git-common-dir'));
    const branch = git(info.path, 'rev-parse', '--abbrev-ref', 'HEAD');
    git(info.path, 'cat-file', '-e', `${info.baseCommit}^{commit}`);
    return actualRoot === expectedRoot && actualRepo === expectedRepo && branch === info.branch;
  } catch {
    return false;
  }
}

function git(cwd: string, ...args: string[]): string {
  return execFileSync('git', args, { cwd, encoding: 'utf-8', stdio: ['ignore', 'pipe', 'pipe'] }).trim();
}

function normalizedPaths(values: string[]): string[] {
  return [...new Set(values.map(value => value.trim().replace(/\\/g, '/').replace(/^\.\//, '')).filter(Boolean))].sort();
}

function scopeTokens(scope = ''): string[] {
  return scope.split(/[\s,;]+/).map(value => value.trim().replace(/\\/g, '/').replace(/^\.\//, '').replace(/\/+$/, '')).filter(Boolean);
}

function pathAllowed(relative: string, scope = ''): boolean {
  const tokens = scopeTokens(scope);
  if (tokens.some(token => token === '*' || token === '.' || token.toLowerCase() === 'repo')) return true;
  return tokens.some(token => relative === token || relative.startsWith(`${token}/`));
}

function parentDirtyPaths(repoRoot: string): string[] {
  return normalizedPaths([
    ...git(repoRoot, 'diff', '--name-only', 'HEAD').split('\n'),
    ...git(repoRoot, 'ls-files', '--others', '--exclude-standard').split('\n'),
  ]);
}

/**
 * Integrate one reviewed isolated assignment into its parent checkout. The operation fails closed:
 * the worktree manifest must still match the receipt, every path must fit the assignment scope,
 * and neither committed nor uncommitted parent work may overlap those paths. Merge conflicts are
 * aborted and the worktree is retained for review. Cleanup happens only after byte-for-byte parent
 * verification, so an integration receipt can never describe work that was merely attempted.
 */
export function integrateWorktree(
  info: WorktreeInfo,
  expectedPaths: string[],
  scope: string,
  taskId: string,
): WorktreeIntegration {
  const expected = normalizedPaths(expectedPaths);
  if (expected.length === 0) throw new Error(`Task ${taskId} has no changed files to integrate.`);
  const current = inspectWorktreeChanges(info);
  if (JSON.stringify(current) !== JSON.stringify(expected)) {
    throw new Error(`Task ${taskId}'s worktree changed after settlement; review it again before integration.`);
  }
  const outside = expected.filter(relative => !pathAllowed(relative, scope));
  if (outside.length) throw new Error(`Task ${taskId} changed files outside its scope (${scope || 'unscoped'}): ${outside.join(', ')}`);

  const dirtyOverlap = parentDirtyPaths(info.repoRoot).filter(relative => expected.includes(relative));
  if (dirtyOverlap.length) throw new Error(`Parent checkout has uncommitted changes overlapping task ${taskId}: ${dirtyOverlap.join(', ')}`);
  const parentCommittedOverlap = normalizedPaths(git(info.repoRoot, 'diff', '--name-only', `${info.baseCommit}...HEAD`).split('\n'))
    .filter(relative => expected.includes(relative));
  if (parentCommittedOverlap.length) {
    throw new Error(`Parent branch changed task ${taskId}'s files since assignment: ${parentCommittedOverlap.join(', ')}`);
  }

  // Capture dirty worker edits in an engine-authored commit. Local -c identity avoids mutating the
  // user's repository configuration while still working in fresh repositories.
  if (git(info.path, 'status', '--porcelain')) {
    git(info.path, 'add', '--all');
    git(info.path, '-c', 'user.name=Bimax', '-c', 'user.email=bimax@local', 'commit', '-m', `bimax: integrate ${taskId}`);
  }
  const workerCommit = git(info.path, 'rev-parse', 'HEAD');
  try {
    git(info.repoRoot, '-c', 'user.name=Bimax', '-c', 'user.email=bimax@local', 'merge', '--no-ff', '--no-edit', info.branch);
  } catch (error: any) {
    try { git(info.repoRoot, 'merge', '--abort'); } catch { /* merge may have failed before starting */ }
    throw new Error(`Task ${taskId} could not be merged safely: ${error?.message?.split('\n')[0] || error}`, { cause: error });
  }

  const mismatches = expected.filter(relative => {
    const parentFile = path.join(info.repoRoot, relative);
    const workerFile = path.join(info.path, relative);
    const parentExists = fs.existsSync(parentFile);
    const workerExists = fs.existsSync(workerFile);
    if (parentExists !== workerExists) return true;
    if (!parentExists) return false;
    try { return !fs.readFileSync(parentFile).equals(fs.readFileSync(workerFile)); }
    catch { return true; }
  });
  if (mismatches.length) {
    throw new Error(`Task ${taskId} merged but parent verification differs for: ${mismatches.join(', ')}`);
  }

  let cleanedUp = true;
  try {
    git(info.repoRoot, 'worktree', 'remove', '--force', info.path);
    git(info.repoRoot, 'branch', '-D', info.branch);
  } catch (error: any) {
    cleanedUp = false;
    Logger.warn(`[Worktree] Integrated task ${taskId}, but cleanup failed: ${error?.message?.split('\n')[0]}`);
  }
  return { commit: workerCommit, paths: expected, integratedAt: Date.now(), cleanedUp };
}

/**
 * Create an isolated worktree for a task. Returns null (with a warning) when the cwd isn't a git
 * repo or creation fails — callers fall back to running the sub-agent unisolated, which is the
 * pre-worktree behavior, never a hard failure.
 */
export function createWorktree(cwd: string, taskId: string): WorktreeInfo | null {
  try {
    const repoRoot = git(cwd, 'rev-parse', '--show-toplevel');
    const baseCommit = git(repoRoot, 'rev-parse', 'HEAD');
    // taskId is "subagent-<uuid>" — the uuid tail keeps branch/dir names short but unique.
    const shortId = taskId.replace(/^subagent-/, '').slice(0, 8) || taskId;
    const branch = `bimax/sub-${shortId}`;
    const wtPath = path.join(repoRoot, '.bimax', 'worktrees', shortId);
    git(repoRoot, 'worktree', 'add', '-b', branch, wtPath, 'HEAD');
    Logger.info(`[Worktree] Created ${wtPath} (branch ${branch}) for ${taskId}`);
    return { path: wtPath, branch, baseCommit, repoRoot };
  } catch (e: any) {
    Logger.warn(`[Worktree] Could not create worktree for ${taskId}: ${e?.message?.split('\n')[0]} — running unisolated.`);
    return null;
  }
}

/**
 * Settle a worktree after its agent finished: remove it (and its branch) when nothing changed,
 * keep both and describe them when something did.
 */
export function settleWorktree(info: WorktreeInfo): WorktreeSettle {
  let changed: boolean;
  try {
    const dirty = git(info.path, 'status', '--porcelain');
    const head = git(info.path, 'rev-parse', 'HEAD');
    changed = dirty.length > 0 || head !== info.baseCommit;
  } catch {
    // Worktree already gone (agent or user deleted it) — treat as settled.
    try { git(info.repoRoot, 'worktree', 'prune'); } catch { /* best-effort */ }
    return { removed: true, changed: false, note: '' };
  }

  if (changed) {
    return {
      removed: false,
      changed: true,
      note: `Worktree kept — the sub-agent made changes in ${info.path} on branch ${info.branch}. Review and merge (or discard with \`git worktree remove --force ${info.path}\`).`,
    };
  }

  try {
    git(info.repoRoot, 'worktree', 'remove', '--force', info.path);
    git(info.repoRoot, 'branch', '-D', info.branch);
    Logger.info(`[Worktree] Removed unchanged worktree ${info.path}`);
  } catch (e: any) {
    Logger.warn(`[Worktree] Cleanup of ${info.path} failed: ${e?.message?.split('\n')[0]}`);
  }
  return { removed: true, changed: false, note: '' };
}

import { Logger } from '../utils';
import { waitWithSignal } from '../utils/request.deadline';
import { Mutex } from 'async-mutex';
import { KeyUsage, KeyUsageStore, RPM_WINDOW_MS, keyId, resolveKeyUsageStore } from './key.usage.ledger';

export interface KeyConfig {
  keyStr: string;
  model?: string;
  baseURL?: string;
  provider?: string;
  label?: string;
  /**
   * The provider's per-key request limit, per minute, shared by every engine on the Mac (0 or
   * absent = no known limit; the pool then learns only from 429s).
   */
  rpm?: number;
}

export interface KeyState extends KeyConfig {
  /** Ledger identity: a hash prefix, never the key. */
  id: string;
  /** Starts this process handed out inside the window — the pacing used when the shared ledger is unusable. */
  local_starts: number[];
  cooldown_until: number;
  consecutive_429: number;
  consecutive_403: number;
  consecutive_401: number;
  total_ok: number;
  total_fail: number;
  last_used: number;
  // Latency health (NIM free-tier keys get server-side queued INDIVIDUALLY — one key answers in
  // 1s while a sibling takes 40s or hangs, so rotation must be latency-aware, not blind RR).
  ewma_first_ms: number; // time-to-first-token EWMA; 0 = no data yet
  hang_strikes: number;  // consecutive first-token timeouts — benched with growing cooldowns
}

export interface KeyResult {
  keyStr: string | null;
  model: string | null;
  baseURL: string | null;
  provider: string | null;
  idx: number | null;
  waitTimeSecs: number;
}

export interface ApiKeyManagerOptions {
  /** Shared per-key request ledger. Defaults to the machine-wide file (see key.usage.ledger.ts). */
  store?: KeyUsageStore;
  /** Clock, epoch ms. Injected by tests. */
  now?: () => number;
}

export class ApiKeyManager {
  private keyStates: KeyState[] = [];
  private keyRR: number = 0;
  private readonly store: KeyUsageStore;
  private readonly clock: () => number;

  private readonly KEY_COOLDOWN_BASE = 2.0;
  private readonly KEY_COOLDOWN_MAX = 60.0;
  private readonly KEY_COOLDOWN_JITTER = 1.0;
  // RPM pacing: with SEVERAL keys in the pool, avoid re-using the same key within this window when
  // a colder sibling is available — a burst of calls then fans out across the whole pool instead of
  // hammering one key into its per-key RPM limit and eating a 429 + cooldown. With a single key this
  // never applies (nothing to prefer), so solo setups see zero added latency. Seconds.
  private readonly MIN_REUSE_SECS = Math.max(0, (parseInt(process.env.BIMAX_KEY_MIN_INTERVAL_MS || '1100', 10) || 0) / 1000);

  constructor(keys: KeyConfig[], options: ApiKeyManagerOptions = {}) {
    this.store = options.store ?? resolveKeyUsageStore();
    this.clock = options.now ?? Date.now;
    this.setKeys(keys);
  }

  /**
   * Replace the key pool in place (e.g. after /keys adds a key mid-session — previously a new key
   * only took effect after a restart). Health state is preserved for keys that survive the rebuild,
   * so a key on 429 cooldown doesn't get a clean slate just because a sibling was added.
   */
  public setKeys(keys: KeyConfig[]): void {
    const prior = new Map(this.keyStates.map(s => [s.keyStr, s]));
    const uniqueKeys = new Map<string, KeyConfig>();
    for (const k of keys) {
      if (!uniqueKeys.has(k.keyStr)) uniqueKeys.set(k.keyStr, k);
    }
    this.keyStates = Array.from(uniqueKeys.values()).map(k => {
      const old = prior.get(k.keyStr);
      return {
        ...k,
        id: keyId(k.keyStr),
        local_starts: old?.local_starts ?? [],
        cooldown_until: old?.cooldown_until ?? 0.0,
        consecutive_429: old?.consecutive_429 ?? 0,
        consecutive_403: old?.consecutive_403 ?? 0,
        consecutive_401: old?.consecutive_401 ?? 0,
        total_ok: old?.total_ok ?? 0,
        total_fail: old?.total_fail ?? 0,
        last_used: old?.last_used ?? 0,
        ewma_first_ms: old?.ewma_first_ms ?? 0,
        hang_strikes: old?.hang_strikes ?? 0,
      };
    });
    // Start the rotation at a random index: N parallel sub-agent workers each build their OWN
    // manager over the same pool, and a deterministic start had them all piling onto key #1.
    this.keyRR = this.keyStates.length > 0
      ? (this.keyRR || Math.floor(Math.random() * this.keyStates.length)) % this.keyStates.length
      : 0;
    const limits = Array.from(new Set(this.keyStates.map(s => s.rpm || 0)));
    const rpmNote = limits.length === 1 && limits[0] > 0 ? `, ${limits[0]} requests/min each` : '';
    Logger.info(`[ApiKeyManager] Key pool set: ${this.keyStates.length} key(s) across ${new Set(keys.map(k => k.provider || 'unknown')).size} provider(s)${rpmNote}.`);
  }

  private mutex = new Mutex();

  /**
   * The hybrid round robin. Every call walks the pool in rotation order and considers only keys
   * that are usable right now: off this process's cooldown, off any cooldown another engine
   * recorded for the key, and under the key's requests-per-minute limit counted across EVERY
   * engine on the Mac. Among those it prefers, in order:
   *   1. a key not used in the last MIN_REUSE_SECS (a burst fans out across the pool instead of
   *      hammering one key into its limit), then
   *   2. the lowest measured time-to-first-token, weighted up by how much of its minute the key
   *      has already spent — NIM free-tier keys are queued individually server-side (1s on one
   *      key, 40s on a sibling), so blind rotation kept walking calls into the slow lane.
   * Ties go to rotation order. When no key is usable, nothing is reserved and `waitTimeSecs`
   * says when the earliest one frees; the caller waits and asks again.
   */
  public async getNextKey(options: { exclude?: number } = {}): Promise<KeyResult> {
    return await this.mutex.runExclusive(async () => {
      if (this.keyStates.length === 0) return { keyStr: null, model: null, baseURL: null, provider: null, idx: null, waitTimeSecs: 0 };

      const nowMs = this.clock();
      let pickedIdx = -1;
      let seen = new Map<string, KeyUsage>();
      const choose = (usage: Map<string, KeyUsage>): string | null => {
        seen = usage;
        pickedIdx = this.choose(usage, nowMs, options.exclude);
        return pickedIdx >= 0 ? this.keyStates[pickedIdx].id : null;
      };
      try {
        this.store.reserve(this.keyStates.map(s => s.id), nowMs, choose);
      } catch (e: any) {
        // The shared ledger is unusable (disk full, a lock held by a dead process past its stale
        // window). Pace from this process's own memory — the pre-ledger behaviour — rather than
        // refuse a turn over bookkeeping.
        Logger.warn(`[ApiKeyManager] shared key ledger unavailable (${e?.message || e}); pacing this engine alone.`);
        choose(this.localUsage(nowMs));
      }

      if (pickedIdx >= 0) {
        const state = this.keyStates[pickedIdx];
        this.keyRR = (pickedIdx + 1) % this.keyStates.length;
        state.last_used = nowMs / 1000;
        state.local_starts = state.local_starts.filter(t => nowMs - t < RPM_WINDOW_MS);
        state.local_starts.push(nowMs);
        return { keyStr: state.keyStr, model: state.model || null, baseURL: state.baseURL || null, provider: state.provider || null, idx: pickedIdx, waitTimeSecs: 0 };
      }

      // Nothing usable: report the key that frees soonest, and when. Not reserved — the caller
      // must come back, because by then a different key may be the better pick.
      let soonIdx = 0;
      let soonest = Infinity;
      for (let idx = 0; idx < this.keyStates.length; idx++) {
        const freeAt = this.freeAt(this.keyStates[idx], seen.get(this.keyStates[idx].id), nowMs);
        if (freeAt < soonest) { soonest = freeAt; soonIdx = idx; }
      }
      const s = this.keyStates[soonIdx];
      return { keyStr: s.keyStr, model: s.model || null, baseURL: s.baseURL || null, provider: s.provider || null, idx: soonIdx, waitTimeSecs: Math.max(0, (soonest - nowMs) / 1000) };
    });
  }

  /**
   * A key that is usable now, waiting — for at most `maxWaitMs` — while every key is cooling down
   * or at its per-minute limit. Each wake asks the pool again, because the key that frees first is
   * not necessarily the one to use (another engine may have taken it, or a faster one freed).
   *
   * Stops waiting early when every key has failed authentication: that can never clear by itself.
   * Past the budget it returns the soonest key anyway and lets the provider answer, so a
   * misconfigured limit can slow a turn but never wedge it.
   */
  public async acquire(options: {
    maxWaitMs?: number;
    signal?: AbortSignal;
    sleep?: (ms: number) => Promise<void>;
    onWait?: (waitSecs: number) => void;
  } = {}): Promise<KeyResult> {
    options.signal?.throwIfAborted();
    const maxWaitMs = options.maxWaitMs ?? 120_000;
    const sleep = options.sleep ?? (options.signal
      ? (ms: number) => waitWithSignal(ms, options.signal!)
      : (ms: number) => new Promise<void>(resolve => setTimeout(resolve, ms)));
    const started = this.clock();
    let kr = await this.getNextKey();
    options.signal?.throwIfAborted();
    while (kr.keyStr && kr.waitTimeSecs > 0 && !this.allKeysAuthDead()) {
      const remaining = maxWaitMs - (this.clock() - started);
      if (remaining <= 0) break;
      options.onWait?.(kr.waitTimeSecs);
      // Never sleep less than a beat: a slot that frees "in 0.001s" would otherwise spin the loop.
      await sleep(Math.max(50, Math.min(kr.waitTimeSecs * 1000, remaining)));
      options.signal?.throwIfAborted();
      kr = await this.getNextKey();
      options.signal?.throwIfAborted();
    }
    return kr;
  }

  /**
   * Index of the key to use now, or -1 when every key is cooling down or at its limit. `exclude` is a
   * key that must not be picked — the one a hedged request is already waiting on.
   */
  private choose(usage: Map<string, KeyUsage>, nowMs: number, exclude?: number): number {
    const n = this.keyStates.length;
    const now = nowMs / 1000;
    const known = this.keyStates.filter(s => s.ewma_first_ms > 0).map(s => s.ewma_first_ms).sort((a, b) => a - b);
    const median = known.length ? known[Math.floor(known.length / 2)] : 1000;
    let bestIdx = -1;
    let bestScore = Infinity;
    for (let i = 0; i < n; i++) {
      const idx = (this.keyRR + i) % n;
      if (idx === exclude) continue;
      const state = this.keyStates[idx];
      const u = usage.get(state.id) ?? { recent: 0, cooldownUntil: 0, starts: [] };
      if (now < state.cooldown_until || u.cooldownUntil > nowMs) continue;
      const rpm = state.rpm || 0;
      if (rpm > 0 && u.recent >= rpm) continue;
      const latency = state.ewma_first_ms > 0 ? state.ewma_first_ms : median;
      const load = rpm > 0 ? u.recent / rpm : 0;
      const warm = n > 1 && this.MIN_REUSE_SECS > 0 && now - state.last_used < this.MIN_REUSE_SECS;
      const score = (warm ? 1e12 : 0) + latency * (1 + load);
      if (score < bestScore) {
        bestScore = score;
        bestIdx = idx;
      }
    }
    return bestIdx;
  }

  /** Epoch ms at which this key next becomes usable. */
  private freeAt(state: KeyState, u: KeyUsage | undefined, nowMs: number): number {
    let at = Math.max(nowMs, state.cooldown_until * 1000, u?.cooldownUntil ?? 0);
    const rpm = state.rpm || 0;
    if (rpm > 0 && u && u.recent >= rpm) at = Math.max(at, u.starts[u.recent - rpm] + RPM_WINDOW_MS);
    return at;
  }

  private localUsage(nowMs: number): Map<string, KeyUsage> {
    return new Map(this.keyStates.map(s => {
      const starts = s.local_starts.filter(t => nowMs - t < RPM_WINDOW_MS).sort((a, b) => a - b);
      return [s.id, { recent: starts.length, cooldownUntil: 0, starts }];
    }));
  }

  /** Tell every other engine on the Mac that a provider asked for this key to be left alone. */
  private shareCooldown(s: KeyState, untilSecs: number): void {
    try { this.store.cooldown(s.id, untilSecs * 1000, this.clock()); } catch { /* local cooldown still applies */ }
  }

  public reportKeyResult(idx: number, status: number, retryAfterSecs: number | null = null): void {
    const now = this.clock() / 1000;
    const s = this.keyStates[idx];
    if (!s) return;

    // Status 0 = the failure was LOCAL (DNS, socket, connect) — the provider never saw the
    // request, so the key is not to blame. Neutral: no health counters, no cooldown. Billing
    // the machine's network to the key is how one blip snowballed into a benched pool.
    if (status === 0) return;

    if (status >= 200 && status < 300) {
      s.total_ok++;
      s.consecutive_429 = 0;
      s.consecutive_403 = 0;
      s.consecutive_401 = 0;
      s.cooldown_until = 0.0;
      return;
    }

    s.total_fail++;

    if (status === 429) {
      s.consecutive_429++;
      const cooldown = retryAfterSecs ?? Math.min(this.KEY_COOLDOWN_BASE * Math.pow(2, s.consecutive_429 - 1), this.KEY_COOLDOWN_MAX);
      const jitter = Math.random() * this.KEY_COOLDOWN_JITTER;
      s.cooldown_until = now + cooldown + jitter;
      this.shareCooldown(s, s.cooldown_until);
      Logger.warn(`[ApiKeyManager] KEY #${idx + 1} (${s.label || s.provider || '?'}) -> 429 cooldown ${cooldown.toFixed(1)}s`);
    } else if (status === 403) {
      s.consecutive_403++;
      s.cooldown_until = now + 2.0;
    } else if (status === 401) {
      s.consecutive_401++;
      s.cooldown_until = now + 5.0;
    } else if (status === 408) {
      s.cooldown_until = now + 2.0;
    } else if (status === 502 || status === 504) {
      s.cooldown_until = now + 2.0;
    } else if (status >= 500) {
      s.cooldown_until = now + 3.0;
    }
  }

  /**
   * Feed back a successful call's time-to-first-token so the picker can prefer fast keys.
   * EWMA (α=0.3) smooths jitter; a success also clears the hang bench.
   */
  public reportKeyLatency(idx: number, firstTokenMs: number): void {
    const s = this.keyStates[idx];
    if (!s || !(firstTokenMs > 0)) return;
    s.ewma_first_ms = s.ewma_first_ms > 0 ? Math.round(0.7 * s.ewma_first_ms + 0.3 * firstTokenMs) : Math.round(firstTokenMs);
    s.hang_strikes = 0;
  }

  /**
   * A first-token timeout on this key — the provider is queueing/hanging it server-side. Bench it
   * with a growing cooldown (45s → 90s → 3min → capped 10min) so rotation stops feeding the dead
   * lane; a later success clears the strikes (reportKeyLatency).
   */
  public reportKeyHang(idx: number): void {
    const now = this.clock() / 1000;
    const s = this.keyStates[idx];
    if (!s) return;
    s.hang_strikes++;
    // Benching exists to steer ROTATION away from a hanging lane. With a single key there is
    // nothing to rotate to — a long bench just converts one stall into minutes of self-inflicted
    // "all keys cooling down" dead time (observed live). Cap the solo-pool bench at 3s.
    const benchSecs = this.keyStates.length === 1
      ? 3
      : Math.min(45 * Math.pow(2, s.hang_strikes - 1), 600);
    s.cooldown_until = Math.max(s.cooldown_until, now + benchSecs);
    if (this.keyStates.length > 1) this.shareCooldown(s, s.cooldown_until);
    // Poison the latency estimate too, so pass-1 stops preferring it even after the bench expires.
    s.ewma_first_ms = Math.max(s.ewma_first_ms, 60_000);
    Logger.warn(`[ApiKeyManager] KEY #${idx + 1} (${s.label || s.provider || '?'}) hung before first token — benched ${benchSecs.toFixed(0)}s (strike ${s.hang_strikes})`);
  }

  /** Pool size — lets the adapter pick a tighter first-token budget when rotation is possible. */
  public size(): number {
    return this.keyStates.length;
  }

  /**
   * True when EVERY key in the pool has most recently failed auth (401/403). Auth failures are
   * permanent for a given key string — sleeping through a cooldown and retrying the same key can
   * never succeed, it just adds dead seconds to every turn. Callers should fail fast with an
   * actionable "fix your key" error instead of waiting. A success resets the counters (see
   * reportKeyResult), so a key fixed mid-session recovers on its next use.
   */
  public allKeysAuthDead(): boolean {
    return this.keyStates.length > 0 &&
      this.keyStates.every(s => s.consecutive_401 > 0 || s.consecutive_403 > 1);
  }

  public getStates() {
    const now = this.clock() / 1000;
    return this.keyStates.map(s => ({
      label: s.label || s.provider || 'key',
      model: s.model || 'default',
      baseURL: s.baseURL || 'default',
      ok: s.total_ok,
      fail: s.total_fail,
      onCooldown: s.cooldown_until > now,
      cooldownSecs: Math.max(0, s.cooldown_until - now),
      firstTokenMs: s.ewma_first_ms,
      hangs: s.hang_strikes,
      rpm: s.rpm || 0,
      lastMinute: s.local_starts.filter(t => this.clock() - t < RPM_WINDOW_MS).length,
    }));
  }
}

import { stateDir } from '../utils/state.dir';
import * as fs from 'fs/promises';
import * as path from 'path';
import { Logger } from '../utils';
import { Mutex } from 'async-mutex';

export class FreeCreditsTracker {
  private dailyQuota = 10;
  private currentUsage = 0;
  private lastResetDate = '';
  private readonly QUOTA_PATH = path.join(stateDir('.breakglass'), 'credits', 'quota.json');
  private mutex = new Mutex();

  constructor() {
    this.loadQuota().catch(() => {});
  }

  private getLocalDate(): string {
    // Returns YYYY-MM-DD in local timezone
    return new Date().toLocaleDateString('en-CA');
  }

  private async loadQuota() {
    return await this.mutex.runExclusive(async () => {
      try {
        const data = await fs.readFile(this.QUOTA_PATH, 'utf-8');
        const payload = JSON.parse(data);

        const today = this.getLocalDate();
        if (payload.lastResetDate === today) {
          this.currentUsage = payload.currentUsage;
          this.lastResetDate = payload.lastResetDate;
        } else {
          // New day, reset quota
          this.currentUsage = 0;
          this.lastResetDate = today;
          await this.saveQuotaInternal();
          Logger.info(`[FreeTier] Local midnight passed. Free quota reset to 0.`);
        }
      } catch (e) {
        // Initialize fresh
        this.lastResetDate = this.getLocalDate();
        await this.saveQuotaInternal();
      }
    });
  }

  private async saveQuotaInternal() {
    try {
      await fs.mkdir(path.dirname(this.QUOTA_PATH), { recursive: true });
      await fs.writeFile(this.QUOTA_PATH, JSON.stringify({
        currentUsage: this.currentUsage,
        lastResetDate: this.lastResetDate
      }, null, 2), 'utf-8');
    } catch (e) {
      Logger.error(`[FreeTier] Failed to write quota to disk.`);
    }
  }

  private async saveQuota() {
    return await this.mutex.runExclusive(async () => {
      await this.saveQuotaInternal();
    });
  }

  async canUseFreeTier(): Promise<boolean> {
    await this.loadQuota(); // ensure state is synced
    return this.currentUsage < this.dailyQuota;
  }

  async recordUsage(): Promise<void> {
    // Check-and-increment must be atomic so concurrent calls cannot both pass the
    // quota check and over-spend. saveQuotaInternal is used (not saveQuota) because
    // the mutex is not reentrant.
    await this.mutex.runExclusive(async () => {
      if (this.currentUsage < this.dailyQuota) {
        this.currentUsage++;
        await this.saveQuotaInternal();
        Logger.info(`[FreeTier] Used 1 free credit. (${this.currentUsage}/${this.dailyQuota} used today)`);
      }
    });
  }

  getRemaining(): number {
    return this.dailyQuota - this.currentUsage;
  }
}

import * as crypto from 'crypto';
import * as fs from 'fs';
import * as os from 'os';
import * as path from 'path';

/**
 * One request ledger per API key for the whole Mac — the shared half of the key pool.
 *
 * THE DEFECT THIS CLOSES. `ApiKeyManager` paced keys with in-memory state only, and every engine
 * builds its own manager: the project window, each live Bimax Thread, and each sub-agent worker
 * (a separate V8 isolate). A provider's per-key limit (NVIDIA's free tier: 40 requests a minute)
 * is a per-KEY budget, so N engines each spending "their" 40 was N×40 against one key — the pool
 * learned about the limit only from the 429s. It is the same shape as the spend ledger
 * (`src/governor/spend.ledger.ts`) and the sub-agent worker cap: a per-machine budget applied
 * per process. This file follows their proven pattern: an O_EXCL lock file, a read-modify-write
 * inside it, an atomic rename.
 *
 * WHAT IS STORED. A 16-hex-character SHA-256 prefix per key, never the key; the start times of
 * requests inside the last minute; and a cooldown a provider imposed (a 429, a hang), so one
 * engine's 429 stops the others from walking into the same wall.
 *
 * FAILURE POLICY. A ledger that cannot be locked or parsed must never stop a turn: the caller
 * falls back to its own in-memory pacing, which is exactly the behaviour before this file existed.
 */

export const KEY_LEDGER_ENV = 'BIMAX_KEY_LEDGER_PATH';
/** The window a provider's "requests per minute" limit is measured over. */
export const RPM_WINDOW_MS = 60_000;

const LOCK_STALE_MS = 5_000;
const LOCK_ATTEMPTS = 40;
/** A key unused for a day is dropped, so a rotated-out key does not live in the file forever. */
const FORGET_AFTER_MS = 24 * 60 * 60 * 1000;

/** The identity a key is recorded under. Irreversible, and short enough that two keys never share it in practice. */
export function keyId(keyStr: string): string {
  return crypto.createHash('sha256').update(keyStr).digest('hex').slice(0, 16);
}

export interface KeyUsage {
  /** Requests started with this key inside the last RPM_WINDOW_MS, by every engine on the Mac. */
  recent: number;
  /** Epoch ms before which a provider asked for this key to be left alone (0 = none). */
  cooldownUntil: number;
  /** Start times inside the window, oldest first — tells the caller when the next slot opens. */
  starts: number[];
}

interface LedgerEntry { starts: number[]; cooldownUntil: number; seen: number }
interface LedgerFile { version: 1; keys: Record<string, LedgerEntry> }

export interface KeyUsageStore {
  /**
   * Atomically read every key's usage, let `choose` pick one of `ids` (or none), and record a
   * request start for the pick. Returns the usage `choose` saw. Throws only when the store is
   * unusable; the caller then paces from memory.
   */
  reserve(ids: string[], now: number, choose: (usage: Map<string, KeyUsage>) => string | null): { picked: string | null; usage: Map<string, KeyUsage> };
  /** Share a provider-imposed cooldown for one key with every engine on the Mac. */
  cooldown(id: string, untilMs: number, now: number): void;
}

/** Usage of one key. Callers prune first, so every start here is inside the window. */
function usageOf(entry: LedgerEntry | undefined, now: number): KeyUsage {
  const starts = [...(entry?.starts ?? [])].sort((a, b) => a - b);
  return { recent: starts.length, cooldownUntil: entry && entry.cooldownUntil > now ? entry.cooldownUntil : 0, starts };
}

function prune(file: LedgerFile, now: number): void {
  for (const [id, entry] of Object.entries(file.keys)) {
    entry.starts = entry.starts.filter((t) => now - t < RPM_WINDOW_MS);
    if (entry.cooldownUntil <= now) entry.cooldownUntil = 0;
    if (entry.starts.length === 0 && entry.cooldownUntil === 0 && now - entry.seen > FORGET_AFTER_MS) delete file.keys[id];
  }
}

function applyReserve(file: LedgerFile, ids: string[], now: number, choose: (usage: Map<string, KeyUsage>) => string | null) {
  prune(file, now);
  const usage = new Map(ids.map((id) => [id, usageOf(file.keys[id], now)]));
  const picked = choose(usage);
  if (picked) {
    const entry = file.keys[picked] ?? (file.keys[picked] = { starts: [], cooldownUntil: 0, seen: now });
    entry.starts.push(now);
    entry.seen = now;
  }
  return { picked, usage };
}

function applyCooldown(file: LedgerFile, id: string, untilMs: number, now: number): void {
  const entry = file.keys[id] ?? (file.keys[id] = { starts: [], cooldownUntil: 0, seen: now });
  entry.cooldownUntil = Math.max(entry.cooldownUntil, untilMs);
  entry.seen = now;
}

/** Process-local store: used when no file is configured, and as the tests' hermetic default. */
export class MemoryKeyUsageStore implements KeyUsageStore {
  private file: LedgerFile = { version: 1, keys: {} };
  reserve(ids: string[], now: number, choose: (usage: Map<string, KeyUsage>) => string | null) {
    return applyReserve(this.file, ids, now, choose);
  }
  cooldown(id: string, untilMs: number, now: number): void {
    applyCooldown(this.file, id, untilMs, now);
  }
}

function sleepSync(ms: number): void {
  try { Atomics.wait(new Int32Array(new SharedArrayBuffer(4)), 0, 0, ms); } catch { /* retry */ }
}

/** Cross-process store: one JSON file, updated under an exclusive lock and replaced atomically. */
export class FileKeyUsageStore implements KeyUsageStore {
  constructor(readonly filePath: string) {}

  private withLock<T>(fn: (file: LedgerFile) => T): T {
    fs.mkdirSync(path.dirname(this.filePath), { recursive: true, mode: 0o700 });
    const lock = `${this.filePath}.lock`;
    let fd: number | null = null;
    for (let attempt = 0; attempt < LOCK_ATTEMPTS; attempt++) {
      try { fd = fs.openSync(lock, 'wx', 0o600); break; } catch (error: any) {
        if (error?.code !== 'EEXIST') throw error;
        try {
          if (Date.now() - fs.statSync(lock).mtimeMs > LOCK_STALE_MS) fs.unlinkSync(lock);
        } catch { /* another process released it */ }
        sleepSync(3);
      }
    }
    if (fd === null) throw new Error('key usage ledger is busy');
    try {
      const file: LedgerFile = { version: 1, keys: {} };
      try {
        const parsed = JSON.parse(fs.readFileSync(this.filePath, 'utf8'));
        if (parsed?.version === 1 && parsed.keys && typeof parsed.keys === 'object') {
          for (const [id, raw] of Object.entries<any>(parsed.keys)) {
            if (!/^[0-9a-f]{16}$/.test(id) || !raw || typeof raw !== 'object') continue;
            file.keys[id] = {
              starts: Array.isArray(raw.starts) ? raw.starts.filter((t: unknown) => typeof t === 'number' && Number.isFinite(t)) : [],
              cooldownUntil: typeof raw.cooldownUntil === 'number' ? raw.cooldownUntil : 0,
              seen: typeof raw.seen === 'number' ? raw.seen : 0,
            };
          }
        }
      } catch { /* absent or corrupt → start empty; losing a minute of pacing is the cheap failure */ }
      const result = fn(file);
      const tmp = `${this.filePath}.tmp-${process.pid}-${crypto.randomBytes(4).toString('hex')}`;
      fs.writeFileSync(tmp, JSON.stringify(file), { encoding: 'utf8', mode: 0o600 });
      fs.renameSync(tmp, this.filePath);
      return result;
    } finally {
      try { fs.closeSync(fd); } catch { /* closed */ }
      try { fs.unlinkSync(lock); } catch { /* released */ }
    }
  }

  reserve(ids: string[], now: number, choose: (usage: Map<string, KeyUsage>) => string | null) {
    return this.withLock((file) => applyReserve(file, ids, now, choose));
  }

  cooldown(id: string, untilMs: number, now: number): void {
    this.withLock((file) => applyCooldown(file, id, untilMs, now));
  }
}

/**
 * The store for this process. The desktop points every engine it spawns at one file in its own
 * data folder; a terminal run shares `~/.breakglass/key-usage.json` (relocated by
 * `BIMAX_BREAKGLASS_DIR`, which is how tests stay off the real home directory).
 */
export function resolveKeyUsageStore(env: NodeJS.ProcessEnv = process.env): KeyUsageStore {
  const explicit = String(env[KEY_LEDGER_ENV] || '').trim();
  if (explicit === 'memory') return new MemoryKeyUsageStore();
  const dir = env.BIMAX_BREAKGLASS_DIR || path.join(os.homedir(), '.breakglass');
  return new FileKeyUsageStore(explicit || path.join(dir, 'key-usage.json'));
}

import { stateDir } from '../utils/state.dir';
import * as fs from 'fs';
import * as path from 'path';

export interface SessionMeta {
  id: string;           // same as the JSONL filename stem
  title: string;        // first user message, truncated
  /** What the session is for, in a few words, named after its first reply (engine/session.summary.ts). */
  summary?: string;
  cwd: string;          // working directory when session started
  startedAt: string;    // ISO
  endedAt?: string;     // ISO — set on shutdown
  messageCount: number;
  tokenEstimate: number;
  goalId?: string;      // active GoalManager goal at session start
  goalTitle?: string;
}


// Resolved lazily: the engine chdir()s to BIMAX_CWD during boot (after some modules load) and
// tests chdir to tmpdirs — a captured-at-import path would write meta into the wrong project.
function metaPath(): string {
  return path.join(stateDir('.breakglass'), 'sessions', 'sessions-meta.jsonl');
}

function readAllMeta(): SessionMeta[] {
  let raw: string;
  try {
    raw = fs.readFileSync(metaPath(), 'utf8');
  } catch {
    return [];   // no file yet — a genuinely empty history
  }
  // Parse per line. A torn or truncated line is the ONLY thing that should be lost: parsing the
  // whole file under one try/catch meant a single bad byte returned [], which silently erased the
  // entire session list (Recents rendered "Nothing yet") AND made updateMeta's findIndex miss every
  // id, so titles and message counts stopped being written and every later session stayed
  // "(no messages yet)" forever. Append-only logs must degrade line by line.
  const out: SessionMeta[] = [];
  for (const line of raw.split('\n')) {
    if (!line.trim()) continue;
    try {
      out.push(JSON.parse(line) as SessionMeta);
    } catch { /* skip the damaged line, keep the history */ }
  }
  return out;
}

function appendMeta(meta: SessionMeta): void {
  try {
    const p = metaPath();
    fs.mkdirSync(path.dirname(p), { recursive: true });
    fs.appendFileSync(p, JSON.stringify(meta) + '\n', 'utf8');
  } catch { /* best-effort */ }
}

function updateMeta(id: string, updates: Partial<SessionMeta>): void {
  try {
    const all = readAllMeta();
    const idx = all.findIndex(m => m.id === id);
    if (idx === -1) return;
    all[idx] = { ...all[idx], ...updates };
    // Write through a temp file and rename. A full-file writeFileSync here races appendMeta (and a
    // second engine process), and an interrupted one leaves a half-written line that used to poison
    // every later read. rename(2) is atomic on the same filesystem, so a reader sees either the old
    // file or the new one — never a torn one.
    const p = metaPath();
    const tmp = `${p}.${process.pid}.tmp`;
    fs.mkdirSync(path.dirname(p), { recursive: true });
    fs.writeFileSync(tmp, all.map(m => JSON.stringify(m)).join('\n') + '\n', 'utf8');
    fs.renameSync(tmp, p);
  } catch { /* best-effort */ }
}

// --- Module-level session tracker ---

let _current: SessionMeta | null = null;

// Progress writes are debounced so a long session doesn't trigger O(n) JSONL rewrites on
// every assistant message. The timer fires 10s after the last update; endSessionMeta() always
// flushes immediately regardless.
let _progressTimer: ReturnType<typeof setTimeout> | null = null;

function scheduleProgressFlush(): void {
  if (_progressTimer) return;
  _progressTimer = setTimeout(() => {
    _progressTimer = null;
    if (_current) updateMeta(_current.id, { messageCount: _current.messageCount, tokenEstimate: _current.tokenEstimate });
  }, 10_000);
  // A pending flush must never hold the engine process open after stdin closes.
  (_progressTimer as any).unref?.();
}

/** Flush the debounced progress write immediately (shutdown paths and tests). */
export function flushSessionMeta(): void {
  if (!_current) return;
  if (_progressTimer) { clearTimeout(_progressTimer); _progressTimer = null; }
  updateMeta(_current.id, { messageCount: _current.messageCount, tokenEstimate: _current.tokenEstimate });
}

/** Called at session start (in FullScreen after sessionRef.init()). */
export function startSessionMeta(sessionId: string, cwd: string, goalId?: string, goalTitle?: string): void {
  _current = {
    id: sessionId,
    title: '(no messages yet)',
    cwd,
    startedAt: new Date().toISOString(),
    messageCount: 0,
    tokenEstimate: 0,
    goalId,
    goalTitle,
  };
  appendMeta(_current);
}

/** Called when the first user message arrives — sets the session title. Returns true if it did. */
export function recordFirstUserMessage(text: string): boolean {
  if (!_current || _current.title !== '(no messages yet)') return false;
  _current.title = text.replace(/\s+/g, ' ').trim().slice(0, 80);
  updateMeta(_current.id, { title: _current.title });
  return true;
}

/**
 * Point the tracker at an EXISTING session (true resume: the thread continues in its own record).
 * Reuses the on-disk record when present; a session that predates meta tracking gets a new record
 * so it appears in lists from now on. Clears endedAt — the thread is live again.
 */
export function resumeSessionMeta(id: string, fallbackTitle?: string): void {
  const existing = readAllMeta().find(m => m.id === id);
  if (existing) {
    _current = { ...existing, endedAt: undefined };
    updateMeta(id, { endedAt: undefined });
  } else {
    _current = {
      id,
      title: (fallbackTitle || '').replace(/\s+/g, ' ').trim().slice(0, 80) || '(no messages yet)',
      cwd: process.cwd(),
      startedAt: new Date().toISOString(),
      messageCount: 0,
      tokenEstimate: 0,
    };
    appendMeta(_current);
  }
}

/** Called on each assistant message — keeps message count and token estimate current. */
export function recordSessionProgress(messageCount: number, tokenEstimate: number): void {
  if (!_current) return;
  _current.messageCount = messageCount;
  _current.tokenEstimate = tokenEstimate;
  scheduleProgressFlush();
}

/** Called on shutdown — flushes any pending progress and marks the session as ended. */
export function endSessionMeta(): void {
  if (!_current) return;
  if (_progressTimer) { clearTimeout(_progressTimer); _progressTimer = null; }
  updateMeta(_current.id, {
    messageCount: _current.messageCount,
    tokenEstimate: _current.tokenEstimate,
    endedAt: new Date().toISOString(),
  });
  _current = null;
}

export function getCurrentSessionId(): string | null {
  return _current?.id ?? null;
}

/** The session being recorded, as a copy, or null before the first message. */
export function currentSessionMeta(): SessionMeta | null {
  return _current ? { ..._current } : null;
}

/**
 * Name a session by what it is for (engine/session.summary.ts). Written to the record even when the
 * tracker has moved on to another session — the title arrives a model call later. Returns whether a
 * record took it.
 */
export function recordSessionSummary(id: string, summary: string): boolean {
  const text = summary.replace(/\s+/g, ' ').trim().slice(0, 64);
  if (!id || !text) return false;
  if (_current?.id === id) _current.summary = text;
  if (!readAllMeta().some(m => m.id === id)) return false;
  updateMeta(id, { summary: text });
  return true;
}

/** Returns the most recent N session metadata records, newest first. */
export function listSessionMeta(n = 40): SessionMeta[] {
  return readAllMeta().reverse().slice(0, n);
}

import * as fs from 'fs';
import * as path from 'path';
import { readPdf, extractTextLayer, hasTextLayer } from './pdf.raster';
import { ocrPages } from './ocr';

/**
 * Universal text extraction with provenance.
 *
 * The Composer's premise is that a user drops *whatever they have* — a scanned inspection report, a
 * vendor quote, a spreadsheet of thickness readings, a shutdown punch list, a P&ID photo — and the
 * system reads it. That is only useful if every extracted fragment can say where it came from:
 * an approval note citing "corrosion at nozzle N2" is worthless to an inspection engineer unless it
 * also says *E-204 Inspection Report.pdf, page 3*. So extraction never returns a bare string. It
 * returns SEGMENTS, each carrying a locator, and the retrieval layer keeps that locator attached all
 * the way to the model's context window.
 *
 * Design notes worth keeping:
 *
 * 1. **A segment is a natural unit of the source, not a fixed size.** A PDF page, a spreadsheet
 *    sheet, a slide (plus its speaker notes), a text file. Chunking to a token budget happens later
 *    and downstream — splitting here would destroy the locator, because a 1,200-character window
 *    that straddles pages 3 and 4 can be honestly cited as neither.
 *
 * 2. **Extraction must degrade, never throw.** One unreadable file in a 200-file shutdown drop must
 *    not fail the drop. Every extractor reports `ok: false` with a reason and the corpus records it,
 *    so the user is told "191 of 200 ingested, 9 skipped, here is why" instead of silence.
 *
 * 3. **Nothing here reaches the network.** OCR is Apple Vision or Tesseract, both local; the Office
 *    formats are ZIP containers parsed in-process. This file is safe under `--sovereign`.
 *
 *    One qualification, because the claim above is load-bearing and the exception is real. When the
 *    optional layout converter is installed, PDFs are routed through it first — a local Python
 *    subprocess, not a network call. Its models are downloaded at INSTALL time (`/sidecars install
 *    docling`) precisely so conversion needs no network. If that prefetch was skipped or failed,
 *    Docling would try to fetch weights on first use; an air-gapped host denies that at the kernel
 *    via the sandbox, the conversion fails, and `tryLayoutPdf` falls through to the built-in reader.
 *    So the guarantee holds either way — the worst case is the older, structure-losing result, not
 *    an escape.
 */

/** Where a fragment came from, in the source's own coordinates. */
export interface Locator {
  /** 1-indexed page, for paged formats. */
  page?: number;
  /** Worksheet name, for spreadsheets. */
  sheet?: string;
  /** 1-indexed slide number, for presentations. */
  slide?: string | number;
  /** A named section, for formats that have them. */
  section?: string;
}

export interface Segment {
  text: string;
  locator: Locator;
  /**
   * A short line that must ride on EVERY chunk cut from this segment, not just the first.
   *
   * This is the deterministic half of Contextual Retrieval (measured: prepending chunk-specific
   * context cuts top-20 retrieval failures 5.7% -> 2.9%, and 1.9% with reranking). The failure it
   * removes is the dominant one for engineering documents: a spreadsheet is ONE segment, so when it
   * is chunked only the first chunk keeps the header row — every later chunk becomes a grid of bare
   * numbers whose columns are unnamed and whose equipment is unstated. Error analysis of
   * text-and-table retrieval puts 73% of residual failures in exactly that class.
   *
   * Deliberately derived from the document, never generated by a model: it must run at ingest speed
   * on an air-gapped box.
   */
  context?: string;
  /**
   * How the text was obtained. `ocr` means it was *read from an image* and may contain errors;
   * `layout` means a layout model recovered reading order and table structure, so the rows in it
   * are rows rather than a run of numbers that happened to be adjacent on the page.
   */
  via: 'text' | 'text-layer' | 'ocr' | 'cells' | 'xml' | 'layout';
  /** Mean OCR confidence 0..1, when the segment came from a recognizer. */
  confidence?: number;
}

export interface ExtractionResult {
  ok: boolean;
  file: string;
  /** Lower-case extension including the dot, or '' when the file has none. */
  kind: string;
  segments: Segment[];
  /** Human-readable reason when `ok` is false, or a caveat when it is true. */
  note?: string;
  bytes: number;
}

/** Formats we parse structurally rather than by sniffing. */
const PDF = new Set(['.pdf']);
const IMAGE = new Set(['.png', '.jpg', '.jpeg', '.gif', '.webp', '.bmp', '.tif', '.tiff', '.heic']);
const SHEET = new Set(['.xlsx', '.xlsm', '.xltx']);
const CSVISH = new Set(['.csv', '.tsv']);
const DOCX = new Set(['.docx', '.docm']);
const PPTX = new Set(['.pptx', '.pptm']);

/**
 * Extensions that are archives, executables or media we cannot read as text. Sniffing these wastes
 * time and, worse, a binary that happens to pass the printable-ratio test injects garbage into
 * retrieval that outranks real content on rare-token matches.
 */
const OPAQUE = new Set([
  '.zip', '.tar', '.gz', '.bz2', '.xz', '.7z', '.rar', '.dmg', '.iso', '.pkg',
  '.exe', '.dll', '.so', '.dylib', '.o', '.a', '.class', '.jar', '.wasm',
  '.mp4', '.mov', '.avi', '.mkv', '.webm', '.mp3', '.wav', '.m4a', '.flac', '.ogg',
  '.ttf', '.otf', '.woff', '.woff2', '.eot',
  '.db', '.sqlite', '.sqlite3', '.mdb', '.bin', '.dat', '.pyc', '.lock',
]);

/** Hard ceiling per file. A 500 MB log is not a document; ingesting it evicts everything useful. */
const MAX_BYTES = 64 * 1024 * 1024;
/** Cap on text taken from any one file, after extraction. */
const MAX_CHARS = 8 * 1024 * 1024;

function clean(value: string): string {
  // Normalise the whitespace OCR and XML extraction both produce in abundance, and drop the control
  // characters that survive PDF text layers. Keeps chunk boundaries meaningful.
  return value
    .replace(/\r\n?/g, '\n')
    // eslint-disable-next-line no-control-regex
    .replace(/[\x00-\x08\x0B\x0C\x0E-\x1F\x7F]/g, ' ')
    .replace(/[ \t]+\n/g, '\n')
    .replace(/\n{3,}/g, '\n\n')
    .trim();
}

/**
 * Is this buffer text?
 *
 * A NUL byte is the classic binary tell and costs nothing to check. Beyond that we require most
 * bytes to be printable: a file that is 30% control characters is a binary that happens to contain
 * some ASCII, and admitting it pollutes retrieval. UTF-16 text (a BOM plus alternating NULs) is
 * recognised rather than rejected, because Windows-authored refinery logs are routinely UTF-16.
 */
export function looksLikeText(buffer: Buffer): { text: boolean; encoding: BufferEncoding } {
  if (buffer.length === 0) return { text: false, encoding: 'utf8' };
  if (buffer[0] === 0xff && buffer[1] === 0xfe) return { text: true, encoding: 'utf16le' };
  if (buffer[0] === 0xef && buffer[1] === 0xbb && buffer[2] === 0xbf) return { text: true, encoding: 'utf8' };

  const sample = buffer.subarray(0, Math.min(buffer.length, 8192));
  let printable = 0;
  let nul = 0;
  for (const byte of sample) {
    if (byte === 0) nul++;
    else if (byte === 9 || byte === 10 || byte === 13 || (byte >= 32 && byte !== 127)) printable++;
  }
  if (nul > sample.length * 0.01) return { text: false, encoding: 'utf8' };
  return { text: printable / sample.length > 0.85, encoding: 'utf8' };
}

/** ZIP central-directory reader. docx/pptx/xlsx are all ZIP containers of XML. */
async function unzipEntries(file: string, wanted: (name: string) => boolean): Promise<Map<string, string>> {
  // jszip is already in the dependency tree and parses in-process with no temp files, which keeps
  // an Office document's contents off disk — it may be confidential.
  // eslint-disable-next-line @typescript-eslint/no-require-imports
  const JSZip = require('jszip');
  const zip = await JSZip.loadAsync(await fs.promises.readFile(file));
  const out = new Map<string, string>();
  const names: string[] = Object.keys(zip.files);
  for (const name of names) {
    if (!wanted(name) || zip.files[name].dir) continue;
    out.set(name, await zip.files[name].async('string'));
  }
  return out;
}

/** Strip XML tags to readable text, preserving paragraph and cell boundaries as newlines/tabs. */
function xmlToText(xml: string): string {
  return xml
    // Word/PowerPoint break elements become real breaks before the tags are stripped.
    .replace(/<\/w:p>|<\/a:p>|<w:br\b[^>]*\/?>|<a:br\b[^>]*\/?>/g, '\n')
    .replace(/<\/w:tc>|<\/a:tc>/g, '\t')
    .replace(/<\/w:tr>|<\/a:tr>/g, '\n')
    .replace(/<[^>]+>/g, '')
    .replace(/&lt;/g, '<').replace(/&gt;/g, '>')
    .replace(/&amp;/g, '&').replace(/&quot;/g, '"').replace(/&apos;/g, "'")
    .replace(/&#(\d+);/g, (_m, d) => String.fromCharCode(Number(d)));
}

/**
 * Layout-aware conversion, when it happens to be installed.
 *
 * Returns null — never a partial result — whenever the layout path cannot be used, so the caller
 * falls through to the built-in reader. That includes: not installed, disabled, the helper failing,
 * the conversion timing out, and the conversion "succeeding" while producing nothing. An optional
 * upgrade that turns a readable PDF into an empty one would be worse than not having it.
 *
 * Why PDF and not every format: this is the only route where the built-in reader genuinely loses
 * structure. Spreadsheets already arrive as exact cells through ExcelJS (with formula *results*,
 * which a layout model would have to read off a rendering), and Office XML already carries real
 * paragraph and cell boundaries. A PDF is where a table becomes a run of adjacent words and where a
 * scan becomes whatever the recognizer thought it saw.
 */
interface LayoutRead {
  /** False when the converter could not report page provenance — no per-page merge is possible. */
  paged: boolean;
  segments: Segment[];
  byPage: Map<number, Segment>;
}

async function tryLayoutPdf(file: string): Promise<LayoutRead | null> {
  try {
    // Lazy require, exactly as jszip and exceljs are loaded in this file: the layout path is
    // optional, and a static import would pull the sidecar machinery into every extraction.
    // eslint-disable-next-line @typescript-eslint/no-require-imports
    const docling = require('./docling') as typeof import('./docling');
    if (!(await docling.doclingAvailable())) return null;
    const [converted] = await docling.doclingConvert([file]);
    if (!converted?.ok) return null;
    const segments = docling.toSegments(converted);
    if (segments.length === 0) return null;
    const byPage = new Map<number, Segment>();
    for (const segment of segments) {
      if (segment.locator.page !== undefined) byPage.set(segment.locator.page, segment);
    }
    return { paged: converted.paged, segments, byPage };
  } catch {
    // Deliberately silent at this level. `doclingConvert` already logs the specific failure, and a
    // second warning on every PDF would train people to ignore it.
    return null;
  }
}

/**
 * OCR, without letting its failure cost the pages that were already read.
 *
 * ocr.ts reports rather than degrades, on purpose: an OCR layer that quietly returns empty text
 * makes a scanned report look like a blank one. That is right for the page it could not read — and
 * wrong for every other page, which is what actually happened. The macOS helper is COMPILED on
 * first use, so anything that breaks swiftc (an Xcode licence reset after an update is enough)
 * threw straight out of extractPdf, and a 40-page born-digital report with one scanned page
 * returned ZERO pages, ok:false, with the compiler's command line as the only explanation.
 *
 * So the failure is still reported — as a note naming the pages nobody could read — and the pages
 * the text layer or the converter already produced are kept. When OCR was the only possible source,
 * the caller sees no segments and the note, which is the honest "this document was not read".
 */
async function ocrOrNote(images: string[]): Promise<{ pages: Array<{ imagePath: string; text: string; confidence?: number }>; note?: string }> {
  try {
    const { pages } = await ocrPages(images);
    return { pages };
  } catch (error) {
    const reason = (error as Error).message.split('\n')[0];
    return { pages: [], note: `${images.length} page(s) needed OCR and it was unavailable: ${reason}` };
  }
}

/** Letters and digits only — the same measure `hasTextLayer` uses, for the same reason. */
function meaningfulLength(value: string | undefined): number {
  if (!value) return 0;
  return value.replace(/[^\p{L}\p{N}]/gu, '').length;
}

/**
 * How much of the text layer a layout page must recover to be trusted for that page.
 *
 * A layout model legitimately returns LESS than `pdftotext` does: it drops running headers, footers
 * and page numbers, and it reorders columns into reading order. So the floor is not "as much as the
 * text layer" — it is "enough that it plainly read the page". Half is far below any healthy
 * conversion and far above the failure being caught, which is a page that came back empty or with a
 * single stray caption.
 *
 * Compared on letters and digits, so the markdown pipes and dashes a recovered table adds cannot
 * inflate the layout side into passing a page it actually lost.
 */
const LAYOUT_FLOOR = 0.5;

/**
 * Merge a paged layout conversion with the built-in reader, deciding PER PAGE.
 *
 * The all-or-nothing version of this shipped first and had a real hole: a 40-page report where the
 * converter silently produced nothing for six pages kept the 34 good pages and lost the other six,
 * because the fallback only triggered when the whole document came back empty. Six missing pages in
 * an otherwise healthy extraction is exactly the kind of loss nobody notices until a citation cannot
 * be found.
 *
 * The text layer is the floor because it is nearly free — `extractTextLayer` is one `pdftotext` call
 * and no rasterisation — and because it is the ground truth for what characters are actually on a
 * born-digital page. Rasterising is only paid for pages that end up needing OCR, which keeps the
 * cost of a healthy conversion identical to before.
 */
async function mergeLayoutPages(file: string, byPage: Map<number, Segment>): Promise<{ segments: Segment[]; note?: string }> {
  let layers: string[];
  try {
    layers = await extractTextLayer(file);
  } catch {
    // No poppler, or an unreadable PDF. There is no floor to compare against, so the layout result
    // stands on its own rather than being discarded over a missing comparison.
    return { segments: [...byPage.values()].sort((a, b) => (a.locator.page ?? 0) - (b.locator.page ?? 0)) };
  }

  const lastPage = Math.max(layers.length, ...(byPage.size ? [...byPage.keys()] : [0]));
  const segments: Segment[] = [];
  const needOcr: number[] = [];

  for (let page = 1; page <= lastPage; page++) {
    const layout = byPage.get(page);
    const layerText = layers[page - 1];
    const layerSize = meaningfulLength(layerText);

    // A page the layout model read to the floor wins: it is the only source that recovered rows.
    //
    // `layoutSize > 0` is not redundant. On a scanned page the text layer is empty, so the floor is
    // zero and an EMPTY layout result satisfies `>= 0` — which accepted a page the converter had
    // plainly dropped and skipped the OCR that would have read it. A floor of nothing is not a
    // floor, so the layout side has to clear an absolute bar as well as a relative one.
    const layoutSize = meaningfulLength(layout?.text);
    if (layout && layoutSize > 0 && layoutSize >= layerSize * LAYOUT_FLOOR) {
      segments.push(layout);
      continue;
    }
    // It did not, so prefer real characters over a thin conversion.
    if (hasTextLayer(layerText)) {
      const cleaned = clean(layerText!);
      segments.push({ text: cleaned, locator: { page }, via: 'text-layer', context: leadingContext(cleaned) });
      continue;
    }
    // No text layer either. A scanned page the converter DID read is still better than nothing —
    // Docling runs its own recognizer — so only a page nobody read goes to OCR.
    if (layout && layout.text.trim()) {
      segments.push(layout);
      continue;
    }
    needOcr.push(page);
  }

  if (needOcr.length === 0) return { segments };

  // Only now is rasterising justified, and only these pages are recognised.
  const wanted = new Set(needOcr);
  const result = await readPdf(file);
  try {
    const images = result.pages.filter((p) => wanted.has(p.page) && p.imagePath);
    if (images.length === 0) return { segments: segments.sort((a, b) => (a.locator.page ?? 0) - (b.locator.page ?? 0)) };

    const { pages: recognised, note } = await ocrOrNote(images.map((p) => p.imagePath!));
    const byImage = new Map(recognised.map((p) => [p.imagePath, p]));
    for (const page of images) {
      const hit = byImage.get(page.imagePath!);
      if (!hit || !hit.text.trim()) continue;
      const cleaned = clean(hit.text);
      segments.push({
        text: cleaned, locator: { page: page.page }, via: 'ocr',
        confidence: hit.confidence, context: leadingContext(cleaned),
      });
    }
    return { segments: segments.sort((a, b) => (a.locator.page ?? 0) - (b.locator.page ?? 0)), note };
  } finally { await result.dispose?.(); }
}

async function extractPdf(file: string): Promise<{ segments: Segment[]; note?: string }> {
  // Preference order, decided per page: layout model, then the text layer, then OCR. The first is
  // optional and the other two always work, so this only ever adds structure — it can never lose a
  // page that one of the other two could have read.
  const layout = await tryLayoutPdf(file);
  if (layout) {
    // Unpaged conversions cannot be aligned against the text layer page by page, so they stay
    // all-or-nothing. Inventing an alignment would attach one page's floor to another page's text.
    if (!layout.paged) return { segments: layout.segments };
    return mergeLayoutPages(file, layout.byPage);
  }

  // readPdf already does the right thing: embedded text layer FIRST, rasterise + OCR only the pages
  // that have none. A born-digital report costs no OCR; a scanned one is recognised page by page.
  const result = await readPdf(file);
  try {
    const needOcr = result.pages.filter((p) => !p.text && p.imagePath);
    const recognized = new Map<string, { text: string; confidence?: number }>();
    let note: string | undefined;
    if (needOcr.length) {
      const ocr = await ocrOrNote(needOcr.map((p) => p.imagePath!));
      note = ocr.note;
      for (const page of ocr.pages) recognized.set(page.imagePath, { text: page.text, confidence: page.confidence });
    }
    const segments: Segment[] = [];
    for (const page of result.pages) {
      if (page.text && page.text.trim()) {
        const cleaned = clean(page.text);
        segments.push({ text: cleaned, locator: { page: page.page }, via: 'text-layer', context: leadingContext(cleaned) });
        continue;
      }
      const hit = page.imagePath ? recognized.get(page.imagePath) : undefined;
      if (hit && hit.text.trim()) {
        const cleaned = clean(hit.text);
        segments.push({ text: cleaned, locator: { page: page.page }, via: 'ocr', confidence: hit.confidence, context: leadingContext(cleaned) });
      }
    }
    return { segments, note };
  } finally { await result.dispose?.(); }
}

async function extractImage(file: string): Promise<Segment[]> {
  if (/\.tiff?$/i.test(file)) {
    // Reject a truncated/foreign TIFF before probing or compiling a native OCR
    // helper. Classic TIFF and BigTIFF both carry an endian marker and magic.
    const handle = await fs.promises.open(file, 'r');
    try {
      const header = Buffer.alloc(8);
      const { bytesRead } = await handle.read(header, 0, header.length, 0);
      const magic = header.subarray(0, 4).toString('hex');
      if (bytesRead < 8 || !['49492a00', '4d4d002a', '49492b00', '4d4d002b'].includes(magic)) {
        throw new Error('Unreadable TIFF: missing or truncated image header.');
      }
    } finally { await handle.close(); }
  }
  const { pages } = await ocrPages([file]);
  const page = pages[0];
  if (!page || !page.text.trim()) return [];
  return [{ text: clean(page.text), locator: {}, via: 'ocr', confidence: page.confidence }];
}

async function extractSheet(file: string, isCsv: boolean): Promise<Segment[]> {
  // eslint-disable-next-line @typescript-eslint/no-require-imports
  const ExcelJS = require('exceljs');
  const workbook = new ExcelJS.Workbook();
  if (isCsv) await workbook.csv.readFile(file);
  else await workbook.xlsx.readFile(file);

  const segments: Segment[] = [];
  workbook.eachSheet((sheet: any) => {
    const rows: string[] = [];
    sheet.eachRow({ includeEmpty: false }, (row: any) => {
      const cells: string[] = [];
      row.eachCell({ includeEmpty: true }, (cell: any) => {
        const value = cell?.value;
        if (value === null || value === undefined) { cells.push(''); return; }
        // A formula cell carries both the formula and its last computed result; the RESULT is the
        // measurement an engineer means. `=B4-C4` retrieves nothing useful; `7.8` does.
        if (typeof value === 'object' && 'result' in value) { cells.push(String(value.result ?? '')); return; }
        if (typeof value === 'object' && 'text' in value) { cells.push(String((value as any).text ?? '')); return; }
        if (value instanceof Date) { cells.push(value.toISOString().slice(0, 10)); return; }
        cells.push(String(value));
      });
      const line = cells.join('\t').trimEnd();
      if (line.trim()) rows.push(line);
    });
    if (rows.length) {
      // The first row of a worksheet is its column names in almost every real workbook. Losing it
      // turns "7.8" into an uninterpretable number; carrying it makes every chunk self-describing.
      const header = rows[0].split('\t').some((cell) => /[A-Za-z]/.test(cell)) ? rows[0] : undefined;
      segments.push({
        text: clean(rows.join('\n')),
        locator: { sheet: sheet.name },
        via: 'cells',
        context: header ? `columns: ${header.replace(/\t/g, ' | ')}` : undefined,
      });
    }
  });
  return segments;
}

async function extractDocx(file: string): Promise<Segment[]> {
  const entries = await unzipEntries(file, (n) =>
    n === 'word/document.xml' || /^word\/(header|footer)\d*\.xml$/.test(n));
  const body = entries.get('word/document.xml');
  const segments: Segment[] = [];
  if (body) {
    const text = clean(xmlToText(body));
    if (text) segments.push({ text, locator: { section: 'body' }, via: 'xml' });
  }
  for (const [name, xml] of entries) {
    if (name === 'word/document.xml') continue;
    const text = clean(xmlToText(xml));
    // Headers and footers carry the document control numbers and revision stamps an approval note
    // has to quote, so they are kept — but as their own segment, not spliced into the body.
    if (text) segments.push({ text, locator: { section: path.basename(name, '.xml') }, via: 'xml' });
  }
  return segments;
}

async function extractPptx(file: string): Promise<Segment[]> {
  const entries = await unzipEntries(file, (n) =>
    /^ppt\/slides\/slide\d+\.xml$/.test(n) || /^ppt\/notesSlides\/notesSlide\d+\.xml$/.test(n));
  const slides = new Map<number, { body: string; notes: string }>();
  for (const [name, xml] of entries) {
    const match = name.match(/(\d+)\.xml$/);
    if (!match) continue;
    const index = Number(match[1]);
    const entry = slides.get(index) ?? { body: '', notes: '' };
    if (name.includes('notesSlides')) entry.notes = clean(xmlToText(xml));
    else entry.body = clean(xmlToText(xml));
    slides.set(index, entry);
  }
  return [...slides.entries()]
    .sort((a, b) => a[0] - b[0])
    .map(([index, { body, notes }]) => ({
      // Speaker notes routinely hold the reasoning the slide only asserts, which is exactly what a
      // later question ("why did we defer that repair?") needs to retrieve.
      text: notes ? `${body}\n\n[Speaker notes]\n${notes}`.trim() : body,
      locator: { slide: index },
      via: 'xml' as const,
    }))
    .filter((segment) => segment.text.trim().length > 0);
}

async function extractPlainText(file: string, bytes: number): Promise<{ segments: Segment[]; note?: string }> {
  const buffer = await fs.promises.readFile(file);
  const { text, encoding } = looksLikeText(buffer);
  if (!text) return { segments: [], note: 'not text (binary content)' };
  let content = clean(buffer.toString(encoding));
  let note: string | undefined;
  if (content.length > MAX_CHARS) {
    content = content.slice(0, MAX_CHARS);
    note = `truncated to ${MAX_CHARS} characters (source was ${bytes} bytes)`;
  }
  if (!content) return { segments: [], note: 'file is empty after normalisation' };
  return { segments: [{ text: content, locator: {}, via: 'text', context: leadingContext(content) }], note };
}

/**
 * Extract one file. Never throws for a content reason — a failure is a result with `ok: false`.
 */
export async function extractFile(file: string): Promise<ExtractionResult> {
  const kind = path.extname(file).toLowerCase();
  const base: Omit<ExtractionResult, 'ok' | 'segments'> = { file, kind, bytes: 0 };

  let stat: fs.Stats;
  try {
    stat = await fs.promises.stat(file);
  } catch (error) {
    return { ...base, ok: false, segments: [], note: `cannot read: ${(error as Error).message}` };
  }
  if (stat.isDirectory()) return { ...base, ok: false, segments: [], note: 'is a directory' };
  base.bytes = stat.size;
  if (stat.size === 0) return { ...base, ok: false, segments: [], note: 'file is empty' };
  if (stat.size > MAX_BYTES) {
    return { ...base, ok: false, segments: [], note: `larger than the ${MAX_BYTES / 1024 / 1024} MB ingest limit` };
  }
  if (OPAQUE.has(kind)) {
    return { ...base, ok: false, segments: [], note: `${kind} is not a readable document format` };
  }

  try {
    if (PDF.has(kind)) {
      // A PDF that produced nothing is not ok, whatever the reason — and when a page needed OCR
      // that could not run, the note says so instead of the extraction silently coming back empty.
      const { segments, note } = await extractPdf(file);
      return { ...base, ok: segments.length > 0, segments, note };
    }
    if (IMAGE.has(kind)) return { ...base, ok: true, segments: await extractImage(file) };
    if (SHEET.has(kind)) return { ...base, ok: true, segments: await extractSheet(file, false) };
    if (CSVISH.has(kind)) return { ...base, ok: true, segments: await extractSheet(file, true) };
    if (DOCX.has(kind)) return { ...base, ok: true, segments: await extractDocx(file) };
    if (PPTX.has(kind)) return { ...base, ok: true, segments: await extractPptx(file) };
    // Everything else — .md, .txt, source code, .json, .yaml, .log, and the genuinely unknown
    // `.xyz` an instrument vendor invented — goes through the sniffer.
    const { segments, note } = await extractPlainText(file, stat.size);
    return { ...base, ok: segments.length > 0, segments, note };
  } catch (error) {
    return { ...base, ok: false, segments: [], note: `extraction failed: ${(error as Error).message}` };
  }
}

/**
 * The opening line of a segment, when it looks like a title rather than prose.
 *
 * On a repetitive form the equipment identity sits at the top of the page ("INSPECTION RECORD
 * SHEET. Equipment E-204."), and every chunk below the first loses it. Carrying it forward is what
 * lets a query naming the vessel reach the chunk holding its measurement.
 */
export function leadingContext(text: string): string | undefined {
  const first = text.split('\n').map((line) => line.trim()).find((line) => line.length > 0);
  if (!first) return undefined;
  // A long paragraph is prose, not a heading; repeating it on every chunk would bloat the index
  // and add no identifying signal.
  if (first.length > 160) return first.slice(0, 160);
  return first;
}

/** Render a locator the way it should appear in a citation. */
export function describeLocator(locator: Locator): string {
  const parts: string[] = [];
  if (locator.page !== undefined) parts.push(`page ${locator.page}`);
  if (locator.sheet !== undefined) parts.push(`sheet ${locator.sheet}`);
  if (locator.slide !== undefined) parts.push(`slide ${locator.slide}`);
  if (locator.section !== undefined) parts.push(locator.section);
  return parts.join(' · ');
}

import type PDFKitModule from 'pdfkit';

/**
 * pdfkit, loaded so that its standard fonts exist inside the compiled engine.
 *
 * pdfkit's Node build registers the 14 PDF standard fonts as lazy loaders —
 * `() => require$1('#standard-fonts/Helvetica')`, with `require$1 = createRequire(...)`. A bundler
 * cannot follow that alias, so `bun build --compile` never packs the font data, and the first
 * `doc.font()` in the engine binary throws `Cannot find module '#standard-fonts/Helvetica'`. Every
 * PDF the DocumentTool was asked for failed that way — the model then pip-installed Python PDF
 * libraries to work around it — while jest, running plain Node, stayed green. pdfkit 0.20.2 is the
 * latest release, and its Node entry does not export `registerStdFonts`.
 *
 * So the font data is required below with literal specifiers, which the bundler does pack, and
 * pdfkit is loaded while `createRequire` answers `#standard-fonts/*` from that table. It has to be
 * the CommonJS build: that one reads `module.createRequire` as a property when it loads, whereas
 * the ESM build binds the import before any of this can run. The patch is undone the moment
 * pdfkit has loaded.
 *
 * Measured with a compiled probe (2026-09-13): the ESM build, bundling the font modules alone, and
 * a Bun runtime plugin all still threw; this path produced a valid `%PDF-`.
 */
const STANDARD_FONTS: Record<string, unknown> = {
  Courier: require('pdfkit/standard-fonts/Courier'),
  CourierBold: require('pdfkit/standard-fonts/CourierBold'),
  CourierBoldOblique: require('pdfkit/standard-fonts/CourierBoldOblique'),
  CourierOblique: require('pdfkit/standard-fonts/CourierOblique'),
  Helvetica: require('pdfkit/standard-fonts/Helvetica'),
  HelveticaBold: require('pdfkit/standard-fonts/HelveticaBold'),
  HelveticaBoldOblique: require('pdfkit/standard-fonts/HelveticaBoldOblique'),
  HelveticaOblique: require('pdfkit/standard-fonts/HelveticaOblique'),
  Symbol: require('pdfkit/standard-fonts/Symbol'),
  TimesBold: require('pdfkit/standard-fonts/TimesBold'),
  TimesBoldItalic: require('pdfkit/standard-fonts/TimesBoldItalic'),
  TimesItalic: require('pdfkit/standard-fonts/TimesItalic'),
  TimesRoman: require('pdfkit/standard-fonts/TimesRoman'),
  ZapfDingbats: require('pdfkit/standard-fonts/ZapfDingbats'),
};

const FONT_PREFIX = '#standard-fonts/';

function loadPdfkit(): typeof PDFKitModule {
  const nodeModule: { createRequire: (from: string | URL) => NodeRequire } = require('module');
  const createRequire = nodeModule.createRequire;
  nodeModule.createRequire = (from) => {
    const real = createRequire(from);
    const withFonts = (id: string): unknown => {
      const name = id.startsWith(FONT_PREFIX) ? id.slice(FONT_PREFIX.length) : '';
      return name in STANDARD_FONTS ? STANDARD_FONTS[name] : real(id);
    };
    return Object.assign(withFonts, real);
  };
  try {
    const loaded = require('pdfkit');
    return loaded.default ?? loaded;
  } finally {
    nodeModule.createRequire = createRequire;
  }
}

export const PDFDocument = loadPdfkit();

import PptxGenJS from 'pptxgenjs';
import { CHART, COLOR, DocumentSpec, FONT, Slide, TYPE, resolveDate } from './design';
import { fitBox, loadImage } from './images';

/**
 * Slides, not documents with a projector aimed at them.
 *
 * Three rules do most of the work here. A slide carries ONE claim, so the title is the claim and
 * the bullets are its support — not a heading with the content underneath. Text is never shrunk to
 * fit: if it does not fit, the slide is trying to be two slides, and silently reflowing to 9pt is
 * how decks become unreadable. And the layout is a fixed grid — same title baseline, same left
 * edge, same footer on every slide — so the deck does not appear to shuffle as it advances.
 */

// 16:9 inches.
const W = 13.333;
const H = 7.5;
const M = 0.72;

const hex = (c: string): string => c;

function footer(slide: PptxGenJS.Slide, spec: DocumentSpec, index: number): void {
  slide.addText(spec.title, {
    x: M, y: H - 0.52, w: W - M * 2 - 0.6, h: 0.3,
    fontSize: 9, color: hex(COLOR.faint), fontFace: FONT.sans, align: 'left',
  });
  slide.addText(String(index), {
    x: W - M - 0.6, y: H - 0.52, w: 0.6, h: 0.3,
    fontSize: 9, color: hex(COLOR.faint), fontFace: FONT.sans, align: 'right',
  });
}

function contentSlide(pptx: PptxGenJS, spec: DocumentSpec, s: Slide, index: number, baseDir: string): void {
  const slide = pptx.addSlide();
  slide.background = { color: 'FFFFFF' };

  slide.addText(s.title, {
    x: M, y: 0.62, w: W - M * 2, h: 0.9,
    fontSize: 26, bold: true, color: hex(COLOR.ink), fontFace: FONT.sans,
    valign: 'top', wrap: true, shrinkText: false,
  });
  // A short accent rule under the title anchors every slide to the same baseline.
  slide.addShape(pptx.ShapeType.rect, {
    x: M, y: 1.58, w: 1.1, h: 0.045, fill: { color: hex(COLOR.accent) }, line: { width: 0 },
  });

  const top = 2.0;
  const bodyHeight = H - top - 0.8;

  if (s.statement) {
    slide.addText(s.statement, {
      x: M, y: top, w: W - M * 2, h: bodyHeight,
      fontSize: 40, bold: true, color: hex(COLOR.accent), fontFace: FONT.sans,
      valign: 'middle', align: 'left',
    });
  } else if (s.table) {
    const head = s.table.columns.map(c => ({
      text: c,
      options: { bold: true, color: hex(COLOR.accent), fill: { color: hex(COLOR.accentWash) }, fontSize: 13 },
    }));
    const rows = s.table.rows.map(r => r.map(cell => ({
      text: String(cell), options: { color: hex(COLOR.body), fontSize: 13 },
    })));
    slide.addTable([head, ...rows], {
      x: M, y: top, w: W - M * 2,
      fontFace: FONT.sans,
      border: [
        { type: 'none' }, { type: 'none' },
        { type: 'solid', color: hex(COLOR.rule), pt: 0.5 }, { type: 'none' },
      ] as PptxGenJS.TableProps['border'],
      rowH: 0.38,
      valign: 'middle',
    });
  } else if (s.image) {
    // Centred in the body box at its true aspect ratio. A slide-filling stretch is how a
    // screenshot ends up unreadable, so the picture is fitted, never cropped or distorted.
    const img = loadImage(s.image.path, baseDir);
    const capH = s.image.caption ? 0.32 : 0;
    const box = fitBox(img.width, img.height, W - M * 2, bodyHeight - capH);
    slide.addImage({
      data: `image/${img.type};base64,${img.data.toString('base64')}`,
      x: M + (W - M * 2 - box.w) / 2, y: top, w: box.w, h: box.h,
    });
    if (s.image.caption) {
      slide.addText(s.image.caption, {
        x: M, y: top + box.h + 0.06, w: W - M * 2, h: capH,
        fontSize: 11, color: hex(COLOR.muted), fontFace: FONT.sans, align: 'center',
      });
    }
  } else if (s.chart) {
    const c = s.chart;
    const type = c.chart === 'line' ? pptx.ChartType.line : c.chart === 'pie' ? pptx.ChartType.pie : pptx.ChartType.bar;
    // A real chart part, not a picture of one: the reader can click it and see the numbers.
    const data = c.chart === 'pie'
      ? [{ name: c.series[0].name, labels: c.labels, values: c.series[0].values }]
      : c.series.map(ser => ({ name: ser.name, labels: c.labels, values: ser.values }));
    const capH = c.caption ? 0.32 : 0;
    slide.addChart(type, data, {
      x: M, y: top, w: W - M * 2, h: bodyHeight - capH,
      chartColors: [...CHART],
      showLegend: c.chart === 'pie' || c.series.length > 1,
      legendPos: 'b', legendFontFace: FONT.sans, legendFontSize: 11,
      catAxisLabelFontFace: FONT.sans, catAxisLabelFontSize: 11, catAxisLabelColor: hex(COLOR.muted),
      valAxisLabelFontFace: FONT.sans, valAxisLabelFontSize: 11, valAxisLabelColor: hex(COLOR.muted),
      dataLabelFontFace: FONT.sans, dataLabelFontSize: 10,
      showValue: c.chart === 'pie',
      showPercent: false,
    });
    if (c.caption) {
      slide.addText(c.caption, {
        x: M, y: H - 1.05, w: W - M * 2, h: capH,
        fontSize: 11, color: hex(COLOR.muted), fontFace: FONT.sans, align: 'center',
      });
    }
  } else if (s.bullets?.length) {
    slide.addText(
      s.bullets.map(b => ({ text: b, options: { bullet: { characterCode: '2022' }, breakLine: true } })),
      {
        x: M, y: top, w: W - M * 2, h: bodyHeight,
        // One size. Nothing here scales with bullet count on purpose: an overfull slide should
        // look overfull so it gets split, not silently shrink until it is unreadable.
        fontSize: 18, color: hex(COLOR.body), fontFace: FONT.sans,
        lineSpacingMultiple: 1.35, valign: 'top',
      },
    );
  }

  if (s.notes) slide.addNotes(s.notes);
  footer(slide, spec, index);
}

export async function buildPptx(spec: DocumentSpec, baseDir: string = process.cwd()): Promise<Buffer> {
  const pptx = new PptxGenJS();
  pptx.layout = 'LAYOUT_16x9';
  pptx.author = spec.author || 'Bimax';
  pptx.title = spec.title;

  // Title slide: the deck's one full-bleed moment.
  const cover = pptx.addSlide();
  cover.background = { color: hex(COLOR.accent) };
  // 44pt overflowed a realistic title off the right edge. 34pt with two lines of room wraps
  // instead of clipping, and `wrap` is set explicitly rather than relied on as a default.
  cover.addText(spec.title, {
    x: M, y: 2.15, w: W - M * 2, h: 2.0,
    fontSize: 34, bold: true, color: 'FFFFFF', fontFace: FONT.sans,
    valign: 'bottom', wrap: true, shrinkText: false,
  });
  if (spec.subtitle) {
    cover.addText(spec.subtitle, {
      x: M, y: 4.05, w: W - M * 2, h: 0.6,
      fontSize: 18, color: 'D6E2EF', fontFace: FONT.sans,
    });
  }
  cover.addText([spec.author, resolveDate(spec)].filter(Boolean).join('   ·   '), {
    x: M, y: H - 1.1, w: W - M * 2, h: 0.4,
    fontSize: 12, color: 'AFC4D9', fontFace: FONT.sans,
  });

  (spec.slides ?? []).forEach((s, i) => contentSlide(pptx, spec, s, i + 1, baseDir));

  const out = await pptx.write({ outputType: 'nodebuffer' });
  return out as Buffer;
}

/**
 * Adversarial Verifier — a second review pass after self-critic, framed as red-team.
 *
 * Self-critic (lite model, ~300 tokens): "did you satisfy the request?"
 * Adversarial verifier (full model, ~800 tokens): "try to BREAK this — find bugs, edge
 * cases, security holes, missed requirements that the agent and self-critic both missed."
 *
 * Off by default (/governor redteam on). Only fires when:
 *   - Enabled
 *   - Not in plan mode
 *   - The turn touched code (contains a file path or function call)
 *   - Self-critic already ran and approved (avoid double-flagging known issues)
 */

import { getGlobalPatternStore } from '../genome/pattern.store';

let enabled = false;

export function setAdversarialVerifyEnabled(value: boolean): void { enabled = value; }
export function isAdversarialVerifyEnabled(): boolean { return enabled; }

const CODE_SIGNAL_RE = /\.(ts|tsx|js|jsx|py|go|rs|java|cpp|c|rb|swift|kt)\b|function\s+\w+|class\s+\w+|def\s+\w+/;

/** True when the execution log looks like it touched real code (not a doc/chat turn). */
export function looksLikeCodeWork(log: string): boolean {
  return CODE_SIGNAL_RE.test(log) && log.length > 100;
}

const REDTEAM_SYSTEM = `You are an adversarial red-team code reviewer. Your job is to FIND BUGS — not to be nice.

You are reviewing work done by an AI coding agent. The self-critic already approved it as "complete". Your job is to find what they MISSED.

Hunt for:
- Logic bugs: off-by-one, wrong operator, null/undefined dereference, missing await
- Edge cases: empty input, large input, concurrent calls, error paths not handled
- Security holes: injection, prototype pollution, path traversal, exposed secrets
- Missed requirements: parts of the user's request that were silently skipped
- Type safety: places where TypeScript types were bypassed or any-cast
- Performance traps: accidental O(n²), unbounded loops, missing index

Instructions:
- If you find NOTHING, reply with exactly: VERIFIED
- If you find issues, list each as a SHORT bullet: file:line — what the problem is and why it matters
- Be specific and actionable. Do not repeat what the self-critic already said.
- Do not invent requirements that weren't asked for. Stay inside the scope of what was requested.`;

/**
 * Run the adversarial verifier on a completed turn.
 * Returns null if nothing was found ("VERIFIED"), or a bulleted list of issues.
 */
export async function runAdversarialVerifier(
  originalPrompt: string,
  executionLog: string,
  llmAdapter: { chatCompletion: (msgs: any[], system: string, opts?: any) => Promise<string> }
): Promise<string | null> {
  if (!enabled || !looksLikeCodeWork(executionLog)) return null;

  // Cap what we send to avoid token blowout on massive logs
  const logSlice = executionLog.length > 6000
    ? executionLog.slice(0, 3000) + '\n\n[... middle truncated ...]\n\n' + executionLog.slice(-2000)
    : executionLog;

  try {
    const result = await llmAdapter.chatCompletion(
      [{
        role: 'user',
        content: `User's original request:\n${originalPrompt}\n\n--- Agent's work (self-critic already approved) ---\n${logSlice}`,
      }],
      REDTEAM_SYSTEM,
      { lite: false } // use the full model — adversarial pass needs depth
    );

    const trimmed = result.trim();
    if (!trimmed || /^verified$/i.test(trimmed)) return null;
    // Log verification failures to genome so self-evolution can learn failure patterns
    try { getGlobalPatternStore()?.appendVerificationFail(originalPrompt.slice(0, 120), trimmed.slice(0, 300)); } catch { /* ignore */ }
    return trimmed;
  } catch {
    return null; // adversarial pass is best-effort
  }
}

let customRules: [RegExp, string][] = [];
const builtInAgents: string[] = ['bimax', 'hermes', 'opencode', 'openclaw'];

export function setCustomRoutingRules(rules: string[][]) {
  customRules = rules.map(([pattern, agent]) => [new RegExp(pattern, 'i'), agent]);
}

export function addCustomRule(pattern: string, agent: string) {
  customRules.push([new RegExp(pattern, 'i'), agent]);
}

export function removeCustomRule(index: number) {
  if (index >= 0 && index < customRules.length) customRules.splice(index, 1);
}

export function getCustomRules(): string[][] {
  return customRules.map(([re, agent]) => [re.source, agent]);
}

export function registerAgent(name: string) {
  if (!builtInAgents.includes(name)) builtInAgents.push(name);
}

export function getKnownAgents(): string[] {
  // Keep this import lazy. The headless entry imports the router before personas are built;
  // eagerly loading persona.config.loader here also loads base.persona, whose tool graph reaches back to
  // this router. CommonJS then exposes a half-initialized AgentPersona and DynamicPersona crashes
  // at module evaluation (`Class extends value undefined`). By the time callers ask for the menu,
  // persona construction is complete and loading the legacy JSON personas is safe.
  const { PersonaConfigLoader } = require('./persona.config.loader') as typeof import('./persona.config.loader');
  const dynamicPersonas = Object.keys(PersonaConfigLoader.getAllPersonas());
  return Array.from(new Set([...builtInAgents, ...dynamicPersonas]));
}

export function routeQuery(query: string): string {
  for (const [pattern, agent] of customRules) {
    if (pattern.test(query)) return agent;
  }
  return 'bimax';
}

import { engineEvents } from './events';
import { AgentMode, setAgentMode, setExploreEngagedGate, didExploreEngageGate } from './agentMode';

// Single source of truth for switching the agent's behavioral mode, shared by the /mode command,
// the TUI's Shift+Tab cycle, and ModeTool (the agent switching ITSELF). Centralizing it means the
// governor gating (read-only for explore/sketch, writes for code/beast/general) and the mode_change
// event (which drives the footer chip) can never drift between the three entry points.

// When entering explore/sketch we flip the governor to its read-only 'plan' gate. We remember the
// PRIOR governor mode so leaving restores exactly what was there (interactive OR bypass) — instead
// of guessing — and we only restore if WE engaged the gate (never cancel a user's own `/plan on`).
let _priorGovernorMode: string | null = null;

export function applyAgentMode(mode: AgentMode, governor: any): void {
  setAgentMode(mode);

  if (mode === 'explore' || mode === 'sketch') {
    if (governor && governor.mode !== 'plan') {
      _priorGovernorMode = governor.mode;
      governor.mode = 'plan'; // reuse the proven write-gate for read-only enforcement
      setExploreEngagedGate(true);
    }
    engineEvents.emit('mode_change', mode === 'sketch' ? 'SKETCH' : 'EXPLORE');
    return;
  }

  // Leaving a read-only mode: restore writes ONLY if we were the ones who engaged the gate.
  if (governor && governor.mode === 'plan' && didExploreEngageGate()) {
    governor.mode = _priorGovernorMode || 'interactive';
  }
  setExploreEngagedGate(false);
  _priorGovernorMode = null;
  engineEvents.emit('mode_change', mode === 'code' ? 'CODE' : mode === 'beast' ? 'BEAST' : '');
}

