import { globalCommandRegistry } from './registry';
import { getRecentToolCalls } from '../toolHistory';
import type { ToolCallEntry } from '../events';

const TOOL_LABELS: Record<string, string> = {
  BashTool: 'Bash', ReadFileTool: 'Read', WriteFileTool: 'Write', EditFileTool: 'Edit',
  MultiEditTool: 'MultiEdit', GrepTool: 'Grep', GlobTool: 'Glob', WebFetchTool: 'Fetch',
  WebSearchTool: 'Search', GraphQueryTool: 'Graph',
};

/** Short, human label for a tool call: "Bash(npm test)". */
function summarize(call: ToolCallEntry): string {
  const label = TOOL_LABELS[call.toolName] || call.toolName.replace(/Tool$/, '');
  let arg = '';
  try {
    const p = JSON.parse(call.input);
    const c = p.command || p.filePath || p.path || p.pattern || p.glob || p.url || p.query || p.name;
    if (typeof c === 'string') arg = c;
  } catch { arg = (call.input || '').replace(/\n/g, ' '); }
  arg = arg.length > 44 ? arg.slice(0, 41) + '…' : arg;
  return arg ? `${label}(${arg})` : label;
}

/** BashTool stores {stdout,stderr} as JSON — show the real text, not the wrapper. */
function fullOutput(call: ToolCallEntry): string {
  const raw = call.output || '';
  if (call.toolName === 'BashTool') {
    try {
      const o = JSON.parse(raw);
      if (o && typeof o === 'object' && ('stdout' in o || 'stderr' in o)) {
        return [o.stdout && String(o.stdout), o.stderr && `[stderr]\n${o.stderr}`].filter(Boolean).join('\n').trim() || '(no output)';
      }
    } catch { /* not JSON — fall through */ }
  }
  return raw.trim() || '(no output)';
}

// /output — the full-output viewer. The transcript truncates long tool output (and can't expand in
// place because committed rows live in Ink's write-once <Static>); this lets you pull up the
// COMPLETE output of any recent tool call from the toolHistory ring buffer. Delivers the value of
// collapse/expand without the <Static> rewrite. Registry-derived → also in the Ctrl+G palette.
globalCommandRegistry.register({
  name: '/output',
  aliases: ['/tools', '/out'],
  category: 'Code & Intelligence',
  description: 'View the full, untruncated output of a recent tool call',
  execute: async (_args, context) => {
    const calls = getRecentToolCalls();
    if (calls.length === 0) {
      return { type: 'message', level: 'info', content: 'No tool output captured yet this session.' };
    }
    return {
      type: 'menu',
      title: 'Tool Output — pick a call to view its full output',
      options: calls.map(c => {
        const lines = (c.output || '').split('\n').length;
        return {
          label: summarize(c),
          value: c.id,
          desc: `${lines} line${lines === 1 ? '' : 's'} · ${c.status}${c.agentLabel ? ` · ${c.agentLabel}` : ''}`,
          category: 'Recent tool calls',
        };
      }),
      onSelect: (opt: any) => {
        const call = calls.find(c => c.id === opt.value);
        if (call) context.addSystemMessage(call.status === 'error' ? 'error' : 'info', `${summarize(call)}\n\n${fullOutput(call)}`);
      },
    };
  },
});

import { globalCommandRegistry } from './registry';
import { perfSnapshot, PerfSnapshot } from '../../telemetry/perf';
import { guardTimings } from '../../tools/guard.timing';
import { performanceBudgetReport } from '../../telemetry/performance.budget';
import { slowWaitEvidence, describeAttribution } from '../../telemetry/netprobe';

/**
 * /perf — a hidden diagnostics readout of the engine's own performance: cold-start (process load →
 * ready), per-turn time-to-first-token (p50/p95), and memory. Pure local counters (see PRIVACY.md);
 * "you can't call it smooth without a number." Frame-level render metrics live in the Go TUI.
 */
export function renderPerf(s: PerfSnapshot): string {
  const ms = (n: number) => (n > 0 ? `${n} ms` : '—');
  const lines = [
    '● **Performance**',
    '',
    `  Cold start (load → ready):  **${ms(s.coldStartMs)}**` + (s.coldStartMs > 0 && s.coldStartMs < 300 ? '  ✓ < 300 ms' : ''),
    `  Uptime:                     ${Math.round(s.uptimeMs / 1000)} s`,
    `  Memory:                     ${s.rssMb} MB rss · ${s.heapMb} MB heap`,
    '',
    `  Turns measured:             ${s.turns}`,
    `  Time-to-first-token:        p50 ${ms(s.firstTokenP50)} · p95 ${ms(s.firstTokenP95)}`,
    '',
    `  Bimax overhead (ours):      p50 ${ms(s.overheadP50)} · p95 ${ms(s.overheadP95)}`,
    `  Provider wait (theirs):     p50 ${ms(s.providerWaitP50)} · p95 ${ms(s.providerWaitP95)}`,
    `  Render (payload→visible):   p95 ${ms(s.renderP95)}`,
    `  Greeting-lane overhead:     p95 ${ms(s.liteOverheadP95)}`,
  ];
  if (s.lastTurn) {
    lines.push(`  Last turn:                  first token ${ms(s.lastTurn.firstTokenMs)} · total ${ms(s.lastTurn.totalMs)} · ${s.lastTurn.streamedChars} streamed chars`);
  }
  if (s.lastBreakdown) {
    const b = s.lastBreakdown;
    lines.push(`  Last turn split:            ${b.lane} lane · overhead ${ms(b.overheadMs)} · provider ${ms(b.providerWaitMs)} · render ${ms(b.renderMs)}`);
  }

  if (s.providerRounds > 0) {
    // Characters are characters and tokens are tokens: a count the provider never reported reads
    // "unavailable", never 0, so an unmetered route can't look free.
    const tok = (n: number | null) => (n === null ? 'unavailable' : String(n));
    lines.push(
      '',
      `  Provider rounds:            ${s.providerRounds} · wait p50 ${ms(s.roundWaitP50)} · p95 ${ms(s.roundWaitP95)}`,
      `  Provider-reported usage:    ${s.roundsWithUsage}/${s.providerRounds} round(s) · ` +
      `in ${tok(s.providerInputTokens)} · out ${tok(s.providerOutputTokens)} · cached-in ${tok(s.providerCachedInputTokens)}`,
    );
  }

  lines.push('', '  Performance budgets:');
  for (const check of performanceBudgetReport(s)) {
    const state = !check.measured ? '○ unmeasured' : check.pass ? '✓ pass' : '✗ over';
    lines.push(`    ${check.metric.padEnd(20)} ${state} · ${check.value || '—'} / ${check.budget} ${check.unit}`);
  }

  try {
    const snapshot = require('../../outcome/outcome.manager').getOutcomeManager().snapshot();
    if (snapshot) {
      const schedule = snapshot.schedule;
      lines.push('', '  Active outcome:');
      lines.push(`    elapsed                  ${ms(snapshot.elapsedMs)}`);
      lines.push(`    time to verified         ${snapshot.timeToVerifiedMs ? ms(snapshot.timeToVerifiedMs) : 'in progress'}`);
      lines.push(`    estimated parallel save  ${ms(schedule.estimatedParallelSavingsMs)}`);
      lines.push(`    remaining critical path  ${ms(schedule.estimatedCriticalPathMs)}`);
    }
  } catch { /* /perf also works before the outcome runtime starts */ }

  // Slow-wait attribution: every long first-token wait triggered a background DNS→TCP→TLS probe
  // of the provider origin, so a stall is attributed from EVIDENCE, never assumption.
  const waits = slowWaitEvidence();
  if (waits.length > 0) {
    lines.push('', '  Slow-wait evidence (most recent first):');
    for (const w of waits.slice(0, 5)) {
      const when = new Date(w.at).toLocaleTimeString();
      const phases = w.probe.ok || w.probe.failedPhase
        ? `dns ${w.probe.dnsMs}ms · tcp ${w.probe.tcpMs}ms · tls ${w.probe.tlsMs}ms${w.probe.failedPhase ? ` · ${w.probe.failedPhase} FAILED` : ''}`
        : 'probe failed';
      lines.push(`    ${when}  waited ${Math.round(w.waitedMs / 1000)}s${w.timedOut ? ' (timed out)' : ''} on ${w.origin}`);
      lines.push(`      ${phases} → ${describeAttribution(w.attribution)}`);
    }
  }

  // WS5 step 3 — guard pipeline timing. Shows whether tool latency is spent in the guards
  // (governor approval, hooks) or in the tool itself, so a slow guard is caught, not blamed.
  const guards = guardTimings();
  if (guards.length > 0) {
    lines.push('', '  Guard pipeline (this session):');
    for (const g of guards) {
      lines.push(`    ${g.phase.padEnd(18)} ${g.count}× · avg ${g.avgMs.toFixed(1)} ms · max ${g.maxMs} ms · total ${Math.round(g.totalMs)} ms`);
    }
  }
  return lines.join('\n');
}

globalCommandRegistry.register({
  name: '/perf',
  description: 'Engine perf readout — cold start, time-to-first-token, memory',
  category: 'Code & Intelligence',
  hidden: true, // diagnostics, not an everyday verb — reachable when typed
  execute: async () => ({ type: 'message', level: 'info', content: renderPerf(perfSnapshot()) }),
});

import { globalCommandRegistry } from './registry';
import { engineEvents } from '../events';
import { getPlanManager } from '../../memory/plan.manager';

/**
 * /plan — Read-only planning mode + plan file management.
 *
 * /plan [on|off]      — toggle read-only plan mode (agent researches, doesn't write)
 * /plan list          — list all saved plan files
 * /plan show [slug]   — display a saved plan (or the most recent one)
 * /plan delete <slug> — delete a plan file
 */
globalCommandRegistry.register({
  name: '/plan',
  description: 'Enter read-only plan mode · /plan list · /plan show [slug]',
  category: 'General',
  execute: async (args, context) => {
    const governor = context.options.governor;
    const sub = (args[0] || '').toLowerCase();

    // --- Plan mode toggle ---
    if (sub === 'off' || sub === 'exit') {
      governor.mode = context.options.dangerouslySkipPermissions ? 'bypass' : 'interactive';
      engineEvents.emit('mode_change', '');
      return { type: 'message', level: 'success', content: 'Plan mode OFF — agent can make changes again. Ask it to execute the plan.' };
    }

    if (sub === '' || sub === 'on') {
      if (governor.mode === 'plan') {
        return { type: 'message', level: 'info', content: 'Already in plan mode. Use /plan off to allow changes.' };
      }
      governor.mode = 'plan';
      engineEvents.emit('mode_change', 'PLAN');
      return {
        type: 'message',
        level: 'success',
        content: 'Plan mode ON — read-only. Agent will research and propose a plan (all writes blocked).\nWhen ready: /plan off to execute, or ask the agent to call PlanTool to save the plan first.',
      };
    }

    // --- /plan list ---
    if (sub === 'list') {
      try {
        const pm = getPlanManager();
        const slugs = await pm.list();
        if (slugs.length === 0) {
          return { type: 'message', level: 'info', content: 'No saved plans. In /plan mode, ask the agent to call PlanTool(action:"write") to save one.' };
        }
        const lines: string[] = [];
        for (const slug of slugs) {
          const plan = await pm.load(slug);
          if (!plan) continue;
          const done = plan.steps.filter(s => s.done).length;
          const total = plan.steps.length;
          const bar = `[${done}/${total}]`;
          lines.push(`  • ${slug}  ${bar}  ${plan.title}`);
        }
        return {
          type: 'menu',
          title: `Saved plans (${slugs.length}) — select to view`,
          options: slugs.map(s => ({ label: s, value: s, desc: `view ${s}`, category: 'Plans' })),
          onSelect: async (opt: any) => {
            const pm2 = getPlanManager();
            const plan = await pm2.load(opt.value);
            if (plan) context.addSystemMessage('info', pm2.formatPlan(plan));
          },
        };
      } catch {
        return { type: 'message', level: 'error', content: 'Plan manager not initialized.' };
      }
    }

    // --- /plan show [slug] ---
    if (sub === 'show') {
      try {
        const pm = getPlanManager();
        const slug = args[1];
        if (slug) {
          const plan = await pm.load(slug);
          if (!plan) return { type: 'message', level: 'error', content: `No plan with slug "${slug}". Use /plan list.` };
          return { type: 'message', level: 'info', content: pm.formatPlan(plan) };
        }
        // No slug — show the most recently MODIFIED plan (not the last alphabetical one).
        const newest = await pm.newestSlug();
        if (!newest) return { type: 'message', level: 'info', content: 'No saved plans. Use /plan list.' };
        const plan = await pm.load(newest);
        if (!plan) return { type: 'message', level: 'error', content: 'Could not load plan.' };
        return { type: 'message', level: 'info', content: pm.formatPlan(plan) };
      } catch {
        return { type: 'message', level: 'error', content: 'Plan manager not initialized.' };
      }
    }

    // --- /plan delete <slug> ---
    if (sub === 'delete' || sub === 'rm') {
      const slug = args[1];
      if (!slug) return { type: 'message', level: 'error', content: 'Usage: /plan delete <slug>' };
      try {
        const ok = await getPlanManager().delete(slug);
        return ok
          ? { type: 'message', level: 'success', content: `Plan "${slug}" deleted.` }
          : { type: 'message', level: 'error', content: `No plan with slug "${slug}".` };
      } catch {
        return { type: 'message', level: 'error', content: 'Plan manager not initialized.' };
      }
    }

    return { type: 'message', level: 'error', content: 'Usage: /plan [on|off|list|show [slug]|delete <slug>]' };
  },
});

import { globalCommandRegistry } from './registry';
import { globalMcpManager } from '../../mcp/manager';
import { globalSkillService } from '../../skills/skill.service';
import { getCustomRules } from '../agentRouter';
import { globalWatcherManager } from '../watchers';

// Plugin Hub (`/plugins`) — one browsable view of BiMax's whole integration ecosystem: MCP servers,
// Agent Skills, routing rules, background watchers, and the command surface. It's the "crazy
// integration" surfacing from docs/TUI_GRAND_UPGRADE.md: power that used to be invisible (scattered
// across /mcp, /skills, /routes, /watch) becomes one categorized overview. Each row Enters into the
// relevant subsystem command, so the hub composes the existing tools rather than duplicating them.
// Read-only + registry-derived → also appears automatically in the Ctrl+G palette.
globalCommandRegistry.register({
  name: '/plugins',
  aliases: ['/hub', '/integrations'],
  category: 'Configuration',
  description: 'Integration hub — MCP servers, skills, routes & watchers in one view',
  execute: async (_args, context) => {
    const options: { label: string; value: string; desc: string; category: string }[] = [];

    // --- MCP servers (connected first, then configured-but-not-connected) ---
    const connected = globalMcpManager.list();
    const configured = globalMcpManager.configuredNames();
    if (connected.length === 0 && configured.length === 0) {
      options.push({ label: '(none)', value: '/mcp', desc: 'Enter to add an MCP server', category: 'MCP Servers' });
    } else {
      for (const c of connected) {
        options.push({ label: c.name, value: '/mcp', desc: `${c.toolNames.length} tool(s) · connected`, category: 'MCP Servers' });
      }
      for (const n of configured) {
        if (connected.some(c => c.name === n)) continue;
        options.push({ label: n, value: '/mcp', desc: globalMcpManager.isDisabled(n) ? 'disabled' : 'not connected', category: 'MCP Servers' });
      }
    }

    // --- Agent Skills ---
    try { globalSkillService.load(context.cwd); } catch { /* best-effort rescan */ }
    const skills = globalSkillService.list();
    if (skills.length === 0) {
      options.push({ label: '(none)', value: '/skills', desc: 'Enter to create a skill', category: 'Agent Skills' });
    } else {
      for (const s of skills) options.push({ label: s.name, value: '/skills', desc: s.source, category: 'Agent Skills' });
    }

    // --- Routing rules ---
    const rules = getCustomRules();
    if (rules.length === 0) {
      options.push({ label: '(none)', value: '/routes', desc: 'Enter to add a routing rule', category: 'Routing Rules' });
    } else {
      for (const [pattern, agent] of rules) options.push({ label: pattern, value: '/routes', desc: `→ ${agent}`, category: 'Routing Rules' });
    }

    // --- Background watchers ---
    const watchers = globalWatcherManager.list();
    if (watchers.length === 0) {
      options.push({ label: '(none)', value: '/watch', desc: 'Enter to add a file/cron watcher', category: 'Watchers' });
    } else {
      for (const w of watchers) {
        options.push({
          label: `${w.kind}: ${w.spec}`,
          value: '/watch',
          desc: `→ ${w.action} · ${w.fires}/${w.maxFires}${w.enabled ? '' : ' (off)'}`,
          category: 'Watchers',
        });
      }
    }

    // --- Command surface (registry-derived) ---
    options.push({
      label: `${globalCommandRegistry.getAllCommands().length} commands`,
      value: '/help',
      desc: 'Press Ctrl+G for the fuzzy command palette',
      category: 'Commands',
    });

    return {
      type: 'menu',
      title: 'Plugin Hub — your integration ecosystem (type to search, Enter opens a subsystem)',
      options,
      onSelect: (opt: any) => context.executeCommand(opt.value),
    };
  },
});

import { globalCommandRegistry } from './registry';
import { getGlobalRecipeLoader } from '../../recipes/recipe.loader';

// Recipes currently mid-run, by name. Sub-recipes re-dispatch via executeCommand('/recipe run X'),
// so a circular reference (A → B → A) would recurse until the stack overflows. This set breaks the
// cycle: a recipe already running is skipped rather than re-entered.
const _runningRecipes = new Set<string>();

/**
 * /recipe — YAML-based configurable task configurations.
 *
 * /recipe                — list available recipes
 * /recipe run <name>     — inject a recipe's instructions into the agent and execute
 * /recipe show <name>    — preview a recipe without running it
 * /recipe new <name>     — scaffold a new recipe YAML in .bimax/recipes/
 */
globalCommandRegistry.register({
  name: '/recipe',
  aliases: ['/rec'],
  description: 'YAML-defined task configurations — list / run / scaffold recipes',
  category: 'Code & Intelligence',
  execute: async (args, context) => {
    const loader = getGlobalRecipeLoader();
    if (!loader) {
      return { type: 'message', level: 'error', content: 'Recipe loader not initialised. Restart BiMax in a project directory.' };
    }

    const sub = (args[0] || '').toLowerCase();

    // /recipe new <name>
    if (sub === 'new' || sub === 'create') {
      const name = args.slice(1).join(' ').trim() || 'my-recipe';
      const filePath = loader.scaffoldExample(name);
      return { type: 'message', level: 'success', content: `Recipe scaffold created: ${filePath}\nEdit it with your instructions, then run /recipe run ${name}.` };
    }

    // /recipe show <name>
    if (sub === 'show' || sub === 'inspect') {
      const name = args.slice(1).join(' ').trim();
      const recipe = loader.getByName(name);
      if (!recipe) return { type: 'message', level: 'error', content: `Recipe "${name}" not found. Use /recipe to list available recipes.` };
      const lines = [
        `**Recipe: ${recipe.name}**`,
        recipe.description ? `Description: ${recipe.description}` : '',
        `File: ${recipe.filePath}`,
        '',
        '**Instructions:**',
        recipe.instructions,
      ];
      if (recipe.extensions?.length) lines.push('', `Extensions: ${recipe.extensions.join(', ')}`);
      if (recipe.sub_recipes?.length) lines.push(`Sub-recipes: ${recipe.sub_recipes.join(', ')}`);
      if (recipe.success_checks?.length) lines.push(`Success checks: ${recipe.success_checks.join(', ')}`);
      if (recipe.retry) lines.push(`Retry: ${recipe.retry}`);
      return { type: 'message', level: 'info', content: lines.filter(l => l !== undefined).join('\n') };
    }

    // /recipe run <name>
    if (sub === 'run' || sub === 'exec' || sub === 'execute') {
      const name = args.slice(1).join(' ').trim();
      if (!name) return { type: 'message', level: 'error', content: 'Usage: /recipe run <name>' };

      const recipe = loader.getByName(name);
      if (!recipe) return { type: 'message', level: 'error', content: `Recipe "${name}" not found. Use /recipe to list available recipes.` };

      // Cycle guard: refuse to re-enter a recipe already running in this chain (A → B → A).
      if (_runningRecipes.has(recipe.name)) {
        return { type: 'message', level: 'error', content: `Recipe cycle detected: "${recipe.name}" is already running (sub-recipe loop). Skipping to avoid infinite recursion.` };
      }

      _runningRecipes.add(recipe.name);
      try {
        // Run sub-recipes first (executeCommand is only available in interactive TUI context)
        if (recipe.sub_recipes && recipe.sub_recipes.length > 0) {
          if (!context.executeCommand) {
            context.addSystemMessage('info', `Sub-recipes (${recipe.sub_recipes.join(', ')}) skipped — not in interactive context.`);
          } else {
            context.addSystemMessage('info', `Running sub-recipes: ${recipe.sub_recipes.join(', ')}`);
            for (const subName of recipe.sub_recipes) {
              await context.executeCommand(`/recipe run ${subName}`);
            }
          }
        }
      } finally {
        _runningRecipes.delete(recipe.name);
      }

      // Surface the recipe instructions as a formatted message.
      // The user can submit these instructions directly or copy them into the prompt.
      const checks = recipe.success_checks?.length
        ? `\n\nAfter completing the above, verify success by checking:\n${recipe.success_checks.map(c => `  - ${c}`).join('\n')}`
        : '';
      return {
        type: 'message',
        level: 'info',
        content: `**Recipe: ${recipe.name}**\n\nPaste or submit the following instructions to the agent:\n\n---\n${recipe.instructions}${checks}\n---`,
      };
    }

    // /recipe — list all
    const all = loader.list();
    if (all.length === 0) {
      return {
        type: 'message',
        level: 'info',
        content: `No recipes found in ${loader.recipesDir}.\n\nCreate one with: /recipe new <name>`,
      };
    }

    return {
      type: 'menu',
      title: `Recipes (${all.length} found in ${loader.recipesDir})`,
      options: [
        { label: '[+] New recipe…', value: '__new__', desc: 'Scaffold a new recipe YAML' },
        ...all.map(r => ({
          label: r.name,
          value: r.name,
          desc: r.description ?? r.instructions.slice(0, 80),
        })),
      ],
      onSelect: (opt: any) => {
        if (opt.value === '__new__') {
          context.setActivePrompt?.({
            title: 'Recipe name:',
            onResolve: (name: string) => { if (name.trim()) context.executeCommand(`/recipe new ${name.trim()}`); },
          });
        } else {
          context.executeCommand(`/recipe run ${opt.value}`);
        }
      },
    };
  },
});

import { AppState, appStore } from '../../state/app.state';
import { IGovernor } from '../../core/interfaces';
import { recordUsage } from '../../mind/usage.counters';

export type CommandCategory = 'Configuration' | 'Code & Intelligence' | 'Source Control' | 'General' | 'Session & Context';

export type CommandResult = 
  | { type: 'message'; content: string; level: 'info' | 'success' | 'error' }
  | { type: 'menu'; title: string; options: any[]; onSelect?: (val: any) => void | Promise<void> }
  | { type: 'prompt'; title: string; onResolve: (val: string) => void; isMasked?: boolean }
  | { type: 'redirect'; command: string }
  // A rich front-end panel (HelpDashboard / StatsDashboard / DataTableDashboard) forwarded to the
  // TUI as a message carrying a uiComponent + payload.
  | { type: 'dashboard'; uiComponent: string; payload: any }
  | { type: 'none' }; // Handled externally

export interface CommandContext {
  cwd: string;
  options: any; // The global cli options
  codebaseIndexer?: any; // To support /index commands
  graphStore?: any; // Dependency graph, for /impact and /ask
  saveConfig: (updates: any) => Promise<any>;
  addSystemMessage: (level: 'info' | 'success' | 'error', msg: string) => void;
  setActiveMenu: (menu: any) => void;
  setActivePrompt: (prompt: any) => void;
  executeCommand: (cmd: string) => void;
  /**
   * Replace the live conversation with LLM-ready messages (session/branch resume — convert UI
   * entries through messageEntriesToLLM first). Returns false when refused (e.g. mid-turn).
   */
  restoreMessages?: (messages: any[]) => boolean | void;
  /** Return the current live conversation messages (for branching). */
  getMessages?: () => any[];
  /**
   * The active session/task id, when this run has one (see headless.session.ts, which supplies it
   * from the session recorder). Commands that drive the desktop use it to route to that task's own
   * computer session instead of a single shared one — see `isSessionRoutableDesktopRuntime`.
   */
  sessionId?: string;
  /** The evidence inspector's plain-language report for the active conversation (see src/context/inspector.ts). */
  contextReport?: () => string | null;
}

export interface Command {
  name: string;
  aliases?: string[];
  description: string;
  category: CommandCategory;
  /** Demote from the palette + `/` autocomplete (still runnable when typed in full). See PALETTE_HIDDEN. */
  hidden?: boolean;
  isEnabled?: (context: Partial<CommandContext>) => { enabled: boolean; reason?: string };
  execute(args: string[], context: CommandContext): Promise<CommandResult>;
}

// Surface triage (identity/runtime plan, Phase D): the engine registers ~70 commands, but showing
// all of them dilutes discoverability. These are demoted from the palette + `/` autocomplete — they
// remain fully registered and runnable when typed in full (hidden aliases), and their capability is
// reachable through a smaller set of primary verbs + the Ctrl+X mind HUD. Tune freely; nothing here
// deletes a command. Grouped by where the capability now lives:
export const PALETTE_HIDDEN = new Set<string>([
  // Mind layer → the Ctrl+X mind HUD (panels, not commands you type).
  'mind', 'self', 'drives', 'habits', 'dogfood', 'claims', 'ledger', 'taint',
  'exemplars', 'episodes', 'impact', 'replay', 'dream', 'calibration', 'harness', 'journal',
  // Multi-agent variants → /swarm and /beast.
  'speculate', 'evolve', 'council', 'orchestrate', 'heal', 'scout',
  // Time-travel → /rewind.
  'undo', 'checkpoint', 'backups', 'tx',
  // Model / routing internals → /model. ('route' explains a routing decision — a diagnostic
  // readout, not a verb you reach for; it stays runnable when typed in full.)
  'provider', 'tier', 'reasoning', 'routes', 'arms', 'route', 'slot',
  // Variants of a primary verb → the primary (e.g. /context, /diff, /index).
  'context-mode', 'context-window', 'diff-approval', 'diff-file', 'self-critic',
  'a11y', 'agent-decisions', 'index-ai', // 'index-ai' → /index (semantic variant)
  // File-op tools the agent invokes directly — rarely typed as a slash command.
  'edit', 'write',
  // Session resume folds into /sessions (which lists + resumes); output format into /config.
  'resume', 'output',
  // Niche / advanced — reachable when typed, off the browsable surface.
  'agents', 'ask', 'autocommit', 'branch', 'check', 'keys', 'lint', 'log', 'changelog', 'watch',
  // Phase 3 utility readouts — advisory, not primary verbs (run when typed in full).
  'update', 'upgrade', 'power',
  // Already represented by primary product surfaces: Map panel and Security settings/status.
  'map', 'governor',
  'pipelines', 'recipe', 'selection', 'shortcuts', 'headroom',
  // Diagnostic readouts → demoted on the same rule that demoted 'route' above: a thing you run to
  // CHECK the product is not a verb you reach for to DO work. All three stay runnable when typed.
  //   retrieval — "prove semantic search is live: one real embedding call, with the margin"
  //   trace     — recent OTel GenAI spans + where they exported to
  //   sidecars  — optional Python-backed capabilities, i.e. configuring infrastructure
  // The surface had drifted to 33 against a documented ceiling of 30; these are the three least
  // verb-like on it. /evidence and /compliance were the other candidates and are deliberately KEPT —
  // "what the model was shown" and "check documents against a rule set" are things a user wants to
  // find by browsing, not diagnostics.
  'retrieval', 'trace', 'sidecars',
]);

/** Is this command demoted from the browsable palette / autocomplete? (names may carry a leading /) */
export function isHiddenCommand(c: Command): boolean {
  const bare = c.name.toLowerCase().replace(/^\//, '');
  return c.hidden === true || PALETTE_HIDDEN.has(bare);
}

export class CommandRegistry {
  private commands = new Map<string, Command>();

  register(command: Command) {
    this.commands.set(command.name.toLowerCase(), command);
    command.aliases?.forEach(a => this.commands.set(a.toLowerCase(), command));
  }

  async execute(input: string, context: CommandContext): Promise<CommandResult> {
    const [name, ...args] = input.trim().split(/\s+/);
    const command = this.commands.get(name.toLowerCase());

    if (!command) {
      throw new Error(`Unknown command: ${name}`);
    }

    // Recorded under the CANONICAL name, not the alias that was typed, so /mind and /self are one
    // number rather than two halves. Names only — never the arguments (see usage.counters.ts).
    recordUsage('command', command.name);

    return command.execute(args, context);
  }

  getSuggestions(partial: string): string[] {
    const matches = new Set<string>();
    for (const [key, cmd] of this.commands.entries()) {
      if (key.startsWith(partial.toLowerCase())) {
        matches.add(`${cmd.name} — ${cmd.description}`);
      }
    }
    return Array.from(matches);
  }

  getAllCommands(): Command[] {
    const uniqueCommands = new Set<Command>();
    for (const cmd of this.commands.values()) {
      uniqueCommands.add(cmd);
    }
    return Array.from(uniqueCommands);
  }

  /**
   * Palette rows for the Ctrl+K command palette: one entry per registered command (deduped by
   * object identity, so aliases don't double-list), sorted by category then name. This is the
   * SINGLE SOURCE OF TRUTH for "what commands exist" — the palette derives from the live registry
   * (built-ins + user `.bimax/commands/*.md`), so it can never drift from reality the way a
   * hardcoded list does.
   */
  getPaletteOptions(store?: any): { label: string; value: string; desc: string; category: string; disabled?: boolean; disabledReason?: string }[] {
    const ctx: Partial<CommandContext> = { graphStore: store };
    return this.getAllCommands()
      .filter(c => !isHiddenCommand(c)) // curated surface — hidden commands still run when typed
      .map(c => {
        let disabled = false;
        let disabledReason: string | undefined;
        if (c.isEnabled) {
          const res = c.isEnabled(ctx);
          disabled = !res.enabled;
          disabledReason = res.reason;
        }
        return { label: c.name, value: c.name, desc: c.description, category: c.category, disabled, disabledReason };
      })
      .sort((a, b) => a.category.localeCompare(b.category) || a.label.localeCompare(b.label));
  }
}

export const globalCommandRegistry = new CommandRegistry();

import { stateDir } from '../../utils/state.dir';
import * as fs from 'fs';
import * as path from 'path';
import { globalCommandRegistry } from './registry';
import { SessionStore } from '../session';

/**
 * /replay — export the current session transcript as a shareable markdown report.
 */
globalCommandRegistry.register({
  name: '/replay',
  aliases: ['/export'],
  description: 'Export this session as a markdown report',
  category: 'Session & Context',
  execute: async (_args, context) => {
    const store = new SessionStore();
    const messages = await store.loadAll();
    if (messages.length === 0) {
      return { type: 'message', level: 'info', content: 'No session transcript to export yet.' };
    }

    const lines: string[] = [
      `# BiMax Session Replay`,
      ``,
      `- Exported: ${new Date().toISOString()}`,
      `- Workspace: ${context.cwd}`,
      `- Messages: ${messages.length}`,
      ``,
      `---`,
      ``,
    ];
    for (const m of messages) {
      const who = m.role === 'user' ? '🧑 User' : m.role === 'assistant' ? '🤖 BiMax' : 'ℹ️ System';
      const ts = m.timestamp ? new Date(m.timestamp).toLocaleTimeString() : '';
      const text = typeof m.content === 'string' ? m.content.trim() : '';
      lines.push(`### ${who}${ts ? ` · ${ts}` : ''}`, ``, text || '_(empty)_', ``);
    }

    const outDir = path.join(stateDir('.breakglass', context.cwd), 'replays');
    fs.mkdirSync(outDir, { recursive: true });
    const stamp = new Date().toISOString().replace(/[:.]/g, '-');
    const outPath = path.join(outDir, `replay-${stamp}.md`);
    try {
      fs.writeFileSync(outPath, lines.join('\n'), 'utf-8');
    } catch (e: any) {
      return { type: 'message', level: 'error', content: `Failed to write replay: ${e.message}` };
    }
    return { type: 'message', level: 'success', content: `📝 Session exported (${messages.length} messages) to ${path.relative(context.cwd, outPath)}` };
  }
});

import { globalCommandRegistry } from './registry';
import { routeToModel, explainRoute, decideSlot } from '../task.router';

/**
 * `/route` — show which model a prompt would be served by, and why.
 *
 * PS 26117 asks for a demonstration of "model auto selection across at least two different task
 * types". A demonstration needs an artefact: watching two prompts get two answers proves nothing
 * about which model produced them. This prints the slot, the signal that fired, and the model
 * chosen, without spending a turn or a token — so the claim can be checked rather than believed.
 */
globalCommandRegistry.register({
  name: '/route',
  aliases: ['/slot'],
  category: 'Configuration',
  description: 'Explain which model a prompt routes to, and on what signal',
  execute: async (args, _context) => {
    const prompt = args.join(' ').trim();
    if (!prompt) {
      return {
        type: 'message',
        level: 'error',
        content: 'Usage: /route <prompt>\n\n'
          + 'Examples that take different routes:\n'
          + '  /route refactor the tokenizer to stream\n'
          + '  /route read the scanned inspection report and list the findings\n'
          + '  /route draft an approval note as a Word document\n'
          + '  /route what is the difference between let and const',
      };
    }
    // `attachments` deliberately stays empty here: the command classifies the TEXT so an evaluator
    // can retype a prompt and reproduce the decision. A real turn passes its actual attachments,
    // which outrank any textual signal.
    const choice = routeToModel(prompt);
    return { type: 'message', level: 'info', content: explainRoute(prompt, choice) };
  },
});

/** Exported for the headless surface, which renders decisions rather than command output. */
