    // WS1.5: live pool health from the adapter's key manager (ok/fail counts, cooldowns).
    // Rendered as an informational category above the provider picker.
    let poolOptions: any[] = [];
    try {
      const states = context.options?.llmAdapter?.getKeyStates?.() ?? [];
      poolOptions = states.map((s: any) => ({
        label: `${s.onCooldown ? '⏸' : '●'} ${s.label}`,
        value: s.label,
        desc: [
          s.model !== 'default' ? s.model : null,
          `${s.ok} ok / ${s.fail} fail`,
          s.firstTokenMs > 0 ? `~${(s.firstTokenMs / 1000).toFixed(1)}s to first token` : null,
          s.hangs > 0 ? `${s.hangs} hang${s.hangs > 1 ? 's' : ''}` : null,
          s.onCooldown ? `cooldown ${Math.ceil(s.cooldownSecs)}s` : null,
        ].filter(Boolean).join(' · '),
        category: 'Pool health (this session)',
      }));
    } catch { /* adapter optional — key pool UI degrades to provider list only */ }

    return {
      type: 'menu',
      title: 'Select a provider to add / replace its API key',
      options: [
        ...providers.map(p => ({
          label: p.name,
          value: p.name,
          desc: process.env[p.apiKeyEnv] ? `${p.apiKeyEnv} · configured` : `${p.apiKeyEnv} · missing`,
          category: 'Add / replace key',
        })),
        ...poolOptions,
      ],
      onSelect: (opt: any) => {
        // Pool-health rows are informational; only provider rows open the key prompt.
        if (providers.some(p => p.name === opt.value)) promptForKey(opt.value, context);
      },
    };
  }
});

globalCommandRegistry.register({
  name: '/sessions',
  description: 'Browse saved sessions — pick one to preview or resume',
  category: 'Session & Context',
  execute: async (_args, context) => {
    const store = new SessionStore();
    const files = await store.listSessions();
    if (files.length === 0) {
      return { type: 'message', level: 'info', content: 'No saved sessions yet (.breakglass/sessions). They accrue as you chat.' };
    }

    // Enrich with metadata where available (title, cwd, message count, goal)
    const metaMap = new Map(listSessionMeta(80).map(m => [m.id, m]));

    const options = files.slice(0, 40).map(f => {
      const id = f.replace(/\.jsonl$/, '');
      const meta = metaMap.get(id);
      const label = meta?.title && meta.title !== '(no messages yet)'
        ? meta.title.slice(0, 60)
        : prettySessionName(f);
      const descParts: string[] = [prettySessionName(f)];
      if (meta?.cwd) descParts.push(meta.cwd.split('/').slice(-2).join('/'));
      if (meta?.messageCount) descParts.push(`${meta.messageCount} msgs`);
      if (meta?.goalTitle) descParts.push(`goal: ${meta.goalTitle.slice(0, 30)}`);
      return { label, value: f, desc: descParts.join(' · '), category: 'Sessions' };
    });

    return {
      type: 'menu',
      title: 'Saved sessions — pick one to resume (newest first)',
      options,
      onSelect: (opt: any) => { void resumeSession(opt.value, context, store); },
    };
  }
});

globalCommandRegistry.register({
  name: '/resume',
  aliases: ['/session'],
  description: 'Resume a past session by injecting its messages into the current context',
  category: 'Session & Context',
  execute: async (args, context) => {
    const store = new SessionStore();
    if (args[0]) {
      const files = await store.listSessions();
      // Prefer an exact match; only fall back to prefix when it's unambiguous. A short prefix like
      // "2026" otherwise silently resumed whichever session happened to sort first.
      const exact = files.find(f => f === args[0] || f === `${args[0]}.jsonl`);
      let match = exact;
      if (!match) {
        const prefixed = files.filter(f => f.startsWith(args[0]));
        if (prefixed.length === 1) {
          match = prefixed[0];
        } else if (prefixed.length > 1) {
          engineEvents.emit('session_restore_failed', { id: args[0], reason: `more than one saved conversation starts with "${args[0]}"` });
          return { type: 'message', level: 'error', content: `"${args[0]}" matches ${prefixed.length} sessions (${prefixed.slice(0, 5).join(', ')}…). Be more specific or open /sessions.` };
        }
      }
      if (!match) {
        engineEvents.emit('session_restore_failed', { id: args[0], reason: 'no saved conversation has that id' });
        return { type: 'message', level: 'error', content: `No session matching "${args[0]}". Open /sessions to browse.` };
      }
      await resumeSession(match, context, store);
      return { type: 'none' };
    }
    return { type: 'redirect', command: '/sessions' };
  }
});

globalCommandRegistry.register({
  name: '/branch',
  description: 'Fork the current session into a named branch, or switch to a saved one',
  category: 'Session & Context',
  execute: async (args, context) => {
    const store = new SessionStore();

    // /branch create <name> — save current conversation as a named branch
    if (args[0] === 'create' || args[0] === 'save') {
      const name = args.slice(1).join('_').replace(/\s+/g, '_') || '';
      if (!name) return { type: 'message', level: 'error', content: 'Usage: /branch create <name>   (name the fork)' };
      const msgs = context.getMessages?.() || [];
      if (msgs.length === 0) return { type: 'message', level: 'info', content: 'Nothing to branch — conversation is empty.' };
      await store.saveBranch(name, msgs);
      return { type: 'message', level: 'success', content: `Branch "${name}" saved (${msgs.length} message(s)). Resume it later with /branch switch ${name}` };
    }

    // /branch delete <name>
    if (args[0] === 'delete' || args[0] === 'rm') {
      const name = args.slice(1).join('_') || '';
      if (!name) return { type: 'message', level: 'error', content: 'Usage: /branch delete <name>' };
      const ok = await store.deleteBranch(name);
      return ok
        ? { type: 'message', level: 'success', content: `Branch "${name}" deleted.` }
        : { type: 'message', level: 'error', content: `No branch named "${name}".` };
    }

    // /branch switch <name> or /branch list (default)
    const branches = await store.listBranches();

    if (args[0] === 'switch' || args[0] === 'load') {
      const name = args.slice(1).join('_') || '';
      if (!name) return { type: 'message', level: 'error', content: 'Usage: /branch switch <name>' };
      const msgs = await store.loadBranch(name);
      if (msgs.length === 0) return { type: 'message', level: 'error', content: `Branch "${name}" not found or empty. Use /branch list.` };
      if (!context.restoreMessages) {
        return { type: 'message', level: 'error', content: 'Branch restore is not available in this context.' };
      }
      const tail = messageEntriesToLLM(msgs).slice(-40);
      if (context.restoreMessages(tail) === false) return { type: 'none' };
      engineEvents.emit('session_restore', { id: `branch:${name}`, entries: msgs.slice(-400) });
      return { type: 'message', level: 'success', content: `Switched to branch "${name}" · ${tail.length} turn(s) loaded.` };
    }

    // List branches
    if (branches.length === 0) {
      return { type: 'message', level: 'info', content: 'No branches yet. Create one with /branch create <name>' };
    }
    return {
      type: 'menu',
      title: 'Saved branches — pick one to switch to',
      options: branches.map(b => ({ label: b, value: b, desc: `switch to branch "${b}"`, category: 'Branches' })),
      onSelect: async (opt: any) => {
        const msgs = await store.loadBranch(opt.value);
        const tail = messageEntriesToLLM(msgs).slice(-40);
        if (context.restoreMessages) {
          if (context.restoreMessages(tail) === false) return;
          engineEvents.emit('session_restore', { id: `branch:${opt.value}`, entries: msgs.slice(-400) });
          context.addSystemMessage('success', `Switched to branch "${opt.value}" · ${tail.length} turn(s) loaded.`);
        } else {
          context.addSystemMessage('error', 'Branch restore not available.');
        }
      },
    };
  }
});

import { globalCommandRegistry } from './registry';
import { getProviders, setProvider, getCurrentProvider, buildKeyPool } from '../provider';
import { saveApiKeyToEnv } from '../env.loader';
import { curatedModelMenuOptions, isReasoningModel, DEFAULT_LITE_MODEL } from '../models';
import { engineEvents } from '../events';

/**
 * /setup — the guided first-run wizard: provider → API key → model, three explicit steps.
 *
 * Design rules (per the CLI onboarding redesign):
 *  - NOTHING is auto-picked. The user chooses the provider, pastes the key, and picks the model
 *    themselves — the wizard never silently lands them on a default they didn't choose.
 *  - Every provider row carries the URL where its key actually lives (rendered as a clickable
 *    OSC-8 link in the TUI), so "go get a key" is one click, not a search.
 *  - The model step defaults to "one model for everything" — the split coding/lite/sub-agent
 *    slots stay one hop away in /model for people who want them.
 *  - Runs automatically on a keyless first launch (headless.entry), and stays re-runnable any
 *    time via /setup.
 */

// Picking a provider without a key drops the user straight onto the page where the key is minted:
// the URL is opened in their default browser AND copied to the clipboard (both best-effort — a
// headless/SSH box just skips them and the OSC-8 link in the prompt title still works).
function openKeyPage(url: string): void {
  const { spawn } = require('child_process') as typeof import('child_process');
  const opener = process.platform === 'darwin' ? ['open', url]
    : process.platform === 'win32' ? ['cmd', '/c', 'start', '', url]
    : ['xdg-open', url];
  try { spawn(opener[0], opener.slice(1), { stdio: 'ignore', detached: true }).unref(); } catch { /* no GUI */ }
  try {
    if (process.platform === 'darwin') {
      const pb = spawn('pbcopy', [], { stdio: ['pipe', 'ignore', 'ignore'] });
      pb.stdin.end(url);
    }
  } catch { /* clipboard optional */ }
}

// Where each provider's API keys are minted. Shown as the wizard's clickable links.
const KEY_PAGES: Record<string, { url: string; note: string }> = {
  nvidia: { url: 'https://build.nvidia.com', note: 'Free tier — generous limits, no card needed' },
  openai: { url: 'https://platform.openai.com/api-keys', note: 'Paid — GPT-4o and friends' },
  anthropic: { url: 'https://console.anthropic.com/settings/keys', note: 'Paid — Claude models' },
  openrouter: { url: 'https://openrouter.ai/keys', note: 'One key, many models (incl. free ones)' },
  deepseek: { url: 'https://platform.deepseek.com/api_keys', note: 'Cheap strong coder models' },
  google: { url: 'https://aistudio.google.com/apikey', note: 'Free tier — Gemini models' },
};

function stepModel(context: any): void {
  // Fetch the fresh provider's live model list (the key was applied moments ago), then present
  // the CURATED picker — explicit choice, never an auto-selected default.
  void (async () => {
    let live: string[] | null = null;
    try {
      const ids = await context.options?.llmAdapter?.listProviderModels?.();
      if (ids && ids.length) live = ids;
    } catch { /* offline / no models endpoint — curated catalog still works */ }

    const applyEverywhere = (model: string) => {
      // Reasoners never fill the lite slot (no API switch turns their thinking off — small talk
      // and aux calls would each hide 20-30s of CoT). Quick replies run on the plain lite default.
      const lite = isReasoningModel(model) ? DEFAULT_LITE_MODEL : model;
      try { context.options?.llmAdapter?.applyConfig?.({ model, liteModel: lite }); } catch { /* optional */ }
      context.options.model = model;
      (context.options as any).liteModel = lite;
      context.saveConfig({ model, liteModel: lite, subagentModel: '', onboardingKeysDone: true });
      engineEvents.emit('config_changed');
      context.addSystemMessage('success', lite === model
        ? `You're set: everything runs on ${model}.`
        : `You're set: ${model} does the work · ${lite} answers quick replies instantly.`);
      context.addSystemMessage('info',
        'Quickstart — just describe an outcome ("explain this codebase", "fix the failing test"). ' +
        'Useful next: /help commands · /model change models · Shift+Tab cycles agent modes · Ctrl+A live sub-agents.');
    };

    context.setActiveMenu?.({
      title: 'Step 3 of 3 — Pick your model',
      subtitle: 'Runs everything · split slots later via /model',
      options: [
        ...curatedModelMenuOptions(live, context.options?.model),
        {
          label: '⌕ Browse all…',
          value: '__browse__',
          desc: live ? `All ${live.length} ids on ${getCurrentProvider().name}` : 'Full provider catalog',
          category: 'More',
        },
        { label: '✎ Custom id…', value: '__custom__', desc: 'Type any model id', category: 'More' },
      ],
      onSelect: (opt: any) => {
        if (opt.value === '__browse__') { context.executeCommand?.('/model browse one'); return; }
        if (opt.value === '__custom__') {
          context.setActivePrompt({
            title: 'Enter a model id (e.g. publisher/model-name)',
            onResolve: (val: string) => {
              const id = (val || '').trim();
              if (id) applyEverywhere(id);
              else context.addSystemMessage('info', 'No model id entered — run /setup or /model when ready.');
            },
          });
          return;
        }
        applyEverywhere(opt.value);
      },
    });
  })();
}

function stepKey(providerName: string, context: any): void {
  const match = getProviders().find(p => p.name === providerName);
  if (!match) return;
  const page = KEY_PAGES[providerName];
  context.setActivePrompt({
    title: `Step 2 of 3 — Paste your ${match.name} API key${page ? ` (get one: ${page.url})` : ''}`,
    isMasked: true,
    onResolve: (keyStr: string) => {
      const key = (keyStr || '').trim();
      if (!key) {
        context.addSystemMessage('info', 'No key entered — run /setup again when you have one.');
        return;
      }
      try {
        saveApiKeyToEnv(match.apiKeyEnv, key);
        process.env[match.apiKeyEnv] = key;
        try { context.options?.llmAdapter?.setKeys?.(buildKeyPool()); } catch { /* adapter optional */ }
        context.addSystemMessage('success', `${match.apiKeyEnv} saved to ~/.breakglass/.env — keys stay on this machine.`);
        stepModel(context);
      } catch (e: any) {
        context.addSystemMessage('error', `Failed to save key: ${e.message}`);
      }
    },
  });
}

globalCommandRegistry.register({
  name: '/setup',
  aliases: ['/onboard', '/start'],
  description: 'Guided setup — pick a provider, add your key, choose your model',
  category: 'Configuration',
  execute: async (_args, context) => {
    const providers = getProviders();
    return {
      type: 'menu',
      title: 'Welcome to Bimax — Step 1 of 3 — Choose your AI provider',
      subtitle: 'Bimax is the harness; you bring the model. Your key is stored locally and sent only to the provider you pick.',
      options: providers.map(p => {
        const page = KEY_PAGES[p.name];
        const hasKey = !!process.env[p.apiKeyEnv];
        return {
          label: hasKey ? `● ${p.name}` : p.name,
          value: p.name,
          desc: `${page?.note || p.baseURL}${hasKey ? ' · key already set' : ''}`,
          category: page && page.note.startsWith('Free') ? 'Free to start' : 'Bring a paid key',
          link: page?.url,
        };
      }),
      onSelect: (opt: any) => {
        const found = setProvider(opt.value);
        if (!found) return;
        try { saveApiKeyToEnv('BGW_PROVIDER', opt.value); } catch { /* persistence optional */ }
        if (process.env[found.apiKeyEnv]) {
          context.addSystemMessage('success', `Provider: ${found.name} (key already configured).`);
          stepModel(context);
        } else {
          const page = KEY_PAGES[opt.value];
          if (page) {
            openKeyPage(page.url);
            context.addSystemMessage('info', `Opening ${page.url} in your browser (link copied) — grab a key, then paste it below.`);
          }
          stepKey(opt.value, context);
        }
      },
    };
  },
});

import * as fs from 'fs';
import * as path from 'path';
import { globalCommandRegistry } from './registry';
import { globalSkillService } from '../../skills/skill.service';

const SKILL_TEMPLATE = (name: string) => `---
name: ${name}
description: One sentence on what this skill does and WHEN to use it (the model reads this to decide).
# allowed-tools: BashTool, ReadFileTool   # optional, advisory
---

# ${name}

Write the step-by-step instructions the agent should follow when this skill is loaded.

1. ...
2. ...

Put any helper scripts or templates next to this SKILL.md; the agent can read or run them.
`;

// Agent Skills — model-invoked capability packs (SKILL.md). Distinct from JSON agent personas,
// which are listed under /agents.
globalCommandRegistry.register({
  name: '/skills',
  category: 'Configuration',
  description: 'List / create Agent Skills (SKILL.md capability packs)',
  execute: async (args, context) => {
    const sub = (args[0] || '').toLowerCase();

    if (sub === 'new') {
      const name = (args[1] || '').toLowerCase().replace(/[^a-z0-9-]/g, '-');
      if (!name) return { type: 'message', level: 'error', content: 'Usage: /skills new <name>' };
      const dir = path.join(context.cwd, '.bimax', 'skills', name);
      const file = path.join(dir, 'SKILL.md');
      if (fs.existsSync(file)) return { type: 'message', level: 'info', content: `Skill '${name}' already exists at ${file}.` };
      fs.mkdirSync(dir, { recursive: true });
      fs.writeFileSync(file, SKILL_TEMPLATE(name), 'utf8');
      globalSkillService.load(context.cwd);
      return { type: 'message', level: 'success', content: `Created ${file} — edit it, then /skills reload.` };
    }

    // Default + `/skills reload`: (re)scan and list.
    globalSkillService.load(context.cwd);
    const skills = globalSkillService.list();
    if (skills.length === 0) {
      return {
        type: 'message',
        level: 'info',
        content: 'No Agent Skills installed. Create one with /skills new <name> (writes .bimax/skills/<name>/SKILL.md). JSON agent personas are under /agents.',
      };
    }
    return {
      type: 'menu',
      title: 'Agent Skills (model-invoked via SkillTool)',
      options: skills.map(s => ({
        label: s.name,
        value: `skill:${s.name}`,
        desc: `${s.description.slice(0, 70)}${s.description.length > 70 ? '…' : ''} · ${s.source}`,
      })),
      onSelect: (opt: any) => {
        const name = String(opt.value).replace(/^skill:/, '');
        const s = globalSkillService.get(name);
        if (s) context.addSystemMessage('info', `${s.name} — ${s.description}\nSource: ${s.dir}`);
      },
    };
  },
});

import { createHash } from 'node:crypto';
import * as fs from 'fs';
import * as path from 'path';
import { globalCommandRegistry } from './registry';
import {
  isSovereign, setSovereignMode, sovereignAllowlist, setSovereignAllowlist, classifyDestination, hostOf,
} from '../../security/sovereign';
import {
  sessionEgress, summarize, readLedger, ledgerPath, ledgerWriteFailures, EgressSummary,
  verifyLedger, ledgerHead, ChainVerification,
} from '../../security/egress.ledger';
import { canonicalJson } from '../../evidence/schema';
import { isEgressPerimeterInstalled, unpatchableEgressSurfaces } from '../../security/egress.perimeter';
import { isSandboxEnabled, sandboxAvailable, sandboxBackend } from '../../sandbox/exec.sandbox';

/**
 * `/sovereign` — the command that turns the sovereignty claim into something someone else can read.
 *
 * The ledger has always held the evidence; nothing surfaced it, so "no external calls were made"
 * was an assertion rather than an artefact. PS 26117 is explicit that the artefact is the
 * deliverable ("through logs or a visible network monitor... that's the actual proof of the
 * sovereign claim, not just a statement of it"), and this is where an evaluator reads it.
 *
 * Two scopes, deliberately distinguished. THIS SESSION answers "what did this run contact?" from
 * the in-memory mirror. ON DISK answers "what has this installation ever contacted?" by re-reading
 * the NDJSON, which is the question an audit actually asks and the one a session-scoped counter
 * cannot answer.
 */

/** `142 attempts · 142 loopback · 0 external` — the line an auditor reads first. */
function headline(s: EgressSummary): string {
  const parts = [`${s.attempts} attempt${s.attempts === 1 ? '' : 's'}`];
  if (s.loopback) parts.push(`${s.loopback} loopback`);
  if (s.privateLan) parts.push(`${s.privateLan} private-lan`);
  if (s.allowlisted) parts.push(`${s.allowlisted} allowlisted`);
  parts.push(`${s.external} external`);
  if (s.refused) parts.push(`${s.refused} refused`);
  return parts.join(' · ');
}

/**
 * The honesty footnote. A ledger that failed to write is INCOMPLETE, and a report that presented an
 * incomplete ledger as a complete one would be the exact overstatement this whole subsystem exists
 * to remove.
 */
function completeness(): string[] {
  const out: string[] = [];
  const failures = ledgerWriteFailures();
  if (failures > 0) {
    out.push(`⚠ ${failures} ledger write${failures === 1 ? '' : 's'} failed — the file on disk is INCOMPLETE.`);
  }
  if (!isEgressPerimeterInstalled()) {
    out.push('⚠ The egress perimeter is NOT installed in this process. Only modules that call the '
      + 'guard explicitly are covered, so this report is not a whole-process claim.');
  }
  const holes = unpatchableEgressSurfaces();
  if (holes.length > 0) {
    out.push(`⚠ The perimeter could not wrap: ${holes.join(', ')}. Traffic through those is unrecorded.`);
  }
  return out;
}

/**
 * The chain verdict, phrased so it cannot be read as more than it is.
 *
 * "intact" means nothing edited a line in place or removed one. It does NOT mean the file is
 * authentic — a wholesale rewrite recomputes every digest and verifies clean. The only defence
 * against that is a head recorded outside this process, so the head is always printed.
 */
function chainReport(v: ChainVerification): string[] {
  const out: string[] = [];
  if (v.checked === 0) {
    out.push(v.unchained > 0
      ? `Chain: NOT VERIFIABLE — all ${v.unchained} entries predate chaining and carry no digest.`
      : 'Chain: nothing to verify — the ledger is empty.');
  } else if (v.intact) {
    out.push(`Chain: intact — ${v.checked} entr${v.checked === 1 ? 'y' : 'ies'} verified`
      + `${v.unchained ? `, ${v.unchained} earlier entr${v.unchained === 1 ? 'y' : 'ies'} unchained` : ''}.`);
  } else {
    out.push(`Chain: BROKEN at entry ${v.brokenAt} — ${v.reason}`);
    out.push(`  ${v.checked} entr${v.checked === 1 ? 'y' : 'ies'} before it verified; everything after is unproven.`);
  }
  if (v.head) {
    out.push(`Head:  ${v.head}`);
    out.push('  Record this digest somewhere Bimax cannot write. A later report that presents a');
    out.push('  different head for the same history has been rewritten, which the chain alone');
    out.push('  cannot detect.');
  }
  return out;
}

/** How the shell is governed — the half of the claim the in-process perimeter cannot make. */
function shellPosture(): string {
  if (!isSovereign()) {
    return isSandboxEnabled() ? 'sandbox on (network permitted — ordinary profile)' : 'sandbox off';
  }
  if (!sandboxAvailable()) {
    return 'NO OS BACKEND — BashTool is refused rather than run without kernel isolation';
  }
  return `network denied at the kernel (${sandboxBackend()})`;
}

function statusReport(): string {
  const on = isSovereign();
  const allow = sovereignAllowlist();
  const session = summarize(sessionEgress());
  const lines = [
    `Sovereign mode: ${on ? 'ON — external egress fails closed' : 'off — external egress is permitted and recorded'}`,
    `Egress perimeter: ${isEgressPerimeterInstalled() ? 'installed (fetch · http · https · net · tls · dns)' : 'NOT INSTALLED'}`,
    `Shell:            ${shellPosture()}`,
    `Allowlist:        ${allow.length ? allow.join(', ') : '(empty — only loopback and private-LAN are local)'}`,
    '',
    `This session:     ${headline(session)}`,
  ];
  if (session.externalHosts.length > 0) {
    lines.push(`External hosts:   ${session.externalHosts.join(', ')}`);
  }
  lines.push('', `Ledger: ${ledgerPath()}`);
  const currentHead = ledgerHead();
  if (currentHead) lines.push(`Head:   ${currentHead}  (/sovereign verify to check the chain)`);
  lines.push(...completeness());
  return lines.join('\n');
}

function fullReport(): string {
  const session = summarize(sessionEgress());
  const { entries, skipped } = readLedger();
  const disk = summarize(entries);
  const lines = [
    'EGRESS REPORT',
    '',
    `This session: ${headline(session)}`,
    `On disk:      ${headline(disk)}${skipped ? ` (${skipped} unreadable line${skipped === 1 ? '' : 's'} skipped)` : ''}`,
    `Ledger file:  ${ledgerPath()}`,
    '',
  ];

  if (disk.external === 0) {
    lines.push('No external destination was ever contacted by this installation.');
  } else {
    lines.push(`External destinations contacted (${disk.externalHosts.length}):`);
    for (const host of disk.externalHosts) {
      const hits = entries.filter(e => e.host === host);
      const refused = hits.filter(e => e.verdict === 'refused').length;
      const by = [...new Set(hits.map(e => e.subsystem))].join(', ');
      lines.push(`  ${host} — ${hits.length} attempt${hits.length === 1 ? '' : 's'}`
        + `, ${refused} refused · from ${by}`);
    }
  }

  const recent = entries.slice(-12);
  if (recent.length > 0) {
    lines.push('', `Last ${recent.length} attempt${recent.length === 1 ? '' : 's'}:`);
    for (const e of recent) {
      lines.push(`  ${e.at}  ${e.verdict === 'refused' ? 'REFUSED' : 'allowed'}  `
        + `${e.destination.padEnd(11)} ${e.host}  (${e.subsystem}${e.purpose ? ` ${e.purpose}` : ''})`);
    }
  }

  lines.push('');
  lines.push(...chainReport(verifyLedger(entries)));

  lines.push('');
  lines.push('Scope: this records what the APPLICATION attempted. A child process has its own network');
  lines.push('stack and is governed by the sandbox, not by this ledger — see /sovereign status.');
  lines.push(...completeness());
  return lines.join('\n');
}

/**
 * A self-contained proof bundle an evaluator can carry away and re-check.
 *
 * The bundle digests itself over its canonical form, so the summary and the entries it claims to
 * summarise cannot be separated: change a count and the bundle digest stops matching; change an
 * entry and the chain inside it breaks as well.
 */
function buildBundle(): { bundle: Record<string, unknown>; verification: ChainVerification } {
  const { entries, skipped } = readLedger();
  const verification = verifyLedger(entries);
  const body = {
    kind: 'bimax.egress-proof/v1',
    generatedAt: new Date().toISOString(),
    posture: {
      sovereign: isSovereign(),
      perimeterInstalled: isEgressPerimeterInstalled(),
      unpatchableSurfaces: unpatchableEgressSurfaces(),
      shell: shellPosture(),
      allowlist: sovereignAllowlist(),
    },
    ledger: {
      path: ledgerPath(),
      writeFailures: ledgerWriteFailures(),
      unreadableLines: skipped,
    },
    chain: verification,
    summary: { session: summarize(sessionEgress()), disk: summarize(entries) },
    entries,
  };
  const bundleDigest = createHash('sha256').update(canonicalJson(body)).digest('hex');
  return { bundle: { ...body, bundleDigest }, verification };
}

globalCommandRegistry.register({
  name: '/sovereign',
  aliases: ['/airgap', '/offline'],
  category: 'Configuration',
  description: 'Air-gap mode — fail-closed external egress, and the ledger that proves it',
  execute: async (args, _context) => {
    const sub = (args[0] || 'status').toLowerCase();

    if (sub === 'on' || sub === 'off') {
      setSovereignMode(sub === 'on');
      return {
        type: 'message',
        level: 'success',
        content: sub === 'on'
          ? `Sovereign mode ON.\n\n${statusReport()}`
          : `Sovereign mode off. Egress is still RECORDED — the ledger keeps answering "what did it `
            + `contact?" whether or not the mode is on.\n\n${statusReport()}`,
      };
    }

    if (sub === 'report') {
      return { type: 'message', level: 'info', content: fullReport() };
    }

    if (sub === 'verify') {
      const v = verifyLedger();
      return {
        type: 'message',
        // Three states, not two. A chain with nothing in it to check is neither a pass nor a
        // failure, and reading green because there was nothing to verify is the exact failure mode
        // this command exists to remove — so it resolves to `info`, never `success`.
        level: !v.intact ? 'error' : v.checked === 0 ? 'info' : 'success',
        content: [`Ledger: ${ledgerPath()}`, '', ...chainReport(v)].join('\n'),
      };
    }

    if (sub === 'export') {
      const target = (args[1] || '').trim();
      if (!target) {
        return {
          type: 'message', level: 'error',
          content: 'Usage: /sovereign export <path>\n\nWrites a self-contained proof bundle — the '
            + 'posture, the summary, the chain verdict and every recorded attempt — digested over '
            + 'its own canonical form so the summary cannot be separated from the entries it '
            + 'summarises.',
        };
      }
      const { bundle, verification } = buildBundle();
      const out = path.resolve(target);
      try {
        fs.mkdirSync(path.dirname(out), { recursive: true });
        // 0600: the bundle carries every hostname and purpose the ledger does.
        fs.writeFileSync(out, `${JSON.stringify(bundle, null, 2)}\n`, { mode: 0o600 });
      } catch (error) {
        return {
          type: 'message', level: 'error',
          content: `Could not write ${out}: ${error instanceof Error ? error.message : String(error)}`,
        };
      }
      return {
        type: 'message',
        level: verification.intact ? 'success' : 'error',
        content: [
          `Wrote ${out}`,
          `Bundle digest: ${bundle.bundleDigest}`,
          '',
          ...chainReport(verification),
        ].join('\n'),
      };
    }

    if (sub === 'json') {
      const { entries, skipped } = readLedger();
      return {
        type: 'message',
        level: 'info',
        content: JSON.stringify({
          sovereign: isSovereign(),
          perimeterInstalled: isEgressPerimeterInstalled(),
          unpatchableSurfaces: unpatchableEgressSurfaces(),
          shell: shellPosture(),
          allowlist: sovereignAllowlist(),
          ledgerPath: ledgerPath(),
          ledgerWriteFailures: ledgerWriteFailures(),
          unreadableLines: skipped,
          chain: verifyLedger(entries),
          session: summarize(sessionEgress()),
          disk: summarize(entries),
        }, null, 2),
      };
    }

    if (sub === 'allow') {
      const host = (args[1] || '').trim().toLowerCase();
      if (!host) {
        return {
          type: 'message', level: 'error',
          content: 'Usage: /sovereign allow <host>\n\nDeclares an on-premises host that carries an '
            + 'ordinary name (an internal vLLM box at models.corp.mrpl, say). A leading dot covers '
            + 'subdomains. This is an operator decision and it is recorded in the ledger like any '
            + 'other — it does not make the host local, it records that you asserted it is.',
        };
      }
      const next = [...new Set([...sovereignAllowlist(), host])];
      setSovereignAllowlist(next);
      return {
        type: 'message', level: 'success',
        content: `Allowlisted "${host}" (${classifyDestination(host)}).\nAllowlist: ${next.join(', ')}\n\n`
          + 'This is a session override. Persist it with BIMAX_SOVEREIGN_ALLOW to survive a restart.',
      };
    }

    if (sub === 'check') {
      const target = (args[1] || '').trim();
      if (!target) {
        return { type: 'message', level: 'error', content: 'Usage: /sovereign check <url-or-host>' };
      }
      const destination = classifyDestination(target);
      const refused = isSovereign() && destination === 'external';
      return {
        type: 'message',
        level: refused ? 'error' : 'success',
        content: `${target}\n  host:        ${hostOf(target) || '(unparseable)'}\n`
          + `  destination: ${destination}\n  verdict:     ${refused ? 'REFUSED' : 'allowed'}\n\n`
          + 'Classified by name only — resolving it would itself be egress, and the answer could '
          + 'change between the check and the connection.',
      };
    }

    if (sub === 'status') {
      return { type: 'message', level: 'info', content: statusReport() };
    }

    return {
      type: 'message', level: 'error',
      content: 'Usage: /sovereign [status | on | off | report | verify | export <path> | json '
        + '| allow <host> | check <host>]',
    };
  },
});

import { globalCommandRegistry } from './registry';
import { SafetyPolicy } from '../../governor/policy.engine';
import { HISTORY_DAYS, SpendLedger, resolveSpendContext } from '../../governor/spend.ledger';

/**
 * /spend — what today has cost, across every Bimax Thread on this Mac.
 *
 * Backlog N6/F5: Bimax measured turn time per model and never showed money. Worse, until
 * `spend.ledger.ts` there was no single number to show — each Bimax Thread kept its own daily total
 * under its own state directory, so "the" daily spend did not exist.
 */

function money(n: number): string {
  return `$${n.toFixed(n < 0.01 && n > 0 ? 4 : 2)}`;
}

globalCommandRegistry.register({
  name: '/spend',
  aliases: ['/budget', '/cost'],
  category: 'Configuration',
  description: "Today's spend for this Mac, by task, against the daily cap",
  execute: async () => {
    const { path: ledgerPath, scope } = resolveSpendContext();
    const cap = SafetyPolicy.maxDailySpendUsd;

    if (!ledgerPath) {
      return {
        type: 'message', level: 'info',
        content: [
          '## Spend', '',
          'No shared ledger is configured for this process, so only this engine’s own daily total applies.',
          '',
          'The desktop sets `BIMAX_SPEND_LEDGER_PATH` when it starts a Bimax Thread; a bare CLI run keeps its',
          'own per-folder total, which is the behaviour that predates the shared ledger.',
          '',
          `Daily cap: **${money(cap)}** (raise with \`MAX_DAILY_SPEND\`, or turn the cap off with \`/governor off\`).`,
        ].join('\n'),
      };
    }

    let state;
    let breakdown: Array<{ scope: string; spent: number }>;
    let summary: ReturnType<SpendLedger['summary']>;
    try {
      const ledger = new SpendLedger(ledgerPath);
      state = ledger.read(scope);
      breakdown = ledger.breakdown();
      summary = ledger.summary();
    } catch (e: any) {
      return {
        type: 'message', level: 'error',
        content: `Could not read the spend ledger at \`${ledgerPath}\`: ${e?.message || e}\n\nSpending is not blocked by this — the governor falls back to this engine’s own daily total.`,
      };
    }

    const remaining = cap > 0 ? Math.max(0, cap - state.total) : null;
    const pct = cap > 0 ? Math.round((state.total / cap) * 100) : null;

    const lines = [
      '## Spend', '',
      cap > 0
        ? `**${money(state.total)} of ${money(cap)}** today (${pct}%), **${money(remaining!)} left** — across every Bimax Thread on this Mac.`
        : `**${money(state.total)}** today. No cap is set (\`MAX_DAILY_SPEND\` is 0 or the governor is off).`,
      '',
    ];

    if (scope) {
      const share = parseFloat(process.env.BIMAX_SPEND_SCOPE_CAP || '');
      lines.push(
        Number.isFinite(share) && share > 0
          ? `This task: **${money(state.scopeTotal)} of ${money(share)}** of its own share.`
          : `This task: **${money(state.scopeTotal)}** (no per-task share set — bounded only by the Mac’s cap).`,
        '',
      );
    }

    if (breakdown.length) {
      lines.push('**By task**', '');
      for (const row of breakdown) {
        lines.push(`- \`${row.scope}\`${row.scope === scope ? ' *(this one)*' : ''} — ${money(row.spent)}`);
      }
      lines.push('');
    } else if (state.total === 0) {
      lines.push('_Nothing spent yet today._', '');
    }

    // N6: by model today, and the days before — the ledger used to forget each day at midnight.
    if (summary.models.length) {
      lines.push('**By model**', '');
      for (const row of summary.models) lines.push(`- \`${row.model}\` — ${money(row.spent)}`);
      lines.push('');
    }
    if (summary.days.length) {
      lines.push('**Earlier days**', '');
      for (const day of summary.days.slice(0, 7)) {
        const top = Object.entries(day.models).sort((a, b) => b[1] - a[1])[0];
        lines.push(`- ${day.date} — ${money(day.total)}${top ? ` (most on \`${top[0]}\`)` : ''}`);
      }
      lines.push('');
    }

    lines.push(
      `_Today resets at UTC midnight; earlier days are kept for ${HISTORY_DAYS} days. Ledger: \`${ledgerPath}\`. Set the daily cap and each task’s share in Settings → Agent behavior._`,
    );

    return { type: 'message', level: 'info', content: lines.join('\n') };
  },
});

import { globalCommandRegistry } from './registry';
import { globalSubAgentBlackboard, SubAgentClaim } from '../../core/subagent.blackboard';
import { engineEvents } from '../events';
import { formatSubAgentResult } from '../../core/subagent.result';

const ICON: Record<SubAgentClaim['status'], string> = { running: '◍', done: '✓', failed: '✗' };

function fmtAge(c: SubAgentClaim): string {
  const ms = (c.endedAt ?? Date.now()) - c.startedAt;
  const s = Math.round(ms / 1000);
  return s < 60 ? `${s}s` : `${Math.floor(s / 60)}m${s % 60}s`;
}

export function renderSubagents(claims: SubAgentClaim[]): string {
  if (claims.length === 0) return '● **Sub-agents**\n\n  None spawned this session.';
  const running = claims.filter(c => c.status === 'running').length;
  const lines = ['● **Sub-agents** — ' + `${running} running · ${claims.length} total`, ''];
  for (const c of claims) {
    lines.push(`  ${ICON[c.status]} **${c.agentType}** · \`${c.scope}\` · ${c.toolCalls} tool calls · ${fmtAge(c)}`);
    lines.push(`     ${c.prompt}`);
    if (c.status === 'failed' && c.error) lines.push(`     ✗ ${c.error.slice(0, 160)}`);
  }
  return lines.join('\n');
}

globalCommandRegistry.register({
  name: '/subagents',
  description: 'Live sub-agent coverage — who is running, their scope, and status. `timings` shows boot vs model latency; `resume` respawns a crashed session\'s agents.',
  category: 'Code & Intelligence',
  execute: async (args) => {
    // Deferred requires keep command registration free of core-module init order concerns.
    // eslint-disable-next-line @typescript-eslint/no-require-imports
    const ckpt = require('../../core/agent.checkpoint') as typeof import('../../core/agent.checkpoint');

    if ((args[0] || '').toLowerCase() === 'timings') {
      // WS2 measurement view: where do the seconds go — boot overhead (ours) vs the model's
      // time-to-first-action vs the tool loop. Folded from the lifecycle journal in the ledger.
      // eslint-disable-next-line @typescript-eslint/no-require-imports
      const { foldSubagentRuns, summarizeRun } = require('../../core/subagent.journal') as typeof import('../../core/subagent.journal');
      const runs = foldSubagentRuns();
      if (runs.length === 0) {
        return { type: 'message', level: 'info', content: 'No sub-agent runs recorded yet (journal is empty).' };
      }
      const boots = runs.map(r => r.msToReady).filter((n): n is number => n !== undefined).sort((a, b) => a - b);
      const median = boots.length ? boots[Math.floor(boots.length / 2)] : undefined;
      const lines = [`● **Sub-agent timings** — ${runs.length} run(s)`, ''];
      if (median !== undefined) lines.push(`  Median boot overhead: **${median}ms**  (key pool · config · graph load · tool registration · persona)`, '');
      for (const r of runs.slice(-20)) lines.push(`  ${summarizeRun(r)}`);
      return { type: 'message', level: 'info', content: lines.join('\n') };
    }

    if ((args[0] || '').toLowerCase() === 'resume') {
      const recoverable = ckpt.crashedAgents();
      if (recoverable.length === 0) {
        return { type: 'message', level: 'info', content: 'No crashed sub-agents to resume.' };
      }
      // eslint-disable-next-line @typescript-eslint/no-require-imports
      const { globalSubAgentManager } = require('../../core/subagent.manager') as typeof import('../../core/subagent.manager');
      // eslint-disable-next-line @typescript-eslint/no-require-imports
      const { getOutcomeManager } = require('../../outcome/outcome.manager') as typeof import('../../outcome/outcome.manager');
      const { randomUUID } = require('crypto') as typeof import('crypto');
      let outcomeManager: ReturnType<typeof getOutcomeManager> | null = null;
      try { outcomeManager = getOutcomeManager(); } catch { /* uncoordinated legacy recovery */ }

      const coordinated = recoverable.filter(agent => agent.config.outcomeTaskId);
      const missingSession = coordinated.find(agent => !agent.config.outcomeSessionId);
      if (missingSession) {
        return { type: 'message', level: 'error', content: 'A crashed coordinated agent predates session-bound recovery and cannot be resumed safely. Requeue its outcome task from the original session.' };
      }
      const sessions = [...new Set(coordinated.map(agent => agent.config.outcomeSessionId).filter(Boolean))];
      if (sessions.length > 1) {
        return { type: 'message', level: 'error', content: `The crash snapshot contains agents from multiple outcome sessions (${sessions.join(', ')}). Resume and recover each session separately.` };
      }
      const outcomeTaskIds = coordinated.map(agent => agent.config.outcomeTaskId!);
      const duplicateTask = outcomeTaskIds.find((id, index) => outcomeTaskIds.indexOf(id) !== index);
      if (duplicateTask) {
        return { type: 'message', level: 'error', content: `The crash snapshot contains multiple workers for outcome task ${duplicateTask}. The checkpoint was preserved for manual review.` };
      }
      const requiredSession = sessions[0] || '';
      if (requiredSession && outcomeManager?.activeSessionId() !== requiredSession) {
        return { type: 'message', level: 'error', content: `These agents belong to outcome session ${requiredSession}. Run \`/resume ${requiredSession}\` first, then \`/subagents resume\`.` };
      }

      // Validate the entire coordinated snapshot before consuming it. A stale owner or an
      // ineligible task must leave every checkpoint intact for inspection and manual repair.
      if (outcomeManager) {
        try {
          for (const agent of coordinated) {
            outcomeManager.assertAssignmentRecoverable(agent.config.outcomeTaskId!, agent.claim.taskId);
          }
        } catch (error: any) {
          return {
            type: 'message', level: 'error',
            content: `Recovery validation failed; the crash checkpoint was preserved. ${error?.message || error}`,
          };
        }
      }

      // Consume the dead snapshot BEFORE registering replacement workers. Clearing it afterwards
      // would delete the brand-new checkpoint written by the first resumed agent.
      const crashed = ckpt.consumeCrashedAgents();
      const lines = [`Respawning ${crashed.length} sub-agent(s) from the crashed session:`];
      for (const a of crashed) {
        const taskId = `subagent-${randomUUID()}`;
        const config = ckpt.resumeConfigFor(a);
        if (a.config.outcomeTaskId && outcomeManager) {
          try { outcomeManager.resumeAssignment(a.config.outcomeTaskId, a.claim.taskId, taskId); }
          catch (error: any) {
            lines.push(`  ✗ ${a.claim.agentType} · \`${a.claim.scope}\` · ${error?.message || error}`);
            continue;
          }
        }
        // Fire-and-forget like SpawnSubagentTool — results surface as system messages via the board.
        globalSubAgentManager.spawnWorker(taskId, config).then(result => {
          const text = formatSubAgentResult(result);
          if (config.outcomeTaskId && config.outcomeSessionId && outcomeManager) {
            try { outcomeManager.settleAssignmentForSession(config.outcomeSessionId, config.outcomeTaskId, taskId, true, result); } catch { /* task remains inspectable */ }
          }
          engineEvents.emit('message', {
            id: `subagent-result-${taskId}`, role: 'system', level: 'success',
            content: `✓ Resumed sub-agent ${config.agentType} (${taskId}) finished:\n\n${text.slice(0, 4000)}`,
            timestamp: new Date(),
          });
        }).catch(error => {
          if (config.outcomeTaskId && config.outcomeSessionId && outcomeManager) {
            try { outcomeManager.settleAssignmentForSession(config.outcomeSessionId, config.outcomeTaskId, taskId, false, error?.message || String(error)); } catch { /* task remains inspectable */ }
          }
        });
        lines.push(`  ◍ ${a.claim.agentType} · \`${a.claim.scope}\` · ${a.claim.prompt}`);
      }
      return { type: 'message', level: 'success', content: lines.join('\n') };
    }

    globalSubAgentBlackboard.prune();
    let out = renderSubagents(globalSubAgentBlackboard.all());
    const crashed = ckpt.crashedAgents();
    if (crashed.length > 0) {
      out += `\n\n  ⚠ ${crashed.length} agent(s) from a CRASHED session are recoverable — \`/subagents resume\` respawns them:`;
      for (const a of crashed) out += `\n     ◍ ${a.claim.agentType} · \`${a.claim.scope}\` · ${a.claim.prompt}`;
    }
    return { type: 'message', level: 'info', content: out };
  },
});

