import { globalCommandRegistry } from './registry';
import { globalCheckpointManager, Checkpoint } from '../../sandbox/checkpoint.manager';
import { engineEvents } from '../events';

function rel(ts: number): string {
  const s = Math.round((Date.now() - ts) / 1000);
  if (s < 60) return `${s}s ago`;
  if (s < 3600) return `${Math.round(s / 60)}m ago`;
  if (s < 86400) return `${Math.round(s / 3600)}h ago`;
  return `${Math.round(s / 86400)}d ago`;
}

function describe(c: Checkpoint): string {
  return `${c.id}  ${c.auto ? '·' : '★'} ${c.label} (${rel(c.timestamp)})`;
}

globalCommandRegistry.register({
  name: '/checkpoint',
  aliases: ['/cp'],
  description: 'Snapshot the working tree (Time Machine)',
  category: 'Session & Context',
  execute: async (args) => {
    if (!globalCheckpointManager.isGitRepo()) {
      return { type: 'message', level: 'error', content: 'Checkpoints need a git repository. Run `git init` first.' };
    }
    if (args[0] === 'list') {
      const list = globalCheckpointManager.list();
      if (list.length === 0) return { type: 'message', level: 'info', content: 'No checkpoints yet. Run /checkpoint to make one.' };
      return { type: 'message', level: 'info', content: `Checkpoints (★ manual · auto):\n${list.map(describe).join('\n')}` };
    }
    const label = args.join(' ').trim() || 'manual checkpoint';
    const cp = globalCheckpointManager.create(label, false);
    if (!cp) {
      engineEvents.emit('checkpoint_failed', label); // review domain records the failed attempt
      return { type: 'message', level: 'error', content: 'Failed to create checkpoint.' };
    }
    engineEvents.emit('timemachine_changed'); // ui_snapshot.checkpoints → front-end History strips
    return { type: 'message', level: 'success', content: `📸 Checkpoint ${cp.id} saved — "${cp.label}". Use /rewind to restore.` };
  }
});

globalCommandRegistry.register({
  name: '/rewind',
  description: 'Restore an earlier checkpoint (Time Machine)',
  category: 'Session & Context',
  execute: async (args, context) => {
    if (!globalCheckpointManager.isGitRepo()) {
      return { type: 'message', level: 'error', content: 'Rewind needs a git repository.' };
    }
    const list = globalCheckpointManager.list();
    if (list.length === 0) {
      return { type: 'message', level: 'info', content: 'No checkpoints to rewind to. Run /checkpoint first.' };
    }

    if (!args[0]) {
      return {
        type: 'menu',
        title: 'Rewind working tree to checkpoint',
        options: list.slice(0, 25).map(c => ({
          label: describe(c),
          value: c.id,
          desc: c.auto ? 'auto-snapshot' : 'manual checkpoint'
        })),
        onSelect: (opt: any) => context.executeCommand(`/rewind ${opt.value}`)
      };
    }

    const id = args[0].replace(/^rewind:/, '');
    const result = globalCheckpointManager.restore(id);
    if (!result) {
      return { type: 'message', level: 'error', content: `Checkpoint "${id}" not found. Use /checkpoint list.` };
    }
    engineEvents.emit('timemachine_changed');
    const safetyNote = result.safety ? ` A safety checkpoint (${result.safety.id}) of your previous state was saved — /rewind it to undo this.` : '';
    return {
      type: 'message',
      level: 'success',
      content: `⏪ Rewound working tree to ${result.restored.id} — "${result.restored.label}".${safetyNote}`
    };
  }
});

import { globalCommandRegistry } from './registry';
import { globalTransactionManager } from '../../core/transaction.manager';
import { randomUUID } from 'crypto';

/**
 * /tx — Tracked multi-file edit transactions.
 *
 * /tx begin             — open a transaction (assigns an ID)
 * /tx commit            — finalize, keep all edits
 * /tx rollback          — undo every edit made since /tx begin
 * /tx rollback --force  — also overwrite files changed after the transaction wrote them
 * /tx recover           — retry paths a previous rollback could not restore
 * /tx status            — show whether a transaction is open, and anything pending recovery
 *
 * While a transaction is open, every mutating tool records the file's pre-edit state and declares
 * what it is about to write. If any edit fails, or if /tx rollback is called, every tracked path is
 * put back — EXCEPT one whose current content is neither the recorded original nor something this
 * transaction wrote. That is somebody else's later edit; it is kept, reported as a conflict, and
 * the pre-transaction bytes are retained under `.breakglass/transactions/<id>/` so nothing is lost.
 * `--force` overwrites those deliberately. A path whose original could not be read is reported as
 * unprotected rather than deleted.
 */
globalCommandRegistry.register({
  name: '/tx',
  description: 'Tracked multi-file edit transaction — begin / commit / rollback',
  category: 'Code & Intelligence',
  execute: async (args, _context) => {
    const sub = (args[0] || '').toLowerCase();

    if (sub === 'begin' || sub === 'start') {
      // Begin fails if one is already open — report that at error level, not success.
      if (globalTransactionManager.isOpen()) {
        return { type: 'message', level: 'error', content: `Transaction ${globalTransactionManager.currentId()} is already open. Commit or roll it back first (/tx commit · /tx rollback).` };
      }
      const id = `TX-${randomUUID().slice(0, 6).toUpperCase()}`;
      const msg = globalTransactionManager.begin(id);
      return { type: 'message', level: globalTransactionManager.currentId() === id ? 'success' : 'error', content: msg };
    }

    if (sub === 'commit' || sub === 'done') {
      const wasOpen = globalTransactionManager.isOpen();
      const msg = globalTransactionManager.commit();
      return { type: 'message', level: wasOpen && !globalTransactionManager.isOpen() ? 'success' : 'error', content: msg };
    }

    if (sub === 'rollback' || sub === 'abort' || sub === 'undo') {
      const force = args.slice(1).some(a => a.toLowerCase() === '--force' || a.toLowerCase() === 'force');
      const result = await globalTransactionManager.rollbackDetailed({ force });
      // A rollback that kept a conflicting file, hit a failure, or could not protect a path is not
      // a success message — the receipt has to carry the same weight the outcome does.
      const unresolved = result.entries.filter(e => e.status === 'conflict' || e.status === 'failed' || e.status === 'unprotected');
      return { type: 'message', level: !result.id || unresolved.length ? 'error' : 'info', content: result.message };
    }

    if (sub === 'recover') {
      const blocked = globalTransactionManager.status().phase !== 'idle';
      const msg = await globalTransactionManager.recover();
      return { type: 'message', level: blocked || globalTransactionManager.pendingRecovery() ? 'error' : 'info', content: msg };
    }

    if (sub === 'status') {
      const status = globalTransactionManager.status();
      const pending = globalTransactionManager.pendingRecoveries();
      const pendingNote = pending.map(pending =>
          `\nTransaction ${pending.id} has ${pending.paths.length} path(s) still pending: ${pending.paths.join(', ')}.` +
          (pending.dir ? ` Pre-transaction content is retained in ${pending.dir}.` : ' Their content is held in memory only.') +
          ' Use /tx recover to retry; newer content and permissions are kept.'
      ).join('');
      const budgetNote = `\nSnapshot memory: ${status.heldSnapshotBytes} / ${status.maxTotalSnapshotBytes} bytes held or reserved, including recovery baselines.`;
      if (status.phase === 'restoring') {
        return { type: 'message', level: 'info', content: `Restoration is in progress. Wait before beginning a transaction or retrying recovery.${budgetNote}${pendingNote}` };
      }
      if (globalTransactionManager.isOpen()) {
        const coverage = `\n${status.paths} path(s) captured: ${status.protectedPaths} protected, ${status.unprotectedPaths} unprotected; ${status.pendingSnapshots} snapshot operation(s) pending.`;
        return { type: 'message', level: status.unprotectedPaths ? 'error' : 'info', content: `Transaction ${globalTransactionManager.currentId()} is OPEN. Use /tx commit or /tx rollback.${coverage}${budgetNote}${pendingNote}` };
      }
      return { type: 'message', level: pending.length ? 'error' : 'info', content: `No open transaction. Use /tx begin to start one.${budgetNote}${pendingNote}` };
    }

    return {
      type: 'message',
      level: 'info',
      content: [
        '/tx begin    — open a transaction (tracks edits and reports snapshot coverage)',
        '/tx commit   — finalize and keep all edits',
        '/tx rollback — undo every edit made in this transaction (files changed since are kept)',
        '/tx rollback --force — also overwrite files changed after this transaction wrote them',
        '/tx recover  — retry paths a previous rollback could not restore',
        '/tx status   — inspect protected paths, snapshot memory and pending recovery',
      ].join('\n'),
    };
  },
});

import * as fs from 'fs/promises';
import * as path from 'path';
import * as os from 'os';

// ─── Configuration scopes and precedence ────────────────────────────────────────────────────────
// Effective config is composed from explicit scopes, lowest to highest precedence:
//
//   1. BUILT-IN DEFAULTS  (DEFAULTS below)
//   2. USER GLOBAL        ~/.breakglass/config.json          — persisted preferences
//   3. WORKSPACE/PROJECT  <cwd>/.breakglass/config.json      — per-codebase fields only
//   4. ENVIRONMENT        BGW_* variables                    — volatile, session-scoped
//
// (CLI flags and test overrides ride the ENVIRONMENT scope: both set BGW_*/BIMAX_* vars.)
//
// The invariant that makes scope 4 safe: VOLATILE VALUES NEVER PERSIST. Only two things may
// write config files — an explicit user action (a /command, the Settings UI) or a runtime
// recovery write that passes the volatility guard in saveConfig. This is the structural fix for
// the observed contamination class: a benchmark run with BGW_MODEL=mock caused healModel to
// persist {"model":"mock"} into the user's global config. Provenance is queryable via
// configSource(key), and every file write is atomic (tmp + rename).
// API keys are stored separately in ~/.breakglass/.env (see env.loader.ts).

// BIMAX_BREAKGLASS_DIR relocates the global dir (multi-profile + test isolation) — the same
// override env.loader.ts honours for the secrets file. Resolved lazily so tests can retarget it.
const globalDir = () => process.env.BIMAX_BREAKGLASS_DIR || path.join(os.homedir(), '.breakglass');
const globalPath = () => path.join(globalDir(), 'config.json');
const projectDir = () => path.join(process.cwd(), '.breakglass');
const projectPath = () => path.join(projectDir(), 'config.json');

// Fields that belong to the project, not to the user's global preferences.
const PROJECT_KEYS: (keyof EngineConfig)[] = ['onboardingComplete', 'workspaceRoot'];

// Environment overrides: the volatile scope. Maps config key → env var. Parsed on load; tracked
// as provenance 'env'; refused persistence for runtime-origin writes.
const ENV_OVERRIDES: Partial<Record<keyof EngineConfig, string>> = {
  model: 'BGW_MODEL',
  liteModel: 'BGW_LITE_MODEL',
  visionModel: 'BGW_VISION_MODEL',
  reasoningEffort: 'BGW_REASONING_EFFORT',
};

const STRICT_MODEL_KEYS: readonly (keyof EngineConfig)[] = [
  'model',
  'liteModel',
  'visionModel',
  'fallbackModel',
  'subagentModel',
];
const desktopStrictModel = (): string => String(process.env.BIMAX_DESKTOP_STRICT_MODEL || '').trim();

export type ConfigSource = 'default' | 'global' | 'project' | 'env';

export interface EngineConfig {
  defaultAgent: string;
  model: string; // the CODING model — drives the main agent loop
  liteModel: string; // the LITE model — used for cheap aux calls (summaries, self-critic, ask-user)
  visionModel: string; // the VISION model — image turns reroute here when the coding model is text-only ('' = none)
  // Resilience chain: when the active model keeps failing mid-run (retry budget exhausted, or the
  // provider starts rejecting it), the loop switches to this model once instead of dying. '' = off.
  fallbackModel: string;
  // Model sub-agents run on. '' (default) = inherit the main model. A per-spawn `model` arg on
  // SpawnSubagentTool overrides this for that one agent.
  subagentModel: string;
  timeout: number;
  temperature: number;
  topP: number; // nucleus sampling cap; clips the low-probability tail that drives dropped tool args / fabricated paths
  maxTokens: number;
  theme: string;
  verbose: boolean;
  dangerouslySkipPermissions: boolean;
  skipSemanticMetadata: boolean;
  autoIndex: boolean;
  excludeFromIndex: string[];
  maxToolIterations: number;
  maxSubAgents: number;
  // Per-task limits (backlog F5). Retries after a failed completion check within one user turn, and the longest one
  // run may take in minutes (0: no limit). BIMAX_TASK_MAX_RETRIES / BIMAX_TASK_MAX_MINUTES override them per engine.
  taskCheckRetries: number;
  taskMaxMinutes: number;
  // Spending (N6), set in Settings. Unset means the older sources decide: MAX_DAILY_SPEND (default $5) and the
  // desktop's per-Thread share. When set, they win over those, because Settings is the one the user can see.
  spendDailyCapUsd?: number;
  spendTaskShareUsd?: number;
  // Resume recent, bounded outcome assignments after an engine crash. Bypass-mode and ambiguous
  // snapshots always require manual recovery regardless of this preference.
  autoResumeAgents: boolean;
  // Wake the parent coordinator when background outcome work settles, then keep converging until
  // verified, waiting on active work, user-blocked, interrupted, or stopped by a circuit breaker.
  autoContinueOutcome: boolean;
  notificationBell: boolean;
  customRoutingRules: string[][];
  workspaceRoot: string;
  autoAgentDecisions: boolean;
  diffApproval: boolean;
  blastGate: boolean; // G5: confirm edits touching HIGH/CRITICAL graph symbols (off by default)
  gitAutoCommit: boolean; // B1: auto-commit each successful edit (off by default)
  autoVerify: boolean; // B2: typecheck after edits + feed errors back (off by default)
  sandboxBash: boolean; // B3: run BashTool under macOS sandbox-exec (off by default)
  selfCritic: boolean;
  adversarialVerify: boolean; // Phase 4: full-model red-team pass after self-critic (off by default)
  allowSelfEvolution: boolean;
  reasoningEffort?: string; // off by default; 'low'|'medium'|'high' to speed up thinking models
  /**
   * NOT SENT ANYWHERE. It was documented as an upper bound on a thinking model's reasoning tokens,
   * "gated exactly like reasoningEffort", and no request builder ever read it: the app's "Thinking
   * budget" control saved it and changed nothing (fix list item 13, 2026-09-30). The control is gone;
   * the key stays so existing config files still parse. Wire it through llm.adapter.ts (per provider —
   * Anthropic `thinking.budget_tokens`, OpenRouter `reasoning.max_tokens`) before offering it again.
   */
  maxThinkingTokens: number;
  /**
   * The active LLM provider (see engine/provider.ts). Persisted so a choice made in the UI survives a
   * restart: this used to be a module-level variable set only by the /provider command, so every
   * launch silently reverted to BGW_PROVIDER or 'nvidia' regardless of what the user had picked.
   * Precedence is unchanged — a runtime /provider override still wins, then this, then the env var.
   */
  provider: string;
  /** OpenAI-compatible endpoint override for the active provider ('' = the provider's own URL). */
  providerBaseURL: string;
  onboardingComplete: boolean; // per-project: has the map-graph/AI-graph onboarding flow run once?
  showMapPanel: boolean; // pinned codebase-map overview panel above the input
  showTokenMeter: boolean; // live "tokens that will be sent" estimate near the input
  // How much we put on the wire each turn:
  //   'smart' (default) — send only the core working-set of tool schemas; rare/heavy tools and
  //                       all MCP tools are deferred, loaded on demand via ToolSearchTool.
  //   'full'            — send every tool description, every turn (no deferral). Heavier, but the
  //                       model always sees the entire toolbox.
  contextMode: 'smart' | 'full';
  // The active model's context window in tokens. Drives when proactive compaction fires. 0 = use
  // the safe built-in default (128k). Set this to YOUR model's real window — bimax talks to any
  // OpenAI-compatible provider, so we can't reliably auto-detect it (no Claude-style per-variant map).
  contextWindowTokens: number;
  // Let the model emit multiple tool calls per turn (batched reads/greps run concurrently → faster).
  // Default true; set false for backends that reject multi-tool turns (e.g. NVIDIA NIM).
  parallelToolCalls: boolean;
  // Optional TUI keybinding overrides, e.g. { "search": "ctrl+/", "toggleLogs": "ctrl+l" }.
  // Action names + defaults live in keybindings.ts; only overrides go here.
  keybindings?: Record<string, string>;
  // Accessibility: calm static UI — disables spinner/shimmer animation (also set via BGW_REDUCED_MOTION env).
  reducedMotion?: boolean;

  // ── Memory / retrieval ────────────────────────────────────────────────────────────────────────
  // Model ids for the four-stage memory pipeline (see src/memory). '' or 0 = the built-in default;
  // resolution and env overrides live in src/memory/settings.ts. Changing the embedding model or
  // dimensions changes the vector space id, which re-embeds stored memories rather than comparing
  // vectors across spaces.
  memoryEmbeddingModel: string;
  memoryEmbeddingDimensions: number;
  memoryRerankModel: string;
  /** Off = no automatic per-turn recall; the memory_query tool keeps working. */
  memoryAutoRecall: boolean;
  /** Build the repository-local lexical code index. */
  codeIndexEnabled: boolean;
  /** Explicit consent for sending source chunks to a remote embedding/reranking provider. */
  codeIndexRemoteEmbeddings: boolean;
}

