let cached: EngineConfig | null = null;
let sources: Partial<Record<keyof EngineConfig, ConfigSource>> = {};

/** Where the effective value of `key` came from. 'default' until loadConfig() has run. */
export function configSource(key: keyof EngineConfig): ConfigSource {
  return sources[key] || 'default';
}

/** Test seam: drop the module-level cache so the next loadConfig() re-reads scopes. */
export function __resetConfigForTests(): void {
  cached = null;
  sources = {};
}

// Distinguishes "file absent" (normal) from "file corrupt" (must not be silently treated as
// empty — a later save would then rewrite the file from just the update, losing every other
// key). A corrupt file is preserved to config.json.corrupt-<ts> and an empty scope returned.
async function readJson(file: string): Promise<Partial<EngineConfig>> {
  let raw: string;
  try {
    raw = await fs.readFile(file, 'utf-8');
  } catch {
    return {}; // absent/unreadable — an empty scope
  }
  try {
    const parsed = JSON.parse(raw);
    return parsed && typeof parsed === 'object' && !Array.isArray(parsed) ? parsed : {};
  } catch {
    const backup = `${file}.corrupt-${Date.now()}`;
    try {
      await fs.copyFile(file, backup);
      console.warn(
        `[Config] ${file} is not valid JSON — preserved a copy at ${backup} and continuing with defaults for that scope.`,
      );
    } catch {
      /* best-effort backup */
    }
    return {};
  }
}

// Atomic write: same-directory temp file + rename, so a crash mid-write can never leave a
// half-written config.json, and concurrent writers each land a complete file (last one wins,
// which is the same semantics the two processes would have had with whole-file writes).
let tmpSeq = 0;
async function writeJsonAtomic(file: string, value: unknown): Promise<void> {
  // eslint-disable-next-line @typescript-eslint/no-require-imports
  require('../core/fault.injection').faultPoint('config.write');
  await fs.mkdir(path.dirname(file), { recursive: true });
  const tmp = `${file}.tmp-${process.pid}-${++tmpSeq}`;
  await fs.writeFile(tmp, JSON.stringify(value, null, 2), 'utf-8');
  try {
    await fs.rename(tmp, file);
  } catch (e) {
    try {
      await fs.unlink(tmp);
    } catch {
      /* already gone */
    }
    throw e;
  }
}

function parseEnvValue(key: keyof EngineConfig, raw: string): unknown {
  // Union-typed keys cannot take an arbitrary string: the declared type would be a lie, and an
  // unrecognized approval mode must fail SAFE (ask about everything) rather than silently widening
  // what runs unattended. Matches the capability provider's own config.
  const kind = typeof (DEFAULTS as any)[key];
  if (kind === 'number') {
    const n = Number(raw);
    return Number.isFinite(n) ? n : undefined;
  }
  if (kind === 'boolean') return raw !== 'false' && raw !== '0';
  return raw;
}

export async function loadConfig(): Promise<EngineConfig> {
  if (cached) return cached;
  const globalCfg = await readJson(globalPath());
  const rawProjectCfg = await readJson(projectPath());
  // Old builds wrote the whole default object into .breakglass/config.json. Letting those stale
  // values override current defaults silently kept this workspace at 50 iterations even after the
  // long-run default was raised. The scope contract above is authoritative: only project-owned
  // fields may flow from this file.
  const projectCfg = Object.fromEntries(
    PROJECT_KEYS.filter((key) => key in rawProjectCfg).map((key) => [key, rawProjectCfg[key]]),
  ) as Partial<EngineConfig>;
  // Compose the scopes in precedence order, recording where each effective value came from.
  const merged: EngineConfig = { ...DEFAULTS, ...globalCfg, ...projectCfg };
  sources = {};
  for (const key of Object.keys(DEFAULTS) as (keyof EngineConfig)[]) {
    if (key in projectCfg) sources[key] = 'project';
    else if (key in globalCfg) sources[key] = 'global';
    else sources[key] = 'default';
  }
  // Environment overrides win over both files but are VOLATILE: they colour the session and are
  // never written back. (Previously config.model silently clobbered BGW_MODEL — the precedence
  // was backwards, and the mock benchmark only worked because healModel then "healed" the config
  // model to the mock id and persisted it into the user's real config.)
  for (const [key, envVar] of Object.entries(ENV_OVERRIDES) as [keyof EngineConfig, string][]) {
    const raw = process.env[envVar];
    if (raw !== undefined && raw !== '') {
      const v = parseEnvValue(key, raw);
      if (v !== undefined) {
        (merged as any)[key] = v;
        sources[key] = 'env';
      }
    }
  }
  cached = merged;
  cached.workspaceRoot = path.resolve(projectCfg.workspaceRoot || globalCfg.workspaceRoot || DEFAULTS.workspaceRoot);
  // Migration: only retired routes are moved to current defaults (below). A model the user put in
  // the quick slot stays theirs, even when it is the same reasoning model as the work slot.
  const strictModel = desktopStrictModel();
  if (strictModel) {
    cached.model = strictModel;
    cached.liteModel = strictModel;
    cached.visionModel = strictModel;
    cached.subagentModel = strictModel;
    cached.fallbackModel = '';
    for (const key of STRICT_MODEL_KEYS) sources[key] = 'env';
  } else
    try {
      const retiredStep = (value: string): boolean => /(?:stepfun-ai\/)?step-3\.7-flash/i.test(value);
      // The former Desktop build persisted Step 3.7 into every role. NVIDIA retired that route, so
      // migrate the effective session to current defaults without silently rewriting the user's
      // config file; the next explicit picker change persists normally.
      if (retiredStep(cached.model)) cached.model = DEFAULTS.model;
      if (retiredStep(cached.liteModel)) cached.liteModel = DEFAULTS.liteModel;
      if (retiredStep(cached.visionModel)) cached.visionModel = DEFAULTS.visionModel;
      if (retiredStep(cached.subagentModel)) cached.subagentModel = DEFAULTS.subagentModel;
      if (retiredStep(cached.fallbackModel)) cached.fallbackModel = DEFAULTS.fallbackModel;
      if (cached.provider.trim().toLowerCase() === 'stepfun') cached.provider = 'nvidia';
      // A reasoning model in both slots used to be swapped here for LEGACY_SAFE_LITE_MODEL, a model the
      // user never chose. NVIDIA 404s mistral-7b-instruct-v0.3 for some accounts, so every greeting and
      // short question failed while the configured model answered fine. The user's pick now stands.
    } catch {
      /* models module unavailable in some test harnesses — defaults already sane */
    }
  return cached;
}

export function getConfig(): EngineConfig {
  if (!cached) throw new Error('Config not loaded. Call loadConfig() first.');
  return cached;
}

export interface SaveOptions {
  /**
   * Who is asking for persistence.
   *   'user'    (default) — an explicit user action (/command, Settings UI). Always persisted.
   *   'runtime' — automatic recovery/healing. Persisted ONLY when the affected key's effective
   *               value did not come from a volatile scope: if the key is currently
   *               env-overridden, the recovery was recovering a session-scoped value, and writing
   *               it would leak test/benchmark/CI state into the user's real configuration.
   */
  origin?: 'user' | 'runtime';
}

// In-process saves are serialized so two same-tick writers can't interleave their
// read-merge-write cycles (each write still lands atomically; this makes the MERGE atomic too).
let saveChain: Promise<unknown> = Promise.resolve();

export function saveConfig(updates: Partial<EngineConfig>, opts: SaveOptions = {}): Promise<EngineConfig> {
  const run = saveChain.then(
    () => doSave(updates, opts),
    () => doSave(updates, opts),
  );
  saveChain = run;
  return run;
}

async function doSave(updates: Partial<EngineConfig>, opts: SaveOptions = {}): Promise<EngineConfig> {
  const origin = opts.origin || 'user';
  const current = await loadConfig();

  // Attribution for model writes.
  //
  // The stored work model was repeatedly found replaced by an id the provider does not serve, and
  // four separate writers were fixed on suspicion without the cause ever being reproduced. A
  // config layer cannot know WHO called it — but it can record the stack, which turns "something
  // rewrote my model" from a guess into a name. Only fires when a model key actually CHANGES
  // value, so it costs nothing on an ordinary save, and writes to the same place the engine already
  // logs so it survives into a packaged run.
  try {
    const MODEL_KEYS = ['model', 'liteModel', 'visionModel', 'fallbackModel', 'subagentModel'] as const;
    const changed = MODEL_KEYS.filter(
      (k) => updates[k] !== undefined && updates[k] !== (current as unknown as Record<string, unknown>)[k],
    );
    if (changed.length > 0) {
      const where = (new Error().stack || '').split('\n').slice(2, 7).map(l => l.trim()).join(' <- ');
      for (const key of changed) {
        // console.warn, not Logger: this module is imported by the config layer itself and must
        // not take a dependency on the logger's own configuration to report a config problem.
        console.warn(
          `[Config] model write: ${key} "${String((current as unknown as Record<string, unknown>)[key] ?? '')}" -> `
          + `"${String(updates[key])}" origin=${origin} :: ${where}`,
        );
      }
    }
  } catch { /* diagnostics must never break a save */ }

  // Model controls are read-only in the single-model Desktop build. Drop these writes entirely:
  // persisting them would mutate the user's separate Terminal preferences even though the app
  // cannot honor them. Non-model settings in the same patch still save normally.
  const effectiveUpdates: Partial<EngineConfig> = { ...updates };
  if (desktopStrictModel()) {
    for (const key of STRICT_MODEL_KEYS) delete (effectiveUpdates as any)[key];
  }

  // The volatility guard: runtime-origin writes to env-overridden keys are dropped (in-memory
  // state still updates, so the session keeps working with the recovered value).
  let accepted: Partial<EngineConfig> = effectiveUpdates;
  if (origin === 'runtime') {
    accepted = {};
    for (const [key, value] of Object.entries(effectiveUpdates) as [keyof EngineConfig, any][]) {
      if (sources[key] === 'env') {
        console.warn(
          `[Config] Not persisting runtime change to "${key}" — its value came from ${ENV_OVERRIDES[key] || 'the environment'} and is session-scoped.`,
        );
      } else {
        (accepted as any)[key] = value;
      }
    }
  }

  cached = { ...current, ...effectiveUpdates }; // the live session reflects accepted session state

  // Route each accepted key to the file it belongs in.
  const globalUpdates: Record<string, any> = {};
  const projectUpdates: Record<string, any> = {};
  for (const [key, value] of Object.entries(accepted)) {
    if (PROJECT_KEYS.includes(key as keyof EngineConfig)) projectUpdates[key] = value;
    else globalUpdates[key] = value;
    // A persisted value's provenance becomes its destination scope.
    sources[key as keyof EngineConfig] = PROJECT_KEYS.includes(key as keyof EngineConfig) ? 'project' : 'global';
  }

  try {
    if (Object.keys(globalUpdates).length) {
      const existing = await readJson(globalPath());
      await writeJsonAtomic(globalPath(), { ...existing, ...globalUpdates });
      // Migrate-on-write: a legacy combined project file merges LAST in loadConfig, so a stale copy
      // of a global key there (e.g. an old `model`) silently shadows the value we just saved — the
      // user "changes model" and nothing actually changes (this pinned sub-agents to a model the
      // user had switched away from). Strip the just-updated global keys from the project file.
      try {
        const existingProject = await readJson(projectPath());
        const stale = Object.keys(globalUpdates).filter((k) => k in existingProject);
        if (stale.length) {
          for (const k of stale) delete (existingProject as any)[k];
          await writeJsonAtomic(projectPath(), existingProject);
        }
      } catch {
        /* no project file — nothing to migrate */
      }
    }
    if (Object.keys(projectUpdates).length) {
      const existing = await readJson(projectPath());
      await writeJsonAtomic(projectPath(), { ...existing, ...projectUpdates });
    }
  } catch (e: any) {
    // A read-only config dir (EROFS/EACCES/EPERM) must not crash the session — the in-memory
    // state above already reflects the change; it just won't survive a restart.
    if (['EROFS', 'EACCES', 'EPERM'].includes(e?.code)) {
      console.warn(`[Config] Config directory is not writable (${e.code}) — change applies to this session only.`);
    } else {
      throw e;
    }
  }

  return cached;
}

import { EventEmitter } from 'events';
import { appStore } from '../state/app.state';
import { recordToolCall } from './toolHistory';
import { isReplayActive } from '../core/replay.scope';

class AppEventEmitter extends EventEmitter {
  emit(event: string | symbol, ...args: any[]): boolean {
    // The lab's recorded calls are evaluation data. Delivering them here also writes them to the
    // live session recorder, review state and UI, so suppress the entire live event seam in replay.
    if (isReplayActive()) return false;
    const result = super.emit(event, ...args);

    // Bridge to new appStore state
    try {
      if (event === 'log') {
        const payload = args[0];
        if (typeof payload === 'string') {
          appStore.setState(prev => ({
            logs: [...prev.logs, { id: Date.now() + Math.random(), level: 'info', text: payload, timestamp: new Date() }]
          }));
        } else if (payload && payload.text) {
          appStore.setState(prev => ({
            logs: [...prev.logs, payload]
          }));
        }
      } else if (event === 'message') {
        appStore.setState(prev => ({
          messages: [...prev.messages, args[0]]
        }));
      } else if (event === 'spinner_state') {
        appStore.setState({ spinner: { status: args[0], message: args[1] || '' } });
      } else if (event === 'status') {
        appStore.setState({ statusText: args[0] });
      } else if (event === 'veto_prompt') {
        appStore.setState({ vetoResolver: { question: args[0], options: args[1], resolve: args[2] } });
      } else if (event === 'tool_call') {
        const tc = args[0];
        appStore.setState(prev => {
          const arr = [...prev.streamingToolCalls];
          const idx = arr.findIndex(t => t.id === tc.id);
          if (idx !== -1) arr[idx] = tc; else arr.push(tc);
          return { streamingToolCalls: arr };
        });
      } else if (event === 'todo_update') {
        appStore.setState({ todos: args[0] || [] });
      } else if (event === 'tool_call_result') {
        const tc = args[0];
        appStore.setState(prev => {
          const arr = [...prev.streamingToolCalls];
          const idx = arr.findIndex(t => t.id === tc.id);
          if (idx !== -1) arr[idx] = tc;
          return { streamingToolCalls: arr };
        });
        // Capture the finished call (with its full, untruncated output) for the /output viewer.
        try { recordToolCall(tc); } catch { /* best-effort */ }
      }
    } catch (e) {
      // Ignore bridging errors
    }

    return result;
  }
}

export const engineEvents = new AppEventEmitter();
// Several components subscribe per-render/per-turn; raise the cap so Node
// doesn't print MaxListenersExceededWarning during long sessions.
engineEvents.setMaxListeners(50);

// Central session-usage accumulator. `cost_update` fires the streamed-char count at the end of
// every turn; the Footer renders the live rate, but commands (e.g. /cost) need the running total
// too — so we accumulate it once here instead of locking the number inside one component.
let _sessionChars = 0;
engineEvents.on('cost_update', (chars: number) => { if (typeof chars === 'number' && chars > 0) _sessionChars += chars; });
/** Rough running token estimate for the session (≈ chars/4). 0 before any output streams. */
export function getSessionTokenEstimate(): number {
  return Math.round(_sessionChars / 4);
}

export type AgentState = 'idle' | 'thinking' | 'decomposing' | 'executing' | 'vetoing' | 'blocked' | 'responding';

export type LogLevel = 'info' | 'warn' | 'error' | 'success' | 'debug';

export interface LogEntry {
  id: number;
  level: LogLevel;
  text: string;
  timestamp: Date;
}

export interface ToolCallEntry {
  parts?: import('../protocol/presentation').PresentationPart[];
  id: string;
  toolName: string;
  input: string;
  output: string;
  status: 'running' | 'success' | 'error';
  startTime: Date;
  endTime?: Date;
  // Set when this call was made by a sub-agent (worker thread) rather than the main loop. The UI
  // indents and labels such calls so /swarm & /speculate work is legible instead of an opaque
  // "Subagent (running…)" line. `parentId` is the spawning task id; `agentLabel` is the agent type.
  parentId?: string;
  agentLabel?: string;
}

export interface MessageEntry {
  id: string;
  role: 'user' | 'assistant' | 'system';
  level?: 'info' | 'warn' | 'error' | 'success';
  uiComponent?: string;
  payload?: any;
  content: string;
  toolCalls?: ToolCallEntry[];
  // Wall-clock the model spent in its reasoning channel this turn. Rendered as a collapsed
  // "Thought for Ns" line (Claude Code style) once thinking finishes.
  thoughtMs?: number;
  timestamp: Date;
}

// Events (live wires — keep this list in sync with actual emit/on sites):
// - log: (entry: LogEntry) => Appends to log stream
// - message: (msg: MessageEntry) => New chat message
// - tool_call: (call: ToolCallEntry) => A tool started running
// - tool_call_result: (call: ToolCallEntry) => A tool finished (status success/error)
// - veto_prompt: (question, options, resolve, isAskPrompt?) => Triggers permission overlay
// - host_call: retired compatibility event; ProtocolHost resolves it unavailable without contacting the app.
// - spinner_state: (state: AgentState, message?: string) => Updates the footer status indicator
// - status: (text: string) => Status bar update
// - mode_change: (mode: string) => Governor mode change (footer)
// - model_tier: ({ tier, pinned }) => Active routing tier changed (footer)
// - set_tier: ('auto'|'lite'|'heavy') => Manual tier pin request (/tier command → FullScreen)
// - cost_update: (chars: number) => End-of-turn streamed-char count (footer + session accumulator)
// - todo_update: (todos) => TodoWrite tool updated the task list (appStore → /todos panel)
// - completion_check: (snapshot) => a task's completion checks or their last result changed (F3)
// - turn_limit: ({ kind, minutes }) => a run stopped at its time limit (F5)
// - wake_request: (WakeRequest) / wake_cancel: ({ id }) => a task asks to be resumed by an event, or drops that (F4)
// - folder_status: ({ items: FolderStatusItem[] }) => a task reports files against its folder's outcome (FL1 part 2)
// - organize_plan: ({ id, title, root, moves }) => a task proposes a plan of moves for the person to rearrange (FL2)
// - steer_queued / steered: ({ text }) => steering words were held for the running turn's next step, then taken (F7)
// - config_changed / graph_changed / cwd_changed / mcp_changed => live UI refresh signals
// - rerun_onboarding: () => Re-open the first-run onboarding flow
// - thinking: (text: string) => Model's internal reasoning stream (status display only)
// - thinking_clear: () => Reset the thinking display between turns
// - shutdown: () => Graceful shutdown
// - loop_detected: (signal: LoopSignal) => Agent loop detected a repetition pattern (Footer flash)
// - goals_changed: () => Active goals changed (Footer goal counter refresh)
// - outcome_update: (snapshot|null) => Active outcome contract + completion-gate progress

import { stateDir } from '../utils/state.dir';
import * as fs from 'fs/promises';
import * as path from 'path';
import { execSync } from 'child_process';
import { structuredPatch } from 'diff';

const BACKUP_DIR = path.join(stateDir('.breakglass'), 'backups');

/**
 * A compact, context-limited unified diff (git-style: 3 lines of context around each change) with
 * ABSOLUTE line numbers in the @@ hunk headers. Unlike unifiedDiff() below — which emits the whole
 * file as context — this stays small even for a one-line change in a large file, so it's cheap to
 * put in tool output and clean to render with line numbers. Used by the edit/write tools.
 */
export function compactDiff(oldText: string, newText: string, label: string, context = 3): string {
  const patch = structuredPatch(label, label, oldText, newText, '', '', { context });
  if (patch.hunks.length === 0) return '';
  const out: string[] = [];
  for (const h of patch.hunks) {
    out.push(`@@ -${h.oldStart},${h.oldLines} +${h.newStart},${h.newLines} @@`);
    out.push(...h.lines);
  }
  return out.join('\n');
}

/** Truncate a diff to a sane number of lines for tool output / display. */
export function capDiff(diff: string, maxLines = 80): string {
  const lines = diff.split('\n');
  if (lines.length <= maxLines) return diff;
  return lines.slice(0, maxLines).join('\n') + `\n…(${lines.length - maxLines} more diff lines)`;
}

export interface BackupEntry {
  file: string;
  backupPath: string;
  timestamp: number;
}

function ensureBackupDir() {
  return fs.mkdir(BACKUP_DIR, { recursive: true });
}

export async function backupFile(filePath: string): Promise<string | null> {
  try {
    await ensureBackupDir();
    const absPath = path.resolve(filePath);
    const content = await fs.readFile(absPath, 'utf-8');
    const backupName = `${Date.now()}_${path.basename(filePath)}`;
    const backupPath = path.join(BACKUP_DIR, backupName);
    await fs.writeFile(backupPath, content, 'utf-8');
    return backupPath;
  } catch { return null; }
}

export async function getBackups(filePath?: string): Promise<BackupEntry[]> {
  try {
    await ensureBackupDir();
    const files = await fs.readdir(BACKUP_DIR);
    const entries: BackupEntry[] = [];
    for (const f of files) {
      const stat = await fs.stat(path.join(BACKUP_DIR, f));
      entries.push({ file: f, backupPath: path.join(BACKUP_DIR, f), timestamp: stat.mtimeMs });
    }
    entries.sort((a, b) => b.timestamp - a.timestamp);
    if (filePath) {
      const basename = path.basename(filePath);
      return entries.filter(e => e.file.endsWith(basename));
    }
    return entries;
  } catch { return []; }
}

export async function undoLast(filePath: string): Promise<boolean> {
  const backups = await getBackups(filePath);
  if (backups.length === 0) return false;
  try {
    const content = await fs.readFile(backups[0].backupPath, 'utf-8');
    await fs.writeFile(path.resolve(filePath), content, 'utf-8');
    return true;
  } catch { return false; }
}

export async function previewDiff(filePath: string): Promise<string> {
  try {
    const absPath = path.resolve(filePath);
    const backups = await getBackups(filePath);
    if (backups.length === 0) return '(no backup to diff against)';
    const original = await fs.readFile(backups[0].backupPath, 'utf-8');
    const current = await fs.readFile(absPath, 'utf-8');
    return generateDiff(original, current, filePath);
  } catch (e: any) { return `(diff failed: ${e.message})`; }
}

/** Public unified-diff helper used for inline diff approval previews. */
export function unifiedDiff(oldText: string, newText: string, label: string): string {
  return generateDiff(oldText, newText, label);
}

function generateDiff(oldText: string, newText: string, label: string): string {
  const oldLines = oldText.split('\n');
  const newLines = newText.split('\n');
  const result: string[] = [`--- a/${label}`, `+++ b/${label}`];
  let i = 0, j = 0;
  while (i < oldLines.length || j < newLines.length) {
    if (i < oldLines.length && j < newLines.length && oldLines[i] === newLines[j]) {
      result.push(` ${oldLines[i]}`);
      i++; j++;
    } else {
      const startI = i, startJ = j;
      while (i < oldLines.length && (j >= newLines.length || oldLines[i] !== newLines[j])) i++;
      while (j < newLines.length && (i >= oldLines.length || oldLines[i] !== newLines[j])) j++;
      result.push(`@@ -${startI + 1},${i - startI} +${startJ + 1},${j - startJ} @@`);
      for (let k = startI; k < i; k++) result.push(`-${oldLines[k]}`);
      for (let k = startJ; k < j; k++) result.push(`+${newLines[k]}`);
    }
  }
  return result.join('\n');
}

export async function writeWithBackup(filePath: string, content: string): Promise<string | null> {
  const absPath = path.resolve(filePath);
  const exists = await fs.access(absPath).then(() => true).catch(() => false);
  if (exists) {
    const backupPath = await backupFile(filePath);
    await fs.writeFile(absPath, content, 'utf-8');
    return backupPath;
  } else {
    await fs.mkdir(path.dirname(absPath), { recursive: true });
    await fs.writeFile(absPath, content, 'utf-8');
    return null;
  }
}

export async function editFileLines(filePath: string, search: string, replace: string): Promise<boolean> {
  try {
    const absPath = path.resolve(filePath);
    const content = await fs.readFile(absPath, 'utf-8');
    if (!content.includes(search)) return false;
    await backupFile(filePath);
    // Replacer function so `$$`/`$&`/`` $` ``/`$'` in the replacement text aren't interpreted by
    // String.replace and silently corrupt the write (e.g. `$$` → `$`). See edit.tool.ts.
    const updated = content.replace(search, () => replace);
    await fs.writeFile(absPath, updated, 'utf-8');
    return true;
  } catch { return false; }
}

/**
 * The agent gates Settings can switch, and the live flag each one drives.
 *
 * Each gate is a module-level flag (diffApproval.ts, blastGate.ts, …) that only its slash command set.
 * The command ALSO saved the choice to the config file, and the app's Settings window wrote that same
 * file key — so Settings → Agent safety → "Diff approval", "Blast-radius gate", "Sandboxed shell" and
 * Agent behavior → "Self-critic", "Adversarial verify", "Auto-verify edits", "Git auto-commit" all
 * showed a switch that saved and did nothing: nothing read the key back, not live and not at the next
 * boot (fix list item 12, measured 2026-09-30). Every flag defaults to off, as every config default
 * does, so a gate the user never touched is unchanged.
 *
 * `applyGateFlags` is the one bridge: startHeadless applies the saved config before the first message,
 * and the settings wire applies each patch the moment it is saved. Setters are required lazily so this
 * module stays cheap to import from the wire, which is unit-tested without booting anything.
 */

export const GATE_KEYS = [
  'diffApproval', 'blastGate', 'sandboxBash', 'autoVerify', 'selfCritic', 'adversarialVerify', 'gitAutoCommit',
] as const;

export type GateKey = typeof GATE_KEYS[number];

const SETTERS: Record<GateKey, () => (on: boolean) => void> = {
  diffApproval: () => (require('./diffApproval') as typeof import('./diffApproval')).setDiffApprovalEnabled,
  blastGate: () => (require('./blastGate') as typeof import('./blastGate')).setBlastGateEnabled,
  sandboxBash: () => (require('../sandbox/exec.sandbox') as typeof import('../sandbox/exec.sandbox')).setSandboxEnabled,
  autoVerify: () => (require('../sandbox/verify.loop') as typeof import('../sandbox/verify.loop')).setVerifyEnabled,
  selfCritic: () => (require('./selfCritic') as typeof import('./selfCritic')).setSelfCriticEnabled,
  adversarialVerify: () => (require('./adversarialVerifier') as typeof import('./adversarialVerifier')).setAdversarialVerifyEnabled,
  gitAutoCommit: () => (require('../tools/git.autocommit') as typeof import('../tools/git.autocommit')).setGitAutoCommitEnabled,
};

/**
 * Apply every gate key present in `cfg` as a boolean. Anything else — absent, null, a string — is left
 * alone rather than read as false, so a one-key patch from one Settings row touches one gate.
 * Returns the keys it applied.
 */
export function applyGateFlags(cfg: Record<string, unknown> | null | undefined): GateKey[] {
  const applied: GateKey[] = [];
  if (!cfg) return applied;
  for (const key of GATE_KEYS) {
    const value = cfg[key];
    if (typeof value !== 'boolean') continue;
    SETTERS[key]()(value);
    applied.push(key);
  }
  return applied;
}

import { exec } from 'child_process';
import { promisify } from 'util';

const execAsync = promisify(exec);

export interface LintResult {
  success: boolean;
  output: string;
  errors: string[];
}

async function run(cmd: string): Promise<LintResult> {
  try {
    const { stdout, stderr } = await execAsync(cmd, { timeout: 60000 });
    return { success: true, output: stdout, errors: [] };
  } catch (e: any) {
    const output = (e.stdout || '') + '\n' + (e.stderr || '');
    const lines = output.split('\n').filter((l: string) => l.includes('error') || l.includes('Error') || l.includes('ERROR'));
    return { success: false, output, errors: lines.slice(0, 20) };
  }
}

export async function runTypeCheck(projectRoot: string): Promise<LintResult> {
  return run('npx tsc --noEmit 2>&1');
}

export async function runLint(projectRoot: string): Promise<LintResult> {
  return run('npx eslint "src/**/*.ts" 2>&1');
}

export function formatErrors(result: LintResult): string {
  if (result.success) return '✅ All checks passed';
  return result.errors.slice(0, 10).join('\n');
}

