import { createTasksTool } from '../tools/implementations/tasks.tool';
import {
  CAPACITY_LEASE_ENV,
  CAPACITY_PATH_ENV,
  CAPACITY_RUN_ENV,
  SubAgentCapacityCoordinator,
} from '../core/subagent.capacity';

// Core sub-agent run, transport-agnostic: build the isolated agent + tools and execute the task,
// relaying each tool event through `emitEvent`. Shared by BOTH the worker_thread path (runWorker,
// Node dev/dist) and the subprocess path (runAsSubprocess, the bun-compiled binary). Throws on
// failure so each caller reports it its own way.
async function runSubAgentCore(
  config: SubAgentConfig,
  emitEvent: (subtype: 'tool_call' | 'tool_call_result', call: any) => void,
  signalReady?: () => void,
): Promise<string> {
  // Sandbox floor (BiMax v2): this worker is an isolated autonomous episode. Bash enforcement
  // lives in bash.tool.ts (kernel sandbox via the thread-local FLOOR_ENV), but the Node-side
  // file tools must be confined too — narrow the governor's workspace boundary to the episode
  // root so Write/Edit/Delete outside the worktree are vetoed in-process.
  inheritRunBudget(config.runBudget instanceof SharedArrayBuffer ? config.runBudget : workerData?.runBudget);
  const episodeFloor = floorRoot();
  if (episodeFloor) SafetyPolicy.allowedWorkspace = episodeFloor;
  const botPolicy = config.botRun ? await import('../bots/worker.policy') : undefined;
  const botRun = botPolicy ? await botPolicy.validateBotAssignment(config.botRun, config.cwd) : undefined;
  if (botRun && episodeFloor) throw new Error('Bot runs are not admitted inside a floored training episode.');

  // Nesting: record this worker's depth in its own (thread/process-local) env so the spawn tool
  // inside this agent knows where in the tree it sits. Worker threads get a COPY of process.env,
  // so this never leaks to the parent or siblings.
  const depth = Math.max(1, Number(config.depth ?? 1));
  process.env.BIMAX_SUBAGENT_DEPTH = String(depth);
  let capacity: SubAgentCapacityCoordinator | null = null;
  let capacityHeartbeat: ReturnType<typeof setInterval> | null = null;
  if (config.capacityPath && config.capacityRunId) {
    process.env[CAPACITY_PATH_ENV] = config.capacityPath;
    process.env[CAPACITY_RUN_ENV] = config.capacityRunId;
    if (config.capacityLeaseId) process.env[CAPACITY_LEASE_ENV] = config.capacityLeaseId;
    capacity = new SubAgentCapacityCoordinator(config.capacityPath);
    if (config.capacityLeaseId) {
      capacity.heartbeat(config.capacityLeaseId, process.pid);
      capacityHeartbeat = setInterval(() => {
        try { capacity?.heartbeat(config.capacityLeaseId!, process.pid); } catch { /* parent TTL is fallback */ }
      }, 10_000);
      capacityHeartbeat.unref?.();
    }
  }

  try {
    const pool = buildKeyPool();
    const apiKeyManager = new ApiKeyManager(pool);
    const llmAdapter = new LlmAdapter(apiKeyManager);
    // Subagents must run on the SAME model/config the user chose — otherwise they silently fall back
    // to the adapter's hardcoded default. Load the persisted config and apply it.
    try {
      const cfg = await loadConfig();
      llmAdapter.applyConfig({
        model: cfg.model,
        // No explicit lite model → use the USER'S model for the lite lane too, not the adapter's
        // hardcoded default. Sub-agents otherwise made their first call (router/smalltalk lane) on
        // a reasoning model the user never chose — which NIM queues for minutes on free keys, the
        // core of "sub-agents are hell of slow". Matching slots also lets the router short-circuit
        // (no pre-flight classifier call at all).
        liteModel: cfg.liteModel || cfg.model,
        visionModel: cfg.visionModel,
        temperature: cfg.temperature, topP: cfg.topP,
        maxTokens: cfg.maxTokens, reasoningEffort: cfg.reasoningEffort, parallelToolCalls: cfg.parallelToolCalls,
      });
    } catch { /* fall back to adapter defaults if config can't be read in the worker */ }
    // Per-agent model override (spawn tool's `model` arg / config.subagentModel) wins over the
    // inherited config. Set as BOTH slots so the router's unified short-circuit applies — a
    // sub-agent on an explicit model never burns a pre-flight classifier call.
    if (config.model) llmAdapter.applyConfig({ model: config.model, liteModel: config.model });
    // Permission bridge: inherit parent's mode
    const eventBus = new EventBus();
    const governor = new Governor(eventBus);
    governor.mode = config.parentMode as any;

    const toolRegistry = new ToolRegistry();
    const workerSessionId = config.outcomeTaskId || `worker-${process.pid}-${Date.now()}`;
    const workerOutcome = new OutcomeManager({
      sessionId: () => workerSessionId,
      directory: () => path.join(os.tmpdir(), 'bimax-worker-outcomes'),
    });
    workerOutcome.syncSession();
    __setOutcomeManager(workerOutcome);
    const onReviewChange = () => workerOutcome.onMutation();
    const onReviewEvidence = (event: any) => workerOutcome.onBuildEvidence(event);
    engineEvents.on('review_change', onReviewChange);
    engineEvents.on('review_evidence', onReviewEvidence);
    // Must match the parent's graph backend (container.ts uses createGraphStore: SQLite when
    // available, legacy JSON otherwise), keyed off the sub-agent's project cwd — NOT
    // ~/.breakglass/graph.json, which left workers querying an empty/stale store.
    const { createGraphStore } = await import('../graph/sqlite.graph.store');
    const graphStore = createGraphStore(config.cwd || process.cwd());
    const { isCodebase } = await import('../graph/graph.summary');
    if (isCodebase(config.cwd || process.cwd())) {
      await graphStore.loadFromDisk();
    }

    // Register basic tools for the worker
    toolRegistry.register(createBashTool(governor));
    toolRegistry.register(createReadFileTool(governor));
    toolRegistry.register(createWriteFileTool(governor));
    toolRegistry.register(createEditFileTool(governor));
    toolRegistry.register(createMultiEditTool(governor));
    toolRegistry.register(createSymbolEditTool(governor));
    toolRegistry.register(createRelatedTestsTool(governor));
    toolRegistry.register(createDeleteTool(governor));
    toolRegistry.register(createMakeDirTool(governor));
    toolRegistry.register(createGrepTool(governor));
    toolRegistry.register(createGlobTool(governor));
    toolRegistry.register(createTodoWriteTool(governor));
    toolRegistry.register(createOutcomeTool(governor));
    toolRegistry.register(createTasksTool(governor));
    // Floored episodes are net: none — WebFetch/WebSearch run fetches from the worker thread
    // itself, where the kernel sandbox on Bash children can't reach, so simply don't arm them.
    if (!episodeFloor) toolRegistry.register(createWebFetchTool(governor));
    toolRegistry.register(createCdTool(governor));
    toolRegistry.register(createGraphQueryTool(governor, graphStore));
    toolRegistry.register(createGraphContextTool(governor, graphStore));
    toolRegistry.register(createGitTool(governor));
    // Shared project memory is a persistence channel out of the episode — floored workers'
    // lessons re-enter only via the dream grader, never directly.
    if (!episodeFloor) toolRegistry.register(createRememberTool(governor, globalProjectMemory));
    // Same retrieval policy as the parent; this isolate owns a distinct instance. Shared-file
    // writes are coordinated by VectorStore's transaction protocol, not a shared JS mutex.
    // Floored episodes cannot read/write shared memory.
    if (!episodeFloor && apiKeyManager) {
      const { createMemoryRetrieval } = await import('../memory/retrieval.factory');
      const retrieval = createMemoryRetrieval({
        ...(botRun ? { store: { storePath: botPolicy!.botMemoryFile(botRun) } } : {}),
        resolveChat: async () => {
          const key = await apiKeyManager.getNextKey();
          if (!key.keyStr) return null;
          return { apiKey: key.keyStr, baseURL: key.baseURL || 'https://integrate.api.nvidia.com/v1' };
        },
      });
      globalProjectMemory.useStore(retrieval.store);
      if (botRun) toolRegistry.register(createMemoryQueryTool(governor, retrieval.store));
    }
    globalSkillService.load(config.cwd || process.cwd());
    toolRegistry.register(createSkillTool(governor, globalSkillService));
    // Skill installs fetch from the network AND persist outside the episode — both off-limits
    // under the floor (persistence must go through the objective grader, not side effects).
    if (!episodeFloor) toolRegistry.register(createSkillInstallTool(governor, globalSkillService));
    loadHooksConfig(config.cwd || process.cwd());
    toolRegistry.register(createToolSearchTool(governor, toolRegistry));
    if (!episodeFloor) toolRegistry.register(createWebSearchTool(governor));

    // Nested sub-agents (3-level agent trees, the Claude Code June-2026 pattern): a worker that
    // still has depth budget can spawn its own children for layered task decomposition. The spawn
    // tool re-checks BIMAX_SUBAGENT_DEPTH itself, so the registration gate here is belt-and-braces.
    // Floored episodes don't get it — their children would inherit the floor but multiply the
    // blast radius of an autonomous episode.
    if (depth + 1 < MAX_SUBAGENT_DEPTH && !episodeFloor) {
      const { createSpawnSubagentTool } = await import('../tools/implementations/spawn.tool');
      toolRegistry.register(createSpawnSubagentTool(governor, toolRegistry, llmAdapter));
    }
    if (botRun) await botPolicy!.applyBotWorkerPolicy(botRun, toolRegistry);

    // 2. Instantiate Persona
    let agent: AgentPersona;
    if (botRun) agent = new DynamicPersona({ name: botRun.definition.name,
      roleDescription: botRun.handoff.text, allowedTools: botRun.definition.requestedTools }, toolRegistry, llmAdapter);
    else if (config.agentType === 'Hermes') agent = new HermesPersona(toolRegistry, llmAdapter);
    else if (config.agentType === 'OpenCode') agent = new OpenCodePersona(toolRegistry, llmAdapter);
    else if (config.agentType === 'OpenClaw') agent = new OpenClawPersona(toolRegistry, llmAdapter);
    else if (config.agentType === 'BiMax') agent = new BiMaxPersona(toolRegistry, llmAdapter);
    else {
      // Each worker loads its own persona configuration
      PersonaConfigLoader.loadPersonas();
      const personaConfig = PersonaConfigLoader.getPersona(config.agentType);
      if (personaConfig) {
        agent = new DynamicPersona(personaConfig, toolRegistry, llmAdapter);
      } else {
        // Unknown/blank type → spawn BiMax itself rather than failing the whole sub-agent.
        agent = new BiMaxPersona(toolRegistry, llmAdapter);
      }
    }

    // Isolate CWD
    agent.cwd = config.cwd;

    // Forward this sub-agent's tool activity to the parent so the UI can nest it under the spawn
    // (T3). engineEvents here is the process/thread-local singleton the agent loop emits on; the
    // transport-specific emitEvent relays it (postMessage for a thread, a stdout sentinel for a
    // subprocess). The parent (SubAgentManager) tags it with parentId/agentLabel.
    const onCall = (call: any) => emitEvent('tool_call', call);
    const onResult = (call: any) => emitEvent('tool_call_result', call);
    engineEvents.on('tool_call', onCall);
    engineEvents.on('tool_call_result', onResult);

    // Boot done — everything above (key pool, config, graph store, ~18 tools, persona/system-prompt)
    // is the fixable per-spawn overhead WS2 measures. Signal it NOW, before the first llm call, so
    // the parent can split boot time from the model's time-to-first-action.
    signalReady?.();

    // 3. Execute
    try {
      // Keep recall anchored to the exact task. Using the entire handoff as its query makes
      // wrapper/instruction words drown the subject and can trigger lexical abstention.
      return await agent.execute(botRun?.task ?? config.prompt, () => { /* streaming ignored in sub-agents */ });
    } finally {
      engineEvents.off('tool_call', onCall);
      engineEvents.off('tool_call_result', onResult);
      engineEvents.off('review_change', onReviewChange);
      engineEvents.off('review_evidence', onReviewEvidence);
      workerOutcome.shutdown();
      __setOutcomeManager(null);
    }
  } finally {
    if (capacityHeartbeat) clearInterval(capacityHeartbeat);
    if (capacity && config.capacityLeaseId) {
      try { capacity.release(config.capacityLeaseId); } catch { /* TTL reclaims it */ }
    }
  }
}

// Worker-thread transport (Node dev/dist): config in workerData, results/events via postMessage.
async function runWorker(): Promise<void> {
  if (!parentPort) return;
  const config = workerData as SubAgentConfig;
  try {
    const result = await runSubAgentCore(
      config,
      (subtype, call) => parentPort!.postMessage({ type: 'tool_event', subtype, call }),
      () => parentPort!.postMessage({ type: 'ready' }),
    );
    parentPort.postMessage({ type: 'success', result });
  } catch (err: any) {
    parentPort.postMessage({ type: 'error', error: err?.message || String(err) });
  }
}

// Subprocess transport (the bun-compiled single binary re-execing itself): config arrives via env,
// results/events go out as stdout sentinel lines the parent parses back into worker-style messages.
// index.ts calls this when it detects BIMAX_SUBAGENT_CONFIG, instead of booting the engine.
export async function runAsSubprocess(): Promise<void> {
  const write = (s: string) => { try { process.stdout.write(s + '\n'); } catch { /* best-effort */ } };
  let config: SubAgentConfig;
  try { config = JSON.parse(process.env.BIMAX_SUBAGENT_CONFIG || '{}') as SubAgentConfig; }
  catch { write(SUB_ERROR + JSON.stringify({ error: 'invalid BIMAX_SUBAGENT_CONFIG' })); process.exit(1); return; }
  try {
    const result = await runSubAgentCore(
      config,
      (subtype, call) => write(SUB_EVENT + JSON.stringify({ subtype, call })),
      () => write(SUB_READY),
    );
    write(SUB_RESULT + JSON.stringify({ result }));
    process.exit(0);
  } catch (err: any) {
    write(SUB_ERROR + JSON.stringify({ error: err?.message || String(err) }));
    process.exit(1);
  }
}

if (parentPort) runWorker();

import * as fs from 'fs';
import * as os from 'os';
import * as path from 'path';
import { execFileSync } from 'child_process';
import { createHash } from 'crypto';
import { sampleResources, ResourceSample, AttrValue } from '../telemetry/measure';

/**
 * The P01 paired baseline/candidate runner.
 *
 * `competitive/examples/P01_FAST_CODE_AND_COWORK.md` is an evaluation contract with a specific
 * shape, and most of the ways a performance comparison lies are shapes this runner refuses to make:
 *
 *  - **An arm never grades itself.** Every run is judged by an independent grader that inspects the
 *    end state. A run that claims success and fails the grader is `rejected`, and its time is still
 *    charged. "Finished instantly with no output" cannot win.
 *  - **The denominator is every valid run.** Acceptance rate is reported over valid attempts, not
 *    over whichever runs an arm happened to finish, so refusing hard cases lowers the score instead
 *    of lowering the latency.
 *  - **Quality gates before latency.** A candidate whose acceptance rate falls more than the
 *    predeclared margin below the baseline is `regressed`, however fast it was.
 *  - **Cost is charged, not the winner's highlights.** Total wall time of every attempt, including
 *    failed and rejected ones, divides into accepted results as cost per accepted result.
 *  - **Order alternates.** Pair 0 runs baseline first, pair 1 candidate first, so drift and warmup
 *    do not attach themselves to one arm.
 *  - **Slow valid runs stay in.** Nothing is dropped for being slow. A run leaves the timing set
 *    only through the explicit `discard` hook, which must name a reason, and every discard is
 *    reported.
 *  - **The comparison is predeclared.** Pair count and margins are hashed into the report, and the
 *    report file refuses to overwrite an existing one.
 *
 * Statistics are deliberately plain: nearest-rank percentiles over the raw samples, paired deltas
 * over pairs where both arms were accepted, and an explicit count of that subset. No smoothing, no
 * outlier rejection, no confidence claim the sample size does not support.
 */

export type ArmName = 'baseline' | 'candidate';

export interface RunContext {
  arm: ArmName;
  /** 0-based pair index. */
  pairIndex: number;
  /** Position within the pair: 0 ran first, 1 ran second. */
  positionInPair: number;
  /** Global run counter across both arms, including warmup runs (which are numbered negatively). */
  runIndex: number;
}

export interface ArmOutcome<T = unknown> {
  /** What the implementation says about itself. Never trusted; the grader decides. */
  claimedSuccess: boolean;
  value?: T;
  error?: string;
}

export type Arm<T = unknown> = (ctx: RunContext) => Promise<ArmOutcome<T>>;

export interface Grade {
  accepted: boolean;
  /** Why. Required for both outcomes so a report explains itself without the source. */
  reason: string;
  evidence?: Record<string, AttrValue>;
}

export type Grader<T = unknown> = (outcome: ArmOutcome<T>, ctx: RunContext) => Promise<Grade> | Grade;

export type RunStatus = 'accepted' | 'rejected' | 'error' | 'discarded';

export interface RunRecord {
  arm: ArmName;
  pairIndex: number;
  positionInPair: number;
  runIndex: number;
  status: RunStatus;
  /** Wall time of the attempt, monotonic. Present even for rejected and errored runs. */
  durationMs: number;
  claimedSuccess: boolean;
  gradeReason: string;
  gradeEvidence?: Record<string, AttrValue>;
  error?: string;
  discardReason?: string;
  rssDeltaBytes: number;
  peakEventLoopDelayMs: number | null;
  processTreeRssBytes: number | null;
}

export interface ArmStats {
  arm: ArmName;
  attempts: number;
  /** Attempts minus discarded runs — the denominator for acceptance. */
  valid: number;
  accepted: number;
  rejected: number;
  errored: number;
  discarded: number;
  /** accepted / valid, or null when nothing valid ran. */
  acceptedFraction: number | null;
  /** Latency over ACCEPTED runs only. Null when no run was accepted. */
  p50Ms: number | null;
  p95Ms: number | null;
  minMs: number | null;
  maxMs: number | null;
  acceptedN: number;
  /** Wall time of every valid attempt, accepted or not. This is what a candidate actually costs. */
  totalWallMs: number;
  /** totalWallMs / accepted. Null when nothing was accepted — not Infinity, not zero. */
  costPerAcceptedMs: number | null;
  peakRssDeltaBytes: number;
  maxEventLoopDelayMs: number | null;
  maxProcessTreeRssBytes: number | null;
}

export type Verdict = 'improved' | 'no-change' | 'regressed' | 'inconclusive' | 'invalid';

export interface PairedComparison {
  /** Pairs where BOTH arms were accepted — the only pairs a paired delta can be computed from. */
  pairedSuccessN: number;
  /** candidate − baseline, one per paired-success pair. Negative is faster. */
  deltasMs: number[];
  p50DeltaMs: number | null;
  /** Relative change of the paired p50 latency. Negative is faster. */
  relativeChange: number | null;
  acceptedFractionDelta: number | null;
  costPerAcceptedChange: number | null;
  verdict: Verdict;
  reasons: string[];
}

export interface PairedConfig {
  name: string;
  /** Predeclared number of pairs. Every pair runs both arms. */
  pairs: number;
  /**
   * How far the candidate's acceptance rate may fall below the baseline's before the result is a
   * regression regardless of latency. Expressed in absolute fraction points (0.05 = 5 points).
   */
  qualityRegressionMargin: number;
  /** Relative paired-p50 change that counts as a real move rather than noise (0.05 = 5%). */
  minImprovementFraction: number;
  /** Runs per arm before measurement begins. Not recorded in the statistics. */
  warmupRuns?: number;
  /**
   * Minimum fraction of pairs that must produce a paired success before a latency verdict is
   * allowed. Below it the result is `inconclusive`, never `improved`. Default 0.5.
   */
  minPairedSuccessFraction?: number;
}

export interface PairedReport {
  schema: 1;
  name: string;
  startedAt: string;
  finishedAt: string;
  config: PairedConfig;
  /** SHA-256 of the predeclared config, so a post-hoc edit is visible. */
  configHash: string;
  manifest: RunManifest;
  percentileMethod: 'nearest-rank';
  runs: RunRecord[];
  baseline: ArmStats;
  candidate: ArmStats;
  comparison: PairedComparison;
  discards: { reason: string; count: number }[];
  notes: string[];
}

// --- statistics ---------------------------------------------------------------------------------

/**
 * Nearest-rank percentile: the smallest value at or above the q-th position of the sorted sample.
 * Chosen because it always returns an observed value and needs no interpolation assumption; the
 * method name travels with the report so a reader can reproduce it.
 */
export function percentile(values: number[], q: number): number | null {
  if (values.length === 0) return null;
  const sorted = [...values].sort((a, b) => a - b);
  const rank = Math.max(1, Math.ceil(q * sorted.length));
  return sorted[rank - 1];
}

function statsFor(arm: ArmName, runs: RunRecord[]): ArmStats {
  const mine = runs.filter(r => r.arm === arm);
  const discarded = mine.filter(r => r.status === 'discarded');
  const valid = mine.filter(r => r.status !== 'discarded');
  const accepted = valid.filter(r => r.status === 'accepted');
  const acceptedMs = accepted.map(r => r.durationMs);
  const totalWallMs = valid.reduce((sum, r) => sum + r.durationMs, 0);
  const elDelays = valid.map(r => r.peakEventLoopDelayMs).filter((v): v is number => v !== null);
  const treeRss = valid.map(r => r.processTreeRssBytes).filter((v): v is number => v !== null);
  return {
    arm,
    attempts: mine.length,
    valid: valid.length,
    accepted: accepted.length,
    rejected: valid.filter(r => r.status === 'rejected').length,
    errored: valid.filter(r => r.status === 'error').length,
    discarded: discarded.length,
    acceptedFraction: valid.length ? accepted.length / valid.length : null,
    p50Ms: percentile(acceptedMs, 0.5),
    p95Ms: percentile(acceptedMs, 0.95),
    minMs: acceptedMs.length ? Math.min(...acceptedMs) : null,
    maxMs: acceptedMs.length ? Math.max(...acceptedMs) : null,
    acceptedN: accepted.length,
    totalWallMs,
    costPerAcceptedMs: accepted.length ? totalWallMs / accepted.length : null,
    peakRssDeltaBytes: valid.reduce((max, r) => Math.max(max, r.rssDeltaBytes), 0),
    maxEventLoopDelayMs: elDelays.length ? Math.max(...elDelays) : null,
    maxProcessTreeRssBytes: treeRss.length ? Math.max(...treeRss) : null,
  };
}

export function compare(config: PairedConfig, runs: RunRecord[], baseline: ArmStats, candidate: ArmStats): PairedComparison {
  const reasons: string[] = [];
  const byPair = new Map<number, { baseline?: RunRecord; candidate?: RunRecord }>();
  for (const run of runs) {
    if (run.pairIndex < 0) continue; // warmup
    const slot = byPair.get(run.pairIndex) ?? {};
    slot[run.arm] = run;
    byPair.set(run.pairIndex, slot);
  }
  const deltasMs: number[] = [];
  for (const slot of byPair.values()) {
    if (slot.baseline?.status === 'accepted' && slot.candidate?.status === 'accepted') {
      deltasMs.push(slot.candidate.durationMs - slot.baseline.durationMs);
    }
  }
  const p50DeltaMs = percentile(deltasMs, 0.5);
  const relativeChange =
    p50DeltaMs !== null && baseline.p50Ms !== null && baseline.p50Ms > 0 ? p50DeltaMs / baseline.p50Ms : null;
  const acceptedFractionDelta =
    candidate.acceptedFraction !== null && baseline.acceptedFraction !== null
      ? candidate.acceptedFraction - baseline.acceptedFraction
      : null;
  const costPerAcceptedChange =
    candidate.costPerAcceptedMs !== null && baseline.costPerAcceptedMs !== null && baseline.costPerAcceptedMs > 0
      ? (candidate.costPerAcceptedMs - baseline.costPerAcceptedMs) / baseline.costPerAcceptedMs
      : null;

  const minPairedFraction = config.minPairedSuccessFraction ?? 0.5;
  let verdict: Verdict;

  if (baseline.valid === 0 || candidate.valid === 0) {
    verdict = 'invalid';
    reasons.push('an arm produced no valid run; there is nothing to compare');
  } else if (candidate.accepted === 0 && baseline.accepted > 0) {
    // Covers the false-success mutant: it claimed success every time and was graded wrong every time.
    verdict = 'regressed';
    reasons.push(
      `candidate had no accepted run against ${baseline.accepted} for the baseline; ` +
      `it produced no result to be fast about`
    );
  } else if (
    acceptedFractionDelta !== null &&
    acceptedFractionDelta < -config.qualityRegressionMargin
  ) {
    // Covers the denominator mutant: skipping hard cases lowers latency and loses here.
    verdict = 'regressed';
    reasons.push(
      `acceptance rate fell ${(Math.abs(acceptedFractionDelta) * 100).toFixed(1)} points ` +
      `(${(baseline.acceptedFraction! * 100).toFixed(1)}% → ${(candidate.acceptedFraction! * 100).toFixed(1)}%), ` +
      `past the predeclared ${(config.qualityRegressionMargin * 100).toFixed(1)}-point margin`
    );
  } else if (deltasMs.length < Math.ceil(minPairedFraction * config.pairs)) {
    verdict = 'inconclusive';
    reasons.push(
      `only ${deltasMs.length} of ${config.pairs} pairs had both arms accepted; ` +
      `too few paired successes for a latency verdict`
    );
  } else if (relativeChange === null) {
    verdict = 'inconclusive';
    reasons.push('no baseline latency to compare against');
  } else if (relativeChange <= -config.minImprovementFraction) {
    if (costPerAcceptedChange !== null && costPerAcceptedChange > config.minImprovementFraction) {
      verdict = 'inconclusive';
      reasons.push(
        `paired p50 improved ${(Math.abs(relativeChange) * 100).toFixed(1)}% but cost per accepted result ` +
        `rose ${(costPerAcceptedChange * 100).toFixed(1)}%; a faster run that costs more per accepted ` +
        `result is not an improvement`
      );
    } else {
      verdict = 'improved';
      reasons.push(
        `paired p50 improved ${(Math.abs(relativeChange) * 100).toFixed(1)}% over ${deltasMs.length} paired successes`
      );
    }
  } else if (relativeChange >= config.minImprovementFraction) {
    verdict = 'regressed';
    reasons.push(`paired p50 worsened ${(relativeChange * 100).toFixed(1)}% over ${deltasMs.length} paired successes`);
  } else {
    verdict = 'no-change';
    reasons.push(
      `paired p50 moved ${(relativeChange * 100).toFixed(1)}%, inside the predeclared ` +
      `${(config.minImprovementFraction * 100).toFixed(1)}% band`
    );
  }

  if (verdict !== 'invalid' && candidate.p95Ms !== null && baseline.p95Ms !== null && baseline.p95Ms > 0) {
    const p95Change = (candidate.p95Ms - baseline.p95Ms) / baseline.p95Ms;
    if (verdict === 'improved' && p95Change >= config.minImprovementFraction) {
      reasons.push(`p95 rose ${(p95Change * 100).toFixed(1)}% while p50 fell; report both before adopting`);
    }
  }

  return { pairedSuccessN: deltasMs.length, deltasMs, p50DeltaMs, relativeChange, acceptedFractionDelta, costPerAcceptedChange, verdict, reasons };
}

// --- manifest -----------------------------------------------------------------------------------

export interface DirtyState {
  /**
   * How the digest was produced. `status+content-hash` hashes the working-tree bytes of every path
   * `git status --porcelain` reports as changed. `git diff HEAD` is deliberately not used: on this
   * checkout it takes over two minutes, and a manifest step that stalls a measurement run is worse
   * than one that identifies the same state a cheaper way.
   */
  method: 'status+content-hash';
  /** SHA-256 over `<path>\0<sha256 of working-tree bytes>` for each changed path, sorted. */
  sha256: string;
  changedPaths: number;
  /** Paths git reported as changed but whose bytes could not be read (deleted, unreadable). */
  unreadablePaths: number;
}

export interface RunManifest {
  startedAt: string;
  gitHead: string | null;
  /**
   * Identity of the working tree beyond the commit. Null when git is unavailable — a missing
   * digest stays missing rather than implying a clean checkout.
   */
  dirtyState: DirtyState | null;
  node: string;
  bun: string | null;
  platform: string;
  arch: string;
  osRelease: string;
  cpuModel: string;
  cpuCount: number;
  totalMemBytes: number;
  freeMemBytes: number;
  loadAverage: number[];
  /** SHA-256 of each named fixture or source file the comparison depends on. */
  files: Record<string, string>;
}

function git(args: string[], timeoutMs = 20_000): string | null {
  try {
    return execFileSync('git', args, { encoding: 'utf8', timeout: timeoutMs, maxBuffer: 64 * 1024 * 1024 });
  } catch {
    return null;
  }
}

/** Memoized: the checkout does not change during a run, and a repeated probe is pure overhead. */
let cachedIdentity: { head: string | null; dirty: DirtyState | null } | undefined;

export function checkoutIdentity(): { head: string | null; dirty: DirtyState | null } {
  if (cachedIdentity) return cachedIdentity;
  const head = git(['rev-parse', 'HEAD'])?.trim() ?? null;
  const status = git(['status', '--porcelain']);
  let dirty: DirtyState | null = null;
  if (status !== null) {
    const paths: string[] = [];
    for (const line of status.split('\n')) {
      if (!line.trim()) continue;
      // Porcelain v1: two status characters, a space, then the path (or `old -> new` for a rename).
      const raw = line.slice(3);
      const renamed = raw.split(' -> ');
      paths.push(renamed[renamed.length - 1].replace(/^"|"$/g, ''));
    }
    let unreadable = 0;
    const entries: string[] = [];
    for (const p of paths.sort()) {
      try {
        const st = fs.statSync(p);
        if (st.isDirectory()) { entries.push(`${p}\0directory`); continue; }
        entries.push(`${p}\0${createHash('sha256').update(fs.readFileSync(p)).digest('hex')}`);
      } catch {
        unreadable++;
        entries.push(`${p}\0unreadable`);
      }
    }
    dirty = {
      method: 'status+content-hash',
      sha256: createHash('sha256').update(entries.join('\n')).digest('hex'),
      changedPaths: paths.length,
      unreadablePaths: unreadable,
    };
  }
  cachedIdentity = { head, dirty };
  return cachedIdentity;
}

/** Test seam: forget the memoized checkout identity. */
export function __resetCheckoutIdentity(): void { cachedIdentity = undefined; }

export function buildManifest(files: string[] = []): RunManifest {
  const identity = checkoutIdentity();
  const cpus = os.cpus();
  const hashes: Record<string, string> = {};
  for (const file of files) {
    try {
      hashes[file] = createHash('sha256').update(fs.readFileSync(file)).digest('hex');
    } catch (e: any) {
      hashes[file] = `unavailable: ${e?.code ?? 'read failed'}`;
    }
  }
  return {
    startedAt: new Date().toISOString(),
    gitHead: identity.head,
    dirtyState: identity.dirty,
    node: process.version,
    bun: (globalThis as any).Bun?.version ?? null,
    platform: process.platform,
    arch: process.arch,
    osRelease: os.release(),
    cpuModel: cpus[0]?.model ?? 'unknown',
    cpuCount: cpus.length,
    totalMemBytes: os.totalmem(),
    freeMemBytes: os.freemem(),
    loadAverage: os.loadavg(),
    files: hashes,
  };
}

/**
 * Resident memory of this process and every descendant, in bytes. Null when `ps` is unavailable or
 * unparsable — a missing measurement stays missing rather than becoming this process's own RSS.
 */
export function processTreeRssBytes(rootPid = process.pid): number | null {
  let out: string;
  try {
    out = execFileSync('ps', ['-Ao', 'pid=,ppid=,rss='], { encoding: 'utf8', timeout: 5_000 });
  } catch {
    return null;
  }
  const children = new Map<number, number[]>();
  const rssKb = new Map<number, number>();
  for (const line of out.split('\n')) {
    const m = line.trim().match(/^(\d+)\s+(\d+)\s+(\d+)$/);
    if (!m) continue;
    const pid = Number(m[1]);
    const ppid = Number(m[2]);
    rssKb.set(pid, Number(m[3]));
    children.set(ppid, [...(children.get(ppid) ?? []), pid]);
  }
  if (!rssKb.has(rootPid)) return null;
  let total = 0;
  const stack = [rootPid];
  const seen = new Set<number>();
  while (stack.length) {
    const pid = stack.pop()!;
    if (seen.has(pid)) continue;
    seen.add(pid);
    total += rssKb.get(pid) ?? 0;
    for (const child of children.get(pid) ?? []) stack.push(child);
  }
  return total * 1024;
}

// --- the runner ---------------------------------------------------------------------------------

export interface PairedRunOptions<T> {
  config: PairedConfig;
  baseline: Arm<T>;
  candidate: Arm<T>;
  grade: Grader<T>;
  /**
   * Return a reason to invalidate a run (a provider outage, a machine that went to sleep). A
   * discarded run is excluded from timing and from the acceptance denominator, and every discard is
   * counted with its reason in the report. A product-caused hang or timeout is NOT a discard.
   */
  discard?: (record: Omit<RunRecord, 'status' | 'discardReason'>, outcome: ArmOutcome<T>) => string | null;
  /** Files whose hashes identify this comparison. */
  manifestFiles?: string[];
  /** Collect whole-process-tree RSS around each run. Off by default: it spawns `ps`. */
  measureProcessTree?: boolean;
  /**
   * The clock each run is timed with, in ms. Defaults to `performance.now`. Tests of the VERDICT
   * rule inject one: two 4 ms arms timed on a loaded machine differ by more than the 5% band from
   * timer jitter alone, which made "identical implementations are no-change" fail now and then.
   */
  now?: () => number;
}

export async function runPaired<T>(options: PairedRunOptions<T>): Promise<PairedReport> {
  const { config, grade } = options;
  if (!Number.isInteger(config.pairs) || config.pairs < 1) {
    throw new Error('pairs must be a positive integer, predeclared before the run');
  }
  const manifest = buildManifest(options.manifestFiles ?? []);
  const startedAt = new Date().toISOString();
  const runs: RunRecord[] = [];
  let runIndex = 0;

  const executeOne = async (arm: ArmName, pairIndex: number, positionInPair: number): Promise<void> => {
    const fn = arm === 'baseline' ? options.baseline : options.candidate;
    const ctx: RunContext = { arm, pairIndex, positionInPair, runIndex: runIndex++ };
    const before = sampleResources();
    const treeBefore = options.measureProcessTree ? processTreeRssBytes() : null;
    const now = options.now ?? (() => performance.now());
    const t0 = now();
    let outcome: ArmOutcome<T>;
    try {
      outcome = await fn(ctx);
    } catch (e: any) {
      outcome = { claimedSuccess: false, error: e?.message ?? String(e) };
    }
    const durationMs = now() - t0;
    const after = sampleResources();
    const treeAfter = options.measureProcessTree ? processTreeRssBytes() : null;

    let graded: Grade;
    try {
      graded = await grade(outcome, ctx);
    } catch (e: any) {
      graded = { accepted: false, reason: `grader failed: ${e?.message ?? String(e)}` };
    }

    const partial: Omit<RunRecord, 'status' | 'discardReason'> = {
      arm,
      pairIndex,
      positionInPair,
      runIndex: ctx.runIndex,
      durationMs,
      claimedSuccess: outcome.claimedSuccess,
      gradeReason: graded.reason,
      gradeEvidence: graded.evidence,
      error: outcome.error,
      rssDeltaBytes: after.rssBytes - before.rssBytes,
      peakEventLoopDelayMs: after.eventLoopDelayMaxMs,
      processTreeRssBytes:
        treeAfter !== null && treeBefore !== null ? Math.max(treeAfter, treeBefore) : treeAfter ?? treeBefore,
    };

    const discardReason = options.discard?.(partial, outcome) ?? null;
    const status: RunStatus = discardReason
      ? 'discarded'
      : graded.accepted
        ? 'accepted'
        : outcome.error && !outcome.claimedSuccess
          ? 'error'
          : 'rejected';
    if (pairIndex >= 0) runs.push({ ...partial, status, ...(discardReason ? { discardReason } : {}) });
  };

  for (let w = 0; w < (config.warmupRuns ?? 0); w++) {
    await executeOne('baseline', -1, 0);
    await executeOne('candidate', -1, 1);
  }
  for (let pair = 0; pair < config.pairs; pair++) {
    // Alternate which arm goes first so warmup, cache and thermal drift do not favour one side.
    const order: ArmName[] = pair % 2 === 0 ? ['baseline', 'candidate'] : ['candidate', 'baseline'];
    for (let position = 0; position < order.length; position++) {
      await executeOne(order[position], pair, position);
    }
  }

  const baseline = statsFor('baseline', runs);
  const candidate = statsFor('candidate', runs);
  const comparison = compare(config, runs, baseline, candidate);

  const discardCounts = new Map<string, number>();
  for (const run of runs) {
    if (run.status === 'discarded' && run.discardReason) {
      discardCounts.set(run.discardReason, (discardCounts.get(run.discardReason) ?? 0) + 1);
    }
  }

  const notes: string[] = [];
  if (comparison.pairedSuccessN < config.pairs) {
    notes.push(
      `${config.pairs - comparison.pairedSuccessN} of ${config.pairs} pairs did not produce a paired ` +
      `success; the paired latency subset is ${comparison.pairedSuccessN} pairs`
    );
  }
  if (baseline.discarded || candidate.discarded) {
    notes.push(`${baseline.discarded + candidate.discarded} run(s) were discarded as invalid and excluded from timing`);
  }
  notes.push('Durations are attempt wall time on this machine, not product latency for any user-visible boundary.');

  return {
    schema: 1,
    name: config.name,
    startedAt,
    finishedAt: new Date().toISOString(),
    config,
    configHash: createHash('sha256').update(JSON.stringify(config)).digest('hex'),
    manifest,
    percentileMethod: 'nearest-rank',
    runs,
    baseline,
    candidate,
    comparison,
    discards: [...discardCounts.entries()].map(([reason, count]) => ({ reason, count })),
    notes,
  };
}

/** Write a report without ever replacing one. A rerun gets a new path or it does not get written. */
export function writeReport(filePath: string, report: PairedReport): void {
  fs.mkdirSync(path.dirname(filePath), { recursive: true });
  fs.writeFileSync(filePath, JSON.stringify(report, null, 2) + '\n', { flag: 'wx' });
}

export function summarize(report: PairedReport): string {
  const ms = (v: number | null) => (v === null ? 'unavailable' : `${v.toFixed(1)} ms`);
  const pct = (v: number | null) => (v === null ? 'unavailable' : `${(v * 100).toFixed(1)}%`);
  const arm = (s: ArmStats) =>
    `${s.arm.padEnd(9)} accepted ${s.accepted}/${s.valid} (${pct(s.acceptedFraction)}) · ` +
    `p50 ${ms(s.p50Ms)} · p95 ${ms(s.p95Ms)} · total ${ms(s.totalWallMs)} · per accepted ${ms(s.costPerAcceptedMs)}`;
  return [
    `${report.name} — ${report.comparison.verdict.toUpperCase()}`,
    arm(report.baseline),
    arm(report.candidate),
    `paired successes: ${report.comparison.pairedSuccessN}/${report.config.pairs} · ` +
    `p50 delta ${ms(report.comparison.p50DeltaMs)} (${pct(report.comparison.relativeChange)})`,
    ...report.comparison.reasons.map(r => `  · ${r}`),
    ...report.notes.map(n => `  note: ${n}`),
  ].join('\n');
}

// Bimax causal evidence vocabulary — the shared cross-product contract for owner sections 28/29
// (V28B, V29B; see docs/product-reset/11_SECTIONS_28_29_RESEARCH_AND_DELIVERY_PLAN.md §2.2 and
// §10 slice S28-A step 1).
//
// This file is the SOURCE OF TRUTH and is mirrored verbatim into the Desktop app by
// `npm run gen:app-protocol` (drift gate: `npm run check:protocol-mirror`). It must therefore stay
// dependency-free and pure: no `node:` imports, no filesystem, no crypto, no engine types. Hashing,
// persistence and redaction *policy sources* live on each side of the boundary; the vocabulary,
// the canonical serialization and the honesty invariants live here so both products agree on what
// a piece of evidence means and when it is inadmissible.
//
// Two rules from the research shape almost every type below and are enforced, not documented:
//
//   1. "An evidence gap, dropped event or unavailable sensor cannot produce an unqualified safe
//      verdict" (08_ACCEPTANCE_GATES.md, section 28 gate). A Verification therefore carries
//      `satisfied: boolean | null` and `null` is the *required* value when the observation backing
//      it is incomplete or stale. There is no way to spell "safe, but we did not look".
//   2. "A lower level cannot waive a higher-level denial … no model-only block" (§2.3, §6). The
//      detection layer that produced a Decision bounds the disposition it is allowed to carry, in
//      both directions: a model may not block, and a deterministic hard floor may not be softened
//      into an advisory by anything that ran later.

/** Wire identity of this vocabulary. Consumers must reject a payload from another schema line. */
export const EVIDENCE_SCHEMA = 'bimax.evidence/1' as const;
export type EvidenceSchema = typeof EVIDENCE_SCHEMA;

/** JSON-safe value. Evidence crosses a process boundary; nothing else may be stored in it. */
export type JsonValue = string | number | boolean | null | JsonValue[] | { [k: string]: JsonValue };

// --- Identity and relationships ------------------------------------------------------------

/** What an observation is *about*. §2.2 "Identity". */
export type IdentityKind =
  | 'process' | 'executable' | 'package' | 'project' | 'app' | 'endpoint'
  | 'capability' | 'file' | 'user' | 'agent';

export interface Identity {
  kind: IdentityKind;
  /** Stable, already-redacted identifier: a normalized path, bundle id, host:port, package name. */
  id: string;
  display?: string;
  /** Code-signing / publisher identity when macOS or a package manifest supplied one. */
  signer?: string | null;
  /** Content digest when the artifact is content-addressed (`sha256:...`). */
  digest?: string | null;
  /** How Bimax learned this identity exists. Absent means "asserted by the caller", the weakest. */
  provenance?: 'macos' | 'signed-metadata' | 'observed' | 'declared' | null;
}

/** §2.2 "Relationship". The verbs a causal graph edge may use. */
export type RelationshipKind =
  | 'spawned-by' | 'read' | 'wrote' | 'deleted' | 'connected-to' | 'installed-by' | 'loaded-by';

export interface Relationship { kind: RelationshipKind; object: Identity }

// --- Collection contract (§2.1) -------------------------------------------------------------

export type Scope = 'task' | 'project' | 'app' | 'device';
/** Sensitivity class. `secret` is not a storage class — it is a refusal: see `redactFacts`. */
export type Sensitivity = 'public' | 'project' | 'sensitive' | 'secret';
/** Retention class. `none` means the datum may be used for a decision and never persisted. */
export type Retention = 'none' | 'session' | 'task' | 'bounded' | 'audit';

/** Which Bimax component produced an observation. There is no "unknown" sensor. */
export type SensorId =
  | 'engine.tool'
  | 'engine.governor'
  | 'mcp.client'
  | 'package.resolver'
  | 'environment.inventory'
  | 'browser.runtime'
  | 'desktop.mac'
  | 'desktop.broker'
  | 'capability.graph';

/**
 * Whether the evidence behind a claim is whole. Every sensor must report this honestly; a sensor
 * that cannot tell reports `complete: false` with a reason rather than assuming success.
 */
export interface Completeness {
  complete: boolean;
  /** Events the sensor knows it lost (queue overflow, coalesced FSEvents, dropped XPC messages). */
  droppedEvents: number;
  /** Monotonic sequence the sensor was at, when it has one. A gap here is a gap in the graph. */
  sequence?: number | null;
  /** Required whenever `complete` is false. Rendered to the user verbatim. */
  reason?: string | null;
}

export const COMPLETE: Completeness = { complete: true, droppedEvents: 0, sequence: null, reason: null };

export function gap(reason: string, droppedEvents = 0, sequence: number | null = null): Completeness {
  return { complete: false, droppedEvents, sequence, reason };
}

/** True when this completeness record may back a positive ("it is fine") claim. */
export function admissible(c: Completeness): boolean {
  return c.complete && c.droppedEvents === 0;
}

/**
 * Whether a conclusion rests on what was measured or on what something said it would do.
 *
 * This is a different axis from completeness, and conflating the two was a real defect: Terminal has
 * no process-provenance sensor (that is S28-D, entitlement-gated), so the effects of a shell command
 * are read from its text. That is not a *gap* — nothing was dropped, and treating it as one made
 * every ordinary `npm test` raise an evidence-gap finding, which would fail the notification-volume
 * budget in 08_ACCEPTANCE_GATES.md rather than protect anyone.
 *
 * A declared basis is still enough to refuse an operation — a command that names a credential store
 * is refused on its text, exactly as the Governor's static analysis already does. It is not enough
 * to certify an end state, which is why `satisfied: true` requires `observed`.
 */
export type EvidenceBasis = 'observed' | 'declared' | 'mixed';

const BASES: ReadonlySet<string> = new Set<EvidenceBasis>(['observed', 'declared', 'mixed']);

/** True when a value is a real basis. A record that omits it makes no claim about its own footing. */
export function isBasis(value: unknown): value is EvidenceBasis {
  return typeof value === 'string' && BASES.has(value);
}

/** The weaker of two bases. `observed` only survives when nothing declared is mixed in. */
export function combineBasis(a: EvidenceBasis, b: EvidenceBasis): EvidenceBasis {
  if (a === b) return a;
  return 'mixed';
}

/** The basis implied by an identity's provenance. */
export function basisOfProvenance(provenance: Identity['provenance']): EvidenceBasis {
  return provenance === 'declared' || provenance === null || provenance === undefined
    ? 'declared' : 'observed';
}

// --- TaskIntent: what the user approved, and its boundaries ----------------------------------

/**
 * The declared boundary of a task. Absent permission is denial: every field is an allowance, and
 * the default-constructed boundary allows nothing beyond reading the project.
 */
export interface TaskBoundary {
  /** Normalized absolute roots the task may write inside. Empty means "no writes are in scope". */
  writeRoots: string[];
  /** Normalized absolute roots the task may read inside. */
  readRoots: string[];
  /** Hosts the task declared it would contact. Empty with `allowNetwork` means "any declared use". */
  allowedHosts: string[];
  allowNetwork: boolean;
  /** Dependency/lockfile changes — "run tests; do not install" is the canonical §5 contract. */
  allowInstall: boolean;
  allowDeploy: boolean;
  /** Reading credential stores (SSH keys, keychains, browser credential databases). */
  allowCredentialAccess: boolean;
  /** LaunchAgents/LaunchDaemons/login items — persistence, MITRE T1543. */
  allowPersistence: boolean;
  /** Modifying security settings. Never grantable to a Bimax-owned operation; see RULE_IDS. */
  allowSecuritySettings: false;
}

export function emptyBoundary(overrides: Partial<Omit<TaskBoundary, 'allowSecuritySettings'>> = {}): TaskBoundary {
  return {
    writeRoots: [], readRoots: [], allowedHosts: [],
    allowNetwork: false, allowInstall: false, allowDeploy: false,
    allowCredentialAccess: false, allowPersistence: false,
    allowSecuritySettings: false,
    ...overrides,
  };
}

export type ApprovalMode = 'interactive' | 'plan' | 'auto' | 'strict' | 'bypass' | 'unattended';

export interface TaskIntent {
  schema: EvidenceSchema;
  kind: 'TaskIntent';
  id: string;
  createdAt: number;
  /** One line of what the user asked for. Never the full prompt — that is task-scoped content. */
  summary: string;
  projectRoot: string | null;
  boundary: TaskBoundary;
  approvalMode: ApprovalMode;
}

// --- OperationIntent: what the agent or subsystem proposed -----------------------------------

export type Subsystem =
  | 'engine-tool' | 'mcp' | 'package' | 'environment' | 'browser' | 'computer-use' | 'capability';

/**
 * What an operation says it will do, captured *before* it runs. The whole of Layer B is comparing
 * this against the TaskBoundary, and later against what the ActionReceipt shows actually happened.
 */
export interface DeclaredEffects {
  reads: string[];
  writes: string[];
  deletes: string[];
  hosts: string[];
  /** Executables the operation expects to launch, by basename or absolute path. */
  processes: string[];
  installsDependencies: boolean;
  /** Set when the operation is inherently read-only; a write in its receipt then contradicts it. */
  readOnly: boolean;
}

export function noEffects(overrides: Partial<DeclaredEffects> = {}): DeclaredEffects {
  return {
    reads: [], writes: [], deletes: [], hosts: [], processes: [],
    installsDependencies: false, readOnly: false, ...overrides,
  };
}

export interface OperationIntent {
  schema: EvidenceSchema;
  kind: 'OperationIntent';
  id: string;
  taskIntentId: string;
  /** The operation that caused this one. This is the edge the causal path in §5 walks. */
  parentOperationId: string | null;
  createdAt: number;
  subsystem: Subsystem;
  /** Tool/verb name, e.g. `Bash`, `mcp:filesystem/read_file`, `mac.click`, `npm.install`. */
  operation: string;
  actor: Identity;
  declared: DeclaredEffects;
  /**
   * Content that reached this operation from an untrusted source (web page, MCP tool output,
   * package description). Carried so a Decision can say *why* an operation is treated as tainted.
   */
  taint: string[];
}

// --- Observation: an immutable fact from an identified sensor --------------------------------

export interface Observation {
  schema: EvidenceSchema;
  kind: 'Observation';
  id: string;
  createdAt: number;
  sensor: SensorId;
  scope: Scope;
  sensitivity: Sensitivity;
  retention: Retention;
  taskIntentId: string | null;
  operationIntentId: string | null;
  subject: Identity;
  relationship: Relationship | null;
  /** Already-redacted. `redactFacts` is the only supported way to build this. */
  facts: Record<string, JsonValue>;
  /** Age of the underlying measurement when it was recorded, in ms. 0 means "measured now". */
  freshnessMs: number;
  completeness: Completeness;
}

// --- Decision: rule/model versions, factors, disposition -------------------------------------

/**
 * §6 detection stack. The layer is not decoration: `dispositionCeiling` reads it to decide what a
 * layer is permitted to conclude.
 */
export type DetectionLayer =
  | 'A' // invariants — deterministic hard floors
  | 'B' // task and capability mismatch — deterministic, comparison of declared vs approved
  | 'C' // known risky macOS behavior — versioned deterministic rules
  | 'D' // provenance anomaly — explain-only until a labeled local corpus exists
  | 'E' // statistical anomaly — ranks review, never authorizes
  | 'F'; // model-assisted explanation — hypotheses only

/** §7 disposition ladder, ordered from least to most invasive. */
export const DISPOSITIONS = [
  'observe', 'explain', 'recommend', 'require-approval', 'isolate', 'block', 'repair',
] as const;
export type Disposition = typeof DISPOSITIONS[number];

export function dispositionRank(d: Disposition): number { return DISPOSITIONS.indexOf(d); }

function unreachable(value: never): never {
  throw new Error(`unhandled evidence variant: ${String(value)}`);
}

/**
 * The highest disposition a layer may reach on its own. Layers D–F are advisory by construction:
 * "Scores rank review; they do not directly authorize repair or destructive containment" (§6 E) and
 * a model's "output is labeled model explanation … cannot change disposition" (§6 F).
 */
export function dispositionCeiling(layer: DetectionLayer): Disposition {
  switch (layer) {
    case 'A': return 'repair';
    case 'B': return 'block';
    case 'C': return 'require-approval';
    case 'D': return 'recommend';
    case 'E': return 'recommend';
    case 'F': return 'explain';
  }
  return unreachable(layer);
}

/** §7 named factors. A single opaque score is explicitly rejected by the research. */
export interface RiskFactors {
  hardBoundary: boolean;
  taskMismatch: boolean;
  identityTrust: 'macos-verified' | 'signed' | 'known' | 'unknown' | 'contradicted';
  targetSensitivity: Sensitivity;
  persistencePotential: boolean;
  networkNovelty: boolean;
  /** Two or more independently weak signals on one causal path — §5's combined finding. */
  causalCombination: boolean;
  observationCompleteness: Completeness;
  /** 0..1, or null when no statistical layer ran. Never the sole cause of a block or repair. */
  anomalyConfidence: number | null;
}

export interface EvidenceRef {
  /** An Observation id. Findings that cite nothing are vacuous and are rejected by `validate`. */
  observationId: string;
  why: string;
}

export interface Finding {
  /** Stable rule identifier, e.g. `BMX-A-CREDENTIAL-READ`. Registered in RULE_IDS. */
  ruleId: string;
  layer: DetectionLayer;
  /** What happened, in the user's language. */
  what: string;
  /** Which expectation it violated. */
  violated: string;
  /**
   * Who performed it and what it touched. §5 requires every finding to answer "which identity
   * performed it" and "what caused it"; a finding that cannot name a subject is not actionable, so
   * `validate` rejects an empty list.
   */
  subjects: Identity[];
  /** Plausible benign explanations, per §5. Empty is allowed only for Layer A invariants. */
  benignExplanations: string[];
  evidence: EvidenceRef[];
}

export interface Decision {
  schema: EvidenceSchema;
  kind: 'Decision';
  id: string;
  createdAt: number;
  taskIntentId: string;
  operationIntentId: string;
  /** Version of the deterministic rule set that ran. Always present. */
  ruleVersion: string;
  /** Version of the model that contributed an explanation, or null when none did. */
  modelVersion: string | null;
  /** The highest layer that contributed to `disposition`. Bounds it via `dispositionCeiling`. */
  layer: DetectionLayer;
  factors: RiskFactors;
  disposition: Disposition;
  findings: Finding[];
  /** Whether the findings rest on measurement or on declaration. See `EvidenceBasis`. */
  evidenceBasis: EvidenceBasis;
  /** Free-text model hypothesis, always labelled and never load-bearing. */
  modelExplanation: string | null;
}

// --- Approval, ActionReceipt, Verification, Rollback -----------------------------------------

export interface Approval {
  schema: EvidenceSchema;
  kind: 'Approval';
  id: string;
  createdAt: number;
  operationIntentId: string;
  decisionId: string | null;
  grantedBy: 'user' | 'policy';
  /** Exactly what was approved — narrower than or equal to the operation's declared effects. */
  scope: DeclaredEffects;
  /** Absolute ms. `null` means single-use: valid only for the operation it names. */
  expiresAt: number | null;
}

export type ActionOutcome = 'applied' | 'refused' | 'failed' | 'rolled-back';

export interface ActionReceipt {
  schema: EvidenceSchema;
  kind: 'ActionReceipt';
  id: string;
  createdAt: number;
  operationIntentId: string;
  approvalId: string | null;
  /** Which executor actually performed it (`bash`, `native-semantic`, `mcp-stdio`, …). */
  executor: string;
  outcome: ActionOutcome;
  /** What the operation actually touched, as observed — not as declared. */
  observed: DeclaredEffects;
  /** Observation ids for the before state. */
  before: string[];
  /** Observation ids for the after state. */
  after: string[];
  reason: string;
}

export interface Verification {
  schema: EvidenceSchema;
  kind: 'Verification';
  id: string;
  createdAt: number;
  actionReceiptId: string;
  /** Human-readable postcondition that was checked. */
  postcondition: string;
  /**
   * `true` only when the check ran on complete, fresh evidence. `false` is a real negative.
   * `null` is "unknown" and is the required value whenever the evidence cannot support a verdict.
   */
  satisfied: boolean | null;
  /** Age of the evidence the verdict rests on. */
  freshnessMs: number;
  /** Maximum age this postcondition tolerates. Older evidence forces `satisfied: null`. */
  freshnessBudgetMs: number;
  completeness: Completeness;
  /** Measured or declared. A postcondition certified from a declaration certifies nothing. */
  basis: EvidenceBasis;
  evidence: EvidenceRef[];
  reason: string;
}

export interface Rollback {
  schema: EvidenceSchema;
  kind: 'Rollback';
  id: string;
  createdAt: number;
  actionReceiptId: string;
  /** What the restoration targets — a checkpoint id, previous capability version, lockfile digest. */
  target: string;
  result: 'restored' | 'partial' | 'failed' | 'not-required';
  /** Verification id proving the restoration, when one ran. A `restored` claim requires one. */
  verificationId: string | null;
  reason: string;
}

export type EvidenceRecord =
  | TaskIntent | OperationIntent | Observation | Decision
  | Approval | ActionReceipt | Verification | Rollback;

// --- Rule registry ---------------------------------------------------------------------------

/**
 * The deterministic rule identifiers this schema line recognizes. A Finding carrying an
 * unregistered id is rejected: a rule the user cannot look up is not explainable, and §5 requires
 * every finding to name "which rule/model produced the assessment".
 */
export const RULE_IDS = {
  // Layer A — invariants. Not overridable by any approval.
  CREDENTIAL_READ: 'BMX-A-CREDENTIAL-READ',
  PERSISTENCE_WRITE: 'BMX-A-PERSISTENCE-WRITE',
  SECURITY_SETTING_MUTATION: 'BMX-A-SECURITY-SETTING',
  SYSTEM_INTEGRITY: 'BMX-A-SYSTEM-INTEGRITY',
  PLAN_MODE_WRITE: 'BMX-A-PLAN-MODE-WRITE',
  // Layer B — task and capability mismatch.
  WRITE_OUTSIDE_BOUNDARY: 'BMX-B-WRITE-OUTSIDE-BOUNDARY',
  READ_OUTSIDE_BOUNDARY: 'BMX-B-READ-OUTSIDE-BOUNDARY',
  UNDECLARED_INSTALL: 'BMX-B-UNDECLARED-INSTALL',
  UNDECLARED_HOST: 'BMX-B-UNDECLARED-HOST',
  MANIFEST_EXCEEDED: 'BMX-B-MANIFEST-EXCEEDED',
  RECEIPT_CONTRADICTS_INTENT: 'BMX-B-RECEIPT-CONTRADICTS-INTENT',
  // Layer C — known risky macOS behavior.
  LAUNCH_ITEM_CHANGE: 'BMX-C-LAUNCH-ITEM',
  SSH_AUTHORIZED_KEYS: 'BMX-C-SSH-AUTHORIZED-KEYS',
  BROWSER_CREDENTIAL_STORE: 'BMX-C-BROWSER-CREDENTIALS',
  EXECUTABLE_REPLACED: 'BMX-C-EXECUTABLE-REPLACED',
  // Layer D/E/F — advisory.
  PROVENANCE_ANOMALY: 'BMX-D-PROVENANCE-ANOMALY',
  STATISTICAL_ANOMALY: 'BMX-E-STATISTICAL-ANOMALY',
  MODEL_HYPOTHESIS: 'BMX-F-MODEL-HYPOTHESIS',
  // Evidence honesty — reported like any other finding so a gap is visible in the timeline.
  EVIDENCE_GAP: 'BMX-X-EVIDENCE-GAP',
} as const;

export type RuleId = typeof RULE_IDS[keyof typeof RULE_IDS];

const RULE_ID_SET: ReadonlySet<string> = new Set(Object.values(RULE_IDS));

export function isRuleId(value: string): value is RuleId { return RULE_ID_SET.has(value); }

/** The layer a rule id belongs to, read from its own name so the two can never drift apart. */
export function ruleLayer(ruleId: string): DetectionLayer | 'X' | null {
  const match = /^BMX-([ABCDEFX])-/.exec(ruleId);
  return match ? (match[1] as DetectionLayer | 'X') : null;
}

// --- Redaction -------------------------------------------------------------------------------

/**
 * Keys whose values are never stored, at any sensitivity. §4 (S28-2): "Never store environment
 * variables wholesale. Redact tokens, credentials, query parameters, clipboard content, and file
 * contents". Matching is on the normalized key, so `AWS_SECRET_ACCESS_KEY` and `awsSecretAccessKey`
 * are the same key.
 */
const SECRET_KEY_PATTERNS: RegExp[] = [
  /secret/, /password/, /passwd/, /token/, /apikey/, /credential/, /privatekey/,
  /authorization/, /cookie/, /session(id)?$/, /bearer/, /passphrase/, /keychain/,
  /clipboard/, /filecontents?/, /^content$/, /^body$/, /^env$/, /^environ(ment)?$/,
];

const normalizeKey = (key: string): string => key.toLowerCase().replace(/[^a-z0-9]/g, '');

export function isSecretKey(key: string): boolean {
  const normalized = normalizeKey(key);
  return SECRET_KEY_PATTERNS.some(pattern => pattern.test(normalized));
}

/** The marker left in place of a redacted value, so the *shape* of the fact survives. */
export const REDACTED = '[redacted]' as const;

/**
 * Strip secret-bearing keys and query strings, recursively. This is the only supported way to build
 * `Observation.facts`; `validate` rejects an Observation whose facts still contain a secret key, so
 * a sensor cannot bypass it by constructing the object literally.
 */
export function redactFacts(input: Record<string, unknown>, depth = 0): Record<string, JsonValue> {
  const out: Record<string, JsonValue> = {};
  if (depth > 6) return out;
  for (const [key, value] of Object.entries(input)) {
    if (isSecretKey(key)) { out[key] = REDACTED; continue; }
    out[key] = redactValue(value, depth);
  }
  return out;
}

function redactValue(value: unknown, depth: number): JsonValue {
  if (value === null || value === undefined) return null;
  if (typeof value === 'string') return redactString(value);
  if (typeof value === 'number') return Number.isFinite(value) ? value : null;
  if (typeof value === 'boolean') return value;
  if (Array.isArray(value)) return depth > 6 ? [] : value.slice(0, 64).map(v => redactValue(v, depth + 1));
  if (typeof value === 'object') return redactFacts(value as Record<string, unknown>, depth + 1);
  return null;
}

/**
 * Query strings are dropped from anything URL-shaped: §4 names query parameters explicitly, and a
 * host/port/path is enough identity for every decision this schema supports.
 */
export function redactString(value: string): string {
  if (value.length > 4096) return `${value.slice(0, 4096)}…`;
  return value.replace(/^([a-z][a-z0-9+.-]*:\/\/[^\s?#]*)[?#][^\s]*/i, '$1?[redacted]');
}

/** True when a facts object is already clean — no secret keys survive at any depth. */
export function factsRedacted(facts: Record<string, JsonValue>, depth = 0): boolean {
  if (depth > 8) return true;
  for (const [key, value] of Object.entries(facts)) {
    if (isSecretKey(key) && value !== REDACTED) return false;
    if (value && typeof value === 'object' && !Array.isArray(value)) {
      if (!factsRedacted(value as Record<string, JsonValue>, depth + 1)) return false;
    }
  }
  return true;
}

// --- Canonical serialization -----------------------------------------------------------------

/**
 * Deterministic JSON: object keys sorted, `undefined` dropped. Content-addressed ids are taken over
 * this string on both sides of the boundary, so Desktop and Terminal derive the same id for the
 * same record and a mutated record cannot keep its id.
 */
export function canonicalJson(value: unknown): string {
  return JSON.stringify(canonicalize(value));
}

function canonicalize(value: unknown): JsonValue {
  if (value === null || value === undefined) return null;
  if (Array.isArray(value)) return value.map(canonicalize);
  if (typeof value === 'object') {
    const source = value as Record<string, unknown>;
    const out: { [k: string]: JsonValue } = {};
    for (const key of Object.keys(source).sort()) {
      if (source[key] === undefined) continue;
      out[key] = canonicalize(source[key]);
    }
    return out;
  }
  if (typeof value === 'number') return Number.isFinite(value) ? value : null;
  if (typeof value === 'string' || typeof value === 'boolean') return value;
  return null;
}

/** The exact bytes an id is computed over: the record without its own `id`. */
export function identityPayload(record: EvidenceRecord): string {
  const { id: _ignored, ...rest } = record as EvidenceRecord & { id: string };
  return canonicalJson(rest);
}

/** Short prefix for a record id, so an id is readable in a log line. */
export function idPrefix(kind: EvidenceRecord['kind']): string {
  switch (kind) {
    case 'TaskIntent': return 'task';
    case 'OperationIntent': return 'op';
    case 'Observation': return 'obs';
    case 'Decision': return 'dec';
    case 'Approval': return 'apr';
    case 'ActionReceipt': return 'rcp';
    case 'Verification': return 'ver';
    case 'Rollback': return 'rbk';
  }
  return unreachable(kind);
}

// --- Validation: the honesty invariants -------------------------------------------------------

export interface ValidationResult { ok: boolean; violations: string[] }

const ok = (): ValidationResult => ({ ok: true, violations: [] });
const fail = (...violations: string[]): ValidationResult => ({ ok: false, violations });

/**
 * Reject a record that would let Bimax make a claim its evidence does not support. This runs on
 * every record before it enters a ledger, on both sides of the boundary. It is deliberately
 * unforgiving: an invalid record is a defect in the producer, not a finding about the user.
 */
export function validate(record: EvidenceRecord): ValidationResult {
  if ((record as { schema?: string }).schema !== EVIDENCE_SCHEMA) {
    return fail(`record is not ${EVIDENCE_SCHEMA}`);
  }
  switch (record.kind) {
    case 'TaskIntent': return validateTaskIntent(record);
    case 'OperationIntent': return validateOperationIntent(record);
    case 'Observation': return validateObservation(record);
    case 'Decision': return validateDecision(record);
    case 'Approval': return validateApproval(record);
    case 'ActionReceipt': return validateActionReceipt(record);
    case 'Verification': return validateVerification(record);
    case 'Rollback': return validateRollback(record);
    default: return fail(`unknown evidence kind ${(record as { kind: string }).kind}`);
  }
}

function validateTaskIntent(record: TaskIntent): ValidationResult {
  const violations: string[] = [];
  if (!record.summary.trim()) violations.push('TaskIntent.summary is empty');
  // `allowSecuritySettings` is typed `false`, but the record may arrive over a wire from an older
  // or hostile producer, so the runtime check has to exist too.
  if ((record.boundary as { allowSecuritySettings: unknown }).allowSecuritySettings === true) {
    violations.push('TaskBoundary.allowSecuritySettings can never be granted');
  }
  if (record.boundary.writeRoots.some(root => !root.startsWith('/'))) {
    violations.push('TaskBoundary.writeRoots must be absolute normalized paths');
  }
  if (record.boundary.readRoots.some(root => !root.startsWith('/'))) {
    violations.push('TaskBoundary.readRoots must be absolute normalized paths');
  }
  return violations.length ? fail(...violations) : ok();
}

function validateOperationIntent(record: OperationIntent): ValidationResult {
  const violations: string[] = [];
  if (!record.taskIntentId) violations.push('OperationIntent must name its TaskIntent');
  if (!record.operation.trim()) violations.push('OperationIntent.operation is empty');
  if (record.parentOperationId === record.id) violations.push('OperationIntent is its own parent');
  const declared = record.declared;
  if (declared.readOnly && (declared.writes.length || declared.deletes.length || declared.installsDependencies)) {
    violations.push('OperationIntent declares readOnly and mutations at once');
  }
  return violations.length ? fail(...violations) : ok();
}

function validateObservation(record: Observation): ValidationResult {
  const violations: string[] = [];
  if (record.sensitivity === 'secret') {
    violations.push('an Observation may not be classified secret — redact it instead of storing it');
  }
  if (!factsRedacted(record.facts)) {
    violations.push('Observation.facts still contains a secret-bearing key');
  }
  if (record.freshnessMs < 0) violations.push('Observation.freshnessMs is negative');
  if (!record.completeness.complete && !record.completeness.reason) {
    violations.push('an incomplete Observation must state why');
  }
  if (!record.subject.id) violations.push('Observation.subject has no identity');
  return violations.length ? fail(...violations) : ok();
}

function validateDecision(record: Decision): ValidationResult {
  const violations: string[] = [];
  const ceiling = dispositionCeiling(record.layer);
  if (dispositionRank(record.disposition) > dispositionRank(ceiling)) {
    violations.push(
      `layer ${record.layer} may not reach disposition ${record.disposition} (ceiling ${ceiling})`,
    );
  }
  if (!record.ruleVersion) violations.push('Decision.ruleVersion is required');
  if (!isBasis(record.evidenceBasis)) {
    violations.push('Decision.evidenceBasis must say whether this rests on measurement or declaration');
  }
  if (record.modelExplanation && !record.modelVersion) {
    violations.push('a model explanation must name the model version that produced it');
  }
  for (const finding of record.findings) {
    if (!isRuleId(finding.ruleId)) {
      violations.push(`finding cites unregistered rule ${finding.ruleId}`);
      continue;
    }
    const layerOfRule = ruleLayer(finding.ruleId);
    if (layerOfRule && layerOfRule !== 'X' && layerOfRule !== finding.layer) {
      violations.push(`finding ${finding.ruleId} claims layer ${finding.layer}`);
    }
    if (!finding.evidence.length) {
      violations.push(`finding ${finding.ruleId} cites no observation — a vacuous finding`);
    }
    if (!finding.subjects.length) {
      violations.push(`finding ${finding.ruleId} names no identity that performed or received it`);
    }
    if (finding.layer !== 'A' && !finding.benignExplanations.length) {
      violations.push(`finding ${finding.ruleId} offers no plausible benign explanation`);
    }
  }
  // §6 F and §7: a block or a repair must rest on something deterministic. An anomaly score, however
  // confident, is not that thing.
  if (dispositionRank(record.disposition) >= dispositionRank('block')) {
    const deterministic = record.findings.some(f => f.layer === 'A' || f.layer === 'B' || f.layer === 'C');
    if (!deterministic) violations.push('block/repair requires a deterministic Layer A/B/C finding');
    if (!record.findings.length) violations.push('block/repair with no findings');
  }
  // An unfinished picture may raise suspicion, never lower it: a gap can escalate to explain, but
  // it cannot be the reason a Decision settles at `observe`.
  if (!admissible(record.factors.observationCompleteness) && record.disposition === 'observe') {
    violations.push('a Decision on incomplete evidence may not settle at observe');
  }
  // Refusing on a declaration is legitimate — a command that names a credential store is refused on
  // its text. Repairing on one is not: a correction mutates the machine, and §8 requires it to start
  // from "fresh minimal evidence", not from what a tool said it was about to do.
  if (record.disposition === 'repair' && record.evidenceBasis !== 'observed') {
    violations.push(`a repair requires observed evidence; this rests on ${record.evidenceBasis} effects`);
  }
  if (record.factors.anomalyConfidence !== null
    && (record.factors.anomalyConfidence < 0 || record.factors.anomalyConfidence > 1)) {
    violations.push('anomalyConfidence must be within 0..1');
  }
  return violations.length ? fail(...violations) : ok();
}

function validateApproval(record: Approval): ValidationResult {
  const violations: string[] = [];
  if (!record.operationIntentId) violations.push('Approval must name the operation it approves');
  if (record.expiresAt !== null && record.expiresAt <= record.createdAt) {
    violations.push('Approval expires at or before it was granted');
  }
  return violations.length ? fail(...violations) : ok();
}

function validateActionReceipt(record: ActionReceipt): ValidationResult {
  const violations: string[] = [];
  if (!record.operationIntentId) violations.push('ActionReceipt must name its OperationIntent');
  if (!record.executor) violations.push('ActionReceipt must name the executor that ran it');
  if (record.outcome === 'applied' && !record.after.length) {
    violations.push('an applied ActionReceipt must cite after-state observations');
  }
  if (record.outcome === 'rolled-back' && !record.before.length) {
    violations.push('a rolled-back ActionReceipt must cite the before state it returned to');
  }
  return violations.length ? fail(...violations) : ok();
}

function validateVerification(record: Verification): ValidationResult {
  const violations: string[] = [];
  if (!record.actionReceiptId) violations.push('Verification must name its ActionReceipt');
  if (record.freshnessBudgetMs <= 0) violations.push('Verification.freshnessBudgetMs must be positive');
  const stale = record.freshnessMs > record.freshnessBudgetMs;
  const incomplete = !admissible(record.completeness);
  // The rule the whole schema exists for. Stale or incomplete evidence yields "unknown", and the
  // type system cannot express that — only this check can.
  if (record.satisfied === true && (stale || incomplete)) {
    violations.push(
      'a satisfied Verification requires complete, fresh evidence: '
      + [stale ? `evidence is ${record.freshnessMs}ms old against a ${record.freshnessBudgetMs}ms budget` : '',
        incomplete ? (record.completeness.reason || 'observation is incomplete') : '']
        .filter(Boolean).join('; '),
    );
  }
  // The other half of the same rule. Complete, fresh evidence *of a declaration* still says nothing
  // about the end state, and a postcondition is a claim about the end state.
  if (record.satisfied === true && record.basis !== 'observed') {
    violations.push(
      `a satisfied Verification requires observed evidence; this rests on ${record.basis} effects`,
    );
  }
  if (!isBasis(record.basis)) {
    violations.push('Verification.basis must say whether the postcondition was measured or declared');
  }
  if (record.satisfied !== null && !record.evidence.length) {
    violations.push('a Verification verdict must cite the observations it rests on');
  }
  if (!record.reason.trim()) violations.push('Verification.reason is empty');
  return violations.length ? fail(...violations) : ok();
}

/**
 * Turn a raw postcondition observation into an admissible verdict.
 *
 * Producers must not assign `Verification.satisfied` themselves — this is the only function that
 * decides it. A negative stays negative no matter how patchy the evidence is (Bimax saw something
 * wrong, and hiding that behind "unknown" would be the same lie in the other direction). Only the
 * positive requires complete, fresh evidence; otherwise the verdict is `null`, "we cannot say".
 */
export function concludeSatisfied(
  observedTruth: boolean,
  freshnessMs: number,
  freshnessBudgetMs: number,
  completeness: Completeness,
): boolean | null {
  if (!observedTruth) return false;
  if (!admissible(completeness)) return null;
  if (freshnessMs > freshnessBudgetMs) return null;
  return true;
}

function validateRollback(record: Rollback): ValidationResult {
  const violations: string[] = [];
  if (!record.actionReceiptId) violations.push('Rollback must name its ActionReceipt');
  if (!record.target) violations.push('Rollback must name a restoration target');
  // "mutation testing proves a fake repair cannot pass when end state is wrong" (S28-C exit). A
  // restoration that was never independently checked is a claim, not a result.
  if (record.result === 'restored' && !record.verificationId) {
    violations.push('a restored Rollback must cite an independent Verification');
  }
  return violations.length ? fail(...violations) : ok();
}

import Parser from 'web-tree-sitter';
import { Logger, treeSitterRuntimeAvailable } from '../utils';

export interface Classification {
  category: 'read' | 'write' | 'network_exec' | 'install' | 'unknown';
  risk: 'none' | 'low' | 'medium' | 'high' | 'unknown';
}

// Numeric ordering so we can aggregate the riskiest sub-command of a compound line.
const RISK_ORDER: Record<Classification['risk'], number> = {
  none: 0, low: 1, unknown: 1, medium: 2, high: 3,
};

// Commands that "wrap" another command — the real command is the first non-flag argument
// after them (e.g. `sudo rm -rf /`, `env FOO=1 bash`, `xargs rm`). Unwrapping these is the
// single biggest win over the old first-token tokenizer, which classified `sudo rm` as the
// unknown command "sudo" and missed the dangerous payload entirely.
const WRAPPERS = new Set([
  'sudo', 'doas', 'env', 'command', 'exec', 'nice', 'nohup', 'setsid', 'stdbuf', 'nohup',
]);

// Shell / script interpreters — the dangerous tail of a `curl … | sh` pipeline.
const INTERPRETERS = new Set([
  'sh', 'bash', 'zsh', 'dash', 'ksh', 'fish', 'csh', 'tcsh',
  'python', 'python2', 'python3', 'perl', 'ruby', 'node', 'php', 'rscript', 'osascript',
]);

// Tools that pull bytes off the network — the dangerous head of a download-pipe-to-shell.
const DOWNLOADERS = new Set(['curl', 'wget', 'fetch', 'aria2c', 'http', 'https']);

// Paths a write redirection (`>`, `>>`) should never touch without an explicit prompt.
const SENSITIVE_PREFIXES = [
  '/etc/', '/usr/', '/bin/', '/sbin/', '/boot/', '/sys/', '/dev/', '/var/',
  '/system/', '/library/', '/private/etc/',
];
const SENSITIVE_DOTFILES = ['.ssh/', '.bashrc', '.zshrc', '.bash_profile', '.profile', '.aws/', '.kube/'];

export class BashStaticAnalyzer {
  private static languagePromise: Promise<Parser.Language> | null = null;
  private readonly READ_ONLY_COMMANDS = new Set([
    'ls', 'cat', 'echo', 'pwd', 'whoami', 'date', 'ps', 'top',
    'head', 'tail', 'less', 'more', 'find', 'grep', 'awk', 'sed', 'wc',
    'diff', 'stat', 'file', 'type', 'which', 'whereis', 'git status', 'git log', 'git diff', 'git show',
  ]);

  private readonly WRITE_COMMANDS = new Set([
    'touch', 'mkdir', 'rm', 'rmdir', 'mv', 'cp', 'chmod', 'chown', 'ln',
    'git add', 'git commit', 'git push', 'git checkout', 'git branch', 'git reset',
    'npm run', 'yarn run', 'pnpm run',
  ]);

  private readonly CURL_PIPE_PATTERN = /(curl|wget).*\|\s*(sh|bash|zsh)/i;
  private readonly INSTALL_PATTERNS = [
    /npm\s+(i|install)/i,
    /yarn\s+(add|install)/i,
    /pnpm\s+(add|install)/i,
    /pip\s+install/i,
    /apt(-get)?\s+install/i,
    /brew\s+install/i,
    /gem\s+install/i,
  ];

  // tree-sitter state. Loaded lazily/asynchronously (WASM); analyze() stays synchronous and
  // simply falls back to the regex path until the grammar is ready (or if it never loads).
  private parser: Parser | null = null;
  private warmStarted = false;

  /**
   * Pre-load the tree-sitter-bash grammar so analyze() can use the AST path. Idempotent and
   * best-effort: on any failure we log once and leave the analyzer on its regex fallback.
   * Fire-and-forget this at startup (the Governor does) — there's no need to await it.
   */
  public async warmUp(): Promise<void> {
    if (this.warmStarted) return;
    this.warmStarted = true;
    // Standalone-binary guard: Parser.init() with no wasm on disk aborts with an unhandled
    // rejection that escapes this try/catch (Emscripten). Check before touching it.
    if (!treeSitterRuntimeAvailable()) {
      Logger.warn('[BashAnalyzer] tree-sitter wasm runtime not present — using regex fallback.');
      return;
    }
    try {
      // Parser.init + WASM loading are process-wide work. Governors can be created repeatedly in
      // tests and sub-systems; sharing the promise prevents parallel WASM loads and descriptor
      // spikes while still giving each analyzer its own lightweight Parser instance.
      if (!BashStaticAnalyzer.languagePromise) {
        BashStaticAnalyzer.languagePromise = (async () => {
          await Parser.init();
          const wasmPath = require.resolve('tree-sitter-wasms/out/tree-sitter-bash.wasm');
          return Parser.Language.load(wasmPath);
        })();
      }
      const lang = await BashStaticAnalyzer.languagePromise;
      const parser = new Parser();
      parser.setLanguage(lang);
      this.parser = parser;
      Logger.info('[BashAnalyzer] tree-sitter-bash loaded — AST command analysis active.');
    } catch (e: any) {
      this.parser = null;
      BashStaticAnalyzer.languagePromise = null;
      Logger.warn(`[BashAnalyzer] AST grammar unavailable, using regex fallback: ${e?.message ?? e}`);
    }
  }

  /** True once the AST path is live (mainly for diagnostics/tests). */
  public isAstReady(): boolean { return this.parser !== null; }

  public analyze(command: string): Classification {
    const trimmed = command.trim();
    if (!trimmed) return { category: 'read', risk: 'none' }; // Empty command is safe

    // Prefer the AST path; it inspects EVERY command in a compound line (`a && rm -rf /`),
    // sees into command substitutions (`$(curl … | sh)`), and reads pipelines structurally.
    if (this.parser) {
      const ast = this.analyzeAst(trimmed);
      if (ast) return ast;
    }
    return this.analyzeRegex(trimmed);
  }

  // --- AST path -----------------------------------------------------------------------------

  private analyzeAst(command: string): Classification | null {
    let root: Parser.SyntaxNode;
    try {
      root = this.parser!.parse(command).rootNode;
    } catch {
      return null; // parser blew up — let the regex path try
    }

    const cmdNodes = root.descendantsOfType('command');

    // 1) Download-piped-into-a-shell, detected structurally (catches multi-stage pipes and
    //    reordering the old `curl … | sh` regex missed, e.g. `curl x | tee y | sudo bash`).
    for (const pipe of root.descendantsOfType('pipeline')) {
      if (this.isDownloadToInterpreter(pipe)) {
        return { category: 'network_exec', risk: 'high' };
      }
    }

    const errored = typeof (root as any).hasError === 'function'
      ? (root as any).hasError()
      : (root as any).hasError;
    if (cmdNodes.length === 0) {
      // Nothing we recognise as a command — only trust "safe" if the parse was clean.
      return errored ? null : { category: 'read', risk: 'none' };
    }

    // 2) Classify every command and keep the riskiest. This closes the biggest hole in the
    //    old analyzer: it only ever looked at the FIRST token, so `ls && rm -rf /` read as
    //    a harmless `ls`. Here `rm -rf /` is seen and wins.
    let worst: Classification = { category: 'read', risk: 'none' };
    for (const node of cmdNodes) {
      const cls = this.classifyCommandText(this.effectiveCommandText(node));
      if (RISK_ORDER[cls.risk] > RISK_ORDER[worst.risk]) worst = cls;
    }

    // 3) Write redirections into sensitive paths (`echo x > /etc/passwd`).
    const redir = this.redirectRisk(root);
    if (redir && RISK_ORDER[redir.risk] > RISK_ORDER[worst.risk]) worst = redir;

    return worst;
  }

  /** Does this pipeline pull from the network and feed a shell/interpreter? */
  private isDownloadToInterpreter(pipeNode: Parser.SyntaxNode): boolean {
    let sawDownloader = false;
    let sawInterpreter = false;
    for (const cmd of pipeNode.descendantsOfType('command')) {
      const name = this.effectiveCommandName(cmd);
      if (DOWNLOADERS.has(name)) sawDownloader = true;
      if (INTERPRETERS.has(name)) sawInterpreter = true;
    }
    return sawDownloader && sawInterpreter;
  }

  /** The basename of a command, unwrapping a leading wrapper like `sudo`/`env`/`xargs`. */
  private effectiveCommandName(cmdNode: Parser.SyntaxNode): string {
    const name = basename(cmdNode.childForFieldName('name')?.text ?? '');
    if (WRAPPERS.has(name)) {
      // Skip by node type — web-tree-sitter hands back fresh wrappers, so a `===` identity
      // check against the name node would never match.
      for (const child of cmdNode.namedChildren) {
        if (child.type === 'command_name') continue;
        const t = child.text;
        if (!t || t.startsWith('-') || t.includes('=')) continue; // skip flags / env assignments
        return basename(t);
      }
    }
    return name;
  }

  /**
   * The text of a command with any leading wrapper stripped, so per-command classification
   * (which reuses the regex sets + write-risk heuristics) sees the real payload. For a plain
   * command this is just its text.
   */
  private effectiveCommandText(cmdNode: Parser.SyntaxNode): string {
    const name = basename(cmdNode.childForFieldName('name')?.text ?? '');
    if (!WRAPPERS.has(name)) return cmdNode.text;
    // Drop the wrapper word and any immediately-following flags / env assignments.
    const parts: string[] = [];
    let skipping = true;
    for (const child of cmdNode.namedChildren) {
      if (child.type === 'command_name') continue; // the wrapper itself
      const t = child.text;
      if (skipping && (t.startsWith('-') || t.includes('='))) continue;
      skipping = false;
      parts.push(t);
    }
    return parts.join(' ') || cmdNode.text;
  }

  /** Classify a single, already-unwrapped command string. */
  private classifyCommandText(text: string): Classification {
    const trimmed = text.trim();
    if (!trimmed) return { category: 'read', risk: 'none' };

    if (this.INSTALL_PATTERNS.some(p => p.test(trimmed))) {
      return { category: 'install', risk: 'medium' };
    }

    const tokens = this.tokenize(trimmed);
    const cmdBase = tokens[0] || '';
    const cmdWithSub = tokens.length > 1 ? `${cmdBase} ${tokens[1]}` : cmdBase;

    if (this.READ_ONLY_COMMANDS.has(cmdWithSub) || this.READ_ONLY_COMMANDS.has(cmdBase)) {
      return { category: 'read', risk: 'none' };
    }
    if (this.WRITE_COMMANDS.has(cmdWithSub) || this.WRITE_COMMANDS.has(cmdBase)) {
      return { category: 'write', risk: this.assessWriteRisk(tokens) };
    }
    return { category: 'unknown', risk: 'unknown' };
  }

  /** Escalate write redirections aimed at sensitive system / dotfile paths. */
  private redirectRisk(root: Parser.SyntaxNode): Classification | null {
    const redirects = root.descendantsOfType(['file_redirect', 'redirected_statement']);
    for (const r of redirects) {
      const txt = r.text;
      // Only writes/appends, not reads (`<`). file_redirect text looks like `> /etc/passwd`.
      if (!/(^|\s)>>?(?!\|)/.test(txt) && !txt.includes('>')) continue;
      if (txt.includes('<') && !txt.includes('>')) continue;
      const dest = txt.replace(/^.*?>>?/, '').trim().split(/\s+/)[0] || '';
      if (this.isSensitivePath(dest)) return { category: 'write', risk: 'high' };
    }
    return null;
  }

  private isSensitivePath(p: string): boolean {
    const clean = p.replace(/^['"]|['"]$/g, '');
    if (SENSITIVE_PREFIXES.some(pre => clean.toLowerCase().startsWith(pre))) return true;
    if (clean.startsWith('~/') && SENSITIVE_DOTFILES.some(d => clean.slice(2).startsWith(d))) return true;
    return false;
  }

  // --- Regex fallback (original behaviour, unchanged) ---------------------------------------

  private analyzeRegex(trimmed: string): Classification {
    // Pipe to bash/sh detection
    if (this.CURL_PIPE_PATTERN.test(trimmed)) {
      return { category: 'network_exec', risk: 'high' };
    }

    // Package installs
    if (this.INSTALL_PATTERNS.some(p => p.test(trimmed))) {
      return { category: 'install', risk: 'medium' };
    }

    const tokens = this.tokenize(trimmed);
    const cmdBase = tokens[0] || '';
    const cmdWithSub = tokens.length > 1 ? `${cmdBase} ${tokens[1]}` : cmdBase;

    if (this.READ_ONLY_COMMANDS.has(cmdWithSub) || this.READ_ONLY_COMMANDS.has(cmdBase)) {
      return { category: 'read', risk: 'none' };
    }

    if (this.WRITE_COMMANDS.has(cmdWithSub) || this.WRITE_COMMANDS.has(cmdBase)) {
      const risk = this.assessWriteRisk(tokens);
      return { category: 'write', risk };
    }

    return { category: 'unknown', risk: 'unknown' };
  }

  private tokenize(command: string): string[] {
    // Basic tokenizer that splits by spaces but respects quotes
    const regex = /[^\s"']+|"([^"]*)"|'([^']*)'/g;
    const tokens: string[] = [];
    let match;
    while ((match = regex.exec(command)) !== null) {
      tokens.push(match[1] || match[2] || match[0]);
    }
    return tokens;
  }

  private assessWriteRisk(tokens: string[]): 'low' | 'medium' | 'high' {
    const cmd = tokens.join(' ');

    // Recursive+force delete: high risk when aimed at root, home, an absolute path,
    // a parent dir, or anything containing a glob; medium otherwise. Detect the flags
    // regardless of ordering or whether they are combined (e.g. -rf, -fr, -r -f).
    const isRecursiveForce =
      /\brm\b/.test(cmd) &&
      /-[a-z]*r[a-z]*/.test(cmd) &&
      /-[a-z]*f[a-z]*/.test(cmd);
    if (isRecursiveForce) {
      const dangerous = tokens.some(t =>
        t === '/' || t === '~' || t === '.' || t === '..' ||
        t.startsWith('/') || t.startsWith('~') ||
        t.includes('*') || t.includes('..')
      );
      return dangerous ? 'high' : 'medium';
    }

    return 'low';
  }
}

/** basename without pulling in path: `/usr/bin/curl` → `curl`, `./foo` → `foo`. */
function basename(s: string): string {
  const cleaned = s.replace(/^['"]|['"]$/g, '');
  const slash = cleaned.lastIndexOf('/');
  return slash >= 0 ? cleaned.slice(slash + 1) : cleaned;
}

import { stateDir } from '../utils/state.dir';
import { Logger } from '../utils';
import { SafetyPolicy, configuredSpend } from './policy.engine';
import { GovernorVetoError } from '../core/errors';
import { engineEvents } from '../engine/events';
import * as fsSync from 'fs';
import * as fs from 'fs/promises';
import * as path from 'path';
import { Mutex } from 'async-mutex';
import { SpendLedger, resolveSpendContext, type SpendCaps } from './spend.ledger';

export class BudgetVeto {
  /**
   * The machine-wide ledger, when the host configured one (`BIMAX_SPEND_LEDGER_PATH`), plus the
   * scope this engine charges to (`BIMAX_SPEND_SCOPE`, normally one Bimax Thread).
   *
   * WHY. The file this class writes lives under `stateDir('.breakglass')`, and `stateDir` honours
   * `BIMAX_STATE_DIR` — which the desktop sets PER Bimax Thread. So every Thread had its own
   * spend.json and its own full daily cap; measured 2026-09-19, four independent ledgers already
   * existed on the development machine. See src/governor/spend.ledger.ts for the measurement.
   *
   * The local counters below are kept either way: they are what the warning and the log line read,
   * and they still bound THIS process. The shared ledger is authoritative for the refusal.
   *
   * KNOWN BOUND, stated rather than hidden: reservations remain in-process, so two engines can each
   * pass a check and each start one call before either settles. The overshoot is therefore at most
   * one in-flight call per live engine — bounded by MAX_LIVE_ENGINES — and `recordSettled` always
   * books the real cost, so the total stays truthful and the next check refuses. Distributed
   * reservations would need a lease protocol; that is not worth it for a bounded single-call window.
   */
  private readonly shared: SpendLedger | null;
  private readonly scope: string | null;
  private currentDailySpend: number = 0;
  private reservedSpend: number = 0;
  // The day `currentDailySpend` belongs to. A long-running process (day-long autonomous loops)
  // crosses midnight, so the reset can't live only in the constructor — it's re-checked on every
  // spend/veto via rolloverIfNewDay(), otherwise yesterday's spend carries into today (tripping the
  // cap early) and gets persisted stamped with today's date.
  private spendDate: string = new Date().toISOString().split('T')[0];
  private readonly spendFilePath: string;
  private budgetMutex = new Mutex();
  // When the governor is bypassed (/governor off), the budget stops vetoing — it still TRACKS spend
  // so the running total stays accurate, but it never blocks a call. The adapter holds this instance
  // directly (container.setBudgetVeto), so without this flag disabling the governor left the daily
  // cap silently killing every LLM response ("Budget limit exceeded" with no output). The Governor
  // keeps this in sync with its mode.
  public enabled: boolean = true;
  /** Fraction of the daily cap at which the user is warned that a long run is about to be stopped. */
  private static readonly WARN_AT = 0.8;
  /** The day the approaching-cap warning was last shown, so it appears once rather than per call. */
  private warnedOn: string | null = null;

  constructor() {
    const { path: sharedPath, scope } = resolveSpendContext();
    this.shared = sharedPath ? new SpendLedger(sharedPath) : null;
    this.scope = scope;

    const creditsDir = path.join(stateDir('.breakglass'), 'credits');
    this.spendFilePath = path.join(creditsDir, 'spend.json');

    // Use sync fs here because constructor cannot be async easily
    if (!fsSync.existsSync(creditsDir)) {
      fsSync.mkdirSync(creditsDir, { recursive: true });
    }

    this.loadPersistentSpendSync();
  }

  private loadPersistentSpendSync() {
    try {
      if (fsSync.existsSync(this.spendFilePath)) {
        const data = JSON.parse(fsSync.readFileSync(this.spendFilePath, 'utf8'));

        // Reset budget if it's a new day
        const today = new Date().toISOString().split('T')[0];
        this.spendDate = today;
        if (data.date !== today) {
          this.currentDailySpend = 0;
          this.savePersistentSpendSync();
          Logger.info(`[Governor] New day detected. Budget reset to $0.00.`);
        } else {
          this.currentDailySpend = data.spend || 0;
          Logger.info(`[Governor] Loaded physical budget: $${this.currentDailySpend.toFixed(2)} / $${SafetyPolicy.maxDailySpendUsd.toFixed(2)}`);
        }
      } else {
        this.savePersistentSpendSync();
      }
    } catch (e: any) {
      Logger.error(`[Governor] Failed to load spend.json: ${e.message}`);
    }
  }

  private savePersistentSpendSync() {
    const data = {
      date: this.spendDate,
      spend: this.currentDailySpend
    };
    fsSync.writeFileSync(this.spendFilePath, JSON.stringify(data, null, 2), 'utf8');
  }

  private async savePersistentSpendAsync() {
    const data = {
      date: this.spendDate,
      spend: this.currentDailySpend
    };
    await fs.writeFile(this.spendFilePath, JSON.stringify(data, null, 2), 'utf8');
  }

  /**
   * Roll the daily counters over when the wall-clock day has advanced since the last spend was
   * recorded. Called inside the budget mutex at the top of every spend/veto path so a process that
   * outlives midnight resets exactly once, instead of carrying yesterday's total into today.
   */
  private rolloverIfNewDay() {
    const today = new Date().toISOString().split('T')[0];
    if (this.spendDate !== today) {
      this.currentDailySpend = 0;
      this.reservedSpend = 0;
      this.spendDate = today;
      Logger.info(`[Governor] New day detected mid-session. Budget reset to $0.00.`);
    }
  }

  /** The ceilings in force: the machine's daily cap, and this Thread's share of it when set. */
  private caps(): SpendCaps {
    const daily = SafetyPolicy.maxDailySpendUsd;
    // Each task's share: Settings (N6) first, then the desktop's per-Thread setting. 0 means no share.
    const configured = configuredSpend('spendTaskShareUsd');
    const share = configured !== undefined ? configured : parseFloat(process.env.BIMAX_SPEND_SCOPE_CAP || '');
    return { daily, perScope: Number.isFinite(share) && share > 0 ? share : undefined };
  }

  /**
   * Book a cost that has ALREADY been incurred, in the shared ledger as well as locally.
   *
   * Deliberately never conditional on the cap: a provider call that completed cost money whatever
   * the ledger says, and skipping it would make the machine total under-report — the one direction
   * that turns this from a safety rail into a lie.
   */
  private bookShared(actualCostUsd: number, model: string | null = null): void {
    if (!this.shared || !(actualCostUsd > 0)) return;
    try { this.shared.recordSettled(actualCostUsd, this.scope, model); } catch (e: any) {
      // A ledger that cannot be written must not fail the turn whose money is already spent. It is
      // logged rather than swallowed, because a silently unrecorded charge is how a cap drifts.
      Logger.error(`[Governor] Shared spend ledger write failed; machine total is now under-reported: ${e?.message || e}`);
    }
  }

  /** `model` is the model the charge was for, so the ledger can show cost by model (N6). */
  async recordSpend(actualCostUsd: number, estimatedCostUsd: number = 0, model: string | null = null): Promise<void> {
    await this.budgetMutex.runExclusive(async () => {
      this.rolloverIfNewDay();
      this.reservedSpend = Math.max(0, this.reservedSpend - estimatedCostUsd);
      this.currentDailySpend += actualCostUsd;
      this.bookShared(actualCostUsd, model);
      await this.savePersistentSpendAsync();
      Logger.info(`[Governor] Budget updated: $${this.currentDailySpend.toFixed(2)} / $${SafetyPolicy.maxDailySpendUsd.toFixed(2)}`);
      this.warnIfApproachingCap();
    });
  }

  /**
   * Tell the user BEFORE the cap stops them, once per day.
   *
   * The cap was previously silent until it fired: spend crossed only into a Logger.info line the
   * user never sees, and the first signal was a veto mid-task — observed killing a real run at
   * 15/16 completed steps, which reads as a crash rather than a budget decision. A warning at 80%
   * is the difference between raising the cap now and losing the work in progress.
   *
   * Caller holds the budget mutex. Never throws: a warning that breaks a turn would be worse than
   * the silence it replaces.
   */
  private warnIfApproachingCap(): void {
    if (!this.enabled) return;
    const cap = SafetyPolicy.maxDailySpendUsd;
    if (!(cap > 0) || this.warnedOn === this.spendDate) return;
    if (this.currentDailySpend < cap * BudgetVeto.WARN_AT) return;
    this.warnedOn = this.spendDate;
    const remaining = Math.max(0, cap - this.currentDailySpend);
    try {
      engineEvents.emit('status',
        `Daily budget ${Math.round((this.currentDailySpend / cap) * 100)}% used `
        + `($${this.currentDailySpend.toFixed(2)} of $${cap.toFixed(2)}, $${remaining.toFixed(2)} left). `
        + `Raise it with MAX_DAILY_SPEND or disable the cap with /governor off before starting long work.`);
    } catch { /* the warning is an observer — never let it break a turn */ }
  }

  /**
   * The shared ledger's refusal for this call, or null when it allows it (or is not configured).
   *
   * Consulted IN ADDITION to the local counters, never instead of them: the local total still
   * bounds this process, and the shared one bounds the machine. Whichever refuses first wins, and
   * its own message is used — a Thread that has used its share needs to hear that, not "daily
   * budget reached", which would send the user raising a cap that is not the one stopping them.
   */
  private sharedRefusal(estimatedCostUsd: number): string | null {
    if (!this.shared || !this.enabled) return null;
    try {
      const verdict = this.shared.wouldAllow(estimatedCostUsd, this.caps(), this.scope);
      return verdict.ok ? null : verdict.reason;
    } catch (e: any) {
      // Fail OPEN. A locked or unreadable ledger must not stop work the user is watching; the local
      // cap below still applies, so this degrades to the old per-process behaviour rather than to
      // no limit at all.
      Logger.error(`[Governor] Shared spend ledger unreadable, falling back to the local cap: ${e?.message || e}`);
      return null;
    }
  }

  async checkVeto(estimatedCostUsd: number): Promise<void> {
    await this.budgetMutex.runExclusive(async () => {
      this.rolloverIfNewDay();
      const refusal = this.sharedRefusal(estimatedCostUsd);
      if (refusal) {
        Logger.error(`[Governor: Veto] API call blocked by the machine-wide budget.`);
        throw new GovernorVetoError(refusal);
      }
      // Bypassed governor → reserve (to keep the running estimate honest) but never veto.
      if (this.enabled && this.currentDailySpend + this.reservedSpend + estimatedCostUsd > SafetyPolicy.maxDailySpendUsd) {
        Logger.error(`[Governor: Veto] API call blocked. Exceeds daily limit of $${SafetyPolicy.maxDailySpendUsd}`);
        throw new GovernorVetoError(`Daily budget of $${SafetyPolicy.maxDailySpendUsd.toFixed(2)} reached (spent $${this.currentDailySpend.toFixed(2)}). Disable the cap with /governor off, or raise it via MAX_DAILY_SPEND.`);
      }
      this.reservedSpend += estimatedCostUsd;
    });
  }

  async releaseReservation(estimatedCostUsd: number): Promise<void> {
    await this.budgetMutex.runExclusive(async () => {
      this.reservedSpend = Math.max(0, this.reservedSpend - estimatedCostUsd);
    });
  }

  async executeWithBudget<T>(estimatedCostUsd: number, action: () => Promise<{ actualCostUsd: number, result: T }>): Promise<T> {
    return await this.budgetMutex.runExclusive(async () => {
      this.rolloverIfNewDay();
      const refusal = this.sharedRefusal(estimatedCostUsd);
      if (refusal) {
        Logger.error(`[Governor: Veto] API call blocked by the machine-wide budget.`);
        throw new GovernorVetoError(refusal);
      }
      if (this.enabled && this.currentDailySpend + this.reservedSpend + estimatedCostUsd > SafetyPolicy.maxDailySpendUsd) {
        Logger.error(`[Governor: Veto] API call blocked. Exceeds daily limit of $${SafetyPolicy.maxDailySpendUsd}`);
        throw new GovernorVetoError(`Daily budget of $${SafetyPolicy.maxDailySpendUsd.toFixed(2)} reached (spent $${this.currentDailySpend.toFixed(2)}). Disable the cap with /governor off, or raise it via MAX_DAILY_SPEND.`);
      }

      const { actualCostUsd, result } = await action();
      this.currentDailySpend += actualCostUsd;
      this.bookShared(actualCostUsd);
      await this.savePersistentSpendAsync();
      Logger.info(`[Governor] Budget updated: $${this.currentDailySpend.toFixed(2)} / $${SafetyPolicy.maxDailySpendUsd.toFixed(2)}`);
      this.warnIfApproachingCap();
      return result;
    });
  }
}

import { Logger } from '../utils';
import { SafetyPolicy } from './policy.engine';
import { GovernorVetoError } from '../core/errors';
import * as path from 'path';
import * as fs from 'fs/promises';

/**
 * Whether a canonical path falls under a forbidden path: `entry` must match whole path segments. It was a plain substring
 * test, so '/var' blocked ~/Documents/various and '/system' blocked ~/code/system-design — every edit in such a folder was
 * refused as "Forbidden path access" (found 2026-09-21 while testing F3). A folder literally named `var` or `.ssh` is
 * still refused, wherever it is, as before; case is ignored, as before.
 */
export function underForbiddenPath(normalized: string, entry: string): boolean {
  const target = normalized.toLowerCase().replace(/\/+$/, '');
  const forbidden = entry.toLowerCase().replace(/\/+$/, '');
  if (!forbidden) return false;
  return target === forbidden || target.endsWith(forbidden) || target.includes(`${forbidden}/`);
}

export class FileSystemVeto {
  async checkVeto(targetPath: string): Promise<void> {
    // Resolve the nearest existing ancestor, not just the immediate parent. A symlink
    // followed by two nonexistent directories must not turn into an unresolved allowed path.
    const canonical = async (input: string): Promise<string> => {
      let current = path.resolve(input);
      const missing: string[] = [];
      for (;;) {
        try { return path.join(await fs.realpath(current), ...missing.reverse()); }
        catch (error: any) {
          if (error?.code !== 'ENOENT') throw error;
          const entry = await fs.lstat(current).catch(() => null);
          if (entry?.isSymbolicLink()) throw new GovernorVetoError('Unresolvable symbolic link in target path.');
          const parent = path.dirname(current);
          if (parent === current) throw error;
          missing.push(path.basename(current));
          current = parent;
        }
      }
    };
    const realPath = await canonical(targetPath);
    // Preserve case: case-sensitive volumes must not admit a differently-cased sibling.
    const normalized = path.normalize(realPath);
    const canonicalWorkspace = await canonical(SafetyPolicy.allowedWorkspace);

    // 1. Must be inside workspace (separator-aware to prevent sibling-prefix escapes,
    //    e.g. /home/user/workspace-evil must NOT pass for workspace /home/user/workspace)
    const withSep = canonicalWorkspace.endsWith(path.sep) ? canonicalWorkspace : canonicalWorkspace + path.sep;
    if (normalized !== canonicalWorkspace && !normalized.startsWith(withSep)) {
      Logger.error(`[Governor: Veto] File operation blocked. Target is outside the allowed workspace: ${realPath}`);
      throw new GovernorVetoError('Path outside workspace boundary.');
    }

    // 2. Cannot touch forbidden system paths
    for (const forbidden of SafetyPolicy.forbiddenPaths) {
      if (underForbiddenPath(normalized, forbidden)) {
        Logger.error(`[Governor: Veto] File operation blocked. Target contains forbidden path: ${forbidden}`);
        throw new GovernorVetoError('Forbidden path access.');
      }
    }

    // 3. Sensitive filename pattern detection (e.g. id_rsa)
    for (const regex of SafetyPolicy.forbiddenRegex) {
      if (regex.test(normalized)) {
        Logger.error(`[Governor: Veto] File operation blocked. Target matches forbidden filename pattern: ${regex}`);
        throw new GovernorVetoError('Forbidden sensitive filename.');
      }
    }

    // 4. Cannot touch forbidden extensions
    const ext = path.extname(normalized);
    if (SafetyPolicy.forbiddenExtensions.includes(ext)) {
      Logger.error(`[Governor: Veto] File operation blocked. Extension is forbidden: ${ext}`);
      throw new GovernorVetoError('Forbidden file extension.');
    }
  }
}

import { BudgetVeto } from './budget.veto';
import { FileSystemVeto } from './fs.veto';
import { Logger } from '../utils';
import { GovernorVetoError } from '../core/errors';
import { IGovernor, IEventBus } from '../core/interfaces';
import { GlobalPrompter } from '../engine/prompter';
import { YoloClassifier } from '../security/yolo.classifier';
import { engineEvents } from '../engine/events';
import { BashStaticAnalyzer } from './bash.analyzer';
import * as fsp from 'fs/promises';
import { isApprovalReadOnlyShellCommand } from '../tools/shell.readonly';
import { enforceThreadScope } from '../tools/thread.scope';
import { approvalCard, deletesOutsideBin, planFileChange } from '../tools/thread.changes';
import { recordBeforeChange } from '../tools/thread.journal';
import { grantFor, taskGrants } from './task.grants';
import { protectedPaths, protectedRefusal, protectedTouchedBy } from '../tools/thread.rules';
import { taintRestriction } from '../mind/taint';

/** Why a thread refuses a delete it cannot send to the Bin, and how to delete so the user can undo it. */
/** The approval-card choice that allows a described change for the rest of the task (N13). */
export const TASK_GRANT_OPTION = 'Allow for this task';
const THREAD_DELETE_GUIDANCE = 'In a Bimax thread, deletes go to the Bin so the user can undo them. Delete with a plain `rm <path>…` (optionally after `cd <folder> &&`; same-folder wildcards are fine) or DeleteTool — not find -delete, a pipeline or a chain of commands. Nothing was deleted.';

/**
 * `unattended` (backlog FL5, night shift): nobody is there to answer, so what would be asked is decided instead.
 * Work inside the workspace goes ahead without a prompt, but every floor still holds — workspace containment, the
 * sensitive-target refusals, the spend cap (unlike `bypass`, which lifts it) and the taint block, which turns into a
 * refusal because nobody can knowingly allow it. Computer control is refused outright.
 */
export type SessionPermissionMode = 'interactive' | 'plan' | 'auto' | 'strict' | 'bypass' | 'unattended';

export interface ToolPermissionRule {
  tool: string;
  pattern?: string;
  effect: 'allow' | 'deny';
  persistent: boolean;
  /** Exact built-in/MCP tool identity; absent legacy allows do not grant authority. */
  subject?: string;
}

export class Governor implements IGovernor {
  public budget: BudgetVeto;
  public fs: FileSystemVeto;
  private _mode: SessionPermissionMode = 'interactive';
  private bashAnalyzer = new BashStaticAnalyzer();
  private readonly analyzerWarmup: Promise<void>;

  // mode is assigned directly in many places (index.ts, /governor, /plan, …). Route those writes
  // through a setter so disabling the governor (bypass) ALSO lifts the budget veto, which the LLM
  // adapter holds directly — otherwise "/governor off" left the daily cap blocking every response.
  public get mode(): SessionPermissionMode { return this._mode; }
  public set mode(m: SessionPermissionMode) {
    this._mode = m;
    if (this.budget) this.budget.enabled = m !== 'bypass';
  }
  public rules: ToolPermissionRule[] = [];
  constructor(private eventBus: IEventBus, private yolo?: YoloClassifier) {
    this.budget = new BudgetVeto();
    this.fs = new FileSystemVeto();
    // Pre-load the grammar in the long-lived application. Unit tests construct many short-lived
    // governors; their fire-and-forget WASM loads can outlive Jest environments, so those tests use
    // the deterministic regex path unless they explicitly await BashStaticAnalyzer.warmUp().
    this.analyzerWarmup = process.env.NODE_ENV === 'test'
      ? Promise.resolve()
      : this.bashAnalyzer.warmUp();
    Logger.info('[Governor] Initialized Multi-Layer Permission Engine.');
  }

  /** Lets lifecycle-aware hosts await the optional AST safety-parser warm-up. */
  public async ready(): Promise<void> { await this.analyzerWarmup; }

  public addRule(rule: ToolPermissionRule) {
    this.rules.push(rule);
  }

  public async approveTaskExecution(taskType: string, payload: any): Promise<void> {
    // Retired capability: refuse even stale plugins, bypass mode, and saved allow rules before any shortcut.
    if (taskType === 'COMPUTER_CONTROL') {
      throw new GovernorVetoError('Computer Use has been removed from Bimax.');
    }

    // NetworkConsent owns per-host caching; a first host requires actual user authority.
    if (taskType === 'NETWORK_ACCESS') {
      if (this.mode === 'bypass') return;
      if (this.mode === 'unattended') throw new GovernorVetoError('No standing consent for this host; approve it interactively first.');
      let host: string;
      try { host = new URL(String(payload.target)).host; }
      catch { throw new GovernorVetoError('Invalid network destination.'); }
      if (!host || host !== payload.host) throw new GovernorVetoError('Network consent host mismatch.');
      const answer = await GlobalPrompter.ask(`Allow ${String(payload.tool)} to reach ${host}? (${String(payload.purpose || 'network access')})`, ['Yes', 'No']);
      if (answer !== 'Yes') throw new GovernorVetoError('Network access declined.');
      return;
    }

    // Taint capability narrowing (v2 D3) — computed BEFORE the rule shortcut so a persistent
    // "Always Allow" created in a clean session can never waive it: once untrusted content
    // (file/web/MCP output) is in the conversation, network-capable commands are hard-blocked in
    // auto mode and always face the human elsewhere.
    const taintCut: { action: 'block' | 'ask'; reason: string } | null =
      taskType === 'OS_COMMAND' ? taintRestriction(payload.command || '', this.mode) : null;
    if (taintCut?.action === 'block') {
      throw new GovernorVetoError(`Blocked: ${taintCut.reason}`);
    }

    // Folder-bound Bimax threads (BIMAX_THREAD_ROOT) cannot inherit bypass or persistent blanket grants.
    // Creating a new file inside the thread's folder and proven read-only commands are routine; a
    // replacement, a delete, a shell mutation or any other destructive action needs one fresh answer for
    // that exact action, which the app shows in the thread's approval popup.
    if (process.env.BIMAX_THREAD_ROOT && taskType !== 'API_CALL') {
      await enforceThreadScope(payload, payload.context?.cwd || process.cwd());
      // The workspace floor (forbidden paths, sensitive names and extensions) still applies inside the
      // thread's own folder — thread engines run with WORKSPACE_ROOT set to that folder.
      if ((taskType === 'FILE_WRITE' || taskType === 'FILE_DELETE') && typeof payload.targetPath === 'string') {
        await this.fs.checkVeto(payload.targetPath);
      }
      if (this.mode === 'plan' && payload.isDestructive !== false) throw new GovernorVetoError('Plan mode: approve the plan before changing files.');
      const threadCwd = payload.context?.cwd || process.cwd();
      // A delete the thread cannot send to the Bin would be permanent and impossible to undo: refuse it before
      // asking, and say how to delete so it can be undone.
      if (taskType === 'OS_COMMAND' && deletesOutsideBin(String(payload.command || ''), threadCwd)) {
        throw new GovernorVetoError(THREAD_DELETE_GUIDANCE);
      }
      let routine = payload.isDestructive === false;
      if (taskType === 'OS_COMMAND') routine = isApprovalReadOnlyShellCommand(payload.command) && !taintCut;
      if (taskType === 'FILE_WRITE' && typeof payload.targetPath === 'string') {
        try { await fsp.lstat(payload.targetPath); routine = false; }
        catch (error: any) { if (error.code === 'ENOENT') routine = true; else throw error; }
      }
      // Say what will happen in words, list every affected item, and say whether it can be undone. The raw
      // command is still on the card, but it is no longer the whole question.
      const change = planFileChange(taskType, payload, threadCwd);
      // The user's folder rules protect some items outright: refused before any card, so no approval can override them.
      const guarded = protectedTouchedBy(change, taskType === 'OS_COMMAND' ? String(payload.command || '') : '', protectedPaths(), process.env.BIMAX_THREAD_ROOT);
      if (guarded) throw new GovernorVetoError(protectedRefusal(guarded));
      if (!routine) {
        // N13: every floor above has already run. A change the user allowed for this task — the same file, the same
        // command, or an undoable change inside the folder — is not asked about again; anything else is.
        const grant = grantFor(taskType, change, payload, process.env.BIMAX_THREAD_ROOT, threadCwd);
        const granted = grant && !taintCut ? taskGrants.use(grant.key) : null;
        if (granted) {
          engineEvents.emit('status', `Allowed for this task: ${granted.label}`);
        } else {
          const card = approvalCard(change, taskType, payload);
          const options = grant && !taintCut ? ['Allow', TASK_GRANT_OPTION, 'Deny'] : ['Allow', 'Deny'];
          const body = grant && !taintCut ? `${card.body}\n\n“${TASK_GRANT_OPTION}” also allows ${grant.label} until this task ends, without asking again.` : card.body;
          const answer = await GlobalPrompter.ask(taintCut ? `TAINTED CONTEXT — ${taintCut.reason}\n${card.question}` : card.question, options, { body });
          if (answer === TASK_GRANT_OPTION && grant && !taintCut) {
            taskGrants.add(grant);
            engineEvents.emit('message', { id: `grant-${Date.now()}`, role: 'system', level: 'info', content: `For the rest of this task Bimax will not ask again about ${grant.label}. Run /grants clear to be asked again.`, timestamp: new Date() });
          } else if (answer !== 'Allow') {
            throw new GovernorVetoError('Action declined. No permission was granted.');
          }
        }
      }
      // Recorded once the change is allowed (or routine) and before it runs, so "↶ Undo" can reverse it.
      if (change) {
        await recordBeforeChange(change, String(payload.tool || taskType)).catch((error: any) => {
          Logger.warn(`[Governor] Could not record undo for "${change.title}": ${error?.message ?? error}`);
        });
      }
      return;
    }

    // Workspace containment is a hard floor, including persistent allow rules and bypass mode.
    if (taskType === 'FILE_WRITE' || taskType === 'FILE_DELETE') {
      await this.fs.checkVeto(payload.targetPath);
    }

    if (this.mode === 'bypass' && !taintCut) {
      Logger.info(`[Governor] ⚠️ Bypassed completely for task: ${taskType}`);
      engineEvents.emit('status', `Approved (Bypassed): ${taskType}`);
      return;
    }

    // Layer 0: Plan Mode — research only. Block every mutating action so the agent
    // can read, search, and reason but cannot touch the workspace until the plan
    // is approved and the session is switched out of 'plan' mode.
    if (this.mode === 'plan') {
      const blocked =
        taskType === 'FILE_WRITE' ||
        taskType === 'FILE_DELETE' ||
        (taskType === 'OS_COMMAND' && !isApprovalReadOnlyShellCommand(payload.command || '')) ||
        (payload.isDestructive !== false && taskType === 'TOOL_EXECUTION');

      if (blocked) {
        const label = taskType === 'OS_COMMAND'
          ? `run "${String(payload.command || '').slice(0, 60)}"`
          : taskType === 'FILE_WRITE' ? `write ${payload.targetPath || payload.path || 'a file'}`
          : `delete ${payload.targetPath || payload.path || 'a file'}`;
        throw new GovernorVetoError(
          `Plan mode is active — cannot ${label}. Present your plan to the user; they can approve and exit plan mode (/plan off) to let you execute.`
        );
      }
      // Read-only work is allowed through; fall past the destructive prompt below.
      engineEvents.emit('status', `Approved (Plan/read-only): ${taskType}`);
      return;
    }

    // Unattended (a night shift): a tainted network command was already refused above — taintRestriction blocks
    // rather than asks when nobody is watching — so what reaches here is decided without a prompt.
    if (this.mode === 'unattended') {
      engineEvents.emit('status', `Approved (unattended): ${taskType}`);
      return;
    }

    // Layer 1: Persistent Rules Check
    const subject = typeof payload.tool === 'string' && payload.tool ? payload.tool : undefined;
    const matchingRule = this.rules.find(r => r.tool === taskType && r.effect === 'deny') ?? this.rules.find(r => r.tool === taskType && (
      taskType === 'OS_COMMAND'
        ? r.pattern !== undefined && r.pattern === payload.command
        : subject !== undefined && r.subject === subject
    ));
    if (matchingRule) {
      if (matchingRule.effect === 'deny') {
        throw new GovernorVetoError(`Rule explicitly denied task: ${taskType}`);
      }
      if (matchingRule.effect === 'allow' && !taintCut) {
        engineEvents.emit('status', `Approved (Rule): ${taskType}`);
        return;
      }
    }

    try {

      if (taskType === 'API_CALL') {
        await this.budget.checkVeto(payload.estimatedCost);
      }

      // Layer 2: Static Analysis for Bash Commands
      if (taskType === 'OS_COMMAND') {
        const analysis = this.bashAnalyzer.analyze(payload.command);

        // Taint-narrowed commands (computed above) keep none of the fast paths below —
        // they fall through to the human prompt with the taint source named. Read-only
        // auto-approve is unaffected for untainted-restricted commands (ls can't exfil).
        if (analysis.category === 'read' && analysis.risk === 'none' && isApprovalReadOnlyShellCommand(payload.command) && this.mode !== 'strict' && !taintCut) {
          // Auto-approve read-only safe commands
          Logger.info(`[Governor] Auto-approved safe read command: ${payload.command}`);
          engineEvents.emit('status', `Approved (Static Analysis): ${taskType}`);
          return;
        }

        // Fallback: Layer 3 ML Classifier (only if auto mode or interactive).
        // Never lets a tainted network command through — that's the human's call.
        if (this.yolo && this.mode === 'auto' && !taintCut) {
          const isSafe = await this.yolo.evaluateAction(payload.command, payload.context);
          if (isSafe) {
             engineEvents.emit('status', `Approved (ML Classifier): ${taskType}`);
             return;
          }
        }
      }
    } catch (e: any) {
      if (e instanceof GovernorVetoError) {
        Logger.error(`[Governor] 🚨 SEVERE VIOLATION DETECTED. BROADCASTING EMERGENCY HALT. 🚨`);
        this.eventBus.emit('EMERGENCY_HALT', { reason: e.message });
      }
      throw e;
    }

    // Layer 4: Interactive Fallback
    // Honor the fail-closed destructive declaration of generic tools as well as file/shell tasks.
    const isDestructiveTask = payload.isDestructive !== false && (
      taskType === 'FILE_WRITE' || taskType === 'OS_COMMAND' || taskType === 'FILE_DELETE'
      || taskType === 'TOOL_EXECUTION'
    );
    const shouldAsk = isDestructiveTask || this.mode === 'strict' || !!taintCut;

    if (shouldAsk) {
      const label = taskType === 'FILE_WRITE' ? `Write ${payload.targetPath || payload.path || 'file'}`
        : taskType === 'OS_COMMAND' ? `Run: ${(payload.command || '').slice(0, 60)}`
        : taskType === 'TOOL_EXECUTION' && payload.tool ? `Run ${payload.tool}`
        : `${taskType}`;

      // A taint-narrowed command asks with the taint source in view — the human decides knowingly.
      const question = taintCut ? `⚠ TAINTED CONTEXT — ${taintCut.reason}\nAllow anyway? ${label}` : `Allow? ${label}`;
      const always = taskType === 'OS_COMMAND' ? 'Always Allow This Command' : 'Always Allow This Tool';
      const remember = !taintCut && (taskType === 'OS_COMMAND' || subject !== undefined);
      const options = remember ? ['Yes', 'No', always] : ['Yes', 'No'];
      const answer = await GlobalPrompter.ask(question, options);

      if (!options.includes(answer) || answer === 'No') {
        throw new GovernorVetoError("User explicitly denied this action.");
      }

      if (answer === always && remember) {
        this.addRule({ tool: taskType, effect: 'allow', persistent: true, ...(taskType === 'OS_COMMAND' ? { pattern: String(payload.command) } : { subject }) });
        Logger.info(`[Governor] Added persistent allow rule for ${taskType}`);
      }


    }

    Logger.info(`[Governor] ✅ Veto cleared. Task approved.`);
    engineEvents.emit('status', `Approved: ${taskType}`);
  }
}

import { stateDir } from '../utils/state.dir';
import * as fs from 'fs';
import * as path from 'path';
import { Logger } from '../utils';

/** Explicit override from .breakglass/policy.json, which outranks the environment. */
let maxDailySpendOverrideUsd: number | undefined;

export const SafetyPolicy = {
  /**
   * Read LAZILY, never snapshotted at import.
   *
   * `parseFloat(process.env.MAX_DAILY_SPEND)` as an initializer runs when this module is first
   * imported — and imports are hoisted, so it ran BEFORE `loadGlobalEnv()` at index.ts:20 had read
   * ~/.breakglass/.env. The variable was therefore always undefined and the cap always $5.00, which
   * made the veto's own advice ("raise it via MAX_DAILY_SPEND") impossible to follow through the
   * documented file. Measured 2026-08-18: MAX_DAILY_SPEND=1000000 in .env, engine started after the
   * write, and the governor still loaded "$5.07 / $5.00" and vetoed.
   *
   * Same hazard provider.ts:21 already guards against by name. A getter costs one parse per read
   * and cannot be defeated by import order.
   */
  get maxDailySpendUsd(): number {
    if (maxDailySpendOverrideUsd !== undefined) return maxDailySpendOverrideUsd;
    // Settings (N6) before the environment: it is the value the user can see and change.
    const configured = configuredSpend('spendDailyCapUsd');
    if (configured !== undefined) return configured;
    const parsed = parseFloat(process.env.MAX_DAILY_SPEND || '');
    return Number.isFinite(parsed) && parsed >= 0 ? parsed : 5.00;
  },
  /** policy.json still overrides the environment; the setter keeps that path working. */
  set maxDailySpendUsd(value: number) {
    maxDailySpendOverrideUsd = value;
  },
  allowedWorkspace: process.env.WORKSPACE_ROOT || process.cwd(),
  forbiddenExtensions: ['.env', '.pem', '.key', '.p12'],
  forbiddenPaths: ['/etc', '/system', '/var', '/root', '/.ssh', '/proc'],
  // Path-based patterns — only match specific filename patterns, never broad words like "password"
  // or "secret" which would block legitimate code files (e.g. password_reset.ts, secret_key.ts).
  // Extension-based blocks (.env, .pem, .key) are already handled by forbiddenExtensions above.
  forbiddenRegex: [/id_rsa/i]
};

const POLICY_FILE = path.join(stateDir('.breakglass'), 'policy.json');

/** A spending limit set in Settings (N6), or undefined when none is. Lazy: config imports much of the engine. */
export function configuredSpend(key: 'spendDailyCapUsd' | 'spendTaskShareUsd'): number | undefined {
  try {
    const value = (require('../engine/config') as typeof import('../engine/config')).getConfig()[key];
    return typeof value === 'number' && Number.isFinite(value) && value >= 0 ? value : undefined;
  } catch { return undefined; }
}

let policyWatcher: fs.FSWatcher | null = null;

export function initPolicyEngine() {
  if (fs.existsSync(POLICY_FILE)) {
    loadPolicy();
  }

  // Watch for runtime changes (GOV-004). Watch the .breakglass DIRECTORY, not cwd: fs.watch on a
  // directory is non-recursive, so watching cwd never reported changes to the nested
  // .breakglass/policy.json. Directory watches emit the bare basename ("policy.json").
  try {
    const policyDir = path.dirname(POLICY_FILE);
    if (fs.existsSync(policyDir)) {
      policyWatcher = fs.watch(policyDir, (_eventType, filename) => {
        if (filename === 'policy.json') {
          setTimeout(loadPolicy, 100); // small debounce — editors write in bursts
        }
      });
      // Some restricted/container filesystems create the watcher successfully and then report an
      // asynchronous EMFILE/EPERM error. A surrounding try/catch cannot catch EventEmitter errors;
      // without this listener the error becomes an uncaught exception and can crash startup.
      policyWatcher.on('error', (e: NodeJS.ErrnoException) => {
        Logger.warn(`[PolicyEngine] Hot reload disabled: ${e.message}`);
        policyWatcher?.close();
        policyWatcher = null;
      });
      // Don't let the watcher keep the process alive
      policyWatcher.unref();
    }
  } catch (e) {
    // Ignore watch errors if platform doesn't support it
  }
}

export function destroyPolicyEngine() {
  if (policyWatcher) {
    policyWatcher.close();
    policyWatcher = null;
  }
}

function loadPolicy() {
  try {
    if (!fs.existsSync(POLICY_FILE)) return;
    const data = fs.readFileSync(POLICY_FILE, 'utf-8');
    const parsed = JSON.parse(data);

    if (parsed.maxDailySpendUsd !== undefined) SafetyPolicy.maxDailySpendUsd = parsed.maxDailySpendUsd;
    if (parsed.allowedWorkspace !== undefined) SafetyPolicy.allowedWorkspace = parsed.allowedWorkspace;
    if (parsed.forbiddenExtensions) SafetyPolicy.forbiddenExtensions = parsed.forbiddenExtensions;
    if (parsed.forbiddenPaths) SafetyPolicy.forbiddenPaths = parsed.forbiddenPaths;

    if (parsed.forbiddenRegex) {
      SafetyPolicy.forbiddenRegex = parsed.forbiddenRegex.map((r: string) => new RegExp(r, 'i'));
    }

    Logger.info(`[PolicyEngine] Dynamically reloaded SafetyPolicy from disk.`);
  } catch (e: any) {
    Logger.warn(`[PolicyEngine] Failed to reload dynamic policy: ${e.message}`);
  }
}

// Auto-init in the long-lived application. Jest evaluates this module in many isolated runtimes;
// one watcher per test file can exhaust the host descriptor limit before teardown.
if (process.env.NODE_ENV !== 'test') initPolicyEngine();

import * as crypto from 'crypto';
import * as fs from 'fs';
import * as path from 'path';

/**
 * One money ledger for the machine, and a ceiling per Bimax Thread (backlog F5).
 *
 * THE DEFECT THIS CLOSES. `BudgetVeto` keeps the daily total in
 * `<stateDir('.breakglass')>/credits/spend.json`, and `stateDir` honours `BIMAX_STATE_DIR` — which
 * the desktop sets per Bimax Thread, to a folder-hashed directory under app data
 * (`app/src/main/thread.undo.ts:threadStateRoot`). So every Thread got its own private spend file
 * and its own private $5/day. MEASURED on this machine 2026-09-19: four independent ledgers
 * already exist — two under `thread-state/`, one at `~/.breakglass`, one in the repo — each
 * enforcing `SafetyPolicy.maxDailySpendUsd` on its own. The effective ceiling is therefore
 * $5 × (folders ever opened as a Thread), and it grows by $5 every time someone ⌘2s somewhere new.
 *
 * This is the same shape as the sub-agent worker cap (docs/product-reset/57, WP-1): a per-MACHINE
 * constant applied per-Thread. The difference is that this one spends real money.
 *
 * WHY A NEW LEDGER RATHER THAN A SHARED PATH. Pointing every engine at one `spend.json` would have
 * been a one-line fix and a lost-update race: `BudgetVeto`'s mutex is an in-process `async-mutex`,
 * and each Bimax Thread is a separate OS process. Two engines would each read $2, each add $1, and
 * each write $3 — with $4 actually spent. Money needs cross-process atomicity, so this follows the
 * pattern already proven in `src/core/subagent.capacity.ts`: an O_EXCL lock file, a read-modify-
 * write inside it, and an atomic rename.
 *
 * TWO CEILINGS, BOTH ENFORCED. The machine total is what protects the bill. The per-Thread ceiling
 * is what stops ONE unattended folder task eating the whole day before the others start — the
 * actual ask in F5. A charge is refused when either would be exceeded, and the refusal says which.
 */

export const SPEND_LEDGER_ENV = 'BIMAX_SPEND_LEDGER_PATH';
/** Per-Bimax-Thread ceiling, as a fraction of the machine's daily cap. Absent → no per-Thread limit. */
export const SPEND_SCOPE_ENV = 'BIMAX_SPEND_SCOPE';

const LOCK_STALE_MS = 5_000;
const LOCK_ATTEMPTS = 50;

export interface SpendLedgerFile {
  version: 1;
  /** ISO date (UTC) the totals belong to. A new day resets everything. */
  date: string;
  /** Machine-wide total for `date`. */
  total: number;
  /** Per-scope totals for `date`; a scope is normally one Bimax Thread. */
  scopes: Record<string, number>;
  /** Per-model totals for `date` (N6). Absent in ledgers written before it. */
  models?: Record<string, number>;
  /** Earlier days, newest first, at most HISTORY_DAYS (N6): a day's totals are kept when it rolls over, not lost. */
  history?: SpendDay[];
}

/** One finished day's spend. */
export interface SpendDay { date: string; total: number; scopes: Record<string, number>; models: Record<string, number> }

/** How many finished days the ledger keeps. */
export const HISTORY_DAYS = 30;

export interface SpendCaps {
  /** The machine's daily ceiling, in USD. `0` or less means unlimited. */
  daily: number;
  /** One scope's daily ceiling, in USD. Absent/0 means the scope is bounded only by `daily`. */
  perScope?: number;
}

export interface SpendState {
  date: string;
  total: number;
  scope: string | null;
  scopeTotal: number;
}

export type ChargeRefusal = { ok: false; reason: string; which: 'machine' | 'scope'; state: SpendState };
export type ChargeAccepted = { ok: true; state: SpendState };
export type ChargeResult = ChargeAccepted | ChargeRefusal;

export class SpendLedgerError extends Error {}

function today(now: number): string {
  return new Date(now).toISOString().slice(0, 10);
}

function wait(ms: number): void {
  try { Atomics.wait(new Int32Array(new SharedArrayBuffer(4)), 0, 0, ms); } catch { /* retry */ }
}

function fresh(date: string): SpendLedgerFile {
  return { version: 1, date, total: 0, scopes: {} };
}

/**
 * Where the shared ledger lives, and which scope this process charges to.
 *
 * Both come from the environment because the desktop is the only thing that can know them: it owns
 * userData and it is the one spawning a Thread's engine. Absent, the caller keeps whatever
 * behaviour it had — this must never make a CLI or headless run refuse to spend.
 */
export function resolveSpendContext(env: NodeJS.ProcessEnv = process.env): { path: string | null; scope: string | null } {
  const p = (env[SPEND_LEDGER_ENV] || '').trim();
  const s = (env[SPEND_SCOPE_ENV] || '').trim();
  return { path: p || null, scope: s || null };
}

export class SpendLedger {
  constructor(
    readonly filePath: string,
    private readonly now: () => number = Date.now,
  ) {}

  private lockPath(): string { return `${this.filePath}.lock`; }

  /**
   * Read-modify-write under an exclusive lock. Mirrors SubAgentCapacityCoordinator.withLock, with
   * one deliberate difference: a corrupt ledger here does NOT throw. Refusing to spend because a
   * JSON file went bad would brick every task on the machine; losing today's running total is the
   * cheaper failure, and it is loud in the returned state rather than silent.
   */
  private withLock<T>(fn: (file: SpendLedgerFile, now: number) => T): T {
    fs.mkdirSync(path.dirname(this.filePath), { recursive: true });
    const lock = this.lockPath();
    let fd: number | null = null;
    for (let attempt = 0; attempt < LOCK_ATTEMPTS; attempt++) {
      try { fd = fs.openSync(lock, 'wx', 0o600); break; } catch (error: any) {
        if (error?.code !== 'EEXIST') throw new SpendLedgerError(`Spend ledger unavailable: ${error?.message || error}`);
        try {
          if (this.now() - fs.statSync(lock).mtimeMs > LOCK_STALE_MS) fs.unlinkSync(lock);
        } catch { /* another process released it */ }
        wait(5);
      }
    }
    if (fd === null) throw new SpendLedgerError('Spend ledger is busy.');

    try {
      const now = this.now();
      const date = today(now);
      let file = fresh(date);
      try {
        const parsed = JSON.parse(fs.readFileSync(this.filePath, 'utf8'));
        if (parsed?.version === 1 && typeof parsed.total === 'number' && typeof parsed.date === 'string') {
          const map = (v: unknown): Record<string, number> => (v && typeof v === 'object' ? v as Record<string, number> : {});
          file = {
            version: 1, date: parsed.date, total: parsed.total, scopes: map(parsed.scopes), models: map(parsed.models),
            history: Array.isArray(parsed.history) ? parsed.history.filter((d: any) => d && typeof d.date === 'string' && typeof d.total === 'number')
              .map((d: any) => ({ date: d.date, total: d.total, scopes: map(d.scopes), models: map(d.models) })) : [],
          };
        }
      } catch { /* absent or corrupt → start today at zero */ }

      // Midnight rollover happens here, inside the lock, so a process that outlives the day resets
      // exactly once no matter how many engines are running. The day that ended goes to the history (N6).
      if (file.date !== date) {
        const ended: SpendDay = { date: file.date, total: file.total, scopes: file.scopes, models: file.models ?? {} };
        const history = file.total > 0 ? [ended, ...(file.history ?? [])] : (file.history ?? []);
        file = { ...fresh(date), history: history.slice(0, HISTORY_DAYS) };
      }

      const result = fn(file, now);
      const tmp = `${this.filePath}.tmp-${process.pid}-${crypto.randomBytes(4).toString('hex')}`;
      try {
        fs.writeFileSync(tmp, JSON.stringify(file, null, 2), { encoding: 'utf8', mode: 0o600 });
        fs.renameSync(tmp, this.filePath);
      } finally {
        try { fs.rmSync(tmp, { force: true }); } catch { /* best-effort */ }
      }
      return result;
    } finally {
      try { if (fd !== null) fs.closeSync(fd); } catch { /* best-effort */ }
      try { fs.unlinkSync(lock); } catch { /* best-effort */ }
    }
  }

  /** Today's totals, without charging anything. */
  read(scope: string | null = null): SpendState {
    return this.withLock((file) => ({
      date: file.date,
      total: file.total,
      scope,
      scopeTotal: scope ? (file.scopes[scope] ?? 0) : 0,
    }));
  }

  /**
   * Would this charge be allowed? Pure with respect to the ledger — it takes the lock to read a
   * consistent snapshot but writes nothing, so a check is never a charge.
   */
  wouldAllow(amountUsd: number, caps: SpendCaps, scope: string | null = null): ChargeResult {
    return this.decide(this.read(scope), amountUsd, caps, scope);
  }

  private decide(state: SpendState, amountUsd: number, caps: SpendCaps, scope: string | null): ChargeResult {
    const amount = Number.isFinite(amountUsd) && amountUsd > 0 ? amountUsd : 0;
    // The machine ceiling is checked FIRST: it is the one that protects the bill, and naming it in
    // the refusal is more useful than naming a scope the user may not even be looking at.
    if (caps.daily > 0 && state.total + amount > caps.daily) {
      return {
        ok: false, which: 'machine', state,
        reason: `Daily budget of $${caps.daily.toFixed(2)} reached for this Mac (spent $${state.total.toFixed(2)} across every Bimax Thread today). Raise it with MAX_DAILY_SPEND, or disable the cap with /governor off.`,
      };
    }
    if (scope && caps.perScope && caps.perScope > 0 && state.scopeTotal + amount > caps.perScope) {
      return {
        ok: false, which: 'scope', state,
        reason: `This task has used its own $${caps.perScope.toFixed(2)} share (spent $${state.scopeTotal.toFixed(2)}). The Mac's daily budget still has $${Math.max(0, caps.daily - state.total).toFixed(2)} left for other tasks.`,
      };
    }
    return { ok: true, state };
  }

  /**
   * Charge, atomically, if both ceilings allow it. One lock covers the check and the write, so two
   * engines cannot both pass a check and then both spend.
   */
  charge(amountUsd: number, caps: SpendCaps, scope: string | null = null): ChargeResult {
    return this.withLock((file) => {
      const state: SpendState = {
        date: file.date, total: file.total, scope,
        scopeTotal: scope ? (file.scopes[scope] ?? 0) : 0,
      };
      const verdict = this.decide(state, amountUsd, caps, scope);
      if (!verdict.ok) return verdict;

      const amount = Number.isFinite(amountUsd) && amountUsd > 0 ? amountUsd : 0;
      file.total += amount;
      if (scope) file.scopes[scope] = (file.scopes[scope] ?? 0) + amount;
      return { ok: true, state: { ...state, total: file.total, scopeTotal: scope ? file.scopes[scope] : 0 } };
    });
  }

  /**
   * Record a charge that has ALREADY happened, whatever the ceilings say.
   *
   * A provider call that completed cost money regardless of what a budget file thinks, and dropping
   * it because it crossed the cap would make the ledger under-report — the one direction that turns
   * a safety rail into a lie. Ceilings refuse the NEXT call; they never un-spend the last one.
   */
  recordSettled(amountUsd: number, scope: string | null = null, model: string | null = null): SpendState {
    return this.withLock((file) => {
      const amount = Number.isFinite(amountUsd) && amountUsd > 0 ? amountUsd : 0;
      file.total += amount;
      if (scope) file.scopes[scope] = (file.scopes[scope] ?? 0) + amount;
      if (model && amount > 0) { file.models ??= {}; file.models[model] = (file.models[model] ?? 0) + amount; }
      return { date: file.date, total: file.total, scope, scopeTotal: scope ? file.scopes[scope] : 0 };
    });
  }

  /** Today by model, largest first, and the finished days, newest first (N6). */
  summary(): { models: Array<{ model: string; spent: number }>; days: SpendDay[] } {
    const file = this.withLock((f) => f);
    return {
      models: Object.entries(file.models ?? {}).map(([model, spent]) => ({ model, spent })).sort((a, b) => b.spent - a.spent),
      days: file.history ?? [],
    };
  }

  /** Every scope that spent today, largest first — the data behind a per-task cost view (N6). */
  breakdown(): Array<{ scope: string; spent: number }> {
    const file = this.withLock((f) => f);
    return Object.entries(file.scopes)
      .map(([scope, spent]) => ({ scope, spent }))
      .sort((a, b) => b.spent - a.spent);
  }
}

import * as fs from 'fs';
import * as path from 'path';
import type { ChangePlan } from '../tools/thread.changes';

/**
 * Task grants (backlog N13): "Allow for this task" on a thread's approval card.
 *
 * A thread asked afresh for every existing-file write and every mutating command — the fifth edit to the same file
 * as much as the first. A grant lets the user answer once for an explicitly described change, and it is reused only
 * while the target, the scope and the risk stay the same:
 * - editing one existing file: that exact file, nothing else;
 * - moving, renaming, copying or creating items, or moving them to the Bin: only when every item stays inside the
 *   thread's folder AND the undo journal can reverse it; a change that cannot be undone never gets a grant;
 * - a command the thread cannot describe: that exact command text, in that exact folder.
 * Anything else — another file, another folder, another command, an irreversible change — asks as before.
 *
 * A grant is checked AFTER every floor in the governor's thread path (folder scope, forbidden paths, plan mode,
 * permanent deletes, the user's protected paths), so it can never let through what a floor refuses; it only saves
 * the question. Grants live in the engine, so they end with the task, and `/grants clear` ends them sooner.
 */

export interface TaskGrant {
  key: string;
  /** What it allows, in words, e.g. edits to “math.js”. */
  label: string;
  at: number;
  uses: number;
}

const quote = (name: string): string => `“${name}”`;
const MAX_COMMAND_CHARS = 300;

function real(p: string): string {
  try { return fs.realpathSync(p); } catch { return path.resolve(p); }
}

function inside(root: string, p: string): boolean {
  const rel = path.relative(real(root), real(p));
  return rel === '' || (!rel.startsWith('..') && !path.isAbsolute(rel));
}

/** The grant this change could be answered with, or null when it may only be allowed one time. */
export function grantFor(taskType: string, plan: ChangePlan | null, payload: any, root: string, cwd: string): { key: string; label: string } | null {
  if (!plan) return null;
  const folder = quote(path.basename(real(root)) || root);
  if (plan.kind === 'write') {
    if (plan.overwrites.length !== 1 || !inside(root, plan.overwrites[0])) return null;
    const file = plan.overwrites[0];
    return { key: `write:${real(file)}`, label: `edits to ${quote(path.basename(file))}` };
  }
  if (plan.kind === 'command') {
    const command = String(payload?.command ?? '').trim();
    if (taskType !== 'OS_COMMAND' || !command || command.length > MAX_COMMAND_CHARS || /[\r\n]/.test(command)) return null;
    return { key: `command:${real(cwd)}:${command}`, label: `running \`${command}\` in ${quote(path.basename(real(cwd)) || cwd)}` };
  }
  // The rest are the journal's own shapes; a grant covers them only while every item stays in the folder and the
  // change can be put back.
  const paths = [...plan.moves.flatMap((m) => [m.from, m.to]), ...plan.trash, ...plan.creates, ...plan.overwrites];
  if (!plan.undoable || !paths.length || !paths.every((p) => inside(root, p))) return null;
  const labels: Record<string, string> = {
    move: `moving and renaming items inside ${folder} (each can be undone)`,
    copy: `copying items inside ${folder} (each can be undone)`,
    create: `creating files and folders inside ${folder}`,
    trash: `moving items inside ${folder} to the Bin (each can be put back)`,
  };
  const label = labels[plan.kind];
  return label ? { key: `${plan.kind}:${real(root)}`, label } : null;
}

export class TaskGrants {
  private grants = new Map<string, TaskGrant>();

  /** Whether `key` was granted; counts the use. */
  use(key: string): TaskGrant | null {
    const grant = this.grants.get(key);
    if (grant) grant.uses++;
    return grant ?? null;
  }

  add(grant: { key: string; label: string }): void {
    if (!this.grants.has(grant.key)) this.grants.set(grant.key, { ...grant, at: Date.now(), uses: 0 });
  }

  list(): TaskGrant[] { return [...this.grants.values()]; }

  clear(): number {
    const n = this.grants.size;
    this.grants.clear();
    return n;
  }
}

/** The engine's grants: one task per engine, so one set. */
export const taskGrants = new TaskGrants();

/** Grants end with the task: a new task in this engine (`clear`), or a switch to another saved one (`session_changed`). */
export function endGrantsWithTask(events: { on(event: string, fn: () => void): unknown }, grants: TaskGrants = taskGrants): void {
  events.on('clear', () => grants.clear());
  events.on('session_changed', () => grants.clear());
}

// CodememBackend — the codebase-memory engine fronted as Bimax's native graph backend.
//
// Approach (b): instead of dumping 14 raw `mcp__codebase-memory__*` tools on the model, we hold
// ONE persistent connection to the binary and route the existing GraphQueryTool / GraphContextTool
// verbs through it (search, callers/callees, blast radius, read symbol, plan context) — plus the
// capabilities the native AST graph lacks: local SEMANTIC vector search (bundled nomic-embed-code
// embeddings, 768d int8) and a clustered ARCHITECTURE overview.
//
// Every method is best-effort and returns null on any miss/error so the caller transparently falls
// back to Bimax's in-memory graph. The engine is never required for Bimax to work.
// See memory [[bake_in_codemem_headroom]].

import * as fs from 'fs';
import { Logger } from '../../utils/logger';
import { engineEvents } from '../../engine/events';
import { openClient } from '../../mcp/client';
import { ensureBinary, SERVER_NAME } from '../../mcp/builtin/codebaseMemory';
import { projectNameFromPath } from './projectName';

/** Pull the text payload out of an MCP tool result and JSON-parse it when possible. */
function parseResult(res: any): any {
  const parts = res?.content;
  let text = '';
  if (Array.isArray(parts)) {
    text = parts.filter((p: any) => p?.type === 'text').map((p: any) => p.text).join('');
  } else if (typeof res === 'string') {
    text = res;
  }
  try { return JSON.parse(text); } catch { return text; }
}

const STOP = new Set(['the', 'a', 'an', 'of', 'to', 'in', 'for', 'and', 'or', 'is', 'on', 'with', 'how', 'what', 'where']);
/** Turn a natural-language target into keyword array for semantic_query (vocabulary-bridging search). */
function semanticTokens(target: string): string[] {
  const words = target
    .replace(/([a-z])([A-Z])/g, '$1 $2') // split camelCase
    .toLowerCase()
    .split(/[^a-z0-9]+/)
    .filter(w => w.length >= 3 && !STOP.has(w));
  return [...new Set(words)].slice(0, 6);
}

export class CodememBackend {
  private client: any = null;
  private project: string | null = null;
  private ready = false;
  private starting: Promise<void> | null = null;
  private root = process.cwd();

  /** True once connected AND a populated project is resolved. */
  isReady(): boolean { return this.ready && !!this.client && !!this.project; }
  projectName(): string | null { return this.project; }

  /**
   * Connect to the engine and resolve (indexing if needed) the project for `projectRoot`.
   * Idempotent and non-throwing; runs in the background — callers just poll isReady().
   */
  init(projectRoot: string): Promise<void> {
    if (this.starting) return this.starting;
    this.root = projectRoot;
    this.starting = this._init(projectRoot).catch(e => {
      Logger.warn(`[codebase-memory] backend init failed: ${e?.message || e}`);
    });
    return this.starting;
  }

  private async _init(projectRoot: string): Promise<void> {
    if (process.env.BIMAX_DISABLE_CODEBASE_MEMORY === '1') return;
    const bin = await ensureBinary();
    if (!bin) return;
    this.client = await openClient({ name: SERVER_NAME, command: bin, args: [] });
    Logger.info('[codebase-memory] backend connected');
    await this.resolveProject(projectRoot);
  }

  /** Find an existing populated project matching this root, or index one. */
  private async resolveProject(projectRoot: string): Promise<void> {
    const want = realpath(projectRoot);
    const guess = projectNameFromPath(want);

    const existing = await this.findProject(want);
    if (existing) {
      this.project = existing;
      this.markReady();
      Logger.info(`[codebase-memory] using indexed project '${existing}'`);
      return;
    }

    // Not indexed yet — build it. 'full' enables the embedding/similarity edges that power
    // semantic vector search; the index is cached to disk so it's a one-time cost per repo.
    Logger.info(`[codebase-memory] indexing '${guess}' (full, one-time)...`);
    let indexed: any;
    try {
      indexed = await this.call('index_repository', { repo_path: want, mode: 'full' });
    } catch (e: any) {
      Logger.warn(`[codebase-memory] index failed: ${e?.message || e}`);
      return;
    }
    // index_repository echoes the project name it created — trust that over re-deriving.
    const name = indexed?.project || (await this.findProject(want)) || guess;
    this.project = name;
    this.markReady();
    Logger.info(`[codebase-memory] project '${name}' ready (${indexed?.nodes ?? '?'} nodes)`);
  }

  /** Strip the long project-slug prefix from a qualified_name for readable, paste-able output. */
  private shortQN(qn: string): string {
    if (!qn) return qn;
    return this.project && qn.startsWith(this.project + '.') ? qn.slice(this.project.length + 1) : qn;
  }

  /** Flip to ready and nudge the UI snapshot (footer/map badge) + tool-gating to refresh. */
  private markReady(): void {
    this.ready = true;
    try { engineEvents.emit('graph_changed'); } catch { /* events optional */ }
  }

  /** list_projects → name of the entry whose root_path matches `wantReal`, with nodes>0. */
  private async findProject(wantReal: string): Promise<string | null> {
    try {
      const data = await this.call('list_projects', {});
      const projects = data?.projects;
      if (!Array.isArray(projects)) return null;
      for (const p of projects) {
        if ((p?.nodes || 0) > 0 && p?.root_path && realpath(p.root_path) === wantReal) return p.name;
      }
      return null;
    } catch { return null; }
  }

  private async call(tool: string, args: Record<string, any>): Promise<any> {
    if (!this.client) throw new Error('not connected');
    const res = await this.client.callTool({ name: tool, arguments: args });
    if (res?.isError) throw new Error(typeof res === 'object' ? JSON.stringify(parseResult(res)) : String(res));
    return parseResult(res);
  }

  // ── Native-verb handlers (return formatted string, or null to fall back) ─────────────

  /**
   * SEARCH_NODES (keyword/BM25) and SEMANTIC (vector). semantic=true runs the bundled
   * nomic-embed-code vectors (vocabulary-bridging); else BM25 full-text with camelCase splitting.
   */
  async search(target: string, semantic = false): Promise<string | null> {
    if (!this.isReady()) return null;
    try {
      const args: any = { project: this.project, limit: semantic ? 30 : 25 };
      if (semantic) args.semantic_query = semanticTokens(target);
      else args.query = target;
      const data = await this.call('search_graph', args);
      if (typeof data === 'string') return data || null;
      let rows = [...(data.results || []), ...(data.semantic_results || [])];
      // Keep real definitions; drop File/Folder/Module/Project/Variable noise (semantic mode returns
      // the whole graph scored, so this is what makes the output usable).
      const DEF = new Set(['Function', 'Method', 'Class', 'Interface', 'Route', 'Struct', 'Enum', 'Trait', 'Type', 'Constructor', 'Channel']);
      const defs = rows.filter((r: any) => DEF.has(r.label));
      if (defs.length) rows = defs;
      const seen = new Set<string>();
      const lines = rows
        .filter((r: any) => { const k = r.qualified_name || r.name; if (!k || seen.has(k)) return false; seen.add(k); return true; })
        .slice(0, semantic ? 15 : 25)
        .map((r: any) => `- ${r.label || 'node'} ${this.shortQN(r.qualified_name || r.name)}${r.file_path ? ` (${r.file_path}${r.start_line ? ':' + r.start_line : ''})` : ''}`);
      if (lines.length === 0) return null;
      const more = data.has_more ? `\n…(${data.total} total — narrow the query)` : '';
      const how = semantic ? 'semantic (vector) search' : 'search';
      return `codebase-memory ${how} — ${lines.length} match(es) for "${target}":\n${lines.join('\n')}${more}`;
    } catch (e: any) { Logger.warn(`[codebase-memory] search failed: ${e?.message || e}`); return null; }
  }

  /** GET_DEPENDENTS / GET_DEPENDENCIES via trace_path calls mode. */
  async traceCalls(target: string, direction: 'inbound' | 'outbound'): Promise<string | null> {
    if (!this.isReady()) return null;
    try {
      const data = await this.call('trace_path', { project: this.project, function_name: target, direction, depth: 1, mode: 'calls' });
      if (typeof data === 'string') return data || null;
      const arr = (direction === 'inbound' ? data.callers : data.callees) || [];
      if (!Array.isArray(arr) || arr.length === 0) return null;
      const rel = direction === 'inbound' ? 'directly call (depend on)' : 'are directly called by';
      const list = arr.slice(0, 40).map((x: any) => `- ${this.shortQN(x.qualified_name || x.name)}`);
      return `${list.length} symbol(s) that ${rel} ${target}:\n${list.join('\n')}`;
    } catch (e: any) { Logger.warn(`[codebase-memory] trace failed: ${e?.message || e}`); return null; }
  }

  /** BLAST_RADIUS — deep both-direction trace with risk labels (callers + callees, transitive). */
  async blastRadius(target: string): Promise<string | null> {
    if (!this.isReady()) return null;
    try {
      const data = await this.call('trace_path', { project: this.project, function_name: target, direction: 'both', depth: 5, mode: 'calls', risk_labels: true });
      if (typeof data === 'string') return data || null;
      const callers = data.callers || [];
      const callees = data.callees || [];
      const count = callers.length + callees.length;
      if (count === 0) return null;
      const sev = count > 20 ? '🔴 LARGE' : count > 5 ? '🟡 MODERATE' : '🟢 SMALL';
      const fmt = (x: any) => `  - ${this.shortQN(x.qualified_name || x.name)}${x.risk ? ` [${x.risk}]` : ''}${x.hop ? ` (hop ${x.hop})` : ''}`;
      const sections = [
        `Blast radius for ${target}: ${sev} (${count} reachable)`,
        callers.length ? `Upstream callers (${callers.length}):\n${callers.slice(0, 20).map(fmt).join('\n')}` : '',
        callees.length ? `Downstream callees (${callees.length}):\n${callees.slice(0, 20).map(fmt).join('\n')}` : '',
        count > 20 ? '⚠️ Large reach — review dependents and run tests after editing.' : '',
      ].filter(Boolean);
      return sections.join('\n');
    } catch (e: any) { Logger.warn(`[codebase-memory] blast failed: ${e?.message || e}`); return null; }
  }

  /** READ_SYMBOL — exact source for a symbol. */
  async readSymbol(target: string): Promise<string | null> {
    if (!this.isReady()) return null;
    try {
      const data = await this.call('get_code_snippet', { project: this.project, qualified_name: target, include_neighbors: false });
      return this.fmtSnippet(data, false);
    } catch (e: any) { Logger.warn(`[codebase-memory] read failed: ${e?.message || e}`); return null; }
  }

  /** PLAN_CONTEXT — symbol source plus its neighbors (callers/callees). */
  async planContext(target: string): Promise<string | null> {
    if (!this.isReady()) return null;
    try {
      const data = await this.call('get_code_snippet', { project: this.project, qualified_name: target, include_neighbors: true });
      return this.fmtSnippet(data, true);
    } catch (e: any) { Logger.warn(`[codebase-memory] plan failed: ${e?.message || e}`); return null; }
  }

  /** ARCHITECTURE — clustered structural overview (no native equivalent). */
  async architecture(scopePath?: string): Promise<string | null> {
    if (!this.isReady()) return null;
    try {
      const args: any = { project: this.project };
      if (scopePath) args.path = scopePath;
      const data = await this.call('get_architecture', args);
      if (typeof data === 'string') return data || null;
      const sec: string[] = ['Architecture overview:'];
      const langs = (data.languages || []).map((l: any) => `${l.language} (${l.file_count})`);
      if (langs.length) sec.push(`Languages: ${langs.join(', ')}`);
      const pkgs = (data.packages || []).slice(0, 12).map((p: any) => `  - ${p.name} (${p.node_count} nodes, fan-in ${p.fan_in}/fan-out ${p.fan_out})`);
      if (pkgs.length) sec.push(`Packages:\n${pkgs.join('\n')}`);
      const clusters = (data.clusters || []).slice(0, 8).map((c: any) => `  - ${c.label || c.name}${c.cohesion != null ? ` (cohesion ${c.cohesion})` : ''}${c.member_count ? ` ×${c.member_count}` : ''}`);
      if (clusters.length) sec.push(`Module clusters (community detection):\n${clusters.join('\n')}`);
      const entries = (data.entry_points || []).slice(0, 10).map((e: any) => `  - ${this.shortQN(e.qualified_name || e.name)}${e.file ? ` (${e.file})` : ''}`);
      if (entries.length) sec.push(`Entry points:\n${entries.join('\n')}`);
      const hot = (data.hotspots || []).slice(0, 10).map((h: any) => `  - ${this.shortQN(h.qualified_name || h.name)} (fan-in ${h.fan_in})`);
      if (hot.length) sec.push(`Hotspots (most depended-on):\n${hot.join('\n')}`);
      return sec.length > 1 ? sec.join('\n') : JSON.stringify(data, null, 2);
    } catch (e: any) { Logger.warn(`[codebase-memory] architecture failed: ${e?.message || e}`); return null; }
  }

  private fmtSnippet(data: any, withNeighbors: boolean): string | null {
    if (typeof data === 'string') return data || null;
    // Ambiguous short name → the engine returns candidate suggestions instead of source.
    if (data?.suggestions && !data.source && !data.code) {
      const s = (data.suggestions || []).slice(0, 10).map((x: any) => '- ' + this.shortQN(x.qualified_name || x.name)).join('\n');
      return s ? `"${data.query || ''}" is ambiguous — candidates:\n${s}` : null;
    }
    const code = data.source || data.code || data.snippet;
    if (!code) return null;
    const header = [
      data.qualified_name && `// ${data.label || 'symbol'} ${this.shortQN(data.qualified_name)}`,
      data.file_path && `// ${data.file_path}${data.start_line ? ':' + data.start_line : ''}${data.end_line ? '-' + data.end_line : ''}`,
      data.signature && `// ${data.signature}${data.return_type || ''}`,
    ].filter(Boolean).join('\n');
    let out = `${header}\n${code}`;
    if (withNeighbors) {
      const callers = data.caller_names || [];
      const callees = data.callee_names || [];
      if (callers.length) out += `\n// called by: ${callers.slice(0, 12).join(', ')}`;
      if (callees.length) out += `\n// calls: ${callees.slice(0, 12).join(', ')}`;
    }
    return out;
  }

  async close(): Promise<void> {
    try { await this.client?.close?.(); } catch { /* ignore */ }
    this.client = null; this.ready = false;
  }
}

function realpath(p: string): string {
  try { return fs.realpathSync(p); } catch { return p; }
}

// Process-wide singleton (one engine connection per Bimax process).
export const globalCodemem = new CodememBackend();
export function isCodememReady(): boolean { return globalCodemem.isReady(); }

import * as fs from 'fs/promises';
import * as path from 'path';
import { GraphData, GraphNode, GraphEdge, IGraphStore } from './models';
import { Logger } from '../utils';

export class GraphStore implements IGraphStore {
  private revision = 0;

  /** Changes only when the store publishes a graph mutation; used by derived-data caches. */
  public getRevision(): number { return this.revision; }
  private data: GraphData = {
    nodes: new Map(),
    edges: []
  };

  // O(1) Adjacency Lists
  private edgesFrom: Map<string, GraphEdge[]> = new Map();
  private edgesTo: Map<string, GraphEdge[]> = new Map();

  constructor(private storagePath: string) {}

  public setStoragePath(newPath: string) {
    this.storagePath = newPath;
  }

  public clear() {
    this.revision++;
    this.data = { nodes: new Map(), edges: [] };
    this.edgesFrom.clear();
    this.edgesTo.clear();
  }

  public setGraph(graph: GraphData) {
    this.revision++;
    this.data = graph;
    this.rebuildIndices();
  }

  public getGraph(): GraphData {
    return this.data;
  }

  public getNode(id: string): GraphNode | undefined {
    return this.data.nodes.get(id);
  }

  public getEdgesFrom(sourceId: string): GraphEdge[] {
    return this.edgesFrom.get(sourceId) || [];
  }

  public getEdgesTo(targetId: string): GraphEdge[] {
    return this.edgesTo.get(targetId) || [];
  }

  public addNode(node: GraphNode) {
    if (!this.data.nodes.has(node.id)) {
      this.revision++;
      this.data.nodes.set(node.id, node);
    }
  }

  public addEdge(edge: GraphEdge) {
    this.revision++;
    this.data.edges.push(edge);

    if (!this.edgesFrom.has(edge.sourceId)) this.edgesFrom.set(edge.sourceId, []);
    this.edgesFrom.get(edge.sourceId)!.push(edge);

    if (!this.edgesTo.has(edge.targetId)) this.edgesTo.set(edge.targetId, []);
    this.edgesTo.get(edge.targetId)!.push(edge);
  }

  public removeNode(id: string) {
    this.removeNodes([id]);
  }

  /** Remove a file/batch with one edge scan and one adjacency rebuild. */
  public removeNodes(ids: Iterable<string>): void {
    const removed = new Set(ids);
    if (removed.size === 0) return;
    this.revision++;
    for (const id of removed) this.data.nodes.delete(id);

    // Remove touching edges
    this.data.edges = this.data.edges.filter(e => !removed.has(e.sourceId) && !removed.has(e.targetId));
    this.rebuildIndices();
  }

  private rebuildIndices() {
    this.edgesFrom.clear();
    this.edgesTo.clear();

    for (const edge of this.data.edges) {
      if (!this.edgesFrom.has(edge.sourceId)) this.edgesFrom.set(edge.sourceId, []);
      this.edgesFrom.get(edge.sourceId)!.push(edge);

      if (!this.edgesTo.has(edge.targetId)) this.edgesTo.set(edge.targetId, []);
      this.edgesTo.get(edge.targetId)!.push(edge);
    }
  }

  public async saveToDisk(): Promise<void> {
    const rawNodes = Array.from(this.data.nodes.values());
    const rawData = {
      nodes: rawNodes,
      edges: this.data.edges
    };

    if (this.storagePath === ':memory:') return;

    const dir = path.dirname(this.storagePath);
    await fs.mkdir(dir, { recursive: true });

    await fs.writeFile(this.storagePath, JSON.stringify(rawData, null, 2), 'utf-8');
    Logger.info(`[GraphStore] Graph saved successfully to ${this.storagePath}`);
  }

  public async loadFromDisk(): Promise<void> {
    if (this.storagePath === ':memory:') return;

    try {
      const fileContent = await fs.readFile(this.storagePath, 'utf-8');
      const rawData = JSON.parse(fileContent);

      const nodesMap = new Map<string, GraphNode>();
      for (const node of rawData.nodes) {
        nodesMap.set(node.id, node);
      }

      this.setGraph({
        nodes: nodesMap,
        edges: rawData.edges || []
      });
      Logger.info(`[GraphStore] Graph loaded from ${this.storagePath}. Nodes: ${this.data.nodes.size}, Edges: ${this.data.edges.length}`);
    } catch (e: any) {
      if (e.code === 'ENOENT') {
        Logger.info(`[GraphStore] No existing graph found at ${this.storagePath}. Starting fresh.`);
      } else {
        Logger.error(`[GraphStore] Failed to load graph: ${e.message}`);
      }
    }
  }
}

import { IGraphStore, GraphNode, GraphEdge } from './models';

export interface BlastRadiusReport {
  targetNodeId: string;
  totalImpactedNodes: number;
  impactedFiles: number;
  impactedFunctions: number;
  impactedClasses: number;
  highestRiskScore: number;
  criticalPath: string[]; // Just an example path showing the deepest connection
}

export interface IImpactEngine {
  getForwardDependencies(startNodeId: string, maxDepth?: number): GraphNode[];
  getReverseDependencies(startNodeId: string, maxDepth?: number): GraphNode[];
  calculateBlastRadius(targetNodeId: string): BlastRadiusReport;
  getAllPaths(startNodeId: string, endNodeId: string, maxDepth?: number): GraphNode[][];
  getDataFlow(variableId: string): GraphNode[];
  clearCache(): void;
}

export class ImpactEngine implements IImpactEngine {
  private blastRadiusCache: Map<string, BlastRadiusReport> = new Map();

  constructor(private store: IGraphStore) {}

  public clearCache(): void {
    this.blastRadiusCache.clear();
  }

  /**
   * Forward Dependency Lookup: "What does this node depend on?"
   * (Follow outgoing edges like CALLS, IMPORTS)
   */
  public getForwardDependencies(startNodeId: string, maxDepth: number = 3): GraphNode[] {
    return this.traverse(startNodeId, maxDepth, 'forward');
  }

  /**
   * Reverse Dependency Lookup: "Who depends on this node?"
   * (Follow incoming edges)
   */
  public getReverseDependencies(startNodeId: string, maxDepth: number = 3): GraphNode[] {
    return this.traverse(startNodeId, maxDepth, 'reverse');
  }

  /**
   * Calculate Blast Radius for modifying a specific node
   */
  public calculateBlastRadius(targetNodeId: string): BlastRadiusReport {
    const targetNode = this.store.getNode(targetNodeId);
    if (!targetNode) {
      throw new Error(`Node ${targetNodeId} not found in graph.`);
    }

    if (this.blastRadiusCache.has(targetNodeId)) {
      return this.blastRadiusCache.get(targetNodeId)!;
    }

    const impactedNodes = this.getReverseDependencies(targetNodeId, 5); // Default deep search

    let files = 0;
    let functions = 0;
    let classes = 0;
    let maxRisk = 0;

    for (const node of impactedNodes) {
      if (node.type === 'FILE') files++;
      if (node.type === 'FUNCTION') functions++;
      if (node.type === 'CLASS') classes++;

      // riskScore is a top-level GraphNode field (set by the semantic augmenter); the older
      // metadata.riskScore path was always undefined, so highestRiskScore was silently always 0.
      const riskScore = node.riskScore ?? (node as any).metadata?.riskScore ?? 0;
      if (riskScore > maxRisk) {
        maxRisk = riskScore;
      }
    }

    const report: BlastRadiusReport = {
      targetNodeId,
      totalImpactedNodes: impactedNodes.length,
      impactedFiles: files,
      impactedFunctions: functions,
      impactedClasses: classes,
      highestRiskScore: maxRisk,
      criticalPath: impactedNodes.map(n => n.id).slice(0, 3) // Simplified critical path for MVP
    };

    this.blastRadiusCache.set(targetNodeId, report);
    return report;
  }

  /**
   * Standard BFS Traversal
   */
  private traverse(startNodeId: string, maxDepth: number, direction: 'forward' | 'reverse'): GraphNode[] {
    const visited = new Set<string>();
    const result: GraphNode[] = [];
    let queue = [startNodeId];
    let head = 0;
    let layerEnd = 1;
    let depth = 0;
    visited.add(startNodeId);

    // Keep FIFO/depth order without front shifts or per-node depth objects. Clear
    // consumed IDs and compact only when at least half the array has been consumed:
    // copied IDs are amortized linear, and queue slots stay O(live frontier + 1024).
    while (head < queue.length) {
      if (depth >= maxDepth) break;
      const current = queue[head];
      queue[head++] = '';
      const edges = direction === 'forward'
        ? this.store.getEdgesFrom(current)
        : this.store.getEdgesTo(current);
      for (const edge of edges) {
        const nextId = direction === 'forward' ? edge.targetId : edge.sourceId;
        if (!visited.has(nextId)) {
          visited.add(nextId);
          const nextNode = this.store.getNode(nextId);
          if (nextNode) {
            result.push(nextNode);
            queue.push(nextId);
          }
        }
      }
      if (head === layerEnd) { depth++; layerEnd = queue.length; }
      if (head >= 1024 && head * 2 >= queue.length) {
        queue = queue.slice(head);
        layerEnd -= head;
        head = 0;
      }
    }

    return result;
  }

  /**
   * SHOW_ALL_PATHS: Find all paths between two nodes using DFS
   */
  public getAllPaths(startNodeId: string, endNodeId: string, maxDepth: number = 5): GraphNode[][] {
    const paths: GraphNode[][] = [];

    const dfs = (currentId: string, currentPath: GraphNode[], depth: number, visited: Set<string>) => {
      if (depth > maxDepth) return;
      if (currentId === endNodeId) {
        paths.push([...currentPath]);
        return;
      }

      const edges = this.store.getEdgesFrom(currentId);
      for (const edge of edges) {
        if (!visited.has(edge.targetId)) {
          visited.add(edge.targetId);
          const nextNode = this.store.getNode(edge.targetId);
          if (nextNode) {
            currentPath.push(nextNode);
            dfs(edge.targetId, currentPath, depth + 1, visited);
            currentPath.pop();
          }
          visited.delete(edge.targetId);
        }
      }
    };

    const startNode = this.store.getNode(startNodeId);
    if (startNode) {
      dfs(startNodeId, [startNode], 0, new Set([startNodeId]));
    }

    return paths;
  }

  /**
   * SHOW_DATA_FLOW: Traces where a variable flows
   */
  public getDataFlow(variableId: string): GraphNode[] {
    const node = this.store.getNode(variableId);
    if (!node || node.type !== 'VARIABLE') {
      throw new Error(`Node ${variableId} is not a valid VARIABLE.`);
    }
    // We get all statements or blocks that USE this variable
    const edges = this.store.getEdgesTo(variableId).filter(e => e.type === 'USES_VARIABLE');
    const flowNodes = edges.map(e => this.store.getNode(e.sourceId)).filter(Boolean) as GraphNode[];
    return flowNodes;
  }
}

import * as fs from 'fs';
import * as path from 'path';
import * as readline from 'readline';
import { StaticAnalyzer } from './static.analyzer';
import { TreeSitterAnalyzer } from './treesitter.analyzer';
import { SemanticAugmenter } from './semantic.augmenter';
import { GraphStore } from './graph.store';
import { SqliteGraphStore } from './sqlite.graph.store';
import { Logger } from '../utils';
import { publishFileGraph } from './file.graph';

export class CodebaseIndexer {
  public enabled: boolean = true;
  public excludePatterns: string[] = [];

  constructor(
    private projectRoot: string,
    private graphStore: GraphStore,
    private analyzer: StaticAnalyzer,
    private augmenter: SemanticAugmenter
  ) {}

  public setProjectRoot(newRoot: string) {
    this.projectRoot = newRoot;
    this.analyzer.setProjectRoot(newRoot);
    this.augmenter.setProjectRoot(newRoot);
  }

  /**
   * Multi-language AST pass: index non-TS/JS files (Python, …) via tree-sitter into the same
   * graph. Additive and best-effort — runs after the TS analyzer and never throws upward, so
   * a repo with no tsconfig still gets a graph from its other languages.
   */
  private async runTreeSitterPass(): Promise<void> {
    try {
      const tsa = new TreeSitterAnalyzer(this.projectRoot, this.graphStore, this.excludePatterns);
      await tsa.analyzeProject();
    } catch (e: any) {
      Logger.warn(`[CodebaseIndexer] tree-sitter pass skipped: ${e.message}`);
    }
  }

  /**
   * @param interactive  Only true for a standalone (non-TUI) CLI invocation. MUST be false when
   *   called from inside the Ink TUI: Ink owns process.stdin in raw mode, and opening a second
   *   readline interface here makes two consumers fight over the same raw TTY — a stdin busy-loop
   *   that pins a CPU core and freezes the UI (the "Mac frying an egg while idle" bug). In the TUI
   *   we AST-index silently and leave semantic ingestion as an explicit opt-in (/graph ingest).
   */
  public async autoIndex(force: boolean = false, interactive: boolean = false): Promise<void> {
    if (!this.enabled) {
      Logger.info(`[CodebaseIndexer] Skipped — disabled by config.`);
      return;
    }
    // Store-agnostic "already indexed" check: count nodes in the LOADED store (works for
    // both the SQLite and the legacy JSON backends). If the store looks empty, give it one
    // load attempt — boot paths that skipped loadFromDisk (or a fresh SQLite DB sitting
    // next to a legacy playground.json awaiting migration) are covered by this.
    if (this.graphStore.getGraph().nodes.size === 0) {
      try { await this.graphStore.loadFromDisk(); } catch { /* treat as unindexed */ }
    }
    const needsIndexing = this.graphStore.getGraph().nodes.size === 0;

    if (!force && !needsIndexing) {
      // Already indexed — keep it FRESH instead of frozen (v2 §3.9): re-parse changed
      // files in the background, bounded, never blocking boot.
      this.refreshStale().catch(() => { /* freshness is best-effort */ });
      return;
    }

    if (force) {
      this.graphStore.clear(); // Clear existing graph if forced
    }

    Logger.info(`[CodebaseIndexer] Indexing codebase (AST) for ${this.projectRoot}…`);

    // 1. Physical Indexing — never let an unreadable/invalid tsconfig kill the boot. The TS
    // pass and the tree-sitter pass are independent: a failure in one must not skip the other.
    try {
      this.analyzer.analyzeProject();
    } catch (e: any) {
      Logger.warn(`[CodebaseIndexer] TS AST pass skipped: ${e.message}`);
    }
    await this.runTreeSitterPass();
    await this.graphStore.saveToDisk();
    if (this.graphStore instanceof SqliteGraphStore) this.graphStore.recordFileHashes(this.projectRoot);

    const nodeCount = this.graphStore.getGraph().nodes.size;
    if (nodeCount === 0) {
      Logger.warn(`[CodebaseIndexer] No indexable source found in ${this.projectRoot}.`);
      return;
    }
    Logger.info(`[CodebaseIndexer] Codebase index complete: ${nodeCount} nodes extracted.`);

    // 2. Semantic ingestion prompt — ONLY for a standalone CLI run. Never under the Ink TUI:
    // readline + Ink both reading the raw TTY deadlock-spin on stdin (100% CPU, frozen UI).
    if (interactive && process.stdout.isTTY) {
      await this.promptForSemanticIngestion(nodeCount);
    } else {
      Logger.info(`[CodebaseIndexer] AST index ready (${nodeCount} nodes). Run semantic ingestion explicitly with /index-ai when you want LLM metadata.`);
    }
  }

  private promptForSemanticIngestion(nodeCount: number): Promise<void> {
    return new Promise((resolve) => {
      const rl = readline.createInterface({
        input: process.stdin,
        output: process.stdout
      });

      console.log(`\nShould I also run **Semantic Ingestion** to add LLM meta-data (purpose, risk scores) to these nodes?`);
      console.log(`(Warning: This will make ~${nodeCount} API calls using your configured LLM keys)`);

      rl.question(`Run Semantic Ingestion? [Y/n] `, async (answer) => {
        rl.close();
        if (answer.toLowerCase() === 'y' || answer.toLowerCase() === 'yes' || answer === '') {
          console.log(`\n🚀 Starting Semantic Ingestion... I'll let you know when I'm done.`);
          await this.augmenter.augmentGraph();
          console.log(`\n🧠 Semantic Ingestion complete! The graph now has Mythos-level intelligence.`);
        } else {
          console.log(`\nSkipping Semantic Ingestion. You can run it manually later.`);
        }
        resolve();
      });
    });
  }

  /**
   * Incremental refresh (v2 §3.9): re-parse ONLY the files whose content hash moved
   * since the last (re)index, prune nodes of deleted files. Needs the SQLite store
   * (which carries the hash baseline); on the JSON store it reports 'unsupported'.
   * Bounded: past `fullThreshold` stale files a full reindex is cheaper and cleaner.
   */
  public async refreshStale(opts?: { fullThreshold?: number }): Promise<{ supported: boolean; changed: number; deleted: number; full: boolean }> {
    if (!(this.graphStore instanceof SqliteGraphStore) || !this.graphStore.isAvailable()) {
      return { supported: false, changed: 0, deleted: 0, full: false };
    }
    const store = this.graphStore;
    const { changed, deleted } = store.staleFiles(this.projectRoot);
    // Hash rows only know old paths. Config discovery also finds new/renamed TS/JS
    // files without constructing a Program or reparsing the unchanged majority.
    const known = store.recordedFiles();
    const pending = new Set(changed);
    try {
      const candidates = [...this.analyzer.getProjectFiles(),
        ...new TreeSitterAnalyzer(this.projectRoot, store, this.excludePatterns).getProjectFiles()];
      for (const abs of candidates) {
        const rel = path.relative(this.projectRoot, abs);
        if (!known.has(rel) && !pending.has(rel)) {
          changed.push(rel);
          pending.add(rel);
        }
      }
    } catch (e: any) {
      Logger.warn(`[CodebaseIndexer] source discovery failed: ${e.message}`);
    }
    if (changed.length === 0 && deleted.length === 0) return { supported: true, changed: 0, deleted: 0, full: false };

    const threshold = opts?.fullThreshold ?? 200;
    if (changed.length + deleted.length > threshold) {
      Logger.info(`[CodebaseIndexer] ${changed.length + deleted.length} stale files — beyond the incremental budget, full reindex.`);
      await this.buildAstIndex();
      return { supported: true, changed: changed.length, deleted: deleted.length, full: true };
    }

    // Keep deletion baselines until the graph commit succeeds. A crash/failure before
    // that commit must leave enough evidence to prune the old persisted nodes again.
    for (const rel of deleted) store.removeFileNodes(rel, true);
    const tsLike = /\.(?:[cm]?[jt]s|[jt]sx)$/i;
    const refreshed: string[] = [];
    const parsedStates = new Map<string, NonNullable<ReturnType<typeof store.captureFileState>>>();
    // Capture all identities before constructing the shared Program; later files must
    // never certify newer disk bytes against an older compiler snapshot.
    const inputStates = new Map(changed.map(rel => [rel, store.captureFileState(this.projectRoot, rel)]));
    let snapshot: ReturnType<StaticAnalyzer['createProgram']> | undefined;
    try { if (changed.some(rel => tsLike.test(rel))) snapshot = this.analyzer.createProgram(); }
    catch (e: any) { Logger.warn(`[CodebaseIndexer] compiler snapshot unavailable: ${e.message}`); }
    for (const rel of changed) {
      const abs = path.isAbsolute(rel) ? rel : path.join(this.projectRoot, rel);
      try {
        const state = inputStates.get(rel);
        if (!state) throw new Error('Source unavailable or changed while reading.');
        if (tsLike.test(rel)) {
          if (!snapshot) throw new Error('Compiler snapshot unavailable.');
          this.analyzer.analyzeSingleFile(abs, snapshot);
        } else {
          const replacement = new GraphStore(':memory:');
          const tsa = new TreeSitterAnalyzer(this.projectRoot, replacement, this.excludePatterns);
          if (!await tsa.analyzeSingleFile(abs)) throw new Error('No parser or grammar available for source.');
          publishFileGraph(store, rel, replacement.getGraph());
        }
        refreshed.push(rel);
        parsedStates.set(rel, state);
      } catch (e: any) {
        Logger.warn(`[CodebaseIndexer] incremental re-parse of ${rel} failed: ${e.message}`);
      }
    }
    await this.graphStore.saveToDisk();
    store.recordFileHashes(this.projectRoot, refreshed, parsedStates, deleted);
    Logger.info(`[CodebaseIndexer] Incremental refresh: ${refreshed.length} file(s) re-parsed, ${deleted.length} pruned, ${changed.length - refreshed.length} parse failures pending.`);
    return { supported: true, changed: changed.length, deleted: deleted.length, full: false };
  }

  public async buildAstIndex(): Promise<number> {
    Logger.info(`[CodebaseIndexer] Manually triggering AST indexing for ${this.projectRoot}`);
    this.graphStore.clear();
    try {
      this.analyzer.analyzeProject();
    } catch (e: any) {
      Logger.warn(`[CodebaseIndexer] TS AST pass skipped: ${e.message}`);
    }
    await this.runTreeSitterPass();
    await this.graphStore.saveToDisk();
    if (this.graphStore instanceof SqliteGraphStore) this.graphStore.recordFileHashes(this.projectRoot);
    return this.graphStore.getGraph().nodes.size;
  }

  public async buildSemanticIndex(): Promise<void> {
    Logger.info(`[CodebaseIndexer] Manually triggering Semantic Ingestion for ${this.projectRoot}`);
    await this.augmenter.augmentGraph();
    await this.graphStore.saveToDisk();
  }
}

export type NodeType = 'PROJECT' | 'DIRECTORY' | 'FILE' | 'CLASS' | 'FUNCTION' | 'INTERFACE' | 'UNKNOWN' | 'FOLDER' | 'BLOCK' | 'STATEMENT' | 'VARIABLE' | 'EVENT' | 'GOAL' | 'TASK' | 'SUBTASK' | 'CAPABILITY';
export type EdgeType = 'CONTAINS' | 'IMPORTS' | 'CALLS' | 'IMPLEMENTS' | 'EXTENDS' | 'USES_VARIABLE' | 'DECLARES_VARIABLE' | 'SUBSCRIBES_TO' | 'PUBLISHES_TO' | 'SPAWNS' | 'SATISFIES' | 'REQUIRES';

export interface GraphNode {
  id: string; // Unique identifier, typically absolute path + symbol name
  name: string;
  type: NodeType;
  filePath?: string; // Where this node lives

  // Source location (1-based, inclusive). Populated by the static analyzers so the agent
  // can read just this symbol's source instead of the whole file. Optional for backward
  // compatibility: graphs serialized before this existed simply lack the fields until
  // they are re-indexed.
  startLine?: number;
  endLine?: number;
  signature?: string; // The declaration's first line (e.g. `function foo(a: number): void`)

  // Semantic Metadata (Populated by LLM in Phase 2)
  purpose?: string;
  criticality?: 'LOW' | 'MEDIUM' | 'HIGH' | 'CRITICAL';
  riskScore?: number; // 0-100
}

export interface GraphEdge {
  sourceId: string;
  targetId: string;
  type: EdgeType;
  metadata?: Record<string, any>;
}

export interface GraphData {
  nodes: Map<string, GraphNode>;
  edges: GraphEdge[]; // Keeping raw edges for serialization
}

export interface IGraphStore {
  /** Monotonic local mutation revision, when supported by the store. */
  getRevision?(): number;
  setGraph(graph: GraphData): void;
  getGraph(): GraphData;
  getNode(id: string): GraphNode | undefined;
  getEdgesFrom(nodeId: string): GraphEdge[];
  getEdgesTo(nodeId: string): GraphEdge[];
  addNode(node: GraphNode): void;
  removeNode(id: string): void;
  addEdge(edge: GraphEdge): void;
  saveToDisk(): Promise<void>;
  loadFromDisk(): Promise<void>;
  clear(): void;
  setStoragePath(newPath: string): void;
}

import { GraphStore } from './graph.store';
import { LlmAdapter } from '../core/llm.adapter';
import { Logger } from '../utils';
import * as fs from 'fs/promises';
import * as path from 'path';

export class SemanticAugmenter {
  public enabled: boolean = true;

  constructor(private graphStore: GraphStore, private llmAdapter: LlmAdapter, private projectRoot: string) {}

  public setProjectRoot(newRoot: string) {
    this.projectRoot = newRoot;
  }

  public async augmentGraph(limit?: number): Promise<void> {
    if (!this.enabled) {
      Logger.info(`[SemanticAugmenter] Skipped — disabled by config.`);
      return;
    }
    const graph = this.graphStore.getGraph();
    let augmentedCount = 0;

    Logger.info(`[SemanticAugmenter] Starting semantic augmentation of nodes...`);

    for (const [id, node] of graph.nodes.entries()) {
      if (limit && augmentedCount >= limit) {
        break;
      }

      // Skip nodes that already have metadata
      if (node.purpose && node.criticality && node.riskScore !== undefined) {
        continue;
      }

      // Only augment Files, Classes, and Functions for now
      if (!['FILE', 'CLASS', 'FUNCTION'].includes(node.type)) {
        continue;
      }

      let codeSnippet = '';
      try {
        if (node.filePath) {
          const fullPath = path.join(this.projectRoot, node.filePath);
          const fullContent = await fs.readFile(fullPath, 'utf8');

          if (node.type === 'FILE') {
            // Send only the first 30 lines of a file to avoid massive token usage
            codeSnippet = fullContent.split('\n').slice(0, 30).join('\n') + '\n// ... (truncated)';
          } else if (node.startLine && node.endLine) {
            const lines = fullContent.split('\n');
            const start = Math.max(0, node.startLine - 1);
            const end = Math.min(lines.length, node.endLine);
            const snippet = lines.slice(start, end).join('\n');
            codeSnippet = snippet + '\n// ... (truncated)';
          } else {
            // Fallback: send the first 50 lines if no source location is available
            codeSnippet = fullContent.split('\n').slice(0, 50).join('\n') + '\n// ... (truncated)';
          }
        }
      } catch (e) {
        Logger.warn(`[SemanticAugmenter] Could not read file for node ${node.id}`);
        continue;
      }

      Logger.info(`[SemanticAugmenter] Augmenting: ${node.id}`);

      const metadata = await this.llmAdapter.generateSemanticMetadata(node.id, node.name, node.type, codeSnippet);

      if (metadata) {
        node.purpose = metadata.purpose;
        node.criticality = metadata.criticality;
        node.riskScore = metadata.riskScore;
        augmentedCount++;

        // Checkpoint save every 10 nodes to avoid losing work on crash
        if (augmentedCount % 10 === 0) {
          await this.graphStore.saveToDisk();
        }
      }
    }

    if (augmentedCount > 0) {
      await this.graphStore.saveToDisk();
    }

    Logger.info(`[SemanticAugmenter] Semantic augmentation complete. Augmented ${augmentedCount} nodes.`);
  }
}

import { stateDir } from '../utils/state.dir';
import * as fs from 'fs';
import * as path from 'path';
import * as crypto from 'crypto';
import { GraphStore } from './graph.store';
import { GraphNode, GraphEdge, IGraphStore } from './models';
import { Logger } from '../utils';
import { openSqlite } from '../core/sqlite';

/**
 * SQLite-backed graph store (v2 §3.9, honest-minimal tier).
 *
 * Queries stay in memory (the GraphStore adjacency maps — that part was never the
 * problem); what moves to SQLite is PERSISTENCE and STALENESS:
 *
 *   - `saveToDisk` writes nodes/edges in ONE transaction (atomic — a crash mid-save
 *     can no longer truncate the graph the way a half-written 10MB JSON could) and
 *     records a content hash per indexed file.
 *   - `staleFiles` compares those hashes against the working tree (mtime+size fast
 *     path, hash on suspicion), so the indexer re-parses ONLY what changed — the
 *     plan's per-file invalidation, with a flat hash table standing in for the
 *     merkle tree until repo scale demands sharding.
 *   - One-time migration: an empty DB sitting next to a legacy `playground.json`
 *     imports it on first load, then the JSON is left untouched as a fossil.
 *
 * Where node:sqlite is unavailable the caller falls back to the JSON GraphStore via
 * `createGraphStore` — same API, older durability story.
 */

interface FileState { hash: string; mtimeMs: number; ctimeMs: number; size: number }

export class SqliteGraphStore extends GraphStore implements IGraphStore {
  private db: any | null = null;
  private available = false;
  private dbPath: string;

  constructor(dbPath: string) {
    super(':memory:'); // the JSON path is never used; SQLite owns persistence
    this.dbPath = dbPath;
    try {
      fs.mkdirSync(path.dirname(dbPath), { recursive: true });
      // openSqlite → node:sqlite (dev/CI) or bun:sqlite (the packaged bun --compile engine). Both
      // expose the same exec/prepare surface used below; null means no SQLite on this runtime.
      this.db = openSqlite(dbPath);
      if (!this.db) throw new Error('no SQLite backend (node:sqlite / bun:sqlite) on this runtime');
      this.db.exec('PRAGMA journal_mode = WAL');
      this.db.exec('PRAGMA busy_timeout = 3000');
      this.db.exec('CREATE TABLE IF NOT EXISTS nodes (id TEXT PRIMARY KEY, json TEXT NOT NULL)');
      this.db.exec('CREATE TABLE IF NOT EXISTS edges (source TEXT NOT NULL, target TEXT NOT NULL, type TEXT NOT NULL, json TEXT NOT NULL)');
      this.db.exec('CREATE INDEX IF NOT EXISTS idx_edges_source ON edges(source)');
      this.db.exec('CREATE INDEX IF NOT EXISTS idx_edges_target ON edges(target)');
      this.db.exec('CREATE TABLE IF NOT EXISTS file_hashes (path TEXT PRIMARY KEY, hash TEXT NOT NULL, mtime REAL NOT NULL, size INTEGER NOT NULL)');
      // Serialize the old-schema check and migration across engines sharing this database.
      this.db.exec('BEGIN IMMEDIATE');
      try {
        if (!this.db.prepare('PRAGMA table_info(file_hashes)').all().some((column: any) => column.name === 'ctime')) {
          // NULL forces one hash check for rows written by older builds.
          this.db.exec('ALTER TABLE file_hashes ADD COLUMN ctime REAL');
        }
        this.db.exec('COMMIT');
      } catch (error) {
        this.db.exec('ROLLBACK');
        throw error;
      }
      this.available = true;
    } catch (e: any) {
      Logger.warn(`[SqliteGraphStore] no compatible SQLite backend (${e?.message}); persistence disabled.`);
      this.db = null;
      this.available = false;
    }
  }

  isAvailable(): boolean { return this.available; }

  public async loadFromDisk(): Promise<void> {
    if (!this.available || !this.db) return;
    try {
      const nodeRows = this.db.prepare('SELECT json FROM nodes').all();
      if (nodeRows.length === 0 && this.importLegacyJson()) return; // migration already populated + saved
      const nodes = new Map<string, GraphNode>();
      for (const r of nodeRows) {
        const n = JSON.parse(String(r.json)) as GraphNode;
        nodes.set(n.id, n);
      }
      const edges = this.db.prepare('SELECT json FROM edges').all().map((r: any) => JSON.parse(String(r.json)) as GraphEdge);
      this.setGraph({ nodes, edges });
      Logger.info(`[SqliteGraphStore] Graph loaded from ${this.dbPath}. Nodes: ${nodes.size}, Edges: ${edges.length}`);
    } catch (e: any) {
      Logger.error(`[SqliteGraphStore] load failed: ${e.message}`);
    }
  }

  public async saveToDisk(): Promise<void> {
    if (!this.available || !this.db) return;
    try {
      const g = this.getGraph();
      this.db.exec('BEGIN IMMEDIATE');
      try {
        this.db.exec('DELETE FROM nodes');
        this.db.exec('DELETE FROM edges');
        const insN = this.db.prepare('INSERT OR REPLACE INTO nodes (id, json) VALUES (?, ?)');
        for (const n of g.nodes.values()) insN.run(n.id, JSON.stringify(n));
        const insE = this.db.prepare('INSERT INTO edges (source, target, type, json) VALUES (?, ?, ?, ?)');
        for (const e of g.edges) insE.run(e.sourceId, e.targetId, e.type, JSON.stringify(e));
        this.db.exec('COMMIT');
      } catch (e) {
        try { this.db.exec('ROLLBACK'); } catch { /* already rolled back */ }
        throw e;
      }
      Logger.info(`[SqliteGraphStore] Graph saved to ${this.dbPath} (${g.nodes.size} nodes, ${g.edges.length} edges, one transaction).`);
    } catch (e: any) {
      Logger.error(`[SqliteGraphStore] save failed: ${e.message}`);
      throw e; // callers must not advance hash baselines after a failed graph commit
    }
  }

  /** The legacy JSON import (one-time): true when a playground.json was migrated in. */
  private importLegacyJson(): boolean {
    try {
      const legacy = path.join(path.dirname(this.dbPath), 'playground.json');
      if (!fs.existsSync(legacy)) return false;
      const raw = JSON.parse(fs.readFileSync(legacy, 'utf-8'));
      if (!Array.isArray(raw.nodes) || raw.nodes.length === 0) return false;
      const nodes = new Map<string, GraphNode>();
      for (const n of raw.nodes) nodes.set(n.id, n);
      this.setGraph({ nodes, edges: raw.edges || [] });
      void this.saveToDisk();
      Logger.info(`[SqliteGraphStore] Imported legacy playground.json (${nodes.size} nodes) into ${this.dbPath}.`);
      return true;
    } catch { return false; }
  }

  private hashFile(abs: string): FileState | null {
    try {
      const st = fs.statSync(abs);
      const hash = crypto.createHash('sha1').update(fs.readFileSync(abs)).digest('hex');
      const after = fs.statSync(abs);
      if (st.mtimeMs !== after.mtimeMs || st.ctimeMs !== after.ctimeMs || st.size !== after.size || st.ino !== after.ino) return null;
      return { hash, mtimeMs: st.mtimeMs, ctimeMs: st.ctimeMs, size: st.size };
    } catch { return null; }
  }

  captureFileState(projectRoot: string, rel: string): FileState | null {
    return this.hashFile(path.isAbsolute(rel) ? rel : path.join(projectRoot, rel));
  }

  recordedFiles(): Set<string> {
    if (!this.available || !this.db) return new Set();
    return new Set(this.db.prepare('SELECT path FROM file_hashes').all().map((row: any) => String(row.path)));
  }

  /**
   * Record the content hash of every file the graph currently indexes — the staleness
   * baseline. Call after a full or partial (re)index.
   */
  recordFileHashes(projectRoot: string, onlyPaths?: string[], expected?: ReadonlyMap<string, FileState>, deleted: readonly string[] = []): number {
    if (!this.available || !this.db) return 0;
    const paths = new Set<string>();
    if (onlyPaths) {
      for (const p of onlyPaths) paths.add(p.replace(/\\/g, '/'));
    } else {
      for (const n of this.getGraph().nodes.values()) {
        if (n.filePath) paths.add(n.filePath.replace(/\\/g, '/'));
      }
    }
    let recorded = 0;
    try {
      const ins = this.db.prepare('INSERT OR REPLACE INTO file_hashes (path, hash, mtime, size, ctime) VALUES (?, ?, ?, ?, ?)');
      this.db.exec('BEGIN IMMEDIATE');
      try {
        if (!onlyPaths) this.db.exec('DELETE FROM file_hashes');
        for (const rel of deleted) this.db.prepare('DELETE FROM file_hashes WHERE path = ?').run(rel);
        for (const rel of paths) {
          const st = this.hashFile(path.isAbsolute(rel) ? rel : path.join(projectRoot, rel));
          if (expected) {
            const parsed = expected.get(rel);
            if (!st || !parsed || st.hash !== parsed.hash || st.mtimeMs !== parsed.mtimeMs || st.ctimeMs !== parsed.ctimeMs || st.size !== parsed.size) continue;
          }
          if (st) { ins.run(rel, st.hash, st.mtimeMs, st.size, st.ctimeMs); recorded++; }
        }
        this.db.exec('COMMIT');
      } catch (e) {
        try { this.db.exec('ROLLBACK'); } catch { /* rolled back */ }
        throw e;
      }
    } catch { /* staleness degrades, queries don't */ }
    return recorded;
  }

  /**
   * Which indexed files changed since their recorded hash? mtime+size short-circuits
   * the untouched majority; only suspects get re-hashed. Deleted files are reported
   * separately so the indexer can prune their nodes.
   */
  staleFiles(projectRoot: string): { changed: string[]; deleted: string[] } {
    const changed: string[] = [];
    const deleted: string[] = [];
    if (!this.available || !this.db) return { changed, deleted };
    try {
      for (const r of this.db.prepare('SELECT path, hash, mtime, size, ctime FROM file_hashes').all()) {
        const rel = String(r.path);
        const abs = path.isAbsolute(rel) ? rel : path.join(projectRoot, rel);
        let st: fs.Stats;
        try { st = fs.statSync(abs); } catch (error: any) {
          if (error.code === 'ENOENT' || error.code === 'ENOTDIR') deleted.push(rel);
          else changed.push(rel); // unavailable is not proof of deletion
          continue;
        }
        if (r.ctime !== null && st.ctimeMs === Number(r.ctime) && st.mtimeMs === Number(r.mtime) && st.size === Number(r.size)) continue;
        const now = this.hashFile(abs);
        if (!now) { changed.push(rel); continue; }
        if (now.hash !== String(r.hash)) changed.push(rel);
        else {
          // touched but identical — refresh the stat baseline so it stays a fast path
          try { this.db.prepare('UPDATE file_hashes SET mtime = ?, size = ?, ctime = ? WHERE path = ?').run(now.mtimeMs, now.size, now.ctimeMs, rel); } catch { /* cosmetic */ }
        }
      }
    } catch { /* staleness degrades, queries don't */ }
    return { changed, deleted };
  }

  /** Drop every node (and its edges) belonging to one file — the per-file invalidation. */
  removeFileNodes(relPath: string, preserveHash = false): number {
    const rel = relPath.replace(/\\/g, '/');
    const toRemove: string[] = [];
    for (const [id, n] of this.getGraph().nodes.entries()) {
      const np = (n.filePath || '').replace(/\\/g, '/');
      if (np === rel || id === `file:${rel}` || (!np && (id.endsWith(`:${rel}`) || id.startsWith(`func:${rel}:`) || id.startsWith(`class:${rel}:`)))) toRemove.push(id);
    }
    this.removeNodes(toRemove);
    if (!preserveHash && this.available && this.db) {
      try { this.db.prepare('DELETE FROM file_hashes WHERE path = ?').run(rel); } catch { /* cosmetic */ }
    }
    return toRemove.length;
  }

  close(): void {
    try { this.db?.close(); } catch { /* closing */ }
    this.db = null;
    this.available = false;
  }
}

/**
 * The factory every boot path uses: SQLite store when node:sqlite or bun:sqlite exists, legacy
 * JSON store otherwise. Same directory family, same IGraphStore, zero caller changes.
 */
export function createGraphStore(projectRoot: string): GraphStore {
  const dir = path.join(stateDir('.breakglass', projectRoot), 'graph');
  const sq = new SqliteGraphStore(path.join(dir, 'graph.db'));
  if (sq.isAvailable()) return sq;
  return new GraphStore(path.join(dir, 'playground.json'));
}

import * as ts from 'typescript';
import * as path from 'path';
import * as fs from 'fs';
import { minimatch } from 'minimatch';
import { IGraphStore, GraphNode, GraphEdge, NodeType, EdgeType } from './models';
import { Logger } from '../utils';
import { GraphStore } from './graph.store';
import { publishFileGraph } from './file.graph';

export interface IStaticAnalyzer {
  analyzeProject(): void;
  analyzeSingleFile(absolutePath: string): void;
}

export class StaticAnalyzer implements IStaticAnalyzer {
  private excludeMatchers: ((filePath: string) => boolean)[] = [];

  constructor(
    private projectRoot: string,
    private store: IGraphStore,
    excludePatterns: string[] = []
  ) {
    this.setExcludePatterns(excludePatterns);
  }

  public setExcludePatterns(patterns: string[]) {
    this.excludeMatchers = patterns.map(p => (filePath: string) => minimatch(filePath, p));
  }

  private isExcluded(filePath: string): boolean {
    if (this.excludeMatchers.length === 0) return false;
    const relPath = this.getRelativePath(filePath);
    return this.excludeMatchers.some(match => match(relPath));
  }

  public setProjectRoot(newRoot: string) {
    this.projectRoot = newRoot;
  }

  /** Config discovery only: no Program, type checker or AST extraction for unchanged files. */
  public getProjectFiles(): string[] {
    const configPath = ts.findConfigFile(this.projectRoot, ts.sys.fileExists, 'tsconfig.json');
    if (!configPath) return [];
    const config = ts.readConfigFile(configPath, ts.sys.readFile);
    if (config.error) throw new Error(ts.flattenDiagnosticMessageText(config.error.messageText, '\n'));
    return ts.parseJsonConfigFileContent(config.config, ts.sys, this.projectRoot).fileNames
      .filter(file => !/\.d\.[cm]?ts$/i.test(file) && !this.isExcluded(file));
  }

  /** One compiler snapshot may serve a bounded batch; each refresh constructs a fresh one. */
  public createProgram(): ts.Program {
    const configPath = ts.findConfigFile(this.projectRoot, ts.sys.fileExists, 'tsconfig.json');
    if (!configPath) throw new Error(`Could not find a valid tsconfig.json at ${this.projectRoot}.`);
    const configFile = ts.readConfigFile(configPath, ts.sys.readFile);
    if (configFile.error) throw new Error(ts.flattenDiagnosticMessageText(configFile.error.messageText, '\n'));
    const parsedConfig = ts.parseJsonConfigFileContent(configFile.config, ts.sys, this.projectRoot);
    return ts.createProgram(parsedConfig.fileNames, parsedConfig.options);
  }

  public analyzeProject(): void {
    Logger.info(`[StaticAnalyzer] Initializing TS Program for: ${this.projectRoot}`);
    const program = this.createProgram();
    const typeChecker = program.getTypeChecker();

    const sourceFiles = program.getSourceFiles()
      .filter(sf => !sf.isDeclarationFile)
      .filter(sf => !this.isExcluded(sf.fileName));

    Logger.info(`[StaticAnalyzer] Parsing ${sourceFiles.length} source files...`);

    // Pass 1: Extract Nodes (Files, Classes, Functions)
    for (const sourceFile of sourceFiles) {
      this.extractNodes(sourceFile);
    }

    // Pass 2: Extract Edges (Imports, Calls)
    for (const sourceFile of sourceFiles) {
      this.extractEdges(sourceFile, typeChecker);
    }

    const nodesCount = this.store.getGraph().nodes.size;
    const edgesCount = this.store.getGraph().edges.length;
    Logger.info(`[StaticAnalyzer] Graph generation complete. Extracted ${nodesCount} nodes and ${edgesCount} wires.`);
  }

  public analyzeSingleFile(absolutePath: string, snapshot?: ts.Program) {
    const relPath = this.getRelativePath(absolutePath);
    // Prepare the replacement before publishing; failed parsing preserves the last good graph.
    const program = snapshot ?? this.createProgram();
    const typeChecker = program.getTypeChecker();

    const sourceFile = program.getSourceFile(absolutePath);
    if (!sourceFile) {
      throw new Error(`Could not find source file in TS Program: ${absolutePath}`);
    }

    const replacement = new GraphStore(':memory:');
    const extractor = new StaticAnalyzer(this.projectRoot, replacement);
    extractor.extractNodes(sourceFile);
    extractor.extractEdges(sourceFile, typeChecker);
    publishFileGraph(this.store, relPath, replacement.getGraph());

    Logger.info(`[StaticAnalyzer] Hot-reloaded AST for ${relPath}`);
  }

  private addNode(node: GraphNode) {
    this.store.addNode(node);
  }

  private addEdge(edge: GraphEdge) {
    this.store.addEdge(edge);
  }

  private getRelativePath(absolutePath: string): string {
    return path.relative(this.projectRoot, absolutePath);
  }

  /**
   * Source location of an AST node as 1-based, inclusive line numbers, plus the
   * declaration's first line as a short signature. Lets the graph point the agent at the
   * exact span of a symbol so it can read just that symbol instead of the whole file.
   */
  private locOf(node: ts.Node, sourceFile: ts.SourceFile): { startLine: number; endLine: number; signature: string } {
    const start = sourceFile.getLineAndCharacterOfPosition(node.getStart(sourceFile));
    const end = sourceFile.getLineAndCharacterOfPosition(node.getEnd());
    const declaration = node.getText(sourceFile);
    const firstLine = declaration.split('\n', 1)[0].trim();
    let signature = firstLine.length > 200 ? firstLine.slice(0, 197) + '...' : firstLine;
    // Detach the <=200 UTF-16 units from large bodies; sliced strings can retain source text.
    if (declaration.length > 4096) signature = Buffer.from(signature, 'utf16le').toString('utf16le');
    return { startLine: start.line + 1, endLine: end.line + 1, signature };
  }

  private extractNodes(sourceFile: ts.SourceFile) {
    const relPath = this.getRelativePath(sourceFile.fileName);
    const fileNodeId = `file:${relPath}`;

    // Add File Node
    this.addNode({
      id: fileNodeId,
      name: path.basename(sourceFile.fileName),
      type: 'FILE',
      filePath: relPath
    });

    const visit = (node: ts.Node) => {
      if (ts.isClassDeclaration(node) && node.name) {
        const className = node.name.text;
        const classId = `class:${relPath}:${className}`;
        this.addNode({
          id: classId,
          name: className,
          type: 'CLASS',
          filePath: relPath,
          ...this.locOf(node, sourceFile)
        });

        // Edge from File to Class
        this.addEdge({ sourceId: fileNodeId, targetId: classId, type: 'CONTAINS' });

        // Extract methods inside class
        ts.forEachChild(node, (member) => {
          if (ts.isMethodDeclaration(member) && member.name && ts.isIdentifier(member.name)) {
            const methodName = member.name.text;
            const methodId = `func:${relPath}:${className}.${methodName}`;
            this.addNode({
              id: methodId,
              name: methodName,
              type: 'FUNCTION',
              filePath: relPath,
              ...this.locOf(member, sourceFile)
            });
            this.addEdge({ sourceId: classId, targetId: methodId, type: 'CONTAINS' });
          }
        });

      } else if (ts.isFunctionDeclaration(node) && node.name) {
        const funcName = node.name.text;
        const funcId = `func:${relPath}:${funcName}`;
        this.addNode({
          id: funcId,
          name: funcName,
          type: 'FUNCTION',
          filePath: relPath,
          ...this.locOf(node, sourceFile)
        });

        // Edge from File to Function
        this.addEdge({ sourceId: fileNodeId, targetId: funcId, type: 'CONTAINS' });
      } else if (ts.isBlock(node)) {
        const blockId = `block:${relPath}:${node.pos}`;
        this.addNode({
          id: blockId,
          name: `Block@${node.pos}`,
          type: 'BLOCK',
          filePath: relPath
        });

        // Find parent container to link
        const parentId = this.findNearestContainerId(node.parent, relPath, fileNodeId);
        if (parentId) {
          this.addEdge({ sourceId: parentId, targetId: blockId, type: 'CONTAINS' });
        }
      } else if (ts.isVariableDeclaration(node) && ts.isIdentifier(node.name)) {
        const varName = node.name.text;
        const varId = `var:${relPath}:${varName}@${node.pos}`;
        this.addNode({
          id: varId,
          name: varName,
          type: 'VARIABLE',
          filePath: relPath,
          ...this.locOf(node, sourceFile)
        });

        const parentId = this.findNearestContainerId(node.parent, relPath, fileNodeId);
        if (parentId) {
          this.addEdge({ sourceId: parentId, targetId: varId, type: 'CONTAINS' });
          this.addEdge({ sourceId: parentId, targetId: varId, type: 'DECLARES_VARIABLE' });
        }
      } else if (ts.isStatement(node) && !ts.isBlock(node)) {
        const stmtId = `stmt:${relPath}:${node.pos}`;
        const stmtName = ts.SyntaxKind[node.kind];

        this.addNode({
          id: stmtId,
          name: `${stmtName}@${node.pos}`,
          type: 'STATEMENT',
          filePath: relPath
        });

        const parentId = this.findNearestContainerId(node.parent, relPath, fileNodeId);
        if (parentId) {
          this.addEdge({ sourceId: parentId, targetId: stmtId, type: 'CONTAINS' });
        }
      }

      ts.forEachChild(node, visit);
    };

    ts.forEachChild(sourceFile, visit);
  }

  private findNearestContainerId(node: ts.Node, relPath: string, defaultId: string): string {
    let current: ts.Node | undefined = node;
    while (current) {
      if (ts.isBlock(current)) return `block:${relPath}:${current.pos}`;
      if (ts.isFunctionDeclaration(current) && current.name) return `func:${relPath}:${current.name.text}`;
      if (ts.isMethodDeclaration(current) && current.name && ts.isIdentifier(current.name)) {
        const parent = current.parent;
        if (ts.isClassDeclaration(parent) && parent.name) {
          return `func:${relPath}:${parent.name.text}.${current.name.text}`;
        }
      }
      if (ts.isClassDeclaration(current) && current.name) return `class:${relPath}:${current.name.text}`;
      current = current.parent;
    }
    return defaultId;
  }

  // A checker owns compiler state; keep it scoped to extraction, never the long-lived analyzer.
  private extractEdges(sourceFile: ts.SourceFile, typeChecker: ts.TypeChecker) {
    const relPath = this.getRelativePath(sourceFile.fileName);
    const fileNodeId = `file:${relPath}`;

    const visit = (node: ts.Node) => {
      // Find the most granular container for this node
      const currentContainerId = this.findNearestContainerId(node, relPath, fileNodeId);

      // Detect Imports
      if (ts.isImportDeclaration(node)) {
        const moduleSpecifier = node.moduleSpecifier;
        if (ts.isStringLiteral(moduleSpecifier)) {
          const importPath = moduleSpecifier.text;

          // Heuristic: If it's a relative path, try to resolve to a file node
          if (importPath.startsWith('.')) {
            let resolvedExt = '';
            const absoluteImportDir = path.dirname(sourceFile.fileName);
            const resolvedPath = path.resolve(absoluteImportDir, importPath);

            // Basic resolution (very simplified, usually TS Compiler API does this better)
            if (fs.existsSync(resolvedPath + '.ts')) resolvedExt = '.ts';
            else if (fs.existsSync(path.join(resolvedPath, 'index.ts'))) resolvedExt = '/index.ts';

            if (resolvedExt) {
              const targetRelPath = this.getRelativePath(resolvedPath + resolvedExt);
              const targetNodeId = `file:${targetRelPath}`;
              this.addEdge({ sourceId: fileNodeId, targetId: targetNodeId, type: 'IMPORTS' });
            }
          }
        }
      }

      // Detect Function Calls
      if (ts.isCallExpression(node)) {
        const signature = typeChecker.getResolvedSignature(node);

        // --- Runtime Event Graph: Detect eventBus.emit and eventBus.on ---
        if (ts.isPropertyAccessExpression(node.expression)) {
          const propName = node.expression.name.text;
          if (propName === 'emit' || propName === 'on') {
            const firstArg = node.arguments[0];
            if (firstArg && ts.isStringLiteral(firstArg)) {
              const eventName = firstArg.text;
              const eventNodeId = `event:${eventName}`;

              this.addNode({
                id: eventNodeId,
                name: eventName,
                type: 'EVENT',
                filePath: '' // Events span across files
              });

              if (propName === 'emit') {
                this.addEdge({ sourceId: currentContainerId, targetId: eventNodeId, type: 'PUBLISHES_TO' });
              } else if (propName === 'on') {
                this.addEdge({ sourceId: currentContainerId, targetId: eventNodeId, type: 'SUBSCRIBES_TO' });
              }
            }
          }
        }

        if (signature) {
          const decl = signature.getDeclaration();
          if (decl && decl.getSourceFile()) {
            const targetFile = decl.getSourceFile();
            const targetRelPath = this.getRelativePath(targetFile.fileName);

            let targetId = '';
            if (ts.isFunctionDeclaration(decl) && decl.name) {
              targetId = `func:${targetRelPath}:${decl.name.text}`;
            } else if (ts.isMethodDeclaration(decl) && decl.name && ts.isIdentifier(decl.name)) {
              const parent = decl.parent;
              if (ts.isClassDeclaration(parent) && parent.name) {
                targetId = `func:${targetRelPath}:${parent.name.text}.${decl.name.text}`;
              }
            }

            if (targetId) {
              this.addEdge({ sourceId: currentContainerId, targetId: targetId, type: 'CALLS' });
            }
          }
        }
      }

      // Detect Variable Usage
      if (ts.isIdentifier(node)) {
        const symbol = typeChecker.getSymbolAtLocation(node);
        if (symbol && symbol.valueDeclaration) {
          const decl = symbol.valueDeclaration;
          if (ts.isVariableDeclaration(decl) && ts.isIdentifier(decl.name)) {
            const targetFile = decl.getSourceFile();
            const targetRelPath = this.getRelativePath(targetFile.fileName);
            const varId = `var:${targetRelPath}:${decl.name.text}@${decl.pos}`;

            // Avoid self-references (a declaration using itself in its init)
            if (currentContainerId !== varId) {
              this.addEdge({ sourceId: currentContainerId, targetId: varId, type: 'USES_VARIABLE' });
            }
          }
        }
      }

      ts.forEachChild(node, visit);
    };

    ts.forEachChild(sourceFile, visit);
  }
}

import * as fs from 'fs/promises';
import * as path from 'path';
import { GraphNode } from './models';
import { sliceLineRange } from '../tools/file-range';

// Single source of truth for "read just this symbol's source from disk". Used by the
// READ_SYMBOL verb, the context planner, and @symbol mentions so the file-read + line-slice
// path exists exactly once (no duplication).

/**
 * Read the on-disk source for a single graph node, sliced to its recorded line range and
 * numbered. `filePath` may be absolute or relative to `cwd`. Returns `{ error }` when the
 * node lacks a range/path or the file can't be read — callers decide how to surface it.
 */
export async function readSymbolSource(
  node: GraphNode,
  cwd: string
): Promise<{ text?: string; error?: string }> {
  if (!node.filePath) return { error: `${node.id} has no file path on record.` };
  if (node.startLine == null || node.endLine == null) {
    return { error: `${node.id} has no recorded line range — re-run /index to populate symbol ranges.` };
  }
  const full = path.isAbsolute(node.filePath) ? node.filePath : path.resolve(cwd, node.filePath);
  try {
    const content = await fs.readFile(full, 'utf8');
    return sliceLineRange(content, node.startLine, node.endLine);
  } catch (e: any) {
    if (e.code === 'ENOENT') {
      return { error: `file not found at ${node.filePath} — the graph may be stale, re-run /index.` };
    }
    return { error: e.message };
  }
}

import * as fs from 'fs';
import * as path from 'path';
import { minimatch } from 'minimatch';
import Parser from 'web-tree-sitter';
import { IGraphStore, GraphNode } from './models';
import { Logger, treeSitterRuntimeAvailable } from '../utils';

// M1 — tree-sitter multi-language backend. Indexes non-TS/JS languages (Python first) into
// the SAME graph model (FILE/CLASS/FUNCTION nodes + CONTAINS/CALLS edges) with line ranges,
// so the whole graph-native context engine (READ_SYMBOL, context packs, @mentions, blast
// gate) works on those repos too. tree-sitter gives node.startPosition/endPosition.row
// directly, so G1 line ranges come for free.
//
// NOTE: init/grammar-load are async (WASM), so this analyzer's methods are async — it fills
// the same role as the synchronous StaticAnalyzer but cannot share its exact sync signature.
// The indexer awaits it as a second, additive pass.

interface LangSpec {
  /** tree-sitter node type for a function/def. */
  funcType: string;
  /** tree-sitter node type for a class. */
  classType: string;
  /** call-expression node type. */
  callType: string;
}

// Per-language node-type map. Python first; the others are wired so adding them later is
// just confirming their node-type names (kept conservative — only what we emit today).
const LANGUAGES: Record<string, { wasm: string; spec: LangSpec }> = {
  '.py': {
    wasm: 'tree-sitter-python',
    spec: { funcType: 'function_definition', classType: 'class_definition', callType: 'call' },
  },
};

// Directories never worth indexing — dependencies, build output, caches, tool/IDE metadata. Matched
// by basename during the file walk. Kept broad on purpose: indexing a venv / site-packages / VS Code
// extensions folder is what balloons the graph into 100k+ junk nodes.
const IGNORED_DIRS = new Set([
  // VCS + our own
  '.git', '.hg', '.svn', '.breakglass',
  // JS / TS deps + build + caches
  'node_modules', 'bower_components', 'jspm_packages', 'dist', 'build', 'out', 'coverage',
  '.next', '.nuxt', '.svelte-kit', '.turbo', '.parcel-cache', '.cache', '.expo', '.yarn', '.pnpm-store',
  // Python
  '__pycache__', '.venv', 'venv', 'site-packages', '.tox', '.mypy_cache', '.pytest_cache',
  '.ipynb_checkpoints', '.eggs',
  // Rust / Go / Java / .NET / iOS / Dart
  'target', 'vendor', '.gradle', 'Pods', 'obj', 'DerivedData', '.dart_tool', '.cargo', '.rustup',
  // Tooling / IDE / infra
  '.idea', '.vscode', '.vscode-server', '.terraform', '.serverless',
  // macOS home heavyweights (so `/index ~` doesn't crawl the whole machine)
  'Library', 'Applications',
]);

function resolveGrammarWasm(name: string): string | null {
  try {
    return require.resolve(`tree-sitter-wasms/out/${name}.wasm`);
  } catch {
    return null;
  }
}

export class TreeSitterAnalyzer {
  private parser: Parser | null = null;
  private langCache: Map<string, Parser.Language | null> = new Map();
  private excludeMatchers: ((filePath: string) => boolean)[] = [];

  constructor(
    private projectRoot: string,
    private store: IGraphStore,
    excludePatterns: string[] = []
  ) {
    this.setExcludePatterns(excludePatterns);
  }

  public setProjectRoot(newRoot: string) { this.projectRoot = newRoot; }
  public setExcludePatterns(patterns: string[]) {
    this.excludeMatchers = patterns.map(p => (fp: string) => minimatch(fp, p));
  }

  /** Extensions this analyzer can index given the grammars actually present on disk. */
  public static supportedExtensions(): string[] {
    if (!treeSitterRuntimeAvailable()) return [];
    return Object.keys(LANGUAGES).filter(ext => resolveGrammarWasm(LANGUAGES[ext].wasm) !== null);
  }

  /** False when the wasm runtime isn't on disk (standalone binary) — callers must bail. */
  private async init(): Promise<boolean> {
    if (this.parser) return true;
    // Parser.init() without the wasm file aborts with an UNCATCHABLE unhandled rejection
    // (Emscripten) — never call it unless the runtime is really present.
    if (!treeSitterRuntimeAvailable()) {
      Logger.warn('[TreeSitter] wasm runtime not present — non-TS indexing disabled.');
      return false;
    }
    await Parser.init();
    this.parser = new Parser();
    return true;
  }

  private async languageFor(ext: string): Promise<Parser.Language | null> {
    if (this.langCache.has(ext)) return this.langCache.get(ext)!;
    const entry = LANGUAGES[ext];
    const wasmPath = entry ? resolveGrammarWasm(entry.wasm) : null;
    if (!wasmPath) { this.langCache.set(ext, null); return null; }
    try {
      const lang = await Parser.Language.load(wasmPath);
      this.langCache.set(ext, lang);
      return lang;
    } catch (e: any) {
      Logger.warn(`[TreeSitter] Failed to load grammar for ${ext}: ${e.message}`);
      this.langCache.set(ext, null);
      return null;
    }
  }

  private getRelativePath(absPath: string): string {
    return path.relative(this.projectRoot, absPath).replace(/\\/g, '/');
  }

  private isExcluded(relPath: string): boolean {
    return this.excludeMatchers.some(m => m(relPath));
  }

  /** Recursively collect indexable source files under projectRoot. */
  private collectFiles(dir: string, out: string[] = []): string[] {
    let entries: fs.Dirent[];
    try { entries = fs.readdirSync(dir, { withFileTypes: true }); } catch { return out; }
    for (const e of entries) {
      if (e.name.startsWith('.') && e.name !== '.') {
        if (IGNORED_DIRS.has(e.name)) continue;
      }
      const full = path.join(dir, e.name);
      if (e.isDirectory()) {
        if (IGNORED_DIRS.has(e.name)) continue;
        this.collectFiles(full, out);
      } else if (LANGUAGES[path.extname(e.name)]) {
        const rel = this.getRelativePath(full);
        if (!this.isExcluded(rel)) out.push(full);
      }
    }
    return out;
  }

  /** Discover supported paths without parsing their contents. */
  public getProjectFiles(): string[] {
    if (TreeSitterAnalyzer.supportedExtensions().length === 0) return [];
    return this.collectFiles(this.projectRoot);
  }

  /** Index every supported non-TS file under the project root into the shared graph. */
  public async analyzeProject(): Promise<void> {
    if (!(await this.init())) return;
    const files = this.collectFiles(this.projectRoot);
    if (files.length === 0) return;

    // Pass 1 — parse each file once, emit nodes + CONTAINS, and remember the tree so the
    // call-resolution pass doesn't re-parse. Build a name→ids map for CALLS resolution.
    const trees: { file: string; ext: string; root: Parser.SyntaxNode }[] = [];
    const nameToIds = new Map<string, string[]>();

    for (const file of files) {
      const ext = path.extname(file);
      const lang = await this.languageFor(ext);
      if (!lang) continue;
      let source: string;
      try { source = fs.readFileSync(file, 'utf8'); } catch { continue; }
      this.parser!.setLanguage(lang);
      const tree = this.parser!.parse(source);
      trees.push({ file, ext, root: tree.rootNode });
      this.extractNodes(tree.rootNode, file, ext, nameToIds);
    }

    // Pass 2 — resolve CALLS by callee name (a function defined exactly once in the project).
    for (const { file, ext, root } of trees) {
      this.extractCalls(root, file, ext, nameToIds);
    }

    Logger.info(`[TreeSitter] Indexed ${trees.length} file(s) across ${TreeSitterAnalyzer.supportedExtensions().join(', ')}.`);
  }

  /** Parse and index a single file (used by the live observer for incremental updates). */
  public async analyzeSingleFile(absolutePath: string): Promise<boolean> {
    const ext = path.extname(absolutePath);
    if (!LANGUAGES[ext]) return false;
    if (!(await this.init())) return false;
    const lang = await this.languageFor(ext);
    if (!lang) return false;
    let source: string;
    try { source = fs.readFileSync(absolutePath, 'utf8'); } catch { return false; }
    this.parser!.setLanguage(lang);
    const tree = this.parser!.parse(source);
    const nameToIds = new Map<string, string[]>();
    this.extractNodes(tree.rootNode, absolutePath, ext, nameToIds);
    this.extractCalls(tree.rootNode, absolutePath, ext, nameToIds);
    return true;
  }

  private signatureOf(node: Parser.SyntaxNode): string {
    const first = node.text.split('\n')[0].trim();
    return first.length > 200 ? first.slice(0, 197) + '...' : first;
  }

  private addSymbol(node: GraphNode, nameToIds: Map<string, string[]>) {
    this.store.addNode(node);
    const list = nameToIds.get(node.name) || [];
    list.push(node.id);
    nameToIds.set(node.name, list);
  }

  private extractNodes(root: Parser.SyntaxNode, file: string, ext: string, nameToIds: Map<string, string[]>) {
    const relPath = this.getRelativePath(file);
    const fileId = `file:${relPath}`;
    this.store.addNode({ id: fileId, name: path.basename(file), type: 'FILE', filePath: relPath });

    const spec = LANGUAGES[ext].spec;

    for (let i = 0; i < root.namedChildCount; i++) {
      const child = root.namedChild(i)!;

      if (child.type === spec.funcType) {
        const name = child.childForFieldName('name')?.text;
        if (!name) continue;
        const id = `func:${relPath}:${name}`;
        this.addSymbol({
          id, name, type: 'FUNCTION', filePath: relPath,
          startLine: child.startPosition.row + 1,
          endLine: child.endPosition.row + 1,
          signature: this.signatureOf(child),
        }, nameToIds);
        this.store.addEdge({ sourceId: fileId, targetId: id, type: 'CONTAINS' });
      } else if (child.type === spec.classType) {
        const className = child.childForFieldName('name')?.text;
        if (!className) continue;
        const classId = `class:${relPath}:${className}`;
        this.addSymbol({
          id: classId, name: className, type: 'CLASS', filePath: relPath,
          startLine: child.startPosition.row + 1,
          endLine: child.endPosition.row + 1,
          signature: this.signatureOf(child),
        }, nameToIds);
        this.store.addEdge({ sourceId: fileId, targetId: classId, type: 'CONTAINS' });

        // Methods inside the class body.
        const body = child.childForFieldName('body');
        if (body) {
          for (let j = 0; j < body.namedChildCount; j++) {
            const m = body.namedChild(j)!;
            if (m.type !== spec.funcType) continue;
            const mName = m.childForFieldName('name')?.text;
            if (!mName) continue;
            const mId = `func:${relPath}:${className}.${mName}`;
            this.addSymbol({
              id: mId, name: `${className}.${mName}`, type: 'FUNCTION', filePath: relPath,
              startLine: m.startPosition.row + 1,
              endLine: m.endPosition.row + 1,
              signature: this.signatureOf(m),
            }, nameToIds);
            this.store.addEdge({ sourceId: classId, targetId: mId, type: 'CONTAINS' });
          }
        }
      }
    }
  }

  /** The id of the nearest enclosing function/method for a node, or null at module scope. */
  private enclosingSymbolId(node: Parser.SyntaxNode, relPath: string, funcType: string, classType: string): string | null {
    let cur: Parser.SyntaxNode | null = node.parent;
    while (cur) {
      if (cur.type === funcType) {
        const name = cur.childForFieldName('name')?.text;
        if (!name) return null;
        // Method? walk up for an enclosing class to build Class.method.
        let p: Parser.SyntaxNode | null = cur.parent;
        while (p) {
          if (p.type === classType) {
            const cls = p.childForFieldName('name')?.text;
            return cls ? `func:${relPath}:${cls}.${name}` : `func:${relPath}:${name}`;
          }
          if (p.type === funcType) break; // nested function — stop at the inner one
          p = p.parent;
        }
        return `func:${relPath}:${name}`;
      }
      cur = cur.parent;
    }
    return null;
  }

  private extractCalls(root: Parser.SyntaxNode, file: string, ext: string, nameToIds: Map<string, string[]>) {
    const relPath = this.getRelativePath(file);
    const spec = LANGUAGES[ext].spec;

    const visit = (node: Parser.SyntaxNode) => {
      if (node.type === spec.callType) {
        const fn = node.childForFieldName('function');
        // Bare-name calls only (e.g. `helper(x)`); attribute calls (`a.b()`) are skipped to
        // avoid false matches — keeping CALLS precise rather than noisy.
        if (fn && fn.type === 'identifier') {
          const targets = nameToIds.get(fn.text);
          if (targets && targets.length === 1) {
            const callerId = this.enclosingSymbolId(node, relPath, spec.funcType, spec.classType);
            if (callerId && callerId !== targets[0]) {
              this.store.addEdge({ sourceId: callerId, targetId: targets[0], type: 'CALLS' });
            }
          }
        }
      }
      for (let i = 0; i < node.namedChildCount; i++) visit(node.namedChild(i)!);
    };
    visit(root);
  }
}

// The Bimax engine's one and only entry point.
//
// THERE IS NO CLI ANY MORE. This file used to be two front doors in one: the engine the desktop
// boots, and a `commander` program with flags (-p print mode, --acp, `bimax mcp`, terminal themes)
// left over from the Go/Bubble Tea TUI that was archived on 2026-09-06. The TUI was the CLI; once it
// left, the flags were parsing arguments no front-end ever passed, and print mode, the ACP agent and
// the MCP graph server were reachable only through them. All of it now lives in
// ~/Developer/bimax-archive at its repo path, cmp-verified, not deleted.
//
// What boots this module, and nothing else does:
//   • the desktop app — a worker thread inside the app's process, handed a MessagePort to speak on (the monolith,
//     record 64). Since M4 (2026-09-30) that is the only way: the separate engine process that spoke NDJSON on
//     stdin/stdout is gone, and an engine started without the app's port stops at once and says why.
//   • itself — a one-shot sub-agent carrying BIMAX_SUBAGENT_CONFIG.
// Every mode is chosen by ENVIRONMENT, never by argv, so there is no argument surface to drift.

// FIRST, before any other module runs: an engine hosted as a worker thread in the app's process (the monolith,
// record 64) gets a working folder of its own. Does nothing on the main thread (a sub-agent re-exec, a test).
import './engine/worker.folder';

// Buffer boot logs so they don't fight the front-end for stdout during boot
const bootLogs: string[] = [];
const originalConsoleLog = console.log;
const originalConsoleWarn = console.warn;
const originalConsoleError = console.error;

function startBootCapture() {
  console.log = (...args: any[]) => { bootLogs.push(args.join(' ')); };
  console.warn = (...args: any[]) => { bootLogs.push(`[WARN] ${args.join(' ')}`); };
  console.error = (...args: any[]) => { bootLogs.push(`[ERROR] ${args.join(' ')}`); };
}

// Start capturing IMMEDIATELY before imports trigger prints
startBootCapture();

import * as fs from 'fs';
import * as path from 'path';
import dotenv from 'dotenv';
import { stateDir } from './utils/state.dir';
import { redactSecrets } from './security/secret.scan';
import { loadGlobalEnv } from './engine/env.loader';
loadGlobalEnv();
dotenv.config();
// The egress perimeter goes up the instant the environment is readable and before any other module
// gets a chance to open a socket. It is what makes "nothing leaves the premises" a property of the
// process rather than a promise about sixteen call sites. See security/egress.perimeter.ts.
import { installEgressPerimeter } from './security/egress.perimeter';
installEgressPerimeter();
import { createContainer } from './core/container';
import { loadConfig } from './engine/config';
import { setCustomRoutingRules } from './engine/agentRouter';
import { engineEvents } from './engine/events';
import { setGlobalPatternStore, GenomePatternStore } from './genome/pattern.store';
import { setGlobalRecipeLoader, RecipeLoader } from './recipes/recipe.loader';
import { setContextManagerGraphStore } from './memory/context.manager';

// Sovereign mode is resolved BEFORE the container boots, so the very first request any subsystem
// makes is already governed. Resolving it later would leave a window in which a start-up probe
// (an update check, a telemetry handshake) leaves the premises before the mode is on — and a
// window is exactly what an air-gap claim cannot have. It reads BIMAX_SOVEREIGN /
// BIMAX_SOVEREIGN_ALLOW, which is where it always resolved from — the old --sovereign flags only
// ever set the same two values one layer higher up.
{
  const { isSovereign, sovereignAllowlist } = require('./security/sovereign');
  if (isSovereign()) {
    const { ledgerPath } = require('./security/egress.ledger');
    const allow = sovereignAllowlist();
    // Printed, not logged: an operator who asked for air-gap mode must be able to SEE that it took
    // effect, and the boot-log buffer is replayed too late to serve as confirmation.
    originalConsoleLog(
      `\n  SOVEREIGN MODE — external egress fails closed.\n` +
      `  Local: loopback + private LAN${allow.length ? ` + allowlist (${allow.join(', ')})` : ' (no allowlist)'}\n` +
      `  Shell: network denied at the kernel; refused outright where the OS cannot enforce it\n` +
      `  Ledger: ${ledgerPath()}   ·   /sovereign report for the audit trail\n`
    );
  }
}

// A crash note goes to Bimax's own log folder, scrubbed of keys. It used to be written to the working directory —
// the person's project folder — as `fatal-crash.log`, where nothing read it and it could land in their git status.
function writeCrashLog(msg: string): void {
  try {
    const dir = path.join(stateDir('.breakglass'), 'logs');
    fs.mkdirSync(dir, { recursive: true });
    fs.appendFileSync(path.join(dir, 'fatal-crash.log'), new Date().toISOString() + ' ' + redactSecrets(msg) + '\n');
  } catch { /* the process is exiting either way; the message still reaches stderr below */ }
}

// 4. Graceful Boot Error Handling (API-006)
process.on('uncaughtException', (err) => {
  // A broken pipe means our reader — the desktop — closed stdout/stderr, i.e. it exited. That's a
  // normal shutdown, not a crash: leave quietly with no scary fatal-crash.log or CRITICAL CRASH banner.
  if ((err as NodeJS.ErrnoException).code === 'EPIPE') { process.exit(0); }

  const msg = `[FATAL] Uncaught Exception: ${err.message}\n${err.stack}`;
  writeCrashLog(msg);

  if (bootLogs.length > 0) {
    originalConsoleError(msg);
  } else {
    engineEvents.emit('message', { id: `crash-${Date.now()}`, role: 'assistant', content: `❌ **CRITICAL CRASH:** ${err.message}`, timestamp: new Date() });
  }
  process.exit(1);
});

process.on('unhandledRejection', (reason, promise) => {
  const msg = `[FATAL] Unhandled Rejection at: ${promise}, reason: ${reason}`;
  writeCrashLog(msg);
  if (bootLogs.length > 0) {
    originalConsoleError(msg);
  } else {
    engineEvents.emit('message', { id: `crash-${Date.now()}`, role: 'assistant', content: `❌ **UNHANDLED REJECTION:** ${reason}`, timestamp: new Date() });
  }
});

async function main() {
  // Sub-agent SUBPROCESS mode: the engine re-execs itself with BIMAX_SUBAGENT_CONFIG to run a
  // sub-agent (worker_threads can't carry their deps inside a bundled engine; a full re-exec can).
  // Intercept before ANY engine boot — this process is a one-shot worker, not a front-end's engine.
  if (process.env.BIMAX_SUBAGENT_CONFIG) {
    const { runAsSubprocess } = await import('./engine/worker.entry');
    await runAsSubprocess();
    return;
  }

  // The engine speaks only over the port the app hands its worker (record 64, M4). Checked before config, storage or
  // indexing start: an engine started any other way stops having read no config and opened no store. (Loading the
  // modules above may already have created the empty `.breakglass/logs` folder — measured, nothing else.)
  const { engineWorkerPort } = await import('./protocol/port.host');
  const port = engineWorkerPort();
  if (!port) {
    originalConsoleError('[bimax] The engine runs only as a worker thread inside the Bimax app, which hands it a port to '
      + 'speak on (record 64). It was started without one, so it is stopping. To run it by hand, use '
      + '`npx electron app/scripts/verify-engine.js`.');
    process.exit(2);
  }

  // Honor the front-end's working directory BEFORE anything reads config or the graph. The engine's
  // own cwd is wherever it was spawned; the user's actual PROJECT is passed as BIMAX_CWD. This must
  // run before loadConfig(), or the project config (`<cwd>/.breakglass/config.json`) is read from
  // the wrong directory and cached — e.g. a repo's pinned model overriding the user's default.
  if (process.env.BIMAX_CWD) {
    try { process.chdir(process.env.BIMAX_CWD); } catch { /* keep current cwd on failure */ }
  }

  // Supervised launches see real startup phases on stdout instead of silence until `ready`.
  const { reportBootPhase } = await import('./protocol/boot.status');
  reportBootPhase('booting');

  reportBootPhase('loading_storage');
  const config = await loadConfig();
  if (config.customRoutingRules.length > 0) {
    setCustomRoutingRules(config.customRoutingRules);
  }

  const container = await createContainer(config);
  const { governor, graphStore } = container;
  // A night shift (FL5) runs unattended: set by the Bimax app for that task only, in its isolated checkout.
  governor.mode = config.dangerouslySkipPermissions ? 'bypass' : process.env.BIMAX_UNATTENDED === '1' ? 'unattended' : 'interactive';

  // Wire genome pattern store, recipe loader, and graph store for context injection
  setGlobalPatternStore(new GenomePatternStore(process.cwd()));
  setGlobalRecipeLoader(new RecipeLoader(process.cwd()));
  if (graphStore) setContextManagerGraphStore(graphStore);

  // The import below evaluates the whole command/persona tree — on a cold page cache that is the longest silent
  // stretch of boot, so report it or the front-end shows a hang between the container and `ready`.
  reportBootPhase('loading_interface');
  const { startHeadless } = await import('./protocol/headless.entry');
  // One entry file, one boot, one place a fix lands: a second entry for a second host is how desktop.runtime.ts and
  // the two env builders once drifted, with the copy nobody ran quietly losing features the other had.
  await startHeadless(container, config, { port });
  process.exit(0);
}

main().catch((e) => {
  // Restore console in case of crash
  console.log = originalConsoleLog;
  console.warn = originalConsoleWarn;
  console.error = originalConsoleError;
  console.error('Fatal error:', e);
  process.exit(1);
});

import * as fs from 'fs';
import * as path from 'path';
import * as url from 'url';
import { spawn, ChildProcess } from 'child_process';
import { LspServerSpec } from './registry';
import { Logger } from '../utils/logger';
import { withTimeoutOr } from '../utils/withTimeout';

// C1 — a minimal LSP client over stdio (vscode-jsonrpc). Spawns a language server, performs
// the initialize handshake, opens documents, and exposes the two enrichments the agent
// actually benefits from: DIAGNOSTICS (pushed by the server after didOpen) and REFERENCES
// (precise, better than the graph's name-based CALLS). One client per (server, root); kept
// alive and reused across calls. Everything degrades to [] on failure — never throws upward.
const rpc = require('vscode-jsonrpc/node');

const SEVERITY: Record<number, string> = { 1: 'error', 2: 'warning', 3: 'information', 4: 'hint' };

export interface LspDiagnostic { line: number; character: number; severity: string; message: string; }
export interface LspLocation { uri: string; line: number; character: number; }

export class LspClient {
  private proc: ChildProcess | null = null;
  private connection: any = null;
  private opened = new Map<string, number>();      // uri -> document version
  private diagnostics = new Map<string, any[]>();    // uri -> latest diagnostics
  private initialized = false;
  private startFailed = false;

  constructor(private spec: LspServerSpec, private rootPath: string) {}

  private uriFor(file: string): string { return url.pathToFileURL(file).toString(); }
  private langId(file: string): string {
    const e = path.extname(file).toLowerCase();
    return e === '.py' ? 'python' : e.startsWith('.ts') ? 'typescript' : 'javascript';
  }

  /** Lazily spawn + initialize the server. Returns false (cached) if it can't start. */
  async start(): Promise<boolean> {
    if (this.initialized) return true;
    if (this.startFailed) return false;
    try {
      this.proc = spawn(this.spec.command, this.spec.args, { cwd: this.rootPath, stdio: ['pipe', 'pipe', 'pipe'] });
    } catch (e: any) {
      Logger.warn(`[LSP] spawn failed for ${this.spec.command}: ${e.message}`);
      this.startFailed = true;
      return false;
    }
    if (!this.proc.pid || !this.proc.stdout || !this.proc.stdin) { this.startFailed = true; return false; }
    this.proc.on('error', () => { this.startFailed = true; });

    const reader = new rpc.StreamMessageReader(this.proc.stdout);
    const writer = new rpc.StreamMessageWriter(this.proc.stdin);
    this.connection = rpc.createMessageConnection(reader, writer);
    this.connection.onError(() => { /* non-fatal */ });
    this.connection.onNotification('textDocument/publishDiagnostics', (params: any) => {
      this.diagnostics.set(params.uri, params.diagnostics || []);
    });
    this.connection.listen();

    try {
      await this.connection.sendRequest('initialize', {
        processId: process.pid,
        rootUri: url.pathToFileURL(this.rootPath).toString(),
        capabilities: { textDocument: { publishDiagnostics: {}, references: {} } },
      });
      this.connection.sendNotification('initialized', {});
      this.initialized = true;
      return true;
    } catch (e: any) {
      Logger.warn(`[LSP] initialize failed for ${this.spec.command}: ${e.message}`);
      this.startFailed = true;
      return false;
    }
  }

  /** didOpen on first sight of a file, didChange thereafter (so the server sees latest text). */
  private syncDocument(file: string): string {
    const uri = this.uriFor(file);
    const text = fs.readFileSync(file, 'utf8');
    if (!this.opened.has(uri)) {
      this.opened.set(uri, 1);
      this.connection.sendNotification('textDocument/didOpen', {
        textDocument: { uri, languageId: this.langId(file), version: 1, text },
      });
    } else {
      const version = this.opened.get(uri)! + 1;
      this.opened.set(uri, version);
      this.connection.sendNotification('textDocument/didChange', {
        textDocument: { uri, version },
        contentChanges: [{ text }],
      });
    }
    return uri;
  }

  async diagnose(file: string, timeoutMs = 8000): Promise<LspDiagnostic[]> {
    if (!(await this.start())) return [];
    const uri = this.syncDocument(file);
    this.diagnostics.delete(uri); // wait for a fresh publish for this version
    const deadline = Date.now() + timeoutMs;
    while (!this.diagnostics.has(uri) && Date.now() < deadline) {
      await new Promise(r => setTimeout(r, 100));
    }
    return (this.diagnostics.get(uri) || []).map((d: any) => ({
      line: d.range.start.line,
      character: d.range.start.character,
      severity: SEVERITY[d.severity] || 'info',
      message: d.message,
    }));
  }

  async references(file: string, line0: number, char0: number, timeoutMs = 8000): Promise<LspLocation[]> {
    if (!(await this.start())) return [];
    const uri = this.syncDocument(file);
    try {
      const locs = await withTimeoutOr<any>(
        this.connection.sendRequest('textDocument/references', {
          textDocument: { uri }, position: { line: line0, character: char0 }, context: { includeDeclaration: true },
        }),
        timeoutMs,
        null,
      );
      if (!Array.isArray(locs)) return [];
      return locs.map((l: any) => ({ uri: l.uri, line: l.range.start.line, character: l.range.start.character }));
    } catch {
      return [];
    }
  }

  dispose(): void {
    try { this.connection?.dispose(); } catch { /* ignore */ }
    try { this.proc?.kill(); } catch { /* ignore */ }
    this.initialized = false;
  }
}

// Built-in engine: codebase-memory-mcp (DeusData/codebase-memory-mcp).
//
// A single static C binary that speaks MCP over stdio and exposes a 158-language
// code knowledge graph (callers/callees, cross-service call graphs, data-flow,
// clusters, cohesion, ADR hints) — a far richer replacement for Bimax's basic
// native graph. We "bake it in" without bloating the repo: the 269 MB binary is
// NOT committed (it's gitignored under vendor/*/bin/). Instead we provision it on
// first use exactly the way the upstream npm package does — fetch the pinned
// release archive for this platform, verify its checksum, extract, and cache it.
//
// The agent then gets the engine auto-registered as a built-in MCP server with
// zero manual setup. See memory [[bake_in_codemem_headroom]].

import * as fs from 'fs';
import * as os from 'os';
import * as path from 'path';
import * as https from 'https';
import * as crypto from 'crypto';
import { execFileSync } from 'child_process';
import { McpServerSpec } from '../config';
import { Logger } from '../../utils/logger';

const REPO = 'DeusData/codebase-memory-mcp';
const VERSION = '0.8.1';
export const SERVER_NAME = 'codebase-memory';

/** Repo/package root (where vendor/ lives). Works from both dist/ and src (tsx). */
function pkgRoot(): string {
  // dist/mcp/builtin/codebaseMemory.js  -> ../../.. = repo root
  // src/mcp/builtin/codebaseMemory.ts   -> ../../.. = repo root
  return path.resolve(__dirname, '..', '..', '..');
}

function binName(): string {
  return process.platform === 'win32' ? 'codebase-memory-mcp.exe' : 'codebase-memory-mcp';
}

function binDir(): string {
  return path.join(pkgRoot(), 'vendor', 'codebase-memory', 'bin');
}

export function binPath(): string {
  return path.join(binDir(), binName());
}

function getPlatform(): string {
  switch (process.platform) {
    case 'linux': return 'linux';
    case 'darwin': return 'darwin';
    case 'win32': return 'windows';
    default: throw new Error(`Unsupported platform: ${process.platform}`);
  }
}

function getArch(): string {
  switch (process.arch) {
    case 'arm64': return 'arm64';
    case 'x64': return 'amd64';
    default: throw new Error(`Unsupported architecture: ${process.arch}`);
  }
}

function assetName(): string {
  const platform = getPlatform();
  const arch = getArch();
  const ext = platform === 'windows' ? 'zip' : 'tar.gz';
  // Linux ships a fully-static "-portable" build; the standard linux binary links
  // glibc 2.38+ and fails on older distros. macOS/Windows have no such variant.
  const variant = platform === 'linux' ? '-portable' : '';
  return `codebase-memory-mcp-${platform}-${arch}${variant}.${ext}`;
}

function assertHttps(url: string): void {
  if (!url.startsWith('https://')) throw new Error(`Refusing non-HTTPS URL: ${url}`);
}

function download(url: string, dest: string): Promise<void> {
  assertHttps(url);
  return new Promise((resolve, reject) => {
    const follow = (u: string, depth: number) => {
      if (depth > 5) { reject(new Error('Too many redirects')); return; }
      assertHttps(u);
      https.get(u, (res) => {
        if (res.statusCode === 301 || res.statusCode === 302) {
          const loc = res.headers.location;
          if (!loc) { reject(new Error('Redirect with no location')); return; }
          follow(loc.startsWith('/') ? new URL(loc, u).href : loc, depth + 1);
          return;
        }
        if (res.statusCode !== 200) { reject(new Error(`HTTP ${res.statusCode} for ${u}`)); return; }
        const file = fs.createWriteStream(dest);
        res.pipe(file);
        file.on('finish', () => file.close(() => resolve()));
        file.on('error', reject);
      }).on('error', reject);
    };
    follow(url, 0);
  });
}

/** Verify the archive's sha256 against the release checksums.txt. Mismatch is fatal. */
async function verifyChecksum(archivePath: string, archiveName: string): Promise<void> {
  const url = `https://github.com/${REPO}/releases/download/v${VERSION}/checksums.txt`;
  const tmp = archivePath + '.checksums';
  try {
    await download(url, tmp);
    const line = fs.readFileSync(tmp, 'utf8').split('\n').find((l) => l.includes(archiveName));
    if (!line) return; // checksum line missing — non-fatal (pre-release etc.)
    const expected = line.split(/\s+/)[0];
    const actual = crypto.createHash('sha256').update(fs.readFileSync(archivePath)).digest('hex');
    if (expected !== actual) {
      throw new Error(`Checksum mismatch for ${archiveName}: expected ${expected}, got ${actual}`);
    }
    Logger.info('[codebase-memory] checksum verified');
  } catch (err: any) {
    if (String(err?.message).startsWith('Checksum mismatch')) throw err;
    // Network/unavailable — non-fatal, proceed without verification.
  } finally {
    try { fs.unlinkSync(tmp); } catch { /* ignore */ }
  }
}

let provisioning: Promise<string | null> | null = null;

/**
 * Ensure the codebase-memory binary exists locally, fetching it once on first use.
 * Returns the absolute binary path, or null if provisioning failed (best-effort).
 * Concurrent callers share a single in-flight download.
 */
export function ensureBinary(): Promise<string | null> {
  const target = binPath();
  if (fs.existsSync(target)) return Promise.resolve(target);
  if (provisioning) return provisioning;

  provisioning = (async () => {
    const archiveName = assetName();
    const url = `https://github.com/${REPO}/releases/download/v${VERSION}/${archiveName}`;
    const ext = archiveName.endsWith('.zip') ? 'zip' : 'tar.gz';
    fs.mkdirSync(binDir(), { recursive: true });
    const tmpDir = fs.mkdtempSync(path.join(os.tmpdir(), 'cbm-'));
    const tmpArchive = path.join(tmpDir, `cbm.${ext}`);
    try {
      Logger.info(`[codebase-memory] provisioning v${VERSION} for ${getPlatform()}/${getArch()} (one-time)...`);
      await download(url, tmpArchive);
      await verifyChecksum(tmpArchive, archiveName);
      if (ext === 'tar.gz') {
        execFileSync('tar', ['-xzf', tmpArchive, '-C', tmpDir, '--no-same-owner']);
      } else {
        execFileSync('powershell', ['-NoProfile', '-Command',
          `Expand-Archive -Path '${tmpArchive}' -DestinationPath '${tmpDir}' -Force`]);
      }
      const extracted = path.join(tmpDir, binName());
      // tar-slip defense: extracted path must stay inside tmpDir.
      if (!path.resolve(extracted).startsWith(path.resolve(tmpDir) + path.sep)) {
        throw new Error('Path traversal detected in archive');
      }
      fs.copyFileSync(extracted, target);
      fs.chmodSync(target, 0o755);
      // macOS: strip the Gatekeeper quarantine flag so the binary can be spawned.
      if (process.platform === 'darwin') {
        try { execFileSync('xattr', ['-d', 'com.apple.quarantine', target]); } catch { /* not quarantined */ }
      }
      Logger.info('[codebase-memory] binary ready');
      return target;
    } catch (err: any) {
      Logger.warn(`[codebase-memory] provisioning failed: ${err?.message || err}`);
      provisioning = null; // allow a later retry
      return null;
    } finally {
      try { fs.rmSync(tmpDir, { recursive: true, force: true }); } catch { /* ignore */ }
    }
  })();
  return provisioning;
}

/**
 * Built-in MCP server spec for codebase-memory, or null if disabled / unprovisionable.
 * Opt out with BIMAX_DISABLE_CODEBASE_MEMORY=1. Default invocation (no args) runs the
 * JSON-RPC stdio MCP server; cwd is inherited from the engine (the project root).
 */
export async function codebaseMemorySpec(): Promise<McpServerSpec | null> {
  if (process.env.BIMAX_DISABLE_CODEBASE_MEMORY === '1') return null;
  const bin = await ensureBinary();
  if (!bin) return null;
  return { name: SERVER_NAME, command: bin, args: [] };
}

import { grantMcpUi, revokeMcpUi } from './ui.grants';
import { mcpPresentation } from './presentation';
import { outcomeError, outcomeOk } from '../tools/outcome';
import { reportCapability } from '../core/capability.status';
import { ToolRegistry } from '../tools/tool.registry';
import { buildTool, BuiltTool } from '../tools/tool.factory';
import { IGovernor } from '../core/interfaces';
import { Logger } from '../utils/logger';
import { withRequestDeadline } from '../utils/request.deadline';
import { McpStderrTail } from './stderr';
import { McpToolCatalog } from './tool.catalog';
import { buildMcpResourceTools } from './resources';
import * as path from 'path';
import { pathToFileURL } from 'url';
import { recordMcpCall } from './stats';
import { McpServerSpec, expandSpecVars } from './config';
import { extractTaskRef, awaitTaskResult } from './tasks';
import { FileOAuthProvider, McpSignInRequired, openInBrowser, waitForAuthorizationCode } from './oauth';
import { engineEvents } from '../engine/events';

// The MCP SDK ships package "exports" maps that our classic TS moduleResolution can't follow
// for types; the dual-published CJS build resolves fine at runtime, so we require() it at the
// boundary and keep the SDK objects loosely typed inside this module only.
/* eslint-disable @typescript-eslint/no-require-imports */
const { Client } = require('@modelcontextprotocol/sdk/client/index.js');
const { StdioClientTransport } = require('@modelcontextprotocol/sdk/client/stdio.js');
const { StreamableHTTPClientTransport } = require('@modelcontextprotocol/sdk/client/streamableHttp.js');
const { SSEClientTransport } = require('@modelcontextprotocol/sdk/client/sse.js');
const { UnauthorizedError } = require('@modelcontextprotocol/sdk/client/auth.js');
const { ListRootsRequestSchema, ToolListChangedNotificationSchema } = require('@modelcontextprotocol/sdk/types.js');
/* eslint-enable @typescript-eslint/no-require-imports */

// Baseline env a spawned server needs to function as a process — nothing secret in it.
// v2 threat model, cut #4: a stdio MCP server used to inherit the FULL parent env, so every
// API key on the machine leaked to every community server (one compromised npm package away
// from exfiltration). Now a server sees this baseline + ONLY the env its spec declares.
const MCP_ENV_BASELINE = [
  'PATH', 'HOME', 'SHELL', 'TMPDIR', 'LANG', 'LC_ALL', 'TERM', 'USER', 'LOGNAME',
  // Node/npm plumbing many stdio servers (npx-launched) legitimately need:
  'NODE_ENV', 'NODE_PATH', 'NODE_OPTIONS', 'npm_config_cache', 'npm_config_prefix',
];

/** Scrubbed env for a stdio MCP server: toolchain baseline + the spec's declared env only. */
export function mcpChildEnv(spec: McpServerSpec): Record<string, string> {
  // Escape hatch for setups that rely on globally-exported keys instead of declaring them
  // per-server. Explicit and loud — inheriting everything is the insecure legacy behavior.
  if (!spec.forceScrubEnv && process.env.BIMAX_MCP_ENV_INHERIT === '1') {
    return { ...process.env as Record<string, string>, ...(spec.env || {}) };
  }
  const out: Record<string, string> = {};
  for (const k of MCP_ENV_BASELINE) {
    if (spec.forceScrubEnv && (k === 'NODE_OPTIONS' || k === 'NODE_PATH')) continue;
    if (process.env[k] !== undefined) out[k] = process.env[k]!;
  }
  return { ...out, ...(spec.env || {}) };
}

export interface OpenOptions {
  /** Cancels this connection attempt, including catalog discovery. */
  signal?: AbortSignal;
  /**
   * Complete an OAuth sign-in in the browser when the server asks for one. Off for every automatic
   * connect (boot, watchdog, self-heal): a sign-in then fails with McpSignInRequired instead of a
   * browser window appearing out of nowhere. On only for an explicit `/mcp login`.
   */
  interactiveSignIn?: boolean;
  /** The folder offered to servers that ask for MCP roots. Defaults to the workspace. */
  root?: string;
}

/**
 * A client that answers `roots/list` with the workspace folder. Filesystem-style servers scope
 * themselves to the client's roots when it offers them; with `capabilities: {}` they fell back to
 * command-line paths, which a pasted config from a README usually leaves as placeholders.
 */
function newClient(root: string): any {
  const client = new Client({ name: 'bimax', version: '1.0.0' }, { capabilities: { roots: { listChanged: false } } });
  client.setRequestHandler(ListRootsRequestSchema, async () => ({
    roots: [{ uri: pathToFileURL(root).href, name: path.basename(root) || root }],
  }));
  return client;
}

/** SDK initialize failure and our cleanup can close concurrently; both must await one close. */
function ownTransportClose(transport: any): any {
  const close = transport.close.bind(transport);
  let closing: Promise<void> | undefined;
  transport.close = () => closing ??= Promise.resolve().then(close);
  return transport;
}

/**
 * How long a server may take to answer the handshake. A launcher that downloads the server first
 * (`npx -y`, `uvx`, `docker run`) routinely takes longer than 30s on its first run, which failed
 * the server on exactly the machine that had just added it.
 */
export function connectTimeoutMs(spec: McpServerSpec, env: NodeJS.ProcessEnv = process.env): number {
  const configured = Number(env.BIMAX_MCP_CONNECT_TIMEOUT_MS);
  if (Number.isFinite(configured) && configured >= 1000) return Math.min(configured, 10 * 60_000);
  const launcher = path.basename(String(spec.command || ''));
  if (!spec.url && /^(npx|uvx|uv|bunx|pnpx|pnpm|pipx|docker|podman|deno)$/.test(launcher)) return 90_000;
  return 30_000;
}

function isUnauthorized(e: any): boolean {
  return e instanceof UnauthorizedError || e?.name === 'UnauthorizedError' || e?.code === 401 || e?.status === 401
    || /\b401\b|unauthori[sz]ed/i.test(String(e?.message || ''));
}

/**
 * Open a transport+client for a spec. Local (stdio) specs launch a command; remote specs
 * connect to a URL — trying Streamable HTTP first, then falling back to SSE (older hosted
 * servers only speak SSE). Returns a connected client or throws.
 */
export async function openClient(rawSpec: McpServerSpec, options: OpenOptions = {}): Promise<any> {
  options.signal?.throwIfAborted();
  const { spec, missing } = expandSpecVars(rawSpec);
  if (missing.length) {
    throw new Error(`MCP '${spec.name}' needs ${missing.join(', ')}, which ${missing.length > 1 ? 'are' : 'is'} not set. ` +
      `Add ${missing.length > 1 ? 'them' : 'it'} to ~/.breakglass/.env (or the server's "env"), then run /mcp reconnect ${spec.name}.`);
  }
  const root = options.root || process.env.WORKSPACE_ROOT || process.cwd();
  const timeoutMs = connectTimeoutMs(spec);

  if (spec.url) return openRemote(spec, root, timeoutMs, options.interactiveSignIn === true, options.signal);

  const client = newClient(root);
  // `stderr: 'pipe'` is critical: the SDK default is 'inherit', which dumps the child server's
  // stderr straight into our Ink TUI (corrupting the display). Piping keeps it off the terminal,
  // and we drain it into the logger — and into the failure reason when a server exits on startup.
  const transport = ownTransportClose(new StdioClientTransport({
    command: spec.command,
    args: spec.args || [],
    // Scrubbed: baseline + declared env only — a server missing a key should have it
    // declared in its spec (or set BIMAX_MCP_ENV_INHERIT=1 to accept the legacy leak).
    env: mcpChildEnv(spec),
    stderr: 'pipe',
  }));

  const stderrTail = new McpStderrTail();
  // The SDK exposes its pipe before start(). Draining only after the handshake can
  // deadlock a launcher that fills stderr before it sends its initialize response.
  transport.stderr?.on('data', (data: Buffer) => {
    const text = stderrTail.append(data);
    if (text) Logger.warn(`[MCP:${spec.name}] ${text.slice(-4096).trim()}`);
  });

  try {
    await withRequestDeadline(timeoutMs, options.signal,
      () => new Error(`MCP '${spec.name}' (stdio) timed out after ${timeoutMs}ms`),
      (signal, remainingMs) => client.connect(transport, { signal, timeout: remainingMs() }));
    return client;
  } catch (e: any) {
    // openClient has not returned yet, so connectAndRegister cannot own cleanup.
    // Close here even when the handshake timed out after spawning a child.
    try { await client.close(); } catch { /* preserve the startup failure */ }
    const detail = stderrTail.text().trim();
    if (detail) {
      const lastLines = detail.split('\n').filter(Boolean).slice(-3).join(' ');
      throw new Error(`${e?.message || e} — server said: ${lastLines}`, { cause: e });
    }
    throw e;
  }
}

async function openRemote(spec: McpServerSpec, root: string, timeoutMs: number, interactive: boolean, signal?: AbortSignal): Promise<any> {
  const url = new URL(spec.url!);
  const headers = spec.headers || undefined;
  // A server configured with its own Authorization header uses that token; OAuth is for the rest.
  const staticAuth = !!headers && Object.keys(headers).some(k => k.toLowerCase() === 'authorization');
  let authorizationUrl: URL | null = null;
  const provider = staticAuth ? undefined : new FileOAuthProvider(url.href, (u) => { authorizationUrl = u; });
  const transportOptions = { ...(headers ? { requestInit: { headers } } : {}), ...(provider ? { authProvider: provider } : {}) };
  const makeTransport = (kind: 'http' | 'sse') => ownTransportClose(kind === 'sse'
    ? new SSEClientTransport(url, transportOptions)
    : new StreamableHTTPClientTransport(url, transportOptions));

  const attempt = async (kind: 'http' | 'sse') => {
    const client = newClient(root);
    const transport = makeTransport(kind);
    try {
      await withRequestDeadline(timeoutMs, signal,
        () => new Error(`MCP '${spec.name}' (${kind === 'sse' ? 'SSE' : 'HTTP'}) timed out after ${timeoutMs}ms`),
        (requestSignal, remainingMs) => client.connect(transport, { signal: requestSignal, timeout: remainingMs() }));
      return client;
    } catch (e: any) {
      try { await client.close?.(); } catch { /* failed transports are best-effort cleanup */ }
      signal?.throwIfAborted();
      if (provider && isUnauthorized(e)) {
        if (!interactive || !authorizationUrl) throw new McpSignInRequired(spec.name);
        return signInThenConnect(kind, transport);
      }
      throw e;
    }
  };

  // The browser round trip for an explicit login. The listener is already up (see below); the SDK
  // has registered the client, stored the PKCE verifier and produced the authorization URL.
  let listener: ReturnType<typeof waitForAuthorizationCode> | null = null;
  const signInThenConnect = async (kind: 'http' | 'sse', transport: any) => {
    engineEvents.emit('status', `MCP '${spec.name}': finish signing in in your browser…`);
    const code = await withRequestDeadline(5 * 60_000, signal,
      () => new Error('MCP sign-in timed out after 5 minutes.'), async requestSignal => {
        await openInBrowser(authorizationUrl!);
        requestSignal.throwIfAborted();
        return listener!.code;
      });
    await withRequestDeadline(timeoutMs, signal,
      () => new Error(`MCP '${spec.name}' authentication timed out after ${timeoutMs}ms`),
      () => transport.finishAuth(code));
    const client = newClient(root);
    try {
      await withRequestDeadline(timeoutMs, signal,
        () => new Error(`MCP '${spec.name}' (after sign-in) timed out after ${timeoutMs}ms`),
        (requestSignal, remainingMs) => client.connect(makeTransport(kind), { signal: requestSignal, timeout: remainingMs() }));
    } catch (error) {
      try { await client.close(); } catch { /* preserve the startup error */ }
      throw error;
    }
    engineEvents.emit('status', `MCP '${spec.name}': signed in.`);
    return client;
  };

  try {
    if (interactive && provider) {
      listener = waitForAuthorizationCode(() => provider.expectedState());
      await listener.ready;
    }
    if (spec.type === 'sse') return await attempt('sse');
    try {
      return await attempt('http');
    } catch (httpErr: any) {
      signal?.throwIfAborted();
      // A sign-in need is not a transport mismatch: falling back to SSE would only hide it.
      if (httpErr instanceof McpSignInRequired || isUnauthorized(httpErr)) throw httpErr;
      Logger.warn(`[MCP] '${spec.name}' HTTP transport failed (${httpErr.message}); trying SSE.`);
      return await attempt('sse');
    }
  } finally {
    listener?.close();
  }
}

/**
 * Coerce a single value to the type its JSON Schema declares. Only converts the safe, common cases
 * a weak model gets wrong — string→number/integer and string→boolean — and recurses into arrays and
 * nested objects. Anything that doesn't cleanly convert is left untouched so we never corrupt input.
 */
function coerceValueToSchema(value: any, schema: any): any {
  if (!schema || value == null) return value;
  // JSON Schema `type` may be a string or an array of allowed types; normalize to a set.
  const types: string[] = Array.isArray(schema.type) ? schema.type : schema.type ? [schema.type] : [];

  if ((types.includes('number') || types.includes('integer')) && typeof value === 'string') {
    const trimmed = value.trim();
    if (trimmed !== '' && !isNaN(Number(trimmed))) {
      const n = Number(trimmed);
      return types.includes('integer') && !types.includes('number') ? Math.trunc(n) : n;
    }
  }
  if (types.includes('boolean') && typeof value === 'string') {
    const l = value.trim().toLowerCase();
    if (l === 'true') return true;
    if (l === 'false') return false;
  }
  if (types.includes('array') && Array.isArray(value) && schema.items) {
    return value.map((v) => coerceValueToSchema(v, schema.items));
  }
  if (types.includes('object') && value && typeof value === 'object' && schema.properties) {
    return coerceArgsToSchema(value, schema);
  }
  return value;
}

/** Coerce each property of an args object to the types its tool input schema declares. */
export function coerceArgsToSchema(args: any, schema: any): any {
  if (!schema || !schema.properties || !args || typeof args !== 'object' || Array.isArray(args)) return args;
  const out: any = { ...args };
  for (const [key, propSchema] of Object.entries<any>(schema.properties)) {
    if (key in out) out[key] = coerceValueToSchema(out[key], propSchema);
  }
  return out;
}

export interface ConnectedMcp {
  name: string;
  client: any;
  toolNames: string[];
  /** The exact spec this connection was opened with — lets the watchdog/healer reconnect a server
   *  that isn't in any config file (built-ins, tests) without a config round-trip. */
  spec: McpServerSpec;
  /** Retire tools synchronously, then close the transport. Safe to call repeatedly. */
  dispose?: () => Promise<void>;
}

/** List every page and return a stable order, as required by the MCP tools contract. */
export async function listAllMcpTools(client: any, maxPages = 32, maxTools = 2048,
  requestOptions?: () => { signal: AbortSignal; timeout: number }): Promise<any[]> {
  const tools: any[] = [];
  let cursor: string | undefined;
  for (let page = 0; page < maxPages; page++) {
    const params = cursor ? { cursor } : undefined;
    const listed = await (requestOptions ? client.listTools(params, requestOptions()) : client.listTools(params));
    if (Array.isArray(listed?.tools)) tools.push(...listed.tools);
    if (tools.length > maxTools) throw new Error(`MCP tool catalog exceeds ${maxTools} entries`);
    const next = typeof listed?.nextCursor === 'string' && listed.nextCursor ? listed.nextCursor : undefined;
    if (!next) break;
    cursor = next;
    if (page === maxPages - 1) throw new Error(`MCP tool catalog exceeds ${maxPages} pages`);
  }
  return tools.sort((a, b) => String(a?.name || '').localeCompare(String(b?.name || '')));
}

/**
 * Is this text block just a re-serialization of the same structured payload?
 *
 * Key order is not normalized: a server emits both fields from one object, so they agree on order,
 * and canonicalizing would make two genuinely different payloads look identical. Only formatting is
 * neutralized, which is the difference this is meant to see through.
 */
function sameJsonPayload(text: string, structured: unknown): boolean {
  try {
    return JSON.stringify(JSON.parse(text)) === JSON.stringify(structured);
  } catch {
    return false; // not JSON at all — a real summary, keep it
  }
}

/** Flatten an MCP tool result's content array into a plain string for the agent. */
export function contentToString(result: any): string {
  if (!result) return '';
  const content = result.content;
  if (Array.isArray(content)) {
    const rendered = content
      .map((c: any) => {
        if (c?.type === 'text') return c.text;
        if (c?.type === 'resource') return c.resource?.text || (c.resource ? JSON.stringify(c.resource) : '[resource content]');
        if (c?.type === 'image') return `[image content: ${c.mimeType || 'unknown type'}, ${c.data?.length || 0} encoded bytes]`;
        return c?.type ? `[${c.type} content]` : '';
      })
      .filter(Boolean)
      .join('\n');
    if (result.structuredContent !== undefined) {
      const structured = JSON.stringify(result.structuredContent, null, 2);
      if (!rendered) return structured;
      // MCP lets a server answer in both fields, and the spec ENCOURAGES mirroring the structured
      // payload into a text block for clients that cannot read `structuredContent`. Our own
      // `mac_control` does exactly that, so every computer-use result was being handed to the model
      // twice — an observe carrying 40+ elements paid for its whole element list, its guidance
      // prose and its screenshot metadata a second time, in the same turn that a small model has to
      // plan the next action from. Emit one copy when they are the same payload.
      //
      // Compared parsed, not textually: the two differ in whitespace by construction (the text
      // block is the server's own formatting, this one is 2-space). A server that puts a genuine
      // human summary in text and data in structured is NOT the same payload and keeps both.
      if (sameJsonPayload(rendered, result.structuredContent)) return structured;
      return `${rendered}\n${structured}`;
    }
    return rendered;
  }
  return typeof result === 'string' ? result : JSON.stringify(result);
}

/** Does this error mean the transport/process is gone (vs. the tool itself failing)? */
export function isDeadConnectionError(e: any): boolean {
  const msg = String(e?.message || e);
  return /connection closed|not connected|transport (?:closed|error)|EPIPE|ECONNRESET|write after end/i.test(msg);
}

/**
 * A healer the manager injects: given a server name, try to bring it back and return the FRESH
 * client (or null). Only an explicitly read-only tool may retry after a lost response;
 * unannotated or destructive operations retain unknown completion without replay.
 */
export type McpHealer = (serverName: string) => Promise<any | null>;

/**
 * Acting on the host computer is outside the code-only Bimax product boundary, even when an
 * arbitrary MCP server advertises the old tool name under a different server id.
 *
 * This and `approvalHandledByMotionProvider` below are the two live re-entry points for Bimax
 * Motion: `grep -rn Motion src/` finds every seam the archived provider has to meet. The
 * IDENTIFIERS carry the product's own vocabulary; the STRINGS deliberately do not. `mac_control`,
 * `computer_control`, `computer` and the `bimax-mac` server id are what the provider in
 * ~/Developer/bimax-archive actually registers over MCP, so renaming them here would not rename
 * anything — it would only stop this gate recognising the thing it exists to refuse. They change
 * when the provider changes, on the same commit, and not before.
 */
export function isDisabledMotionToolName(name: string): boolean {
  return /^(?:mac_control|computer_control|computer)$/i.test(String(name || '').trim());
}

/**
 * Bimax for Mac owns approval for its single native Computer Use entrypoint.
 *
 * A Control Mac instruction is explicitly selected in the desktop composer, then the provider
 * applies its resolved-target policy, sensitive-surface blocks and takeover gate to every action.
 * Sending that same entrypoint through the terminal engine's generic external-tool governor made
 * one task ask "Run mac_control?" before every observation and click. That was duplicate consent,
 * not an additional safety boundary. Keep every other MCP tool fail-closed.
 */
export function approvalHandledByMotionProvider(serverName: string, toolName: string): boolean {
  return serverName === 'bimax-mac' && toolName === 'mac_control';
}

export function mcpToolCallRequest(
  _serverName: string,
  toolName: string,
  args: Record<string, unknown>,
): Record<string, unknown> {
  // This used to attach a signed `_meta.bimaxTrustedPlan` envelope for the app-owned `mac_control`
  // entrypoint. Bimax is a code-only agentic IDE (see archive/computer-use/): no Computer Use
  // provider is ever registered, and `isDisabledMotionToolName` above refuses `mac_control`
  // at registration, so the envelope had no reachable consumer. Keep the request shape plain.
  return { name: toolName, arguments: args };
}

/**
 * Connect to one MCP server (stdio) and register each of its tools into the registry as a
 * native-looking `mcp__<server>__<tool>` tool, governed like any other. Returns the
 * connection (for later close), or null if the server failed to start — never throws, so a
 * bad server never blocks boot.
 */
export async function connectAndRegister(
  spec: McpServerSpec,
  registry: ToolRegistry,
  governor: IGovernor,
  onError?: (message: string) => void,
  healer?: McpHealer,
  options: OpenOptions = {},
): Promise<ConnectedMcp | null> {
  let client: any;
  const catalog = new McpToolCatalog(registry);
  const lifetime = new AbortController();
  let catalogClosed = false;
  let closing: Promise<void> | undefined;
  const closeClient = (): Promise<void> => {
    if (!client) return Promise.resolve();
    return closing ??= Promise.resolve().then(() => client.close()).catch(() => { /* best-effort */ });
  };
  const dispose = (): Promise<void> => {
    revokeMcpUi(lifetime);
    lifetime.abort(new Error(`MCP '${spec.name}' connection retired.`));
    catalog.clear();
    options.signal?.removeEventListener('abort', cancel);
    return closeClient();
  };
  const cancel = () => { void dispose(); };
  options.signal?.addEventListener('abort', cancel, { once: true });
  if (options.signal?.aborted) cancel();
  const signalFor = (context: any): AbortSignal => {
    lifetime.signal.throwIfAborted();
    return context?.signal ? AbortSignal.any([lifetime.signal, context.signal]) : lifetime.signal;
  };

  const buildMcpTool = (t: any): BuiltTool | null => {
    if (isDisabledMotionToolName(String(t.name || ''))) {
      Logger.warn(`[MCP] Skipping disabled Computer Use tool '${spec.name}/${t.name}'.`);
      return null;
    }
    const toolName = `mcp__${spec.name}__${t.name}`;
    const built: BuiltTool = buildTool({
      name: toolName,
      description: `[MCP:${spec.name}] ${t.description || t.name}`,
      schema: t.inputSchema || { type: 'object', properties: {} },
      isDestructive: true, // external tools are fail-closed under the Governor
      approvalHandledInternally: approvalHandledByMotionProvider(spec.name, String(t.name || '')),
      execute: async (args: any, context?: any) => {
        lifetime.signal.throwIfAborted();
        // Weak models routinely emit numbers/booleans as strings ("1", "true"). MCP servers
        // validate strictly (zod) and reject those, so coerce each arg to its declared schema
        // type first. Native tools tolerate strings already; MCP is where strict validation bites.
        const coerced = coerceArgsToSchema(args || {}, t.inputSchema);
        const timeoutMs = callTimeoutMs();
        const started = Date.now();
        try {
          let callClient = client;
          const call = mcpToolCallRequest(spec.name, String(t.name || ''), coerced);
          // A read-only heal replaces and retires this connection while the original call
          // transfers to the fresh client. Keep the caller's Stop signal across that transfer.
          const res = await withRequestDeadline(timeoutMs, context?.signal,
            () => new Error(`MCP tool '${spec.name}/${t.name}' timed out after ${timeoutMs}ms`), async (signal, remainingMs) => {
            let result: any;
            try {
              result = await callClient.callTool(call, undefined, { signal, timeout: remainingMs() });
            } catch (e: any) {
              // Self-heal: a crashed/expired server shows up as a dead transport, not a tool error.
              // Reconnect once and retry on the fresh client — the retry is a direct client call
              // (never back through the registry), so a still-dead server can't recurse.
              signal.throwIfAborted();
              if (!healer || !isDeadConnectionError(e)) throw e;
              // A broken reply does not establish whether the server acted. Only
              // explicitly read-only tools may replay; annotations grant no approval.
              if (t.annotations?.readOnlyHint !== true || t.annotations?.destructiveHint === true) {
                throw new Error(`MCP tool '${spec.name}/${t.name}' lost its connection; completion is unknown. It was not replayed. Reconnect and inspect the actual state before retrying.`, { cause: e });
              }
              reportCapability({ id: `mcp:${spec.name}`, label: `MCP ${spec.name}`, state: 'unavailable',
                reason: 'The connection stopped responding during an operation.', impact: 'The operation requires a reconnect.',
                action: 'Bimax is attempting its bounded reconnect.' });
              Logger.warn(`[MCP] '${spec.name}' connection dead mid-call (${e?.message}); reconnecting to retry.`);
              const fresh = await healer(spec.name);
              remainingMs();
              if (!fresh) throw e;
              callClient = fresh;
              result = await callClient.callTool(call, undefined, { signal, timeout: remainingMs() });
            }
            // MCP Tasks extension: a task-shaped response means the server accepted the work
            // and is running it asynchronously — poll it to completion (within the remaining
            // call budget) and substitute the real result, so the agent never sees the stub.
            remainingMs();
            const taskRef = extractTaskRef(result);
            if (taskRef) {
              result = await awaitTaskResult(callClient, spec.name, t.name, taskRef, remainingMs(), signal);
            }
            remainingMs();
            return result;
          });
          const text = contentToString(res);
          recordMcpCall(spec.name, t.name, Date.now() - started, res?.isError ? text : undefined);
          const outcome = res?.isError ? outcomeError('unknown', `MCP tool ${t.name} reported an error: ${text}`) : outcomeOk(text);
          outcome.presentation = mcpPresentation(spec.name, t, args, res).map(part => part.kind !== 'mcp-app' ? part : grantMcpUi(part, {
            owner: lifetime, alive: () => !lifetime.signal.aborted && !catalogClosed && registry.getTool(toolName) === built,
            read: async () => {
              const response: any = await withRequestDeadline(10_000, lifetime.signal, () => new Error('Tool UI resource timed out.'), (signal, remaining) => client.readResource({uri:part.resourceUri},{signal,timeout:remaining()}));
              const resource = response?.contents?.find((c:any) => c.uri===part.resourceUri && typeof c.text==='string' && c.mimeType?.startsWith('text/html'));
              if (!resource || Buffer.byteLength(resource.text)>192*1024) throw new Error('Tool UI must be a bundled HTML resource of at most 192 KiB.');
              return {html:resource.text,input:part.input,result:part.result};
            },
            call: async (name, input, signal) => {
              if (name!==t.name || t._meta?.ui?.visibility && !t._meta.ui.visibility.includes('app')) throw new Error('This tool is not available to its UI.');
              let outcome: any;
              const text = await built.execute(input,{signal,reportOutcome:(value:any)=>{outcome=value;}});
              return {content:[{type:'text',text:String(text)}],...(outcome?.presentation?.find((p:any)=>p.kind==='data') ? {structuredContent:outcome.presentation.find((p:any)=>p.kind==='data').value} : {}),isError:outcome?.status!=='ok'};
            },
          }));
          return outcome;
        } catch (e: any) {
          recordMcpCall(spec.name, t.name, Date.now() - started, e?.message || String(e));
          throw e;
        }
      },
    }, governor);
    return built;
  };

  try {
    client = await openClient(spec, { ...options, signal: lifetime.signal });
    lifetime.signal.throwIfAborted();
    // Transport loss stops catalog writes; it does not revoke read-only self-healing.
    const onclose = client.onclose;
    client.onclose = () => { catalogClosed = true; onclose?.(); };
    const caps = typeof client.getServerCapabilities === 'function' ? client.getServerCapabilities() : null;
    const resources = caps?.resources ? buildMcpResourceTools(client, spec.name, governor, callTimeoutMs, signalFor) : [];
    const readCatalog = async (): Promise<BuiltTool[]> => {
      const timeoutMs = connectTimeoutMs(spec);
      const listed = caps?.tools ? await withRequestDeadline(timeoutMs, lifetime.signal,
        () => new Error(`MCP '${spec.name}' tool catalog timed out after ${timeoutMs}ms`),
        (signal, remainingMs) => listAllMcpTools(client, 32, 2048, () => ({ signal, timeout: remainingMs() }))) : [];
      lifetime.signal.throwIfAborted();
      if (catalogClosed) throw new Error(`MCP '${spec.name}' connection closed during catalog discovery.`);
      return [...listed.map(buildMcpTool).filter((tool): tool is BuiltTool => tool !== null), ...resources];
    };

    // Install before the initial read, so changes during discovery schedule a follow-up.
    // Notifications arriving during a read coalesce to one dirty bit, never parallel reads.
    let dirty = false;
    let initializing = true;
    let refreshing: Promise<void> | undefined;
    const refresh = (): Promise<void> => {
      dirty = true;
      if (initializing || catalogClosed || lifetime.signal.aborted) return Promise.resolve();
      if (refreshing) return refreshing;
      refreshing = (async () => {
        while (dirty && !catalogClosed && !lifetime.signal.aborted) {
          dirty = false;
          try {
            const next = await readCatalog();
            lifetime.signal.throwIfAborted();
            catalog.replace(next);
            if (spec.eager) registry.markDiscovered(catalog.names);
            Logger.info(`[MCP] '${spec.name}' tool list changed — ${catalog.names.length} tool(s) now.`);
            engineEvents.emit('mcp_changed');
          } catch (e: any) {
            if (!lifetime.signal.aborted && !catalogClosed) {
              Logger.warn(`[MCP] '${spec.name}' tool list changed but could not be re-read: ${e?.message || e}`);
            }
          }
        }
      })().finally(() => { refreshing = undefined; });
      return refreshing;
    };
    if (caps?.tools?.listChanged) client.setNotificationHandler(ToolListChangedNotificationSchema, refresh);
    catalog.replace(await readCatalog());
    initializing = false;
    if (dirty) void refresh();
    Logger.info(`[MCP] Connected '${spec.name}' — registered ${catalog.names.length} tool(s).`);
    return { name: spec.name, client, toolNames: catalog.names, spec, dispose };
  } catch (e: any) {
    await dispose();
    const msg = e?.message || String(e);
    if (!options.signal?.aborted) {
      Logger.warn(`[MCP] Failed to connect '${spec.name}': ${msg}`);
      onError?.(msg);
    }
    return null;
  }
}

function callTimeoutMs(): number {
  const configuredTimeout = Number(process.env.BIMAX_MCP_CALL_TIMEOUT_MS || 120000);
  return Number.isFinite(configuredTimeout)
    ? Math.min(Math.max(configuredTimeout, 1000), 10 * 60 * 1000)
    : 120000;
}

/** Connect every configured server and register its tools. Returns the live connections. */
export async function registerMcpTools(
  specs: McpServerSpec[],
  registry: ToolRegistry,
  governor: IGovernor
): Promise<ConnectedMcp[]> {
  const connected: ConnectedMcp[] = [];
  for (const spec of specs) {
    const c = await connectAndRegister(spec, registry, governor);
    if (c) connected.push(c);
  }
  return connected;
}

import * as fs from 'fs';
import * as os from 'os';
import * as path from 'path';

// A3 — MCP client config. Servers are declared in `.bimax/mcp.json`. Two shapes are
// accepted: our `{ servers: [{ name, command, args, env }] }`, and the Claude-style
// `{ mcpServers: { "<name>": { command, args, env } } }` for drop-in compatibility.
//
// A server is either LOCAL (stdio — `command`/`args`) or REMOTE (`url`, optionally
// `type: 'http' | 'sse'` and `headers`). Remote servers cover hosted endpoints like the
// ones mcpmarket / Smithery hand out as a single `https://…/mcp` link.

export interface McpServerSpec {
  name: string;
  // Local (stdio) transport:
  command?: string;
  args?: string[];
  env?: Record<string, string>;
  /** Internal trusted runtimes can forbid the legacy full-parent-env escape hatch. */
  forceScrubEnv?: boolean;
  /** Host-owned capability schemas that must be available without model-side discovery. */
  eager?: boolean;
  // Remote transport:
  url?: string;
  type?: 'http' | 'sse' | 'stdio';
  headers?: Record<string, string>;
  // When true, the server is kept in config but NOT started at boot until re-enabled.
  disabled?: boolean;
}

export const HOST_CAPABILITIES_ENV = 'BIMAX_HOST_CAPABILITIES_JSON';

/** Computer Use was removed from the product. Keep the name reservation at the generic MCP seam
 * so neither an embedding host nor a project config can silently restore the old mac_control path. */
export function isDisabledProductCapabilityName(name: string): boolean {
  return String(name || '').trim().toLowerCase() === 'bimax-mac';
}

/**
 * Parse the narrow, process-local capability contract supplied by an embedding host.
 *
 * This deliberately accepts only absolute stdio commands, string arguments and string-valued
 * environment entries. It cannot add a remote endpoint or opt into parent-environment inheritance.
 * The embedding application owns the process and lifecycle; the engine only consumes MCP schemas
 * and results through the same generic connector used for every other provider.
 */
export function loadHostCapabilityServers(raw = process.env[HOST_CAPABILITIES_ENV]): McpServerSpec[] {
  if (!raw) return [];
  try {
    const parsed = JSON.parse(raw);
    const candidates = Array.isArray(parsed) ? parsed : parsed?.servers;
    if (!Array.isArray(candidates)) return [];
    const seen = new Set<string>();
    const out: McpServerSpec[] = [];
    for (const value of candidates.slice(0, 8)) {
      const name = typeof value?.name === 'string' ? value.name.trim() : '';
      const command = typeof value?.command === 'string' ? value.command.trim() : '';
      if (
        !/^[a-z0-9][a-z0-9._-]{0,63}$/i.test(name)
        || isDisabledProductCapabilityName(name)
        || seen.has(name)
        || !path.isAbsolute(command)
      ) continue;
      const args = Array.isArray(value.args) && value.args.every((arg: unknown) => typeof arg === 'string')
        ? value.args.slice(0, 32) : [];
      const envEntries = value.env && typeof value.env === 'object' && !Array.isArray(value.env)
        ? Object.entries(value.env).filter((entry): entry is [string, string] =>
          /^[A-Z][A-Z0-9_]{0,127}$/.test(entry[0]) && typeof entry[1] === 'string')
        : [];
      seen.add(name);
      out.push({ name, command, args, env: Object.fromEntries(envEntries), type: 'stdio', forceScrubEnv: true, eager: true });
    }
    return out;
  } catch {
    return [];
  }
}

/**
 * Coerce `args` into a string[]. Tolerates the many shapes a weak model emits:
 *   - a real array:                 ["-y", "pkg"]
 *   - a JSON string:                "[\"-y\", \"pkg\"]"
 *   - a single-quoted literal:      "['-y', 'pkg']"   (Python/JS style — not valid JSON)
 *   - a plain space-separated line: "-y pkg"
 */
export function normalizeArgs(args: any): string[] | undefined {
  if (args == null) return undefined;
  if (Array.isArray(args)) return args.map(String);
  if (typeof args !== 'string') return undefined;

  const trimmed = args.trim();
  if (!trimmed) return undefined;

  // Bracketed literal — try strict JSON, then a tolerant comma-split that handles single quotes.
  if (trimmed.startsWith('[')) {
    try {
      const parsed = JSON.parse(trimmed);
      if (Array.isArray(parsed)) return parsed.map(String);
    } catch { /* fall through to tolerant parse */ }
    const inner = trimmed.replace(/^\[/, '').replace(/\]$/, '');
    const parts = inner
      .split(',')
      .map(s => s.trim().replace(/^['"]+|['"]+$/g, '').trim())
      .filter(s => s.length > 0);
    return parts.length ? parts : undefined;
  }

  // Plain string → whitespace split.
  return trimmed.split(/\s+/);
}

/** A spec is usable if it has either a launch command or a remote URL. */
function isValidSpec(s: any): s is McpServerSpec {
  return !!(s && s.name && !isDisabledProductCapabilityName(s.name) && (s.command || s.url));
}

/**
 * Returns the absolute-path arguments that DON'T exist on disk. Servers like
 * @modelcontextprotocol/server-filesystem take real directories to expose; pasting a docs
 * template leaves placeholders like "/path/to/allowed/folder/one" that make the server exit
 * on startup. Catching these up front turns a cryptic ENOENT into a clear, fixable message.
 */
export function missingPathArgs(args?: string[]): string[] {
  if (!args) return [];
  return args.filter(a => {
    if (typeof a !== 'string') return false;
    // Only check things that look like filesystem paths, not flags or package names.
    if (!/^(\/|~\/|~$|\.\.?\/)/.test(a)) return false;
    const resolved = a.startsWith('~') ? path.join(os.homedir(), a.slice(1)) : a;
    return !fs.existsSync(resolved);
  });
}

/** Apply arg normalization to a raw spec object. */
function cleanSpec(s: any): McpServerSpec {
  return { ...s, args: normalizeArgs(s.args) };
}

/**
 * Every transport spelling found in the wild, normalised. Claude/Cursor say `http`/`sse`/`stdio`,
 * VS Code `http`/`sse`/`stdio`, others `streamable-http`, `streamableHttp` or `streamable_http`.
 */
export function normalizeTransportType(raw: unknown): McpServerSpec['type'] | undefined {
  const t = String(raw ?? '').trim().toLowerCase().replace(/[\s_-]/g, '');
  if (!t) return undefined;
  if (t === 'sse') return 'sse';
  if (t === 'stdio' || t === 'local' || t === 'command') return 'stdio';
  if (t === 'http' || t === 'streamablehttp' || t === 'streamable' || t === 'remote' || t === 'https') return 'http';
  return undefined;
}

/**
 * One server entry from ANY of the common config shapes, keyed by its name:
 *   Claude Desktop / Claude Code / Cursor: `{ command, args, env }` or `{ url, headers, type }`
 *   VS Code:                               the same, under `servers` as an OBJECT
 *   Windsurf:                              `{ serverUrl }`
 *   Gemini CLI:                            `{ httpUrl }` (Streamable HTTP) or `{ url }` (SSE)
 *   others:                                `transport` instead of `type`
 */
function specFromEntry(name: string, v: any): McpServerSpec {
  const httpUrl = typeof v?.httpUrl === 'string' ? v.httpUrl : undefined;
  const url = httpUrl ?? (typeof v?.url === 'string' ? v.url : typeof v?.serverUrl === 'string' ? v.serverUrl : undefined);
  const type = normalizeTransportType(v?.type ?? v?.transport) ?? (httpUrl ? 'http' : undefined);
  return {
    name,
    command: v?.command,
    args: v?.args,
    env: v?.env,
    url,
    type,
    headers: v?.headers,
    disabled: v?.disabled ?? (v?.enabled === false ? true : undefined),
  };
}

export function loadMcpServers(dir: string = process.cwd()): McpServerSpec[] {
  const file = path.join(dir, '.bimax', 'mcp.json');
  let cfg: any;
  try {
    cfg = JSON.parse(fs.readFileSync(file, 'utf8'));
  } catch {
    return [];
  }

  // Our own normalised shape: `{ servers: [ { name, ... } ] }`.
  if (Array.isArray(cfg.servers)) {
    return cfg.servers
      .map((s: any) => (s && typeof s === 'object' ? { ...s, ...specFromEntry(s.name, s) } : s))
      .filter(isValidSpec).map(cleanSpec);
  }
  // Every keyed shape — `mcpServers` (Claude, Cursor, Windsurf, Gemini CLI) and VS Code's object
  // `servers` — used to fall through to `mcpServers` only, so a pasted VS Code config loaded NOTHING
  // and said nothing.
  const keyed = cfg.mcpServers && typeof cfg.mcpServers === 'object' ? cfg.mcpServers
    : cfg.servers && typeof cfg.servers === 'object' ? cfg.servers
    : null;
  if (keyed) {
    return Object.entries(keyed)
      .map(([name, v]: [string, any]) => specFromEntry(name, v))
      .filter(isValidSpec)
      .map(cleanSpec);
  }
  return [];
}

/**
 * `${VAR}`, `${VAR:-default}` and VS Code's `${env:VAR}` in a server's command, arguments, env
 * values, URL and headers. Shared configs keep secrets OUT of the file this way — a README's
 * `"Authorization": "Bearer ${GITHUB_TOKEN}"` used to be sent literally. Resolved at connect time
 * from the engine's environment (which includes ~/.breakglass/.env); the stored config keeps the
 * reference, so rewriting mcp.json never writes the secret into it.
 */
export function expandSpecVars(spec: McpServerSpec, env: NodeJS.ProcessEnv = process.env): { spec: McpServerSpec; missing: string[] } {
  const missing = new Set<string>();
  const expand = (value: string): string => value.replace(/\$\{(?:env:)?([A-Za-z_][A-Za-z0-9_]*)(?::-([^}]*))?\}/g, (_m, name: string, fallback?: string) => {
    const found = env[name];
    if (found !== undefined && found !== '') return found;
    if (fallback !== undefined) return fallback;
    missing.add(name);
    return '';
  });
  const mapValues = (obj?: Record<string, string>) => obj
    ? Object.fromEntries(Object.entries(obj).map(([k, v]) => [k, typeof v === 'string' ? expand(v) : v]))
    : undefined;
  const out: McpServerSpec = {
    ...spec,
    ...(spec.command ? { command: expand(spec.command) } : {}),
    ...(spec.args ? { args: spec.args.map((a) => (typeof a === 'string' ? expand(a) : a)) } : {}),
    ...(spec.env ? { env: mapValues(spec.env) } : {}),
    ...(spec.url ? { url: expand(spec.url) } : {}),
    ...(spec.headers ? { headers: mapValues(spec.headers) } : {}),
  };
  return { spec: out, missing: [...missing] };
}

import { reportCapability } from '../core/capability.status';
import * as fs from 'fs';
import * as os from 'os';
import * as path from 'path';
import { ToolRegistry } from '../tools/tool.registry';
import { IGovernor } from '../core/interfaces';
import { Logger } from '../utils/logger';
import { McpServerSpec, loadHostCapabilityServers, loadMcpServers, normalizeArgs, missingPathArgs } from './config';
import { connectAndRegister, ConnectedMcp, OpenOptions } from './client';
import { forgetSignIn } from './oauth';
import { engineEvents } from '../engine/events';
import { codebaseMemorySpec } from './builtin/codebaseMemory';
import { withTimeout } from '../utils/withTimeout';
import { serverCallSummary } from './stats';

export type McpHealthState = 'connected' | 'disabled' | 'connecting' | 'disconnected' | 'error';

export interface McpHealth {
  name: string;
  state: McpHealthState;
  transport: 'stdio' | 'http' | 'sse';
  toolCount: number;
  error?: string;
  missingPaths?: string[];
  /** Lifetime call telemetry for this server's tools (0s when unused this session). */
  calls: number;
  callErrors: number;
  avgMs: number;
}

/**
 * Built-in engines baked into Bimax (auto-provisioned, not user-configured). Seeded into the
 * connect set before user config so a same-named entry in .bimax/mcp.json still wins. Failures
 * are swallowed — a missing engine must never block boot.
 *
 * codebase-memory is fronted natively by the GraphQueryTool/GraphContextTool backend (approach b),
 * so by default we do NOT also register its 14 raw `mcp__codebase-memory__*` tools (that would dump
 * redundant tools on the model and spawn a second engine process). Power users can opt into the raw
 * tools with BIMAX_CODEMEM_RAW_TOOLS=1.
 */
async function optionalBuiltinServers(): Promise<McpServerSpec[]> {
  const out: McpServerSpec[] = [];
  if (process.env.BIMAX_CODEMEM_RAW_TOOLS === '1') {
    try {
      const cbm = await codebaseMemorySpec();
      if (cbm) out.push(cbm);
    } catch { /* best-effort */ }
  }
  return out;
}

/** Defend every entry point: a model may pass `args` as a JSON string — coerce it to a real array. */
function cleanSpec(spec: McpServerSpec): McpServerSpec {
  return { ...spec, args: normalizeArgs(spec.args) };
}

// Runtime manager for MCP servers: holds the live connections so they can be listed, tested,
// added, and removed at runtime (the boot path, the /mcp command, and the agent's McpManageTool
// all go through here). Config lives in `.bimax/mcp.json`.

export class McpManager {
  private connections: Map<string, ConnectedMcp> = new Map();
  /** Server names currently in the middle of a connect attempt. Used by ToolSearchTool to warn the
   *  model that a missing MCP tool might appear once the server finishes connecting. */
  private pending = new Map<string, AbortController>();
  private pendingFinished = new WeakMap<AbortController, Promise<void>>();
  private heals = new Map<string, Promise<ConnectedMcp | null>>();
  /** The reason the most recent connect attempt failed (for surfacing to the user/agent). */
  public lastError: string | null = null;
  /** Failure state is tracked per server so one bad connector cannot hide another one's cause. */
  private errors: Map<string, string> = new Map();

  // MCP servers are stored GLOBALLY by default (~/.bimax/mcp.json) so a server added in any
  // directory persists everywhere — just like API keys. Passing an explicit `cwd` targets that
  // project's `.bimax/mcp.json` instead (used by tests and project-local team configs).
  private configRoot(cwd?: string): string {
    return cwd ?? os.homedir();
  }

  private configPath(cwd?: string): string {
    return path.join(this.configRoot(cwd), '.bimax', 'mcp.json');
  }

  /** Connect one server and retain the connection. Returns the live connection or null. */
  private reportConnection(name: string, ready: boolean): void {
    reportCapability({ id: `mcp:${name}`, label: `MCP ${name}`, state: ready ? 'ready' : 'unavailable',
      reason: ready ? 'The connection answered successfully.' : 'The configured connection failed.',
      impact: ready ? '' : 'Its tools may be unavailable.', action: ready ? '' : 'Check the server or use /mcp reconnect.' });
  }

  public async connectSpec(
    spec: McpServerSpec,
    registry: ToolRegistry,
    governor: IGovernor,
    options: OpenOptions = {},
  ): Promise<ConnectedMcp | null> {
    this.lastError = null;
    this.pending.get(spec.name)?.abort(new Error('Superseded MCP connection attempt.'));
    const attempt = new AbortController();
    let finish!: () => void;
    this.pendingFinished.set(attempt, new Promise<void>(resolve => { finish = resolve; }));
    this.pending.set(spec.name, attempt);
    const cancel = () => attempt.abort(options.signal?.reason);
    options.signal?.addEventListener('abort', cancel, { once: true });
    if (options.signal?.aborted) cancel();
    let failure: string | null = null;
    let owned: ConnectedMcp | null = null;
    try {
      const conn = await connectAndRegister(cleanSpec(spec), registry, governor, (msg) => {
        failure = msg;
      }, async () => {
        if (!owned) return null;
        return (await this.healConnection(owned, registry, governor))?.client ?? null;
      }, { ...options, signal: attempt.signal });
      if (attempt.signal.aborted || this.pending.get(spec.name) !== attempt) {
        await conn?.dispose?.();
        return null;
      }
      if (!conn) {
        this.lastError = failure || 'Connection failed without an error message.';
        this.errors.set(spec.name, this.lastError);
        this.reportConnection(spec.name, false);
        return null;
      }

      const previous = this.connections.get(conn.name);
      owned = conn;
      // Publish ownership before awaiting old transport cleanup. Disconnect/replacement now
      // sees the new connection and can retire it, even if the old close takes a long time.
      this.connections.set(conn.name, conn);
      this.pending.delete(spec.name);
      if (spec.eager) registry.markDiscovered(conn.toolNames);
      this.errors.delete(spec.name);
      this.reportConnection(spec.name, true);
      if (previous && previous !== conn) await this.disposeConnection(previous, registry);
      return this.connections.get(conn.name) === conn ? conn : null;
    } catch (error) {
      if (!attempt.signal.aborted) this.reportConnection(spec.name, false);
      throw error;
    } finally {
      if (this.pending.get(spec.name) === attempt) this.pending.delete(spec.name);
      options.signal?.removeEventListener('abort', cancel);
      finish();
    }
  }

  private async disposeConnection(conn: ConnectedMcp, registry?: ToolRegistry): Promise<void> {
    if (conn.dispose) {
      await conn.dispose();
      return;
    }
    // Compatibility for embedding/test connections that do not supply owned disposal.
    if (registry) for (const name of conn.toolNames) registry.unregister(name);
    try { await conn.client?.close?.(); } catch { /* best-effort */ }
  }

  private healConnection(conn: ConnectedMcp, registry: ToolRegistry, governor: IGovernor): Promise<ConnectedMcp | null> {
    if (this.connections.get(conn.name) !== conn) return Promise.resolve(null);
    const healing = this.heals.get(conn.name);
    if (healing) return healing;
    // A manual replacement has precedence over an automatic retry of the old specification.
    if (this.pending.has(conn.name)) return Promise.resolve(null);
    const next = this.connectSpec(conn.spec, registry, governor).finally(() => {
      if (this.heals.get(conn.name) === next) this.heals.delete(conn.name);
    });
    this.heals.set(conn.name, next);
    return next;
  }

  /**
   * Connect embedding-host capabilities before the headless protocol reports ready.
   *
   * This generic compatibility seam is for embedding integrations. Bimax CU uses a transferred
   * internal MessagePort instead; it has no MCP connection or environment descriptor.
   */
  public async connectHostCapabilities(
    registry: ToolRegistry,
    governor: IGovernor,
  ): Promise<number> {
    const specs = loadHostCapabilityServers();
    const results = await Promise.allSettled(specs.map(async (spec) => {
      if (spec.disabled) return false;
      const connection = await this.connectSpec(spec, registry, governor);
      if (connection) {
        engineEvents.emit('status', `Host capability '${spec.name}' connected — ${connection.toolNames.length} tool(s)`);
        return true;
      }
      const why = this.lastErrorFor(spec.name);
      if (why) engineEvents.emit('status', `Host capability '${spec.name}' failed: ${why}`);
      return false;
    }));
    const connected = results.filter(result => result.status === 'fulfilled' && result.value).length;
    if (connected > 0) engineEvents.emit('mcp_changed');
    return connected;
  }

  /**
   * Connect every configured server. Merges the GLOBAL store (~/.bimax/mcp.json) with the
   * project-local one (<projectRoot>/.bimax/mcp.json) — project entries override globals of the
   * same name. Best-effort. Used at boot.
   */
  public async connectAll(registry: ToolRegistry, governor: IGovernor, projectRoot?: string): Promise<number> {
    const byName = new Map<string, McpServerSpec>();
    // Host capabilities are reserved by the embedding app. A project MCP config must never replace
    // `bimax-mac` with a same-named third-party process after the trusted provider connected.
    const host = loadHostCapabilityServers();
    const reservedHostNames = new Set(host.map(spec => spec.name));
    for (const s of host) byName.set(s.name, s);
    for (const s of await optionalBuiltinServers()) byName.set(s.name, s);
    for (const s of loadMcpServers(os.homedir())) {
      if (!reservedHostNames.has(s.name)) byName.set(s.name, s);
    }
    if (projectRoot && projectRoot !== os.homedir()) {
      for (const s of loadMcpServers(projectRoot)) {
        if (!reservedHostNames.has(s.name)) byName.set(s.name, s);
      }
    }
    // Connect all servers IN PARALLEL — boot used to pay the sum of every server's handshake
    // (npx cold-starts routinely take seconds each); now it pays only the slowest one. Each
    // connectSpec tracks its own pending/error state, so concurrency is safe here.
    const results = await Promise.allSettled(Array.from(byName.values()).map(async (spec) => {
      // The critical host provider was connected synchronously before protocol readiness. Do not
      // restart it when the delayed optional-MCP sweep begins.
      if (spec.eager && this.connections.has(spec.name)) return true;
      // Skip servers the user turned off — they stay in config until re-enabled.
      if (spec.disabled) {
        Logger.info(`[MCP] Skipping disabled server '${spec.name}'.`);
        return false;
      }
      // Skip servers whose path args don't exist — they would just fail and slow the others.
      const missing = missingPathArgs(normalizeArgs(spec.args));
      if (missing.length) {
        this.reportConnection(spec.name, false);
        Logger.warn(`[MCP] Skipping '${spec.name}': path(s) do not exist: ${missing.join(', ')}`);
        engineEvents.emit('status', `MCP '${spec.name}' skipped — missing path(s): ${missing.join(', ')}`);
        return false;
      }
      const c = await this.connectSpec(spec, registry, governor);
      if (c) {
        engineEvents.emit('status', `MCP '${spec.name}' connected — ${c.toolNames.length} tool(s)`);
        return true;
      }
      const why = this.lastErrorFor(spec.name);
      if (why) engineEvents.emit('status', `MCP '${spec.name}' failed: ${why}`);
      return false;
    }));
    const n = results.filter(r => r.status === 'fulfilled' && r.value).length;
    if (n > 0) engineEvents.emit('mcp_changed');
    return n;
  }

  /** Enable or disable a server in config. Disconnects it live when disabling. */
  public async setEnabled(name: string, enabled: boolean, registry?: ToolRegistry, cwd?: string): Promise<boolean> {
    const root = this.configRoot(cwd);
    const specs = loadMcpServers(root);
    const spec = specs.find(s => s.name === name);
    if (!spec) return false;
    spec.disabled = !enabled;
    const file = this.configPath(cwd);
    fs.mkdirSync(path.dirname(file), { recursive: true });
    fs.writeFileSync(file, JSON.stringify({ servers: specs }, null, 2), 'utf8');
    if (!enabled) await this.disconnect(name, registry);
    engineEvents.emit('mcp_changed');
    return true;
  }

  /** Is a configured server currently turned off? */
  public isDisabled(name: string, cwd?: string): boolean {
    return !!loadMcpServers(this.configRoot(cwd)).find(s => s.name === name)?.disabled;
  }

  /** Server names still connecting — used by ToolSearchTool to warn the model of pending tools. */
  public getPendingServers(): string[] {
    return Array.from(this.pending.keys());
  }

  public list(): ConnectedMcp[] {
    return Array.from(this.connections.values());
  }

  public get(name: string): ConnectedMcp | undefined {
    return this.connections.get(name);
  }

  /** Last failure for one server (unlike lastError, this survives other servers connecting). */
  public lastErrorFor(name: string): string | null {
    return this.errors.get(name) ?? null;
  }

  /** Snapshot connector health without making network requests. */
  public health(cwd?: string): McpHealth[] {
    const specs = loadMcpServers(this.configRoot(cwd));
    const byName = new Map(specs.map(spec => [spec.name, spec]));
    // Include a live connector even if its config was removed or changed out-of-band.
    for (const conn of this.list()) {
      if (!byName.has(conn.name)) byName.set(conn.name, { name: conn.name, command: 'live' });
    }

    return Array.from(byName.values()).map(spec => {
      const conn = this.connections.get(spec.name);
      const missing = missingPathArgs(normalizeArgs(spec.args));
      const error = this.errors.get(spec.name);
      let state: McpHealthState = 'disconnected';
      if (spec.disabled) state = 'disabled';
      else if (this.pending.has(spec.name)) state = 'connecting';
      else if (conn) state = error ? 'error' : 'connected';
      else if (error || missing.length) state = 'error';

      const usage = serverCallSummary(spec.name);
      return {
        name: spec.name,
        state,
        transport: spec.url ? (spec.type === 'sse' ? 'sse' : 'http') : 'stdio',
        toolCount: conn?.toolNames.length ?? 0,
        calls: usage.calls,
        callErrors: usage.errors,
        avgMs: usage.avgMs,
        ...(error ? { error } : {}),
        ...(missing.length ? { missingPaths: missing } : {}),
      } as McpHealth;
    });
  }

  /** Actively probe connected servers. This is intentionally read-only and bounded. */
  public async diagnose(cwd?: string): Promise<McpHealth[]> {
    for (const conn of this.list()) {
      try {
        const probe = typeof conn.client?.ping === 'function'
          ? conn.client.ping()
          : conn.client.listTools();
        await withTimeout(Promise.resolve(probe), 5000, `MCP '${conn.name}' health check`);
        if (this.connections.get(conn.name) !== conn) continue;
        this.errors.delete(conn.name);
        this.reportConnection(conn.name, true);
      } catch (e: any) {
        if (this.connections.get(conn.name) !== conn) continue;
        this.errors.set(conn.name, e?.message || String(e));
        this.reportConnection(conn.name, false);
      }
    }
    return this.health(cwd);
  }

  /** Reconnect one configured server while preserving a working old connection on failure. */
  public async reconnect(
    name: string,
    registry: ToolRegistry,
    governor: IGovernor,
    cwd?: string,
  ): Promise<ConnectedMcp | null> {
    this.healFailures.delete(name); // a manual reconnect resets the watchdog's give-up counter
    const spec = loadMcpServers(this.configRoot(cwd)).find(s => s.name === name);
    if (!spec) {
      const msg = `No MCP server named '${name}' is configured.`;
      this.lastError = msg;
      this.errors.set(name, msg);
      return null;
    }
    if (spec.disabled) {
      const msg = `MCP server '${name}' is disabled.`;
      this.lastError = msg;
      this.errors.set(name, msg);
      return null;
    }
    return this.connectSpec(spec, registry, governor);
  }

  /**
   * Sign in to a hosted server (OAuth) and connect it. Opens the browser — only ever from an
   * explicit request; automatic connects fail with a "needs you to sign in" message instead.
   */
  public async login(name: string, registry: ToolRegistry, governor: IGovernor, cwd?: string): Promise<ConnectedMcp | null> {
    const spec = loadMcpServers(this.configRoot(cwd)).find(s => s.name === name) ?? this.connections.get(name)?.spec;
    const refuse = (msg: string) => { this.lastError = msg; this.errors.set(name, msg); return null; };
    if (!spec) return refuse(`No MCP server named '${name}' is configured.`);
    if (!spec.url) return refuse(`MCP '${name}' runs on this Mac, so it has no sign-in. Give it its keys in its "env" instead.`);
    this.healFailures.delete(name);
    return this.connectSpec(spec, registry, governor, { interactiveSignIn: true });
  }

  /** Forget a hosted server's sign-in and disconnect it. */
  public async logout(name: string, registry?: ToolRegistry, cwd?: string): Promise<boolean> {
    const spec = loadMcpServers(this.configRoot(cwd)).find(s => s.name === name) ?? this.connections.get(name)?.spec;
    if (!spec?.url) return false;
    forgetSignIn(spec.url);
    await this.disconnect(name, registry);
    this.errors.set(name, `Signed out. Run /mcp login ${name} to sign in again.`);
    return true;
  }

  /** Live tool names contributed by all connected servers. */
  public toolNames(): string[] {
    return this.list().flatMap(c => c.toolNames);
  }

  // --- Watchdog: background self-healing -----------------------------------------------------

  private watchdog: ReturnType<typeof setInterval> | null = null;
  private watchdogGeneration = 0;
  /** Consecutive failed heal attempts per server — after 3 the watchdog stops trying (manual /mcp reconnect resets it). */
  private healFailures: Map<string, number> = new Map();
  private static readonly MAX_HEAL_ATTEMPTS = 3;

  /**
   * Start the background auto-doctor: every `intervalMs` (default 60s) probe each live connector
   * and auto-reconnect dead ones. Backs off after MAX_HEAL_ATTEMPTS consecutive failures so a
   * permanently-broken server isn't relaunched forever. Never prompts — connect/reconnect paths
   * don't gate through the Governor. The interval is unref'd so it can't keep the process alive.
   */
  public startWatchdog(registry: ToolRegistry, governor: IGovernor, intervalMs = 60000): void {
    if (this.watchdog || process.env.BIMAX_MCP_WATCHDOG === '0') return;
    const generation = ++this.watchdogGeneration;
    const current = () => this.watchdogGeneration === generation && this.watchdog !== null;
    let sweeping = false; // a slow sweep must not overlap the next tick
    this.watchdog = setInterval(async () => {
      if (sweeping) return;
      sweeping = true;
      try {
        for (const conn of this.list()) {
          if (!current()) break;
          try {
            const probe = typeof conn.client?.ping === 'function' ? conn.client.ping() : conn.client.listTools();
            await withTimeout(Promise.resolve(probe), 5000, `MCP '${conn.name}' watchdog probe`);
            if (this.connections.get(conn.name) !== conn || !current()) continue;
            this.healFailures.delete(conn.name);
            this.reportConnection(conn.name, true);
          } catch (probeErr: any) {
            if (this.connections.get(conn.name) !== conn || !current()) continue;
            this.reportConnection(conn.name, false);
            const attempts = this.healFailures.get(conn.name) ?? 0;
            if (attempts >= McpManager.MAX_HEAL_ATTEMPTS) continue; // gave up — manual reconnect resets
            this.errors.set(conn.name, probeErr?.message || String(probeErr));
            Logger.warn(`[MCP] Watchdog: '${conn.name}' failed its probe (${probeErr?.message}); auto-reconnecting (attempt ${attempts + 1}/${McpManager.MAX_HEAL_ATTEMPTS}).`);
            // Reconnect with the connection's own spec — config-file lookup would miss built-ins.
            const fresh = await this.healConnection(conn, registry, governor);
            if (fresh && current()) {
              this.healFailures.delete(conn.name);
              engineEvents.emit('status', `MCP '${conn.name}' auto-healed — ${fresh.toolNames.length} tool(s) back.`);
              engineEvents.emit('mcp_changed');
            } else if (this.connections.get(conn.name) === conn && current()) {
              this.healFailures.set(conn.name, attempts + 1);
              if (attempts + 1 >= McpManager.MAX_HEAL_ATTEMPTS) {
                engineEvents.emit('status', `MCP '${conn.name}' is down (${McpManager.MAX_HEAL_ATTEMPTS} heal attempts failed) — run /mcp doctor.`);
              }
            }
          }
        }
      } finally {
        sweeping = false;
      }
    }, intervalMs);
    this.watchdog.unref?.();
  }

  public stopWatchdog(): void {
    this.watchdogGeneration++;
    if (this.watchdog) { clearInterval(this.watchdog); this.watchdog = null; }
  }

  /** Disconnect a server, drop its tools from the registry, and forget the connection. */
  public async disconnect(name: string, registry?: ToolRegistry): Promise<boolean> {
    const attempt = this.pending.get(name);
    this.pending.delete(name);
    attempt?.abort(new Error(`MCP '${name}' disconnected.`));
    const conn = this.connections.get(name);
    this.connections.delete(name);
    this.healFailures.delete(name);
    if (conn) await this.disposeConnection(conn, registry);
    if (attempt) await this.pendingFinished.get(attempt);
    return !!conn || !!attempt;
  }

  /** Persist a server into `.bimax/mcp.json` (normalized `{ servers: [...] }` shape). Global by default. */
  public addToConfig(spec: McpServerSpec, cwd?: string): void {
    const file = this.configPath(cwd);
    const specs = loadMcpServers(this.configRoot(cwd)).filter(s => s.name !== spec.name);
    specs.push(cleanSpec(spec));
    fs.mkdirSync(path.dirname(file), { recursive: true });
    fs.writeFileSync(file, JSON.stringify({ servers: specs }, null, 2), 'utf8');
    Logger.info(`[McpManager] Saved server '${spec.name}' to ${file}`);
  }

  /** Remove a server from `.bimax/mcp.json`. Returns true if it was present. Global by default. */
  public removeFromConfig(name: string, cwd?: string): boolean {
    const file = this.configPath(cwd);
    const specs = loadMcpServers(this.configRoot(cwd));
    const next = specs.filter(s => s.name !== name);
    if (next.length === specs.length) return false;
    fs.mkdirSync(path.dirname(file), { recursive: true });
    fs.writeFileSync(file, JSON.stringify({ servers: next }, null, 2), 'utf8');
    this.errors.delete(name);
    return true;
  }

  /** Names of servers declared in config (whether or not currently connected). Global by default. */
  public configuredNames(cwd?: string): string[] {
    return loadMcpServers(this.configRoot(cwd)).map(s => s.name);
  }
}

export const globalMcpManager = new McpManager();

import * as crypto from 'crypto';
import * as fs from 'fs';
import * as http from 'http';
import * as os from 'os';
import * as path from 'path';
import { execFile } from 'child_process';

/**
 * Sign-in for hosted MCP servers (OAuth 2.1, as the MCP authorization spec requires).
 *
 * THE GAP. Most hosted MCP servers — GitHub, Linear, Notion, Atlassian, Sentry, Stripe — answer an
 * unauthenticated connect with 401 and expect the client to run the OAuth flow: discover the
 * authorization server, register itself, send the person to a browser, take the code back on a
 * local redirect, and refresh the token later. Bimax had none of it, so every such server failed
 * with a bare "Unauthorized" and could only be used by pasting a personal token into `headers`.
 *
 * WHAT LIVES HERE. The MCP SDK performs the protocol (discovery, dynamic client registration,
 * PKCE, token exchange and refresh). This file supplies the three things the SDK leaves to the
 * client: where the credentials are kept, the loopback redirect listener, and opening the browser.
 *
 * STORAGE. One file per server URL under `~/.breakglass/mcp-auth/` (relocated with
 * BIMAX_BREAKGLASS_DIR), mode 0600 in a 0700 directory — the same protection `~/.breakglass/.env`
 * gets. Keyed by a hash of the URL, so renaming a server keeps its sign-in and a different server
 * can never read another's tokens.
 *
 * NEVER A SURPRISE BROWSER. A connect that needs sign-in fails with `McpSignInRequired`; only an
 * explicit `/mcp login <name>` (or the agent's `McpManageTool` login action, which is approval-
 * gated) opens the browser.
 */

export const OAUTH_CALLBACK_PATH = '/mcp/oauth/callback';

/**
 * One fixed loopback port. The redirect URI is registered with each authorization server once, and
 * a later sign-in must present the same URI, so the port cannot be random.
 */
export function oauthCallbackPort(env: NodeJS.ProcessEnv = process.env): number {
  const n = Number(env.BIMAX_MCP_OAUTH_PORT);
  return Number.isInteger(n) && n > 1023 && n < 65536 ? n : 33418;
}

export function oauthRedirectUrl(env: NodeJS.ProcessEnv = process.env): string {
  return `http://127.0.0.1:${oauthCallbackPort(env)}${OAUTH_CALLBACK_PATH}`;
}

/** A connect that needs the person to sign in first. Carries the server name for the message. */
export class McpSignInRequired extends Error {
  constructor(readonly serverName: string) {
    super(`MCP '${serverName}' needs you to sign in. Run /mcp login ${serverName} to open the sign-in page.`);
    this.name = 'McpSignInRequired';
  }
}

interface StoredAuth {
  serverUrl: string;
  clientInformation?: unknown;
  tokens?: unknown;
  codeVerifier?: string;
  state?: string;
  discoveryState?: unknown;
}

function authDir(): string {
  return path.join(process.env.BIMAX_BREAKGLASS_DIR || path.join(os.homedir(), '.breakglass'), 'mcp-auth');
}

export function authFileFor(serverUrl: string): string {
  const id = crypto.createHash('sha256').update(new URL(serverUrl).href).digest('hex').slice(0, 24);
  return path.join(authDir(), `${id}.json`);
}

function read(serverUrl: string): StoredAuth {
  try {
    const parsed = JSON.parse(fs.readFileSync(authFileFor(serverUrl), 'utf8'));
    if (parsed && typeof parsed === 'object' && parsed.serverUrl === new URL(serverUrl).href) return parsed;
  } catch { /* none yet */ }
  return { serverUrl: new URL(serverUrl).href };
}

function write(serverUrl: string, data: StoredAuth): void {
  const file = authFileFor(serverUrl);
  fs.mkdirSync(path.dirname(file), { recursive: true, mode: 0o700 });
  try { fs.chmodSync(path.dirname(file), 0o700); } catch { /* best effort */ }
  const tmp = `${file}.tmp-${process.pid}-${crypto.randomBytes(4).toString('hex')}`;
  fs.writeFileSync(tmp, JSON.stringify(data), { encoding: 'utf8', mode: 0o600 });
  fs.renameSync(tmp, file);
}

/** True once a sign-in has stored tokens for this server. */
export function hasStoredTokens(serverUrl: string): boolean {
  return !!read(serverUrl).tokens;
}

/** Forget a server's sign-in (tokens, registration, everything). */
export function forgetSignIn(serverUrl: string): void {
  try { fs.unlinkSync(authFileFor(serverUrl)); } catch { /* nothing stored */ }
}

/**
 * The SDK's `OAuthClientProvider`, backed by the per-server file. `onAuthorizationUrl` decides what
 * a needed sign-in does: record it (boot), or open the browser (an explicit login).
 */
export class FileOAuthProvider {
  constructor(
    private readonly serverUrl: string,
    private readonly onAuthorizationUrl: (url: URL) => void | Promise<void>,
    private readonly env: NodeJS.ProcessEnv = process.env,
  ) {}

  get redirectUrl(): string { return oauthRedirectUrl(this.env); }

  get clientMetadata() {
    return {
      client_name: 'Bimax',
      client_uri: 'https://bimax.app',
      redirect_uris: [this.redirectUrl],
      grant_types: ['authorization_code', 'refresh_token'],
      response_types: ['code'],
      // A desktop app cannot keep a client secret; PKCE protects the code exchange instead.
      token_endpoint_auth_method: 'none',
    };
  }

  state(): string {
    const data = read(this.serverUrl);
    data.state = crypto.randomBytes(16).toString('hex');
    write(this.serverUrl, data);
    return data.state;
  }

  expectedState(): string | undefined { return read(this.serverUrl).state; }

  clientInformation(): any { return read(this.serverUrl).clientInformation; }
  saveClientInformation(info: unknown): void { write(this.serverUrl, { ...read(this.serverUrl), clientInformation: info }); }

  tokens(): any { return read(this.serverUrl).tokens; }
  saveTokens(tokens: unknown): void { write(this.serverUrl, { ...read(this.serverUrl), tokens }); }

  async redirectToAuthorization(url: URL): Promise<void> { await this.onAuthorizationUrl(url); }

  saveCodeVerifier(codeVerifier: string): void { write(this.serverUrl, { ...read(this.serverUrl), codeVerifier }); }
  codeVerifier(): string {
    const v = read(this.serverUrl).codeVerifier;
    if (!v) throw new Error('No sign-in is in progress for this server.');
    return v;
  }

  saveDiscoveryState(state: unknown): void { write(this.serverUrl, { ...read(this.serverUrl), discoveryState: state }); }
  discoveryState(): any { return read(this.serverUrl).discoveryState; }

  invalidateCredentials(scope: 'all' | 'client' | 'tokens' | 'verifier' | 'discovery'): void {
    if (scope === 'all') { forgetSignIn(this.serverUrl); return; }
    const data = read(this.serverUrl);
    if (scope === 'client') delete data.clientInformation;
    if (scope === 'tokens') delete data.tokens;
    if (scope === 'verifier') delete data.codeVerifier;
    if (scope === 'discovery') delete data.discoveryState;
    write(this.serverUrl, data);
  }
}

/**
 * Listen on the loopback redirect for ONE authorization response. Resolves with the code when the
 * `state` matches (CSRF protection), rejects on an error response, a mismatched state or the
 * timeout. Binds 127.0.0.1 only, and closes after the first valid response.
 */
export function waitForAuthorizationCode(
  expectedState: () => string | undefined,
  options: { port?: number; timeoutMs?: number } = {},
): { ready: Promise<void>; code: Promise<string>; close: () => void } {
  const port = options.port ?? oauthCallbackPort();
  const timeoutMs = options.timeoutMs ?? 5 * 60_000;
  let settle!: { resolve: (c: string) => void; reject: (e: Error) => void };
  const code = new Promise<string>((resolve, reject) => { settle = { resolve, reject }; });
  const close = () => { clearTimeout(timer); try { server.close(); } catch { /* closed */ } };
  const page = (title: string, body: string) =>
    `<!doctype html><meta charset="utf-8"><title>${title}</title><body style="font:15px -apple-system,system-ui;padding:48px;max-width:520px;margin:auto"><h2>${title}</h2><p>${body}</p></body>`;

  const server: http.Server = http.createServer((req, res) => {
    const url = new URL(req.url || '/', `http://127.0.0.1:${port}`);
    if (url.pathname !== OAUTH_CALLBACK_PATH) { res.writeHead(404).end(); return; }
    const error = url.searchParams.get('error');
    const got = url.searchParams.get('code');
    const state = url.searchParams.get('state');
    const want = expectedState();
    res.setHeader('Content-Type', 'text/html; charset=utf-8');
    if (error) {
      res.writeHead(400).end(page('Sign-in was not completed', `The server said: ${error.replace(/[<>&]/g, '')}. You can close this window.`));
      close();
      settle.reject(new Error(`Sign-in was refused: ${error}`));
      return;
    }
    if (!got || (want && state !== want)) {
      res.writeHead(400).end(page('Sign-in link did not match', 'Start the sign-in again from Bimax.'));
      return; // keep listening: a stray or forged request must not end a real sign-in
    }
    res.writeHead(200).end(page('Signed in to Bimax', 'You can close this window and go back to Bimax.'));
    close();
    settle.resolve(got);
  });
  const ready = new Promise<void>((resolve, reject) => {
    server.once('error', (e: any) => {
      const err = new Error(e?.code === 'EADDRINUSE'
        ? `Port ${port} is in use, so the sign-in page cannot return to Bimax. Close whatever uses it or set BIMAX_MCP_OAUTH_PORT.`
        : `Could not start the sign-in listener: ${e?.message || e}`);
      settle.reject(err);
      reject(err);
    });
    server.listen(port, '127.0.0.1', () => resolve());
  });
  const timer = setTimeout(() => { close(); settle.reject(new Error('Sign-in timed out after 5 minutes.')); }, timeoutMs);
  timer.unref?.();
  return { ready, code, close };
}

/** Open a URL in the default browser. Only http(s) URLs, passed as one argument, never through a shell. */
export function openInBrowser(url: URL): Promise<void> {
  if (url.protocol !== 'https:' && url.protocol !== 'http:') return Promise.reject(new Error(`Refusing to open a ${url.protocol} sign-in link.`));
  const opener = process.platform === 'darwin' ? 'open' : process.platform === 'win32' ? 'explorer' : 'xdg-open';
  return new Promise((resolve, reject) => execFile(opener, [url.href], (err) => (err ? reject(err) : resolve())));
}

import { presentationParts, type PresentationPart } from '../protocol/presentation';

/** Preserve presentation separately; the existing model-facing string stays unchanged. */
export function mcpPresentation(server: string, tool: any, input: unknown, result: any): PresentationPart[] {
  const parts: PresentationPart[] = [];
  if (result?.structuredContent !== undefined)
    parts.push({ kind: 'data', id: 'structured', value: result.structuredContent });
  for (const [i, c] of (Array.isArray(result?.content) ? result.content : []).entries()) {
    if (c?.type === 'image')
      parts.push({ kind: 'image', id: `media-${i}`, mimeType: c.mimeType, data: c.data });
    if (c?.type === 'resource' && c.resource?.uri)
      parts.push({
        kind: 'resource',
        id: `embedded-${i}`,
        uri: c.resource.uri,
        mimeType: c.resource.mimeType,
        ...(typeof c.resource.text === 'string' ? { text: c.resource.text } : {}),
      });
    if (c?.type === 'resource' && c.resource?.blob && c.resource?.mimeType?.startsWith('image/'))
      parts.push({
        kind: 'image',
        id: `embedded-image-${i}`,
        mimeType: c.resource.mimeType,
        data: c.resource.blob,
      });
    if (c?.type === 'resource_link')
      parts.push({
        kind: 'resource',
        id: `resource-${i}`,
        uri: c.uri,
        title: c.title || c.name,
        mimeType: c.mimeType,
      });
  }
  const resourceUri =
    tool?._meta?.ui?.resourceUri || tool?._meta?.['ui/resourceUri'] || tool?._meta?.['openai/outputTemplate'];
  if (typeof resourceUri === 'string' && resourceUri.startsWith('ui://')) {
    parts.push({
      kind: 'mcp-app',
      id: 'app',
      server,
      tool: tool.name,
      resourceUri,
      input,
      result: {
        content: result?.content,
        structuredContent: result?.structuredContent,
        _meta: result?._meta,
        isError: result?.isError,
      },
    });
  }
  return presentationParts(parts);
}

import { IGovernor } from '../core/interfaces';
import { buildTool, BuiltTool } from '../tools/tool.factory';
import { outcomeError, outcomeOk } from '../tools/outcome';
import { withRequestDeadline } from '../utils/request.deadline';

/** Resource adapters share the same deadline and Stop behavior as advertised MCP tools. */
export function buildMcpResourceTools(
  client: any,
  name: string,
  governor: IGovernor,
  timeoutMs: () => number,
  signalFor: (context: any) => AbortSignal,
): BuiltTool[] {
  const listName = `mcp__${name}__list_resources`;
  const readName = `mcp__${name}__read_resource`;
  const run = <T>(operation: string, context: any,
    body: (signal: AbortSignal, remainingMs: () => number) => Promise<T>) => {
    const budget = timeoutMs();
    return withRequestDeadline(budget, signalFor(context),
      () => new Error(`MCP '${name}' ${operation} timed out after ${budget}ms`), body);
  };
  return [
    buildTool({
      name: listName,
      description: `[MCP:${name}] List the resources (documents, files, records) this server can provide, with their URIs. Read one with ${readName}.`,
      schema: { type: 'object', properties: { cursor: { type: 'string', description: 'Pagination cursor from a previous call' } } },
      isDestructive: true,
      execute: async (args: any, context?: any) => run('resources/list', context, async (signal, remainingMs) => {
        const res = await client.listResources(args?.cursor ? { cursor: String(args.cursor) } : undefined,
          { signal, timeout: remainingMs() });
        remainingMs();
        const lines = (res?.resources || []).map((r: any) => `${r.uri} — ${r.name || r.title || ''}${r.mimeType ? ` (${r.mimeType})` : ''}${r.description ? ` — ${r.description}` : ''}`);
        let templates: string[] = [];
        try {
          const budget = Math.min(10_000, remainingMs());
          const listed = await withRequestDeadline<any>(budget, signal,
            () => new Error(`MCP '${name}' resources/templates/list timed out after ${budget}ms`),
            (templateSignal, templateRemaining) => client.listResourceTemplates(undefined,
              { signal: templateSignal, timeout: templateRemaining() }));
          templates = (listed?.resourceTemplates || []).map((r: any) => `${r.uriTemplate} — ${r.name || ''}${r.description ? ` — ${r.description}` : ''}`);
        } catch {
          // Templates are optional; Stop and the enclosing deadline are never optional.
          remainingMs();
        }
        remainingMs();
        return outcomeOk([
          lines.length ? lines.join('\n') : 'No resources listed.',
          templates.length ? `\nURI templates (fill in the {placeholders}):\n${templates.join('\n')}` : '',
          res?.nextCursor ? `\nMore: call again with cursor "${res.nextCursor}".` : '',
        ].join(''));
      }),
    }, governor),
    buildTool({
      name: readName,
      description: `[MCP:${name}] Read one resource by its URI (from ${listName}).`,
      schema: { type: 'object', properties: { uri: { type: 'string', description: 'The resource URI' } }, required: ['uri'] },
      isDestructive: true,
      execute: async (args: any, context?: any) => {
        const uri = String(args?.uri || '');
        if (!uri) return outcomeError('invalid_args', 'uri is required');
        return run('resources/read', context, async (signal, remainingMs) => {
          const res = await client.readResource({ uri }, { signal, timeout: remainingMs() });
          remainingMs();
          const parts = (res?.contents || []).map((c: any) => typeof c.text === 'string'
            ? c.text
            : `[binary ${c.mimeType || 'content'}, ${Math.round(String(c.blob || '').length * 0.75)} bytes — not shown as text]`);
          return outcomeOk(parts.join('\n') || '(empty resource)');
        });
      },
    }, governor),
  ];
}

import { Logger } from '../utils/logger';
import { engineEvents } from '../engine/events';
import { waitWithSignal, withRequestDeadline } from '../utils/request.deadline';

/**
 * MCP Tasks extension support (spec 2025-11-25, carried into the 2026-07-28 RC): a server may
 * answer tools/call with a TASK reference instead of an inline result — long-running work
 * (builds, deploys, big queries) then runs server-side while the client polls. Without this,
 * a task-shaped response would surface as a useless JSON blob and the actual result would be
 * lost. With it, BiMax polls `tasks/get` (backing off 500ms → 5s), streams status lines to the
 * footer, and fetches `tasks/result` when the task completes — inside the tool call's normal
 * timeout budget, so the agent loop and governor see an ordinary (just slower) tool call.
 *
 * Defensive by design: servers in the wild disagree on the envelope, so the task reference is
 * accepted both as `result.task.taskId` (spec shape) and the `_meta` fallback some SDKs emit.
 */

// zod ships with the MCP SDK; a passthrough schema lets us use client.request() without
// re-declaring the (still-evolving) task result shapes.
// eslint-disable-next-line @typescript-eslint/no-require-imports
const { z } = require('zod');
const PASSTHROUGH = z.object({}).passthrough();

const TERMINAL = new Set(['completed', 'failed', 'cancelled']);

export interface TaskRef {
  taskId: string;
  status?: string;
}

/** Pull a task reference out of a tools/call result, or null for ordinary inline results. */
export function extractTaskRef(res: any): TaskRef | null {
  const t = res?.task;
  if (t && typeof t.taskId === 'string' && t.taskId) {
    return { taskId: t.taskId, status: typeof t.status === 'string' ? t.status : undefined };
  }
  const meta = res?._meta?.['io.modelcontextprotocol/task'];
  if (meta && typeof meta.taskId === 'string' && meta.taskId) {
    return { taskId: meta.taskId, status: typeof meta.status === 'string' ? meta.status : undefined };
  }
  return null;
}

/**
 * Poll a task to a terminal state and return its result payload (the same shape a synchronous
 * tools/call would have returned). Throws on failure/cancellation/timeout — the caller's normal
 * error path then applies.
 */
export async function awaitTaskResult(
  client: any,
  serverName: string,
  toolName: string,
  ref: TaskRef,
  timeoutMs: number,
  signal?: AbortSignal,
): Promise<any> {
  let delay = 500;
  let status = ref.status || 'working';
  let statusMessage = '';
  const timeoutError = () =>
    new Error(
      `MCP task ${ref.taskId} (${serverName}/${toolName}) did not finish within ${Math.round(timeoutMs / 1000)}s (last status: ${status}).`,
    );
  // Stop is also sent to the server, once and without waiting for an acknowledgement.
  // A cancelled local wait cannot establish that a remote side effect was undone.
  const cancelRemote = () => {
    try {
      Promise.resolve(
        client.request({ method: 'tasks/cancel', params: { taskId: ref.taskId } }, PASSTHROUGH, { timeout: 1000 }),
      ).catch(() => {
        /* cancellation is best-effort */
      });
    } catch {
      /* a closed transport cannot acknowledge cancellation */
    }
  };
  signal?.addEventListener('abort', cancelRemote, { once: true });
  if (signal?.aborted) cancelRemote();
  try {
    return await withRequestDeadline(timeoutMs, signal, timeoutError, async (requestSignal, remainingMs) => {
      const request = (method: string) =>
        client.request({ method, params: { taskId: ref.taskId } }, PASSTHROUGH, {
          signal: requestSignal,
          timeout: remainingMs(),
        });
      while (!TERMINAL.has(status)) {
        if (status === 'input_required') {
          // Server-side elicitation mid-task — nothing an autonomous poll can answer.
          throw new Error(
            `MCP task ${ref.taskId} (${serverName}/${toolName}) needs additional input (status: input_required)` +
              `${statusMessage ? ` — ${statusMessage}` : ''}. Re-run the tool with the missing information supplied up front.`,
          );
        }
        await waitWithSignal(Math.min(delay, remainingMs()), requestSignal);
        remainingMs();
        delay = Math.min(delay * 1.5, 5000);

        const got = await request('tasks/get');
        remainingMs();
        const t = got?.task ?? got ?? {};
        status = String(t.status || 'working');
        statusMessage = typeof t.statusMessage === 'string' ? t.statusMessage : '';
        try {
          engineEvents.emit(
            'status',
            `MCP task ${serverName}/${toolName}: ${status}${statusMessage ? ` — ${statusMessage.slice(0, 80)}` : ''}`,
          );
        } catch {
          /* UI is best-effort */
        }
      }

      if (status !== 'completed') {
        throw new Error(
          `MCP task ${ref.taskId} (${serverName}/${toolName}) ended ${status}${statusMessage ? `: ${statusMessage}` : ''}.`,
        );
      }

      Logger.info(`[MCP] Task ${ref.taskId} (${serverName}/${toolName}) completed; fetching result.`);
      const result = await request('tasks/result');
      remainingMs();
      // Some servers nest the tool result under `result`, some return it directly.
      return result?.result ?? result;
    });
  } finally {
    signal?.removeEventListener('abort', cancelRemote);
  }
}

import { LLMProvider, Message } from '../core/llm.provider';
import { contentToText, isScreenshotObservationMessage } from '../core/multimodal';
import { Logger } from '../utils/logger';
import { fileStateCache } from './file-state-cache';
import { RECALL_PREFIX } from './recall';
import { archiveOutput } from '../context/output.archive';
import { ContextEvidence, evidenceSpan, fileEvidence, fileVersion, versionOfText } from '../context/evidence';
import { CONTINUATION_PREFIX, ContinuationState, isContinuationMessage } from '../context/continuation';
