export type ContextMode = 'smart' | 'full';

/**
 * ContextManager — bimax's layered context manager (the analogue of Claude Code's multi-layer
 * compaction stack). Before each API call in SMART mode it runs an ordered set of deterministic
 * passes, cheapest first, so we only pay for the expensive (LLM-summarizing) layer when the cheap
 * ones haven't freed enough room:
 *
 *   1. capToolResults  — truncate any single oversized tool result (no LLM, always).
 *   2. microCompact    — clear OLD tool results, keep the last N intact (no LLM, always).
 *   3. snip            — drop the oldest history beyond a protected tail for runaway sessions (no LLM).
 *   4. compact         — summarize older messages into one system note (LLM, only under token pressure).
 *
 * FULL mode skips all proactive passes — everything is sent until the API itself rejects it, at
 * which point reactiveCompact() recovers. The model always sees the whole history in full mode.
 */
// Module-level graph store reference injected by the container at startup.
// When set, checkAndCompact() injects a compact RepoMap outline at the capToolResults layer.
let _graphStore: IGraphStore | null = null;
/** The note compaction appends to a tool result it compressed; the raw output's archive handle follows it. */
const RAW_OUTPUT_NOTE = 'compressed to save context; the raw output is archived as';

/** The raw output's archive handle in a tool result compaction compressed, or null. */
function rawHandleIn(content: string): string | null {
  const at = content.lastIndexOf(`[${RAW_OUTPUT_NOTE} archive:`);
  if (at < 0) return null;
  return /^archive:[0-9a-f]{32}/.exec(content.slice(at + RAW_OUTPUT_NOTE.length + 2))?.[0] ?? null;
}

export function setContextManagerGraphStore(store: IGraphStore): void { _graphStore = store; }
/** The boot-wired native graph store, for code that needs a RepoMap outside the compaction loop. */
export function getContextManagerGraphStore(): IGraphStore | null { return _graphStore; }

// Pull "code-ish" focus terms from the latest user message to personalize the repo map: camelCase,
// snake_case, paths, or dotted names (setAuthCookie, auth.ts, src/auth). Plain prose words are
// skipped — boosting on "read"/"improve" would surface unrelated symbols. Empty for a vague request,
// so the map falls back to pure PageRank ranking.
export function focusTermsFromMessages(msgs: Message[]): string[] {
  const lastUser = [...msgs].reverse().find(m => m.role === 'user' && !isScreenshotObservationMessage(m));
  const text = lastUser ? contentToText(lastUser.content as any) : '';
  if (!text) return [];
  const terms = new Set<string>();
  for (const w of text.match(/[A-Za-z_][A-Za-z0-9_./-]{2,}/g) || []) {
    if (/[A-Z]/.test(w) || w.includes('_') || w.includes('/') || w.includes('.')) {
      terms.add(w);
      if (terms.size >= 40) break;
    }
  }
  return [...terms];
}

/** Inject a refreshed RepoMap without violating strict tool-result role ordering. */
export function injectRepoMap(messages: Message[], outline: string): Message[] {
  const withoutOldMap = messages.filter(m => !(
    (m.role === 'system' || m.role === 'user')
    && typeof m.content === 'string'
    && m.content.startsWith('[RepoMap]')
  ));
  if (!outline) return withoutOldMap;

  let lastUser = -1;
  for (let i = withoutOldMap.length - 1; i >= 0; i--) {
    if (withoutOldMap[i].role === 'user' && !isScreenshotObservationMessage(withoutOldMap[i])) {
      lastUser = i;
      break;
    }
  }
  const insertionIndex = lastUser >= 0 ? lastUser : withoutOldMap.length;
  // Screenshot observations are protocol turns, not new human requests. Anchor the refreshed map
  // before the latest real user turn so it never lands inside assistant → tool → assistant → user.
  const mapMsg: Message = { role: 'system', content: outline };
  return [
    ...withoutOldMap.slice(0, insertionIndex),
    mapMsg,
    ...withoutOldMap.slice(insertionIndex),
  ];
}

/**
 * Serialize the backlog for the summarizer, bounded to `limitChars`.
 *
 * Whole messages are kept from BOTH ends and the middle is elided, because the two ends are the
 * two things the five-section summary is actually asking for: the oldest messages carry the goal
 * and the original constraints, the newest carry what was just done and what is next. A plain
 * head- or tail-truncation loses one of them outright, and cutting mid-message hands the model a
 * severed JSON object to reason about.
 *
 * Under the limit this is exactly `JSON.stringify(messages)`, byte for byte.
 */
function serializeSummaryMessage(message: { role: string; content: unknown }, limitChars: number): string | null {
  // JSON quoting cannot shorten a primitive string. Skip copies of a provably unselectable
  // plain record, but preserve native behavior for hooks, accessors, proxies and nested values.
  if (message && typeof message === 'object' && !types.isProxy(message)) {
    const content = Object.getOwnPropertyDescriptor(message, 'content');
    if (content?.enumerable && 'value' in content && typeof content.value === 'string'
      && content.value.length > limitChars) {
      const prototype = Object.getPrototypeOf(message);
      if ((prototype === Object.prototype || prototype === null) && !('toJSON' in message)) {
        const fields = Object.values(Object.getOwnPropertyDescriptors(message));
        if (fields.every(field => 'value' in field && (field.value === null
          || ['string', 'number', 'boolean', 'undefined'].includes(typeof field.value)))) return null;
      }
    }
  }
  return JSON.stringify(message);
}

export function boundSummaryInput(messages: { role: string; content: unknown }[], limitChars: number): string {
  if (!Number.isFinite(limitChars) || limitChars < 2) throw new RangeError('Summary input budget must hold a JSON array.');
  limitChars = Math.floor(limitChars);
  const encoded = messages.map(m => serializeSummaryMessage(m, limitChars));
  const wholeLength = 2 + encoded.reduce((n, text) => n + (text?.length ?? limitChars + 1), 0) + Math.max(0, encoded.length - 1);
  if (wholeLength <= limitChars) return `[${encoded.join(',')}]`;

  const markerFor = (dropped: number): string => JSON.stringify({ role: 'system', content: `[${dropped} message(s) omitted from this summarization input — consult the continuation state or archive for retained evidence]` });
  // Reserve the actual largest marker, including commas. Tiny budgets still return valid bounded JSON.
  let remaining = limitChars - 2 - markerFor(encoded.length).length;
  if (remaining < 0) return '[]';
  const head: string[] = [], tail: string[] = [];
  let headChars = 0, tailChars = 0, lo = 0, hi = encoded.length - 1;
  let headBlocked = false, tailBlocked = false;
  while (lo <= hi && !(headBlocked && tailBlocked)) {
    const takeHead = !headBlocked && (tailBlocked || headChars <= tailChars);
    const text = encoded[takeHead ? lo : hi];
    const cost = text === null ? Number.POSITIVE_INFINITY : text.length + 1;
    if (text === null || cost > remaining) {
      if (takeHead) headBlocked = true; else tailBlocked = true;
      continue;
    }
    remaining -= cost;
    if (takeHead) { head.push(text); lo++; headChars += cost; }
    else { tail.push(text); hi--; tailChars += cost; }
  }
  const dropped = encoded.length - head.length - tail.length;
  return `[${[...head, markerFor(dropped), ...tail.reverse()].join(',')}]`;
}

export class ContextManager {
  private readonly MAX_TOKENS: number;
  private readonly COMPACT_THRESHOLD = 0.7; // summarize when reaching 70% of the window
  private readonly WARN_THRESHOLD = 0.5;    // one-time early warning at 50%
  private currentTokens: number = 0;
  private halfWindowWarnEmitted = false;    // fire the 50% nudge only once per session

  // Cheap-pass tuning. Deliberately conservative so multi-step tasks keep the context they need.
  private readonly TOOL_RESULT_MAX_CHARS = 16000; // cap on a single tool result
  private readonly KEEP_RECENT_TOOL_RESULTS = 6;  // most recent tool outputs left fully intact
  private readonly MIN_ARCHIVED_RESULT_CHARS = 512; // shorter cleared results get the short stub, unarchived
  private readonly SNIP_TRIGGER_MESSAGES = 100;   // only guard against truly runaway histories
  private readonly SNIP_KEEP_TAIL = 60;
  // Snip is the LAST resort, so it sits above COMPACT_THRESHOLD: summarizing gets first refusal and
  // snip only runs when that did not shrink the window enough. Both are fractions of the window, so
  // neither is a pinned token count.
  private readonly SNIP_PRESSURE = 0.85;
  // The degenerate shape the message-count guard was actually written for: thousands of tiny
  // messages that never accumulate tokens but do cost per-request overhead.
  private readonly SNIP_HARD_MESSAGES = 1200;
  /**
   * What compact() may hand the summarizer, in characters (~24k tokens at 4 chars/token).
   *
   * The summarizer runs on the LITE model, and the input it was being given was the whole backlog
   * — which, by construction, is ~70% of the MAIN model's window. Pairing a 200k main model with a
   * 32k lite model is an ordinary, supported configuration, and it made every compaction on a long
   * session fail. This is deliberately sized for the smallest model anyone would sensibly route
   * `lite` to rather than for the main window, because the main window says nothing about it.
   */
  private readonly SUMMARY_INPUT_CHARS = 96_000;
  private readonly RESTORE_BUDGET_CHARS = 40_000; // total post-compact file re-injection budget (~10k tok)

  /**
   * What this session showed the model and where it came from (record 50 step 5): recalled memory, restored files and
   * archived tool output. A span goes stale when the source it was taken from changes.
   */
  readonly evidence = new ContextEvidence();
  /** What compaction removed that a long task must keep: the user's words, commands run, the assistant's claims. */
  readonly continuation = new ContinuationState();

  // Real-usage overhead calibration (C4): our estimate only sees `messages`, but the request also
  // carries the system prompt + tool schemas (10-30k tokens the estimate is blind to). The provider's
  // usage report includes everything, so (real − estimate-of-what-we-sent) measures that invisible
  // overhead; folding it into every pressure ratio makes compaction fire when the REQUEST nears the
  // window, not when the visible history does — which was systematically late.
  private lastSentEstimate = 0;
  private overheadTokens = 0;

  // System messages the manager (or the persona) re-generates fresh each turn/compaction. Preserving
  // them across compactions was pure context rot: every compact accreted another stale summary +
  // stale file restorations that all later compacts dutifully kept forever.
  private static readonly TRANSIENT_SYSTEM_PREFIXES = [
    '[Previous Context Summary]',
    '[Post-Compact Restoration',
    '[RepoMap]',
    '[TurnContext]',
    '[ContextManager]',
    '[Older messages aggressively compacted',
    // Recalled memory is evidence for the turn it was retrieved for. Kept durable, a recalled fact
    // outlived its freshness and could never be refreshed (record 47, A04); AgentLoop forgets the
    // session's recalls when compaction drops one, so a question still in play recalls again.
    RECALL_PREFIX,
    // Re-rendered from ContextManager.continuation into every compacted window; an old copy is never kept.
    CONTINUATION_PREFIX,
  ];

  private isTransientSystem(m: Message): boolean {
    return m.role === 'system' && typeof m.content === 'string' &&
      ContextManager.TRANSIENT_SYSTEM_PREFIXES.some(p => (m.content as string).startsWith(p));
  }

  // Epoch counter: incremented at the start of each compact() call.
  // Lets callers detect whether compaction ran between two points in time (ABA prevention).
  private compactionEpoch = 0;

  // Default is a safe generic window (most modern OpenAI-compatible models are >=128k). The agent
  // loop passes the user-configured value when set, so this only applies if nothing wired a real one.
  constructor(private llm: LLMProvider, maxTokens: number = 128000) {
    this.MAX_TOKENS = maxTokens > 0 ? maxTokens : 128000;
  }

  /** Returns the current compaction epoch. Callers can snapshot this and later call checkEpoch(). */
  getEpoch(): number { return this.compactionEpoch; }

  /**
   * Returns true if the epoch hasn't changed since `priorEpoch` was captured — meaning no
   * compaction ran between then and now, so any buffered messages are still valid.
   */
  checkEpoch(priorEpoch: number): boolean { return this.compactionEpoch === priorEpoch; }

  /** Called by the AgentLoop when the LLM returns token usage. */
  updateTokens(promptTokens: number) {
    this.currentTokens = promptTokens;
    // Calibrate the invisible request overhead (system prompt + tool schemas + serialization):
    // real reported prompt tokens minus our estimate of the history we actually sent.
    if (this.lastSentEstimate > 0 && promptTokens > 0) {
      this.overheadTokens = Math.max(0, promptTokens - this.lastSentEstimate);
    }
  }

  /** Estimated request tokens = visible history + calibrated invisible overhead (C4). */
  private effectiveTokens(messages: Message[]): number {
    return this.estimateTokens(messages) + this.overheadTokens;
  }

  /**
   * Run the layered compaction before an API call. In FULL mode this is a no-op (reactiveCompact
   * still recovers on a 413). In SMART mode it applies the cheap passes always, then summarizes
   * only if still over the token threshold.
   */
  async checkAndCompact(messages: Message[], mode: ContextMode = 'smart', signal?: AbortSignal): Promise<Message[]> {
    signal?.throwIfAborted();
    if (mode === 'full') {
      // Even with no compaction, record what we're sending so updateTokens can calibrate overhead.
      this.lastSentEstimate = this.estimateTokens(messages);
      return messages;
    }

    // Layer 0 — deterministic in-process log compression, only under TOKEN PRESSURE. The default
    // compactor is compressBacklog: bounded, deterministic, in-process, and code-safe (skipCode
    // keeps code verbatim; error/warning lines are always preserved). Opt out entirely with
    // BIMAX_DISABLE_COMPRESSION=1.
    //
    // The optional Headroom Kompress ML compressor is STRICTLY opt-in (BIMAX_ENABLE_HEADROOM=1):
    // it spawns a separately-provisioned localhost sidecar, and NOTHING on the foreground turn path
    // may create a Python venv, pip-install, download a model, or open a listener. Without the
    // explicit opt-in it is never imported, so a user turn does deterministic in-process work only.
    let msgs: Message[] = messages;
    const pressureRatio = this.effectiveTokens(messages) / this.MAX_TOKENS;
    if (process.env.BIMAX_DISABLE_COMPRESSION !== '1' && pressureRatio >= this.COMPACT_THRESHOLD) {
      // Which model the saving is attributed to (for the per-model /headroom report).
      let model = 'unknown';
      try { const c = require('../engine/config').getConfig(); model = c.model || c.liteModel || 'unknown'; } catch { /* config optional */ }

      let saved = 0;
      let usedProxy = false;
      if (process.env.BIMAX_ENABLE_HEADROOM === '1') {
        // Explicitly-enabled ML path. Fire-and-forget warm-up (idempotent); NEVER wait for the
        // sidecar in front of a turn — if it isn't ready, the native pass below covers this turn.
        import('./headroomProxy').then(m => m.ensureHeadroomProxy().catch(() => {})).catch(() => {});
        const proxied = await proxyCompress(messages as any, model === 'unknown' ? '' : model, this.MAX_TOKENS);
        if (proxied) {
          const before = this.estimateTokens(messages);
          const after = this.estimateTokens(proxied.messages as Message[]);
          if (after > before) {
            // Sanity net: a compactor that GROWS the context is a regression. Keep the original.
            Logger.warn(`[Headroom] proxy returned a LARGER context (${before} → ${after} tok); discarding its result.`);
          } else {
            // Stack the lossless native pass on top to also collapse repetitive log spam.
            const stacked = compressBacklog(proxied.messages as any, { protectRecent: 0, skipCode: true });
            msgs = stacked.messages as Message[];
            const finalAfter = this.estimateTokens(msgs);
            saved = Math.max(0, before - finalAfter, proxied.saved);
            usedProxy = true;
            if (saved > 0) recordCompression(model, before, Math.max(0, before - saved), 'proxy');
          }
        }
      }
      if (!usedProxy) {
        // Default deterministic path: collapse repetitive log/ANSI spam in tool outputs. skipCode
        // guarantees code passes through VERBATIM; error/warning lines are always kept.
        const { messages: compressed, stats } = compressBacklog(messages as any, { protectRecent: 0, skipCode: true });
        msgs = compressed as Message[];
        saved = stats.saved;
        if (saved > 0) recordCompression(model, stats.compressedBefore, stats.compressedAfter, 'native');
      }
      msgs = this.keepRawOutput(messages, msgs);
      if (saved > 0) {
        Logger.info(`[Headroom] ${usedProxy ? 'Kompress proxy' : 'native'} compression saved ~${saved} tokens (model ${model})`);
        // Token-meter refresh only. This must NOT be 'graph_changed' — the TUI renders that as
        // "code graph updated", which is a lie for a context-token refresh.
        try { engineEvents.emit('context_changed'); } catch { /* best-effort */ }
      }
    }

    msgs = this.capToolResults(msgs);
    // microCompact only under pressure (C3): running it unconditionally destroyed old tool results
    // even at 5% usage (context the model may still need, for zero benefit) AND moved its stub
    // boundary every round — rewriting history bytes mid-prefix, churning the provider cache.
    if (this.effectiveTokens(msgs) / this.MAX_TOKENS >= this.WARN_THRESHOLD) {
      msgs = this.microCompact(msgs);
    }
    msgs = this.snip(msgs);

    // RepoMap (aider-style): refresh it EVERY turn so it reflects current files and re-ranks toward
    // THIS request (focus terms from the latest user message). Strip any prior map first so history
    // keeps exactly one copy — current, personalized, no accumulation.
    //
    // PLACEMENT MATTERS: the map is injected immediately BEFORE the latest user message, never at
    // messages[0]. A per-turn-changing message at the head of the conversation invalidates the
    // provider's prompt-prefix cache for the ENTIRE history on every single turn — the silent tax
    // that made long sessions slow and expensive. Near the tail, only the last few messages are
    // uncached; everything earlier stays a byte-stable, cacheable prefix. (Within one agent-loop
    // turn the position is stable too — tool rounds append after it.)
    if (process.env.BIMAX_REPO_MAP === '0') msgs = injectRepoMap(msgs, '');
    if (_graphStore && process.env.BIMAX_REPO_MAP !== '0') {
      try {
        // Cross-repo (PR3): merges every indexed repo in a multi-repo workspace into one map; with a
        // single repo it returns exactly the old single-repo outline. Sync — never blocks on disk.
        const outline = crossRepoMapSync(_graphStore, 1500, focusTermsFromMessages(msgs));
        msgs = injectRepoMap(msgs, outline);
      } catch { /* pagerank optional — never fail the compaction loop */ }
    }

    // Heavy fallback: summarize only when the cheap passes left us above the threshold.
    // Ratio includes the calibrated request overhead (system prompt + schemas) — see updateTokens.
    const ratio = this.effectiveTokens(msgs) / this.MAX_TOKENS;

    // One-time early nudge at 50% so the model can be conservative before forced compaction.
    if (!this.halfWindowWarnEmitted && ratio >= this.WARN_THRESHOLD) {
      this.halfWindowWarnEmitted = true;
      Logger.warn(`[ContextManager] Context window ${Math.round(ratio * 100)}% full — approaching compaction threshold.`);
      msgs = [
        ...msgs,
        {
          role: msgs[msgs.length - 1]?.role === 'tool' ? 'user' as const : 'system' as const,
          content: `[ContextManager] You have used ~${Math.round(ratio * 100)}% of your context window. To avoid forced compaction, prefer targeted reads (startLine/endLine), release unneeded context with FreeContextTool, and avoid re-reading files you already have.`,
        },
      ];
    }

    if (ratio > this.COMPACT_THRESHOLD) {
      Logger.warn(`[ContextManager] ${Math.round(ratio * 100)}% after cheap passes — summarizing older history.`);
      msgs = await this.compact(msgs, signal);
    }
    // What we're actually sending this round — updateTokens diffs the provider's real usage
    // against this to keep the overhead calibration current.
    signal?.throwIfAborted();
    this.lastSentEstimate = this.estimateTokens(msgs);
    return msgs;
  }

  /**
   * Layer 1 — cap a single oversized tool result so one giant Bash/log dump can't dominate the
   * window. Keeps the head and tail (where the signal usually is) and notes how much was elided.
   *
   * CODE IS NEVER ELIDED: a source-file read or code-dense output passes through verbatim no
   * matter its size (`looksLikeCode`). Partially-elided code is worse than either extreme — the
   * model edits against a file it believes it has whole. Code leaves the window only via the
   * explicit, whole-result mechanisms (micro-compact stubs of OLD results, FreeContextTool), never
   * via silent mid-content truncation.
   */
  /**
   * Compression is lossy — order, individual samples and ANSI are gone — and it ran before any archive existed, so a
   * compressed result could later be cleared with only its compressed form saved, or none at all (audit 51, U11). Each
   * tool result compression changed is archived raw first and carries that handle; a result that would not stay
   * shorter with the note, or whose raw form cannot be saved, keeps its compressed form as before.
   */
  private keepRawOutput(before: Message[], after: Message[]): Message[] {
    if (before.length !== after.length) return after;
    return after.map((m, i) => {
      const raw = before[i]?.content;
      if (m.role !== 'tool' || typeof raw !== 'string' || typeof m.content !== 'string' || m.content === raw) return m;
      if (raw.length < this.MIN_ARCHIVED_RESULT_CHARS || rawHandleIn(m.content)) return m;
      const handle = this.archive(raw);
      if (!handle) return m;
      // A log keeps its shape: the line count and first failures of the raw output lead the compressed form (step 6d).
      const summary = carriedSummary(m.content) ? null : summarizeLog(raw);
      const content = `${summary ? `${summary}\n` : ''}${m.content}\n[${RAW_OUTPUT_NOTE} ${handle} (ContextArchiveTool)]`;
      return content.length < raw.length ? { ...m, content } : m;
    });
  }

  private capToolResults(messages: Message[]): Message[] {
    const max = this.TOOL_RESULT_MAX_CHARS;
    let trimmed = 0;
    const out = messages.map(m => {
      if (m.role !== 'tool' || typeof m.content !== 'string' || m.content.length <= max) return m;
      if (looksLikeCode(m.content)) return m; // code survives every compaction path verbatim
      trimmed++;
      const head = m.content.slice(0, Math.floor(max * 0.7));
      const tail = m.content.slice(-Math.floor(max * 0.2));
      const elided = m.content.length - head.length - tail.length;
      // The whole result is archived first, so the cut middle stays recoverable instead of silently lost. A result
      // compression already archived raw keeps that handle: the raw output is the better original.
      const archived = rawHandleIn(m.content) ?? this.archive(m.content);
      const where = archived ? `; the full result is archived as ${archived} (ContextArchiveTool)` : '';
      const summary = carriedSummary(m.content) ? null : summarizeLog(m.content);
      return { ...m, content: `${summary ? `${summary}\n` : ''}${head}\n\n… [${elided} chars elided to save context${where}] …\n\n${tail}` };
    });
    if (trimmed) Logger.info(`[ContextManager] Capped ${trimmed} oversized tool result(s).`);
    return out;
  }

  /**
   * Layer 2 — micro-compact: clear the content of OLD tool results, keeping the most recent
   * KEEP_RECENT_TOOL_RESULTS intact. No LLM call. The tool message itself (and its tool_call_id)
   * is preserved so tool_use/tool_result pairing never breaks — only its body becomes a stub.
   */
  /** Archive a tool result before it leaves the prompt, record it as evidence, and return its handle (null if unsaved). */
  private archive(text: string): string | null {
    const archived = archiveOutput(text);
    if (!archived) return null;
    this.evidence.admit(evidenceSpan({
      sourceId: `tool-output:${archived.id}`,
      sourceVersion: `sha256:${archived.sha256}`,
      locator: { kind: 'tool-output', handle: archived.handle },
      rawHandle: archived.handle,
      text: text.slice(0, 280),
      scope: {},
      derivedFrom: [],
      kind: 'observation',
    }));
    return archived.handle;
  }

  private microCompact(messages: Message[]): Message[] {
    const toolIdx = messages.map((m, i) => (m.role === 'tool' ? i : -1)).filter(i => i >= 0);
    if (toolIdx.length <= this.KEEP_RECENT_TOOL_RESULTS) return messages;

    const clearBefore = toolIdx[toolIdx.length - this.KEEP_RECENT_TOOL_RESULTS];
    let cleared = 0;
    const out = messages.map((m, i) => {
      if (m.role !== 'tool' || i >= clearBefore) return m;
      if (typeof m.content === 'string' && m.content.startsWith('[tool result cleared')) return m; // already stubbed
      cleared++;
      // Code is never silently TRUNCATED: an old code result is evicted WHOLE and replaced with a
      // resolvable reference — the file path when the read header carries one — so the model re-reads
      // real content instead of reasoning over a half-cut ghost.
      //
      // A re-read returns the file as it is NOW, and the agent edits files: read foo.ts → evict →
      // edit foo.ts → a re-read hands back different bytes. So the stub never promises that re-reading
      // gets the original back.
      //
      // What it can offer is the plumbing this comment once asked for instead of a bare hash: the cleared
      // text is archived under its content hash before the stub replaces it, and ContextArchiveTool checks
      // that hash on every read. The handle returns the earlier output, labelled as earlier; a re-read
      // returns the current file (record 50 step 5). When the archive cannot be written, the stub says
      // nothing about one.
      // A stub with a handle runs to about 130 characters, so a result shorter than MIN_ARCHIVED_RESULT_CHARS
      // keeps the short stub instead: archiving it would make micro-compaction grow the context it shrinks.
      const archived = typeof m.content === 'string' && (rawHandleIn(m.content)
        ?? (m.content.length >= this.MIN_ARCHIVED_RESULT_CHARS ? this.archive(m.content) : null));
      const saved = archived ? ` The cleared output is archived as ${archived} (ContextArchiveTool).` : '';
      if (typeof m.content === 'string' && looksLikeCode(m.content)) {
        const file = m.content.match(/^FILE\s+(.+?):/m)?.[1];
        return {
          ...m,
          content: file
            ? `[tool result cleared to save context — code from ${file}; re-read it for the current contents, which may have changed since.${saved}]`
            : `[tool result cleared to save context — code output; re-run the tool for a current result, which may differ from the cleared one.${saved}]`,
        };
      }
      const stub = archived
        ? `[tool result cleared to save context — archived as ${archived}; read it back with ContextArchiveTool]`
        : '[tool result cleared to save context]';
      // A cleared log keeps its one-line summary, when the stub stays well under what it replaces (step 6d).
      const summary = archived && typeof m.content === 'string' ? carriedSummary(m.content) ?? summarizeLog(m.content) : null;
      const withSummary = summary ? `${stub}\n${summary}` : stub;
      return { ...m, content: typeof m.content === 'string' && withSummary.length * 2 <= m.content.length ? withSummary : stub };
    });
    if (cleared) Logger.info(`[ContextManager] Micro-compacted ${cleared} old tool result(s).`);
    return out;
  }

  /**
   * Reactive cheap recovery for a provider-reported context overflow. Unlike the proactive
   * micro-compact pass in checkAndCompact(), this is intentionally not pressure-gated: the
   * provider has already told us the request is too large. Tool-call/result structure remains
   * intact because microCompact only replaces old result bodies by message id.
   */
  reactiveDrain(messages: Message[]): { messages: Message[]; changed: boolean } {
    const drained = this.microCompact(messages);
    return {
      messages: drained,
      changed: drained.some((message, index) => message !== messages[index]),
    };
  }

  /**
   * Layer 3 — snip: a blunt guard for runaway sessions. When the non-system history grows past
   * SNIP_TRIGGER_MESSAGES, keep only the last SNIP_KEEP_TAIL of it (plus all system messages),
   * never letting the kept window begin on an orphaned tool result.
   */
  private snip(messages: Message[]): Message[] {
    this.adoptCarriedContinuation(messages);
    const nonSystem = messages.filter(m => m.role !== 'system');
    if (nonSystem.length <= this.SNIP_TRIGGER_MESSAGES) return messages;

    // A message count is not token pressure, and snipping on the count alone made this blunt guard
    // the ONLY control on every long session. Measured over 150 realistic rounds: the session
    // finished at the SAME 52,143 tokens whether the window was 32k, 128k, 200k or 1M — 5.2% of a
    // 1M window — because snip fired five times on the count while every token-driven layer below
    // its threshold stayed asleep. capToolResults never capped, microCompact never stubbed, and
    // compact() — the one pass that writes the goal/progress/decisions note — was never called
    // once. What the user sees is ~41 messages disappearing every ~20 rounds and the model losing
    // the thread, on a window that was three-quarters empty.
    //
    // So the count only nominates a session; pressure decides. Below SNIP_PRESSURE the ladder that
    // is designed to preserve meaning (cap → stub → summarize) gets first refusal, and snip goes
    // back to being what its name says: the last resort when summarizing did not shrink enough.
    // SNIP_HARD_MESSAGES still catches the degenerate case this guard was written for — thousands
    // of tiny messages that never accumulate tokens but do blow up per-request overhead.
    const pressure = this.effectiveTokens(messages) / this.MAX_TOKENS;
    if (pressure < this.SNIP_PRESSURE && nonSystem.length <= this.SNIP_HARD_MESSAGES) return messages;

    const tail = retainRecentHistory(nonSystem, this.SNIP_KEEP_TAIL);
    this.compactionEpoch++;
    this.continuation.absorb(nonSystem.filter(m => !tail.includes(m)), (text) => this.archive(text));
    const system = messages.filter(m => m.role === 'system' && !isContinuationMessage(m));
    Logger.warn(`[ContextManager] Snipped ${nonSystem.length - tail.length} old message(s) (runaway history guard).`);
    return [...system, ...this.continuationMessages(), ...tail];
  }

  // Identity avoids re-tokenizing unchanged strings. Mutable content parts are compared as rendered text.
  private tokenCache = new WeakMap<object, { text: string; reasoning: unknown; tokens: number }>();

  private countMessageTokens(m: Message): number {
    const key = m as unknown as object;
    const text = contentToText(m.content);
    const hit = this.tokenCache.get(key);
    if (hit && hit.text === text && hit.reasoning === m.reasoning_content) return hit.tokens;
    const tokens = countTokens(`${text}${m.reasoning_content || ''}`);
    this.tokenCache.set(key, { text, reasoning: m.reasoning_content, tokens });
    return tokens;
  }

  estimateTokens(messages: Message[]): number {
    // +1 per message ≈ the joining newline the old whole-conversation encode counted.
    let total = 0;
    for (const m of messages) total += this.countMessageTokens(m) + 1;
    return total;
  }

  /** Layer 4 — summarize older messages into a single system note (the one LLM-backed pass). */
  async compact(messages: Message[], signal?: AbortSignal): Promise<Message[]> {
    signal?.throwIfAborted();
    this.adoptCarriedContinuation(messages);
    // Keep only DURABLE system messages (C2). Transients are either superseded by this compact
    // (the previous summary — folded into the new summarization input below — and the previous
    // file restorations) or regenerated fresh next turn (RepoMap, TurnContext, pressure nudges).
    // The old behavior kept every one of them forever: each compaction accreted another stale
    // summary + up to 250KB of stale restorations that all later compactions preserved.
    const systemMessages = messages.filter(m => m.role === 'system' && !this.isTransientSystem(m));
    const priorSummaries = messages.filter(m =>
      this.isTransientSystem(m) && (m.content as string).startsWith('[Previous Context Summary]'));

    // Preserve the last 15 messages. Trim any leading orphan tool results so the window can't
    // begin with a `tool` message whose parent assistant tool_calls was cut.
    const recentMessages = retainRecentHistory(messages, 15);

    const olderMessages = messages.filter(m =>
      m.role !== 'system' && !recentMessages.includes(m)
    );

    // Nothing to summarize — return BEFORE touching the epoch, so checkEpoch() doesn't see a
    // phantom "compaction happened" when none did (which falsely invalidated buffered messages).
    if (olderMessages.length === 0) {
      return messages;
    }

    // Increment epoch only now that a real compaction is underway, so a concurrent caller can
    // detect a compaction in flight.
    this.compactionEpoch++;
    const myEpoch = this.compactionEpoch;

    Logger.info(`[ContextManager] Summarizing ${olderMessages.length} older messages (epoch ${myEpoch})...`);

    // Flatten any multimodal (image) content to text before serializing: a base64 data URL can be
    // megabytes, and embedding it in the summary prompt would blow up tokens/cost and likely 400 the
    // very summarizer meant to SHRINK context. contentToText replaces image parts with "[image]".
    // The previous compaction's summary leads the input so its goal/decisions/progress carry forward
    // into the NEW summary instead of being silently dropped with the transient strip above.
    const olderForSummary = [
      ...priorSummaries.map(m => ({ role: 'system' as const, content: contentToText(m.content) })),
      // The active request stays verbatim in the main window, but the summarizer also needs its
      // goal: it may otherwise see only tool activity or a summary of a previous request.
      ...(latestHumanRequest(messages) ? [{ role: 'user' as const, content: contentToText(latestHumanRequest(messages)!.content) }] : []),
      ...olderMessages.map(m => ({ ...m, content: contentToText(m.content) })),
    ];

    const summaryPrompt: Message[] = [
      {
        role: 'system',
        content: `You are summarizing a coding session. Output ONLY these five sections with NO other prose:

## Goal
One sentence: the exact task or question the user gave.

## Progress
Bullet list of what was actually completed — include file paths, function names, commands run, and test results.

## Key Decisions
Up to 3 bullets: non-obvious choices made and the reason (e.g. "Used X not Y because..."). Omit if nothing non-obvious occurred.

## Next Steps
What should happen next to finish the task. If the task is done, write "DONE".

## Relevant Files
Comma-separated list of files created, modified, or important to the task.`,
      },
      {
        role: 'user',
        content: `Summarize these messages into the five sections above:\n${boundSummaryInput(olderForSummary, this.SUMMARY_INPUT_CHARS)}`,
      },
    ];

    let summaryText = '';
    try {
      summaryText = await this.collectSummary(summaryPrompt, signal);
    } catch (e: any) {
      signal?.throwIfAborted();
      const overflowed = /too long|too large|maximum context|context length|context window/i.test(String(e?.message ?? ''))
        || e?.code === 'context_length_exceeded' || e?.code === 'prompt_too_long' || e?.status === 413;
      if (overflowed) {
        Logger.warn('[ContextManager] Summarizer rejected the input — retrying at a quarter of the budget.');
        try {
          const retry: Message[] = [summaryPrompt[0], { role: 'user', content: `Summarize these messages into the five sections above:\n${boundSummaryInput(olderForSummary, Math.floor(this.SUMMARY_INPUT_CHARS / 4))}` }];
          summaryText = await this.collectSummary(retry, signal);
        } catch (retryError: any) {
          signal?.throwIfAborted();
          Logger.error(`[ContextManager] Reduced summary failed: ${retryError.message}`);
        }
      } else Logger.error(`[ContextManager] Failed to summarize context: ${e.message}`);
    }
    signal?.throwIfAborted();

    // If another compact() call ran while we were awaiting the LLM, our result is stale —
    // return original messages unchanged so the later epoch's result takes precedence.
    if (this.compactionEpoch !== myEpoch) {
      Logger.warn(`[ContextManager] Epoch mismatch after compact (started ${myEpoch}, now ${this.compactionEpoch}) — discarding stale result.`);
      return messages;
    }

    const summaryMsg: Message = {
      role: 'system',
      content: `[Previous Context Summary]\n${summaryText}`,
    };
    // The summary is a narrative a summarizer may get wrong or leave empty, so it is not the only record: the
    // continuation state keeps what these messages said, word for word (record 50 step 6).
    // Continuation and evidence publish together only after asynchronous restoration validates this epoch.

    // Post-compact file restoration: re-inject recently-read files as synthetic attachments
    // so the model doesn't need to re-read files it was actively working with. Bounded by a TOTAL
    // budget (C5): unbudgeted, 5 files × 50KB could pour ~60k tokens right back into the window the
    // compaction just fought to free. Most-recent files first; one oversized file can't starve a
    // smaller, newer one behind it.
    const recentReads = fileStateCache.getRecentReads();
    const fileAttachments: Message[] = [];
    let restoreUsed = 0, restoreSkipped = 0, restoreStale = 0;
    const sourceVersions: Array<{ id: string; version: string | null }> = [];
    const restoredEvidence: ReturnType<typeof fileEvidence>[] = [];
    for (const f of recentReads) {
      if (restoreUsed + f.content.length > this.RESTORE_BUDGET_CHARS) { restoreSkipped++; continue; }
      // Cached content whose file was edited externally (or deleted) since the read must NEVER be
      // re-injected as current — that silently feeds the model a stale version of the file it is about
      // to modify. "Verified unchanged on disk" is a claim about bytes, and a matching mtime is not
      // proof: a rewrite that put the old mtime back was restored as current (record 47, A01). So the
      // file is read now and compared with the hash taken when it was cached; a read cached without a
      // hash is verified only when it was the complete file, by comparing the text itself. A preview of
      // a large file has neither, so it is never restored as the file. The comparison runs through the
      // session's evidence, so an earlier restoration of a file that has since changed goes stale too.
      const claimed = f.fileHash ? `sha256:${f.fileHash}` : f.complete ? versionOfText(f.content) : null;
      const current = await fileVersion(f.path, signal);
      signal?.throwIfAborted();
      sourceVersions.push({ id: `file:${f.path}`, version: current });
      let mtimeHolds = false;
      try {
        // eslint-disable-next-line @typescript-eslint/no-require-imports
        mtimeHolds = (require('fs') as typeof import('fs')).statSync(f.path).mtimeMs === f.mtime;
      } catch { /* deleted/unreadable — do not restore */ }
      if (!claimed || !mtimeHolds || current !== claimed) { restoreStale++; continue; }
      restoreUsed += f.content.length;
      // A partial read is labeled as exactly that — never presented as the complete file.
      const scope = f.complete
        ? 'complete file'
        : `PARTIAL read (offset ${f.offset}${f.limit >= 0 ? `, limit ${f.limit}` : ''}) — NOT the whole file`;
      fileAttachments.push({
        role: 'system' as const,
        content: `[Post-Compact Restoration — ${f.path} — ${scope}, verified unchanged on disk]\n${f.content}`,
      });
      restoredEvidence.push(fileEvidence(f.path, f.content, claimed, { partial: !f.complete }));
    }

    if (fileAttachments.length > 0 || restoreSkipped > 0 || restoreStale > 0) {
      Logger.info(`[ContextManager] Restored ${fileAttachments.length} recently-read file(s) post-compact${restoreSkipped ? ` (${restoreSkipped} skipped — over the ${this.RESTORE_BUDGET_CHARS}-char budget)` : ''}${restoreStale ? ` (${restoreStale} not restored — not verified unchanged on disk)` : ''}.`);
    }

    signal?.throwIfAborted();
    if (this.compactionEpoch !== myEpoch) return messages;
    if (!summaryText.trim()) {
      const saved = this.archive(JSON.stringify(olderForSummary));
      const prior = priorSummaries.map(m => contentToText(m.content)).join('\n');
      summaryText = `${prior ? `${prior}\n` : ''}[Context summary unavailable; ${saved ? `earlier conversation archived as ${saved} (ContextArchiveTool)` : 'only the bounded continuation evidence is retained'}]`;
      summaryMsg.content = `[Previous Context Summary]\n${summaryText}`;
    }
    this.continuation.absorb(olderMessages, (text) => this.archive(text));
    for (const source of sourceVersions) this.evidence.sourceChanged(source.id, source.version);
    this.evidence.admitAll(restoredEvidence);

    const compacted = [...systemMessages, summaryMsg, ...this.continuationMessages(), ...fileAttachments, ...recentMessages];
    this.currentTokens = this.estimateTokens(compacted);
    return compacted;
  }

  /** Aux requests have a whole-operation deadline; late tokens never publish into live context. */
  private async collectSummary(messages: Message[], parent?: AbortSignal): Promise<string> {
    return withRequestDeadline(180_000, parent, () => new Error('Context summary deadline exceeded.'), async (signal) => {
      let text = '';
      for await (const event of this.llm.chat(messages, { lite: true, signal })) {
        signal.throwIfAborted();
        if (event.type === 'error') {
          const error = new Error(event.message) as Error & { code?: string };
          if (event.kind === 'context') error.code = 'context_length_exceeded';
          throw error;
        }
        if (event.type === 'truncated') throw new Error('Context summary was truncated.');
        if (event.type === 'token') {
          text += event.text;
          if (text.length > 32_000) throw new Error('Context summary exceeded its output bound.');
        }
      }
      signal.throwIfAborted();
      if (!text.trim()) throw new Error('Context summary was empty.');
      return text;
    });
  }

  /**
   * A manager rebuilt mid-task — the persona makes a new one when the context window changes, as on a model switch —
   * takes over the continuation state its predecessor left in the window, before anything strips that block (step 8).
   */
  private adoptCarriedContinuation(messages: Message[]): void {
    if (!this.continuation.isEmpty()) return;
    const carried = messages.find((m) => isContinuationMessage(m));
    if (carried && typeof carried.content === 'string') this.continuation.adopt(carried.content);
  }

  /** The continuation state as one system message, or nothing while it is empty. */
  private continuationMessages(maxChars?: number): Message[] {
    const text = this.continuation.render((saved) => this.archive(saved), maxChars);
    return text ? [{ role: 'system', content: text }] : [];
  }

  /** The model's context window this manager budgets for, in tokens. */
  get contextWindow(): number {
    return this.MAX_TOKENS;
  }

  /** The last request's budget: what it held, what gave way, whether it was sent. Null before the first request. */
  lastRequest: RequestRecord | null = null;

  recordRequest(record: RequestRecord): void {
    this.lastRequest = record;
  }

  private toolCallTokens = new WeakMap<object, {
    calls: Array<{ id: string; type: string; name: string; args: string; extra: string | undefined }>;
    tokens: number;
  }>();

  /** Tokens the messages take in a request: their content, the tool calls they carry, and each message's framing. */
  requestTokens(messages: Message[]): number {
    let total = 0;
    for (const m of messages) {
      total += this.countMessageTokens(m) + MESSAGE_FRAMING_TOKENS;
      const calls = (m as { tool_calls?: unknown[] }).tool_calls;
      if (calls?.length) {
        const key = calls as unknown as object;
        let hit = this.toolCallTokens.get(key);
        // Arguments are immutable strings, even when their enclosing call mutates. Comparing
        // protocol fields avoids copying/tokenizing large unchanged arguments on every pressure
        // check. Opaque provider metadata can be nested, so compare its serialized value too.
        const snapshot = (m.tool_calls ?? []).map(call => ({
          id: call.id, type: call.type, name: call.function.name, args: call.function.arguments,
          extra: call.extra_content === undefined ? undefined : JSON.stringify(call.extra_content),
        }));
        const unchanged = hit && hit.calls.length === snapshot.length && snapshot.every((call, i) => {
          const prior = hit!.calls[i];
          return prior.id === call.id && prior.type === call.type && prior.name === call.name
            && prior.args === call.args && prior.extra === call.extra;
        });
        if (!unchanged) {
          hit = { calls: snapshot, tokens: countTokens(JSON.stringify(calls)) };
          this.toolCallTokens.set(key, hit);
        }
        total += hit!.tokens;
      }
    }
    return total;
  }

  /**
   * Fit `messages` into `budget` request tokens at the request boundary (record 50 step 6c), cheapest loss first:
   * blocks that are rebuilt anyway (the repo map, restored files, nudges), then old tool results, then a summary of
   * older turns, then the oldest turns themselves, and last the length of the continuation state. Everything that
   * leaves goes through the continuation state, and the latest user message never leaves. The caller checks whether
   * the result fits and refuses to send it when it does not.
   */
  async fitWithin(messages: Message[], budget: number, signal?: AbortSignal): Promise<{ messages: Message[]; tokens: number; steps: string[] }> {
    this.adoptCarriedContinuation(messages);
    signal?.throwIfAborted();
    const steps: string[] = [];
    let out = messages;
    const fits = (): boolean => this.requestTokens(out) <= budget;
    if (!fits()) {
      const kept = out.filter((m) => !this.isRebuiltLater(m));
      if (kept.length !== out.length) { out = kept; steps.push('removed the repo map and restored files, which are rebuilt later'); }
    }
    if (!fits()) {
      const drained = this.reactiveDrain(out);
      if (drained.changed) { out = drained.messages; steps.push('cleared old tool results'); }
    }
    if (!fits()) {
      const compacted = await this.compact(out, signal);
      if (compacted !== out && this.requestTokens(compacted) < this.requestTokens(out)) { out = compacted; steps.push('summarized older turns'); }
    }
    if (!fits()) {
      const trimmed = this.moveOldestTurnsOut(out, budget);
      if (trimmed !== out) { out = trimmed; steps.push('moved the oldest turns into the continuation state'); }
    }
    if (!fits()) {
      const shortened = this.shortenContinuation(out, budget);
      if (shortened !== out) { out = shortened; steps.push('shortened the continuation state, archiving the rest'); }
    }
    signal?.throwIfAborted();
    return { messages: out, tokens: this.requestTokens(out), steps };
  }

  private isRebuiltLater(m: Message): boolean {
    if (typeof m.content !== 'string') return false;
    const content = m.content;
    if (content.startsWith('[RepoMap]')) return m.role === 'system' || m.role === 'user';
    return m.role === 'system' && ['[Post-Compact Restoration', '[TurnContext]', '[ContextManager]'].some((prefix) => content.startsWith(prefix));
  }

  /** Drop whole turns from the front, a call with its results, until the request fits or the latest user message is next. */
  private moveOldestTurnsOut(messages: Message[], budget: number): Message[] {
    const system = messages.filter((m) => m.role === 'system' && !isContinuationMessage(m));
    let tail = messages.filter((m) => m.role !== 'system');
    const latestUser = latestHumanRequest(tail);
    let current = messages;
    while (tail.length && this.requestTokens(current) > budget) {
      let cut = 1;
      while (cut < tail.length && tail[cut].role === 'tool') cut++;
      const leaving = tail.slice(0, cut);
      if (latestUser && leaving.includes(latestUser)) break;
      this.continuation.absorb(leaving, (text) => this.archive(text));
      tail = tail.slice(cut);
      current = [...system, ...this.continuationMessages(), ...tail];
    }
    return current;
  }

  /** Re-render the continuation state short enough for the request to fit, when it is what stands in the way. */
  private shortenContinuation(messages: Message[], budget: number): Message[] {
    const at = messages.findIndex((m) => isContinuationMessage(m));
    if (at < 0) return messages;
    const over = this.requestTokens(messages) - budget;
    const blockTokens = this.requestTokens([messages[at]]);
    const [shortened] = this.continuationMessages(Math.max(0, (blockTokens - over) * 3));
    if (!shortened || shortened.content === messages[at].content) return messages;
    const out = [...messages];
    out[at] = shortened;
    return out;
  }

  /**
   * The residency ledger (record 47 §3.5): ids of the admitted, current evidence spans whose text is in `messages` — a
   * recall block and the memories it was built from, a restored file, a tool output named by its archive handle.
   */
  residentEvidence(messages: Message[]): string[] {
    const contents = messages.map((m) => (typeof m.content === 'string' ? m.content : contentToText(m.content)));
    const exact = new Set(contents);
    const handles = new Set<string>();
    for (const content of contents) for (const handle of content.match(/archive:[0-9a-f]{32}/g) ?? []) handles.add(handle);
    const resident = new Set<string>();
    for (const span of this.evidence.all()) {
      if (this.evidence.isStale(span.id)) continue;
      const locator = span.locator;
      const present = (span.rawHandle !== undefined && handles.has(span.rawHandle) && span.text.length > 0 && contents.some(content => content.includes(span.text)))
        || (locator.kind === 'derived' && exact.has(span.text))
        || (locator.kind === 'file' && contents.some((content) => content.startsWith(`[Post-Compact Restoration — ${locator.path} —`) && span.text.length > 0 && content.includes(span.text)));
      if (!present) continue;
      resident.add(span.id);
      for (const dep of span.derivedFrom) {
        if (!dep.sourceId.startsWith('span:')) continue;
        const source = this.evidence.get(dep.sourceId.slice('span:'.length));
        if (source && !this.evidence.isStale(source.id) && source.text.length > 0
          && contents.some(content => content.includes(source.text))) resident.add(source.id);
      }
    }
    return [...resident];
  }

  /** Reactive recovery: fires when the API rejects a request as too long. Cuts the window hard. */
  async reactiveCompact(messages: Message[], error: any): Promise<Message[]> {
    this.adoptCarriedContinuation(messages);
    // Match everything classifyStreamError treats as a context overflow (413s, "too large",
    // provider codes), not just two message spellings — a mismatch here meant the agent loop
    // decided "compact and retry" but this guard rethrew, killing the turn instead.
    const msg = String(error?.message || '');
    const isContextOverflow =
      /too long|too large|maximum context|context length|context window/i.test(msg) ||
      error?.code === 'prompt_too_long' || error?.code === 'context_length_exceeded' ||
      error?.status === 413;
    if (isContextOverflow) {
      Logger.warn(`[ContextManager] Reactive compact triggered by API error: ${error.message}`);
      this.compactionEpoch++;
      this.currentTokens = this.MAX_TOKENS; // force it
      // Same transient strip as compact() (C6) — an overflow caused by accreted summaries/
      // restorations must actually SHRINK here, or the retry 413s again and the turn dies.
      // Exception: keep the newest [Previous Context Summary] — no new summary is generated on
      // this path, so dropping it would erase everything the session learned before the overflow.
      const durableSystem = messages.filter(m => m.role === 'system' && !this.isTransientSystem(m));
      const lastSummary = [...messages].reverse().find(m =>
        this.isTransientSystem(m) && (m.content as string).startsWith('[Previous Context Summary]'));
      const recentMessages = retainRecentHistory(messages, 5);
      this.continuation.absorb(messages.filter(m => m.role !== 'system' && !recentMessages.includes(m)), (text) => this.archive(text));
      return [
        ...durableSystem,
        ...(lastSummary ? [lastSummary] : []),
        ...this.continuationMessages(),
        { role: 'system', content: '[Older messages aggressively compacted due to API context limits]' } as Message,
        ...recentMessages,
      ];
    }
    throw error;
  }
}

import * as fs from 'fs';
import * as path from 'path';
import { openSqlite, type SqliteDB } from '../core/sqlite';
import { Logger } from '../utils';
import { Segment, describeLocator } from '../documents/extract';

/**
 * Measured facts, extracted from documents and queryable as data.
 *
 * ## Why this exists at all
 *
 * Error analysis of retrieval over text-and-table documents puts **73% of residual failures in
 * "table structure mismatch" and a further 20% in numerical reasoning** — 93% of what still breaks
 * after hybrid retrieval and reranking are working. The cause is not a weak model, it is a category
 * error: in a vector index **numbers are tokens, not quantities.** Nothing in an embedding makes
 * 7.8 rank as *less than* 8.0.
 *
 * So a question an inspection engineer actually asks —
 *
 *     "which exchangers are below minimum allowable thickness?"
 *
 * is not a retrieval question, and no amount of retrieval tuning will answer it. It is a `SELECT`.
 * This module extracts the numbers out of the documents at ingest and puts them somewhere they can
 * be compared, sorted and filtered, while keeping every value chained to the file, sheet and row it
 * was read from so a computed answer stays as citable as a quoted one.
 *
 * ## What is deliberately NOT done
 *
 * - **No inference.** A unit the document does not state is not guessed. A corrosion rate the source
 *   does not give is not derived here — the agent may compute one, in the open, from facts that
 *   carry their provenance.
 * - **No prose mining beyond one line.** A regex that pairs an identifier in one paragraph with a
 *   number in another manufactures facts that were never asserted. Facts come from table rows, where
 *   the association between subject, property and value is structural, plus the narrow case of a
 *   single line that contains all three.
 *
 * A fact we did not read is not a fact.
 */

export interface Fact {
  /** The equipment or instrument the fact is about, e.g. `E-204`. */
  subject: string;
  /** What was measured, from the column header or the line's own wording. */
  property: string;
  value: number;
  /** Only when the document states it. Never inferred. */
  unit: string | null;
  /** ISO date when the document states one. */
  measuredOn: string | null;
  sourceFile: string;
  sourceName: string;
  locator: string;
  entryId: string;
}

export interface FactQuery {
  subject?: string;
  property?: string;
  /** Numeric comparison — the thing retrieval fundamentally cannot do. */
  op?: 'lt' | 'lte' | 'gt' | 'gte' | 'eq';
  value?: number;
  limit?: number;
}

const IDENTIFIER = /^[A-Z]{1,4}-\d{2,5}[A-Z]?$/;
const MAX_ROWS = 500;

/** `Measured mm`, `Thickness (mm)`, `Nominal, mm` → `mm`. Absent when the header states no unit. */
export function unitFromHeader(header: string): string | null {
  const parenthesised = /\(([^)]{1,12})\)\s*$/.exec(header);
  if (parenthesised) return parenthesised[1].trim();
  const trailing = /[\s,]([A-Za-zµ°%/]{1,8})\s*$/.exec(header.trim());
  if (trailing && !/^(no|id|name|type|date|ref)$/i.test(trailing[1])) return trailing[1];
  return null;
}

/** The column header minus its unit, so `Measured mm` and `Measured (mm)` are one property. */
export function propertyFromHeader(header: string): string {
  return header
    .replace(/\([^)]*\)\s*$/, '')
    .replace(/[\s,]+[A-Za-zµ°%/]{1,8}$/, (match) => (unitFromHeader(header) ? '' : match))
    .trim() || header.trim();
}

function parseNumber(raw: string): number | null {
  const cleaned = raw.replace(/,/g, '').trim();
  if (!/^-?\d+(\.\d+)?$/.test(cleaned)) return null;
  const value = Number(cleaned);
  return Number.isFinite(value) ? value : null;
}

function parseDate(raw: string): string | null {
  const iso = /^(\d{4})-(\d{2})-(\d{2})/.exec(raw.trim());
  return iso ? iso[0] : null;
}

/**
 * Pull facts out of one extracted segment.
 *
 * Tabular segments (`via: 'cells'`) are the reliable source: the header row names the properties and
 * each row's identifier column names the subject, so the subject/property/value association is
 * structural rather than guessed.
 */
export function factsFromSegment(
  segment: Segment,
  source: { file: string; name: string; entryId: string },
): Fact[] {
  const locator = describeLocator(segment.locator);
  const facts: Fact[] = [];
  const lines = segment.text.split('\n').filter((line) => line.trim());
  if (!lines.length) return facts;

  if (segment.via === 'cells') {
    const headers = lines[0].split('\t').map((cell) => cell.trim());
    // A header row must actually name things; a sheet that opens with data has no property names
    // and would otherwise produce facts called "7.8".
    if (!headers.some((header) => /[A-Za-z]{2,}/.test(header))) return facts;

    for (const line of lines.slice(1)) {
      const cells = line.split('\t').map((cell) => cell.trim());
      const subjectIndex = cells.findIndex((cell) => IDENTIFIER.test(cell.toUpperCase()));
      if (subjectIndex === -1) continue;                 // no subject → no assertion to record
      const subject = cells[subjectIndex].toUpperCase();
      const rowDate = cells.map(parseDate).find(Boolean) ?? null;

      cells.forEach((cell, index) => {
        if (index === subjectIndex) return;
        const value = parseNumber(cell);
        if (value === null) return;
        const header = headers[index] || `column ${index + 1}`;
        facts.push({
          subject,
          property: propertyFromHeader(header).toLowerCase(),
          value,
          unit: unitFromHeader(header),
          measuredOn: rowDate,
          sourceFile: source.file,
          sourceName: source.name,
          locator,
          entryId: source.entryId,
        });
      });
    }
    return facts;
  }

  // Prose, narrowly: subject, property and value must appear on ONE line. Pairing across lines is
  // how a fact gets manufactured that the document never asserted.
  for (const line of lines) {
    const subjectMatch = /\b([A-Z]{1,4}-\d{2,5}[A-Z]?)\b/.exec(line.toUpperCase());
    if (!subjectMatch) continue;
    const measurement = /([A-Za-z][A-Za-z -]{2,40}?)\s+(-?\d+(?:\.\d+)?)\s*([A-Za-zµ°%/]{1,8})\b/.exec(line);
    if (!measurement) continue;
    const value = parseNumber(measurement[2]);
    if (value === null) continue;
    facts.push({
      subject: subjectMatch[1],
      property: measurement[1].trim().toLowerCase(),
      value,
      unit: measurement[3],
      measuredOn: parseDate(line),
      sourceFile: source.file,
      sourceName: source.name,
      locator,
      entryId: source.entryId,
    });
  }
  return facts;
}

export class FactStore {
  private db: SqliteDB | null = null;

  constructor(private readonly storePath: string) {
    try {
      fs.mkdirSync(path.dirname(storePath), { recursive: true });
      this.db = openSqlite(storePath);
      if (!this.db) {
        // Visible, not silent: with no SQLite backend the numeric lane simply does not exist, and a
        // user must be told that rather than shown an empty result set.
        Logger.warn('[facts] no SQLite backend on this runtime — numeric fact queries are unavailable');
        return;
      }
      this.db.exec(`CREATE TABLE IF NOT EXISTS facts (
        subject TEXT NOT NULL,
        property TEXT NOT NULL,
        value REAL NOT NULL,
        unit TEXT,
        measured_on TEXT,
        source_file TEXT NOT NULL,
        source_name TEXT NOT NULL,
        locator TEXT,
        entry_id TEXT NOT NULL
      )`);
      this.db.exec('CREATE INDEX IF NOT EXISTS facts_subject ON facts(subject)');
      this.db.exec('CREATE INDEX IF NOT EXISTS facts_property ON facts(property)');
      this.db.exec('CREATE INDEX IF NOT EXISTS facts_entry ON facts(entry_id)');
    } catch (error) {
      Logger.warn(`[facts] store unavailable: ${(error as Error).message}`);
      this.db = null;
    }
  }

  available(): boolean { return this.db !== null; }

  add(facts: Fact[]): number {
    if (!this.db || !facts.length) return 0;
    const insert = this.db.prepare(
      `INSERT INTO facts (subject, property, value, unit, measured_on, source_file, source_name, locator, entry_id)
       VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)`,
    );
    for (const fact of facts) {
      insert.run(fact.subject, fact.property, fact.value, fact.unit, fact.measuredOn,
        fact.sourceFile, fact.sourceName, fact.locator, fact.entryId);
    }
    return facts.length;
  }

  removeEntry(entryId: string): number {
    if (!this.db) return 0;
    const before = this.count();
    this.db.prepare('DELETE FROM facts WHERE entry_id = ?').run(entryId);
    return before - this.count();
  }

  clear(): void {
    if (this.db) this.db.exec('DELETE FROM facts');
  }

  count(): number {
    if (!this.db) return 0;
    return Number(this.db.prepare('SELECT COUNT(*) AS n FROM facts').get()?.n ?? 0);
  }

  /**
   * Query facts. The comparison operators are the entire point — this is what the vector index
   * cannot express, and the parameters are bound, never concatenated.
   */
  query(request: FactQuery): Fact[] {
    if (!this.db) return [];
    const clauses: string[] = [];
    const params: (string | number)[] = [];
    if (request.subject) { clauses.push('subject = ?'); params.push(request.subject.toUpperCase()); }
    if (request.property) { clauses.push('property LIKE ?'); params.push(`%${request.property.toLowerCase()}%`); }
    if (request.op && typeof request.value === 'number') {
      const operator = { lt: '<', lte: '<=', gt: '>', gte: '>=', eq: '=' }[request.op];
      clauses.push(`value ${operator} ?`);
      params.push(request.value);
    }
    const limit = Math.max(1, Math.min(request.limit ?? 100, MAX_ROWS));
    const where = clauses.length ? `WHERE ${clauses.join(' AND ')}` : '';
    const rows = this.db.prepare(
      `SELECT subject, property, value, unit, measured_on, source_file, source_name, locator, entry_id
       FROM facts ${where} ORDER BY subject, property, measured_on LIMIT ${limit}`,
    ).all(...params);

    return rows.map((row: any) => ({
      subject: row.subject, property: row.property, value: row.value, unit: row.unit,
      measuredOn: row.measured_on, sourceFile: row.source_file, sourceName: row.source_name,
      locator: row.locator, entryId: row.entry_id,
    }));
  }

  /** What the corpus can actually be asked about — so the model discovers rather than guesses. */
  schema(): { subjects: string[]; properties: { property: string; unit: string | null; count: number }[] } {
    if (!this.db) return { subjects: [], properties: [] };
    const subjects = this.db.prepare('SELECT DISTINCT subject FROM facts ORDER BY subject LIMIT 200')
      .all().map((row: any) => row.subject);
    const properties = this.db.prepare(
      `SELECT property, unit, COUNT(*) AS n FROM facts GROUP BY property, unit ORDER BY n DESC LIMIT 60`,
    ).all().map((row: any) => ({ property: row.property, unit: row.unit, count: Number(row.n) }));
    return { subjects, properties };
  }
}

let globalFactStore: FactStore | null = null;
export function setFactStore(store: FactStore | null): void { globalFactStore = store; }
export function getFactStore(): FactStore | null { return globalFactStore; }

// Headroom context compression.
//
// The REAL engine is the Headroom Kompress proxy (see headroomProxy.ts): the
// chopratejas/kompress-v2-base ModernBERT token classifier, run torch-free via int8 ONNX, reached
// over HEADROOM_PROXY_URL → POST /v1/compress (proxyCompress below). It compresses tool outputs
// ~30-40% while protecting error/signal lines.
//
// The native compressText/compressBacklog below is only a dependency-light SAFETY NET used while the
// proxy is still provisioning (first-run venv + 261MB model download): it strips ANSI and collapses
// repetitive log/build line-runs, always preserving error/warning lines. Pure + synchronous so it
// never blocks the request path.

import { Logger } from '../utils/logger';

export interface BacklogStats {
  tokensBefore: number;   // whole message array
  tokensAfter: number;
  saved: number;
  compressedMessages: number;
  compressedBefore: number; // only the outputs that were compressed (for a true ratio)
  compressedAfter: number;
}

export interface HeadroomModelRow { model: string; saved: number; before: number; after: number; count: number }
export interface HeadroomReport {
  totalSaved: number;
  totalBefore: number;   // sum of compressed-output sizes before
  totalAfter: number;
  compressions: number;
  ratio: number;         // after/before over compressed content (0.14 ⇒ 86% saved)
  engine: 'native' | 'proxy';
  byModel: HeadroomModelRow[];
}

// Process-wide session stats, attributed per model — this is the data behind the TUI /headroom report.
const _byModel = new Map<string, { saved: number; before: number; after: number; count: number }>();
let _lastEngine: 'native' | 'proxy' = 'native';

/** Record one compaction's savings against the model that was active. */
export function recordCompression(model: string, before: number, after: number, engine: 'native' | 'proxy' = 'native'): void {
  const saved = Math.max(0, before - after);
  if (saved <= 0) return;
  _lastEngine = engine;
  const key = model || 'unknown';
  const a = _byModel.get(key) || { saved: 0, before: 0, after: 0, count: 0 };
  a.saved += saved; a.before += before; a.after += after; a.count += 1;
  _byModel.set(key, a);
}

export function getHeadroomSavedTokens(): number {
  let s = 0; for (const a of _byModel.values()) s += a.saved; return s;
}

export function getHeadroomReport(): HeadroomReport {
  let saved = 0, before = 0, after = 0, count = 0;
  const byModel: HeadroomModelRow[] = [];
  for (const [model, a] of _byModel) {
    saved += a.saved; before += a.before; after += a.after; count += a.count;
    byModel.push({ model, saved: a.saved, before: a.before, after: a.after, count: a.count });
  }
  byModel.sort((x, y) => y.saved - x.saved);
  return { totalSaved: saved, totalBefore: before, totalAfter: after, compressions: count, ratio: before > 0 ? after / before : 1, engine: _lastEngine, byModel };
}

/**
 * A terminal escape sequence. The ESC byte is REQUIRED.
 *
 * It used to be optional (`\u001b?`), which made this pattern match any `[`, digits, then a
 * letter — ordinary text, in other words. It silently ate the first character of every markdown
 * link (`[Read the docs](…)` → `ead the docs](…)`), every checkbox (`[x]` → `]`) and every
 * variable array index (`a[i]` → `a]`), inside tool results the model then reasoned against. It
 * only fired above the 70% compaction threshold, so it corrupted long sessions and left short
 * ones alone, which is the hardest version of this bug to notice.
 */
// eslint-disable-next-line no-control-regex
const ANSI = /\u001b\[[0-9;]*[A-Za-z]/g;
export const ERROR_LINE = /\b(error|err|fail(ed|ure)?|exception|traceback|panic|fatal|warn(ing)?|denied|refused|timeout|cannot|unable)\b/i;

/** Normalize a line so log lines that differ only by numbers/timestamps/hashes collapse together. */
function signature(line: string): string {
  return line
    .replace(/\b[0-9a-f]{7,40}\b/gi, '#')   // hashes/ids
    .replace(/\d+/g, '#')                     // numbers/timestamps
    .replace(/\s+/g, ' ')
    .trim();
}

/** A hash-like id: 7 to 40 hex digits with at least one letter. A plain seven-digit count is a number, not an id. */
const HASH_ID = /\b(?=[0-9a-f]*[a-f])[0-9a-f]{7,40}\b/gi;

/**
 * The numbers in a line, in order, signed where a minus sign starts the number (not a date's `2026-09-14`), skipping
 * hash-like ids. Dropping every 7-to-40-digit integer as an id and every sign lost a 9,000,000 outlier outright and
 * reported `-900` among `-100`s as "ranged 100–900" (audit 51, U10).
 */
function numbersIn(line: string): number[] {
  return (line.replace(HASH_ID, '#').match(/(?<![\w.])-?\d+(?:\.\d+)?(?:e[+-]?\d+)?|\d+(?:\.\d+)?/gi) ?? []).map(Number);
}

/**
 * The spread of every number that varies across a run of similar lines, as `min–max`, in the order
 * the numbers appear. Collapsing a run to one representative line used to drop every other value,
 * including the one worth seeing (a 900 ms spike among 100 ms lines, record 47 A08), so the elision
 * marker carries the ranges. Empty when nothing varies or the lines' numbers do not line up.
 */
function numberRanges(run: string[]): string[] {
  const rows = run.map(numbersIn);
  if (!rows.length) return [];
  const width = rows[0].length;
  if (!width || rows.some((row) => row.length !== width)) return [];
  const ranges: string[] = [];
  for (let k = 0; k < width; k++) {
    let min = Infinity;
    let max = -Infinity;
    for (const row of rows) {
      if (row[k] < min) min = row[k];
      if (row[k] > max) max = row[k];
    }
    if (min !== max) ranges.push(`${min}–${max}`);
  }
  return ranges;
}

/**
 * The rows holding each varying number's minimum and maximum, so the collapsed run keeps the actual extreme lines,
 * not only their values. At most `limit`, first columns first. Empty when the lines' numbers do not line up.
 */
function extremeRows(run: string[], limit = 4): number[] {
  const rows = run.map(numbersIn);
  const width = rows[0]?.length ?? 0;
  if (!width || rows.some((row) => row.length !== width)) return [];
  const picked = new Set<number>();
  for (let k = 0; k < width && picked.size < limit; k++) {
    let min = 0;
    let max = 0;
    rows.forEach((row, r) => {
      if (row[k] < rows[min][k]) min = r;
      if (row[k] > rows[max][k]) max = r;
    });
    if (rows[min][k] === rows[max][k]) continue;
    picked.add(min);
    if (picked.size < limit) picked.add(max);
  }
  return [...picked];
}

/**
 * Compress a single tool/output blob: strip ANSI, collapse runs of near-identical lines (the
 * classic log/build spam), and squeeze blank-line runs. Error/warning lines are kept verbatim and
 * never fold into a "similar lines" group. Returns the original if it can't beat it.
 */
export function compressText(text: string): string {
  if (!text) return text;
  const stripped = text.replace(ANSI, '');
  const lines = stripped.split('\n');
  const out: string[] = [];

  let i = 0;
  while (i < lines.length) {
    const line = lines[i];

    // Squeeze 2+ blank lines to one.
    if (line.trim() === '') {
      out.push('');
      while (i < lines.length && lines[i].trim() === '') i++;
      continue;
    }

    // Error/warning lines are signal — never collapse them.
    if (ERROR_LINE.test(line)) { out.push(line); i++; continue; }

    // Collapse a run of >=4 lines sharing a signature (repetitive logs).
    const sig = signature(line);
    let j = i + 1;
    while (j < lines.length && !ERROR_LINE.test(lines[j]) && signature(lines[j]) === sig) j++;
    const run = j - i;
    if (run >= 4) {
      const block = lines.slice(i, j);
      // Keep one representative and the lines holding each varying number's extremes, in their original order.
      const kept = [...new Set([0, ...extremeRows(block)])].sort((a, b) => a - b);
      for (const k of kept) out.push(block[k]);
      const ranges = numberRanges(block);
      out.push(`… (×${run - kept.length} more similar lines elided${ranges.length ? `; numbers ranged ${ranges.join(', ')}` : ''}) …`);
      i = j;
    } else {
      out.push(line);
      i++;
    }
  }

  const result = out.join('\n');
  return result.length < stripped.length ? result : stripped;
}

const cheapTokens = (s: string): number => Math.ceil(s.length / 4);

/**
 * Does this tool output look like SOURCE CODE (vs. logs / build spam)? The generic Kompress
 * token-classifier shreds code into syntactically-invalid fragments — dropped closing braces,
 * stripped `export function` keywords, orphaned expressions (verified empirically against the
 * v0.27.0 proxy on /v1/compress). For a *coding* agent that's the worst kind of lossy: the model
 * can't tell a brace is missing and may reproduce broken code. So we detect code and keep it
 * verbatim. AST-aware compression (headroom-ai[code]) only engages on the transparent /v1/messages
 * path, not the /v1/compress call we make — so on this path code must be protected by us.
 */
export function looksLikeCode(text: string): boolean {
  if (!text || text.length < 40) return false;
  if (/^FILE\s.+:/m.test(text)) return true;                         // bimax file-read header
  const lines = text.split('\n');
  if (lines.length < 3) return false;
  const codeLines = lines.filter(l =>
    /[;{}]\s*$/.test(l) ||                                           // statement/block punctuation
    /=>/.test(l) ||
    /\b(function|const|let|var|class|def|import|export|return|interface|struct|impl|fn|func|public|private)\b/.test(l),
  ).length;
  return codeLines / lines.length > 0.4;                             // dense code, not a log dump
}

/**
 * Optional hook to the REAL Headroom engine: if HEADROOM_PROXY_URL is set (a running
 * `headroom proxy`, e.g. http://localhost:8787), POST the messages to /v1/compress and use its
 * ML-compressed result. Returns null on any miss so the caller falls back to the native compressor.
 * This is how the full Kompress model plugs in without bloating the repo with a Python+model runtime.
 */
export async function proxyCompress(
  messages: { role: string; content: any; [k: string]: any }[],
  model: string,
  tokenBudget?: number,
): Promise<{ messages: any[]; saved: number } | null> {
  const base = process.env.HEADROOM_PROXY_URL;
  if (!base) return null;
  // model is required by /v1/compress; config tunes the Kompress router (protect the last couple of
  // turns + the user's messages, let it compress the rest). target_ratio nudges it more aggressive
  // than its conservative default. The proxy's own ONNX Kompress backend does the real work.
  const body: any = {
    messages,
    model: model || 'claude-sonnet-4-5-20250929',
    config: { protect_recent: 2, compress_user_messages: false, target_ratio: 0.5 },
  };
  if (tokenBudget) body.token_budget = tokenBudget;
  // ONE timeout must cover BOTH the fetch AND the body read: the proxy returns 200 headers quickly but
  // streams the compressed body only after the (slow) Kompress inference finishes. Clearing the timer
  // after fetch() and then awaiting res.json() left the body read UNBOUNDED — a slow first inference
  // (e.g. CoreML graph compilation) would hang the whole compaction forever. Keep the timer live until
  // json() resolves. 45s headroom; only invoked under token pressure, where the latency is worth it.
  const ctrl = new AbortController();
  const t = setTimeout(() => ctrl.abort(), 45000);
  try {
    const res = await fetch(`${base.replace(/\/$/, '')}/v1/compress`, {
      method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify(body), signal: ctrl.signal,
    });
    if (!res.ok) { Logger.warn(`[Headroom] proxy /v1/compress returned ${res.status}; falling back to native.`); return null; }
    const data: any = await res.json();
    if (!Array.isArray(data?.messages)) { Logger.warn('[Headroom] proxy response had no messages array; falling back to native.'); return null; }

    // CODE GUARD — never let the generic token-classifier mangle source. The proxy preserves message
    // order/count, so we zip by index: any tool message that was code-shaped is restored to its
    // original verbatim, while logs/build-spam tool outputs keep the proxy's real compression. This is
    // the difference between "15% saved on logs" and "15% saved but the model now sees broken code".
    const out: any[] = data.messages;
    let restored = 0;
    if (out.length === messages.length) {
      for (let i = 0; i < out.length; i++) {
        const orig = messages[i];
        if (orig?.role === 'tool' && typeof orig.content === 'string' && looksLikeCode(orig.content)) {
          const oc = out[i]?.content;
          if (typeof oc !== 'string' || oc !== orig.content) { out[i] = { ...out[i], content: orig.content }; restored++; }
        }
      }
    }
    // Recompute savings from the (restored) array — the proxy's tokens_saved over-counts now that we
    // put code back. char/4 keeps it cheap; the caller re-measures precisely anyway.
    let saved = Math.max(0, Number(data.tokens_saved) || 0);
    if (restored > 0) {
      let before = 0, after = 0;
      for (let i = 0; i < messages.length; i++) {
        if (typeof messages[i].content === 'string') before += cheapTokens(messages[i].content as string);
        if (typeof out[i]?.content === 'string') after += cheapTokens(out[i].content as string);
      }
      saved = Math.max(0, before - after);
      Logger.info(`[Headroom] code guard restored ${restored} code-shaped tool output(s) to verbatim (logs still compressed).`);
    }
    return { messages: out, saved };
  } catch (e) {
    Logger.warn(`[Headroom] proxy /v1/compress failed (${(e as Error).name === 'AbortError' ? 'timeout >45s' : (e as Error).message}); falling back to native.`);
    return null;
  } finally {
    clearTimeout(t);
  }
}

/**
 * Compress the OLD tool-result backlog of a message array, protecting the most recent turns and all
 * non-tool roles. Returns the (new) messages plus token stats. Char/4 token estimate keeps it cheap;
 * the caller can re-measure precisely if it wants.
 */
export function compressBacklog(
  messages: { role: string; content: any; [k: string]: any }[],
  opts: { protectRecent?: number; minChars?: number; skipCode?: boolean } = {},
): { messages: typeof messages; stats: BacklogStats } {
  const protectRecent = opts.protectRecent ?? 6;
  const minChars = opts.minChars ?? 400;
  const skipCode = opts.skipCode ?? false;
  const cutoff = Math.max(0, messages.length - protectRecent);

  let before = 0, after = 0, compressedMessages = 0, compressedBefore = 0, compressedAfter = 0;
  const out = messages.map((m, idx) => {
    // Never collapse code: even the lossless run-deduper folds near-identical lines (e.g. a block of
    // similar getters/exports) behind a "(×N elided)" marker. That's fine for log spam, lossy for
    // source. When stacking after the proxy code guard, skipCode keeps the guarantee absolute.
    const isOldTool = m.role === 'tool' && idx < cutoff && typeof m.content === 'string'
      && !(skipCode && looksLikeCode(m.content));
    if (!isOldTool || m.content.length < minChars) {
      if (typeof m.content === 'string') { before += cheapTokens(m.content); after += cheapTokens(m.content); }
      return m;
    }
    const compressed = compressText(m.content);
    const cb = cheapTokens(m.content), ca = cheapTokens(compressed);
    before += cb;
    after += ca;
    if (compressed.length < m.content.length) {
      compressedMessages++;
      compressedBefore += cb;
      compressedAfter += ca;
      return { ...m, content: compressed };
    }
    return m;
  });

  return {
    messages: out,
    stats: { tokensBefore: before, tokensAfter: after, saved: Math.max(0, before - after), compressedMessages, compressedBefore, compressedAfter },
  };
}

// Built-in engine: the REAL Headroom Kompress proxy (headroomlabs-ai/headroom).
//
// This replaces the old "native heuristic" fallback (a ~50-line log/ANSI deduper that only ever
// shaved ~1%) with Headroom's actual ML compressor: the `chopratejas/kompress-v2-base` ModernBERT
// token classifier, run torch-free via its int8 ONNX backend on onnxruntime. It compresses the
// noisy bulk of an agent's context (tool outputs, logs, file dumps) ~30-40% while its learned
// "must-keep" head protects error/warning/signal lines (verified: ECONNREFUSED & friends survive).
//
// We bake it in the same spirit as codebase-memory: provision on first use, cache under vendor/
// (gitignored), auto-spawn as a localhost sidecar, and expose it to the engine via the standard
// `HEADROOM_PROXY_URL` that `headroom.compress.ts#proxyCompress` already speaks to (POST /v1/compress).
//
// Heavy bits (a Python venv + ~261MB model) live entirely under vendor/headroom and never touch git.
// Opt out with BIMAX_DISABLE_HEADROOM=1. If Python isn't available we degrade silently to the native
// compressor — but the whole point of this module is to make the real engine the default.
//
// See memory [[bake_in_codemem_headroom]].

import * as fs from 'fs';
import * as os from 'os';
import * as path from 'path';
import * as http from 'http';
import * as net from 'net';
import { spawn, ChildProcess } from 'child_process';
import { Logger } from '../utils/logger';

const DEFAULT_PORT = Number(process.env.HEADROOM_PORT_OVERRIDE) || 8788; // 8788 avoids a user-run :8787
// The live port for THIS engine's proxy. Starts at the default but a cross-process singleton may
// bind an ephemeral port instead when 8788 is already taken — so two engines never race for 8788
// (the "address already in use" bug).
let _port = DEFAULT_PORT;
const PIP_SPEC = 'headroom-ai[proxy]';

/** Repo/package root (where vendor/ lives). Works from both dist/ and src (tsx). */
function pkgRoot(): string {
  // dist/memory/headroomProxy.js -> ../.. = repo root ; src/memory/headroomProxy.ts -> ../.. = repo root
  return path.resolve(__dirname, '..', '..');
}
function homeDir(): string { return path.join(pkgRoot(), 'vendor', 'headroom'); }
function venvDir(): string { return path.join(homeDir(), 'venv'); }
function venvBin(name: string): string {
  return path.join(venvDir(), process.platform === 'win32' ? 'Scripts' : 'bin', name + (process.platform === 'win32' ? '.exe' : ''));
}

let _child: ChildProcess | null = null;
let _starting: Promise<boolean> | null = null;
let _ready = false;
let _ownsLock = false;

export function isHeadroomReady(): boolean { return _ready; }

// ---- Cross-process singleton ownership -------------------------------------------------------
// A lockfile records the pid + port of whichever engine owns the sidecar. A second engine reads it,
// health-probes that port, and REUSES the live proxy instead of spawning its own on the same fixed
// port. Stale locks (owner died, proxy unhealthy) are cleaned. This is the deterministic answer to
// two simultaneous starts colliding on :8788.

interface ProxyLock { pid: number; port: number; startedAt: number; }

function lockFile(): string { return path.join(homeDir(), 'proxy.lock'); }

export function readProxyLock(file = lockFile()): ProxyLock | null {
  try {
    const raw = JSON.parse(fs.readFileSync(file, 'utf-8'));
    if (typeof raw?.pid === 'number' && typeof raw?.port === 'number') return raw as ProxyLock;
  } catch { /* missing or corrupt */ }
  return null;
}

/** Atomically claim the lock (fails if another live owner holds it). Returns true on success. */
export function acquireProxyLock(port: number, file = lockFile()): boolean {
  try {
    fs.mkdirSync(path.dirname(file), { recursive: true });
    fs.writeFileSync(file, JSON.stringify({ pid: process.pid, port, startedAt: Date.now() } as ProxyLock), { flag: 'wx' });
    return true;
  } catch {
    return false; // exists — someone else owns it
  }
}

/** Overwrite the lock unconditionally (used after we confirm the prior owner is stale). */
function writeProxyLock(port: number, file = lockFile()): void {
  try {
    fs.mkdirSync(path.dirname(file), { recursive: true });
    fs.writeFileSync(file, JSON.stringify({ pid: process.pid, port, startedAt: Date.now() } as ProxyLock));
  } catch { /* best-effort */ }
}

/** Remove the lockfile only if THIS process owns it — never yank a sibling engine's lock. */
export function releaseProxyLock(file = lockFile()): void {
  try {
    const lock = readProxyLock(file);
    if (lock && lock.pid === process.pid) fs.rmSync(file, { force: true });
  } catch { /* best-effort */ }
}

/** True when nothing is listening on `port` (safe to bind). */
export function isPortFree(port: number): Promise<boolean> {
  return new Promise(resolve => {
    const srv = net.createServer();
    srv.once('error', () => resolve(false));
    srv.once('listening', () => srv.close(() => resolve(true)));
    srv.listen(port, '127.0.0.1');
  });
}

/** An OS-assigned free ephemeral port. */
export function findFreePort(): Promise<number> {
  return new Promise((resolve, reject) => {
    const srv = net.createServer();
    srv.once('error', reject);
    srv.listen(0, '127.0.0.1', () => {
      const addr = srv.address();
      const port = typeof addr === 'object' && addr ? addr.port : DEFAULT_PORT;
      srv.close(() => resolve(port));
    });
  });
}

export interface ProxyPlan { action: 'reuse' | 'spawn' | 'external'; port: number; }

/**
 * Decide what a starting engine should do, WITHOUT any side effects — the singleton's brain, kept
 * pure so the race logic is unit-testable with fake probes. Order:
 *   1. A user-provided external proxy (not on our port) → use it as-is.
 *   2. A lockfile whose recorded port is actually healthy → reuse that live sidecar.
 *   3. Otherwise spawn — on the default port if free, else on an OS-assigned ephemeral port so we
 *      never collide with whatever already holds 8788.
 */
export async function planProxyStartup(opts: {
  lockFile: string;
  defaultPort: number;
  externalUrl?: string;
  healthy: (port: number) => Promise<boolean>;
  portFree: (port: number) => Promise<boolean>;
  freePort: () => Promise<number>;
}): Promise<ProxyPlan> {
  if (opts.externalUrl && !opts.externalUrl.includes(`:${opts.defaultPort}`)) {
    return { action: 'external', port: opts.defaultPort };
  }
  const lock = readProxyLock(opts.lockFile);
  if (lock && await opts.healthy(lock.port)) return { action: 'reuse', port: lock.port };
  const port = (await opts.portFree(opts.defaultPort)) ? opts.defaultPort : await opts.freePort();
  return { action: 'spawn', port };
}

/**
 * Wait (bounded) for the proxy to become ready. ensureHeadroomProxy() is already racing to bring it up
 * in the background; this lets the first under-pressure compaction give it a beat rather than instantly
 * falling back to native. Returns fast once ready; the cap keeps a still-provisioning fresh machine
 * (minutes of install/download) from hanging the request.
 */
export async function awaitHeadroomReady(timeoutMs: number): Promise<boolean> {
  if (_ready) return true;
  // Nothing is bringing the proxy up (no in-flight ensureHeadroomProxy) — don't burn the caller's
  // budget polling for something that will never arrive: unit tests, provisioning disabled/failed,
  // or a host without python3. Waiting the full timeout here was an 8s stall on the first pressured
  // turn (and a >5s test-timeout). Only wait when a startup is actually in flight.
  if (!_starting) return false;
  const deadline = Date.now() + timeoutMs;
  while (!_ready && Date.now() < deadline) await new Promise(r => setTimeout(r, 300));
  return _ready;
}

type ProcessResult = { status: number | null; stdout: string; stderr: string };

/** Run provisioning commands without ever blocking the engine's protocol/UI event loop. */
function runProcess(command: string, args: string[]): Promise<ProcessResult> {
  return new Promise((resolve) => {
    let stdout = '';
    let stderr = '';
    let child: ChildProcess;
    try {
      child = spawn(command, args, { stdio: ['ignore', 'pipe', 'pipe'] });
    } catch (error) {
      resolve({ status: -1, stdout, stderr: (error as Error).message });
      return;
    }
    child.stdout?.on('data', (chunk: Buffer) => { stdout += chunk.toString(); });
    child.stderr?.on('data', (chunk: Buffer) => { stderr += chunk.toString(); });
    child.once('error', (error) => resolve({ status: -1, stdout, stderr: error.message }));
    child.once('close', (status) => resolve({ status, stdout, stderr }));
  });
}

/** Locate a usable system python3 to bootstrap the venv from. Returns null if none. */
async function findSystemPython(): Promise<string | null> {
  for (const cand of ['python3', 'python']) {
    const r = await runProcess(cand, ['-c', 'import sys; print(sys.version_info[0])']);
    if (r.status === 0 && (r.stdout || '').trim().startsWith('3')) return cand;
  }
  return null;
}

/** True once the venv has headroom-ai[proxy] importable. */
async function venvProvisioned(): Promise<boolean> {
  const py = venvBin('python');
  if (!fs.existsSync(py)) return false;
  const r = await runProcess(py, ['-c', 'import headroom, fastapi, onnxruntime']);
  return r.status === 0;
}

/** Create the venv and pip-install headroom-ai[proxy]. Slow (first run only). Returns success. */
async function provisionVenv(): Promise<boolean> {
  const sys = await findSystemPython();
  if (!sys) { Logger.warn('[Headroom] no python3 found — cannot provision the Kompress proxy; staying on native compressor.'); return false; }
  fs.mkdirSync(homeDir(), { recursive: true });
  if (!fs.existsSync(venvBin('python'))) {
    Logger.info('[Headroom] creating Python venv for the Kompress proxy (vendor/headroom/venv)…');
    const v = await runProcess(sys, ['-m', 'venv', venvDir()]);
    if (v.status !== 0) { Logger.warn(`[Headroom] venv creation failed: ${v.stderr || v.stdout}`); return false; }
  }
  Logger.info(`[Headroom] installing ${PIP_SPEC} (one-time, ~hundreds of MB)…`);
  const pip = await runProcess(venvBin('python'), ['-m', 'pip', 'install', '-q', '--upgrade', 'pip']);
  if (pip.status !== 0) Logger.warn(`[Headroom] pip self-upgrade warning: ${pip.stderr}`);
  const inst = await runProcess(venvBin('python'), ['-m', 'pip', 'install', '-q', PIP_SPEC]);
  if (inst.status !== 0) { Logger.warn(`[Headroom] pip install failed: ${inst.stderr || inst.stdout}`); return false; }
  Logger.info('[Headroom] proxy dependencies installed.');
  return true;
}

function httpGetOk(pathname: string, timeoutMs: number, port: number = _port): Promise<boolean> {
  return new Promise(resolve => {
    const req = http.get({ host: '127.0.0.1', port, path: pathname, timeout: timeoutMs }, res => {
      res.resume();
      resolve((res.statusCode || 500) < 400);
    });
    req.on('error', () => resolve(false));
    req.on('timeout', () => { req.destroy(); resolve(false); });
  });
}

async function waitReady(totalMs: number): Promise<boolean> {
  const deadline = Date.now() + totalMs;
  while (Date.now() < deadline) {
    if (await httpGetOk('/readyz', 1000)) return true;
    await new Promise(r => setTimeout(r, 500));
  }
  return false;
}

/** Spawn `headroom proxy` with the Kompress ONNX backend forced. */
function spawnProxy(): ChildProcess {
  // CoreML on macOS (ANE/GPU) where available, else CPU ONNX — both torch-free. 'auto' picks the best.
  // NB: we deliberately leave HF_HOME alone so the ~261MB Kompress model lands in the user's standard
  // HuggingFace cache (downloaded once, reused across sessions/tools) rather than duplicated per-repo.
  // Backend pinned to CPU `onnx` (NOT CoreML `auto`): CoreML compiles the ONNX graph to the ANE on the
  // first non-trivial inference, which can stall or error mid-request (the cold first compaction then
  // times out → native fallback). CPU ONNX is a predictable ~1-9s with no compile step. Override with
  // HEADROOM_KOMPRESS_BACKEND if you want to opt into CoreML.
  const env = {
    ...process.env,
    HEADROOM_HOME: homeDir(),
    HF_HUB_DISABLE_TELEMETRY: '1',
    HEADROOM_KOMPRESS_BACKEND: process.env.HEADROOM_KOMPRESS_BACKEND || 'onnx',
    HEADROOM_DISABLE_KOMPRESS: '0',
    HEADROOM_MODE: 'token',                            // prioritize compression
  };
  const child = spawn(venvBin('headroom'), ['proxy', '--port', String(_port), '--no-cache', '--no-rate-limit', '--no-ccr-inject-tool'], {
    env, stdio: ['ignore', 'ignore', 'pipe'], detached: false,
  });
  child.stderr?.on('data', (b: Buffer) => {
    const s = b.toString().trim();
    if (/error|traceback|failed/i.test(s)) Logger.warn(`[Headroom proxy] ${s.slice(0, 300)}`);
  });
  child.on('exit', code => { _ready = false; if (code) Logger.warn(`[Headroom] proxy exited (code ${code}).`); });
  unrefSidecarHandles(child);
  return child;
}

/**
 * Keep the optional compressor sidecar from extending the parent engine's lifetime. The process
 * exit hook below still terminates a sidecar we own, while unref lets short-lived callers such as
 * `bimax --version` and the Jest release gate finish naturally once their own work is complete.
 */
export function unrefSidecarHandles(child: Pick<ChildProcess, 'stderr' | 'unref'>): void {
  (child.stderr as (NodeJS.ReadableStream & { unref?: () => void }) | null)?.unref?.();
  child.unref();
}

/**
 * Ensure the real Headroom Kompress proxy is provisioned, running, and wired into the engine via
 * HEADROOM_PROXY_URL. Idempotent and safe to fire-and-forget at startup — provisioning/model download
 * happen in the background and never block the request path. The engine only *calls* the proxy when a
 * turn is under token pressure (see context.manager), so a slow first boot costs nothing.
 */
export async function ensureHeadroomProxy(): Promise<boolean> {
  if (process.env.BIMAX_DISABLE_HEADROOM === '1') return false;
  // Compression disabled ⇒ the proxy would never be used — don't provision a Python venv +
  // hundreds of MB of pip installs for nothing (this bit hard in benchmark containers).
  if (process.env.BIMAX_DISABLE_COMPRESSION === '1') return false;
  // Respect a user-provided external proxy — don't spawn our own.
  if (process.env.HEADROOM_PROXY_URL && !process.env.HEADROOM_PROXY_URL.includes(`:${DEFAULT_PORT}`)) { _ready = true; return true; }
  if (_ready) return true;
  if (_starting) return _starting;

  _starting = (async () => {
    try {
      const plan = await planProxyStartup({
        lockFile: lockFile(),
        defaultPort: DEFAULT_PORT,
        externalUrl: process.env.HEADROOM_PROXY_URL,
        healthy: (port) => httpGetOk('/readyz', 800, port),
        portFree: isPortFree,
        freePort: findFreePort,
      });

      if (plan.action === 'external') { _ready = true; return true; }

      if (plan.action === 'reuse') {
        // Another engine already owns a healthy sidecar — wire to it, spawn nothing.
        _port = plan.port;
        process.env.HEADROOM_PROXY_URL = `http://127.0.0.1:${_port}`;
        _ready = true;
        Logger.info(`[Headroom] reusing existing Kompress proxy at ${process.env.HEADROOM_PROXY_URL} (singleton).`);
        return true;
      }

      // plan.action === 'spawn'. Claim ownership atomically BEFORE spawning so two engines can't both
      // start on the same port. If the claim loses the race, a sibling is coming up — reuse it.
      _port = plan.port;
      if (!acquireProxyLock(_port)) {
        const other = readProxyLock();
        if (other && await waitReady(15_000)) { // sibling on our default port came up
          _port = other.port; process.env.HEADROOM_PROXY_URL = `http://127.0.0.1:${_port}`; _ready = true;
          Logger.info(`[Headroom] reusing sibling Kompress proxy at ${process.env.HEADROOM_PROXY_URL}.`);
          return true;
        }
        // Sibling never came up (stale claim) — take over the port ourselves.
        writeProxyLock(_port);
      }
      _ownsLock = true;

      if (!(await venvProvisioned()) && !(await provisionVenv())) { releaseProxyLock(); _ownsLock = false; return false; }

      if (!(await httpGetOk('/readyz', 800))) {
        _child = spawnProxy();
        if (!(await waitReady(60_000))) {
          Logger.warn('[Headroom] proxy did not become ready in time.');
          releaseProxyLock(); _ownsLock = false;
          return false;
        }
      }
      writeProxyLock(_port); // record the confirmed-live port for the next engine to reuse
      process.env.HEADROOM_PROXY_URL = `http://127.0.0.1:${_port}`;
      _ready = true;
      Logger.info(`[Headroom] Kompress proxy live at ${process.env.HEADROOM_PROXY_URL} — real ML context compression enabled.`);
      warmModel(); // load/download the Kompress model now so the first under-pressure compaction is warm
      return true;
    } catch (e) {
      Logger.warn(`[Headroom] could not start proxy: ${(e as Error).message}`);
      return false;
    } finally {
      _starting = null;
    }
  })();
  return _starting;
}

/**
 * Fire a throwaway /v1/compress to force the Kompress ONNX model to load/download (~261MB on a fresh
 * machine) off the request path, so the first real under-pressure compaction returns savings instead
 * of a cold-start no-op. Best-effort; failures are ignored.
 */
function warmModel(): void {
  // Warm with a representative agent backlog (code read + logs across several turns) so the Kompress
  // model actually LOADS and runs an inference now — not on the user's first real compaction. A
  // trivial one-liner doesn't exercise the kompress path, leaving the first real call to pay the cold
  // load. Unique-ish content avoids the proxy's content cache short-circuiting the warmup.
  const stamp = Date.now();
  const code = Array.from({ length: 90 }, (_, i) => `export function warm_${stamp}_${i}(a, b) { return a + b + ${i}; }`).join('\n');
  const logs = Array.from({ length: 80 }, (_, i) => `[${stamp}:${i}] INFO compiled ./src/m${i}.ts in ${i * 3}ms`).join('\n');
  const body = JSON.stringify({
    messages: [
      { role: 'system', content: 'warmup' },
      { role: 'user', content: 'warmup' },
      { role: 'tool', content: 'FILE warm.ts:\n' + code },
      { role: 'tool', content: '$ npm run build\n' + logs + '\nBuild succeeded.' },
      { role: 'assistant', content: 'ok' },
      { role: 'user', content: 'ok' },
    ],
    model: 'claude-sonnet-4-5-20250929',
    config: { protect_recent: 2, target_ratio: 0.5 },
  });
  const req = http.request(
    { host: '127.0.0.1', port: _port, path: '/v1/compress', method: 'POST', timeout: 120_000, headers: { 'content-type': 'application/json', 'content-length': Buffer.byteLength(body) } },
    res => { res.resume(); res.on('end', () => Logger.info('[Headroom] Kompress model warmed.')); },
  );
  req.on('error', () => { /* warmup is best-effort */ });
  req.on('timeout', () => req.destroy());
  req.write(body); req.end();
}

/** Best-effort, deterministic shutdown of the spawned sidecar. Releases the singleton lock we own. */
export function stopHeadroomProxy(): void {
  if (_child && !_child.killed) { try { _child.kill('SIGTERM'); } catch { /* ignore */ } }
  _child = null; _ready = false;
  if (_ownsLock) { releaseProxyLock(); _ownsLock = false; }
}

process.once('exit', stopHeadroomProxy);
process.once('SIGINT', () => { stopHeadroomProxy(); });
process.once('SIGTERM', () => { stopHeadroomProxy(); });

import { stateDir } from '../utils/state.dir';
import { reportCapability } from '../core/capability.status';
import * as fs from 'fs/promises';
import * as path from 'path';
import { Logger } from '../utils';
import { Mutex } from 'async-mutex';
import { Bm25Index, tokenize } from './bm25';
import { BoundedTopK } from '../utils/bounded.top.k';
import { contentStems } from './sufficiency';
import { reciprocalRankFusion } from './fusion';
import { chunkDocument } from './chunking';
import { dot, type EmbeddingBackend } from './embeddings';
import type { Reranker } from './rerank';
import { randomUUID } from 'node:crypto';
import { withMemoryWriteTransaction } from './write.transaction';

/**
 * File-backed memory with a four-stage retrieval pipeline.
 *
 *   chunk → { BM25 ∥ dense } → reciprocal rank fusion → cross-encoder rerank
 *
 * Each stage exists because the one before it has a specific ceiling:
 *
 *   - **Chunking** because an embedding is an average: a long note embeds as slightly-about each of
 *     the eight things it covers and strongly about none, so the information is present and the
 *     representation buries it.
 *   - **Two retrievers** because they fail in opposite directions. BM25 owns exact tokens — error
 *     codes, identifiers, branch names — which are precisely where a model that never saw them is
 *     worst. Dense owns paraphrase, which is precisely where a lexical matcher scores zero.
 *   - **Rank fusion** rather than score addition, because BM25 is unbounded and corpus-dependent
 *     while cosine is bounded: adding them lets one drown the other with no error and no way to see
 *     it from the output.
 *   - **Reranking** because both retrievers score a document without ever seeing it beside the
 *     query. That is what makes them fast enough to run over everything, and it is their ceiling.
 *     Fusion is good at putting the right document *somewhere* in the top twenty and mediocre at
 *     putting it in the top three — and the top three is all that fits in a prompt.
 *
 * ## Every stage degrades separately, and says so
 *
 * Embeddings and reranking each need a network and a key. When either is unavailable it returns
 * null and the pipeline runs without that stage — never with a fabricated substitute. A reranker
 * that silently returned its input unchanged, or an embedder that returned hashed pseudo-vectors,
 * would be indistinguishable from one that worked. `lastSearchMode()` reports which stages actually
 * ran, so a caller can admit to degraded results instead of quietly serving them.
 *
 * ## Writes deduplicate before they store
 *
 * A memory that keeps every phrasing of the same fact is a store that slowly fills with near
 * copies, and retrieval then spends its top-three budget on the same fact twice. `storeDocument`
 * therefore merges into an existing document when the new text is near-identical (embedding
 * centroid cosine, with a lexical Jaccard fallback when embeddings are off) instead of appending.
 */
export interface StoredChunk {
  id: string;
  text: string;
  /** Unit-length dense vector, absent until embedded. */
  embedding?: number[];
  /** The vector space `embedding` belongs to. A mismatch invalidates it rather than comparing. */
  space?: string;
}

export interface VectorDocument {
  id: string;
  /** Fresh on each content replacement; binds delayed work even across an old→new→old edit. */
  generation?: string;
  metadata: {
    tags: string[];
    content: string;
  };
  /** Retrieval operates on these; the document is what gets returned. */
  chunks?: StoredChunk[];
  /**
   * Only on search results requested with `SearchOptions.passages`: this document's chunks that matched,
   * best first. Those results are copies, so this is never stored.
   */
  matchedChunks?: StoredChunk[];
  /**
   * When this document was last *retrieved*, not when it was written.
   *
   * Eviction reads this. FIFO — the previous policy — discards the oldest record regardless of how
   * often it has proved useful, which on a memory store means the hard-won fact learned in week one
   * is the first thing thrown away. Least-recently-retrieved keeps what the system actually uses.
   */
  lastUsedAt?: number;
}

/** Which stages ran. Reported rather than inferred — a degraded pipeline looks identical. */
export interface SearchMode {
  lexical: boolean;
  dense: boolean;
  reranked: boolean;
}

export interface SearchOptions {
  /**
   * Restrict retrieval to documents carrying at least one of these tags. Applied BEFORE depth is
   * consumed, not as a post-filter: a caller asking for 3 project-memories must get the 3 best
   * project-memories, not the 3 best documents of which 1 happens to be tagged.
   */
  tags?: string[];
  /**
   * Exclude documents carrying any of these tags. The two injection paths divide the store this
   * way: the persona's prompt block owns project-memory (conventions deliberately re-shown every
   * turn), automatic recall owns everything else — without the exclusion, one memory would be
   * injected twice in the same turn from two paths that cannot see each other.
   */
  excludeTags?: string[];
  /**
   * Restrict retrieval to documents whose tags pass this test, applied before depth is consumed like
   * `tags`. Tag equality cannot express a path scope, and filtering the results afterwards returned
   * nothing whenever out-of-scope documents ranked higher (record 47, A02).
   */
  where?: (tags: readonly string[]) => boolean;
  /**
   * Report which chunks of each result matched (`VectorDocument.matchedChunks`), best first, so a caller
   * can quote the part of a long note that answers instead of its opening (record 47, A03). Honoured by
   * VectorStore; the code store's documents are single chunks already.
   */
  passages?: boolean;
  /**
   * Which retrievers run. Default 'hybrid'. 'lexical' skips the embedding call entirely (no key,
   * or a caller that wants grep-class results fast); 'dense' skips BM25 — the diagnostic position
   * that isolates what fusion adds over either retriever alone.
   */
  mode?: 'hybrid' | 'lexical' | 'dense';
}

export interface StoreStats {
  documents: number;
  chunks: number;
  /** Chunks with a live vector in the active space. */
  embedded: number;
  /** Chunks the dense stage cannot see — embedded by `backfillEmbeddings` once a key exists. */
  pending: number;
  maxVectors: number;
  lastMode: SearchMode;
}

/** Kept exported: callers outside this module score ad-hoc text against a query with it. */
export function lexicalRelevance(query: string, text: string): number {
  const q = new Set(tokenize(query));
  const d = tokenize(text);
  if (!q.size || !d.length) return 0;
  let hits = 0;
  for (const term of d) if (q.has(term)) hits++;
  return hits / d.length;
}

/**
 * Jaccard over content tokens — the dedup floor when embeddings are off. Word order and length do
 * not matter, which is the point: "the fix asks a freshly spawned child" and "a freshly spawned
 * child is what the fix asks for" are the same memory.
 */
function tokenJaccard(a: string, b: string): number {
  const sa = new Set(tokenize(a));
  const sb = new Set(tokenize(b));
  if (!sa.size || !sb.size) return 0;
  let shared = 0;
  for (const t of sa) if (sb.has(t)) shared++;
  return shared / (sa.size + sb.size - shared);
}

/** Above this a stored document and the incoming text are the same memory in different words. */
const DEDUP_COSINE = 0.92;
/**
 * Lexical corroboration required alongside the cosine. Embedding centroids of two DIFFERENT facts
 * about the same topic can collide above any fixed threshold — the coarser the space (a small
 * Matryoshka cut, a low-dimension model), the easier — and a merge is a deletion of the older
 * memory, so embeddings alone must never be enough to trigger it. A genuine paraphrase shares most
 * of its content words with the original, which a different fact about the same topic does not.
 */
const DEDUP_CORROBORATION = 0.35;
/** Near-verbatim, with or without embeddings. */
const DEDUP_JACCARD = 0.8;

/**
 * Unit-length mean of a document's chunk vectors in the given space, or null when it has none
 * there. Chunk-level detail is deliberately averaged away: dedup wants "same fact?", and two
 * phrasings of one note share their centre of mass even when their chunk boundaries differ.
 */
function centroidOf(chunks: StoredChunk[], spaceId: string | null): number[] | null {
  if (!spaceId) return null;
  let sum: number[] | null = null;
  for (const chunk of chunks) {
    if (!chunk.embedding || chunk.space !== spaceId) continue;
    if (!sum) sum = new Array(chunk.embedding.length).fill(0);
    chunk.embedding.forEach((v, i) => { sum![i] += v; });
  }
  if (!sum) return null;
  const norm = Math.sqrt(sum.reduce((acc, v) => acc + v * v, 0));
  if (!norm || !Number.isFinite(norm)) return null;
  return sum.map((v) => v / norm);
}

export interface VectorStoreOptions {
  /** Where the JSON store lives. Default: <cwd>/.breakglass/memory/vectors.json. */
  storePath?: string;
  /**
   * Document cap before LRU-by-retrieval eviction. The memory store's 500 is tuned for
   * hand-written notes; a code index over a real repo needs an order of magnitude more.
   */
  maxVectors?: number;
  /**
   * How a document becomes chunks. The default splits prose; a code index passes an identity
   * chunker because it pre-chunks by source symbol, and re-splitting code on sentence
   * boundaries would index tokens the file never contained.
   */
  chunker?: (id: string, text: string) => { id: string; text: string }[];
  /**
   * Near-duplicate merging is right for memory (two phrasings of one fact are one memory) and
   * WRONG for code (two files with similar bodies are two files). Default true.
   */
  dedup?: boolean;
}

export class VectorStore {
  private store: VectorDocument[] = [];
  private diskIdentity: string | null = null;
  private readonly STORE_PATH: string;
  private rwMutex = new Mutex();
  private readonly MAX_VECTORS: number;

  private readonly embeddings: EmbeddingBackend | null;
  private readonly reranker: Reranker | null;
  private readonly chunk: (id: string, text: string) => { id: string; text: string }[];
  private readonly dedup: boolean;
  /** Indexed over CHUNKS, not documents — the unit retrieval scores. */
  private index = new Bm25Index();
  private indexDirty = true;
  /** Mixed-radix positions reuse the stored arrays without allocating an object per chunk. */
  private chunkOwner = new Map<string, number | readonly [number, number]>();
  private duplicateChunkOwners = false;
  private mode: SearchMode = { lexical: true, dense: false, reranked: false };
  /** Recency changed on the read path and is waiting for the coalesced flush (see semanticSearch). */
  private recencyDirty = false;
  private recencyTimer: NodeJS.Timeout | null = null;
  /** Tunable for tests and tight loops; 10s is the production default. */
  private readonly recencyFlushMs = Math.max(1, Number(process.env.BIMAX_RECENCY_FLUSH_MS ?? 10_000));

  constructor(
    embeddings: EmbeddingBackend | null = null,
    reranker: Reranker | null = null,
    options: VectorStoreOptions = {},
  ) {
    this.embeddings = embeddings;
    this.reranker = reranker;
    this.STORE_PATH = options.storePath ?? path.join(stateDir('.breakglass'), 'memory', 'vectors.json');
    this.MAX_VECTORS = Math.max(1, options.maxVectors ?? 500);
    this.chunk = options.chunker ?? ((id, text) => chunkDocument(id, text));
    this.dedup = options.dedup ?? true;
    this.loadStore().catch(() => {});
  }

  lastSearchMode(): SearchMode {
    return this.mode;
  }

  private stemCache = new WeakMap<VectorDocument, { content: string; stems: Set<string> }>();

  /**
   * Which of these stemmed content words appear in no document a search with `scope` could return (see
   * `memory/sufficiency.ts`). Reads the store as the last search left it.
   */
  unknownTerms(stems: readonly string[], scope: Pick<SearchOptions, 'tags' | 'excludeTags' | 'where'> = {}): string[] {
    const remaining = new Set(stems);
    for (const doc of this.store) {
      if (!remaining.size) break;
      const tags = doc.metadata?.tags ?? [];
      if (scope.tags?.length && !tags.some((t) => scope.tags!.includes(t))) continue;
      if (scope.excludeTags?.length && tags.some((t) => scope.excludeTags!.includes(t))) continue;
      if (scope.where && !scope.where(tags)) continue;
      const content = doc.metadata?.content ?? '';
      let cached = this.stemCache.get(doc);
      if (!cached || cached.content !== content) {
        cached = { content, stems: new Set(contentStems(content)) };
        this.stemCache.set(doc, cached);
      }
      for (const term of remaining) if (cached.stems.has(term)) remaining.delete(term);
    }
    return [...remaining];
  }

  /** A snapshot for readouts (/retrieval) — counts, not contents. */
  stats(): StoreStats {
    let chunks = 0;
    let embedded = 0;
    const space = this.embeddings?.id;
    for (const doc of this.store) {
      for (const chunk of doc.chunks ?? []) {
        chunks++;
        if (space && chunk.embedding && chunk.space === space) embedded++;
      }
    }
    return {
      documents: this.store.length,
      chunks,
      embedded,
      pending: chunks - embedded,
      maxVectors: this.MAX_VECTORS,
      lastMode: this.mode,
    };
  }

  private async loadStore(alreadyLocked: boolean = false) {
    const load = async () => {
      try {
        // A retrieval may have updated recency in memory while its coalesced disk flush is still
        // pending. Reloading the file for the next search must not erase that newer timestamp.
        const stat = await fs.stat(this.STORE_PATH, { bigint: true });
        const identity = `${stat.dev}:${stat.ino}:${stat.size}:${stat.mtimeNs}:${stat.ctimeNs}`;
        if (identity === this.diskIdentity) return;
        const pendingRecency = this.recencyDirty
          ? new Map(this.store.map((doc) => [doc.id, doc.lastUsedAt ?? 0]))
          : null;
        const data = await fs.readFile(this.STORE_PATH, 'utf-8');
        const parsed = JSON.parse(data);
        if (!Array.isArray(parsed)) throw new Error('Invalid memory store');
        this.store = parsed;
        for (const doc of this.store) {
          if (pendingRecency?.has(doc.id)) {
            doc.lastUsedAt = Math.max(doc.lastUsedAt ?? 0, pendingRecency.get(doc.id) ?? 0);
          }
          // Records written before chunking existed have no `chunks`. Derive them on load rather
          // than migrating the file: a read-time upgrade cannot corrupt anything, and the next
          // write persists the result anyway.
          if (!doc.chunks?.length) {
            const chunks = this.chunk(doc.id, doc.metadata?.content || '').map((c) => ({ id: c.id, text: c.text }));
            doc.chunks = chunks;
          }
          if (this.embeddings) {
            for (const chunk of doc.chunks) {
              if (chunk.space && chunk.space !== this.embeddings.id) {
                delete chunk.embedding;
                delete chunk.space;
              }
            }
          }
        }
        this.diskIdentity = identity;
        this.indexDirty = true;
        Logger.info(`[VectorStore] Loaded ${this.store.length} memories from disk.`);
        reportCapability({ id: 'memory-storage-read', label: 'Memory storage', state: 'ready',
          reason: 'Stored memories were read successfully.', impact: '', action: '' });
      } catch (error: any) {
        if (error?.code === 'ENOENT') {
          this.store = [];
          this.diskIdentity = null;
          this.indexDirty = true;
          return;
        }
        reportCapability({ id: 'memory-storage-read', label: 'Memory storage', state: 'unavailable',
          reason: 'Stored memories could not be read.', impact: 'Memory results cannot be trusted as complete.',
          action: 'Check the memory file and disk access before retrying.' });
        throw error;
      }
    };

    if (alreadyLocked) await load();
    else await this.rwMutex.runExclusive(load);
  }

  private async saveStore() {
    try {
      await fs.mkdir(path.dirname(this.STORE_PATH), { recursive: true });
      const tmp = `${this.STORE_PATH}.${randomUUID()}.tmp`;
      try {
        await fs.writeFile(tmp, JSON.stringify(this.store, null, 2), { encoding: 'utf8', mode: 0o600, flag: 'wx' });
        const written = await fs.stat(tmp, { bigint: true });
        await fs.rename(tmp, this.STORE_PATH);
        const stat = await fs.stat(this.STORE_PATH, { bigint: true });
        // Cache only the bytes we wrote. Another writer may replace/overwrite the destination
        // between rename and stat; its identity must never be attached to our in-memory data.
        const stillOurs = stat.dev === written.dev && stat.ino === written.ino
          && stat.size === written.size && stat.mtimeNs === written.mtimeNs;
        this.diskIdentity = stillOurs ? `${stat.dev}:${stat.ino}:${stat.size}:${stat.mtimeNs}:${stat.ctimeNs}` : null;
      } finally { await fs.rm(tmp, { force: true }).catch(() => {}); }
      reportCapability({ id: 'memory-storage-write', label: 'Memory persistence', state: 'ready',
        reason: 'Stored memories were saved successfully.', impact: '', action: '' });
    } catch (error) {
      reportCapability({ id: 'memory-storage-write', label: 'Memory persistence', state: 'unavailable',
        reason: 'Memories could not be saved.', impact: 'The update is not durable.',
        action: 'Check free disk space and memory-directory permissions, then retry.' });
      throw error;
    }
  }

  /** All JSON mutators share one reload/publication authority, including background recency. */
  private async mutateStore<T>(run: () => Promise<T>): Promise<T> {
    return this.rwMutex.runExclusive(() => withMemoryWriteTransaction(this.STORE_PATH, async () => {
      await this.loadStore(true);
      try { return await run(); }
      catch (error) {
        // A rejected write must not leave a cache identity that can later republish ghost edits.
        this.diskIdentity = null;
        this.indexDirty = true;
        throw error;
      }
    }));
  }

  private rebuildIndex(): void {
    if (!this.indexDirty) return;
    const documents: { id: string; text: string }[] = [];
    this.chunkOwner = new Map();
    this.duplicateChunkOwners = false;
    const width = this.store.length;
    for (const [docAt, doc] of this.store.entries()) {
      for (const [chunkAt, chunk] of (doc.chunks ?? []).entries()) {
        documents.push({ id: chunk.id, text: chunk.text });
        // Preserve the original lookup's first chunk within the last owning document.
        const previous = this.chunkOwner.get(chunk.id);
        const ownerAt = typeof previous === 'number' ? previous % width : previous?.[0];
        if (ownerAt === docAt) continue;
        if (previous !== undefined) this.duplicateChunkOwners = true;
        const address = chunkAt * width + docAt;
        // The tuple is only a correctness fallback for positions beyond safe integer arithmetic.
        this.chunkOwner.set(chunk.id, Number.isSafeInteger(address) ? address : [docAt, chunkAt]);
      }
    }
    this.index.build(documents);
    this.indexDirty = false;
  }

  private ownerOf(chunkId: string): VectorDocument | undefined {
    const address = this.chunkOwner.get(chunkId);
    return address === undefined ? undefined : this.store[typeof address === 'number' ? address % this.store.length : address[0]];
  }

  private chunkAt(address: number | readonly [number, number], doc: VectorDocument): StoredChunk | undefined {
    return doc.chunks?.[typeof address === 'number' ? Math.floor(address / this.store.length) : address[1]];
  }

  async storeDocument(id: string, text: string, tags: string[]): Promise<void> {
    return this.storeDocuments([{ id, text, tags }]);
  }

  /**
   * Store many documents with ONE embedding pass over all their chunks. A code index syncing a
   * directory is hundreds of documents; per-document embed calls would turn that into hundreds of
   * HTTP round trips carrying one vector each, when the backend exists to batch 64 to a call.
   */
  async storeDocuments(inputs: { id: string; text: string; tags: string[] }[]): Promise<void> {
    if (!inputs.length) return;
    const prepared = inputs.map((input) => ({
      ...input,
      chunks: this.chunk(input.id, input.text).map((c): StoredChunk => ({ id: c.id, text: c.text })),
    }));

    // Embed OUTSIDE the mutex: network call, and the store lock must not serialize behind it.
    const flatText = prepared.flatMap((d) => d.chunks.map((c) => c.text));
    let vectors: number[][] | null = null;
    if (this.embeddings && flatText.length) {
      vectors = await this.embeddings.embed(flatText, 'passage').catch(() => null);
    }
    if (vectors) {
      let k = 0;
      for (const doc of prepared) {
        for (const chunk of doc.chunks) {
          const v = vectors[k++];
          if (v) {
            chunk.embedding = v;
            chunk.space = this.embeddings!.id;
          }
        }
      }
    }

    await this.mutateStore(async () => {
      for (const input of prepared) {
        // Near-duplicate merge BEFORE insert (memory only — see VectorStoreOptions.dedup): a
        // store that keeps every phrasing of one fact spends its top-three retrieval budget
        // showing the same memory twice. The incoming text replaces the older copy's content
        // (newest phrasing wins) under the OLD id, so references and the retrieval history
        // attached to that memory survive; tags union so nothing is lost.
        const centroid = this.dedup ? centroidOf(input.chunks, this.embeddings?.id ?? null) : null;
        const duplicateId = this.dedup ? this.findNearDuplicate(input.id, input.text, centroid) : null;
        const targetId = duplicateId ?? input.id;
        const existing = this.store.find((d) => d.id === targetId);
        const mergedTags = Array.from(new Set([...(existing?.metadata?.tags ?? []), ...input.tags]));
        const doc: VectorDocument = {
          id: targetId,
          generation: randomUUID(),
          metadata: { tags: mergedTags, content: input.text },
          chunks: input.chunks,
          lastUsedAt: Date.now(),
        };
        const existingIdx = this.store.findIndex((d) => d.id === targetId);
        if (existingIdx >= 0) this.store[existingIdx] = doc;
        else this.store.push(doc);
        if (duplicateId) {
          Logger.info(`[VectorStore] Merged near-duplicate of '${duplicateId}' (${input.chunks.length} chunk(s)).`);
        }
      }
      const memorized = prepared.filter((p) => this.store.some((d) => d.id === p.id));
      if (memorized.length) {
        Logger.info(`[VectorStore] Memorized ${memorized.length} document(s) (${prepared.reduce((n, p) => n + p.chunks.length, 0)} chunk(s)).`);
      }

      // Least-recently-USED, not first-in. See `lastUsedAt`.
      if (this.store.length > this.MAX_VECTORS) {
        this.store.sort((a, b) => (a.lastUsedAt ?? 0) - (b.lastUsedAt ?? 0));
        this.store.splice(0, this.store.length - this.MAX_VECTORS);
      }
      this.indexDirty = true;
      await this.saveStore();
    });
  }

  /**
   * The closest existing memory to the incoming text, or null. Merging is a deletion of the older
   * copy, so it demands AGREEMENT between two independent signals:
   *
   *   - near-verbatim: token Jaccard ≥ 0.8, with or without embeddings; or
   *   - paraphrase: embedding centroid cosine ≥ 0.92 AND Jaccard ≥ 0.35 — semantic proximity says
   *     "same idea", lexical overlap says "same words rearranged", and only together do they say
   *     "same memory". Either alone deletes distinct facts that happen to be nearby in the space.
   */
  private findNearDuplicate(incomingId: string, incomingText: string, incomingCentroid: number[] | null): string | null {
    let best: { id: string; cosine: number; jaccard: number } | null = null;
    for (const doc of this.store) {
      if (doc.id === incomingId) continue; // exact re-store is an update, not a merge
      const jaccard = tokenJaccard(incomingText, doc.metadata?.content || '');
      let cosine = 0;
      if (incomingCentroid) {
        const c = centroidOf(doc.chunks ?? [], this.embeddings?.id ?? null);
        if (c) cosine = dot(incomingCentroid, c);
      }
      if (
        jaccard >= DEDUP_JACCARD
        || (cosine >= DEDUP_COSINE && jaccard >= DEDUP_CORROBORATION)
      ) {
        if (!best || cosine + jaccard > best.cosine + best.jaccard) best = { id: doc.id, cosine, jaccard };
      }
    }
    return best?.id ?? null;
  }

  /** Remove documents matching the predicate. Returns how many were removed. Persists immediately. */
  async deleteWhere(predicate: (doc: VectorDocument) => boolean): Promise<number> {
    return this.mutateStore(async () => {
      const before = this.store.length;
      this.store = this.store.filter((doc) => !predicate(doc));
      const removed = before - this.store.length;
      if (removed > 0) {
        this.indexDirty = true;
        await this.saveStore();
      }
      return removed;
    });
  }

  /**
   * The full pipeline.
   *
   * `minScore` is kept for API compatibility and reinterpreted: RRF scores and cross-encoder logits
   * are not similarities, so a cosine floor is meaningless against them. It is applied as a lexical
   * overlap floor, and ONLY to documents that no semantic stage surfaced — filtering a dense hit by
   * shared words would delete the capability the dense stage exists to add.
   */
  async semanticSearch(query: string, limit: number = 3, minScore: number = 0.25, options: SearchOptions = {}): Promise<VectorDocument[]> {
    if (!query.trim()) return [];

    const mode = options.mode ?? 'hybrid';
    const queryVector = this.embeddings && mode !== 'lexical'
      ? (await this.embeddings.embed([query], 'query').catch(() => null))?.[0] ?? null
      : null;

    // Stages 1–3 under the lock; stage 4 is another network call and must not hold it.
    const fusedCandidates = await this.rwMutex.runExclusive(async () => {
      await this.loadStore(true);
      if (!this.store.length) return null;
      this.rebuildIndex();

      // Tag scoping happens BEFORE depth is consumed (see SearchOptions) — filtering after
      // truncation quietly returns fewer results than asked for whenever unscoped documents rank
      // higher, which reads to the caller as "the memory doesn't exist".
      const tagSet = options.tags?.length ? new Set(options.tags) : null;
      const exclSet = options.excludeTags?.length ? new Set(options.excludeTags) : null;
      const docAllowed = (doc: VectorDocument | undefined): boolean => {
        if (!doc) return false;
        const tags = doc.metadata?.tags ?? [];
        if (tagSet && !tags.some((t) => tagSet.has(t))) return false;
        if (exclSet && tags.some((t) => exclSet.has(t))) return false;
        if (options.where && !options.where(tags)) return false;
        return true;
      };
      const allowed = (chunkId: string): boolean => docAllowed(this.ownerOf(chunkId));

      // Deeper than `limit` on purpose: fusion can only promote a candidate that appears in a list,
      // and the reranker can only reorder what it is given. Truncating early throws away the
      // agreement RRF exists to find and the recovery reranking exists to perform. The floor scales
      // with corpus reality: 32 was tuned on a memory store of hundreds of chunks; a code index
      // runs to thousands, where a 32-deep window is a sample, not a ranking.
      const depth = Math.max(limit * 8, 64);
      const lexicalHits = mode === 'dense' ? [] : this.index.search(query).filter(h => allowed(h.id));
      const lexical = lexicalHits.slice(0, depth).map(h => h.id);
      let dense: string[] = [];
      type DenseCandidate = { id: string; score: number; recency: number };
      let denseScored: DenseCandidate[] = [];
      const compare = (a: DenseCandidate, b: DenseCandidate): number =>
        b.score - a.score
        || b.recency - a.recency
        || a.id.localeCompare(b.id);
      if (queryVector) {
        const scored = new BoundedTopK<DenseCandidate>(depth, compare);
        for (const doc of this.store) {
          if (!docAllowed(doc)) continue;
          for (const chunk of doc.chunks ?? []) {
            if (!chunk.embedding || chunk.space !== this.embeddings?.id) continue;
            scored.add({ id: chunk.id, score: dot(queryVector, chunk.embedding),
              recency: (this.duplicateChunkOwners ? this.ownerOf(chunk.id)?.lastUsedAt : doc.lastUsedAt) ?? 0 });
          }
        }
        denseScored = scored.sorted();
        dense = denseScored.map(s => s.id);
      }

      const fused = reciprocalRankFusion({ lexical: { ids: lexical }, dense: { ids: dense } });
      const candidates = (hits: typeof fused) => hits.map(hit => {
        const address = this.chunkOwner.get(hit.id);
        const doc = address === undefined ? undefined : this.store[typeof address === 'number' ? address % this.store.length : address[0]];
        const chunk = address === undefined || !doc ? undefined : this.chunkAt(address, doc);
        return doc && chunk ? { id: hit.id, text: chunk.text, doc, chunk, fromDense: hit.ranks.dense !== undefined } : null;
      }).filter((candidate): candidate is NonNullable<typeof candidate> => candidate !== null);
      const primary = candidates(fused);
      const eligible = new Set<string>();
      for (const candidate of primary) {
        if (!candidate.fromDense && minScore > 0 && lexicalRelevance(query, candidate.text) < minScore) continue;
        eligible.add(candidate.doc.id);
        // Reranking reorders this pool; it never removes a candidate. No backfill is needed.
        if (eligible.size >= limit) return { dense: dense.length > 0, candidates: primary, backfill: [] };
      }

      // Only an underfull primary pool needs document diversity. Keep its original ranks/prefix.
      const lexicalDocuments: string[] = [];
      const seenDocuments = new Set<string>();
      for (const hit of lexicalHits) {
        const doc = this.ownerOf(hit.id)!;
        if (seenDocuments.has(doc.id)) continue;
        const chunk = this.chunkAt(this.chunkOwner.get(hit.id)!, doc)!;
        if (minScore > 0 && lexicalRelevance(query, chunk.text) < minScore) continue;
        seenDocuments.add(doc.id);
        lexicalDocuments.push(hit.id);
        if (lexicalDocuments.length >= limit) break;
      }
      let denseDocuments: string[] = [];
      if (queryVector) {
        const known = new Map<VectorDocument, DenseCandidate>();
        if (!this.duplicateChunkOwners) for (const candidate of denseScored) {
          const doc = this.ownerOf(candidate.id)!;
          if (!known.has(doc)) known.set(doc, candidate);
        }
        const documents = new BoundedTopK<DenseCandidate>(limit, compare);
        for (const doc of this.store) {
          if (!docAllowed(doc)) continue;
          // A document represented in the global top-k already has its best chunk there.
          // Reuse it rather than rescoring the long document that crowded out the other sources.
          let best = known.get(doc);
          if (!best) for (const chunk of doc.chunks ?? []) {
            if (!chunk.embedding || chunk.space !== this.embeddings?.id) continue;
            const candidate = { id: chunk.id, score: dot(queryVector, chunk.embedding),
              recency: (this.duplicateChunkOwners ? this.ownerOf(chunk.id)?.lastUsedAt : doc.lastUsedAt) ?? 0 };
            if (!best || compare(candidate, best) < 0) best = candidate;
          }
          if (best) documents.add(best);
        }
        denseDocuments = documents.sorted().map(s => s.id);
      }
      const backfill = reciprocalRankFusion({ lexical: { ids: lexicalDocuments }, dense: { ids: denseDocuments } });
      return { dense: dense.length > 0, candidates: primary, backfill: candidates(backfill) };
    });

    if (!fusedCandidates) {
      this.mode = { lexical: true, dense: false, reranked: false };
      return [];
    }

    // Stage 4. A null result keeps the fused order — never a reordering we did not compute.
    let ordered = fusedCandidates.candidates;
    let reranked = false;
    if (this.reranker && ordered.length > 1) {
      const scores = await this.reranker
        .rerank(query, ordered.map((c) => ({ id: c.id, text: c.text })))
        .catch(() => null);
      if (scores?.length) {
        // A remote reranker is another signal, not an oracle. Fuse its ordering with the retrieval
        // ordering so one noisy response cannot erase candidates both first-stage retrievers liked.
        const guarded = reciprocalRankFusion({
          retrieval: { ids: ordered.map((candidate) => candidate.id), weight: 1.25 },
          rerank: { ids: scores.map((score) => score.id) },
        });
        const rank = new Map(guarded.map((hit, i) => [hit.id, i]));
        ordered = [...ordered].sort((a, b) => (rank.get(a.id) ?? Infinity) - (rank.get(b.id) ?? Infinity));
        reranked = true;
      }
    }

    this.mode = { lexical: true, dense: fusedCandidates.dense, reranked };
    Logger.info(
      `[VectorStore] search "${query.substring(0, 30)}" — lexical${fusedCandidates.dense ? '+dense' : ''}${reranked ? '+rerank' : ''}`,
    );

    // Chunks collapse to documents: several chunks of one note are one result, ranked by its best.
    // With `passages`, each result also keeps the rest of its matching chunks, in rank order.
    const matched = new Map<string, StoredChunk[]>();
    const results: VectorDocument[] = [];
    for (const candidate of ordered) {
      const chunks = matched.get(candidate.doc.id);
      if (chunks && !options.passages) continue;
      if (!chunks && results.length >= limit) {
        if (options.passages) continue;
        break;
      }
      if (!candidate.fromDense && minScore > 0) {
        if (lexicalRelevance(query, candidate.text) < minScore) continue;
      }
      if (chunks) {
        chunks.push(candidate.chunk);
        continue;
      }
      matched.set(candidate.doc.id, [candidate.chunk]);
      results.push(candidate.doc);
    }

    // This pool is document-diverse, at most one champion per document from each retriever.
    // It neither reorders the successful prefix nor adds another remote reranking request.
    if (results.length < limit) {
      for (const candidate of fusedCandidates.backfill) {
        if (matched.has(candidate.doc.id)) continue;
        if (!candidate.fromDense && minScore > 0 && lexicalRelevance(query, candidate.text) < minScore) continue;
        matched.set(candidate.doc.id, [candidate.chunk]);
        results.push(candidate.doc);
        if (results.length >= limit) break;
      }
    }

    // Retrieval is what "used" means for eviction. Writing the file on EVERY search was the
    // obvious implementation and it was wrong twice: it puts a disk write on the read path of every
    // query, and — because it cannot be awaited without making every search wait on I/O it does not
    // need — it races anything that inspects the store right after a read. So the in-memory value
    // is updated immediately (eviction reads it on the next write, which persists everything
    // anyway), and the disk copy is flushed by a COALESCED background write: the first retrieval
    // arms one 10s timer, every further retrieval inside the window rides on it, and the timer is
    // unref'd so it can never hold the process open. Worst case is unchanged from before — a
    // crash inside the window forgets recency, which is a hint for eviction, not a fact anything
    // depends on.
    if (results.length) {
      const now = Date.now();
      for (const doc of results) {
        const live = this.store.find((d) => d.id === doc.id);
        if (live) live.lastUsedAt = now;
      }
      this.scheduleRecencyFlush();
    }

    return options.passages
      ? results.map((doc) => ({ ...doc, matchedChunks: matched.get(doc.id) }))
      : results;
  }

  private scheduleRecencyFlush(): void {
    this.recencyDirty = true;
    if (this.recencyTimer) return;
    this.recencyTimer = setTimeout(() => {
      this.recencyTimer = null;
      if (!this.recencyDirty) return;
      this.mutateStore(async () => {
        await this.saveStore();
        this.recencyDirty = false;
      }).catch(() => {
        // Keep the dirty bit: the next retrieval or write gets another chance to persist it.
        this.recencyDirty = true;
      });
    }, this.recencyFlushMs);
    this.recencyTimer.unref?.();
  }

  /** Embed every chunk that has no usable vector. Idempotent; safe to call repeatedly. */
  async backfillEmbeddings(batch: number = 32): Promise<{ embedded: number; pending: number }> {
    if (!this.embeddings) return { embedded: 0, pending: 0 };

    const stale = await this.rwMutex.runExclusive(async () => {
      await this.loadStore(true);
      const out: { id: string; text: string; documentId: string; generation?: string; documentText: string; ordinal: number }[] = [];
      for (const doc of this.store) {
        for (const [ordinal, chunk] of (doc.chunks ?? []).entries()) {
          if (!chunk.embedding || chunk.space !== this.embeddings!.id) out.push({
            id: chunk.id, text: chunk.text, documentId: doc.id, generation: doc.generation,
            documentText: doc.metadata.content, ordinal,
          });
          if (out.length >= batch) return out;
        }
      }
      return out;
    });
    if (!stale.length) return { embedded: 0, pending: 0 };

    const vectors = await this.embeddings.embed(stale.map((s) => s.text), 'passage').catch(() => null);
    if (!vectors) return { embedded: 0, pending: stale.length };
    // A backend can learn its actual width on the first response. Bind that observed space now,
    // then recheck it after waiting for publication rather than stamping a later active space.
    const returnedSpace = this.embeddings.id;

    return this.mutateStore(async () => {
      const byId = new Map(this.store.map(doc => [doc.id, doc]));

      let embedded = 0;
      stale.forEach((item, i) => {
        const doc = byId.get(item.documentId);
        const chunk = doc?.chunks?.[item.ordinal];
        if (!doc || doc.generation !== item.generation || doc.metadata.content !== item.documentText
          || !chunk || chunk.id !== item.id || chunk.text !== item.text
          || !vectors[i] || this.embeddings!.id !== returnedSpace) return;
        chunk.embedding = vectors[i];
        chunk.space = returnedSpace;
        embedded++;
      });
      if (embedded) { this.indexDirty = true; await this.saveStore(); }

      let pending = 0;
      for (const doc of this.store) {
        for (const chunk of doc.chunks ?? []) {
          if (!chunk.embedding || chunk.space !== this.embeddings!.id) pending++;
        }
      }
      return { embedded, pending };
    });
  }
}

import fs = require('fs');
import * as os from 'os';
import * as path from 'path';
import * as self from '../self.model';
import { beginBackgroundEvidence } from '../background.evidence';
import { EpistemicLedger, __setEpistemicLedger, EVIDENCE_OUTPUT_MAX_CHARS, coverageExecutedPaths } from '../epistemic.ledger';
import { EventLedger, __setEventLedger } from '../event.ledger';
import { resetTracerForTests } from '../../telemetry/trace';

const origin = { traceId: 'origin', spanId: 'launch' };
describe('background evidence identity and completion gates', () => {
  let root: string, ep: EpistemicLedger, ev: EventLedger;
  beforeEach(() => {
    root = fs.mkdtempSync(path.join(os.tmpdir(), 'bimax-bg-evidence-'));
    fs.mkdirSync(path.join(root, 'src')); fs.writeFileSync(path.join(root, 'src/a.ts'), 'export const value = 1;');
    jest.spyOn(self, 'mindSingletonRoot').mockReturnValue(root);
    ep = new EpistemicLedger(root); ev = new EventLedger(root);
    __setEpistemicLedger(ep); __setEventLedger(ev);
    process.env.BIMAX_TRACE_DIR = path.join(root, 'traces');
    ep.openClaim('ts', 0.8, 'src/a.ts'); ep.saveNow();
  });
  afterEach(async () => {
    ep.saveNow(); await resetTracerForTests(); __setEpistemicLedger(null); __setEventLedger(null);
    jest.restoreAllMocks(); delete process.env.BIMAX_TRACE_DIR;
    fs.rmSync(root, { recursive: true, force: true });
  });
  it('does nothing at launch, resolves exact scope at completion, and folds completion once', () => {
    const sensor = beginBackgroundEvidence('tsc src/a.ts', root, origin)!;
    expect(ev.count()).toBe(0); expect(ep.stats().open).toBe(1);
    sensor.append('src/'); sensor.append('a.ts(1,1): error TS1000');
    sensor.finish('task', 1, true); sensor.finish('task', 1, true);
    expect(ep.stats()).toMatchObject({ resolved: 1, open: 0 });
    expect(ev.byType('evidence')).toHaveLength(1);
    expect(new EpistemicLedger(root).stats().resolved).toBe(1);
  });
  it.each(['no-file', 'basename', 'wrong-file', 'late-claim', 'changed-file', 'truncated', 'cancelled', 'missing-exit', 'green', 'cross-stream-fragment'])('refuses %s evidence', reason => {
    const sensor = beginBackgroundEvidence('tsc src/a.ts', root, origin)!;
    if (reason === 'late-claim') ep.openClaim('ts', 0.8, 'src/a.ts');
    if (reason === 'changed-file') fs.writeFileSync(path.join(root, 'src/a.ts'), 'export const value = 2;');
    const output = reason === 'no-file' ? 'compiler unavailable' : reason === 'basename' ? 'a.ts(1,1): error'
      : reason === 'wrong-file' ? 'other/a.ts(1,1): error' : 'src/a.ts(1,1): error';
    if (reason === 'cross-stream-fragment') { sensor.append('src/a'); sensor.append('.ts(1,1): error', 'stderr'); }
    else sensor.append(output);
    if (reason === 'truncated') sensor.append('x'.repeat(EVIDENCE_OUTPUT_MAX_CHARS));
    sensor.finish('task', reason === 'green' ? 0 : reason === 'missing-exit' ? null : 1, reason !== 'cancelled');
    expect(ep.stats().resolved).toBe(0); expect(ep.stats().open).toBeGreaterThan(0);
  });
  it('never captures claims minted after launch', () => {
    ep.resolve(false, { output: 'src/a.ts: old error' });
    const sensor = beginBackgroundEvidence('tsc src/a.ts', root, origin)!;
    ep.openClaim('ts', 0.8, 'src/a.ts'); sensor.append('src/a.ts: error'); sensor.finish('task', 1, true);
    expect(ep.stats()).toMatchObject({ resolved: 1, open: 1 });
  });
  it('does not attach evidence without provenance or outside the owning project', () => {
    expect(beginBackgroundEvidence('tsc', root)).toBeUndefined();
    expect(beginBackgroundEvidence('tsc', path.dirname(root), origin)).toBeUndefined();
  });
  it('keeps the last complete snapshot when atomic replacement fails, then retries', () => {
    ep.openClaim('ts', 0.8, 'src/b.ts');
    const rename = jest.spyOn(fs, 'renameSync').mockImplementationOnce(() => { throw new Error('simulated rename interruption'); });
    ep.saveNow();
    expect(new EpistemicLedger(root).stats().open).toBe(1);
    rename.mockRestore(); ep.saveNow();
    expect(new EpistemicLedger(root).stats().open).toBe(2);
    expect(fs.readdirSync(path.join(root, '.bimax')).some(f => f.endsWith('.tmp'))).toBe(false);
  });

  // A green run's positive scope comes only from the runner's own execution attestation.
  const attest = (file: string, hit: number) => `TN:\nSF:${file}\nLF:3\nLH:${hit}\nend_of_record\n`;

  it('reads executed files out of an LCOV report, and only those', () => {
    expect(coverageExecutedPaths(attest('src/a.ts', 3))).toEqual(['src/a.ts']);
    // Loaded but nothing ran: an SF record is not by itself verification.
    expect(coverageExecutedPaths(attest('src/a.ts', 0))).toEqual([]);
    // A tail cut before its LH strands the record; an unparsed count is never a hit.
    expect(coverageExecutedPaths('SF:src/a.ts\nLF:3\n')).toEqual([]);
    // A stranded record must not inherit the NEXT record's hit count either.
    expect(coverageExecutedPaths('SF:src/a.ts\nLF:3\nSF:src/b.ts\nLH:2\nend_of_record\n')).toEqual(['src/b.ts']);
    expect(coverageExecutedPaths('SF:src/a.ts\nend_of_record\nLH:9\n')).toEqual([]);
    // Full project-relative paths, never a basename that could match another directory.
    expect(coverageExecutedPaths(attest('src/deep/nested/util.ts', 2))).toEqual(['src/deep/nested/util.ts']);
    expect(coverageExecutedPaths('')).toEqual([]);
    // Bounded by the same ceiling the diagnostic parser uses.
    expect(coverageExecutedPaths('.'.repeat(EVIDENCE_OUTPUT_MAX_CHARS) + attest('src/a.ts', 3))).toEqual([]);
  });

  it('settles a claim on a green run the runner attests executed it, as CORRECT', () => {
    const sensor = beginBackgroundEvidence('tsc src/a.ts', root, origin)!;
    sensor.append(attest('src/a.ts', 3));
    sensor.finish('task', 0, true);
    expect(ep.stats()).toMatchObject({ resolved: 1, open: 0 });
    // Confirmation, not refutation: the claim's decile must record it correct.
    expect(ep.calibration().find(r => r.n > 0)!.observed).toBe(1);
    expect(new EpistemicLedger(root).stats().resolved).toBe(1);
  });

  it.each([
    ['attests another file', 'src/other.ts', 3, 'attestation-covers-no-claim'],
    ['attests the claim file as loaded but never run', 'src/a.ts', 0, 'no-execution-attestation'],
  ])('refuses a green run that %s', (_label, file, hit, reason) => {
    const sensor = beginBackgroundEvidence('tsc src/a.ts', root, origin)!;
    sensor.append(attest(file as string, hit as number));
    sensor.finish('task', 0, true);
    expect(ep.stats()).toMatchObject({ resolved: 0, open: 1 });
    expect(ev.byType('evidence_skipped')[0].payload.reason).toBe(reason);
  });

  it('does not treat a path merely mentioned in passing output as executed', () => {
    const sensor = beginBackgroundEvidence('tsc src/a.ts', root, origin)!;
    // The run names src/a.ts in its own output while attesting only src/other.ts.
    sensor.append('checked src/a.ts against the fixture\n' + attest('src/other.ts', 3));
    sensor.finish('task', 0, true);
    expect(ep.stats()).toMatchObject({ resolved: 0, open: 1 });
    const skipped = ev.byType('evidence_skipped')[0].payload;
    expect(skipped.outputFiles).toContain('src/a.ts');   // it was mentioned
    expect(skipped.attestedFiles).not.toContain('src/a.ts'); // it was not executed
    expect(skipped.reason).toBe('attestation-covers-no-claim');
  });
});

import { stateDir, stateRoot } from '../utils/state.dir';
import * as fs from 'fs';
import * as path from 'path';
import { exec } from 'child_process';
import { mindSingletonRoot } from './self.model';

/**
 * DrivesEngine — goal homeostasis. The agent gets persistent *drives*: measurable
 * codebase health signals with setpoints (tests green, zero type errors, TODO debt
 * bounded, working tree not sprawling). Deviation from a setpoint is "discomfort":
 * it is surfaced in the system prompt so the agent proactively offers to restore
 * equilibrium, feeds Dream Mode's practice-task supply, and is inspectable via /drives.
 *
 * Measurement is ON DEMAND (/drives check, dream cycles) and strictly SEQUENTIAL —
 * never a hot background loop — so it can't cook the user's machine.
 */

export interface DriveMeasurement { at: string; ok: boolean }

export interface DriveState {
  id: string;
  label: string;
  enabled: boolean;
  /** true = at setpoint (comfortable), false = deviating. undefined = never measured. */
  lastOk?: boolean;
  lastValue?: string;   // human-readable measurement ("3 type errors", "41 TODOs")
  detail?: string;      // first lines of evidence (truncated command output)
  lastRun?: string;     // ISO timestamp
  heavy: boolean;       // heavy drives run builds/tests — only on explicit full checks
  /** Recent measurement history — persistence-gated drives alarm only on sustained breaches. */
  history?: DriveMeasurement[];
}

interface DrivesFile { version: 1; drives: Record<string, Partial<DriveState>> }

interface DriveDef {
  id: string;
  label: string;
  heavy: boolean;
  /**
   * Noisy-by-nature drives (a dirty tree during active work is normal, not a deviation)
   * must breach on ≥2 measurements spaced ≥30 min apart before they alarm — a CUSUM-lite
   * persistence gate. A single spike never nags.
   */
  requiresPersistence?: boolean;
  /** Whether this drive applies to the project at all. */
  applies(root: string): boolean;
  measure(root: string): Promise<{ ok: boolean; value: string; detail?: string }>;
}

const EXEC_TIMEOUT_MS = 180_000;

function run(cmd: string, cwd: string, timeout = EXEC_TIMEOUT_MS): Promise<{ code: number; out: string }> {
  return new Promise(resolve => {
    exec(cmd, { cwd, timeout, maxBuffer: 8 * 1024 * 1024 }, (err, stdout, stderr) => {
      resolve({ code: err ? (typeof (err as any).code === 'number' ? (err as any).code : 1) : 0, out: `${stdout}\n${stderr}`.trim() });
    });
  });
}

function hasFile(root: string, name: string): boolean {
  try { return fs.existsSync(path.join(root, name)); } catch { return false; }
}

function pkgScripts(root: string): Record<string, string> {
  try { return JSON.parse(fs.readFileSync(path.join(root, 'package.json'), 'utf-8')).scripts || {}; } catch { return {}; }
}

const TODO_SETPOINT = 60;
const DIRTY_FILES_SETPOINT = 25;

const DRIVE_DEFS: DriveDef[] = [
  {
    id: 'todo-debt',
    label: 'TODO/FIXME debt bounded',
    heavy: false,
    applies: root => hasFile(root, 'src') || hasFile(root, 'package.json') || hasFile(root, 'go.mod'),
    measure: async root => {
      const dir = hasFile(root, 'src') ? 'src' : '.';
      const excludes = "--exclude-dir=node_modules --exclude-dir=dist --exclude-dir=.git --exclude-dir=vendor --exclude-dir=coverage";
      const { out } = await run(`grep -rEc "TODO|FIXME|HACK" ${dir} ${excludes} --include='*.ts' --include='*.js' --include='*.go' --include='*.py' 2>/dev/null | awk -F: '{s+=$2} END {print s+0}'`, root, 30_000);
      const n = parseInt(out.trim(), 10) || 0;
      return { ok: n <= TODO_SETPOINT, value: `${n} TODO/FIXME markers (setpoint ≤ ${TODO_SETPOINT})` };
    },
  },
  {
    id: 'tree-hygiene',
    label: 'working tree not sprawling',
    heavy: false,
    requiresPersistence: true, // a dirty tree mid-feature is WIP, not a deviation — must persist ≥30 min
    applies: root => hasFile(root, '.git'),
    measure: async root => {
      const { out } = await run('git status --porcelain', root, 20_000);
      const n = out ? out.split('\n').filter(Boolean).length : 0;
      return { ok: n <= DIRTY_FILES_SETPOINT, value: `${n} uncommitted paths (setpoint ≤ ${DIRTY_FILES_SETPOINT})` };
    },
  },
  {
    // Cross-engine insight no other tool can compute: the epistemic ledger knows how many
    // of the agent's correctness claims EXPIRED without any build/test ever checking them.
    // Low coverage = the agent (and the repo) is flying blind — a testing-culture gap
    // surfaced as a measurable drive, not a lecture.
    id: 'verify-coverage',
    label: 'edits actually get verified',
    heavy: false,
    applies: root => hasFile(stateRoot(root), path.join('.bimax', 'epistemic.json')),
    measure: async root => {
      const { EpistemicLedger } = await import('./epistemic.ledger');
      const s = new EpistemicLedger(root).stats();
      const total = s.resolved + s.expired;
      if (total < 20) return { ok: true, value: `only ${total} claims so far — too few to judge (needs 20)` };
      const coverage = s.resolved / total;
      return {
        ok: coverage >= 0.4,
        value: `${Math.round(coverage * 100)}% of ${total} correctness claims met build/test evidence (setpoint ≥ 40%)`,
        detail: coverage < 0.4 ? 'Most edits are never followed by a verifying build/test run — run checks after changes, or add tests where none exist.' : undefined,
      };
    },
  },
  {
    id: 'type-clean',
    label: 'zero TypeScript errors',
    heavy: true,
    applies: root => hasFile(root, 'tsconfig.json'),
    measure: async root => {
      const { code, out } = await run('npx tsc --noEmit --pretty false 2>&1 | head -40', root);
      const errors = (out.match(/error TS\d+/g) || []).length;
      return { ok: code === 0 && errors === 0, value: errors === 0 ? 'typecheck clean' : `${errors}+ type errors`, detail: errors ? out.slice(0, 800) : undefined };
    },
  },
  {
    id: 'tests-green',
    label: 'test suite green',
    heavy: true,
    applies: root => !!pkgScripts(root).test || hasFile(root, 'go.mod'),
    measure: async root => {
      const cmd = pkgScripts(root).test ? 'npm test --silent 2>&1 | tail -25' : 'go test ./... 2>&1 | tail -25';
      const { code, out } = await run(cmd, root, 420_000);
      const failMatch = out.match(/(\d+) failed/i);
      const ok = code === 0 && !/FAIL/i.test(out.replace(/\d+ passed/gi, ''));
      return { ok, value: ok ? 'tests green' : failMatch ? `${failMatch[1]} tests failing` : 'tests failing', detail: ok ? undefined : out.slice(0, 800) };
    },
  },
  {
    id: 'build-green',
    label: 'build succeeds',
    heavy: true,
    applies: root => !!pkgScripts(root).build,
    measure: async root => {
      const { code, out } = await run('npm run build --silent 2>&1 | tail -25', root, 420_000);
      return { ok: code === 0, value: code === 0 ? 'build green' : 'build broken', detail: code === 0 ? undefined : out.slice(0, 800) };
    },
  },
];

export class DrivesEngine {
  private state: Record<string, Partial<DriveState>> = {};
  private loaded = false;
  private filePath: string;
  private root: string;

  constructor(projectRoot: string = process.cwd()) {
    this.root = projectRoot;
    this.filePath = path.join(stateDir('.bimax', projectRoot), 'drives.json');
  }

  private load(): void {
    if (this.loaded) return;
    this.loaded = true;
    try {
      const parsed: DrivesFile = JSON.parse(fs.readFileSync(this.filePath, 'utf-8'));
      if (parsed && parsed.drives && typeof parsed.drives === 'object') this.state = parsed.drives;
    } catch { /* first run */ }
  }

  private save(): void {
    try {
      fs.mkdirSync(path.dirname(this.filePath), { recursive: true });
      fs.writeFileSync(this.filePath, JSON.stringify({ version: 1, drives: this.state } as DrivesFile, null, 2), 'utf-8');
    } catch { /* best-effort */ }
  }

  /** All drives applicable to this project, merged with persisted state. */
  list(): DriveState[] {
    this.load();
    return DRIVE_DEFS.filter(d => {
      try { return d.applies(this.root); } catch { return false; }
    }).map(d => {
      const s = this.state[d.id] || {};
      return {
        id: d.id,
        label: d.label,
        heavy: d.heavy,
        enabled: s.enabled !== false, // enabled unless explicitly disabled
        lastOk: s.lastOk,
        lastValue: s.lastValue,
        detail: s.detail,
        lastRun: s.lastRun,
        history: s.history,
      };
    });
  }

  setEnabled(id: string, enabled: boolean): boolean {
    this.load();
    if (!DRIVE_DEFS.some(d => d.id === id)) return false;
    this.state[id] = { ...(this.state[id] || {}), enabled };
    this.save();
    return true;
  }

  /**
   * Measure drives SEQUENTIALLY (never in parallel — thermal discipline). `quick`
   * skips heavy drives (builds/tests). `only` restricts to one drive id.
   */
  async check(opts?: { quick?: boolean; only?: string }): Promise<DriveState[]> {
    this.load();
    const targets = this.list().filter(d =>
      d.enabled &&
      (!opts?.only || d.id === opts.only) &&
      (!opts?.quick || !d.heavy)
    );
    for (const t of targets) {
      const def = DRIVE_DEFS.find(d => d.id === t.id)!;
      const now = new Date().toISOString();
      try {
        const r = await def.measure(this.root);
        const prev = this.state[t.id] || {};
        const history = [...(prev.history || []), { at: now, ok: r.ok }].slice(-30);
        this.state[t.id] = { ...prev, lastOk: r.ok, lastValue: r.value, detail: r.detail, lastRun: now, history };
      } catch (e: any) {
        this.state[t.id] = { ...(this.state[t.id] || {}), lastOk: undefined, lastValue: `measurement failed: ${e?.message}`, lastRun: now };
      }
      this.save(); // persist after each so a long check that gets interrupted keeps partial results
    }
    return this.list();
  }

  /**
   * Persistence gate for noisy drives: the CURRENT breach must have held across ≥2
   * measurements ≥30 minutes apart with no green measurement in between. A single
   * spike (or a rapid re-check of the same state) never alarms.
   */
  private breachPersisted(d: DriveState): boolean {
    const h = d.history || [];
    if (h.length === 0 || h[h.length - 1].ok) return false;
    // Walk back through the current uninterrupted breach run.
    let earliest = h[h.length - 1].at;
    for (let i = h.length - 2; i >= 0; i--) {
      if (h[i].ok) break;
      earliest = h[i].at;
    }
    const spanMs = new Date(h[h.length - 1].at).getTime() - new Date(earliest).getTime();
    return spanMs >= 30 * 60_000;
  }

  /**
   * Drives currently deviating from setpoint: fresh breach, and for persistence-gated
   * drives the breach must have HELD across measurements (see breachPersisted).
   */
  deviations(maxAgeHours = 24): DriveState[] {
    const cutoff = Date.now() - maxAgeHours * 3600_000;
    return this.list().filter(d => {
      if (!d.enabled || d.lastOk !== false || d.lastRun === undefined || new Date(d.lastRun).getTime() < cutoff) return false;
      const def = DRIVE_DEFS.find(x => x.id === d.id);
      if (def?.requiresPersistence) return this.breachPersisted(d);
      return true;
    });
  }

  /**
   * Prompt block: current deviations as standing discomfort. Only fresh measurements —
   * stale deviations would have the agent chasing ghosts.
   */
  getPromptBlock(): string {
    const dev = this.deviations();
    if (dev.length === 0) return '';
    const lines = dev.map(d => `- ${d.label}: ${d.lastValue}${d.detail ? `\n  evidence: ${d.detail.split('\n')[0]}` : ''}`);
    return `### DRIVES (homeostasis — the codebase is off its setpoints)\nThese measured health signals are deviating. If the user's request touches related code, fix the deviation as part of the work; otherwise briefly offer to. Do not silently ignore them.\n${lines.join('\n')}`;
  }

  /** A concrete micro-task prompt to restore the worst deviation — Dream Mode's task supply. */
  nextRestorationTask(): { drive: DriveState; prompt: string } | null {
    const dev = this.deviations();
    if (dev.length === 0) return null;
    // Heavy signals (broken build/tests) outrank hygiene ones.
    const worst = dev.sort((a, b) => Number(b.heavy) - Number(a.heavy))[0];
    const prompts: Record<string, string> = {
      'type-clean': `The TypeScript typecheck is failing (${worst.lastValue}). Run \`npx tsc --noEmit\`, fix every error, and verify the typecheck passes.`,
      'tests-green': `The test suite is failing (${worst.lastValue}). Run the tests, fix the failures (fix the code, not the assertions, unless the test is provably stale), and verify green.`,
      'build-green': `The build is broken (${worst.lastValue}). Run the build, fix the errors, and verify it completes.`,
      'todo-debt': `TODO/FIXME debt is above setpoint (${worst.lastValue}). Pick the 5 oldest/riskiest markers in src/, resolve them properly (implement or delete with justification), and re-count.`,
      'tree-hygiene': `The working tree has too many uncommitted paths (${worst.lastValue}). Review git status, group related changes, and propose commit(s) — do not commit without approval.`,
      'verify-coverage': `Most recent edits were never verified by any build/test run (${worst.lastValue}). Identify the recently-edited files with no covering tests, add focused tests for the riskiest ones, and run them.`,
    };
    return { drive: worst, prompt: prompts[worst.id] || `Restore drive "${worst.label}" — current: ${worst.lastValue}.` };
  }

  report(): string[] {
    const all = this.list();
    if (all.length === 0) return ['- No drives apply to this directory.'];
    return all.map(d => {
      const def = DRIVE_DEFS.find(x => x.id === d.id);
      const pending = d.lastOk === false && def?.requiresPersistence && !this.breachPersisted(d);
      const glyph = !d.enabled ? '○' : d.lastOk === undefined ? '·' : d.lastOk ? '✓' : pending ? '~' : '✗';
      const age = d.lastRun ? ` (checked ${timeAgo(d.lastRun)})` : ' (never checked)';
      const note = pending ? ' — breach not yet persistent (likely WIP, watching)' : '';
      return `- ${glyph} ${d.label}${d.enabled ? `: ${d.lastValue ?? 'unmeasured'}${age}${note}` : ' — disabled'}`;
    });
  }
}

function timeAgo(iso: string): string {
  const s = Math.max(0, (Date.now() - new Date(iso).getTime()) / 1000);
  if (s < 90) return `${Math.round(s)}s ago`;
  if (s < 5400) return `${Math.round(s / 60)}m ago`;
  if (s < 129600) return `${Math.round(s / 3600)}h ago`;
  return `${Math.round(s / 86400)}d ago`;
}

let _global: DrivesEngine | null = null;
export function getDrivesEngine(): DrivesEngine {
  if (!_global) _global = new DrivesEngine(mindSingletonRoot());
  return _global;
}
export function __setDrivesEngine(e: DrivesEngine | null): void { _global = e; }

/**
 * Local embeddings (BiMax v2, D2 — the honest zero-dependency tier).
 *
 * Character/token n-gram FEATURE HASHING into a fixed-dimension vector + cosine
 * similarity. Runs everywhere, costs nothing, needs no model download — and is
 * deliberately labeled for what it is: a lexical-similarity kernel, not a semantic
 * model. For the two v2 consumers (diff-taste k-NN, exemplar retrieval) that's the
 * right honesty tradeoff, because BOTH only ever use embeddings as *evidence
 * retrieval with the retrieved items shown* (the plan's own self-critique made that
 * a hard rule).
 *
 * BACKEND SEAM: `embed()` delegates to the active EmbedBackend. A real local encoder
 * (ONNX, reusing the Headroom venv muscle) plugs in via `setEmbedBackend` or the
 * BIMAX_EMBEDDER_MODULE env hook (a module exporting `createBackend()`), and every
 * vector store re-embeds automatically because they persist `embedderInfo().version`
 * alongside their cached vectors — swapping the model can never silently mix vector
 * spaces.
 */

export const EMBED_DIM = 256;

export interface EmbedBackend {
  name: string;
  /** Bump when vectors are incompatible with the previous backend — stores re-embed on mismatch. */
  version: number;
  dim: number;
  embed(text: string): Float32Array;
}

/** FNV-1a 32-bit — fast, stable string hash for feature bucketing. */
function fnv1a(s: string): number {
  let h = 0x811c9dc5;
  for (let i = 0; i < s.length; i++) {
    h ^= s.charCodeAt(i);
    h = Math.imul(h, 0x01000193);
  }
  return h >>> 0;
}

/**
 * Embed text: word unigrams+bigrams and char trigrams, hashed into EMBED_DIM buckets
 * with a sign trick (second hash decides ±) to reduce collision bias, L2-normalized.
 */
function hashKernelEmbed(text: string): Float32Array {
  const v = new Float32Array(EMBED_DIM);
  const norm = (text || '').toLowerCase().replace(/\s+/g, ' ').trim().slice(0, 20_000);
  if (!norm) return v;

  const bump = (feat: string, w: number) => {
    const h = fnv1a(feat);
    const sign = (h & 0x80000000) ? -1 : 1;
    v[h % EMBED_DIM] += sign * w;
  };

  const words = norm.split(/[^a-z0-9_$./-]+/).filter(w => w.length > 1);
  for (let i = 0; i < words.length; i++) {
    bump(`w:${words[i]}`, 1);
    if (i + 1 < words.length) bump(`b:${words[i]}|${words[i + 1]}`, 1.5);
  }
  for (let i = 0; i + 3 <= Math.min(norm.length, 4000); i++) {
    bump(`c:${norm.slice(i, i + 3)}`, 0.25);
  }

  let mag = 0;
  for (let i = 0; i < EMBED_DIM; i++) mag += v[i] * v[i];
  mag = Math.sqrt(mag);
  if (mag > 0) for (let i = 0; i < EMBED_DIM; i++) v[i] /= mag;
  return v;
}

const HASH_KERNEL: EmbedBackend = { name: 'hash-kernel', version: 1, dim: EMBED_DIM, embed: hashKernelEmbed };

let _backend: EmbedBackend | null = null;

/**
 * Resolve the active backend: an explicitly-set one wins; otherwise the
 * BIMAX_EMBEDDER_MODULE hook is tried ONCE (a module exporting `createBackend():
 * EmbedBackend` — the ONNX plug point); the hash kernel is the always-works floor.
 */
function activeBackend(): EmbedBackend {
  if (_backend) return _backend;
  const mod = process.env.BIMAX_EMBEDDER_MODULE;
  if (mod) {
    try {
      // eslint-disable-next-line @typescript-eslint/no-var-requires
      const loaded = require(mod);
      const b = loaded?.createBackend?.();
      if (b && typeof b.embed === 'function' && b.version > 1) {
        _backend = b as EmbedBackend;
        return _backend;
      }
    } catch { /* a broken plugin must never take retrieval down — fall through */ }
  }
  _backend = HASH_KERNEL;
  return _backend;
}

/** Swap the encoder (tests, or a real ONNX backend wired at boot). Null restores the default resolution. */
export function setEmbedBackend(b: EmbedBackend | null): void { _backend = b; }

/** What the persisted vector stores stamp next to their cached vectors. */
export function embedderInfo(): { name: string; version: number; dim: number } {
  const b = activeBackend();
  return { name: b.name, version: b.version, dim: b.dim };
}

/** Embed text with the active backend (hash kernel unless a real encoder is plugged in). */
export function embed(text: string): Float32Array {
  return activeBackend().embed(text);
}

/** Cosine similarity of two L2-normalized vectors (plain dot product). */
export function cosine(a: ArrayLike<number>, b: ArrayLike<number>): number {
  const n = Math.min(a.length, b.length);
  let dot = 0;
  for (let i = 0; i < n; i++) dot += a[i] * b[i];
  return dot;
}

/** Round-trippable compact form for JSON stores (3 decimals is plenty for cosine). */
export function packEmbedding(v: Float32Array): number[] {
  return Array.from(v, x => Math.round(x * 1000) / 1000);
}

export interface Neighbor<T> { item: T; sim: number }

/** k nearest neighbors by cosine among items carrying packed embeddings. */
export function nearest<T extends { embedding?: number[] }>(
  query: Float32Array, items: T[], k: number, minSim = 0.1
): Neighbor<T>[] {
  const scored: Neighbor<T>[] = [];
  for (const item of items) {
    if (!item.embedding || item.embedding.length === 0) continue;
    const sim = cosine(query, item.embedding);
    if (sim >= minSim) scored.push({ item, sim });
  }
  return scored.sort((a, b) => b.sim - a.sim).slice(0, k);
}

import { stateDir } from '../utils/state.dir';
import * as fs from 'fs';
import * as path from 'path';
import * as crypto from 'crypto';
import { LLMProvider, Message, ChatOptions, ChatEvent } from '../core/llm.provider';
import { mindSingletonRoot } from './self.model';
import { getEventLedger } from './event.ledger';
import { redactSecretsDeep } from '../security/secret.scan';
import { isReplayActive } from '../core/replay.scope';
export { isReplayActive } from '../core/replay.scope';

/**
 * Episode bundles — the agent's black-box flight recorder (BiMax v2, Phase 4 minimal).
 *
 * Every AgentLoop.execute() becomes an EPISODE: an append-only, hash-chained JSONL
 * bundle under .bimax/episodes/ recording each LLM call's request hash, the messages
 * that were NEW since the previous call (tool results, nudges — the causal trace), and
 * the full coalesced response stream (thinking, text, tool calls, usage).
 *
 * Two things this buys, per the v2 plan (§7 / §9.5):
 *   - Flight recorder: "why did it edit that file?" is answerable after the fact from
 *     the recorded stream — /episodes renders any past run step by step.
 *   - Replay: ReplayProvider re-serves the recorded responses keyed by request hash,
 *     so a harness/prompt/policy change can be evaluated against RECORDED traffic at
 *     zero token cost — divergence (a request whose hash no longer matches) is itself
 *     the signal, marking exactly where the changed harness alters behavior.
 *
 * Same discipline as the event ledger: recording is strictly best-effort (never throws,
 * BIMAX_RECORDER=0 disables), bundles are tamper-evident (each line's hash covers its
 * predecessor's), and old bundles are pruned so the recorder can be always-on.
 */

const EPISODES_KEPT = 40;             // prune beyond this many bundles (oldest first)
const MSG_CONTENT_CAP = 200_000;      // pathology bound only — tools cap their own output far
                                      // below this; truncation breaks replay fidelity for that
                                      // message, so the ceiling is deliberately generous

export interface RecordedResponse {
  text: string;
  thinking?: string;
  toolCalls: { id: string; name: string; args: string }[];
  usage?: { prompt: number; completion: number };
  error?: string;
  /** Stream ended without a 'done' event (abort / crash mid-stream). */
  incomplete?: boolean;
}

export interface RecordedCall {
  idx: number;
  ts: number;
  reqHash: string;
  msgCount: number;
  /** Sorted tool names advertised on this request — replay re-advertises exactly these. */
  toolNames: string[];
  /** Messages appended to the history since the previous call in this episode. */
  newMessages: (Pick<Message, 'tool_calls'> & { role: string; content?: string; name?: string; tool_call_id?: string })[];
  /** Set when the history SHRANK since the last call (compaction) — newMessages is a snapshot tail. */
  reset?: boolean;
  response: RecordedResponse;
}

export interface EpisodeHeader {
  v: 1;
  id: string;
  session: string;
  startedAt: number;
  sysHash: string;
  /** Full system prompt — replay's default baseline (compare-against-current is the eval). */
  system?: string;
  /** Repo HEAD when the episode started — the snapshot key for history-replay task generation. */
  commit?: string;
  lite: boolean;
}

/** Deterministic JSON with recursively sorted keys — object key order must not change hashes. */
function stableStringify(v: any): string {
  if (v === null || typeof v !== 'object') return JSON.stringify(v);
  if (Array.isArray(v)) return `[${v.map(stableStringify).join(',')}]`;
  const keys = Object.keys(v).filter(k => v[k] !== undefined).sort();
  return `{${keys.map(k => `${JSON.stringify(k)}:${stableStringify(v[k])}`).join(',')}}`;
}

export function requestToolNames(options: ChatOptions): string[] {
  return (options.tools || [])
    .map((t: any) => t?.function?.name || t?.name || '?')
    .sort();
}

/**
 * Canonical hash of one LLM request — the replay key. Covers everything that shapes the
 * response: full message history, system prompt, tool NAMES (schemas are huge and change
 * with descriptions; the name set is what alters model behavior), sampling knobs, tier.
 * Key-order-insensitive so a replay that RECONSTRUCTS messages hashes identically.
 */
export function hashRequest(messages: Message[], options: ChatOptions): string {
  const body = stableStringify({
    system: options.system || '',
    lite: !!options.lite,
    temperature: options.temperature ?? null,
    effort: options.reasoningEffort ?? null,
    tools: requestToolNames(options),
    messages,
  });
  return crypto.createHash('sha256').update(body).digest('hex');
}

// --- Replay guard -----------------------------------------------------------
// While a replay is driving a real AgentLoop, the learning observers (self-model,
// habit miner, epistemic claims, event ledger) and the recorder itself must stand
// down — a replayed episode re-observed as fresh experience would double-count
// every outcome it already learned from.

const SESSION_ID = `${process.pid}-${Date.now().toString(36)}`;

function episodesDir(root: string): string {
  return path.join(stateDir('.bimax', root), 'episodes');
}

/**
 * One stored message for the bundle. Full fidelity is the goal — replay reconstructs the
 * initial history and serves tool results from these, so tool_calls are preserved and
 * truncation only fires at a pathology bound. Multimodal parts are the one lossy case
 * (reduced to a marker) — a replay across them diverges by construction and says so.
 */
function capMessage(m: Message): RecordedCall['newMessages'][number] {
  let content: string | undefined;
  if (typeof m.content === 'string') {
    content = m.content.length > MSG_CONTENT_CAP
      ? m.content.slice(0, MSG_CONTENT_CAP) + `\n…[truncated ${m.content.length - MSG_CONTENT_CAP} chars]`
      : m.content;
  } else if (Array.isArray(m.content)) {
    content = `[multimodal content: ${m.content.length} part(s)]`;
  }
  const out: RecordedCall['newMessages'][number] = { role: m.role };
  if (content !== undefined) out.content = content;
  if (m.name) out.name = m.name;
  if (m.tool_call_id) out.tool_call_id = m.tool_call_id;
  if (m.tool_calls) out.tool_calls = m.tool_calls;
  return out;
}

/**
 * Writes one episode bundle, one JSONL line per LLM call, hash-chained like the event
 * ledger: line N's `h` covers its own body plus line N−1's `h`. Self-flushing — the
 * bundle is valid after every call, so no close step is needed (a crash simply leaves
 * the last completed call as the end of the recording).
 */
export class EpisodeWriter {
  readonly id: string;
  private filePath: string;
  private prevHash = '';
  private headerWritten = false;
  private disabled: boolean;
  private lastMsgCount = 0;
  private idx = 0;

  constructor(private root: string = mindSingletonRoot()) {
    this.id = `e-${Date.now().toString(36)}-${crypto.randomBytes(2).toString('hex')}`;
    this.filePath = path.join(episodesDir(root), `${this.id}.jsonl`);
    this.disabled = process.env.BIMAX_RECORDER === '0';
  }

  file(): string { return this.filePath; }

  private writeLine(raw: Record<string, any>): void {
    const obj = redactSecretsDeep(raw); // scrubbed before hashing, so the chain covers what is on disk
    const body = JSON.stringify(obj);
    const h = crypto.createHash('sha256').update(`${this.prevHash}|${body}`).digest('hex');
    fs.appendFileSync(this.filePath, JSON.stringify({ ...obj, h }) + '\n', 'utf-8');
    this.prevHash = h;
  }

  private ensureHeader(options: ChatOptions): void {
    if (this.headerWritten) return;
    fs.mkdirSync(episodesDir(this.root), { recursive: true });
    pruneEpisodes(this.root);
    const header: EpisodeHeader = {
      v: 1,
      id: this.id,
      session: SESSION_ID,
      startedAt: Date.now(),
      sysHash: crypto.createHash('sha256').update(options.system || '').digest('hex').slice(0, 16),
      system: options.system || '',
      lite: !!options.lite,
    };
    try {
      const { execFileSync } = require('child_process');
      header.commit = String(execFileSync('git', ['rev-parse', 'HEAD'], { cwd: this.root, stdio: 'pipe', timeout: 3000 })).trim();
    } catch { /* not a git repo — history-replay just won't offer this episode */ }
    this.writeLine(header);
    this.headerWritten = true;
    // One anchor event in the ledger per episode — the bundle itself holds the detail.
    getEventLedger().append('episode', { id: this.id, session: SESSION_ID });
  }

  /** Record one completed (or aborted) LLM call. Never throws. */
  recordCall(messages: Message[], options: ChatOptions, reqHash: string, response: RecordedResponse): void {
    if (this.disabled) return;
    try {
      this.ensureHeader(options);
      const reset = messages.length < this.lastMsgCount;
      const delta = reset ? messages.slice(-6) : messages.slice(this.lastMsgCount);
      const call: RecordedCall = {
        idx: this.idx++,
        ts: Date.now(),
        reqHash,
        msgCount: messages.length,
        toolNames: requestToolNames(options),
        newMessages: delta.map(capMessage),
        response,
      };
      if (reset) call.reset = true;
      this.lastMsgCount = messages.length;
      this.writeLine(call as any);
    } catch { /* best-effort — recording must never break the agent */ }
  }
}

/** LLMProvider wrapper that streams through unchanged while recording each call. */
export class RecordingProvider implements LLMProvider {
  constructor(private inner: LLMProvider, readonly writer: EpisodeWriter) {}

  async *chat(messages: Message[], options: ChatOptions): AsyncGenerator<ChatEvent> {
    const reqHash = hashRequest(messages, options);
    let text = '';
    let thinking = '';
    const toolCalls: RecordedResponse['toolCalls'] = [];
    let usage: RecordedResponse['usage'];
    let error: string | undefined;
    let sawDone = false;
    try {
      for await (const ev of this.inner.chat(messages, options)) {
        switch (ev.type) {
          case 'token': text += ev.text; break;
          case 'thinking': thinking += ev.text; break;
          case 'tool_call': toolCalls.push({ id: ev.id, name: ev.name, args: ev.args }); break;
          case 'usage': usage = { prompt: ev.prompt, completion: ev.completion }; break;
          case 'error': error = ev.message; break;
          case 'done': sawDone = true; break;
        }
        yield ev;
      }
    } finally {
      // Runs on normal completion AND when the consumer abandons the stream (abort) —
      // an interrupted call is recorded as incomplete rather than lost.
      const response: RecordedResponse = { text, toolCalls };
      if (thinking) response.thinking = thinking;
      if (usage) response.usage = usage;
      if (error) response.error = error;
      if (!sawDone) response.incomplete = true;
      this.writer.recordCall(messages, options, reqHash, response);
    }
  }
}

/**
 * Start recording an episode around a provider. The one integration point for the agent
 * loop: wraps the provider when recording is possible, hands back the original when not.
 */
export function startEpisodeRecording(inner: LLMProvider, root?: string): { llm: LLMProvider; id: string | null } {
  // A replayed run must not record a fresh episode of itself.
  if (process.env.BIMAX_RECORDER === '0' || isReplayActive()) return { llm: inner, id: null };
  // Callers such as the counterfactual lab may provide an explicit recorder so they can own the
  // episode id and location. Wrapping it again creates two adjacent ledger anchors for one run;
  // the empty interval between them then makes the recorded-failure census read 0/0. Reuse the
  // existing recorder instead of nesting flight recorders.
  if (inner instanceof RecordingProvider) return { llm: inner, id: inner.writer.id };
  try {
    const writer = new EpisodeWriter(root);
    return { llm: new RecordingProvider(inner, writer), id: writer.id };
  } catch {
    return { llm: inner, id: null };
  }
}

// ---------------------------------------------------------------------------
// Reading side — list, load/verify, replay.
// ---------------------------------------------------------------------------

export interface EpisodeSummary {
  id: string;
  file: string;
  startedAt: number;
  endedAt: number;
  calls: number;
  toolCalls: number;
  bytes: number;
  incomplete: boolean;
}

export interface LoadedEpisode {
  header: EpisodeHeader;
  calls: RecordedCall[];
  chainOk: boolean;
  brokenAt: number | null;   // 1-based line number of the first bad hash
  file: string;
}

function parseBundle(file: string): LoadedEpisode | null {
  try {
    const lines = fs.readFileSync(file, 'utf-8').split('\n').filter(l => l.trim());
    if (lines.length === 0) return null;
    let prev = '';
    let chainOk = true;
    let brokenAt: number | null = null;
    const parsed: any[] = [];
    for (let i = 0; i < lines.length; i++) {
      const obj = JSON.parse(lines[i]);
      const { h, ...body } = obj;
      const expect = crypto.createHash('sha256').update(`${prev}|${JSON.stringify(body)}`).digest('hex');
      if (chainOk && expect !== h) { chainOk = false; brokenAt = i + 1; }
      prev = h;
      parsed.push(obj);
    }
    const header = parsed[0] as EpisodeHeader;
    if (header?.v !== 1 || !header.id) return null;
    return { header, calls: parsed.slice(1) as RecordedCall[], chainOk, brokenAt, file };
  } catch {
    return null;
  }
}

export function listEpisodes(root: string = mindSingletonRoot()): EpisodeSummary[] {
  try {
    const dir = episodesDir(root);
    const files = fs.readdirSync(dir).filter(f => f.endsWith('.jsonl')).sort();
    const out: EpisodeSummary[] = [];
    for (const f of files) {
      const full = path.join(dir, f);
      const ep = parseBundle(full);
      if (!ep) continue;
      const last = ep.calls[ep.calls.length - 1];
      out.push({
        id: ep.header.id,
        file: full,
        startedAt: ep.header.startedAt,
        endedAt: last?.ts || ep.header.startedAt,
        calls: ep.calls.length,
        toolCalls: ep.calls.reduce((a, c) => a + (c.response?.toolCalls?.length || 0), 0),
        bytes: fs.statSync(full).size,
        incomplete: !!last?.response?.incomplete,
      });
    }
    return out;
  } catch {
    return [];
  }
}

export function loadEpisode(idOrFile: string, root: string = mindSingletonRoot()): LoadedEpisode | null {
  const file = idOrFile.endsWith('.jsonl') ? idOrFile : path.join(episodesDir(root), `${idOrFile}.jsonl`);
  return parseBundle(file);
}

function pruneEpisodes(root: string): void {
  try {
    const dir = episodesDir(root);
    const files = fs.readdirSync(dir).filter(f => f.endsWith('.jsonl')).sort();
    for (const f of files.slice(0, Math.max(0, files.length - (EPISODES_KEPT - 1)))) {
      fs.unlinkSync(path.join(dir, f));
    }
  } catch { /* best-effort */ }
}

/**
 * Serves a recorded episode as an LLMProvider — the replay half of the recorder.
 *
 * Matching: a request whose hash equals an unserved recorded call gets that call's
 * response (deterministic replay). A request with NO hash match — the harness changed
 * the prompt/context — gets the next unserved call IN ORDER, and the mismatch is logged
 * as a divergence: the precise point where the change under test alters the trajectory.
 * When the recording is exhausted, an unrecoverable error event ends the run.
 */
export class ReplayProvider implements LLMProvider {
  readonly divergences: { idx: number; expected: string; got: string }[] = [];
  served = 0;
  private consumed = new Set<number>();

  constructor(private calls: RecordedCall[]) {}

  /** The next unserved recorded call — the replay harness advertises ITS tool names. */
  peekNext(): RecordedCall | undefined {
    return this.calls.find(c => !this.consumed.has(c.idx));
  }

  async *chat(messages: Message[], options: ChatOptions): AsyncGenerator<ChatEvent> {
    const got = hashRequest(messages, options);
    let rec = this.calls.find(c => !this.consumed.has(c.idx) && c.reqHash === got);
    if (!rec) {
      rec = this.calls.find(c => !this.consumed.has(c.idx));
      if (rec) this.divergences.push({ idx: rec.idx, expected: rec.reqHash, got });
    }
    if (!rec) {
      yield { type: 'error', message: 'Replay exhausted — no recorded calls left in this episode.', recoverable: false };
      return;
    }
    this.consumed.add(rec.idx);
    this.served++;
    const r = rec.response;
    if (r.thinking) yield { type: 'thinking', text: r.thinking };
    if (r.text) yield { type: 'token', text: r.text };
    for (const tc of r.toolCalls || []) yield { type: 'tool_call', id: tc.id, name: tc.name, args: tc.args };
    if (r.usage) yield { type: 'usage', prompt: r.usage.prompt, completion: r.usage.completion };
    if (r.error) yield { type: 'error', message: r.error, recoverable: false };
    yield { type: 'done' };
  }
}

import { stateDir } from '../utils/state.dir';
import * as fs from 'fs';
import * as path from 'path';
import { randomUUID } from 'crypto';
import { mindSingletonRoot } from './self.model';
import { wilsonInterval, isotonicFit, expectedCalibrationError } from './stats';
import { TestDependencyMap, importReachable } from './tdm';

/**
 * EpistemicLedger v2 — calibrated confidence with SCOPED attribution.
 *
 * v1's fatal flaw: any build/test evidence within 15 minutes resolved EVERY open claim,
 * so one pre-existing red test refuted innocent edits and the calibration curve
 * converged to biased noise. v2 resolves a claim only with evidence that plausibly
 * COVERS it:
 *
 *   - Claims carry the FILE they mutated.
 *   - RED evidence refutes only claims whose file appears in the failure output
 *     (compiler/test runners print paths — tsc `a.ts(12,3)`, jest `FAIL src/x.test.ts`,
 *     go `./pkg/f.go:33`). Red output naming no files resolves NOTHING — it is
 *     counted as unattributed evidence instead of poisoning the labels.
 *   - GREEN evidence from a repo-wide command (no path arguments) confirms all open
 *     claims in the window — a green full check is legitimately global. Green from a
 *     path-scoped command (e.g. `jest src/x.test.ts`) confirms only matching claims.
 *
 * From resolved claims: a calibration curve (stated confidence deciles vs. observed
 * accuracy) and overconfident domains that get a verification-escalation prompt rule.
 * Unresolved claims expire — silence is not evidence — and the expiry rate itself is
 * reported (it measures how much of the agent's work nothing ever verifies).
 */

export interface OpenClaim {
  id?: string;        // legacy claims may lack identity; never eligible for background settlement
  domain: string;      // file extension the mutation touched
  file?: string;       // the mutated path — the scoping key
  confidence: number;  // 0..1, stated at claim time (grounded in the self-model)
  at: number;          // epoch ms
}

/** Engine-authored receipt describing both settlement and the exact verification scope. */
export interface EvidenceResolution {
  settled: number;
  coveredFiles: string[];
  /** True only for a successful evidence command with no path arguments. */
  repoWide: boolean;
}

interface Bucket { n: number; correct: number }

interface DomainStat { n: number; correct: number; confSum: number }

interface LedgerFile {
  version: 2;
  open: OpenClaim[];
  buckets: Bucket[];             // 10 deciles: [0-10%), [10-20%) … [90-100%]
  domains: Record<string, DomainStat>;
  expired: number;               // claims that timed out unverified (verification-coverage gap)
  unattributed: number;          // red evidence that named no files (couldn't be scoped)
}

export const CLAIM_TTL_MS = 30 * 60_000;   // unresolved claims expire — silence is not evidence
const EVIDENCE_WINDOW_MS = 15 * 60_000; // evidence only resolves claims this recent
const MIN_DOMAIN_SAMPLES = 5;       // weighted samples before a domain can escalate

// Attribution weights (the plan's TDM tiers, path-evidence flavor): an exact path-suffix
// match is strong evidence about THAT claim; a basename-only match might be a same-named
// file elsewhere; a repo-wide green check is legitimately global.
const W_EXACT = 1.0;
const W_BASENAME = 0.7;

/** Does this shell command produce correctness evidence (build/test/typecheck)? */
export function isEvidenceCommand(command: string): boolean {
  const c = (command || '').toLowerCase();
  if (/\b(node\s+--test|bun\s+test)\b/.test(c)) return true;
  return /\b(npm (run )?(test|build)|npx? (tsc|jest|vitest|eslint)|yarn (test|build)|pnpm (test|build)|go (build|test|vet)|cargo (build|test|check)|pytest|tsc\b|jest\b|vitest\b|make (test|build|check))\b/.test(c);
}

/** A bounded whole-repository check, with no narrowing flags, directory switch or shell masking. */
export function isRepoWideEvidenceCommand(command: string): boolean {
  return /^(?:(?:npm|yarn|pnpm) (?:test|build|run (?:test|build))|(?:npx )?(?:jest|vitest)(?: --(?:runInBand|coverage(?:=false)?))?|(?:npx )?tsc(?: --noEmit)?|bun test|node --test|go (?:test|build|vet) \.\/\.\.\.|cargo (?:test|build|check)|pytest|make (?:test|build|check))$/.test(command.trim());
}

/** File-ish tokens in a shell command (path arguments) — used to detect scoped vs repo-wide runs. */
export function commandPathTokens(command: string): string[] {
  return (command || '')
    .split(/\s+/)
    .filter(t => !t.startsWith('-') && /\.[A-Za-z]{1,5}$/.test(t) && !/^\d+\.\d+/.test(t))
    .map(t => t.replace(/^['"]|['"]$/g, ''));
}

export const EVIDENCE_OUTPUT_MAX_CHARS = 20_000; // existing diagnostic parser input ceiling

/** Source-file paths named in build/test output (tsc, jest, vitest, go, cargo, pytest formats). */
export function outputFilePaths(output: string): string[] {
  const found = new Set<string>();
  const re = /([A-Za-z0-9_$@./\\-]+\.(?:ts|tsx|js|jsx|mjs|cjs|go|py|rs|java|rb|c|cc|cpp|h|hpp))(?=[:(\s'"]|$)/gm;
  let m: RegExpExecArray | null;
  const capped = (output || '').slice(0, EVIDENCE_OUTPUT_MAX_CHARS);
  while ((m = re.exec(capped)) !== null) {
    found.add(m[1]);
    if (found.size >= 50) break;
  }
  return Array.from(found);
}

/**
 * Files a runner's own LCOV report proves it EXECUTED (`SF:` with a non-zero `LH:`).
 *
 * This is the only positive scope accepted. Green stdout cannot supply one: measured on
 * node 22.23.1 under piped capture, `node --test` names only test names on success and
 * jest prints aggregate counts with no per-file line even at `--verbose`, while both name
 * paths on failure. Reporters report exceptions, not the routine.
 *
 * Coverage is independent of the command in the way that matters: a path can be named on
 * the command line and still never run — filtered, skipped, or never imported — and such a
 * file gets no `SF:` record at all. `SF:` carries the full project-relative path, so no
 * basename reassembly (and therefore no basename matching) is involved. `LH: 0` is not
 * verification: the file was loaded but nothing in it ran. A record stranded without its
 * `LH:` by a truncated tail counts as nothing, never as a hit.
 */
export function coverageExecutedPaths(output: string): string[] {
  const executed = new Set<string>();
  const capped = (output || '').slice(0, EVIDENCE_OUTPUT_MAX_CHARS);
  let file: string | null = null;
  for (const raw of capped.split('\n')) {
    const line = raw.trim();
    if (line.startsWith('SF:')) { file = line.slice(3).trim() || null; continue; }
    if (!file) continue;
    if (line === 'end_of_record') { file = null; continue; }
    if (line.startsWith('LH:')) {
      const hit = Number(line.slice(3).trim());
      if (Number.isInteger(hit) && hit > 0) executed.add(file);
      file = null;
      if (executed.size >= 50) break;
    }
  }
  return Array.from(executed);
}

/**
 * How strongly does the named evidence cover this claim's file?
 * 1.0 = a path-suffix match (same file), 0.7 = basename-only (could be a same-named
 * file elsewhere — evidence, but weaker), 0 = not covered at all.
 */
function matchWeight(claimFile: string | undefined, evidencePaths: string[]): number {
  if (!claimFile || evidencePaths.length === 0) return 0;
  const cBase = path.basename(claimFile);
  const cNorm = claimFile.replace(/\\/g, '/');
  let best = 0;
  for (const p of evidencePaths) {
    const pNorm = p.replace(/\\/g, '/');
    if (pNorm.endsWith(cNorm) || cNorm.endsWith(pNorm)) return W_EXACT;
    if (path.basename(pNorm) === cBase) best = Math.max(best, W_BASENAME);
  }
  return best;
}

/**
 * Import-tier reachability over the live code graph, resolved lazily (and via require,
 * so mind ↛ memory doesn't become a static import cycle). Unavailable graph = tier off.
 */
function graphImportReach(from: string, to: string): boolean {
  try {
    // eslint-disable-next-line @typescript-eslint/no-var-requires
    const { getContextManagerGraphStore } = require('../memory/context.manager');
    const store = getContextManagerGraphStore();
    return store ? importReachable(store, from, to) : false;
  } catch { return false; }
}

export class EpistemicLedger {
  private data: LedgerFile = {
    version: 2,
    open: [],
    buckets: Array.from({ length: 10 }, () => ({ n: 0, correct: 0 })),
    domains: {},
    expired: 0,
    unattributed: 0,
  };
  private loaded = false;
  private dirty = false;
  private filePath: string;
  private saveTimer: NodeJS.Timeout | null = null;
  private tdm: TestDependencyMap;

  constructor(projectRoot: string = process.cwd()) {
    this.filePath = path.join(stateDir('.bimax', projectRoot), 'epistemic.json');
    this.tdm = new TestDependencyMap(projectRoot);
  }

  /**
   * Path heuristics OR the Test-Dependency Map, whichever covers more strongly. The TDM
   * is what lets `jest src/__tests__/x.test.ts` evidence settle a claim on `src/x.ts` —
   * different paths, but the map knows that check verifies that file (coverage 1.0 /
   * naming convention 0.7 / import reachability 0.3).
   */
  private coverWeight(claimFile: string | undefined, evidencePaths: string[]): number {
    let best = matchWeight(claimFile, evidencePaths);
    if (!claimFile || best >= W_EXACT) return best;
    for (const p of evidencePaths) {
      const hit = this.tdm.weightFor(p, claimFile, { importReach: graphImportReach });
      if (hit && hit.weight > best) best = hit.weight;
      if (best >= W_EXACT) break;
    }
    return best;
  }

  private load(): void {
    if (this.loaded) return;
    this.loaded = true;
    try {
      const parsed = JSON.parse(fs.readFileSync(this.filePath, 'utf-8'));
      if (parsed && Array.isArray(parsed.open) && Array.isArray(parsed.buckets) && parsed.buckets.length === 10 && parsed.domains) {
        this.data = {
          version: 2,
          open: parsed.open,
          buckets: parsed.buckets,
          domains: parsed.domains,
          expired: parsed.expired || 0,
          unattributed: parsed.unattributed || 0,
        };
      }
    } catch { /* first run */ }
  }

  private scheduleSave(): void {
    this.dirty = true;
    if (this.saveTimer) return;
    this.saveTimer = setTimeout(() => { this.saveTimer = null; this.saveNow(); }, 1500);
    this.saveTimer.unref?.();
  }

  saveNow(): void {
    if (!this.dirty) return;
    const temporary = `${this.filePath}.${randomUUID()}.tmp`;
    try {
      fs.mkdirSync(path.dirname(this.filePath), { recursive: true });
      fs.writeFileSync(temporary, JSON.stringify(this.data, null, 2), 'utf-8');
      fs.renameSync(temporary, this.filePath);
      this.dirty = false;
    } catch { /* retain dirty state for retry; old complete snapshot remains readable */ }
    finally { try { fs.unlinkSync(temporary); } catch { /* renamed or absent */ } }
  }

  private expire(now: number): void {
    const before = this.data.open.length;
    this.data.open = this.data.open.filter(c => now - c.at <= CLAIM_TTL_MS);
    this.data.expired += before - this.data.open.length;
  }

  /** A mutating tool succeeded — the agent implicitly claims the change is correct. */
  openClaim(domain: string, confidence: number, file?: string): string {
    this.load();
    const now = Date.now();
    this.expire(now);
    const id = randomUUID();
    this.data.open.push({ id, domain, file, confidence: Math.min(1, Math.max(0, confidence)), at: now });
    this.scheduleSave();
    return id;
  }

  /** Immutable launch-time claim identities for delayed evidence. */
  claimSnapshot(): OpenClaim[] {
    this.load();
    return this.data.open.map(claim => ({ ...claim }));
  }

  /** Weighted settlement — a claim resolved by weaker evidence moves the stats less. */
  private settle(claims: { claim: OpenClaim; w: number }[], evidenceOk: boolean): void {
    for (const { claim: c, w } of claims) {
      const bucket = Math.min(9, Math.floor(c.confidence * 10));
      this.data.buckets[bucket].n += w;
      if (evidenceOk) this.data.buckets[bucket].correct += w;
      const d = this.data.domains[c.domain] || (this.data.domains[c.domain] = { n: 0, correct: 0, confSum: 0 });
      d.n += w;
      d.confSum += c.confidence * w;
      if (evidenceOk) d.correct += w;
    }
  }

  /**
   * Hard evidence arrived (build/test run). Resolves only the open claims the evidence
   * COVERS (see module docs). Returns how many claims were settled.
   */
  resolveDetailed(evidenceOk: boolean, opts?: { command?: string; output?: string; claimIds?: readonly string[]; exactFiles?: readonly string[] }): EvidenceResolution {
    this.load();
    const now = Date.now();
    this.expire(now);
    const cmdPaths = commandPathTokens(opts?.command || '');
    // Attested scope is deliberately narrow: it never widens into a repo-wide settle.
    const repoWide = evidenceOk && opts?.exactFiles === undefined && isRepoWideEvidenceCommand(opts?.command || '');
    const inWindow = this.data.open.filter(c => now - c.at <= EVIDENCE_WINDOW_MS
      && (opts?.claimIds === undefined || (!!c.id && opts.claimIds.includes(c.id))));
    if (inWindow.length === 0) return { settled: 0, coveredFiles: [], repoWide };

    // Opportunistic TDM growth: a path-scoped coverage run just PROVED which files that
    // check executes — remember it for every future attribution (v2 §3.4 tier 1).
    try { this.tdm.ingestCoverageRun(opts?.command || ''); } catch { /* best-effort */ }

    let covered: { claim: OpenClaim; w: number }[];

    if (evidenceOk) {
      // Green: a repo-wide run is legitimately global (full weight); a path-scoped run
      // covers only claims whose file it plausibly targets, at the match tier's weight.
      // Attested green: the caller proved which files the run EXECUTED, so only those
      // claims settle — never the command's targets, which express intent, not outcome.
      covered = opts?.exactFiles !== undefined
        ? inWindow.map(c => ({ claim: c, w: c.file && opts.exactFiles!.includes(c.file) ? W_EXACT : 0 })).filter(x => x.w > 0)
        : repoWide
          ? inWindow.map(c => ({ claim: c, w: W_EXACT }))
          : inWindow.map(c => ({ claim: c, w: this.coverWeight(c.file, cmdPaths) })).filter(x => x.w > 0);
    } else {
      // Red: only claims whose file the FAILURE OUTPUT names are refuted. A red run
      // that names no files (or only files nobody claimed) refutes nothing — the
      // failure may predate every open claim, and guessing poisons calibration.
      const failPaths = outputFilePaths(opts?.output || '');
      const scope = failPaths; // A command target is not a file named by the failure.
      if (scope.length === 0) {
        this.data.unattributed++;
        this.scheduleSave();
        return { settled: 0, coveredFiles: [], repoWide: false };
      }
      covered = inWindow.map(c => ({ claim: c, w: opts?.exactFiles !== undefined
        ? (c.file && opts.exactFiles.includes(c.file) ? W_EXACT : 0)
        : this.coverWeight(c.file, scope) })).filter(x => x.w > 0);
      if (covered.length === 0) this.data.unattributed++;
    }

    if (covered.length > 0) {
      const coveredSet = new Set(covered.map(x => x.claim));
      this.data.open = this.data.open.filter(c => !coveredSet.has(c));
      this.settle(covered, evidenceOk);
    }
    this.scheduleSave();
    return {
      settled: covered.length,
      coveredFiles: [...new Set(covered.map(item => item.claim.file).filter((file): file is string => !!file))].sort(),
      repoWide,
    };
  }

  /** Backwards-compatible count-only API used by calibration callers. */
  resolve(evidenceOk: boolean, opts?: { command?: string; output?: string }): number {
    return this.resolveDetailed(evidenceOk, opts).settled;
  }

  /**
   * Domains whose overconfidence is STATISTICALLY significant: stated confidence lies
   * above the Wilson 95% upper bound of observed accuracy. No fixed gap threshold —
   * small samples get wide intervals and simply can't escalate yet (v2 §4.2 in the
   * honest pre-bootstrap form).
   */
  overconfidentDomains(): { domain: string; stated: number; observed: number; n: number }[] {
    this.load();
    const out: { domain: string; stated: number; observed: number; n: number }[] = [];
    for (const [domain, d] of Object.entries(this.data.domains)) {
      if (d.n < MIN_DOMAIN_SAMPLES) continue;
      const stated = d.confSum / d.n;
      const observed = d.correct / d.n;
      if (stated > wilsonInterval(d.correct, d.n).hi) out.push({ domain, stated, observed, n: d.n });
    }
    return out.sort((a, b) => (b.stated - b.observed) - (a.stated - a.observed));
  }

  /** Global weighted ECE over the decile bins — the one-number calibration summary. */
  ece(): number {
    this.load();
    return expectedCalibrationError(
      this.data.buckets
        .map((b, i) => ({ conf: i / 10 + 0.05, acc: b.n > 0 ? b.correct / b.n : 0, w: b.n }))
        .filter(b => b.w > 0)
    );
  }

  /** Monotone reliability curve (PAV isotonic fit over the decile bins). */
  isotonicCurve(): { stated: number; corrected: number }[] {
    this.load();
    const pts = this.data.buckets
      .map((b, i) => ({ x: i / 10 + 0.05, y: b.n > 0 ? b.correct / b.n : 0, w: b.n }))
      .filter(p => p.w > 0);
    return isotonicFit(pts).map(p => ({ stated: p.x, corrected: p.yhat }));
  }

  /** Escalation rule for the prompt — only when there's a real calibration gap. */
  getPromptBlock(): string {
    const over = this.overconfidentDomains().slice(0, 3);
    if (over.length === 0) return '';
    const lines = over.map(o =>
      `- \`${o.domain}\`: you claim ${Math.round(o.stated * 100)}% confidence but are right only ${Math.round(o.observed * 100)}% of the time (n=${Math.round(o.n * 10) / 10}, significant at 95%). In this domain, ALWAYS run the build/tests before declaring a change done.`
    );
    return `### CALIBRATION (your measured overconfidence — escalate verification)\n${lines.join('\n')}`;
  }

  /** Aggregate counters — feeds the verification-coverage drive and /self. */
  stats(): { resolved: number; expired: number; open: number; unattributed: number } {
    this.load();
    return {
      resolved: this.data.buckets.reduce((a, b) => a + b.n, 0),
      expired: this.data.expired,
      open: this.data.open.length,
      unattributed: this.data.unattributed,
    };
  }

  /** Calibration curve rows for /self — stated-confidence decile vs. observed accuracy. */
  calibration(): { range: string; n: number; observed: number }[] {
    this.load();
    return this.data.buckets
      .map((b, i) => ({ range: `${i * 10}–${i * 10 + 10}%`, n: b.n, observed: b.n > 0 ? b.correct / b.n : 0 }))
      .filter(r => r.n > 0);
  }

  report(): string[] {
    this.load();
    const rows = this.calibration();
    const totalResolved = rows.reduce((a, r) => a + r.n, 0);
    if (totalResolved === 0 && this.data.expired === 0) {
      return ['- No resolved claims yet — claims open on edits and resolve when a build/test run names (or clears) the touched files.'];
    }
    const lines = [`- Resolved (weighted): ${Math.round(totalResolved * 10) / 10} · open: ${this.data.open.length} · expired unverified: ${this.data.expired} · unattributed red evidence: ${this.data.unattributed}`];
    if (totalResolved > 0) {
      lines.push(`- ECE ${Math.round(this.ece() * 100)}% (weighted decile bins, isotonic-monotone curve below)`);
    }
    const verified = totalResolved + this.data.expired > 0
      ? Math.round((totalResolved / (totalResolved + this.data.expired)) * 100)
      : 0;
    if (this.data.expired > 0) {
      lines.push(`- Verification coverage: ${verified}% of claims ever met evidence — the rest is work nothing checks.`);
    }
    for (const r of rows) {
      lines.push(`  · stated ${r.range}: observed ${Math.round(r.observed * 100)}% correct (n=${Math.round(r.n * 10) / 10})`);
    }
    const over = this.overconfidentDomains();
    if (over.length > 0) {
      lines.push(`- ⚠ Overconfident in: ${over.map(o => `${o.domain} (${Math.round(o.stated * 100)}%→${Math.round(o.observed * 100)}%)`).join(', ')} — verification escalated.`);
    } else if (totalResolved > 0) {
      lines.push('- Calibration healthy — no domain shows an overconfidence gap.');
    }
    return lines;
  }
}

let _global: EpistemicLedger | null = null;
export function getEpistemicLedger(): EpistemicLedger {
  if (!_global) {
    _global = new EpistemicLedger(mindSingletonRoot());
    process.once('exit', () => { try { _global?.saveNow(); } catch { /* exiting */ } });
  }
  return _global;
}
export function __setEpistemicLedger(l: EpistemicLedger | null): void { _global = l; }

import { stateDir } from '../utils/state.dir';
import * as fs from 'fs';
import * as path from 'path';
import * as crypto from 'crypto';
import { mindSingletonRoot } from './self.model';
import { openSqlite } from '../core/sqlite';

/**
 * The Event Ledger (BiMax v2, D1 — minimal variant).
 *
 * One append-only, hash-chained event log per repo, on SQLite/WAL. This is the single
 * source of truth the mind layer's JSON "databases" will become materialized views of:
 * every learning-relevant fact (tool outcomes with their typed labels, evidence runs,
 * dream episodes) lands here first, immutably, so learned state can be rebuilt, audited,
 * and rolled back instead of trusted blindly.
 *
 * Deliberately the self-critique-blessed variant: NO daemon. A session writes directly
 * with an IMMEDIATE transaction per append (SQLite handles one writer fine; a second
 * concurrent session just retries past a short busy timeout). Uses node:sqlite in Node and
 * bun:sqlite in the compiled desktop engine, both with zero new dependencies. Where neither is
 * available the ledger degrades to a silent no-op: recording must never break the agent.
 *
 * Append-only is enforced by construction (this module exposes no update/delete) and
 * made TAMPER-EVIDENT by a hash chain: each event's hash covers its content plus the
 * previous event's hash, so any retroactive edit breaks verification from that point on.
 */

export interface LedgerEvent {
  id: number;
  ts: number;
  session: string;
  type: string;
  payload: any;
  hash: string;
}

// One stable id per process — enough to attribute events to a session in the log.
const SESSION_ID = `${process.pid}-${Date.now().toString(36)}`;

export class EventLedger {
  private db: any | null = null;
  private available = false;

  constructor(projectRoot: string) {
    try {
      // Tolerant open: node:sqlite (dev/CI) OR bun:sqlite (the packaged bun --compile engine).
      // Absence of both must leave a working (no-op) ledger, never a crashed agent.
      const dir = stateDir('.bimax', projectRoot);
      fs.mkdirSync(dir, { recursive: true });
      this.db = openSqlite(path.join(dir, 'ledger.db'));
      if (!this.db) throw new Error('no SQLite backend (node:sqlite / bun:sqlite) on this runtime');
      this.db.exec('PRAGMA journal_mode = WAL');
      this.db.exec('PRAGMA busy_timeout = 3000');
      this.db.exec(
        'CREATE TABLE IF NOT EXISTS events (' +
        ' id INTEGER PRIMARY KEY AUTOINCREMENT,' +
        ' ts INTEGER NOT NULL,' +
        ' session TEXT NOT NULL,' +
        ' type TEXT NOT NULL,' +
        ' payload TEXT NOT NULL,' +
        ' hash TEXT NOT NULL)'
      );
      this.db.exec('CREATE INDEX IF NOT EXISTS idx_events_type ON events(type, id)');
      this.available = true;
    } catch {
      this.db = null;
      this.available = false;
    }
  }

  isAvailable(): boolean { return this.available; }

  /** Append one event. Never throws — recording is strictly best-effort. */
  append(type: string, payload: Record<string, any>): void {
    if (!this.available || !this.db) return;
    try {
      const ts = Date.now();
      const body = JSON.stringify(payload);
      // IMMEDIATE: take the write lock up front so a concurrent session fails fast into
      // the busy timeout instead of deadlocking mid-transaction. The previous hash MUST
      // be read inside the lock — a cached one goes stale the moment another session
      // appends, silently breaking the chain.
      this.db.exec('BEGIN IMMEDIATE');
      try {
        const prev = this.db.prepare('SELECT hash FROM events ORDER BY id DESC LIMIT 1').get()?.hash || '';
        const hash = crypto.createHash('sha256')
          .update(`${prev}|${ts}|${SESSION_ID}|${type}|${body}`)
          .digest('hex');
        this.db.prepare('INSERT INTO events (ts, session, type, payload, hash) VALUES (?, ?, ?, ?, ?)')
          .run(ts, SESSION_ID, type, body, hash);
        this.db.exec('COMMIT');
      } catch (e) {
        try { this.db.exec('ROLLBACK'); } catch { /* already rolled back */ }
        throw e;
      }
    } catch { /* best-effort */ }
  }

  count(): number {
    if (!this.available || !this.db) return 0;
    try { return Number(this.db.prepare('SELECT COUNT(*) AS n FROM events').get()?.n || 0); }
    catch { return 0; }
  }

  countByType(): Record<string, number> {
    if (!this.available || !this.db) return {};
    try {
      const rows = this.db.prepare('SELECT type, COUNT(*) AS n FROM events GROUP BY type ORDER BY n DESC').all();
      const out: Record<string, number> = {};
      for (const r of rows) out[String(r.type)] = Number(r.n);
      return out;
    } catch { return {}; }
  }

  /** All events of one type, oldest first — the input stream for view rebuilds. */
  byType(type: string, limit = 100_000): LedgerEvent[] {
    if (!this.available || !this.db) return [];
    try {
      const rows = this.db.prepare('SELECT * FROM events WHERE type = ? ORDER BY id ASC LIMIT ?').all(type, limit);
      return rows.map((r: any) => ({
        id: Number(r.id), ts: Number(r.ts), session: String(r.session), type: String(r.type),
        payload: JSON.parse(String(r.payload)), hash: String(r.hash),
      }));
    } catch { return []; }
  }

  /** Every event oldest-first — the input for folds that need cross-type ordering. */
  all(limit = 200_000): LedgerEvent[] {
    if (!this.available || !this.db) return [];
    try {
      const rows = this.db.prepare('SELECT * FROM events ORDER BY id ASC LIMIT ?').all(limit);
      return rows.map((r: any) => ({
        id: Number(r.id), ts: Number(r.ts), session: String(r.session), type: String(r.type),
        payload: JSON.parse(String(r.payload)), hash: String(r.hash),
      }));
    } catch { return []; }
  }

  tail(limit = 20): LedgerEvent[] {
    if (!this.available || !this.db) return [];
    try {
      const rows = this.db.prepare('SELECT * FROM events ORDER BY id DESC LIMIT ?').all(limit);
      return rows.reverse().map((r: any) => ({
        id: Number(r.id), ts: Number(r.ts), session: String(r.session), type: String(r.type),
        payload: JSON.parse(String(r.payload)), hash: String(r.hash),
      }));
    } catch { return []; }
  }

  /**
   * Recompute the hash chain over the whole log. Returns the first broken event id, or
   * null when the chain is intact — the audit primitive every view rebuild can trust.
   */
  verifyChain(): { ok: boolean; events: number; brokenAt: number | null } {
    if (!this.available || !this.db) return { ok: true, events: 0, brokenAt: null };
    try {
      const rows = this.db.prepare('SELECT id, ts, session, type, payload, hash FROM events ORDER BY id ASC').all();
      let prev = '';
      for (const r of rows) {
        const expect = crypto.createHash('sha256')
          .update(`${prev}|${r.ts}|${r.session}|${r.type}|${r.payload}`)
          .digest('hex');
        if (expect !== String(r.hash)) return { ok: false, events: rows.length, brokenAt: Number(r.id) };
        prev = String(r.hash);
      }
      return { ok: true, events: rows.length, brokenAt: null };
    } catch { return { ok: true, events: 0, brokenAt: null }; }
  }

  close(): void {
    try { this.db?.close(); } catch { /* closing */ }
    this.db = null;
    this.available = false;
  }
}

let _global: EventLedger | null = null;
export function getEventLedger(): EventLedger {
  if (!_global) _global = new EventLedger(mindSingletonRoot());
  return _global;
}
/** Test hook — swap the singleton (tests that seed episodes need per-test isolation). */
export function __setEventLedger(l: EventLedger | null): void {
  if (_global && _global !== l) { try { _global.close(); } catch { /* already closed */ } }
  _global = l;
}

import { stateDir } from '../utils/state.dir';
import * as fs from 'fs';
import * as path from 'path';
import * as crypto from 'crypto';
import { getEventLedger } from './event.ledger';
import { getTracer } from '../telemetry/trace';
import { Logger } from '../utils/logger';

/**
 * Counterfactual Harness Lab — experiment model + store (INFRA P4 #10).
 *
 * A proposed harness patch is no longer judged on live traffic first: it becomes a
 * counterfactual EXPERIMENT evaluated offline against recorded episodes (see
 * harness.lab.eval.ts) before it may inject a single live prompt token. This module owns
 * the durable half: the typed experiment record (immutable candidate identity, cohort
 * manifest + hash, paired per-episode results, gate evidence, verdict), its lifecycle,
 * and the on-disk store under .bimax/harness-lab/.
 *
 * Design invariants:
 *   - Experiment id is DERIVED from the candidate's content (tool|errorClass|rule), so
 *     concurrent sessions creating "the same" experiment converge on one file instead of
 *     duplicating — idempotency by construction, no lock daemon.
 *   - One JSON file per experiment, written atomically (tmp + rename). A corrupt file is
 *     quarantined (renamed aside, ledger-audited), never silently deleted or trusted.
 *   - Every lifecycle transition is guarded (illegal moves refused) and lands in the
 *     event ledger + trace layer, so create→evaluate→verdict→activate/reject/rollback is
 *     auditable end to end.
 *   - Artifacts store hashes, counts, and gate evidence — never raw episode content or
 *     recorded prompts (episodes already live in .bimax/episodes/; no second copy).
 */

// ---------------------------------------------------------------------------
// Typed experiment model
// ---------------------------------------------------------------------------

export type LabVerdict = 'pass' | 'insufficient_evidence' | 'veto';

export type ExperimentStatus =
  | 'pending'      // created, no evaluation yet
  | 'evaluated'    // has ≥1 evaluation; latest verdict did not activate or veto
  | 'activated'    // candidate went live (lab pass or manual approval)
  | 'rejected'     // candidate refused (gate veto or manual) — terminal
  | 'rolled_back'; // was activated, then reverted — terminal

/** Immutable identity of the steering change under test. */
export interface LabCandidate {
  /** HarnessPatch id this candidate came from (audit link; not part of identity). */
  patchId: string;
  tool: string;
  errorClass: string;
  rule: string;
  /** The exact system-prompt block the candidate arm appends (renderHarnessBlock([rule])). */
  promptBlock: string;
  /** sha256 of promptBlock — the candidate arm's identity. */
  blockHash: string;
}

export interface CohortEpisodeRef {
  id: string;
  file: string;
  startedAt: number;
  calls: number;
  /** sha256 of the bundle file bytes — pins the exact recording the experiment saw. */
  contentHash: string;
  /** Episode actually calls the candidate's target tool (carries effect signal). */
  signalBearing: boolean;
}

export interface CohortSkip { id: string; reason: string }

export interface CohortManifest {
  selectedAt: number;
  criteria: { limit: number; minCalls: number };
  episodes: CohortEpisodeRef[];
  /** Every considered-but-excluded episode with its reason — nothing is skipped silently. */
  skipped: CohortSkip[];
  /** sha256 over the ordered episode content hashes — the cohort's identity. */
  cohortHash: string;
}

/** One arm's hermetic replay outcome for one episode. */
export interface ArmReplayResult {
  /** The loop finished on recorded data (no crash, no unrecoverable replay error). */
  completed: boolean;
  /** Bit-for-bit trajectory match with the recording (baseline requirement). */
  identical: boolean;
  callsRecorded: number;
  callsServed: number;
  divergences: number;
  firstDivergence: number | null;
  toolResultsMissing: number;
  /** sha256(finalText) — lets pairs compare outputs without persisting transcript text. */
  finalTextHash: string;
  error?: string;
}

/** Recorded-failure census for one episode (ledger-correlated, typed outcomes). */
export interface EpisodeCensus {
  /** False when the ledger anchor for this episode is missing — evidence unavailable. */
  available: boolean;
  targetToolCalls: number;
  /** Failures on the target tool matching the candidate's errorClass. */
  targetHits: number;
  otherToolFailures: number;
}

export interface EpisodePairResult {
  episodeId: string;
  signalBearing: boolean;
  baseline: ArmReplayResult;
  candidate: ArmReplayResult;
  census: EpisodeCensus;
  /** Baseline replayed bit-for-bit — only then is the pair a valid instrument. */
  usable: boolean;
  excludedReason?: string;
}

export interface GateResult {
  gate: string;
  pass: boolean;
  /** 'measured' = computed from recorded data; 'proxy' = an honest stand-in, labeled. */
  basis: 'measured' | 'proxy';
  detail: string;
  /** Failing a veto gate is terminal for the candidate (retire), not just "wait for data". */
  veto: boolean;
}

export interface LabEvaluation {
  /** ev-<sha256(blockHash|cohortHash)> — deterministic: same candidate × cohort ⇒ same id. */
  id: string;
  at: number;
  backend: string;
  cohort: CohortManifest;
  pairs: EpisodePairResult[];
  aggregate: {
    episodesSelected: number;
    episodesUsable: number;
    signalEpisodes: number;
    censusEpisodes: number;
    targetToolCalls: number;
    targetHits: number;
    targetFailureRate: { point: number; wilsonLo: number; wilsonHi: number } | null;
    /** Fraction of usable pairs whose candidate arm completed cleanly (must be 1). */
    candidateCompletion: number;
    promptCostChars: number;
    approxPromptCostTokens: number;
  };
  gates: GateResult[];
  verdict: LabVerdict;
  vetoReasons: string[];
  confidence: 'high' | 'moderate' | 'low';
  /** Honesty rail: caveats + the measured-vs-inferred boundary, rendered by /harness lab explain. */
  notes: string[];
}

export interface ExperimentTransition {
  at: number;
  from: ExperimentStatus | null;
  to: ExperimentStatus;
  reason?: string;
  by: 'auto' | 'user';
}

export interface Experiment {
  v: 1;
  id: string;
  status: ExperimentStatus;
  createdAt: number;
  updatedAt: number;
  candidate: LabCandidate;
  /** The control arm is each episode's own recorded prompt — pinned by the cohort manifest. */
  baseline: { kind: 'recorded-episodes'; description: string };
  /** Append-only evaluation history; the latest entry governs status decisions. */
  evaluations: LabEvaluation[];
  statusReason?: string;
  transitions: ExperimentTransition[];
}

// ---------------------------------------------------------------------------
// Identity + rendering helpers (shared with the tuner — no tuner import, no cycle)
// ---------------------------------------------------------------------------

const BLOCK_HEADER =
  '### HARNESS PATCHES (self-tuned — mined from YOUR OWN recent failures; each is auto-retired if it stops helping)';

/** The one place the live prompt block is rendered — tuner and lab share it byte-for-byte. */
export function renderHarnessBlock(rules: string[]): string {
  if (rules.length === 0) return '';
  return `${BLOCK_HEADER}\n${rules.map(r => `- ${r}`).join('\n')}`;
}

export function sha256(text: string): string {
  return crypto.createHash('sha256').update(text).digest('hex');
}

/** Deterministic experiment id from candidate content — same candidate ⇒ same experiment. */
export function experimentIdFor(c: { tool: string; errorClass: string; rule: string }): string {
  return `cx-${sha256(`${c.tool}|${c.errorClass}|${c.rule}`).slice(0, 12)}`;
}

export function candidateFrom(p: { id: string; tool: string; errorClass: string; rule: string }): LabCandidate {
  const promptBlock = renderHarnessBlock([p.rule]);
  return {
    patchId: p.id,
    tool: p.tool,
    errorClass: p.errorClass,
    rule: p.rule,
    promptBlock,
    blockHash: sha256(promptBlock),
  };
}

/** The lab gate is on by default; BIMAX_HARNESS_LAB=0 restores legacy immediate activation. */
export function labEnabled(): boolean {
  return process.env.BIMAX_HARNESS_LAB !== '0';
}

// ---------------------------------------------------------------------------
// Ledger + trace plumbing — every lab action is auditable and correlatable
// ---------------------------------------------------------------------------

export function labEvent(action: string, fields: Record<string, any>): void {
  try { getEventLedger().append('harness_lab', { action, ...fields }); } catch { /* best-effort */ }
}

// ---------------------------------------------------------------------------
// Store
// ---------------------------------------------------------------------------

const TERMINAL: ReadonlySet<ExperimentStatus> = new Set(['rejected', 'rolled_back']);
const LEGAL_MOVES: Record<ExperimentStatus, ExperimentStatus[]> = {
  pending: ['evaluated', 'activated', 'rejected'],
  evaluated: ['evaluated', 'activated', 'rejected'],
  activated: ['rolled_back'],
  rejected: [],
  rolled_back: [],
};
const EXPERIMENTS_KEPT = 50; // terminal experiments pruned beyond this (oldest first)

export class HarnessLabStore {
  constructor(private root: string) {}

  dir(): string {
    return path.join(stateDir('.bimax', this.root), 'harness-lab');
  }

  private fileFor(id: string): string {
    return path.join(this.dir(), `${id}.json`);
  }

  /** Atomic write: no reader ever observes a half-written experiment. */
  private write(exp: Experiment): void {
    fs.mkdirSync(this.dir(), { recursive: true });
    const file = this.fileFor(exp.id);
    const tmp = `${file}.tmp-${process.pid}-${crypto.randomBytes(3).toString('hex')}`;
    fs.writeFileSync(tmp, JSON.stringify(exp, null, 2), 'utf-8');
    fs.renameSync(tmp, file);
  }

  /**
   * Load one experiment file; a corrupt/incompatible one is QUARANTINED (renamed aside,
   * ledger-audited) so the store recovers instead of crashing or silently trusting it.
   */
  private read(file: string): Experiment | null {
    let raw: string;
    try { raw = fs.readFileSync(file, 'utf-8'); } catch { return null; }
    try {
      const exp = JSON.parse(raw);
      if (exp?.v !== 1 || typeof exp.id !== 'string' || !exp.candidate || !Array.isArray(exp.evaluations)) {
        throw new Error('unrecognized experiment shape');
      }
      return exp as Experiment;
    } catch (e: any) {
      const quarantined = `${file}.corrupt-${Date.now().toString(36)}`;
      try { fs.renameSync(file, quarantined); } catch { /* leave in place if rename fails */ }
      Logger.warn(`[HarnessLab] Quarantined corrupt experiment file ${path.basename(file)} (${e?.message}).`);
      labEvent('recovered', { file: path.basename(file), quarantined: path.basename(quarantined), error: String(e?.message || e).slice(0, 200) });
      return null;
    }
  }

  list(): Experiment[] {
    let files: string[];
    try { files = fs.readdirSync(this.dir()).filter(f => f.startsWith('cx-') && f.endsWith('.json')); } catch { return []; }
    const out: Experiment[] = [];
    for (const f of files.sort()) {
      const exp = this.read(path.join(this.dir(), f));
      if (exp) out.push(exp);
    }
    return out.sort((a, b) => b.updatedAt - a.updatedAt || a.id.localeCompare(b.id));
  }

  get(id: string): Experiment | null {
    return this.read(this.fileFor(id));
  }

  /**
   * Create-or-load, idempotent: the id is content-derived, so two racing sessions write
   * the same initial record to the same file — the race collapses into one experiment.
   */
  getOrCreate(candidate: LabCandidate): { exp: Experiment; created: boolean } {
    const id = experimentIdFor(candidate);
    const existing = this.get(id);
    if (existing) return { exp: existing, created: false };
    const now = Date.now();
    const exp: Experiment = {
      v: 1,
      id,
      status: 'pending',
      createdAt: now,
      updatedAt: now,
      candidate,
      baseline: {
        kind: 'recorded-episodes',
        description: 'each cohort episode replayed under its own recorded system prompt (paired control)',
      },
      evaluations: [],
      transitions: [{ at: now, from: null, to: 'pending', by: 'auto', reason: 'staged by HarnessTuner' }],
    };
    this.write(exp);
    labEvent('created', { expId: id, patchId: candidate.patchId, tool: candidate.tool, errorClass: candidate.errorClass });
    getTracer().startSpan('harness.lab.create', { expId: id, tool: candidate.tool, errorClass: candidate.errorClass }).end();
    this.prune();
    return { exp, created: true };
  }

  /** Append one evaluation (dedup by deterministic evaluation id) and mark 'evaluated'. */
  appendEvaluation(id: string, ev: LabEvaluation): Experiment | null {
    const exp = this.get(id);
    if (!exp || TERMINAL.has(exp.status)) return null;
    if (!exp.evaluations.some(e => e.id === ev.id)) exp.evaluations.push(ev);
    if (exp.status !== 'activated') {
      this.recordTransition(exp, 'evaluated', `verdict: ${ev.verdict}`, 'auto');
    }
    exp.updatedAt = Date.now();
    this.write(exp);
    labEvent('evaluated', {
      expId: id, evaluationId: ev.id, verdict: ev.verdict, cohortHash: ev.cohort.cohortHash,
      episodes: ev.cohort.episodes.length, usable: ev.aggregate.episodesUsable, confidence: ev.confidence,
    });
    return exp;
  }

  /** Guarded lifecycle move; illegal transitions are refused, never silently applied. */
  transition(id: string, to: ExperimentStatus, reason: string, by: 'auto' | 'user'): Experiment | null {
    const exp = this.get(id);
    if (!exp) return null;
    if (!LEGAL_MOVES[exp.status]?.includes(to)) return null;
    this.recordTransition(exp, to, reason, by);
    exp.updatedAt = Date.now();
    this.write(exp);
    labEvent(to, { expId: id, reason, by });
    return exp;
  }

  private recordTransition(exp: Experiment, to: ExperimentStatus, reason: string, by: 'auto' | 'user'): void {
    if (exp.status === to && to !== 'evaluated') return;
    exp.transitions.push({ at: Date.now(), from: exp.status, to, reason, by });
    exp.status = to;
    exp.statusReason = reason;
  }

  /** Keep the artifact directory bounded: terminal experiments beyond the cap age out. */
  private prune(keep = EXPERIMENTS_KEPT): void {
    try {
      const all = this.list();
      const terminal = all.filter(e => TERMINAL.has(e.status)).sort((a, b) => a.updatedAt - b.updatedAt);
      const excess = all.length - keep;
      for (const e of terminal.slice(0, Math.max(0, excess))) {
        fs.unlinkSync(this.fileFor(e.id));
      }
    } catch { /* best-effort */ }
  }

  /**
   * Advisory cross-process evaluation lock (O_EXCL create; stale after TTL, dead-PID
   * pruned like file claims). Prevents two sessions from duplicating the same replay
   * work — correctness never depends on it, since evaluations are deterministic and
   * idempotent by id.
   */
  acquireEvalLock(ttlMs = 5 * 60_000): (() => void) | null {
    const lockFile = path.join(this.dir(), '.eval.lock');
    try {
      fs.mkdirSync(this.dir(), { recursive: true });
      try {
        const raw = fs.readFileSync(lockFile, 'utf-8'); // ENOENT ⇒ no lock, skip to acquire
        let stale = true; // unparseable lock counts as stale — it must never wedge the lab
        try {
          const prev = JSON.parse(raw);
          const fresh = Date.now() - Number(prev?.at || 0) <= ttlMs;
          let alive = false;
          try { process.kill(Number(prev?.pid), 0); alive = true; } catch { alive = false; }
          stale = !fresh || !alive;
        } catch { stale = true; }
        if (stale) fs.unlinkSync(lockFile);
      } catch { /* no lock file */ }
      fs.writeFileSync(lockFile, JSON.stringify({ pid: process.pid, at: Date.now() }), { flag: 'wx' });
      return () => { try { fs.unlinkSync(lockFile); } catch { /* released elsewhere */ } };
    } catch {
      return null; // held by a live process — skip this pass, next boundary retries
    }
  }
}

/**
 * Reproducible LIVE tool/sensor proof, not a model-quality evaluation or trace miner.
 * Usage: bun src/mind/learning.proof.ts <new-artifact-directory>
 * The provider scripts actions; actual tools edit disk and run the Node test runner.
 */
import * as fs from 'fs';
import * as path from 'path';
import * as crypto from 'crypto';
import * as assert from 'assert';
import { execFileSync } from 'child_process';
import type { ChatEvent, LLMProvider } from '../core/llm.provider';

async function main() {
  const requested = process.argv[2];
  if (!requested) throw new Error('Usage: bun src/mind/learning.proof.ts <new-artifact-directory>');
  const artifact = path.resolve(requested);
  fs.mkdirSync(artifact); // fresh state or fail; never reuse a prior proof's observations
  const root = path.join(artifact, 'workspace');
  fs.mkdirSync(path.join(root, 'src'), { recursive: true });
  execFileSync('git', ['init', '--quiet', root]);
  process.chdir(root);
  process.env.BIMAX_BREAKGLASS_DIR = path.join(artifact, 'config');
  process.env.BIMAX_TRACE_DIR = path.join(root, '.bimax', 'traces');
  process.env.BIMAX_TRACE = '1';
  process.env.BIMAX_RECORDER = '1';
  delete process.env.BIMAX_OTLP_ENDPOINT;
  delete process.env.OTEL_EXPORTER_OTLP_ENDPOINT;

  const { AgentLoop } = await import('../core/agent.loop');
  const { ToolRegistry } = await import('../tools/tool.registry');
  const { createWriteFileTool } = await import('../tools/implementations/file.tool');
  const { createBashTool } = await import('../tools/implementations/bash.tool');
  const { getEpistemicLedger } = await import('./epistemic.ledger');
  const { getEventLedger } = await import('./event.ledger');
  const { shutdownTracer } = await import('../telemetry/trace');
  const { attributeTrace } = await import('./trace.attribution');
  const { CLAIM_TTL_MS } = await import('./epistemic.ledger');
  const { mindSingletonRoot } = await import('./self.model');
  assert.strictEqual(mindSingletonRoot(), root, 'learning must be isolated to this workspace');

  const file = 'src/claim.test.js';
  const initial = "const { test } = require('node:test');\nconst assert = require('node:assert/strict');\ntest('addition', () => assert.equal(1 + 1, 2));\n";
  const changed = initial.replace('1 + 1, 2', '1 + 1, 3');
  fs.writeFileSync(file, initial);
  fs.writeFileSync(path.join(artifact, 'before.js'), initial);
  const command = `node --test --test-reporter=tap ${file}`;
  const noFiles = `node --test --bimax-invalid-option ${file}`;
  const governor = {
    async approveTaskExecution(kind: string, payload: { path?: string; command?: string }) {
      if (kind === 'FILE_WRITE' && path.resolve(payload.path || '') === path.join(root, file)) return;
      if (kind === 'OS_COMMAND' && (payload.command === command || payload.command === noFiles)) return;
      throw new Error(`Proof governor refused unexpected operation: ${kind}`);
    },
  };
  const registry = new ToolRegistry();
  registry.register(createWriteFileTool(governor));
  registry.register(createBashTool(governor));
  const actions = [
    { name: 'BashTool', args: { command } }, // actual passing baseline, no claims yet
    { name: 'WriteFileTool', args: { path: file, content: changed } },
    { name: 'BashTool', args: { command: noFiles } }, // red, names no files; cannot refute
    { name: 'BashTool', args: { command } }, // actual assertion failure names the changed file
  ];
  const states: ReturnType<ReturnType<typeof getEpistemicLedger>['stats']>[] = [];
  let round = 0;
  const provider: LLMProvider = {
    async *chat(): AsyncGenerator<ChatEvent> {
      states.push(getEpistemicLedger().stats());
      const action = actions[round++];
      if (action) yield { type: 'tool_call', id: `proof-${round}`, name: action.name, args: JSON.stringify(action.args) };
      else yield { type: 'token', text: 'Finished the prescribed real-tool sensor proof.' };
      yield { type: 'done' };
    },
  };
  try {
    const loop = new AgentLoop(provider, registry);
    for await (const _ of loop.execute([{ role: 'user', content: 'Run the prescribed isolated sensor proof.' }],
      'Deterministic tool-path proof; no model inference.', { maxIterations: actions.length + 1 }, { cwd: root })) { /* drain */ }
    getEpistemicLedger().saveNow();
    await shutdownTracer();
    const events = getEventLedger().all();
    const chain = getEventLedger().verifyChain();
    fs.writeFileSync(path.join(artifact, 'events.json'), JSON.stringify(events, null, 2));
    fs.writeFileSync(path.join(artifact, 'states.json'), JSON.stringify(states, null, 2));
    const spans = fs.readdirSync(process.env.BIMAX_TRACE_DIR!).filter(f => f.endsWith('.jsonl'))
      .flatMap(f => fs.readFileSync(path.join(process.env.BIMAX_TRACE_DIR!, f), 'utf8').trim().split('\n').filter(Boolean).map(l => JSON.parse(l)));
    const attribution = attributeTrace(spans, Date.now(), CLAIM_TTL_MS);
    fs.writeFileSync(path.join(artifact, 'attribution.json'), JSON.stringify(attribution, null, 2));
    fs.writeFileSync(path.join(artifact, 'spans.jsonl'), spans.map(s => JSON.stringify(s)).join('\n') + '\n');
    const saved = JSON.parse(fs.readFileSync(path.join(root, '.bimax', 'epistemic.json'), 'utf8'));
    const claims = events.filter(e => e.type === 'claim');
    const evidence = events.filter(e => e.type === 'evidence');
    const named = evidence.find(e => e.payload.settled > 0);
    const refusal = evidence.find(e => e.payload.command === noFiles);
    assert.strictEqual(fs.readFileSync(file, 'utf8'), changed, 'real edit did not land');
    assert.strictEqual(claims.length, 1, 'exactly one real mutation must mint a claim');
    assert.strictEqual(claims[0].payload.after.open, 1);
    assert.strictEqual(refusal?.payload.ok, false);
    assert.deepStrictEqual(refusal?.payload.outputFiles, []);
    assert.strictEqual(refusal?.payload.settled, 0);
    assert.strictEqual(refusal?.payload.after.open, 1);
    assert.strictEqual(named?.payload.ok, false);
    assert.strictEqual(named?.payload.settled, 1);
    assert.strictEqual(named?.payload.after.open, 0);
    assert.strictEqual(named?.payload.after.resolved, 1);
    assert.deepStrictEqual(named?.payload.outputFiles.includes(file), true);
    assert.strictEqual(saved.open.length, 0);
    assert.strictEqual(saved.buckets.reduce((n: number, b: { n: number }) => n + b.n, 0), 1);
    const attributed = attribution.operations.filter(o => o.attribution === 'scoped-verification');
    assert.strictEqual(attributed.length, 1);
    assert.strictEqual(attributed[0].claim, 'refuted');
    assert.strictEqual(attributed[0].spanId, claims[0].payload.spanId);
    assert.strictEqual(attributed[0].evidenceSpanId, named?.payload.spanId);
    assert.ok(chain.ok && chain.events > 0);
    const summary = {
      property: 'real edit -> durable open claim -> no-file refusal -> actual named test failure -> durable refutation',
      source: 'scripted action selection; real AgentLoop, WriteFileTool, BashTool, Node test process and SQLite',
      modelInference: false, states, claimEventId: claims[0].id, evidenceEventId: named!.id,
      noFileEvidenceEventId: refusal!.id, chain,
      claims: { minted: claims.length, resolved: attributed.length, attributionFraction: attributed.length / claims.length },
      spans: { count: spans.length, attributed: attributed.length, attributionFraction: attributed.length / spans.length },
      fileBeforeSha256: crypto.createHash('sha256').update(initial).digest('hex'),
      fileAfterSha256: crypto.createHash('sha256').update(changed).digest('hex'),
      calibration: { ece: getEpistemicLedger().ece(), curve: getEpistemicLedger().isotonicCurve(), samples: 1 },
      limits: ['One deterministic real-tool trace, not model quality or a policy holdout experiment.',
        'Green diagnostic mention is not accepted for trace verification; background completions are not instrumented.'],
    };
    fs.writeFileSync(path.join(artifact, 'summary.json'), JSON.stringify(summary, null, 2) + '\n');
    console.log(JSON.stringify(summary, null, 2));
  } finally {
    getEpistemicLedger().saveNow();
    await shutdownTracer();
    getEventLedger().close();
  }
}
main().catch(error => { console.error(error); process.exitCode = 1; });

import { stateDir } from '../utils/state.dir';
import * as fs from 'fs';
import * as path from 'path';
import { mindSingletonRoot } from './self.model';
import { getEventLedger, EventLedger } from './event.ledger';
import { wilsonInterval } from './stats';

/**
 * Policy arms (v2 §4.4) — every learned prompt intervention becomes an ARM whose effect
 * is measurable from the ledger instead of assumed.
 *
 * The mechanism the whole plan leans on: when a mind block (self-model hints, habits,
 * user model, drives, calibration escalation, exemplars) is about to enter the prompt,
 * the arm DECIDES (show / hold out) and the decision is logged as a `policy_active`
 * event WITH ITS PROPENSITY. Active arms show with P = 1 − holdout; shadow arms never
 * show but still log what they would have said. Rewards are folded from the ledger per
 * episode (boundary-to-boundary tool-outcome success), and self-normalized IPS gives the
 * off-policy answer — "does showing this block make episodes go better?" — from
 * historical traffic, at zero token cost.
 *
 * The holdout defaults to ZERO: arms always show. A randomized holdout is the price of
 * ever knowing the counterfactual, but it is only worth paying once something reads the
 * estimate. Measured 2026-09-09: no project had accumulated a single scored episode, so
 * every held-out turn degraded its own prompt to buy information nothing consumed —
 * strictly worse than not randomizing. Set BIMAX_POLICY_HOLDOUT (e.g. 0.1) to resume
 * buying counterfactuals when episodes are actually accruing and the estimate is read.
 *
 * Honest scope: reward = episode tool-success ratio ≥ 0.8 (a proxy the ledger can
 * compute today; verified-claim reward joins when TDM coverage deepens), and demotion
 * is surfaced as evidence in `/arms` rather than auto-flipped — the human stays in the
 * loop until the estimator has history behind it.
 */

export const ARM_IDS = ['self-knowledge', 'habits', 'user-model', 'drives', 'calibration', 'exemplars', 'journal'] as const;
export type ArmId = typeof ARM_IDS[number];

const DEFAULT_HOLDOUT = 0;     // arms always show — the counterfactual budget is not spent
                               // while nothing reads the estimate (see the module doc)
const REWARD_OK_RATIO = 0.8;   // an episode "went well" when ≥80% of its tool calls succeeded
const MIN_EPISODE_TOOLS = 2;   // fewer tool calls than this = no signal, episode skipped

export interface ArmDecision { show: boolean; propensity: number }

interface ArmsFile {
  version: 1;
  status: Partial<Record<ArmId, 'active' | 'shadow'>>;
}

export interface ArmReport {
  arm: ArmId;
  status: 'active' | 'shadow';
  decisions: number;      // policy_active events with a reward-scored episode
  shownRate: number;
  vShow: number | null;   // self-normalized IPS value of "always show"
  vHide: number | null;   // …and of "never show"
  lift: number | null;    // vShow − vHide
}

export class PolicyArms {
  private filePath: string;
  private data: ArmsFile = { version: 1, status: {} };
  private loaded = false;
  private rng: () => number;
  private holdout: number;

  constructor(projectRoot: string = mindSingletonRoot(), opts?: { rng?: () => number; holdout?: number }) {
    this.filePath = path.join(stateDir('.bimax', projectRoot), 'policy-arms.json');
    this.rng = opts?.rng ?? Math.random;
    const env = Number(process.env.BIMAX_POLICY_HOLDOUT);
    this.holdout = opts?.holdout ?? (Number.isFinite(env) && env >= 0 && env < 1 ? env : DEFAULT_HOLDOUT);
  }

  private load(): void {
    if (this.loaded) return;
    this.loaded = true;
    try {
      const parsed = JSON.parse(fs.readFileSync(this.filePath, 'utf-8'));
      if (parsed?.status) this.data.status = parsed.status;
    } catch { /* first run */ }
  }

  private save(): void {
    try {
      fs.mkdirSync(path.dirname(this.filePath), { recursive: true });
      fs.writeFileSync(this.filePath, JSON.stringify(this.data, null, 2), 'utf-8');
    } catch { /* best-effort */ }
  }

  /** The randomization rate in force, so a report can say WHY it has no counterfactual. */
  holdoutRate(): number { return this.holdout; }

  status(arm: ArmId): 'active' | 'shadow' {
    this.load();
    return this.data.status[arm] || 'active';
  }

  setStatus(arm: ArmId, status: 'active' | 'shadow'): void {
    this.load();
    this.data.status[arm] = status;
    this.save();
    try { getEventLedger().append('policy_status', { arm, status }); } catch { /* best-effort */ }
  }

  /**
   * The per-injection gate. Call ONLY when the arm actually has content (an empty block
   * is not a decision). Logs the propensity-carrying event and answers show/hide.
   */
  decide(arm: ArmId, ledger: EventLedger = getEventLedger()): ArmDecision {
    const st = this.status(arm);
    const propensity = st === 'shadow' ? 0 : 1 - this.holdout;
    // With no holdout there is nothing to draw: showing is deterministic, so do not
    // consume randomness. The decision is still logged — it is the audit trail.
    const show = st === 'shadow' ? false : this.holdout <= 0 || this.rng() >= this.holdout;
    try { ledger.append('policy_active', { arm, shown: show, propensity }); } catch { /* best-effort */ }
    return { show, propensity };
  }

  /**
   * Fold (decision, reward) pairs from the ledger: each policy_active event joins the
   * episode it sits in (boundary-to-boundary), whose reward is its tool-success ratio.
   */
  foldRewards(ledger: EventLedger = getEventLedger()): Record<ArmId, { shown: boolean; propensity: number; reward: number }[]> {
    const out = Object.fromEntries(ARM_IDS.map(a => [a, [] as { shown: boolean; propensity: number; reward: number }[]])) as Record<ArmId, { shown: boolean; propensity: number; reward: number }[]>;
    let events: { type: string; payload: any }[];
    try { events = ledger.all() as any; } catch { return out; }

    let pending: { arm: ArmId; shown: boolean; propensity: number }[] = [];
    let ok = 0;
    let total = 0;
    const closeEpisode = () => {
      if (pending.length > 0 && total >= MIN_EPISODE_TOOLS) {
        const reward = ok / total >= REWARD_OK_RATIO ? 1 : 0;
        for (const p of pending) {
          if ((ARM_IDS as readonly string[]).includes(p.arm)) out[p.arm].push({ shown: p.shown, propensity: p.propensity, reward });
        }
      }
      pending = [];
      ok = 0;
      total = 0;
    };

    for (const e of events) {
      if (e.type === 'boundary') closeEpisode();
      else if (e.type === 'policy_active' && e.payload?.arm) {
        pending.push({ arm: e.payload.arm, shown: !!e.payload.shown, propensity: Number(e.payload.propensity) || 0 });
      } else if (e.type === 'tool_outcome') {
        const s = e.payload?.status;
        if (s === 'rejected' || s === 'blocked') continue; // policy/preference, not competence
        total++;
        if (s === 'ok') ok++;
      }
    }
    closeEpisode();
    return out;
  }

  /**
   * Self-normalized IPS for one arm: value of the "always show" policy vs "never show",
   * from logged propensities. Null until both sides have observations to weight.
   */
  ipsEstimate(samples: { shown: boolean; propensity: number; reward: number }[]): { vShow: number | null; vHide: number | null; lift: number | null } {
    let wS = 0, rS = 0, wH = 0, rH = 0;
    for (const s of samples) {
      if (s.shown && s.propensity > 0) {
        const w = 1 / s.propensity;
        wS += w; rS += w * s.reward;
      } else if (!s.shown && s.propensity < 1) {
        const w = 1 / (1 - s.propensity);
        wH += w; rH += w * s.reward;
      }
    }
    const vShow = wS > 0 ? rS / wS : null;
    const vHide = wH > 0 ? rH / wH : null;
    return { vShow, vHide, lift: vShow !== null && vHide !== null ? vShow - vHide : null };
  }

  /**
   * Nominal 95% Newcombe/Wilson difference interval for independent binary episodes
   * at one fixed randomized propensity. No CI for shadow traffic or adaptive weights.
   * Source: Newcombe (1998), doi:10.1002/(SICI)1097-0258(19980430)17:8<873::AID-SIM779>3.0.CO;2-I.
   * Callers must establish independent, completed episodes; this method does not
   * turn historical observations into a randomized experiment.
   */
  holdoutComparison(samples: { shown: boolean; propensity: number; reward: number }[]): {
    shown: number; hidden: number; lift: number | null;
    interval: { lo: number; hi: number } | null; reason: string | null;
  } {
    const shown = samples.filter(s => s.shown);
    const hidden = samples.filter(s => !s.shown);
    const unavailable = (reason: string) => ({ shown: shown.length, hidden: hidden.length, lift: null, interval: null, reason });
    if (!shown.length || !hidden.length) return unavailable('Both randomized arms require observations');
    const propensity = samples[0].propensity;
    if (samples.some(s => !Number.isFinite(s.propensity) || s.propensity <= 0 || s.propensity >= 1
      || s.propensity !== propensity || (s.reward !== 0 && s.reward !== 1))) {
      return unavailable('Requires fixed propensity in (0,1) and binary independent episode rewards');
    }
    const yes = shown.reduce((n, s) => n + s.reward, 0);
    const no = hidden.reduce((n, s) => n + s.reward, 0);
    const p = yes / shown.length, q = no / hidden.length;
    const a = wilsonInterval(yes, shown.length), b = wilsonInterval(no, hidden.length);
    const lift = p - q;
    return {
      shown: shown.length, hidden: hidden.length, lift,
      interval: {
        lo: Math.max(-1, lift - Math.hypot(p - a.lo, b.hi - q)),
        hi: Math.min(1, lift + Math.hypot(a.hi - p, q - b.lo)),
      }, reason: null,
    };
  }

  report(ledger: EventLedger = getEventLedger()): ArmReport[] {
    const folded = this.foldRewards(ledger);
    return ARM_IDS.map(arm => {
      const samples = folded[arm];
      const { vShow, vHide, lift } = this.ipsEstimate(samples);
      return {
        arm,
        status: this.status(arm),
        decisions: samples.length,
        shownRate: samples.length > 0 ? samples.filter(s => s.shown).length / samples.length : 0,
        vShow, vHide, lift,
      };
    });
  }
}

let _global: PolicyArms | null = null;
export function getPolicyArms(): PolicyArms {
  if (!_global) _global = new PolicyArms(mindSingletonRoot());
  return _global;
}
export function __setPolicyArms(p: PolicyArms | null): void { _global = p; }

import { AgentLoop } from '../core/agent.loop';
import { Message } from '../core/llm.provider';
import {
  LoadedEpisode, ReplayProvider, loadEpisode,
} from './episode.recorder';
import { mindSingletonRoot } from './self.model';
import { inReplayScope } from '../core/replay.scope';

/**
 * Replay harness (BiMax v2, Phase 4 — the divergence-report consumer).
 *
 * Re-drives a REAL AgentLoop over a recorded episode: LLM responses come from the
 * bundle's ReplayProvider, tool calls are answered from the recorded tool results
 * (side-effect-free — nothing executes), and the learning observers stand down.
 *
 * What that measures: with an unchanged harness the re-run is deterministic — every
 * request hash matches its recording and the report says IDENTICAL (the determinism
 * gate). After a harness change (system prompt, context assembly, sanitizer, tool
 * surface), the first request whose hash no longer matches is the exact point where
 * the change alters the agent's trajectory — an eval on recorded traffic at zero
 * token cost, which is D5's whole demand.
 */

export interface ReplayReport {
  id: string;
  callsRecorded: number;
  callsServed: number;
  divergences: { idx: number; expected: string; got: string }[];
  /** The system prompt used for the re-run differed from the recorded one. */
  systemChanged: boolean;
  /** Served every recorded call with zero divergence — bit-for-bit trajectory match. */
  identical: boolean;
  /** Tool executions that ran past the recorded results (a diverged trajectory asked for more). */
  toolResultsMissing: number;
  /** Text the re-run yielded (what the user would have seen). */
  finalText: string;
  /** Fidelity caveats baked into the recording itself (compaction snapshots, multimodal markers). */
  caveats: string[];
}

/**
 * A ToolRegistry stand-in serving the episode's recorded reality: schemas advertise
 * exactly the tool names the NEXT recorded call advertised (so request hashes can
 * match), and execute() answers with the recorded tool results in recorded order.
 */
function recordedToolRegistry(ep: LoadedEpisode, provider: ReplayProvider) {
  // Recorded tool results, in the order the original loop appended them.
  const results: { id?: string; content: string }[] = [];
  for (const c of ep.calls) {
    for (const m of c.newMessages) {
      if (m.role === 'tool') results.push({ id: m.tool_call_id, content: m.content || '' });
    }
  }
  let cursor = 0;
  let missing = 0;
  let lastNames: string[] = ep.calls[0]?.toolNames || [];
  // Every tool name this episode ever advertised or called — getTool answers only for
  // these, matching the original registry's "unknown tool" behavior.
  const known = new Set<string>();
  for (const c of ep.calls) {
    for (const n of c.toolNames || []) known.add(n);
    for (const t of c.response?.toolCalls || []) known.add(t.name);
  }

  const makeTool = (name: string) => ({
    name,
    isConcurrencySafe: false, // sequential — preserves the recorded result order exactly
    execute: async () => {
      const next = results[cursor++];
      if (!next) { missing++; return '[replay] No recorded result left for this tool call — the trajectory diverged past the recording.'; }
      return next.content;
    },
  });

  return {
    getSchemas: () => {
      const next = provider.peekNext();
      if (next?.toolNames?.length) lastNames = next.toolNames;
      return lastNames.map(n => ({ type: 'function', function: { name: n, parameters: { type: 'object', properties: {} } } }));
    },
    getTool: (name: string) => (known.has(name) ? makeTool(name) : undefined),
    missingCount: () => missing,
  };
}

/** Reconstruct the exact Message the original loop held from its recorded form. */
function toMessage(m: LoadedEpisode['calls'][number]['newMessages'][number]): Message {
  const out: Message = { role: m.role as Message['role'] };
  if (m.content !== undefined) out.content = m.content;
  if (m.name) out.name = m.name;
  if (m.tool_call_id) out.tool_call_id = m.tool_call_id;
  if (m.tool_calls) out.tool_calls = m.tool_calls;
  return out;
}

/**
 * Re-run one recorded episode through the current harness. `systemPrompt` defaults to
 * the RECORDED prompt (determinism check); pass a different one to evaluate a prompt
 * change against recorded traffic.
 */
export async function replayEpisode(
  idOrFile: string,
  opts?: { root?: string; systemPrompt?: string }
): Promise<ReplayReport | { error: string }> {
  const ep = loadEpisode(idOrFile, opts?.root || mindSingletonRoot());
  if (!ep) return { error: `No episode bundle "${idOrFile}" found.` };
  if (!ep.chainOk) return { error: `Bundle hash chain is broken at line ${ep.brokenAt} — refusing to replay a tampered recording.` };
  if (ep.calls.length === 0) return { error: 'Bundle has no recorded calls.' };
  if (ep.header.system === undefined) {
    return { error: 'Bundle predates replay support (no system prompt recorded) — record a fresh episode.' };
  }

  const caveats: string[] = [];
  if (ep.calls.some(c => c.reset)) caveats.push('recording spans a compaction — the snapshot tail is approximate');
  if (ep.calls.some(c => c.newMessages.some(m => typeof m.content === 'string' && m.content.startsWith('[multimodal content:')))) {
    caveats.push('recording contains multimodal content (stored as markers) — those requests diverge by construction');
  }

  const system = opts?.systemPrompt ?? ep.header.system;
  const provider = new ReplayProvider(ep.calls);
  const registry = recordedToolRegistry(ep, provider);
  // Call 0's delta IS the full history at the first request (lastMsgCount started at 0).
  const initialMessages = ep.calls[0].newMessages.map(toMessage);

  return inReplayScope(async () => {
    const loop = new AgentLoop(provider, registry as any);
    let finalText = '';
    const gen = loop.execute(initialMessages, system, {
      maxIterations: ep.calls.length + 2,
      useLite: ep.header.lite,
    });
    for await (const chunk of gen) finalText += chunk;

    return {
      id: ep.header.id,
      callsRecorded: ep.calls.length,
      callsServed: provider.served,
      divergences: [...provider.divergences],
      systemChanged: system !== ep.header.system,
      identical: provider.served === ep.calls.length && provider.divergences.length === 0
        && registry.missingCount() === 0,
      toolResultsMissing: registry.missingCount(),
      finalText: finalText.trim(),
      caveats,
    };
  });
}

import { stateDir } from '../utils/state.dir';
import * as fs from 'fs';
import * as os from 'os';
import * as path from 'path';
import { betaTailProb, betaMean } from './stats';

/**
 * Root for the mind layer's SINGLETONS. Under jest, unrelated tests exercise the agent
 * loop (whose observers feed the singletons), and persisting that fake experience into
 * the repo's real .bimax/ would poison the agent's actual self-knowledge — so test runs
 * get a throwaway temp root. Explicit `new X(root)` instances (mind.test.ts) are unaffected.
 *
 * In production this MUST be stable for the whole process, anchored to the PROJECT root — not
 * raw process.cwd(). cwd() fragments the mind: launching from a subdirectory (or after a
 * ChangeDirectoryTool) opened a *different* .bimax/ledger.db, so rewards (tool_outcome),
 * episode boundaries, and policy decisions scattered across files and never assembled into a
 * scorable episode — which is exactly why /arms had no data to fold. We resolve the nearest
 * ancestor holding a .git or existing .bimax once and cache it, so every singleton shares one
 * coherent store regardless of where the binary was launched.
 */
let _cachedRoot: string | null = null;
export function mindSingletonRoot(): string {
  if (process.env.JEST_WORKER_ID) {
    return fs.mkdtempSync(path.join(os.tmpdir(), 'bimax-mind-singleton-'));
  }
  if (_cachedRoot) return _cachedRoot;
  _cachedRoot = findProjectRoot(process.cwd());
  return _cachedRoot;
}

/**
 * Walk up from `start` to the git project root; fall back to `start` if the tree has no `.git`.
 * We anchor on `.git` (not `.bimax`) deliberately: a stray `.bimax/` left in a subdirectory by the
 * old cwd-fragmented behavior must NOT win over the real project root, or it would perpetuate the
 * very fragmentation this fix removes.
 */
function findProjectRoot(start: string): string {
  let dir = start;
  for (let i = 0; i < 40; i++) {
    if (fs.existsSync(path.join(dir, '.git'))) return dir;
    const parent = path.dirname(dir);
    if (parent === dir) break; // reached filesystem root
    dir = parent;
  }
  return start;
}

/**
 * SelfModel v2 — the agent's learned model of its OWN error surface (metacognition),
 * now statistically honest:
 *
 *   - Cells are keyed tool × domain × MODEL. Failure rates learned under one backing
 *     model never punish a different model after a swap (the v1 conflation bug).
 *   - Decisions are posterior probability statements on a Beta-Bernoulli model with
 *     partial pooling, not `n >= 6 && rate >= 0.3` magic numbers. A cell's prior is
 *     pulled from the SAME TOOL's other cells (excluding itself), falling back to a
 *     global base failure rate — so two early failures don't brand a tool "weak",
 *     while a sustained pattern does, with quantified confidence.
 *   - "Weak spot"  = P(θ_fail > 0.30) > 0.90 under the posterior.
 *   - "Escalation" = P(θ_fail > 0.45) > 0.90.
 *   - Stated confidence for the epistemic ledger = 1 − posterior mean failure rate,
 *     which is what makes the calibration curve meaningful.
 *
 * Recency: the posterior's likelihood uses the rolling window (last 40 outcomes per
 * cell); lifetime counts inform only the pooled prior. A change in behavior therefore
 * dominates within ~a window, without a hard cliff.
 */

export interface OutcomeCell {
  ok: number;
  err: number;
  /** Rolling window of the last N outcomes (1 = error) — the posterior's likelihood. */
  recent: number[];
  lastErr?: string;
  updated: string;
}

export interface WeakSpot {
  tool: string;
  domain: string;
  model: string;
  failRate: number;   // posterior mean failure rate
  pWeak: number;      // P(θ > WEAK_LEVEL) — the decision statistic
  n: number;          // window samples behind it
  advice: string;
  lastErr?: string;
}

interface SelfModelFile {
  version: 2;
  cells: Record<string, OutcomeCell>;
}

const RECENT_WINDOW = 40;
// Decision levels (what failure rate matters) and the posterior mass required to act.
const WEAK_LEVEL = 0.30;
const ESCALATE_LEVEL = 0.45;
const DECISION_MASS = 0.90;
// Pooling strength: the prior is worth κ pseudo-observations of the parent's rate.
const KAPPA = 4;
// Global base failure rate when a tool has no other history to pool from.
const PRIOR_FAIL = 0.15;

/** Routing alternatives keyed by tool — what to reach for instead when a cell is weak. */
const ALTERNATIVES: Record<string, string> = {
  EditFileTool: 'prefer SymbolEditTool (AST-addressed, whole-symbol replace) or MultiEditTool, and re-read the file immediately before editing',
  MultiEditTool: 'fall back to single EditFileTool calls with a fresh ReadFileTool before each',
  SymbolEditTool: 'fall back to EditFileTool with an exact unique old_string taken from a fresh read',
  WriteFileTool: 'read the target first and prefer surgical edits over whole-file rewrites',
  BashTool: 'double-check flags against --help before running, and prefer dedicated tools (GrepTool/GlobTool/ReadFileTool) over shell equivalents',
  GrepTool: 'try GraphQueryTool SEARCH_NODES / SEMANTIC when the repo is indexed — it resolves symbols greps miss',
  WebFetchTool: 'try WebSearchTool first to find a working URL',
};

/** Short, stable key for the active backing model ('-' when unknown). */
export function currentModelKey(): string {
  try {
    // Lazy require avoids a config→mind→config cycle and tolerates config not loaded yet.
    const { getConfig } = require('../engine/config');
    const id = String(getConfig().model || '');
    if (!id) return '-';
    return id.split('/').pop()!.slice(0, 40);
  } catch { return '-'; }
}

function cellKey(tool: string, domain: string, model: string): string {
  return `${tool}|${domain}|${model}`;
}

/** Parse a v1 or v2 cell key. v1 keys (`tool|domain`) are treated as model '-'. */
function parseKey(key: string): { tool: string; domain: string; model: string } {
  const parts = key.split('|');
  return { tool: parts[0], domain: parts[1] ?? '-', model: parts[2] ?? '-' };
}

/**
 * Classify a tool result into ok | err | rejected. Necessary because most tools report
 * failure by RETURNING an error string (the loop's isError flag only covers throws), so
 * outcome telemetry keyed on isError alone would count almost every real failure as a
 * success. 'rejected' (user said no to a diff) is neither — it's preference data, not
 * agent incompetence, and must not poison the failure rates.
 */
export function classifyOutcome(result: string, isError: boolean): 'ok' | 'err' | 'rejected' {
  const head = (result || '').slice(0, 300);
  if (/rejected by user/i.test(head)) return 'rejected';
  if (isError) return 'err';
  if (/^\s*(Error|Tool Error|Failed|❌|✗)/i.test(head)) return 'err';
  if (/\b(syntax check failed|no match found|not found in file|blocked by governor|governor blocked|edit shield|command failed|ENOENT|EACCES)\b/i.test(head)) return 'err';
  return 'ok';
}

/**
 * The single rule for labelling a tool call, used by every observer that learns from one.
 *
 * A typed outcome is ground truth ONLY when the tool itself declared it. `confidence: 'low'` marks
 * the factory's own guess at legacy "Error: …" prose (tool.factory.ts wraps it as errorClass
 * 'unknown'), and preferring that guess over {@link classifyOutcome} is how a "rejected by user"
 * coming back from an unswept or MCP tool got filed as an agent failure — while the identical
 * rejection from a swept tool was correctly preference data. Low confidence means "ask the
 * classifier", which is the only reason the classifier was kept.
 */
export function labelOutcome(
  typed: { status: 'ok' | 'error' | 'rejected' | 'blocked'; confidence?: 'high' | 'low' } | undefined,
  result: string,
  isError: boolean,
): 'ok' | 'err' | 'rejected' {
  const declared = typed && typed.confidence !== 'low' ? typed : undefined;
  if (!declared) return classifyOutcome(result, isError);
  return declared.status === 'ok' ? 'ok' : declared.status === 'error' ? 'err' : 'rejected';
}

/**
 * Derive the outcome domain from a tool call's raw JSON args: file extension for
 * path-taking tools, the shell program for BashTool, '-' otherwise.
 */
export function domainOf(toolName: string, rawArgs: string): string {
  let args: any;
  try { args = JSON.parse(rawArgs || '{}'); } catch { return '-'; }
  if (toolName === 'BashTool') {
    const cmd = String(args.command || '').trim();
    const first = cmd.split(/\s+/)[0] || '-';
    // strip paths: /usr/bin/git → git
    return first.split('/').pop() || '-';
  }
  const p = args.path || args.file_path || args.filePath || args.file || args.target || '';
  if (typeof p === 'string' && p) {
    const ext = path.extname(p).replace(/^\./, '');
    return ext || path.basename(p);
  }
  return '-';
}

/** The file path a tool call touches, if any — used by the epistemic ledger to scope claims. */
export function pathOf(rawArgs: string): string | undefined {
  try {
    const args = JSON.parse(rawArgs || '{}');
    const p = args.path || args.file_path || args.filePath || args.file || args.target;
    return typeof p === 'string' && p ? p : undefined;
  } catch { return undefined; }
}

export class SelfModel {
  private cells: Record<string, OutcomeCell> = {};
  private loaded = false;
  private dirty = false;
  private filePath: string;
  private saveTimer: NodeJS.Timeout | null = null;

  constructor(projectRoot: string = process.cwd()) {
    this.filePath = path.join(stateDir('.bimax', projectRoot), 'self-model.json');
  }

  /** Synchronous lazy load — prompt building is sync, so the model must be too. */
  private load(): void {
    if (this.loaded) return;
    this.loaded = true;
    try {
      const parsed: SelfModelFile = JSON.parse(fs.readFileSync(this.filePath, 'utf-8'));
      if (parsed && typeof parsed.cells === 'object' && parsed.cells !== null && !Array.isArray(parsed.cells)) {
        this.cells = parsed.cells; // v1 two-part keys parse as model '-' via parseKey
      }
    } catch { /* first run / corrupt file — start empty */ }
  }

  private scheduleSave(): void {
    if (this.saveTimer) return;
    this.saveTimer = setTimeout(() => {
      this.saveTimer = null;
      this.saveNow();
    }, 1500);
    // Never keep the process alive just to flush telemetry.
    this.saveTimer.unref?.();
  }

  /** Drop in-memory state and re-read the file on next use — after a view rebuild swapped it. */
  reload(): void {
    if (this.saveTimer) { clearTimeout(this.saveTimer); this.saveTimer = null; }
    this.loaded = false;
    this.dirty = false;
    this.cells = {};
  }

  /** Cell totals keyed by tool|domain|model — the comparable essence of the learned state. */
  cellTotals(): Record<string, { ok: number; err: number }> {
    this.load();
    const out: Record<string, { ok: number; err: number }> = {};
    for (const [k, c] of Object.entries(this.cells)) out[k] = { ok: c.ok, err: c.err };
    return out;
  }

  /** Flush to disk immediately (also used on shutdown). Best-effort, no-op when clean. */
  saveNow(): void {
    if (!this.dirty) return;
    try {
      fs.mkdirSync(path.dirname(this.filePath), { recursive: true });
      const data: SelfModelFile = { version: 2, cells: this.cells };
      fs.writeFileSync(this.filePath, JSON.stringify(data, null, 2), 'utf-8');
      this.dirty = false;
    } catch { /* telemetry must never break the loop */ }
  }

  record(tool: string, domain: string, ok: boolean, errSample?: string, modelKey?: string): void {
    this.load();
    this.dirty = true;
    // modelKey override exists for ledger replays (rebuilds must attribute each event to
    // the model that produced it, not whichever model is active at rebuild time).
    const key = cellKey(tool, domain, modelKey ?? currentModelKey());
    let c = this.cells[key];
    if (!c) {
      c = { ok: 0, err: 0, recent: [], updated: '' };
      this.cells[key] = c;
    }
    if (ok) c.ok++; else c.err++;
    c.recent.push(ok ? 0 : 1);
    if (c.recent.length > RECENT_WINDOW) c.recent.splice(0, c.recent.length - RECENT_WINDOW);
    if (!ok && errSample) c.lastErr = errSample.slice(0, 200);
    c.updated = new Date().toISOString();
    this.scheduleSave();
  }

  /**
   * Pooled prior mean for a cell: the same tool's OTHER cells' lifetime failure rate
   * (Jeffreys-smoothed), falling back to the global base rate. Excluding the cell
   * itself is what stops a lone cell from being its own prior (which would defeat
   * shrinkage entirely and let two early failures condemn a tool).
   */
  private priorMean(key: string): number {
    const { tool } = parseKey(key);
    let okSum = 0, errSum = 0;
    for (const [k, c] of Object.entries(this.cells)) {
      if (k === key) continue;
      if (parseKey(k).tool !== tool) continue;
      okSum += c.ok;
      errSum += c.err;
    }
    const n = okSum + errSum;
    if (n === 0) return PRIOR_FAIL;
    return (errSum + 0.5) / (n + 1); // Jeffreys smoothing
  }

  /** Posterior Beta(α, β) over the cell's FAILURE rate: pooled prior + recent-window likelihood. */
  private posterior(key: string, c: OutcomeCell): { alpha: number; beta: number; n: number } {
    const mu = this.priorMean(key);
    const f = c.recent.reduce((a: number, b: number) => a + b, 0);
    const s = c.recent.length - f;
    return { alpha: KAPPA * mu + f, beta: KAPPA * (1 - mu) + s, n: c.recent.length };
  }

  /** Cells relevant to the ACTIVE model (its own cells plus legacy model-agnostic ones). */
  private activeCells(): Array<{ key: string; tool: string; domain: string; model: string; cell: OutcomeCell }> {
    this.load();
    const active = currentModelKey();
    const out: Array<{ key: string; tool: string; domain: string; model: string; cell: OutcomeCell }> = [];
    for (const [key, cell] of Object.entries(this.cells)) {
      const p = parseKey(key);
      if (p.model === active || p.model === '-') out.push({ key, ...p, cell });
    }
    return out;
  }

  weakSpots(): WeakSpot[] {
    const out: WeakSpot[] = [];
    for (const { key, tool, domain, model, cell } of this.activeCells()) {
      const { alpha, beta, n } = this.posterior(key, cell);
      const pWeak = betaTailProb(WEAK_LEVEL, alpha, beta);
      if (pWeak < DECISION_MASS) continue;
      const advice = ALTERNATIVES[tool] || 'slow down here: verify arguments before the call and read the result back after';
      out.push({ tool, domain, model, failRate: betaMean(alpha, beta), pWeak, n, advice, lastErr: cell.lastErr });
    }
    return out.sort((a, b) => b.failRate - a.failRate);
  }

  /**
   * Stated confidence for a claim made after using this tool on this domain under the
   * active model: 1 − posterior mean failure rate. With no history the pooled prior
   * yields ≈ 1 − PRIOR_FAIL, so cold cells state ~0.85 — grounded, not hardcoded.
   */
  confidenceFor(tool: string, domain: string): number {
    this.load();
    const key = cellKey(tool, domain, currentModelKey());
    const c = this.cells[key] ?? this.cells[cellKey(tool, domain, '-')];
    if (!c) {
      const mu = this.priorMean(key);
      return Math.min(0.99, Math.max(0.05, 1 - mu));
    }
    const { alpha, beta } = this.posterior(key, c);
    return Math.min(0.99, Math.max(0.05, 1 - betaMean(alpha, beta)));
  }

  /** Domains where the agent is unreliable enough that claims need hard evidence. */
  escalationDomains(): string[] {
    const out: string[] = [];
    for (const { key, tool, domain, cell } of this.activeCells()) {
      const { alpha, beta } = this.posterior(key, cell);
      if (betaTailProb(ESCALATE_LEVEL, alpha, beta) >= DECISION_MASS) out.push(`${tool} on ${domain}`);
    }
    return out;
  }

  /** Total recorded outcomes — used by /self to show how much experience the model rests on. */
  totals(): { calls: number; errors: number; cells: number } {
    this.load();
    let calls = 0, errors = 0;
    for (const c of Object.values(this.cells)) { calls += c.ok + c.err; errors += c.err; }
    return { calls, errors, cells: Object.keys(this.cells).length };
  }

  /**
   * The SELF-KNOWLEDGE prompt section: top weak spots as routing rules. Empty string
   * when there's nothing actionable (never pad the prompt with noise).
   */
  getPromptBlock(): string {
    const weak = this.weakSpots().slice(0, 5);
    if (weak.length === 0) return '';
    const lines = weak.map(w =>
      `- ${w.tool} on \`${w.domain}\` fails ~${Math.round(w.failRate * 100)}% of the time here (P>${Math.round(w.pWeak * 100)}% certain, n=${w.n}) — ${w.advice}.`
    );
    return `### SELF-KNOWLEDGE (learned from your own telemetry — route around your weaknesses)\nThese are YOUR measured failure rates in this repo under the current model. Adjust your tool choices accordingly; after acting in a weak area, verify the result (read the file back / run the check) before claiming success.\n${lines.join('\n')}`;
  }

  /** Human-readable report for /self and /diagnostics. */
  report(): string[] {
    this.load();
    const t = this.totals();
    if (t.calls === 0) return ['- No outcomes recorded yet — the self-model builds as tools run.'];
    const lines = [`- Experience: ${t.calls} tool outcomes across ${t.cells} tool×domain×model cells (${t.errors} failures).`];
    const weak = this.weakSpots().slice(0, 6);
    if (weak.length === 0) {
      lines.push('- No weak spots above the posterior decision threshold — all routes healthy.');
    } else {
      for (const w of weak) {
        lines.push(`- ⚠ ${w.tool} × ${w.domain}${w.model !== '-' ? ` × ${w.model}` : ''}: ~${Math.round(w.failRate * 100)}% fail (P(θ>${WEAK_LEVEL})=${w.pWeak.toFixed(2)}, n=${w.n}) → ${w.advice}`);
      }
    }
    const esc = this.escalationDomains();
    if (esc.length > 0) lines.push(`- Verification escalated for: ${esc.join(', ')}`);
    return lines;
  }
}

let _global: SelfModel | null = null;
export function getSelfModel(): SelfModel {
  if (!_global) {
    _global = new SelfModel(mindSingletonRoot());
    // The debounced save can be lost on a fast exit; flush whatever is pending.
    process.once('exit', () => { try { _global?.saveNow(); } catch { /* exiting */ } });
  }
  return _global;
}
/** Test hook: replace the singleton (e.g. with one rooted in a temp dir). */
export function __setSelfModel(m: SelfModel | null): void { _global = m; }

import { EventLedger, getEventLedger } from './event.ledger';
import { SelfModel, getSelfModel, mindSingletonRoot } from './self.model';

/**
 * Materialized views over the event ledger (BiMax v2, D1).
 *
 * The v2 property being delivered here: learned state is not a mutable database you have
 * to trust — it is a FOLD over the append-only event log, reproducible by construction.
 * The JSON files the mind engines read stay exactly as they are (fast, sync, prompt-time
 * friendly); what changes is their status: they become caches that can be dropped and
 * rebuilt from the ledger at any time, audited against it, or re-derived with better
 * math later without losing a single observation.
 *
 * The self-model is the flagship view (it feeds routing, claim confidence, and the
 * ledger's own escalations). Habit/epistemic views can follow the same pattern — their
 * raw events (boundary, claim, evidence) are already being recorded.
 */

export interface RebuildReport {
  events: number;        // tool_outcome events replayed
  skipped: number;       // rejected/blocked events (never failure-rate samples)
  cells: number;         // resulting cells
  cellsBefore: number;   // cells in the live model before the swap
  agreed: boolean;       // live totals ⊆ rebuilt totals matched exactly (where comparable)
}

/** Fold tool_outcome events into a fresh SelfModel instance (no disk writes). */
export function foldSelfModel(events: { payload: any }[], root: string): { model: SelfModel; replayed: number; skipped: number } {
  const model = new SelfModel(root);
  let replayed = 0;
  let skipped = 0;
  for (const e of events) {
    const p = e.payload || {};
    const status = String(p.status || '');
    // Same policy as the live loop: rejections and policy blocks are preference/policy
    // data — they never count toward a tool's failure rate.
    if (status === 'rejected' || status === 'blocked') { skipped++; continue; }
    const ok = status === 'ok';
    model.record(String(p.tool || '-'), String(p.domain || '-'), ok, ok ? undefined : p.errSample, String(p.model || '-'));
    replayed++;
  }
  return { model, replayed, skipped };
}

/**
 * Rebuild the self-model from the ledger and swap it in atomically: fold events into a
 * fresh model, compare against the live one, write, and make the singleton reload.
 * Returns null when the ledger is unavailable or empty (nothing to rebuild from).
 */
export function rebuildSelfModel(ledger: EventLedger = getEventLedger(), root: string = mindSingletonRoot()): RebuildReport | null {
  const events = ledger.byType('tool_outcome');
  if (events.length === 0) return null;

  const { model, replayed, skipped } = foldSelfModel(events, root);

  // Agreement check (advisory, shown to the human): for every cell in the rebuilt view,
  // the live model — which may hold MORE history than the ledger (it predates it) —
  // should have at least as many samples. A live count BELOW the rebuilt one means the
  // JSON lost observations the ledger kept: exactly the drift views exist to expose.
  const live = getSelfModel().cellTotals();
  const rebuilt = model.cellTotals();
  let agreed = true;
  for (const [k, r] of Object.entries(rebuilt)) {
    const l = live[k];
    if (!l || l.ok < r.ok || l.err < r.err) { agreed = false; break; }
  }

  model.saveNow();
  getSelfModel().reload();

  return { events: replayed + skipped, skipped, cells: Object.keys(rebuilt).length, cellsBefore: Object.keys(live).length, agreed };
}

import * as fs from 'fs';
import * as path from 'path';
import { engineEvents } from '../engine/events';
import { sessionDir } from '../engine/session';
import { getSessionRecorder } from '../engine/session.recorder';
import { BashStaticAnalyzer } from '../governor/bash.analyzer';

/**
 * Completion checks (backlog F3): "done" means a stated check passed, not that the model stopped talking.
 *
 * Before this a task ended "completed" whenever a turn finished without an error, and nothing looked at the work. The
 * outcome contract could require proof, but only if the model chose to define one — on the development machine, 22
 * saved tasks and 0 contracts. So the check is asked for by the harness, not left to the model's initiative:
 * - a turn that changed files and has no check is asked, once, to state one (or to skip, with a reason);
 * - when the turn ends, the ENGINE runs the checks itself — a command through the same shell tool and permission rules
 *   as any other, a file or JSON check read directly — and grades them by what it observed, never by what the model
 *   said about them;
 * - a failed check sends the task back to work with the failure, up to a retry limit (F5), and a turn that still fails
 *   ends "check failed", not "done";
 * - the model cannot swap or skip a check that failed in the same turn; the user can, in their next message.
 * The checks and their last result are saved per session next to the outcome contract, so a resumed task (F2) keeps them.
 */

export type CompletionCheck =
  | { kind: 'command'; command: string }
  | { kind: 'file'; path: string; contains?: string }
  | { kind: 'json'; path: string };

/**
 * none: nothing changed, nothing to check. unchecked: files changed and there is no check (or it was skipped).
 * pending: a check is set and has not run since the last change. passed / failed: its last run.
 */
export type CheckState = 'none' | 'unchecked' | 'pending' | 'passed' | 'failed';

export interface CheckResult { check: CompletionCheck; ok: boolean; detail: string }

export interface CheckSnapshot {
  state: CheckState;
  checks: CompletionCheck[];
  skipped?: string;
  results: CheckResult[];
  /** Test files this user turn changed before the checks passed: the pass may rest on those edits. */
  testsEdited?: string[];
  /** Failed runs in the current user turn; the task goes back to work while this is at most `maxRetries`. */
  attempts: number;
  maxRetries: number;
  checkedAt?: number;
}

/** Runs a command the way the task's own shell would, and reports the exit code the engine observed. */
export type CommandRunner = (command: string) => Promise<{ exitCode: number | null; output: string }>;

/** What the loop does at the end of a turn: go back to work with this message, or end, optionally saying something. */
export type Verdict = { continue: string } | { end: string | null };

interface Stored {
  version: 1;
  sessionId: string;
  checks: CompletionCheck[];
  skipped?: string;
  state: CheckState;
  results: CheckResult[];
  attempts: number;
  checkedAt?: number;
  testsEdited?: string[];
}

/** Automatic retries after a failed check, per user turn. The app sets it per task from Settings (F5). */
export const DEFAULT_CHECK_RETRIES = 2;
const MAX_FILE_BYTES = 8 * 1024 * 1024;
const DETAIL_CHARS = 1200;

export const ASK_FOR_CHECK = [
  '[Completion check] This task changed files. Before you finish, state how the result will be checked: call',
  'CompletionCheckTool with action "set" and one or more checks — a command that must exit 0 (such as the project\'s',
  'tests or its build), a file that must exist (optionally containing some text), or a JSON file that must parse.',
  'Bimax runs the checks itself when you finish, and the user can change them. If nothing meaningful can be checked,',
  'call CompletionCheckTool with action "skip" and say why.',
].join(' ');

export function describeCheck(check: CompletionCheck): string {
  if (check.kind === 'command') return `\`${check.command}\` exits 0`;
  if (check.kind === 'json') return `${check.path} is valid JSON`;
  return check.contains !== undefined ? `${check.path} contains "${check.contains}"` : `${check.path} exists`;
}

/** The checks in `input` that are well formed, or the reason the list is not. */
export function parseChecks(input: unknown): { checks: CompletionCheck[] } | { error: string } {
  if (!Array.isArray(input) || input.length === 0) return { error: 'give at least one check' };
  const checks: CompletionCheck[] = [];
  for (const [index, raw] of input.entries()) {
    const item = (raw ?? {}) as Record<string, unknown>;
    const text = (key: string): string => (typeof item[key] === 'string' ? (item[key] as string).trim() : '');
    if (item.kind === 'command' && text('command')) checks.push({ kind: 'command', command: text('command') });
    else if (item.kind === 'file' && text('path')) {
      checks.push({ kind: 'file', path: text('path'), ...(typeof item.contains === 'string' && item.contains ? { contains: item.contains } : {}) });
    } else if (item.kind === 'json' && text('path')) checks.push({ kind: 'json', path: text('path') });
    else return { error: `check ${index + 1} needs kind "command" with a command, or kind "file"/"json" with a path` };
  }
  return { checks };
}

const tail = (text: string): string => {
  const flat = text.trim();
  return flat.length > DETAIL_CHARS ? `…${flat.slice(-DETAIL_CHARS)}` : flat;
};

/** The output a command left, without the shell tool's JSON wrapping when it has one. */
function commandText(output: string): string {
  try {
    const parsed = JSON.parse(output) as { stdout?: string; stderr?: string };
    return [parsed.stdout, parsed.stderr].filter(Boolean).join('\n');
  } catch { return output; }
}

async function evaluate(check: CompletionCheck, run: CommandRunner, cwd: string): Promise<CheckResult> {
  if (check.kind === 'command') {
    const { exitCode, output } = await run(check.command);
    const status = exitCode === null ? 'did not run to an exit code' : `exit ${exitCode}`;
    const text = tail(commandText(output));
    return { check, ok: exitCode === 0, detail: text ? `${status}: ${text}` : status };
  }
  const file = path.resolve(cwd, check.path);
  let stat: fs.Stats;
  try { stat = fs.statSync(file); } catch { return { check, ok: false, detail: `${check.path} does not exist` }; }
  if (!stat.isFile()) return { check, ok: false, detail: `${check.path} is not a file` };
  if (check.kind === 'file' && check.contains === undefined) return { check, ok: true, detail: `${check.path} exists (${stat.size} bytes)` };
  if (stat.size > MAX_FILE_BYTES) return { check, ok: false, detail: `${check.path} is ${stat.size} bytes, more than the ${MAX_FILE_BYTES} a check reads` };
  const text = fs.readFileSync(file, 'utf8');
  if (check.kind === 'json') {
    try { JSON.parse(text); return { check, ok: true, detail: `${check.path} parses as JSON` }; }
    catch (error) { return { check, ok: false, detail: `${check.path} is not valid JSON: ${(error as Error).message}` }; }
  }
  return text.includes(check.contains!)
    ? { check, ok: true, detail: `${check.path} contains "${check.contains}"` }
    : { check, ok: false, detail: `${check.path} exists but does not contain "${check.contains}"` };
}

/**
 * Whether a path names a test file: a tests/spec folder, or a name like test.js, test-strings.js, test_math.py,
 * math.test.ts or math_test.go. A command check usually runs these, so a task that edits them can pass its own exam.
 * Measured live: given a test it could not pass, a model rewrote the test's expected value and the check went green.
 */
export function isTestFile(file: string): boolean {
  const parts = file.split(/[\\/]/).filter(Boolean);
  const name = parts.pop() ?? '';
  if (parts.some((dir) => /^(tests?|__tests__|specs?)$/i.test(dir))) return true;
  return /^(tests?|specs?)([._-][^/]*)?\.[a-z0-9]+$/i.test(name) || /[._-](tests?|specs?)\.[a-z0-9]+$/i.test(name);
}

const FILE_TOOLS = new Set(['EditFileTool', 'WriteFileTool', 'MultiEditTool', 'SymbolEditTool', 'DeleteTool', 'CreateDirectoryTool']);
let analyzer: BashStaticAnalyzer | null = null;

/**
 * Whether a successful tool call changed files, which makes the task one that needs a check. A shell command counts when
 * the governor's own analyzer classifies it as a write or an install; anything it cannot place ("unknown", such as a
 * script) does not, so a question answered by running the tests is not asked for a check.
 */
export function changesFiles(tool: string, args: string, result: string): boolean {
  if (FILE_TOOLS.has(tool)) return true;
  if (tool === 'DocumentTool') return !result.startsWith('Draft retained');
  if (tool !== 'BashTool') return false;
  let command: string;
  try { command = String((JSON.parse(args) as { command?: unknown }).command ?? ''); } catch { return false; }
  analyzer ??= new BashStaticAnalyzer();
  const { category } = analyzer.analyze(command);
  return category === 'write' || category === 'install';
}

const empty = (sessionId: string): Stored => ({ version: 1, sessionId, checks: [], state: 'none', results: [], attempts: 0 });

export class CompletionChecks {
  private data: Stored = empty('');
  /** Per turn: whether it changed files, whether it was already asked for a check, whether it set one. */
  private changed = false;
  private asked = false;
  private setThisTurn = false;
  /** Files the current user turn changed, as the tools named them. */
  private changedFiles = new Set<string>();

  constructor(private readonly io: {
    sessionId?: () => string;
    directory?: () => string;
    /** Fixed limit, for tests. */
    maxRetries?: () => number;
    /** The engine config's `taskCheckRetries`, used when the environment sets none. */
    configuredRetries?: () => number | undefined;
  } = {}) {}

  private sessionId(): string { return this.io.sessionId?.() || getSessionRecorder()?.currentId() || ''; }
  private directory(): string { return this.io.directory?.() || sessionDir(); }
  /** The first valid of: the fixed limit, BIMAX_TASK_MAX_RETRIES, the engine config; else the default (F5). */
  private maxRetries(): number {
    const env = process.env.BIMAX_TASK_MAX_RETRIES?.trim();
    for (const value of [this.io.maxRetries?.(), env ? Number(env) : undefined, this.io.configuredRetries?.()]) {
      if (typeof value === 'number' && Number.isInteger(value) && value >= 0) return value;
    }
    return DEFAULT_CHECK_RETRIES;
  }

  /** Follow the active session: save the one being left, load the one arrived at. */
  syncSession(): void {
    const id = this.sessionId();
    if (id === this.data.sessionId) return;
    this.data = id ? this.load(id) : empty('');
    this.publish();
  }

  /** A new turn. A user's turn also resets the retry count, so asking again gets fresh attempts. */
  beginTurn(internal = false): void {
    this.syncSession();
    this.changed = false;
    this.asked = false;
    this.setThisTurn = false;
    if (!internal) { this.data.attempts = 0; this.changedFiles.clear(); }
  }

  /** The turn changed files: a check that passed before this no longer says anything about the result. */
  noteChange(file?: string): void {
    this.changed = true;
    if (file) this.changedFiles.add(file);
    if (this.data.checks.length && this.data.state === 'passed') this.update('pending');
  }

  /** Set by the model. Refused when a check failed earlier in this same turn: the task may not change its own grader. */
  set(checks: CompletionCheck[]): string | null {
    if (this.data.attempts > 0) return 'a check failed in this turn, so it can only be changed when the user asks for it';
    this.syncSession();
    this.data = { ...this.data, checks, skipped: undefined, results: [], attempts: 0, checkedAt: undefined };
    this.setThisTurn = true;
    this.update('pending');
    return null;
  }

  skip(reason: string): string | null {
    if (this.data.attempts > 0) return 'a check failed in this turn, so it can only be skipped when the user asks for it';
    this.syncSession();
    this.data = { ...this.data, checks: [], skipped: reason.trim() || 'no reason given', results: [], attempts: 0, checkedAt: undefined };
    this.update(this.changed ? 'unchecked' : 'none');
    return null;
  }

  snapshot(): CheckSnapshot {
    const { state, checks, skipped, results, attempts, checkedAt, testsEdited } = this.data;
    return {
      state, checks, ...(skipped ? { skipped } : {}), results, ...(testsEdited?.length ? { testsEdited } : {}),
      attempts, maxRetries: this.maxRetries(), ...(checkedAt ? { checkedAt } : {}),
    };
  }

  /** The standing prompt block while a check is set, so the model works toward it rather than learning of it at the end. */
  promptBlock(): string {
    if (!this.data.checks.length) return '';
    const last = this.data.results.length && this.data.state !== 'pending'
      ? `\nLast run: ${this.data.state}${this.data.results.filter((r) => !r.ok).map((r) => `\n- ${describeCheck(r.check)}: ${r.detail.slice(0, 300)}`).join('')}`
      : '';
    return [
      '### COMPLETION CHECK',
      'Bimax runs these itself when you finish; the task is not done until every one passes:',
      ...this.data.checks.map((check) => `- ${describeCheck(check)}`),
      'Do not edit the tests a check runs to make it pass. If a test looks wrong, say so to the user instead.',
    ].join('\n') + last;
  }

  /**
   * The end of a turn. Asks once for a check when the turn changed files and has none; otherwise runs the checks when
   * there is something new to grade, and sends the task back to work while failures remain within the retry limit.
   */
  async settle(run: CommandRunner, cwd: string): Promise<Verdict> {
    this.syncSession();
    if (!this.data.checks.length) {
      if (!this.changed) return { end: null };
      if (!this.data.skipped && !this.asked) { this.asked = true; return { continue: ASK_FOR_CHECK }; }
      this.update('unchecked');
      return { end: null };
    }
    // Nothing new to grade: no change, no new check, no run owed, and nothing failed in this turn. After a failure the
    // check reruns even with no change seen — a command that changes files is not always recognisable as one.
    if (!this.changed && !this.setThisTurn && this.data.state !== 'pending' && this.data.attempts === 0) return { end: null };

    const results: CheckResult[] = [];
    for (const check of this.data.checks) results.push(await evaluate(check, run, cwd));
    this.data.results = results;
    this.data.checkedAt = Date.now();
    // A later edit makes this run stale again; until then nothing new needs grading.
    this.changed = false;
    this.setThisTurn = false;
    const failed = results.filter((r) => !r.ok);
    if (!failed.length) {
      // A pass is reported with the test files this turn changed, when it changed any: the pass may rest on them.
      const edited = [...this.changedFiles].filter(isTestFile);
      this.data.testsEdited = edited.length ? edited : undefined;
      this.update('passed');
      const passed = `\n\n✓ Completion check passed: ${results.map((r) => describeCheck(r.check)).join('; ')}.`;
      return {
        end: edited.length
          ? `${passed} This task also changed test files (${edited.join(', ')}), so the pass may rest on those edits — review them.\n`
          : `${passed}\n`,
      };
    }
    this.data.attempts++;
    const max = this.maxRetries();
    const lines = failed.map((r) => `- ${describeCheck(r.check)} — ${r.detail}`).join('\n');
    this.update('failed');
    if (this.data.attempts <= max) {
      return {
        continue: `[Completion check] The check did not pass, so the task is not done (attempt ${this.data.attempts} of ${max + 1}):\n${lines}\n`
          + 'Find and fix the cause, then finish again; Bimax will rerun the check. Do not change or skip the check, or edit the '
          + 'tests it runs, to make it pass; if a test itself is wrong, say so to the user instead.',
      };
    }
    return { end: `\n\n✕ Completion check failed ${this.data.attempts} time${this.data.attempts === 1 ? '' : 's'}, so this task is not done:\n${lines}\n` };
  }

  private update(state: CheckState): void {
    this.data.state = state;
    this.save();
    this.publish();
  }

  private publish(): void {
    try { engineEvents.emit('completion_check', this.snapshot()); } catch { /* best-effort */ }
  }

  private file(id: string): string { return path.join(this.directory(), `${id}.checks.json`); }

  private save(): void {
    if (!this.data.sessionId) return;
    try {
      fs.mkdirSync(this.directory(), { recursive: true });
      const target = this.file(this.data.sessionId);
      const temporary = `${target}.${process.pid}.tmp`;
      fs.writeFileSync(temporary, JSON.stringify(this.data, null, 2), 'utf8');
      fs.renameSync(temporary, target);
    } catch { /* persistence must never break a live turn */ }
  }

  private load(id: string): Stored {
    try {
      const parsed = JSON.parse(fs.readFileSync(this.file(id), 'utf8')) as Partial<Stored>;
      const checks = parseChecks(parsed.checks);
      const states: CheckState[] = ['none', 'unchecked', 'pending', 'passed', 'failed'];
      return {
        version: 1,
        sessionId: id,
        checks: 'checks' in checks ? checks.checks : [],
        ...(typeof parsed.skipped === 'string' ? { skipped: parsed.skipped } : {}),
        state: states.includes(parsed.state as CheckState) ? parsed.state as CheckState : 'none',
        results: Array.isArray(parsed.results) ? parsed.results : [],
        attempts: 0,
        ...(typeof parsed.checkedAt === 'number' ? { checkedAt: parsed.checkedAt } : {}),
        ...(Array.isArray(parsed.testsEdited) && parsed.testsEdited.length ? { testsEdited: parsed.testsEdited.map(String) } : {}),
      };
    } catch { return empty(id); }
  }
}

let runtime: CompletionChecks | null = null;

/** The root engine's checks (headless entry). Workers and tests without it get null, and the loop skips checks. */
export function startCompletionChecks(): CompletionChecks {
  if (runtime) return runtime;
  runtime = new CompletionChecks({
    configuredRetries: () => {
      try { return (require('../engine/config') as typeof import('../engine/config')).getConfig().taskCheckRetries; } catch { return undefined; }
    },
  });
  engineEvents.on('session_changed', () => runtime?.syncSession());
  runtime.syncSession();
  return runtime;
}

export function getCompletionChecks(): CompletionChecks | null { return runtime; }

/** Test seam: do not use in production code. */
export function __setCompletionChecks(value: CompletionChecks | null): void { runtime = value; }

import * as crypto from 'crypto';
import * as fs from 'fs';
import * as path from 'path';
import { engineEvents } from '../engine/events';
import { getSessionRecorder } from '../engine/session.recorder';
import { sessionDir } from '../engine/session';
import {
  CompletionGate,
  CriterionStatus,
  EvidenceKind,
  OutcomeContract,
  OutcomeContinuation,
  OutcomeAssignmentReceipt,
  OutcomeCriterion,
  OutcomeEvidence,
  OutcomeGap,
  OutcomePhase,
  OutcomeTask,
  OutcomeTaskStatus,
  completionGate,
  createContract,
  slugId,
  toOutcomeSnapshot,
  validateTaskGraph,
} from './outcome.model';
import { computeAdaptiveSchedule } from './adaptive.scheduler';
import type { SubAgentResultEnvelope } from '../core/subagent.result';
import { inspectWorktreeChanges, integrateWorktree } from '../core/worktree.manager';
import { requiresBuildVerification } from '../review/verification.scope';

type CriterionInput = string | Partial<OutcomeCriterion>;
type TaskInput = Pick<OutcomeTask, 'title'> & Partial<Omit<OutcomeTask, 'title'>>;

function randomId(prefix: string): string {
  return `${prefix}-${crypto.randomBytes(4).toString('hex')}`;
}

/**
 * Per-session persistent outcome runtime. It binds the existing todo/review/checkpoint event seams
 * into one contract and publishes a compact full snapshot for every front-end.
 */
export class OutcomeManager {
  private contract: OutcomeContract | null = null;
  private emitTimer: ReturnType<typeof setTimeout> | null = null;
  private saveTimer: ReturnType<typeof setTimeout> | null = null;
  private touchedThisTurn = false;

  constructor(private readonly io: {
    sessionId?: () => string;
    directory?: () => string;
    silent?: boolean;
  } = {}) {}

  private sessionId(): string {
    return this.io.sessionId?.() || getSessionRecorder()?.currentId() || '';
  }

  private directory(): string {
    return this.io.directory?.() || sessionDir();
  }

  private filePath(sessionId: string): string {
    return path.join(this.directory(), `${sessionId}.outcome.json`);
  }

  syncSession(): void {
    const sessionId = this.sessionId();
    if (!sessionId) {
      this.contract = null;
      this.publishNow();
      return;
    }
    if (this.contract?.sessionId === sessionId) return;
    this.saveNow();
    this.contract = this.load(sessionId);
    this.publishNow();
  }

  current(): OutcomeContract | null {
    return this.contract ? JSON.parse(JSON.stringify(this.contract)) : null;
  }

  snapshot() {
    if (!this.contract) return null;
    return { ...toOutcomeSnapshot(this.contract), schedule: computeAdaptiveSchedule(this.contract) };
  }

  schedule(maxParallel = 4) {
    return this.contract ? computeAdaptiveSchedule(this.contract, maxParallel) : null;
  }

  task(id: string): OutcomeTask | null {
    const task = this.contract?.tasks.find(item => item.id === id);
    return task ? JSON.parse(JSON.stringify(task)) : null;
  }

  activeSessionId(): string { return this.contract?.sessionId || ''; }

  /** Turn boundary: retain the durable contract but reset whether this user turn actively used it. */
  beginTurn(): void { this.touchedThisTurn = false; }

  wasTouchedThisTurn(): boolean { return this.touchedThisTurn; }

  /**
   * Persistence nudge for AgentLoop. Empty means it is honest to return control to the user. A
   * user-required blocker is terminal for this turn; everything else keeps converging.
   */
  continuationPrompt(): string {
    const contract = this.contract;
    if (!contract || !this.touchedThisTurn) return '';
    if (contract.phase === 'blocked' && contract.blocker?.requiresUser) return '';
    const gate = completionGate(contract);
    if (gate.allowed && contract.phase === 'verified') return '';
    if (gate.allowed) {
      return 'The outcome completion gate is now OPEN, but you stopped before recording the verified terminal state. Call OutcomeTool(action:"finish", finish_status:"verified"), then give the user the evidence-backed result.';
    }
    return [
      'You stopped, but the engine-owned outcome contract is still incomplete:',
      ...gate.reasons.slice(0, 8).map(reason => `- ${reason}`),
      'Continue with the highest-value action that closes these gaps. Change strategy if the previous approach stalled. Do not claim completion while the gate is closed; if a genuine external blocker requires the user, record it with OutcomeTool and explain it precisely.',
    ].join('\n');
  }

  /** Compact dynamic prompt block so the model cannot forget the contract after context compaction. */
  getPromptBlock(): string {
    const contract = this.contract;
    const snapshot = this.snapshot();
    if (!contract || !snapshot) return '';
    const criteria = contract.criteria.map(c =>
      `- [${c.status === 'passed' ? 'x' : c.status === 'failed' ? '!' : c.status === 'blocked' ? 'b' : ' '}] [${c.id}] ${c.description}`
    );
    const active = contract.tasks
      .filter(t => t.status !== 'verified' && !(t.status === 'completed' && !t.owner))
      .slice(0, 12)
      .map(t => `- [${t.status}] [${t.id}] ${t.title}${t.owner ? ` · owner ${t.owner}` : ''}${t.assignment?.integrationStatus === 'pending' ? ' · INTEGRATION PENDING' : ''}`);
    const schedule = computeAdaptiveSchedule(contract);
    const reports = contract.evidence.filter(e => e.provenance === 'subagent').slice(-4)
      .map(e => `- ${e.source || 'sub-agent'}: ${e.ok ? 'reported complete' : 'reported failure'} — ${e.summary.slice(0, 500)}`);
    return [
      `### ACTIVE OUTCOME CONTRACT — LOOP ${contract.iteration}`,
      `Objective: ${contract.objective}`,
      `Completion gate: ${snapshot.canComplete ? 'OPEN' : 'CLOSED'} · ${snapshot.passed}/${snapshot.required} required criteria passed · ${snapshot.openGaps} gap(s)`,
      ...criteria,
      ...(active.length ? ['Open tasks:', ...active] : []),
      `Scheduler: ${schedule.activeAgents} agent(s) active · ${schedule.parallelTasks} safe dispatch slot(s) · critical ${schedule.criticalTaskId || 'none'}`,
      ...(schedule.dispatchTaskIds.length ? [`Dispatch now: ${schedule.dispatchTaskIds.join(', ')}`] : []),
      ...(reports.length ? ['Recent sub-agent reports (UNTRUSTED until parent verification):', ...reports] : []),
      `Next: ${snapshot.nextAction}`,
      'Use OutcomeTool to keep this contract current. Do not claim verified completion while the gate is CLOSED.',
    ].join('\n');
  }

  define(objective: string, criteria: CriterionInput[]): OutcomeContract {
    const sessionId = this.sessionId() || this.contract?.sessionId || '';
    if (!sessionId) throw new Error('No active session yet — define the outcome after the user task begins.');
    if (!String(objective || '').trim()) throw new Error('Outcome objective is required.');
    if (!Array.isArray(criteria) || criteria.length === 0) throw new Error('At least one acceptance criterion is required.');
    this.contract = createContract(sessionId, objective, criteria);
    this.touch();
    return this.current()!;
  }

  setTasks(inputs: TaskInput[]): OutcomeTask[] {
    const contract = this.requireContract();
    const at = Date.now();
    const seen = new Set<string>();
    const tasks = (inputs || []).map((input, index): OutcomeTask => {
      let id = slugId(String(input.id || input.title), `task-${index + 1}`);
      for (let n = 2; seen.has(id); n++) id = `${slugId(id, 'task')}-${n}`;
      seen.add(id);
      return {
        id,
        title: String(input.title || '').trim(),
        status: input.status === 'verified' ? 'completed' : input.status || 'pending',
        required: input.required !== false,
        dependsOn: Array.isArray(input.dependsOn) ? [...new Set(input.dependsOn.map(String))] : [],
        owner: input.owner ? String(input.owner) : undefined,
        criterionIds: Array.isArray(input.criterionIds) ? [...new Set(input.criterionIds.map(String))] : [],
        evidenceIds: Array.isArray(input.evidenceIds) ? [...new Set(input.evidenceIds.map(String))] : [],
        scope: input.scope ? String(input.scope) : undefined,
        mutates: input.mutates !== false,
        execution: input.execution || 'either',
        estimateMs: Math.max(1, Number(input.estimateMs) || 60_000),
        priority: Number(input.priority) || 0,
        isolation: input.isolation === 'worktree' ? 'worktree' : undefined,
        attempts: Math.max(0, Number(input.attempts) || 0),
        maxAttempts: Math.max(1, Number(input.maxAttempts) || 3),
        assignment: input.assignment,
        updatedAt: at,
      };
    }).filter(t => t.title);
    const errors = validateTaskGraph(tasks);
    if (errors.length) throw new Error(errors.join(' '));
    contract.tasks = tasks;
    contract.phase = tasks.length ? 'planning' : contract.phase;
    this.touch();
    return this.current()!.tasks;
  }

  updateTask(id: string, status: OutcomeTaskStatus, owner?: string): OutcomeTask {
    const contract = this.requireContract();
    const task = contract.tasks.find(t => t.id === id);
    if (!task) throw new Error(`Unknown outcome task: ${id}`);
    if (status === 'verified') return this.validateTask(id);
    if (status === 'in_progress') {
      const incomplete = task.dependsOn.filter(dep => {
        const d = contract.tasks.find(t => t.id === dep);
        return !d || (d.status !== 'verified' && (d.status !== 'completed' || !!d.owner));
      });
      if (incomplete.length) throw new Error(`Task ${id} is waiting on: ${incomplete.join(', ')}`);
    }
    task.status = status;
    if (owner !== undefined) task.owner = owner || undefined;
    task.updatedAt = Date.now();
    if (status === 'in_progress') contract.phase = 'executing';
    if (status === 'blocked') contract.phase = 'blocked';
    if (status === 'failed') contract.phase = 'failed';
    this.touch();
    return { ...task, dependsOn: [...task.dependsOn], criterionIds: [...task.criterionIds] };
  }

  /** Claim one scheduler-approved task for a concrete worker. */
  assignTask(id: string, owner: string, maxParallel = 4): OutcomeTask {
    const task = this.task(id);
    if (!task) throw new Error(`Unknown outcome task: ${id}`);
    if (task.status !== 'pending') throw new Error(`Task ${id} is ${task.status}, not pending.`);
    if (task.execution === 'local') throw new Error(`Task ${id} is reserved for local execution.`);
    const schedule = this.schedule(maxParallel);
    if (!schedule?.dispatchTaskIds.includes(id)) {
      const waiting = task.dependsOn.filter(dep => {
        const item = this.contract?.tasks.find(candidate => candidate.id === dep);
        return !item || (item.status !== 'verified' && (item.status !== 'completed' || !!item.owner));
      });
      if (waiting.length) throw new Error(`Task ${id} is waiting on: ${waiting.join(', ')}`);
      throw new Error(`Task ${id} is not in the current safe dispatch set (${schedule?.dispatchTaskIds.join(', ') || 'empty'}).`);
    }
    const live = this.requireContract().tasks.find(item => item.id === id)!;
    if (live.attempts >= live.maxAttempts) throw new Error(`Task ${id} exhausted its ${live.maxAttempts} attempt(s).`);
    live.attempts++;
    delete live.recovery;
    const assigned = this.updateTask(id, 'in_progress', owner);
    this.saveNow();
    return assigned;
  }

  /** Rebind a checkpointed assignment without charging a second attempt for the same interrupted run. */
  assertAssignmentRecoverable(id: string, previousOwner: string, maxParallel = 4): void {
    const task = this.task(id);
    if (!task) throw new Error(`Unknown outcome task: ${id}`);
    if (task.status === 'pending') {
      if (task.execution === 'local') throw new Error(`Task ${id} is reserved for local execution.`);
      const schedule = this.schedule(maxParallel);
      if (!schedule?.dispatchTaskIds.includes(id)) {
        throw new Error(`Task ${id} is not in the current safe dispatch set (${schedule?.dispatchTaskIds.join(', ') || 'empty'}).`);
      }
      if (task.attempts >= task.maxAttempts) throw new Error(`Task ${id} exhausted its ${task.maxAttempts} attempt(s).`);
      return;
    }
    if (task.status !== 'in_progress') throw new Error(`Task ${id} is ${task.status}, not recoverable.`);
    if (task.owner !== previousOwner) throw new Error(`Task ${id} is owned by ${task.owner || 'nobody'}, not crashed worker ${previousOwner}.`);
  }

  /** Rebind a checkpointed assignment without charging a second attempt for the same interrupted run. */
  resumeAssignment(id: string, previousOwner: string, newOwner: string, maxParallel = 4): OutcomeTask {
    const contract = this.requireContract();
    const task = contract.tasks.find(item => item.id === id);
    this.assertAssignmentRecoverable(id, previousOwner, maxParallel);
    if (!task) throw new Error(`Unknown outcome task: ${id}`);
    if (task.status === 'pending') return this.assignTask(id, newOwner, maxParallel);
    task.owner = newOwner;
    task.updatedAt = Date.now();
    task.recovery = { state: 'resumed', previousOwner, resumedAt: task.updatedAt };
    contract.iteration++;
    contract.phase = 'executing';
    this.touch();
    this.saveNow();
    return { ...task, dependsOn: [...task.dependsOn], criterionIds: [...task.criterionIds], evidenceIds: [...task.evidenceIds] };
  }

  retryTask(id: string): OutcomeTask {
    const contract = this.requireContract();
    const task = contract.tasks.find(item => item.id === id);
    if (!task) throw new Error(`Unknown outcome task: ${id}`);
    if (task.status !== 'failed' && task.status !== 'blocked') throw new Error(`Task ${id} is ${task.status}, not retryable.`);
    if (task.attempts >= task.maxAttempts) throw new Error(`Task ${id} exhausted its ${task.maxAttempts} attempt(s); change the graph or record a genuine blocker.`);
    contract.iteration++;
    return this.updateTask(id, 'pending', '');
  }

  /** A worker report completes execution, never verification; parent evidence still gates outcome. */
  settleAssignment(id: string, owner: string, ok: boolean, report: string | SubAgentResultEnvelope): OutcomeTask {
    const task = this.task(id);
    if (!task) throw new Error(`Unknown outcome task: ${id}`);
    if (task.owner && task.owner !== owner) throw new Error(`Task ${id} is owned by ${task.owner}, not ${owner}.`);
    const summary = typeof report === 'string' ? report : report.report;
    this.addEvidence({
      kind: 'agent_report',
      summary: String(summary || (ok ? 'Sub-agent completed.' : 'Sub-agent failed.')).slice(0, 2000),
      source: owner,
      ok,
      criterionIds: [],
      provenance: 'subagent',
      trusted: false,
    });
    if (typeof report !== 'string') {
      const live = this.requireContract().tasks.find(item => item.id === id)!;
      live.assignment = {
        version: 1,
        agentTaskId: report.taskId,
        report: report.report,
        claimedScope: report.claimedScope,
        observedChangedFiles: [...report.observedChangedFiles],
        startedAt: report.startedAt,
        endedAt: report.endedAt,
        toolCalls: report.toolCalls,
        integrationStatus: report.isolation && report.observedChangedFiles.length ? 'pending' : 'not_required',
        ...(report.isolation ? { isolation: {
          kind: 'worktree' as const,
          repoRoot: report.isolation.repoRoot,
          path: report.isolation.path,
          branch: report.isolation.branch,
          baseCommit: report.isolation.baseCommit,
        } } : {}),
      };
    }
    const settled = this.updateTask(id, ok ? 'completed' : 'failed', owner);
    this.requestContinuation([id], 'assignment_settled');
    this.saveNow();
    return settled;
  }

  /** Persist and publish a parent-coordinator wake-up without trusting the worker report. */
  requestContinuation(
    taskIds: string[] = [],
    reason: OutcomeContinuation['reason'] = 'outcome_incomplete',
  ): OutcomeContinuation {
    const contract = this.requireContract();
    const previous = contract.continuation;
    const at = Date.now();
    contract.continuation = {
      state: 'pending',
      revision: (previous?.revision || 0) + 1,
      taskIds: [...new Set([...(previous?.state === 'pending' || previous?.state === 'running' ? previous.taskIds : []), ...taskIds])],
      reason,
      requestedAt: at,
      wakeups: previous?.wakeups || 0,
      consecutiveNoProgress: previous?.consecutiveNoProgress || 0,
      lastWakeAt: previous?.lastWakeAt,
      lastError: previous?.lastError,
    };
    this.touch();
    this.saveNow();
    if (!this.io.silent) {
      engineEvents.emit('outcome_continuation_requested', {
        sessionId: contract.sessionId,
        revision: contract.continuation.revision,
        taskIds: [...contract.continuation.taskIds],
        reason,
      });
    }
    return JSON.parse(JSON.stringify(contract.continuation));
  }

  continuation(): OutcomeContinuation | null {
    const value = this.contract?.continuation;
    return value ? JSON.parse(JSON.stringify(value)) : null;
  }

  /** Atomically lease one durable coordinator wake. A crashed running lease becomes reclaimable. */
  claimContinuation(maxWakeups = 24, leaseMs = 10 * 60_000, now = Date.now()): OutcomeContinuation | null {
    const contract = this.requireContract();
    const continuation = contract.continuation;
    if (!continuation || continuation.state === 'idle' || continuation.state === 'halted') return null;
    if (continuation.state === 'running' && now - (continuation.lastWakeAt || now) < leaseMs) return null;
    if (continuation.wakeups >= maxWakeups || continuation.consecutiveNoProgress >= 3) {
      continuation.state = 'halted';
      continuation.lastError ||= continuation.consecutiveNoProgress >= 3
        ? 'Coordinator made no measurable outcome progress in three consecutive wakes.'
        : `Coordinator reached its ${maxWakeups}-wake circuit breaker.`;
      this.touch();
      this.saveNow();
      return null;
    }
    continuation.state = 'running';
    continuation.claimedRevision = continuation.revision;
    continuation.wakeups++;
    continuation.lastWakeAt = now;
    delete continuation.lastError;
    this.touch();
    this.saveNow();
    return JSON.parse(JSON.stringify(continuation));
  }

  /** Finish a wake while preserving any newer result queued during the coordinator turn. */
  completeContinuation(claimedRevision: number, progress: boolean, error?: string): OutcomeContinuation | null {
    const contract = this.requireContract();
    const continuation = contract.continuation;
    if (!continuation) return null;
    continuation.consecutiveNoProgress = progress ? 0 : continuation.consecutiveNoProgress + 1;
    if (error) continuation.lastError = error.slice(0, 1000);
    if (continuation.revision > claimedRevision) continuation.state = 'pending';
    else continuation.state = continuation.consecutiveNoProgress >= 3 ? 'halted' : 'idle';
    continuation.claimedRevision = undefined;
    this.touch();
    this.saveNow();
    return JSON.parse(JSON.stringify(continuation));
  }

  /** Facts that change only when real outcome work progressed, excluding continuation bookkeeping. */
  progressFingerprint(): string {
    const contract = this.requireContract();
    return JSON.stringify({
      phase: contract.phase,
      iteration: contract.iteration,
      lastMutationAt: contract.lastMutationAt,
      criteria: contract.criteria.map(item => [item.id, item.status, item.updatedAt, item.evidenceIds]),
      tasks: contract.tasks.map(item => [item.id, item.status, item.owner, item.updatedAt, item.attempts, item.assignment?.integrationStatus]),
      evidence: contract.evidence.map(item => [item.id, item.ok, item.trusted, item.at]),
      gaps: contract.gaps.map(item => [item.id, item.resolved, item.updatedAt]),
      blocker: contract.blocker,
    });
  }

  /** Settle the assignment in the session that spawned it, even if the UI switched threads. */
  settleAssignmentForSession(sessionId: string, id: string, owner: string, ok: boolean, report: string | SubAgentResultEnvelope): OutcomeTask {
    if (!sessionId) throw new Error('Outcome session id is required for session-bound settlement.');
    if (this.contract?.sessionId === sessionId) return this.settleAssignment(id, owner, ok, report);
    const detached = new OutcomeManager({ sessionId: () => sessionId, directory: () => this.directory(), silent: true });
    detached.syncSession();
    try {
      const settled = detached.settleAssignment(id, owner, ok, report);
      detached.saveNow();
      return settled;
    } finally {
      detached.shutdown();
    }
  }

  /** Promote a completion only after fresh, trusted parent-side verification exists. */
  validateTask(id: string, evidenceIds: string[] = []): OutcomeTask {
    const contract = this.requireContract();
    const task = contract.tasks.find(item => item.id === id);
    if (!task) throw new Error(`Unknown outcome task: ${id}`);
    if (task.status !== 'completed') throw new Error(`Task ${id} must be completed before validation (currently ${task.status}).`);
    if (task.assignment?.integrationStatus === 'pending') throw new Error(`Task ${id} has isolated changes pending integration.`);
    if (task.assignment?.integrationStatus === 'conflict') throw new Error(`Task ${id} has an unresolved integration conflict.`);
    const requested = new Set(evidenceIds);
    const candidates = contract.evidence.filter(evidence => {
      if (!evidence.trusted || !evidence.ok || evidence.at < task.updatedAt) return false;
      if (requested.size && !requested.has(evidence.id)) return false;
      return task.criterionIds.length === 0 || evidence.criterionIds.some(id => task.criterionIds.includes(id));
    });
    if (!candidates.length) throw new Error(`Task ${id} has no fresh trusted parent verification.${task.assignment?.observedChangedFiles.length ? ' Missing verification covering: ' + task.assignment.observedChangedFiles.join(', ') : ''}`);
    const requiredFiles = (task.assignment?.observedChangedFiles || []).filter(requiresBuildVerification);
    if (requiredFiles.length) {
      const repoWide = candidates.some(evidence => evidence.repoWide === true);
      const covered = new Set(candidates.flatMap(evidence => evidence.coveredFiles || []).map(file => path.resolve(file)));
      const missing = repoWide ? [] : requiredFiles.filter(file => !covered.has(path.resolve(file)));
      if (missing.length) throw new Error(`Task ${id} has no fresh trusted verification covering: ${missing.join(', ')}`);
    }
    task.evidenceIds = [...new Set([...(task.evidenceIds || []), ...candidates.map(evidence => evidence.id)])];
    task.status = 'verified';
    task.updatedAt = Date.now();
    this.touch();
    return this.task(id)!;
  }

  /** Verify that reviewed isolated files now exactly match the parent checkout. Does not merge. */
  confirmTaskIntegration(id: string): OutcomeAssignmentReceipt {
    const contract = this.requireContract();
    const task = contract.tasks.find(item => item.id === id);
    if (!task) throw new Error(`Unknown outcome task: ${id}`);
    const receipt = task.assignment;
    if (!receipt) throw new Error(`Task ${id} has no structured assignment receipt.`);
    if (receipt.integrationStatus === 'not_required' || receipt.integrationStatus === 'integrated') return { ...receipt };
    if (!receipt.isolation) throw new Error(`Task ${id} has no isolated worktree receipt.`);

    const fail = (message: string): never => {
      receipt.integrationStatus = 'conflict';
      task.updatedAt = Date.now();
      this.touch();
      this.saveNow();
      throw new Error(message);
    };
    let currentManifest: string[];
    try {
      currentManifest = inspectWorktreeChanges({
        repoRoot: receipt.isolation.repoRoot,
        path: receipt.isolation.path,
        branch: receipt.isolation.branch,
        baseCommit: receipt.isolation.baseCommit,
      });
    } catch (error: any) {
      return fail(`Cannot reinspect task ${id}'s worktree: ${error?.message || error}`);
    }
    const expected = [...receipt.observedChangedFiles].sort();
    if (JSON.stringify(currentManifest) !== JSON.stringify(expected)) {
      return fail(`Task ${id}'s worktree changed after settlement; review it again before integration.`);
    }

    const mismatches = expected.filter(relative => {
      const parentFile = path.join(receipt.isolation!.repoRoot, relative);
      const workerFile = path.join(receipt.isolation!.path, relative);
      const parentExists = fs.existsSync(parentFile);
      const workerExists = fs.existsSync(workerFile);
      if (parentExists !== workerExists) return true;
      if (!parentExists) return false;
      try { return !fs.readFileSync(parentFile).equals(fs.readFileSync(workerFile)); }
      catch { return true; }
    });
    if (mismatches.length) return fail(`Task ${id} is not integrated in the parent checkout: ${mismatches.join(', ')}`);

    const at = Date.now();
    receipt.integrationStatus = 'integrated';
    receipt.integratedAt = at;
    task.updatedAt = at;
    contract.lastMutationAt = at;
    for (const criterion of contract.criteria) {
      if (criterion.requiresFreshEvidence && criterion.status === 'passed') {
        criterion.status = 'pending';
        criterion.updatedAt = at;
      }
    }
    contract.phase = 'executing';
    this.touch();
    this.saveNow();
    return JSON.parse(JSON.stringify(receipt));
  }

  /** Safely commit, merge, verify, and clean up an isolated delegated assignment. */
  integrateTask(id: string): OutcomeAssignmentReceipt {
    const contract = this.requireContract();
    const task = contract.tasks.find(item => item.id === id);
    if (!task) throw new Error(`Unknown outcome task: ${id}`);
    const receipt = task.assignment;
    if (!receipt?.isolation) throw new Error(`Task ${id} has no isolated worktree receipt.`);
    if (receipt.integrationStatus === 'integrated') return JSON.parse(JSON.stringify(receipt));
    if (receipt.integrationStatus === 'not_required') throw new Error(`Task ${id} does not require integration.`);

    try {
      const result = integrateWorktree(
        receipt.isolation,
        receipt.observedChangedFiles,
        task.scope || receipt.claimedScope,
        id,
      );
      receipt.integrationStatus = 'integrated';
      receipt.integratedAt = result.integratedAt;
      receipt.integrationCommit = result.commit;
      task.updatedAt = result.integratedAt;
      contract.lastMutationAt = result.integratedAt;
      for (const criterion of contract.criteria) {
        if (criterion.requiresFreshEvidence && criterion.status === 'passed') {
          criterion.status = 'pending';
          criterion.updatedAt = result.integratedAt;
        }
      }
      contract.phase = 'executing';
      for (const file of result.paths) engineEvents.emit('review_change', { tool: 'SubAgentIntegration', file });
      this.touch();
      this.saveNow();
      return JSON.parse(JSON.stringify(receipt));
    } catch (error) {
      receipt.integrationStatus = 'conflict';
      task.updatedAt = Date.now();
      this.touch();
      this.saveNow();
      throw error;
    }
  }

  addEvidence(input: {
    kind: EvidenceKind;
    summary: string;
    source?: string;
    ok: boolean;
    criterionIds?: string[];
    provenance?: OutcomeEvidence['provenance'];
    trusted?: boolean;
    coveredFiles?: string[];
    repoWide?: boolean;
  }): OutcomeEvidence {
    const contract = this.requireContract();
    const criterionIds = [...new Set((input.criterionIds || []).map(String))];
    const unknown = criterionIds.filter(id => !contract.criteria.some(c => c.id === id));
    if (unknown.length) throw new Error(`Unknown criteria: ${unknown.join(', ')}`);
    const evidence: OutcomeEvidence = {
      id: randomId('evidence'),
      kind: input.kind,
      summary: String(input.summary || '').trim(),
      source: input.source ? String(input.source) : undefined,
      ok: !!input.ok,
      provenance: input.provenance || 'model',
      trusted: input.trusted === true,
      criterionIds,
      ...(Array.isArray(input.coveredFiles) ? { coveredFiles: [...new Set(input.coveredFiles.map(String))].sort() } : {}),
      ...(input.repoWide !== undefined ? { repoWide: input.repoWide === true } : {}),
      at: Date.now(),
    };
    if (!evidence.summary) throw new Error('Evidence summary is required.');
    contract.evidence.push(evidence);
    if (contract.evidence.length > 200) contract.evidence.splice(0, contract.evidence.length - 200);
    for (const criterion of contract.criteria.filter(c => criterionIds.includes(c.id))) {
      if (!criterion.evidenceIds.includes(evidence.id)) criterion.evidenceIds.push(evidence.id);
      if (evidence.trusted) criterion.status = evidence.ok ? 'passed' : 'failed';
      criterion.updatedAt = evidence.at;
    }
    contract.phase = 'verifying';
    this.touch();
    return { ...evidence, criterionIds: [...evidence.criterionIds] };
  }

  setCriterion(id: string, status: CriterionStatus, evidenceIds: string[] = []): OutcomeCriterion {
    const contract = this.requireContract();
    const criterion = contract.criteria.find(c => c.id === id);
    if (!criterion) throw new Error(`Unknown acceptance criterion: ${id}`);
    const known = new Set(contract.evidence.map(e => e.id));
    const unknownEvidence = evidenceIds.filter(e => !known.has(e));
    if (unknownEvidence.length) throw new Error(`Unknown evidence: ${unknownEvidence.join(', ')}`);
    criterion.status = status;
    criterion.evidenceIds = [...new Set([...criterion.evidenceIds, ...evidenceIds])];
    criterion.updatedAt = Date.now();
    this.touch();
    return { ...criterion, evidenceIds: [...criterion.evidenceIds] };
  }

  setGaps(gaps: Array<Pick<OutcomeGap, 'description'> & Partial<OutcomeGap>>): OutcomeGap[] {
    const contract = this.requireContract();
    const at = Date.now();
    contract.gaps = (gaps || []).map((gap, index) => ({
      id: slugId(String(gap.id || gap.description), `gap-${index + 1}`),
      description: String(gap.description || '').trim(),
      criterionId: gap.criterionId ? String(gap.criterionId) : undefined,
      resolved: !!gap.resolved,
      updatedAt: at,
    })).filter(g => g.description);
    this.touch();
    return this.current()!.gaps;
  }

  setBlocker(description: string, attempted: string[] = [], requiresUser = false): void {
    const contract = this.requireContract();
    const text = String(description || '').trim();
    contract.blocker = text ? {
      description: text,
      attempted: (attempted || []).map(String).filter(Boolean).slice(0, 20),
      requiresUser: !!requiresUser,
      at: Date.now(),
    } : undefined;
    contract.phase = text ? 'blocked' : 'executing';
    this.touch();
  }

  advanceIteration(): number {
    const contract = this.requireContract();
    contract.iteration++;
    if (contract.phase === 'failed' || contract.phase === 'blocked') contract.phase = 'executing';
    contract.blocker = undefined;
    this.touch();
    return contract.iteration;
  }

  requestFinish(phase: 'verified' | 'partially_verified' | 'blocked' | 'failed', detail?: string): CompletionGate {
    const contract = this.requireContract();
    const gate = completionGate(contract);
    if (phase === 'verified' && !gate.allowed) {
      contract.phase = 'verifying';
      this.touch();
      return gate;
    }
    contract.phase = phase;
    if (phase === 'verified') contract.verifiedAt ||= Date.now();
    if (phase === 'blocked' && detail) this.setBlocker(detail, [], true);
    else this.touch();
    return gate;
  }

  /** Existing review truth: any mutation invalidates freshness-dependent passing criteria. */
  onMutation(): void {
    if (!this.contract) return;
    const at = Date.now();
    this.contract.lastMutationAt = at;
    for (const criterion of this.contract.criteria) {
      if (criterion.requiresFreshEvidence && criterion.status === 'passed') {
        criterion.status = 'pending';
        criterion.updatedAt = at;
      }
    }
    this.contract.phase = 'executing';
    this.touch();
  }

  /** Existing build/test evidence automatically covers criteria that explicitly request it. */
  onBuildEvidence(event: { command?: string; ok?: boolean; coveredFiles?: string[]; repoWide?: boolean }): void {
    if (!this.contract || !event?.command) return;
    const covered = new Set((event.coveredFiles || []).map(file => path.resolve(file)));
    const ids = this.contract.criteria.filter(c => c.verification === 'build_test' && (
      event.repoWide === true || (c.files?.length && c.files.every(file => covered.has(path.resolve(file))))
    )).map(c => c.id);
    if (!ids.length) return;
    this.addEvidence({
      kind: 'test', summary: String(event.command), source: String(event.command), ok: !!event.ok,
      criterionIds: ids, provenance: 'engine', trusted: true,
      coveredFiles: event.coveredFiles, repoWide: event.repoWide,
    });
  }

  /** Native browser receipts automatically cover criteria that explicitly request visual proof. */
  onBrowserEvidence(event: { action?: string; ok?: boolean; trusted?: boolean; source?: string; summary?: string }): void {
    if (!this.contract || !event?.action) return;
    const ids = this.contract.criteria.filter(c => c.verification === 'visual' || c.verification === 'runtime').map(c => c.id);
    if (!ids.length) return;
    this.addEvidence({
      kind: event.action === 'screenshot' ? 'screenshot' : 'browser',
      summary: String(event.summary || `Browser ${event.action}`),
      source: event.source ? String(event.source) : 'BrowserTool',
      ok: !!event.ok,
      criterionIds: ids,
      provenance: 'engine',
      // A screenshot is a durable artifact, not a semantic comparison. Deterministic assertions
      // and exact visual-baseline comparisons may open the gate without user confirmation.
      trusted: event.trusted === true,
    });
  }

  /** Reuse the existing TodoWrite list as task state when an explicit dependency graph is absent. */
  onTodos(todos: unknown): void {
    if (!this.contract || this.contract.tasks.some(t => t.dependsOn.length > 0 || t.owner)) return;
    if (!Array.isArray(todos)) return;
    const at = Date.now();
    this.contract.tasks = todos.map((todo: any, index): OutcomeTask => ({
      id: slugId(String(todo?.content || ''), `task-${index + 1}`),
      title: String(todo?.content || '').trim(),
      status: todo?.status === 'completed' ? 'completed' : todo?.status === 'in_progress' ? 'in_progress' : 'pending',
      required: true,
      dependsOn: [],
      criterionIds: [],
      evidenceIds: [],
      mutates: true,
      execution: 'either',
      estimateMs: 60_000,
      priority: 0,
      attempts: 0,
      maxAttempts: 3,
      updatedAt: at,
    })).filter(t => t.title);
    if (this.contract.tasks.some(t => t.status === 'in_progress')) this.contract.phase = 'executing';
    this.touch();
  }

  saveNow(): void {
    if (this.saveTimer) { clearTimeout(this.saveTimer); this.saveTimer = null; }
    if (!this.contract?.sessionId) return;
    let tmp = '';
    try {
      fs.mkdirSync(this.directory(), { recursive: true });
      const file = this.filePath(this.contract.sessionId);
      tmp = `${file}.tmp-${process.pid}-${crypto.randomBytes(4).toString('hex')}`;
      fs.writeFileSync(tmp, JSON.stringify(this.contract, null, 2), 'utf8');
      fs.renameSync(tmp, file);
    } catch { /* persistence must never break a live turn */ }
    finally { if (tmp) { try { fs.rmSync(tmp, { force: true }); } catch { /* best-effort */ } } }
  }

  shutdown(): void { this.saveNow(); }

  private requireContract(): OutcomeContract {
    if (!this.contract) throw new Error('No outcome contract is active. Define one first.');
    return this.contract;
  }

  private touch(): void {
    if (!this.contract) return;
    this.touchedThisTurn = true;
    this.contract.updatedAt = Date.now();
    this.schedulePublish();
    if (!this.saveTimer) {
      this.saveTimer = setTimeout(() => { this.saveTimer = null; this.saveNow(); }, 300);
      this.saveTimer.unref?.();
    }
  }

  private schedulePublish(): void {
    if (this.emitTimer) return;
    this.emitTimer = setTimeout(() => {
      this.emitTimer = null;
      this.publishNow();
    }, 50);
    this.emitTimer.unref?.();
  }

  private publishNow(): void {
    if (this.io.silent) return;
    engineEvents.emit('outcome_update', this.snapshot());
  }

  private load(sessionId: string): OutcomeContract | null {
    try {
      const parsed = JSON.parse(fs.readFileSync(this.filePath(sessionId), 'utf8'));
      if (!parsed || parsed.version !== 1 || !Array.isArray(parsed.criteria)) return null;
      return {
        ...parsed,
        version: 1,
        sessionId,
        objective: String(parsed.objective || ''),
        phase: parsed.phase as OutcomePhase,
        iteration: Math.max(1, Number(parsed.iteration) || 1),
        startedAt: Number(parsed.startedAt) || Date.now(),
        updatedAt: Number(parsed.updatedAt) || Date.now(),
        verifiedAt: Number(parsed.verifiedAt) || undefined,
        lastMutationAt: Number(parsed.lastMutationAt) || 0,
        criteria: parsed.criteria,
        tasks: Array.isArray(parsed.tasks) ? parsed.tasks.map((task: Partial<OutcomeTask>) => ({
          ...task,
          mutates: task.mutates !== false,
          execution: task.execution || 'either',
          estimateMs: Math.max(1, Number(task.estimateMs) || 60_000),
          priority: Number(task.priority) || 0,
          evidenceIds: Array.isArray(task.evidenceIds) ? task.evidenceIds : [],
          attempts: Math.max(0, Number(task.attempts) || 0),
          maxAttempts: Math.max(1, Number(task.maxAttempts) || 3),
          assignment: task.assignment,
          recovery: task.recovery,
        })) : [],
        evidence: Array.isArray(parsed.evidence) ? parsed.evidence.map((evidence: Partial<OutcomeEvidence>) => ({
          ...evidence,
          provenance: evidence.provenance || 'model',
          trusted: evidence.trusted === true,
        })) : [],
        gaps: Array.isArray(parsed.gaps) ? parsed.gaps : [],
        blocker: parsed.blocker,
        continuation: parsed.continuation && typeof parsed.continuation === 'object' ? {
          state: ['pending', 'running', 'idle', 'halted'].includes(parsed.continuation.state)
            ? parsed.continuation.state : 'pending',
          revision: Math.max(1, Number(parsed.continuation.revision) || 1),
          claimedRevision: Number(parsed.continuation.claimedRevision) || undefined,
          taskIds: Array.isArray(parsed.continuation.taskIds) ? parsed.continuation.taskIds.map(String) : [],
          reason: parsed.continuation.reason === 'assignment_settled' ? 'assignment_settled' : 'outcome_incomplete',
          requestedAt: Number(parsed.continuation.requestedAt) || Date.now(),
          wakeups: Math.max(0, Number(parsed.continuation.wakeups) || 0),
          consecutiveNoProgress: Math.max(0, Number(parsed.continuation.consecutiveNoProgress) || 0),
          lastWakeAt: Number(parsed.continuation.lastWakeAt) || undefined,
          lastError: parsed.continuation.lastError ? String(parsed.continuation.lastError) : undefined,
        } : undefined,
      };
    } catch { return null; }
  }
}

let manager: OutcomeManager | null = null;

export function startOutcomeManager(): OutcomeManager {
  if (manager) return manager;
  manager = new OutcomeManager();
  engineEvents.on('session_changed', () => manager?.syncSession());
  engineEvents.on('review_change', () => manager?.onMutation());
  engineEvents.on('review_evidence', (event: any) => manager?.onBuildEvidence(event));
  engineEvents.on('browser_evidence', (event: any) => manager?.onBrowserEvidence(event));
  engineEvents.on('todo_update', (todos: any) => manager?.onTodos(todos));
  engineEvents.on('shutdown', () => manager?.shutdown());
  manager.syncSession();
  return manager;
}

export function getOutcomeManager(): OutcomeManager {
  if (!manager) throw new Error('[OutcomeManager] not initialized — start the headless outcome runtime first.');
  return manager;
}

/** Test seam: do not use in production code. */
export function __setOutcomeManager(value: OutcomeManager | null): void { manager = value; }

import type { CatalogModelEntry, CatalogResultMsg, ProviderEntry } from './protocol';

/**
 * The provider + model catalogue behind protocol `catalogGet` / `providerSet`.
 *
 * Why this exists as a wire message rather than a static list in the front-end: a model id is only
 * meaningful against a provider. The curated catalogue in engine/models.ts is a *recommendation*,
 * while the provider's `/models` endpoint is what will actually be accepted, and the two disagree
 * constantly (NVIDIA lists ids it then 404s; a rotated catalogue silently orphans a saved pin).
 * A picker built from either one alone is wrong in a way the user cannot see, so both cross the
 * wire and the front-end shows the difference.
 *
 * Credential rule, enforced here rather than trusted to callers: a key value NEVER leaves this
 * module. `hasKey`, `keyCount`, and a 4-character display tail are the only things reported.
 */

/** The engine seams this needs. Structural so tests can drive it without a container. */
export interface CatalogDeps {
  getProviders: () => Array<{ name: string; baseURL: string; apiKeyEnv: string; defaultModel: string }>;
  /** The provider currently in use. */
  activeProvider: () => { name: string };
  /** Curated recommendations. */
  catalog: () => Array<{
    label: string;
    value: string;
    desc: string;
    tier: 'coding' | 'vision' | 'lite' | 'other';
    avoidAutoSelect?: boolean;
    recommendedFor?: Array<'coding' | 'vision' | 'lite'>;
    tags?: string[];
    parameters?: string;
    releaseDate?: string;
  }>;
  /** Ids the ACTIVE provider currently serves. Rejects/throws when offline or unkeyed. */
  listServed: (refresh: boolean) => Promise<string[]>;
  /** Resolved capabilities for one model id. */
  capabilities: (provider: string | null, id: string) => Record<string, any>;
  /** Raw value of an environment variable — read only, never reported. */
  readEnv: (name: string) => string | undefined;
}

const PROVIDER_LABEL: Record<string, string> = {
  nvidia: 'NVIDIA NIM',
  openai: 'OpenAI',
  anthropic: 'Anthropic',
  openrouter: 'OpenRouter',
  deepseek: 'DeepSeek',
  google: 'Google AI',
};

/**
 * Describe one provider's credential state WITHOUT disclosing it.
 *
 * A key may be a comma-separated rotation, so the count is reported too — "1 key" vs "3 keys" is
 * the difference between a rate limit being fatal and being routine, and the user cannot otherwise
 * tell what the engine loaded.
 */
function describeKeys(raw: string | undefined): { hasKey: boolean; keyCount: number; keyHint?: string } {
  const keys = String(raw || '')
    .split(',')
    .map((k) => k.trim())
    .filter(Boolean);
  if (keys.length === 0) return { hasKey: false, keyCount: 0 };
  const last = keys[keys.length - 1];
  // A 4-character tail identifies a key to the person who owns it and to nobody else. Short keys
  // get no hint at all rather than a hint that is most of the secret.
  const keyHint = last.length >= 12 ? `…${last.slice(-4)}` : undefined;
  return { hasKey: true, keyCount: keys.length, keyHint };
}

export function buildProviderEntries(deps: CatalogDeps): ProviderEntry[] {
  const active = deps.activeProvider().name;
  return deps.getProviders().map((provider) => ({
    name: provider.name,
    label: PROVIDER_LABEL[provider.name] || provider.name,
    baseURL: provider.baseURL,
    apiKeyEnv: provider.apiKeyEnv,
    active: provider.name === active,
    ...describeKeys(deps.readEnv(provider.apiKeyEnv)),
  }));
}

/**
 * Join the curated catalogue with what the provider actually serves.
 *
 * Both directions of the mismatch are preserved deliberately:
 *   - curated but NOT served → kept, `served: false`. Hiding it is what makes a stale pin
 *     undiagnosable: the user's configured model would simply vanish from the picker with no
 *     explanation, which is precisely the "I can't find my model" report.
 *   - served but NOT curated → appended, `curated: false`. These are real, selectable ids we have
 *     no measurement for; the front-end presents them as unvetted rather than recommended.
 */
export function buildModelEntries(
  deps: CatalogDeps,
  servedIds: string[],
  provider: string | null,
): CatalogModelEntry[] {
  const served = new Set(servedIds);
  const curated = deps.catalog();
  const seen = new Set<string>();

  const capabilitiesFor = (id: string): CatalogModelEntry['capabilities'] => {
    try {
      const caps = deps.capabilities(provider, id) || {};
      return {
        visionInput: !!caps.visionInput,
        reasoningEffortKnob: !!caps.reasoningEffortKnob,
        thinking: !!(caps.nativeThinking || caps.inlineReasoning || caps.openerlessReasoning),
        structuredOutputs: !!caps.structuredOutputs,
        parallelToolCalls: !!caps.parallelToolCalls,
        contextWindow: Number(caps.contextWindow) || 0,
      };
    } catch {
      return undefined;
    }
  };

  const rows: CatalogModelEntry[] = curated.map((entry) => {
    seen.add(entry.value);
    return {
      id: entry.value,
      label: entry.label,
      desc: entry.desc,
      tier: entry.tier,
      ...(entry.recommendedFor ? { recommendedFor: entry.recommendedFor } : {}),
      ...(entry.tags ? { tags: entry.tags } : {}),
      ...(entry.parameters ? { parameters: entry.parameters } : {}),
      ...(entry.releaseDate ? { releaseDate: entry.releaseDate } : {}),
      // With no live list at all (offline / no key), "not served" would be a lie about every model.
      // Report served:false only when we genuinely have a list to have been absent from.
      served: served.size === 0 ? false : served.has(entry.value),
      curated: true,
      ...(entry.avoidAutoSelect ? { avoidAutoSelect: true } : {}),
      capabilities: capabilitiesFor(entry.value),
    };
  });

  for (const id of servedIds) {
    if (seen.has(id)) continue;
    rows.push({
      id,
      label: id,
      desc: 'Served by this provider — not measured by us',
      tier: 'other',
      served: true,
      curated: false,
      capabilities: capabilitiesFor(id),
    });
  }

  return rows;
}

/** Assemble one `catalogResult`. Never throws: a failed model fetch becomes `error`, not a hang. */
export async function buildCatalog(deps: CatalogDeps, id: number, refresh = false): Promise<CatalogResultMsg> {
  const providers = buildProviderEntries(deps);
  const active = deps.activeProvider().name;

  let servedIds: string[] = [];
  let error: string | undefined;
  try {
    servedIds = (await deps.listServed(refresh)) || [];
    if (servedIds.length === 0) {
      const hasKey = providers.find((p) => p.active)?.hasKey;
      error = hasKey
        ? 'This provider returned no model list. The curated models below are unverified against it.'
        : 'No API key is set for this provider, so its model list could not be read.';
    }
  } catch (e: any) {
    error = String(e?.message || e || 'The provider’s model list could not be read.');
  }

  return {
    t: 'catalogResult',
    id,
    providers,
    models: buildModelEntries(deps, servedIds, active),
    ...(error ? { error } : {}),
  };
}

/**
 * The settings surface behind protocol v3's `configGet` / `configSet`.
 *
 * This is the silent path a graphical front-end uses instead of driving transcript menus, and it
 * exists as its own module for one reason: it has to be testable without booting a container.
 *
 * The bug it was extracted to prevent — a settings screen that verifies the wrong thing:
 *
 *   `configSet` used to `saveConfig(patch)` and then answer with the config FILE. The file had
 *   genuinely changed, so the front-end's read-back compared its own request against its own
 *   request and reported "applied" every time. But `LlmAdapter` caches the model slots at boot
 *   (`userModel` / `defaultModel`), and nothing here ever told it. Every other write path —
 *   `/model` (engine/commands/meta.ts), `/config set` (engine/commands/builtins.ts), ModelTool — follows
 *   its save with an `applyConfig`. This one did not, so the desktop's model picker changed the
 *   file, said it worked, and every request kept going to the model loaded at startup.
 *
 * Two invariants follow, and both are pinned by `src/__tests__/config.wire.test.ts`:
 *
 *   1. A write that touches an adapter-owned key MUST reach the adapter.
 *   2. A read MUST report the adapter's loaded state for those keys, not the file's — so when the
 *      two disagree, the front-end sees the disagreement instead of a false success.
 */

/**
 * The allowlisted, JSON-safe subset of `EngineConfig` a front-end may read and write directly.
 * Sensitive / engine-internal keys (API keys, workspaceRoot, dangerouslySkipPermissions,
 * onboarding flags) stay OFF the wire on purpose.
 */
export const CONFIG_WIRE_KEYS = [
  'model', 'liteModel', 'visionModel', 'fallbackModel', 'subagentModel',
  'provider', 'providerBaseURL',
  'temperature', 'topP', 'maxTokens', 'timeout',
  // `maxThinkingTokens` is off the wire: nothing sends it (engine/config.ts), so a front-end that can
  // write it can only offer a control that does nothing.
  'reasoningEffort',
  'contextMode', 'contextWindowTokens', 'parallelToolCalls',
  'maxToolIterations', 'maxSubAgents', 'taskCheckRetries', 'taskMaxMinutes', 'spendDailyCapUsd', 'spendTaskShareUsd',
  'autoResumeAgents',
  'notificationBell', 'verbose', 'reducedMotion', 'theme',
  'autoIndex', 'gitAutoCommit', 'autoVerify', 'sandboxBash',
  'autoContinueOutcome',
  'selfCritic', 'adversarialVerify', 'diffApproval', 'blastGate',
  'showMapPanel', 'showTokenMeter',
] as const;

/**
 * The subset of the above that `LlmAdapter.applyConfig` owns. Persisting one of these is only half
 * the change; the adapter holds its own copy and answers every request from it.
 */
export const ADAPTER_KEYS = [
  'model', 'liteModel', 'visionModel', 'reasoningEffort',
  'temperature', 'topP', 'maxTokens', 'timeout', 'parallelToolCalls',
] as const;

/** The slice of `LlmAdapter` this module needs. Kept structural so tests can pass a stub. */
export interface ConfigWireAdapter {
  applyConfig?: (cfg: Record<string, any>) => void;
  readEffective?: () => Record<string, any>;
}

export interface ConfigWireDeps {
  getConfig: () => Record<string, any>;
  saveConfig: (updates: Record<string, any>) => Promise<unknown>;
  llmAdapter?: ConfigWireAdapter | null;
  /**
   * Applies a saved patch to the engine's live switches beyond the adapter — the agent gates
   * (engine/gate.flags.ts). Without it a Settings toggle saved the file and changed nothing.
   */
  applyLive?: (patch: Record<string, any>) => void;
  /** Notifies attached front-ends + re-snapshots. Called only when something actually changed. */
  onChanged?: () => void;
}

export interface ConfigWire {
  /** Answer `configGet` / the result of `configSet`. */
  read: () => Record<string, any>;
  /** Handle `configSet`: filter, persist, apply to the live adapter, then answer with the truth. */
  write: (patch: Record<string, any>) => Promise<Record<string, any>>;
}

export function createConfigWire(deps: ConfigWireDeps): ConfigWire {
  const read = (): Record<string, any> => {
    const out: Record<string, any> = {};
    try {
      const file = deps.getConfig() ?? {};
      for (const key of CONFIG_WIRE_KEYS) if (file[key] !== undefined) out[key] = file[key];
    } catch { /* config not loaded yet — the adapter below may still have answers */ }
    // The adapter wins for its own keys: it is what the next request will actually use.
    try {
      const live = deps.llmAdapter?.readEffective?.();
      if (live) for (const key of ADAPTER_KEYS) if (live[key] !== undefined) out[key] = live[key];
    } catch { /* adapter optional in embeds/tests — the file subset still answers */ }
    return out;
  };

  const write = async (patch: Record<string, any>): Promise<Record<string, any>> => {
    const safe: Record<string, any> = {};
    for (const key of CONFIG_WIRE_KEYS) if (patch?.[key] !== undefined) safe[key] = patch[key];
    if (Object.keys(safe).length === 0) return read();

    await deps.saveConfig(safe);

    // Only forward keys actually present. `applyConfig` treats `undefined` as "leave alone", which
    // is what makes a single-key patch from one settings row safe.
    const adapterPatch: Record<string, any> = {};
    for (const key of ADAPTER_KEYS) if (safe[key] !== undefined) adapterPatch[key] = safe[key];
    if (Object.keys(adapterPatch).length > 0) {
      try { deps.llmAdapter?.applyConfig?.(adapterPatch); }
      catch { /* the saved config still applies on next boot; never fail the write over this */ }
    }
    try { deps.applyLive?.(safe); }
    catch { /* the saved config still applies on next boot; never fail the write over this */ }

    deps.onChanged?.();
    return read();
  };

  return { read, write };
}

import { engineEvents, MessageEntry } from '../engine/events';
import { isCodebase } from '../graph/graph.summary';
import type { HeadlessSession } from './headless.session';

// Boot-time chores of the engine's session, split out of startHeadless (flaw list C19). Each is best-effort: none may
// block or fail the engine becoming ready.

/**
 * Launch-grade first run: an empty key pool opens the real provider picker automatically. The
 * selected provider then uses the protocol's masked input request, saves the key globally, applies
 * it to the live adapter, and opens model discovery — no shell exports or restart required.
 * Delay until the ready handshake is on the wire; if a user turn wins the race, defer instead of
 * interrupting it. BIMAX_SKIP_KEY_ONBOARDING=1 is available for hermetic embeds/tests.
 */
export function offerKeySetupWhenPoolEmpty(session: HeadlessSession): void {
  if (process.env.BIMAX_SKIP_KEY_ONBOARDING !== '1') {
    try {
      const { buildKeyPool } = require('../engine/provider') as typeof import('../engine/provider');
      if (buildKeyPool().length === 0) {
        const offerKeys = (attempt = 0) => {
          if (session.isBusy && attempt < 20) {
            const timer = setTimeout(() => offerKeys(attempt + 1), 500);
            timer.unref?.();
            return;
          }
          if (!session.isBusy) void session.dispatch('/setup');
        };
        const timer = setTimeout(() => offerKeys(), 350);
        timer.unref?.();
      }
    } catch {
      /* onboarding must never block engine readiness */
    }
  }
}

/**
 * Mind layer wake-up: one QUICK drives measurement at boot (cheap signals only — a grep and a
 * git status, strictly sequential, never builds/tests) so the footer's 🧠 strip and the DRIVES
 * prompt section reflect reality from the first turn instead of waiting for a manual
 * /drives check. Fire-and-forget; re-snapshots when done. BIMAX_DRIVES_BOOT=0 disables.
 */
export function wakeDrives(): void {
  if (process.env.BIMAX_DRIVES_BOOT !== '0' && isCodebase(process.cwd())) {
    void (async () => {
      try {
        const { getDrivesEngine } = require('../mind/drives.engine');
        await getDrivesEngine().check({ quick: true });
        engineEvents.emit('mind_changed');
      } catch {
        /* best-effort */
      }
    })();
  }
}

/**
 * Crash recovery for task workspaces: tasks the PREVIOUS process left non-terminal are marked
 * failed-resumable in the execution ledger (their processes died with that engine — honesty
 * first), and the user is told what can be re-created. Zellij-style resurrection: we re-CREATE
 * recorded work on request (/tasks retry <id>); we never pretend it kept running.
 */
export function reportInterruptedTasks(): void {
  try {
    const { getExecutionLedger } = require('../core/execution.ledger');
    const ledger = getExecutionLedger();
    const interrupted = ledger.interruptedTasks();
    if (interrupted.length) {
      for (const t of interrupted) {
        ledger.append({
          taskId: t.taskId,
          type: 'transition',
          state: 'failed-resumable',
          reason: 'engine restarted while task was running',
        });
      }
      const resumable = interrupted.filter((t: any) => t.resumable);
      const lines = interrupted
        .slice(0, 5)
        .map((t: any) => `  ✗ ${t.title}${t.resumable ? ` — retry with /tasks retry ${t.taskId}` : ''}`);
      engineEvents.emit('message', {
        id: `task-recovery-${Date.now()}`,
        role: 'system',
        level: 'warn',
        content: `${interrupted.length} background task(s) were interrupted by the last shutdown:\n${lines.join('\n')}${resumable.length ? '' : '\n  (none are re-creatable — no recorded command)'}`,
        timestamp: new Date(),
      } as MessageEntry);
    }
  } catch {
    /* ledger recovery is best-effort */
  }
}

/**
 * Self-heal a stale/invalid model pin (e.g. config.json points at a model from a different
 * provider) so the first turn doesn't 400. Non-blocking — runs concurrently with `ready` so it
 * never delays startup; if the user's first turn beats it, the agent loop's model-404 message
 * covers that one turn. Session-scoped: the switch is NOT persisted (see the note below).
 */
export function healModelPins(llmAdapter: { healModels(): Promise<unknown[]> }): void {
  void (async () => {
    try {
      const healed = await llmAdapter.healModels();
      if (healed.length) {
        // The heal applies to THIS SESSION only — it is deliberately not persisted.
        //
        // It used to `saveConfig(patch, { origin: 'runtime' })` so "the next launch is already
        // correct". That silently overwrote the model the user had explicitly chosen in the
        // picker, and because `moonshotai/kimi-k3` is the top-ranked coding candidate
        // (models.ts:autoSelectCandidates), every heal landed on the same id. The reported
        // symptom was "whenever I open the app the kimi model is selected again" — one transient
        // provider hiccup was enough to replace a deliberate choice permanently, and the user had
        // no way to tell that anything had rewritten it.
        //
        // Healing in memory keeps the session working (nothing 400s) while the stored choice
        // stays the user's. If the pin is genuinely dead the heal simply runs again next launch
        // and says so again, which is honest; a stale pin is now fixed by the user in the picker,
        // never by the engine behind their back.
        const lines = (healed as Array<{ slot: string; from: string; to: string }>).map(
          (h) => `  • ${h.slot}: "${h.from}" → ${h.to ? `"${h.to}"` : 'the Work model'}`,
        );
        engineEvents.emit('message', {
          id: `heal-${Date.now()}`,
          role: 'system',
          level: 'info',
          // Deliberately not "aren't served by your provider": a slot also heals when the model IS
          // served but can't do the job (e.g. one that 400s on every tools+image request), and
          // claiming the provider doesn't have it would send the user chasing the wrong problem.
          content: `${healed.length === 1 ? "A model pinned in your config can't run here" : `${healed.length} models pinned in your config can't run here`} — switched:\n${lines.join('\n')}\nUse /model to choose another.`,
          timestamp: new Date(),
        } as MessageEntry);
        engineEvents.emit('config_changed');
      }
    } catch {
      /* best-effort */
    }
  })();
}

// The egress perimeter must go up before any module here opens a socket — see
// security/egress.perimeter.ts for why the guard lives beneath the code rather than beside it.
import { installEgressPerimeter } from '../security/egress.perimeter';
installEgressPerimeter();
import { engineEvents } from '../engine/events';
import { goalEvents } from '../memory/goal.manager';
import { buildPersonas } from '../engine/personas/factory';
import { HeadlessSession } from './headless.session';
import { startPortHost, type EnginePortLike } from './port.host';
import { startUiSnapshot, setTokensBaseline, setApprovalsReader } from './ui.snapshot';
import { getConfig, saveConfig } from '../engine/config';
import { estimateTokens } from '../graph/context.planner';
import { startAssignmentRecovery } from './headless.recovery';
import { startOutcomeContinuation } from './headless.continuation';
import { buildHostHandlers } from './headless.handlers';
import { startHeartbeat } from './headless.heartbeat';
import { offerKeySetupWhenPoolEmpty, wakeDrives, reportInterruptedTasks, healModelPins } from './headless.boot';
import { startIndexOnboarding } from './headless.onboarding';
// Register every slash command for its side effect. Commands self-register on import (each module
// calls globalCommandRegistry.register at top level), and the Ink path got them via FullScreen's
// imports — but headless imports only the bare registry, so without this the palette is EMPTY:
// no autocomplete for "/", and every slash command falls through as "Unknown command".
import '../engine/commands';

/**
 * Run the engine's session for the app: the engine is a worker thread in the app's process (the monolith, record 64)
 * and speaks over the MessagePort the app handed it, one protocol message per port message (port.host.ts). Called by
 * index.ts once the container is built.
 *
 * `container` is the createContainer() result; `config` the loaded config. Resolves only when the session shuts down:
 * when the app closes its end of the port, or an `engineEvents` 'shutdown'.
 *
 * Until record 64's M4 (2026-09-30) the engine could also run as its own process, speaking NDJSON on stdin/stdout;
 * that transport (stdio.host.ts, parent.port.ts, codec.ts) is in ~/Developer/bimax-archive and at the git tag
 * `keep/engine-process-fallback`.
 */
export interface HeadlessTransport {
  /** The port the app handed this engine worker. The app closing its end shuts the engine down. */
  port: EnginePortLike;
}

export async function startHeadless(container: any, config: any, transport: HeadlessTransport): Promise<void> {
  const { toolRegistry, llmAdapter, governor, graphStore, codebaseIndexer } = container;

  // The agent gates the user saved — diff approval, the blast-radius gate, self-critic and the rest —
  // are in force from the first message. Only their slash commands used to set them, so a choice made
  // in Settings was saved and never ran (engine/gate.flags.ts, fix list item 12).
  require('../engine/gate.flags').applyGateFlags(config);
  // Auto-verify and git auto-commit are PostToolUse hooks, and the Ink terminal's boot was the only
  // thing that registered them: when Ink was retired both went with it, so their switches — slash
  // command or Settings — did nothing at all (fix list item 12). Each hook returns at once until its
  // gate is on.
  {
    const { registerPostHook } = require('../tools/hooks') as typeof import('../tools/hooks');
    const verify = require('../sandbox/verify.loop') as typeof import('../sandbox/verify.loop');
    const autoCommit = require('../tools/git.autocommit') as typeof import('../tools/git.autocommit');
    verify.registerVerifyGraphStore(graphStore ?? null);
    registerPostHook(verify.VERIFY_TOOLS, verify.verifyHook);
    registerPostHook(autoCommit.GIT_AUTOCOMMIT_TOOLS, autoCommit.gitAutoCommitHook);
  }

  // User-defined slash commands: `.bimax/commands/<name>.md` in the project (winning) then
  // ~/.bimax/commands. The loader has existed and been unit-tested since A1, and nothing ever
  // called it — commands/index.ts imports its 53 siblings for their registration side effects, but
  // this one registers from the FILESYSTEM, so it needs invoking rather than importing. The feature
  // was complete and unreachable.
  //
  // Called here because it must run after the engine has chdir'd to the project (index.ts honours
  // BIMAX_CWD before the container is built), and before the first `query` can ask for completions.
  // A command body is dispatched as `redirect`, i.e. exactly as if the user had typed it, so it
  // faces the same governor and approval ladder as anything else — a project-supplied command still
  // cannot act without the user invoking it by name and approving what it does.
  try {
    const { loadCustomCommands } = require('../engine/commands/custom.loader') as typeof import('../engine/commands/custom.loader');
    const custom = loadCustomCommands();
    if (custom.length) {
      const { Logger } = require('../utils/logger') as typeof import('../utils/logger');
      Logger.info(`[commands] loaded ${custom.length} custom command(s): ${custom.join(' ')}`);
    }
  } catch { /* best-effort: a broken command file must never stop the engine booting */ }

  const options = {
    toolRegistry,
    llmAdapter,
    governor,
    maxToolIterations: config.maxToolIterations,
    notificationBell: config.notificationBell,
    persona: null,
  };

  // Session persistence: append every message/tool call to .breakglass/sessions/<id>.jsonl and
  // keep sessions-meta.jsonl current, so /sessions, /resume, and the desktop's thread surfaces
  // have real data. Attach BEFORE the host so nothing emitted during boot is lost.
  const { reportBootPhase } = require('./boot.status') as typeof import('./boot.status');
  reportBootPhase('restoring_session');
  const { startSessionRecorder } = require('../engine/session.recorder');
  const sessionRecorder = startSessionRecorder();
  // Recents names a session by what it is for, from its first reply (engine/session.summary.ts). After
  // the recorder, so the session it names already exists when the first message arrives.
  require('../engine/session.summary').startSessionSummaries(llmAdapter);

  // Review domain: fold approvals / attributed changes / verification evidence / checkpoints into
  // the per-thread review file and publish `review_update` snapshots. Rides the same thread
  // lifecycle as the recorder above (session_changed), so it must start after it.
  const { startReviewManager } = require('../review/review.manager');
  const reviewManager = startReviewManager();

  // Outcome runtime: one persistent acceptance/task/evidence contract per thread. It starts after
  // the recorder so session_changed always has a concrete id, and listens to the review domain's
  // mutation/evidence facts instead of inventing a second source of truth.
  const { startOutcomeManager } = require('../outcome/outcome.manager');
  const outcomeManager = startOutcomeManager();
  // Task grants (N13) end with the task: a new task in this engine, or a switch to another saved one.
  require('../governor/task.grants').endGrantsWithTask(engineEvents);
  // Completion checks (F3): per session, like the outcome contract, so they follow session_changed too.
  require('../outcome/completion.check').startCompletionChecks();

  const personas = buildPersonas(toolRegistry, llmAdapter);
  const session = new HeadlessSession({
    personas,
    options,
    graphStore,
    codebaseIndexer,
    saveConfig,
  });

  // Unattended crash recovery of interrupted assignments (headless.recovery.ts).
  const stopRecovery = startAssignmentRecovery({ session, outcomeManager, config });

  // Outcome auto-continuation: wake the coordinator when background work settles (headless.continuation.ts).
  const stopContinuation = startOutcomeContinuation({ session, outcomeManager, config });

  // Token-meter baseline = system prompt + tool-schema JSON (the fixed per-request cost), recomputed
  // on demand so a Smart↔Full context-mode toggle moves the meter. Mirrors FullScreen's calc.
  setTokensBaseline(() => {
    try {
      const mode = (getConfig().contextMode as 'smart' | 'full') || 'smart';
      const persona = personas.bimax || Object.values(personas)[0];
      const sys = persona?.getSystemPrompt({ planMode: governor?.mode === 'plan', contextMode: mode }) || '';
      let toolTokens = 0;
      try {
        toolTokens = estimateTokens(JSON.stringify(toolRegistry.getSchemas({ mode })));
      } catch {
        /* registry optional */
      }
      return estimateTokens(sys) + toolTokens;
    } catch {
      return 0;
    }
  });

  // What the engine does with each message the app sends (headless.handlers.ts).
  const handlers = buildHostHandlers({ session, graphStore, llmAdapter });
  const dispose = startPortHost({ emitter: engineEvents, port: transport.port, onClose: () => engineEvents.emit('shutdown'), ...handlers });

  // Liveness heartbeat for the supervisor's hang watchdog, on the host's queue (headless.heartbeat.ts).
  const stopHeartbeat = startHeartbeat((msg) => dispose.send(msg), () => session.isBusy);

  // Register the inline diff-approval gate over the protocol (Ink registers its own in FullScreen).
  // When the user enables /diff-approval, mutating tools surface their diff and wait for a reply.
  const { registerDiffApprover } = require('../engine/diffApproval');
  registerDiffApprover(
    (summary: string, diff: string) =>
      new Promise<boolean>((resolve) => {
        engineEvents.emit('diff_prompt', summary, diff, (answer: string) =>
          resolve(/^(a|y|approve|accept)/i.test(answer)),
        );
      }),
  );

  // Goal mutations land on a separate emitter; FullScreen bridges it to engineEvents for Ink, so the
  // headless path must too — otherwise the footer goal counter (refreshed by ui_snapshot on
  // goals_changed) never updates out-of-process.
  const onGoals = () => engineEvents.emit('goals_changed');
  goalEvents.on('goals_changed', onGoals);

  // The approval gates as the engine will apply them — the composer's permission pill shows this, not
  // what it last sent (fix list item 12).
  setApprovalsReader(() => ({
    askBeforeEdits: require('../engine/diffApproval').isDiffApprovalEnabled(),
    readOnly: governor?.mode === 'plan',
    unattended: governor?.mode === 'bypass' || governor?.mode === 'unattended',
  }));
  // Push footer + map-panel + token-meter state the Go front-end can't read from engine singletons.
  startUiSnapshot(graphStore, toolRegistry);

  // Boot chores, each best-effort (headless.boot.ts): open provider setup when there is no key, a quick drives check,
  // report background tasks the last shutdown interrupted, and heal a model pin that cannot run here.
  offerKeySetupWhenPoolEmpty(session);
  wakeDrives();
  reportInterruptedTasks();
  healModelPins(llmAdapter);

  // Offer (or start) the code map on a new codebase, then the AI layer once the map exists (headless.onboarding.ts).
  const stopOnboarding = startIndexOnboarding({ graphStore, codebaseIndexer });

  await new Promise<void>((resolve) => {
    let done = false;
    const shutdown = () => {
      if (done) return;
      done = true;
      // Flush every durable domain directly, so the latest assignment and evidence cannot vanish when the app closes
      // the port.
      try {
        outcomeManager.shutdown();
      } catch {
        /* best-effort */
      }
      try {
        reviewManager.shutdown();
      } catch {
        /* best-effort */
      }
      try {
        sessionRecorder.shutdown();
      } catch {
        /* best-effort */
      }
      stopHeartbeat();
      stopRecovery();
      stopContinuation();
      stopOnboarding();
      goalEvents.off('goals_changed', onGoals);
      dispose();
      resolve();
    };
    // The app closing the port emits 'shutdown' (port.host.ts). There is no stdin to watch and no signal to catch: a
    // worker thread receives no signals, so SIGINT/SIGTERM listeners here never ran once the engine became a worker.
    engineEvents.once('shutdown', shutdown);
  });
}

import { engineEvents } from '../engine/events';
import type { HeadlessSession } from './headless.session';
import type { HostHandlers } from './host';
import { createConfigWire } from './config.wire';
import { buildCatalog, type CatalogDeps } from './catalog.wire';
import { getProviders, getProvider, getCurrentProvider, setProvider } from '../engine/provider';
import { saveApiKeyToEnv } from '../engine/env.loader';
import { MODEL_CATALOG } from '../engine/models';
import { capabilitiesFor } from '../core/capabilities';
import { completeInput } from './completions';
import { getConfig, saveConfig } from '../engine/config';

/**
 * What the engine does with each message the app sends (split out of startHeadless, flaw list C19): input,
 * interrupts, steering, completions (and the Composer's ingest), menus, resume, controls, settings, the model
 * catalogue and the provider switch.
 */
export function buildHostHandlers(deps: { session: HeadlessSession; graphStore: any; llmAdapter: any }): HostHandlers {
  const { session, graphStore, llmAdapter } = deps;
  // Settings surface (protocol v3): the allowlisted, JSON-safe subset of EngineConfig a graphical
  // front-end may read and write directly — the silent path behind settings pages, replacing
  // transcript menus. The allowlist, the persistence and the live-adapter application all live in
  // protocol/config.wire.ts so the seam is testable without booting a container; see that file for
  // why a read-back of the config FILE is not proof that anything took effect.
  const configWire = createConfigWire({
    getConfig: () => getConfig() as any,
    saveConfig: (updates) => saveConfig(updates as any),
    llmAdapter,
    // The agent gates Settings switches take effect now, not never (engine/gate.flags.ts).
    applyLive: (patch) => { require('../engine/gate.flags').applyGateFlags(patch); },
    onChanged: () => engineEvents.emit('config_changed'), // re-snapshot + notify every front-end
  });
  const configSubset = (): Record<string, any> => configWire.read();

  // The provider + model catalogue behind the desktop's model picker. `listServed` is the live
  // `/models` call, so the picker offers ids the provider genuinely accepts instead of a hand-typed
  // list that drifts — and `capabilities` lets the UI grey out a knob a model does not have rather
  // than sending a parameter the backend will reject the whole request over.
  const catalogDeps: CatalogDeps = {
    getProviders: () => getProviders(),
    activeProvider: () => getCurrentProvider(),
    catalog: () =>
      MODEL_CATALOG.map((m) => ({
        label: m.label,
        value: m.value,
        desc: m.desc,
        tier: m.tier,
        avoidAutoSelect: m.avoidAutoSelect,
        recommendedFor: m.recommendedFor,
        tags: m.tags,
        parameters: m.parameters,
        releaseDate: m.releaseDate,
      })),
    listServed: (refresh) => llmAdapter.listProviderModels(refresh),
    capabilities: (provider, id) => capabilitiesFor(provider, id) as any,
    readEnv: (name) => process.env[name],
  };
  const buildVisibleCatalog = (refresh: boolean) => buildCatalog(catalogDeps, 0, refresh);

  // The handlers are the same whatever the transport; only how messages travel differs.
  return {
    onInput: (text, scope, display) => {
      void session.dispatch(text, scope, display);
    },
    onInterrupt: () => session.interrupt(),
    onSteer: (text) => session.steer(text),
    onQuery: async (text) => {
      const UI = '\u0000presentation:';
      if(text.startsWith(UI)) {
        try { const result = await require('../mcp/ui.grants').requestMcpUi(JSON.parse(text.slice(UI.length))); return [{label:'presentation',kind:'path' as const,desc:'',value:JSON.stringify({result})}]; }
        catch(error) { return [{label:'presentation',kind:'path' as const,desc:'',value:JSON.stringify({error:String(error)})}]; }
      }
      // The completions channel doubles as the Composer's ingest channel.
      //
      // Attaching a file must READ IT THERE AND THEN, the way every assistant people already use
      // does. Deferring to send time is what made the model appear to "go find the file and read
      // it": the path travelled in the prompt, and the reading was visible work inside the turn.
      // Ingesting at attach means that by the time a turn runs, the document is already parsed and
      // only its passages travel.
      //
      // Carried on `query` deliberately: it is already a request/response channel with an id, so
      // this needs no new message type, no protocol version bump, and no regenerated mirror. The
      // reserved prefix cannot collide with a completion — completions are what the user typed.
      const INGEST = '\u0000composer:ingest:';
      if (text.startsWith(INGEST)) {
        const file = text.slice(INGEST.length);
        try {
          const { getComposerCorpus } = require('../memory/corpus') as typeof import('../memory/corpus');
          const corpus = getComposerCorpus();
          if (!corpus) return [{ label: 'unavailable', value: '', kind: 'path' as const, desc: 'no corpus' }];
          const report = await corpus.ingest([file], 'session');
          const entry = report.ingested[0];
          if (entry) {
            return [{
              label: 'read', value: String(entry.chunks), kind: 'path' as const,
              desc: entry.ocr ? 'ocr' : '',
            }];
          }
          // Unchanged means an identical file is already indexed — still "read" from the user's
          // point of view, and reporting it as a failure would be a lie about the corpus.
          if (report.unchanged) return [{ label: 'read', value: '0', kind: 'path' as const, desc: '' }];
          return [{
            label: 'failed', value: '0', kind: 'path' as const,
            desc: report.skipped[0]?.reason || 'no readable text',
          }];
        } catch (error) {
          return [{ label: 'failed', value: '0', kind: 'path' as const, desc: String((error as Error)?.message || error) }];
        }
      }
      return completeInput(text, graphStore, process.cwd());
    },
    onMenuSelect: (id, value) => session.selectMenu(id, value),
    // Typed recovery resume (protocol v3 additive): same code path as the user's /resume, but
    // requested as a structured message so front-ends never fabricate slash-command text.
    onResume: (id) => {
      void session.dispatch(`/resume ${id}`);
    },
    onControls: async ({ mode, tier, autonomy }) => {
      // One wire message, one serialized sequence. In particular, every non-plan autonomy preset
      // exits plan mode first, so the chrome can never claim edits are enabled while PLAN still
      // blocks them in the governor.
      const { getAgentMode } = require('../engine/agentMode') as typeof import('../engine/agentMode');
      const preservedMode = getAgentMode();
      const commands: Record<string, string[]> = {
        ask: ['/plan off', '/governor on', '/diff-approval on'],
        auto: ['/plan off', '/governor on', '/diff-approval off'],
        plan: ['/plan on'],
        full: ['/plan off', '/governor off', '/diff-approval off'],
      };
      for (const command of autonomy ? (commands[autonomy] ?? []) : []) await session.dispatch(command);
      // /plan on|off emits the legacy mode_change event for the TUI. Re-apply the behavioral mode
      // afterwards so Code/Beast/Explore/Sketch never visually collapse to General, and their
      // governor gate remains the final authority for combinations such as Explore + Full auto.
      if (mode || autonomy) await session.dispatch(`/mode ${mode ?? preservedMode}`);
      if (tier) await session.dispatch(`/tier ${tier}`);
      // The composer's approval pill reads the engine's real gates from the snapshot, so a change here
      // has to produce one — /governor on|off saves nothing and would otherwise refresh no front-end.
      if (autonomy) engineEvents.emit('config_changed');
    },
    onConfigGet: configSubset,
    onConfigSet: (patch) => configWire.write(patch),
    onCatalogGet: async (refresh) => {
      const { t, id, ...rest } = await buildVisibleCatalog(refresh);
      return rest;
    },
    onProviderSet: async ({ name, baseURL, apiKey }) => {
      const provider = getProvider(name);
      if (!provider) return { providers: [], models: [], error: `Unknown provider "${name}".` };

      // Save the key BEFORE switching, so the catalogue fetch that answers this request is made
      // with the credential the user just supplied — that round-trip is how they find out whether
      // the key works, and asking them to press refresh afterwards to discover a typo is a worse
      // answer than simply using it. saveApiKeyToEnv writes owner-only, refuses to follow a
      // symlink, and updates process.env so the running key pool picks it up without a restart.
      if (apiKey) {
        try {
          saveApiKeyToEnv(provider.apiKeyEnv, apiKey);
        } catch (e: any) {
          return { providers: [], models: [], error: `Could not save the key: ${String(e?.message || e)}` };
        }
      }

      setProvider(name);
      // Persist, so the choice survives a restart — the whole point of the `provider` config key.
      // Without this the switch lives in a module variable and every relaunch silently reverts.
      await saveConfig({ provider: name, ...(baseURL ? { providerBaseURL: baseURL } : {}) } as any);
      // A new provider means a new key pool, a new endpoint and a different served-model list; the
      // session cache belongs to the old one, so force a refresh rather than answering from it.
      const { t, id, ...rest } = await buildVisibleCatalog(true);
      engineEvents.emit('config_changed');
      return rest;
    },
  };
}

import { engineEvents, MessageEntry } from '../engine/events';
import { isCodebase, summarizeGraph } from '../graph/graph.summary';
import { getConfig, saveConfig } from '../engine/config';

/**
 * First-run onboarding (parity with Ink's FullScreen): inside a real project with no map yet,
 * offer to build the AST index; once it exists, offer the AI (semantic) layer. Each offer is a
 * menu the front-end renders; selecting an option dispatches the matching slash command. Both are
 * gated on config.onboardingComplete so we never nag twice. Off entirely outside a codebase, so a
 * scratch dir (~ / Desktop) never indexes hundreds of thousands of junk nodes.
 * The payload carries the SAME id as the message so both front-ends correlate a selection the
 * same way (the desktop replies with the message id, the TUI with payload.id). These onboarding
 * menus have no engine-side onSelect: every option value is a slash command the front-end's
 * menuSelect dispatches directly.
 *
 * Split out of startHeadless (flaw list C19). Returns the function that stops listening for the finished map; the listener used
 * to outlive the session.
 */
export function startIndexOnboarding(deps: { graphStore: any; codebaseIndexer: any }): () => void {
  const { graphStore, codebaseIndexer } = deps;
  const uiMenu = (title: string, options: any[]): MessageEntry => {
    const id = `ui-${Date.now()}-${Math.random().toString(36).slice(2, 7)}`;
    return {
      id,
      role: 'system',
      uiComponent: 'menu',
      payload: { id, title, options },
      content: '',
      timestamp: new Date(),
    };
  };
  let aiOffered = false;
  let mapOffered = false;
  const onboardingDone = () => {
    try {
      return !!getConfig().onboardingComplete;
    } catch {
      return false;
    }
  };
  const nodeCount = () => {
    try {
      return summarizeGraph(graphStore).nodeCount;
    } catch {
      return 0;
    }
  };

  // After a map is built, offer the AI graph once (the indexer emits graph_changed on completion).
  const onGraphChanged = () => {
    if (aiOffered || onboardingDone()) return;
    let s;
    try {
      s = summarizeGraph(graphStore);
    } catch {
      return;
    }
    if (s.nodeCount > 0 && !s.aiGraphBuilt) {
      aiOffered = true;
      try {
        saveConfig({ onboardingComplete: true } as any);
      } catch {
        /* best-effort */
      }
      engineEvents.emit(
        'message',
        uiMenu('Add the AI graph? (semantic layer: purpose + risk per symbol)', [
          { label: 'Build AI graph', value: '/index-ai force', desc: 'Makes API calls — richer impact analysis' },
          { label: 'Skip', value: '', desc: 'You can run /index-ai later' },
        ]),
      );
    }
  };
  engineEvents.on('graph_changed', onGraphChanged);

  // BIMAX_AUTO_INDEX=0: a supervising front-end sheds background indexing on memory-constrained
  // machines (capability `autoIndex`). Config keeps working for everyone else.
  const autoIndexEnabled = () => {
    if (process.env.BIMAX_AUTO_INDEX === '0') return false;
    try {
      return getConfig().autoIndex !== false;
    } catch {
      return true;
    }
  };

  if (isCodebase(process.cwd()) && nodeCount() === 0) {
    if (autoIndexEnabled()) {
      // autoIndex: true → build the graph in the background automatically (idempotent: autoIndex()
      // no-ops if a graph already exists on disk). THIS is what unlocks the repo map + GraphContext/
      // GraphQuery tools without the user clicking a menu or running /index. Previously "autoIndex"
      // only flipped an enabled flag and nothing ever called it, so the graph stayed empty.
      engineEvents.emit('status', 'Indexing codebase for symbol-level navigation…');
      void codebaseIndexer.autoIndex(false, false).catch(() => {
        /* best-effort; /index retries */
      });
    } else if (!onboardingDone()) {
      // autoIndex off → ask before building (the original onboarding menu).
      setTimeout(() => {
        if (mapOffered || nodeCount() !== 0 || onboardingDone()) return;
        // Record that the question was ASKED, before asking it — exactly what the AI-graph offer
        // above does. Without this the prompt had no memory at all: "Skip" carries `value: ''`,
        // which sends nothing to the engine, so declining recorded nothing and the next engine
        // process asked again. On a memory-constrained box that is every session, because
        // `resources.ts` sets BIMAX_AUTO_INDEX=0 under the `minimal` profile and this branch is
        // the one that runs. Reported live: the same repo, the same chat tab, asked over and over.
        //
        // The file comment two blocks up already states the intent — "gated on
        // config.onboardingComplete so we never nag twice" — and it was true of the AI-graph offer
        // and never of this one. `mapOffered` additionally covers repeats inside one process.
        mapOffered = true;
        try {
          saveConfig({ onboardingComplete: true } as any);
        } catch {
          /* best-effort — an unwritable project dir must not block the prompt itself */
        }
        engineEvents.emit(
          'message',
          // Labels are DATA, not presentation. These carried literal square brackets —
          // "[ Build map graph ]" — which is terminal decoration, and the desktop app renders the
          // label verbatim into a button. The result was a GUI card that looked like a TUI prompt.
          // A front-end that wants brackets can add them; one that doesn't cannot remove them.
          uiMenu('New codebase detected — build the map graph?', [
            {
              label: 'Build map graph',
              value: '/index force',
              desc: 'AST index so I navigate to the exact symbol (skips node_modules, .git, build dirs)',
            },
            { label: 'Skip', value: '', desc: 'You can run /index later' },
          ]),
        );
      }, 600);
    }
  }
  return () => { engineEvents.off('graph_changed', onGraphChanged); };
}

import { engineEvents } from '../engine/events';
import type { HeadlessSession } from './headless.session';
import type { OutcomeManager } from '../outcome/outcome.manager';

/**
 * Unattended crash recovery: only recent, single-session, outcome-bound assignments running
 * under normal permissions qualify. The recovery command reuses the same audited session and
 * assignment rebinding path as manual `/subagents resume`; unsafe/legacy snapshots stay visible
 * for manual review. A user turn that wins the startup race is never interrupted or switched.
 *
 * Split out of startHeadless (flaw list C19). Returns the function that stops it.
 */
export function startAssignmentRecovery(deps: {
  session: HeadlessSession;
  outcomeManager: OutcomeManager;
  config: { autoResumeAgents?: boolean };
}): () => void {
  const { session, outcomeManager, config } = deps;
  let recoveryStarted = false;
  let recoveryTimer: ReturnType<typeof setTimeout> | null = null;
  const attemptAutomaticRecovery = async (attempt = 0): Promise<void> => {
    if (recoveryStarted) return;
    const checkpoint = require('../core/agent.checkpoint') as typeof import('../core/agent.checkpoint');
    const plan = checkpoint.planAutomaticRecovery(checkpoint.crashedAgents(), {
      enabled: config.autoResumeAgents !== false && process.env.BIMAX_AUTO_RESUME_AGENTS !== '0',
    });
    if (!plan.automatic || !plan.sessionId) {
      engineEvents.emit('status', `${plan.reason} Use /subagents resume after reviewing the interrupted work.`);
      return;
    }
    if (session.isBusy) {
      if (attempt < 30)
        recoveryTimer = setTimeout(() => {
          void attemptAutomaticRecovery(attempt + 1);
        }, 1000);
      else
        engineEvents.emit(
          'status',
          'Automatic assignment recovery deferred because the current turn stayed busy; use /subagents resume later.',
        );
      return;
    }
    // `activeSessionId()` is '' on every fresh boot — a brand-new terminal is indistinguishable
    // from "picking the same session back up" by process state alone, so treating '' as a pass
    // here silently hijacked EVERY new chat onto whatever old session left a crashed sub-agent
    // behind: it dispatched a full /resume (replaying that session's transcript into the new
    // terminal and rebinding the recorder so every later turn kept appending to the old thread).
    // Automatic recovery is only safe when the CURRENT session already is the crashed one.
    const activeSession = outcomeManager.activeSessionId();
    if (activeSession !== plan.sessionId) {
      engineEvents.emit(
        'status',
        `${plan.agents.length} interrupted assignment(s) from a previous session (${plan.sessionId}) can be recovered — run /resume ${plan.sessionId} then /subagents resume to pick them back up.`,
      );
      return;
    }
    recoveryStarted = true;
    engineEvents.emit('status', `Recovering ${plan.agents.length} interrupted assignment(s) from ${plan.sessionId}…`);
    await session.dispatch(`/resume ${plan.sessionId}`);
    if (outcomeManager.activeSessionId() !== plan.sessionId) {
      recoveryStarted = false;
      engineEvents.emit(
        'status',
        `Could not restore outcome session ${plan.sessionId}; interrupted agents were not restarted.`,
      );
      return;
    }
    await session.dispatch('/subagents resume');
    engineEvents.emit('status', `${plan.agents.length} interrupted assignment(s) resumed safely.`);
  };
  const onAgentRecoveryAvailable = () => {
    void attemptAutomaticRecovery();
  };
  engineEvents.on('agent_recovery_available', onAgentRecoveryAvailable);
  return () => {
    if (recoveryTimer) clearTimeout(recoveryTimer);
    engineEvents.off('agent_recovery_available', onAgentRecoveryAvailable);
  };
}

import { engineEvents, MessageEntry } from '../engine/events';
import { AgentPersona } from '../engine/personas/base.persona';
import { routeQuery } from '../engine/agentRouter';
import { expandAtMentions, expandFileAtMentions } from '../engine/atMention';
import { globalCommandRegistry } from '../engine/commands/registry';
import { decideTier, Tier, isConversational } from '../engine/model.router';
import { getEpistemicLedger } from '../mind/epistemic.ledger';
import {
  recordTurn, beginTurnTimeline, markRouted, markAssembled, markFirstVisibleToken, endTurnTimeline,
} from '../telemetry/perf';
import { IGraphStore } from '../graph/models';
import { getSessionRecorder } from '../engine/session.recorder';
import { clearSteer, drainSteer, pushSteer } from '../core/steering';
import { attachedPictures, MAX_PICTURE_BYTES, MAX_TURN_PICTURES } from '../core/multimodal';
import * as path from 'path';
import type { TurnToolScope } from './protocol';

/**
 * Confidence-in-margin (turn-end form): from the epistemic-ledger delta across a turn, decide what
 * to say about its verification posture. `verified` = claims resolved by a build/test run that named
 * the touched files; `opened` = new claims (edits) still unchecked. Returns null when the turn
 * changed nothing that the ledger tracks — it speaks only to confirm verified work or nudge an
 * unverified change. Pure, so it's unit-testable without driving a whole turn.
 */
export function ledgerTurnSummary(
  before: { resolved: number; open: number } | null,
  after: { resolved: number; open: number },
): { text: string; level: 'success' | 'info' } | null {
  if (!before) return null;
  const verified = after.resolved - before.resolved;
  const opened = after.open - before.open;
  if (verified > 0) {
    return { text: `◇ ledger · verified ${verified} change${verified > 1 ? 's' : ''} this turn`, level: 'success' };
  }
  if (opened > 0) {
    return { text: `◇ ledger · ${opened} change${opened > 1 ? 's' : ''} unverified — run a build/test to confirm`, level: 'info' };
  }
  return null;
}

/**
 * Menu labels are DATA, not presentation. Commands historically wrote terminal decoration into the
 * label itself — "[ Start Indexing ]", "[ Cancel ]" — which the desktop app renders verbatim into a
 * button, so a GUI card looked like a TUI prompt. Strip the wrapper once at the protocol boundary:
 * a front-end that wants brackets can add them, one that doesn't cannot remove them. (The TUI draws
 * its own "❯ " cursor and colour, and the brackets were eating 4 of its 24-char label budget.)
 */
function undecorate(opt: any): any {
  if (!opt || typeof opt.label !== 'string') return opt;
  const label = opt.label.trim().replace(/^\[\s*(.*?)\s*\]$/, '$1').trim();
  return label === opt.label ? opt : { ...opt, label };
}

export interface HeadlessDeps {
  personas: Record<string, AgentPersona>;
  options: any;           // the same `options` bag FullScreen receives (governor, llmAdapter, toolRegistry, …)
  graphStore: IGraphStore;
  codebaseIndexer?: any;
  saveConfig?: (updates: Record<string, any>) => Promise<any>;
}

/**
 * Drives a BiMax session with no UI — the headless counterpart to FullScreen's handleSubmit.
 * Same engine entrypoints (agent router → persona.execute, globalCommandRegistry.execute,
 * @-mention expansion), but every UI effect is replaced by a `engineEvents` emit the ProtocolHost
 * forwards over the wire. Deliberately leaner than handleSubmit: it omits Ink-only concerns
 * (autocomplete, paste chips, tier-routing UI, vision) — those belong to the front-end.
 */
export class HeadlessSession {
  private busy = false;
  private turnFinished: Promise<void> = Promise.resolve();
  private finishTurn: (() => void) | null = null;
  private clearing: Promise<void> | null = null;
  // Aborts the in-flight turn when the front-end sends an interrupt. Non-null only while a turn runs.
  private turnAbort: AbortController | null = null;
  // Manual model-tier pin (the /tier command / Ctrl+T). null = automatic routing. Mirrors the
  // pinnedTierRef FullScreen keeps for the Ink path, so headless honors /tier identically.
  private pinnedTier: Tier | null = null;
  // Active interactive menus, keyed by the id sent to the front-end. Holds the option list + the
  // onSelect callback (which can't cross the wire), so a menuSelect reply can run the real handler —
  // e.g. picking a model id in /model applies it instead of dispatching the bare id as a chat turn.
  private menus = new Map<string, { options: any[]; onSelect?: (opt: any) => void }>();
  private menuSeq = 0;

  constructor(private deps: HeadlessDeps) {
    // /tier auto|lite|heavy emits set_tier; apply the pin and reflect it in the footer, exactly as
    // FullScreen.handleSetTier does for Ink. (set_tier is also forwarded to the front-end verbatim.)
    engineEvents.on('set_tier', (t: 'auto' | 'lite' | 'heavy') => {
      this.pinnedTier = t === 'auto' ? null : t;
      engineEvents.emit('model_tier', { tier: this.pinnedTier ?? 'lite', pinned: this.pinnedTier });
      engineEvents.emit('status', this.pinnedTier === null
        ? 'Routing → auto (lite decides, escalates as needed)'
        : `Routing pinned → ${this.pinnedTier} model`);
    });
  }

  /** Whether a turn is executing right now — the heartbeat's `activeTurn` signal. */
  get isBusy(): boolean {
    return this.busy;
  }

  /** A submitted line: a slash command or a user turn. */
  async dispatch(text: string, toolScope?: TurnToolScope, displayText?: string): Promise<void> {
    const query = (text || '').trim();
    if (!query) return;
    if (toolScope) {
      // A scoped task is never interpreted as an app command, a greeting or persona-switch syntax.
      await this.runTurn(query, { toolScope, displayText });
      return;
    }
    if (/^\/clear\s+force(?:\s|$)/i.test(query)) {
      if (!this.clearing) {
        this.interrupt();
        this.clearing = this.turnFinished.then(() => this.runCommand(query));
      }
      try { await this.clearing; } finally { this.clearing = null; }
      return;
    }
    if (this.clearing) await this.clearing;
    if (query.startsWith('/')) { await this.runCommand(query); return; }
    await this.runTurn(query, { displayText });
  }

  /**
   * Words for the running turn (backlog F7), taken by the agent loop at its next step. With no turn running — or for
   * a slash command — they are an ordinary input.
   */
  steer(text: string): void {
    const trimmed = (text || '').trim();
    if (!trimmed) return;
    if (!this.busy || trimmed.startsWith('/')) { void this.dispatch(trimmed); return; }
    pushSteer(trimmed);
    engineEvents.emit('steer_queued', { text: trimmed });
    engineEvents.emit('status', 'Your message reaches the running task at its next step.');
  }

  /** Engine-owned continuation turn. It uses the coordinator without fabricating user chat. */
  async dispatchAutonomous(text: string): Promise<'completed' | 'busy' | 'failed' | 'interrupted'> {
    const query = (text || '').trim();
    if (!query || query.startsWith('/')) return 'failed';
    if (this.clearing) return 'busy';
    return this.runTurn(query, { autonomous: true });
  }

  /**
   * Cancel the in-flight turn (the front-end's Ctrl-C / Esc). Cooperative: the agent loop stops at
   * its next safe boundary, then the `finally` in runTurn emits the idle spinner. A no-op when idle.
   */
  interrupt(): void {
    if (!this.busy || !this.turnAbort) return;
    clearSteer();
    this.turnAbort.abort();
    engineEvents.emit('status', 'Interrupting…');
  }

  private async runTurn(query: string, opts: { autonomous?: boolean; toolScope?: TurnToolScope; displayText?: string } = {}): Promise<'completed' | 'busy' | 'failed' | 'interrupted'> {
    if (this.busy) {
      if (!opts.autonomous) engineEvents.emit('status', 'Busy — finish the current turn before sending another.');
      return 'busy';
    }
    this.busy = true;
    this.turnFinished = new Promise(resolve => { this.finishTurn = resolve; });
    this.turnAbort = new AbortController();
    const turnStart = Date.now();
    // A fresh user instruction legitimizes repetition — failure-memory counters reset so the
    // system never blocks something the human explicitly re-asked for.
    if (!opts.autonomous) { try { require('../core/failure.memory').getFailureMemory().newUserTurn(); } catch { /* observer */ } }
    let firstTokenMs = 0; // set on the first streamed token (perf: time-to-first-token)
    // Lightweight conversation lane (P0-3): greetings/acks/simple meta questions bypass the full
    // harness entirely. A manual heavy pin or an engine wake keeps the full path. The decision is
    // local (no model call), so a "hi" never pays for routing, graph, memory, or verification.
    const conversational = !opts.toolScope && !opts.autonomous && this.pinnedTier !== 'heavy'
      && isConversational(query);
    const model = this.deps.options.llmAdapter?.userModel || this.deps.options.llmAdapter?.defaultModel;
    beginTurnTimeline(conversational ? 'lite' : 'full', model);
    // Snapshot the epistemic ledger so we can report THIS turn's verification posture at the end:
    // claims open on edits and resolve when a build/test run names the touched files.
    const beforeLedger = (() => { try { return getEpistemicLedger().stats(); } catch { return null; } })();
    if (!opts.autonomous) engineEvents.emit('message', this.msg('user', opts.displayText ?? query));
    // Show activity IMMEDIATELY — @-mention expansion below can take a moment, during which the
    // front-end would otherwise sit silent after the user's message. (Routing itself is local now.)
    engineEvents.emit('spinner_state', 'thinking', 'Thinking…');

    const active = (conversational || opts.autonomous || opts.toolScope)
      ? this.deps.personas.bimax
      : (this.deps.personas[routeQuery(query)] || this.deps.personas.bimax);
    const before = active.messages.length;
    let totalChars = 0;
    let streamed = '';
    const onToken = (token: string) => {
      if (firstTokenMs === 0) { firstTokenMs = Date.now() - turnStart; markFirstVisibleToken(); }
      totalChars += token.length; streamed += token; engineEvents.emit('stream_token', token);
    };

    let result: 'completed' | 'failed' | 'interrupted' = 'failed';
    try {
      if (conversational) {
        // The lite lane: no routing, no @-mention expansion, no tools. Fall back to the full harness
        // if the conversational completion errors (a keyless/cold provider shouldn't lose the turn).
        engineEvents.emit('model_tier', { tier: 'lite', pinned: this.pinnedTier });
        markRouted();
        markAssembled();
        try {
          await active.converse(query, onToken, { useLite: true, signal: this.turnAbort.signal });
        } catch (error) {
          if (this.turnAbort.signal.aborted) throw error;
          streamed = ''; // discard any partial lite output; the full harness re-runs the turn cleanly
          // forceHeavy: the lite lane just failed, and the router would send this same trivial query
          // straight back to the same lite model. Retrying the thing that just broke is not a
          // fallback — escalate to the work model so the retry can actually succeed.
          await this.runFullHarness(active, query, !!opts.autonomous, onToken, true);
        }
      } else {
        await this.runFullHarness(active, query, !!opts.autonomous, onToken, false, opts.toolScope);
      }

      // Prefer the streamed text; fall back to the message-slice only if nothing streamed.
      const content = this.cleanTurnText(streamed) || this.collectTurnText(active, before);
      if (content) engineEvents.emit('message', this.msg('assistant', content));
      // A turn that ends with NOTHING is the worst failure mode there is: the UI returns to Ready and
      // the user cannot tell whether the agent ignored them, crashed, or is still working. Every path
      // that produces no text and no error must still say something actionable.
      else if (!this.turnAbort.signal.aborted) {
        engineEvents.emit('message', this.msg('system',
          '⚠ The model returned an empty response. Check /model — the configured model may not be served by your provider — or retry.', 'error'));
      }
      engineEvents.emit('cost_update', totalChars);
      // Whatever partial work streamed before the interrupt is kept; tell the user it stopped early.
      if (this.turnAbort.signal.aborted) engineEvents.emit('message', this.msg('system', '⏹ Turn interrupted.'));
      result = this.turnAbort.signal.aborted ? 'interrupted' : 'completed';
    } catch (e: any) {
      const detail = e?.message ?? String(e);
      // A governor veto (budget cap, denied permission, plan mode) otherwise looked like a silent
      // "no response" — only a dim log line. Surface it as a visible system message with the fix.
      if (e?.name === 'GovernorVetoError' || /budget|veto|plan mode/i.test(detail)) {
        engineEvents.emit('message', this.msg('system', `⚠ ${detail}`, 'error'));
      } else if (/No API keys configured/i.test(detail)) {
        // First-run / dismissed onboarding: a keyless turn must say so in the transcript, not die
        // into the hidden log view. Name the exact next step.
        const strictKimiK3 = /kimi-k3/i.test(String(process.env.BIMAX_DESKTOP_STRICT_MODEL || ''));
        engineEvents.emit('message', this.msg('system', strictKimiK3
          ? '⚠ Kimi K3 needs an NVIDIA provider key. Open Bimax Settings → Models → Providers and add or select NVIDIA.'
          : '⚠ No API key configured — run /keys to add one for the selected provider.', 'error'));
      } else if (/rejected the API key|unauthorized/i.test(detail)) {
        // Auth-dead pool (expired key): the adapter fails fast now; make the failure actionable.
        engineEvents.emit('message', this.msg('system', `⚠ ${detail}`, 'error'));
      } else if (/is not served by provider|model.{0,20}(not found|not available|does not exist)/i.test(detail)) {
        // A stale model pin. The adapter already writes the actionable form of this ("run /model to
        // pick an id <provider> serves"), but it only reached the hidden log view, so the turn looked
        // like an unexplained silence. This is THE failure the user actually hits after a provider
        // rotates its catalog — it belongs in the transcript.
        engineEvents.emit('message', this.msg('system', `⚠ ${detail}`, 'error'));
        // Startup healing trusts /models, which can list an id the provider then 404s. THIS is the
        // moment we learn the truth, so re-heal now that the adapter has marked the id unservable.
        // The turn is not replayed: it may already have run tools, and re-running those to recover
        // from a model error is not a trade the user agreed to. Repair, then say it's safe to retry.
        void this.healAfterModelFailure();
      } else {
        // Anything else still ends the turn with no reply. Surface a short form rather than leaving
        // the transcript blank; the full text stays in the log line emitted below.
        engineEvents.emit('message', this.msg('system', `⚠ Turn failed: ${detail}`, 'error'));
      }
      engineEvents.emit('log', { id: Date.now(), level: 'error', text: `Agent error: ${detail}`, timestamp: new Date() });
    } finally {
      this.busy = false;
      this.turnAbort = null;
      recordTurn({ firstTokenMs, totalMs: Date.now() - turnStart, streamedChars: totalChars });
      endTurnTimeline(); // close the phase timeline (persists the secret-free record for /perf)
      engineEvents.emit('thinking_clear');
      // Confidence-in-margin (turn-end form): report whether this turn's edits were checked. The
      // ledger delta tells us how many claims opened (edits) vs resolved (a build/test run named the
      // touched files) during the turn. Silent when the turn changed nothing — it only speaks to
      // confirm verified work or nudge that a change went unchecked.
      if (beforeLedger) {
        try {
          const sum = ledgerTurnSummary(beforeLedger, getEpistemicLedger().stats());
          if (sum) engineEvents.emit('message', this.msg('system', sum.text, sum.level));
        } catch { /* ledger best-effort */ }
      }
      // Steering the turn never took — it arrived after the loop's last step, or the turn never ran the loop — goes back
      // to the front-end, which queues it as the next message, before idle settles this turn (F7).
      const unused = drainSteer();
      if (unused.length) engineEvents.emit('steer_unused', { texts: unused });
      engineEvents.emit('spinner_state', 'idle', 'Ready');
      this.finishTurn?.();
      this.finishTurn = null;
    }
    return result;
  }

  /**
   * The full agent harness: model-tier routing, @-mention expansion, then the agent loop with tools,
   * memory, graph, outcome, and the self-critic/adversarial passes. Extracted so runTurn can pick
   * between this and the lightweight `converse` lane. Streams tokens through `onToken` (which also
   * feeds the perf timeline and the wire) and marks the routing/assembly phase boundaries.
   */
  /**
   * Re-run model healing after a live call proved a configured model unservable, and tell the user
   * what changed. Startup healing can only ask the provider what it CLAIMS to serve; a real 404 is
   * the only proof that a listed id is a lie. Best-effort and never throws — this runs while the
   * turn is already failing, and a failure to self-repair must not replace the original error.
   */
  private async healAfterModelFailure(): Promise<void> {
    try {
      const adapter: any = this.deps.options.llmAdapter;
      if (typeof adapter?.healModels !== 'function') return;
      const healed = await adapter.healModels() as Array<{ slot: string; from: string; to: string }>;
      if (!healed.length) return;
      // Session-scoped, like the boot healer: recover the turn without rewriting the model the
      // user chose. See the note in headless.entry.ts — persisting this is what made an explicit
      // pick silently revert to the top-ranked candidate on every later launch.
      const lines = healed.map(h => `  • ${h.slot}: "${h.from}" → ${h.to ? `"${h.to}"` : 'the Work model'}`);
      engineEvents.emit('message', this.msg('system',
        `Switched to a model your provider actually serves — send that again:\n${lines.join('\n')}`, 'info'));
      engineEvents.emit('config_changed');
    } catch { /* self-repair is best-effort */ }
  }

  private async runFullHarness(active: AgentPersona, query: string, autonomous: boolean, onToken: (t: string) => void, forceHeavy = false, toolScope?: TurnToolScope): Promise<void> {
    // Routing is local and deterministic (no model call) — it resolves in ~0ms. Kicked off before
    // @-mention expansion purely so the decision is ready the moment expansion completes.
    const tierPromise = decideTier(this.deps.options.llmAdapter, query, this.pinnedTier)
      .catch(() => ({ tier: 'lite' as const, via: 'fallback' as const }));

    let agentQuery = query;
    try { agentQuery = (await expandFileAtMentions(agentQuery, process.cwd())).text; } catch { /* best-effort */ }
    try { agentQuery = (await expandAtMentions(agentQuery, this.deps.graphStore, process.cwd())).text; } catch { /* best-effort */ }

    let useLite = !forceHeavy;
    try {
      const decision = await tierPromise;
      const tier = forceHeavy ? 'heavy' as const : decision.tier;
      useLite = tier === 'lite';
      engineEvents.emit('model_tier', { tier, pinned: this.pinnedTier });
    } catch { /* routing is best-effort; fall back to lite (or heavy when forced) */ }
    markRouted();

    // Pictures the person attached (N5) go to the model as images; one that cannot be sent is named, never dropped silently.
    const pictures = attachedPictures(query);
    if (pictures.skipped.length) {
      engineEvents.emit('message', this.msg('system',
        `Not sent as a picture (missing, not an image, over ${MAX_PICTURE_BYTES / 1024 / 1024} MB, or more than ${MAX_TURN_PICTURES}): ${pictures.skipped.map((p) => path.basename(p)).join(', ')}`, 'warn'));
    }

    engineEvents.emit('spinner_state', 'thinking', 'Thinking…');
    markAssembled();
    await active.execute(agentQuery, onToken, {
      toolNames: toolScope?.names,
      requireTool: toolScope?.required,
      images: pictures.paths,
      maxIterations: this.deps.options.maxToolIterations,
      planMode: this.deps.options.governor?.mode === 'plan',
      useLite,
      internalTurn: autonomous,
      signal: this.turnAbort?.signal,
      sessionId: getSessionRecorder()?.currentId() || undefined,
    });
  }

  private async runCommand(query: string): Promise<void> {
    const context: any = {
      cwd: process.cwd(),
      sessionId: getSessionRecorder()?.currentId() || undefined,
      options: this.deps.options,
      codebaseIndexer: this.deps.codebaseIndexer,
      graphStore: this.deps.graphStore,
      saveConfig: this.deps.saveConfig ?? (() => {}),
      addSystemMessage: (level: string, msg: string) =>
        engineEvents.emit('message', this.msg('system', msg, level)),
      // Menus / prompts are forwarded as messages carrying a uiComponent + payload; the front-end
      // renders them and replies via the protocol's menuSelect / reply channel.
      setActiveMenu: (menu: any) => this.emitMenu(menu),
      // Free-form prompts go through the request/reply channel (the old uiComponent-'prompt'
      // message was unrenderable out-of-process: its onResolve callback can't cross the wire, so
      // flows like /keys dead-ended with no visible prompt). isMasked rides along so secrets are
      // masked by contract. setActivePrompt(null) is the Ink "dismiss" — a no-op over the wire.
      setActivePrompt: (prompt: any) => {
        if (!prompt || !prompt.title) return;
        engineEvents.emit('input_prompt', prompt.title, (val: string) => prompt.onResolve?.(val), { masked: !!prompt.isMasked });
      },
      executeCommand: (cmd: string) => { void this.dispatch(cmd); },
      // Contract: receives LLM-ready Message[] (already through messageEntriesToLLM — raw UI
      // entries poisoned provider payloads). Returns false when refused so callers can stop.
      restoreMessages: (msgs: any[]): boolean => {
        // Refuse to swap the history array while a turn is running — the agent loop is mutating it,
        // and replacing it mid-flight corrupts the conversation. Same guard as runTurn().
        if (this.busy) { engineEvents.emit('status', 'Busy — finish the current turn before loading a session.'); return false; }
        const active = this.deps.personas.bimax;
        if (Array.isArray(msgs)) {
          for (const persona of new Set(Object.values(this.deps.personas))) {
            persona.messages = [];
            try { persona.resetContextSession?.(); } catch { /* best-effort */ }
          }
        }
        if (active && Array.isArray(msgs)) {
          active.messages = msgs.slice() as any;
          // Explicit session boundary (/clear, session load/resume): the session-scoped
          // ContextManager (calibration, warning latch, compaction epochs) resets WITH the history.
          try { (active as any).resetContextSession?.(); } catch { /* best-effort */ }
        }
        return true;
      },
      // Return the live conversation so /cost, /save, /sessions et al. work (was stubbed to [], which
      // made those commands silently show nothing).
      contextReport: (): string | null => {
        const active = this.deps.personas.bimax as { contextReport?: () => string } | undefined;
        return typeof active?.contextReport === 'function' ? active.contextReport() : null;
      },
      getMessages: () => {
        const active = this.deps.personas.bimax;
        return active && Array.isArray(active.messages) ? active.messages : [];
      },
    };

    try {
      const result = await globalCommandRegistry.execute(query, context);
      if (!result) return;
      if (result.type === 'message') engineEvents.emit('message', this.msg('system', result.content, result.level));
      else if (result.type === 'menu') this.emitMenu(result);
      else if (result.type === 'prompt') {
        // Free-form text prompt: bridge its onResolve callback through the request/reply channel.
        const r: any = result;
        engineEvents.emit('input_prompt', r.title, (val: string) => r.onResolve?.(val), { masked: !!r.isMasked });
      } else if (result.type === 'redirect') void this.dispatch(result.command);
      else if (result.type === 'dashboard') engineEvents.emit('message', this.uiMsg(result.uiComponent, result.payload));
    } catch (err: any) {
      if (!String(err?.message).includes('Unknown command')) {
        engineEvents.emit('message', this.msg('system', err?.message ?? String(err), 'error'));
      }
    }
  }

  /**
   * Emit an interactive menu to the front-end, remembering its onSelect so a later menuSelect can run
   * the real handler. The id correlates the two. Options with full-command values still work for
   * menus that have no onSelect (selectMenu falls back to dispatching the value).
   */
  private emitMenu(menu: any): void {
    const id = `menu-${++this.menuSeq}`;
    this.menus.set(id, { options: menu.options || [], onSelect: menu.onSelect });
    // Cap the registry — only the most recent few menus can realistically be selected.
    if (this.menus.size > 16) {
      const oldest = this.menus.keys().next().value;
      if (oldest) this.menus.delete(oldest);
    }
    // The MessageEntry carries the SAME id as the registry key. A front-end that replies with the
    // message's id (the desktop app does; the TUI reads payload.id) then hits the real entry — with
    // two different ids, every `onSelect` menu fell through to `dispatch(value)` and options whose
    // value is not a command (a model id, a rule index, `__custom__`) silently did nothing.
    engineEvents.emit('message', {
      ...this.uiMsg('menu', {
        id,
        title: menu.title,
        subtitle: menu.subtitle,
        options: (menu.options || []).map(undecorate),
        initialIndex: menu.initialIndex,
      }),
      id,
    });
  }

  /** Run a menu option's onSelect (or dispatch its value as a command if the menu had none). */
  selectMenu(id: string, value: string): void {
    const entry = this.menus.get(id);
    if (entry?.onSelect) {
      const opt = entry.options.find((o: any) => o?.value === value) ?? { value, label: value };
      this.menus.delete(id);
      try { entry.onSelect(opt); } catch (e: any) {
        engineEvents.emit('message', this.msg('system', `Menu action failed: ${e?.message ?? e}`, 'error'));
      }
      return;
    }
    this.menus.delete(id);
    // No onSelect (or unknown menu): the value is a command/redirect — dispatch it as the user would.
    if (value) void this.dispatch(value);
  }

  /** Concatenate this turn's assistant text, stripping reasoning/tool-call scaffolding. */
  private collectTurnText(active: AgentPersona, before: number): string {
    const joined = active.messages
      .slice(before)
      .filter((m: any) => m.role === 'assistant' && typeof m.content === 'string' && m.content.trim())
      .map((m: any) => m.content.trim())
      .join('\n\n');
    return this.cleanTurnText(joined);
  }

  /** Strip reasoning / tool-call scaffolding from a chunk of assistant text. */
  private cleanTurnText(text: string): string {
    return (text || '')
      .replace(/<thinking>[\s\S]*?<\/thinking>/g, '')
      .replace(/<think>[\s\S]*?<\/think>/g, '')
      .replace(/<tool_call>[\s\S]*?<\/tool_call>/g, '')
      // A still-open <tool_call> is a streaming cutoff — strip it to the end, but ONLY when a JSON
      // payload actually follows. Otherwise a literal "<tool_call>" mentioned in prose would nuke
      // the rest of a real answer (the audit's display-eating bug).
      .replace(/<tool_call>\s*[[{][\s\S]*$/, '')
      .trim();
  }

  private msg(role: 'user' | 'assistant' | 'system', content: string, level?: string): MessageEntry {
    return { id: `msg-${Date.now()}-${Math.random().toString(36).slice(2, 7)}`, role, level: level as any, content, timestamp: new Date() };
  }

  private uiMsg(uiComponent: string, payload: any): MessageEntry {
    return { id: `ui-${Date.now()}-${Math.random().toString(36).slice(2, 7)}`, role: 'system', uiComponent, payload, content: '', timestamp: new Date() };
  }
}

import { capabilitySnapshot, capabilityMessage } from '../core/capability.status';
import { EventEmitter } from 'events';
import {
  Outbound, Inbound, ReplyMsg, MenuSelectMsg, CompletionItem, CatalogResultMsg, HostCapability, JsonValue, TurnToolScope,
  FORWARDED_EVENTS, PROMPT_EVENT, DIFF_PROMPT_EVENT, INPUT_PROMPT_EVENT, HOST_CALL_EVENT,
  PROTOCOL_FEATURES, PROTOCOL_MAX_COMPATIBLE_MAJOR, PROTOCOL_MIN_COMPATIBLE_MAJOR,
  PROTOCOL_SEMVER, PROTOCOL_VERSION, sanitizeArgs,
} from './protocol';
import { markReady, loadPersistedTimelines } from '../telemetry/perf';

export interface HostHandlers {
  /** A submitted prompt line (user turn or slash command) arrived from the front-end. */
  onInput?: (text: string, toolScope?: TurnToolScope, displayText?: string) => void;
  /** The front-end asked to cancel the in-flight turn. */
  onInterrupt?: () => void;
  /** Words for the running turn, taken at its next step (F7). */
  onSteer?: (text: string) => void;
  /** The front-end asked for autocomplete candidates for the current input. */
  onQuery?: (text: string) => CompletionItem[] | Promise<CompletionItem[]>;
  /** The front-end picked an option in a menu the engine emitted — run that menu's onSelect. */
  onMenuSelect?: (id: string, value: string) => void;
  /** Settings page read — return the allowlisted config subset (v3). */
  onConfigGet?: () => Record<string, any>;
  /** Settings page write — merge the allowlisted patch, return the post-write subset (v3). */
  onConfigSet?: (patch: Record<string, any>) => Record<string, any> | Promise<Record<string, any>>;
  /** Provider + model catalogue read (v3 additive) — answered with a `catalogResult`. */
  onCatalogGet?: (refresh: boolean) => Promise<Omit<CatalogResultMsg, 't' | 'id'>>;
  /**
   * Switch the active provider, optionally saving a key for it first (v3 additive). The key is
   * write-only: it is handed straight to the engine's secrets path and is never echoed back.
   */
  onProviderSet?: (input: { name: string; baseURL?: string; apiKey?: string }) => Promise<Omit<CatalogResultMsg, 't' | 'id'>>;
  /** Typed session resume (recovery flows) — restore the saved thread with this id. */
  onResume?: (id: string) => void;
  /** Atomically apply mode/tier/autonomy controls; the session serializes the underlying actions. */
  onControls?: (controls: { mode?: string; tier?: string; autonomy?: string }) => void | Promise<void>;
}

/**
 * Engine-side endpoint of the UI protocol. It bridges the in-process `engineEvents` emitter +
 * GlobalPrompter approval round-trip to an out-of-process front-end, transport-agnostically:
 * you give it a `write` sink (stdout, a socket, a test buffer) and feed it inbound lines.
 *
 *   • Forwarded events  → serialized as `event` messages.
 *   • `veto_prompt`      → translated to a `request`; its in-process resolve callback is held in
 *                          a pending map and fired when the matching `reply` returns.
 *   • inbound `input`    → routed to handlers.onInput (the engine's existing dispatch).
 *
 * Nothing here touches Ink: attaching the host adds listeners; the in-process appStore bridge in
 * events.ts keeps working untouched, so the two front-ends are interchangeable, not exclusive.
 */
/** What a host call resolves with: the app's value, or why it did not (or could not) answer. */
export interface HostCallResult { ok: boolean; value?: JsonValue; error?: string }

export class ProtocolHost {
  private emitter: EventEmitter | null = null;
  private listeners: Array<{ event: string; fn: (...a: any[]) => void }> = [];
  private pending = new Map<number, (answer: string) => void>();
  // Request kind per pending id — resolution announcements skip kind 'input' (may carry secrets).
  private pendingKind = new Map<number, string>();
  private nextRequestId = 1;

  /** Announce a request's resolution to in-process observers (ReviewManager). Never for inputs. */
  private announceResolved(id: number, value: string, interrupted?: boolean): void {
    const kind = this.pendingKind.get(id);
    this.pendingKind.delete(id);
    if (!kind || kind === 'input' || !this.emitter) return;
    try {
      this.emitter.emit('request_resolved', { id, value, ...(interrupted ? { interrupted: true } : {}) });
    } catch { /* observers must never break the wire */ }
  }

  constructor(
    private write: (line: Outbound) => void,
    private handlers: HostHandlers = {},
  ) {}

  /** Subscribe to the engine's event seam and emit the handshake. */
  attach(emitter: EventEmitter): void {
    if (this.emitter) throw new Error('[ProtocolHost] already attached');
    this.emitter = emitter;

    for (const name of FORWARDED_EVENTS) {
      const fn = (...args: any[]) => this.write({ t: 'event', name, args: sanitizeArgs(args) });
      emitter.on(name, fn);
      this.listeners.push({ event: name, fn });
    }

    // Review-domain meta-events: the host is the one choke point every approval round-trip passes
    // through (veto, diff, ask, input — with the wire-visible ids and duplicate-reply dropping),
    // so it announces request lifecycle on the engine emitter for in-process observers
    // (ReviewManager). These are internal — deliberately NOT in FORWARDED_EVENTS.
    const announcePending = (id: number, kind: string, question: string, isAsk?: boolean) => {
      this.pendingKind.set(id, kind);
      try { emitter.emit('request_pending', { id, kind, question, isAsk: !!isAsk }); } catch { /* observers must never break the wire */ }
    };

    // veto_prompt(question, options, resolve, isAsk?) — the one event carrying a callback.
    // `body`: an approval card's detail (tools/thread.changes.ts approvalCard) — every affected item, whether it
    // can be undone, and the command itself.
    const promptFn = (question: string, options: string[], resolve: (a: string) => void, isAsk?: boolean, isMultiSelect?: boolean, body?: string) => {
      const id = this.nextRequestId++;
      this.pending.set(id, resolve);
      announcePending(id, 'prompt', question, isAsk);
      this.write({ t: 'request', id, kind: 'prompt', question, options: options || [], isAsk: !!isAsk, isMulti: !!isMultiSelect, ...(body ? { body } : {}) });
    };
    emitter.on(PROMPT_EVENT, promptFn);
    this.listeners.push({ event: PROMPT_EVENT, fn: promptFn });

    // diff_prompt(summary, diff, resolve) — the inline diff-approval gate. Same request/reply
    // mechanism as veto_prompt, but carries the diff body for the front-end to render.
    const diffFn = (summary: string, diff: string, resolve: (a: string) => void) => {
      const id = this.nextRequestId++;
      this.pending.set(id, resolve);
      announcePending(id, 'diff', summary);
      this.write({ t: 'request', id, kind: 'diff', question: summary, options: ['Approve', 'Reject'], body: diff });
    };
    emitter.on(DIFF_PROMPT_EVENT, diffFn);
    this.listeners.push({ event: DIFF_PROMPT_EVENT, fn: diffFn });

    // input_prompt(title, resolve, opts?) — a free-form text prompt (e.g. /keys asking for an API
    // key). `opts.masked` rides the wire so the front-end masks secrets BY CONTRACT — not by
    // guessing from the question's wording. Announced with kind 'input' so review observers can
    // ignore it; input replies are never re-announced (they can carry secrets).
    const inputFn = (title: string, resolve: (a: string) => void, opts?: { masked?: boolean }) => {
      const id = this.nextRequestId++;
      this.pending.set(id, resolve);
      announcePending(id, 'input', title);
      this.write({ t: 'request', id, kind: 'input', question: title, options: [], masked: !!opts?.masked });
    };
    emitter.on(INPUT_PROMPT_EVENT, inputFn);
    this.listeners.push({ event: INPUT_PROMPT_EVENT, fn: inputFn });

    // Compatibility tombstone: retired calls fail immediately and never reach the app.
    const hostCallFn = (capability: HostCapability, op: string, args: JsonValue, resolve: (r: HostCallResult) => void) => {
      resolve({ ok: false, error: 'Computer Use has been removed from Bimax.' });
    };
    emitter.on(HOST_CALL_EVENT, hostCallFn);
    this.listeners.push({ event: HOST_CALL_EVENT, fn: hostCallFn });

    markReady(); // engine wired + handshake sent — the cold-start clock stops here (/perf)
    loadPersistedTimelines(); // seed /perf so it can explain prior turns after a restart/crash
    this.write({
      t: 'hello',
      engine: {
        version: process.env.BIMAX_ENGINE_VERSION?.trim() || 'dev',
        buildCommit: process.env.BIMAX_ENGINE_COMMIT?.trim() || 'unknown',
      },
      protocolVersion: PROTOCOL_SEMVER,
      protocolMajor: PROTOCOL_VERSION,
      minCompatibleMajor: PROTOCOL_MIN_COMPATIBLE_MAJOR,
      maxCompatibleMajor: PROTOCOL_MAX_COMPATIBLE_MAJOR,
      features: [...PROTOCOL_FEATURES],
    });
    this.write({ t: 'ready', protocol: PROTOCOL_VERSION });
    for (const status of capabilitySnapshot().filter(s => s.state !== 'ready')) {
      this.write({ t: 'event', name: 'message', args: sanitizeArgs([capabilityMessage(status)]) });
    }
  }

  /** Route one decoded inbound message. Unknown / stale messages are ignored, never thrown. */
  ingest(msg: Inbound): void {
    switch (msg.t) {
      case 'reply': {
        const { id, value } = msg as ReplyMsg;
        const resolve = this.pending.get(id);
        if (resolve) { this.pending.delete(id); this.announceResolved(id, value); resolve(value); }
        return; // a reply with no pending id is a late/duplicate answer — drop it
      }
      case 'host_result': {
        return; // Compatibility tombstone: no active capability or pending calls remain.
      }
      case 'input':
        // A forced clear ends the task that is running, like Stop, before the clear itself is dispatched.
        if (/^\/clear\s+force(?:\s|$)/i.test(String(msg.text ?? '').trim())) {
          this.handlers.onInterrupt?.();
          this.cancelPending();
        }
        this.handlers.onInput?.(msg.text, msg.toolScope, msg.displayText);
        return;
      case 'menuSelect': {
        const { id, value } = msg as MenuSelectMsg;
        this.handlers.onMenuSelect?.(id, value);
        return;
      }
      case 'interrupt':
        this.handlers.onInterrupt?.();
        this.cancelPending();
        return;
      case 'steer':
        this.handlers.onSteer?.(String((msg as { text?: unknown }).text ?? ''));
        return;
      case 'ping':
        // Answered synchronously from the ingest path — no engine work is awaited, so a pong only
        // fails to return when the process/event loop is genuinely wedged (which is the signal).
        this.write({ t: 'pong', id: msg.id });
        return;
      case 'query': {
        const { id, text } = msg;
        Promise.resolve(this.handlers.onQuery?.(text) ?? [])
          .then(items => this.write({ t: 'queryResult', id, items }))
          .catch(() => this.write({ t: 'queryResult', id, items: [] }));
        return;
      }
      case 'configGet': {
        let config: Record<string, any> = {};
        try { config = this.handlers.onConfigGet?.() ?? {}; } catch { /* answer empty, never hang */ }
        this.write({ t: 'configResult', id: msg.id, config });
        return;
      }
      case 'resume': {
        // Ids come from ui_snapshot session lists, but validate anyway: a session id is a short
        // slug, never something with newlines/quotes that could smell like command injection.
        const id = String(msg.id ?? '').trim();
        if (id && /^[\w.:-]{1,128}$/.test(id)) this.handlers.onResume?.(id);
        return;
      }
      case 'controls': {
        const mode = ['general', 'explore', 'sketch', 'code', 'beast'].includes(String(msg.mode)) ? msg.mode : undefined;
        const tier = ['auto', 'lite', 'heavy'].includes(String(msg.tier)) ? msg.tier : undefined;
        const autonomy = ['ask', 'auto', 'plan', 'full'].includes(String(msg.autonomy)) ? msg.autonomy : undefined;
        if (mode || tier || autonomy) void this.handlers.onControls?.({ mode, tier, autonomy });
        return;
      }
      case 'configSet': {
        const { id, patch } = msg;
        Promise.resolve(this.handlers.onConfigSet?.(patch ?? {}) ?? {})
          .then(config => this.write({ t: 'configResult', id, config }))
          .catch(() => this.write({ t: 'configResult', id, config: {} }));
        return;
      }
      case 'catalogGet': {
        const { id } = msg;
        this.answerCatalog(id, this.handlers.onCatalogGet?.(msg.refresh === true));
        return;
      }
      case 'providerSet': {
        const { id } = msg;
        // Validate before the key ever reaches a handler: a provider name is a short slug, and a
        // base URL must be an http(s) origin. An unvalidated baseURL is a credential-exfiltration
        // primitive — it is where the API key gets sent on the very next request.
        const name = String(msg.name ?? '').trim();
        if (!/^[\w.-]{1,64}$/.test(name)) {
          this.answerCatalog(id, Promise.reject(new Error('Invalid provider name.')));
          return;
        }
        const baseURL = String(msg.baseURL ?? '').trim();
        if (baseURL && !/^https?:\/\/[^\s]+$/i.test(baseURL)) {
          this.answerCatalog(id, Promise.reject(new Error('A provider endpoint must be an http(s) URL.')));
          return;
        }
        this.answerCatalog(id, this.handlers.onProviderSet?.({
          name,
          ...(baseURL ? { baseURL } : {}),
          ...(typeof msg.apiKey === 'string' && msg.apiKey ? { apiKey: msg.apiKey } : {}),
        }));
        return;
      }
    }
  }

  /**
   * Answer a catalogue request, correlated by `id`.
   *
   * A front-end blocks its picker on this reply, so every path must produce exactly one message:
   * an unhandled message kind or a rejected fetch answers with an empty catalogue carrying the
   * reason, never with silence.
   */
  private answerCatalog(id: number, work?: Promise<Omit<CatalogResultMsg, 't' | 'id'>>): void {
    Promise.resolve(work ?? { providers: [], models: [], error: 'This engine does not provide a catalogue.' })
      .then(result => this.write({ t: 'catalogResult', id, ...result }))
      .catch((e: any) => this.write({
        t: 'catalogResult', id, providers: [], models: [],
        error: String(e?.message || e || 'The catalogue could not be read.'),
      }));
  }

  /**
   * Resolve every unanswered prompt as interrupted. Stop and a forced clear end the task that asked, so a late
   * "Approve" must not reach it (record 49); a reply that arrives afterwards finds nothing pending and is ignored.
   */
  private cancelPending(): void {
    const pending = [...this.pending.entries()];
    this.pending.clear();
    for (const [id, resolve] of pending) {
      this.announceResolved(id, '', true);
      try { resolve(''); } catch { /* ignore */ }
    }
  }

  /** Number of approval requests still awaiting an answer (for diagnostics / tests). */
  pendingCount(): number { return this.pending.size; }

  /** Remove all listeners. Any unanswered prompts are resolved empty so the engine doesn't hang. */
  detach(): void {
    if (this.emitter) {
      for (const { event, fn } of this.listeners) this.emitter.off(event, fn);
    }
    // Announce interruption BEFORE dropping the emitter so review observers record that these
    // approvals were never answered (front-end gone / shutdown) — not silently approved or denied.
    for (const id of this.pending.keys()) this.announceResolved(id, '', true);
    this.listeners = [];
    this.emitter = null;
    for (const resolve of this.pending.values()) {
      try { resolve(''); } catch { /* ignore */ }
    }
    this.pending.clear();
    this.pendingKind.clear();
  }
}

// BiMax UI protocol — the wire contract between the engine (Node) and the out-of-process
// front-end (the Go / Bubble Tea TUI in tui/). It exists so the engine's UI seam — the
// `engineEvents` emitter (src/engine/events.ts) + the GlobalPrompter approval round-trip — can be
// driven over a pipe instead of in-process, WITHOUT touching engine logic. This is the sole
// interactive path; it activates in headless mode, which the TUI always spawns.
//
// Transport is newline-delimited JSON (NDJSON): one JSON object per line, both directions. See
// codec.ts for framing and host.ts for the engine-side endpoint.

// v2 (2026-07-10): ui_snapshot gains optional sessions / checkpoints / git fields (all additive —
// a v1 front-end ignores them; a v2 front-end hides the matching UI when they're absent).
// v3 (2026-07-11): silent config round-trip — configGet/configSet inbound + configResult outbound,
// so graphical front-ends drive settings pages without printing menus into the transcript.
// v3 additive (2026-07-12): `boot` + `health` outbound (startup progress + liveness heartbeat for
// the desktop supervisor) and `resume` inbound (typed session-resume, so front-ends never have to
// synthesize a slash command). All additive — a front-end that doesn't know them ignores them, an
// engine that predates `resume` drops it — so the version stays 3.
// v3 additive (2026-08-10): `catalogGet` / `providerSet` inbound + `catalogResult` outbound — the
// model and provider catalogue, so a graphical front-end can offer a real picker (which provider,
// which key, which of the ids that provider ACTUALLY serves) instead of a free-text model field.
// Additive, so the major stays 3 and the `catalog` feature flag gates it.
export const PROTOCOL_VERSION = 3;
/** Semantic wire release. Major compatibility remains available to v2 clients. */
export const PROTOCOL_SEMVER = '3.8.0';
export const PROTOCOL_MIN_COMPATIBLE_MAJOR = 2;
export const PROTOCOL_MAX_COMPATIBLE_MAJOR = 3;

/** Negotiated features. Clients must hide/degrade features that are not advertised. */
export const PROTOCOL_FEATURES = [
  'rich-presentation',
  'approvals',
  'boot',
  'catalog',
  'config',
  'controls',
  'health',
  'interrupt',
  'resume',
  'review-snapshot',
  'outcome-snapshot',
  'host-call',
  'turn-tool-scope',
] as const;

// A JSON-safe value. The codec guarantees only these cross the wire (sanitizeArgs strips the rest).
export type JsonValue = string | number | boolean | null | JsonValue[] | { [k: string]: JsonValue };

// --- Outbound: engine → front-end ----------------------------------------------------------

/** A forwarded `engineEvents` emit. `name` is the event, `args` its (sanitized) payload. */
export interface EventMsg {
  t: 'event';
  name: string;
  args: JsonValue[];
}

/**
 * An approval / ask-user request that needs an answer before the engine can continue. This is
 * the GlobalPrompter `veto_prompt` round-trip: its in-process `resolve` callback can't cross a
 * pipe, so it becomes a request `id` the front-end answers with a matching `reply`.
 */
export interface RequestMsg {
  t: 'request';
  id: number;
  kind: 'prompt' | 'diff' | 'input'; // option-select | diff-approval | free-form text
  question: string;
  options: string[];
  isAsk?: boolean; // true for the AskUser tool (free-form) vs a governor yes/no/always veto
  isMulti?: boolean; // true for multi-select checklists
  body?: string; // for kind:'diff', the unified diff to render before the choices
  masked?: boolean; // for kind:'input': the answer is a secret — render it as bullets, never echo
}

/**
 * The engine asks the app that hosts it to do something only the app may do (record 65): look at an app's window
 * (stage 2), press one control in it (stage 3), type into one box (stage 6, 3.5.0) or scroll it (3.6.0), for a Bimax
 * Thread the user let do so. The app answers with a {@link HostResultMsg} of the same `id`. It travels on the engine's own channel, never a
 * socket or an environment token, so nothing the engine runs (a shell command) can make the call. The app decides —
 * grant, scope, whether a step needs the person's card, what the result may contain; the engine only asks.
 */
export type HostCapability = 'look' | 'press' | 'type' | 'scroll';

export interface HostCallMsg {
  t: 'host_call';
  id: number;
  capability: HostCapability;
  op: string;
  args: JsonValue;
}

/** Handshake — sent once when the host attaches, so the front-end can version-check. */
export interface ReadyMsg {
  t: 'ready';
  protocol: number;
}

/**
 * Rich, additive handshake sent immediately before `ready`.
 *
 * Older v2/v3 clients ignore this unknown message and continue on `ready`; current clients use it
 * to negotiate an overlapping major range and feature vocabulary before enabling optional UI.
 */
export interface HelloMsg {
  t: 'hello';
  engine: { version: string; buildCommit: string };
  protocolVersion: string;
  protocolMajor: number;
  minCompatibleMajor: number;
  maxCompatibleMajor: number;
  features: string[];
}

/** A single autocomplete candidate (slash command, @symbol, or @path). */
export interface CompletionItem {
  value: string; // the text to insert (e.g. "/git", "@handlePayment", "@./src/")
  label: string; // display label
  desc: string; // short description / category
  kind: 'command' | 'symbol' | 'path';
  disabled?: boolean;
  disabledReason?: string;
}

/** Completions for a {@link QueryMsg}, correlated by `id` so stale results can be dropped. */
export interface QueryResultMsg {
  t: 'queryResult';
  id: number;
  items: CompletionItem[];
}

/** Liveness answer to a {@link PingMsg} — echoes `id` so the front-end can match it. */
export interface PongMsg {
  t: 'pong';
  id: number;
}

/**
 * The engine's settings, answering a {@link ConfigGetMsg} or {@link ConfigSetMsg} — only the
 * allowlisted, JSON-safe subset of EngineConfig crosses the wire (headless.entry owns the list).
 */
export interface ConfigResultMsg {
  t: 'configResult';
  id: number;
  config: { [k: string]: JsonValue };
}

/**
 * Startup progress. Emitted BEFORE the protocol host attaches (boot.status.ts writes it directly — on
 * stdout, or on the worker's port when the engine is a worker thread in the app), so a supervising
 * front-end can show real phases instead of an indefinite spinner.
 * Phases arrive in order; `ready` (the handshake) supersedes them all.
 */
export interface BootMsg {
  t: 'boot';
  phase: 'booting' | 'loading_storage' | 'loading_graph' | 'loading_tools' | 'loading_interface' | 'restoring_session';
  detail?: string;
  pid: number;
}

/**
 * Periodic liveness heartbeat, emitted every few seconds once the engine is interactive. A stalled
 * stream of these means the event loop is wedged (or the process is gone) — the supervising
 * front-end distinguishes that from legitimate long work via `activeTurn`.
 *
 * When the engine is a worker thread in the app (record 64), `uptimeMs` and `rssMb` describe the
 * whole app process, which is all Node reports inside a worker; `heapMb` is the engine's own isolate.
 */
export interface HealthMsg {
  t: 'health';
  uptimeMs: number;
  rssMb: number;
  heapMb: number;
  eventLoopDelayMs: number; // p99 event-loop delay since the last heartbeat
  activeTurn: boolean; // a user turn is executing (long work is expected)
  phase: 'ready';
}

/**
 * One provider the engine can talk to.
 *
 * `hasKey` is the only thing said about credentials — a key never crosses the wire, in either
 * direction, and `keyHint` is a display tail (last 4 characters) so a user can tell two saved keys
 * apart without the value being recoverable.
 */
export interface ProviderEntry {
  name: string;
  label: string;
  baseURL: string;
  /** The environment variable this provider's key is read from (shown as setup guidance). */
  apiKeyEnv: string;
  hasKey: boolean;
  keyHint?: string;
  /** Number of keys in the rotation for this provider. */
  keyCount: number;
  /** True for the provider the engine is currently using. */
  active: boolean;
}

/**
 * One model the front-end may offer for a slot.
 *
 * `served` is the distinction that matters and the reason this crosses the wire at all: catalogue
 * membership is a curated recommendation, while `served` reports whether the ACTIVE provider's
 * `/models` endpoint actually lists the id right now. A picker that hides unserved models makes a
 * stale pin undiagnosable — the user's configured model simply vanishes from the list — so both
 * are sent and the front-end shows the gap.
 *
 * `avoidAutoSelect` mirrors the catalogue's own bar on choosing this model automatically; the
 * reason is in `desc`. The user may still pick it deliberately.
 */
export interface CatalogModelEntry {
  id: string;
  label: string;
  desc: string;
  /** 'coding' = Work, 'lite' = Quick, 'vision' = Vision, 'other' = needs its own key. */
  tier: 'coding' | 'vision' | 'lite' | 'other';
  /** Curated slot recommendations. A model may appear in more than one slot. */
  recommendedFor?: Array<'coding' | 'vision' | 'lite'>;
  tags?: string[];
  parameters?: string;
  /** ISO release date from a curated first-party model card. */
  releaseDate?: string;
  served: boolean;
  curated: boolean;
  avoidAutoSelect?: boolean;
  /** Resolved model capabilities, so the UI can disable knobs a model does not have. */
  capabilities?: {
    visionInput: boolean;
    reasoningEffortKnob: boolean;
    thinking: boolean;
    structuredOutputs: boolean;
    parallelToolCalls: boolean;
    contextWindow: number;
  };
}

/**
 * The provider + model catalogue, answering a {@link CatalogGetMsg} or {@link ProviderSetMsg}.
 * `error` is set when the live model list could not be fetched (offline, bad key, no `/models`
 * endpoint); `models` then carries the curated catalogue with `served` false throughout, which the
 * front-end must present as "unverified", never as "unavailable".
 */
export interface CatalogResultMsg {
  t: 'catalogResult';
  id: number;
  providers: ProviderEntry[];
  models: CatalogModelEntry[];
  error?: string;
}

export type Outbound =
  | EventMsg
  | RequestMsg
  | ReadyMsg
  | HelloMsg
  | QueryResultMsg
  | PongMsg
  | ConfigResultMsg
  | CatalogResultMsg
  | BootMsg
  | HealthMsg
  | HostCallMsg;

// --- Inbound: front-end → engine -----------------------------------------------------------

/** The app's answer to a {@link HostCallMsg}, correlated by `id`. `error` is shown to the model as the tool's result. */
export interface HostResultMsg {
  t: 'host_result';
  id: number;
  ok: boolean;
  value?: JsonValue;
  error?: string;
}

/** The answer to a {@link RequestMsg}, correlated by `id`. */
export interface ReplyMsg {
  t: 'reply';
  id: number;
  value: string;
}

/** A submitted prompt line — a user turn OR a slash command (engine decides, as handleSubmit does). */
/** Host-selected per-turn tool boundary. It cannot install a tool or create host authority. */
export interface TurnToolScope { names: string[]; required?: string }
export interface InputMsg {
  t: 'input';
  text: string;
  toolScope?: TurnToolScope;
  /** User-visible words, without host context added to text. */
  displayText?: string;
}

/** Cancel the in-flight turn (Ctrl-C / Esc in the front-end). */
export interface InterruptMsg {
  t: 'interrupt';
}

/**
 * Words for the running turn (backlog F7): taken at its next step rather than after it ends. Sent when the task is
 * idle, it is an ordinary input.
 */
export interface SteerMsg {
  t: 'steer';
  text: string;
}

/** Ask the engine for autocomplete candidates for the current input `text`. */
export interface QueryMsg {
  t: 'query';
  id: number;
  text: string;
}

/**
 * The user picked an option in an interactive menu. `id` correlates to the menu the engine emitted;
 * `value` is the chosen option's value. The engine runs that menu's `onSelect` (which can't cross the
 * wire as a callback) — falling back to dispatching `value` as a command for menus that have none.
 */
export interface MenuSelectMsg {
  t: 'menuSelect';
  id: string;
  value: string;
}

/**
 * Liveness probe from the front-end. Answered immediately with a {@link PongMsg} — if the answer
 * doesn't come back, the engine's event loop is wedged (or the process is a zombie) and the
 * front-end can tell the user instead of showing a spinner forever.
 */
export interface PingMsg {
  t: 'ping';
  id: number;
}

/** Read the engine's settings (allowlisted subset) — answered with a {@link ConfigResultMsg}. */
export interface ConfigGetMsg {
  t: 'configGet';
  id: number;
}

/**
 * Write settings: `patch` merges into the engine config (allowlisted keys only; unknown keys are
 * dropped, never errors). Answered with the post-write {@link ConfigResultMsg} and followed by a
 * `config_changed` event so every attached front-end (and ui_snapshot) refreshes.
 */
export interface ConfigSetMsg {
  t: 'configSet';
  id: number;
  patch: { [k: string]: JsonValue };
}

/**
 * Resume a saved session by id — the typed equivalent of the user running /resume. Lets a
 * graphical front-end's recovery flow restore a thread without synthesizing slash-command text.
 * Ignored (never an error) when the id doesn't resolve to a saved session.
 */
export interface ResumeMsg {
  t: 'resume';
  id: string;
}

/**
 * Atomically apply shell controls. A graphical front-end must not synthesize several independent
 * slash-command messages for one autonomy preset: those dispatch concurrently and can leave the
 * governor, plan mode, and diff gate disagreeing. The headless session serializes this one request.
 */
export interface ControlsMsg {
  t: 'controls';
  mode?: 'general' | 'explore' | 'sketch' | 'code' | 'beast';
  tier?: 'auto' | 'lite' | 'heavy';
  autonomy?: 'ask' | 'auto' | 'plan' | 'full';
}

/**
 * Read the provider + model catalogue — answered with a {@link CatalogResultMsg}.
 *
 * `refresh` re-fetches the active provider's live `/models` list instead of answering from the
 * session cache. Costs a request, so the front-end should only set it on an explicit user action
 * (opening the picker, pressing refresh, after saving a key).
 */
export interface CatalogGetMsg {
  t: 'catalogGet';
  id: number;
  refresh?: boolean;
}

/**
 * Switch the active provider, optionally saving a key for it first.
 *
 * `apiKey` is write-only and one-way: it is stored in the engine's secrets file (never in
 * config.json, never echoed back) and applied to the live key rotation, so a key added here takes
 * effect without a restart. Answered with a {@link CatalogResultMsg} for the newly active
 * provider — which is how the front-end confirms the key works: the model list either populates or
 * comes back with `error`.
 *
 * `baseURL` registers/overrides an OpenAI-compatible endpoint, covering local models and proxies.
 */
export interface ProviderSetMsg {
  t: 'providerSet';
  id: number;
  name: string;
  baseURL?: string;
  apiKey?: string;
}

export type Inbound =
  | ReplyMsg
  | InputMsg
  | InterruptMsg
  | SteerMsg
  | QueryMsg
  | MenuSelectMsg
  | PingMsg
  | ConfigGetMsg
  | ConfigSetMsg
  | CatalogGetMsg
  | ProviderSetMsg
  | ResumeMsg
  | ControlsMsg
  | HostResultMsg;

// --- Event vocabulary ----------------------------------------------------------------------

// The serializable engine→UI signals forwarded verbatim (kept in sync with the contract block at
// the bottom of src/engine/events.ts). `veto_prompt` is intentionally absent — it carries a callback
// and is translated to a RequestMsg by the host instead.
export const FORWARDED_EVENTS: readonly string[] = [
  'log',
  'message',
  'tool_call',
  'tool_call_result',
  'spinner_state',
  'status',
  'mode_change',
  'model_tier',
  'set_tier',
  'cost_update',
  'todo_update',
  // F3: a task's completion checks and their last result (outcome/completion.check.ts).
  'completion_check',
  // F5: a run stopped at its time limit, so the front-end does not report it as done or as stopped by the user.
  'turn_limit',
  // F4: a task asks to be resumed by an event, or cancels that; the app keeps and delivers wakes.
  'wake_request',
  'wake_cancel',
  // FL1 part 2: which files in a folder with an outcome are ready, and which need the person.
  'folder_status',
  // FL2: a plan of moves, shown as a preview the person rearranges and applies.
  'organize_plan',
  // F7: steering words were taken by the running turn ('steered'), or held for its next step ('steer_queued').
  'steer_queued',
  'steered',
  'steer_unused',
  'subagent_update',
  'thinking',
  'thinking_clear',
  'config_changed',
  'graph_changed',
  'cwd_changed',
  'mcp_changed',
  'rerun_onboarding',
  'shutdown',
  'loop_detected',
  'goals_changed',
  // /clear wipes the front-end transcript (the engine has no in-process UI to intercept it).
  'clear',
  // True resume: `{ id, entries }` — the saved thread's transcript (messages + tool lines) so a
  // graphical front-end can rebuild its scrollback, not just inject invisible context.
  'session_restore',
  // A resume that could not happen: `{ id, reason }`, so a front-end waiting on that id says so instead of waiting forever.
  'session_restore_failed',
  // Review domain: the current thread's derived review snapshot (plan, approvals, attributed
  // changes, verification runs, checkpoint state). Always a FULL snapshot — a reconnecting
  // front-end is correct again on the next emit.
  'review_update',
  // Outcome domain: compact full snapshot of the active contract, acceptance gate, task/gap counts,
  // iteration and blocker. Null means this thread has no substantial outcome contract yet.
  'outcome_update',
  // The driver re-emits each reply token here so the out-of-process front-end can render the stream.
  'stream_token',
  'engine_notice',
  // Footer state read from engine singletons; snapshotted for the out-of-process front-end.
  'ui_snapshot',
];

/** Events the host special-cases into a {@link RequestMsg} (they carry a resolve callback). */
export const PROMPT_EVENT = 'veto_prompt';
export const DIFF_PROMPT_EVENT = 'diff_prompt';
export const INPUT_PROMPT_EVENT = 'input_prompt';
/** `host_call(capability, op, args, resolve)` — the host turns it into a {@link HostCallMsg}; `resolve` gets the result. */
export const HOST_CALL_EVENT = 'host_call';

// React element brand — so a `message` event carrying a JSX `content`/`payload` doesn't blow up
// JSON.stringify; we replace it with a placeholder the front-end can render generically.
const REACT_ELEMENT = Symbol.for('react.element');

/**
 * Make an event's args safe to serialize: drop functions, replace React elements with a marker,
 * and let JSON handle the rest (Dates become ISO strings). Never throws — a value that can't be
 * cloned (e.g. a cycle) collapses to null rather than killing the stream.
 */
export function sanitizeArgs(args: any[]): JsonValue[] {
  const replacer = (_key: string, value: any): any => {
    if (typeof value === 'function') return undefined;
    if (typeof value === 'bigint') return value.toString();
    if (value && typeof value === 'object' && (value as any).$$typeof === REACT_ELEMENT) {
      return { __ui: (value as any).type?.name || 'component' };
    }
    return value;
  };
  return args.map((a) => {
    // Fast path: primitives are already JSON-safe, so skip the stringify→parse clone. This runs
    // once per streamed token (the hottest event on the wire) — avoiding two JSON passes per token
    // is the cheapest real win here; the final encode() stringifies the whole message exactly once.
    if (a == null) return null;
    const t = typeof a;
    if (t === 'string' || t === 'number' || t === 'boolean') return a;
    if (t === 'bigint') return (a as bigint).toString();
    if (t === 'function') return null;
    // Objects/arrays: clone through JSON to drop functions, mark React elements, ISO-ify Dates.
    try {
      return JSON.parse(JSON.stringify(a, replacer));
    } catch {
      return null;
    }
  });
}

