// Footer state that the Ink UI reads directly from engine singletons (getConfig, getGoalManager)
// rather than from events. An out-of-process front-end can't reach those, so we snapshot them into
// a `ui_snapshot` event the ProtocolHost forwards. Emitted once at startup and again whenever the
// underlying state changes (config / goals / graph), so the Go footer + map panel + token-meter
// stay live without polling.

export interface UiSnapshotModule {
  name: string;
  criticality?: string;
}

export interface UiSnapshotGraph {
  nodeCount: number;
  fileCount: number;
  aiGraphBuilt: boolean;
  modules: UiSnapshotModule[];
  // Which engine is backing the graph tools: 'codebase-memory' (baked-in 158-language engine with
  // local semantic search), 'native' (BiMax's in-memory AST graph), or 'none' (not indexed yet).
  // Lets the Go TUI badge the codebase map / footer so the user knows semantic search is live.
  engine: 'codebase-memory' | 'native' | 'none';
}

// Mind-layer strip for the footer: how many learned weak spots the self-model is routing
// around, how many drives are deviating (fresh measurements only), and compiled habit count.
// The detail arrays make the 🧠 chip EXPLAINABLE (v2 §3.11): the TUI's mind HUD renders the
// top weak spots with their posterior stats, the deviating drives with a measurement
// sparkline, and the compiled habit names — evidence, not an opaque counter.
export interface UiSnapshotMindWeak {
  tool: string;
  domain: string;
  failRate: number; // posterior mean failure rate
  pWeak: number;    // P(θ > weak level) — the decision statistic
  n: number;        // window samples behind it
  advice: string;
}

export interface UiSnapshotMindDrive {
  label: string;
  value: string;    // human-readable last measurement ("3 type errors", "41 TODOs")
  ok: boolean;      // at setpoint?
  // Recent measurement history, oldest → newest (1 = at setpoint, 0 = deviating) — sparkline fuel.
  spark: number[];
}

// The epistemic ledger's verification posture — the correctness half of the mind HUD's "receipts".
export interface UiSnapshotMindLedger {
  resolved: number;      // claims a build/test run confirmed
  open: number;          // edits whose correctness nothing has checked yet
  expired: number;       // claims that timed out unverified (a verification-coverage gap)
  coveragePct: number;   // resolved / (resolved + expired) — % of claims that ever met evidence
  overconfident: number; // domains with a statistically significant overconfidence gap
}

export interface UiSnapshotMind {
  weakSpots: number;
  driveDeviations: number;
  habits: number;
  weak?: UiSnapshotMindWeak[];
  drives?: UiSnapshotMindDrive[];
  habitNames?: string[];
  ledger?: UiSnapshotMindLedger;
}

// --- Protocol v2 additive fields ------------------------------------------------------------
// All optional: a v1 front-end ignores them, a v2 front-end hides the matching panel when absent.

/** One saved session for the front-end's session list (sidebar) — from db/session.meta. */
export interface UiSnapshotSession {
  id: string;
  title: string;
  startedAt: string; // ISO
  messageCount: number;
  cwd: string;
  current: boolean;  // the live session this engine process is writing
}

/** One Time Machine checkpoint (sandbox/checkpoint.manager) for the History strip. */
export interface UiSnapshotCheckpoint {
  id: string;
  label: string;
  ts: number;   // epoch ms
  auto: boolean;
}

export interface UiSnapshotGit {
  branch: string;
  dirty: number; // changed files (index + worktree + untracked)
  ahead: number;
  behind: number;
}

/** Live tool fabric: what the model can call now vs what remains load-on-demand. */
export interface UiSnapshotTools {
  registered: number;
  ready: number;
  deferred: number;
  discovered: number;
  mcp: number;
  graphReady: boolean;
}

/** One live/recent task workspace for the front-end task panel (task.registry.ts). */
export interface UiSnapshotTask {
  id: string;
  kind: string;       // 'shell' | 'browser' | 'subagent' | 'build' | 'test' | 'generic'
  title: string;
  state: string;      // TaskState — the 16-state machine in execution.ledger.ts
  elapsedMs: number;
  attention: boolean;
  pinned: boolean;
  lastEvent?: string;
  progress?: number;  // 0..1 where measurable
  canPause: boolean;  // honest capability flags — the TUI only offers what's real
  canResume: boolean;
  canCancel: boolean;
}

/**
 * The Composer's corpus, mirrored so a front-end can show what it is actually working from.
 *
 * `skipped` is the field that earns its place: a user who drops 200 inspection reports and is told
 * only "191 ingested" will proceed as though all 200 were read, and the nine unreadable scans are
 * precisely the ones that change an assessment. Silence about a failed attachment is the worst
 * available outcome, so the reasons ride all the way to the UI.
 */
export interface UiSnapshotComposer {
  /** Documents dropped for the task at hand. */
  session: number;
  /** Documents promoted into the standing knowledge library. */
  library: number;
  /** Indexed passages across both corpora. */
  passages: number;
  /** Measured values extracted from tables, queryable numerically. */
  facts: number;
  /** Outcome of the most recent ingest, including what could not be read and why. */
  lastIngest?: {
    ingested: number;
    chunks: number;
    skipped: { name: string; reason: string }[];
  };
}

/**
 * What the engine will do before it changes something, read from the live gates:
 *   askBeforeEdits — every file edit shows its diff and waits (diffApproval.ts);
 *   readOnly       — plan mode: nothing is written at all;
 *   unattended     — the governor is bypassed or unattended: nothing asks.
 */
export interface UiSnapshotApprovals {
  askBeforeEdits: boolean;
  readOnly: boolean;
  unattended: boolean;
}

export interface UiSnapshot {
  models: { coding: string; lite: string; vision?: string };
  goalCount: number;
  mind: UiSnapshotMind;
  // The codebase-map graph overview, mirrored so the Go front-end can render CodebaseMapPanel and
  // size its token-meter context window — neither of which it can compute from the engine singletons.
  graph: UiSnapshotGraph;
  // Effective context window (tokens) for the active model, so the Go token meter shows a real
  // "how full" fraction instead of a bare count. Resolved from config / model capabilities here.
  contextWindow: number;
  // The fixed cost every request pays — system prompt + tool-schema JSON — so the Go token meter
  // reflects real usage (thousands of tokens) instead of just the streamed reply (~tens). The
  // front-end adds the live conversation tokens on top. Mirrors Ink's systemPromptTokens.
  tokensBaseline: number;
  // Cumulative tokens saved this session by Headroom-style backlog compression — shown next to the
  // token meter so the user sees the compression paying off.
  compressionSaved: number;
  // Multi-repo workspace: how many repos are in context and their names, so the TUI status bar
  // always shows the working set (workspace.manager.ts). count <= 1 = single-repo session.
  workspace: { count: number; names: string[]; writable: number };
  // v2: recent sessions (newest first, capped) for the front-end sidebar; resume via `/resume <id>`.
  sessions?: UiSnapshotSession[];
  // v2: Time Machine checkpoints (newest first, capped) for the History strip; restore via `/rewind <id>`.
  checkpoints?: UiSnapshotCheckpoint[];
  // v2: coarse git state for header pills. Front-ends that can poll git natively (the Electron app)
  // may prefer their own fresher poll; this is for the ones that can't.
  git?: UiSnapshotGit;
  // v3 additive: live registry posture for desktop/tooling surfaces.
  tools?: UiSnapshotTools;
  // v3 additive: task workspaces (live + recent terminal tasks awaiting close) for the task panel.
  tasks?: UiSnapshotTask[];
  // v3 additive: the Composer's document corpus and extracted facts.
  composer?: UiSnapshotComposer;
  // v3 additive: the approval gates as they stand in THIS engine, so the composer's permission pill
  // states what will actually happen rather than what it last sent (fix list item 12).
  approvals?: UiSnapshotApprovals;
  // NOTE: the Grok-port power/update footer chips were removed — no front-end ever consumed them
  // (silent TS→Go drift). Power posture is read via /power and update posture via /update.
}

/** Lazily-computed baseline (system prompt + tool schemas). Set by headless.entry, which has the
 *  personas + tool registry; ui.snapshot only sees the graph store. */
let baselineFn: (() => number) | undefined;
export function setTokensBaseline(fn: () => number): void { baselineFn = fn; }

/** The live approval gates. Set by headless.entry, which holds the governor; ui.snapshot does not. */
let approvalsFn: (() => UiSnapshotApprovals) | undefined;
export function setApprovalsReader(fn: () => UiSnapshotApprovals): void { approvalsFn = fn; }

export function buildUiSnapshot(graphStore?: IGraphStore, toolRegistry?: ToolRegistry): UiSnapshot {
  let models: { coding: string; lite: string; vision?: string } = { coding: '', lite: '' };
  let goalCount = 0;
  let contextWindow = 0;
  let contextMode: ContextMode = 'smart';
  try {
    const { getConfig } = require('../engine/config');
    const c = getConfig();
    models = { coding: c.model, lite: c.liteModel, vision: c.visionModel || undefined };
    contextWindow = c.contextWindowTokens || 0;
    contextMode = c.contextMode === 'full' ? 'full' : 'smart';
  } catch { /* config not ready */ }
  if (!contextWindow || contextWindow <= 0) {
    try {
      const { capabilitiesFor } = require('../core/capabilities');
      contextWindow = capabilitiesFor(undefined, models.coding || models.lite).contextWindow || 0;
    } catch { /* capabilities optional */ }
  }
  try {
    const { getGoalManager } = require('../memory/goal.manager');
    goalCount = getGoalManager().getActiveGoals().length;
  } catch { /* goal manager not initialized */ }

  const codememReady = (() => { try { return isCodememReady(); } catch { return false; } })();
  let graph: UiSnapshotGraph = { nodeCount: 0, fileCount: 0, aiGraphBuilt: false, modules: [], engine: codememReady ? 'codebase-memory' : 'none' };
  try {
    // Only surface the map in a real project root — never in a scratch dir like ~ or the Desktop,
    // where a stale/global graph would otherwise show hundreds of thousands of junk nodes.
    if (graphStore && isCodebase(process.cwd())) {
      const s = summarizeGraph(graphStore);
      graph = {
        nodeCount: s.nodeCount,
        fileCount: s.fileCount,
        aiGraphBuilt: s.aiGraphBuilt,
        modules: s.topModules.slice(0, 5).map((m) => ({ name: m.name, criticality: m.criticality })),
        // codebase-memory wins the badge when live; else native if the in-memory graph has nodes.
        engine: codememReady ? 'codebase-memory' : (s.nodeCount > 0 ? 'native' : 'none'),
      };
    }
  } catch { /* graph summary best-effort */ }

  let tokensBaseline = 0;
  try { tokensBaseline = baselineFn ? baselineFn() : 0; } catch { /* best-effort */ }

  let compressionSaved = 0;
  try { compressionSaved = getHeadroomSavedTokens(); } catch { /* best-effort */ }

  let mind: UiSnapshotMind = { weakSpots: 0, driveDeviations: 0, habits: 0 };
  try {
    const { getSelfModel } = require('../mind/self.model');
    const { getDrivesEngine } = require('../mind/drives.engine');
    const { getHabitMiner } = require('../mind/habit.compiler');
    const { getEpistemicLedger } = require('../mind/epistemic.ledger');
    const weakAll = getSelfModel().weakSpots();
    const drivesEngine = getDrivesEngine();
    const deviations = drivesEngine.deviations();
    const compiled = getHabitMiner().habits().filter((h: any) => h.compiled);
    // Drive detail: deviating drives first, then healthy measured ones, capped at 5 —
    // enough for the HUD without bloating every snapshot frame.
    const measured = (drivesEngine.list() as any[])
      .filter((d: any) => d.lastOk !== undefined)
      .sort((a: any, b: any) => Number(a.lastOk) - Number(b.lastOk))
      .slice(0, 5);
    mind = {
      weakSpots: weakAll.length,
      driveDeviations: deviations.length,
      habits: compiled.length,
      weak: weakAll.slice(0, 4).map((w: any) => ({
        tool: w.tool, domain: w.domain, failRate: w.failRate, pWeak: w.pWeak, n: w.n, advice: w.advice,
      })),
      drives: measured.map((d: any) => ({
        label: d.label,
        value: d.lastValue || '',
        ok: !!d.lastOk,
        spark: (d.history || []).slice(-16).map((h: any) => (h.ok ? 1 : 0)),
      })),
      habitNames: compiled.slice(0, 5).map((h: any) => h.slug || h.key),
      ledger: (() => {
        const st = getEpistemicLedger().stats();
        const met = st.resolved + st.expired;
        return {
          resolved: st.resolved, open: st.open, expired: st.expired,
          coveragePct: met > 0 ? Math.round((st.resolved / met) * 100) : 0,
          overconfident: (getEpistemicLedger().overconfidentDomains() || []).length,
        };
      })(),
    };
  } catch { /* mind layer best-effort */ }

  let workspace = { count: 0, names: [] as string[], writable: 0 };
  try {
    const { tryGetWorkspace } = require('../core/workspace.manager');
    const ws = tryGetWorkspace();
    if (ws) workspace = ws.snapshot();
  } catch { /* workspace best-effort */ }

  // v2 fields — each independently best-effort so one broken subsystem never blanks the others.
  let sessions: UiSnapshotSession[] | undefined;
  try {
    const { listSessionMeta, getCurrentSessionId } = require('../db/session.meta');
    const current = getCurrentSessionId();
    const { headlineFromPrompt } = require('../engine/session.summary');
    sessions = (listSessionMeta(20) as any[]).map((m) => ({
      id: m.id,
      // What the session is for (fix list item 7): the Quick model's title once the first reply has
      // named it, and until then — or for sessions recorded before titles existed — the first request
      // with its greeting and filler removed. Never the raw first prompt.
      title: m.summary || (m.title && m.title !== '(no messages yet)' ? headlineFromPrompt(m.title) : '(no messages yet)'),
      startedAt: m.startedAt || '',
      messageCount: m.messageCount || 0,
      cwd: m.cwd || '',
      current: m.id === current,
    }));
  } catch { /* session meta best-effort */ }

  let checkpoints: UiSnapshotCheckpoint[] | undefined;
  try {
    const { globalCheckpointManager } = require('../sandbox/checkpoint.manager');
    if (globalCheckpointManager.isGitRepo()) {
      checkpoints = (globalCheckpointManager.list() as any[]).slice(0, 15).map((c) => ({
        id: c.id, label: c.label, ts: c.timestamp, auto: !!c.auto,
      }));
    }
  } catch { /* checkpoints best-effort */ }

  let git: UiSnapshotGit | undefined;
  try {
    const { getGitStatus } = require('../engine/git');
    const s = getGitStatus(process.cwd());
    if (s) {
      git = {
        branch: s.branch,
        dirty: s.added.length + s.modified.length + s.deleted.length + s.unstaged.length,
        ahead: s.ahead,
        behind: s.behind,
      };
    }
  } catch { /* git best-effort */ }

  let composer: UiSnapshotComposer | undefined;
  try {
    const { getComposerCorpus } = require('../memory/corpus') as typeof import('../memory/corpus');
    const { getFactStore } = require('../memory/facts') as typeof import('../memory/facts');
    const corpus = getComposerCorpus();
    if (corpus) {
      // Synchronous by design: the snapshot is built on a debounce and must not await disk. The
      // manifest is already resident once anything has been ingested; before that the counts are
      // zero, which is the truth.
      const snap = corpus.snapshot();
      composer = {
        session: snap.session,
        library: snap.library,
        passages: snap.chunks,
        facts: getFactStore()?.count() ?? 0,
        lastIngest: snap.lastIngest ?? undefined,
      };
    }
  } catch { /* composer best-effort — a front-end without it simply shows no corpus chip */ }

  let tools: UiSnapshotTools | undefined;
  try {
    if (toolRegistry) {
      const names = toolRegistry.getToolNames();
      tools = {
        registered: names.length,
        ready: names.filter((name) => toolRegistry.isSent(name, contextMode)).length,
        deferred: names.filter((name) => toolRegistry.isDeferred(name) && !toolRegistry.isDiscovered(name)).length,
        discovered: names.filter((name) => toolRegistry.isDiscovered(name)).length,
        mcp: names.filter((name) => name.startsWith('mcp__')).length,
        graphReady: toolRegistry.isGraphReady(),
      };
    }
  } catch { /* registry posture best-effort */ }

  let tasks: UiSnapshotTask[] | undefined;
  try {
    const { getTaskRegistry } = require('../core/task.registry');
    const list = getTaskRegistry().list() as any[];
    if (list.length) {
      tasks = list.slice(0, 12).map((t) => ({
        id: t.id, kind: t.kind, title: t.title, state: t.state,
        elapsedMs: (t.endedAt || Date.now()) - (t.startedAt || t.createdAt),
        attention: !!t.attention, pinned: !!t.pinned,
        lastEvent: t.lastEvent, progress: t.progress,
        canPause: !!t.supports?.pause, canResume: !!t.supports?.resume, canCancel: !!t.supports?.cancel,
      }));
    }
  } catch { /* task registry best-effort */ }

  let approvals: UiSnapshotApprovals | undefined;
  try { approvals = approvalsFn?.(); } catch { approvals = undefined; }

  return { models, goalCount, mind, graph, contextWindow, tokensBaseline, compressionSaved, workspace, sessions, checkpoints, git, tools, tasks, composer, approvals };
}

/** Begin emitting `ui_snapshot` (immediately + on config/goal/graph changes). Call after the host attaches. */
export function startUiSnapshot(graphStore?: IGraphStore, toolRegistry?: ToolRegistry): void {
  // First snapshot is synchronous (the front-end needs footer state with the `ready` handshake);
  // afterwards a trailing 80ms debounce coalesces change bursts — a /beast step can fire
  // config+goals+graph+mind together, and each snapshot walks the whole graph summary.
  engineEvents.emit('ui_snapshot', buildUiSnapshot(graphStore, toolRegistry));
  let timer: ReturnType<typeof setTimeout> | null = null;
  const emit = () => {
    if (timer) return;
    timer = setTimeout(() => {
      timer = null;
      engineEvents.emit('ui_snapshot', buildUiSnapshot(graphStore, toolRegistry));
    }, 80);
    timer.unref?.();
  };
  engineEvents.on('config_changed', emit);
  engineEvents.on('goals_changed', emit);
  engineEvents.on('graph_changed', emit);
  // Context-token refresh (compression/compaction changed the estimate). Deliberately its own
  // event: it refreshes the footer meter WITHOUT the TUI printing "code graph updated".
  engineEvents.on('context_changed', emit);
  engineEvents.on('mcp_changed', emit);
  engineEvents.on('tools_changed', emit);
  // Mind layer: re-snapshot when self-model / drives / habits change so the footer's 🧠 strip
  // stays live.
  engineEvents.on('mind_changed', emit);
  // Workspace: repo registered / scoped / ignored → status-bar repo chip updates.
  engineEvents.on('workspace_changed', emit);
  // v2: checkpoint created / rewound → History strip updates; clear/resume → session list updates.
  engineEvents.on('timemachine_changed', emit);
  engineEvents.on('clear', emit);
  // Session recorder: thread created / titled / rotated / resumed → sidebar session list updates.
  engineEvents.on('session_changed', emit);
  // Task workspaces: create / transition / output activity → task panel updates.
  engineEvents.on('tasks_changed', emit);
  // Composer: a drop finished ingesting → the corpus chip updates without waiting for a config or
  // graph event that may never come during a document-only session.
  engineEvents.on('composer_changed', emit);
}

import { Outbound } from './protocol';

/**
 * Bounded, strictly ordered outbound queue for the engine's protocol channel. It was written for an NDJSON pipe; since
 * record 64 the channel is a MessagePort, whose acknowledged window (port.host.ts) plays the part of `write()`
 * returning false. The reasoning below is unchanged by that.
 *
 * The sink used to be `out.write(encode(msg))` with the return value discarded. `write()` returning
 * false is Node telling you the kernel buffer is full and it is now buffering in the process's own
 * heap; ignoring it means a front-end that stops reading turns engine output into unbounded memory
 * growth, and nothing upstream ever learns that the consumer is gone.
 *
 * ## Ordering is not negotiable, so priority is not the mechanism
 *
 * Everything here shares one pipe. Bytes already handed to `write()` are ahead of anything enqueued
 * afterwards, and no amount of prioritisation can pull a later message in front of them — a
 * "high-priority" lane on a single stream is a comforting lie. An approval request cannot overtake a
 * megabyte of streamed tokens that is already queued.
 *
 * So delivery of critical messages is guaranteed by **reserving capacity before saturation**, not by
 * reordering after it:
 *
 *   0 ────────────── bulkHighWater ──────────── maxQueuedBytes
 *   │  bulk + critical admitted   │  critical only (the reserve)  │
 *
 * Bulk output stops being admitted at the high-water mark, well below the ceiling, which keeps the
 * gap between the two marks free for lifecycle and approval traffic. Hysteresis (`bulkLowWater`)
 * stops the producer flapping. If the reserve itself fills, the consumer is not draining at all:
 * the queue reports overflow once, refuses everything after it, and the caller is expected to stop
 * producing and surface a disconnected consumer rather than pretend the message got through.
 *
 * ## What may and may not be lost
 *
 * A refused bulk message is **counted and reported**, never silently discarded — the caller emits a
 * visible notice, so a truncated transcript is visibly truncated. A critical message is never
 * refused while the queue is below its ceiling, and never dropped by this queue at all.
 *
 * Nothing here inspects message content, so no prompt, source or credential text is retained: the
 * queue holds already-encoded lines and their byte lengths.
 */

export type MessageClass = 'critical' | 'bulk';

/**
 * Which messages must get through.
 *
 * Critical: the handshake, correlated answers a front-end is blocking on, approval requests, and
 * the liveness pong. Losing any of these strands a front-end waiting for a reply that will never
 * come. Everything else — the forwarded display events, which is where stream tokens live — is
 * bulk: it is what floods, and it is what a paused consumer can be told it missed.
 */
export function outboundClass(msg: Outbound): MessageClass {
  switch (msg.t) {
    case 'event':
      return msg.name === 'message' && (msg.args?.[0] as any)?.payload?.capabilityStatus ? 'critical' : 'bulk';
    default:
      return 'critical';
  }
}

export interface WireQueueOptions {
  /** The underlying sink. Returns false when the consumer is not keeping up (Node's contract). */
  write: (chunk: string) => boolean;
  /** Subscribe to the sink's drain signal. Returns an unsubscribe function. */
  onDrain: (listener: () => void) => () => void;
  /** Hard ceiling on queued bytes. Past this the consumer is treated as gone. */
  maxQueuedBytes?: number;
  /** Bulk admission stops at or above this. Must be below `maxQueuedBytes`. */
  bulkHighWaterBytes?: number;
  /** Bulk admission resumes at or below this. Must be below the high-water mark. */
  bulkLowWaterBytes?: number;
  /** Bulk was refused; the caller should stop producing and say so visibly. */
  onBulkPaused?: (info: { queuedBytes: number }) => void;
  /** Bulk is welcome again; `refused` counts what was turned away during the pause. */
  onBulkResumed?: (info: { queuedBytes: number; refused: number; refusedBytes: number }) => void;
  /** The reserve filled: critical delivery can no longer be guaranteed. Fires at most once. */
  onOverflow?: (info: { queuedBytes: number; maxQueuedBytes: number }) => void;
}

export interface WireQueueStats {
  queuedBytes: number;
  queuedMessages: number;
  /** Peak `queuedBytes` seen, for a budget to be checked against. */
  peakQueuedBytes: number;
  enqueuedCritical: number;
  enqueuedBulk: number;
  refusedBulk: number;
  refusedBulkBytes: number;
  refusedCritical: number;
  /** Times the sink asked us to stop writing. */
  backpressureEvents: number;
  bulkPaused: boolean;
  overflowed: boolean;
  /** Bulk messages discarded by an explicit `dropPendingBulk` call, e.g. on interrupt. */
  droppedBulkOnCancel: number;
  writtenMessages: number;
  writtenBytes: number;
}

export type AdmissionResult =
  | { admitted: true }
  | { admitted: false; reason: 'bulk-paused' | 'overflow' | 'disposed' };

const DEFAULT_MAX_QUEUED_BYTES = 8 * 1024 * 1024;
const DEFAULT_BULK_HIGH_WATER = 4 * 1024 * 1024;
const DEFAULT_BULK_LOW_WATER = 1 * 1024 * 1024;

interface QueuedLine {
  chunk: string;
  bytes: number;
  cls: MessageClass;
}

export class WireQueue {
  private readonly opts: Required<Pick<WireQueueOptions, 'write' | 'onDrain'>> & WireQueueOptions;
  private readonly maxQueuedBytes: number;
  private readonly bulkHighWaterBytes: number;
  private readonly bulkLowWaterBytes: number;

  private queue: QueuedLine[] = [];
  private queuedBytes = 0;
  private flushing = false;
  private waitingForDrain = false;
  private offDrain: (() => void) | null = null;
  private disposed = false;
  /** A sink that threw (EPIPE) is terminal: there is no drain event coming for a dead pipe. */
  private sinkFailed = false;

  private stats: WireQueueStats = {
    queuedBytes: 0, queuedMessages: 0, peakQueuedBytes: 0,
    enqueuedCritical: 0, enqueuedBulk: 0,
    refusedBulk: 0, refusedBulkBytes: 0, refusedCritical: 0,
    backpressureEvents: 0, bulkPaused: false, overflowed: false,
    droppedBulkOnCancel: 0, writtenMessages: 0, writtenBytes: 0,
  };

  constructor(options: WireQueueOptions) {
    this.opts = options as Required<Pick<WireQueueOptions, 'write' | 'onDrain'>> & WireQueueOptions;
    this.maxQueuedBytes = options.maxQueuedBytes ?? DEFAULT_MAX_QUEUED_BYTES;
    this.bulkHighWaterBytes = options.bulkHighWaterBytes ?? Math.min(DEFAULT_BULK_HIGH_WATER, Math.floor(this.maxQueuedBytes / 2));
    this.bulkLowWaterBytes = options.bulkLowWaterBytes ?? Math.min(DEFAULT_BULK_LOW_WATER, Math.floor(this.bulkHighWaterBytes / 2));
    if (!(this.bulkLowWaterBytes <= this.bulkHighWaterBytes && this.bulkHighWaterBytes < this.maxQueuedBytes)) {
      throw new Error(
        `[WireQueue] watermarks must satisfy low <= high < max; got ${this.bulkLowWaterBytes}, ` +
        `${this.bulkHighWaterBytes}, ${this.maxQueuedBytes}`
      );
    }
  }

  /**
   * Offer one already-encoded line. FIFO: an admitted message goes behind everything already
   * queued, whatever its class. Class decides ADMISSION, never position.
   */
  enqueue(chunk: string, cls: MessageClass): AdmissionResult {
    if (this.disposed) return { admitted: false, reason: 'disposed' };
    const bytes = Buffer.byteLength(chunk, 'utf8');

    if (cls === 'bulk') {
      if (this.stats.overflowed) { this.refuseBulk(bytes); return { admitted: false, reason: 'overflow' }; }
      if (this.stats.bulkPaused || this.queuedBytes + bytes > this.bulkHighWaterBytes) {
        if (!this.stats.bulkPaused) {
          this.stats.bulkPaused = true;
          this.opts.onBulkPaused?.({ queuedBytes: this.queuedBytes });
        }
        this.refuseBulk(bytes);
        return { admitted: false, reason: 'bulk-paused' };
      }
      this.stats.enqueuedBulk++;
    } else {
      if (this.stats.overflowed) { this.stats.refusedCritical++; return { admitted: false, reason: 'overflow' }; }
      if (this.queuedBytes + bytes > this.maxQueuedBytes) {
        // The reserve is exhausted: the consumer is not reading at all. Say so once, refuse
        // everything after it, and let the caller tear the connection down visibly. Continuing to
        // queue would trade a visible failure for unbounded memory growth.
        this.stats.overflowed = true;
        this.stats.refusedCritical++;
        this.opts.onOverflow?.({ queuedBytes: this.queuedBytes, maxQueuedBytes: this.maxQueuedBytes });
        return { admitted: false, reason: 'overflow' };
      }
      this.stats.enqueuedCritical++;
    }

    this.queue.push({ chunk, bytes, cls });
    this.queuedBytes += bytes;
    if (this.queuedBytes > this.stats.peakQueuedBytes) this.stats.peakQueuedBytes = this.queuedBytes;
    this.syncCounters();
    this.flush();
    return { admitted: true };
  }

  private refuseBulk(bytes: number): void {
    this.stats.refusedBulk++;
    this.stats.refusedBulkBytes += bytes;
  }

  /**
   * Write until the sink pushes back or the queue empties. Re-entrancy is guarded because a sink
   * can call back synchronously.
   */
  private flush(): void {
    if (this.flushing || this.waitingForDrain || this.disposed) return;
    this.flushing = true;
    try {
      while (this.queue.length > 0) {
        const line = this.queue[0];
        let accepted: boolean;
        try {
          accepted = this.opts.write(line.chunk);
        } catch {
          // A dead pipe (EPIPE) throws, and a dead pipe never drains. Stop writing and leave the
          // line queued: continued production then fills the queue and reports overflow, which is
          // how the caller learns the consumer is gone. Pretending the write succeeded would lose
          // the message silently.
          this.sinkFailed = true;
          this.waitingForDrain = true;
          break;
        }
        // The line was handed over either way: `false` means "buffered, stop sending more", not
        // "rejected". Removing it is correct; what changes is that we stop the loop.
        this.queue.shift();
        this.queuedBytes -= line.bytes;
        this.stats.writtenMessages++;
        this.stats.writtenBytes += line.bytes;
        if (!accepted) {
          this.stats.backpressureEvents++;
          this.waitingForDrain = true;
          this.offDrain?.();
          this.offDrain = this.opts.onDrain(() => {
            this.offDrain?.();
            this.offDrain = null;
            this.waitingForDrain = false;
            this.flush();
          });
          break;
        }
      }
      this.syncCounters();
      this.maybeResumeBulk();
    } finally {
      this.flushing = false;
    }
  }

  private maybeResumeBulk(): void {
    if (!this.stats.bulkPaused || this.stats.overflowed) return;
    if (this.queuedBytes > this.bulkLowWaterBytes) return;
    const refused = this.stats.refusedBulk;
    const refusedBytes = this.stats.refusedBulkBytes;
    this.stats.bulkPaused = false;
    this.opts.onBulkResumed?.({ queuedBytes: this.queuedBytes, refused, refusedBytes });
  }

  /**
   * Discard queued bulk. Used when a turn is cancelled: its remaining display output describes work
   * the user stopped. Critical messages are never touched, and the count is reported so the drop is
   * visible rather than silent.
   */
  dropPendingBulk(): number {
    const before = this.queue.length;
    const kept: QueuedLine[] = [];
    let bytes = 0;
    for (const line of this.queue) {
      if (line.cls === 'bulk') continue;
      kept.push(line);
      bytes += line.bytes;
    }
    const dropped = before - kept.length;
    this.queue = kept;
    this.queuedBytes = bytes;
    this.stats.droppedBulkOnCancel += dropped;
    this.syncCounters();
    this.maybeResumeBulk();
    return dropped;
  }

  private syncCounters(): void {
    this.stats.queuedBytes = this.queuedBytes;
    this.stats.queuedMessages = this.queue.length;
  }

  /**
   * True when enough is queued that a message enqueued now would sit behind a meaningful backlog.
   * Callers use it to decide whether cancelling needs to discard queued bulk to stay responsive.
   */
  congested(): boolean { return this.queuedBytes > this.bulkLowWaterBytes; }

  /** True once the sink threw. No drain is coming; the queue only reports from here. */
  isSinkFailed(): boolean { return this.sinkFailed; }

  snapshot(): WireQueueStats { return { ...this.stats }; }

  /** Lines still queued when the transport was disposed, so a caller can report what never went. */
  dispose(): { unsentMessages: number; unsentBytes: number } {
    this.disposed = true;
    this.offDrain?.();
    this.offDrain = null;
    const unsent = { unsentMessages: this.queue.length, unsentBytes: this.queuedBytes };
    this.queue = [];
    this.queuedBytes = 0;
    this.syncCounters();
    return unsent;
  }
}

import * as fs from 'fs';
import * as path from 'path';
import * as yaml from 'js-yaml';

export interface RecipeDefinition {
  name: string;
  description?: string;
  instructions: string;
  extensions?: string[];         // MCP server names to enable for this recipe
  sub_recipes?: string[];        // other recipe names to run before this one
  success_checks?: string[];     // shell commands that must exit 0 after completion
  retry?: number;                // max retries on failure (default 0)
  filePath: string;              // set by loader, not from YAML
}

const RECIPE_DIR = '.bimax/recipes';

export class RecipeLoader {
  constructor(private projectRoot: string) {}

  get recipesDir(): string {
    return path.join(this.projectRoot, RECIPE_DIR);
  }

  list(): RecipeDefinition[] {
    const dir = this.recipesDir;
    if (!fs.existsSync(dir)) return [];
    try {
      return fs.readdirSync(dir)
        .filter(f => f.endsWith('.yaml') || f.endsWith('.yml'))
        .map(f => this.load(path.join(dir, f)))
        .filter((r): r is RecipeDefinition => r !== null);
    } catch {
      return [];
    }
  }

  load(filePath: string): RecipeDefinition | null {
    try {
      const raw = fs.readFileSync(filePath, 'utf8');
      const parsed = yaml.load(raw) as any;
      if (!parsed || typeof parsed !== 'object') return null;
      return {
        name: parsed.name ?? path.basename(filePath, path.extname(filePath)),
        description: parsed.description,
        instructions: parsed.instructions ?? '',
        extensions: Array.isArray(parsed.extensions) ? parsed.extensions : [],
        sub_recipes: Array.isArray(parsed.sub_recipes) ? parsed.sub_recipes : [],
        success_checks: Array.isArray(parsed.success_checks) ? parsed.success_checks : [],
        retry: typeof parsed.retry === 'number' ? parsed.retry : 0,
        filePath,
      };
    } catch {
      return null;
    }
  }

  getByName(name: string): RecipeDefinition | null {
    const all = this.list();
    return all.find(r => r.name === name) ?? null;
  }

  ensureDir(): void {
    fs.mkdirSync(this.recipesDir, { recursive: true });
  }

  scaffoldExample(name: string): string {
    this.ensureDir();
    const slug = name.toLowerCase().replace(/\s+/g, '-');
    const filePath = path.join(this.recipesDir, `${slug}.yaml`);
    const template = [
      `name: ${slug}`,
      `description: ${name}`,
      `instructions: |`,
      `  Describe what the agent should do for this recipe.`,
      `  Be specific about inputs, outputs, and acceptance criteria.`,
      `# extensions:`,
      `#   - my-mcp-server`,
      `# sub_recipes:`,
      `#   - another-recipe`,
      `# success_checks:`,
      `#   - npm test`,
      `# retry: 1`,
    ].join('\n');
    fs.writeFileSync(filePath, template, 'utf8');
    return filePath;
  }
}

let _loader: RecipeLoader | null = null;
export function getGlobalRecipeLoader(): RecipeLoader | null { return _loader; }
export function setGlobalRecipeLoader(l: RecipeLoader): void { _loader = l; }

import * as fs from 'fs';
import * as path from 'path';
import { engineEvents, ToolCallEntry } from '../engine/events';
import { sessionDir } from '../engine/session';
import { getSessionRecorder } from '../engine/session.recorder';
import {
  ReviewFacts, ReviewApprovalKind, emptyFacts, toSnapshot, readsAsApproved, pendingApprovals,
} from './review.model';
import { CLAIMING_TOOLS } from '../core/agent.loop';
import { isRepoWideEvidenceCommand } from '../mind/epistemic.ledger';

/**
 * The review recorder — the single producer of per-thread review state, shaped exactly like the
 * SessionRecorder it rides alongside: it listens on engineEvents at the engine's points of truth,
 * folds them into a ReviewFacts file at `<project>/.breakglass/sessions/<id>.review.json`, and
 * publishes the derived snapshot over the wire as a debounced `review_update` event (a full
 * snapshot, so a front-end that reconnects after missing events is correct on the next emit).
 *
 * Sources (all already flowing, or emitted one line from where truth is computed):
 *   request_pending / request_resolved  ← ProtocolHost — every approval round-trip, with real ids;
 *                                         late/duplicate replies never produce a second resolution
 *                                         because the host drops them before we ever hear of them.
 *   review_change                       ← agent.loop, beside the epistemic claim (attributed file).
 *   review_evidence                     ← agent.loop, beside ledger settlement (real exit codes).
 *   timemachine_changed / checkpoint_failed ← the Time Machine commands.
 *   todo_update                         ← the live plan.
 *   tool_call / tool_call_result        ← transient "applying" liveness (never persisted).
 *   session_changed                     ← thread lifecycle: rotate closes the facts file (pending
 *                                         approvals marked interrupted), resume loads the thread's
 *                                         own facts — approvals that were pending when a previous
 *                                         process died load as interrupted, never falsely pending.
 */

const APPROVAL_CAP = 50;
const VERIFICATION_CAP = 50;
const CHECKPOINT_CAP = 20;

function reviewPath(id: string): string {
  return path.join(sessionDir(), `${id}.review.json`);
}

export class ReviewManager {
  private facts: ReviewFacts = emptyFacts('');
  // Wire request-id → approval index guard: ids restart at 1 in every process, so only ids issued
  // by THIS process may resolve entries recorded by this process.
  private liveRequestIds = new Set<number>();
  private runningMutations = new Set<string>(); // tool_call ids of in-flight mutating tools
  private emitTimer: ReturnType<typeof setTimeout> | null = null;
  private saveTimer: ReturnType<typeof setTimeout> | null = null;

  // --- thread lifecycle -------------------------------------------------------------------

  /** Reconcile with the SessionRecorder's current thread (driven by 'session_changed'). */
  syncSession(): void {
    const id = getSessionRecorder()?.currentId() ?? '';
    if (id === this.facts.sessionId) return;
    if (this.facts.sessionId) this.close(); // rotate/switch away: seal the old thread's facts
    if (id) {
      const loaded = this.loadFacts(id);
      if (loaded) {
        this.facts = loaded;
        this.markDanglingInterrupted('restored'); // a previous process may have died mid-approval
      } else {
        // Fresh thread adopts anything recorded before the session id existed (rare boot facts).
        this.facts.sessionId = id;
      }
    } else {
      this.facts = emptyFacts('');
    }
    this.touch();
  }

  /** Seal the current thread: pending approvals can never be answered once we leave it. */
  private close(): void {
    this.markDanglingInterrupted('rotated');
    this.saveNow();
    this.facts = emptyFacts('');
  }

  private markDanglingInterrupted(_why: 'restored' | 'rotated'): void {
    const pending = pendingApprovals(this.facts);
    if (pending.length === 0) return;
    const at = Date.now();
    for (const a of pending) a.resolution = { value: '', approved: false, at, interrupted: true };
    this.facts.interrupted = true;
  }

  // --- fact intake ------------------------------------------------------------------------

  onRequestPending(req: { id: number; kind: string; question: string; isAsk?: boolean }): void {
    if (!req || req.kind === 'input') return; // free-form input prompts (API keys…) are not review
    const kind: ReviewApprovalKind = req.kind === 'diff' ? 'diff' : req.isAsk ? 'question' : 'permission';
    this.liveRequestIds.add(req.id);
    this.facts.approvals.push({ id: req.id, kind, question: String(req.question || ''), requestedAt: Date.now() });
    if (this.facts.approvals.length > APPROVAL_CAP) this.facts.approvals.splice(0, this.facts.approvals.length - APPROVAL_CAP);
    this.touch();
  }

  onRequestResolved(res: { id: number; value: string; interrupted?: boolean }): void {
    if (!res || !this.liveRequestIds.has(res.id)) return; // late/foreign id — never resurrect
    this.liveRequestIds.delete(res.id);
    const a = [...this.facts.approvals].reverse().find(x => x.id === res.id && !x.resolution);
    if (!a) return;
    a.resolution = {
      value: String(res.value ?? ''),
      approved: !res.interrupted && readsAsApproved(a.kind, String(res.value ?? '')),
      at: Date.now(),
      ...(res.interrupted ? { interrupted: true } : {}),
    };
    this.touch();
  }

  onChange(c: { tool: string; file?: string; callId?: string }): void {
    if (!c || !c.tool) return;
    const file = c.file || '(unattributed)';
    const now = Date.now();
    const existing = this.facts.changes.find(x => x.file === file);
    if (existing) {
      existing.edits++;
      existing.lastAt = now;
      existing.lastCallId = c.callId ?? existing.lastCallId;
      if (!existing.tools.includes(c.tool)) existing.tools.push(c.tool);
    } else {
      this.facts.changes.push({ file, tools: [c.tool], edits: 1, lastCallId: c.callId, lastAt: now });
    }
    this.touch();
  }

  onEvidence(e: { command: string; ok: boolean; settled: number; coveredFiles?: string[]; repoWide?: boolean }): void {
    if (!e || !e.command) return;
    this.facts.verifications.push({
      command: String(e.command).slice(0, 200), ok: !!e.ok, settled: Number(e.settled) || 0, at: Date.now(),
      coveredFiles: Array.isArray(e.coveredFiles) ? [...new Set(e.coveredFiles.map(String))] : [],
      repoWide: e.repoWide === true || (e.repoWide === undefined && !!e.ok && isRepoWideEvidenceCommand(e.command)),
    });
    if (this.facts.verifications.length > VERIFICATION_CAP) {
      this.facts.verifications.splice(0, this.facts.verifications.length - VERIFICATION_CAP);
    }
    this.touch();
  }

  onCheckpointChanged(): void {
    try {
      const { globalCheckpointManager } = require('../sandbox/checkpoint.manager');
      const latest = globalCheckpointManager.list()[0];
      if (!latest) return;
      if (this.facts.checkpoints.some(c => c.id === latest.id)) return;
      this.facts.checkpoints.push({ id: latest.id, label: latest.label, ts: latest.timestamp, auto: !!latest.auto, ok: true });
      if (this.facts.checkpoints.length > CHECKPOINT_CAP) {
        this.facts.checkpoints.splice(0, this.facts.checkpoints.length - CHECKPOINT_CAP);
      }
      this.touch();
    } catch { /* checkpoint manager optional (non-git projects) */ }
  }

  onCheckpointFailed(label: string): void {
    this.facts.checkpoints.push({ id: '', label: String(label || 'checkpoint'), ts: Date.now(), auto: false, ok: false });
    if (this.facts.checkpoints.length > CHECKPOINT_CAP) {
      this.facts.checkpoints.splice(0, this.facts.checkpoints.length - CHECKPOINT_CAP);
    }
    this.touch();
  }

  onTodos(todos: unknown): void {
    this.facts.todos = Array.isArray(todos)
      ? todos.map((t: any) => ({ content: String(t?.content ?? ''), status: String(t?.status ?? 'pending') })).slice(0, 50)
      : [];
    this.touch();
  }

  onToolCall(call: ToolCallEntry): void {
    if (!call?.id || !CLAIMING_TOOLS.has(call.toolName)) return;
    if (call.status === 'running') this.runningMutations.add(call.id);
    else this.runningMutations.delete(call.id);
    this.scheduleEmit();
  }

  onToolResult(call: ToolCallEntry): void {
    if (!call?.id) return;
    if (this.runningMutations.delete(call.id)) this.scheduleEmit();
  }

  // --- publication & persistence ------------------------------------------------------------

  snapshot() {
    return toSnapshot(this.facts, { applying: this.runningMutations.size > 0 });
  }

  private touch(): void {
    this.facts.updatedAt = Date.now();
    this.scheduleEmit();
    this.scheduleSave();
  }

  private scheduleEmit(): void {
    if (this.emitTimer) return;
    this.emitTimer = setTimeout(() => {
      this.emitTimer = null;
      engineEvents.emit('review_update', this.snapshot());
    }, 80);
    this.emitTimer.unref?.();
  }

  private scheduleSave(): void {
    if (this.saveTimer) return;
    this.saveTimer = setTimeout(() => { this.saveTimer = null; this.saveNow(); }, 400);
    this.saveTimer.unref?.();
  }

  saveNow(): void {
    if (this.saveTimer) { clearTimeout(this.saveTimer); this.saveTimer = null; }
    if (!this.facts.sessionId) return; // nothing durable to attach the facts to yet
    try {
      fs.mkdirSync(sessionDir(), { recursive: true });
      fs.writeFileSync(reviewPath(this.facts.sessionId), JSON.stringify(this.facts, null, 2), 'utf8');
    } catch { /* persistence is best-effort — never break the live turn */ }
  }

  private loadFacts(id: string): ReviewFacts | null {
    try {
      const parsed = JSON.parse(fs.readFileSync(reviewPath(id), 'utf8'));
      if (!parsed || parsed.version !== 1 || !Array.isArray(parsed.approvals)) return null;
      return {
        version: 1,
        sessionId: id,
        approvals: parsed.approvals,
        changes: Array.isArray(parsed.changes) ? parsed.changes : [],
        verifications: Array.isArray(parsed.verifications) ? parsed.verifications.map((v: any) => ({
          ...v,
          coveredFiles: Array.isArray(v.coveredFiles) ? v.coveredFiles.map(String) : [],
          repoWide: v.repoWide === true || (v.repoWide === undefined && !!v.ok && isRepoWideEvidenceCommand(String(v.command || ''))),
        })) : [],
        checkpoints: Array.isArray(parsed.checkpoints) ? parsed.checkpoints : [],
        todos: Array.isArray(parsed.todos) ? parsed.todos : [],
        interrupted: !!parsed.interrupted,
        updatedAt: Number(parsed.updatedAt) || Date.now(),
      };
    } catch {
      return null; // pre-review thread / unreadable file → fresh facts, never an error
    }
  }

  /** Engine shutdown — pending approvals died with the process; say so on disk. */
  shutdown(): void {
    this.markDanglingInterrupted('rotated');
    this.saveNow();
  }
}

let manager: ReviewManager | null = null;

/** Attach the review recorder to engineEvents (idempotent). Called once from the headless entry. */
export function startReviewManager(): ReviewManager {
  if (manager) return manager;
  manager = new ReviewManager();
  engineEvents.on('request_pending', (r: any) => manager?.onRequestPending(r));
  engineEvents.on('request_resolved', (r: any) => manager?.onRequestResolved(r));
  engineEvents.on('review_change', (c: any) => manager?.onChange(c));
  engineEvents.on('review_evidence', (e: any) => manager?.onEvidence(e));
  engineEvents.on('timemachine_changed', () => manager?.onCheckpointChanged());
  engineEvents.on('checkpoint_failed', (label: any) => manager?.onCheckpointFailed(String(label ?? '')));
  engineEvents.on('todo_update', (todos: any) => manager?.onTodos(todos));
  engineEvents.on('tool_call', (c: any) => manager?.onToolCall(c));
  engineEvents.on('tool_call_result', (c: any) => manager?.onToolResult(c));
  engineEvents.on('session_changed', () => manager?.syncSession());
  engineEvents.on('shutdown', () => manager?.shutdown());
  manager.syncSession(); // adopt an already-live thread, then publish the initial state
  return manager;
}

export function getReviewManager(): ReviewManager | null {
  return manager;
}

import * as fs from 'fs';
import * as path from 'path';
import { execFile } from 'child_process';
import { promisify } from 'util';
import { IGraphStore } from '../graph/models';
import { PostHookResult } from '../tools/hooks';

const execFileAsync = promisify(execFile);

// B2 — auto edit→verify→fix loop. Implemented as a PostToolUse hook on the edit tools: after
// a successful edit, run a fast check and, on failure, APPEND the diagnostics to the tool
// result so the model self-corrects on its next loop step (no nested LLM call, no
// re-entrancy). Off by default (/governor verify on). Capped per file so a fix the model
// can't make doesn't nag forever.

let enabled = false;
let store: IGraphStore | null = null;
const attempts = new Map<string, number>(); // fullPath -> consecutive failed verifies reported
const MAX_ATTEMPTS = 2;

export function setVerifyEnabled(v: boolean): void { enabled = v; if (!v) attempts.clear(); }
export function isVerifyEnabled(): boolean { return enabled; }
export function registerVerifyGraphStore(s: IGraphStore | null): void { store = s; }

const CHECKABLE = new Set(['.ts', '.tsx', '.js', '.jsx', '.mjs', '.cjs']);
const EDIT_TOOLS = ['EditFileTool', 'WriteFileTool', 'MultiEditTool'];
export const VERIFY_TOOLS = EDIT_TOOLS;

function editedPath(args: any): string | null {
  if (args?.path) return args.path;
  if (Array.isArray(args?.edits) && args.edits[0]?.path) return args.edits[0].path;
  return null;
}

/** True when no graph store is registered, or the file owns at least one graph node. */
function fileIsRelevant(absPath: string): boolean {
  if (!store) return true;
  const norm = absPath.replace(/\\/g, '/');
  for (const node of store.getGraph().nodes.values()) {
    if (node.filePath && norm.endsWith(node.filePath.replace(/\\/g, '/'))) return true;
  }
  return false;
}

/** Run the fast check for a file: `node --check` for JS, project `tsc --noEmit` (filtered to
 *  the file) for TS. Returns passed=true when there's nothing actionable to report. */
async function runCheck(full: string, cwd: string, ext: string): Promise<{ passed: boolean; logs: string }> {
  if (['.js', '.jsx', '.mjs', '.cjs'].includes(ext)) {
    try {
      await execFileAsync('node', ['--check', full], { timeout: 20000 });
      return { passed: true, logs: '' };
    } catch (e: any) {
      return { passed: false, logs: (e.stderr || e.message || '').toString().trim() };
    }
  }
  // TypeScript: a project typecheck is accurate (single-file tsc misreports cross-file
  // imports). Run it, then keep only diagnostics for the edited file.
  if (!fs.existsSync(path.join(cwd, 'tsconfig.json'))) return { passed: true, logs: '' };
  try {
    await execFileAsync('npx', ['tsc', '--noEmit'], { cwd, timeout: 90000, maxBuffer: 4 * 1024 * 1024 });
    return { passed: true, logs: '' };
  } catch (e: any) {
    const out = ((e.stdout || '') + '\n' + (e.stderr || '')).toString();
    const rel = path.relative(cwd, full).replace(/\\/g, '/');
    const mine = out.split('\n').filter(l => l.includes(rel) || l.includes(path.basename(full)));
    if (mine.length === 0) return { passed: true, logs: '' }; // errors are elsewhere, not our edit
    return { passed: false, logs: mine.join('\n') };
  }
}

/** PostToolUse handler implementing the verify loop. */
export async function verifyHook(_toolName: string, args: any, result: any, context: any): Promise<PostHookResult | void> {
  if (!enabled) return undefined;
  if (typeof result === 'string' && /\b(rejected|cancelled|blocked|not found|Error)\b/i.test(result)) return undefined;

  const rel = editedPath(args);
  if (!rel) return undefined;
  const cwd = context?.cwd || process.cwd();
  const full = path.resolve(cwd, rel);
  const ext = path.extname(full).toLowerCase();
  if (!CHECKABLE.has(ext)) return undefined;
  if (!fileIsRelevant(full)) return undefined;

  const { passed, logs } = await runCheck(full, cwd, ext);
  if (passed) { attempts.delete(full); return undefined; }

  const n = (attempts.get(full) || 0) + 1;
  attempts.set(full, n);
  if (n > MAX_ATTEMPTS) {
    return { appendToResult: `⚠️ Auto-verify: ${rel} still fails after ${MAX_ATTEMPTS} fix attempt(s) — pausing auto-verify for it. Fix manually or run /heal.` };
  }
  return { appendToResult: `⚠️ Auto-verify failed for ${rel}. Fix these errors, then continue:\n${logs.slice(0, 1500)}` };
}

/**
 * The append-only record of every outbound network attempt this product made.
 *
 * ## What it is for
 *
 * PS-grade sovereignty is not a statement, it is an artefact someone else can read. A packet
 * capture proves what crossed the wire during the minutes it was running; this ledger proves what
 * the application *tried*, continuously, with the caller and purpose attached — which is the part a
 * capture cannot tell you. The two are complementary and the demo shows both.
 *
 * ## Why allowed calls are recorded too
 *
 * A ledger of refusals answers "what did we block?" — a question nobody asks at an audit. The
 * question asked is "what did you send, and to whom?", so an allowed loopback call to the local
 * model server is recorded with the same weight as a refused one. The report's headline number is
 * therefore honest by construction: `142 attempts · 142 loopback · 0 external`.
 *
 * ## Append-only, and what that does and does not mean
 *
 * Entries are appended as NDJSON and never rewritten in place: one line per attempt, so a truncated
 * write costs the last line and not the file.
 *
 * Each entry also carries the digest of the entry before it. That is what makes "append-only" a
 * property a READER can check rather than a description of how we happen to write: editing a line,
 * deleting one, or inserting one breaks every digest after it, and {@link verifyLedger} names the
 * first position that failed. Without the chain the file was tamper-evident in name only — the
 * lines were independent, so removing the one that recorded a leak left a file that still parsed
 * and still verified against nothing.
 *
 * It is tamper-EVIDENT, not tamper-PROOF, and the distinction is not pedantry. Anything with write
 * access can rewrite the whole file and recompute every digest, and that forgery verifies clean.
 * The chain raises the cost from "edit one line" to "rewrite the entire history consistently"; the
 * only thing that closes the rest of the gap is the head digest recorded somewhere this process
 * cannot reach, which is why {@link ledgerHead} is printed by `/sovereign verify` for an evaluator
 * to write down. Making the file genuinely append-only is the operating system's job (`chattr +a`,
 * a log shipper, an audit mount), and the deployment guide is where that belongs.
 *
 * The file lives beside the existing logs (`.breakglass/` in the workspace, per `utils/logger.ts`)
 * and is created 0600 inside a 0700 directory, because it records hostnames and purposes from
 * confidential work.
 */

import { stateDir } from '../utils/state.dir';
import { createHash } from 'node:crypto';
import * as fs from 'fs';
import * as path from 'path';
import { Destination } from './sovereign';
import { canonicalJson } from '../evidence/schema';

export interface EgressEntry {
  /** ISO-8601, UTC. */
  at: string;
  host: string;
  destination: Destination;
  verdict: 'allowed' | 'refused';
  /** Who attempted it — `LlmAdapter`, `WebFetchTool`, `RemoteEmbeddingBackend`, … */
  subsystem: string;
  purpose?: string;
  /** True when sovereign mode was active for this attempt. A verdict is only meaningful with it. */
  sovereign: boolean;
  /**
   * The digest of the entry before this one — `null` at the head of a chain.
   *
   * This is what makes the file's "append-only" claim checkable. Without it, deleting the one line
   * that records a leak, or rewriting a host, leaves no trace: the remaining lines are individually
   * well-formed and the file still parses. Linking each entry to its predecessor means any edit,
   * deletion or insertion breaks every digest after it, and {@link verifyLedger} names the first
   * position that failed.
   */
  prev?: string | null;
  /** sha256 over this entry's canonical form excluding `digest` itself. */
  digest?: string;
}

/** The bytes an entry's digest is computed over: the entry without its own `digest`. */
function digestPayload(entry: EgressEntry): string {
  const { digest: _ignored, ...rest } = entry;
  return canonicalJson(rest);
}

export function entryDigest(entry: EgressEntry): string {
  return createHash('sha256').update(digestPayload(entry)).digest('hex');
}

/** In-memory mirror of what this process appended, so `/sovereign` can report without re-reading. */
const session: EgressEntry[] = [];

/** Bounded: a long autonomous run must not turn the report into a memory leak. */
const SESSION_CAP = 5_000;

export function ledgerPath(): string {
  const override = process.env.BIMAX_EGRESS_LEDGER;
  if (override) return override;
  return path.join(stateDir('.breakglass'), 'egress.ledger');
}

/**
 * Append one attempt. Never throws: a ledger that can crash the turn it is auditing would be a
 * reason to switch auditing off, and an unwritable disk is not evidence about the network. A write
 * failure degrades to the in-memory mirror, and {@link ledgerWriteFailures} reports the count so
 * the CLI can say the file is incomplete instead of implying it is complete.
 */
let writeFailures = 0;

/**
 * The digest of the last entry appended, which the next one links to.
 *
 * `undefined` means "not yet established": the first write of a process reads the tail of the file
 * so a restart continues the existing chain instead of starting a second one. `null` means the
 * chain genuinely starts here (no file, or a file whose entries predate chaining).
 */
let head: string | null | undefined = undefined;

function seedHead(): void {
  const { entries } = readLedger();
  for (let i = entries.length - 1; i >= 0; i--) {
    if (entries[i].digest) { head = entries[i].digest as string; return; }
  }
  head = null;
}

/** The current chain head — the value an evaluator records to detect a later wholesale rewrite. */
export function ledgerHead(): string | null {
  if (head === undefined) seedHead();
  return head ?? null;
}

export function recordEgress(entry: EgressEntry): void {
  if (head === undefined) seedHead();
  // Any prev/digest a caller supplied is discarded: the chain is this module's to compute, and
  // accepting one from outside would let a caller forge a link.
  const { prev: _p, digest: _d, ...clean } = entry;
  const linked: EgressEntry = { ...clean, prev: head ?? null };
  linked.digest = entryDigest(linked);
  head = linked.digest;

  session.push(linked);
  if (session.length > SESSION_CAP) session.splice(0, session.length - SESSION_CAP);
  try {
    const file = ledgerPath();
    const dir = path.dirname(file);
    if (!fs.existsSync(dir)) fs.mkdirSync(dir, { recursive: true, mode: 0o700 });
    fs.appendFileSync(file, `${JSON.stringify(linked)}\n`, { mode: 0o600 });
  } catch {
    writeFailures += 1;
  }
}

export function ledgerWriteFailures(): number {
  return writeFailures;
}

/** Everything this process recorded, oldest first. */
export function sessionEgress(): readonly EgressEntry[] {
  return session;
}

/** Test seam and `/reset` hook. Does not touch the file — a session reset is not an audit reset. */
export function resetSessionEgress(): void {
  session.length = 0;
  writeFailures = 0;
  // Forget the head too, so the next write re-seeds from whatever file is now in play. Without
  // this a test that repoints BIMAX_EGRESS_LEDGER would chain the new file's first entry onto the
  // old file's last digest, and the new chain would verify as broken at position 0.
  head = undefined;
}

export interface EgressSummary {
  attempts: number;
  loopback: number;
  privateLan: number;
  allowlisted: number;
  external: number;
  refused: number;
  /** Distinct external hosts, for the line an auditor reads first. */
  externalHosts: string[];
  writeFailures: number;
}

export function summarize(entries: readonly EgressEntry[] = session): EgressSummary {
  const externalHosts = new Set<string>();
  let loopback = 0, privateLan = 0, allow = 0, external = 0, refused = 0;
  for (const e of entries) {
    if (e.destination === 'loopback') loopback += 1;
    else if (e.destination === 'private-lan') privateLan += 1;
    else if (e.destination === 'allowlisted') allow += 1;
    else { external += 1; externalHosts.add(e.host); }
    if (e.verdict === 'refused') refused += 1;
  }
  return {
    attempts: entries.length,
    loopback,
    privateLan,
    allowlisted: allow,
    external,
    refused,
    externalHosts: [...externalHosts].sort(),
    writeFailures,
  };
}

/**
 * Read back what is on disk. Used by `bimax sovereign report` so the proof covers previous runs,
 * not only the current process. A malformed line is skipped and counted rather than aborting the
 * read — a partially written last line must not make the whole ledger unreadable.
 */
export function readLedger(file = ledgerPath()): { entries: EgressEntry[]; skipped: number } {
  let raw: string;
  try {
    raw = fs.readFileSync(file, 'utf8');
  } catch {
    return { entries: [], skipped: 0 };
  }
  const entries: EgressEntry[] = [];
  let skipped = 0;
  for (const line of raw.split('\n')) {
    if (!line.trim()) continue;
    try {
      entries.push(JSON.parse(line) as EgressEntry);
    } catch {
      skipped += 1;
    }
  }
  return { entries, skipped };
}

export interface ChainVerification {
  /** True when every chained entry recomputes and links to the one before it. */
  intact: boolean;
  /** Entries carrying no digest because they predate chaining. Not a failure — an unproven prefix. */
  unchained: number;
  /** How many entries were actually checked. `0 checked` is not a pass; the report must say so. */
  checked: number;
  /** Position of the first entry that failed, as an index into `entries`. */
  brokenAt?: number;
  /** What specifically failed, in the terms an operator can act on. */
  reason?: string;
  /** Digest of the last verified entry. Compare against a head recorded elsewhere. */
  head: string | null;
}

/**
 * Walk the chain and report the first break.
 *
 * What this catches: editing an entry (its digest stops matching its content), deleting one (the
 * next entry's `prev` no longer names its predecessor), inserting one, and truncating the middle.
 *
 * What it does NOT catch, and the report must never imply otherwise: someone who rewrites the whole
 * file can recompute every digest, and the result verifies perfectly. The chain reduces tampering
 * from "edit one line" to "rewrite the entire file consistently", and the only thing that closes
 * the remaining gap is a head digest recorded somewhere this process cannot reach — which is why
 * {@link ledgerHead} is surfaced for an evaluator to write down.
 */
export function verifyLedger(entries: EgressEntry[] = readLedger().entries): ChainVerification {
  let unchained = 0;
  let checked = 0;
  let expectedPrev: string | null = null;
  let started = false;

  for (let i = 0; i < entries.length; i++) {
    const entry = entries[i];

    if (!entry.digest) {
      // A digest-less entry is only innocent while it is still the unchained prefix. Once chaining
      // has begun, one appearing again means a digest was stripped or raw lines were appended.
      if (started) {
        return {
          intact: false, unchained, checked, brokenAt: i, head: expectedPrev,
          reason: `has no digest, but the chain had already started — a digest was `
            + 'stripped, or unchained lines were appended by something other than this process',
        };
      }
      unchained += 1;
      continue;
    }

    if (entryDigest(entry) !== entry.digest) {
      return {
        intact: false, unchained, checked, brokenAt: i, head: expectedPrev,
        reason: `does not match its own digest — its contents were changed after it `
          + 'was written',
      };
    }
    if ((entry.prev ?? null) !== expectedPrev) {
      return {
        intact: false, unchained, checked, brokenAt: i, head: expectedPrev,
        reason: `links to ${entry.prev ?? 'nothing'}, but the entry before it digests to `
          + `${expectedPrev ?? 'nothing'} — an entry was removed or inserted here`,
      };
    }

    started = true;
    checked += 1;
    expectedPrev = entry.digest;
  }

  return { intact: true, unchained, checked, head: expectedPrev };
}

import { BashStaticAnalyzer } from '../governor/bash.analyzer';
import { Logger } from '../utils/logger';

/**
 * YoloClassifier — static bash command safety gate for 'auto' governor mode.
 *
 * Replaced the original two-LLM-call approach (64 + 1024 token round-trips per command)
 * with a deterministic rule-based classifier backed by BashStaticAnalyzer. Zero API cost,
 * zero hallucination risk, and consistent results.
 *
 * Risk threshold: 'none' or 'low' → safe; anything else → require explicit user approval.
 *   none  — read-only (ls, cat, grep…)                            → auto-approve
 *   low   — benign writes (git add, touch, npm run…)              → auto-approve
 *   medium — destructive potential (npm install, pip install…)    → ask user
 *   high  — highly dangerous (rm -rf /, curl | bash…)            → ask user
 *   unknown — unrecognized; unknown risk = not auto-approved       → ask user
 */
export class YoloClassifier {
  private readonly analyzer = new BashStaticAnalyzer();

  // LlmAdapter parameter kept for API compatibility but no longer used.
  constructor(_llm?: unknown) {}

  public async evaluateAction(action: string, _context?: unknown): Promise<boolean> {
    const { risk } = this.analyzer.analyze(action);
    const safe = risk === 'none' || risk === 'low';
    Logger.info(`[YoloClassifier] ${action.slice(0, 80)} → risk=${risk} → ${safe ? 'SAFE' : 'BLOCKED'}`);
    return safe;
  }
}

import * as net from 'net';
import * as tls from 'tls';
import { ConnectorConfig, QueryTemplate, MAX_ROWS } from './contract';

/**
 * Datastore adapters for the Open Socket.
 *
 * Each adapter has exactly one job: run a *pre-declared, human-authored* statement with bound
 * parameters and return rows. None of them accept model-authored query text, so none of them need
 * to defend against injection — the shape of the query is fixed before the model is involved.
 *
 * The read-only property is enforced in three independent places, because one is not enough:
 *
 *  - the template author writes only read statements;
 *  - `assertReadOnly` below refuses a template whose statement is not a read, at LOAD time, so a
 *    mistake in config fails at startup rather than at 2 a.m. against production;
 *  - the connection itself is put in a read-only mode where the server supports it (Postgres gets
 *    `default_transaction_read_only=on`), so even a server-side function that tries to write fails
 *    at the database rather than being trusted not to.
 *
 * The third layer is the one that matters when the first two are wrong.
 */

export interface QueryResult {
  rows: Record<string, unknown>[];
  rowCount: number;
  /** Bytes the process actually sent, for the ledger. */
  bytesOut: number;
  truncated: boolean;
}

export interface Adapter {
  readonly kind: string;
  query(template: QueryTemplate, bound: (string | number | boolean)[]): Promise<QueryResult>;
  close(): Promise<void>;
}

export class SocketQueryError extends Error {}

/**
 * Statement-level read-only check, run when config is LOADED, not per call.
 *
 * This is a config linter, not a security parser — the security comes from the model never writing
 * statements. Its job is to catch an operator who pastes an UPDATE into a template file, early and
 * loudly, instead of discovering it when an agent runs it.
 */
export function assertReadOnly(template: QueryTemplate, kind: ConnectorConfig['kind']): void {
  const statement = template.statement.trim();
  if (kind === 'postgres') {
    const head = statement.replace(/^\s*(?:--[^\n]*\n|\/\*[\s\S]*?\*\/|\s)*/g, '').slice(0, 40).toUpperCase();
    if (!/^(SELECT|WITH|TABLE|VALUES|EXPLAIN|SHOW)\b/.test(head)) {
      throw new SocketQueryError(
        `template "${template.name}" is not a read: it begins "${head.slice(0, 20).trim()}". `
        + 'Open Socket templates may only SELECT/WITH/TABLE/VALUES/EXPLAIN/SHOW.',
      );
    }
    // A stacked statement is how a "SELECT" template smuggles a write. Templates are single
    // statements; a semicolon that is not the trailing one is refused.
    const withoutTrailing = statement.replace(/;\s*$/, '');
    if (withoutTrailing.includes(';')) {
      throw new SocketQueryError(
        `template "${template.name}" contains more than one statement. Templates must be a single query.`,
      );
    }
    if (/\b(INSERT|UPDATE|DELETE|DROP|ALTER|CREATE|TRUNCATE|GRANT|REVOKE|COPY|CALL|DO)\b/i.test(withoutTrailing)) {
      throw new SocketQueryError(
        `template "${template.name}" contains a write keyword. Even inside a CTE this is refused.`,
      );
    }
    return;
  }

  // Redis: the statement is a command line; only retrieval commands are permitted.
  const command = statement.trim().split(/\s+/)[0]?.toUpperCase() || '';
  const READ_COMMANDS = new Set([
    'GET', 'MGET', 'STRLEN', 'EXISTS', 'TYPE', 'TTL', 'PTTL',
    'HGET', 'HMGET', 'HGETALL', 'HKEYS', 'HVALS', 'HLEN', 'HEXISTS',
    'LRANGE', 'LLEN', 'LINDEX',
    'SMEMBERS', 'SCARD', 'SISMEMBER', 'SRANDMEMBER',
    'ZRANGE', 'ZREVRANGE', 'ZRANGEBYSCORE', 'ZSCORE', 'ZCARD', 'ZCOUNT', 'ZRANK',
    'SCAN', 'HSCAN', 'SSCAN', 'ZSCAN', 'KEYS',
    'JSON.GET', 'JSON.MGET', 'JSON.TYPE', 'JSON.OBJKEYS',
    'FT.SEARCH', 'FT.AGGREGATE', 'FT.INFO',
    'XRANGE', 'XREVRANGE', 'XLEN', 'GETRANGE', 'BITCOUNT', 'DBSIZE',
  ]);
  if (!READ_COMMANDS.has(command)) {
    throw new SocketQueryError(
      `template "${template.name}" uses Redis command "${command}", which is not a read. `
      + `Permitted: ${[...READ_COMMANDS].slice(0, 12).join(', ')}, …`,
    );
  }
}

function password(config: ConnectorConfig): string | undefined {
  // The secret is read from the environment at connect time and never stored in config or logged.
  return config.passwordEnv ? process.env[config.passwordEnv] : undefined;
}

/* ------------------------------------------------------------------ Postgres */

/**
 * How a Postgres client is constructed. Injectable so a test can drive the adapter without a server
 * AND without module mocking — `jest.doMock('pg', …)` is defeated as soon as anything else in the
 * same worker has already loaded the real driver, which is exactly what happens once the live
 * integration tests run alongside these. A seam is deterministic where a mock is order-dependent.
 */
export type PgClientFactory = (options: Record<string, unknown>) => {
  connect(): Promise<void>;
  query(config: { text: string; values: unknown[] }): Promise<{ rows: Record<string, unknown>[] }>;
  end(): Promise<void>;
};

export class PostgresAdapter implements Adapter {
  readonly kind = 'postgres';
  private client: any = null;

  constructor(
    private readonly config: ConnectorConfig,
    private readonly clientFactory?: PgClientFactory,
  ) {}

  private async connect(): Promise<any> {
    if (this.client) return this.client;
    // eslint-disable-next-line @typescript-eslint/no-require-imports
    const Client = this.clientFactory ?? ((options: Record<string, unknown>) => new (require('pg').Client)(options));
    const client = Client({
      host: this.config.host,
      port: this.config.port,
      database: this.config.database,
      user: this.config.user,
      password: password(this.config),
      ssl: this.config.tls ? { rejectUnauthorized: false } : undefined,
      connectionTimeoutMillis: this.config.timeoutMs ?? 10_000,
      statement_timeout: this.config.timeoutMs ?? 10_000,
      // Server-enforced read-only. If a template or a server-side function attempts a write, the
      // DATABASE refuses it — we are not relying on our own checks having been correct.
      options: '-c default_transaction_read_only=on',
      application_name: 'bimax-open-socket',
    });
    await client.connect();
    this.client = client;
    return client;
  }

  async query(template: QueryTemplate, bound: (string | number | boolean)[]): Promise<QueryResult> {
    const client = await this.connect();
    const limit = Math.min(template.maxRows ?? MAX_ROWS, MAX_ROWS);
    // Parameters ride the driver's binary bind path — they are never concatenated into SQL, so a
    // value cannot alter the statement's shape whatever it contains.
    const bytesOut = Buffer.byteLength(template.statement, 'utf8')
      + bound.reduce<number>((sum, value) => sum + Buffer.byteLength(String(value), 'utf8'), 0);
    let result: any;
    try {
      result = await client.query({ text: template.statement, values: bound, rowMode: undefined });
    } catch (error) {
      throw new SocketQueryError(`postgres refused the query: ${(error as Error).message}`);
    }
    const rows = (result.rows || []).slice(0, limit);
    return { rows, rowCount: rows.length, bytesOut, truncated: (result.rows || []).length > limit };
  }

  async close(): Promise<void> {
    if (this.client) { try { await this.client.end(); } catch { /* already gone */ } this.client = null; }
  }
}

/* --------------------------------------------------------------------- Redis */

/** Encode a Redis command as a RESP array — the only thing we ever write to the socket. */
function encodeCommand(parts: string[]): Buffer {
  const head = `*${parts.length}\r\n`;
  const body = parts.map((part) => `$${Buffer.byteLength(part, 'utf8')}\r\n${part}\r\n`).join('');
  return Buffer.from(head + body, 'utf8');
}

type RespValue = string | number | null | RespValue[];

/** Minimal RESP2 reader. Returns [value, bytesConsumed] or null when more data is needed. */
function parseResp(buffer: Buffer, offset: number): [RespValue, number] | null {
  if (offset >= buffer.length) return null;
  const type = buffer[offset];
  const lineEnd = buffer.indexOf('\r\n', offset);
  if (lineEnd === -1) return null;
  const line = buffer.toString('utf8', offset + 1, lineEnd);
  const next = lineEnd + 2;

  switch (type) {
    case 0x2b: return [line, next];                       // +simple
    case 0x3a: return [Number(line), next];               // :integer
    case 0x2d: throw new SocketQueryError(`redis error: ${line}`); // -error
    case 0x24: {                                          // $bulk
      const length = Number(line);
      if (length === -1) return [null, next];
      if (buffer.length < next + length + 2) return null;
      return [buffer.toString('utf8', next, next + length), next + length + 2];
    }
    case 0x2a: {                                          // *array
      const count = Number(line);
      if (count === -1) return [null, next];
      const items: RespValue[] = [];
      let cursor = next;
      for (let i = 0; i < count; i++) {
        const parsed = parseResp(buffer, cursor);
        if (!parsed) return null;
        items.push(parsed[0]);
        cursor = parsed[1];
      }
      return [items, cursor];
    }
    default:
      throw new SocketQueryError(`unrecognised RESP type byte 0x${type.toString(16)}`);
  }
}

export class RedisAdapter implements Adapter {
  readonly kind = 'redis';

  constructor(private readonly config: ConnectorConfig) {}

  /** One connection per call, closed immediately. A retrieval window holds nothing open. */
  private async send(commands: string[][]): Promise<{ replies: RespValue[]; bytesOut: number }> {
    const timeout = this.config.timeoutMs ?? 10_000;
    const payloads = commands.map(encodeCommand);
    const bytesOut = payloads.reduce((sum, part) => sum + part.length, 0);

    return new Promise((resolve, reject) => {
      const options = { host: this.config.host, port: this.config.port };
      const socket: net.Socket = this.config.tls
        ? tls.connect({ ...options, rejectUnauthorized: false })
        : net.connect(options);

      let chunks = Buffer.alloc(0);
      const replies: RespValue[] = [];
      const done = (error?: Error) => {
        socket.destroy();
        if (error) reject(error); else resolve({ replies, bytesOut });
      };

      socket.setTimeout(timeout, () => done(new SocketQueryError(`redis timed out after ${timeout}ms`)));
      socket.on('error', (error) => done(new SocketQueryError(`redis connection failed: ${error.message}`)));
      socket.on('connect', () => { for (const payload of payloads) socket.write(payload); });
      socket.on('data', (part) => {
        chunks = Buffer.concat([chunks, part]);
        try {
          let offset = 0;
          for (;;) {
            const parsed = parseResp(chunks, offset);
            if (!parsed) break;
            replies.push(parsed[0]);
            offset = parsed[1];
            if (replies.length === commands.length) { done(); return; }
          }
          chunks = chunks.subarray(offset);
        } catch (error) { done(error as Error); }
      });
    });
  }

  async query(template: QueryTemplate, bound: (string | number | boolean)[]): Promise<QueryResult> {
    // `$1`-style placeholders are substituted into ARGUMENT SLOTS, never into the command line as
    // text: the command is tokenised first, then each token that is exactly a placeholder is
    // replaced by its bound value. A value containing a space therefore stays one argument and
    // cannot become a second command.
    const tokens = template.statement.trim().split(/\s+/);
    const argv = tokens.map((token) => token.replace(/\$(\d+)/g, (_whole, digits: string) => {
      // Substitution happens WITHIN a token, because the useful Redis forms embed the parameter in
      // a key: `GET reading:$1`, `HGETALL equipment:$1`. An earlier version only replaced a token
      // that was exactly `$1`, so those templates sent the literal text "reading:$1" to the server
      // and quietly returned nothing — the failure looked like "no such key" rather than a bug.
      //
      // Tokenising FIRST and substituting after is what keeps this safe: the argv boundaries are
      // fixed by the template's own whitespace before any value is seen, so a parameter containing
      // a space lands inside one argument and cannot become a second one.
      const index = Number(digits) - 1;
      if (index < 0 || index >= bound.length) {
        throw new SocketQueryError(`template "${template.name}" references $${digits} with no such parameter`);
      }
      return String(bound[index]);
    }));

    const preamble: string[][] = [];
    const secret = password(this.config);
    if (secret) preamble.push(this.config.user ? ['AUTH', this.config.user, secret] : ['AUTH', secret]);
    // `database` was honoured by the Postgres adapter and silently IGNORED here, so a connector
    // pointing at any Redis logical database other than 0 read from the wrong one and returned
    // "no such key" — indistinguishable from a genuinely absent record, which is the worst way for
    // a retrieval surface to be wrong. Found by running against a real server rather than a script.
    const database = (this.config.database ?? '').trim();
    if (database) {
      if (!/^\d{1,3}$/.test(database)) {
        throw new SocketQueryError(
          `connector "${this.config.name}": Redis database must be a number, got "${database}"`,
        );
      }
      preamble.push(['SELECT', database]);
    }

    const { replies, bytesOut } = await this.send([...preamble, argv]);
    const reply = replies[replies.length - 1];
    const limit = Math.min(template.maxRows ?? MAX_ROWS, MAX_ROWS);

    // Flatten RESP into rows so the caller renders one shape regardless of datastore.
    let rows: Record<string, unknown>[];
    if (Array.isArray(reply)) {
      rows = reply.slice(0, limit).map((value, index) => ({ index, value: Array.isArray(value) ? value : value }));
    } else {
      rows = reply === null ? [] : [{ index: 0, value: reply }];
    }
    return {
      rows, rowCount: rows.length, bytesOut,
      truncated: Array.isArray(reply) && reply.length > limit,
    };
  }

  async close(): Promise<void> { /* connections are per-call */ }
}

export function createAdapter(config: ConnectorConfig): Adapter {
  if (config.kind === 'postgres') return new PostgresAdapter(config);
  if (config.kind === 'redis') return new RedisAdapter(config);
  throw new SocketQueryError(`unsupported connector kind: ${(config as ConnectorConfig).kind}`);
}

