import { SubTask, ClassifiedTask, ClassifiedTaskSchema, TaskTypeEnum } from './types';
import { LlmAdapter } from '../core/llm.adapter';
import { Logger } from '../utils';

export class TaskClassifier {
  constructor(private llm: LlmAdapter) {}

  async classify(task: SubTask, maxRetries = 3): Promise<ClassifiedTask> {
    Logger.info(`[Classifier] Classifying node: ${task.id}`);

    let lastError = "";

    for (let attempt = 1; attempt <= maxRetries; attempt++) {
      const systemPrompt = `You are a strict task classifier. Analyze the following task description and classify it into exactly ONE of these types:
"trigger", "cron", "webhook", "cli", "agent"

Respond with a JSON object:
{ "type": "the_type" }

${lastError ? `\nWARNING: Your previous attempt failed validation. Fix this error:\n${lastError}` : ''}`;

      const result = await this.llm.generateTinyPlans(task.description, systemPrompt);

      if (result.status !== 200 || !result.data) {
        await new Promise(r => setTimeout(r, (result.retryAfter || 2) * 1000));
        continue;
      }

      try {
        if (!result.data.type) throw new Error("Missing 'type' field in JSON response.");

        const typeValue = TaskTypeEnum.parse(result.data.type);

        const classifiedTask: ClassifiedTask = {
          ...task,
          type: typeValue,
          metadata: { classifiedAt: Date.now() }
        };

        // Final sanity check
        ClassifiedTaskSchema.parse(classifiedTask);

        Logger.info(`[Classifier] ✅ Node ${task.id} classified as [${typeValue}]`);
        return classifiedTask;

      } catch (e: any) {
        Logger.warn(`[Classifier] ⚠ Classification failed. Auto-correcting...`);
        lastError = e.message;
      }
    }

    throw new Error(`[Classifier] FATAL: Failed to classify task ${task.id}.`);
  }
}

import { SubTask, SubTaskArraySchema } from './types';
import { LlmAdapter } from '../core/llm.adapter';
import { Logger } from '../utils';

export class TaskDecomposer {
  constructor(private llm: LlmAdapter) {}

  async decompose(prompt: string, maxRetries = 3): Promise<SubTask[]> {
    Logger.info(`[Decomposer] Initiating robust decomposition for: "${prompt}"`);

    let lastError = "";

    for (let attempt = 1; attempt <= maxRetries; attempt++) {
      const systemPrompt = `You are the Mythos Decomposer, the master planner of BreakGlassWing. 
Your role is to translate high-level user requests into a Directed Acyclic Graph (DAG) of asynchronous SubTasks.

You MUST respond with a JSON array of objects. 

## The Law of the DAG
- Tasks must be hyper-focused and isolated. A WorkerAgent should be able to execute a task using ONLY the context provided in its description.
- Identify parallelization opportunities. If two files can be refactored independently, they must not depend on each other.
- The \`dependencies\` array defines execution order. Use it strictly to prevent race conditions.

## The Governor Verification Step
- Always schedule a final Verification Task at the end of the DAG. The WorkerAgent assigned to this task must run the test suite or syntax checker so the Governor can stamp the execution as safe.

Each object MUST match this schema:
{
  "id": "string", // A unique local id like task-1
  "description": "string", // Clear action to perform. Provide absolute paths and exact targets.
  "dependencies": ["string"] // Array of task ids that must be completed first
}

${lastError ? `\nWARNING: Your previous attempt failed validation. Please correct this exact error:\n${lastError}` : ''}`;

      Logger.info(`[Decomposer] LLM Attempt ${attempt}/${maxRetries}...`);
      const result = await this.llm.generateTinyPlans(prompt, systemPrompt);

      if (result.status !== 200 || !result.data) {
        Logger.error(`[Decomposer] LLM Network Error. Retry after: ${result.retryAfter}s`);
        await new Promise(r => setTimeout(r, (result.retryAfter || 2) * 1000));
        continue;
      }

      try {
        // Attempt strict Zod validation
        let rawData = result.data;
        if (rawData.tasks && Array.isArray(rawData.tasks)) {
           rawData = rawData.tasks;
        } else if (!Array.isArray(rawData)) {
           throw new Error("Expected a JSON array of tasks.");
        }

        const validTasks = SubTaskArraySchema.parse(rawData);

        // CYCLE DETECTION DFS (TASK-002)
        const checkCycles = (tasks: SubTask[]) => {
          const visited = new Set<string>();
          const recursionStack = new Set<string>();
          const taskMap = new Map(tasks.map(t => [t.id, t]));

          const dfs = (nodeId: string) => {
            if (recursionStack.has(nodeId)) return true;
            if (visited.has(nodeId)) return false;

            visited.add(nodeId);
            recursionStack.add(nodeId);

            const task = taskMap.get(nodeId);
            if (task && task.dependencies) {
              for (const dep of task.dependencies) {
                if (dfs(dep)) return true;
              }
            }
            recursionStack.delete(nodeId);
            return false;
          };

          for (const task of tasks) {
            if (dfs(task.id)) return true;
          }
          return false;
        };

        if (checkCycles(validTasks)) {
          throw new Error("DAG contains circular dependencies. SubTasks must form a valid acyclic graph.");
        }

        Logger.info(`[Decomposer] ✅ Schema validated successfully. Generated ${validTasks.length} DAG nodes.`);
        return validTasks;

      } catch (e: any) {
        Logger.warn(`[Decomposer] ⚠ Validation Failed on attempt ${attempt}. Injecting auto-correction.`);
        lastError = e.message;
        if (attempt >= maxRetries) {
          throw new Error(`[Decomposer] FATAL: Failed to generate valid task graph after ${maxRetries} attempts. Last error: ${lastError}`, { cause: e });
        }
      }
    }

    throw new Error(`[Decomposer] FATAL: Exceeded maximum retries (${maxRetries}).`);
  }
}

export * from './types';
export * from './decomposer';
export * from './classifier';
export * from './mapper';

import { TaskDecomposer } from './decomposer';
import { TaskClassifier } from './classifier';
import { TaskMapper } from './mapper';
import { MappedTask } from './types';
import { LlmAdapter } from '../core/llm.adapter';
import { ApiKeyManager } from '../credits/api.key.manager';
import { IEventBus } from '../core/interfaces';

/**
 * The Task Pipeline processes raw user prompts through
 * decomposition, classification, and mapping to produce executable tasks.
 */
export class TaskPipeline {
  private decomposer: TaskDecomposer;
  private classifier: TaskClassifier;
  private mapper: TaskMapper;


  constructor(private eventBus: IEventBus, private llmAdapter: LlmAdapter) {
    this.decomposer = new TaskDecomposer(this.llmAdapter);
    this.classifier = new TaskClassifier(this.llmAdapter);
    this.mapper = new TaskMapper();
  }

  /**
   * Runs the full pipeline on a prompt.
   */
  async process(prompt: string): Promise<MappedTask[]> {
    console.log(`[TaskPipeline] Starting process for prompt...`);

    // 1. Decompose
    this.eventBus.emit('PIPELINE_UPDATE', { stage: 'Decomposer' });
    const subTasks = await this.decomposer.decompose(prompt);

    // 2. Classify
    this.eventBus.emit('PIPELINE_UPDATE', { stage: 'Classifier' });
    const classifiedTasks = await Promise.all(
      subTasks.map(task => this.classifier.classify(task))
    );

    // 3. Map
    this.eventBus.emit('PIPELINE_UPDATE', { stage: 'Mapper' });
    const mappedTasks = classifiedTasks.map(task => this.mapper.map(task));

    console.log(`[TaskPipeline] Finished processing. Generated ${mappedTasks.length} tasks.\n`);
    this.eventBus.emit('PIPELINE_UPDATE', { stage: 'Execution' });
    return mappedTasks;
  }
}

import * as os from 'os';
import { Logger } from '../utils';

import { IEventBus } from '../core/interfaces';

export class MemoryMonitor {
  private isRunning = false;
  private monitorLoop: NodeJS.Timeout | null = null;

  constructor(
    private eventBus: IEventBus,
    private readonly MEM_WARNING_MB = 1000,
    private readonly MEM_CRITICAL_MB = 2000
  ) {}

  public start(intervalMs: number = 5000) {
    if (this.isRunning) {
      this.stop(); // Clear existing interval if called multiple times
    }

    this.isRunning = true;
    Logger.info(`[MemoryMonitor] Started tracking RSS usage. Critical limit: ${this.MEM_CRITICAL_MB}MB`);

    this.monitorLoop = setInterval(() => {
      if (!this.isRunning) {
        this.stop();
        return;
      }
      this.checkMemory();
    }, intervalMs);
    // Don't let the monitor timer keep the process (or a Jest worker) alive past its real work.
    this.monitorLoop.unref();
  }

  public stop() {
    this.isRunning = false;
    if (this.monitorLoop) {
      clearInterval(this.monitorLoop);
      this.monitorLoop = null;
    }
  }

  public getMemoryMB(): number {
    const memoryUsage = process.memoryUsage();
    return Math.round(memoryUsage.rss / 1024 / 1024);
  }

  private checkMemory() {
    const rssMB = this.getMemoryMB();

    if (rssMB > this.MEM_CRITICAL_MB) {
      Logger.error(`[MemoryMonitor] CRITICAL: Memory usage (${rssMB}MB) exceeded limit of ${this.MEM_CRITICAL_MB}MB.`);
      Logger.error(`[MemoryMonitor] Forcing clean restart to prevent OOM.`);
      // Emit EMERGENCY_HALT to trigger graceful shutdown (GlobalShutdown coordinates this)
      this.eventBus.emit('EMERGENCY_HALT', { reason: 'OUT_OF_MEMORY' });
    } 
    else if (rssMB > this.MEM_WARNING_MB) {
      Logger.warn(`[MemoryMonitor] WARNING: Memory usage (${rssMB}MB) approaching critical limit.`);
    }
  }
}

import { globalTelemetry } from './telemetry';
import { Logger } from '../utils/logger';

/**
 * OTLP metrics exporter — the time-series counterpart of trace.ts. Gathers the counters the
 * engine already keeps (per-tool latency stats, prompt-cache hit rate, Headroom compression
 * savings) into OTLP/HTTP JSON gauges/sums and POSTs them to {endpoint}/v1/metrics on an
 * interval, so a Grafana/Datadog dashboard gets live series instead of only spans.
 *
 * Zero dependencies, entirely off unless OTEL_EXPORTER_OTLP_ENDPOINT (or BIMAX_OTLP_ENDPOINT)
 * is set. Gauge semantics: every export reports the CURRENT session-cumulative value with a
 * fresh timestamp — backends diff/rate() as needed.
 */

interface MetricPoint {
  name: string;
  value: number;
  attributes?: Record<string, string>;
}

/** Snapshot every exportable counter the engine tracks right now. */
export function gatherMetrics(): MetricPoint[] {
  const out: MetricPoint[] = [];

  for (const t of globalTelemetry.getToolStats()) {
    const attrs = { 'gen_ai.tool.name': t.name };
    out.push({ name: 'bimax.tool.calls', value: t.count, attributes: attrs });
    out.push({ name: 'bimax.tool.duration.avg_ms', value: t.avgMs, attributes: attrs });
    out.push({ name: 'bimax.tool.duration.p95_ms', value: t.p95Ms, attributes: attrs });
  }

  const cache = globalTelemetry.getCacheStats();
  out.push({ name: 'bimax.cache.read_tokens', value: cache.readTokens });
  out.push({ name: 'bimax.cache.creation_tokens', value: cache.creationTokens });
  out.push({ name: 'bimax.prompt.total_tokens', value: cache.totalPrompt });
  const rate = parseFloat(cache.hitRate);
  if (Number.isFinite(rate)) out.push({ name: 'bimax.cache.hit_rate_pct', value: rate });

  // Headroom compression savings — optional subsystem, must never break metrics gathering.
  try {
    // eslint-disable-next-line @typescript-eslint/no-require-imports
    const { getHeadroomReport } = require('../memory/headroom.compress') as typeof import('../memory/headroom.compress');
    const r = getHeadroomReport();
    if (r && typeof r.totalSaved === 'number') {
      out.push({ name: 'bimax.compression.saved_tokens', value: r.totalSaved });
    }
  } catch { /* headroom optional */ }

  return out;
}

/** OTLP/HTTP JSON encoding: every point as a gauge (backends rate()/diff() as needed). */
export function toOtlpMetricsJson(points: MetricPoint[], serviceName = 'bimax'): object {
  const now = `${Date.now()}000000`;
  const attrList = (attrs: Record<string, string> = {}) =>
    Object.entries(attrs).map(([key, v]) => ({ key, value: { stringValue: v } }));
  return {
    resourceMetrics: [{
      resource: { attributes: attrList({ 'service.name': serviceName }) },
      scopeMetrics: [{
        scope: { name: 'bimax.metrics', version: '1' },
        metrics: points.map(p => ({
          name: p.name,
          gauge: {
            dataPoints: [{
              timeUnixNano: now,
              ...(Number.isInteger(p.value) ? { asInt: String(p.value) } : { asDouble: p.value }),
              attributes: attrList(p.attributes),
            }],
          },
        })),
      }],
    }],
  };
}

let _timer: NodeJS.Timeout | null = null;

/** POST one metrics snapshot now. No-op without an endpoint. */
export async function exportMetricsNow(): Promise<boolean> {
  const endpoint = process.env.OTEL_EXPORTER_OTLP_ENDPOINT || process.env.BIMAX_OTLP_ENDPOINT;
  if (!endpoint) return false;
  const points = gatherMetrics();
  if (points.length === 0) return false;
  try {
    await fetch(endpoint.replace(/\/$/, '') + '/v1/metrics', {
      method: 'POST',
      headers: { 'content-type': 'application/json' },
      body: JSON.stringify(toOtlpMetricsJson(points)),
      signal: AbortSignal.timeout(3000),
    });
    return true;
  } catch (e: any) {
    Logger.warn(`[Metrics] OTLP export failed: ${e?.message}`);
    return false;
  }
}

/**
 * Start the periodic exporter (default every 60s). Silent no-op when no OTLP endpoint is
 * configured, so boot can call this unconditionally. unref'd — never keeps the process alive.
 */
export function startMetricsExporter(intervalMs = 60_000): void {
  const endpoint = process.env.OTEL_EXPORTER_OTLP_ENDPOINT || process.env.BIMAX_OTLP_ENDPOINT;
  if (_timer || !endpoint) return;
  _timer = setInterval(() => void exportMetricsNow(), intervalMs);
  _timer.unref?.();
}

export function stopMetricsExporter(): void {
  if (_timer) { clearInterval(_timer); _timer = null; }
}

import { stateDir } from '../utils/state.dir';
import { Logger } from '../utils/logger';
import * as fs from 'fs/promises';
import * as path from 'path';

export class TelemetryEngine {
  private bootTime: number;
  private readonly STORAGE_DIR = path.join(stateDir('.breakglass'), 'telemetry');
  private readonly METRICS_FILE = path.join(this.STORAGE_DIR, 'metrics.json');

  constructor() {
    this.bootTime = Date.now();
    this.initStorage().catch(console.error);
  }

  private async initStorage() {
    try {
      await fs.mkdir(this.STORAGE_DIR, { recursive: true });
    } catch (e) {
      // ignore
    }
  }

  public getUptimeSeconds(): number {
    return (Date.now() - this.bootTime) / 1000;
  }

  public async flushTelemetry(rssMB: number, keyStates: any[]) {
    const payload = {
      timestamp: new Date().toISOString(),
      metrics: {
        memory_mb: rssMB,
        uptime_s: this.getUptimeSeconds(),
        keys: keyStates.map((k: any, i: number) => ({
          key_index: i + 1,
          total_ok: k.total_ok,
          total_fail: k.total_fail,
          consecutive_429: k.consecutive_429
        }))
      }
    };

    Logger.info(`[TelemetryEngine] Flushing metrics to Disk: Mem ${payload.metrics.memory_mb}MB, Uptime ${payload.metrics.uptime_s.toFixed(1)}s`);

    // Physically persist telemetry to a JSON file so external scrapers can read it
    try {
      await fs.writeFile(this.METRICS_FILE, JSON.stringify(payload, null, 2), 'utf-8');
    } catch (err: any) {
      Logger.error(`[TelemetryEngine] Failed to write metrics.json: ${err.message}`);
    }
  }
}

// Provider-neutral latency attribution. When a model response stalls, the honest question is
// "whose delay is this?" — and the only honest answer comes from measuring the network path at
// the moment it happens. This module probes the provider ORIGIN (DNS → TCP → TLS, no request
// body, no credentials) and classifies the stall from evidence:
//
//   local path fast + long wait   → the delay happened beyond our connection (provider-side)
//   DNS failed/slow               → this machine's resolver, not the provider
//   TCP/TLS failed/slow           → the network path, not the provider
//
// Nothing in the product is allowed to say "provider cold start" unless an entry here backs it.
// Evidence is kept in a small in-memory ring surfaced by /perf.

import * as dns from 'dns';
import * as net from 'net';
import * as tls from 'tls';

export type WaitAttribution = 'provider-side' | 'local-dns' | 'network-path' | 'network-slow' | 'unknown';

export interface OriginProbe {
  origin: string;
  ok: boolean;
  dnsMs: number;
  tcpMs: number;
  tlsMs: number;
  totalMs: number;
  failedPhase?: 'dns' | 'tcp' | 'tls';
  error?: string;
}

export interface SlowWaitEvidence {
  at: number;            // wall clock, for the /perf readout
  origin: string;
  waitedMs: number;      // how long the first token / first byte took (or timed out after)
  timedOut: boolean;
  probe: OriginProbe;
  attribution: WaitAttribution;
}

/** A first-token wait longer than this is worth attributing with a probe. */
export const SLOW_WAIT_THRESHOLD_MS = 8_000;
/** Local path (dns+tcp+tls) faster than this at probe time = "the local path is fine". */
const HEALTHY_PATH_MS = 1_500;
const PROBE_PHASE_TIMEOUT_MS = 4_000;
/** At most one probe per origin per window — evidence, not surveillance. */
const PROBE_COOLDOWN_MS = 60_000;
const MAX_EVIDENCE = 20;

const evidence: SlowWaitEvidence[] = [];
const lastProbeAt = new Map<string, number>();

/** Pure classification of a stall from its probe. Exported for tests. */
export function classifyWait(probe: OriginProbe): WaitAttribution {
  if (!probe.ok) {
    if (probe.failedPhase === 'dns') return 'local-dns';
    if (probe.failedPhase === 'tcp' || probe.failedPhase === 'tls') return 'network-path';
    return 'unknown';
  }
  return probe.totalMs <= HEALTHY_PATH_MS ? 'provider-side' : 'network-slow';
}

/** One neutral, evidence-grounded sentence per attribution. */
export function describeAttribution(a: WaitAttribution): string {
  switch (a) {
    case 'provider-side': return 'local network path verified fast — the wait happened on the provider side';
    case 'local-dns': return 'DNS resolution failed on this machine — the provider was never reached';
    case 'network-path': return 'the network path to the provider failed — not a provider delay';
    case 'network-slow': return 'the network path itself was slow — attribution split between network and provider';
    case 'unknown': return 'attribution inconclusive — no phase produced usable evidence';
    default: return 'attribution inconclusive — no phase produced usable evidence';
  }
}

function timed<T>(work: (done: (err: Error | null, value?: T) => void) => void, timeoutMs: number): Promise<{ ms: number; value?: T }> {
  const start = performance.now();
  return new Promise((resolve, reject) => {
    let settled = false;
    const timer = setTimeout(() => {
      if (settled) return;
      settled = true;
      reject(new Error(`timed out after ${timeoutMs}ms`));
    }, timeoutMs);
    work((err, value) => {
      if (settled) return;
      settled = true;
      clearTimeout(timer);
      if (err) reject(err);
      else resolve({ ms: performance.now() - start, value });
    });
  });
}

/**
 * Measure DNS → TCP → TLS to an origin. No HTTP request is made and no credentials are involved:
 * this is purely "can this machine reach that host, and how fast is each phase right now".
 */
export async function probeOrigin(originUrl: string): Promise<OriginProbe> {
  let url: URL;
  try { url = new URL(originUrl); }
  catch {
    return { origin: originUrl, ok: false, dnsMs: 0, tcpMs: 0, tlsMs: 0, totalMs: 0, failedPhase: 'dns', error: 'invalid origin URL' };
  }
  const origin = url.origin;
  const host = url.hostname;
  const port = Number(url.port) || (url.protocol === 'http:' ? 80 : 443);
  const result: OriginProbe = { origin, ok: false, dnsMs: 0, tcpMs: 0, tlsMs: 0, totalMs: 0 };

  let address: string;
  try {
    const r = await timed<string>(done => {
      dns.lookup(host, (err, addr) => done(err, addr));
    }, PROBE_PHASE_TIMEOUT_MS);
    result.dnsMs = Math.round(r.ms);
    address = r.value!;
  } catch (err: any) {
    result.failedPhase = 'dns';
    result.error = String(err?.message || err).slice(0, 200);
    result.totalMs = result.dnsMs;
    return result;
  }

  let socket: net.Socket;
  try {
    const r = await timed<net.Socket>(done => {
      const s = net.connect({ host: address, port });
      s.once('connect', () => done(null, s));
      s.once('error', e => done(e));
    }, PROBE_PHASE_TIMEOUT_MS);
    result.tcpMs = Math.round(r.ms);
    socket = r.value!;
  } catch (err: any) {
    result.failedPhase = 'tcp';
    result.error = String(err?.message || err).slice(0, 200);
    result.totalMs = result.dnsMs + result.tcpMs;
    return result;
  }

  if (url.protocol === 'https:') {
    try {
      const r = await timed<tls.TLSSocket>(done => {
        const t = tls.connect({ socket, servername: host }, () => done(null, t));
        t.once('error', e => done(e));
      }, PROBE_PHASE_TIMEOUT_MS);
      result.tlsMs = Math.round(r.ms);
      r.value!.destroy();
    } catch (err: any) {
      socket.destroy();
      result.failedPhase = 'tls';
      result.error = String(err?.message || err).slice(0, 200);
      result.totalMs = result.dnsMs + result.tcpMs + result.tlsMs;
      return result;
    }
  } else {
    socket.destroy();
  }

  result.ok = true;
  result.totalMs = result.dnsMs + result.tcpMs + result.tlsMs;
  return result;
}

/**
 * Fire-and-forget attribution of one slow first-token wait. Rate-limited per origin; records an
 * evidence entry the /perf readout renders. Never throws, never blocks the turn.
 */
export function attributeSlowWait(baseURL: string, waitedMs: number, timedOut: boolean): void {
  let origin: string;
  try { origin = new URL(baseURL).origin; } catch { return; }
  const now = Date.now();
  const last = lastProbeAt.get(origin) || 0;
  if (now - last < PROBE_COOLDOWN_MS) return;
  lastProbeAt.set(origin, now);
  void probeOrigin(origin)
    .then(probe => {
      evidence.push({ at: now, origin, waitedMs: Math.round(waitedMs), timedOut, probe, attribution: classifyWait(probe) });
      if (evidence.length > MAX_EVIDENCE) evidence.shift();
    })
    .catch(() => { /* evidence is best-effort */ });
}

/** Most-recent-first evidence for the /perf readout. */
export function slowWaitEvidence(): SlowWaitEvidence[] {
  return evidence.slice().reverse();
}

/** Test seam. */
export function __resetNetprobe(): void {
  evidence.length = 0;
  lastProbeAt.clear();
}

/**
 * Per-task counters — the denominator this project has been claiming numbers without.
 *
 * The master refactor plan's headline success criterion is "at least 50% fewer model/tool turns on
 * forms and menus" (§24.2). The porting ledger then records that the turn-count gates "cannot
 * honestly be measured yet". Nothing between those two sentences counted turns per task, so every
 * later performance claim had no denominator. This module is that denominator.
 *
 * Deliberately narrow:
 *
 * - It COUNTS. It does not classify beyond what the tool trace actually proves. `surface` is derived
 *   from which tools ran, which is observable; the finer distinction a benchmark cares about
 *   ("form" vs "menu") is NOT derivable from a tool trace, so it is an optional `label` the fixture
 *   harness sets, never a guess made here. A fabricated classifier would put fake precision under
 *   the exact number the plan is trying to move.
 * - It holds no thresholds and asserts no budgets. `docs/RESEARCH_LEDGER.md` and two shipped
 *   regressions record what happens when a perf constant is written before it is measured: the test
 *   pins the wrong number and the system can no longer contradict it. Measure first; constants come
 *   later, from this data, in a separate change.
 * - It is additive and free when idle. `globalTelemetry` forwards to whichever task is live; with no
 *   live task the forward is a null check. Nothing in the loop changes behavior because of it.
 *
 * Disk is opt-in (`BIMAX_TASK_METRICS=1`), memory is always on — a session holds a handful of
 * numbers per task, and `/diagnostics` can then answer "how many turns did that take" without the
 * user having planned ahead to enable anything.
 */

import { stateDir } from '../utils/state.dir';
import * as fs from 'fs';
import * as path from 'path';
import { Logger } from '../utils/logger';

/**
 * What the task actually touched, derived from the tools that ran. Honest by construction: every
 * value here is a statement about the recorded trace, not an inference about intent.
 */
export type TaskSurface =
  | 'computer'   // desktop control only
  | 'browser'    // browser control only
  | 'code'       // file reads/edits only
  | 'shell'      // shell only
  | 'mixed'      // more than one of the above
  | 'none';      // answered with no tools at all

export interface TaskRun {
  id: string;
  startedAt: string;
  finishedAt: string;
  wallClockMs: number;
  /** Derived from the tool trace. See TaskSurface. */
  surface: TaskSurface;
  /**
   * Set by a benchmark fixture that knows what it is exercising ("form", "menu", "navigation").
   * Never inferred. Absent for organic sessions.
   */
  label?: string;
  /** Model round-trips. This is the number the ≥50% criterion is about. */
  turns: number;
  toolCalls: number;
  toolCallsByName: Record<string, number>;
  promptTokens: number;
  cacheReadTokens: number;
  cacheCreationTokens: number;
  /** Which computer-use backend served this task, when one did. */
  computerBackend?: 'native' | 'compatibility';
  /** True when the user interrupted, so a short turn count is not read as efficiency. */
  interrupted: boolean;
}

const COMPUTER_TOOLS = new Set(['ComputerTool', 'NativeComputerTool', 'NativeComputerTransactionTool']);
const BROWSER_TOOLS = new Set(['BrowserTool']);
const CODE_TOOLS = new Set([
  'ReadFileTool', 'WriteFileTool', 'EditFileTool', 'MultiEditTool', 'SymbolEditTool',
  'GrepTool', 'GlobTool', 'DeleteTool', 'CreateDirectoryTool', 'NotebookEditTool',
]);
const SHELL_TOOLS = new Set(['BashTool']);

/** Native tool names are registered dynamically, so match the family rather than an exact list. */
function isComputerTool(name: string): boolean {
  return COMPUTER_TOOLS.has(name) || name.startsWith('NativeComputer');
}

function deriveSurface(byName: Record<string, number>): TaskSurface {
  const names = Object.keys(byName);
  if (names.length === 0) return 'none';
  const touched = new Set<TaskSurface>();
  for (const name of names) {
    if (isComputerTool(name)) touched.add('computer');
    else if (BROWSER_TOOLS.has(name)) touched.add('browser');
    else if (CODE_TOOLS.has(name)) touched.add('code');
    else if (SHELL_TOOLS.has(name)) touched.add('shell');
  }
  if (touched.size === 0) return 'none';
  if (touched.size > 1) return 'mixed';
  return [...touched][0];
}

class LiveTask {
  readonly id = `task-${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 6)}`;
  readonly startedAtMs = Date.now();
  readonly startedAt = new Date().toISOString();
  turns = 0;
  toolCalls = 0;
  readonly toolCallsByName: Record<string, number> = {};
  promptTokens = 0;
  cacheReadTokens = 0;
  cacheCreationTokens = 0;
  label?: string;
  computerBackend?: 'native' | 'compatibility';
  interrupted = false;
}

/** Cap so a very long session cannot grow this unboundedly; the JSONL file keeps the full record. */
const MAX_RETAINED_RUNS = 200;

class TaskMetricsStore {
  private live: LiveTask | null = null;
  private runs: TaskRun[] = [];
  private warnedOnWriteFailure = false;

  /**
   * Begin a task. A nested call (a sub-agent running inside a task) is deliberately ignored rather
   * than replacing the outer task: the outer turn count is the one the criterion is about, and
   * silently rebinding it would under-count the parent.
   */
  begin(label?: string): void {
    if (this.live) return;
    this.live = new LiveTask();
    if (label) this.live.label = label;
  }

  /** True when a task is in flight — lets callers skip work entirely when nothing is recording. */
  get isRecording(): boolean {
    return this.live !== null;
  }

  recordTurn(): void {
    if (this.live) this.live.turns++;
  }

  recordToolCall(toolName: string): void {
    if (!this.live) return;
    this.live.toolCalls++;
    this.live.toolCallsByName[toolName] = (this.live.toolCallsByName[toolName] || 0) + 1;

    // Attribute the backend from the tool that actually ran, rather than asking the computer
    // runtime to report it. The native tools are only ever registered when `assessNativeCutover`
    // has already cleared the route, so their presence in the trace IS the evidence — and deriving
    // it here means no computer-use file needs an instrumentation edit.
    if (!this.live.computerBackend) {
      if (toolName.startsWith('NativeComputer')) this.live.computerBackend = 'native';
      else if (toolName === 'ComputerTool') this.live.computerBackend = 'compatibility';
    }
  }

  recordUsage(promptTokens: number, cacheRead: number, cacheCreation: number): void {
    if (!this.live) return;
    this.live.promptTokens += promptTokens;
    this.live.cacheReadTokens += cacheRead;
    this.live.cacheCreationTokens += cacheCreation;
  }

  /**
   * Override the derived backend. `recordToolCall` already infers it from the tool family, which
   * is correct today; this exists for the case where the runtime knows something the tool name
   * does not (a shadow run, say) and should not require a rewrite to express it.
   */
  recordComputerBackend(backend: 'native' | 'compatibility'): void {
    if (this.live) this.live.computerBackend = backend;
  }

  markInterrupted(): void {
    if (this.live) this.live.interrupted = true;
  }

  /** Set or correct the fixture label mid-task. No-op with no live task. */
  setLabel(label: string): void {
    if (this.live) this.live.label = label;
  }

  /** End the live task and retain it. Safe to call when nothing is live. */
  end(): TaskRun | undefined {
    const live = this.live;
    if (!live) return undefined;
    this.live = null;

    const run: TaskRun = {
      id: live.id,
      startedAt: live.startedAt,
      finishedAt: new Date().toISOString(),
      wallClockMs: Date.now() - live.startedAtMs,
      surface: deriveSurface(live.toolCallsByName),
      ...(live.label ? { label: live.label } : {}),
      turns: live.turns,
      toolCalls: live.toolCalls,
      toolCallsByName: { ...live.toolCallsByName },
      promptTokens: live.promptTokens,
      cacheReadTokens: live.cacheReadTokens,
      cacheCreationTokens: live.cacheCreationTokens,
      ...(live.computerBackend ? { computerBackend: live.computerBackend } : {}),
      interrupted: live.interrupted,
    };

    this.runs.push(run);
    if (this.runs.length > MAX_RETAINED_RUNS) this.runs.shift();
    this.appendToDisk(run);
    return run;
  }

  getRuns(): TaskRun[] {
    return [...this.runs];
  }

  /**
   * Turn/tool/token medians per surface. Medians rather than means because one interrupted or
   * pathological task should not move the number the criterion is judged on.
   */
  summarize(): Array<{
    surface: TaskSurface;
    label?: string;
    tasks: number;
    medianTurns: number;
    medianToolCalls: number;
    medianPromptTokens: number;
  }> {
    const groups = new Map<string, TaskRun[]>();
    for (const run of this.runs) {
      // Interrupted tasks are excluded: a task the user stopped early has an artificially low turn
      // count and would flatter any comparison it landed in.
      if (run.interrupted) continue;
      const key = `${run.surface}\u0000${run.label || ''}`;
      const bucket = groups.get(key);
      if (bucket) bucket.push(run); else groups.set(key, [run]);
    }

    const median = (values: number[]): number => {
      if (values.length === 0) return 0;
      const sorted = [...values].sort((a, b) => a - b);
      const mid = Math.floor(sorted.length / 2);
      return sorted.length % 2 === 0
        ? Math.round((sorted[mid - 1] + sorted[mid]) / 2)
        : sorted[mid];
    };

    return [...groups.entries()].map(([key, group]) => {
      const [surface, label] = key.split('\u0000');
      return {
        surface: surface as TaskSurface,
        ...(label ? { label } : {}),
        tasks: group.length,
        medianTurns: median(group.map(r => r.turns)),
        medianToolCalls: median(group.map(r => r.toolCalls)),
        medianPromptTokens: median(group.map(r => r.promptTokens)),
      };
    }).sort((a, b) => b.tasks - a.tasks);
  }

  reset(): void {
    this.live = null;
    this.runs = [];
  }

  /**
   * Append one JSON line. Opt-in, best-effort, and never allowed to fail a task: a metrics write
   * that throws into the agent loop would be a self-inflicted outage in the name of measurement.
   */
  private appendToDisk(run: TaskRun): void {
    if (process.env.BIMAX_TASK_METRICS !== '1') return;
    try {
      const dir = process.env.BIMAX_TASK_METRICS_DIR
        || path.join(stateDir('.breakglass'), 'metrics');
      fs.mkdirSync(dir, { recursive: true });
      fs.appendFileSync(path.join(dir, 'task-runs.jsonl'), JSON.stringify(run) + '\n');
    } catch (e: any) {
      // Warn once. A user who opted into metrics deserves to know the file is not being written,
      // but a broken path must not produce one warning per task for the rest of the session.
      if (!this.warnedOnWriteFailure) {
        this.warnedOnWriteFailure = true;
        Logger.warn(`[TaskMetrics] disk append disabled for this session: ${e?.message}`);
      }
    }
  }
}

export const taskMetrics = new TaskMetricsStore();

import { stateDir } from '../utils/state.dir';
import { randomBytes } from 'crypto';
import * as fs from 'fs';
import * as path from 'path';
import { Logger } from '../utils/logger';
import { redactSecretsDeep } from '../security/secret.scan';

/**
 * Trace layer — OpenTelemetry GenAI semantic-convention spans, zero external dependencies.
 *
 * Every agent turn produces a small span tree following the OTel GenAI conventions
 * (gen_ai.operation.name = invoke_agent | chat | execute_tool, gen_ai.usage.*, gen_ai.tool.name),
 * so any OTLP backend (Jaeger, Datadog, Honeycomb, Grafana) can ingest BiMax traces unchanged:
 *
 *   invoke_agent bimax                 ← one per AgentLoop.execute()
 *   ├── chat {model}                   ← one per LLM round (tokens, finish reason)
 *   │   ├── execute_tool {tool}        ← one per tool call (outcome, error class, claim confidence)
 *   │   └── execute_tool {tool}
 *   └── invoke_agent {subAgentType}    ← one per sub-agent spawn (lifetime, outcome)
 *
 * Exporters (both best-effort, never on the hot path's critical section):
 *   • JSONL  — every ended span appends one line to .bimax/traces/YYYY-MM-DD.jsonl (always on).
 *   • OTLP   — when OTEL_EXPORTER_OTLP_ENDPOINT (or BIMAX_OTLP_ENDPOINT) is set, batches are
 *              POSTed as OTLP/HTTP JSON to {endpoint}/v1/traces every 5s / 64 spans.
 *
 * BIMAX_TRACE=0 disables everything (no-op spans, zero I/O). BIMAX_TRACE_DIR overrides the
 * JSONL directory (tests point it at a tmpdir).
 */

export type AttrValue = string | number | boolean | string[];

export interface SpanContext {
  traceId: string;
  spanId: string;
}

export interface EndedSpan {
  traceId: string;
  spanId: string;
  parentSpanId?: string;
  name: string;
  startTimeUnixNano: string;
  endTimeUnixNano: string;
  attributes: Record<string, AttrValue>;
  status: 'ok' | 'error' | 'unset';
  statusMessage?: string;
}

export interface Span {
  readonly context: SpanContext;
  setAttribute(key: string, value: AttrValue): void;
  setAttributes(attrs: Record<string, AttrValue>): void;
  /** Idempotent — a second end() is ignored, so try/finally double-ends are safe. */
  end(status?: 'ok' | 'error', statusMessage?: string): void;
}

const NOOP_SPAN: Span = {
  context: { traceId: '', spanId: '' },
  setAttribute() { /* disabled */ },
  setAttributes() { /* disabled */ },
  end() { /* disabled */ },
};

function nowNano(): string {
  // Millisecond wall clock is plenty for agent-scale spans; OTLP wants nanoseconds as a string.
  return `${Date.now()}000000`;
}

function hexId(bytes: number): string {
  return randomBytes(bytes).toString('hex');
}

class LiveSpan implements Span {
  readonly context: SpanContext;
  private readonly startNano = nowNano();
  private ended = false;
  private attrs: Record<string, AttrValue>;

  constructor(
    private tracer: Tracer,
    private name: string,
    attrs: Record<string, AttrValue>,
    private parentSpanId?: string,
    traceId?: string
  ) {
    this.context = { traceId: traceId ?? hexId(16), spanId: hexId(8) };
    this.attrs = { ...attrs };
  }

  setAttribute(key: string, value: AttrValue): void {
    if (!this.ended) this.attrs[key] = value;
  }

  setAttributes(attrs: Record<string, AttrValue>): void {
    if (!this.ended) Object.assign(this.attrs, attrs);
  }

  end(status: 'ok' | 'error' = 'ok', statusMessage?: string): void {
    if (this.ended) return;
    this.ended = true;
    this.tracer.onSpanEnd({
      traceId: this.context.traceId,
      spanId: this.context.spanId,
      parentSpanId: this.parentSpanId,
      name: this.name,
      startTimeUnixNano: this.startNano,
      endTimeUnixNano: nowNano(),
      attributes: this.attrs,
      status,
      ...(statusMessage ? { statusMessage: statusMessage.slice(0, 500) } : {}),
    });
  }
}

/** OTLP/HTTP JSON encoding of a span batch (resourceSpans → scopeSpans → spans). */
export function toOtlpJson(spans: EndedSpan[], serviceName = 'bimax'): object {
  const attrList = (attrs: Record<string, AttrValue>) =>
    Object.entries(attrs).map(([key, v]) => ({
      key,
      value:
        Array.isArray(v) ? { arrayValue: { values: v.map(value => ({ stringValue: value })) } }
        : typeof v === 'number'
          ? Number.isInteger(v) ? { intValue: String(v) } : { doubleValue: v }
          : typeof v === 'boolean' ? { boolValue: v } : { stringValue: String(v) },
    }));
  const CODE = { ok: 'STATUS_CODE_OK', error: 'STATUS_CODE_ERROR', unset: 'STATUS_CODE_UNSET' } as const;
  return {
    resourceSpans: [{
      resource: { attributes: attrList({ 'service.name': serviceName }) },
      scopeSpans: [{
        scope: { name: 'bimax.trace', version: '1' },
        spans: spans.map(s => ({
          traceId: s.traceId,
          spanId: s.spanId,
          ...(s.parentSpanId ? { parentSpanId: s.parentSpanId } : {}),
          name: s.name,
          kind: 1, // SPAN_KIND_INTERNAL
          startTimeUnixNano: s.startTimeUnixNano,
          endTimeUnixNano: s.endTimeUnixNano,
          attributes: attrList(s.attributes),
          status: { code: CODE[s.status], ...(s.statusMessage ? { message: s.statusMessage } : {}) },
        })),
      }],
    }],
  };
}

const OTLP_BATCH_MAX = 64;
const OTLP_FLUSH_MS = 5000;

export class Tracer {
  private readonly enabled: boolean;
  private readonly otlpEndpoint: string | null;
  private otlpBuffer: EndedSpan[] = [];
  private otlpTimer: NodeJS.Timeout | null = null;
  private jsonlDirEnsured = false;
  private pendingWrites = new Set<Promise<void>>();
  private closed = false;
  // Recent-span ring for /trace + tests — capped so a day-long session can't grow it unbounded.
  private recent: EndedSpan[] = [];
  private static readonly RECENT_MAX = 200;

  constructor() {
    this.enabled = process.env.BIMAX_TRACE !== '0';
    this.otlpEndpoint =
      process.env.OTEL_EXPORTER_OTLP_ENDPOINT || process.env.BIMAX_OTLP_ENDPOINT || null;
  }

  isEnabled(): boolean { return this.enabled; }

  startSpan(name: string, attrs: Record<string, AttrValue> = {}, parent?: SpanContext): Span {
    if (!this.enabled) return NOOP_SPAN;
    return new LiveSpan(this, name, attrs, parent?.spanId, parent?.traceId);
  }

  /** Last N ended spans, newest last (drives /trace and tests). */
  recentSpans(): EndedSpan[] { return [...this.recent]; }

  private jsonlDir(): string {
    return process.env.BIMAX_TRACE_DIR || path.join(stateDir('.bimax'), 'traces');
  }

  /** Today's JSONL export file (for surfacing the path to the user). */
  exportPath(): string {
    const d = new Date();
    const day = `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`;
    return path.join(this.jsonlDir(), `${day}.jsonl`);
  }

  onSpanEnd(span: EndedSpan): void {
    if (this.closed) return;
    span = redactSecretsDeep(span);
    this.recent.push(span);
    if (this.recent.length > Tracer.RECENT_MAX) this.recent.splice(0, this.recent.length - Tracer.RECENT_MAX);

    // JSONL exporter — async append, best-effort. One small line per span; agent-scale span
    // rates (a handful per turn) make this negligible I/O.
    try {
      const dir = this.jsonlDir();
      if (!this.jsonlDirEnsured) {
        fs.mkdirSync(dir, { recursive: true });
        this.jsonlDirEnsured = true;
      }
      const write = fs.promises.appendFile(this.exportPath(), JSON.stringify(span) + '\n')
        .catch(() => undefined);
      this.pendingWrites.add(write);
      void write.then(() => this.pendingWrites.delete(write));
    } catch { /* tracing must never break the agent */ }

    // OTLP exporter — buffered; flushed on size or timer.
    if (this.otlpEndpoint) {
      this.otlpBuffer.push(span);
      if (this.otlpBuffer.length >= OTLP_BATCH_MAX) {
        void this.flushOtlp();
      } else if (!this.otlpTimer) {
        this.otlpTimer = setTimeout(() => void this.flushOtlp(), OTLP_FLUSH_MS);
        this.otlpTimer.unref?.();
      }
    }
  }

  async flushOtlp(): Promise<void> {
    if (this.otlpTimer) { clearTimeout(this.otlpTimer); this.otlpTimer = null; }
    if (!this.otlpEndpoint || this.otlpBuffer.length === 0) return;
    const batch = this.otlpBuffer;
    this.otlpBuffer = [];
    try {
      const url = this.otlpEndpoint.replace(/\/$/, '') + '/v1/traces';
      await fetch(url, {
        method: 'POST',
        headers: { 'content-type': 'application/json' },
        body: JSON.stringify(toOtlpJson(batch)),
        signal: AbortSignal.timeout(3000),
      });
    } catch (e: any) {
      // Drop the batch — the JSONL file still has every span, so nothing is lost locally.
      Logger.warn(`[Trace] OTLP export failed (${e?.message}); spans remain in ${this.exportPath()}`);
    }
  }

  /** Stop accepting spans and drain local/remote exporters for a clean process or test teardown. */
  async shutdown(): Promise<void> {
    if (this.closed) {
      await Promise.allSettled([...this.pendingWrites]);
      return;
    }
    this.closed = true;
    if (this.otlpTimer) { clearTimeout(this.otlpTimer); this.otlpTimer = null; }
    await Promise.allSettled([...this.pendingWrites]);
    await this.flushOtlp();
  }
}

let _tracer: Tracer | null = null;

/** Process-wide tracer. Lazy so env overrides set in tests (BIMAX_TRACE_DIR) are honored. */
export function getTracer(): Tracer {
  if (!_tracer) _tracer = new Tracer();
  return _tracer;
}

/** Flush and drop the singleton so the next getTracer() re-reads the environment. */
export async function resetTracerForTests(): Promise<void> {
  const previous = _tracer;
  _tracer = null;
  await previous?.shutdown();
}

/** Flush the existing singleton without creating one solely for shutdown. */
export async function shutdownTracer(): Promise<void> { await _tracer?.shutdown(); }

import { BaseAdapter } from './base.adapter';
import { CommandQueue } from './queue';
import { Logger } from '../utils';

export class TerminalMultiplexer {
  private sessions: Map<string, BaseAdapter> = new Map();
  private queues: Map<string, CommandQueue> = new Map();

  constructor(private maxPoolSize: number = 3) {}

  /**
   * Registers a new adapter session into the multiplexer.
   */
  async registerSession(adapter: BaseAdapter): Promise<string> {
    await adapter.spawnSession();
    this.sessions.set(adapter.getId(), adapter);
    if (!this.queues.has(adapter.getToolName())) {
      this.queues.set(adapter.getToolName(), new CommandQueue());
    }
    return adapter.getId();
  }

  /**
   * Gets an available session for a specific tool.
   */
  private getAvailableSession(toolName: string): BaseAdapter | undefined {
    for (const [id, adapter] of this.sessions.entries()) {
      if (adapter.getToolName() === toolName && !adapter.isSessionBusy()) {
        return adapter;
      }
    }
    return undefined;
  }

  /**
   * Routes a command. Buffers to queue if busy.
   */
  async routeCommand(toolName: string, command: string): Promise<string> {
    if (!this.queues.has(toolName)) {
      this.queues.set(toolName, new CommandQueue());
    }

    const session = this.getAvailableSession(toolName);
    const queue = this.queues.get(toolName)!;

    if (!session) {
      // Auto-scale condition hit. Place in queue to await a free session.
      return queue.enqueue(command);
    }

    // Execute immediately
    try {
      const output = await session.execute(command);
      return output;
    } finally {
      // Process queue now that we are free
      this.processQueue(toolName, session);
    }
  }

  private async processQueue(toolName: string, session: BaseAdapter) {
    const queue = this.queues.get(toolName);
    if (!queue || queue.isEmpty() || session.isSessionBusy()) return;

    const item = queue.dequeue();
    if (item) {
      Logger.info(`[Multiplexer] Dequeued task for ${toolName}. Assigning to ${session.getId()}...`);
      try {
        const output = await session.execute(item.command);
        item.resolve(output);
      } catch (err) {
        item.reject(err);
      }
      // Recursive call to drain queue
      this.processQueue(toolName, session);
    }
  }

  /**
   * Closes all active sessions.
   */
  async shutdownAll(): Promise<void> {
    for (const [id, adapter] of this.sessions.entries()) {
      await adapter.killSession();
    }
    this.sessions.clear();
    Logger.info('[Multiplexer] All sessions shut down cleanly.');
  }
}

import { Logger } from '../utils';

interface QueueItem {
  command: string;
  resolve: (value: string) => void;
  reject: (reason?: any) => void;
  timeoutHandle: NodeJS.Timeout;
}

export class CommandQueue {
  private queue: QueueItem[] = [];

  enqueue(command: string): Promise<string> {
    return new Promise((resolve, reject) => {
      Logger.warn(`[CommandQueue] Terminals busy. Pushing task to queue. (Queue depth: ${this.queue.length + 1})`);

      const wrappedResolve = (value: string) => {
        clearTimeout(timeout);
        resolve(value);
      };

      const wrappedReject = (reason?: any) => {
        clearTimeout(timeout);
        reject(reason);
      };

      const timeout = setTimeout(() => {
        // Remove the timed-out item from the queue. NOTE: the stored item's
        // `resolve` is `wrappedResolve` (not the raw `resolve`), so we must
        // compare against `wrappedResolve` — comparing against `resolve` never
        // matched, leaving stale entries in the queue that could be dequeued
        // and silently drop a command's result after it had already rejected.
        this.queue = this.queue.filter(q => q.resolve !== wrappedResolve);
        wrappedReject(new Error("CommandQueue timeout: Session never became available after 60s"));
      }, 60000);

      this.queue.push({ command, resolve: wrappedResolve, reject: wrappedReject, timeoutHandle: timeout });
    });
  }

  dequeue(): QueueItem | undefined {
    const item = this.queue.shift();
    if (item) {
      clearTimeout(item.timeoutHandle);
    }
    return item;
  }

  isEmpty(): boolean {
    return this.queue.length === 0;
  }
}

import { execFileSync } from 'child_process';
import { isGitRepo } from '../engine/git';
import { Logger } from '../utils/logger';

// B1 (opt-in) — auto-commit each successful edit, Aider-style. Off by default; toggled via
// `/git autocommit on|off` or Settings → Git auto-commit. Implemented as a PostToolUse hook (A2)
// registered by startHeadless (the app's engine), so sub-agent workers never auto-commit. A throwing commit is swallowed by
// the hook runner, so a non-repo / empty-diff never breaks the turn.

let enabled = false;
export function setGitAutoCommitEnabled(v: boolean): void { enabled = v; }
export function isGitAutoCommitEnabled(): boolean { return enabled; }

const EDIT_TOOLS = ['EditFileTool', 'WriteFileTool', 'MultiEditTool'];
export const GIT_AUTOCOMMIT_TOOLS = EDIT_TOOLS;

/** Every file the edit touched, as the tool was asked to write it. Empty when the arguments name none. */
function editedPaths(args: any): string[] {
  if (typeof args?.path === 'string' && args.path) return [args.path];
  if (Array.isArray(args?.edits)) {
    const paths: string[] = args.edits.map((edit: any) => edit?.path).filter((p: unknown): p is string => typeof p === 'string' && !!p);
    return [...new Set(paths)];
  }
  return [];
}

/** PostToolUse handler: commit the just-made edit when auto-commit is enabled. */
export async function gitAutoCommitHook(toolName: string, args: any, result: any, context: any): Promise<void> {
  if (!enabled) return;
  // Skip when the edit didn't actually apply (rejected/cancelled/error result strings).
  if (typeof result === 'string' && /\b(rejected|cancelled|Error|blocked)\b/i.test(result)) return;

  const cwd = context?.cwd || process.cwd();
  if (!isGitRepo(cwd)) return; // not a git repo

  // Only the files this edit wrote. This was `git add -A`, which swept the user's own uncommitted work —
  // anything they were halfway through — into a "bimax auto" commit. It never ran in the app (the hook
  // was not registered after the Ink terminal was retired), so it is narrowed before it ever does.
  const paths = editedPaths(args);
  if (paths.length === 0) return;
  try {
    execFileSync('git', ['add', '--', ...paths], { cwd });
    execFileSync('git', ['commit', '-m', `bimax auto: ${toolName} ${paths.join(', ')}`, '--', ...paths], { cwd, stdio: 'ignore' });
    Logger.info(`[GitAutoCommit] committed after ${toolName}`);
  } catch {
    // Nothing staged / empty diff / hook conflict — non-fatal.
  }
}

import * as fs from 'fs';
import * as path from 'path';
import { execFile } from 'child_process';
import { promisify } from 'util';
import { registerPreHook, registerPostHook } from './hooks';
import { Logger } from '../utils/logger';

const execFileAsync = promisify(execFile);

// A2 — load shell-command hooks from .bimax/hooks.json. A PreToolUse command that exits
// non-zero BLOCKS the tool (its stderr becomes the reason); PostToolUse commands run for
// their side effects (e.g. lint/notify). The tool name + JSON args are passed via env vars
// (BIMAX_TOOL_NAME / BIMAX_TOOL_ARGS) so scripts can branch on them.

interface HookSpec { match: string | string[]; command: string; }
interface HooksConfig { preToolUse?: HookSpec[]; postToolUse?: HookSpec[]; }

function runShell(command: string, toolName: string, args: any) {
  let argsJson = '{}';
  try { argsJson = JSON.stringify(args); } catch { /* circular/oversized args → empty */ }
  return execFileAsync('/bin/sh', ['-c', command], {
    env: { ...process.env, BIMAX_TOOL_NAME: toolName, BIMAX_TOOL_ARGS: argsJson },
    timeout: 15000,
    maxBuffer: 1024 * 1024,
  });
}

/**
 * Register hooks declared in `<dir>/.bimax/hooks.json`. Returns the number registered.
 * Best-effort: a missing/invalid file registers nothing.
 */
export function loadHooksConfig(dir: string = process.cwd()): number {
  const file = path.join(dir, '.bimax', 'hooks.json');
  let cfg: HooksConfig;
  try {
    cfg = JSON.parse(fs.readFileSync(file, 'utf8'));
  } catch {
    return 0;
  }

  let n = 0;
  for (const h of cfg.preToolUse || []) {
    if (!h.command) continue;
    registerPreHook(h.match || '*', async (toolName, args) => {
      try {
        await runShell(h.command, toolName, args);
      } catch (e: any) {
        const reason = (e.stderr || e.message || 'hook command failed').toString().trim();
        return { block: true, reason };
      }
      return undefined; // command succeeded — don't block
    });
    n++;
  }
  for (const h of cfg.postToolUse || []) {
    if (!h.command) continue;
    registerPostHook(h.match || '*', async (toolName, args) => {
      try {
        await runShell(h.command, toolName, args);
      } catch (e: any) {
        Logger.warn(`[Hooks] PostToolUse command failed for ${toolName}: ${e.message}`);
      }
    });
    n++;
  }
  return n;
}

import { minimatch } from 'minimatch';
import { Logger } from '../utils/logger';

// A2 — Tool hooks. Run user/built-in handlers around every tool call, at the single
// chokepoint (buildTool). A PreToolUse hook may block the call (surfaced like a governor
// veto); a PostToolUse hook reacts to the result (e.g. the B2 verify loop). Hooks are
// opt-in (nothing runs unless registered/loaded) and always non-fatal — a throwing hook is
// logged and skipped, never breaking the agent.

export interface PreHookResult {
  block?: boolean;   // true → the tool does not run
  reason?: string;   // shown to the model as the blocked tool result
}

export type PreHook = (toolName: string, args: any, context: any) => Promise<PreHookResult | void> | PreHookResult | void;

export interface PostHookResult {
  appendToResult?: string; // appended to the tool's result string (e.g. verify diagnostics)
}
export type PostHook = (toolName: string, args: any, result: any, context: any) => Promise<PostHookResult | void> | PostHookResult | void;

interface PreReg { match: (name: string) => boolean; handler: PreHook; }
interface PostReg { match: (name: string) => boolean; handler: PostHook; }

const preHooks: PreReg[] = [];
const postHooks: PostReg[] = [];

/** Build a tool-name matcher from a glob string, a list of globs, or `'*'` (all tools). */
function toMatcher(pattern: string | string[]): (name: string) => boolean {
  const pats = Array.isArray(pattern) ? pattern : [pattern];
  return (name: string) => pats.some(p => p === '*' || p === name || minimatch(name, p));
}

/** Register a PreToolUse hook. Returns an unregister function. */
export function registerPreHook(pattern: string | string[], handler: PreHook): () => void {
  const reg: PreReg = { match: toMatcher(pattern), handler };
  preHooks.push(reg);
  return () => { const i = preHooks.indexOf(reg); if (i >= 0) preHooks.splice(i, 1); };
}

/** Register a PostToolUse hook. Returns an unregister function. */
export function registerPostHook(pattern: string | string[], handler: PostHook): () => void {
  const reg: PostReg = { match: toMatcher(pattern), handler };
  postHooks.push(reg);
  return () => { const i = postHooks.indexOf(reg); if (i >= 0) postHooks.splice(i, 1); };
}

/** Remove all hooks (used by tests and re-init). */
export function clearHooks(): void {
  preHooks.length = 0;
  postHooks.length = 0;
}

export function hookCounts(): { pre: number; post: number } {
  return { pre: preHooks.length, post: postHooks.length };
}

/**
 * Run matching PreToolUse hooks. Returns the first blocking result, or void to proceed.
 * Hook errors are logged and treated as non-blocking.
 */
export async function runPreHooks(toolName: string, args: any, context: any): Promise<PreHookResult | void> {
  for (const h of preHooks) {
    if (!h.match(toolName)) continue;
    try {
      const r = await h.handler(toolName, args, context);
      if (r && r.block) return r;
    } catch (e: any) {
      Logger.warn(`[Hooks] PreToolUse hook for ${toolName} errored (ignored): ${e.message}`);
    }
  }
  return undefined; // no hook blocked
}

/**
 * Run matching PostToolUse hooks. Returns any text the hooks asked to append to the tool
 * result (joined), or '' if none. Errors are logged and swallowed (never break the turn).
 */
export async function runPostHooks(toolName: string, args: any, result: any, context: any): Promise<string> {
  const appended: string[] = [];
  for (const h of postHooks) {
    if (!h.match(toolName)) continue;
    try {
      const r = await h.handler(toolName, args, result, context);
      if (r && r.appendToResult) appended.push(r.appendToResult);
    } catch (e: any) {
      Logger.warn(`[Hooks] PostToolUse hook for ${toolName} errored (ignored): ${e.message}`);
    }
  }
  return appended.join('\n\n');
}

import { IGovernor } from '../../core/interfaces';
import { buildTool } from '../tool.factory';
import { engineEvents } from '../../engine/events';
import { LlmAdapter } from '../../core/llm.adapter';
import { getConfig } from '../../engine/config';
import { detectDegenerateAsk } from '../ask-guard';

export const createAskUserTool = (governor: IGovernor, llmAdapter: LlmAdapter) => buildTool({
  name: 'AskUserTool',
  description: `Pauses your execution and pings the user with an interactive multiple-choice prompt.

Use this tool when:
- You are about to create a file or folder but encounter a collision (e.g. "File exists" error) and need to ask the user to Overwrite, Cancel, or advise.
- You are asked to operate in a codebase on a directory that does not exist, and you want to explicitly ask if you should create it or abort.
- You hit any major ambiguity that requires human clarification.

The execution will pause until the user selects one of the provided options. The returned result will be the text of the exact option the user selected.`,
  isDestructive: false,
  schema: {
    type: 'object',
    properties: {
      question: { type: 'string', description: 'The question or statement to show to the user (e.g. "The folder \'math\' already exists. What should I do?")' },
      options: { 
        type: 'array', 
        items: { type: 'string' },
        description: 'An array of up to 4 options (e.g. ["Overwrite", "Cancel", "Tell me what else to do"])' 
      },
      isMultiSelect: {
        type: 'boolean',
        description: 'Set to true if the user is allowed to select multiple options. Defaults to false.'
      }
    },
    required: ['question', 'options']
  },
  execute: async (args: { question: string, options: string[], isMultiSelect?: boolean }, context?: any) => {
    // A night shift (FL5): nobody will answer until morning, so a question would stall the whole night.
    if (process.env.BIMAX_UNATTENDED === '1') {
      return `Nobody is here to answer until the morning. Choose the safer option yourself, write the question and your choice in NIGHT-QUESTIONS.md, commit it, and carry on with work that does not depend on it. Question: ${String(args.question ?? '').slice(0, 300)}`;
    }
    // Refuse degenerate / gratuitous prompts (greetings, identity, single-option "decisions").
    // The model must answer the user directly instead of blocking the session on a fake choice.
    const degenerate = detectDegenerateAsk(args.question, args.options);
    if (degenerate) {
      engineEvents.emit('log', { level: 'info', text: `[AskUserTool] Refused degenerate prompt: ${degenerate}` } as any);
      return `AskUserTool was not used: ${degenerate}. This input does not need a user decision — ` +
        `answer the user directly in plain text now (greetings, "who are you", explanations, or anything ` +
        `you can resolve yourself). Only use AskUserTool when you are genuinely blocked on a choice the ` +
        `user must make, with a clear question and at least 2 distinct options.`;
    }

    const config = getConfig();
    if (config.autoAgentDecisions) {
      engineEvents.emit('log', { level: 'info', text: `[AskUserTool] Auto-Agent-Decisions is ON. Delegating question to LLM Supervisor...` } as any);
      const prompt = `You are an AI acting as a human user in an automated workflow.
An AI agent has paused its execution to ask the human a question.
Question: ${args.question}
Options: ${args.options.join(', ')}

Your task is to select the most logical, safest, and productive option to keep the automated workflow moving smoothly.
Reply ONLY with the exact text of the option you choose. Do not provide any conversational text, explanations, or quotes.`;

      try {
        const response = await llmAdapter.chatCompletion([{ role: 'user', content: prompt }], undefined, { lite: true });
        engineEvents.emit('log', { level: 'info', text: `[AskUserTool] LLM Supervisor selected: ${response.trim()}` } as any);
        return `User selected: ${response.trim()}`;
      } catch (e: any) {
        engineEvents.emit('log', { level: 'error', text: `[AskUserTool] Auto-decision failed: ${e.message}. Falling back to human interaction.` } as any);
      }
    }

    return new Promise((resolve, reject) => {
      const signal: AbortSignal | undefined = context?.signal;
      const abort = () => reject(new Error('Question cancelled with this turn.'));
      if (signal?.aborted) { abort(); return; }
      signal?.addEventListener('abort', abort, { once: true });
      // Re-use the existing veto_prompt event architecture, which pops up an Ink PermissionDialog
      // The 4th argument (true) tells the frontend not to bypass this even if YOLO mode is on
      const safeOptions = Array.isArray(args.options) ? args.options : ['Continue', 'Cancel'];
      const safeQuestion = args.question || 'Action requires confirmation';

      engineEvents.emit('veto_prompt', safeQuestion, safeOptions, (answer: string) => {
        signal?.removeEventListener('abort', abort);
        if (!signal?.aborted) resolve(`User selected: ${answer}`);
      }, true, args.isMultiSelect);
    });
  }
}, governor);

import { exec, execFile } from 'child_process';
import { promisify } from 'util';
import * as os from 'os';
import { IGovernor } from '../../core/interfaces';
import { buildTool } from '../tool.factory';
import { sandboxArgv, sandboxBin, floorRoot, floorArgv, floorChildEnv, floorBlockedReason, sovereignShellBlockedReason } from '../../sandbox/exec.sandbox';
import { outcomeOk, classifiedError } from '../outcome';
import { guiAutomationRefusal } from '../gui.automation.guard';
import { isReadOnlyShellCommand } from '../shell.readonly';
import { planShellChange } from '../thread.changes';
import { binLookNote, moveToBin, movedToBinText } from '../thread.bin';
import { recordTrash } from '../thread.journal';

const execAsync = promisify(exec);
const execFileAsync = promisify(execFile);
const MAX_OUTPUT_CHARS = 50_000;

/**
 * A terminal escape sequence — colour, cursor moves, the lot. Matched with the ESC byte REQUIRED,
 * so it can never touch ordinary text containing brackets.
 */
// eslint-disable-next-line no-control-regex
const ANSI_ESCAPE = /\u001b(?:\[[0-9;?]*[ -/]*[@-~]|\][^\u0007\u001b]*(?:\u0007|\u001b\\)|[@-Z\\-_])/g;

/**
 * Ask the child not to colour its output.
 *
 * Nothing did this, so every `npm test`, `eslint`, `cargo`, `git -c color.ui=always` and friend
 * wrote raw SGR escapes straight into the tool result, and from there into the model's context.
 * Two costs, both real: the escapes are tokens that carry no meaning, and the model learns to
 * echo them back — which is what the literal `[0m`/`[1m` fragments in Bimax's own replies were.
 * The ESC byte is invisible in a DOM text node, so `\u001b[1m` renders as the bare letters `[1m`.
 *
 * `NO_COLOR`, `FORCE_COLOR=0` and `CLICOLOR=0` are the conventions tools actually honour, and they
 * also override a `FORCE_COLOR` the parent process had set — which is the common way colour got
 * in, since a piped stdout is not a TTY and most tools are already quiet without one.
 *
 * `TERM` is deliberately left alone: `TERM=dumb` would add almost nothing here and breaks build
 * scripts that call `tput`. stripAnsi() below is the backstop for a tool that ignores all three.
 */
function colourlessEnv(base: NodeJS.ProcessEnv): NodeJS.ProcessEnv {
  return { ...base, NO_COLOR: '1', FORCE_COLOR: '0', CLICOLOR: '0', CLICOLOR_FORCE: '0' };
}

/** Remove terminal escapes from output destined for the model, which has no terminal to render them. */
function stripAnsi(text: string): string {
  return text.includes('\u001b') ? text.replace(ANSI_ESCAPE, '') : text;
}

export const createBashTool = (governor: IGovernor) => buildTool({
  name: 'BashTool',
  description: `Executes a bash command and returns stdout/stderr.

Runs in the agent's current working directory (changeable via ChangeDirectoryTool).
Prefer dedicated tools over BashTool: ReadFileTool for reading, WriteFileTool for writing.
Reserve BashTool for actual shell operations (installs, builds, git, processes, deleting files or folders with rm, moving files with mv).

# Directory Creation & Verification Rules:
- When asked to create a directory, ALWAYS use \`mkdir -p\`. 
- If \`mkdir\` fails with "File exists", it means a FILE (not a folder) with that name already exists. DO NOT tell the user "the folder already exists". Instead, use \`ls -la\` to inspect the conflicting file, and ask the user if they want to delete/rename it.
- Before creating a deeply nested directory (e.g., \`mkdir -p foo/bar/baz\`), use \`ls\` on the parent to verify you are in the correct location.

- Chain dependent commands with \`&&\`. Each call is a fresh subshell.
- NEVER run interactive commands — they produce no output and hang until the timeout kills them: no \`git rebase -i\`, no editors (vim/nano), no commands that prompt for input. Use non-interactive flags (\`-y\`, \`--no-edit\`, \`CI=1\`).
- LONG-RUNNING work (a build, a full test suite, a dev server, anything over ~30s): set \`background: true\`. The command becomes a tracked background task — you get a task id immediately, the user sees it in the task panel, and its output/result arrive via the task system (inspect with the TasksTool or /tasks). Do NOT run watch modes or servers in the foreground.
- Output is truncated after 50,000 characters — pipe noisy commands through \`tail\`/\`head\`/\`grep\` to keep the part you need.
- Use \`~\` for home directory — it will be resolved.
- Quote paths with spaces using double quotes.
- Git: never force-push or reset --hard unless explicitly asked; never commit unless asked.`,
  isDestructive: true,
  /**
   * Per-call, not per-tool. BashTool as a whole is a barrier, but a turn of `git status`, `rg TODO`,
   * `wc -l` is three read-only lookups with no reason to serialize. Only a strictly read-only
   * FOREGROUND command overlaps; `isReadOnlyShellCommand` fails closed on every ambiguity, and the
   * Governor, sandbox and task guard still run for the call either way.
   */
  isConcurrencySafe: (args: any) => args?.background !== true && isReadOnlyShellCommand(args?.command),
  schema: {
    type: 'object',
    properties: {
      command: { type: 'string', description: 'The bash command to execute' },
      timeout: { type: 'number', description: 'Timeout in milliseconds (default: 30000)' },
      background: { type: 'boolean', description: 'Run as a tracked background task (long builds, test suites, servers). Returns a task id immediately.' }
    },
    required: ['command']
  },
  // Shell is not a Computer Use channel: refused before any approval card, so nobody is asked to allow a command that will
  // be refused anyway (measured 2026-10-02: the person allowed `osascript … tell application "Music"` on its card).
  refuseBeforeApproval: (args: { command: string }) => {
    const verdict = guiAutomationRefusal(args?.command);
    return verdict.refused ? `Command blocked: ${verdict.reason}` : undefined;
  },
  execute: async (args: { command: string, timeout?: number, background?: boolean }, context?: any) => {
    // Coerce the model-supplied timeout. LLMs frequently emit it as a string,
    // a float, or an out-of-range value, which makes Node's exec throw
    // ERR_OUT_OF_RANGE ("timeout ... must be an unsigned integer") and derails
    // the whole task. Clamp to a finite integer in [0, 600000]ms.
    // Shell is not a Computer Use channel. Refused BEFORE the sandbox, the governor, or any
    // execution, so a GUI-automation command never reaches the window server by this path.
    const guiRefusal = guiAutomationRefusal(args.command);
    if (guiRefusal.refused) {
      throw classifiedError(`Command blocked: ${guiRefusal.reason}`, 'permission', 'blocked');
    }
    // In a desktop thread a plain `rm`/`rmdir` sends the items to the Bin through the Bimax app instead of deleting
    // them, and records where each one went so the thread can undo it (thread.changes.ts, thread.journal.ts).
    if (process.env.BIMAX_THREAD_ROOT) {
      const change = planShellChange(args.command, context?.cwd || process.cwd());
      if (change?.kind === 'trash') {
        const { moved, error } = await moveToBin(change.trash, context?.signal);
        await recordTrash(change.title, 'BashTool', moved);
        if (error) throw classifiedError(`Moved ${moved.length} of ${change.trash.length} item(s) to the Bin, then stopped: ${error}`, 'external');
        return outcomeOk(movedToBinText(moved.map((m) => m.path)), { exitCode: 0 });
      }
    }
    // A command that looks inside the Bin gets a note in every outcome: Bimax cannot read the Bin, and what the
    // command printed must not be taken as its contents (thread.bin.ts).
    const binNote = binLookNote(args.command);
    const rawTimeout = Number(args.timeout);
    const timeoutMs = Number.isFinite(rawTimeout)
      ? Math.min(Math.max(0, Math.floor(rawTimeout)), 600_000)
      : 30_000;
    try {
      const currentCwd = context?.cwd || process.cwd();
      const cmd = args.command.replace(/^~(?=\/|$)/, os.homedir());
      // Sandbox FLOOR (autonomous episodes): mandatory — no toggle lowers it. If the floor
      // can't be enforced on this platform, Bash is blocked rather than run with ambient
      // authority (BIMAX_SANDBOX_FLOOR_SOFT=1 is the explicit opt-out).
      const blocked = floorBlockedReason();
      if (blocked) throw classifiedError(`Command blocked: ${blocked}`, 'permission', 'blocked');
      // Sovereign mode: a subprocess is outside the in-process egress perimeter, so the kernel has
      // to deny it the network. Where the OS cannot, the shell is refused rather than run with
      // isolation we cannot demonstrate.
      const sovereignBlocked = sovereignShellBlockedReason();
      if (sovereignBlocked) throw classifiedError(`Command blocked: ${sovereignBlocked}`, 'permission', 'blocked');
      // Background promotion: long-running work becomes a tracked task workspace instead of a
      // blocking foreground exec (task registry + execution ledger; honest pause via SIGSTOP).
      // startShellTask applies the same OS isolation, including direct calls and retries.
      if (args.background) {
        const { startShellTask } = require('../../core/shell.tasks');
        const { task, summary } = startShellTask(cmd, { cwd: currentCwd,
          timeoutMs: args.timeout === undefined ? 0 : timeoutMs, learningOrigin: context?.learningTrace });
        if (task.state === 'failed-resumable') throw classifiedError(summary, 'external');
        return outcomeOk(JSON.stringify({ taskId: task.id, state: task.state, note: summary }, null, 2), { exitCode: 0 });
      }
      const flArgv = floorArgv(cmd);
      // When sandboxing is on (B3), run the command under the OS sandbox binary (sandbox-exec on
      // macOS, bwrap on Linux) via execFile so the profile + the command pass as discrete argv (no
      // shell re-quoting). Otherwise run it through the shell exactly as before.
      const sbArgv = flArgv ?? sandboxArgv(cmd, currentCwd);
      const sbBin = sbArgv ? sandboxBin() : null;
      // signal: when the user hits esc mid-turn, the agent loop aborts it and Node kills this child
      // process immediately instead of waiting out the command / its timeout.
      const execOpts = {
        cwd: currentCwd, timeout: timeoutMs, maxBuffer: 10 * 1024 * 1024,
        signal: context?.signal as AbortSignal | undefined,
        // Floored episodes (even soft-bypassed ones) never expose the parent env to children.
        env: colourlessEnv((floorRoot() || process.env.BIMAX_THREAD_ROOT) ? floorChildEnv() : process.env),
      };
      const { stdout, stderr } = sbArgv && sbBin
        ? await execFileAsync(sbBin, sbArgv, execOpts)
        : await execAsync(cmd, execOpts);
      const out = stripAnsi(stdout).trim();
      const err = stripAnsi(stderr).trim();
      // Workspace: a successful `git clone` makes the new repo an ask-once registration
      // candidate (multi-repo awareness, workspace.manager.ts). Best-effort, never blocks.
      if (/git\s+clone\s/.test(cmd)) {
        try { require('../../core/workspace.manager').tryGetWorkspace()?.noticeCommand(cmd, currentCwd); } catch { /* best-effort */ }
      }
      const payload = {
        stdout: out.length > MAX_OUTPUT_CHARS ? out.slice(0, MAX_OUTPUT_CHARS) + '\n...[truncated]' : out,
        stderr: err.length > MAX_OUTPUT_CHARS ? err.slice(0, MAX_OUTPUT_CHARS) + '\n...[truncated]' : err,
        ...(binNote ? { note: binNote } : {}),
      };
      // Typed outcome: text matches the old JSON.stringify wire format exactly; exitCode 0 is
      // ground truth for the epistemic ledger's green evidence flag.
      return outcomeOk(JSON.stringify(payload, null, 2), { exitCode: 0 });
    } catch (e: any) {
      // Interrupted by esc (signal abort) — also sets e.killed, so check it BEFORE the timeout case.
      if (e?.name === 'AbortError' || e?.code === 'ABORT_ERR' || context?.signal?.aborted) {
        throw classifiedError(`Command interrupted: ${args.command}`, 'interrupted');
      }
      if (e.killed) {
        throw classifiedError(`Command timed out after ${timeoutMs}ms: ${args.command}${binNote ? `\n${binNote}` : ''}`, 'timeout');
      }
      // A NON-ZERO exit is normal and useful for many commands — `tsc` with type errors, a failing
      // `npm test`, `grep` with no match. Node's exec rejects in that case but attaches the captured
      // output (e.stdout / e.stderr) and exit code. Return THAT instead of discarding it as a bare
      // "Command failed", so the model sees the actual errors and can act — no more redirecting to a
      // temp file just to read tsc/test output.
      const out = stripAnsi(String(e.stdout || '')).trim();
      const err = stripAnsi(String(e.stderr || '')).trim();
      if (out || err) {
        const tag = e.code != null ? `\n[command exited with code ${e.code}]` : '';
        const payload = {
          stdout: out.length > MAX_OUTPUT_CHARS ? out.slice(0, MAX_OUTPUT_CHARS) + '\n...[truncated]' : out,
          stderr: ((err + tag).length > MAX_OUTPUT_CHARS ? (err + tag).slice(0, MAX_OUTPUT_CHARS) + '\n...[truncated]' : (err + tag)),
          ...(binNote ? { note: binNote } : {}),
        };
        // Still status 'ok' — a failing tsc/test run is a useful result, not a tool failure —
        // but the non-zero exitCode makes the ledger's red evidence flag exact.
        return outcomeOk(JSON.stringify(payload, null, 2), { exitCode: typeof e.code === 'number' ? e.code : 1 });
      }
      const wrapped: any = classifiedError(`Bash execution failed: ${e.message}${binNote ? `\n${binNote}` : ''}`, 'external');
      wrapped.cause = e;
      throw wrapped;
    }
  }
}, governor);

import { IGovernor } from '../../core/interfaces';
import { buildTool } from '../tool.factory';
import { engineEvents } from '../../engine/events';
import * as fs from 'fs';
import * as path from 'path';
import * as os from 'os';

const CODEBASE_MARKERS = ['.git', 'package.json', 'Cargo.toml', 'go.mod', 'pyproject.toml', 'Makefile'];

export const createCdTool = (governor: IGovernor) => buildTool({
  name: 'ChangeDirectoryTool',
  description: `Changes the working directory for this session. Use ONLY when the user asks to move to a different location. You already start in the project directory (see CWD in the environment section) and every other tool takes relative or absolute paths — never cd into the current directory, into "." or into a subdirectory just to work there.`,
  isDestructive: false,
  isConcurrencySafe: false,
  schema: {
    type: 'object',
    properties: {
      targetPath: { type: 'string', description: 'Path to cd into (supports ~)' }
    },
    required: ['targetPath']
  },
  execute: async (args: { targetPath: string }, context?: any) => {
    const currentCwd = context?.cwd || process.cwd();
    const resolvedPath = args.targetPath.replace(/^~(?=\/|$)/, os.homedir());
    const absolutePath = path.resolve(currentCwd, resolvedPath);

    if (!fs.existsSync(absolutePath)) {
      throw new Error(`Directory does not exist: ${absolutePath}`);
    }

    const stats = fs.statSync(absolutePath);
    if (!stats.isDirectory()) {
      throw new Error(`Path is not a directory: ${absolutePath}`);
    }

    // Already there: answer and stop. The engine chdir()s to the user's project at boot (BIMAX_CWD),
    // so a model that opens a task with `cd <the project>` was burning a turn AND re-emitting
    // cwd_changed, which makes the front-end reload the project graph / map panel for no change.
    if (absolutePath === path.resolve(currentCwd)) {
      return `Already in ${absolutePath} — no change. Use paths directly; you do not need to cd first.`;
    }

    // Isolate state by mutating the agent context, not the global process
    if (context && typeof context.cwd !== 'undefined') {
      context.cwd = absolutePath;
    } else {
      process.chdir(absolutePath); // Fallback if no context provided
    }

    // Tell the UI the project changed so it reloads the per-project graph / map panel — otherwise
    // the panel keeps showing whatever was indexed at launch (e.g. a stale home-dir map).
    engineEvents.emit('cwd_changed', absolutePath);

    // Return a single concise line (not a 23-line JSON blob) — enough for the model to know where it
    // landed and roughly what's there; it can `ls` for the full listing if it actually needs it.
    const all = fs.readdirSync(absolutePath).filter(n => n !== '.DS_Store');
    const isCodebase = CODEBASE_MARKERS.some(m => fs.existsSync(path.join(absolutePath, m)));
    const preview = all.slice(0, 12).join(', ');
    const more = all.length > 12 ? ` …(+${all.length - 12} more)` : '';
    return `Now in ${absolutePath}${isCodebase ? ' (codebase)' : ''}. Contains: ${preview}${more}`;
  }
}, governor);

import * as fs from 'fs/promises';
import * as path from 'path';
import { resolvePath, countOccurrences, workspaceWriteBlock } from '../path.util';
import { IGovernor } from '../../core/interfaces';
import { buildTool } from '../tool.factory';
import { backupFile, unifiedDiff, compactDiff, capDiff } from '../../engine/fileEditor';
import { checkEditSyntax, shieldEdit } from '../syntax.check';
import { requestDiffApproval } from '../../engine/diffApproval';
import { checkBlastRadius } from '../../engine/blastGate';
import { detectCorruptWrite } from '../write-guard';
import { fileStateCache } from '../../memory/file-state-cache';
import { globalTransactionManager } from '../../core/transaction.manager';
import { outcomeOk, outcomeError, outcomeRejected } from '../outcome';

interface FallbackMatch {
  resolvedOld: string; // the actual text in the file that will be replaced
  method: string;      // which of the 9 steps succeeded (shown in diff-approval + result)
}

/**
 * 9-step fuzzy edit fallback chain (KiloCode-style).
 * Called only when exact match fails. Each step applies a progressively looser
 * normalization, finds a unique match in the file content, then returns the
 * ACTUAL text from the file (resolvedOld) so the replacement is exact on disk.
 *
 * Steps:
 *   2. TrimmedBoundary     — strip leading/trailing blank lines from oldString
 *   3. LineTrimmed         — trim trailing whitespace from each line
 *   4. WhitespaceNormalized — collapse internal whitespace runs per line
 *   5. IndentationFlexible — strip leading whitespace from each line
 *   6. EscapeNormalized    — resolve \\n, \\t literals in oldString
 *   7. BlockAnchor         — match by first + last non-empty line
 *   8. ContextAware        — anchor on the most distinctive line, extract expected-length block
 *   9. MultiOccurrence     — take the first match when multiple exist (last resort)
 */
export function findFuzzyMatch(content: string, oldString: string): FallbackMatch | null {
  // Try: transform oldString into something that appears verbatim in content (character-level)
  const tryCharTransform = (transform: (s: string) => string, method: string): FallbackMatch | null => {
    const t = transform(oldString);
    if (t === oldString) return null; // transform produced no change
    const n = countOccurrences(content, t);
    if (n === 1) return { resolvedOld: t, method };
    return null;
  };

  // Try: normalize each line of oldString and content, sliding-window match, map back to original
  const tryLineNorm = (normLine: (l: string) => string, method: string): FallbackMatch | null => {
    const oldLines = oldString.split('\n');
    const contentLines = content.split('\n');
    const normOld = oldLines.map(normLine);
    const normContent = contentLines.map(normLine);

    if (normOld.every((l, i) => l === oldLines[i])) return null; // no change from normalization

    const target = normOld.join('\n');
    const n = normOld.length;
    const hits: number[] = [];

    for (let i = 0; i <= normContent.length - n; i++) {
      if (normContent.slice(i, i + n).join('\n') === target) hits.push(i);
    }

    if (hits.length === 1) {
      return { resolvedOld: contentLines.slice(hits[0], hits[0] + n).join('\n'), method };
    }
    if (hits.length > 1) {
      // Multiple matches — take first, note it (Step 9 handles this intentionally)
      return {
        resolvedOld: contentLines.slice(hits[0], hits[0] + n).join('\n'),
        method: `${method} (${hits.length} matches, first used)`,
      };
    }
    return null;
  };

  // Step 2: TrimmedBoundary
  const s2 = tryCharTransform(s => s.replace(/^\n+/, '').replace(/\n+$/, ''), 'TrimmedBoundary');
  if (s2) return s2;

  // Step 3: LineTrimmed
  const s3 = tryLineNorm(l => l.trimEnd(), 'LineTrimmed');
  if (s3) return s3;

  // Step 4: WhitespaceNormalized
  const s4 = tryLineNorm(l => l.replace(/[ \t]+/g, ' ').trimEnd(), 'WhitespaceNormalized');
  if (s4) return s4;

  // Step 5: IndentationFlexible
  const s5 = tryLineNorm(l => l.trimStart(), 'IndentationFlexible');
  if (s5) return s5;

  // Step 6: EscapeNormalized
  const s6 = tryCharTransform(
    s => s.replace(/\\n/g, '\n').replace(/\\t/g, '\t').replace(/\\\\/g, '\\'),
    'EscapeNormalized'
  );
  if (s6) return s6;

  // Step 7: BlockAnchor — match by first + last non-empty lines
  {
    const oldLines = oldString.split('\n');
    const nonEmpty = oldLines.filter(l => l.trim().length > 0);
    if (nonEmpty.length >= 2) {
      const firstTrim = nonEmpty[0].trim();
      const lastTrim = nonEmpty[nonEmpty.length - 1].trim();
      const cLines = content.split('\n');
      const expectedLen = oldLines.length;
      for (let i = 0; i < cLines.length; i++) {
        if (cLines[i].trim() !== firstTrim) continue;
        const maxJ = Math.min(cLines.length - 1, i + expectedLen + 3);
        for (let j = i + 1; j <= maxJ; j++) {
          if (cLines[j].trim() === lastTrim) {
            return { resolvedOld: cLines.slice(i, j + 1).join('\n'), method: 'BlockAnchor' };
          }
        }
      }
    }
  }

  // Step 8: ContextAware — anchor on the most distinctive line, extract expected-length block
  {
    const oldLines = oldString.split('\n');
    const anchor = oldLines
      .map((l, i) => ({ trimmed: l.trim(), idx: i }))
      .filter(x => x.trimmed.length > 15)
      .sort((a, b) => b.trimmed.length - a.trimmed.length)[0];

    if (anchor) {
      const cLines = content.split('\n');
      for (let ci = 0; ci < cLines.length; ci++) {
        if (cLines[ci].trim() !== anchor.trimmed) continue;
        const blockStart = ci - anchor.idx;
        if (blockStart >= 0 && blockStart + oldLines.length <= cLines.length) {
          return {
            resolvedOld: cLines.slice(blockStart, blockStart + oldLines.length).join('\n'),
            method: 'ContextAware',
          };
        }
      }
    }
  }

  // Step 9: MultiOccurrence — WhitespaceNormalized allowing multiple matches (last resort)
  {
    const s9 = tryLineNorm(l => l.replace(/[ \t]+/g, ' ').trimEnd(), 'MultiOccurrence');
    if (s9) return s9;
  }

  return null;
}

/**
 * When an edit can't be located (exact + 9-step fuzzy both failed), find the file region that most
 * resembles oldString and return it with line numbers. Surfacing the ACTUAL current text in the
 * error turns blind "not found" retries — the loop where a model re-emits the same near-miss
 * oldString over and over — into informed ones: it can copy the real text verbatim or anchor a
 * smaller edit. Anchors on the most distinctive line of oldString; scores file lines by word
 * overlap (cheap, robust to indentation/punctuation drift). Returns null if nothing is close enough.
 */
export function closestRegion(content: string, oldString: string): string | null {
  const oldLines = oldString.split('\n').map(l => l.trim()).filter(l => l.length > 3);
  if (oldLines.length === 0) return null;

  const cLines = content.split('\n');
  let bestIdx = -1;
  let bestScore = 0;
  // Score every oldString line against every file line by word overlap and keep the single best
  // pairing — robust to indentation, punctuation, and the surrounding lines being slightly off.
  for (const ol of oldLines) {
    const olTokens = new Set(ol.split(/\s+/).filter(Boolean));
    if (olTokens.size === 0) continue;
    for (let i = 0; i < cLines.length; i++) {
      const toks = cLines[i].trim().split(/\s+/).filter(Boolean);
      if (toks.length === 0) continue;
      let shared = 0;
      for (const tok of toks) if (olTokens.has(tok)) shared++;
      const symmetricScore = shared / Math.max(olTokens.size, toks.length);
      // Models sometimes flatten a multiline oldString into one long line. In that case the
      // symmetric score is tiny even when a short file line is fully contained in the request.
      // This asymmetric diagnostic score only improves the hint; it never authorizes an edit.
      const containmentScore = shared >= 2
        ? shared / Math.min(olTokens.size, toks.length)
        : 0;
      const score = Math.max(symmetricScore, containmentScore * 0.8);
      if (score > bestScore) {
        bestScore = score;
        bestIdx = i;
      }
    }
  }
  if (bestIdx < 0 || bestScore < 0.34) return null; // nothing resembles it — a hint would mislead

  const start = Math.max(0, bestIdx - 3);
  const end = Math.min(cLines.length, bestIdx + 4);
  return cLines
    .slice(start, end)
    .map((l, k) => `${String(start + k + 1).padStart(5)}  ${l}`)
    .join('\n');
}

function lineNumberedMatch(content: string, matched: string, maxLines = 12): string {
  const offset = content.indexOf(matched);
  const firstLine = offset >= 0 ? content.slice(0, offset).split('\n').length : 1;
  const lines = matched.split('\n');
  const shown = lines.slice(0, maxLines)
    .map((line, index) => `${String(firstLine + index).padStart(5)}  ${line}`);
  if (lines.length > maxLines) shown.push(`      … ${lines.length - maxLines} more matched line(s)`);
  return shown.join('\n');
}

/** Render a compact unified-style preview of the change for the transcript. */

interface EditArgs {
  path: string;
  oldString: string;
  newString: string;
  replaceAll?: boolean;
}

export const createEditFileTool = (governor: IGovernor) => buildTool({
  name: 'EditFileTool',
  description: `Performs an exact string replacement inside an existing file. This is the correct tool for modifying code: it is surgical, reviewable, and never rewrites the rest of the file. Prefer it over WriteFileTool (full overwrite) and over \`sed\` via BashTool.

# Instructions
- **oldString** must match the file content EXACTLY, including indentation and line breaks.
- **Keep oldString SMALL** — prefer one line, or a few lines, anchored on a single unique line. Large multi-line blocks with deep indentation are error-prone to reproduce verbatim and are the #1 cause of failed edits. Make several small edits instead of one big one.
- **oldString must be unique** in the file, or the edit fails — include just enough surrounding context to disambiguate. Alternatively pass \`replaceAll: true\` to replace every occurrence.
- **newString** must differ from oldString.
- The file must already exist; use WriteFileTool to create new files.`,
  isDestructive: true,
  schema: {
    type: 'object',
    properties: {
      path: { type: 'string', description: 'Path to the file to edit (supports ~/ for home dir).' },
      oldString: { type: 'string', description: 'The exact text to replace (must match the file verbatim).' },
      newString: { type: 'string', description: 'The replacement text.' },
      replaceAll: { type: 'boolean', description: 'Replace every occurrence instead of requiring uniqueness (default false).' },
    },
    required: ['path', 'oldString', 'newString'],
  },
  execute: async (rawArgs: any, context?: any) => {
    // Accept Claude-Code-style snake_case keys (file_path / old_string / new_string / replace_all)
    // as well as our camelCase schema — many models emit the former.
    const args: EditArgs = {
      path: rawArgs.path ?? rawArgs.file_path ?? rawArgs.filePath,
      oldString: rawArgs.oldString ?? rawArgs.old_string,
      newString: rawArgs.newString ?? rawArgs.new_string,
      replaceAll: rawArgs.replaceAll ?? rawArgs.replace_all,
    };
    const cwd = context?.cwd || process.cwd();
    const fullPath = resolvePath(args.path, cwd);

    const wsBlock = workspaceWriteBlock(fullPath);
    if (wsBlock) return outcomeError('permission', `Error: ${wsBlock}`);

    if (args.oldString === args.newString) {
      return outcomeError('invalid_args', 'Error: newString must be different from oldString.');
    }
    if (!args.oldString) {
      return outcomeError('invalid_args', 'Error: oldString cannot be empty. To create a file, use WriteFileTool.');
    }

    let content: string;
    try {
      content = await fs.readFile(fullPath, 'utf8');
    } catch (e: any) {
      if (e.code === 'ENOENT') {
        return outcomeError('not_found', `Error: File not found: ${args.path}. Use WriteFileTool to create new files.`);
      }
      throw e;
    }

    // When a transaction is open, ANY failure after we've committed to attempting this edit must
    // roll the whole transaction back — that is the atomicity guarantee /tx promises. Outside a
    // transaction this just returns the message unchanged.
    const fail = async (msg: string, reason: string): Promise<string> => {
      if (globalTransactionManager.isOpen()) {
        const rbMsg = await globalTransactionManager.autoRollback(args.path, reason);
        return rbMsg ? `${msg}\n\n${rbMsg}` : msg;
      }
      return msg;
    };

    const occurrences = countOccurrences(content, args.oldString);

    // Resolve the old text to replace: prefer exact match, fall back to 9-step fuzzy chain.
    let resolvedOld = args.oldString;
    let matchMethod: string | null = null;

    if (occurrences === 0) {
      const fuzzy = findFuzzyMatch(content, args.oldString);
      if (!fuzzy) {
        const hint = closestRegion(content, args.oldString);
        return outcomeError('not_found', await fail(
          `Error: oldString not found in ${args.path}. The 9-step fuzzy fallback also failed ` +
          `(TrimmedBoundary → LineTrimmed → WhitespaceNormalized → IndentationFlexible → ` +
          `EscapeNormalized → BlockAnchor → ContextAware → MultiOccurrence).` +
          (hint
            ? `\n\nThe closest region currently in the file is:\n\n${hint}\n\n` +
              `Copy oldString VERBATIM from there (exact whitespace and indentation), or make a ` +
              `smaller edit anchored on a single unique line. Do NOT re-send the same oldString.`
            : ` Re-read the file and copy oldString exactly, including whitespace and indentation.`),
          'oldString not found',
        ));
      }
      resolvedOld = fuzzy.resolvedOld;
      matchMethod = fuzzy.method;
    }

    const resolvedCount = countOccurrences(content, resolvedOld);
    if (resolvedCount > 1 && !args.replaceAll) {
      return outcomeError('ambiguous_match', await fail(
        `Error: oldString appears ${resolvedCount} times in ${args.path}${matchMethod ? ` (matched via ${matchMethod})` : ''}. Add more surrounding context to make it unique, or pass replaceAll: true.`,
        'ambiguous oldString',
      ));
    }

    // Use a replacer FUNCTION, not a string: String.replace interprets `$$`, `$&`, `` $` ``, `$'`
    // in a string replacement even when the pattern is a plain string, so a newString containing
    // e.g. `$$` (Makefiles, shell PID/`$$`) or `$&` (regex/sed code) would be silently corrupted.
    // A function return value is inserted verbatim. (split/join for replaceAll is already literal.)
    const updated = args.replaceAll
      ? content.split(resolvedOld).join(args.newString)
      : content.replace(resolvedOld, () => args.newString);

    // Guard against the "flattened file" corruption (e.g. a whole-file oldString replaced by a
    // newline-stripped newString). Refuse before touching disk.
    const flat = detectCorruptWrite(content, updated, fullPath);
    if (flat) {
      return outcomeError('syntax', await fail(
        `Edit to ${args.path} refused: ${flat}. No changes were made. ` +
        `Make a smaller, surgical edit and keep newline characters intact in newString.`,
        'corrupt-write refused',
      ));
    }

    // Edit Shield: refuse an edit that would introduce NEW syntax errors — the broken file never
    // reaches disk, and the error names the exact lines so the very next attempt can fix it.
    const shield = shieldEdit(fullPath, content, updated);
    if (shield) {
      const approximateMatchDiagnostic = matchMethod
        ? `\n\nImportant: oldString was not an exact match. The fuzzy matcher selected this ` +
          `current region via ${matchMethod}:\n\n${lineNumberedMatch(content, resolvedOld)}\n\n` +
          `The syntax failure may be caused by replacing the wrong or incomplete region, not by ` +
          `newString itself. Retry EditFileTool with a smaller oldString copied verbatim from the ` +
          `region above; do not switch write mechanisms.`
        : '';
      return outcomeError('syntax', await fail(
        `Edit to ${args.path} refused by Edit Shield: ${shield}${approximateMatchDiagnostic}`,
        'edit-shield refused',
      ));
    }

    // Blast-radius gate (no-op unless enabled + interactive + the file owns a HIGH/CRITICAL symbol).
    if (!(await checkBlastRadius(fullPath))) {
      return outcomeRejected(await fail(`Edit to ${args.path} cancelled — declined at the blast-radius gate. No changes were made.`, 'blast-radius declined'));
    }

    // Inline diff approval. When a fuzzy match was used, surface the match method in the summary
    // so the user can see exactly how the approximate match was resolved before approving.
    const approvalSummary = matchMethod
      ? `Edit ${args.path} [APPROXIMATE MATCH via ${matchMethod}]`
      : `Edit ${args.path}`;
    const approved = await requestDiffApproval(approvalSummary, unifiedDiff(content, updated, args.path));
    if (!approved) return outcomeRejected(await fail(`Edit to ${args.path} rejected by user. No changes were made.`, 'rejected by user'));

    // Track the pre-edit state for atomic rollback before touching disk, and declare exactly what
    // this edit is about to leave there — that is what lets rollback tell our own write apart from
    // a change somebody else made afterwards, instead of silently overwriting it.
    await globalTransactionManager.trackEdit(fullPath, updated);
    // Snapshot first so /undo and /diff-file work on every agent edit.
    await backupFile(fullPath);
    try {
      await fs.writeFile(fullPath, updated, 'utf8');
    } catch (e: any) {
      return outcomeError('io', await fail(`Edit to ${args.path} failed while writing: ${e.message}. No changes were applied.`, `write failed: ${e.message}`));
    }
    // Invalidate the read cache so post-compact restoration doesn't re-inject stale content.
    fileStateCache.invalidate(fullPath);

    const n = args.replaceAll ? resolvedCount : 1;
    const matchNote = matchMethod ? ` [matched via ${matchMethod}]` : '';
    const syntaxWarn = checkEditSyntax(fullPath, updated) || '';
    return outcomeOk(`Edited ${args.path} (${n} replacement${n === 1 ? '' : 's'}${matchNote}):\n${capDiff(compactDiff(content, updated, args.path))}${syntaxWarn}`);
  },
}, governor);

import * as fs from 'fs/promises';
import * as path from 'path';
import * as os from 'os';
import { resolvePath, workspaceWriteBlock } from '../path.util';
import * as crypto from 'crypto';
import { IGovernor } from '../../core/interfaces';
import { buildTool } from '../tool.factory';
import { backupFile, unifiedDiff, compactDiff, capDiff } from '../../engine/fileEditor';
import { checkEditSyntax, shieldEdit } from '../syntax.check';
import { requestDiffApproval } from '../../engine/diffApproval';
import { checkBlastRadius } from '../../engine/blastGate';
import { sliceLineRange } from '../file-range';
import { detectCorruptWrite } from '../write-guard';
import { fileStateCache, statStamp, hashFileBytes } from '../../memory/file-state-cache';
import { globalTransactionManager } from '../../core/transaction.manager';
import { outcomeOk, outcomeError, outcomeRejected } from '../outcome';
import { moveToBin, movedToBinText } from '../thread.bin';
import { recordTrash } from '../thread.journal';

// Files larger than this get truncated with a note. The full file content is written to
// a temp path for reference when the file is very large (>1MB).
const MAX_FILE_BYTES = 100 * 1024;        // 100 KB — read in full
const OFFLOAD_FILE_BYTES = 1024 * 1024;   // 1 MB — also write to /tmp for reference
const PREVIEW_LINES = 100;

/** Whitespace-delimited count, matching the familiar `wc -w` behavior. */
export function countWords(content: string, excludeTitle = false): number {
  let counted = content;
  if (excludeTitle) {
    const lines = content.split(/\r?\n/);
    const titleLine = lines.findIndex(line => line.trim().length > 0);
    // A one-line story is not a title. Never erase the entire draft from the count.
    if (titleLine >= 0 && lines.slice(titleLine + 1).some(line => line.trim())) {
      counted = lines.slice(titleLine + 1).join('\n');
    }
  }
  const trimmed = counted.trim();
  return trimmed ? trimmed.split(/\s+/).length : 0;
}

export const createReadFileTool = (governor: IGovernor) => buildTool({
  name: 'ReadFileTool',
  description: `Reads the contents of a file from the local file system.

Use this tool to inspect source code, configuration files, or logs. It natively handles truncation for massive files and is significantly more token-efficient than using \`cat\` in the BashTool.

# Instructions
- **Paths:** Absolute, or relative to the current working directory — both resolve. Prefer the path exactly as the user or a prior tool result gave it.
- **Line Ranges:** If you are working with a massive file (>1000 lines), do NOT attempt to read the entire file at once. Use the \`startLine\` and \`endLine\` parameters to read localized chunks.
- **Context Gathering:** When investigating a bug, do not read files blindly. First, use the \`GraphQueryTool\` to find the exact file paths and class names relevant to the feature.
- **No Directories:** This tool only works on files. If you need to see the contents of a directory, use the \`BashTool\` with \`ls -la\`.`,
  isDestructive: false, // Read-only
  workflowReadOnly: true,
  isConcurrencySafe: true,
  schema: {
    type: 'object',
    properties: {
      path: {
        type: 'string',
        description: 'Path to the file (absolute, or relative to the current working directory).'
      },
      startLine: {
        type: 'number',
        description: 'Optional. The 1-indexed start line to read from.'
      },
      endLine: {
        type: 'number',
        description: 'Optional. The 1-indexed end line to read to.'
      }
    },
    required: ['path']
  },
  execute: async (args: any, context?: any) => {
    try {
      const currentCwd = context?.cwd || process.cwd();
      const fullPath = resolvePath(args.path, currentCwd);

      if (context?.workflowEvidence) {
        // Evidence must describe the returned bytes, not an mtime-cache entry from an older read.
        const rawContent = await context.workflowEvidence.readFile(fullPath);
        if (args.startLine === undefined && args.endLine === undefined) return rawContent;
        const { text, error } = sliceLineRange(rawContent, args.startLine, args.endLine);
        if (error) return outcomeError('invalid_args', `Error: ${error}`);
        return text ?? rawContent;
      }

      // Stat once for the cache lookup and stale detection. The stamp adds size and ctime to mtime, so
      // a rewrite that put the old mtime back is not served from the cache (record 47, A01).
      const fileStat = await fileStateCache.getStat(fullPath);
      if (fileStat === null) return outcomeError('not_found', `Error: File not found at ${args.path}`);
      const mtime = fileStat.mtimeMs;
      const stamp = statStamp(fileStat);

      // When a line range is requested, check the cache first
      if (args.startLine !== undefined || args.endLine !== undefined) {
        const cached = fileStateCache.get(fullPath, mtime, args.startLine, args.endLine, stamp);
        if (cached !== null) return cached;

        const rawBytes = await fs.readFile(fullPath);
        const rawContent = rawBytes.toString('utf8');
        const { text, error } = sliceLineRange(rawContent, args.startLine, args.endLine);
        if (error) return outcomeError('invalid_args', `Error: ${error}`);
        const slicedText = text ?? '';
        fileStateCache.set(fullPath, mtime, slicedText, args.startLine, args.endLine, { stamp, fileHash: hashFileBytes(rawBytes) });
        return slicedText;
      }

      // Full-file read — check cache first
      const cached = fileStateCache.get(fullPath, mtime, undefined, undefined, stamp);
      if (cached !== null) return cached;

      // Size check before reading large files
      const stat = await fs.stat(fullPath);

      if (stat.size > MAX_FILE_BYTES) {
        const rawContent = await fs.readFile(fullPath, 'utf8');
        const allLines = rawContent.split('\n');
        const preview = allLines.slice(0, PREVIEW_LINES).join('\n');
        const sizeKB = Math.round(stat.size / 1024);
        const remaining = allLines.length - PREVIEW_LINES;

        let result: string;

        if (stat.size > OFFLOAD_FILE_BYTES) {
          // Very large file — write to /tmp so model can reference it
          const hash = crypto.createHash('sha256').update(fullPath).digest('hex').slice(0, 8);
          const tmpPath = path.join(os.tmpdir(), `bimax-file-${hash}.txt`);
          await fs.writeFile(tmpPath, rawContent, 'utf8');
          result =
            `[File too large: ${sizeKB}KB — full content offloaded to ${tmpPath}]\n` +
            `[Showing first ${PREVIEW_LINES} of ${allLines.length} lines. Use startLine/endLine to read specific sections.]\n\n` +
            preview +
            (remaining > 0 ? `\n\n[... ${remaining} more lines — read via startLine/endLine or open ${tmpPath}]` : '');
        } else {
          result =
            `[Large file: ${sizeKB}KB — showing first ${PREVIEW_LINES} of ${allLines.length} lines. Use startLine/endLine to read more.]\n\n` +
            preview +
            (remaining > 0 ? `\n\n[... ${remaining} more lines truncated]` : '');
        }

        // Cache the truncated result (the model only got the preview). No file hash: a preview is not
        // the file, so post-compact restoration can never verify it and never restores it as the file.
        fileStateCache.set(fullPath, mtime, result, undefined, undefined, { stamp });
        return result;
      }

      const bytes = await fs.readFile(fullPath);
      const content = bytes.toString('utf8');
      fileStateCache.set(fullPath, mtime, content, undefined, undefined, { stamp, fileHash: hashFileBytes(bytes) });
      return content;
    } catch (e: any) {
      if (e.code === 'ENOENT') {
        return outcomeError('not_found', `Error: File not found at ${args.path}`);
      }
      throw e;
    }
  }
}, governor);

export const createWriteFileTool = (governor: IGovernor) => buildTool({
  name: 'WriteFileTool',
  description: `Creates a new file, or fully replaces an existing one. To CHANGE part of an existing file, use EditFileTool instead — this tool always writes the complete content.

Use this tool to write new code, config files, or artifacts. It is significantly faster, safer, and more reliable than attempting to use \`echo\` or \`cat <<EOF\` via the BashTool.

# Instructions
- **Supports \`~/Desktop/...\` paths** — home directory is automatically resolved.
- **Directory Creation:** If the parent directories do not exist, the tool will automatically create them for you.
- **Do NOT create empty directories:** Do NOT use this tool if you only want to create a new folder/directory. This tool creates FILES. If you need to create an empty directory, use \`BashTool\` with \`mkdir\`.
- **Overwriting:** Writing to an existing file replaces it (a backup is kept for \`/undo\`). You do NOT need to pass anything special to overwrite.
- **Do NOT silently clobber:** When the user asks you to CREATE or ADD a *new* document (a story, note, draft, script, etc.) and a file already exists at the path you'd choose, pick a non-colliding name instead (e.g. \`story.txt\` → \`story-2.txt\`) rather than overwriting — an overwrite destroys their existing file. Overwrite an existing file only when the user clearly means to update/replace *that specific* file (e.g. "fix the bug in X", "rewrite X"). When unsure whether a destination exists, list the directory first.
- **Modifying existing code:** Do NOT rewrite a whole file to change part of it. Use \`EditFileTool\` for a surgical oldString→newString replacement — it is safer and avoids accidentally dropping newlines. A full-file overwrite that collapses a multi-line file to one line will be REFUSED.
- **Multi-line content:** Always emit real newline characters between lines. Never flatten code onto a single line.
- **Exact word counts:** When the user requests an exact length for prose, ALWAYS pass \`expectedWords\`. If the document starts with a title that should not count toward the requested story/article length, also pass \`excludeTitleFromWordCount: true\`. The tool validates the draft before touching disk, so revise a rejected draft instead of creating and then overwriting an approximate one.
- **Validation:** After writing a complex script or TypeScript file, immediately use the \`BashTool\` to run a syntax check (e.g., \`npx tsc --noEmit\`) to verify your write didn't introduce syntax errors.`,
  isDestructive: true,
  schema: {
    type: 'object',
    properties: {
      path: { type: 'string', description: 'Path to the file (supports ~/ for home dir)' },
      content: { type: 'string', description: 'Content to write' },
      overwrite: { type: 'boolean', description: 'Deprecated/ignored — Write always creates or overwrites.' },
      expectedWords: {
        type: 'integer',
        minimum: 0,
        description: 'Exact required word count for prose. Set whenever the user requests a specific number of words.'
      },
      excludeTitleFromWordCount: {
        type: 'boolean',
        description: 'When true, excludes the first non-empty line (the title) from expectedWords validation.'
      }
    },
    required: ['path', 'content']
  },
  execute: async (args: {
    path: string,
    content: string,
    overwrite?: boolean,
    expectedWords?: number,
    excludeTitleFromWordCount?: boolean,
  }, context?: any) => {
    const currentCwd = context?.cwd || process.cwd();
    const fullPath = resolvePath(args.path, currentCwd);
    if (/\.(docx|xlsx|pptx|pdf)$/i.test(fullPath)) {
      return outcomeError('invalid_args', 'WriteFileTool writes text, not office documents. Use DocumentTool to create a valid document; no file was written.');
    }
    const wsBlock = workspaceWriteBlock(fullPath);
    if (wsBlock) return outcomeError('permission', `Error: ${wsBlock}`);

    // Exact-length prose is easy for a model to estimate but hard for it to count reliably. Reject
    // an approximate draft before approvals, backups, or disk mutation so the correction is a
    // retry—not a visible create-then-overwrite sequence that still may miss the requested count.
    let validatedWordCount: number | undefined;
    if (args.expectedWords !== undefined) {
      if (!Number.isInteger(args.expectedWords) || args.expectedWords < 0) {
        return outcomeError('invalid_args', 'Error: expectedWords must be a non-negative integer. Nothing was written.');
      }
      validatedWordCount = countWords(args.content, args.excludeTitleFromWordCount === true);
      if (validatedWordCount !== args.expectedWords) {
        const delta = args.expectedWords - validatedWordCount;
        const adjustment = delta > 0 ? `add ${delta}` : `remove ${Math.abs(delta)}`;
        const scope = args.excludeTitleFromWordCount ? 'body' : 'document';
        return outcomeError(
          'invalid_args',
          `Word-count validation failed: expected exactly ${args.expectedWords} ${scope} words, ` +
          `but received ${validatedWordCount}; ${adjustment} word${Math.abs(delta) === 1 ? '' : 's'} and retry. Nothing was written.`
        );
      }
    }
    const exists = await fs.access(fullPath).then(() => true).catch(() => false);
    // Write creates OR overwrites (standard agent behavior — models emit Write expecting it to
    // replace an existing file, and erroring "file already exists" just wedged them into a retry
    // loop). Accidental clobbering is already guarded against by the corrupt-write check (refuses a
    // flattened/newline-stripped overwrite), the blast-radius gate, the inline diff approval, and the
    // pre-write backup below — so the old hard `overwrite: true` requirement was redundant friction.
    // Blast-radius gate — only meaningful when overwriting an existing, indexed file.
    if (exists && !(await checkBlastRadius(fullPath))) {
      return outcomeRejected(`Write to ${args.path} cancelled — declined at the blast-radius gate. No changes were made.`);
    }
    // Inline diff approval (no-op unless enabled and an interactive approver is registered).
    const prior = exists ? await fs.readFile(fullPath, 'utf-8').catch(() => '') : '';
    const approved = await requestDiffApproval(
      exists ? `Overwrite ${args.path}` : `Create ${args.path}`,
      unifiedDiff(prior, args.content, args.path)
    );
    if (!approved) return outcomeRejected(`Write to ${args.path} rejected by user. No changes were made.`);
    // Guard against the "flattened file" corruption (model strips newlines on a full-file
    // overwrite). Refuse before touching disk and steer the model to a surgical edit.
    if (exists) {
      const flat = detectCorruptWrite(prior, args.content, fullPath);
      if (flat) {
        return outcomeError('syntax', `Write to ${args.path} refused: ${flat}. No changes were made. ` +
          `To modify an existing file use EditFileTool (surgical oldString→newString) and keep real newline characters in multi-line content.`);
      }
    }
    // Edit Shield: a write that would introduce NEW syntax errors (vs. what's on disk; a new file
    // must simply parse) never reaches disk — the error names the lines so the retry can fix it.
    const shield = shieldEdit(fullPath, prior, args.content);
    if (shield) {
      return outcomeError('syntax', `Write to ${args.path} refused by Edit Shield: ${shield}`);
    }
    // Track the pre-write state for atomic rollback when a /tx transaction is open, and declare the
    // content about to land so rollback can tell this write apart from a later external change.
    // Must run before the write so the snapshot is the pre-write state.
    await globalTransactionManager.trackEdit(fullPath, args.content);
    // Snapshot overwrites so /undo and /diff-file can restore the prior version.
    if (exists) await backupFile(fullPath);
    await fs.mkdir(path.dirname(fullPath), { recursive: true });
    try {
      await fs.writeFile(fullPath, args.content, 'utf-8');
    } catch (e: any) {
      if (globalTransactionManager.isOpen()) {
        const rb = await globalTransactionManager.autoRollback(args.path, `write failed: ${e.message}`);
        return outcomeError('io', `Write to ${args.path} failed: ${e.message}.${rb ? `\n\n${rb}` : ''}`);
      }
      throw e;
    }
    // Invalidate read cache so post-compact restoration doesn't re-inject stale pre-write content.
    fileStateCache.invalidate(fullPath);
    const diff = capDiff(compactDiff(prior, args.content, args.path));
    const syntaxWarn = checkEditSyntax(fullPath, args.content) || '';
    const wordCountNote = validatedWordCount === undefined
      ? ''
      : `\nWord count verified: ${validatedWordCount}${args.excludeTitleFromWordCount ? ' (title excluded)' : ''}.`;
    return outcomeOk(`${exists ? 'Updated' : 'Created'} ${args.path}${diff ? `:\n${diff}` : ''}${wordCountNote}${syntaxWarn}`);
  }
}, governor);

export const createDeleteTool = (governor: IGovernor) => buildTool({
  name: 'DeleteTool',
  description: `Deletes files or directories from the local file system.

Use this tool whenever the user explicitly asks you to delete, remove, or trash a file or folder. Do NOT use the BashTool for this.

# Instructions
- **Supports \`~/\` paths** — home directory is automatically resolved.
- **Directories:** It will recursively delete the directory and all of its contents.`,
  isDestructive: true,
  schema: {
    type: 'object',
    properties: {
      path: { type: 'string', description: 'Absolute or relative path to the file or directory to delete' }
    },
    required: ['path']
  },
  execute: async (args: { path: string }, context?: any) => {
    const currentCwd = context?.cwd || process.cwd();
    const fullPath = resolvePath(args.path, currentCwd);
    const wsBlock = workspaceWriteBlock(fullPath);
    if (wsBlock) return outcomeError('permission', `Error: ${wsBlock}`);
    // Verify the target actually exists BEFORE deleting. fs.rm with `force: true`
    // silently treats a missing path as success, which would let us report
    // "Successfully deleted" for a path that never existed (e.g. a bare name
    // resolved against the wrong cwd). Fail loudly instead so the caller can retry.
    const exists = await fs.access(fullPath).then(() => true).catch(() => false);
    if (!exists) {
      return outcomeError('not_found', `Error: Nothing to delete — no file or directory found at ${fullPath} (resolved from "${args.path}" relative to ${currentCwd}). Nothing was changed. If the target lives elsewhere, pass its absolute path.`);
    }
    // In a desktop thread the item goes to the Bin through the Bimax app, and the thread can undo it.
    if (process.env.BIMAX_THREAD_ROOT) {
      const kind = (await fs.stat(fullPath)).isDirectory() ? 'folder' : 'file';
      try {
        const { moved, error } = await moveToBin([fullPath], context?.signal);
        await recordTrash(`Move ${kind} “${path.basename(fullPath)}” to the Bin`, 'DeleteTool', moved);
        if (error || !moved.length) return outcomeError('io', `Could not move ${args.path} to the Bin: ${error || 'nothing was moved'}. Nothing was deleted.`);
        return outcomeOk(movedToBinText(moved.map((m) => m.path)));
      } catch (e: any) {
        return outcomeError('io', `Could not move ${args.path} to the Bin: ${e.message}. Nothing was deleted.`);
      }
    }
    // Back up a file before deleting so /undo and /rewind can bring it back (parity with edit/write,
    // which always back up first). Best-effort: a directory can't be content-backed-up, and a failed
    // backup shouldn't block an explicitly-approved delete.
    try {
      const st = await fs.stat(fullPath);
      // `null` declares the intent: after this tool runs the path is gone, so an open /tx can
      // re-create it on rollback and still detect a file somebody else put back in the meantime.
      if (st.isFile()) { await globalTransactionManager.trackEdit(fullPath, null); await backupFile(fullPath); }
    } catch { /* best-effort */ }
    try {
      await fs.rm(fullPath, { recursive: true, force: true });
      return outcomeOk(`Successfully deleted ${fullPath}`);
    } catch (e: any) {
      return outcomeError('io', `Failed to delete ${args.path}: ${e.message}`);
    }
  }
}, governor);

export const createMakeDirTool = (governor: IGovernor) => buildTool({
  name: 'CreateDirectoryTool',
  description: `Creates a new, empty directory (folder) on the local file system.

Use this tool whenever the user asks you to create, make, or add a new *folder* or *directory*. Do NOT use WriteFileTool for this — that tool writes FILES, not folders.

# Instructions
- **Supports \`~/\` and \`~/Desktop/...\` paths** — the home directory is resolved automatically.
- **Recursive:** Parent directories are created automatically if they are missing (like \`mkdir -p\`).
- **Idempotent:** If the directory already exists, this succeeds without error.`,
  isDestructive: true,
  schema: {
    type: 'object',
    properties: {
      path: { type: 'string', description: 'Path of the directory to create (supports ~/ for home dir)' }
    },
    required: ['path']
  },
  execute: async (args: { path: string }, context?: any) => {
    const currentCwd = context?.cwd || process.cwd();
    const fullPath = resolvePath(args.path, currentCwd);
    const stat = await fs.stat(fullPath).catch(() => null);
    if (stat && stat.isFile()) {
      return outcomeError('invalid_args', `Error: A file already exists at ${fullPath}, so a directory with that name cannot be created. Delete the file first if you meant to replace it with a folder.`);
    }
    const block = workspaceWriteBlock(fullPath);
    if (block) return outcomeError('permission', block);
    await fs.mkdir(fullPath, { recursive: true });
    if (!(await fs.stat(fullPath)).isDirectory()) return outcomeError('io', 'Directory creation could not be verified.');
    return outcomeOk(`Successfully created directory ${fullPath}`);
  }
}, governor);

import * as path from 'path';
import { IGovernor } from '../../core/interfaces';
import { buildTool } from '../tool.factory';
import { engineEvents } from '../../engine/events';

/**
 * FolderStatusTool (backlog FL1, part 2: folders with an outcome). A folder can have a stated outcome — "keep this
 * folder ready for my accountant: every receipt a PDF named by date, in its month's folder". A task working there
 * reports, file by file, whether each one now meets it ("ready") or needs the person ("needs-you", with what they
 * must do). The Bimax app keeps that as the folder's queue: what is ready, and what needs you.
 *
 * The verdicts come from this tool, never from the wording of an answer, so a weak model's prose cannot put a file
 * in the wrong list. Without an outcome (BIMAX_FOLDER_OUTCOME unset) the tool refuses: there is nothing to report
 * against, and no app would keep the queue.
 */

export type FolderItemState = 'ready' | 'needs-you';
export interface FolderStatusItem { path: string; state: FolderItemState; reason?: string }

export const MAX_STATUS_ITEMS = 200;

/** The report as the app receives it: paths absolute and inside the task's folder, a reason for every needs-you. */
export function checkStatusItems(raw: unknown, root: string): FolderStatusItem[] {
  if (!Array.isArray(raw) || raw.length === 0) throw new Error('Give `items`: one entry per file, each with `path` and `state`.');
  if (raw.length > MAX_STATUS_ITEMS) throw new Error(`Report at most ${MAX_STATUS_ITEMS} files at a time.`);
  const folder = path.resolve(root);
  const out: FolderStatusItem[] = [];
  for (const entry of raw as Array<Record<string, unknown>>) {
    const file = typeof entry?.path === 'string' ? entry.path.trim() : '';
    if (!file) throw new Error('Every item needs a `path`.');
    const full = path.resolve(folder, file);
    const rel = path.relative(folder, full);
    if (!rel || rel.startsWith('..') || path.isAbsolute(rel)) throw new Error(`${file} is not inside this task's folder.`);
    if (entry.state !== 'ready' && entry.state !== 'needs-you') throw new Error(`The state of ${file} must be "ready" or "needs-you".`);
    const reason = typeof entry.reason === 'string' ? entry.reason.replace(/\s+/g, ' ').trim().slice(0, 300) : '';
    if (entry.state === 'needs-you' && !reason) throw new Error(`Say what the person must do about ${file}: give a \`reason\`.`);
    out.push({ path: full, state: entry.state, ...(reason ? { reason } : {}) });
  }
  return out;
}

export const createFolderStatusTool = (governor: IGovernor) => buildTool({
  name: 'FolderStatusTool',
  description: `Report where files stand against this folder's outcome (the goal the person set for the folder). For each file you handled or checked, give its path and state:
- "ready": it now meets the outcome.
- "needs-you": it cannot meet the outcome without the person, and \`reason\` says exactly what they must do (e.g. "no date on the receipt — which month is it?").
Use the file's path AFTER any rename or move. Only report files inside the task folder. Call this once near the end of the task, with every file.`,
  isDestructive: false,
  isConcurrencySafe: false,
  schema: {
    type: 'object',
    properties: {
      items: {
        type: 'array',
        description: 'One entry per file.',
        items: {
          type: 'object',
          properties: {
            path: { type: 'string', description: 'The file, relative to the task folder or absolute.' },
            state: { type: 'string', enum: ['ready', 'needs-you'] },
            reason: { type: 'string', description: 'For needs-you: what the person must do.' },
          },
          required: ['path', 'state'],
        },
      },
    },
    required: ['items'],
  },
  execute: async (args: { items?: unknown }, context?: any) => {
    const outcome = process.env.BIMAX_FOLDER_OUTCOME?.trim();
    if (!outcome) throw new Error('This folder has no outcome set, so there is nothing to report against. The person sets one from the ⌘2 bar’s ⋯ menu.');
    const items = checkStatusItems(args.items, process.env.BIMAX_THREAD_ROOT || context?.cwd || process.cwd());
    engineEvents.emit('folder_status', { items });
    const waiting = items.filter((item) => item.state === 'needs-you').length;
    return `Recorded ${items.length} file${items.length === 1 ? '' : 's'}: ${items.length - waiting} ready, ${waiting} needing the person. They appear in the folder's queue.`;
  },
}, governor);

import * as path from 'path';
import { resolvePath } from '../path.util';
import { IGovernor } from '../../core/interfaces';
import { buildTool } from '../tool.factory';
import { fileStateCache } from '../../memory/file-state-cache';

interface FreeContextArgs {
  reason: string;
  items: string[];
}

/** Most recent tool results left intact when releasing tool_results (mirrors ContextManager). */
const KEEP_RECENT_TOOL_RESULTS = 6;
const RELEASED_STUB = '[tool result released via FreeContextTool]';

/** Cheap, deterministic token estimate (chars/4) — used only for the before/after report. */
function estimateTokens(messages: Array<{ content?: unknown }>): number {
  let chars = 0;
  for (const m of messages) if (typeof m?.content === 'string') chars += (m.content as string).length;
  return Math.ceil(chars / 4);
}

/**
 * Release eligible HISTORICAL tool-result bodies from the live session context, in place.
 * Preserves atomic assistant-tool-call/tool-result groupings: only the BODY of an old `tool`
 * message is replaced (role + tool_call_id stay), and the most recent results are kept intact.
 * Returns measured before/after estimates so the model's report is truthful.
 */
export function releaseToolResults(messages: Array<{ role?: string; content?: unknown }>): {
  cleared: number; tokensBefore: number; tokensAfter: number;
} {
  const tokensBefore = estimateTokens(messages);
  const toolIdx = messages.map((m, i) => (m?.role === 'tool' ? i : -1)).filter(i => i >= 0);
  let cleared = 0;
  if (toolIdx.length > KEEP_RECENT_TOOL_RESULTS) {
    const clearBefore = toolIdx[toolIdx.length - KEEP_RECENT_TOOL_RESULTS];
    for (const i of toolIdx) {
      if (i >= clearBefore) break;
      const m = messages[i] as { role?: string; content?: unknown };
      if (typeof m.content !== 'string' || m.content === RELEASED_STUB) continue;
      m.content = RELEASED_STUB; // in-place: the loop and the persona share these objects
      cleared++;
    }
  }
  return { cleared, tokensBefore, tokensAfter: estimateTokens(messages) };
}

/**
 * FreeContextTool — model-driven explicit context release (Bimax-unique).
 *
 * When the model is done working with a set of files or tool results and
 * wants to free context window space, it calls this tool instead of waiting
 * for the ContextManager to evict them automatically. Released files are
 * marked in FileStateCache so they are excluded from post-compact restoration,
 * and "tool_results" ACTUALLY clears eligible historical tool-result bodies
 * from the active session context (measured, not merely acknowledged).
 */
export const createFreeContextTool = (governor: IGovernor) => buildTool({
  name: 'FreeContextTool',
  description: `Explicitly releases context items you no longer need, freeing space in the context window.

Call this when you are done with specific files or have processed a tool result and won't need it again. Released files are excluded from automatic post-compaction restoration.

# When to use
- After reviewing a file to understand something (and you won't edit it)
- After processing a large tool result you've already extracted the key info from
- When the context window is getting full and some of your working set is no longer relevant

# Instructions
- Pass file paths as items (relative or absolute)
- Pass "tool_results" to immediately clear old tool-result bodies from this session (the most recent ${KEEP_RECENT_TOOL_RESULTS} are kept)
- Always provide a reason so the session log is interpretable`,
  isDestructive: false,
  isConcurrencySafe: true,
  schema: {
    type: 'object',
    properties: {
      reason: {
        type: 'string',
        description: 'Why you are releasing this context (e.g. "review complete", "no longer relevant").',
      },
      items: {
        type: 'array',
        items: { type: 'string' },
        description: 'File paths to release from context tracking (relative or absolute), and/or "tool_results" to clear old tool-result history now.',
      },
    },
    required: ['reason', 'items'],
  },
  execute: async (args: FreeContextArgs, context?: any) => {
    const cwd = context?.cwd || process.cwd();
    const released: string[] = [];

    for (const item of args.items) {
      if (!item) continue;
      if (item === 'tool_results') {
        const live = context?.sessionMessages;
        if (!Array.isArray(live)) {
          released.push('(tool results — no live session context available to this call)');
          continue;
        }
        const { cleared, tokensBefore, tokensAfter } = releaseToolResults(live);
        released.push(cleared > 0
          ? `${cleared} historical tool result(s) cleared — context estimate ${tokensBefore} → ${tokensAfter} tokens (~${tokensBefore - tokensAfter} freed; newest ${KEEP_RECENT_TOOL_RESULTS} kept intact)`
          : `tool results — nothing eligible to clear (fewer than ${KEEP_RECENT_TOOL_RESULTS + 1} tool results, or already cleared)`);
        continue;
      }

      const absPath = resolvePath(item, cwd);
      fileStateCache.markEvicted(absPath);
      released.push(path.relative(cwd, absPath) || item);
    }

    if (released.length === 0) {
      return 'No items released — nothing matched. Paths must be existing files in the project.';
    }

    const lines = [
      `Released ${released.length} context item(s). Reason: ${args.reason}.`,
      ...released.map(r => `  • ${r}`),
      '',
      'Released files will not be restored after the next compaction. Proceed with the current task.',
    ];

    return lines.join('\n');
  },
}, governor);

import { execFileSync } from 'child_process';
import { IGovernor } from '../../core/interfaces';
import { buildTool } from '../tool.factory';
import { getGitStatus, gitDiff, gitLog, isGitRepo } from '../../engine/git';

// B1 — agent-callable git. Read actions (status/diff/log) run freely; mutating actions
// (add/commit) are routed through the Governor's OS_COMMAND path (reusing its veto / plan-mode
// blocking / interactive prompt) and use execFileSync arg-arrays so commit messages can't
// inject shell. Intentionally does NOT push — outward-facing actions stay manual.

function git(args: string[], cwd: string): string {
  return execFileSync('git', args, { cwd, encoding: 'utf-8', maxBuffer: 4 * 1024 * 1024 });
}

export const createGitTool = (governor: IGovernor) => buildTool({
  name: 'GitTool',
  description: `Run local git operations on the workspace.

# Actions (pass as \`action\`)
- \`status\` — branch + staged/modified/untracked counts.
- \`diff\` — unstaged diff (optionally limited to \`paths\`).
- \`log\` — recent commits.
- \`add\` — stage \`paths\` (default: everything).
- \`commit\` — stage + commit with your \`message\`. Stages ONLY \`paths\` when given; with no \`paths\` it stages EVERYTHING, including untracked files — pass \`paths\` whenever the working tree may hold unrelated changes, so they don't ride along. Compose a concise, conventional message describing the change.

Does NOT push. Use commit to checkpoint a logical unit of work.`,
  isDestructive: false, // per-action governance handled inside
  /**
   * Per-call: the reporting actions read the repo and may overlap with sibling calls, while `add`
   * and `commit` mutate the index and must hold the turn's barrier. Unknown or missing actions
   * fail closed to exclusive.
   */
  isConcurrencySafe: (args: any) => ['status', 'diff', 'log'].includes(args?.action),
  schema: {
    type: 'object',
    properties: {
      action: { type: 'string', enum: ['status', 'diff', 'log', 'add', 'commit'], description: 'The git operation.' },
      message: { type: 'string', description: 'Commit message (required when action is "commit").' },
      paths: { type: 'string', description: 'Optional space-separated paths for add/diff/commit (default: all).' },
    },
    required: ['action'],
  },
  execute: async (args: { action: string; message?: string; paths?: string }, context?: any) => {
    const cwd = context?.cwd || process.cwd();
    if (!isGitRepo(cwd)) return 'Error: not a git repository (run `git init` first).';

    switch (args.action) {
      case 'status': {
        const s = getGitStatus(cwd);
        if (!s) return 'Repository has no commits yet (unborn HEAD). Stage and commit to create the first commit.';
        return `On ${s.branch} · staged +${s.added.length} modified ~${s.modified.length} deleted -${s.deleted.length} untracked ?${s.unstaged.length}`;
      }
      case 'log':
        return gitLog(cwd, 15) || 'No commits yet.';
      case 'diff':
        return gitDiff(cwd, args.paths?.trim() || undefined) || 'No changes.';
      case 'add': {
        const paths = args.paths?.trim() ? args.paths.trim().split(/\s+/) : ['-A'];
        await governor.approveTaskExecution('OS_COMMAND', { command: `git add ${paths.join(' ')}`, isDestructive: true });
        git(['add', ...paths], cwd);
        return `Staged: ${paths.join(' ')}`;
      }
      case 'commit': {
        if (!args.message?.trim()) return 'Error: commit requires a non-empty `message`.';
        // Honor `paths` exactly like `add` does: a scoped commit must not sweep up unrelated
        // working-tree changes (the description promises this — keep them in lockstep).
        const commitPaths = args.paths?.trim() ? args.paths.trim().split(/\s+/) : ['-A'];
        await governor.approveTaskExecution('OS_COMMAND', { command: `git add ${commitPaths.join(' ')} && git commit`, isDestructive: true });
        git(['add', ...commitPaths], cwd);
        try {
          const out = git(['commit', '-m', args.message.trim()], cwd);
          return out.trim() || 'Committed.';
        } catch (e: any) {
          return `Commit failed: ${(e.stdout || e.stderr || e.message).toString().trim()}`;
        }
      }
      default:
        return `Unknown action: ${args.action}. Use status|diff|log|add|commit.`;
    }
  },
}, governor);

import { IGovernor } from '../../core/interfaces';
import { buildTool } from '../tool.factory';
import { getGoalManager } from '../../memory/goal.manager';

interface GoalsArgs {
  action: 'list' | 'add' | 'complete' | 'abandon' | 'update';
  id?: string;
  title?: string;
  description?: string;
  notes?: string;
}

/**
 * GoalsTool — model-driven management of persistent cross-session goals.
 *
 * Goals survive restarts and appear in every session's system prompt. The model
 * should call this to:
 *   - Mark a goal complete when the user's long-running objective is achieved
 *   - Add a new goal the user articulated (especially ones spanning multiple sessions)
 *   - List current goals to orient on what the user is working toward
 */
export const createGoalsTool = (governor: IGovernor) => buildTool({
  name: 'GoalsTool',
  description: `Manages cross-session persistent goals — objectives that span multiple sessions and should be tracked beyond the current conversation.

Unlike the per-session TodoTool (task steps), goals represent higher-level intentions (e.g. "implement OAuth", "get CI green", "refactor the auth module"). Active goals are automatically shown at session start.

# Actions
- **list**: Show all goals (active, completed, abandoned).
- **add**: Create a new goal. Requires title. Description is optional but useful.
- **complete**: Mark a goal as completed (by id). Call when the user's objective is achieved.
- **abandon**: Mark a goal as abandoned (by id). Call when the user explicitly drops it.
- **update**: Update title, description, or notes on an existing goal (by id).

# When to call
- User mentions a long-running objective ("I want to refactor X over the next few sessions")
- A multi-session task is finally finished → complete it
- User says "add this as a goal" or "track this"`,
  isDestructive: false,
  isConcurrencySafe: true,
  schema: {
    type: 'object',
    properties: {
      action: {
        type: 'string',
        enum: ['list', 'add', 'complete', 'abandon', 'update'],
        description: 'What to do.',
      },
      id: { type: 'string', description: 'Goal ID (required for complete/abandon/update).' },
      title: { type: 'string', description: 'Goal title (required for add; optional for update).' },
      description: { type: 'string', description: 'Longer description of the goal (optional).' },
      notes: { type: 'string', description: 'Progress notes to attach to the goal (for update).' },
    },
    required: ['action'],
  },
  execute: async (args: GoalsArgs, context?: any) => {
    const gm = getGoalManager();
    const sessionId = context?.sessionId as string | undefined;

    switch (args.action) {
      case 'list': {
        const all = gm.getAllGoals();
        if (all.length === 0) return 'No goals yet. Add one with action: "add".';
        const format = (g: any) => {
          const status = g.status === 'active' ? '[active]' : g.status === 'completed' ? '[done] ' : '[gone] ';
          const sess = g.sessions.length ? ` · ${g.sessions.length} session(s)` : '';
          const notes = g.notes ? `\n    Notes: ${g.notes}` : '';
          return `${status} [${g.id}] ${g.title}${g.description ? `\n    ${g.description}` : ''}${notes}${sess}`;
        };
        const active = all.filter(g => g.status === 'active');
        const done = all.filter(g => g.status !== 'active');
        const parts: string[] = [];
        if (active.length) parts.push(`Active (${active.length}):\n${active.map(format).join('\n')}`);
        if (done.length) parts.push(`Completed/Abandoned (${done.length}):\n${done.map(format).join('\n')}`);
        return parts.join('\n\n');
      }

      case 'add': {
        if (!args.title) return 'Error: title is required for action "add".';
        const goal = await gm.addGoal(args.title, args.description || '', sessionId);
        return `Goal added [${goal.id}]: "${goal.title}"\nThis goal will appear in every future session until completed.`;
      }

      case 'complete': {
        if (!args.id) return 'Error: id is required for action "complete".';
        const goal = await gm.setStatus(args.id, 'completed', sessionId);
        if (!goal) return `Error: no goal found with id "${args.id}". Use action "list" to see goal IDs.`;
        return `Goal [${goal.id}] marked complete: "${goal.title}"`;
      }

      case 'abandon': {
        if (!args.id) return 'Error: id is required for action "abandon".';
        const goal = await gm.setStatus(args.id, 'abandoned', sessionId);
        if (!goal) return `Error: no goal found with id "${args.id}". Use action "list" to see goal IDs.`;
        return `Goal [${goal.id}] abandoned: "${goal.title}"`;
      }

      case 'update': {
        if (!args.id) return 'Error: id is required for action "update".';
        const goal = await gm.updateGoal(args.id, {
          ...(args.title !== undefined && { title: args.title }),
          ...(args.description !== undefined && { description: args.description }),
          ...(args.notes !== undefined && { notes: args.notes }),
        }, sessionId);
        if (!goal) return `Error: no goal found with id "${args.id}". Use action "list" to see goal IDs.`;
        return `Goal [${goal.id}] updated: "${goal.title}"`;
      }

      default:
        return `Error: unknown action "${args.action}". Valid: list, add, complete, abandon, update.`;
    }
  },
}, governor);

import { IGovernor } from '../../core/interfaces';
import { buildTool } from '../tool.factory';
import { GraphStore } from '../../graph/graph.store';
import { GraphNode, IGraphStore } from '../../graph/models';
import { ImpactEngine } from '../../graph/impact.engine';
import { fmtNode, searchNodes, resolveNodeId } from '../../graph/node.search';
import { readSymbolSource } from '../../graph/symbol.source';
import { planContext } from '../../graph/context.planner';
import { getTopNodes } from '../../graph/pagerank';
import { globalCodemem } from '../../graph/codemem/backend';
import { parseRepoQualifier, resolveRepoStores, pickRepoStore } from '../../graph/cross.repo';

// When a lookup misses, ORIENT the model instead of dead-ending: tell it what the graph actually
// holds — node-type counts + the most central REAL symbols — so it searches actual names rather than
// guessing conceptual ones (the "assumed an Architecture node exists" problem). No hardcoded
// workflow; just enough signal for the model to self-correct its next call.
function graphOrientation(store: IGraphStore): string {
  const nodes = [...store.getGraph().nodes.values()];
  if (nodes.length === 0) return '';
  // Count only the searchable definition types — STATEMENT/BLOCK/VARIABLE are graph internals the
  // model can't usefully search for, so they'd just be noise here.
  const SHOWN = new Set(['FILE', 'CLASS', 'FUNCTION', 'INTERFACE']);
  const byType = new Map<string, number>();
  for (const n of nodes) if (SHOWN.has(n.type)) byType.set(n.type, (byType.get(n.type) || 0) + 1);
  const types = [...byType.entries()].sort((a, b) => b[1] - a[1]).map(([t, c]) => `${c} ${t}`).join(', ');
  const central = getTopNodes(store, 12).map(r => r.label).filter(Boolean);
  return `\n\nThis graph indexes ${types || nodes.length + ' nodes'}.` +
    (central.length ? ` Its most central symbols: ${central.join(', ')}.` : '') +
    `\nThese are CODE symbols, not domain concepts — search one of the real names above, or run` +
    ` GET_DEPENDENTS / READ_SYMBOL on it.`;
}

export const createGraphQueryTool = (governor: IGovernor, graphStore: GraphStore) => buildTool({
  name: 'GraphQueryTool',
  description: `Queries the live dependency graph (AST topological map) of the project — classes, functions, files and how they connect. Use it to "zoom out" and understand impact BEFORE editing.

# Query verbs (pass as the \`query\` string)
- \`SEARCH_NODES *\` — START HERE on an unfamiliar repo: lists the most central nodes so you see what actually exists (don't guess concept names). \`SEARCH_NODES <keyword>\` then finds a specific symbol/file (matches name, purpose, path).
- \`GET_DEPENDENTS <node>\` — DIRECT callers/users of this symbol (the immediate call sites you MUST update if you change its signature). For transitive reach use BLAST_RADIUS.
- \`GET_DEPENDENCIES <node>\` — what this symbol DIRECTLY depends on (the symbols it calls/uses).
- \`BLAST_RADIUS <node>\` — downstream reach + highest criticality if you modify this node. Run this before signature-changing edits.
- \`READ_SYMBOL <node>\` — return ONLY that symbol's source (its exact line range), with a header (file, signature, criticality). Prefer this over reading a whole file when you just need one function/class.
- \`SEMANTIC <natural-language query>\` — VECTOR search that bridges vocabulary (finds "publish" when you search "send"). Use when you don't know the exact symbol name. Powered by the baked-in codebase-memory engine's local code embeddings.
- \`ARCHITECTURE [path]\` — high-level structural overview: packages, services, and de-facto module clusters (community detection). Use to grasp how an unfamiliar codebase is organized.
- \`<node>\` (bare) — the node plus its direct edges.

\`<node>\` may be an exact node id or a unique keyword; ambiguous keywords return candidates to disambiguate.

# Cross-repo (multi-repo workspaces)
Prefix any query with \`repo:<name>\` to run it against another registered repo's graph — e.g. \`repo:libfoo SEARCH_NODES parse\` or \`repo:libfoo GET_DEPENDENTS Encoder\`. Without a prefix the query runs on the primary repo. The RepoMap already lists each repo's central symbols.`,
  isDestructive: false,
  isConcurrencySafe: true,
  schema: {
    type: 'object',
    properties: {
      query: { type: 'string', description: 'A verb + target (e.g. "BLAST_RADIUS handlePayment") or a bare node id/keyword.' }
    },
    required: ['query']
  },
  execute: async (args: { query: string }, context?: any) => {
    const rawFull = (args.query || '').trim();
    if (!rawFull) return 'Error: empty query.';

    // Cross-repo (PR3): `repo:<name> <verb> <target>` scopes the query to another registered repo's
    // graph; without the prefix, everything runs on the primary store exactly as before.
    const { repo, rest: raw } = parseRepoQualifier(rawFull);
    let store: IGraphStore = graphStore;
    let scopedToSecondary = false;
    let scopedCwd = context?.cwd || process.cwd();
    if (repo) {
      const repos = await resolveRepoStores(graphStore);
      const pick = pickRepoStore(repos, repo);
      if (!pick) {
        return `No repo named "${repo}" in this workspace. Available: ${repos.map(r => r.name).join(', ')}. ` +
          `Register it with WorkspaceTool and index it with /index inside that repo.`;
      }
      store = pick.store;
      scopedToSecondary = !pick.primary;
      if (scopedToSecondary) scopedCwd = pick.root; // READ_SYMBOL reads source from ITS repo
    }

    const verbs = ['SEARCH_NODES', 'GET_DEPENDENTS', 'GET_DEPENDENCIES', 'BLAST_RADIUS', 'READ_SYMBOL', 'SEMANTIC', 'ARCHITECTURE'];
    const firstSpace = raw.indexOf(' ');
    const maybeVerb = (firstSpace === -1 ? raw : raw.slice(0, firstSpace)).toUpperCase();
    const verb = verbs.includes(maybeVerb) ? maybeVerb : null;
    const target = verb ? raw.slice(firstSpace + 1).trim() : raw;

    // codebase-memory engine: when connected + indexed, it fronts these verbs with a richer,
    // 158-language graph + local semantic search. It indexes the PRIMARY repo only, so a query
    // scoped to another repo skips it and goes straight to that repo's native graph. Any miss
    // returns null → native graph below.
    if (!scopedToSecondary && globalCodemem.isReady()) {
      let r: string | null = null;
      if (verb === 'SEMANTIC') r = await globalCodemem.search(target, true);
      else if (verb === 'SEARCH_NODES' && target && target !== '*') r = await globalCodemem.search(target, false);
      else if (verb === 'GET_DEPENDENTS') r = await globalCodemem.traceCalls(target, 'inbound');
      else if (verb === 'GET_DEPENDENCIES') r = await globalCodemem.traceCalls(target, 'outbound');
      else if (verb === 'BLAST_RADIUS') r = await globalCodemem.blastRadius(target);
      else if (verb === 'READ_SYMBOL') r = await globalCodemem.readSymbol(target);
      else if (verb === 'ARCHITECTURE') r = await globalCodemem.architecture(target || undefined);
      if (r) return r;
    }
    // Engine-only verbs with no native equivalent: guide the model when the engine isn't ready.
    if (verb === 'SEMANTIC') return 'Semantic search needs the codebase-memory engine, which is still indexing or unavailable. Use SEARCH_NODES <keyword> for now.';
    if (verb === 'ARCHITECTURE') return 'The architecture overview needs the codebase-memory engine, which is still indexing or unavailable. Explore with SEARCH_NODES * and ls for now.';

    const graph = store.getGraph();
    if (graph.nodes.size === 0) {
      return 'The dependency graph is empty. Run /index (local AST) or /index-ai (semantic) first.';
    }

    if (verb === 'SEARCH_NODES') {
      // Discovery: `SEARCH_NODES *` (or no keyword) lists the most central nodes so the model can see
      // what's actually in the graph and pick real names — instead of guessing concepts.
      if (!target || target === '*') {
        const top = getTopNodes(store, 30);
        if (top.length === 0) return 'The graph is empty.';
        return `Most central ${top.length} nodes (use these names with READ_SYMBOL / GET_DEPENDENTS / BLAST_RADIUS):\n` +
          top.map(r => `- ${r.type} ${r.label}${r.filePath ? ` (${r.filePath})` : ''}`).join('\n');
      }
      const hits = searchNodes(store, target);
      if (hits.length === 0) return `No nodes match "${target}".` + graphOrientation(store);
      return `Found ${hits.length} node(s) for "${target}":\n` + hits.map(n => '- ' + fmtNode(n)).join('\n');
    }

    const engine = new ImpactEngine(store);

    if (verb === 'GET_DEPENDENTS' || verb === 'GET_DEPENDENCIES') {
      const resolved = resolveNodeId(store, target);
      if (resolved.ambiguous) {
        return `"${target}" is ambiguous. Candidates:\n` + resolved.ambiguous.map(n => '- ' + fmtNode(n)).join('\n');
      }
      if (!resolved.id) return `No node found for "${target}". Try SEARCH_NODES ${target}.`;
      // Resolve DIRECT callers/callees, mirroring context.planner so the two never disagree:
      //  • depth 2 crosses the analyzer's block layer (symbol --CONTAINS--> block --CALLS--> neighbor),
      //  • non-symbol intermediaries (blocks/statements/vars) are dropped,
      //  • for dependents the target's own structural parents (the file/class that CONTAINS it) are
      //    excluded — they OWN the symbol, they don't depend on it.
      // This is the fix for the "6 dependents vs 2 real callers" overcount (owners + transitive noise).
      const isSym = (n: GraphNode) => n.type === 'FUNCTION' || n.type === 'CLASS' || n.type === 'INTERFACE';
      let nodes: GraphNode[];
      let dir: string;
      if (verb === 'GET_DEPENDENTS') {
        const parents = new Set(graph.edges.filter(e => e.targetId === resolved.id && e.type === 'CONTAINS').map(e => e.sourceId));
        nodes = engine.getReverseDependencies(resolved.id, 2).filter(isSym).filter(n => !parents.has(n.id));
        dir = 'directly depend on';
      } else {
        nodes = engine.getForwardDependencies(resolved.id, 2).filter(isSym);
        dir = 'are directly depended on by';
      }
      if (nodes.length === 0) return `Nothing ${dir} ${resolved.id} in the graph.`;
      return `${nodes.length} node(s) that ${dir} ${resolved.id} (direct only — use BLAST_RADIUS for transitive reach):\n` +
        nodes.slice(0, 40).map(n => '- ' + fmtNode(n)).join('\n');
    }

    if (verb === 'BLAST_RADIUS') {
      const resolved = resolveNodeId(store, target);
      if (resolved.ambiguous) {
        return `"${target}" is ambiguous. Candidates:\n` + resolved.ambiguous.map(n => '- ' + fmtNode(n)).join('\n');
      }
      if (!resolved.id) return `No node found for "${target}". Try SEARCH_NODES ${target}.`;
      const r = engine.calculateBlastRadius(resolved.id);
      const sev = r.totalImpactedNodes > 20 || r.highestRiskScore >= 70 ? '🔴 LARGE'
        : r.totalImpactedNodes > 5 ? '🟡 MODERATE' : '🟢 SMALL';
      return [
        `Blast radius for ${resolved.id}: ${sev}`,
        `- Impacted nodes: ${r.totalImpactedNodes} (files ${r.impactedFiles}, functions ${r.impactedFunctions}, classes ${r.impactedClasses})`,
        `- Highest downstream criticality score: ${r.highestRiskScore}`,
        r.totalImpactedNodes > 20 ? '⚠️ Large blast radius — review dependents carefully and run tests after editing.' : ''
      ].filter(Boolean).join('\n');
    }

    if (verb === 'READ_SYMBOL') {
      const resolved = resolveNodeId(store, target);
      if (resolved.ambiguous) {
        return `"${target}" is ambiguous. Candidates:\n` + resolved.ambiguous.map(n => '- ' + fmtNode(n)).join('\n');
      }
      if (!resolved.id) return `No node found for "${target}". Try SEARCH_NODES ${target}.`;
      const node = store.getNode(resolved.id)!;
      const { text, error } = await readSymbolSource(node, scopedCwd);
      if (error) return `Error reading ${node.id}: ${error}`;
      const header = [
        `// ${node.type} ${node.name}${node.criticality ? ` [${node.criticality}${node.riskScore != null ? ` risk=${node.riskScore}` : ''}]` : ''}`,
        `// ${node.filePath}:${node.startLine}-${node.endLine}`,
        node.signature ? `// ${node.signature}` : '',
      ].filter(Boolean).join('\n');
      return `${header}\n${text}`;
    }

    // Bare node id / keyword.
    const resolved = resolveNodeId(store, target);
    if (resolved.ambiguous) {
      return `"${target}" matches several nodes — pick one or use SEARCH_NODES:\n` + resolved.ambiguous.map(n => '- ' + fmtNode(n)).join('\n');
    }
    if (!resolved.id) return `No node found for "${target}". Try: SEARCH_NODES ${target}`;
    const node = store.getNode(resolved.id)!;
    const edges = graph.edges.filter(e => e.sourceId === resolved.id || e.targetId === resolved.id);
    return JSON.stringify({ node, edges }, null, 2);
  }
}, governor);

export const createGraphContextTool = (governor: IGovernor, graphStore: GraphStore) => buildTool({
  name: 'GraphContextTool',
  description: `Assembles a MINIMAL, token-budgeted context pack for editing a specific symbol, using the dependency graph — so you load exactly what you need instead of dumping whole files into context.

# Usage
- \`PLAN_CONTEXT <node|keyword>\` (or just \`<node|keyword>\`) — returns the target symbol's FULL source plus the SIGNATURES of its direct callers (who depends on it) and callees/types (what it uses).

Prefer this over ReadFileTool whenever you are about to modify an existing function/class: it shows you the call-site contract you must preserve and the things that break, at a fraction of the tokens.

# Cross-repo
Prefix with \`repo:<name>\` to pack context from another registered repo — e.g. \`repo:libfoo PLAN_CONTEXT Encoder\` when adapting that repo's pattern into this one.`,
  isDestructive: false,
  isConcurrencySafe: true,
  schema: {
    type: 'object',
    properties: {
      query: { type: 'string', description: 'PLAN_CONTEXT <target>, or a bare node id/keyword (e.g. "handlePayment").' }
    },
    required: ['query']
  },
  execute: async (args: { query: string }, context?: any) => {
    const raw = (args.query || '').trim();
    if (!raw) return 'Error: empty query.';

    // Cross-repo (PR3): a leading `repo:<name>` scopes the pack to another registered repo's graph.
    const { repo, rest } = parseRepoQualifier(raw);
    const firstSpace = rest.indexOf(' ');
    const maybeVerb = (firstSpace === -1 ? rest : rest.slice(0, firstSpace)).toUpperCase();
    const target = maybeVerb === 'PLAN_CONTEXT' ? rest.slice(firstSpace + 1).trim() : rest;
    if (!target) return 'Error: PLAN_CONTEXT needs a target symbol (e.g. PLAN_CONTEXT handlePayment, or repo:libfoo PLAN_CONTEXT parse).';

    let store: IGraphStore = graphStore;
    let cwd = context?.cwd || process.cwd();
    let scopedToSecondary = false;
    if (repo) {
      const repos = await resolveRepoStores(graphStore);
      const pick = pickRepoStore(repos, repo);
      if (!pick) {
        return `No repo named "${repo}" in this workspace. Available: ${repos.map(r => r.name).join(', ')}. ` +
          `Register it with WorkspaceTool and index it with /index inside that repo.`;
      }
      store = pick.store;
      scopedToSecondary = !pick.primary;
      if (scopedToSecondary) cwd = pick.root; // read the target's source from ITS repo, not the primary
    }

    // The codebase-memory engine indexes the PRIMARY repo only — use it only when not scoped elsewhere.
    if (!scopedToSecondary && globalCodemem.isReady()) {
      const r = await globalCodemem.planContext(target);
      if (r) return r;
    }

    if (store.getGraph().nodes.size === 0) {
      return repo
        ? `Repo "${repo}" has no index yet — run /index inside it (${cwd}).`
        : 'The dependency graph is empty. Run /index (local AST) or /index-ai (semantic) first.';
    }

    const pack = await planContext(store, target, { cwd });
    if ('error' in pack) {
      return `${pack.error} Try GraphQueryTool ${repo ? `repo:${repo} ` : ''}SEARCH_NODES ${target}.`;
    }
    return pack.text;
  }
}, governor);

import * as fs from 'fs';
import * as path from 'path';
import { IGovernor } from '../../core/interfaces';
import { buildTool } from '../tool.factory';
import { GraphStore } from '../../graph/graph.store';
import { resolveNodeId } from '../../graph/node.search';
import { lspSpecFor, isServerAvailable } from '../../lsp/registry';
import { LspClient } from '../../lsp/client';

// C1 — expose Language-Server enrichments to the agent: compiler-grade DIAGNOSTICS and
// precise REFERENCES (better than the graph's name-based CALLS). Graph-fused: REFERENCES
// resolves its symbol through the graph (node.search), so the agent names a symbol, not a
// line/column. Degrades cleanly when the relevant server isn't installed.

// One client per (server command, project root), reused across calls within the process.
const clients = new Map<string, LspClient>();
function getClient(spec: { command: string; args: string[] }, root: string): LspClient {
  const key = `${spec.command}|${root}`;
  let c = clients.get(key);
  if (!c) { c = new LspClient(spec, root); clients.set(key, c); }
  return c;
}

export const createLspQueryTool = (governor: IGovernor, graphStore: GraphStore) => buildTool({
  name: 'LspQueryTool',
  description: `Query an installed Language Server for precise, compiler-grade code info — complements the structural graph.

# Verbs (pass as \`query\`)
- \`DIAGNOSTICS <file>\` — real type/lint errors for a file from its language server.
- \`REFERENCES <symbol>\` — every precise reference to a graph symbol (node id or keyword).

Requires the language server installed (typescript-language-server for TS/JS, pyright for Python). Returns a clear note if it isn't.`,
  isDestructive: false,
  isConcurrencySafe: true,
  schema: {
    type: 'object',
    properties: { query: { type: 'string', description: 'DIAGNOSTICS <file> | REFERENCES <symbol>' } },
    required: ['query'],
  },
  execute: async (args: { query: string }, context?: any) => {
    const raw = (args.query || '').trim();
    if (!raw) return 'Usage: DIAGNOSTICS <file> | REFERENCES <symbol>';
    const cwd = context?.cwd || process.cwd();
    const sp = raw.indexOf(' ');
    const verb = (sp === -1 ? raw : raw.slice(0, sp)).toUpperCase();
    const target = sp === -1 ? '' : raw.slice(sp + 1).trim();

    if (verb === 'DIAGNOSTICS') {
      if (!target) return 'Usage: DIAGNOSTICS <file>';
      const file = path.isAbsolute(target) ? target : path.resolve(cwd, target);
      if (!fs.existsSync(file)) return `File not found: ${target}`;
      const spec = lspSpecFor(file);
      if (!spec) return `No language server configured for ${path.extname(file) || 'this file type'}.`;
      if (!isServerAvailable(spec)) {
        return `Language server '${spec.command}' is not installed — install it to enable LSP diagnostics (e.g. \`npm i -g ${spec.command}\`).`;
      }
      const diags = await getClient(spec, cwd).diagnose(file);
      if (diags.length === 0) return `No diagnostics for ${target}. ✅`;
      return `${diags.length} diagnostic(s) for ${target}:\n` +
        diags.map(d => `- [${d.severity}] ${d.line + 1}:${d.character + 1} ${d.message}`).join('\n');
    }

    if (verb === 'REFERENCES') {
      if (!target) return 'Usage: REFERENCES <symbol>';
      const resolved = resolveNodeId(graphStore, target);
      if (resolved.ambiguous) return `"${target}" is ambiguous — be more specific or use GraphQueryTool SEARCH_NODES.`;
      if (!resolved.id) return `No graph node found for "${target}".`;
      const node = graphStore.getNode(resolved.id)!;
      if (!node.filePath || node.startLine == null) return `${node.id} has no recorded location — re-run /index.`;
      const file = path.isAbsolute(node.filePath) ? node.filePath : path.resolve(cwd, node.filePath);
      const spec = lspSpecFor(file);
      if (!spec) return `No language server configured for ${path.extname(file)}.`;
      if (!isServerAvailable(spec)) return `Language server '${spec.command}' is not installed.`;
      // Point the request at the symbol's name on its declaration line.
      const simpleName = node.name.split('.').pop() || node.name;
      const lineText = (fs.readFileSync(file, 'utf8').split('\n')[node.startLine - 1]) || '';
      const col = Math.max(0, lineText.indexOf(simpleName));
      const refs = await getClient(spec, cwd).references(file, node.startLine - 1, col);
      if (refs.length === 0) return `No references found for ${node.name}.`;
      return `${refs.length} reference(s) to ${node.name}:\n` +
        refs.map(r => `- ${decodeURIComponent(r.uri.replace(/^file:\/\//, ''))}:${r.line + 1}:${r.character + 1}`).join('\n');
    }

    return 'Usage: DIAGNOSTICS <file> | REFERENCES <symbol>';
  },
}, governor);

import { buildTool, BuiltTool } from '../tool.factory';
import { IGovernor } from '../../core/interfaces';
import { LlmAdapter } from '../../core/llm.adapter';
import { saveConfig, getConfig } from '../../engine/config';
import { getProviders, getCurrentProvider, setProvider } from '../../engine/provider';
import { MODEL_CATALOG } from '../../engine/models';
import { saveApiKeyToEnv } from '../../engine/env.loader';
import { engineEvents } from '../../engine/events';

/**
 * Gives the AGENT self-service over its own model API — the brain it runs on — instead of that being
 * a human-only `/model` / `/provider` command. The agent can list the models its provider actually
 * serves, switch the CODING model (main loop) or the LITE model (cheap aux calls: summaries,
 * self-critic), or switch provider. Changes apply LIVE to the running adapter and persist to config.
 *
 * Creative use: the agent right-sizes its own brain to the task — drop to a fast/cheap model for
 * boilerplate, jump to a stronger model for hard reasoning, all without the user intervening.
 */
export function createModelManageTool(governor: IGovernor, llmAdapter: LlmAdapter): BuiltTool {
  return buildTool({
    name: 'ModelManageTool',
    description: `Inspect and switch the LLM you (the agent) run on. Two slots: CODING (the main agent loop — your reasoning/tool-calling brain) and LITE (cheap auxiliary calls: summaries, self-critic, classification). Changes take effect immediately and persist.

# Actions
- list: show the current coding + lite models, the active provider, and the model ids your provider actually serves (so you don't pick one that 400s).
- use: switch a model. { slot: "coding" | "lite", model: "<id>" }. Use a model id from "list" (or a known catalog id). Switching the coding model changes the brain for subsequent turns.
- provider: switch LLM provider. { provider: "<name>" } from the providers list (each needs its own API key in env). Resets which model namespace is valid — set a model afterward.

# When to use
- A task needs a stronger/cheaper brain than the current one (right-size to the work).
- The user asks to change model/provider, or you hit repeated "invalid model" errors and need to pick a served id.

# Caution
- Only switch the CODING model when it clearly helps — it changes your own behaviour mid-task. Prefer the LITE slot for routine speed-ups. Always pick an id that "list" confirms the provider serves.`,
    isDestructive: false,
    isConcurrencySafe: false,
    schema: {
      type: 'object',
      properties: {
        action: { type: 'string', enum: ['list', 'use', 'provider'], description: 'What to do.' },
        slot: { type: 'string', enum: ['coding', 'lite'], description: 'For use: which model slot to change.' },
        model: { type: 'string', description: 'For use: the model id to switch to (from list).' },
        provider: { type: 'string', description: 'For provider: the provider name to switch to.' },
      },
      required: ['action'],
    },
    execute: async (args: { action: string; slot?: string; model?: string; provider?: string }) => {
      const cfg = () => { try { return getConfig(); } catch { return {} as any; } };

      if (args.action === 'list') {
        const c = cfg();
        const prov = getCurrentProvider();
        let live: string[] = [];
        try { live = (await llmAdapter.listProviderModels()) || []; } catch { /* offline / no endpoint */ }
        const served = live.length
          ? live.slice(0, 40).join(', ') + (live.length > 40 ? `, … (${live.length} total)` : '')
          : MODEL_CATALOG.map(m => m.value).join(', ') + '  (static catalog — provider has no /models endpoint)';
        const providers = getProviders().map(p => p.name).join(', ');
        return [
          `Active provider: ${prov.name}  (available: ${providers})`,
          `Work model:  ${c.model || '(default)'}`,
          `Quick model: ${c.liteModel || '(default)'}`,
          ``,
          `Models your provider serves: ${served}`,
        ].join('\n');
      }

      if (args.action === 'use') {
        if (!args.model) return 'use requires "model" (an id from action="list").';

        // Never PERSIST a model the provider does not serve.
        //
        // This wrote whatever id it was handed. A model id that the provider does not serve then
        // became the stored work model, so every later launch started from a guaranteed 404 and the
        // user's own choice was gone — with nothing on screen saying what had replaced it. An
        // unserved id is never a valid destination for a switch, whoever asked for it.
        //
        // The check is skipped only when the provider list itself is unavailable (empty), because
        // an outage must not block a deliberate switch — that is indistinguishable from "the
        // provider serves nothing", and refusing there would strand the user.
        try {
          const servedIds: string[] = await llmAdapter.listProviderModels();
          if (servedIds.length > 0 && !servedIds.includes(args.model)) {
            // Substring matching is useless here: the real near-miss was
            // `nemotron-3-nano-30b-a3b` against `nemotron-3-nano-omni-30b-a3b-reasoning`, where an
            // inserted token breaks containment. Compare leading hyphen tokens instead.
            const tokens = (id: string): string[] => (id.split('/').pop() || '').split('-');
            const want = tokens(String(args.model));
            const near = servedIds
              .map(id => ({ id, score: tokens(id).findIndex((t, i) => t !== want[i]) }))
              .map(x => ({ ...x, score: x.score === -1 ? want.length : x.score }))
              .filter(x => x.score >= 2)
              .sort((a, b) => b.score - a.score)
              .slice(0, 3)
              .map(x => x.id);
            return `Refusing to switch: "${args.model}" is not served by the active provider.`
              + (near.length ? ` Did you mean: ${near.join(', ')}?` : '')
              + ` Run action="list" to see what it serves.`;
          }
        } catch { /* provider unreachable — fall through rather than block a deliberate switch */ }

        const slot = args.slot === 'lite' ? 'lite' : 'coding';
        if (slot === 'coding') {
          llmAdapter.applyConfig({ model: args.model });
          await saveConfig({ model: args.model });
        } else {
          llmAdapter.applyConfig({ liteModel: args.model });
          await saveConfig({ liteModel: args.model });
        }
        try { engineEvents.emit('config_changed'); } catch { /* UI refresh best-effort */ }
        return `Switched ${slot} model → ${args.model} (live + saved).`;
      }

      if (args.action === 'provider') {
        if (!args.provider) return `provider requires "provider". Available: ${getProviders().map(p => p.name).join(', ')}.`;
        const found = setProvider(args.provider);
        if (!found) return `Unknown provider "${args.provider}". Available: ${getProviders().map(p => p.name).join(', ')}.`;
        try { saveApiKeyToEnv('BGW_PROVIDER', found.name); } catch { /* persistence optional */ }
        const hasKey = !!process.env[found.apiKeyEnv];
        try { engineEvents.emit('config_changed'); } catch { /* best-effort */ }
        return `Switched provider → ${found.name}.${hasKey ? '' : ` ⚠ No ${found.apiKeyEnv} set — add the key or calls will fail.`} ` +
          `Now set a served model with action="use" (default: ${found.defaultModel}).`;
      }

      return `Unknown action "${args.action}". Use "list", "use", or "provider".`;
    },
  }, governor);
}

import * as fs from 'fs/promises';
import * as path from 'path';
import { resolvePath, countOccurrences, workspaceWriteBlock } from '../path.util';
import { IGovernor } from '../../core/interfaces';
import { buildTool } from '../tool.factory';
import { backupFile, unifiedDiff, compactDiff, capDiff } from '../../engine/fileEditor';
import { checkEditSyntax, shieldEdit } from '../syntax.check';
import { requestDiffApproval } from '../../engine/diffApproval';
import { checkBlastRadius } from '../../engine/blastGate';
import { globalTransactionManager } from '../../core/transaction.manager';
import { findFuzzyMatch, closestRegion } from './edit.tool';
import { outcomeOk, outcomeError, outcomeRejected } from '../outcome';

interface SingleEdit {
  path: string;
  oldString: string;
  newString: string;
  replaceAll?: boolean;
}

/**
 * MultiEditTool — applies a batch of string replacements across one or more files
 * atomically: every edit is validated first, and nothing is written unless all
 * edits would succeed. Edits to the same file are applied in order. Each touched
 * file is governed (FILE_WRITE) and backed up so /undo and /rewind still work.
 */
export const createMultiEditTool = (governor: IGovernor) => buildTool({
  name: 'MultiEditTool',
  description: `Applies a batch of exact-string replacements across one or more files in a single atomic operation. Either every edit applies or none do — use this for coordinated refactors (e.g. rename a symbol across files, change a signature and its callers) instead of many separate EditFileTool calls.

# Instructions
- Provide an \`edits\` array. Each entry: { path, oldString, newString, replaceAll? }.
- Each \`oldString\` must match its file exactly (whitespace included) and be unique unless \`replaceAll: true\`.
- Multiple edits to the same file are applied in array order; write later edits against the result of earlier ones.
- If ANY edit fails validation, the whole batch is rejected and no file is modified.`,
  // Governance is enforced per-file inside execute, so the factory wrapper stays out of the way.
  isDestructive: false,
  isConcurrencySafe: false,
  schema: {
    type: 'object',
    properties: {
      edits: {
        type: 'array',
        description: 'The list of edits to apply atomically.',
        items: {
          type: 'object',
          properties: {
            path: { type: 'string', description: 'File to edit (supports ~/).' },
            oldString: { type: 'string', description: 'Exact text to replace.' },
            newString: { type: 'string', description: 'Replacement text.' },
            replaceAll: { type: 'boolean', description: 'Replace every occurrence (default false).' },
          },
          required: ['path', 'oldString', 'newString'],
        },
      },
    },
    required: ['edits'],
  },
  execute: async (args: { edits: SingleEdit[] }, context?: any) => {
    const cwd = context?.cwd || process.cwd();
    // Accept BOTH our camelCase schema and Claude-Code-style snake_case keys (file_path / old_string
    // / new_string / replace_all) — many models emit the latter, which previously arrived as undefined
    // fields ("edit #1 (undefined): newString must differ from oldString").
    const edits: SingleEdit[] = (args.edits || []).map((e: any) => ({
      path: e.path ?? e.file_path ?? e.filePath,
      oldString: e.oldString ?? e.old_string,
      newString: e.newString ?? e.new_string,
      replaceAll: e.replaceAll ?? e.replace_all,
    }));
    if (edits.length === 0) return outcomeError('invalid_args', 'Error: edits array is empty.');

    // Phase 1 — load each distinct file once and validate every edit in order against
    // an in-memory working copy. Nothing touches disk until all edits are proven valid.
    const working = new Map<string, string>(); // fullPath -> current (post-edits) content
    const originals = new Map<string, string>(); // fullPath -> on-disk content (for diff preview)
    const order: string[] = []; // distinct fullPaths in first-seen order

    for (let i = 0; i < edits.length; i++) {
      const e = edits[i];
      if (e.oldString === e.newString) return outcomeError('invalid_args', `Error: edit #${i + 1} (${e.path}): newString must differ from oldString.`);
      if (!e.oldString) return outcomeError('invalid_args', `Error: edit #${i + 1} (${e.path}): oldString cannot be empty.`);

      const full = resolvePath(e.path, cwd);
      const wsBlock = workspaceWriteBlock(full);
      if (wsBlock) return outcomeError('permission', `Error: edit #${i + 1} (${e.path}): ${wsBlock}`);
      if (!working.has(full)) {
        try {
          const disk = await fs.readFile(full, 'utf8');
          working.set(full, disk);
          originals.set(full, disk);
          order.push(full);
        } catch (err: any) {
          if (err.code === 'ENOENT') return outcomeError('not_found', `Error: edit #${i + 1}: file not found: ${e.path}. Use WriteFileTool to create files.`);
          throw err;
        }
      }
      const content = working.get(full)!;
      // Match exactly, then fall back to the same 9-step fuzzy chain EditFileTool uses — MultiEdit was
      // previously exact-only, so a single whitespace/indentation drift in one edit failed the entire
      // batch (the brittle "edit #1 not found" abort). resolvedOld is the ACTUAL file text to replace.
      let resolvedOld = e.oldString;
      let occ = countOccurrences(content, resolvedOld);
      if (occ === 0) {
        const fuzzy = findFuzzyMatch(content, e.oldString);
        if (!fuzzy) {
          const hint = closestRegion(content, e.oldString);
          return outcomeError('not_found', `Error: edit #${i + 1} (${e.path}): oldString not found (after preceding edits).` +
            (hint
              ? `\n\nThe closest region currently in the file is:\n\n${hint}\n\n` +
                `Copy oldString VERBATIM from there, or split this into smaller edits anchored on a single unique line.`
              : ` Re-read the file and match it exactly, including whitespace and indentation.`));
        }
        resolvedOld = fuzzy.resolvedOld;
        occ = countOccurrences(content, resolvedOld);
      }
      if (occ > 1 && !e.replaceAll) return outcomeError('ambiguous_match', `Error: edit #${i + 1} (${e.path}): oldString appears ${occ} times — add context or set replaceAll: true.`);
      // Replacer FUNCTION, not a string: avoids String.replace interpreting `$$`/`$&`/`` $` ``/`$'`
      // in newString (would corrupt Makefiles, shell `$$`, sed/regex code). See edit.tool.ts.
      const updated = e.replaceAll ? content.split(resolvedOld).join(e.newString) : content.replace(resolvedOld, () => e.newString);
      working.set(full, updated);
    }

    // Edit Shield — refuse the whole batch when any file would end up with NEW syntax errors,
    // before anything touches disk (keeps the all-or-nothing promise).
    for (const full of order) {
      const shield = shieldEdit(full, originals.get(full)!, working.get(full)!);
      if (shield) {
        return outcomeError('syntax', `MultiEdit refused by Edit Shield for ${path.relative(cwd, full)}: ${shield}`);
      }
    }

    // Blast-radius gate — check every distinct file; a decline anywhere aborts the whole batch.
    for (const full of order) {
      if (!(await checkBlastRadius(full))) {
        return outcomeRejected(`MultiEdit cancelled — declined at the blast-radius gate for ${path.relative(cwd, full)}. No changes were made.`);
      }
    }

    // Inline diff approval — show the whole batch as one diff; reject is all-or-nothing.
    const combinedDiff = order.map(f => unifiedDiff(originals.get(f)!, working.get(f)!, path.relative(cwd, f))).join('\n');
    const approved = await requestDiffApproval(`MultiEdit: ${edits.length} edit(s) across ${order.length} file(s)`, combinedDiff);
    if (!approved) return outcomeRejected(`MultiEdit rejected by user. No changes were made.`);

    // Phase 2 — governance approval for every distinct file BEFORE any write, so a
    // veto leaves the workspace untouched (keeps the operation atomic).
    for (const full of order) {
      await governor.approveTaskExecution('FILE_WRITE', { targetPath: full, isDestructive: true });
    }

    // Phase 3 — track (for /tx atomic rollback) and back up every file, then write them.
    for (const full of order) {
      await globalTransactionManager.trackEdit(full, working.get(full)!);
      await backupFile(full);
    }
    // If a write fails mid-batch, the files written before it are already changed. Restore each of
    // them to its original on-disk content (held in `originals`) so the batch is truly all-or-nothing
    // — the atomicity this tool promises. Previously only the failed file was addressed, leaving the
    // earlier files partially written (data corruption on a coordinated refactor).
    const written: string[] = [];
    for (const full of order) {
      try {
        await fs.writeFile(full, working.get(full)!, 'utf8');
        written.push(full);
      } catch (e: any) {
        const restoreErrors: string[] = [];
        for (const done of written) {
          try { await fs.writeFile(done, originals.get(done)!, 'utf8'); }
          catch (re: any) { restoreErrors.push(`${path.relative(cwd, done)}: ${re.message}`); }
        }
        // Keep an open /tx transaction's bookkeeping consistent with the rollback we just did.
        if (globalTransactionManager.isOpen()) {
          await globalTransactionManager.autoRollback(path.relative(cwd, full), `write failed: ${e.message}`);
        }
        const ok = written.length - restoreErrors.length;
        return outcomeError('io', `MultiEdit failed writing ${path.relative(cwd, full)}: ${e.message}. ` +
          `Rolled back ${ok} already-written file(s) to their original contents.` +
          (restoreErrors.length ? ` WARNING — could not restore: ${restoreErrors.join('; ')}.` : ''));
      }
    }

    const diff = capDiff(order.map(f => compactDiff(originals.get(f)!, working.get(f)!, path.relative(cwd, f))).join('\n'));
    const syntaxWarn = order.map(f => checkEditSyntax(f, working.get(f)!) || '').join('');
    return outcomeOk(`Applied ${edits.length} edit(s) across ${order.length} file(s):\n${diff}${syntaxWarn}`);
  },
}, governor);

import * as fs from 'fs';
import { IGovernor } from '../../core/interfaces';
import { buildTool } from '../tool.factory';
import { resolvePath } from '../path.util';

// Jupyter notebook editing — .ipynb files are JSON, so the plain Edit/Write tools would force the
// model to hand-splice a large JSON document (brittle, easy to corrupt outputs/metadata). This tool
// operates on CELLS by index instead: read the notebook's structure, then edit / insert / delete a
// cell while preserving every other cell's outputs and metadata. (Parity with Claude Code's
// NotebookEditTool.) Cell source is stored as a string[] of lines per the nbformat spec.

interface NbCell {
  cell_type: 'code' | 'markdown' | 'raw';
  source: string[] | string;
  metadata?: any;
  outputs?: any[];
  execution_count?: number | null;
}
interface Notebook { cells: NbCell[]; metadata?: any; nbformat?: number; nbformat_minor?: number; }

/** nbformat stores source as an array of lines (each with its trailing \n) OR a single string. */
function cellText(c: NbCell): string {
  return Array.isArray(c.source) ? c.source.join('') : (c.source || '');
}
/** Split a source string back into the array-of-lines form nbformat expects (newlines retained). */
function toSourceLines(src: string): string[] {
  if (src === '') return [];
  const parts = src.split('\n');
  return parts.map((p, i) => (i < parts.length - 1 ? p + '\n' : p)).filter((_, i) => !(i === parts.length - 1 && parts[i] === ''));
}

function newCell(cellType: 'code' | 'markdown', src: string): NbCell {
  const base: NbCell = { cell_type: cellType, source: toSourceLines(src), metadata: {} };
  if (cellType === 'code') { base.outputs = []; base.execution_count = null; }
  return base;
}

export const createNotebookEditTool = (governor: IGovernor) => buildTool({
  name: 'NotebookEditTool',
  description: `Edit a Jupyter notebook (.ipynb) by CELL, preserving other cells' outputs and metadata. Prefer this over Edit/Write for notebooks — hand-splicing the JSON corrupts outputs.

# Actions (pass as \`action\`)
- \`read\` — list every cell: index, type (code/markdown), and a source preview.
- \`edit\` — replace cell \`cellIndex\`'s source with \`source\`. Clears that cell's stale outputs.
- \`insert\` — insert a new \`cellType\` (code|markdown) cell with \`source\` at \`cellIndex\` (default: end).
- \`delete\` — remove the cell at \`cellIndex\`.`,
  isDestructive: true, // edit/insert/delete rewrite the file — gate like any other write
  isConcurrencySafe: false,
  schema: {
    type: 'object',
    properties: {
      action: { type: 'string', enum: ['read', 'edit', 'insert', 'delete'], description: 'read | edit | insert | delete' },
      path: { type: 'string', description: 'Path to the .ipynb notebook file.' },
      cellIndex: { type: 'number', description: '0-based cell index. Required for edit/delete; optional for insert (defaults to appending at the end).' },
      source: { type: 'string', description: 'New cell source (for edit/insert).' },
      cellType: { type: 'string', enum: ['code', 'markdown'], description: 'Cell type for insert (default: code).' },
    },
    required: ['action', 'path'],
  },
  execute: async (args: { action: string; path: string; cellIndex?: number; source?: string; cellType?: 'code' | 'markdown' }, context?: any) => {
    const abs = resolvePath(args.path, context?.cwd || process.cwd());
    if (!fs.existsSync(abs)) return `Error: notebook not found: ${args.path}`;

    let nb: Notebook;
    try {
      nb = JSON.parse(fs.readFileSync(abs, 'utf-8'));
    } catch (e: any) {
      return `Error: ${args.path} is not valid JSON (a Jupyter notebook must be): ${e.message}`;
    }
    if (!Array.isArray(nb.cells)) return `Error: ${args.path} has no "cells" array — not a Jupyter notebook.`;

    const action = (args.action || '').toLowerCase();
    const n = nb.cells.length;

    if (action === 'read') {
      if (n === 0) return `${args.path}: empty notebook (0 cells).`;
      const rows = nb.cells.map((c, i) => {
        const text = cellText(c).replace(/\n/g, '⏎');
        const preview = text.length > 100 ? text.slice(0, 100) + '…' : text;
        return `[${i}] ${c.cell_type.padEnd(8)} ${preview}`;
      });
      return `${args.path} — ${n} cell(s):\n\n${rows.join('\n')}`;
    }

    const save = () => fs.writeFileSync(abs, JSON.stringify(nb, null, 1) + '\n', 'utf-8');
    const idx = args.cellIndex;

    if (action === 'edit') {
      if (idx == null || idx < 0 || idx >= n) return `Error: edit needs a valid cellIndex 0..${n - 1} (got ${idx}). Run \`read\` first.`;
      if (args.source == null) return 'Error: edit needs a `source` (the new cell contents).';
      nb.cells[idx].source = toSourceLines(args.source);
      if (nb.cells[idx].cell_type === 'code') { nb.cells[idx].outputs = []; nb.cells[idx].execution_count = null; }
      save();
      return `Edited cell [${idx}] of ${args.path} (its stale outputs were cleared).`;
    }

    if (action === 'insert') {
      const at = idx == null ? n : Math.max(0, Math.min(idx, n));
      const cell = newCell(args.cellType || 'code', args.source || '');
      nb.cells.splice(at, 0, cell);
      save();
      return `Inserted a ${cell.cell_type} cell at [${at}] of ${args.path} (now ${nb.cells.length} cells).`;
    }

    if (action === 'delete') {
      if (idx == null || idx < 0 || idx >= n) return `Error: delete needs a valid cellIndex 0..${n - 1} (got ${idx}).`;
      const removed = nb.cells.splice(idx, 1)[0];
      save();
      return `Deleted ${removed.cell_type} cell [${idx}] of ${args.path} (now ${nb.cells.length} cells).`;
    }

    return `Error: unknown action "${args.action}". Use one of: read, edit, insert, delete.`;
  },
}, governor);

import * as fs from 'fs';
import * as path from 'path';
import { buildTool } from '../tool.factory';
import { IGovernor } from '../../core/interfaces';
import { resolvePath } from '../path.util';
import { readPdf, pdfToolingAvailable, PdfToolingMissing } from '../../documents/pdf.raster';
import { ocrPages, NoOcrBackend } from '../../documents/ocr';
import { outcomeOk, outcomeError } from '../outcome';

/**
 * ReadDocumentTool — read a PDF or a scanned page, on this machine.
 *
 * The product could WRITE four document formats and read none of them, which is why PS 26117's
 * headline demonstration had no input path: nothing could open the inspection report the approval
 * note was supposed to be drafted from.
 *
 * The tool reports HOW each page was read, and that is not a detail. A page taken from an embedded
 * text layer is exact; a page recovered by OCR is a recognizer's best reading, and an engineer
 * acting on a wall thickness needs to know which one they are looking at. Every page is labelled,
 * and low-confidence OCR is called out rather than presented as if it were certain.
 */

/** Below this mean confidence, an OCR page is flagged for human confirmation before it is acted on. */
const LOW_CONFIDENCE = 0.6;

export const createReadDocumentTool = (governor: IGovernor) => buildTool({
  name: 'ReadDocumentTool',
  description: `Reads a PDF or scanned image on this machine and returns its text.

Use this for inspection reports, SOPs, manuals, drawings, and any scanned correspondence. Everything runs locally — the PDF is rasterized with poppler and read with the on-device OCR engine (Apple Vision on macOS, Tesseract elsewhere). Nothing is uploaded.

# How it reads
- A page with a real embedded text layer is read EXACTLY. No OCR runs on it.
- A page that is a picture of text is rasterized and OCR'd, and reported as such with a confidence.
- Each page in the result says which of the two it was, so you never present a recognizer's guess as if it were the document.

# Instructions
- **Large documents:** pass \`firstPage\`/\`lastPage\`. A 200-page manual read whole will bury the answer.
- **Drawings and dense P&IDs:** raise \`dpi\` to 300. The default 150 is right for printed reports.
- **Low confidence:** if a page reports \`lowConfidence\`, say so in your answer rather than asserting the value. Quote the number AND that it was OCR'd.
- Images (.png/.jpg/.tif) are OCR'd directly; no rasterizing step applies.`,
  isDestructive: false,
  isConcurrencySafe: true,
  schema: {
    type: 'object',
    properties: {
      path: { type: 'string', description: 'Path to the PDF or image (absolute, or relative to the working directory).' },
      firstPage: { type: 'number', description: 'Optional. First page to read, 1-indexed.' },
      lastPage: { type: 'number', description: 'Optional. Last page to read, inclusive.' },
      dpi: { type: 'number', description: 'Optional. Rasterization resolution for scanned pages (default 150; use 300 for dense drawings).' },
    },
    required: ['path'],
  },
  execute: async (args: { path: string; firstPage?: number; lastPage?: number; dpi?: number }, context?: any) => {
    const file = resolvePath(args.path, context?.cwd || process.cwd());
    if (!fs.existsSync(file)) return outcomeError('not_found', `No such file: ${args.path}`);

    const extension = path.extname(file).toLowerCase();
    const isImage = ['.png', '.jpg', '.jpeg', '.gif', '.webp', '.bmp', '.tif', '.tiff'].includes(extension);
    if (!isImage && extension !== '.pdf') {
      return outcomeError('invalid_args',
        `ReadDocumentTool reads PDFs and images. "${extension || 'a file with no extension'}" is neither — `
        + `use ReadFileTool for text files.`);
    }

    try {
      // An image is already a page: no text layer to try, nothing to rasterize.
      if (isImage) {
        const { backend, pages } = await ocrPages([file]);
        const page = pages[0];
        return outcomeOk(JSON.stringify({
          file: args.path, kind: 'image', ocrBackend: backend,
          pages: [{
            page: 1, source: 'ocr', text: page.text, lines: page.lines,
            ...(page.confidence !== undefined ? { confidence: Number(page.confidence.toFixed(3)) } : {}),
            ...(page.confidence !== undefined && page.confidence < LOW_CONFIDENCE ? { lowConfidence: true } : {}),
            ...(page.error ? { error: page.error } : {}),
          }],
        }, null, 2));
      }

      const tooling = await pdfToolingAvailable({ signal: context?.signal });
      if (!tooling.ok) return outcomeError('external', new PdfToolingMissing(tooling.missing[0]).message);

      const result = await readPdf(file, {
        firstPage: args.firstPage, lastPage: args.lastPage, dpi: args.dpi, signal: context?.signal,
      });

      try {
        context?.signal?.throwIfAborted();
        // Only pages that genuinely need looking at reach the recognizer. On a digital PDF that is
        // none of them, which is the whole point of trying the text layer first.
        const needOcr = result.pages.filter(p => p.source === 'raster' && p.imagePath);
        let backend: string | undefined;
        const recognized = new Map<string, { text: string; confidence?: number; lines: number; error?: string }>();
        if (needOcr.length > 0) {
          const ocr = await ocrPages(needOcr.map(p => p.imagePath!));
          context?.signal?.throwIfAborted();
          backend = ocr.backend;
          for (const page of ocr.pages) recognized.set(page.imagePath, page);
        }

        const pages = result.pages.map(page => {
          if (page.source === 'text-layer') {
            return { page: page.page, source: 'text-layer', text: page.text ?? '' };
          }
          const hit = page.imagePath ? recognized.get(page.imagePath) : undefined;
          // A page with no text layer that the recognizer also found nothing on is BLANK, not a scan
          // we read. Labelling it 'ocr' would imply a recognizer read something, and a trailing page
          // carrying only a footer would look like a page whose contents we failed to recover.
          const source = hit && hit.lines === 0 && !hit.error ? 'blank' : 'ocr';
          return {
            page: page.page,
            source,
            text: hit?.text ?? '',
            lines: hit?.lines ?? 0,
            ...(hit?.confidence !== undefined ? { confidence: Number(hit.confidence.toFixed(3)) } : {}),
            ...(hit?.confidence !== undefined && hit.confidence < LOW_CONFIDENCE ? { lowConfidence: true } : {}),
            ...(hit?.error ? { error: hit.error } : {}),
          };
        });

        return outcomeOk(JSON.stringify({
          file: args.path,
          kind: 'pdf',
          totalPages: result.totalPages,
          pagesRead: pages.length,
          ...(backend ? { ocrBackend: backend } : {}),
          readExactly: pages.filter(p => p.source === 'text-layer').length,
          readByOcr: pages.filter(p => p.source === 'ocr').length,
          blank: pages.filter(p => p.source === 'blank').length,
          pages,
        }, null, 2));
      } finally { await result.dispose?.(); }
    } catch (error: unknown) {
      if (context?.signal?.aborted) throw error;
      if (error instanceof NoOcrBackend || error instanceof PdfToolingMissing) {
        return outcomeError('external', error.message);
      }
      return outcomeError('io', `Could not read ${args.path}: ${(error as Error).message}`);
    }
  },
}, governor);

import { ToolDef, buildTool, BuiltTool } from '../tool.factory';
import { IGovernor } from '../../core/interfaces';
import { registerAgent, addCustomRule, getCustomRules } from '../../engine/agentRouter';
import { saveConfig } from '../../engine/config';
import { ToolRegistry } from '../tool.registry';

export function createRegisterAgentTool(governor: IGovernor, toolRegistry: ToolRegistry): BuiltTool {
  const def: ToolDef = {
    name: 'RegisterAgentTool',
    description: `Registers a newly installed CLI tool as a persistent agent persona.

Use this AFTER successfully installing a new CLI tool via BashTool (e.g. \`curl ... | bash\`).
This tool will:
1. Register the agent name so routing rules can target it
2. Auto-generate a persona with BashTool and ReadFileTool access
3. Create a routing rule so queries about that tool go to the new agent

# Instructions
- Only call this after the CLI is actually installed and accessible from the terminal
- The agent name should match the CLI command name (e.g., "antigravity" for the \`ag\` CLI)
- Provide keywords that users would type when they want to use this tool`,
    schema: {
      type: 'object',
      properties: {
        agentName: {
          type: 'string',
          description: 'The name of the new agent (lowercase, no spaces, e.g. "antigravity")'
        },
        description: {
          type: 'string',
          description: 'What this CLI does in one sentence'
        },
        routingKeywords: {
          type: 'string',
          description: 'Regex pattern for routing queries to this agent (e.g. "antigravity|ag\\s+")'
        },
        installCommand: {
          type: 'string',
          description: 'The command used to install it (for reference)'
        }
      },
      required: ['agentName', 'description', 'routingKeywords']
    },
    isDestructive: false,
    execute: async (args: { agentName: string; description: string; routingKeywords: string; installCommand?: string }) => {
      const name = args.agentName.toLowerCase().replace(/\s+/g, '-');

      registerAgent(name);

      addCustomRule(args.routingKeywords, name);

      const allRules = getCustomRules();
      await saveConfig({ customRoutingRules: allRules });

      const summary = [
        `✅ Agent "${name}" registered successfully!`,
        `   Description: ${args.description}`,
        `   Routing: /${args.routingKeywords}/ → ${name}`,
        args.installCommand ? `   Install: ${args.installCommand}` : '',
        ``,
        `The agent now has BashTool, ReadFileTool, and WriteFileTool access.`,
        `Type anything matching "${args.routingKeywords}" to route to ${name}.`,
      ].filter(Boolean).join('\n');

      return summary;
    }
  };

  return buildTool(def, governor);
}

import * as fs from 'fs';
import * as path from 'path';
import { execFile } from 'child_process';
import { promisify } from 'util';
import { resolvePath } from '../path.util';
import { IGovernor } from '../../core/interfaces';
import { buildTool } from '../tool.factory';

const execFileAsync = promisify(execFile);

/** Walk up from `dir` to the nearest directory containing package.json (or null). */
function nearestPackageRoot(dir: string): string | null {
  let cur = dir;
  for (let i = 0; i < 12; i++) {
    if (fs.existsSync(path.join(cur, 'package.json'))) return cur;
    const parent = path.dirname(cur);
    if (parent === cur) return null;
    cur = parent;
  }
  return null;
}

type Runner = { kind: 'jest' | 'vitest'; root: string } | { kind: 'go'; root: string };

/** Pick the test runner that covers this file: jest/vitest from the nearest package.json, go for .go. */
export function detectRunner(fullPath: string): Runner | null {
  if (fullPath.endsWith('.go')) return { kind: 'go', root: path.dirname(fullPath) };
  const root = nearestPackageRoot(path.dirname(fullPath));
  if (!root) return null;
  try {
    const pkg = JSON.parse(fs.readFileSync(path.join(root, 'package.json'), 'utf8'));
    const deps = { ...pkg.dependencies, ...pkg.devDependencies };
    if (deps.jest || pkg.jest || fs.existsSync(path.join(root, 'jest.config.js')) || fs.existsSync(path.join(root, 'jest.config.ts'))) {
      return { kind: 'jest', root };
    }
    if (deps.vitest || fs.existsSync(path.join(root, 'vitest.config.ts')) || fs.existsSync(path.join(root, 'vitest.config.js'))) {
      return { kind: 'vitest', root };
    }
  } catch { /* unreadable package.json → no runner */ }
  return null;
}

/** Keep the informative tail of a test run (summaries and failures live at the end). */
function tail(s: string, maxLines = 40): string {
  const lines = s.trim().split('\n');
  return lines.length <= maxLines ? s.trim() : `… (${lines.length - maxLines} lines omitted)\n` + lines.slice(-maxLines).join('\n');
}

/**
 * The verification half of surgical editing: after changing a file, run ONLY the tests that cover
 * it — seconds of signal instead of a full-suite run. Jest's dependency graph (--findRelatedTests),
 * vitest's `related`, or the file's own Go package.
 */
export const createRelatedTestsTool = (governor: IGovernor) => buildTool({
  name: 'RelatedTestsTool',
  description: `Run ONLY the tests related to one just-edited file — surgical verification in seconds instead of a full-suite run.

# How it resolves
- JS/TS file in a jest project → \`jest --findRelatedTests <file>\` (jest's own dependency graph picks the test files).
- JS/TS file in a vitest project → \`vitest related <file> --run\`.
- .go file → \`go test\` on that file's package.

# When to use
- Immediately after EditFileTool / SymbolEditTool / WriteFileTool on source code, to catch regressions while the change is still fresh.
- Prefer this over BashTool test commands: it picks the right runner and the minimal test set for you.
- "No tests found" is a real answer — it means the file has no covering tests (worth telling the user).`,
  isDestructive: false,
  schema: {
    type: 'object',
    properties: {
      path: { type: 'string', description: 'The source file whose related tests should run.' },
    },
    required: ['path'],
  },
  execute: async (rawArgs: any, context?: any) => {
    const cwd = context?.cwd || process.cwd();
    const fullPath = resolvePath(rawArgs.path ?? rawArgs.file_path ?? rawArgs.filePath, cwd);
    if (!fs.existsSync(fullPath)) return `Error: file not found: ${rawArgs.path}`;

    const runner = detectRunner(fullPath);
    if (!runner) {
      return `No test runner detected for ${rawArgs.path} (no jest/vitest in the nearest package.json, not a .go file). Run the project's own test command via BashTool if it uses something else.`;
    }

    const run = async (cmd: string, argv: string[], root: string) => {
      try {
        const { stdout, stderr } = await execFileAsync(cmd, argv, {
          cwd: root, timeout: 180000, maxBuffer: 16 * 1024 * 1024,
          env: { ...process.env, CI: '1', FORCE_COLOR: '0' },
        });
        return { ok: true, out: `${stdout}\n${stderr}` };
      } catch (e: any) {
        // Non-zero exit = failing tests (the useful case), not a tool error.
        return { ok: false, out: `${e.stdout || ''}\n${e.stderr || e.message || e}` };
      }
    };

    let res: { ok: boolean; out: string };
    let what: string;
    if (runner.kind === 'jest') {
      what = `jest --findRelatedTests (root: ${path.relative(cwd, runner.root) || '.'})`;
      res = await run('npx', ['jest', '--findRelatedTests', fullPath, '--passWithNoTests', '--silent'], runner.root);
    } else if (runner.kind === 'vitest') {
      what = `vitest related (root: ${path.relative(cwd, runner.root) || '.'})`;
      res = await run('npx', ['vitest', 'related', fullPath, '--run', '--passWithNoTests'], runner.root);
    } else {
      what = `go test (package: ${path.relative(cwd, runner.root) || '.'})`;
      res = await run('go', ['test', './...'], runner.root);
    }

    const body = tail(res.out);
    return res.ok
      ? `✓ Related tests PASSED for ${rawArgs.path} via ${what}.\n${body}`
      : `✗ Related tests FAILED for ${rawArgs.path} via ${what} — fix these before moving on:\n${body}`;
  },
}, governor);

import { buildTool, BuiltTool } from '../tool.factory';
import { IGovernor } from '../../core/interfaces';
import { ProjectMemory } from '../../memory/project.memory';

/**
 * Lets the agent durably record a project convention, decision, or gotcha. These are
 * recalled and injected into context automatically on later turns, so the project
 * effectively maintains its own CLAUDE.md.
 */
export function createRememberTool(governor: IGovernor, memory: ProjectMemory): BuiltTool {
  return buildTool({
    name: 'RememberTool',
    description: `Saves a durable fact about THIS project to long-term memory: a coding convention, an architectural decision and its rationale, or a gotcha worth not rediscovering. Relevant memories are automatically surfaced to you on future turns.

# When to use
- The user states a preference or rule ("always use X", "never touch Y").
- You discover a non-obvious constraint, build quirk, or decision that future work must respect.
Do NOT use it for transient task state or things already obvious from the code.`,
    isDestructive: false,
    isConcurrencySafe: true,
    schema: {
      type: 'object',
      properties: {
        content: { type: 'string', description: 'The fact to remember, phrased so it is useful out of context.' },
        kind: { type: 'string', enum: ['convention', 'decision', 'gotcha', 'note'], description: 'Category of memory (default note).' },
        tags: { type: 'array', items: { type: 'string' }, description: 'Optional extra tags.' },
      },
      required: ['content'],
    },
    execute: async (args: { content: string; kind?: any; tags?: string[] }) => {
      const id = await memory.remember(args.content, args.kind || 'note', args.tags || []);
      if (!id) return 'Nothing to remember (empty content).';
      return `Saved to project memory (${args.kind || 'note'}): ${args.content.slice(0, 80)}${args.content.length > 80 ? '…' : ''}`;
    },
  }, governor);
}

import * as https from 'https';
import { IGovernor } from '../../core/interfaces';
import { buildTool } from '../tool.factory';

interface ScoutArgs {
  package: string;
  aspect?: 'all' | 'api' | 'readme' | 'versions';
  registry?: 'npm' | 'pypi';
}

function httpsGetOnce(url: string, timeoutMs: number): Promise<string> {
  return new Promise((resolve, reject) => {
    const req = https.get(url, { headers: { 'User-Agent': 'bimax-scout/1.0', 'Accept': 'application/json,text/plain' } }, (res) => {
      // Treat 429 (rate-limit) as a retriable error so the retry loop backs off.
      if (res.statusCode === 429) {
        res.resume();
        reject(Object.assign(new Error('rate-limited'), { code: 'RATE_LIMITED' }));
        return;
      }
      const chunks: Buffer[] = [];
      res.on('data', (c: Buffer) => chunks.push(c));
      res.on('end', () => resolve(Buffer.concat(chunks).toString('utf-8')));
      res.on('error', reject);
    });
    req.setTimeout(timeoutMs, () => { req.destroy(); reject(new Error('timeout')); });
    req.on('error', reject);
  });
}

async function httpsGet(url: string, timeoutMs = 8000, maxRetries = 2): Promise<string> {
  let lastErr: Error = new Error('no attempts');
  for (let attempt = 0; attempt <= maxRetries; attempt++) {
    try {
      return await httpsGetOnce(url, timeoutMs);
    } catch (e: any) {
      lastErr = e;
      // Don't retry on timeout or permanent errors — only on transient network/rate-limit errors.
      if (e.message === 'timeout') throw e;
      if (attempt < maxRetries) {
        // Exponential backoff: 400ms, 800ms
        await new Promise(r => setTimeout(r, 400 * Math.pow(2, attempt)));
      }
    }
  }
  throw lastErr;
}

/** Strip HTML tags and collapse whitespace into plain readable text. */
function htmlToText(html: string): string {
  return html
    .replace(/<script[\s\S]*?<\/script>/gi, '')
    .replace(/<style[\s\S]*?<\/style>/gi, '')
    // Block-level elements → newlines so paragraphs survive as separate lines.
    .replace(/<\/?(p|div|br|h[1-6]|li|tr|blockquote|pre|article|section|header|footer)[^>]*>/gi, '\n')
    // Strip remaining HTML tags: only match patterns that actually look like tags
    // (letter-started tag name) so TypeScript generic syntax like Array<T> is never
    // accidentally consumed — PyPI descriptions are real HTML, not TypeScript source.
    .replace(/<\/?[a-zA-Z][a-zA-Z0-9]*(?:\s[^<>]*)?\/?>/g, '')
    .replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&amp;/g, '&')
    .replace(/&quot;/g, '"').replace(/&#39;/g, "'").replace(/&nbsp;/g, ' ')
    .replace(/[ \t]{2,}/g, ' ')
    .replace(/\n{3,}/g, '\n\n')
    .trim();
}

/** Cap a string to maxChars, appending a note if truncated. */
function cap(s: string, maxChars: number): string {
  if (s.length <= maxChars) return s;
  return s.slice(0, maxChars) + `\n\n[… truncated at ${maxChars} chars — use WebFetchTool for the full content]`;
}

async function scoutNpm(pkg: string, aspect: string): Promise<string> {
  const data = await httpsGet(`https://registry.npmjs.org/${encodeURIComponent(pkg)}`);
  const j = JSON.parse(data);
  const latest = j['dist-tags']?.latest || Object.keys(j.versions || {}).pop() || '?';
  const meta = j.versions?.[latest] || j;
  const name = j.name || pkg;
  const desc = j.description || meta.description || '(no description)';
  const homepage = meta.homepage || j.homepage || '';
  const repo = meta.repository?.url || '';
  const license = meta.license || '?';
  const deps = meta.dependencies ? Object.keys(meta.dependencies).length : 0;
  const mainExports = meta.exports ? JSON.stringify(meta.exports, null, 2).slice(0, 400) : '';
  const mainEntry = meta.main || meta.module || '';
  const types = meta.types || meta.typings || '';
  const keywords = (j.keywords || []).slice(0, 8).join(', ');
  const weeklyDl = j.downloads?.weekly || '?';

  const lines: string[] = [
    `# ${name}@${latest}`,
    `**Description:** ${desc}`,
    `**License:** ${license}  **Dependencies:** ${deps}`,
  ];
  if (keywords) lines.push(`**Keywords:** ${keywords}`);
  if (homepage) lines.push(`**Homepage:** ${homepage}`);
  if (repo) lines.push(`**Repo:** ${repo.replace(/^git\+/, '').replace(/\.git$/, '')}`);
  lines.push(`**Install:** \`npm install ${name}\``);
  if (mainEntry) lines.push(`**Main entry:** ${mainEntry}`);
  if (types) lines.push(`**Types:** ${types}`);
  if (mainExports) lines.push(`\n**Exports:**\n\`\`\`json\n${mainExports}\n\`\`\``);

  if (aspect === 'versions' || aspect === 'all') {
    const versions = Object.keys(j.versions || {}).slice(-10).reverse();
    lines.push(`\n**Recent versions:** ${versions.join(', ')}`);
  }

  // Try to fetch README from npm registry (it's embedded in the main doc)
  if (aspect === 'readme' || aspect === 'all') {
    const readme = j.readme || '';
    if (readme && readme !== 'ERROR: No README data found!') {
      lines.push(`\n## README (excerpt)\n${cap(readme, 3000)}`);
    } else if (repo) {
      // Try GitHub raw README
      const ghPath = repo.replace(/^git\+https?:\/\/github\.com\//, '').replace(/\.git$/, '');
      if (ghPath && !ghPath.includes(' ')) {
        try {
          const raw = await httpsGet(`https://raw.githubusercontent.com/${ghPath}/HEAD/README.md`, 6000);
          lines.push(`\n## README (from GitHub)\n${cap(raw, 3000)}`);
        } catch { /* readme unavailable */ }
      }
    }
  }

  return lines.join('\n');
}

async function scoutPypi(pkg: string, aspect: string): Promise<string> {
  const data = await httpsGet(`https://pypi.org/pypi/${encodeURIComponent(pkg)}/json`);
  const j = JSON.parse(data);
  const info = j.info || {};
  const latest = info.version || '?';
  const desc = info.summary || '(no description)';
  const home = info.home_page || info.project_url || '';
  const license = info.license || '?';
  const requires = (info.requires_dist || []).slice(0, 8).join(', ');
  const keywords = info.keywords || '';

  const lines: string[] = [
    `# ${pkg}@${latest} (PyPI)`,
    `**Description:** ${desc}`,
    `**License:** ${license}`,
  ];
  if (keywords) lines.push(`**Keywords:** ${keywords}`);
  if (home) lines.push(`**Homepage:** ${home}`);
  if (requires) lines.push(`**Requires:** ${requires}`);
  lines.push(`**Install:** \`pip install ${pkg}\``);

  if (aspect === 'readme' || aspect === 'all') {
    const readme = htmlToText(info.description || '');
    if (readme) lines.push(`\n## Description\n${cap(readme, 3000)}`);
  }

  return lines.join('\n');
}

/**
 * ScoutTool — targeted dependency inspection (gap from WebSearch's breadth).
 *
 * WebSearch returns raw search results. ScoutTool fetches structured data from
 * the package registry (npm / PyPI) and synthesizes: version, install command,
 * exports, dependencies, README excerpt. One call, structured answer.
 *
 * Amplifies existing WebFetchTool by pre-structuring package data so the model
 * gets a concise API surface instead of raw HTML.
 */
export const createScoutTool = (governor: IGovernor) => buildTool({
  name: 'ScoutTool',
  description: `Inspect an npm or PyPI package: version, install command, exports, dependencies, README excerpt.

Use this instead of WebSearch when you need "what is this package, how do I use it?" — it fetches structured registry data and returns a compact answer.

# When to use
- Before adding a new dependency (check version, license, size)
- When the user mentions a package name and asks how to use it
- Replacing trial-and-error imports with the actual export map

# Aspect
- **all** (default): full summary — description, install, exports, README excerpt
- **api**: description, exports, types only (no README)
- **readme**: full README excerpt only
- **versions**: recent version history`,
  isDestructive: false,
  isConcurrencySafe: true,
  schema: {
    type: 'object',
    properties: {
      package: { type: 'string', description: 'Package name (e.g. "zod", "react", "axios").' },
      aspect: { type: 'string', enum: ['all', 'api', 'readme', 'versions'], description: 'What to return (default: all).' },
      registry: { type: 'string', enum: ['npm', 'pypi'], description: 'Package registry (default: npm).' },
    },
    required: ['package'],
  },
  execute: async (args: ScoutArgs) => {
    const pkg = (args.package || '').trim();
    if (!pkg) return 'Error: package name is required.';
    const aspect = args.aspect || 'all';
    const registry = args.registry || 'npm';

    try {
      if (registry === 'pypi') return await scoutPypi(pkg, aspect);
      return await scoutNpm(pkg, aspect);
    } catch (e: any) {
      if (e.message === 'timeout') return `Scout timed out fetching "${pkg}" from ${registry}. Try WebFetchTool for a direct URL.`;
      if (e instanceof SyntaxError) return `Scout: "${pkg}" not found in ${registry} registry (or registry returned non-JSON). Check the spelling.`;
      return `Scout error for "${pkg}": ${e.message}`;
    }
  },
}, governor);

import * as fs from 'fs/promises';
import * as path from 'path';
import { resolvePath } from '../path.util';
import { minimatch } from 'minimatch';
import { IGovernor } from '../../core/interfaces';
import { buildTool } from '../tool.factory';
import { walkFiles } from '../../utils/fsWalk';
import { outcomeError } from '../outcome';
import { WorkflowEvidence } from '../../core/workflow.evidence';

/**
 * Human-readable label for where a search actually ran, relative to cwd. Surfacing this in the
 * result is the defense against a model that DROPPED a user-specified `path` arg: instead of
 * silently scanning the whole cwd and then (sometimes) claiming "the path doesn't exist", the
 * output now states the directory it searched, so the discrepancy is visible to model and user.
 */
function describeRoot(root: string, cwd: string): string {
  const rel = path.relative(cwd, root);
  if (rel === '') return 'the current directory';
  if (rel.startsWith('..')) return root; // outside cwd → show absolute
  return rel;
}

/** Cheap binary sniff: a NUL byte in the first chunk means "don't grep this". */
function looksBinary(sample: string): boolean {
  return sample.includes('\u0000');
}

const MAX_FILE_BYTES = 5 * 1024 * 1024; // skip files larger than 5MB

interface GrepArgs {
  pattern: string;
  path?: string;
  glob?: string;
  caseInsensitive?: boolean;
  outputMode?: 'content' | 'files' | 'count';
  contextLines?: number;
  maxResults?: number;
}

export const createGrepTool = (governor: IGovernor) => buildTool({
  name: 'GrepTool',
  description: `Searches file contents across the workspace using a regular expression. This is the right tool for "where is X used / defined / referenced" questions — far faster and more token-efficient than reading files one by one or piping to \`grep\` via BashTool.

# Instructions
- **pattern** is a JavaScript regular expression (e.g. \`function\\s+\\w+\`, \`TODO|FIXME\`). Escape special characters you mean literally.
- Use **glob** to restrict the file set (e.g. \`**/*.ts\`, \`src/**/*.tsx\`).
- **outputMode**: \`content\` returns matching lines with line numbers (default), \`files\` returns just the file paths that contain a match, \`count\` returns the number of matches per file.
- High-traffic directories (node_modules, .git, dist, build, coverage) are skipped automatically.`,
  isDestructive: false,
  workflowReadOnly: true,
  isConcurrencySafe: true,
  schema: {
    type: 'object',
    properties: {
      pattern: { type: 'string', description: 'The regular expression to search for.' },
      path: { type: 'string', description: 'File or directory to search (default: current working directory).' },
      glob: { type: 'string', description: 'Optional glob to filter files, e.g. "**/*.ts".' },
      caseInsensitive: { type: 'boolean', description: 'Case-insensitive matching (default false).' },
      outputMode: { type: 'string', enum: ['content', 'files', 'count'], description: 'content | files | count. Default content.' },
      contextLines: { type: 'number', description: 'Lines of context to show before/after each match (content mode only).' },
      maxResults: { type: 'number', description: 'Maximum matching lines or files to return (default 200).' },
    },
    required: ['pattern'],
  },
  execute: async (args: GrepArgs, context?: any) => {
    const evidence: WorkflowEvidence | undefined = context?.workflowEvidence;
    const signal: AbortSignal | undefined = context?.signal;
    signal?.throwIfAborted();
    const cwd = context?.cwd || process.cwd();
    const root = resolvePath(args.path || '.', cwd);
    const outputMode = args.outputMode || 'content';
    const maxResults = args.maxResults ?? 200;
    const ctx = Math.max(0, args.contextLines ?? 0);

    let regex: RegExp;
    try {
      regex = new RegExp(args.pattern, args.caseInsensitive ? 'i' : undefined);
    } catch (e: any) {
      return outcomeError('invalid_args', `Error: invalid regular expression: ${e.message}`);
    }

    // Build the candidate file list (a single file path is allowed too).
    const rootStat = await fs.stat(root).catch(() => null);
    if (!rootStat) return outcomeError('not_found', `Error: path not found: ${args.path || '.'}`);

    const files: string[] = [];
    if (rootStat.isFile()) {
      files.push(root);
    } else {
      for await (const f of walkFiles(root, {
        signal, onDirectory: (p, entries) => evidence?.directory(p, entries),
        onIncomplete: reason => evidence?.incomplete(reason),
      })) {
        if (args.glob) {
          const rel = path.relative(root, f);
          if (!minimatch(rel, args.glob, { dot: true })) continue;
        }
        files.push(f);
      }
    }

    const contentLines: string[] = [];
    const matchedFiles: string[] = [];
    const counts: { file: string; n: number }[] = [];
    let total = 0;

    // Grep→Read fusion: when ≤5 matches found in content mode with no explicit contextLines,
    // we auto-expand each to ±20 lines so the model sees real context without a separate ReadFile call.
    // Collect raw match records during the walk; decide rendering at the end once total is known.
    const fusionRecords: { rel: string; allLines: string[]; matchIdx: number }[] = [];
    const collectFusion = outputMode === 'content' && args.contextLines === undefined;

    outer: for (const file of files) {
      signal?.throwIfAborted();
      const stat = await fs.stat(file).catch(() => null);
      if (!stat || stat.size > MAX_FILE_BYTES) { evidence?.incomplete('Unreadable or oversized file skipped'); continue; }
      let text: string;
      try {
        text = evidence ? await evidence.readFile(file) : await fs.readFile(file, { encoding: 'utf8', signal });
      } catch {
        signal?.throwIfAborted();
        evidence?.incomplete('File could not be read');
        continue;
      }
      if (looksBinary(text.slice(0, 1024))) { evidence?.incomplete('Binary file skipped'); continue; }

      const lines = text.split('\n');
      let fileMatches = 0;
      for (let i = 0; i < lines.length; i++) {
        // Reset lastIndex defensively in case a global flag is ever added.
        regex.lastIndex = 0;
        if (!regex.test(lines[i])) continue;
        fileMatches++;
        total++;

        if (outputMode === 'content') {
          const rel = path.relative(cwd, file) || path.basename(file);
          if (collectFusion) {
            // Store enough to re-render with ±20 lines later; allLines is the already-read content
            fusionRecords.push({ rel, allLines: lines, matchIdx: i });
          }
          const from = Math.max(0, i - ctx);
          const to = Math.min(lines.length - 1, i + ctx);
          for (let j = from; j <= to; j++) {
            const marker = j === i ? ':' : '-';
            contentLines.push(`${rel}${marker}${j + 1}${marker}${lines[j]}`);
          }
          if (ctx > 0) contentLines.push('--');
          if (contentLines.length >= maxResults) { evidence?.incomplete('Result limit reached'); break outer; }
        } else if (outputMode === 'files') {
          break; // one match is enough to include the file
        }
      }

      if (fileMatches > 0) {
        if (outputMode === 'files') {
          matchedFiles.push(path.relative(cwd, file) || file);
          if (matchedFiles.length >= maxResults) { evidence?.incomplete('Result limit reached'); break; }
        } else if (outputMode === 'count') {
          counts.push({ file: path.relative(cwd, file) || file, n: fileMatches });
        }
      }
    }

    const where = rootStat.isFile() ? (path.relative(cwd, root) || path.basename(root)) : describeRoot(root, cwd);
    if (outputMode === 'files') {
      if (matchedFiles.length === 0) return `No files matched /${args.pattern}/ in ${where}.`;
      return `${matchedFiles.length} file(s) matched in ${where}:\n${matchedFiles.sort().join('\n')}`;
    }
    if (outputMode === 'count') {
      if (counts.length === 0) return `No matches for /${args.pattern}/ in ${where}.`;
      counts.sort((a, b) => b.n - a.n);
      return counts.map(c => `${c.n}\t${c.file}`).join('\n');
    }
    if (contentLines.length === 0) return `No matches for /${args.pattern}/ in ${where}.`;

    // Grep→Read fusion: ≤5 matches and user didn't specify contextLines → auto-expand to ±20
    if (collectFusion && total <= 5 && fusionRecords.length === total) {
      const fusedLines: string[] = [];
      for (const m of fusionRecords) {
        const from = Math.max(0, m.matchIdx - 20);
        const to = Math.min(m.allLines.length - 1, m.matchIdx + 20);
        fusedLines.push(`\n--- ${m.rel}:${m.matchIdx + 1} [±20 lines] ---`);
        for (let j = from; j <= to; j++) {
          const marker = j === m.matchIdx ? ':' : '-';
          fusedLines.push(`${m.rel}${marker}${j + 1}${marker}${m.allLines[j]}`);
        }
        fusedLines.push('--');
      }
      return `Found ${total} match(es) in ${where} [auto-expanded ±20 lines]:\n${fusedLines.join('\n')}`;
    }

    const header = `Found ${total} match(es) in ${where}${total > maxResults ? ` (showing first ${maxResults})` : ''}:`;
    return `${header}\n${contentLines.join('\n')}`;
  },
}, governor);

interface GlobArgs {
  pattern: string;
  path?: string;
  maxResults?: number;
}

export const createGlobTool = (governor: IGovernor) => buildTool({
  name: 'GlobTool',
  description: `Finds files by glob pattern, returned newest-first (by modification time). Use this to locate files by name or extension when you don't know their exact path — e.g. "all test files", "every tsx component".

# Instructions
- **pattern** is a glob such as \`**/*.ts\`, \`src/**/*.tsx\`, or \`**/index.*\`.
- Results are relative to the search directory and exclude node_modules/.git/dist by default.`,
  isDestructive: false,
  workflowReadOnly: true,
  isConcurrencySafe: true,
  schema: {
    type: 'object',
    properties: {
      pattern: { type: 'string', description: 'Glob pattern, e.g. "**/*.ts".' },
      path: { type: 'string', description: 'Directory to search from (default: current working directory).' },
      maxResults: { type: 'number', description: 'Maximum file paths to return (default 500).' },
    },
    required: ['pattern'],
  },
  execute: async (args: GlobArgs, context?: any) => {
    const evidence: WorkflowEvidence | undefined = context?.workflowEvidence;
    const signal: AbortSignal | undefined = context?.signal;
    signal?.throwIfAborted();
    const cwd = context?.cwd || process.cwd();
    const root = resolvePath(args.path || '.', cwd);
    const maxResults = args.maxResults ?? 500;

    const matches: { file: string; mtime: number }[] = [];
    for await (const f of walkFiles(root, {
      signal, onDirectory: (p, entries) => evidence?.directory(p, entries),
      onIncomplete: reason => evidence?.incomplete(reason),
    })) {
      const rel = path.relative(root, f);
      if (!minimatch(rel, args.pattern, { dot: true })) continue;
      const stat = await fs.stat(f).catch(() => null);
      if (stat) evidence?.stat(f, stat);
      else evidence?.incomplete('File metadata unavailable');
      matches.push({ file: path.relative(cwd, f) || f, mtime: stat ? stat.mtimeMs : 0 });
    }

    const where = describeRoot(root, cwd);
    if (matches.length === 0) return `No files matched ${args.pattern} under ${where}.`;
    matches.sort((a, b) => b.mtime - a.mtime);
    const shown = matches.slice(0, maxResults);
    if (shown.length < matches.length) evidence?.incomplete('Result limit reached');
    const suffix = matches.length > maxResults ? `\n...and ${matches.length - maxResults} more` : '';
    return `${matches.length} file(s) matched ${args.pattern} under ${where}:\n${shown.map(m => m.file).join('\n')}${suffix}`;
  },
}, governor);

